window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["证监会"] = {"shangshigongsixinxipiluguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范上市公司及其他信息披露义务人的信息披露行为，加强信息披露事务管理，保护投资者合法权益，根据《中华人民共和国公司法》（以下简称《公司法》）、《中华人民共和国证券法》（以下简称《证券法》）等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"信息披露义务人履行信息披露义务应当遵守本办法的规定，中国证券监督管理委员会（以下简称中国证监会）对首次公开发行股票并上市、上市公司发行证券信息披露另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"信息披露义务人应当及时依法履行信息披露义务，披露的信息应当真实、准确、完整，简明清晰、通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 信息披露义务人披露的信息应当同时向所有投资者披露，不得提前向任何单位和个人泄露。但是，法律、行政法规另有规定的除外。 在内幕信息依法披露前，内幕信息的知情人和非法获取内幕信息的人不得公开或者泄露该信息，不得利用该信息进行内幕交易。任何单位和个人不得非法要求信息披露义务人提供依法需要披露但尚未披露的信息。 证券及其衍生品种同时在境内境外公开发行、交易的，其信息披露义务人在境外市场披露的信息，应当同时在境内市场披露。"},{"i":4,"n":"第四条","txt":"上市公司的董事、监事、高级管理人员应当忠实、勤勉地履行职责，保证披露信息的真实、准确、完整，信息披露及时、公平。"},{"i":5,"n":"第五条","txt":"除依法需要披露的信息之外，信息披露义务人可以自愿披露与投资者作出价值判断和投资决策有关的信息，但不得与依法披露的信息相冲突，不得误导投资者。 信息披露义务人自愿披露的信息应当真实、准确、完整。自愿性信息披露应当遵守公平原则，保持信息披露的持续性和一致性，不得进行选择性披露。 信息披露义务人不得利用自愿披露的信息不当影响公司证券及其衍生品种交易价格，不得利用自愿性信息披露从事市场操纵等违法违规行为。"},{"i":6,"n":"第六条","txt":"上市公司及其控股股东、实际控制人、董事、监事、高级管理人员等作出公开承诺的，应当披露。"},{"i":7,"n":"第七条","txt":"信息披露文件包括定期报告、临时报告、招股说明书、募集说明书、上市公告书、收购报告书等。"},{"i":8,"n":"第八条","txt":"依法披露的信息，应当在证券交易所的网站和符合中国证监会规定条件的媒体发布，同时将其置备于上市公司住所、证券交易所，供社会公众查阅。 信息披露文件的全文应当在证券交易所的网站和符合中国证监会规定条件的报刊依法开办的网站披露，定期报告、收购报告书等信息披露文件的摘要应当在证券交易所的网站和符合中国证监会规定条件的报刊披露。 信息披露义务人不得以新闻发布或者答记者问等任何形式代替应当履行的报告、公告义务，不得以定期报告形式代替应当履行的临时报告义务。"},{"i":9,"n":"第九条","txt":"信息披露义务人应当将信息披露公告文稿和相关备查文件报送上市公司注册地证监局。"},{"i":10,"n":"第十条","txt":"信息披露文件应当采用中文文本。同时采用外文文本的，信息披露义务人应当保证两种文本的内容一致。两种文本发生歧义时，以中文文本为准。"},{"i":11,"n":"第十一条","txt":"中国证监会依法对信息披露文件及公告的情况、信息披露事务管理活动进行监督检查，对信息披露义务人的信息披露行为进行监督管理。 证券交易所应当对上市公司及其他信息披露义务人的信息披露行为进行监督，督促其依法及时、准确地披露信息，对证券及其衍生品种交易实行实时监控。证券交易所制定的上市规则和其他信息披露规则应当报中国证监会批准。"},{"i":12,"n":"第十二条","txt":"上市公司应当披露的定期报告包括年度报告、中期报告。凡是对投资者作出价值判断和投资决策有重大影响的信息，均应当披露。 年度报告中的财务会计报告应当经符合《证券法》规定的会计师事务所审计。"},{"i":13,"n":"第十三条","txt":"年度报告应当在每个会计年度结束之日起四个月内，中期报告应当在每个会计年度的上半年结束之日起两个月内编制完成并披露。"},{"i":14,"n":"第十四条","txt":"年度报告应当记载以下内容： （一）公司基本情况； （二）主要会计数据和财务指标； （三）公司股票、债券发行及变动情况，报告期末股票、债券总额、股东总数，公司前十大股东持股情况； （四）持股百分之五以上股东、控股股东及实际控制人情况； （五）董事、监事、高级管理人员的任职情况、持股变动情况、年度报酬情况； （六）董事会报告； （七）管理层讨论与分析； （八）报告期内重大事件及对公司的影响； （九）财务会计报告和审计报告全文； （十）中国证监会规定的其他事项。"},{"i":15,"n":"第十五条","txt":"中期报告应当记载以下内容： （一）公司基本情况； （二）主要会计数据和财务指标； （三）公司股票、债券发行及变动情况、股东总数、公司前十大股东持股情况，控股股东及实际控制人发生变化的情况； （四）管理层讨论与分析； （五）报告期内重大诉讼、仲裁等重大事件及对公司的影响； （六）财务会计报告； （七）中国证监会规定的其他事项。"},{"i":16,"n":"第十六条","txt":"定期报告内容应当经上市公司董事会审议通过。未经董事会审议通过的定期报告不得披露。 公司董事、高级管理人员应当对定期报告签署书面确认意见，说明董事会的编制和审议程序是否符合法律、行政法规和中国证监会的规定，报告的内容是否能够真实、准确、完整地反映上市公司的实际情况。 监事会应当对董事会编制的定期报告进行审核并提出书面审核意见。监事应当签署书面确认意见。监事会对定期报告出具的书面审核意见，应当说明董事会的编制和审议程序是否符合法律、行政法规和中国证监会的规定，报告的内容是否能够真实、准确、完整地反映上市公司的实际情况。 董事、监事无法保证定期报告内容的真实性、准确性、完整性或者有异议的，应当在董事会或者监事会审议、审核定期报告时投反对票或者弃权票。 董事、监事和高级管理人员无法保证定期报告内容的真实性、准确性、完整性或者有异议的，应当在书面确认意见中发表意见并陈述理由，上市公司应当披露。上"},{"i":17,"n":"第十七条","txt":"上市公司预计经营业绩发生亏损或者发生大幅变动的，应当及时进行业绩预告。"},{"i":18,"n":"第十八条","txt":"定期报告披露前出现业绩泄露，或者出现业绩传闻且公司证券及其衍生品种交易出现异常波动的，上市公司应当及时披露本报告期相关财务数据。"},{"i":19,"n":"第十九条","txt":"定期报告中财务会计报告被出具非标准审计意见的，上市公司董事会应当针对该审计意见涉及事项作出专项说明。 定期报告中财务会计报告被出具非标准审计意见，证券交易所认为涉嫌违法的，应当提请中国证监会立案调查。"},{"i":20,"n":"第二十条","txt":"上市公司未在规定期限内披露年度报告和中期报告的，中国证监会应当立即立案调查，证券交易所应当按照股票上市规则予以处理。"},{"i":21,"n":"第二十一条","txt":"年度报告、中期报告的格式及编制规则，由中国证监会和证券交易所制定。"},{"i":22,"n":"第二十二条","txt":"发生可能对上市公司证券及其衍生品种交易价格产生较大影响的重大事件，投资者尚未得知时，上市公司应当立即披露，说明事件的起因、目前的状态和可能产生的影响。 前款所称重大事件包括： （一）《证券法》第八十条第二款规定的重大事件； （二）公司发生大额赔偿责任； （三）公司计提大额资产减值准备； （四）公司出现股东权益为负值； （五）公司主要债务人出现资不抵债或者进入破产程序，公司对相应债权未提取足额坏账准备； （六）新公布的法律、行政法规、规章、行业政策可能对公司产生重大影响； （七）公司开展股权激励、回购股份、重大资产重组、资产分拆上市或者挂牌； （八）法院裁决禁止控股股东转让其所持股份；任一股东所持公司百分之五以上股份被质押、冻结、司法拍卖、托管、设定信托或者被依法限制表决权等，或者出现被强制过户风险； （九）主要资产被查封、扣押或者冻结；主要银行账户被冻结； （十）上市公司预计经营业绩发"},{"i":23,"n":"第二十三条","txt":"上市公司变更公司名称、股票简称、公司章程、注册资本、注册地址、主要办公地址和联系电话等，应当立即披露。"},{"i":24,"n":"第二十四条","txt":"上市公司应当在最先发生的以下任一时点，及时履行重大事件的信息披露义务： （一）董事会或者监事会就该重大事件形成决议时； （二）有关各方就该重大事件签署意向书或者协议时； （三）董事、监事或者高级管理人员知悉该重大事件发生时。 在前款规定的时点之前出现下列情形之一的，上市公司应当及时披露相关事项的现状、可能影响事件进展的风险因素： （一）该重大事件难以保密； （二）该重大事件已经泄露或者市场出现传闻； （三）公司证券及其衍生品种出现异常交易情况。"},{"i":25,"n":"第二十五条","txt":"上市公司披露重大事件后，已披露的重大事件出现可能对上市公司证券及其衍生品种交易价格产生较大影响的进展或者变化的，上市公司应当及时披露进展或者变化情况、可能产生的影响。"},{"i":26,"n":"第二十六条","txt":"上市公司控股子公司发生本办法第二十二条规定的重大事件，可能对上市公司证券及其衍生品种交易价格产生较大影响的，上市公司应当履行信息披露义务。 上市公司参股公司发生可能对上市公司证券及其衍生品种交易价格产生较大影响的事件的，上市公司应当履行信息披露义务。"},{"i":27,"n":"第二十七条","txt":"涉及上市公司的收购、合并、分立、发行股份、回购股份等行为导致上市公司股本总额、股东、实际控制人等发生重大变化的，信息披露义务人应当依法履行报告、公告义务，披露权益变动情况。"},{"i":28,"n":"第二十八条","txt":"上市公司应当关注本公司证券及其衍生品种的异常交易情况及媒体关于本公司的报道。 证券及其衍生品种发生异常交易或者在媒体中出现的消息可能对公司证券及其衍生品种的交易产生重大影响时，上市公司应当及时向相关各方了解真实情况，必要时应当以书面方式问询。 上市公司控股股东、实际控制人及其一致行动人应当及时、准确地告知上市公司是否存在拟发生的股权转让、资产重组或者其他重大事件，并配合上市公司做好信息披露工作。"},{"i":29,"n":"第二十九条","txt":"公司证券及其衍生品种交易被中国证监会或者证券交易所认定为异常交易的，上市公司应当及时了解造成证券及其衍生品种交易异常波动的影响因素，并及时披露。"},{"i":30,"n":"第三十条","txt":"上市公司应当制定信息披露事务管理制度。信息披露事务管理制度应当包括： （一）明确上市公司应当披露的信息，确定披露标准； （二）未公开信息的传递、审核、披露流程； （三）信息披露事务管理部门及其负责人在信息披露中的职责； （四）董事和董事会、监事和监事会、高级管理人员等的报告、审议和披露的职责； （五）董事、监事、高级管理人员履行职责的记录和保管制度； （六）未公开信息的保密措施，内幕信息知情人登记管理制度，内幕信息知情人的范围和保密责任； （七）财务管理和会计核算的内部控制及监督机制； （八）对外发布信息的申请、审核、发布流程；与投资者、证券服务机构、媒体等的信息沟通制度； （九）信息披露相关文件、资料的档案管理制度； （十）涉及子公司的信息披露事务管理和报告制度； （十一）未按规定披露信息的责任追究机制，对违反规定人员的处理措施。 上市公司信息披露事务管理制度应当经公司董事会审议通过"},{"i":31,"n":"第三十一条","txt":"上市公司董事、监事、高级管理人员应当勤勉尽责，关注信息披露文件的编制情况，保证定期报告、临时报告在规定期限内披露。"},{"i":32,"n":"第三十二条","txt":"上市公司应当制定定期报告的编制、审议、披露程序。经理、财务负责人、董事会秘书等高级管理人员应当及时编制定期报告草案，提请董事会审议；董事会秘书负责送达董事审阅；董事长负责召集和主持董事会会议审议定期报告；监事会负责审核董事会编制的定期报告；董事会秘书负责组织定期报告的披露工作。"},{"i":33,"n":"第三十三条","txt":"上市公司应当制定重大事件的报告、传递、审核、披露程序。董事、监事、高级管理人员知悉重大事件发生时，应当按照公司规定立即履行报告义务；董事长在接到报告后，应当立即向董事会报告，并敦促董事会秘书组织临时报告的披露工作。 上市公司应当制定董事、监事、高级管理人员对外发布信息的行为规范，明确非经董事会书面授权不得对外发布上市公司未披露信息的情形。"},{"i":34,"n":"第三十四条","txt":"上市公司通过业绩说明会、分析师会议、路演、接受投资者调研等形式就公司的经营情况、财务状况及其他事件与任何单位和个人进行沟通的，不得提供内幕信息。"},{"i":35,"n":"第三十五条","txt":"董事应当了解并持续关注公司生产经营情况、财务状况和公司已经发生的或者可能发生的重大事件及其影响，主动调查、获取决策所需要的资料。"},{"i":36,"n":"第三十六条","txt":"监事应当对公司董事、高级管理人员履行信息披露职责的行为进行监督；关注公司信息披露情况，发现信息披露存在违法违规问题的，应当进行调查并提出处理建议。"},{"i":37,"n":"第三十七条","txt":"高级管理人员应当及时向董事会报告有关公司经营或者财务方面出现的重大事件、已披露的事件的进展或者变化情况及其他相关信息。"},{"i":38,"n":"第三十八条","txt":"董事会秘书负责组织和协调公司信息披露事务，汇集上市公司应予披露的信息并报告董事会，持续关注媒体对公司的报道并主动求证报道的真实情况。董事会秘书有权参加股东大会、董事会会议、监事会会议和高级管理人员相关会议，有权了解公司的财务和经营情况，查阅涉及信息披露事宜的所有文件。董事会秘书负责办理上市公司信息对外公布等相关事宜。 上市公司应当为董事会秘书履行职责提供便利条件，财务负责人应当配合董事会秘书在财务信息披露方面的相关工作。"},{"i":39,"n":"第三十九条","txt":"上市公司的股东、实际控制人发生以下事件时，应当主动告知上市公司董事会，并配合上市公司履行信息披露义务: （一）持有公司百分之五以上股份的股东或者实际控制人持有股份或者控制公司的情况发生较大变化，公司的实际控制人及其控制的其他企业从事与公司相同或者相似业务的情况发生较大变化； （二）法院裁决禁止控股股东转让其所持股份，任一股东所持公司百分之五以上股份被质押、冻结、司法拍卖、托管、设定信托或者被依法限制表决权等，或者出现被强制过户风险； （三）拟对上市公司进行重大资产或者业务重组； （四）中国证监会规定的其他情形。 应当披露的信息依法披露前，相关信息已在媒体上传播或者公司证券及其衍生品种出现交易异常情况的，股东或者实际控制人应当及时、准确地向上市公司作出书面报告，并配合上市公司及时、准确地公告。 上市公司的股东、实际控制人不得滥用其股东权利、支配地位，不得要求上市公司向其提供内幕信息。"},{"i":40,"n":"第四十条","txt":"上市公司向特定对象发行股票时，其控股股东、实际控制人和发行对象应当及时向上市公司提供相关信息，配合上市公司履行信息披露义务。"},{"i":41,"n":"第四十一条","txt":"上市公司董事、监事、高级管理人员、持股百分之五以上的股东及其一致行动人、实际控制人应当及时向上市公司董事会报送上市公司关联人名单及关联关系的说明。上市公司应当履行关联交易的审议程序，并严格执行关联交易回避表决制度。交易各方不得通过隐瞒关联关系或者采取其他手段，规避上市公司的关联交易审议程序和信息披露义务。"},{"i":42,"n":"第四十二条","txt":"通过接受委托或者信托等方式持有上市公司百分之五以上股份的股东或者实际控制人，应当及时将委托人情况告知上市公司，配合上市公司履行信息披露义务。"},{"i":43,"n":"第四十三条","txt":"信息披露义务人应当向其聘用的证券公司、证券服务机构提供与执业相关的所有资料，并确保资料的真实、准确、完整，不得拒绝、隐匿、谎报。 证券公司、证券服务机构在为信息披露出具专项文件时，发现上市公司及其他信息披露义务人提供的材料有虚假记载、误导性陈述、重大遗漏或者其他重大违法行为的，应当要求其补充、纠正。信息披露义务人不予补充、纠正的，证券公司、证券服务机构应当及时向公司注册地证监局和证券交易所报告。"},{"i":44,"n":"第四十四条","txt":"上市公司解聘会计师事务所的，应当在董事会决议后及时通知会计师事务所，公司股东大会就解聘会计师事务所进行表决时，应当允许会计师事务所陈述意见。股东大会作出解聘、更换会计师事务所决议的，上市公司应当在披露时说明解聘、更换的具体原因和会计师事务所的陈述意见。"},{"i":45,"n":"第四十五条","txt":"为信息披露义务人履行信息披露义务出具专项文件的证券公司、证券服务机构及其人员，应当勤勉尽责、诚实守信，按照法律、行政法规、中国证监会规定、行业规范、业务规则等发表专业意见，保证所出具文件的真实性、准确性和完整性。 证券服务机构应当妥善保存客户委托文件、核查和验证资料、工作底稿以及与质量控制、内部管理、业务经营有关的信息和资料。证券服务机构应当配合中国证监会的监督管理，在规定的期限内提供、报送或者披露相关资料、信息，保证其提供、报送或者披露的资料、信息真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":46,"n":"第四十六条","txt":"会计师事务所应当建立并保持有效的质量控制体系、独立性管理和投资者保护机制，秉承风险导向审计理念，遵守法律、行政法规、中国证监会的规定，严格执行注册会计师执业准则、职业道德守则及相关规定，完善鉴证程序，科学选用鉴证方法和技术，充分了解被鉴证单位及其环境，审慎关注重大错报风险，获取充分、适当的证据，合理发表鉴证结论。"},{"i":47,"n":"第四十七条","txt":"资产评估机构应当建立并保持有效的质量控制体系、独立性管理和投资者保护机制，恪守职业道德，遵守法律、行政法规、中国证监会的规定，严格执行评估准则或者其他评估规范，恰当选择评估方法，评估中提出的假设条件应当符合实际情况，对评估对象所涉及交易、收入、支出、投资等业务的合法性、未来预测的可靠性取得充分证据，充分考虑未来各种可能性发生的概率及其影响，形成合理的评估结论。"},{"i":48,"n":"第四十八条","txt":"任何单位和个人不得非法获取、提供、传播上市公司的内幕信息，不得利用所获取的内幕信息买卖或者建议他人买卖公司证券及其衍生品种，不得在投资价值分析报告、研究报告等文件中使用内幕信息。"},{"i":49,"n":"第四十九条","txt":"媒体应当客观、真实地报道涉及上市公司的情况，发挥舆论监督作用。 任何单位和个人不得提供、传播虚假或者误导投资者的上市公司信息。"},{"i":50,"n":"第五十条","txt":"中国证监会可以要求信息披露义务人或者其董事、监事、高级管理人员对有关信息披露问题作出解释、说明或者提供相关资料，并要求上市公司提供证券公司或者证券服务机构的专业意见。 中国证监会对证券公司和证券服务机构出具的文件的真实性、准确性、完整性有疑义的，可以要求相关机构作出解释、补充，并调阅其工作底稿。 信息披露义务人及其董事、监事、高级管理人员，证券公司和证券服务机构应当及时作出回复，并配合中国证监会的检查、调查。"},{"i":51,"n":"第五十一条","txt":"上市公司董事、监事、高级管理人员应当对公司信息披露的真实性、准确性、完整性、及时性、公平性负责，但有充分证据表明其已经履行勤勉尽责义务的除外。 上市公司董事长、经理、董事会秘书，应当对公司临时报告信息披露的真实性、准确性、完整性、及时性、公平性承担主要责任。 上市公司董事长、经理、财务负责人应当对公司财务会计报告的真实性、准确性、完整性、及时性、公平性承担主要责任。"},{"i":52,"n":"第五十二条","txt":"信息披露义务人及其董事、监事、高级管理人员违反本办法的，中国证监会为防范市场风险，维护市场秩序，可以采取以下监管措施： （一）责令改正； （二）监管谈话； （三）出具警示函； （四）责令公开说明； （五）责令定期报告； （六）责令暂停或者终止并购重组活动； （七）依法可以采取的其他监管措施。"},{"i":53,"n":"第五十三条","txt":"上市公司未按本办法规定制定上市公司信息披露事务管理制度的，由中国证监会责令改正；拒不改正的，给予警告并处国务院规定限额以下罚款。"},{"i":54,"n":"第五十四条","txt":"信息披露义务人未按照《证券法》规定在规定期限内报送有关报告、履行信息披露义务，或者报送的报告、披露的信息有虚假记载、误导性陈述或者重大遗漏的，由中国证监会按照《证券法》第一百九十七条处罚。 上市公司通过隐瞒关联关系或者采取其他手段，规避信息披露、报告义务的，由中国证监会按照《证券法》第一百九十七条处罚。"},{"i":55,"n":"第五十五条","txt":"为信息披露义务人履行信息披露义务出具专项文件的证券公司、证券服务机构及其人员，违反法律、行政法规和中国证监会规定的，中国证监会为防范市场风险，维护市场秩序，可以采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告等监管措施；依法应当给予行政处罚的，由中国证监会依照有关规定进行处罚。"},{"i":56,"n":"第五十六条","txt":"任何单位和个人泄露上市公司内幕信息，或者利用内幕信息买卖证券的，由中国证监会按照《证券法》第一百九十一条处罚。"},{"i":57,"n":"第五十七条","txt":"任何单位和个人编造、传播虚假信息或者误导性信息，扰乱证券市场的；证券交易场所、证券公司、证券登记结算机构、证券服务机构及其从业人员，证券业协会、中国证监会及其工作人员，在证券交易活动中作出虚假陈述或者信息误导的；传播媒介传播上市公司信息不真实、不客观的，由中国证监会按照《证券法》第一百九十三条处罚。"},{"i":58,"n":"第五十八条","txt":"上市公司董事、监事在董事会或者监事会审议、审核定期报告时投赞成票，又在定期报告披露时表示无法保证定期报告内容的真实性、准确性、完整性或者有异议的，中国证监会可以对相关人员给予警告并处国务院规定限额以下罚款；情节严重的，可以对有关责任人员采取证券市场禁入的措施。"},{"i":59,"n":"第五十九条","txt":"利用新闻报道以及其他传播方式对上市公司进行敲诈勒索的，由中国证监会责令改正，并向有关部门发出监管建议函，由有关部门依法追究法律责任。"},{"i":60,"n":"第六十条","txt":"信息披露义务人违反本办法的规定，情节严重的，中国证监会可以对有关责任人员采取证券市场禁入的措施。"},{"i":61,"n":"第六十一条","txt":"违反本办法，涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"本办法下列用语的含义： （一）为信息披露义务人履行信息披露义务出具专项文件的证券公司、证券服务机构，是指为证券发行、上市、交易等证券业务活动制作、出具保荐书、审计报告、资产评估报告、估值报告、法律意见书、财务顾问报告、资信评级报告等文件的证券公司、会计师事务所、资产评估机构、律师事务所、财务顾问机构、资信评级机构等。 （二）信息披露义务人，是指上市公司及其董事、监事、高级管理人员、股东、实际控制人，收购人，重大资产重组、再融资、重大交易有关各方等自然人、单位及其相关人员，破产管理人及其成员，以及法律、行政法规和中国证监会规定的其他承担信息披露义务的主体。 （三）及时，是指自起算日起或者触及披露时点的两个交易日内。 （四）上市公司的关联交易，是指上市公司或者其控股子公司与上市公司关联人之间发生的转移资源或者义务的事项。 关联人包括关联法人（或者其他组织）和关联自然人。 具有以下情形之一的"},{"i":63,"n":"第六十三条","txt":"中国证监会可以对金融、房地产等特定行业上市公司的信息披露作出特别规定。"},{"i":64,"n":"第六十四条","txt":"境外企业在境内发行股票或者存托凭证并上市的，依照本办法履行信息披露义务。法律、行政法规或者中国证监会另有规定的，从其规定。"},{"i":65,"n":"第六十五条","txt":"本办法自2021年5月1日起施行。2007年1月30日发布的《上市公司信息披露管理办法》（证监会令第40号）、2016年12月9日发布的《公开发行证券的公司信息披露编报规则第13号——季度报告的内容与格式》（证监会公告〔2016〕33号）同时废止。"}],"shangshigongsibinggouchongzucaiwuguwenyewuguanlibaf2f134":[{"i":1,"n":"第一条","txt":"为了规范证券公司、证券投资咨询机构及其他财务顾问机构从事上市公司并购重组财务顾问业务活动，保护投资者的合法权益，促进上市公司规范运作，维护证券市场秩序，根据《证券法》和其他相关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"上市公司并购重组财务顾问业务是指为上市公司的收购、重大资产重组、合并、分立、股份回购等对上市公司股权结构、资产和负债、收入和利润等具有重大影响的并购重组活动提供交易估值、方案设计、出具专业意见等专业服务。 经中国证券监督管理委员会（以下简称中国证监会）核准具有上市公司并购重组财务顾问业务资格的证券公司、证券投资咨询机构或者其他符合条件的财务顾问机构（以下简称财务顾问），可以依照本办法的规定从事上市公司并购重组财务顾问业务。 未经中国证监会核准，任何单位和个人不得从事上市公司并购重组财务顾问业务。"},{"i":3,"n":"第三条","txt":"财务顾问应当遵守法律、行政法规、中国证监会的规定和行业规范，诚实守信，勤勉尽责，对上市公司并购重组活动进行尽职调查，对委托人的申报文件进行核查，出具专业意见，并保证其所出具的意见真实、准确、完整。"},{"i":4,"n":"第四条","txt":"财务顾问的委托人应当依法承担相应的责任，配合财务顾问履行职责，并向财务顾问提供有关文件及其他必要的信息，不得拒绝、隐匿、谎报。 财务顾问履行职责，不能减轻或者免除委托人、其他专业机构及其签名人员的责任。"},{"i":5,"n":"第五条","txt":"中国证监会依照法律、行政法规和本办法的规定，对财务顾问实行资格许可管理，对财务顾问及其负责并购重组项目的签名人员（以下简称财务顾问主办人）的执业情况进行监督管理。 中国证券业协会依法对财务顾问及其财务顾问主办人进行自律管理。"},{"i":6,"n":"第六条","txt":"证券公司从事上市公司并购重组财务顾问业务，应当具备下列条件： （一）公司净资本符合中国证监会的规定； （二）具有健全且运行良好的内部控制机制和管理制度，严格执行风险控制和内部隔离制度； （三）建立健全的尽职调查制度，具备良好的项目风险评估和内核机制； （四）公司财务会计信息真实、准确、完整； （五）公司控股股东、实际控制人信誉良好且最近3年无重大违法违规记录； （六）财务顾问主办人不少于5人； （七）中国证监会规定的其他条件。"},{"i":7,"n":"第七条","txt":"证券投资咨询机构从事上市公司并购重组财务顾问业务，应当具备下列条件： （一）已经取得中国证监会核准的证券投资咨询业务资格； （二）实缴注册资本和净资产不低于人民币500万元； （三）具有健全且运行良好的内部控制机制和管理制度，严格执行风险控制和内部隔离制度； （四）公司财务会计信息真实、准确、完整； （五）控股股东、实际控制人在公司申请从事上市公司并购重组财务顾问业务资格前一年未发生变化，信誉良好且最近3年无重大违法违规记录； （六）具有2年以上从事公司并购重组财务顾问业务活动的执业经历，且最近2年每年财务顾问业务收入不低于100万元； （七）有证券从业资格的人员不少于20人，其中，具有从事证券业务经验3年以上的人员不少于10人，财务顾问主办人不少于5人； （八）中国证监会规定的其他条件。"},{"i":8,"n":"第八条","txt":"其他财务顾问机构从事上市公司并购重组财务顾问业务，除应当符合前条第（二）至（四）项及第（七）项的条件外，还应当具备下列条件： （一）具有3年以上从事公司并购重组财务顾问业务活动的执业经历，且最近3年每年财务顾问业务收入不低于100万元； （二）董事、高级管理人员应当正直诚实，品行良好，熟悉证券法律、行政法规，具有从事证券市场工作3年以上或者金融工作5年以上的经验，具备履行职责所需的经营管理能力； （三）控股股东、实际控制人信誉良好且最近3年无重大违法违规记录； （四）中国证监会规定的其他条件。 资产评估机构、会计师事务所、律师事务所或者相关人员从事上市公司并购重组财务顾问业务，应当另行成立专门机构。"},{"i":9,"n":"第九条","txt":"证券公司、证券投资咨询机构和其他财务顾问机构有下列情形之一的，不得担任财务顾问： （一）最近24个月内存在违反诚信的不良记录； （二）最近24个月内因执业行为违反行业规范而受到行业自律组织的纪律处分； （三）最近36个月内因违法违规经营受到处罚或者因涉嫌违法违规经营正在被调查。"},{"i":10,"n":"第十条","txt":"财务顾问主办人应当具备下列条件： （一）具有证券从业资格； （二）具备中国证监会规定的投资银行业务经历； （三）参加中国证监会认可的财务顾问主办人胜任能力考试且成绩合格； （四）所任职机构同意推荐其担任本机构的财务顾问主办人； （五）未负有数额较大到期未清偿的债务； （六）最近24个月无违反诚信的不良记录； （七）最近24个月未因执业行为违反行业规范而受到行业自律组织的纪律处分； （八）最近36个月未因执业行为违法违规受到处罚； （九）中国证监会规定的其他条件。"},{"i":11,"n":"第十一条","txt":"证券公司、证券投资咨询机构和其他财务顾问机构申请从事上市公司并购重组财务顾问业务资格，应当提交下列文件: （一）申请报告； （二）营业执照复印件和公司章程； （三）董事长、高级管理人员及并购重组业务负责人的简历； （四）符合本办法规定条件的财务顾问主办人的证明材料； （五）关于公司控股股东、实际控制人信誉良好和最近3年无重大违法违规记录的说明； （六）公司治理结构和内控制度的说明，包括公司风险控制、内部隔离制度及内核部门人员名单和最近3年从业经历； （七）经具有从事证券业务资格的会计师事务所审计的公司最近2年的财务会计报告； （八）律师出具的法律意见书； （九）中国证监会规定的其他文件。"},{"i":12,"n":"第十二条","txt":"证券投资咨询机构申请从事上市公司并购重组财务顾问业务资格，除提交本办法第十一条规定的申报材料外，还应当提交下列文件： （一）中国证监会核准的证券投资咨询业务许可证复印件； （二）从事公司并购重组财务顾问业务2年以上执业经历的说明，以及最近2年每年财务顾问业务收入不低于100万元的证明文件，包括相关合同和纳税证明； （三）申请资格前一年控股股东、实际控制人未发生变化的说明。"},{"i":13,"n":"第十三条","txt":"其他财务顾问机构申请从事上市公司并购重组财务顾问业务资格，除提交本办法第十一条规定的申报材料外，还应当提交下列文件： （一）从事公司并购重组财务顾问业务3年以上执业经历的说明，以及最近3年每年财务顾问业务收入不低于100万元的证明文件，包括相关合同和纳税证明； （二）董事、高级管理人员符合本办法规定条件的说明； （三）申请资格前一年控股股东、实际控制人未发生变化的说明。"},{"i":14,"n":"第十四条","txt":"财务顾问申请人应当提交有关财务顾问主办人的下列证明文件： （一）证券从业资格证书； （二）中国证监会规定的投资银行业务经历的证明文件； （三）中国证监会认可的财务顾问主办人胜任能力考试且成绩合格的证书； （四）财务顾问申请人推荐其担任本机构的财务顾问主办人的推荐函； （五）不存在数额较大到期未清偿的债务的说明； （六）最近24个月无违反诚信的不良记录的说明； （七）最近24个月未受到行业自律组织的纪律处分的说明； （八）最近36个月未因执业行为违法违规受到处罚的说明； （九）中国证监会规定的其他文件。"},{"i":15,"n":"第十五条","txt":"财务顾问申请人应当保证申请文件真实、准确、完整。申请期间，文件内容发生重大变化的，财务顾问申请人应当自变化之日起5个工作日内向中国证监会提交更新资料。"},{"i":16,"n":"第十六条","txt":"中国证监会对财务顾问申请人的上市公司并购重组财务顾问业务资格申请进行审查、做出决定。 中国证监会及时公布和更新财务顾问及其财务顾问主办人的名单。"},{"i":17,"n":"第十七条","txt":"证券公司、证券投资咨询机构或者其他财务顾问机构受聘担任上市公司独立财务顾问的，应当保持独立性，不得与上市公司存在利害关系；存在下列情形之一的，不得担任独立财务顾问： （一）持有或者通过协议、其他安排与他人共同持有上市公司股份达到或者超过5%，或者选派代表担任上市公司董事； （二）上市公司持有或者通过协议、其他安排与他人共同持有财务顾问的股份达到或者超过5%，或者选派代表担任财务顾问的董事； （三）最近2年财务顾问与上市公司存在资产委托管理关系、相互提供担保，或者最近一年财务顾问为上市公司提供融资服务； （四）财务顾问的董事、监事、高级管理人员、财务顾问主办人或者其直系亲属有在上市公司任职等影响公正履行职责的情形； （五）在并购重组中为上市公司的交易对方提供财务顾问服务； （六）与上市公司存在利害关系、可能影响财务顾问及其财务顾问主办人独立性的其他情形。"},{"i":18,"n":"第十八条","txt":"上市公司并购重组活动涉及公开发行股票的，应当按照有关规定聘请具有保荐资格的证券公司从事相关业务。"},{"i":19,"n":"第十九条","txt":"财务顾问从事上市公司并购重组财务顾问业务，应当履行以下职责： （一）接受并购重组当事人的委托，对上市公司并购重组活动进行尽职调查，全面评估相关活动所涉及的风险； （二）就上市公司并购重组活动向委托人提供专业服务，帮助委托人分析并购重组相关活动所涉及的法律、财务、经营风险，提出对策和建议，设计并购重组方案，并指导委托人按照上市公司并购重组的相关规定制作申报文件； （三）对委托人进行证券市场规范化运作的辅导，使其熟悉有关法律、行政法规和中国证监会的规定，充分了解其应承担的义务和责任，督促其依法履行报告、公告和其他法定义务； （四）在对上市公司并购重组活动及申报文件的真实性、准确性、完整性进行充分核查和验证的基础上，依据中国证监会的规定和监管要求，客观、公正地发表专业意见； （五）接受委托人的委托，向中国证监会报送有关上市公司并购重组的申报材料，并根据中国证监会的审核意见，组织和协调委托人及"},{"i":20,"n":"第二十条","txt":"财务顾问应当与委托人签订委托协议，明确双方的权利和义务，就委托人配合财务顾问履行其职责的义务、应提供的材料和责任划分、双方的保密责任等事项做出约定。财务顾问接受上市公司并购重组多方当事人委托的，不得存在利益冲突或者潜在的利益冲突。 接受委托的，财务顾问应当指定2名财务顾问主办人负责，同时，可以安排一名项目协办人参与。"},{"i":21,"n":"第二十一条","txt":"财务顾问应当建立尽职调查制度和具体工作规程，对上市公司并购重组活动进行充分、广泛、合理的调查，核查委托人提供的为出具专业意见所需的资料，对委托人披露的内容进行独立判断，并有充分理由确信所作的判断与委托人披露的内容不存在实质性差异。 委托人应当配合财务顾问进行尽职调查，提供相应的文件资料。委托人不能提供必要的材料、不配合进行尽职调查或者限制调查范围的，财务顾问应当终止委托关系或者相应修改其结论性意见。"},{"i":22,"n":"第二十二条","txt":"财务顾问利用其他证券服务机构专业意见的，应当进行必要的审慎核查，对委托人提供的资料和披露的信息进行独立判断。 财务顾问对同一事项所作的判断与其他证券服务机构的专业意见存在重大差异的，应当进一步调查、复核，并可自行聘请相关专业机构提供专业服务。"},{"i":23,"n":"第二十三条","txt":"财务顾问应当采取有效方式对新进入上市公司的董事、监事和高级管理人员、控股股东和实际控制人的主要负责人进行证券市场规范化运作的辅导，包括上述人员应履行的责任和义务、上市公司治理的基本原则、公司决策的法定程序和信息披露的基本要求，并对辅导结果进行验收，将验收结果存档。验收不合格的，财务顾问应当重新进行辅导和验收。"},{"i":24,"n":"第二十四条","txt":"财务顾问对上市公司并购重组活动进行尽职调查应当重点关注以下问题，并在专业意见中对以下问题进行分析和说明： （一）涉及上市公司收购的，担任收购人的财务顾问，应当关注收购人的收购目的、实力、收购人与其控股股东和实际控制人的控制关系结构、管理经验、资信情况、诚信记录、资金来源、履约能力、后续计划、对上市公司未来发展的影响、收购人的承诺及是否具备履行相关承诺的能力等事项；因国有股行政划转或者变更、在同一实际控制人控制的不同主体之间转让股份、继承取得上市公司股份超过30%的，收购人可免于聘请财务顾问； （二）涉及对上市公司进行要约收购的，收购人的财务顾问除关注本条第（一）项所列事项外，还应当关注要约收购的目的、收购人的支付方式和支付条件、履约能力、是否将导致公司退市、对收购完成后剩余中小股东的保护机制是否适当等事项； 收购人公告要约收购报告书摘要后15日内未能发出要约的，财务顾问应当督促收购人立"},{"i":25,"n":"第二十五条","txt":"财务顾问应当设立由专业人员组成的内部核查机构，内部核查机构应当恪尽职守，保持独立判断，对相关业务活动进行充分论证与复核，并就所出具的财务顾问专业意见提出内部核查意见。"},{"i":26,"n":"第二十六条","txt":"财务顾问应当在充分尽职调查和内部核查的基础上，按照中国证监会的相关规定，对并购重组事项出具财务顾问专业意见，并作出以下承诺： （一）已按照规定履行尽职调查义务，有充分理由确信所发表的专业意见与委托人披露的文件内容不存在实质性差异； （二）已对委托人披露的文件进行核查，确信披露文件的内容与格式符合要求； （三）有充分理由确信委托人委托财务顾问出具意见的并购重组方案符合法律、法规和中国证监会及证券交易所的相关规定，所披露的信息真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏； （四）有关本次并购重组事项的财务顾问专业意见已提交内部核查机构审查，并同意出具此专业意见； （五）在与委托人接触后到担任财务顾问期间，已采取严格的保密措施，严格执行风险控制和内部隔离制度，不存在内幕交易、操纵市场和证券欺诈问题。"},{"i":27,"n":"第二十七条","txt":"财务顾问的法定代表人或者其授权代表人、部门负责人、内部核查机构负责人、财务顾问主办人和项目协办人应当在财务顾问专业意见上签名，并加盖财务顾问单位公章。"},{"i":28,"n":"第二十八条","txt":"财务顾问代表委托人向中国证监会提交申请文件后，应当配合中国证监会的审核，并承担以下工作： （一）指定财务顾问主办人与中国证监会进行专业沟通，并按照中国证监会提出的反馈意见作出回复； （二）按照中国证监会的要求对涉及本次并购重组活动的特定事项进行尽职调查或者核查； （三）组织委托人及其他专业机构对中国证监会的意见进行答复； （四）委托人未能在行政许可的期限内公告相关并购重组报告全文的，财务顾问应当督促委托人及时公开披露中国证监会提出的问题及委托人未能如期公告的原因； （五）自申报至并购重组事项完成前，对于上市公司和其他并购重组当事人发生较大变化对本次并购重组构成较大影响的情况予以高度关注，并及时向中国证监会报告； （六）申报本次担任并购重组财务顾问的收费情况； （七）中国证监会要求的其他事项。"},{"i":29,"n":"第二十九条","txt":"财务顾问应当建立健全内部报告制度，财务顾问主办人应当就中国证监会在反馈意见中提出的问题按照内部程序向部门负责人、内部核查机构负责人等相关负责人报告，并对中国证监会提出的问题进行充分的研究、论证，审慎回复。回复意见应当由财务顾问的法定代表人或者其授权代表人、财务顾问主办人和项目协办人签名，并加盖财务顾问单位公章。"},{"i":30,"n":"第三十条","txt":"财务顾问将申报文件报中国证监会审核期间，委托人和财务顾问终止委托协议的，财务顾问和委托人应当自终止之日起5个工作日内向中国证监会报告，申请撤回申报文件，并说明原因。委托人重新聘请财务顾问就同一并购重组事项进行申报的，应当在报送中国证监会的申报文件中予以说明。"},{"i":31,"n":"第三十一条","txt":"根据中国证监会有关并购重组的规定，自上市公司收购、重大资产重组、发行股份购买资产、合并等事项完成后的规定期限内，财务顾问承担持续督导责任。 财务顾问应当通过日常沟通、定期回访等方式，结合上市公司定期报告的披露，做好以下持续督导工作： （一）督促并购重组当事人按照相关程序规范实施并购重组方案，及时办理产权过户手续，并依法履行报告和信息披露的义务； （二）督促上市公司按照《上市公司治理准则》的要求规范运作； （三）督促和检查申报人履行对市场公开作出的相关承诺的情况； （四）督促和检查申报人落实后续计划及并购重组方案中约定的其他相关义务的情况； （五）结合上市公司定期报告，核查并购重组是否按计划实施、是否达到预期目标；其实施效果是否与此前公告的专业意见存在较大差异，是否实现相关盈利预测或者管理层预计达到的业绩目标； （六）中国证监会要求的其他事项。 在持续督导期间，财务顾问应当结合上市公司披"},{"i":32,"n":"第三十二条","txt":"财务顾问应当建立健全内部检查制度，确保财务顾问主办人切实履行持续督导责任，按时向中国证监会派出机构提交持续督导工作的情况报告。 在持续督导期间，财务顾问解除委托协议的，应当及时向中国证监会派出机构作出书面报告，说明无法继续履行持续督导职责的理由，并予以公告。委托人应当在一个月内另行聘请财务顾问对其进行持续督导。"},{"i":33,"n":"第三十三条","txt":"财务顾问应当建立并购重组工作档案和工作底稿制度，为每一项目建立独立的工作档案。 财务顾问的工作档案和工作底稿应当真实、准确、完整，保存期不少于10年。"},{"i":34,"n":"第三十四条","txt":"财务顾问及其财务顾问主办人应当严格履行保密责任，不得利用职务之便买卖相关上市公司的证券或者牟取其他不当利益，并应当督促委托人、委托人的董事、监事和高级管理人员及其他内幕信息知情人严格保密，不得进行内幕交易。 财务顾问应当按照中国证监会的要求，配合提供上市公司并购重组相关内幕信息知情人买卖、持有相关上市公司证券的文件，并向中国证监会报告内幕信息知情人的违法违规行为，配合中国证监会依法进行的调查。"},{"i":35,"n":"第三十五条","txt":"财务顾问从事上市公司并购重组财务顾问业务，应当公平竞争，按照业务复杂程度及所承担的责任和风险与委托人商议财务顾问报酬，不得以明显低于行业水平等不正当竞争手段招揽业务。"},{"i":36,"n":"第三十六条","txt":"中国证券业协会可以根据本办法的规定，制定财务顾问执业规范，组织财务顾问主办人进行持续培训。 财务顾问可以申请加入中国证券业协会。财务顾问主办人应当参加中国证券业协会组织的相关培训，接受后续教育。"},{"i":37,"n":"第三十七条","txt":"中国证监会及其派出机构可以根据审慎监管原则，要求财务顾问提供已按照本办法的规定履行尽职调查义务的证明材料、工作档案和工作底稿，并对财务顾问的公司治理、内部控制、经营运作、风险状况、从业活动等方面进行非现场检查或者现场检查。 财务顾问及其有关人员应当配合中国证监会及其派出机构的检查工作，提交的材料应当真实、准确、完整，不得以任何理由拒绝、拖延提供有关材料，或者提供不真实、不准确、不完整的材料。"},{"i":38,"n":"第三十八条","txt":"中国证监会建立监管信息系统，对财务顾问及其财务顾问主办人进行持续动态监管，并将以下事项记入其诚信档案： （一）财务顾问及其财务顾问主办人被中国证监会采取监管措施的； （二）在持续督导期间，上市公司或者其他委托人违反公司治理有关规定、相关资产状况及上市公司经营成果等与财务顾问的专业意见出现较大差异的； （三）中国证监会认定的其他事项。"},{"i":39,"n":"第三十九条","txt":"财务顾问及其财务顾问主办人出现下列情形之一的，中国证监会对其采取监管谈话、出具警示函、责令改正等监管措施： （一）内部控制机制和管理制度、尽职调查制度以及相关业务规则存在重大缺陷或者未得到有效执行的； （二）未按照本办法规定发表专业意见的； （三）在受托报送申报材料过程中，未切实履行组织、协调义务、申报文件制作质量低下的； （四）未依法履行持续督导义务的； （五）未按照本办法的规定向中国证监会报告或者公告的； （六）违反其就上市公司并购重组相关业务活动所作承诺的； （七）违反保密制度或者未履行保密责任的； （八）采取不正当竞争手段进行恶性竞争的； （九）唆使、协助或者伙同委托人干扰中国证监会审核工作的； （十）中国证监会认定的其他情形。 责令改正的，财务顾问及其财务顾问主办人在改正期间，或者按照要求完成整改并经中国证监会验收合格之前，不得接受新的上市公司并购重组财务顾问业务。"},{"i":40,"n":"第四十条","txt":"上市公司就并购重组事项出具盈利预测报告的，在相关并购重组活动完成后，凡不属于上市公司管理层事前无法获知且事后无法控制的原因，上市公司或者购买资产实现的利润未达到盈利预测报告或者资产评估报告预测金额80%的，中国证监会责令财务顾问及其财务顾问主办人在股东大会及中国证监会指定报刊上公开说明未实现盈利预测的原因并向股东和社会公众投资者道歉；利润实现数未达到盈利预测50%的，中国证监会可以同时对财务顾问及其财务顾问主办人采取监管谈话、出具警示函、责令定期报告等监管措施。"},{"i":41,"n":"第四十一条","txt":"财务顾问不再符合本办法规定条件的，应当在5个工作日内向中国证监会报告并依法进行公告，由中国证监会责令改正。责令改正期满后，仍不符合本办法规定条件的，中国证监会撤销其从事上市公司并购重组财务顾问业务资格。 财务顾问主办人发生变化的，财务顾问应当在5个工作日内向中国证监会报告。财务顾问主办人不再符合本办法规定条件的，中国证监会将其从财务顾问主办人名单中去除，财务顾问不得聘请其作为财务顾问主办人从事相关业务。"},{"i":42,"n":"第四十二条","txt":"财务顾问及其财务顾问主办人或者其他责任人员所发表的专业意见存在虚假记载、误导性陈述或者重大遗漏的，中国证监会责令改正并依据《证券法》第二百二十三条的规定予以处罚。"},{"i":43,"n":"第四十三条","txt":"财务顾问及其财务顾问主办人在相关并购重组信息未依法公开前，泄漏该信息、买卖或者建议他人买卖该公司证券，利用相关并购重组信息散布虚假信息、操纵证券市场或者进行证券欺诈活动的，中国证监会依据《证券法》第二百零二条、第二百零三条、第二百零七条等相关规定予以处罚；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"中国证券业协会对财务顾问及其财务顾问主办人违反自律规范的行为，依法进行调查，给予纪律处分。"},{"i":45,"n":"第四十五条","txt":"本办法自2008年8月4日起施行。"}],"shangshigongsishougouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范上市公司的收购及相关股份权益变动活动，保护上市公司和投资者的合法权益，维护证券市场秩序和社会公共利益，促进证券市场资源的优化配置，根据《证券法》、《公司法》及其他相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"上市公司的收购及相关股份权益变动活动，必须遵守法律、行政法规及中国证券监督管理委员会（以下简称中国证监会）的规定。当事人应当诚实守信，遵守社会公德、商业道德，自觉维护证券市场秩序，接受政府、社会公众的监督。"},{"i":3,"n":"第三条","txt":"上市公司的收购及相关股份权益变动活动，必须遵循公开、公平、公正的原则。 上市公司的收购及相关股份权益变动活动中的信息披露义务人，应当充分披露其在上市公司中的权益及变动情况，依法严格履行报告、公告和其他法定义务。在相关信息披露前，负有保密义务。 信息披露义务人报告、公告的信息必须真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":4,"n":"第四条","txt":"上市公司的收购及相关股份权益变动活动不得危害国家安全和社会公共利益。 上市公司的收购及相关股份权益变动活动涉及国家产业政策、行业准入、国有股份转让等事项，需要取得国家相关部门批准的，应当在取得批准后进行。 外国投资者进行上市公司的收购及相关股份权益变动活动的，应当取得国家相关部门的批准，适用中国法律，服从中国的司法、仲裁管辖。"},{"i":5,"n":"第五条","txt":"收购人可以通过取得股份的方式成为一个上市公司的控股股东，可以通过投资关系、协议、其他安排的途径成为一个上市公司的实际控制人，也可以同时采取上述方式和途径取得上市公司控制权。 收购人包括投资者及与其一致行动的他人。"},{"i":6,"n":"第六条","txt":"任何人不得利用上市公司的收购损害被收购公司及其股东的合法权益。 有下列情形之一的，不得收购上市公司： （一）收购人负有数额较大债务，到期未清偿，且处于持续状态； （二）收购人最近3年有重大违法行为或者涉嫌有重大违法行为； （三）收购人最近3年有严重的证券市场失信行为； （四）收购人为自然人的，存在《公司法》第一百四十六条规定情形； （五）法律、行政法规规定以及中国证监会认定的不得收购上市公司的其他情形。"},{"i":7,"n":"第七条","txt":"被收购公司的控股股东或者实际控制人不得滥用股东权利损害被收购公司或者其他股东的合法权益。 被收购公司的控股股东、实际控制人及其关联方有损害被收购公司及其他股东合法权益的，上述控股股东、实际控制人在转让被收购公司控制权之前，应当主动消除损害；未能消除损害的，应当就其出让相关股份所得收入用于消除全部损害做出安排，对不足以消除损害的部分应当提供充分有效的履约担保或安排，并依照公司章程取得被收购公司股东大会的批准。"},{"i":8,"n":"第八条","txt":"被收购公司的董事、监事、高级管理人员对公司负有忠实义务和勤勉义务，应当公平对待收购本公司的所有收购人。 被收购公司董事会针对收购所做出的决策及采取的措施，应当有利于维护公司及其股东的利益，不得滥用职权对收购设置不适当的障碍，不得利用公司资源向收购人提供任何形式的财务资助，不得损害公司及其股东的合法权益。"},{"i":9,"n":"第九条","txt":"收购人进行上市公司的收购，应当聘请符合《证券法》规定的专业机构担任财务顾问。收购人未按照本办法规定聘请财务顾问的，不得收购上市公司。 财务顾问应当勤勉尽责，遵守行业规范和职业道德，保持独立性，保证其所制作、出具文件的真实性、准确性和完整性。 财务顾问认为收购人利用上市公司的收购损害被收购公司及其股东合法权益的，应当拒绝为收购人提供财务顾问服务。 财务顾问不得教唆、协助或者伙同委托人编制或披露存在虚假记载、误导性陈述或者重大遗漏的报告、公告文件，不得从事不正当竞争，不得利用上市公司的收购谋取不正当利益。 为上市公司收购出具资产评估报告、审计报告、法律意见书的证券服务机构及其从业人员，应当遵守法律、行政法规、中国证监会的有关规定，以及证券交易所的相关规则，遵循本行业公认的业务标准和道德规范，诚实守信，勤勉尽责，对其所制作、出具文件的真实性、准确性和完整性承担责任。"},{"i":10,"n":"第十条","txt":"中国证监会依法对上市公司的收购及相关股份权益变动活动进行监督管理。 中国证监会设立由专业人员和有关专家组成的专门委员会。专门委员会可以根据中国证监会职能部门的请求，就是否构成上市公司的收购、是否有不得收购上市公司的情形以及其他相关事宜提供咨询意见。中国证监会依法做出决定。"},{"i":11,"n":"第十一条","txt":"证券交易所依法制定业务规则，为上市公司的收购及相关股份权益变动活动组织交易和提供服务，对相关证券交易活动进行实时监控，监督上市公司的收购及相关股份权益变动活动的信息披露义务人切实履行信息披露义务。 证券登记结算机构依法制定业务规则，为上市公司的收购及相关股份权益变动活动所涉及的证券登记、存管、结算等事宜提供服务。"},{"i":12,"n":"第十二条","txt":"投资者在一个上市公司中拥有的权益，包括登记在其名下的股份和虽未登记在其名下但该投资者可以实际支配表决权的股份。投资者及其一致行动人在一个上市公司中拥有的权益应当合并计算。"},{"i":13,"n":"第十三条","txt":"通过证券交易所的证券交易，投资者及其一致行动人拥有权益的股份达到一个上市公司已发行股份的5%时，应当在该事实发生之日起3日内编制权益变动报告书，向中国证监会、证券交易所提交书面报告，通知该上市公司，并予公告；在上述期限内，不得再行买卖该上市公司的股票，但中国证监会规定的情形除外。 前述投资者及其一致行动人拥有权益的股份达到一个上市公司已发行股份的5%后，通过证券交易所的证券交易，其拥有权益的股份占该上市公司已发行股份的比例每增加或者减少5%，应当依照前款规定进行报告和公告。在该事实发生之日起至公告后3日内，不得再行买卖该上市公司的股票，但中国证监会规定的情形除外。 前述投资者及其一致行动人拥有权益的股份达到一个上市公司已发行股份的5%后，其拥有权益的股份占该上市公司已发行股份的比例每增加或者减少1%，应当在该事实发生的次日通知该上市公司，并予公告。 违反本条第一款、第二款的规定买入在上"},{"i":14,"n":"第十四条","txt":"通过协议转让方式，投资者及其一致行动人在一个上市公司中拥有权益的股份拟达到或者超过一个上市公司已发行股份的5%时，应当在该事实发生之日起3日内编制权益变动报告书，向中国证监会、证券交易所提交书面报告，通知该上市公司，并予公告。 前述投资者及其一致行动人拥有权益的股份达到一个上市公司已发行股份的5%后，其拥有权益的股份占该上市公司已发行股份的比例每增加或者减少达到或者超过5%的，应当依照前款规定履行报告、公告义务。 前两款规定的投资者及其一致行动人在作出报告、公告前，不得再行买卖该上市公司的股票。相关股份转让及过户登记手续按照本办法第四章及证券交易所、证券登记结算机构的规定办理。"},{"i":15,"n":"第十五条","txt":"投资者及其一致行动人通过行政划转或者变更、执行法院裁定、继承、赠与等方式拥有权益的股份变动达到前条规定比例的，应当按照前条规定履行报告、公告义务，并参照前条规定办理股份过户登记手续。"},{"i":16,"n":"第十六条","txt":"投资者及其一致行动人不是上市公司的第一大股东或者实际控制人，其拥有权益的股份达到或者超过该公司已发行股份的5%，但未达到20%的，应当编制包括下列内容的简式权益变动报告书： （一）投资者及其一致行动人的姓名、住所；投资者及其一致行动人为法人的，其名称、注册地及法定代表人； （二）持股目的，是否有意在未来12个月内继续增加其在上市公司中拥有的权益； （三）上市公司的名称、股票的种类、数量、比例； （四）在上市公司中拥有权益的股份达到或者超过上市公司已发行股份的5%或者拥有权益的股份增减变化达到5%的时间及方式、增持股份的资金来源； （五）在上市公司中拥有权益的股份变动的时间及方式； （六）权益变动事实发生之日前6个月内通过证券交易所的证券交易买卖该公司股票的简要情况； （七）中国证监会、证券交易所要求披露的其他内容。 前述投资者及其一致行动人为上市公司第一大股东或者实际控制人，其拥有权益"},{"i":17,"n":"第十七条","txt":"投资者及其一致行动人拥有权益的股份达到或者超过一个上市公司已发行股份的20%但未超过30%的，应当编制详式权益变动报告书，除须披露前条规定的信息外，还应当披露以下内容： （一）投资者及其一致行动人的控股股东、实际控制人及其股权控制关系结构图； （二）取得相关股份的价格、所需资金额，或者其他支付安排； （三）投资者、一致行动人及其控股股东、实际控制人所从事的业务与上市公司的业务是否存在同业竞争或者潜在的同业竞争，是否存在持续关联交易；存在同业竞争或者持续关联交易的，是否已做出相应的安排，确保投资者、一致行动人及其关联方与上市公司之间避免同业竞争以及保持上市公司的独立性； （四）未来12个月内对上市公司资产、业务、人员、组织结构、公司章程等进行调整的后续计划； （五）前24个月内投资者及其一致行动人与上市公司之间的重大交易； （六）不存在本办法第六条规定的情形； （七）能够按照本办法第五十"},{"i":18,"n":"第十八条","txt":"已披露权益变动报告书的投资者及其一致行动人在披露之日起6个月内，因拥有权益的股份变动需要再次报告、公告权益变动报告书的，可以仅就与前次报告书不同的部分作出报告、公告；自前次披露之日起超过6个月的，投资者及其一致行动人应当按照本章的规定编制权益变动报告书，履行报告、公告义务。"},{"i":19,"n":"第十九条","txt":"因上市公司减少股本导致投资者及其一致行动人拥有权益的股份变动出现本办法第十四条规定情形的，投资者及其一致行动人免于履行报告和公告义务。上市公司应当自完成减少股本的变更登记之日起2个工作日内，就因此导致的公司股东拥有权益的股份变动情况作出公告；因公司减少股本可能导致投资者及其一致行动人成为公司第一大股东或者实际控制人的，该投资者及其一致行动人应当自公司董事会公告有关减少公司股本决议之日起3个工作日内，按照本办法第十七条第一款的规定履行报告、公告义务。"},{"i":20,"n":"第二十条","txt":"上市公司的收购及相关股份权益变动活动中的信息披露义务人依法披露前，相关信息已在媒体上传播或者公司股票交易出现异常的，上市公司应当立即向当事人进行查询，当事人应当及时予以书面答复，上市公司应当及时作出公告。"},{"i":21,"n":"第二十一条","txt":"上市公司的收购及相关股份权益变动活动中的信息披露义务人应当在证券交易所的网站和符合中国证监会规定条件的媒体上依法披露信息；在其他媒体上进行披露的，披露内容应当一致，披露时间不得早于前述披露的时间。"},{"i":22,"n":"第二十二条","txt":"上市公司的收购及相关股份权益变动活动中的信息披露义务人采取一致行动的，可以以书面形式约定由其中一人作为指定代表负责统一编制信息披露文件，并同意授权指定代表在信息披露文件上签字、盖章。 各信息披露义务人应当对信息披露文件中涉及其自身的信息承担责任；对信息披露文件中涉及的与多个信息披露义务人相关的信息，各信息披露义务人对相关部分承担连带责任。"},{"i":23,"n":"第二十三条","txt":"投资者自愿选择以要约方式收购上市公司股份的，可以向被收购公司所有股东发出收购其所持有的全部股份的要约（以下简称全面要约），也可以向被收购公司所有股东发出收购其所持有的部分股份的要约（以下简称部分要约）。"},{"i":24,"n":"第二十四条","txt":"通过证券交易所的证券交易，收购人持有一个上市公司的股份达到该公司已发行股份的30%时，继续增持股份的，应当采取要约方式进行，发出全面要约或者部分要约。"},{"i":25,"n":"第二十五条","txt":"收购人依照本办法第二十三条、第二十四条、第四十七条、第五十六条的规定，以要约方式收购一个上市公司股份的，其预定收购的股份比例均不得低于该上市公司已发行股份的5%。"},{"i":26,"n":"第二十六条","txt":"以要约方式进行上市公司收购的，收购人应当公平对待被收购公司的所有股东。持有同一种类股份的股东应当得到同等对待。"},{"i":27,"n":"第二十七条","txt":"收购人为终止上市公司的上市地位而发出全面要约的，或者因不符合本办法第六章的规定而发出全面要约的，应当以现金支付收购价款；以依法可以转让的证券（以下简称证券）支付收购价款的，应当同时提供现金方式供被收购公司股东选择。"},{"i":28,"n":"第二十八条","txt":"以要约方式收购上市公司股份的，收购人应当编制要约收购报告书，聘请财务顾问，通知被收购公司，同时对要约收购报告书摘要作出提示性公告。 本次收购依法应当取得相关部门批准的，收购人应当在要约收购报告书摘要中作出特别提示，并在取得批准后公告要约收购报告书。"},{"i":29,"n":"第二十九条","txt":"前条规定的要约收购报告书，应当载明下列事项： （一）收购人的姓名、住所；收购人为法人的，其名称、注册地及法定代表人，与其控股股东、实际控制人之间的股权控制关系结构图； （二）收购人关于收购的决定及收购目的，是否拟在未来12个月内继续增持； （三）上市公司的名称、收购股份的种类； （四）预定收购股份的数量和比例； （五）收购价格； （六）收购所需资金额、资金来源及资金保证，或者其他支付安排； （七）收购要约约定的条件； （八）收购期限； （九）公告收购报告书时持有被收购公司的股份数量、比例； （十）本次收购对上市公司的影响分析，包括收购人及其关联方所从事的业务与上市公司的业务是否存在同业竞争或者潜在的同业竞争，是否存在持续关联交易；存在同业竞争或者持续关联交易的，收购人是否已作出相应的安排，确保收购人及其关联方与上市公司之间避免同业竞争以及保持上市公司的独立性； （十一）未来12个月内对"},{"i":30,"n":"第三十条","txt":"收购人按照本办法第四十七条拟收购上市公司股份超过30%，须改以要约方式进行收购的，收购人应当在达成收购协议或者做出类似安排后的3日内对要约收购报告书摘要作出提示性公告，并按照本办法第二十八条、第二十九条的规定履行公告义务，同时免于编制、公告上市公司收购报告书；依法应当取得批准的，应当在公告中特别提示本次要约须取得相关批准方可进行。 未取得批准的，收购人应当在收到通知之日起2个工作日内，公告取消收购计划，并通知被收购公司。"},{"i":31,"n":"第三十一条","txt":"收购人自作出要约收购提示性公告起60日内，未公告要约收购报告书的，收购人应当在期满后次一个工作日通知被收购公司，并予公告；此后每30日应当公告一次，直至公告要约收购报告书。 收购人作出要约收购提示性公告后，在公告要约收购报告书之前，拟自行取消收购计划的，应当公告原因；自公告之日起12个月内，该收购人不得再次对同一上市公司进行收购。"},{"i":32,"n":"第三十二条","txt":"被收购公司董事会应当对收购人的主体资格、资信情况及收购意图进行调查，对要约条件进行分析，对股东是否接受要约提出建议，并聘请独立财务顾问提出专业意见。在收购人公告要约收购报告书后20日内，被收购公司董事会应当公告被收购公司董事会报告书与独立财务顾问的专业意见。 收购人对收购要约条件做出重大变更的，被收购公司董事会应当在3个工作日内公告董事会及独立财务顾问就要约条件的变更情况所出具的补充意见。"},{"i":33,"n":"第三十三条","txt":"收购人作出提示性公告后至要约收购完成前，被收购公司除继续从事正常的经营活动或者执行股东大会已经作出的决议外，未经股东大会批准，被收购公司董事会不得通过处置公司资产、对外投资、调整公司主要业务、担保、贷款等方式，对公司的资产、负债、权益或者经营成果造成重大影响。"},{"i":34,"n":"第三十四条","txt":"在要约收购期间，被收购公司董事不得辞职。"},{"i":35,"n":"第三十五条","txt":"收购人按照本办法规定进行要约收购的，对同一种类股票的要约价格，不得低于要约收购提示性公告日前6个月内收购人取得该种股票所支付的最高价格。 要约价格低于提示性公告日前30个交易日该种股票的每日加权平均价格的算术平均值的，收购人聘请的财务顾问应当就该种股票前6个月的交易情况进行分析，说明是否存在股价被操纵、收购人是否有未披露的一致行动人、收购人前6个月取得公司股份是否存在其他支付安排、要约价格的合理性等。"},{"i":36,"n":"第三十六条","txt":"收购人可以采用现金、证券、现金与证券相结合等合法方式支付收购上市公司的价款。收购人以证券支付收购价款的，应当提供该证券的发行人最近3年经审计的财务会计报告、证券估值报告，并配合被收购公司聘请的独立财务顾问的尽职调查工作。收购人以在证券交易所上市的债券支付收购价款的，该债券的可上市交易时间应当不少于一个月。收购人以未在证券交易所上市交易的证券支付收购价款的，必须同时提供现金方式供被收购公司的股东选择，并详细披露相关证券的保管、送达被收购公司股东的方式和程序安排。 收购人聘请的财务顾问应当对收购人支付收购价款的能力和资金来源进行充分的尽职调查，详细披露核查的过程和依据，说明收购人是否具备要约收购的能力。收购人应当在作出要约收购提示性公告的同时，提供以下至少一项安排保证其具备履约能力： （一）以现金支付收购价款的，将不少于收购价款总额的20%作为履约保证金存入证券登记结算机构指定的银行；收购"},{"i":37,"n":"第三十七条","txt":"收购要约约定的收购期限不得少于30日，并不得超过60日；但是出现竞争要约的除外。 在收购要约约定的承诺期限内，收购人不得撤销其收购要约。"},{"i":38,"n":"第三十八条","txt":"采取要约收购方式的，收购人作出公告后至收购期限届满前，不得卖出被收购公司的股票，也不得采取要约规定以外的形式和超出要约的条件买入被收购公司的股票。"},{"i":39,"n":"第三十九条","txt":"收购要约提出的各项收购条件，适用于被收购公司的所有股东。 上市公司发行不同种类股份的，收购人可以针对持有不同种类股份的股东提出不同的收购条件。 收购人需要变更收购要约的，必须及时公告，载明具体变更事项，并通知被收购公司。变更收购要约不得存在下列情形： （一）降低收购价格； （二）减少预定收购股份数额； （三）缩短收购期限； （四）中国证监会规定的其他情形。"},{"i":40,"n":"第四十条","txt":"收购要约期限届满前15日内，收购人不得变更收购要约；但是出现竞争要约的除外。 出现竞争要约时，发出初始要约的收购人变更收购要约距初始要约收购期限届满不足15日的，应当延长收购期限，延长后的要约期应当不少于15日，不得超过最后一个竞争要约的期满日，并按规定追加履约保证。 发出竞争要约的收购人最迟不得晚于初始要约收购期限届满前15日发出要约收购的提示性公告，并应当根据本办法第二十八条和第二十九条的规定履行公告义务。"},{"i":41,"n":"第四十一条","txt":"要约收购报告书所披露的基本事实发生重大变化的，收购人应当在该重大变化发生之日起2个工作日内作出公告，并通知被收购公司。"},{"i":42,"n":"第四十二条","txt":"同意接受收购要约的股东（以下简称预受股东），应当委托证券公司办理预受要约的相关手续。收购人应当委托证券公司向证券登记结算机构申请办理预受要约股票的临时保管。证券登记结算机构临时保管的预受要约的股票，在要约收购期间不得转让。 前款所称预受，是指被收购公司股东同意接受要约的初步意思表示，在要约收购期限内不可撤回之前不构成承诺。在要约收购期限届满3个交易日前，预受股东可以委托证券公司办理撤回预受要约的手续，证券登记结算机构根据预受要约股东的撤回申请解除对预受要约股票的临时保管。在要约收购期限届满前3个交易日内，预受股东不得撤回其对要约的接受。在要约收购期限内，收购人应当每日在证券交易所网站上公告已预受收购要约的股份数量。 出现竞争要约时，接受初始要约的预受股东撤回全部或者部分预受的股份，并将撤回的股份售予竞争要约人的，应当委托证券公司办理撤回预受初始要约的手续和预受竞争要约的相关手续。"},{"i":43,"n":"第四十三条","txt":"收购期限届满，发出部分要约的收购人应当按照收购要约约定的条件购买被收购公司股东预受的股份，预受要约股份的数量超过预定收购数量时，收购人应当按照同等比例收购预受要约的股份；以终止被收购公司上市地位为目的的，收购人应当按照收购要约约定的条件购买被收购公司股东预受的全部股份；因不符合本办法第六章的规定而发出全面要约的收购人应当购买被收购公司股东预受的全部股份。 收购期限届满后3个交易日内，接受委托的证券公司应当向证券登记结算机构申请办理股份转让结算、过户登记手续，解除对超过预定收购比例的股票的临时保管；收购人应当公告本次要约收购的结果。"},{"i":44,"n":"第四十四条","txt":"收购期限届满，被收购公司股权分布不符合证券交易所规定的上市交易要求，该上市公司的股票由证券交易所依法终止上市交易。在收购行为完成前，其余仍持有被收购公司股票的股东，有权在收购报告书规定的合理期限内向收购人以收购要约的同等条件出售其股票，收购人应当收购。"},{"i":45,"n":"第四十五条","txt":"收购期限届满后15日内，收购人应当向证券交易所提交关于收购情况的书面报告，并予以公告。"},{"i":46,"n":"第四十六条","txt":"除要约方式外，投资者不得在证券交易所外公开求购上市公司的股份。"},{"i":47,"n":"第四十七条","txt":"收购人通过协议方式在一个上市公司中拥有权益的股份达到或者超过该公司已发行股份的5%，但未超过30%的，按照本办法第二章的规定办理。 收购人拥有权益的股份达到该公司已发行股份的30%时，继续进行收购的，应当依法向该上市公司的股东发出全面要约或者部分要约。符合本办法第六章规定情形的，收购人可以免于发出要约。 收购人拟通过协议方式收购一个上市公司的股份超过30%的，超过30%的部分，应当改以要约方式进行；但符合本办法第六章规定情形的，收购人可以免于发出要约。符合前述规定情形的，收购人可以履行其收购协议；不符合前述规定情形的，在履行其收购协议前，应当发出全面要约。"},{"i":48,"n":"第四十八条","txt":"以协议方式收购上市公司股份超过30%，收购人拟依据本办法第六十二条、第六十三条第一款第（一）项、第（二）项、第（十）项的规定免于发出要约的，应当在与上市公司股东达成收购协议之日起3日内编制上市公司收购报告书，通知被收购公司，并公告上市公司收购报告书摘要。 收购人应当在收购报告书摘要公告后5日内，公告其收购报告书、财务顾问专业意见和律师出具的法律意见书；不符合本办法第六章规定的情形的，应当予以公告，并按照本办法第六十一条第二款的规定办理。"},{"i":49,"n":"第四十九条","txt":"依据前条规定所作的上市公司收购报告书，须披露本办法第二十九条第（一）项至第（六）项和第（九）项至第（十四）项规定的内容及收购协议的生效条件和付款安排。 已披露收购报告书的收购人在披露之日起6个月内，因权益变动需要再次报告、公告的，可以仅就与前次报告书不同的部分作出报告、公告；超过6个月的，应当按照本办法第二章的规定履行报告、公告义务。"},{"i":50,"n":"第五十条","txt":"收购人公告上市公司收购报告书时，应当提交以下备查文件： （一）中国公民的身份证明，或者在中国境内登记注册的法人、其他组织的证明文件； （二）基于收购人的实力和从业经验对上市公司后续发展计划可行性的说明，收购人拟修改公司章程、改选公司董事会、改变或者调整公司主营业务的，还应当补充其具备规范运作上市公司的管理能力的说明； （三）收购人及其关联方与被收购公司存在同业竞争、关联交易的，应提供避免同业竞争等利益冲突、保持被收购公司经营独立性的说明； （四）收购人为法人或者其他组织的，其控股股东、实际控制人最近2年未变更的说明； （五）收购人及其控股股东或实际控制人的核心企业和核心业务、关联企业及主营业务的说明；收购人或其实际控制人为两个或两个以上的上市公司控股股东或实际控制人的，还应当提供其持股5%以上的上市公司以及银行、信托公司、证券公司、保险公司等其他金融机构的情况说明； （六）财务顾问关于"},{"i":51,"n":"第五十一条","txt":"上市公司董事、监事、高级管理人员、员工或者其所控制或者委托的法人或者其他组织，拟对本公司进行收购或者通过本办法第五章规定的方式取得本公司控制权（以下简称管理层收购）的，该上市公司应当具备健全且运行良好的组织机构以及有效的内部控制制度，公司董事会成员中独立董事的比例应当达到或者超过1/2。公司应当聘请符合《证券法》规定的资产评估机构提供公司资产评估报告，本次收购应当经董事会非关联董事作出决议，且取得2/3以上的独立董事同意后，提交公司股东大会审议，经出席股东大会的非关联股东所持表决权过半数通过。独立董事发表意见前，应当聘请独立财务顾问就本次收购出具专业意见，独立董事及独立财务顾问的意见应当一并予以公告。 上市公司董事、监事、高级管理人员存在《公司法》第一百四十八条规定情形，或者最近3年有证券市场不良诚信记录的，不得收购本公司。"},{"i":52,"n":"第五十二条","txt":"以协议方式进行上市公司收购的，自签订收购协议起至相关股份完成过户的期间为上市公司收购过渡期（以下简称过渡期）。在过渡期内，收购人不得通过控股股东提议改选上市公司董事会，确有充分理由改选董事会的，来自收购人的董事不得超过董事会成员的1/3；被收购公司不得为收购人及其关联方提供担保；被收购公司不得公开发行股份募集资金，不得进行重大购买、出售资产及重大投资行为或者与收购人及其关联方进行其他关联交易，但收购人为挽救陷入危机或者面临严重财务困难的上市公司的情形除外。"},{"i":53,"n":"第五十三条","txt":"上市公司控股股东向收购人协议转让其所持有的上市公司股份的，应当对收购人的主体资格、诚信情况及收购意图进行调查，并在其权益变动报告书中披露有关调查情况。 控股股东及其关联方未清偿其对公司的负债，未解除公司为其负债提供的担保，或者存在损害公司利益的其他情形的，被收购公司董事会应当对前述情形及时予以披露，并采取有效措施维护公司利益。"},{"i":54,"n":"第五十四条","txt":"协议收购的相关当事人应当向证券登记结算机构申请办理拟转让股份的临时保管手续，并可以将用于支付的现金存放于证券登记结算机构指定的银行。"},{"i":55,"n":"第五十五条","txt":"收购报告书公告后，相关当事人应当按照证券交易所和证券登记结算机构的业务规则，在证券交易所就本次股份转让予以确认后，凭全部转让款项存放于双方认可的银行账户的证明，向证券登记结算机构申请解除拟协议转让股票的临时保管，并办理过户登记手续。 收购人未按规定履行报告、公告义务，或者未按规定提出申请的，证券交易所和证券登记结算机构不予办理股份转让和过户登记手续。 收购人在收购报告书公告后30日内仍未完成相关股份过户手续的，应当立即作出公告，说明理由；在未完成相关股份过户期间，应当每隔30日公告相关股份过户办理进展情况。"},{"i":56,"n":"第五十六条","txt":"收购人虽不是上市公司的股东，但通过投资关系、协议、其他安排导致其拥有权益的股份达到或者超过一个上市公司已发行股份的5%未超过30%的，应当按照本办法第二章的规定办理。 收购人拥有权益的股份超过该公司已发行股份的30%的，应当向该公司所有股东发出全面要约；收购人预计无法在事实发生之日起30日内发出全面要约的，应当在前述30日内促使其控制的股东将所持有的上市公司股份减持至30%或者30%以下，并自减持之日起2个工作日内予以公告；其后收购人或者其控制的股东拟继续增持的，应当采取要约方式；拟依据本办法第六章的规定免于发出要约的，应当按照本办法第四十八条的规定办理。"},{"i":57,"n":"第五十七条","txt":"投资者虽不是上市公司的股东，但通过投资关系取得对上市公司股东的控制权，而受其支配的上市公司股东所持股份达到前条规定比例、且对该股东的资产和利润构成重大影响的，应当按照前条规定履行报告、公告义务。"},{"i":58,"n":"第五十八条","txt":"上市公司实际控制人及受其支配的股东，负有配合上市公司真实、准确、完整披露有关实际控制人发生变化的信息的义务；实际控制人及受其支配的股东拒不履行上述配合义务，导致上市公司无法履行法定信息披露义务而承担民事、行政责任的，上市公司有权对其提起诉讼。实际控制人、控股股东指使上市公司及其有关人员不依法履行信息披露义务的，中国证监会依法进行查处。"},{"i":59,"n":"第五十九条","txt":"上市公司实际控制人及受其支配的股东未履行报告、公告义务的，上市公司应当自知悉之日起立即作出报告和公告。上市公司就实际控制人发生变化的情况予以公告后，实际控制人仍未披露的，上市公司董事会应当向实际控制人和受其支配的股东查询，必要时可以聘请财务顾问进行查询，并将查询情况向中国证监会、上市公司所在地的中国证监会派出机构（以下简称派出机构）和证券交易所报告；中国证监会依法对拒不履行报告、公告义务的实际控制人进行查处。 上市公司知悉实际控制人发生较大变化而未能将有关实际控制人的变化情况及时予以报告和公告的，中国证监会责令改正，情节严重的，认定上市公司负有责任的董事为不适当人选。"},{"i":60,"n":"第六十条","txt":"上市公司实际控制人及受其支配的股东未履行报告、公告义务，拒不履行第五十八条规定的配合义务，或者实际控制人存在不得收购上市公司情形的，上市公司董事会应当拒绝接受受实际控制人支配的股东向董事会提交的提案或者临时议案，并向中国证监会、派出机构和证券交易所报告。中国证监会责令实际控制人改正，可以认定实际控制人通过受其支配的股东所提名的董事为不适当人选；改正前，受实际控制人支配的股东不得行使其持有股份的表决权。上市公司董事会未拒绝接受实际控制人及受其支配的股东所提出的提案的，中国证监会可以认定负有责任的董事为不适当人选。"},{"i":61,"n":"第六十一条","txt":"符合本办法第六十二条、第六十三条规定情形的，投资者及其一致行动人可以： （一）免于以要约收购方式增持股份； （二）存在主体资格、股份种类限制或者法律、行政法规、中国证监会规定的特殊情形的，免于向被收购公司的所有股东发出收购要约。 不符合本章规定情形的，投资者及其一致行动人应当在30日内将其或者其控制的股东所持有的被收购公司股份减持到30%或者30%以下；拟以要约以外的方式继续增持股份的，应当发出全面要约。"},{"i":62,"n":"第六十二条","txt":"有下列情形之一的，收购人可以免于以要约方式增持股份： （一）收购人与出让人能够证明本次股份转让是在同一实际控制人控制的不同主体之间进行，未导致上市公司的实际控制人发生变化； （二）上市公司面临严重财务困难，收购人提出的挽救公司的重组方案取得该公司股东大会批准，且收购人承诺3年内不转让其在该公司中所拥有的权益； （三）中国证监会为适应证券市场发展变化和保护投资者合法权益的需要而认定的其他情形。"},{"i":63,"n":"第六十三条","txt":"有下列情形之一的，投资者可以免于发出要约： （一）经政府或者国有资产管理部门批准进行国有资产无偿划转、变更、合并，导致投资者在一个上市公司中拥有权益的股份占该公司已发行股份的比例超过30%； （二）因上市公司按照股东大会批准的确定价格向特定股东回购股份而减少股本，导致投资者在该公司中拥有权益的股份超过该公司已发行股份的30%； （三）经上市公司股东大会非关联股东批准，投资者取得上市公司向其发行的新股，导致其在该公司拥有权益的股份超过该公司已发行股份的30%，投资者承诺3年内不转让本次向其发行的新股，且公司股东大会同意投资者免于发出要约； （四）在一个上市公司中拥有权益的股份达到或者超过该公司已发行股份的30%的，自上述事实发生之日起一年后，每12个月内增持不超过该公司已发行的2%的股份； （五）在一个上市公司中拥有权益的股份达到或者超过该公司已发行股份的50%的，继续增加其在该公司拥有"},{"i":64,"n":"第六十四条","txt":"收购人按照本章规定的情形免于发出要约的，应当聘请符合《证券法》规定的律师事务所等专业机构出具专业意见。"},{"i":65,"n":"第六十五条","txt":"收购人聘请的财务顾问应当履行以下职责： （一）对收购人的相关情况进行尽职调查； （二）应收购人的要求向收购人提供专业化服务，全面评估被收购公司的财务和经营状况，帮助收购人分析收购所涉及的法律、财务、经营风险，就收购方案所涉及的收购价格、收购方式、支付安排等事项提出对策建议，并指导收购人按照规定的内容与格式制作公告文件； （三）对收购人进行证券市场规范化运作的辅导，使收购人的董事、监事和高级管理人员熟悉有关法律、行政法规和中国证监会的规定，充分了解其应当承担的义务和责任，督促其依法履行报告、公告和其他法定义务； （四）对收购人是否符合本办法的规定及公告文件内容的真实性、准确性、完整性进行充分核查和验证，对收购事项客观、公正地发表专业意见； （五）与收购人签订协议，在收购完成后12个月内，持续督导收购人遵守法律、行政法规、中国证监会的规定、证券交易所规则、上市公司章程，依法行使股东权利，切"},{"i":66,"n":"第六十六条","txt":"收购人聘请的财务顾问就本次收购出具的财务顾问报告，应当对以下事项进行说明和分析，并逐项发表明确意见： （一）收购人编制的上市公司收购报告书或者要约收购报告书所披露的内容是否真实、准确、完整； （二）本次收购的目的； （三）收购人是否提供所有必备证明文件，根据对收购人及其控股股东、实际控制人的实力、从事的主要业务、持续经营状况、财务状况和诚信情况的核查，说明收购人是否具备主体资格，是否具备收购的经济实力，是否具备规范运作上市公司的管理能力，是否需要承担其他附加义务及是否具备履行相关义务的能力，是否存在不良诚信记录； （四）对收购人进行证券市场规范化运作辅导的情况，其董事、监事和高级管理人员是否已经熟悉有关法律、行政法规和中国证监会的规定，充分了解应承担的义务和责任，督促其依法履行报告、公告和其他法定义务的情况； （五）收购人的股权控制结构及其控股股东、实际控制人支配收购人的方式； （六）"},{"i":67,"n":"第六十七条","txt":"上市公司董事会或者独立董事聘请的独立财务顾问，不得同时担任收购人的财务顾问或者与收购人的财务顾问存在关联关系。独立财务顾问应当根据委托进行尽职调查，对本次收购的公正性和合法性发表专业意见。独立财务顾问报告应当对以下问题进行说明和分析，发表明确意见： （一）收购人是否具备主体资格； （二）收购人的实力及本次收购对被收购公司经营独立性和持续发展可能产生的影响分析； （三）收购人是否存在利用被收购公司的资产或者由被收购公司为本次收购提供财务资助的情形； （四）涉及要约收购的，分析被收购公司的财务状况，说明收购价格是否充分反映被收购公司价值，收购要约是否公平、合理，对被收购公司社会公众股股东接受要约提出的建议； （五）涉及收购人以证券支付收购价款的，还应当根据该证券发行人的资产、业务和盈利预测，对相关证券进行估值分析，就收购条件对被收购公司的社会公众股股东是否公平合理、是否接受收购人提出的收购"},{"i":68,"n":"第六十八条","txt":"财务顾问应当在财务顾问报告中作出以下承诺： （一）已按照规定履行尽职调查义务，有充分理由确信所发表的专业意见与收购人公告文件的内容不存在实质性差异； （二）已对收购人公告文件进行核查，确信公告文件的内容与格式符合规定； （三）有充分理由确信本次收购符合法律、行政法规和中国证监会的规定，有充分理由确信收购人披露的信息真实、准确、完整，不存在虚假记载、误导性陈述和重大遗漏； （四）就本次收购所出具的专业意见已提交其内核机构审查，并获得通过； （五）在担任财务顾问期间，已采取严格的保密措施，严格执行内部防火墙制度； （六）与收购人已订立持续督导协议。"},{"i":69,"n":"第六十九条","txt":"财务顾问在收购过程中和持续督导期间，应当关注被收购公司是否存在为收购人及其关联方提供担保或者借款等损害上市公司利益的情形，发现有违法或者不当行为的，应当及时向中国证监会、派出机构和证券交易所报告。"},{"i":70,"n":"第七十条","txt":"财务顾问为履行职责，可以聘请其他专业机构协助其对收购人进行核查，但应当对收购人提供的资料和披露的信息进行独立判断。"},{"i":71,"n":"第七十一条","txt":"自收购人公告上市公司收购报告书至收购完成后12个月内，财务顾问应当通过日常沟通、定期回访等方式，关注上市公司的经营情况，结合被收购公司定期报告和临时公告的披露事宜，对收购人及被收购公司履行持续督导职责： （一）督促收购人及时办理股权过户手续，并依法履行报告和公告义务； （二）督促和检查收购人及被收购公司依法规范运作； （三）督促和检查收购人履行公开承诺的情况； （四）结合被收购公司定期报告，核查收购人落实后续计划的情况，是否达到预期目标，实施效果是否与此前的披露内容存在较大差异，是否实现相关盈利预测或者管理层预计达到的目标； （五）涉及管理层收购的，核查被收购公司定期报告中披露的相关还款计划的落实情况与事实是否一致； （六）督促和检查履行收购中约定的其他义务的情况。 在持续督导期间，财务顾问应当结合上市公司披露的季度报告、半年度报告和年度报告出具持续督导意见，并在前述定期报告披露后的1"},{"i":72,"n":"第七十二条","txt":"在上市公司收购行为完成后12个月内，收购人聘请的财务顾问应当在每季度前3日内就上一季度对上市公司影响较大的投资、购买或者出售资产、关联交易、主营业务调整以及董事、监事、高级管理人员的更换、职工安置、收购人履行承诺等情况向派出机构报告。 收购人注册地与上市公司注册地不同的，还应当将前述情况的报告同时抄报收购人所在地的派出机构。"},{"i":73,"n":"第七十三条","txt":"派出机构根据审慎监管原则，通过与承办上市公司审计业务的会计师事务所谈话、检查财务顾问持续督导责任的落实、定期或者不定期的现场检查等方式，在收购完成后对收购人和上市公司进行监督检查。 派出机构发现实际情况与收购人披露的内容存在重大差异的，对收购人及上市公司予以重点关注，可以责令收购人延长财务顾问的持续督导期，并依法进行查处。 在持续督导期间，财务顾问与收购人解除合同的，收购人应当另行聘请其他财务顾问机构履行持续督导职责。"},{"i":74,"n":"第七十四条","txt":"在上市公司收购中，收购人持有的被收购公司的股份，在收购完成后18个月内不得转让。 收购人在被收购公司中拥有权益的股份在同一实际控制人控制的不同主体之间进行转让不受前述18个月的限制，但应当遵守本办法第六章的规定。"},{"i":75,"n":"第七十五条","txt":"上市公司的收购及相关股份权益变动活动中的信息披露义务人，未按照本办法的规定履行报告、公告以及其他相关义务的，中国证监会责令改正，采取监管谈话、出具警示函、责令暂停或者停止收购等监管措施。在改正前，相关信息披露义务人不得对其持有或者实际支配的股份行使表决权。"},{"i":76,"n":"第七十六条","txt":"上市公司的收购及相关股份权益变动活动中的信息披露义务人在报告、公告等文件中有虚假记载、误导性陈述或者重大遗漏的，中国证监会责令改正，采取监管谈话、出具警示函、责令暂停或者停止收购等监管措施。在改正前，收购人对其持有或者实际支配的股份不得行使表决权。"},{"i":77,"n":"第七十七条","txt":"投资者及其一致行动人取得上市公司控制权而未按照本办法的规定聘请财务顾问，规避法定程序和义务，变相进行上市公司的收购，或者外国投资者规避管辖的，中国证监会责令改正，采取出具警示函、责令暂停或者停止收购等监管措施。在改正前，收购人不得对其持有或者实际支配的股份行使表决权。"},{"i":78,"n":"第七十八条","txt":"收购人未依照本办法的规定履行相关义务、相应程序擅自实施要约收购的，或者不符合本办法规定的免除发出要约情形，拒不履行相关义务、相应程序的，中国证监会责令改正，采取监管谈话、出具警示函、责令暂停或者停止收购等监管措施。在改正前，收购人不得对其持有或者支配的股份行使表决权。 发出收购要约的收购人在收购要约期限届满，不按照约定支付收购价款或者购买预受股份的，自该事实发生之日起3年内不得收购上市公司，中国证监会不受理收购人及其关联方提交的申报文件。 存在前二款规定情形，收购人涉嫌虚假披露、操纵证券市场的，中国证监会对收购人进行立案稽查，依法追究其法律责任；收购人聘请的财务顾问没有充分证据表明其勤勉尽责的，自收购人违规事实发生之日起1年内，中国证监会不受理该财务顾问提交的上市公司并购重组申报文件，情节严重的，依法追究法律责任。"},{"i":79,"n":"第七十九条","txt":"上市公司控股股东和实际控制人在转让其对公司的控制权时，未清偿其对公司的负债，未解除公司为其提供的担保，或者未对其损害公司利益的其他情形作出纠正的，中国证监会责令改正、责令暂停或者停止收购活动。 被收购公司董事会未能依法采取有效措施促使公司控股股东、实际控制人予以纠正，或者在收购完成后未能促使收购人履行承诺、安排或者保证的，中国证监会可以认定相关董事为不适当人选。"},{"i":80,"n":"第八十条","txt":"上市公司董事未履行忠实义务和勤勉义务，利用收购谋取不当利益的，中国证监会采取监管谈话、出具警示函等监管措施，可以认定为不适当人选。 上市公司章程中涉及公司控制权的条款违反法律、行政法规和本办法规定的，中国证监会责令改正。"},{"i":81,"n":"第八十一条","txt":"为上市公司收购出具资产评估报告、审计报告、法律意见书和财务顾问报告的证券服务机构或者证券公司及其专业人员，未依法履行职责的，或者违反中国证监会的有关规定或者行业规范、业务规则的，中国证监会责令改正，采取监管谈话、出具警示函、责令公开说明、责令定期报告等监管措施。 前款规定的证券服务机构及其从业人员被责令改正的，在改正前，不得接受新的上市公司并购重组业务。"},{"i":82,"n":"第八十二条","txt":"中国证监会将上市公司的收购及相关股份权益变动活动中的当事人的违法行为和整改情况记入诚信档案。 违反本办法的规定构成证券违法行为的，依法追究法律责任。"},{"i":83,"n":"第八十三条","txt":"本办法所称一致行动，是指投资者通过协议、其他安排，与其他投资者共同扩大其所能够支配的一个上市公司股份表决权数量的行为或者事实。 在上市公司的收购及相关股份权益变动活动中有一致行动情形的投资者，互为一致行动人。如无相反证据，投资者有下列情形之一的，为一致行动人： （一）投资者之间有股权控制关系； （二）投资者受同一主体控制； （三）投资者的董事、监事或者高级管理人员中的主要成员，同时在另一个投资者担任董事、监事或者高级管理人员； （四）投资者参股另一投资者，可以对参股公司的重大决策产生重大影响； （五）银行以外的其他法人、其他组织和自然人为投资者取得相关股份提供融资安排； （六）投资者之间存在合伙、合作、联营等其他经济利益关系； （七）持有投资者30%以上股份的自然人，与投资者持有同一上市公司股份； （八）在投资者任职的董事、监事及高级管理人员，与投资者持有同一上市公司股份； （九）持有"},{"i":84,"n":"第八十四条","txt":"有下列情形之一的，为拥有上市公司控制权： （一）投资者为上市公司持股50%以上的控股股东； （二）投资者可以实际支配上市公司股份表决权超过30%； （三）投资者通过实际支配上市公司股份表决权能够决定公司董事会半数以上成员选任； （四）投资者依其可实际支配的上市公司股份表决权足以对公司股东大会的决议产生重大影响； （五）中国证监会认定的其他情形。"},{"i":85,"n":"第八十五条","txt":"信息披露义务人涉及计算其拥有权益比例的，应当将其所持有的上市公司已发行的可转换为公司股票的证券中有权转换部分与其所持有的同一上市公司的股份合并计算，并将其持股比例与合并计算非股权类证券转为股份后的比例相比，以二者中的较高者为准；行权期限届满未行权的，或者行权条件不再具备的，无需合并计算。 前款所述二者中的较高者，应当按下列公式计算： （一）投资者持有的股份数量／上市公司已发行股份总数 （二）（投资者持有的股份数量＋投资者持有的可转换为公司股票的非股权类证券所对应的股份数量）／（上市公司已发行股份总数＋上市公司发行的可转换为公司股票的非股权类证券所对应的股份总数） 前款所称“投资者持有的股份数量”包括投资者拥有的普通股数量和优先股恢复的表决权数量，“上市公司已发行股份总数”包括上市公司已发行的普通股总数和优先股恢复的表决权总数。"},{"i":86,"n":"第八十六条","txt":"投资者因行政划转、执行法院裁决、继承、赠与等方式取得上市公司控制权的，应当按照本办法第四章的规定履行报告、公告义务。"},{"i":87,"n":"第八十七条","txt":"权益变动报告书、收购报告书、要约收购报告书、被收购公司董事会报告书等文件的内容与格式，由中国证监会另行制定。"},{"i":88,"n":"第八十八条","txt":"被收购公司在境内、境外同时上市的，收购人除应当遵守本办法及中国证监会的相关规定外，还应当遵守境外上市地的相关规定。"},{"i":89,"n":"第八十九条","txt":"外国投资者收购上市公司及在上市公司中拥有的权益发生变动的，除应当遵守本办法的规定外，还应当遵守外国投资者投资上市公司的相关规定。"},{"i":90,"n":"第九十条","txt":"本办法自2006年9月1日起施行。中国证监会发布的《上市公司收购管理办法》（证监会令第10号）、《上市公司股东持股变动信息披露管理办法》（证监会令第11号）、《关于要约收购涉及的被收购公司股票上市交易条件有关问题的通知》（证监公司字〔2003〕16号）和《关于规范上市公司实际控制权转移行为有关问题的通知》（证监公司字〔2004〕1号）同时废止。"}],"shangshigongsiguquanjiliguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步促进上市公司建立健全激励与约束机制，依据《中华人民共和国公司法》（以下简称《公司法》）、《中华人民共和国证券法》（以下简称《证券法》）及其他法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称股权激励是指上市公司以本公司股票为标的，对其董事、高级管理人员及其他员工进行的长期性激励。 上市公司以限制性股票、股票期权实行股权激励的，适用本办法；以法律、行政法规允许的其他方式实行股权激励的，参照本办法有关规定执行。"},{"i":3,"n":"第三条","txt":"上市公司实行股权激励，应当符合法律、行政法规、本办法和公司章程的规定，有利于上市公司的持续发展，不得损害上市公司利益。 上市公司的董事、监事和高级管理人员在实行股权激励中应当诚实守信，勤勉尽责，维护公司和全体股东的利益。"},{"i":4,"n":"第四条","txt":"上市公司实行股权激励，应当严格按照本办法和其他相关规定的要求履行信息披露义务。"},{"i":5,"n":"第五条","txt":"为上市公司股权激励计划出具意见的证券中介机构和人员，应当诚实守信、勤勉尽责，保证所出具的文件真实、准确、完整。"},{"i":6,"n":"第六条","txt":"任何人不得利用股权激励进行内幕交易、操纵证券市场等违法活动。"},{"i":7,"n":"第七条","txt":"上市公司具有下列情形之一的，不得实行股权激励： （一）最近一个会计年度财务会计报告被注册会计师出具否定意见或者无法表示意见的审计报告； （二）最近一个会计年度财务报告内部控制被注册会计师出具否定意见或无法表示意见的审计报告； （三）上市后最近36个月内出现过未按法律法规、公司章程、公开承诺进行利润分配的情形； （四）法律法规规定不得实行股权激励的； （五）中国证监会认定的其他情形。"},{"i":8,"n":"第八条","txt":"激励对象可以包括上市公司的董事、高级管理人员、核心技术人员或者核心业务人员，以及公司认为应当激励的对公司经营业绩和未来发展有直接影响的其他员工，但不应当包括独立董事和监事。外籍员工任职上市公司董事、高级管理人员、核心技术人员或者核心业务人员的，可以成为激励对象。 单独或合计持有上市公司5%以上股份的股东或实际控制人及其配偶、父母、子女，不得成为激励对象。下列人员也不得成为激励对象： （一）最近12个月内被证券交易所认定为不适当人选； （二）最近12个月内被中国证监会及其派出机构认定为不适当人选； （三）最近12个月内因重大违法违规行为被中国证监会及其派出机构行政处罚或者采取市场禁入措施； （四）具有《公司法》规定的不得担任公司董事、高级管理人员情形的； （五）法律法规规定不得参与上市公司股权激励的； （六）中国证监会认定的其他情形。"},{"i":9,"n":"第九条","txt":"上市公司依照本办法制定股权激励计划的，应当在股权激励计划中载明下列事项： （一）股权激励的目的； （二）激励对象的确定依据和范围； （三）拟授出的权益数量，拟授出权益涉及的标的股票种类、来源、数量及占上市公司股本总额的百分比；分次授出的，每次拟授出的权益数量、涉及的标的股票数量及占股权激励计划涉及的标的股票总额的百分比、占上市公司股本总额的百分比；设置预留权益的，拟预留权益的数量、涉及标的股票数量及占股权激励计划的标的股票总额的百分比； （四）激励对象为董事、高级管理人员的，其各自可获授的权益数量、占股权激励计划拟授出权益总量的百分比；其他激励对象（各自或者按适当分类）的姓名、职务、可获授的权益数量及占股权激励计划拟授出权益总量的百分比； （五）股权激励计划的有效期，限制性股票的授予日、限售期和解除限售安排，股票期权的授权日、可行权日、行权有效期和行权安排； （六）限制性股票的授予价格"},{"i":10,"n":"第十条","txt":"上市公司应当设立激励对象获授权益、行使权益的条件。拟分次授出权益的，应当就每次激励对象获授权益分别设立条件；分期行权的，应当就每次激励对象行使权益分别设立条件。 激励对象为董事、高级管理人员的，上市公司应当设立绩效考核指标作为激励对象行使权益的条件。"},{"i":11,"n":"第十一条","txt":"绩效考核指标应当包括公司业绩指标和激励对象个人绩效指标。相关指标应当客观公开、清晰透明，符合公司的实际情况，有利于促进公司竞争力的提升。 上市公司可以公司历史业绩或同行业可比公司相关指标作为公司业绩指标对照依据，公司选取的业绩指标可以包括净资产收益率、每股收益、每股分红等能够反映股东回报和公司价值创造的综合性指标，以及净利润增长率、主营业务收入增长率等能够反映公司盈利能力和市场价值的成长性指标。以同行业可比公司相关指标作为对照依据的，选取的对照公司不少于3家。 激励对象个人绩效指标由上市公司自行确定。 上市公司应当在公告股权激励计划草案的同时披露所设定指标的科学性和合理性。"},{"i":12,"n":"第十二条","txt":"拟实行股权激励的上市公司，可以下列方式作为标的股票来源： （一）向激励对象发行股份； （二）回购本公司股份； （三）法律、行政法规允许的其他方式。"},{"i":13,"n":"第十三条","txt":"股权激励计划的有效期从首次授予权益日起不得超过10年。"},{"i":14,"n":"第十四条","txt":"上市公司可以同时实行多期股权激励计划。同时实行多期股权激励计划的，各期激励计划设立的公司业绩指标应当保持可比性，后期激励计划的公司业绩指标低于前期激励计划的，上市公司应当充分说明其原因与合理性。 上市公司全部在有效期内的股权激励计划所涉及的标的股票总数累计不得超过公司股本总额的10%。非经股东大会特别决议批准，任何一名激励对象通过全部在有效期内的股权激励计划获授的本公司股票，累计不得超过公司股本总额的1%。 本条第二款所称股本总额是指股东大会批准最近一次股权激励计划时公司已发行的股本总额。"},{"i":15,"n":"第十五条","txt":"上市公司在推出股权激励计划时，可以设置预留权益，预留比例不得超过本次股权激励计划拟授予权益数量的20%。 上市公司应当在股权激励计划经股东大会审议通过后12个月内明确预留权益的授予对象；超过12个月未明确激励对象的，预留权益失效。"},{"i":16,"n":"第十六条","txt":"相关法律、行政法规、部门规章对上市公司董事、高级管理人员买卖本公司股票的期间有限制的，上市公司不得在相关限制期间内向激励对象授出限制性股票，激励对象也不得行使权益。"},{"i":17,"n":"第十七条","txt":"上市公司启动及实施增发新股、并购重组、资产注入、发行可转债、发行公司债券等重大事项期间，可以实行股权激励计划。"},{"i":18,"n":"第十八条","txt":"上市公司发生本办法第七条规定的情形之一的，应当终止实施股权激励计划，不得向激励对象继续授予新的权益，激励对象根据股权激励计划已获授但尚未行使的权益应当终止行使。 在股权激励计划实施过程中，出现本办法第八条规定的不得成为激励对象情形的，上市公司不得继续授予其权益，其已获授但尚未行使的权益应当终止行使。"},{"i":19,"n":"第十九条","txt":"激励对象在获授限制性股票或者对获授的股票期权行使权益前后买卖股票的行为，应当遵守《证券法》《公司法》等相关规定。 上市公司应当在本办法第二十条规定的协议中，就前述义务向激励对象作出特别提示。"},{"i":20,"n":"第二十条","txt":"上市公司应当与激励对象签订协议，确认股权激励计划的内容，并依照本办法约定双方的其他权利义务。 上市公司应当承诺，股权激励计划相关信息披露文件不存在虚假记载、误导性陈述或者重大遗漏。 所有激励对象应当承诺，上市公司因信息披露文件中有虚假记载、误导性陈述或者重大遗漏，导致不符合授予权益或行使权益安排的，激励对象应当自相关信息披露文件被确认存在虚假记载、误导性陈述或者重大遗漏后，将由股权激励计划所获得的全部利益返还公司。"},{"i":21,"n":"第二十一条","txt":"激励对象参与股权激励计划的资金来源应当合法合规，不得违反法律、行政法规及中国证监会的相关规定。 上市公司不得为激励对象依股权激励计划获取有关权益提供贷款以及其他任何形式的财务资助，包括为其贷款提供担保。"},{"i":22,"n":"第二十二条","txt":"本办法所称限制性股票是指激励对象按照股权激励计划规定的条件，获得的转让等部分权利受到限制的本公司股票。 限制性股票在解除限售前不得转让、用于担保或偿还债务。"},{"i":23,"n":"第二十三条","txt":"上市公司在授予激励对象限制性股票时，应当确定授予价格或授予价格的确定方法。授予价格不得低于股票票面金额，且原则上不得低于下列价格较高者： （一）股权激励计划草案公布前1 个交易日的公司股票交易均价的50%； （二）股权激励计划草案公布前20 个交易日、60个交易日或者120个交易日的公司股票交易均价之一的50%。 上市公司采用其他方法确定限制性股票授予价格的，应当在股权激励计划中对定价依据及定价方式作出说明。"},{"i":24,"n":"第二十四条","txt":"限制性股票授予日与首次解除限售日之间的间隔不得少于12 个月。"},{"i":25,"n":"第二十五条","txt":"在限制性股票有效期内，上市公司应当规定分期解除限售，每期时限不得少于12 个月，各期解除限售的比例不得超过激励对象获授限制性股票总额的50%。 当期解除限售的条件未成就的，限制性股票不得解除限售或递延至下期解除限售，应当按照本办法第二十六条规定处理。"},{"i":26,"n":"第二十六条","txt":"出现本办法第十八条、第二十五条规定情形，或者其他终止实施股权激励计划的情形或激励对象未达到解除限售条件的，上市公司应当回购尚未解除限售的限制性股票，并按照《公司法》的规定进行处理。 对出现本办法第十八条第一款情形负有个人责任的，或出现本办法第十八条第二款情形的，回购价格不得高于授予价格；出现其他情形的，回购价格不得高于授予价格加上银行同期存款利息之和。"},{"i":27,"n":"第二十七条","txt":"上市公司应当在本办法第二十六条规定的情形出现后及时召开董事会审议回购股份方案，并依法将回购股份方案提交股东大会批准。回购股份方案包括但不限于以下内容： （一）回购股份的原因； （二）回购股份的价格及定价依据； （三）拟回购股份的种类、数量及占股权激励计划所涉及的标的股票的比例、占总股本的比例； （四）拟用于回购的资金总额及资金来源； （五）回购后公司股本结构的变动情况及对公司业绩的影响。 律师事务所应当就回购股份方案是否符合法律、行政法规、本办法的规定和股权激励计划的安排出具专业意见。"},{"i":28,"n":"第二十八条","txt":"本办法所称股票期权是指上市公司授予激励对象在未来一定期限内以预先确定的条件购买本公司一定数量股份的权利。 激励对象获授的股票期权不得转让、用于担保或偿还债务。"},{"i":29,"n":"第二十九条","txt":"上市公司在授予激励对象股票期权时，应当确定行权价格或者行权价格的确定方法。行权价格不得低于股票票面金额，且原则上不得低于下列价格较高者： （一）股权激励计划草案公布前1 个交易日的公司股票交易均价； （二）股权激励计划草案公布前20个交易日、60个交易日或者120 个交易日的公司股票交易均价之一。 上市公司采用其他方法确定行权价格的，应当在股权激励计划中对定价依据及定价方式作出说明。"},{"i":30,"n":"第三十条","txt":"股票期权授权日与获授股票期权首次可行权日之间的间隔不得少于12个月。"},{"i":31,"n":"第三十一条","txt":"在股票期权有效期内，上市公司应当规定激励对象分期行权，每期时限不得少于12个月，后一行权期的起算日不得早于前一行权期的届满日。每期可行权的股票期权比例不得超过激励对象获授股票期权总额的50%。 当期行权条件未成就的，股票期权不得行权或递延至下期行权，并应当按照本办法第三十二条第二款规定处理。"},{"i":32,"n":"第三十二条","txt":"股票期权各行权期结束后，激励对象未行权的当期股票期权应当终止行权，上市公司应当及时注销。 出现本办法第十八条、第三十一条规定情形，或者其他终止实施股权激励计划的情形或激励对象不符合行权条件的，上市公司应当注销对应的股票期权。"},{"i":33,"n":"第三十三条","txt":"上市公司董事会下设的薪酬与考核委员会负责拟订股权激励计划草案。"},{"i":34,"n":"第三十四条","txt":"上市公司实行股权激励，董事会应当依法对股权激励计划草案作出决议，拟作为激励对象的董事或与其存在关联关系的董事应当回避表决。 董事会审议本办法第四十六条、第四十七条、第四十八条、第四十九条、第五十条、第五十一条规定中有关股权激励计划实施的事项时，拟作为激励对象的董事或与其存在关联关系的董事应当回避表决。 董事会应当在依照本办法第三十七条、第五十四条的规定履行公示、公告程序后，将股权激励计划提交股东大会审议。"},{"i":35,"n":"第三十五条","txt":"独立董事及监事会应当就股权激励计划草案是否有利于上市公司的持续发展，是否存在明显损害上市公司及全体股东利益的情形发表意见。 独立董事或监事会认为有必要的，可以建议上市公司聘请独立财务顾问，对股权激励计划的可行性、是否有利于上市公司的持续发展、是否损害上市公司利益以及对股东利益的影响发表专业意见。上市公司未按照建议聘请独立财务顾问的，应当就此事项作特别说明。"},{"i":36,"n":"第三十六条","txt":"上市公司未按照本办法第二十三条、第二十九条定价原则，而采用其他方法确定限制性股票授予价格或股票期权行权价格的，应当聘请独立财务顾问，对股权激励计划的可行性、是否有利于上市公司的持续发展、相关定价依据和定价方法的合理性、是否损害上市公司利益以及对股东利益的影响发表专业意见。"},{"i":37,"n":"第三十七条","txt":"上市公司应当在召开股东大会前，通过公司网站或者其他途径，在公司内部公示激励对象的姓名和职务，公示期不少于10 天。 监事会应当对股权激励名单进行审核，充分听取公示意见。上市公司应当在股东大会审议股权激励计划前5 日披露监事会对激励名单审核及公示情况的说明。"},{"i":38,"n":"第三十八条","txt":"上市公司应当对内幕信息知情人在股权激励计划草案公告前6 个月内买卖本公司股票及其衍生品种的情况进行自查，说明是否存在内幕交易行为。 知悉内幕信息而买卖本公司股票的，不得成为激励对象，法律、行政法规及相关司法解释规定不属于内幕交易的情形除外。 泄露内幕信息而导致内幕交易发生的，不得成为激励对象。"},{"i":39,"n":"第三十九条","txt":"上市公司应当聘请律师事务所对股权激励计划出具法律意见书，至少对以下事项发表专业意见： （一）上市公司是否符合本办法规定的实行股权激励的条件； （二）股权激励计划的内容是否符合本办法的规定； （三）股权激励计划的拟订、审议、公示等程序是否符合本办法的规定； （四）股权激励对象的确定是否符合本办法及相关法律法规的规定； （五）上市公司是否已按照中国证监会的相关要求履行信息披露义务； （六）上市公司是否为激励对象提供财务资助； （七）股权激励计划是否存在明显损害上市公司及全体股东利益和违反有关法律、行政法规的情形； （八）拟作为激励对象的董事或与其存在关联关系的董事是否根据本办法的规定进行了回避； （九）其他应当说明的事项。"},{"i":40,"n":"第四十条","txt":"上市公司召开股东大会审议股权激励计划时，独立董事应当就股权激励计划向所有的股东征集委托投票权。"},{"i":41,"n":"第四十一条","txt":"股东大会应当对本办法第九条规定的股权激励计划内容进行表决，并经出席会议的股东所持表决权的2/3 以上通过。除上市公司董事、监事、高级管理人员、单独或合计持有上市公司5%以上股份的股东以外，其他股东的投票情况应当单独统计并予以披露。 上市公司股东大会审议股权激励计划时，拟为激励对象的股东或者与激励对象存在关联关系的股东，应当回避表决。"},{"i":42,"n":"第四十二条","txt":"上市公司董事会应当根据股东大会决议，负责实施限制性股票的授予、解除限售和回购以及股票期权的授权、行权和注销。 上市公司监事会应当对限制性股票授予日及期权授予日激励对象名单进行核实并发表意见。"},{"i":43,"n":"第四十三条","txt":"上市公司授予权益与回购限制性股票、激励对象行使权益前，上市公司应当向证券交易所提出申请，经证券交易所确认后，由证券登记结算机构办理登记结算事宜。"},{"i":44,"n":"第四十四条","txt":"股权激励计划经股东大会审议通过后，上市公司应当在60日内授予权益并完成公告、登记；有获授权益条件的，应当在条件成就后60日内授出权益并完成公告、登记。上市公司未能在60日内完成上述工作的，应当及时披露未完成的原因，并宣告终止实施股权激励，自公告之日起3个月内不得再次审议股权激励计划。根据本办法规定上市公司不得授出权益的期间不计算在60 日内。"},{"i":45,"n":"第四十五条","txt":"上市公司应当按照证券登记结算机构的业务规则，在证券登记结算机构开设证券账户，用于股权激励的实施。 激励对象为外籍员工的，可以向证券登记结算机构申请开立证券账户。 尚未行权的股票期权，以及不得转让的标的股票，应当予以锁定。"},{"i":46,"n":"第四十六条","txt":"上市公司在向激励对象授出权益前，董事会应当就股权激励计划设定的激励对象获授权益的条件是否成就进行审议，独立董事及监事会应当同时发表明确意见。律师事务所应当对激励对象获授权益的条件是否成就出具法律意见。 上市公司向激励对象授出权益与股权激励计划的安排存在差异时，独立董事、监事会（当激励对象发生变化时）、律师事务所、独立财务顾问（如有）应当同时发表明确意见。"},{"i":47,"n":"第四十七条","txt":"激励对象在行使权益前，董事会应当就股权激励计划设定的激励对象行使权益的条件是否成就进行审议，独立董事及监事会应当同时发表明确意见。律师事务所应当对激励对象行使权益的条件是否成就出具法律意见。"},{"i":48,"n":"第四十八条","txt":"因标的股票除权、除息或者其他原因需要调整权益价格或者数量的，上市公司董事会应当按照股权激励计划规定的原则、方式和程序进行调整。 律师事务所应当就上述调整是否符合本办法、公司章程的规定和股权激励计划的安排出具专业意见。"},{"i":49,"n":"第四十九条","txt":"分次授出权益的，在每次授出权益前，上市公司应当召开董事会，按照股权激励计划的内容及首次授出权益时确定的原则，决定授出的权益价格、行使权益安排等内容。 当次授予权益的条件未成就时，上市公司不得向激励对象授予权益，未授予的权益也不得递延下期授予。"},{"i":50,"n":"第五十条","txt":"上市公司在股东大会审议通过股权激励方案之前可对其进行变更。变更需经董事会审议通过。 上市公司对已通过股东大会审议的股权激励方案进行变更的，应当及时公告并提交股东大会审议，且不得包括下列情形： （一）导致加速行权或提前解除限售的情形； （二）降低行权价格或授予价格的情形。 独立董事、监事会应当就变更后的方案是否有利于上市公司的持续发展，是否存在明显损害上市公司及全体股东利益的情形发表独立意见。律师事务所应当就变更后的方案是否符合本办法及相关法律法规的规定、是否存在明显损害上市公司及全体股东利益的情形发表专业意见。"},{"i":51,"n":"第五十一条","txt":"上市公司在股东大会审议股权激励计划之前拟终止实施股权激励的，需经董事会审议通过。 上市公司在股东大会审议通过股权激励计划之后终止实施股权激励的，应当由股东大会审议决定。 律师事务所应当就上市公司终止实施激励是否符合本办法及相关法律法规的规定、是否存在明显损害上市公司及全体股东利益的情形发表专业意见。"},{"i":52,"n":"第五十二条","txt":"上市公司股东大会或董事会审议通过终止实施股权激励计划决议，或者股东大会审议未通过股权激励计划的，自决议公告之日起3 个月内，上市公司不得再次审议股权激励计划。"},{"i":53,"n":"第五十三条","txt":"上市公司实行股权激励，应当真实、准确、完整、及时、公平地披露或者提供信息，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":54,"n":"第五十四条","txt":"上市公司应当在董事会审议通过股权激励计划草案后，及时公告董事会决议、股权激励计划草案、独立董事意见及监事会意见。 上市公司实行股权激励计划依照规定需要取得有关部门批准的，应当在取得有关批复文件后的2个交易日内进行公告。"},{"i":55,"n":"第五十五条","txt":"股东大会审议股权激励计划前，上市公司拟对股权激励方案进行变更的，变更议案经董事会审议通过后，上市公司应当及时披露董事会决议公告，同时披露变更原因、变更内容及独立董事、监事会、律师事务所意见。"},{"i":56,"n":"第五十六条","txt":"上市公司在发出召开股东大会审议股权激励计划的通知时，应当同时公告法律意见书；聘请独立财务顾问的，还应当同时公告独立财务顾问报告。"},{"i":57,"n":"第五十七条","txt":"股东大会审议通过股权激励计划及相关议案后，上市公司应当及时披露股东大会决议公告、经股东大会审议通过的股权激励计划、以及内幕信息知情人买卖本公司股票情况的自查报告。股东大会决议公告中应当包括中小投资者单独计票结果。"},{"i":58,"n":"第五十八条","txt":"上市公司分次授出权益的，分次授出权益的议案经董事会审议通过后，上市公司应当及时披露董事会决议公告，对拟授出的权益价格、行使权益安排、是否符合股权激励计划的安排等内容进行说明。"},{"i":59,"n":"第五十九条","txt":"因标的股票除权、除息或者其他原因调整权益价格或者数量的，调整议案经董事会审议通过后，上市公司应当及时披露董事会决议公告，同时公告律师事务所意见。"},{"i":60,"n":"第六十条","txt":"上市公司董事会应当在授予权益及股票期权行权登记完成后、限制性股票解除限售前，及时披露相关实施情况的公告。"},{"i":61,"n":"第六十一条","txt":"上市公司向激励对象授出权益时，应当按照本办法第四十四条规定履行信息披露义务，并再次披露股权激励会计处理方法、公允价值确定方法、涉及估值模型重要参数取值的合理性、实施股权激励应当计提的费用及对上市公司业绩的影响。"},{"i":62,"n":"第六十二条","txt":"上市公司董事会按照本办法第四十六条、第四十七条规定对激励对象获授权益、行使权益的条件是否成就进行审议的，上市公司应当及时披露董事会决议公告，同时公告独立董事、监事会、律师事务所意见以及独立财务顾问意见（如有）。"},{"i":63,"n":"第六十三条","txt":"上市公司董事会按照本办法第二十七条规定审议限制性股票回购方案的，应当及时公告回购股份方案及律师事务所意见。回购股份方案经股东大会批准后，上市公司应当及时公告股东大会决议。"},{"i":64,"n":"第六十四条","txt":"上市公司终止实施股权激励的，终止实施议案经股东大会或董事会审议通过后，上市公司应当及时披露股东大会决议公告或董事会决议公告，并对终止实施股权激励的原因、股权激励已筹划及实施进展、终止实施股权激励对上市公司的可能影响等作出说明，并披露律师事务所意见。"},{"i":65,"n":"第六十五条","txt":"上市公司应当在定期报告中披露报告期内股权激励的实施情况，包括： （一）报告期内激励对象的范围； （二）报告期内授出、行使和失效的权益总额； （三）至报告期末累计已授出但尚未行使的权益总额； （四）报告期内权益价格、权益数量历次调整的情况以及经调整后的最新权益价格与权益数量； （五）董事、高级管理人员各自的姓名、职务以及在报告期内历次获授、行使权益的情况和失效的权益数量； （六）因激励对象行使权益所引起的股本变动情况； （七）股权激励的会计处理方法及股权激励费用对公司业绩的影响； （八）报告期内激励对象获授权益、行使权益的条件是否成就的说明； （九）报告期内终止实施股权激励的情况及原因。"},{"i":66,"n":"第六十六条","txt":"上市公司股权激励不符合法律、行政法规和本办法规定，或者上市公司未按照本办法、股权激励计划的规定实施股权激励的，上市公司应当终止实施股权激励，中国证监会及其派出机构责令改正，并书面通报证券交易所和证券登记结算机构。"},{"i":67,"n":"第六十七条","txt":"上市公司未按照本办法及其他相关规定披露股权激励相关信息或者所披露的信息有虚假记载、误导性陈述或者重大遗漏的，中国证监会及其派出机构对公司及相关责任人员采取责令改正、监管谈话、出具警示函等监管措施；情节严重的，依照《证券法》予以处罚；涉嫌犯罪的，依法移交司法机关追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"上市公司因信息披露文件有虚假记载、误导性陈述或者重大遗漏，导致不符合授予权益或行使权益安排的，未行使权益应当统一回购注销，已经行使权益的，所有激励对象应当返还已获授权益。对上述事宜不负有责任的激励对象因返还已获授权益而遭受损失的，可按照股权激励计划相关安排，向上市公司或负有责任的对象进行追偿。 董事会应当按照前款规定和股权激励计划相关安排收回激励对象所得收益。"},{"i":69,"n":"第六十九条","txt":"上市公司实施股权激励过程中，上市公司独立董事及监事未按照本办法及相关规定履行勤勉尽责义务的，中国证监会及其派出机构采取责令改正、监管谈话、出具警示函、认定为不适当人选等措施；情节严重的，依照《证券法》予以处罚；涉嫌犯罪的，依法移交司法机关追究刑事责任。"},{"i":70,"n":"第七十条","txt":"利用股权激励进行内幕交易或者操纵证券市场的，中国证监会及其派出机构依照《证券法》予以处罚；情节严重的，对相关责任人员实施市场禁入等措施；涉嫌犯罪的，依法移交司法机关追究刑事责任。"},{"i":71,"n":"第七十一条","txt":"为上市公司股权激励计划出具专业意见的证券服务机构和人员未履行勤勉尽责义务，所发表的专业意见存在虚假记载、误导性陈述或者重大遗漏的，中国证监会及其派出机构对相关机构及签字人员采取责令改正、监管谈话、出具警示函等措施；情节严重的，依照《证券法》予以处罚；涉嫌犯罪的，依法移交司法机关追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"本办法下列用语具有如下含义： 标的股票：指根据股权激励计划，激励对象有权获授或者购买的上市公司股票。 权益：指激励对象根据股权激励计划获得的上市公司股票、股票期权。 授出权益（授予权益、授权）：指上市公司根据股权激励计划的安排，授予激励对象限制性股票、股票期权的行为。 行使权益（行权）：指激励对象根据股权激励计划的规定，解除限制性股票的限售、行使股票期权购买上市公司股份的行为。 分次授出权益（分次授权）：指上市公司根据股权激励计划的安排，向已确定的激励对象分次授予限制性股票、股票期权的行为。 分期行使权益（分期行权）：指根据股权激励计划的安排，激励对象已获授的限制性股票分期解除限售、已获授的股票期权分期行权的行为。 预留权益：指股权激励计划推出时未明确激励对象、股权激励计划实施过程中确定激励对象的权益。 授予日或者授权日：指上市公司向激励对象授予限制性股票、股票期权的日期。授予日、授权"},{"i":73,"n":"第七十三条","txt":"国有控股上市公司实施股权激励，国家有关部门对其有特别规定的，应当同时遵守其规定。"},{"i":74,"n":"第七十四条","txt":"本办法适用于股票在上海、深圳证券交易所上市的公司。"},{"i":75,"n":"第七十五条","txt":"本办法自2016年8月13日起施行。原《上市公司股权激励管理办法（试行）》（证监公司字〔2005〕151号）及相关配套制度同时废止。"}],"shangshigongsizhengquanfaxingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范上市公司证券发行行为，保护投资者的合法权益和社会公共利益，根据《证券法》《公司法》制定本办法。"},{"i":2,"n":"第二条","txt":"上市公司申请在境内发行证券，适用本办法。 本办法所称证券，指下列证券品种： （一）股票； （二）可转换公司债券； （三）中国证券监督管理委员会（以下简称中国证监会）认可的其他品种。"},{"i":3,"n":"第三条","txt":"上市公司发行证券，可以向不特定对象公开发行，也可以向特定对象非公开发行。"},{"i":4,"n":"第四条","txt":"上市公司发行证券，必须真实、准确、完整、及时、公平地披露或者提供信息，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":5,"n":"第五条","txt":"中国证监会对上市公司证券发行的核准，不表明其对该证券的投资价值或者投资者的收益作出实质性判断或者保证。因上市公司经营与收益的变化引致的投资风险，由认购证券的投资者自行负责。"},{"i":6,"n":"第六条","txt":"上市公司的组织机构健全、运行良好，符合下列规定： （一）公司章程合法有效，股东大会、董事会、监事会和独立董事制度健全，能够依法有效履行职责； （二）公司内部控制制度健全，能够有效保证公司运行的效率、合法合规性和财务报告的可靠性；内部控制制度的完整性、合理性、有效性不存在重大缺陷； （三）现任董事、监事和高级管理人员具备任职资格，能够忠实和勤勉地履行职务，不存在违反公司法第一百四十七条、第一百四十八条规定的行为，且最近三十六个月内未受到过中国证监会的行政处罚、最近十二个月内未受到过证券交易所的公开谴责； （四）上市公司与控股股东或实际控制人的人员、资产、财务分开，机构、业务独立，能够自主经营管理； （五）最近十二个月内不存在违规对外提供担保的行为。"},{"i":7,"n":"第七条","txt":"上市公司的盈利能力具有可持续性，符合下列规定： （一）最近三个会计年度连续盈利。扣除非经常性损益后的净利润与扣除前的净利润相比，以低者作为计算依据； （二）业务和盈利来源相对稳定，不存在严重依赖于控股股东、实际控制人的情形； （三）现有主营业务或投资方向能够可持续发展，经营模式和投资计划稳健，主要产品或服务的市场前景良好，行业经营环境和市场需求不存在现实或可预见的重大不利变化； （四）高级管理人员和核心技术人员稳定，最近十二个月内未发生重大不利变化； （五）公司重要资产、核心技术或其他重大权益的取得合法，能够持续使用，不存在现实或可预见的重大不利变化； （六）不存在可能严重影响公司持续经营的担保、诉讼、仲裁或其他重大事项； （七）最近二十四个月内曾公开发行证券的，不存在发行当年营业利润比上年下降百分之五十以上的情形。"},{"i":8,"n":"第八条","txt":"上市公司的财务状况良好，符合下列规定： （一）会计基础工作规范，严格遵循国家统一会计制度的规定； （二）最近三年及一期财务报表未被注册会计师出具保留意见、否定意见或无法表示意见的审计报告；被注册会计师出具带强调事项段的无保留意见审计报告的，所涉及的事项对发行人无重大不利影响或者在发行前重大不利影响已经消除； （三）资产质量良好。不良资产不足以对公司财务状况造成重大不利影响； （四）经营成果真实，现金流量正常。营业收入和成本费用的确认严格遵循国家有关企业会计准则的规定，最近三年资产减值准备计提充分合理，不存在操纵经营业绩的情形； （五）最近三年以现金方式累计分配的利润不少于最近三年实现的年均可分配利润的百分之三十。"},{"i":9,"n":"第九条","txt":"上市公司最近三十六个月内财务会计文件无虚假记载，且不存在下列重大违法行为： （一）违反证券法律、行政法规或规章，受到中国证监会的行政处罚，或者受到刑事处罚； （二）违反工商、税收、土地、环保、海关法律、行政法规或规章，受到行政处罚且情节严重，或者受到刑事处罚； （三）违反国家其他法律、行政法规且情节严重的行为。"},{"i":10,"n":"第十条","txt":"上市公司募集资金的数额和使用应当符合下列规定： （一）募集资金数额不超过项目需要量； （二）募集资金用途符合国家产业政策和有关环境保护、土地管理等法律和行政法规的规定； （三）除金融类企业外，本次募集资金使用项目不得为持有交易性金融资产和可供出售的金融资产、借予他人、委托理财等财务性投资，不得直接或间接投资于以买卖有价证券为主要业务的公司； （四）投资项目实施后，不会与控股股东或实际控制人产生同业竞争或影响公司生产经营的独立性； （五）建立募集资金专项存储制度，募集资金必须存放于公司董事会决定的专项账户。"},{"i":11,"n":"第十一条","txt":"上市公司存在下列情形之一的，不得公开发行证券： （一）本次发行申请文件有虚假记载、误导性陈述或重大遗漏； （二）擅自改变前次公开发行证券募集资金的用途而未作纠正； （三）上市公司最近十二个月内受到过证券交易所的公开谴责； （四）上市公司及其控股股东或实际控制人最近十二个月内存在未履行向投资者作出的公开承诺的行为； （五）上市公司或其现任董事、高级管理人员因涉嫌犯罪被司法机关立案侦查或涉嫌违法违规被中国证监会立案调查； （六）严重损害投资者的合法权益和社会公共利益的其他情形。"},{"i":12,"n":"第十二条","txt":"向原股东配售股份（以下简称配股） ，除符合本章第一节规定外，还应当符合下列规定： （一）拟配售股份数量不超过本次配售股份前股本总额的百分之三十; （二）控股股东应当在股东大会召开前公开承诺认配股份的数量； （三）采用证券法规定的代销方式发行。 控股股东不履行认配股份的承诺，或者代销期限届满，原股东认购股票的数量未达到拟配售数量百分之七十的，发行人应当按照发行价并加算银行同期存款利息返还已经认购的股东。"},{"i":13,"n":"第十三条","txt":"向不特定对象公开募集股份（简称“增发”），除符合本章第一节规定外，还应当符合下列规定： （一）最近三个会计年度加权平均净资产收益率平均不低于百分之六。扣除非经常性损益后的净利润与扣除前的净利润相比，以低者作为加权平均净资产收益率的计算依据； （二）除金融类企业外，最近一期末不存在持有金额较大的交易性金融资产和可供出售的金融资产、借予他人款项、委托理财等财务性投资的情形； （三）发行价格应不低于公告招股意向书前二十个交易日公司股票均价或前一个交易日的均价。"},{"i":14,"n":"第十四条","txt":"公开发行可转换公司债券的公司，除应当符合本章第一节规定外，还应当符合下列规定： （一）最近三个会计年度加权平均净资产收益率平均不低于百分之六。扣除非经常性损益后的净利润与扣除前的净利润相比，以低者作为加权平均净资产收益率的计算依据； （二）本次发行后累计公司债券余额不超过最近一期末净资产额的百分之四十; （三）最近三个会计年度实现的年均可分配利润不少于公司债券一年的利息。 前款所称可转换公司债券，是指发行公司依法发行、在一定期间内依据约定的条件可以转换成股份的公司债券。"},{"i":15,"n":"第十五条","txt":"可转换公司债券的期限最短为一年，最长为六年。"},{"i":16,"n":"第十六条","txt":"可转换公司债券每张面值一百元。 可转换公司债券的利率由发行公司与主承销商协商确定，但必须符合国家的有关规定。"},{"i":17,"n":"第十七条","txt":"公开发行可转换公司债券，应当委托具有资格的资信评级机构进行信用评级和跟踪评级。 资信评级机构每年至少公告一次跟踪评级报告。"},{"i":18,"n":"第十八条","txt":"上市公司应当在可转换公司债券期满后五个工作日内办理完毕偿还债券余额本息的事项。"},{"i":19,"n":"第十九条","txt":"公开发行可转换公司债券，应当约定保护债券持有人权利的办法，以及债券持有人会议的权利、程序和决议生效条件。 存在下列事项之一的，应当召开债券持有人会议： （一）拟变更募集说明书的约定； （二）发行人不能按期支付本息； （三）发行人减资、合并、分立、解散或者申请破产； （四）保证人或者担保物发生重大变化； （五）其他影响债券持有人重大权益的事项。"},{"i":20,"n":"第二十条","txt":"公开发行可转换公司债券，应当提供担保，但最近一期末经审计的净资产不低于人民币十五亿元的公司除外。 提供担保的，应当为全额担保，担保范围包括债券的本金及利息、违约金、损害赔偿金和实现债权的费用。 以保证方式提供担保的，应当为连带责任担保，且保证人最近一期经审计的净资产额应不低于其累计对外担保的金额。证券公司或上市公司不得作为发行可转债的担保人，但上市商业银行除外。 设定抵押或质押的，抵押或质押财产的估值应不低于担保金额。估值应经有资格的资产评估机构评估。"},{"i":21,"n":"第二十一条","txt":"可转换公司债券自发行结束之日起六个月后方可转换为公司股票，转股期限由公司根据可转换公司债券的存续期限及公司财务状况确定。 债券持有人对转换股票或者不转换股票有选择权，并于转股的次日成为发行公司的股东。"},{"i":22,"n":"第二十二条","txt":"转股价格应不低于募集说明书公告日前二十个交易日该公司股票交易均价和前一个交易日的均价。 前款所称转股价格，是指募集说明书事先约定的可转换公司债券转换为每股股份所支付的价格。"},{"i":23,"n":"第二十三条","txt":"募集说明书可以约定赎回条款，规定上市公司可按事先约定的条件和价格赎回尚未转股的可转换公司债券。"},{"i":24,"n":"第二十四条","txt":"募集说明书可以约定回售条款，规定债券持有人可按事先约定的条件和价格将所持债券回售给上市公司。 募集说明书应当约定，上市公司改变公告的募集资金用途的，赋予债券持有人一次回售的权利。"},{"i":25,"n":"第二十五条","txt":"募集说明书应当约定转股价格调整的原则及方式。发行可转换公司债券后，因配股、增发、送股、派息、分立及其他原因引起上市公司股份变动的，应当同时调整转股价格。"},{"i":26,"n":"第二十六条","txt":"募集说明书约定转股价格向下修正条款的，应当同时约定： （一）转股价格修正方案须提交公司股东大会表决，且须经出席会议的股东所持表决权的三分之二以上同意。股东大会进行表决时，持有公司可转换债券的股东应当回避； （二）修正后的转股价格不低于前项规定的股东大会召开日前二十个交易日该公司股票交易均价和前一个交易日的均价。"},{"i":27,"n":"第二十七条","txt":"上市公司可以公开发行认股权和债券分离交易的可转换公司债券（以下简称分离交易的可转换公司债券）。 发行分离交易的可转换公司债券，除符合本章第一节规定外，还应当符合下列规定： （一）公司最近一期末经审计的净资产不低于人民币十五亿元； （二）最近三个会计年度实现的年均可分配利润不少于公司债券一年的利息； （三）最近三个会计年度经营活动产生的现金流量净额平均不少于公司债券一年的利息，符合本办法第十四条第（一）项规定的公司除外； （四）本次发行后累计公司债券余额不超过最近一期末净资产额的百分之四十，预计所附认股权全部行权后募集的资金总量不超过拟发行公司债券金额。"},{"i":28,"n":"第二十八条","txt":"分离交易的可转换公司债券应当申请在上市公司股票上市的证券交易所上市交易。 分离交易的可转换公司债券中的公司债券和认股权分别符合证券交易所上市条件的，应当分别上市交易。"},{"i":29,"n":"第二十九条","txt":"分离交易的可转换公司债券的期限最短为一年。 债券的面值、利率、信用评级、偿还本息、债权保护适用本办法第十六条至第十九条的规定。"},{"i":30,"n":"第三十条","txt":"发行分离交易的可转换公司债券，发行人提供担保的，适用本办法第二十条第二款至第四款的规定。"},{"i":31,"n":"第三十一条","txt":"认股权证上市交易的，认股权证约定的要素应当包括行权价格、存续期间、行权期间或行权日、行权比例。"},{"i":32,"n":"第三十二条","txt":"认股权证的行权价格应不低于公告募集说明书日前二十个交易日公司股票均价和前一个交易日的均价。"},{"i":33,"n":"第三十三条","txt":"认股权证的存续期间不超过公司债券的期限，自发行结束之日起不少于六个月。 募集说明书公告的权证存续期限不得调整。"},{"i":34,"n":"第三十四条","txt":"认股权证自发行结束至少已满六个月起方可行权，行权期间为存续期限届满前的一段期间，或者是存续期限内的特定交易日。"},{"i":35,"n":"第三十五条","txt":"分离交易的可转换公司债券募集说明书应当约定，上市公司改变公告的募集资金用途的，赋予债券持有人一次回售的权利。"},{"i":36,"n":"第三十六条","txt":"本办法规定的非公开发行股票，是指上市公司采用非公开方式，向特定对象发行股票的行为。"},{"i":37,"n":"第三十七条","txt":"非公开发行股票的特定对象应当符合下列规定： (一)特定对象符合股东大会决议规定的条件； (二)发行对象不超过三十五名。 发行对象为境外战略投资者的，应当遵守国家的相关规定。"},{"i":38,"n":"第三十八条","txt":"上市公司非公开发行股票，应当符合下列规定： (一)发行价格不低于定价基准日前二十个交易日公司股票均价的百分之八十； (二)本次发行的股份自发行结束之日起，六个月内不得转让；控股股东、实际控制人及其控制的企业认购的股份，十八个月内不得转让； (三)募集资金使用符合本办法第十条的规定； (四)本次发行将导致上市公司控制权发生变化的，还应当符合中国证监会的其他规定。"},{"i":39,"n":"第三十九条","txt":"上市公司存在下列情形之一的，不得非公开发行股票： （一）本次发行申请文件有虚假记载、误导性陈述或重大遗漏； （二）上市公司的权益被控股股东或实际控制人严重损害且尚未消除； （三）上市公司及其附属公司违规对外提供担保且尚未解除； （四）现任董事、高级管理人员最近三十六个月内受到过中国证监会的行政处罚，或者最近十二个月内受到过证券交易所公开谴责； （五）上市公司或其现任董事、高级管理人员因涉嫌犯罪正被司法机关立案侦查或涉嫌违法违规正被中国证监会立案调查； （六）最近一年及一期财务报表被注册会计师出具保留意见、否定意见或无法表示意见的审计报告。保留意见、否定意见或无法表示意见所涉及事项的重大影响已经消除或者本次发行涉及重大重组的除外； （七）严重损害投资者合法权益和社会公共利益的其他情形。"},{"i":40,"n":"第四十条","txt":"上市公司申请发行证券，董事会应当依法就下列事项作出决议，并提请股东大会批准： （一）本次证券发行的方案； （二）本次募集资金使用的可行性报告； （三）前次募集资金使用的报告； （四）其他必须明确的事项。"},{"i":41,"n":"第四十一条","txt":"股东大会就发行股票作出的决定，至少应当包括下列事项： （一）本次发行证券的种类和数量； （二）发行方式、发行对象及向原股东配售的安排； （三）定价方式或价格区间； （四）募集资金用途； （五）决议的有效期； （六）对董事会办理本次发行具体事宜的授权； （七）其他必须明确的事项。"},{"i":42,"n":"第四十二条","txt":"股东大会就发行可转换公司债券作出的决定，至少应当包括下列事项： （一）本办法第四十一条规定的事项； （二）债券利率； （三）债券期限； （四）担保事项； （五）回售条款； （六）还本付息的期限和方式； （七）转股期； （八）转股价格的确定和修正。"},{"i":43,"n":"第四十三条","txt":"股东大会就发行分离交易的可转换公司债券作出的决定，至少应当包括下列事项： （一）本办法第四十一条、第四十二条第（二）项至第（六）项规定的事项； （二）认股权证的行权价格； （三）认股权证的存续期限； （四）认股权证的行权期间或行权日。"},{"i":44,"n":"第四十四条","txt":"股东大会就发行证券事项作出决议，必须经出席会议的股东所持表决权的三分之二以上通过。向本公司特定的股东及其关联人发行证券的，股东大会就发行方案进行表决时，关联股东应当回避。 上市公司就发行证券事项召开股东大会，应当提供网络或者其他方式为股东参加股东大会提供便利。"},{"i":45,"n":"第四十五条","txt":"上市公司申请公开发行证券或者非公开发行新股，应当由保荐人保荐，并向中国证监会申报。 保荐人应当按照中国证监会的有关规定编制和报送发行申请文件。"},{"i":46,"n":"第四十六条","txt":"中国证监会依照下列程序审核发行证券的申请： （一）收到申请文件后，五个工作日内决定是否受理； （二）中国证监会受理后，对申请文件进行初审； （三）发行审核委员会审核申请文件； （四）中国证监会作出核准或者不予核准的决定。"},{"i":47,"n":"第四十七条","txt":"自中国证监会核准发行之日起，上市公司应在十二个月内发行证券；超过十二个月未发行的，核准文件失效，须重新经中国证监会核准后方可发行。"},{"i":48,"n":"第四十八条","txt":"上市公司发行证券前发生重大事项的，应暂缓发行，并及时报告中国证监会。该事项对本次发行条件构成重大影响的，发行证券的申请应重新经过中国证监会核准。"},{"i":49,"n":"第四十九条","txt":"上市公司发行证券，应当由证券公司承销；非公开发行股票，发行对象均属于原前十名股东的，可以由上市公司自行销售。"},{"i":50,"n":"第五十条","txt":"证券发行申请未获核准的上市公司，自中国证监会作出不予核准的决定之日起六个月后，可再次提出证券发行申请。"},{"i":51,"n":"第五十一条","txt":"上市公司发行证券，应当按照中国证监会规定的程序、内容和格式，编制公开募集证券说明书或者其他信息披露文件，依法履行信息披露义务。"},{"i":52,"n":"第五十二条","txt":"上市公司应当保证投资者及时、充分、公平地获得法定披露的信息，信息披露文件使用的文字应当简洁、平实、易懂。 中国证监会规定的内容是信息披露的最低要求，凡对投资者投资决策有重大影响的信息，上市公司均应充分披露。"},{"i":53,"n":"第五十三条","txt":"证券发行议案经董事会表决通过后，应当在两个工作日内报告证券交易所，公告召开股东大会的通知。 使用募集资金收购资产或者股权的，应当在公告召开股东大会通知的同时，披露该资产或者股权的基本情况、交易价格、定价依据以及是否与公司股东或其他关联人存在利害关系。"},{"i":54,"n":"第五十四条","txt":"股东大会通过本次发行议案之日起两个工作日内，上市公司应当公布股东大会决议。"},{"i":55,"n":"第五十五条","txt":"上市公司收到中国证监会关于本次发行申请的下列决定后，应当在次一工作日予以公告： （一）不予受理或者终止审查； （二）不予核准或者予以核准。 上市公司决定撤回证券发行申请的，应当在撤回申请文件的次一工作日予以公告。"},{"i":56,"n":"第五十六条","txt":"上市公司全体董事、监事、高级管理人员应当在公开募集证券说明书上签字，保证不存在虚假记载、误导性陈述或者重大遗漏，并声明承担个别和连带的法律责任。"},{"i":57,"n":"第五十七条","txt":"保荐机构及保荐代表人应当对公开募集证券说明书的内容进行尽职调查并签字，确认不存在虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":58,"n":"第五十八条","txt":"为证券发行出具专项文件的注册会计师、资产评估人员、资信评级人员、律师及其所在机构，应当按照本行业公认的业务标准和道德规范出具文件，并声明对所出具文件的真实性、准确性和完整性承担责任。"},{"i":59,"n":"第五十九条","txt":"公开募集证券说明书所引用的审计报告、盈利预测审核报告、资产评估报告、资信评级报告，应当由有资格的证券服务机构出具，并由至少两名有从业资格的人员签署。 公开募集证券说明书所引用的法律意见书，应当由律师事务所出具，并由至少两名经办律师签署。"},{"i":60,"n":"第六十条","txt":"公开募集证券说明书自最后签署之日起六个月内有效。 公开募集证券说明书不得使用超过有效期的资产评估报告或者资信评级报告。"},{"i":61,"n":"第六十一条","txt":"上市公司在公开发行证券前的二至五个工作日内，应当将经中国证监会核准的募集说明书摘要或者募集意向书摘要刊登在至少一种中国证监会指定的报刊，同时将其全文刊登在中国证监会指定的互联网网站，置备于中国证监会指定的场所，供公众查阅。"},{"i":62,"n":"第六十二条","txt":"上市公司在非公开发行新股后，应当将发行情况报告书刊登在至少一种中国证监会指定的报刊，同时将其刊登在中国证监会指定的互联网网站，置备于中国证监会指定的场所，供公众查阅。"},{"i":63,"n":"第六十三条","txt":"上市公司可以将公开募集证券说明书全文或摘要、发行情况公告书刊登于其他网站和报刊，但不得早于按照第六十一条、第六十二条规定披露信息的时间。"},{"i":64,"n":"第六十四条","txt":"上市公司违反本办法规定，中国证监会可以责令整改；对其直接负责的主管人员和其他直接责任人员，可以采取监管谈话、认定为不适当人选等行政监管措施，记入诚信档案并公布。"},{"i":65,"n":"第六十五条","txt":"上市公司及其直接负责的主管人员和其他直接责任人员违反法律、行政法规或本办法规定，依法应予行政处罚的，依照有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":66,"n":"第六十六条","txt":"上市公司提供的申请文件中有虚假记载、误导性陈述或重大遗漏的，中国证监会可作出终止审查决定，并在三十六个月内不再受理该公司的公开发行证券申请。"},{"i":67,"n":"第六十七条","txt":"上市公司披露盈利预测的，利润实现数如未达到盈利预测的百分之八十，除因不可抗力外，其法定代表人、盈利预测审核报告签字注册会计师应当在股东大会及中国证监会指定报刊上公开作出解释并道歉；中国证监会可以对法定代表人处以警告。 利润实现数未达到盈利预测的百分之五十的，除因不可抗力外，中国证监会在三十六个月内不受理该公司的公开发行证券申请。"},{"i":68,"n":"第六十八条","txt":"上市公司违反本办法第十条第（三）项和第（四）项规定的，中国证监会可以责令改正，并在三十六个月内不受理该公司的公开发行证券申请。"},{"i":69,"n":"第六十九条","txt":"为证券发行出具审计报告、法律意见、资产评估报告、资信评级报告及其他专项文件的证券服务机构和人员，在其出具的专项文件中存在虚假记载、误导性陈述或重大遗漏的，除承担证券法规定的法律责任外，中国证监会十二个月内不接受相关机构出具的证券发行专项文件，三十六个月内不接受相关人员出具的证券发行专项文件。"},{"i":70,"n":"第七十条","txt":"承销机构在承销非公开发行的新股时，将新股配售给不符合本办法第三十七条规定的对象的，中国证监会可以责令改正，并在三十六个月内不接受其参与证券承销。"},{"i":71,"n":"第七十一条","txt":"上市公司在非公开发行新股时，违反本办法第四十九条规定的，中国证监会可以责令改正，并在三十六个月内不受理该公司的公开发行证券申请。"},{"i":72,"n":"第七十二条","txt":"本办法规定的特定对象违反规定，擅自转让限售期限未满的股票的，中国证监会可以责令改正，情节严重的，十二个月内不得作为特定对象认购证券。"},{"i":73,"n":"第七十三条","txt":"上市公司和保荐机构、承销商向参与认购的投资者提供财务资助或补偿的，中国证监会可以责令改正；情节严重的，处以警告、罚款。"},{"i":74,"n":"第七十四条","txt":"上市公司发行以外币认购的证券的办法、上市公司向员工发行证券用于激励的办法，由中国证监会另行规定。"},{"i":75,"n":"第七十五条","txt":"依据本办法通过非公开发行股票取得的上市公司股份，其减持不适用《上市公司股东、董监高减持股份的若干规定》的有关规定。"},{"i":76,"n":"第七十六条","txt":"本办法自2006年5月8日起施行。《上市公司新股发行管理办法》(证监会令第1号)、《关于做好上市公司新股发行工作的通知》(证监发[2001]43号)、《关于上市公司增发新股有关条件的通知》(证监发[2002]55号)、《上市公司发行可转换公司债券实施办法》(证监会令第2号)和《关于做好上市公司可转换公司债券发行工作的通知》(证监发行字[2001]115号)同时废止。"}],"shangshigongsizhongdazichanchongzuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范上市公司重大资产重组行为，保护上市公司和投资者的合法权益，促进上市公司质量不断提高，维护证券市场秩序和社会公共利益，根据《公司法》《证券法》等法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于上市公司及其控股或者控制的公司在日常经营活动之外购买、出售资产或者通过其他方式进行资产交易达到规定的比例，导致上市公司的主营业务、资产、收入发生重大变化的资产交易行为（以下简称重大资产重组）。 上市公司发行股份购买资产应当符合本办法的规定。 上市公司按照经中国证券监督管理委员会（以下简称中国证监会）核准的发行证券文件披露的募集资金用途，使用募集资金购买资产、对外投资的行为，不适用本办法。"},{"i":3,"n":"第三条","txt":"任何单位和个人不得利用重大资产重组损害上市公司及其股东的合法权益。"},{"i":4,"n":"第四条","txt":"上市公司实施重大资产重组，有关各方必须及时、公平地披露或者提供信息，保证所披露或者提供信息的真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":5,"n":"第五条","txt":"上市公司的董事、监事和高级管理人员在重大资产重组活动中，应当诚实守信、勤勉尽责，维护公司资产的安全，保护公司和全体股东的合法权益。"},{"i":6,"n":"第六条","txt":"为重大资产重组提供服务的证券服务机构和人员，应当遵守法律、行政法规和中国证监会的有关规定，以及证券交易所的相关规则，遵循本行业公认的业务标准和道德规范，诚实守信，勤勉尽责，严格履行职责，对其所制作、出具文件的真实性、准确性和完整性承担责任。 前款规定的证券服务机构和人员，不得教唆、协助或者伙同委托人编制或者披露存在虚假记载、误导性陈述或者重大遗漏的报告、公告文件，不得从事不正当竞争，不得利用上市公司重大资产重组谋取不正当利益。"},{"i":7,"n":"第七条","txt":"任何单位和个人对所知悉的重大资产重组信息在依法披露前负有保密义务。 禁止任何单位和个人利用重大资产重组信息从事内幕交易、操纵证券市场等违法活动。"},{"i":8,"n":"第八条","txt":"中国证监会依法对上市公司重大资产重组行为进行监督管理。 中国证监会审核上市公司重大资产重组或者发行股份购买资产的申请，可以根据上市公司的规范运作和诚信状况、财务顾问的执业能力和执业质量，结合国家产业政策和重组交易类型，作出差异化的、公开透明的监管制度安排，有条件地减少审核内容和环节。"},{"i":9,"n":"第九条","txt":"鼓励依法设立的并购基金、股权投资基金、创业投资基金、产业投资基金等投资机构参与上市公司并购重组。"},{"i":10,"n":"第十条","txt":"中国证监会在发行审核委员会中设立上市公司并购重组审核委员会（以下简称并购重组委），并购重组委以投票方式对提交其审议的重大资产重组或者发行股份购买资产申请进行表决，提出审核意见。"},{"i":11,"n":"第十一条","txt":"上市公司实施重大资产重组，应当就本次交易符合下列要求作出充分说明，并予以披露： （一）符合国家产业政策和有关环境保护、土地管理、反垄断等法律和行政法规的规定； （二）不会导致上市公司不符合股票上市条件； （三）重大资产重组所涉及的资产定价公允，不存在损害上市公司和股东合法权益的情形； （四）重大资产重组所涉及的资产权属清晰，资产过户或者转移不存在法律障碍，相关债权债务处理合法； （五）有利于上市公司增强持续经营能力，不存在可能导致上市公司重组后主要资产为现金或者无具体经营业务的情形； （六）有利于上市公司在业务、资产、财务、人员、机构等方面与实际控制人及其关联人保持独立，符合中国证监会关于上市公司独立性的相关规定； （七）有利于上市公司形成或者保持健全有效的法人治理结构。"},{"i":12,"n":"第十二条","txt":"上市公司及其控股或者控制的公司购买、出售资产，达到下列标准之一的，构成重大资产重组： （一）购买、出售的资产总额占上市公司最近一个会计年度经审计的合并财务会计报告期末资产总额的比例达到50%以上； （二）购买、出售的资产在最近一个会计年度所产生的营业收入占上市公司同期经审计的合并财务会计报告营业收入的比例达到50%以上； （三）购买、出售的资产净额占上市公司最近一个会计年度经审计的合并财务会计报告期末净资产额的比例达到50%以上，且超过5000万元人民币。 购买、出售资产未达到前款规定标准，但中国证监会发现存在可能损害上市公司或者投资者合法权益的重大问题的，可以根据审慎监管原则，责令上市公司按照本办法的规定补充披露相关信息、暂停交易、聘请符合《证券法》规定的独立财务顾问或者其他证券服务机构补充核查并披露专业意见。"},{"i":13,"n":"第十三条","txt":"上市公司自控制权发生变更之日起36个月内，向收购人及其关联人购买资产，导致上市公司发生以下根本变化情形之一的，构成重大资产重组，应当按照本办法的规定报经中国证监会核准： （一）购买的资产总额占上市公司控制权发生变更的前一个会计年度经审计的合并财务会计报告期末资产总额的比例达到100%以上； （二）购买的资产在最近一个会计年度所产生的营业收入占上市公司控制权发生变更的前一个会计年度经审计的合并财务会计报告营业收入的比例达到100%以上； （三）购买的资产净额占上市公司控制权发生变更的前一个会计年度经审计的合并财务会计报告期末净资产额的比例达到100%以上； （四）为购买资产发行的股份占上市公司首次向收购人及其关联人购买资产的董事会决议前一个交易日的股份的比例达到100%以上； （五）上市公司向收购人及其关联人购买资产虽未达到本款第（一）至第（四）项标准，但可能导致上市公司主营业务发生根本"},{"i":14,"n":"第十四条","txt":"计算本办法第十二条、第十三条规定的比例时，应当遵守下列规定： （一）购买的资产为股权的，其资产总额以被投资企业的资产总额与该项投资所占股权比例的乘积和成交金额二者中的较高者为准，营业收入以被投资企业的营业收入与该项投资所占股权比例的乘积为准，资产净额以被投资企业的净资产额与该项投资所占股权比例的乘积和成交金额二者中的较高者为准；出售的资产为股权的，其资产总额、营业收入以及资产净额分别以被投资企业的资产总额、营业收入以及净资产额与该项投资所占股权比例的乘积为准。 购买股权导致上市公司取得被投资企业控股权的，其资产总额以被投资企业的资产总额和成交金额二者中的较高者为准，营业收入以被投资企业的营业收入为准，资产净额以被投资企业的净资产额和成交金额二者中的较高者为准；出售股权导致上市公司丧失被投资企业控股权的，其资产总额、营业收入以及资产净额分别以被投资企业的资产总额、营业收入以及净资产额为准"},{"i":15,"n":"第十五条","txt":"本办法第二条所称通过其他方式进行资产交易，包括： （一）与他人新设企业、对已设立的企业增资或者减资； （二）受托经营、租赁其他企业资产或者将经营性资产委托他人经营、租赁； （三）接受附义务的资产赠与或者对外捐赠资产； （四）中国证监会根据审慎监管原则认定的其他情形。 上述资产交易实质上构成购买、出售资产，且按照本办法规定的标准计算的相关比例达到50%以上的，应当按照本办法的规定履行相关义务和程序。"},{"i":16,"n":"第十六条","txt":"上市公司与交易对方就重大资产重组事宜进行初步磋商时，应当立即采取必要且充分的保密措施，制定严格有效的保密制度，限定相关敏感信息的知悉范围。上市公司及交易对方聘请证券服务机构的，应当立即与所聘请的证券服务机构签署保密协议。 上市公司关于重大资产重组的董事会决议公告前，相关信息已在媒体上传播或者公司股票交易出现异常波动的，上市公司应当立即将有关计划、方案或者相关事项的现状以及相关进展情况和风险因素等予以公告，并按照有关信息披露规则办理其他相关事宜。"},{"i":17,"n":"第十七条","txt":"上市公司应当聘请符合《证券法》规定的独立财务顾问、律师事务所以及会计师事务所等证券服务机构就重大资产重组出具意见。 独立财务顾问和律师事务所应当审慎核查重大资产重组是否构成关联交易，并依据核查确认的相关事实发表明确意见。重大资产重组涉及关联交易的，独立财务顾问应当就本次重组对上市公司非关联股东的影响发表明确意见。 资产交易定价以资产评估结果为依据的，上市公司应当聘请符合《证券法》规定的资产评估机构出具资产评估报告。 证券服务机构在其出具的意见中采用其他证券服务机构或者人员的专业意见的，仍然应当进行尽职调查，审慎核查其采用的专业意见的内容，并对利用其他证券服务机构或者人员的专业意见所形成的结论负责。"},{"i":18,"n":"第十八条","txt":"上市公司及交易对方与证券服务机构签订聘用合同后，非因正当事由不得更换证券服务机构。确有正当事由需要更换证券服务机构的，应当披露更换的具体原因以及证券服务机构的陈述意见。"},{"i":19,"n":"第十九条","txt":"上市公司应当在重大资产重组报告书的管理层讨论与分析部分，就本次交易对上市公司的持续经营能力、未来发展前景、当年每股收益等财务指标和非财务指标的影响进行详细分析。"},{"i":20,"n":"第二十条","txt":"重大资产重组中相关资产以资产评估结果作为定价依据的，资产评估机构应当按照资产评估相关准则和规范开展执业活动；上市公司董事会应当对评估机构的独立性、评估假设前提的合理性、评估方法与评估目的的相关性以及评估定价的公允性发表明确意见。 相关资产不以资产评估结果作为定价依据的，上市公司应当在重大资产重组报告书中详细分析说明相关资产的估值方法、参数及其他影响估值结果的指标和因素。上市公司董事会应当对估值机构的独立性、估值假设前提的合理性、估值方法与估值目的的相关性发表明确意见，并结合相关资产的市场可比交易价格、同行业上市公司的市盈率或者市净率等通行指标，在重大资产重组报告书中详细分析本次交易定价的公允性。 前二款情形中，评估机构、估值机构原则上应当采取两种以上的方法进行评估或者估值；上市公司独立董事应当出席董事会会议，对评估机构或者估值机构的独立性、评估或者估值假设前提的合理性和交易定价的公允性"},{"i":21,"n":"第二十一条","txt":"上市公司进行重大资产重组，应当由董事会依法作出决议，并提交股东大会批准。 上市公司董事会应当就重大资产重组是否构成关联交易作出明确判断，并作为董事会决议事项予以披露。 上市公司独立董事应当在充分了解相关信息的基础上，就重大资产重组发表独立意见。重大资产重组构成关联交易的，独立董事可以另行聘请独立财务顾问就本次交易对上市公司非关联股东的影响发表意见。上市公司应当积极配合独立董事调阅相关材料，并通过安排实地调查、组织证券服务机构汇报等方式，为独立董事履行职责提供必要的支持和便利。"},{"i":22,"n":"第二十二条","txt":"上市公司应当在董事会作出重大资产重组决议后的次一工作日至少披露下列文件： （一）董事会决议及独立董事的意见； （二）上市公司重大资产重组预案。 本次重组的重大资产重组报告书、独立财务顾问报告、法律意见书以及重组涉及的审计报告、资产评估报告或者估值报告至迟应当与召开股东大会的通知同时公告。上市公司自愿披露盈利预测报告的，该报告应当经符合《证券法》规定的会计师事务所审核，与重大资产重组报告书同时公告。 本条第一款第（二）项及第二款规定的信息披露文件的内容与格式另行规定。 上市公司只需选择一种符合中国证监会规定条件的媒体公告董事会决议、独立董事的意见，并应当在证券交易所网站全文披露重大资产重组报告书及其摘要、相关证券服务机构的报告或者意见。"},{"i":23,"n":"第二十三条","txt":"上市公司股东大会就重大资产重组作出的决议，至少应当包括下列事项： （一）本次重大资产重组的方式、交易标的和交易对方； （二）交易价格或者价格区间； （三）定价方式或者定价依据； （四）相关资产自定价基准日至交割日期间损益的归属； （五）相关资产办理权属转移的合同义务和违约责任； （六）决议的有效期； （七）对董事会办理本次重大资产重组事宜的具体授权； （八）其他需要明确的事项。"},{"i":24,"n":"第二十四条","txt":"上市公司股东大会就重大资产重组事项作出决议，必须经出席会议的股东所持表决权的2/3以上通过。 上市公司重大资产重组事宜与本公司股东或者其关联人存在关联关系的，股东大会就重大资产重组事项进行表决时，关联股东应当回避表决。 交易对方已经与上市公司控股股东就受让上市公司股权或者向上市公司推荐董事达成协议或者默契，可能导致上市公司的实际控制权发生变化的，上市公司控股股东及其关联人应当回避表决。 上市公司就重大资产重组事宜召开股东大会，应当以现场会议形式召开，并应当提供网络投票和其他合法方式为股东参加股东大会提供便利。除上市公司的董事、监事、高级管理人员、单独或者合计持有上市公司5%以上股份的股东以外，其他股东的投票情况应当单独统计并予以披露。"},{"i":25,"n":"第二十五条","txt":"上市公司应当在股东大会作出重大资产重组决议后的次一工作日公告该决议，以及律师事务所对本次会议的召集程序、召集人和出席人员的资格、表决程序以及表决结果等事项出具的法律意见书。 属于本办法第十三条规定的交易情形的，上市公司还应当按照中国证监会的规定委托独立财务顾问在作出决议后3个工作日内向中国证监会提出申请。"},{"i":26,"n":"第二十六条","txt":"上市公司全体董事、监事、高级管理人员应当公开承诺，保证重大资产重组的信息披露和申请文件不存在虚假记载、误导性陈述或者重大遗漏。 重大资产重组的交易对方应当公开承诺，将及时向上市公司提供本次重组相关信息，并保证所提供的信息真实、准确、完整，如因提供的信息存在虚假记载、误导性陈述或者重大遗漏，给上市公司或者投资者造成损失的，将依法承担赔偿责任。 前二款规定的单位和个人还应当公开承诺，如本次交易因涉嫌所提供或者披露的信息存在虚假记载、误导性陈述或者重大遗漏，被司法机关立案侦查或者被中国证监会立案调查的，在案件调查结论明确之前，将暂停转让其在该上市公司拥有权益的股份。"},{"i":27,"n":"第二十七条","txt":"中国证监会依照法定条件和程序，对上市公司属于本办法第十三条规定情形的交易申请作出予以核准或者不予核准的决定。 中国证监会在审核期间提出反馈意见要求上市公司作出书面解释、说明的，上市公司应当自收到反馈意见之日起30日内提供书面回复意见，独立财务顾问应当配合上市公司提供书面回复意见。逾期未提供的，上市公司应当在到期日的次日就本次交易的进展情况及未能及时提供回复意见的具体原因等予以公告。"},{"i":28,"n":"第二十八条","txt":"股东大会作出重大资产重组的决议后，上市公司拟对交易对象、交易标的、交易价格等作出变更，构成对原交易方案重大调整的，应当在董事会表决通过后重新提交股东大会审议，并及时公告相关文件。 中国证监会审核期间，上市公司按照前款规定对原交易方案作出重大调整的，还应当按照本办法的规定向中国证监会重新提出申请，同时公告相关文件。 中国证监会审核期间，上市公司董事会决议撤回申请的，应当说明原因，予以公告；上市公司董事会决议终止本次交易的，还应当按照公司章程的规定提交股东大会审议。"},{"i":29,"n":"第二十九条","txt":"上市公司重大资产重组属于本办法第十三条规定的交易情形的，应当提交并购重组委审核。"},{"i":30,"n":"第三十条","txt":"上市公司在收到中国证监会关于召开并购重组委工作会议审核其申请的通知后，应当立即予以公告，并申请办理并购重组委工作会议期间直至其表决结果披露前的停牌事宜。 上市公司收到并购重组委关于其申请的表决结果的通知后，应当在次一工作日公告表决结果并申请复牌。公告应当说明，公司在收到中国证监会作出的予以核准或者不予核准的决定后将再行公告。"},{"i":31,"n":"第三十一条","txt":"上市公司收到中国证监会就其申请作出的予以核准或者不予核准的决定后，应当在次一工作日予以公告。 中国证监会予以核准的，上市公司应当在公告核准决定的同时，按照相关信息披露准则的规定补充披露相关文件。"},{"i":32,"n":"第三十二条","txt":"上市公司重大资产重组完成相关批准程序后，应当及时实施重组方案，并于实施完毕之日起3个工作日内编制实施情况报告书，向证券交易所提交书面报告，并予以公告。 上市公司聘请的独立财务顾问和律师事务所应当对重大资产重组的实施过程、资产过户事宜和相关后续事项的合规性及风险进行核查，发表明确的结论性意见。独立财务顾问和律师事务所出具的意见应当与实施情况报告书同时报告、公告。"},{"i":33,"n":"第三十三条","txt":"自完成相关批准程序之日起60日内，本次重大资产重组未实施完毕的，上市公司应当于期满后次一工作日将实施进展情况报告，并予以公告；此后每30日应当公告一次，直至实施完毕。属于本办法第十三条、第四十四条规定的交易情形的，自收到中国证监会核准文件之日起超过12个月未实施完毕的，核准文件失效。"},{"i":34,"n":"第三十四条","txt":"上市公司在实施重大资产重组的过程中，发生法律、法规要求披露的重大事项的，应当及时作出公告；该事项导致本次交易发生实质性变动的，须重新提交股东大会审议，属于本办法第十三条规定的交易情形的，还须重新报经中国证监会核准。"},{"i":35,"n":"第三十五条","txt":"采取收益现值法、假设开发法等基于未来收益预期的方法对拟购买资产进行评估或者估值并作为定价参考依据的，上市公司应当在重大资产重组实施完毕后3年内的年度报告中单独披露相关资产的实际盈利数与利润预测数的差异情况，并由会计师事务所对此出具专项审核意见；交易对方应当与上市公司就相关资产实际盈利数不足利润预测数的情况签订明确可行的补偿协议。 预计本次重大资产重组将摊薄上市公司当年每股收益的，上市公司应当提出填补每股收益的具体措施，并将相关议案提交董事会和股东大会进行表决。负责落实该等具体措施的相关责任主体应当公开承诺，保证切实履行其义务和责任。 上市公司向控股股东、实际控制人或者其控制的关联人之外的特定对象购买资产且未导致控制权发生变更的，不适用本条前二款规定，上市公司与交易对方可以根据市场化原则，自主协商是否采取业绩补偿和每股收益填补措施及相关具体安排。"},{"i":36,"n":"第三十六条","txt":"上市公司重大资产重组发生下列情形的，独立财务顾问应当及时出具核查意见，并予以公告： （一）上市公司完成相关批准程序前，对交易对象、交易标的、交易价格等作出变更，构成对原重组方案重大调整，或者因发生重大事项导致原重组方案发生实质性变动的； （二）上市公司完成相关批准程序后，在实施重组过程中发生重大事项，导致原重组方案发生实质性变动的。"},{"i":37,"n":"第三十七条","txt":"独立财务顾问应当按照中国证监会的相关规定，对实施重大资产重组的上市公司履行持续督导职责。持续督导的期限自本次重大资产重组实施完毕之日起，应当不少于一个会计年度。实施本办法第十三条规定的重大资产重组，持续督导的期限自中国证监会核准本次重大资产重组之日起，应当不少于3个会计年度。"},{"i":38,"n":"第三十八条","txt":"独立财务顾问应当结合上市公司重大资产重组当年和实施完毕后的第一个会计年度的年报，自年报披露之日起15日内，对重大资产重组实施的下列事项出具持续督导意见，并予以公告： （一）交易资产的交付或者过户情况； （二）交易各方当事人承诺的履行情况； （三）已公告的盈利预测或者利润预测的实现情况； （四）管理层讨论与分析部分提及的各项业务的发展现状； （五）公司治理结构与运行情况； （六）与已公布的重组方案存在差异的其他事项。 独立财务顾问还应当结合本办法第十三条规定的重大资产重组实施完毕后的第二、三个会计年度的年报，自年报披露之日起15日内，对前款第（二）至（六）项事项出具持续督导意见，并予以公告。"},{"i":39,"n":"第三十九条","txt":"上市公司筹划、实施重大资产重组，相关信息披露义务人应当公平地向所有投资者披露可能对上市公司股票交易价格产生较大影响的相关信息（以下简称股价敏感信息），不得有选择性地向特定对象提前泄露。"},{"i":40,"n":"第四十条","txt":"上市公司的股东、实际控制人以及参与重大资产重组筹划、论证、决策等环节的其他相关机构和人员，应当及时、准确地向上市公司通报有关信息，并配合上市公司及时、准确、完整地进行披露。上市公司获悉股价敏感信息的，应当及时向证券交易所申请停牌并披露。"},{"i":41,"n":"第四十一条","txt":"上市公司及其董事、监事、高级管理人员，重大资产重组的交易对方及其关联方，交易对方及其关联方的董事、监事、高级管理人员或者主要负责人，交易各方聘请的证券服务机构及其从业人员，参与重大资产重组筹划、论证、决策、审批等环节的相关机构和人员，以及因直系亲属关系、提供服务和业务往来等知悉或者可能知悉股价敏感信息的其他相关机构和人员，在重大资产重组的股价敏感信息依法披露前负有保密义务，禁止利用该信息进行内幕交易。"},{"i":42,"n":"第四十二条","txt":"上市公司筹划重大资产重组事项，应当详细记载筹划过程中每一具体环节的进展情况，包括商议相关方案、形成相关意向、签署相关协议或者意向书的具体时间、地点、参与机构和人员、商议和决议内容等，制作书面的交易进程备忘录并予以妥当保存。参与每一具体环节的所有人员应当即时在备忘录上签名确认。 上市公司预计筹划中的重大资产重组事项难以保密或者已经泄露的，应当及时向证券交易所申请停牌，直至真实、准确、完整地披露相关信息。停牌期间，上市公司应当至少每周发布一次事件进展情况公告。 上市公司股票交易价格因重大资产重组的市场传闻发生异常波动时，上市公司应当及时向证券交易所申请停牌，核实有无影响上市公司股票交易价格的重组事项并予以澄清，不得以相关事项存在不确定性为由不履行信息披露义务。"},{"i":43,"n":"第四十三条","txt":"上市公司发行股份购买资产，应当符合下列规定： （一）充分说明并披露本次交易有利于提高上市公司资产质量、改善财务状况和增强持续盈利能力，有利于上市公司减少关联交易、避免同业竞争、增强独立性； （二）上市公司最近一年及一期财务会计报告被注册会计师出具无保留意见审计报告；被出具保留意见、否定意见或者无法表示意见的审计报告的，须经注册会计师专项核查确认，该保留意见、否定意见或者无法表示意见所涉及事项的重大影响已经消除或者将通过本次交易予以消除； （三）上市公司及其现任董事、高级管理人员不存在因涉嫌犯罪正被司法机关立案侦查或涉嫌违法违规正被中国证监会立案调查的情形，但是，涉嫌犯罪或违法违规的行为已经终止满3年，交易方案有助于消除该行为可能造成的不良后果，且不影响对相关行为人追究责任的除外； （四）充分说明并披露上市公司发行股份所购买的资产为权属清晰的经营性资产，并能在约定期限内办理完毕权属转移手"},{"i":44,"n":"第四十四条","txt":"上市公司发行股份购买资产的，可以同时募集部分配套资金，其定价方式按照现行相关规定办理。 上市公司发行股份购买资产应当遵守本办法关于重大资产重组的规定，编制发行股份购买资产预案、发行股份购买资产报告书，并向中国证监会提出申请。"},{"i":45,"n":"第四十五条","txt":"上市公司发行股份的价格不得低于市场参考价的90%。市场参考价为本次发行股份购买资产的董事会决议公告日前20个交易日、60个交易日或者120个交易日的公司股票交易均价之一。本次发行股份购买资产的董事会决议应当说明市场参考价的选择依据。 前款所称交易均价的计算公式为：董事会决议公告日前若干个交易日公司股票交易均价＝决议公告日前若干个交易日公司股票交易总额/决议公告日前若干个交易日公司股票交易总量。 本次发行股份购买资产的董事会决议可以明确，在中国证监会核准前，上市公司的股票价格相比最初确定的发行价格发生重大变化的，董事会可以按照已经设定的调整方案对发行价格进行一次调整。 前款规定的发行价格调整方案应当明确、具体、可操作，详细说明是否相应调整拟购买资产的定价、发行股份数量及其理由，在首次董事会决议公告时充分披露，并按照规定提交股东大会审议。股东大会作出决议后，董事会按照已经设定的方案调整发行"},{"i":46,"n":"第四十六条","txt":"特定对象以资产认购而取得的上市公司股份，自股份发行结束之日起12个月内不得转让；属于下列情形之一的，36个月内不得转让： （一）特定对象为上市公司控股股东、实际控制人或者其控制的关联人； （二）特定对象通过认购本次发行的股份取得上市公司的实际控制权； （三）特定对象取得本次发行的股份时，对其用于认购股份的资产持续拥有权益的时间不足12个月。 属于本办法第十三条第一款规定的交易情形的，上市公司原控股股东、原实际控制人及其控制的关联人，以及在交易过程中从该等主体直接或间接受让该上市公司股份的特定对象应当公开承诺，在本次交易完成后36个月内不转让其在该上市公司中拥有权益的股份；除收购人及其关联人以外的特定对象应当公开承诺，其以资产认购而取得的上市公司股份自股份发行结束之日起24个月内不得转让。"},{"i":47,"n":"第四十七条","txt":"上市公司申请发行股份购买资产，应当提交并购重组委审核。"},{"i":48,"n":"第四十八条","txt":"上市公司发行股份购买资产导致特定对象持有或者控制的股份达到法定比例的，应当按照《上市公司收购管理办法》的规定履行相关义务。 上市公司向控股股东、实际控制人或者其控制的关联人发行股份购买资产，或者发行股份购买资产将导致上市公司实际控制权发生变更的，认购股份的特定对象应当在发行股份购买资产报告书中公开承诺：本次交易完成后6个月内如上市公司股票连续20个交易日的收盘价低于发行价，或者交易完成后6个月期末收盘价低于发行价的，其持有公司股票的锁定期自动延长至少6个月。 前款规定的特定对象还应当在发行股份购买资产报告书中公开承诺：如本次交易因涉嫌所提供或披露的信息存在虚假记载、误导性陈述或者重大遗漏，被司法机关立案侦查或者被中国证监会立案调查的，在案件调查结论明确以前，不转让其在该上市公司拥有权益的股份。"},{"i":49,"n":"第四十九条","txt":"中国证监会核准上市公司发行股份购买资产的申请后，上市公司应当及时实施。向特定对象购买的相关资产过户至上市公司后，上市公司聘请的独立财务顾问和律师事务所应当对资产过户事宜和相关后续事项的合规性及风险进行核查，并发表明确意见。上市公司应当在相关资产过户完成后3个工作日内就过户情况作出公告，公告中应当包括独立财务顾问和律师事务所的结论性意见。 上市公司完成前款规定的公告、报告后，可以到证券交易所、证券登记结算公司为认购股份的特定对象申请办理证券登记手续。"},{"i":50,"n":"第五十条","txt":"换股吸收合并涉及上市公司的，上市公司的股份定价及发行按照本章规定执行。 上市公司发行优先股用于购买资产或者与其他公司合并，中国证监会另有规定的，从其规定。 上市公司可以向特定对象发行可转换为股票的公司债券、定向权证、存托凭证等用于购买资产或者与其他公司合并。"},{"i":51,"n":"第五十一条","txt":"经中国证监会审核后获得核准的重大资产重组实施完毕后，上市公司申请公开发行新股或者公司债券，同时符合下列条件的，本次重大资产重组前的业绩在审核时可以模拟计算： （一）进入上市公司的资产是完整经营实体； （二）本次重大资产重组实施完毕后，重组方的承诺事项已经如期履行，上市公司经营稳定、运行良好； （三）本次重大资产重组实施完毕后，上市公司和相关资产实现的利润达到盈利预测水平。 上市公司在本次重大资产重组前不符合中国证监会规定的公开发行证券条件，或者本次重组导致上市公司实际控制人发生变化的，上市公司申请公开发行新股或者公司债券，距本次重组交易完成的时间应当不少于一个完整会计年度。"},{"i":52,"n":"第五十二条","txt":"本办法所称完整经营实体，应当符合下列条件： （一）经营业务和经营资产独立、完整，且在最近两年未发生重大变化； （二）在进入上市公司前已在同一实际控制人之下持续经营两年以上； （三）在进入上市公司之前实行独立核算，或者虽未独立核算，但与其经营业务相关的收入、费用在会计核算上能够清晰划分； （四）上市公司与该经营实体的主要高级管理人员签订聘用合同或者采取其他方式，就该经营实体在交易完成后的持续经营和管理作出恰当安排。"},{"i":53,"n":"第五十三条","txt":"未依照本办法的规定履行相关义务或者程序，擅自实施重大资产重组的，由中国证监会责令改正，并可以采取监管谈话、出具警示函等监管措施；情节严重的，可以责令暂停或者终止重组活动，处以警告、罚款，并可以对有关责任人员采取市场禁入的措施。 未经中国证监会核准擅自实施本办法第十三条第一款规定的重大资产重组，交易尚未完成的，中国证监会责令上市公司补充披露相关信息、暂停交易并按照本办法第十三条的规定报送申请文件；交易已经完成的，可以处以警告、罚款，并对有关责任人员采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。 上市公司重大资产重组因定价显失公允、不正当利益输送等问题损害上市公司、投资者合法权益的，由中国证监会责令改正，并可以采取监管谈话、出具警示函等监管措施；情节严重的，可以责令暂停或者终止重组活动，处以警告、罚款，并可以对有关责任人员采取市场禁入的措施。"},{"i":54,"n":"第五十四条","txt":"上市公司或者其他信息披露义务人未按照本办法规定报送重大资产重组有关报告或者履行信息披露义务的，由中国证监会责令改正，依照《证券法》第一百九十七条予以处罚；情节严重的，可以责令暂停或者终止重组活动，并可以对有关责任人员采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。 上市公司控股股东、实际控制人组织、指使从事前款违法违规行为，或者隐瞒相关事项导致发生前款情形的，依照《证券法》第一百九十七条予以处罚；情节严重的，可以责令暂停或者终止重组活动，并可以对有关责任人员采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"上市公司或者其他信息披露义务人报送的报告或者披露的信息存在虚假记载、误导性陈述或者重大遗漏的，由中国证监会责令改正，依照《证券法》第一百九十七条予以处罚；情节严重的，可以责令暂停或者终止重组活动，并可以对有关责任人员采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。 上市公司的控股股东、实际控制人组织、指使从事前款违法违规行为，或者隐瞒相关事项导致发生前款情形的，依照《证券法》第一百九十七条予以处罚；情节严重的，可以责令暂停或者终止重组活动，并可以对有关责任人员采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。 重大资产重组或者发行股份购买资产的交易对方未及时向上市公司或者其他信息披露义务人提供信息，或者提供的信息有虚假记载、误导性陈述或者重大遗漏的，按照第一款规定执行。 上市公司发行股份购买资产，在其公告的有关文件中隐瞒重要事实或者编造重大虚假内容的，中国证监"},{"i":56,"n":"第五十六条","txt":"重大资产重组涉嫌本办法第五十三条、第五十四条、第五十五条规定情形的，中国证监会可以责令上市公司作出公开说明、聘请独立财务顾问或者其他证券服务机构补充核查并披露专业意见，在公开说明、披露专业意见之前，上市公司应当暂停重组；上市公司涉嫌前述情形被司法机关立案侦查或者被中国证监会立案调查的，在案件调查结论明确之前应当暂停重组。 涉嫌本办法第五十四条、第五十五条规定情形，被司法机关立案侦查或者被中国证监会立案调查的，有关单位和个人应当严格遵守其所作的公开承诺，在案件调查结论明确之前，不得转让其在该上市公司拥有权益的股份。"},{"i":57,"n":"第五十七条","txt":"上市公司董事、监事和高级管理人员未履行诚实守信、勤勉尽责义务，或者上市公司的股东、实际控制人及其有关负责人员未按照本办法的规定履行相关义务，导致重组方案损害上市公司利益的，由中国证监会责令改正，并可以采取监管谈话、出具警示函等监管措施；情节严重的，处以警告、罚款，并可以对有关人员采取认定为不适当人选、市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"为重大资产重组出具财务顾问报告、审计报告、法律意见、资产评估报告、估值报告及其他专业文件的证券服务机构及其从业人员未履行诚实守信、勤勉尽责义务，违反中国证监会的有关规定、行业规范、业务规则，或者未依法履行报告和公告义务、持续督导义务的，由中国证监会责令改正，并可以采取监管谈话、出具警示函、责令公开说明、责令定期报告、认定为不适当人选等监管措施；情节严重的，依法追究法律责任。 前款规定的证券服务机构及其从业人员所制作、出具的文件存在虚假记载、误导性陈述或者重大遗漏的，由中国证监会责令改正，依照《证券法》第二百一十三条予以处罚；情节严重的，可以采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。 存在前二款规定情形的，在按照中国证监会的要求完成整改之前，不得接受新的上市公司并购重组业务。"},{"i":59,"n":"第五十九条","txt":"重大资产重组实施完毕后，凡因不属于上市公司管理层事前无法获知且事后无法控制的原因，上市公司所购买资产实现的利润未达到资产评估报告或者估值报告预测金额的80%，或者实际运营情况与重大资产重组报告书中管理层讨论与分析部分存在较大差距的，上市公司的董事长、总经理以及对此承担相应责任的会计师事务所、财务顾问、资产评估机构、估值机构及其从业人员应当在上市公司披露年度报告的同时，在同一媒体上作出解释，并向投资者公开道歉；实现利润未达到预测金额50%的，中国证监会可以对上市公司、相关机构及其责任人员采取监管谈话、出具警示函、责令定期报告等监管措施。 交易对方超期未履行或者违反业绩补偿协议、承诺的，由中国证监会责令改正，并可以采取监管谈话、出具警示函、责令公开说明、认定为不适当人选等监管措施，将相关情况记入诚信档案。"},{"i":60,"n":"第六十条","txt":"任何知悉重大资产重组信息的人员在相关信息依法公开前，泄露该信息、买卖或者建议他人买卖相关上市公司证券、利用重大资产重组散布虚假信息、操纵证券市场或者进行欺诈活动的，中国证监会依照《证券法》第一百九十一条、第一百九十二条、第一百九十三条予以处罚；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"中国证监会对证券交易所相关板块上市公司重大资产重组另有规定的，从其规定。"},{"i":62,"n":"第六十二条","txt":"本办法自2014年11月23日起施行。2008年4月16日发布并于2011年8月1日修改的《上市公司重大资产重组管理办法》（证监会令第73号）、2008年11月11日发布的《关于破产重整上市公司重大资产重组股份发行定价的补充规定》（证监会公告〔2008〕44号）同时废止"}],"zhongguozhengquanjianduguanliweiyuanhuidongjiechafe1a6d7":[{"i":1,"n":"第一条","txt":"为了保护投资者和当事人的合法权益，及时有效查处证券违法行为，规范冻结、查封工作，维护市场秩序，根据《中华人民共和国证券法》及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中国证券监督管理委员会及其派出机构依法履行职责，有权冻结、查封涉案当事人的违法资金、证券等涉案财产或者重要证据。"},{"i":3,"n":"第三条","txt":"冻结、查封违法资金、证券等涉案财产或者重要证据，必须依照本办法规定的程序提交申请，经法律部门审查，报中国证券监督管理委员会主要负责人或者其授权的其他负责人批准，制作决定书、通知书，由执法人员实施。"},{"i":4,"n":"第四条","txt":"中国证券监督管理委员会案件调查部门、案件审理部门及派出机构在对证券违法案件进行调查、审理或者执行时，发现存在下列情形之一的，可以申请冻结、查封： （一）已经转移、隐匿违法资金、证券等涉案财产的； （二）可能转移、隐匿违法资金、证券等涉案财产的； （三）已经隐匿、伪造、毁损重要证据的； （四）可能隐匿、伪造、毁损重要证据的； （五）其他需要及时冻结、查封的情形。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，视为可能转移或者隐匿违法资金、证券等涉案财产： （一）涉案当事人本人开立的资金账户、证券账户和银行账户或由其实际控制的资金账户、证券账户和银行账户，以及与其有关联的资金账户、证券账户和银行账户中存放的违法资金、证券，部分已经被转移或者隐匿的； （二）被举报的违法资金、证券等涉案财产已经或者将要被转移、隐匿并提供具体的转移或者隐匿线索的； （三）通过与他人签订合同等形式，拟将违法资金、证券等涉案财产作为合同标的物或者以偿还贷款、支付合同价款等名义转移占有的； （四）当事人因涉嫌严重违法而被立案调查，且其涉案场所、账户或者人员已经被执法部门调查的； （五）其他有证据证明有转移或者隐匿违法资金、证券等涉案财产迹象的。"},{"i":6,"n":"第六条","txt":"有下列特征之一的，视为重要证据： （一）对案件调查有重大影响的； （二）对案件定性有关键作用的； （三）不可替代或者具有唯一性的； （四）其他重要证据。"},{"i":7,"n":"第七条","txt":"中国证券监督管理委员会案件调查部门、案件审理部门及派出机构需要实施冻结、查封时，应当提交申请，经部门或者派出机构主要负责人批准，交法律部门审查。业务监管部门在履行监管职责中发现需要采取冻结、查封措施的，应当及时通报案件调查部门实施冻结、查封。"},{"i":8,"n":"第八条","txt":"冻结、查封申请书应当载明下列事项： （一）被冻结、查封当事人姓名或者名称、地址等基本情况； （二）申请冻结、查封的具体事项，包括涉案财产或者重要证据的名称、代码、数量、金额、地址等； （三）主要违法事实与申请冻结、查封的理由； （四）其他需要说明的事项。"},{"i":9,"n":"第九条","txt":"负责审查的法律部门应当及时处理冻结、查封申请，出具审核意见，并制作冻结、查封决定书，报中国证券监督管理委员会主要负责人或者其授权的其他负责人批准。"},{"i":10,"n":"第十条","txt":"冻结、查封决定书应当载明下列事项： （一）被冻结、查封当事人姓名或者名称、地址等基本情况； （二）冻结、查封的理由和依据； （三）冻结、查封财产或者证据的名称、数量和期限； （四）申请行政复议的途径； （五）中国证券监督管理委员会公章和日期。"},{"i":11,"n":"第十一条","txt":"申请书、决定书经批准后，由申请部门负责实施。实施冻结、查封的部门应当制作冻结通知书或者查封通知书，通知书应当载明下列事项： （一）协助冻结、查封的单位名称； （二）冻结、查封的法律依据； （三）冻结、查封的财产或者证据所在机构的名称或者地址； （四）冻结、查封的财产或者证据的名称、数额等； （五）冻结、查封的起止时间； （六）其他需要说明的事项； （七）中国证券监督管理委员会公章和日期。"},{"i":12,"n":"第十二条","txt":"实施冻结，应当依照有关规定，向协助执行部门出示冻结决定书，送达冻结通知书，并在实施冻结后及时向当事人送达冻结决定书。当事人应当将被冻结情况告知其控制的涉案财产的名义持有人。"},{"i":13,"n":"第十三条","txt":"实施查封，应当依照有关规定向当事人送达查封决定书。需要有关部门协助的，还应当向协助执行部门送达查封通知书。 实施查封后，应当制作现场笔录和查封清单。查封清单一式两份，由当事人和实施部门分别保存。"},{"i":14,"n":"第十四条","txt":"冻结或者查封应当由两名以上执法人员实施。 执法人员在实施冻结或者查封时应当出示有效证件。"},{"i":15,"n":"第十五条","txt":"现场笔录应当载明下列事项： （一）冻结、查封的时间、地点； （二）实施冻结、查封的单位和个人； （三）被冻结、查封的单位和个人； （四）协助冻结、查封的单位和个人； （五）冻结、查封的具体事项，包括涉案财产或者重要证据的名称、代码、数量、金额、地址等； （六）当事人的陈述和申辩； （七）其他应当载明的事项。 现场笔录和清单由当事人、见证人和执法人员签名或者盖章，当事人不在现场或者当事人、见证人拒绝签名或者盖章的，应当在笔录中予以注明。"},{"i":16,"n":"第十六条","txt":"查封可以采取下列方式： （一）查封动产的，应当在该动产上加贴封条或者采取其他足以公示查封的适当方式； （二）查封已登记的不动产、特定动产及其他财产权的，应当张贴封条或者公告，并通知有关登记机关办理查封登记手续； （三）查封未登记的不动产、特定动产及其他财产权的，应当张贴封条或者公告，并告知法定权属登记机关； （四）查封重要证据的，应当加贴封条或者采取其他足以公示查封的适当方式； （五）其他合法的方式。"},{"i":17,"n":"第十七条","txt":"冻结、查封的期限为六个月。因特殊原因需要延长的，应当在冻结、查封期满前十日内办理继续冻结、查封手续。每次延长期限不得超过三个月，冻结、查封期限最长不超过二年。 逾期未办理继续冻结、查封手续的，视为自动解除冻结、查封。"},{"i":18,"n":"第十八条","txt":"冻结证券，其金额应当以冻结实施日前一交易日收市后的市值计算。 冻结证券时，中国证券监督管理委员会及其派出机构可以明确被冻结的证券是否限制卖出。 限制证券卖出的，由证券公司或者证券登记结算机构协助执行冻结。冻结期间，证券持有人可以提出出售部分或者全部被冻结证券的请求，经申请部门审查认为确有必要的，可以解除卖出限制，并监督证券持有人依法出售，同时将所得资金转入相关资金账户予以冻结。 不限制证券卖出的，由证券公司等控制资金账户的单位协助执行冻结。冻结期间，证券持有人可以依法出售部分或者全部被冻结的证券，同时将所得资金转入相关资金账户予以冻结。 证券公司协助执行冻结的，应当于当日将冻结信息发送证券登记结算机构。 证券被冻结后，不得进行转托管或转指定，不得设定抵押、质押等权利，不得进行非交易过户，不得进行重复冻结。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，经中国证券监督管理委员会主要负责人或者其授权的其他负责人批准，应当及时解除冻结、查封措施： （一）已经完成调查、处罚的； （二）经查证，确实与案件无关的； （三）当事人提供相应担保的； （四）其他应当及时解除冻结、查封的情形。"},{"i":20,"n":"第二十条","txt":"冻结、查封财产的数额应当与违法行为的情节或者行政处罚决定的金额相适应。"},{"i":21,"n":"第二十一条","txt":"案件调查结束后，当事人的违法行为涉嫌犯罪需要移送公安机关的，应当将冻结、查封的证据、材料一并移送。"},{"i":22,"n":"第二十二条","txt":"当事人逾期不履行处罚决定的，中国证券监督管理委员会可以依法申请人民法院强制执行冻结、查封的涉案财产。"},{"i":23,"n":"第二十三条","txt":"解除冻结、查封参照实施冻结、查封程序办理。"},{"i":24,"n":"第二十四条","txt":"当事人对冻结、查封决定不服的，可以依法向中国证券监督管理委员会申请行政复议。 行政复议期间，冻结、查封措施不停止执行，但是有下列情形之一的，可以停止执行： （一）实施部门认为需要停止执行并批准的； （二）当事人申请停止执行并批准的； （三）法律、法规规定应当停止执行的。"},{"i":25,"n":"第二十五条","txt":"未按规定程序实施冻结、查封，给当事人的合法财产造成重大损失的，依法给予赔偿；对直接负责的主管人员和直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"当事人和协助执行单位拒绝、阻碍中国证券监督管理委员会及其执法人员实施冻结、查封措施，由中国证券监督管理委员会责令改正，处以十万元以上一百万元以下的罚款，并由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"本办法由中国证券监督管理委员会负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自2006年1月1日起施行。"}],"zhongguozhengquanjianduguanliweiyuanhuifaxingshenh7e659e":[{"i":1,"n":"第一条","txt":"为了保证在股票发行审核工作中贯彻公开、公平、公正的原则，提高股票发行审核工作的质量、效率和透明度，更好地保护投资者合法权益，根据《中华人民共和国证券法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"中国证券监督管理委员会（以下简称中国证监会）设立发行审核委员会（以下简称发审委）和上市公司并购重组审核委员会（以下简称并购重组委）。 发审委审核发行人股票发行申请和可转换公司债券等中国证监会认可的其他证券的发行申请（以下统称股票发行申请），适用本办法。 并购重组委的组成、职责、工作规程等另行制定。"},{"i":3,"n":"第三条","txt":"发审委依照《中华人民共和国证券法》《中华人民共和国公司法》等法律、行政法规和中国证监会的规定，对发行人的股票发行申请文件和中国证监会有关职能部门的初审报告进行审核。 发审委以投票方式对股票发行申请进行表决，提出审核意见。 中国证监会依照法定条件和法定程序作出予以核准或者不予核准股票发行申请的决定。"},{"i":4,"n":"第四条","txt":"发审委通过发审委工作会议（以下简称发审委会议）履行职责。"},{"i":5,"n":"第五条","txt":"中国证监会负责对发审委事务的日常管理以及对发审委委员的考核和监督。"},{"i":6,"n":"第六条","txt":"发审委委员由中国证监会的专业人员和中国证监会外的有关专家组成，由中国证监会聘任。 发审委委员为66名，部分发审委委员可以为专职。 发审委设会议召集人。"},{"i":7,"n":"第七条","txt":"发审委委员每届任期一年，可以连任，但连续任期最长不超过2届。发审委委员每年至少更换一半。 发审委委员和并购重组委委员不得相互兼任。"},{"i":8,"n":"第八条","txt":"中国证监会设立发审委遴选委员会，按照依法、公开、择优的原则选聘发审委委员，发审委委员人选向市场公开，接受社会监督。"},{"i":9,"n":"第九条","txt":"发审委委员应当符合下列条件： （一）具有较高的政治思想素质、理论水平和道德修养； （二）坚持原则，公正廉洁，忠于职守，严格遵守国家法律、行政法规和规章； （三）熟悉证券、会计业务及有关的法律、行政法规和规章； （四）精通所从事行业的专业知识，在所从事的领域内有较高声誉； （五）没有违法、违纪记录； （六）中国证监会认为需要符合的其他条件。"},{"i":10,"n":"第十条","txt":"发审委委员有下列情形之一的，中国证监会应当予以解聘： （一）违反法律、行政法规、规章和发行审核工作纪律的； （二）未按照中国证监会的有关规定勤勉尽职的； （三）本人提出辞职申请的； （四）2次以上无故不出席发审委会议的； （五）经中国证监会考核认为不适合担任发审委委员的其他情形。 发审委委员的解聘不受任期是否届满的限制。发审委委员解聘后，中国证监会应及时选聘新的发审委委员。 发审委委员因违法违规被解聘的，取消其所在单位5年内再次推荐发审委委员的资格，发审委委员为国家机关、事业单位工作人员的，通报其所在单位，由其所在单位作出相应处分。"},{"i":11,"n":"第十一条","txt":"发审委的职责是：根据有关法律、行政法规和中国证监会的规定，审核股票发行申请是否符合相关条件；审核保荐人、会计师事务所、律师事务所、资产评估机构等证券服务机构及相关人员为股票发行所出具的有关材料及意见书；审核中国证监会有关职能部门出具的初审报告；依法对股票发行申请提出审核意见。"},{"i":12,"n":"第十二条","txt":"发审委委员以个人身份出席发审委会议，依法履行职责，独立发表审核意见并行使表决权。"},{"i":13,"n":"第十三条","txt":"发审委委员可以通过中国证监会有关职能部门调阅履行职责所必需的与发行人有关的资料。"},{"i":14,"n":"第十四条","txt":"发审委委员应当遵守下列规定： （一）按要求出席发审委会议，并在审核工作中勤勉尽职； （二）保守国家秘密和发行人的商业秘密； （三）不得泄露发审委会议讨论内容、表决情况以及其他有关情况； （四）不得利用发审委委员身份或者在履行职责上所得到的非公开信息，为本人或者他人直接或者间接谋取利益； （五）不得与发行人有利害关系，不得直接或间接接受发行人及相关单位或个人提供的资金、物品等馈赠和其他利益，本人及配偶、父母、子女及其配偶不得直接或者以化名、借他人名义持有所核准的发行申请的股票，不得私下与发行人及其他相关单位或个人进行接触； （六）不得有与其他发审委委员串通表决或者诱导其他发审委委员表决的行为； （七）中国证监会以外的专职委员受聘期间，执行中国证监会工作人员禁止买卖股票的规定，相关人员所持股票，原则上应当在具备依法转让条件时受聘一个月内清理完毕，中国证监会以外的兼职委员受聘期间，买卖股票的"},{"i":15,"n":"第十五条","txt":"发审委委员有义务向中国证监会举报任何以不正当手段对其施加影响的发行人及其他相关单位或者个人。"},{"i":16,"n":"第十六条","txt":"发审委委员审核股票发行申请文件时，有下列情形之一的，应及时提出回避： （一）发审委委员或者其亲属担任发行人或者保荐人的董事（含独立董事，下同）、监事、经理或者其他高级管理人员的； （二）发审委委员或者其亲属、发审委委员所在工作单位持有发行人的股票，可能影响其公正履行职责的； （三）发审委委员或者其所在工作单位近两年来为发行人提供保荐、承销、审计、评估、法律、咨询等服务，可能妨碍其公正履行职责的； （四）发审委委员或者其亲属担任董事、监事、经理或者其他高级管理人员的公司与发行人或者保荐人有行业竞争关系，经认定可能影响其公正履行职责的； （五）发审委会议召开前，与本次所审核发行人及其他相关单位或者个人进行过接触，可能影响其公正履行职责的； （六）中国证监会认定的可能产生利害冲突或者发审委委员认为可能影响其公正履行职责的其他情形。 前款所称亲属，是指发审委委员的配偶、父母、子女、兄弟姐妹、配"},{"i":17,"n":"第十七条","txt":"发行人及其他相关单位和个人如果认为发审委委员与其存在利害冲突或者潜在的利害冲突，可能影响发审委委员公正履行职责的，可以在报送发审委会议审核的股票发行申请文件时，向中国证监会提出要求有关发审委委员予以回避的书面申请，并说明理由。 中国证监会根据发行人及其他相关单位和个人提出的书面申请，决定相关发审委委员是否回避。"},{"i":18,"n":"第十八条","txt":"发审委委员接受聘任后，应当承诺遵守中国证监会有关对发审委委员的规定和纪律要求，认真履行职责，接受中国证监会的考核和监督。"},{"i":19,"n":"第十九条","txt":"发审委通过召开发审委会议进行审核工作。"},{"i":20,"n":"第二十条","txt":"发审委会议表决采取记名投票方式。表决票设同意票和反对票，发审委委员不得弃权。发审委委员在投票时应当在表决票上说明理由。"},{"i":21,"n":"第二十一条","txt":"发审委委员应依据法律、行政法规和中国证监会的规定，结合自身的专业知识，独立、客观、公正地对股票发行申请进行审核。 发审委委员应当以审慎、负责的态度，全面审阅发行人的股票发行申请文件和中国证监会有关职能部门出具的初审报告。在审核时，发审委委员应当在工作底稿上填写个人审核意见： （一）发审委委员对初审报告中提请发审委委员关注的问题和审核意见有异议的，应当在工作底稿上对相关内容提出有依据、明确的审核意见； （二）发审委委员认为发行人存在初审报告提请关注问题以外的其他问题的，应当在工作底稿上提出有依据、明确的审核意见； （三）发审委委员认为发行人存在尚待调查核实并影响明确判断的重大问题的，应当在工作底稿上提出有依据、明确的审核意见。 发审委委员在发审委会议上应当根据自己的工作底稿发表个人审核意见，同时应当根据会议讨论情况，完善个人审核意见并在工作底稿上予以记录。 发审委会议在充分讨论的基础上,"},{"i":22,"n":"第二十二条","txt":"发审委会议召集人按照中国证监会的有关规定负责召集发审委会议，组织发审委委员发表意见、讨论，总结发审委会议审核意见和组织投票等事项。 发审委会议结束后，参会发审委委员应当在会议记录、审核意见、表决结果等会议资料上签名确认，同时提交工作底稿。"},{"i":23,"n":"第二十三条","txt":"发审委会议对发行人的股票发行申请形成审核意见之前，可以请发行人代表和保荐代表人到会陈述和接受发审委委员的询问。"},{"i":24,"n":"第二十四条","txt":"发审委会议对发行人的股票发行申请只进行一次审核。 出现发审委会议审核意见与表决结果有明显差异或者发审委会议表决结果显失公正情况的，中国证监会可以进行调查，并依法做出核准或者不予核准的决定。"},{"i":25,"n":"第二十五条","txt":"中国证监会有关职能部门负责安排发审委会议、送达有关审核材料、对发审委会议讨论情况进行记录、起草发审委会议纪要、保管档案等具体工作。"},{"i":26,"n":"第二十六条","txt":"发审委会议根据审核工作需要，可以邀请发审委委员以外的行业专家到会提供专业咨询意见。发审委委员以外的行业专家没有表决权。"},{"i":27,"n":"第二十七条","txt":"发审委每年应当至少召开一次全体会议，对审核工作进行总结。"},{"i":28,"n":"第二十八条","txt":"发审委会议审核发行人公开发行股票申请和可转换公司债券等中国证监会认可的其他公开发行证券申请，适用本节规定。"},{"i":29,"n":"第二十九条","txt":"中国证监会有关职能部门应当在发审委会议召开5日前，将会议通知、股票发行申请文件及中国证监会有关职能部门的初审报告送达参会发审委委员，并将发审委会议审核的发行人名单、会议时间、发行人承诺函和参会发审委委员名单在中国证监会网站上公布。"},{"i":30,"n":"第三十条","txt":"每次参加发审委会议的发审委委员为7名。表决投票时同意票数达到5票为通过，同意票数未达到5票为未通过。"},{"i":31,"n":"第三十一条","txt":"发审委委员发现存在尚待调查核实并影响明确判断的重大问题，应当在发审委会议前以书面方式提议暂缓表决。发审委会议首先对该股票发行申请是否需要暂缓表决进行投票，同意票数达到5票的，可以对该股票发行申请暂缓表决；同意票数未达到5票的，发审委会议按正常程序对该股票发行申请进行审核。 暂缓表决的发行申请再次提交发审委会议审核时，原则上仍由原发审委委员审核。 发审委会议对发行人的股票发行申请只能暂缓表决一次。"},{"i":32,"n":"第三十二条","txt":"发审委会议对发行人的股票发行申请投票表决后，中国证监会在网站上公布表决结果。 发审委会议对发行人股票发行申请作出的表决结果及提出的审核意见，中国证监会有关职能部门应当向发行人聘请的保荐人进行书面反馈。"},{"i":33,"n":"第三十三条","txt":"在发审委会议对发行人的股票发行申请表决通过后至中国证监会核准前，发行人发生了与所报送的股票发行申请文件不一致的重大事项，中国证监会有关职能部门可以提请发审委召开会后事项发审委会议，对该发行人的股票发行申请文件重新进行审核。会后事项发审委会议的参会发审委委员不受是否审核过该发行人的股票发行申请的限制。"},{"i":34,"n":"第三十四条","txt":"发审委会议审核上市公司非公开发行股票申请和中国证监会认可的其他非公开发行证券申请，适用本节规定。"},{"i":35,"n":"第三十五条","txt":"中国证监会有关职能部门应当在发审委会议召开前，将会议通知、股票发行申请文件及中国证监会有关职能部门的初审报告送达参会发审委委员。"},{"i":36,"n":"第三十六条","txt":"每次参加发审委会议的委员为5名。表决投票时同意票数达到3票为通过，同意票数未达到3票为未通过。"},{"i":37,"n":"第三十七条","txt":"发审委委员在审核上市公司非公开发行股票申请和中国证监会认可的其他非公开发行证券申请时，不得提议暂缓表决。"},{"i":38,"n":"第三十八条","txt":"中国证监会不公布发审委会议审核的发行人名单、会议时间、发行人承诺函、参会发审委委员名单和表决结果。"},{"i":39,"n":"第三十九条","txt":"中国证监会设立发行审核监察委员会，对发行审核工作进行监察。"},{"i":40,"n":"第四十条","txt":"中国证监会对发审委实行问责制度。出现发审委会议审核意见与表决结果有明显差异的，中国证监会可以要求所有参会发审委委员分别作出解释和说明。"},{"i":41,"n":"第四十一条","txt":"发审委委员存在违反本办法第十四条规定的行为，或者存在对所参加发审委会议应当回避而未提出回避等其他违反发审委工作纪律的行为的，中国证监会应当根据情节轻重对有关发审委委员分别予以谈话提醒、批评、公开谴责、解聘等处理。"},{"i":42,"n":"第四十二条","txt":"中国证监会建立对发审委委员违法、违纪行为的举报监督机制。 对有线索举报发审委委员存在违法、违纪行为的，中国证监会应当进行调查，根据调查结果对有关发审委委员分别予以谈话提醒、批评、解聘等处理；涉嫌犯罪的，依法移交司法机关处理。"},{"i":43,"n":"第四十三条","txt":"中国证监会对发审委委员的批评可以在新闻媒体上公开。"},{"i":44,"n":"第四十四条","txt":"在发审委会议召开前，有证据表明发行人、其他相关单位或者个人直接或者间接以不正当手段影响发审委委员对发行人股票发行申请的判断，或者以其他方式干扰发审委委员审核的，中国证监会可以暂停对有关发行人的发审委会议审核。 发行人股票发行申请通过发审委会议后，有证据表明发行人、其他相关单位或者个人直接或者间接以不正当手段影响发审委委员对发行人股票发行申请的判断的，或者以其他方式干扰发审委委员审核的，中国证监会可以暂停核准；情节严重的，中国证监会不予核准。"},{"i":45,"n":"第四十五条","txt":"发行人聘请的保荐人有义务督促发行人遵守本办法的有关规定。保荐人唆使、协助或者参与干扰发审委工作的，中国证监会按照有关规定在3个月内不受理该保荐人的推荐。"},{"i":46,"n":"第四十六条","txt":"本办法自2006年5月9日起施行。《中国证券监督管理委员会股票发行审核委员会暂行办法》（证监会令第16号）同时废止。"}],"zhongguozhengquanjianduguanliweiyuanhuixingzhengchb4acf0":[{"i":1,"n":"第一条","txt":"为了规范证券期货违法案件的行政处罚听证程序，保障和监督中国证券监督管理委员会（以下简称中国证监会）及其派出机构依法实施行政处罚，维护公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》、《中华人民共和国证券法》、《中华人民共和国证券投资基金法》和《期货交易管理条例》等法律、行政法规有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"中国证监会及其派出机构作出行政处罚决定前组织的听证，适用本规则。"},{"i":3,"n":"第三条","txt":"中国证监会及其派出机构组织听证，应当遵循公正、公开的原则，保障当事人的各项权利。"},{"i":4,"n":"第四条","txt":"听证依法实行回避制度。 听证主持人、听证员认为自己与本案有利害关系或者有其他关系可能影响案件公正处理的，应当自行回避。当事人认为听证主持人、听证员与本案有利害关系或者有其他关系可能影响案件公正处理的，有权以口头或者书面形式申请听证主持人、听证员回避。 当事人提出回避申请，应当说明理由，在听证开始前提出；回避事由在听证开始后知道的，也可以在听证辩论终结前提出。被申请回避的人员在决定作出前，应当暂停参与案件听证工作，但案件需要采取紧急措施的除外。 听证主持人、听证员的回避，由中国证监会负责组织听证部门的负责人或者派出机构的负责人决定；其他人员的回避，由听证主持人决定。 本条规定适用于书记员、翻译人员、鉴定人。"},{"i":5,"n":"第五条","txt":"中国证监会或其派出机构拟对当事人作出以下一项或者一项以上行政处罚的，应当在向当事人送达的《行政处罚事先告知书》中载明当事人享有要求听证的权利： （一）责令停止发行证券； （二）责令停业整顿； （三）暂停、撤销或者吊销证券、期货、基金相关业务许可； （四）暂停或者撤销任职资格、从业资格； （五）对个人没收业务收入、没收违法所得、罚款，单独或者合计5万元以上； （六）对单位没收业务收入、没收违法所得、罚款，单独或者合计30万元以上； （七）法律、行政法规和规章规定或者中国证监会及其派出机构认为可以听证的其他情形。"},{"i":6,"n":"第六条","txt":"除下列情况外，听证公开举行： （一）案件涉及国家秘密、商业秘密或者个人隐私； （二）案件涉及可能对证券、期货交易价格产生重大影响的尚未公开的信息； （三）法律规定的其他情况。"},{"i":7,"n":"第七条","txt":"当事人要求听证的，应当在《行政处罚事先告知书》送达后3日内提出听证要求。当事人逾期未提出听证要求的，视为放弃听证权利。 行政处罚涉及多个当事人，部分当事人放弃听证权利的，不影响其他当事人要求听证。"},{"i":8,"n":"第八条","txt":"同一案件中，符合本规则第五条规定情形的当事人要求听证的，其他当事人可以在《行政处罚事先告知书》送达后3日内提出一并参加听证的申请，是否准许，由中国证监会或其派出机构决定。"},{"i":9,"n":"第九条","txt":"中国证监会或其派出机构应当及时组织听证，并在举行听证7日前向当事人送达《听证通知书》。 《听证通知书》应当载明以下事项： （一）举行听证的时间、地点； （二）听证主持人、听证员和书记员名单； （三）当事人在听证中的权利和义务； （四）举行听证的程序； （五）中国证监会或其派出机构指定的听证联系人和联系方式； （六）其他应当载明的事项。"},{"i":10,"n":"第十条","txt":"当事人具有正当理由的，应当在收到《听证通知书》后3日内以书面形式提出延期举行听证的申请，是否准许，由中国证监会或其派出机构决定。"},{"i":11,"n":"第十一条","txt":"当事人在听证程序中享有以下权利： （一）亲自参加听证，或者委托1至2名代理人参加听证； （二）在听证召开前书面撤回听证申请； （三）在听证召开前向中国证监会或其派出机构申请查阅拟对其作出行政处罚决定所依据的证据； （四）根据本规则第四条的规定申请相关人员回避； （五）根据本规则第十条的规定申请延期举行听证； （六）带相关人员作为证人到听证现场为其作证； （七）对案件事实认定、法律适用、处罚幅度等进行陈述和申辩； （八）对案件调查人员提出的证据进行质证，并提出新的证据； （九）与案件调查人员进行辩论和作最后陈述； （十）法律、行政法规和规章规定的其他权利。"},{"i":12,"n":"第十二条","txt":"中国证监会或其派出机构同意当事人查阅证据申请的，当事人及其代理人可以按照规定查阅涉及本人行政处罚事项的证据，但涉及国家秘密、商业秘密和个人隐私的内容除外。"},{"i":13,"n":"第十三条","txt":"当事人在听证程序中应当履行以下义务： （一）按时出席或者委托代理人出席听证； （二）如实陈述案件事实和回答提问，举证客观、真实； （三）遵守听证纪律，服从听证主持人的要求； （四）听证结束后，在确认无误的听证笔录上签名或者盖章； （五）对获知的国家秘密、商业秘密和个人隐私应予保密； （六）法律、行政法规和规章规定的其他义务。"},{"i":14,"n":"第十四条","txt":"听证前，当事人及其代理人可以向中国证监会或其派出机构提交陈述申辩意见和证据。"},{"i":15,"n":"第十五条","txt":"中国证监会及其派出机构应当保障当事人充分行使在听证中的各项权利，履行下列职责： （一）组织召开听证； （二）向当事人送达《听证通知书》； （三）对当事人查阅证据申请作出决定； （四）决定回避、延期举行听证、中止听证、终止听证等程序事项； （五）接收并复核当事人及其代理人提交的陈述申辩意见和证据； （六）法律、行政法规和规章规定应当履行的其他职责。"},{"i":16,"n":"第十六条","txt":"听证按照以下程序进行： （一）听证开始前，由书记员查明当事人及其代理人、案件调查人员等听证参加人是否到场，并宣布听证纪律； （二）听证主持人核对听证参加人，宣布出席听证的听证员、书记员名单，告知听证参加人在听证中的权利义务，询问当事人及其代理人是否申请回避； （三）听证主持人宣布听证开始，宣布案由； （四）案件调查人员提出当事人违法的具体事实、证据和行政处罚建议； （五）当事人及其代理人进行陈述和申辩，并可以提出相关事实、理由和证据； （六）当事人及其代理人和案件调查人员双方对有关证据进行质证。经听证主持人允许，双方可以向证人、鉴定人发问； （七）当事人及其代理人和案件调查人员双方进行辩论，经听证主持人允许，双方可以相互发问； （八）当事人及其代理人作最后陈述； （九）听证主持人宣布听证结束。 听证过程中，听证主持人、听证员可以向案件调查人员、当事人及其代理人、证人、鉴定人等提问，有关"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，延期举行听证： （一）因不可抗力致使听证无法按期举行的； （二）当事人及其代理人听证开始时申请回避理由成立，且因无法即时更换被申请回避人员致使听证无法按期举行的； （三）当事人及其代理人申请延期举行听证，并有正当理由的； （四）中国证监会或其派出机构认为需要延期举行听证的其他情形。 除当事人及其代理人申请延期举行听证并经同意的以外，中国证监会或其派出机构应当将延期举行听证的理由及时告知当事人。 延期举行听证的情形消除后，中国证监会或其派出机构应当及时组织听证。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，中止听证： （一）当事人及其代理人在听证过程中提出的回避申请理由成立，且因无法即时更换被申请回避人员致使听证无法继续举行的； （二）当事人及其代理人因不可抗拒的事由，无法继续参加听证的； （三）因不可抗拒的事由，致使听证无法继续举行的； （四）其他应当中止听证的情形。 中止听证的情形消除后，中国证监会或其派出机构应当及时组织听证。"},{"i":19,"n":"第十九条","txt":"当事人及其代理人有下列情形之一的，中国证监会或其派出机构可以终止听证，并将相关情形记录在案： （一）书面撤回听证申请的； （二）无正当理由不出席听证的； （三）未经听证主持人允许中途退场的； （四）严重违反听证纪律，被听证主持人责令退场的； （五）其他符合终止听证的情形。 部分当事人及其代理人因上述情形被终止听证的，不影响其他当事人及其代理人继续行使听证权利。"},{"i":20,"n":"第二十条","txt":"在听证过程中，听证参加人、旁听人员等应当遵守听证纪律，保证听证有序举行。 听证主持人对违反听证纪律、妨碍听证秩序的人员，有权予以制止、口头警告，情节严重的，可以责令其退场。"},{"i":21,"n":"第二十一条","txt":"听证应当制作笔录。听证笔录应当当场交由当事人及其代理人、证人及其他有关人员确认无误后签名或者盖章。相关人员认为对自己陈述的记录有遗漏或者差错的，有权要求补正。相关人员拒绝签名或者盖章的，中国证监会或其派出机构应当在听证笔录中予以注明。"},{"i":22,"n":"第二十二条","txt":"听证结束，当事人及其代理人应当将陈述申辩意见和有关证据提交中国证监会或其派出机构。"},{"i":23,"n":"第二十三条","txt":"听证结束后，中国证监会或其派出机构应当对当事人提出的事实、理由和证据进行复核，当事人提出的事实和理由成立的，应当采纳。 中国证监会或其派出机构应当根据听证复核情况，依据《中华人民共和国行政处罚法》第三十八条的规定，对当事人作出相应的处理决定。 中国证监会或其派出机构不得因当事人申辩和听证而加重处罚。"},{"i":24,"n":"第二十四条","txt":"中国证监会及其派出机构举行听证，不向当事人收取费用。 当事人委托代理人、证人出席听证等所产生的费用以及其他己方支出，由当事人自行承担。"},{"i":25,"n":"第二十五条","txt":"中国证监会及其派出机构拟对当事人采取市场禁入措施的，当事人可以要求举行听证，听证程序参照本规则的规定执行。 中国证监会及其派出机构在对当事人采取注销业务许可、关闭分支机构等重大监管措施之前，认为需要组织听证或者根据当事人申请决定听证的，听证程序参照本规则的规定执行。"},{"i":26,"n":"第二十六条","txt":"本规则规定的期间以日计算。期间开始当日，不计算在期间内。 期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。"},{"i":27,"n":"第二十七条","txt":"本规则自2015年12月4日起施行。《中国证券监督管理委员会行政处罚听证规则》（证监法律字〔2007〕8号）同时废止。"}],"zhongguozhengquanjianduguanliweiyuanhuixingzhengfue186f9":[{"i":1,"n":"第一条","txt":"为了保护公民、法人或者其他组织的合法权益，保障和监督中国证券监督管理委员会（以下简称中国证监会）依法行使监管职权，进一步发挥行政复议制度在解决证券期货行政争议中的作用，不断提高证券期货监督管理机构的依法行政水平，根据《中华人民共和国行政复议法》（以下简称《行政复议法》）、《中华人民共和国证券法》、《中华人民共和国行政复议法实施条例》（以下简称《行政复议法实施条例》）等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为中国证监会或其派出机构、授权组织的具体行政行为侵犯其合法权益的，依照《行政复议法》、《行政复议法实施条例》和本办法的规定向中国证监会申请行政复议。 中国证监会作为行政复议机关，受理行政复议申请，对被申请行政复议的具体行政行为进行审查并作出决定。 对中国证监会具体行政行为不服申请原级行政复议的，原承办具体行政行为有关事项的部门或者机构（以下简称原承办部门）负责向行政复议机构作出答复。 对中国证监会派出机构或者授权组织的具体行政行为不服申请行政复议的，由派出机构或者授权组织负责向行政复议机构作出答复。"},{"i":3,"n":"第三条","txt":"中国证监会负责法制工作的机构作为行政复议机构具体办理行政复议事项，除应当依照《行政复议法》第三条、《行政复议法实施条例》第三条的规定履行职责外，还应当履行下列职责： （一）组织行政复议听证； （二）根据需要提请召开行政复议委员会工作会议； （三）提出审查意见； （四）办理行政复议和解、组织行政复议调解等事项； （五）指导派出机构的行政应诉工作； （六）法律、行政法规规定的其他职责。"},{"i":4,"n":"第四条","txt":"专职行政复议人员应当具备以下条件： （一）正直诚实，品行良好； （二）受过法律专业教育； （三）从事证券期货业工作2年以上或者取得法律、会计等专业资格； （四）法律、行政法规规定的其他条件。"},{"i":5,"n":"第五条","txt":"中国证监会设立行政复议委员会，审查重大复杂行政复议案件。 重大行政应诉案件，可以提交行政复议委员会进行讨论。"},{"i":6,"n":"第六条","txt":"中国证监会通过适当的形式，公布中国证监会管辖的行政复议案件受理范围、受理条件、行政复议申请书样式、行政复议案件审理程序，以及接受行政复议申请书的地址、传真号码等事项。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织对中国证监会或其派出机构、授权组织作出的具体行政行为不服，有下列情形之一的，可以向中国证监会申请行政复议： （一）对中国证监会或其派出机构作出的警告、罚款、没收违法所得、责令关闭、撤销任职资格或者证券从业资格、暂停或者撤销业务许可、吊销业务许可证等行政处罚决定不服的； （二）对中国证监会或其派出机构作出的证券、期货市场禁入决定不服的； （三）对中国证监会或其派出机构作出的冻结、查封、限制交易等行政强制措施不服的； （四）对中国证监会或其派出机构作出的限制业务活动、限期撤销境内分支机构、限制分配红利、限制转让财产、责令限制股东行使股东权利以及责令更换董事、监事、高级管理人员或者限制其权利等行政监管措施不服的； （五）认为中国证监会或其派出机构、授权组织侵犯其合法的经营自主权的； （六）认为符合法定条件，申请办理证券、期货行政许可事项，中国证监会或其派出机构没有依法办"},{"i":8,"n":"第八条","txt":"中国证监会或其派出机构、授权组织的下列行为不属于行政复议申请的范围： （一）中国证监会或其派出机构、授权组织对其工作人员作出的行政处分以及其他人事处理决定； （二）中国证监会或其派出机构、授权组织对证券、期货民事争议所作的调解行为； （三）由中国证监会或其派出机构作出的行政调解和行政和解行为； （四）不具有强制力的证券、期货行政指导行为； （五）中国证监会或其派出机构对公民、法人或者其他组织提起申诉的重复处理行为； （六）证券、期货交易所或证券、期货业协会依据自律规则，对公民、法人或者其他组织作出的决定； （七）对公民、法人或者其他组织的权利义务不产生实际影响的行为。"},{"i":9,"n":"第九条","txt":"依照《行政复议法》、《行政复议法实施条例》以及本办法提起行政复议申请的公民、法人或者其他组织是行政复议的申请人。"},{"i":10,"n":"第十条","txt":"依据《行政复议法实施条例》第七条的规定申请行政复议的，申请人应当同时向行政复议机构提交股份制企业的股东大会、股东代表大会、董事会作出的申请行政复议的决议和授权委托书。"},{"i":11,"n":"第十一条","txt":"向行政复议机构申请作为第三人参加行政复议的，应当证明其与被审查的具体行政行为有利害关系。 经行政复议机构审查同意或者认为第三人有必要参加行政复议的，行政复议机构可以书面通知第三人。 第三人不参加行政复议，不影响行政复议案件的审理。"},{"i":12,"n":"第十二条","txt":"申请人、第三人委托代理人向行政复议机构提交的授权委托书应当载明下列事项： （一）委托人姓名或者名称，委托人为法人或者其他组织的，还应当载明法定代表人或者主要负责人的姓名、职务； （二）代理人姓名、身份证号码、工作单位、通讯地址、邮政编码及电话等联系方式； （三）委托事项和代理期间； （四）代理人代为提起、变更、撤回行政复议申请、参加行政复议调解、达成行政复议和解、参加行政复议听证、递交证据材料、收受行政复议法律文书等代理权限； （五）委托日期及委托人签字或者盖章。 提交授权委托书，应当提供委托人和代理人身份证明，以律师身份代理参加行政复议的，还应当提供律师执业证明文件。"},{"i":13,"n":"第十三条","txt":"申请人对中国证监会或其派出机构、授权组织的具体行政行为不服申请行政复议的，作出该具体行政行为的中国证监会或其派出机构、授权组织是被申请人。 中国证监会或其派出机构委托其他组织作出具体行政行为的，中国证监会或其派出机构是被申请人。"},{"i":14,"n":"第十四条","txt":"申请人对两个以上派出机构或授权组织共同作出的具体行政行为不服申请行政复议的，共同作出具体行政行为的机构或组织是共同被申请人。"},{"i":15,"n":"第十五条","txt":"派出机构或者其他组织依照法律、行政法规、规章规定，报经中国证监会批准作出具体行政行为的，中国证监会是被申请人。"},{"i":16,"n":"第十六条","txt":"对符合《行政复议法实施条例》第十八条、第二十八条的规定，属于行政复议机关受理的行政复议申请，自行政复议机构收到之日起即为受理。 行政复议机构收到行政复议申请的日期，属于申请人当面递交的，由行政复议机构经办人在申请书上注明收到日期，并且由递交人签字确认；属于直接从邮递渠道收取或者其他单位、部门转来的，由行政复议机构签收确认；属于申请人以传真方式提交的，以行政复议机构接收传真之日为准。"},{"i":17,"n":"第十七条","txt":"依照《行政复议法实施条例》第二十九条的规定，行政复议机构可以自收到该行政复议申请之日起5日内书面通知申请人补正，有下列情形之一的，属于行政复议申请材料不齐全或者表述不清楚： （一）未依照《行政复议法实施条例》第十九条第（一）项的规定提供申请人基本情况； （二）无申请人身份证明文件； （三）无明确的被申请人； （四）行政复议请求不具体、不明确； （五）委托代理申请复议的手续不全或者权限不明确； （六）未依照《行政复议法实施条例》第二十一条的规定提供证明材料； （七）其他行政复议申请材料不齐全或者表述不清楚的情形。 申请人收到补正通知后，无正当理由逾期不补正的，视为放弃行政复议申请。"},{"i":18,"n":"第十八条","txt":"申请人采取传真方式提出行政复议申请的，行政复议机构可以要求申请人依照《行政复议法实施条例》第二十九条、本办法第十七条的规定补充提交申请材料的原件。"},{"i":19,"n":"第十九条","txt":"行政复议申请材料不齐全或者表述不清楚，或者采取传真方式提出行政复议申请，行政复议机构书面通知申请人补正或者提交原件的，受理的审查期限应当自收到补正后的行政复议申请材料或者原件之日起算。"},{"i":20,"n":"第二十条","txt":"下列情形不视为申请行政复议，行政复议机构可以告知申请人处理结果或者转由其他机构处理并告知申请人： （一）对中国证监会工作人员的个人违法违纪行为进行举报、控告的； （二）不涉及中国证监会具体行政行为，只对中国证监会规章或者规范性文件有异议的； （三）对行政处罚认定的事实、适用的依据、处罚种类、处罚幅度及处罚程序等没有异议，仅因经济困难，请求减、免、缓缴罚款的； （四）请求解答法律、行政法规、规章的； （五）其他以行政复议申请名义，进行信访投诉的情形。"},{"i":21,"n":"第二十一条","txt":"行政复议机构应当自受理行政复议申请之日起7日内，将行政复议答复通知书、行政复议申请书副本或者行政复议申请笔录复印件以及申请人提交的证据、有关材料的副本发送被申请人或者原承办部门。"},{"i":22,"n":"第二十二条","txt":"被申请人或者原承办部门应当自收到申请书副本或者申请笔录复印件之日起10日内，向行政复议机构提交行政复议答复意见书，并同时提交当初作出具体行政行为的全部证据、依据和其他有关材料。 行政复议答复意见书应当载明下列内容： （一）被申请人当初作出具体行政行为时所认定的事实、证据及适用的法律、行政法规、规章及规范性文件，对有关事实的陈述应当注明相应的证据及证据的来源； （二）对申请人行政复议申请中陈述的事实和理由逐条进行答辩并进行相应的举证； （三）对有关具体行政行为建议维持、变更、撤销或者确认违法，建议驳回行政复议申请，进行行政复议调解等结论； （四）作出书面答复的时间。 被申请人或者原承办部门应当按照行政执法案卷的要求提交单独装订的行政复议答复证据案卷，并明确申请人、第三人可以查阅的案卷材料范围。"},{"i":23,"n":"第二十三条","txt":"一般行政复议案件，由行政复议机构负责审查并提出复议意见；重大复杂的行政复议案件，由行政复议机构提请行政复议委员会进行审查，由行政复议委员会提出复议意见。 行政复议机构审查复议案件，必须有2名以上行政复议人员共同进行。行政复议委员会通过委员会工作会议审查行政复议案件。行政复议委员会的组成和工作规则另行规定。"},{"i":24,"n":"第二十四条","txt":"案件审理人员或者出席会议的复议委员与本案有利害关系或者有其他关系可能影响公正审理行政复议案件的，应当进行回避。"},{"i":25,"n":"第二十五条","txt":"对于案件事实复杂、申请人与被申请人就同一认定事实提交的证据不一致或者行政复议机构认为必要的，行政复议机构可以依照《行政复议法实施条例》第三十四条的规定向有关组织和人员调查取证。 行政复议机构采用询问方式进行调查取证的，应当制作询问笔录，由被调查单位和人员签字或者盖章确认。"},{"i":26,"n":"第二十六条","txt":"行政复议机关提供必要的条件，方便申请人、第三人查阅有关材料。 申请人、第三人查阅有关材料应当遵守下列规定： （一）申请人、第三人向行政复议机构提出书面阅卷请求，阅卷不得违反相关保密的规定； （二）申请人、第三人应当按照指定的时间、地点和阅卷范围进行查阅； （三）查阅时，申请人、第三人应当出示身份证件； （四）申请人、第三人可以摘抄查阅材料的内容； （五）申请人、第三人不得有涂改、替换、毁损、隐匿查阅的材料等行为。 申请人、第三人违反前款第（五）项的，行政复议机构应当立即终止其查阅。情节严重的，依法移送公安机关处理。"},{"i":27,"n":"第二十七条","txt":"申请人、被申请人或者原承办部门对案件事实争议较大或者案件重大复杂的，行政复议机构可以采取听证的方式审理。 被申请人在作出原具体行政行为时，已经采取听证方式的或者采取书面审查可以查明事实、证据的，行政复议机构不再采取听证方式审理。"},{"i":28,"n":"第二十八条","txt":"行政复议机构决定举行听证的，按照下列程序和要求进行： （一）行政复议机构应当将听证的时间、地点、具体要求等事项提前3日通知有关当事人； （二）行政复议听证人员为不得少于3人的单数，由行政复议机构负责人确定，并且指定其中1人为听证主持人； （三）举行听证时，被申请人或者原承办部门的工作人员应当提供行政复议答复意见书以及相应的证据、依据，申请人、第三人可以提出证据，并进行申辩和质证； （四）听证应当制作笔录，听证笔录应当交听证参加人确认无误后签字或者盖章。"},{"i":29,"n":"第二十九条","txt":"行政复议机关对行政复议机构或者行政复议委员会提出的复议意见进行审查，经行政复议机关的负责人同意或者集体讨论通过后，依法作出行政复议决定。"},{"i":30,"n":"第三十条","txt":"依照《行政复议法》第三十一条的规定，有下列情况之一的，可以视为案件情况复杂，经行政复议机关的负责人批准，行政复议期限可以适当延长，但是延长期限最多不超过30日： （一）需要举行行政复议听证的； （二）申请人、第三人提出新的事实、理由或者证据需进一步调查核实的； （三）申请人与被申请人进行和解或者行政复议机构进行调解的； （四）情况复杂，不能在规定期限内作出行政复议决定的其他情况。 延长复议期限，应当制作决定延期通知书，告知有关当事人。"},{"i":31,"n":"第三十一条","txt":"行政复议机关作出行政复议决定，应当制作行政复议决定书，送达申请人和第三人，抄送被申请人。 行政复议决定书应当载明下列内容： （一）申请人、第三人基本情况：自然人姓名、性别、工作单位及职务（原工作单位及职务）、住址；法人或者其他组织的名称、地址、法定代表人或者主要负责人的姓名、职务； （二）被申请人名称、地址； （三）申请人申请复议的请求、事实和理由； （四）被申请人答复的事实、理由、证据和依据； （五）行政复议认定的事实和相应的证据； （六）作出行政复议决定的具体理由和法律依据； （七）行政复议决定的结论； （八）行政复议决定的救济途径； （九）作出行政复议决定的日期。 行政复议决定书应当加盖行政复议机关的印章。"},{"i":32,"n":"第三十二条","txt":"行政复议决定书一经送达，即发生法律效力。行政复议机关可以通过中国证监会门户网站、中国证监会公告等方式公布生效的行政复议决定书。"},{"i":33,"n":"第三十三条","txt":"经被申请人同意，原承办部门、派出机构或者授权组织和申请人可以依照《行政复议法实施条例》第四十条的规定在作出行政复议决定之前自愿达成和解，并向行政复议机构提交书面和解协议。 和解协议应当载明行政复议请求、事实、理由、和解的条件和达成和解的结果。 和解协议应当由申请人和被申请人或者原承办部门签字或者盖章。"},{"i":34,"n":"第三十四条","txt":"行政复议机构应当对申请人和作出具体行政行为的机构提交的和解协议进行备案。和解确属双方真实意思表示，和解内容不损害社会公共利益和他人合法权益的，行政复议机构应当准许和解，终止行政复议案件的审理。 在行政复议期间内未达成和解协议的，行政复议机关应当及时作出行政复议决定。"},{"i":35,"n":"第三十五条","txt":"经行政复议机构准许和解的，申请人和被申请人应当履行和解协议。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的，行政复议机关可以进行调解： （一）公民、法人或者其他组织对中国证监会行使自由裁量权作出的具体行政行为不服申请行政复议的； （二）行政赔偿或者行政补偿纠纷。"},{"i":37,"n":"第三十七条","txt":"调解应当符合以下要求： （一）查明案件事实，充分尊重申请人和被申请人的意愿； （二）调解应当按照自愿、合法的原则，调解结果不得损害国家利益、社会公共利益或者他人合法权益。"},{"i":38,"n":"第三十八条","txt":"申请人和被申请人经调解达成协议的，行政复议机关应当制作行政复议调解书。行政复议调解书应当载明下列内容： （一）申请人基本情况：自然人姓名、性别、工作单位及职务（原工作单位及职务）、住址；法人或者其他组织的名称、地址、法定代表人或者主要负责人的姓名、职务； （二）被申请人名称、地址； （三）申请人申请行政复议的请求、事实和理由； （四）被申请人答复的事实、理由、证据和依据； （五）进行调解的基本情况； （六）调解协议的主要内容和调解结果； （七）申请人、被申请人履行调解书的义务； （八）日期。 行政复议调解书应当加盖行政复议专用章。行政复议调解书经申请人、被申请人签字或者盖章，即具有法律效力。申请人和被申请人应当履行生效的行政复议调解书。"},{"i":39,"n":"第三十九条","txt":"行政复议机关在行政复议期间发现相关行政行为违法或者需要做好善后工作等情况的，可以向被申请人或者原承办部门制作行政复议意见书，并抄报中国证监会监察部门。 行政复议意见书由行政复议机构具体承办，应当包括具体行政行为存在的问题、认定事实、理由和依据、整改意见等。 被申请人或者原承办部门应当自收到行政复议意见书之日起60日内将纠正相关行政违法行为、改进执法工作或者做好善后工作的情况报告行政复议机构。 对突出问题不予整改导致重复违法的，行政复议机关要予以通报。"},{"i":40,"n":"第四十条","txt":"行政复议机构在行政复议期间发现法律、行政法规、规章的实施中带有普遍性的问题，可以向有关立法机关或其他有关行政机关提出完善立法的建议。 行政复议建议书应包括法律、行政法规、规章等存在的问题，相关事实、理由和依据、工作建议等。"},{"i":41,"n":"第四十一条","txt":"中国证监会应当建立行政复议统计报告制度，定期对行政复议、行政应诉案件情况进行分析、研究，总结工作中的经验及不足，提出改进意见。"},{"i":42,"n":"第四十二条","txt":"行政复议人员应当每年参加至少2次行政复议机构或者中国证监会业务部门组织的监管业务培训，提高行政复议人员的专业素质。 业务培训包括以下内容： （一）行政复议及行政应诉业务培训； （二）证券期货案件调查、审理等业务培训； （三）证券期货日常监管及创新业务培训； （四）涉及证券期货市场监管的政治、经济理论培训等。"},{"i":43,"n":"第四十三条","txt":"行政复议机构对于在办理行政复议、行政应诉案件过程中成绩显著的单位和个人，可以提请中国证监会依照有关规定给予表彰和奖励。"},{"i":44,"n":"第四十四条","txt":"行政复议机关在受理、审查、决定行政复议申请过程中，可使用行政复议专用章。在中国证监会行政复议活动中，行政复议专用章和行政复议机关的印章具有同等法律效力。"},{"i":45,"n":"第四十五条","txt":"外国人、无国籍人、外国组织在中华人民共和国境内向中国证监会申请行政复议，适用本办法。"},{"i":46,"n":"第四十六条","txt":"本办法自2010年7月1日起施行。2002年11月25日发布的《中国证券监督管理委员会行政复议办法》（证监会令第13号）同时废止。"}],"zhongguozhengquanjianduguanliweiyuanhuixingzhengxu328c14":[{"i":1,"n":"第一条","txt":"为了规范中国证券监督管理委员会（以下简称中国证监会）实施行政许可行为，完善证券期货行政许可实施程序制度，根据《行政许可法》、《证券法》、《证券投资基金法》、《期货交易管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称行政许可，是指中国证监会根据自然人、法人或者其他组织（以下称申请人）的申请，经依法审查，准予其从事证券期货市场特定活动的行为。"},{"i":3,"n":"第三条","txt":"中国证监会实施行政许可，其程序适用本规定。 申请人依法取得行政许可后，申请变更行政许可、延续行政许可有效期的，适用本规定。"},{"i":4,"n":"第四条","txt":"中国证监会依照法定的权限、范围、条件和程序实施行政许可，遵循公开、公平、公正和便民的原则，提高办事效率，提供优质服务。 法律、行政法规规定实施行政许可应当遵循审慎监管原则的，从其规定。"},{"i":5,"n":"第五条","txt":"中国证监会可以依法授权派出机构实施行政许可。授权实施的行政许可，以派出机构的名义作出行政许可决定。"},{"i":6,"n":"第六条","txt":"中国证监会实施行政许可实行统一受理、统一送达、一次告知补正、说明理由、公示等制度。"},{"i":7,"n":"第七条","txt":"中国证监会实施行政许可，由专门的机构（以下称受理部门）办理行政许可申请受理事项。"},{"i":8,"n":"第八条","txt":"申请人提交申请材料，受理部门应当要求申请人出示单位介绍信、身份证等身份证明文件，并予以核对。申请人委托他人提交申请材料的，受理部门还应当要求受托人提交申请人的授权委托书，出示受托人的身份证明文件。受理部门应当留存申请人、申请人的受托人的身份证明文件复印件。 申请人提交申请材料，应当填写《申请材料情况登记表》。"},{"i":9,"n":"第九条","txt":"受理部门发现申请事项依法不需要取得行政许可或者不属于中国证监会职权范围的，应当即时告知申请人不予受理，并出具不予受理通知。申请事项依法不属于中国证监会职权范围的，还应当同时告知申请人向有关行政机关申请。"},{"i":10,"n":"第十条","txt":"受理部门接收申请材料，应当及时办理登记手续，并向申请人开具申请材料接收凭证。"},{"i":11,"n":"第十一条","txt":"负责审查申请材料的部门（以下称审查部门）对申请材料进行形式审查，需要申请人补正申请材料的，应当自出具接收凭证之日起5个工作日内一次性提出全部补正要求。审查部门不得多次要求申请人补正申请材料。"},{"i":12,"n":"第十二条","txt":"需要申请人补正申请材料的，受理部门应当出具补正通知；申请人补正申请材料需要使用已提交申请材料的，应当将申请材料退回申请人并予以登记。 申请人应当自补正通知发出之日起30个工作日内提交补正申请材料。 受理部门负责接收、登记申请人按照要求提交的补正申请材料。"},{"i":13,"n":"第十三条","txt":"申请人在作出受理申请决定之前要求撤回申请的，受理部门应当检查并留存申请人或者其受托人的身份证明文件（或复印件）、授权委托书、撤回申请的报告，收回申请材料接收凭证，经登记后将申请材料退回申请人。 将申请材料退回申请人，应当留存一份申请材料（或复印件）。"},{"i":14,"n":"第十四条","txt":"申请事项属于中国证监会职权范围，申请材料齐全、符合法定形式的，由受理部门出具受理通知。 决定受理的申请，按照法律、行政法规的规定，申请人应当交纳有关费用的，受理部门应当通知申请人先行交费，凭交费凭证领取受理通知。"},{"i":15,"n":"第十五条","txt":"申请人有下列情形之一的，作出不予受理申请决定： （一）通知申请人补正申请材料，申请人在30个工作日内未能提交全部补正申请材料； （二）申请人在30个工作日内提交的补正申请材料仍不齐全或者不符合法定形式； （三）为申请人制作、出具有关申请材料的证券公司、证券服务机构因涉嫌违法违规被中国证监会及其派出机构立案调查，或者被司法机关侦查，尚未结案，且涉案行为与其为申请人提供服务的行为属于同类业务或者对市场有重大影响； （四）为申请人制作、出具有关申请材料的证券公司、证券服务机构的有关人员因涉嫌违法违规被中国证监会及其派出机构立案调查，或者被司法机关侦查，尚未结案，且涉案行为与其为申请人提供服务的行为属于同类业务或者对市场有重大影响； （五）法律、行政法规及中国证监会规定的其他情形。 决定不予受理申请的，受理部门出具不予受理通知，告知申请人或者其受托人取回申请材料。申请人或者其受托人取回申请材料"},{"i":16,"n":"第十六条","txt":"受理或者不予受理申请决定，应当自出具申请材料接收凭证之日起5个工作日内或者接收全部补正申请材料之日起两个工作日内作出，逾期不作出决定或者不告知申请人补正申请材料的，自出具申请材料接收凭证之日起即为受理。"},{"i":17,"n":"第十七条","txt":"审查部门在审查申请材料过程中，认为需要申请人作出书面说明、解释的，原则上应当将问题一次汇总成书面反馈意见。申请人应当在审查部门规定的期限内提交书面回复意见；确有困难的，可以提交延期回复的书面报告，并说明理由。 确需由申请人作出进一步说明、解释的，审查部门可以提出第二次书面反馈意见，并要求申请人在书面反馈意见发出之日起30个工作日内提交书面回复意见。 申请人的书面回复意见不明确，情况复杂，审查部门难以作出准确判断的，经中国证监会负责人批准，可以增加书面反馈的次数，并要求申请人在书面反馈意见发出之日起30个工作日内提交书面回复意见。 书面反馈意见由受理部门告知、送达申请人。申请人提交的书面回复意见，由受理部门负责接收、登记。 审查部门负责审查申请材料的工作人员在首次书面反馈意见告知、送达申请人之前，不得就申请事项主动与申请人或者其受托人进行接触。"},{"i":18,"n":"第十八条","txt":"需要申请人当面就其提交的书面回复意见作出说明、解释的，审查部门应当指派两名以上工作人员在办公场所与申请人、申请人聘请的中介机构或者申请人的受托人进行会谈。涉及重大事项的，审查部门应当制作会谈记录，并由审查部门工作人员、参与会谈的申请人、申请人聘请的中介机构或者申请人的受托人签字确认。 需要申请人就其提交的书面回复意见作出说明、解释，事项简单的，审查部门工作人员可以通过电话、传真、电子邮件等方式办理，并制作、留存有关电话记录、传真件或者电子邮件。"},{"i":19,"n":"第十九条","txt":"审查部门在审查申请材料过程中，依据法定条件和程序，可以直接或者委托派出机构对申请材料的有关内容进行实地核查。 对有关举报材料，中国证监会及其派出机构可以通过下列方式进行核查： （一）要求申请人作出书面说明； （二）要求负有法定职责的有关中介机构作出书面说明； （三）委托有关中介机构进行实地核查； （四）直接进行实地核查； （五）法律、行政法规以及中国证监会规定的其他核查方式。 需要实地核查的，中国证监会及其派出机构应当指派两名以上工作人员进行核查。"},{"i":20,"n":"第二十条","txt":"在审查申请材料过程中，申请人有下列情形之一的，应当作出终止审查的决定，通知申请人： （一）申请人主动要求撤回申请； （二）申请人是自然人，该自然人死亡或者丧失行为能力； （三）申请人是法人或者其他组织，该法人或者其他组织依法终止； （四）申请人未在规定的期限内提交书面回复意见，且未提交延期回复的报告，或者虽提交延期回复的报告，但未说明理由或理由不充分； （五）申请人未在本规定第十七条第二款、第三款规定的30个工作日内提交书面回复意见。"},{"i":21,"n":"第二十一条","txt":"申请人主动要求撤回申请的，应当向受理部门提交书面报告，受理部门应当出具终止审查通知，经检查并留存申请人或者其受托人的身份证明文件（或复印件）、授权委托书，留存一份申请材料（或复印件），登记后将申请材料退回申请人。"},{"i":22,"n":"第二十二条","txt":"在审查申请材料过程中，有下列情形之一的，应当作出中止审查的决定，通知申请人： （一）申请人因涉嫌违法违规被行政机关调查，或者被司法机关侦查，尚未结案，对其行政许可事项影响重大； （二）申请人被中国证监会依法采取限制业务活动、责令停业整顿、指定其他机构托管、接管等监管措施，尚未解除； （三）为申请人制作、出具有关申请材料的证券公司、证券服务机构因涉嫌违法违规被中国证监会及其派出机构立案调查，或者被司法机关侦查，尚未结案，且涉案行为与其为申请人提供服务的行为属于同类业务或者对市场有重大影响； （四）为申请人制作、出具有关申请材料的证券公司、证券服务机构的有关人员因涉嫌违法违规被中国证监会及其派出机构立案调查，或者被司法机关侦查，尚未结案，且涉案行为与其为申请人提供服务的行为属于同类业务或者对市场有重大影响； （五）对有关法律、行政法规、规章的规定，需要进一步明确具体含义，请求有关机关作出解"},{"i":23,"n":"第二十三条","txt":"因本规定第二十二条第一款第（一）、（二）、（五）项规定情形中止审查的，该情形消失后，中国证监会恢复审查，通知申请人。 因本规定第二十二条第一款第（三）、（四）项规定情形中止审查的，证券公司、证券服务机构应当指派与被调查事项无关的人员，对该机构或者有关人员为被中止审查的申请事项制作、出具的申请材料进行复核。按要求提交复核报告，并对申请事项符合行政许可法定条件、标准，所制作、出具的文件不存在虚假记载、误导性陈述或者重大遗漏发表明确复核意见的，中国证监会应当在30个工作日内恢复审查，通知申请人。 申请人主动要求中止审查的，应当向受理部门提交书面申请。同意中止审查的，受理部门应当出具中止审查通知。申请人申请恢复审查的，应当向受理部门提交书面申请。同意恢复审查的，受理部门应当出具恢复审查通知。"},{"i":24,"n":"第二十四条","txt":"中国证监会根据申请人的申请是否符合法定条件、标准，作出准予或者不予行政许可的决定。 作出不予行政许可决定的，应当在不予行政许可决定中说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":25,"n":"第二十五条","txt":"作出准予行政许可的决定，需要颁发行政许可证件的，应当向申请人颁发下列行政许可证件： （一）中国证监会的批准文件； （二）资格证、资质证或者其他合格证书； （三）许可证、执照或者其他许可证书； （四）法律、行政法规规定的其他行政许可证件。"},{"i":26,"n":"第二十六条","txt":"事项简单、审查标准明确、申请材料采用格式文本的行政许可，其实施程序适用本章规定。 适用简易程序的行政许可事项，由中国证监会予以公布。"},{"i":27,"n":"第二十七条","txt":"适用简易程序的行政许可，受理部门当场进行形式审查，并直接作出是否受理的决定或者提出补正申请材料的要求。申请材料存在可以当场更正的错误的，受理部门应当允许申请人当场更正。"},{"i":28,"n":"第二十八条","txt":"审查部门在审查适用简易程序的行政许可申请过程中，可以向申请人口头提出申请材料中存在的问题，要求申请人进行说明、解释，并应当制作相关记录后签字保存。确需书面反馈意见的，依照本规定第十七条的规定办理。"},{"i":29,"n":"第二十九条","txt":"适用简易程序的行政许可，由审查部门根据中国证监会负责人的授权，作出准予或者不予行政许可决定，并加盖中国证监会印章。"},{"i":30,"n":"第三十条","txt":"派出机构进行初步审查、中国证监会进行复审并作出决定的行政许可，由派出机构依照本规定第二章第一节的规定接收、登记申请材料，作出是否受理的决定并送达申请人。 中国证监会根据审查情况和派出机构的初步审查意见，作出准予或者不予行政许可的决定。"},{"i":31,"n":"第三十一条","txt":"中国证监会审查、派出机构出具书面意见的行政许可，其受理事项依照本规定第二章第一节的规定办理。 中国证监会根据审查情况和派出机构的意见，作出准予或者不予行政许可的决定。"},{"i":32,"n":"第三十二条","txt":"依法由中国证监会和其他行政机关共同作出决定的行政许可，中国证监会主办的，其受理事项依照本规定第二章第一节的规定办理。 中国证监会提出审查意见，将申请材料移送有关行政机关审查会签。有关行政机关审查会签完毕，中国证监会根据会签情况作出准予或者不予行政许可决定。"},{"i":33,"n":"第三十三条","txt":"依法由中国证监会和其他行政机关共同作出决定的行政许可，其他行政机关主办的，由受理部门接收、登记申请材料。 中国证监会审查会签后，退回主办行政机关或者转送其他需要会签的行政机关。"},{"i":34,"n":"第三十四条","txt":"除本规定第四章规定的由派出机构进行初步审查的行政许可、中国证监会和其他行政机关共同作出决定的行政许可外，中国证监会实施行政许可应当自受理申请之日起20个工作日内作出行政许可决定。20个工作日内不能作出行政许可决定的，经中国证监会负责人批准，可以延长10个工作日，并由受理部门将延长期限的理由告知申请人。但是，法律、行政法规另有规定的，从其规定。"},{"i":35,"n":"第三十五条","txt":"派出机构进行初步审查，中国证监会进行复审并作出决定的行政许可，派出机构应当自其受理行政许可申请之日起20个工作日内审查完毕并向中国证监会报送初步审查意见和全部申请材料。中国证监会应当自接收前述材料之日起20个工作日内作出行政许可决定。但是，法律、行政法规另有规定的，从其规定。"},{"i":36,"n":"第三十六条","txt":"需要申请人对申请材料中存在的问题进行说明、解释的，自书面反馈意见发出之日起到接收申请人书面回复意见的时间，不计算在本章规定的期限内。"},{"i":37,"n":"第三十七条","txt":"需要对行政许可申请进行实地核查或者对有关举报材料进行核查的，自作出核查决定之日起到核查结束的时间，不计算在本章规定的期限内。"},{"i":38,"n":"第三十八条","txt":"依法需要专家评审的行政许可，自书面通知专家参加评审会议之日起到评审会议结束所需的时间，不计算在本章规定的期限内。受理部门应当将专家评审会议所需时间在受理通知书中注明。"},{"i":39,"n":"第三十九条","txt":"依照本规定中止审查行政许可申请的，自书面通知中止审查之日起至书面通知恢复审查之日止的时间，不计算在本章规定的期限内。"},{"i":40,"n":"第四十条","txt":"作出准予或者不予行政许可的决定，应当自作出决定之日起10个工作日内向申请人送达本规定第二十五条规定的行政许可证件或者不予行政许可的书面决定。"},{"i":41,"n":"第四十一条","txt":"在行政许可受理、审查环节出具的申请材料接收凭证，送达的补正通知、受理通知、不予受理通知、书面反馈意见等行政许可文件，应当加盖中国证监会行政许可专用章。 由派出机构进行初步审查的行政许可，派出机构在受理环节出具的有关行政许可文件应使用加盖中国证监会行政许可专用章的函件。 在行政许可决定环节送达的中止审查通知、恢复审查通知、终止审查通知、本规定第二十五条规定的行政许可证件以及不予行政许可书面决定等，应当加盖中国证监会印章。"},{"i":42,"n":"第四十二条","txt":"补正通知、受理通知、不予受理通知、书面反馈意见、中止审查通知、恢复审查通知、终止审查通知、本规定第二十五条规定的行政许可证件、不予行政许可书面决定等行政许可文件，由受理部门按照申请人选定的联系方式和送达方式统一告知、送达申请人，受理部门应当对送达的情况进行记录并存档。 依据本规定第三十条、第三十一条作出的行政许可书面决定，还应当同时抄送有关派出机构。"},{"i":43,"n":"第四十三条","txt":"行政许可文件可以通过邮寄、申请人自行领取、申请人委托他人领取、公告等方式送达申请人。"},{"i":44,"n":"第四十四条","txt":"申请人要求邮寄送达行政许可文件的，受理部门应当采用挂号信或者特快专递的方式送达，并应当附送达回证，在挂号信或者特快专递的封面写明行政许可文件的名称。受理部门应当及时向邮政部门索要证明申请人签收的邮政部门回执。"},{"i":45,"n":"第四十五条","txt":"申请人自行领取行政许可文件的，受理部门应当要求申请人出示单位介绍信、身份证等身份证明文件并予以签收。申请人委托他人领取的，受理部门应当要求受托人出示申请人的授权委托书、受托人的身份证明文件并予以签收。受理部门应当留存申请人、申请人的受托人的身份证明文件复印件。"},{"i":46,"n":"第四十六条","txt":"申请人在接到领取通知5个工作日内不领取行政许可文件且受理部门无法通过邮寄等方式送达的，可以公告送达。自公告之日起，经过60日，即视为送达。"},{"i":47,"n":"第四十七条","txt":"行政许可的事项、依据、条件、数量、程序、期限以及需要申请人提交的全部申请材料的目录和申请书示范文本等应当进行公示，以方便申请人查阅。 依法应当举行国家考试，赋予公民从事有关证券期货业务特定资格的，应当事先公示资格考试的报名条件、报考办法、考试科目以及考试大纲。"},{"i":48,"n":"第四十八条","txt":"中国证监会采取下列方式进行公示： （一）在中国证监会互联网站上公布； （二）印制行政许可手册，并放置在办公场所； （三）在办公场所张贴； （四）其他有效便捷的公示方式。"},{"i":49,"n":"第四十九条","txt":"申请人要求对公示内容予以说明、解释的，审查部门予以说明、解释。"},{"i":50,"n":"第五十条","txt":"作出准予或者不予行政许可决定的，应当自作出决定之日起20个工作日内在中国证监会互联网站上予以公布；但涉及国家秘密、商业秘密、个人隐私的除外。 中国证监会定期出版公告，收录中国证监会及其派出机构作出的准予或者不予行政许可决定。"},{"i":51,"n":"第五十一条","txt":"法律、行政法规对有关行政许可实施程序另有规定的，从其规定。 本规定有原则规定，中国证监会规章及规范性文件有具体程序规定的，依照具体程序规定执行。 本规定第三章、第四章未作出规定的其他程序，适用第二章的规定。"},{"i":52,"n":"第五十二条","txt":"中国证监会受理部门、审查部门、派出机构及其工作人员在实施行政许可活动中违反本规定的，依照有关行政许可执法监督的规定进行处理。"},{"i":53,"n":"第五十三条","txt":"本规定自2010年2月1日起施行。《中国证券监督管理委员会行政许可实施程序规定（试行）》（证监发〔2004〕62号）同时废止。"}],"zhongguozhengquanjianduguanliweiyuanhuixianzhizhene78724":[{"i":1,"n":"第一条","txt":"为维护证券市场正常秩序，保护投资者合法权益，有效打击证券违法行为，依据《中华人民共和国证券法》第一百七十条第（七）项，制订本办法。"},{"i":2,"n":"第二条","txt":"限制证券买卖是指中国证券监督管理委员会（以下简称中国证监会）在调查操纵证券市场、内幕交易等重大证券违法行为时，对被调查事件当事人受限账户的证券买卖行为采取的限制措施。 限制证券买卖措施由中国证监会调查部门（以下简称调查部门）具体实施。"},{"i":3,"n":"第三条","txt":"受限账户包括被调查事件当事人及其实际控制的资金账户、证券账户和与当事人有关的其他账户。 与当事人有关的其他账户包括： （一）有资金往来的； （二）资金存取人为相同人员或机构的； （三）交易代理人为相同人员或机构的； （四）有转托管或交叉指定关系的； （五）有抵押关系的； （六）受同一监管协议控制的； （七）下挂同一个或多个股东账户的； （八）属同一控制人控制的； （九）调查部门通过调查认定的其他情况。"},{"i":4,"n":"第四条","txt":"限制证券买卖措施包括： （一）不得买入指定交易品种，但允许卖出； （二）不得卖出指定交易品种，但允许买入； （三）不得买入和卖出指定交易品种； （四）不得办理转托管或撤销指定交易； （五）调查部门认为应采取的其他限制措施。"},{"i":5,"n":"第五条","txt":"调查部门限制证券买卖的时间不得超过三个月。案情复杂的，经批准可延长三个月。"},{"i":6,"n":"第六条","txt":"调查部门实施本措施，应当制作《限制／解除限制证券买卖申请书》，经法律部门审核，报中国证监会主要负责人或者其授权的其他负责人批准。"},{"i":7,"n":"第七条","txt":"《限制／解除限制证券买卖申请书》应当载明以下事项： （一）案由； （二）受限账户的基本情况； （三）采取限制／解除限制措施的原因； （四）采取限制／解除限制措施的法律依据； （五）限制措施的主要内容，包括受限账户名称、代码、限制品种、限制方式和限制期限。 同时，应当附带下列材料： （一）证明调查部门正在对被调查事件当事人的证券违法行为进行调查的材料； （二）证明受限账户基本情况的材料； （三）证明受限账户符合本办法第三条规定的材料； （四）调查部门认为受限账户符合采取限制／解除限制措施的原因的证据。 《限制／解除限制证券买卖申请书》应当经调查部门主要负责人签字批准、加盖公章。"},{"i":8,"n":"第八条","txt":"实施限制证券买卖措施，调查部门应当向证券交易所、证券登记结算公司、证券经营机构等协助实施限制证券买卖的机构发出《限制／解除限制证券买卖通知书》。"},{"i":9,"n":"第九条","txt":"《限制／解除限制证券买卖通知书》应当载明以下事项： （一）实施依据； （二）受限账户； （三）限制方式； （四）限制品种； （五）限制期限； （六）协助执行单位。"},{"i":10,"n":"第十条","txt":"协助实施限制证券买卖的机构应当按要求及时、有效地执行限制措施。限制期满，应及时解除。"},{"i":11,"n":"第十一条","txt":"调查部门应将实施限制证券买卖措施的情况通知当事人或托管受限账户的证券经营机构。 当事人有权申请复议。复议期间，限制证券买卖措施不停止执行。"},{"i":12,"n":"第十二条","txt":"限制期限届满前，需解除限制证券买卖措施的，经中国证监会主要负责人或者其授权的其他负责人批准，可予以解除。"},{"i":13,"n":"第十三条","txt":"根据需要，有关部门可对限制证券买卖情况予以公告。"},{"i":14,"n":"第十四条","txt":"协助实施限制证券买卖的机构未按要求及时、有效地执行限制措施，依有关法规追究责任。"},{"i":15,"n":"第十五条","txt":"调查部门未按规定程序实施限制证券买卖措施的，将依法追究责任。"},{"i":16,"n":"第十六条","txt":"本办法自公布之日起施行。"}],"zhongguozhengjianhuiweituoshanghaishenzhenzhengqua4f1dd1":[{"i":1,"n":"第一条","txt":"为了加强证券期货市场稽查执法力量，规范委托调查行为，维护公开、公平、公正的市场秩序，维护投资者特别是中小投资者合法权益，促进资本市场健康发展，根据《中华人民共和国证券法》、《中华人民共和国证券投资基金法》、《中华人民共和国行政处罚法》、《期货交易管理条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中国证监会及其派出机构负责证券期货市场违法案件的调查工作，中国证监会依法委托上海、深圳证券交易所（以下简称交易所）实施部分案件的调查取证。"},{"i":3,"n":"第三条","txt":"中国证监会委托交易所对部分涉嫌欺诈发行、内幕交易、操纵市场、虚假陈述等违法行为，实施调查取证；采用一事一委托的方式，委托交易所对涉嫌重大、新型、跨市场等特定违法行为，实施调查取证。"},{"i":4,"n":"第四条","txt":"交易所在委托的范围内，应当以中国证监会的名义，依照《中华人民共和国证券法》、《中华人民共和国证券投资基金法》、《中华人民共和国行政处罚法》、《期货交易管理条例》等法律、行政法规和中国证监会相关规定实施案件调查；调查终结，将证据等案件材料移交中国证监会稽查执法部门或其指定的派出机构复核后，由中国证监会或其授权的派出机构依照法定程序对调查结果进行审查、作出决定。 交易所受托实施案件调查，有权采取《中华人民共和国证券法》、《中华人民共和国证券投资基金法》、《期货交易管理条例》等法律、行政法规规定的措施，但需要采取查封、冻结、封存等与行政处罚权有关的行政强制措施的，应当报请中国证监会稽查执法部门依法办理。"},{"i":5,"n":"第五条","txt":"交易所应当设立专门的部门从事受托案件调查，其工作人员经培训、考试考核合格，取得中国证监会统一颁发的行政执法证件后，方可上岗从事案件调查工作。"},{"i":6,"n":"第六条","txt":"交易所应当自行完成受委托的案件调查事项，不得将受委托事项再委托给其他组织或者个人。"},{"i":7,"n":"第七条","txt":"中国证监会依法对交易所及其工作人员实施案件调查进行监督和指导，并对委托行为的后果承担法律责任。"},{"i":8,"n":"第八条","txt":"交易所未根据委托实施案件调查，或者超越委托范围、权限、期限实施案件调查的，中国证监会责令改正；情节严重的，撤销委托，并依法对直接负责的主管人员和其他直接责任人员给予行政处分。 交易所的工作人员执行案件调查任务，滥用职权、徇私舞弊、玩忽职守、泄露秘密，或者有违反法律、行政法规、中国证监会规定的其他情形，造成严重后果的，依法给予处分。 交易所或者其工作人员在受托实施案件调查时，因违法违规行为侵害被调查单位和个人的合法权益而造成损害的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":9,"n":"第九条","txt":"本规定自2015年1月9日起施行。"}],"zhongguozhengjianhuipaichujigoujianguanzhizeguidin207bb3":[{"i":1,"n":"第一条","txt":"为了明确中国证券监督管理委员会派出机构（以下简称派出机构）监管职责，完善证券期货监管，根据《中华人民共和国证券法》、《中华人民共和国证券投资基金法》、《中华人民共和国期货和衍生品法》、《期货交易管理条例》、《证券公司监督管理条例》、《证券公司风险处置条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"派出机构受中国证券监督管理委员会（以下简称中国证监会）垂直领导，依法以自己的名义履行监管职责。"},{"i":3,"n":"第三条","txt":"派出机构负责证券期货市场一线监管工作，按照恪尽职守、敢于监管、精于监管、严格问责的监管精神，切实维护资本市场公开、公平、公正，维护投资者特别是中小投资者合法权益，防范和依法处置辖区市场风险，促进辖区资本市场稳定健康发展。"},{"i":4,"n":"第四条","txt":"派出机构监管职责的确立和履行，遵循职权法定、依法授权、权责统一、公开透明、公平公正的原则。 派出机构履行的监管职责，除法律、行政法规明确规定外，由中国证监会规章授权。 监管职责事项涉及中国证监会职能部门、派出机构、证券期货交易场所、证券登记结算机构、行业协会等的协调配合，需要做出具体安排的，由中国证监会制定工作规程。"},{"i":5,"n":"第五条","txt":"派出机构按照规定履行下列监管职责： （一）对辖区有关市场主体实施日常监管； （二）防范和处置辖区有关市场风险； （三）对证券期货违法违规行为实施调查、作出行政处罚； （四）依法依规整治非法证券期货活动； （五）证券期货投资者教育和保护； （六）法律、行政法规规定和中国证监会授权的其他职责。"},{"i":6,"n":"第六条","txt":"派出机构在其职责范围内，按照中国证监会规定建立健全与证券期货交易场所、证券登记结算机构、行业协会等自律组织、相关会管单位及其他派出机构之间的信息共享和监管合作机制。"},{"i":7,"n":"第七条","txt":"派出机构应当与辖区地方人民政府相关部门、其他金融监管机构的派出机构建立健全监管协作机制，构建综合监管体系，优化监管执法环境，促进辖区资本市场规范运行和健康发展，协同做好区域内金融风险防范和处置工作。"},{"i":8,"n":"第八条","txt":"派出机构负责根据法律、行政法规规定以及中国证监会的授权实施行政许可事项。 派出机构进行初步审查、中国证监会复审并作出决定的行政许可，由派出机构按照规定受理，出具初步审查意见。 中国证监会相关职能部门办理行政许可，需要派出机构检查、核查相关事项或者出具监管意见的，派出机构应当提供协助。"},{"i":9,"n":"第九条","txt":"派出机构负责对下列市场主体实施检查： （一）证券发行人、上市公司、非上市公众公司及其控股股东、实际控制人、收购人等信息披露义务人； （二）证券公司、公募基金管理人、期货公司及其子公司、分支机构，以及其控股股东、实际控制人； （三）公司债券受托管理人、公募基金托管人、客户交易结算资金存管银行等机构； （四）公募基金销售、销售支付、份额登记、估值、投资顾问、评价等服务机构； （五）私募基金管理人、私募基金托管人及其他相关私募基金服务机构； （六）证券期货投资咨询机构及其分支机构； （七）从事证券期货业务的会计师事务所、资产评估机构、资信评级机构、律师事务所及其分支机构； （八）从事证券期货业务的财务顾问机构； （九）证券期货业信息技术系统服务机构； （十）境外证券类机构驻华代表机构； （十一）法律、行政法规和中国证监会规定的其他市场主体。"},{"i":10,"n":"第十条","txt":"检查的事项可以包括市场主体的信息披露、治理情况、内部控制、经营规范、执业活动等，具体检查事项由派出机构依照法律、行政法规和中国证监会规定予以确定。 市场主体取得行政许可或者按照规定进行备案，依法应当持续符合法定条件的，派出机构按规定对其持续符合法定条件的情况进行检查。"},{"i":11,"n":"第十一条","txt":"派出机构根据中国证监会制定的有关检查办法和规程，结合辖区实际情况，制定具体检查方案，对本规定第九条所列市场主体实施检查。"},{"i":12,"n":"第十二条","txt":"派出机构负责按照规定接收第九条所列市场主体依法报送的业务、财务等备案、报告材料，进行审阅分析。"},{"i":13,"n":"第十三条","txt":"派出机构实施检查或者其他日常监管活动，发现有违反法律、行政法规和规章规定情形的，或者发现重大风险和问题的，应当依法采取监管措施、进行立案查处或者移送司法机关及其他相关部门；没有处理权限的，应当及时报告中国证监会或者按照规定转送其他职能部门、单位。"},{"i":14,"n":"第十四条","txt":"派出机构应当根据市场风险防范的需要，结合辖区实际情况，按照规定以风险和问题为导向开展市场信息的搜集和分析工作，加强对市场的动态监测监控，督促市场主体提高防范和化解风险的能力。"},{"i":15,"n":"第十五条","txt":"派出机构负责按照规定对证券公司、公募基金管理人、期货公司的风险指标实施监管。 派出机构根据审慎监管原则，要求证券公司、公募基金管理人、期货公司按照规定编制并报送风险监管报表。"},{"i":16,"n":"第十六条","txt":"证券公司、公募基金管理人、期货公司的风险管理指标达到预警标准的，或者不符合规定标准的，派出机构按照规定采取相关措施。"},{"i":17,"n":"第十七条","txt":"派出机构负责督促辖区证券公司、公募基金管理人、期货公司、证券期货服务机构等落实行业信息安全管理规定、技术标准，及时、完整、准确地向监管部门报送规定的数据，开展信息安全应急演练。 派出机构负责对信息安全应急演练情况进行核查，并按照规定调查处理信息安全事件。"},{"i":18,"n":"第十八条","txt":"派出机构负责对中国证券投资者保护基金公司、中国期货市场监控中心、有关行业协会等机构发出的相关预警信息所涉事宜进行核查；发现问题的，及时采取相应的措施，督促有关市场主体整改，保障客户交易结算资金、客户保证金的安全。"},{"i":19,"n":"第十九条","txt":"证券公司、公募基金管理人、期货公司违法经营或者出现重大风险，严重危害证券市场秩序、损害投资者利益的，派出机构可以依法对该机构及其直接负责的董事、监事、高级管理人员、其他直接责任人员采取相关措施。 派出机构负责与地方人民政府相关部门建立证券公司、公募基金管理人、期货公司风险处置的协作机制。"},{"i":20,"n":"第二十条","txt":"派出机构负责持续跟踪了解可能被强制退市的上市公司情况，按照规定制定上市公司风险应急处置预案。 派出机构负责与证券交易场所、地方人民政府相关部门建立信息通报、共享机制，对于可能被强制退市的上市公司，应当提前将有关情况报告地方人民政府。 派出机构负责配合地方人民政府相关部门对辖区上市公司实施托管，处置有关上市公司风险，建立健全上市公司退市工作协调机制。"},{"i":21,"n":"第二十一条","txt":"派出机构负责协助、配合地方人民政府相关部门开展非上市公众公司风险处置工作。"},{"i":22,"n":"第二十二条","txt":"派出机构按照规定负责公司债券违约事件的处置工作。"},{"i":23,"n":"第二十三条","txt":"派出机构负责配合地方人民政府相关部门开展辖区各类交易场所清理整顿工作，推动建立健全相关交易场所长效管理机制，做好相关协调、指导、监督工作，向中国证监会报送辖区涉及清理整顿工作的政策措施、重大风险等，推动辖区清理整顿各类交易场所工作有序进行。 派出机构负责与地方人民政府相关部门建立区域性股权市场监管协作机制，与其互通互报与区域性股权市场有关的信息，对地方人民政府相关部门开展区域性股权市场监管工作进行业务指导、协调和监督，对可能出现的金融风险进行预警提示和处置督导。"},{"i":24,"n":"第二十四条","txt":"派出机构以风险、问题为导向加强对私募基金管理人的风险监测，负责与地方人民政府相关部门建立私募基金管理人风险处置的协作机制，与地方人民政府相关部门共同组织落实私募基金风险处置各项具体工作。"},{"i":25,"n":"第二十五条","txt":"派出机构负责完善和强化外部协作机制，支持地方人民政府在有关非法证券期货活动案件查处和善后处理中发挥主导作用。 地方人民政府相关部门开展打击非法证券期货活动需要协助、配合的，派出机构应当协助、配合。派出机构应当按照规定及时移送发现的案件线索，并根据公安、司法机关等的请求，出具有关非法证券期货活动案件性质认定意见或者提供政策解释。 派出机构负责对辖区媒体有关非法证券期货活动信息收集、整理，并及时协调处理。"},{"i":26,"n":"第二十六条","txt":"派出机构负责对辖区内证券期货违法违规案件以及中国证监会相关职能部门交办的案件或者事项进行调查。 前款所称中国证监会相关职能部门交办的案件或者事项，包括中国证监会相关职能部门交办的境外机构请求协助调查的案件或事项。"},{"i":27,"n":"第二十七条","txt":"派出机构负责办理中国证监会稽查总队、中国证监会证券监管专员办事处以及其他派出机构等请求协助调查的事项。"},{"i":28,"n":"第二十八条","txt":"对达到刑事案件立案追诉标准的案件，派出机构应当按照规定自行或者报中国证监会向公安机关履行移送程序。"},{"i":29,"n":"第二十九条","txt":"案件调查过程中，依法采取冻结、查封、限制被调查事件当事人证券买卖等强制措施的，派出机构按照规定负责实施。"},{"i":30,"n":"第三十条","txt":"派出机构负责本单位立案调查的证券期货违法违规案件的审理工作，依法对证券期货违法违规当事人实施行政处罚。但是，按照规定由其他派出机构或者中国证监会相关职能部门负责审理的除外。 派出机构可以按照规定审理中国证监会交办的其他派出机构立案调查的案件以及中国证监会相关职能部门负责调查的案件。"},{"i":31,"n":"第三十一条","txt":"派出机构对有关案件作出行政处罚决定的，由该派出机构负责行政处罚执行工作，按规定送达法律文书，督促被处罚对象履行行政处罚决定，依法申请并配合人民法院做好行政处罚强制执行工作。"},{"i":32,"n":"第三十二条","txt":"派出机构负责按照规定做好中国证监会、其他派出机构所委托的行政处罚案件法律文书送达、处罚执行等相关工作。"},{"i":33,"n":"第三十三条","txt":"派出机构负责督促辖区证券期货经营机构落实投资者适当性管理制度。 派出机构应当宣传和推动辖区市场主体完善基础设施和各项制度，优化投资回报机制，畅通与投资者沟通渠道，保障中小投资者的知情权，便利中小投资者行使参与权和监督权。"},{"i":34,"n":"第三十四条","txt":"派出机构负责在辖区组织开展投资者教育活动，督促、引导辖区上市公司、非上市公众公司、证券期货经营机构等市场主体开展投资者教育工作。 派出机构负责在中国证监会统一部署下，联合地方人民政府相关部门、教育机构、新闻媒体等单位，推动将投资者教育纳入国民教育体系，做好资本市场知识普及工作。"},{"i":35,"n":"第三十五条","txt":"派出机构负责建立常态化投资者意见征求机制，按照规定组织或配合开展辖区证券期货投资者调查和权益评估评价，及时了解、分析投资者状况和政策制度的实施效果。"},{"i":36,"n":"第三十六条","txt":"派出机构负责建立辖区中小投资者合法权益保障检查制度，按照本规定第二章的要求组织或配合开展投资者保护专项检查和日常检查。"},{"i":37,"n":"第三十七条","txt":"派出机构负责建立健全投诉处理登记备案管理制度，督促有关辖区市场主体落实投资者投诉处理首要责任。 派出机构负责按照中国证监会的统一部署，支持辖区自律组织等发挥纠纷调解作用，并与辖区司法机关、仲裁、调解等组织加强联系，推动建立完善多元化纠纷解决机制。"},{"i":38,"n":"第三十八条","txt":"派出机构负责支持、配合资本市场全面深化改革以及创新业务试点工作，开展辖区资本市场深化改革和创新业务研究。"},{"i":39,"n":"第三十九条","txt":"派出机构负责按照规定开展辖区证券期货市场统计调查工作。"},{"i":40,"n":"第四十条","txt":"派出机构负责按照资本市场诚信建设统一规划部署，做好辖区资本市场诚信信息管理、诚信激励约束、失信联合惩戒、诚信宣传教育等诚信建设工作。"},{"i":41,"n":"第四十一条","txt":"派出机构负责按照规定做好辖区内信访、举报事项处理工作。"},{"i":42,"n":"第四十二条","txt":"派出机构负责依法主动公开或者依申请公开有关监管信息。"},{"i":43,"n":"第四十三条","txt":"派出机构负责组织开展以证券期货法律、行政法规和规章、规范性文件为重点的法制宣传活动。"},{"i":44,"n":"第四十四条","txt":"派出机构负责以本单位为被申请人的行政复议答复工作、以本单位为被告的行政诉讼应诉工作。 派出机构负责协助中国证监会办理辖区内行政复议申请人及第三人的行政复议法律文书送达、执行工作；协助中国证监会做好涉及本单位工作的以中国证监会为被告的行政诉讼案件应诉工作。"},{"i":45,"n":"第四十五条","txt":"派出机构负责向中国证监会报告发生在辖区以及由辖区司法机关、仲裁机构管辖的行政诉讼、证券期货民事赔偿、证券期货犯罪等与证券期货市场相关的重大行政、民事、刑事典型案件。"},{"i":46,"n":"第四十六条","txt":"派出机构负责协助、配合地方人民政府相关部门、其他国务院金融监督管理机构的派出机构，按照规定开展地方金融改革、反洗钱监管及其他相关工作。"},{"i":47,"n":"第四十七条","txt":"派出机构应当在监管职责范围内与辖区司法机关及其他国家机关建立监管协助机制，依法处理涉及辖区司法机关来访、来函等协助执法事项。 派出机构负责与辖区公安机关建立、完善行政执法与刑事司法衔接协作配合机制，按照规定向公安机关通报证券期货违法犯罪线索，商请公安机关配合开展调查工作。 除前两款规定的职责外，派出机构可以对辖区其他行政执法机关、司法机关等提出的与派出机构监管职责有关的证券期货法律问题提供咨询。"},{"i":48,"n":"第四十八条","txt":"派出机构应当建立健全与辖区新闻媒体管理部门的日常监测和协作监管机制，通报证券期货类节目和产品广告有关情况，配合做好参与广播电视证券节目的机构和人员资质审查和证券信息类产品广告的管理工作。 派出机构负责监测本派出机构和辖区市场相关的舆情信息，并视情况开展后续处理。"},{"i":49,"n":"第四十九条","txt":"派出机构依照法律、行政法规对辖区证券期货行业协会等行业自律组织进行指导和监督。"},{"i":50,"n":"第五十条","txt":"派出机构及有关责任人员不履行或者不正确履行职责，有下列情形之一，造成严重后果或者恶劣影响的，应当予以问责： （一）在重大原则问题上未能同党中央保持一致，贯彻落实党的路线方针政策和执行党中央重大决策部署不力，落实中国证监会党委工作部署及重点任务安排不力； （二）该发现的重大风险问题没有发现，发现重大风险问题不报告不处置，风险应对不及时，风险处置措施失当； （三）履行管理、监督职责不力，监管政策制定不审慎、市场准入把关不严、日常监管不尽职； （四）其他按照规定应当问责的失职失责情形。 派出机构及有关责任人员有前款规定情形之一的，中国证监会相关职能部门应当提出开展问责的建议，开展问责调查，并提出处理建议。中国证监会根据调查情况，按照管理权限作出问责决定。 问责对象涉嫌职务违法或者职务犯罪的，依法移送监察机关处理。"},{"i":51,"n":"第五十一条","txt":"本规定所称派出机构，是指中国证监会派驻各省、自治区、直辖市和计划单列市监管局。 中国证监会证券监管专员办事处的职责，另行制定。中国证监会证券监管专员办事处不履行或者不正确履行职责，应当予以问责的，参照本规定第五十条规定执行。"},{"i":52,"n":"第五十二条","txt":"本规定所称证券期货经营机构，包括证券公司、公募基金管理人、期货公司及其子公司、分支机构，私募基金管理人、证券期货投资咨询机构以及其他经营证券期货相关业务的机构。"},{"i":53,"n":"第五十三条","txt":"本规定自2015年12月1日起施行。中国证监会《关于印发〈派出机构监管工作职责〉的通知》（证监发〔2003〕86号）同时废止。 pt;\">决策部署不力，落实中国证监会党委工作部署及重点任务安排不力； （二）该发现的重大风险问题没有发现，发现重大风险问题不报告不处置，风险应对不及时，风险处置措施失当； （三）履行管理、监督职责不力，监管政策制定不审慎、市场准入把关不严、日常监管不尽职； （四）其他按照规定应当问责的失职失责情形。 派出机构及有关责任人员有前款规定情形之一的，中国证监会相关职能部门应当提出开展问责的建议，开展问责调查，并提出处理建议。中国证监会根据调查情况，按照管理权限作出问责决定。 问责对象涉嫌职务违法或者职务犯罪的，依法移送监察机关处理。"},{"i":54,"n":"第五十一条","txt":"本规定所称派出机构，是指中国证监会派驻各省、自治区、直辖市和计划单列市监管局。 中国证监会证券监管专员办事处的职责，另行制定。中国证监会证券监管专员办事处不履行或者不正确履行职责，应当予以问责的，参照本规定第五十条规定执行。"},{"i":55,"n":"第五十二条","txt":"本规定所称证券期货经营机构，包括证券公司、公募基金管理人、期货公司及其子公司、分支机构，私募基金管理人、证券期货投资咨询机构以及其他经营证券期货相关业务的机构。"},{"i":56,"n":"第五十三条","txt":"本规定自2015年12月1日起施行。中国证监会《关于印发〈派出机构监管工作职责〉的通知》（证监发〔2003〕86号）同时废止。"}],"youxiangushidianguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范优先股发行和交易行为，保护投资者合法权益，根据《公司法》、《证券法》、《国务院关于开展优先股试点的指导意见》及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称优先股是指依照《公司法》，在一般规定的普通种类股份之外，另行规定的其他种类股份，其股份持有人优先于普通股股东分配公司利润和剩余财产，但参与公司决策管理等权利受到限制。"},{"i":3,"n":"第三条","txt":"上市公司可以发行优先股，非上市公众公司可以非公开发行优先股。"},{"i":4,"n":"第四条","txt":"优先股试点应当符合《公司法》、《证券法》、《国务院关于开展优先股试点的指导意见》和本办法的相关规定，并遵循公开、公平、公正的原则，禁止欺诈、内幕交易和操纵市场的行为。"},{"i":5,"n":"第五条","txt":"证券公司及其他证券服务机构参与优先股试点，应当遵守法律法规及中国证券监督管理委员会（以下简称中国证监会）相关规定，遵循行业公认的业务标准和行为规范，诚实守信、勤勉尽责。"},{"i":6,"n":"第六条","txt":"试点期间不允许发行在股息分配和剩余财产分配上具有不同优先顺序的优先股，但允许发行在其他条款上具有不同设置的优先股。 同一公司既发行强制分红优先股，又发行不含强制分红条款优先股的，不属于发行在股息分配上具有不同优先顺序的优先股。"},{"i":7,"n":"第七条","txt":"相同条款的优先股应当具有同等权利。同次发行的相同条款优先股，每股发行的条件、价格和票面股息率应当相同；任何单位或者个人认购的股份，每股应当支付相同价额。"},{"i":8,"n":"第八条","txt":"发行优先股的公司除按《国务院关于开展优先股试点的指导意见》制定章程有关条款外，还应当按本办法在章程中明确优先股股东的有关权利和义务。"},{"i":9,"n":"第九条","txt":"优先股股东按照约定的股息率分配股息后，有权同普通股股东一起参加剩余利润分配的，公司章程应明确优先股股东参与剩余利润分配的比例、条件等事项。"},{"i":10,"n":"第十条","txt":"出现以下情况之一的，公司召开股东大会会议应通知优先股股东，并遵循《公司法》及公司章程通知普通股股东的规定程序。优先股股东有权出席股东大会会议，就以下事项与普通股股东分类表决，其所持每一优先股有一表决权，但公司持有的本公司优先股没有表决权： （一）修改公司章程中与优先股相关的内容； （二）一次或累计减少公司注册资本超过百分之十； （三）公司合并、分立、解散或变更公司形式； （四）发行优先股； （五）公司章程规定的其他情形。 上述事项的决议，除须经出席会议的普通股股东（含表决权恢复的优先股股东）所持表决权的三分之二以上通过之外，还须经出席会议的优先股股东（不含表决权恢复的优先股股东）所持表决权的三分之二以上通过。"},{"i":11,"n":"第十一条","txt":"公司股东大会可授权公司董事会按公司章程的约定向优先股支付股息。公司累计三个会计年度或连续两个会计年度未按约定支付优先股股息的，股东大会批准当年不按约定分配利润的方案次日起，优先股股东有权出席股东大会与普通股股东共同表决，每股优先股股份享有公司章程规定的一定比例表决权。 对于股息可累积到下一会计年度的优先股，表决权恢复直至公司全额支付所欠股息。对于股息不可累积的优先股，表决权恢复直至公司全额支付当年股息。公司章程可规定优先股表决权恢复的其他情形。"},{"i":12,"n":"第十二条","txt":"优先股股东有权查阅公司章程、股东名册、公司债券存根、股东大会会议记录、董事会会议决议、监事会会议决议、财务会计报告。"},{"i":13,"n":"第十三条","txt":"发行人回购优先股包括发行人要求赎回优先股和投资者要求回售优先股两种情况，并应在公司章程和招股文件中规定其具体条件。发行人要求赎回优先股的，必须完全支付所欠股息，但商业银行发行优先股补充资本的除外。优先股回购后相应减记发行在外的优先股股份总数。"},{"i":14,"n":"第十四条","txt":"公司董事、监事、高级管理人员应当向公司申报所持有的本公司优先股及其变动情况，在任职期间每年转让的股份不得超过其所持本公司优先股股份总数的百分之二十五。公司章程可以对公司董事、监事、高级管理人员转让其所持有的本公司优先股股份作出其他限制性规定。"},{"i":15,"n":"第十五条","txt":"除《国务院关于开展优先股试点的指导意见》规定的事项外，计算股东人数和持股比例时应分别计算普通股和优先股。"},{"i":16,"n":"第十六条","txt":"公司章程中规定优先股采用固定股息率的，可以在优先股存续期内采取相同的固定股息率，或明确每年的固定股息率，各年度的股息率可以不同；公司章程中规定优先股采用浮动股息率的，应当明确优先股存续期内票面股息率的计算方法。"},{"i":17,"n":"第十七条","txt":"上市公司应当与控股股东或实际控制人的人员、资产、财务分开，机构、业务独立。"},{"i":18,"n":"第十八条","txt":"上市公司内部控制制度健全，能够有效保证公司运行效率、合法合规和财务报告的可靠性，内部控制的有效性应当不存在重大缺陷。"},{"i":19,"n":"第十九条","txt":"上市公司发行优先股，最近三个会计年度实现的年均可分配利润应当不少于优先股一年的股息。"},{"i":20,"n":"第二十条","txt":"上市公司最近三年现金分红情况应当符合公司章程及中国证监会的有关监管规定。"},{"i":21,"n":"第二十一条","txt":"上市公司报告期不存在重大会计违规事项。公开发行优先股，最近三年财务报表被注册会计师出具的审计报告应当为标准审计报告或带强调事项段的无保留意见的审计报告；非公开发行优先股，最近一年财务报表被注册会计师出具的审计报告为非标准审计报告的，所涉及事项对公司无重大不利影响或者在发行前重大不利影响已经消除。"},{"i":22,"n":"第二十二条","txt":"上市公司发行优先股募集资金应有明确用途，与公司业务范围、经营规模相匹配，募集资金用途符合国家产业政策和有关环境保护、土地管理等法律和行政法规的规定。 除金融类企业外，本次募集资金使用项目不得为持有交易性金融资产和可供出售的金融资产、借予他人等财务性投资，不得直接或间接投资于以买卖有价证券为主要业务的公司。"},{"i":23,"n":"第二十三条","txt":"上市公司已发行的优先股不得超过公司普通股股份总数的百分之五十，且筹资金额不得超过发行前净资产的百分之五十，已回购、转换的优先股不纳入计算。"},{"i":24,"n":"第二十四条","txt":"上市公司同一次发行的优先股，条款应当相同。每次优先股发行完毕前，不得再次发行优先股。"},{"i":25,"n":"第二十五条","txt":"上市公司存在下列情形之一的，不得发行优先股： （一）本次发行申请文件有虚假记载、误导性陈述或重大遗漏； （二）最近十二个月内受到过中国证监会的行政处罚； （三）因涉嫌犯罪正被司法机关立案侦查或涉嫌违法违规正被中国证监会立案调查； （四）上市公司的权益被控股股东或实际控制人严重损害且尚未消除； （五）上市公司及其附属公司违规对外提供担保且尚未解除； （六）存在可能严重影响公司持续经营的担保、诉讼、仲裁、市场重大质疑或其他重大事项； （七）其董事和高级管理人员不符合法律、行政法规和规章规定的任职资格； （八）严重损害投资者合法权益和社会公共利益的其他情形。"},{"i":26,"n":"第二十六条","txt":"上市公司公开发行优先股，应当符合以下情形之一： （一）其普通股为上证50指数成份股； （二）以公开发行优先股作为支付手段收购或吸收合并其他上市公司； （三）以减少注册资本为目的回购普通股的，可以公开发行优先股作为支付手段，或者在回购方案实施完毕后，可公开发行不超过回购减资总额的优先股。 中国证监会核准公开发行优先股后不再符合本条第（一）项情形的，上市公司仍可实施本次发行。"},{"i":27,"n":"第二十七条","txt":"上市公司最近三个会计年度应当连续盈利。扣除非经常性损益后的净利润与扣除前的净利润相比，以孰低者作为计算依据。"},{"i":28,"n":"第二十八条","txt":"上市公司公开发行优先股应当在公司章程中规定以下事项： （一）采取固定股息率； （二）在有可分配税后利润的情况下必须向优先股股东分配股息； （三）未向优先股股东足额派发股息的差额部分应当累积到下一会计年度； （四）优先股股东按照约定的股息率分配股息后，不再同普通股股东一起参加剩余利润分配。 商业银行发行优先股补充资本的，可就第（二）项和第（三）项事项另行约定。"},{"i":29,"n":"第二十九条","txt":"上市公司公开发行优先股的，可以向原股东优先配售。"},{"i":30,"n":"第三十条","txt":"除本办法第二十五条的规定外，上市公司最近三十六个月内因违反工商、税收、土地、环保、海关法律、行政法规或规章，受到行政处罚且情节严重的，不得公开发行优先股。"},{"i":31,"n":"第三十一条","txt":"上市公司公开发行优先股，公司及其控股股东或实际控制人最近十二个月内应当不存在违反向投资者作出的公开承诺的行为。"},{"i":32,"n":"第三十二条","txt":"优先股每股票面金额为一百元。 优先股发行价格和票面股息率应当公允、合理，不得损害股东或其他利益相关方的合法利益，发行价格不得低于优先股票面金额。 公开发行优先股的价格或票面股息率以市场询价或中国证监会认可的其他公开方式确定。非公开发行优先股的票面股息率不得高于最近两个会计年度的年均加权平均净资产收益率。"},{"i":33,"n":"第三十三条","txt":"上市公司不得发行可转换为普通股的优先股。但商业银行可根据商业银行资本监管规定，非公开发行触发事件发生时强制转换为普通股的优先股，并遵守有关规定。"},{"i":34,"n":"第三十四条","txt":"上市公司非公开发行优先股仅向本办法规定的合格投资者发行，每次发行对象不得超过二百人，且相同条款优先股的发行对象累计不得超过二百人。 发行对象为境外战略投资者的，还应当符合国务院相关部门的规定。"},{"i":35,"n":"第三十五条","txt":"上市公司申请发行优先股，董事会应当按照中国证监会有关信息披露规定，公开披露本次优先股发行预案，并依法就以下事项作出决议，提请股东大会批准。 （一）本次优先股的发行方案； （二）非公开发行优先股且发行对象确定的，上市公司与相应发行对象签订的附条件生效的优先股认购合同。认购合同应当载明发行对象拟认购优先股的数量、认购价格或定价原则、票面股息率或其确定原则，以及其他必要条款。认购合同应当约定发行对象不得以竞价方式参与认购，且本次发行一经上市公司董事会、股东大会批准并经中国证监会核准，该合同即应生效； （三）非公开发行优先股且发行对象尚未确定的，决议应包括发行对象的范围和资格、定价原则、发行数量或数量区间。 上市公司的控股股东、实际控制人或其控制的关联人参与认购本次非公开发行优先股的，按照前款第（二）项执行。"},{"i":36,"n":"第三十六条","txt":"上市公司独立董事应当就上市公司本次发行对公司各类股东权益的影响发表专项意见，并与董事会决议一同披露。"},{"i":37,"n":"第三十七条","txt":"上市公司股东大会就发行优先股进行审议，应当就下列事项逐项进行表决： （一）本次发行优先股的种类和数量； （二）发行方式、发行对象及向原股东配售的安排； （三）票面金额、发行价格或其确定原则； （四）优先股股东参与分配利润的方式，包括：票面股息率或其确定原则、股息发放的条件、股息支付方式、股息是否累积、是否可以参与剩余利润分配等； （五）回购条款，包括回购的条件、期间、价格及其确定原则、回购选择权的行使主体等（如有）； （六）募集资金用途； （七）公司与发行对象签订的附条件生效的优先股认购合同（如有）； （八）决议的有效期； （九）公司章程关于优先股股东和普通股股东利润分配、剩余财产分配、优先股表决权恢复等相关政策条款的修订方案； （十）对董事会办理本次发行具体事宜的授权； （十一）其他事项。 上述决议，须经出席会议的普通股股东（含表决权恢复的优先股股东）所持表决权的三分之二以上通过。已"},{"i":38,"n":"第三十八条","txt":"上市公司就发行优先股事项召开股东大会，应当提供网络投票，还可以通过中国证监会认可的其他方式为股东参加股东大会提供便利。"},{"i":39,"n":"第三十九条","txt":"上市公司申请发行优先股应当由保荐人保荐并向中国证监会申报，其申请、审核、核准、发行等相关程序参照《上市公司证券发行管理办法》和《证券发行与承销管理办法》的规定。发审委会议按照《中国证券监督管理委员会发行审核委员会办法》规定的特别程序，审核发行申请。"},{"i":40,"n":"第四十条","txt":"上市公司发行优先股，可以申请一次核准，分次发行，不同次发行的优先股除票面股息率外，其他条款应当相同。自中国证监会核准发行之日起，公司应在六个月内实施首次发行，剩余数量应当在二十四个月内发行完毕。超过核准文件时限的，须申请中国证监会重新核准。首次发行数量应当不少于总发行数量的百分之五十，剩余各次发行的数量由公司自行确定，每次发行完毕后五个工作日内报中国证监会备案。"},{"i":41,"n":"第四十一条","txt":"非上市公众公司非公开发行优先股应符合下列条件： （一）合法规范经营； （二）公司治理机制健全； （三）依法履行信息披露义务。"},{"i":42,"n":"第四十二条","txt":"非上市公众公司非公开发行优先股应当遵守本办法第二十三条、第二十四条、第二十五条、第三十二条、第三十三条的规定。"},{"i":43,"n":"第四十三条","txt":"非上市公众公司非公开发行优先股仅向本办法规定的合格投资者发行，每次发行对象不得超过二百人，且相同条款优先股的发行对象累计不得超过二百人。"},{"i":44,"n":"第四十四条","txt":"非上市公众公司拟发行优先股的，董事会应依法就具体方案、本次发行对公司各类股东权益的影响、发行优先股的目的、募集资金的用途及其他必须明确的事项作出决议，并提请股东大会批准。 董事会决议确定具体发行对象的，董事会决议应当确定具体的发行对象名称及其认购价格或定价原则、认购数量或数量区间等；同时应在召开董事会前与相应发行对象签订附条件生效的股份认购合同。董事会决议未确定具体发行对象的，董事会决议应当明确发行对象的范围和资格、定价原则等。"},{"i":45,"n":"第四十五条","txt":"非上市公众公司股东大会就发行优先股进行审议，表决事项参照本办法第三十七条执行。发行优先股决议，须经出席会议的普通股股东（含表决权恢复的优先股股东）所持表决权的三分之二以上通过。已发行优先股的，还须经出席会议的优先股股东（不含表决权恢复的优先股股东）所持表决权的三分之二以上通过。非上市公众公司向公司特定股东及其关联人发行优先股的，股东大会就发行方案进行表决时，关联股东应当回避，公司普通股股东（不含表决权恢复的优先股股东）人数少于二百人的除外。"},{"i":46,"n":"第四十六条","txt":"非上市公众公司发行优先股的申请、审核（豁免）、发行等相关程序应按照《非上市公众公司监督管理办法》等相关规定办理。"},{"i":47,"n":"第四十七条","txt":"优先股发行后可以申请上市交易或转让，不设限售期。 公开发行的优先股可以在证券交易所上市交易。上市公司非公开发行的优先股可以在证券交易所转让，非上市公众公司非公开发行的优先股可以在全国中小企业股份转让系统转让，转让范围仅限合格投资者。交易或转让的具体办法由证券交易所或全国中小企业股份转让系统另行制定。"},{"i":48,"n":"第四十八条","txt":"优先股交易或转让环节的投资者适当性标准应当与发行环节保持一致；非公开发行的相同条款优先股经交易或转让后，投资者不得超过二百人。"},{"i":49,"n":"第四十九条","txt":"中国证券登记结算公司为优先股提供登记、存管、清算、交收等服务。"},{"i":50,"n":"第五十条","txt":"公司应当按照中国证监会有关信息披露规则编制募集优先股说明书或其他信息披露文件，依法履行信息披露义务。上市公司相关信息披露程序和要求参照《上市公司证券发行管理办法》和《上市公司非公开发行股票实施细则》及有关监管指引的规定。非上市公众公司非公开发行优先股的信息披露程序和要求参照《非上市公众公司监督管理办法》及有关监管指引的规定。"},{"i":51,"n":"第五十一条","txt":"发行优先股的公司披露定期报告时，应当以专门章节披露已发行优先股情况、持有公司优先股股份最多的前十名股东的名单和持股数额、优先股股东的利润分配情况、优先股的回购情况、优先股股东表决权恢复及行使情况、优先股会计处理情况及其他与优先股有关的情况，具体内容与格式由中国证监会规定。"},{"i":52,"n":"第五十二条","txt":"发行优先股的上市公司，发生表决权恢复、回购普通股等事项，以及其他可能对其普通股或优先股交易或转让价格产生较大影响事项的，上市公司应当按照《证券法》第八十条以及中国证监会的相关规定，履行临时报告、公告等信息披露义务。"},{"i":53,"n":"第五十三条","txt":"发行优先股的非上市公众公司按照《非上市公众公司监督管理办法》及有关监管指引的规定履行日常信息披露义务。"},{"i":54,"n":"第五十四条","txt":"上市公司可以非公开发行优先股作为支付手段，向公司特定股东回购普通股。上市公司回购普通股的价格应当公允、合理，不得损害股东或其他利益相关方的合法利益。"},{"i":55,"n":"第五十五条","txt":"上市公司以减少注册资本为目的回购普通股公开发行优先股的，以及以非公开发行优先股为支付手段向公司特定股东回购普通股的，除应当符合优先股发行条件和程序，还应符合以下规定： （一）上市公司回购普通股应当由董事会依法作出决议并提交股东大会批准； （二）上市公司股东大会就回购普通股作出的决议，应当包括下列事项：回购普通股的价格区间，回购普通股的数量和比例，回购普通股的期限，决议的有效期，对董事会办理本次回购股份事宜的具体授权，其他相关事项。以发行优先股作为支付手段的，应当包括拟用于支付的优先股总金额以及支付比例；回购方案实施完毕之日起一年内公开发行优先股的，应当包括回购的资金总额以及资金来源； （三）上市公司股东大会就回购普通股作出决议，必须经出席会议的普通股股东（含表决权恢复的优先股股东）所持表决权的三分之二以上通过； （四）上市公司应当在股东大会作出回购普通股决议后的次日公告该决议； （五）"},{"i":56,"n":"第五十六条","txt":"上市公司收购要约适用于被收购公司的所有股东，但可以针对优先股股东和普通股股东提出不同的收购条件。"},{"i":57,"n":"第五十七条","txt":"上市公司可以按照《上市公司重大资产重组管理办法》规定的条件发行优先股购买资产，同时应当遵守本办法第三十三条，以及第三十五条至第三十八条的规定，依法披露有关信息、履行相应程序。"},{"i":58,"n":"第五十八条","txt":"上市公司发行优先股作为支付手段购买资产的，可以同时募集配套资金。"},{"i":59,"n":"第五十九条","txt":"非上市公众公司发行优先股的方案涉及重大资产重组的，应当符合中国证监会有关重大资产重组的规定。"},{"i":60,"n":"第六十条","txt":"公司及其控股股东或实际控制人，公司董事、监事、高级管理人员以及其他直接责任人员，相关市场中介机构及责任人员，以及优先股试点的其他市场参与者违反本办法规定的，依照《公司法》、《证券法》和中国证监会的有关规定处理；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":61,"n":"第六十一条","txt":"上市公司、非上市公众公司违反本办法规定，存在未按规定制定有关章程条款、不按照约定召集股东大会恢复优先股股东表决权等损害优先股股东和中小股东权益等行为的，中国证监会应当责令改正，对上市公司、非上市公众公司和其直接负责的主管人员和其他直接责任人员，可以采取相应的行政监管措施以及警告、三万元以下罚款等行政处罚。"},{"i":62,"n":"第六十二条","txt":"上市公司违反本办法第二十二条第二款规定的，中国证监会可以责令改正，并在三十六个月内不受理该公司的公开发行证券申请。"},{"i":63,"n":"第六十三条","txt":"上市公司、非上市公众公司向本办法规定的合格投资者以外的投资者非公开发行优先股，中国证监会应当责令改正，并可以自确认之日起在三十六个月内不受理该公司的发行优先股申请。"},{"i":64,"n":"第六十四条","txt":"承销机构在承销非公开发行的优先股时，将优先股配售给不符合本办法合格投资者规定的对象的，中国证监会可以责令改正，并在三十六个月内不接受其参与证券承销。"},{"i":65,"n":"第六十五条","txt":"本办法所称合格投资者包括： （一）经有关金融监管部门批准设立的金融机构，包括商业银行、证券公司、基金管理公司、信托公司和保险公司等； （二）上述金融机构面向投资者发行的理财产品，包括但不限于银行理财产品、信托产品、投连险产品、基金产品、证券公司资产管理产品等; （三）实收资本或实收股本总额不低于人民币五百万元的营利法人； （四）实缴出资总额不低于人民币五百万元的合伙企业； （五）合格境外机构投资者（QFII）、人民币合格境外机构投资者（RQFII）、符合国务院相关部门规定的境外战略投资者； （六）除发行人董事、高级管理人员及其配偶以外的，名下各类证券账户、资金账户、资产管理账户的资产总额不低于人民币五百万元的个人投资者； （七）经中国证监会认可的其他合格投资者。"},{"i":66,"n":"第六十六条","txt":"非上市公众公司首次公开发行普通股并同时非公开发行优先股的，其优先股的发行与信息披露应符合本办法中关于上市公司非公开发行优先股的有关规定。"},{"i":67,"n":"第六十七条","txt":"注册在境内的境外上市公司在境外发行优先股，应当符合境外募集股份及上市的有关规定。 注册在境内的境外上市公司在境内发行优先股，参照执行本办法关于非上市公众公司发行优先股的规定，以及《非上市公众公司监督管理办法》等相关规定，其优先股可以在全国中小企业股份转让系统进行转让。"},{"i":68,"n":"第六十八条","txt":"本办法下列用语含义如下： （一）强制分红：公司在有可分配税后利润的情况下必须向优先股股东分配股息； （二）可分配税后利润：发行人股东依法享有的未分配利润； （三）加权平均净资产收益率：按照《公开发行证券的公司信息披露编报规则第9号——净资产收益率和每股收益的计算及披露》计算的加权平均净资产收益率； （四）上证50指数：中证指数有限公司发布的上证50指数。"},{"i":69,"n":"第六十九条","txt":"本办法中计算合格投资者人数时，同一资产管理机构以其管理的两只以上产品认购或受让优先股的，视为一人。"},{"i":70,"n":"第七十条","txt":"本办法自公布之日起施行。"}],"quanguozhongxiaoqiyegufenzhuanrangxitongyouxianzer358112":[{"i":1,"n":"第一条","txt":"为加强对全国中小企业股份转让系统有限责任公司（以下简称全国股份转让系统公司）的管理，明确其职权与责任，维护股票挂牌转让及相关活动的正常秩序，根据《公司法》、《证券法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"全国中小企业股份转让系统（以下简称全国股份转让系统）是经国务院批准设立的全国性证券交易场所。"},{"i":3,"n":"第三条","txt":"股票在全国股份转让系统挂牌的公司（以下简称挂牌公司）为非上市公众公司，股东人数可以超过200人，接受中国证券监督管理委员会（以下简称中国证监会）的统一监督管理。"},{"i":4,"n":"第四条","txt":"全国股份转让系统公司负责组织和监督挂牌公司的股票转让及相关活动，实行自律管理。"},{"i":5,"n":"第五条","txt":"全国股份转让系统公司应当坚持公益优先的原则，维护公开、公平、公正的市场环境，保证全国股份转让系统的正常运行，为全国股份转让系统各参与人提供优质、高效、低成本的金融服务。"},{"i":6,"n":"第六条","txt":"全国股份转让系统的股票挂牌转让及相关活动，必须遵守法律、行政法规和各项规章规定，禁止欺诈、内幕交易、操纵市场等违法违规行为。"},{"i":7,"n":"第七条","txt":"中国证监会依法对全国股份转让系统公司、全国股份转让系统的各项业务活动及各参与人实行统一监督管理，维护全国股份转让系统运行秩序，依法查处违法违规行为。"},{"i":8,"n":"第八条","txt":"全国股份转让系统公司的职能包括： （一）建立、维护和完善股票转让相关技术系统和设施； （二）制定和修改全国股份转让系统业务规则； （三）接受并审查股票挂牌及其他相关业务申请，安排符合条件的公司股票挂牌； （四）组织、监督股票转让及相关活动； （五）对主办券商等全国股份转让系统参与人进行监管； （六）对挂牌公司及其他信息披露义务人进行监管； （七）管理和公布全国股份转让系统相关信息； （八）中国证监会批准的其他职能。"},{"i":9,"n":"第九条","txt":"全国股份转让系统公司应当就股票挂牌、股票转让、主办券商管理、挂牌公司管理、投资者适当性管理等依法制定基本业务规则。 全国股份转让系统公司制定与修改基本业务规则，应当经中国证监会批准。制定与修改其他业务规则，应当报中国证监会备案。"},{"i":10,"n":"第十条","txt":"全国股份转让系统挂牌新的证券品种应当向中国证监会报告，采用新的转让方式应当报中国证监会批准。"},{"i":11,"n":"第十一条","txt":"全国股份转让系统公司应当为组织公平的股票转让提供保障，公布股票转让即时行情。未经全国股份转让系统公司许可，任何单位和个人不得发布、使用或传播股票转让即时行情。"},{"i":12,"n":"第十二条","txt":"全国股份转让系统公司收取的资金和费用应当符合有关主管部门的规定，并优先用于维护和完善相关技术系统和设施。 全国股份转让系统公司应当制定专项财务管理规则，并报中国证监会备案。"},{"i":13,"n":"第十三条","txt":"全国股份转让系统公司应当从其收取的费用中提取一定比例的金额设立风险基金。风险基金提取和使用的具体办法，由中国证监会另行制定。"},{"i":14,"n":"第十四条","txt":"全国股份转让系统的登记结算业务由中国证券登记结算有限责任公司负责。全国股份转让系统公司应当与其签订业务协议，并报中国证监会备案。"},{"i":15,"n":"第十五条","txt":"全国股份转让系统公司应当按照《公司法》等法律、行政法规和中国证监会的规定，制定公司章程，明确股东会、董事会、监事会和经理层之间的职责划分，建立健全内部组织机构，完善公司治理。 全国股份转让系统公司章程的制定和修改，应当经中国证监会批准。"},{"i":16,"n":"第十六条","txt":"全国股份转让系统公司的股东应当具备法律、行政法规和中国证监会规定的资格条件，股东持股比例应当符合中国证监会的有关规定。 全国股份转让系统公司新增股东或原股东转让所持股份的，应当向中国证监会报告。"},{"i":17,"n":"第十七条","txt":"全国股份转让系统公司董事会、监事会的组成及议事规则应当符合有关法律、行政法规和中国证监会的规定，并报中国证监会备案。"},{"i":18,"n":"第十八条","txt":"全国股份转让系统公司董事长、副董事长、监事会主席及高级管理人员由中国证监会提名，任免程序和任期遵守《公司法》和全国股份转让系统公司章程的有关规定。 前款所述高级管理人员的范围，由全国股份转让系统公司章程规定。"},{"i":19,"n":"第十九条","txt":"全国股份转让系统公司应当根据需要设立专门委员会。各专门委员会的组成及议事规则报中国证监会备案。"},{"i":20,"n":"第二十条","txt":"全国股份转让系统实行主办券商制度。在全国股份转让系统从事主办券商业务的证券公司称为主办券商。 主办券商业务包括推荐股份公司股票挂牌，对挂牌公司进行持续督导，代理投资者买卖挂牌公司股票，为股票转让提供做市服务及其他全国股份转让系统公司规定的业务。"},{"i":21,"n":"第二十一条","txt":"全国股份转让系统公司依法对股份公司股票挂牌、定向发行等申请及主办券商推荐文件进行审查，出具审查意见。 全国股份转让系统公司应当与符合条件的股份公司签署挂牌协议，确定双方的权利义务关系。"},{"i":22,"n":"第二十二条","txt":"全国股份转让系统公司应当督促申请股票挂牌的股份公司、挂牌公司及其他信息披露义务人，依法履行信息披露义务，真实、准确、完整、及时地披露信息，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":23,"n":"第二十三条","txt":"挂牌公司应当符合全国股份转让系统持续挂牌条件，不符合持续挂牌条件的，全国股份转让系统公司应当及时作出股票暂停或终止挂牌的决定，及时公告，并报中国证监会备案。"},{"i":24,"n":"第二十四条","txt":"挂牌股票转让可以采取做市方式、协议方式、竞价方式或证监会批准的其他转让方式。"},{"i":25,"n":"第二十五条","txt":"全国股份转让系统实行投资者适当性管理制度。参与股票转让的投资者应当具备一定的证券投资经验和相应的风险识别和承担能力，了解熟悉相关业务规则。"},{"i":26,"n":"第二十六条","txt":"因突发性事件而影响股票转让的正常进行时，全国股份转让系统公司可以采取技术性停牌措施；因不可抗力的突发性事件或者为维护股票转让的正常秩序，可以决定临时停市。 全国股份转让系统公司采取技术性停牌或者决定临时停市，应当及时报告中国证监会。"},{"i":27,"n":"第二十七条","txt":"全国股份转让系统公司应当建立市场监控制度及相应技术系统，配备专门市场监察人员，依法对股票转让实行监控，及时发现、及时制止内幕交易、市场操纵等异常转让行为。 对违反法律法规及业务规则的，全国股份转让系统公司应当及时采取自律监管措施，并视情节轻重或根据监管要求，及时向中国证监会报告。"},{"i":28,"n":"第二十八条","txt":"全国股份转让系统公司应当督促主办券商、律师事务所、会计师事务所等为挂牌转让等相关业务提供服务的证券服务机构和人员，诚实守信、勤勉尽责，严格履行法定职责，遵守法律法规和行业规范，并对出具文件的真实性、准确性、完整性负责。"},{"i":29,"n":"第二十九条","txt":"全国股份转让系统公司发现相关当事人违反法律法规及业务规则的，可以依法采取自律监管措施，并报中国证监会备案。依法应当由中国证监会进行查处的，全国股份转让系统公司应当向中国证监会提出查处建议。"},{"i":30,"n":"第三十条","txt":"全国股份转让系统公司应当向中国证监会报告股东会、董事会、监事会、总经理办公会议和其他重要会议的会议纪要，全国股份转让系统运行情况，全国股份转让系统公司自律监管职责履行情况、日常工作动态以及中国证监会要求报告的其他信息。 全国股份转让系统公司的其他报告义务，比照执行证券交易所管理有关规定。"},{"i":31,"n":"第三十一条","txt":"中国证监会有权要求全国股份转让系统公司对其章程和业务规则进行修改。"},{"i":32,"n":"第三十二条","txt":"中国证监会依法对全国股份转让系统公司进行监管，开展定期、不定期的现场检查，并对其履职和运营情况进行评估和考核。 全国股份转让系统公司及相关人员违反本办法规定，在监管工作中不履行职责，或者不履行本办法规定的有关义务，中国证监会比照证券交易所管理有关规定进行查处。"},{"i":33,"n":"第三十三条","txt":"全国股份转让系统公司为其他证券品种提供挂牌转让服务的，比照本办法执行。"},{"i":34,"n":"第三十四条","txt":"在证券公司代办股份转让系统的原STAQ、NET系统挂牌公司和退市公司及其股份转让相关活动，由全国股份转让系统公司负责监督管理。"},{"i":35,"n":"第三十五条","txt":"本办法公布之日起施行。"}],"gongsizhaiquanfaxingyujiaoyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范公司债券的发行、交易或转让行为，保护投资者的合法权益和社会公共利益，根据《证券法》《公司法》和其他相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，公开发行公司债券并在证券交易所、全国中小企业股份转让系统交易，非公开发行公司债券并在证券交易所、全国中小企业股份转让系统、证券公司柜台转让的，适用本办法。法律法规和中国证券监督管理委员会（以下简称中国证监会）另有规定的，从其规定。本办法所称公司债券，是指公司依照法定程序发行、约定在一定期限还本付息的有价证券。"},{"i":3,"n":"第三条","txt":"公司债券可以公开发行，也可以非公开发行。"},{"i":4,"n":"第四条","txt":"发行人及其他信息披露义务人应当及时、公平地履行披露义务，所披露或者报送的信息必须真实、准确、完整，简明清晰，通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":5,"n":"第五条","txt":"发行人及其控股股东、实际控制人应当诚实守信，发行人的董事、监事、高级管理人员应当勤勉尽责，维护债券持有人享有的法定权利和债券募集说明书约定的权利。 发行人及其控股股东、实际控制人、董事、监事、高级管理人员不得怠于履行偿债义务或者通过财产转移、关联交易等方式逃废债务，蓄意损害债券持有人权益。"},{"i":6,"n":"第六条","txt":"为公司债券发行提供服务的承销机构、受托管理人，以及资信评级机构、会计师事务所、资产评估机构、律师事务所等专业机构和人员应当勤勉尽责，严格遵守执业规范和监管规则，按规定和约定履行义务。 发行人及其控股股东、实际控制人应当全面配合承销机构、受托管理人、证券服务机构的相关工作。"},{"i":7,"n":"第七条","txt":"发行人、承销机构及其相关工作人员在发行定价和配售过程中，不得有违反公平竞争、进行利益输送、直接或间接谋取不正当利益以及其他破坏市场秩序的行为。"},{"i":8,"n":"第八条","txt":"中国证监会对公司债券发行的注册，证券交易所对公司债券发行出具的审核意见，或者中国证券业协会按照本办法对公司债券发行的报备，不表明其对发行人的经营风险、偿债风险、诉讼风险以及公司债券的投资风险或收益等作出判断或者保证。公司债券的投资风险，由投资者自行承担。"},{"i":9,"n":"第九条","txt":"中国证监会依法对公司债券的发行及其交易或转让活动进行监督管理。证券自律组织依照相关规定对公司债券的发行、上市交易或挂牌转让、登记结算、承销、尽职调查、信用评级、受托管理及增信等进行自律管理。 证券自律组织应当制定相关业务规则，明确公司债券发行、承销、报备、上市交易或挂牌转让、信息披露、登记结算、投资者适当性管理、持有人会议及受托管理等具体规定，报中国证监会批准或备案。"},{"i":10,"n":"第十条","txt":"发行公司债券，发行人应当依照《公司法》或者公司章程相关规定对以下事项作出决议： （一）发行债券的金额； （二）发行方式； （三）债券期限； （四）募集资金的用途； （五）其他按照法律法规及公司章程规定需要明确的事项。 发行公司债券，如果对增信机制、偿债保障措施作出安排的，也应当在决议事项中载明。"},{"i":11,"n":"第十一条","txt":"发行公司债券，可以附认股权、可转换成相关股票等条款。上市公司、股票公开转让的非上市公众公司股东可以发行附可交换成上市公司或非上市公众公司股票条款的公司债券。商业银行等金融机构可以按照有关规定发行公司债券补充资本。上市公司发行附认股权、可转换成股票条款的公司债券，应当符合上市公司证券发行管理的相关规定。股票公开转让的非上市公众公司发行附认股权、可转换成股票条款的公司债券，由中国证监会另行规定。"},{"i":12,"n":"第十二条","txt":"根据财产状况、金融资产状况、投资知识和经验、专业能力等因素，公司债券投资者可以分为普通投资者和专业投资者。专业投资者的标准按照中国证监会的相关规定执行。 证券自律组织可以在中国证监会相关规定的基础上，设定更为严格的投资者适当性要求。 发行人的董事、监事、高级管理人员及持股比例超过百分之五的股东，可视同专业投资者参与发行人相关公司债券的认购或交易、转让。"},{"i":13,"n":"第十三条","txt":"公开发行公司债券筹集的资金，必须按照公司债券募集说明书所列资金用途使用；改变资金用途，必须经债券持有人会议作出决议。非公开发行公司债券，募集资金应当用于约定的用途；改变资金用途，应当履行募集说明书约定的程序。 公开发行公司债券筹集的资金，不得用于弥补亏损和非生产性支出。发行人应当指定专项账户，用于公司债券募集资金的接收、存储、划转。"},{"i":14,"n":"第十四条","txt":"公开发行公司债券，应当符合下列条件： （一）具备健全且运行良好的组织机构； （二）最近三年平均可分配利润足以支付公司债券一年的利息； （三）具有合理的资产负债结构和正常的现金流量； （四）国务院规定的其他条件。 公开发行公司债券，由证券交易所负责受理、审核，并报中国证监会注册。"},{"i":15,"n":"第十五条","txt":"存在下列情形之一的，不得再次公开发行公司债券： （一）对已公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，仍处于继续状态； （二）违反《证券法》规定，改变公开发行公司债券所募资金用途。"},{"i":16,"n":"第十六条","txt":"资信状况符合以下标准的公开发行公司债券，专业投资者和普通投资者可以参与认购： （一）发行人最近三年无债务违约或者延迟支付本息的事实； （二）发行人最近三年平均可分配利润不少于债券一年利息的1.5倍； （三）发行人最近一期末净资产规模不少于250亿元； （四）发行人最近36个月内累计公开发行债券不少于3期，发行规模不少于100亿元； （五）中国证监会根据投资者保护的需要规定的其他条件。 未达到前款规定标准的公开发行公司债券，仅限于专业投资者参与认购。 第二节注册程序"},{"i":17,"n":"第十七条","txt":"发行人公开发行公司债券，应当按照中国证监会有关规定制作注册申请文件，由发行人向证券交易所申报。 证券交易所收到注册申请文件后，在五个工作日内作出是否受理的决定。"},{"i":18,"n":"第十八条","txt":"自注册申请文件受理之日起，发行人及其控股股东、实际控制人、董事、监事、高级管理人员，以及与本次债券公开发行并上市相关的主承销商、证券服务机构及相关责任人员，即承担相应法律责任。"},{"i":19,"n":"第十九条","txt":"注册申请文件受理后，未经中国证监会或者证券交易所同意，不得改动。 发生重大事项的，发行人、主承销商、证券服务机构应当及时向证券交易所报告，并按要求更新注册申请文件和信息披露资料。"},{"i":20,"n":"第二十条","txt":"证券交易所负责审核发行人公开发行公司债券并上市申请。 证券交易所主要通过向发行人提出审核问询、发行人回答问题方式开展审核工作，判断发行人是否符合发行条件、上市条件和信息披露要求。"},{"i":21,"n":"第二十一条","txt":"证券交易所按照规定的条件和程序，提出审核意见。认为发行人符合发行条件和信息披露要求的，将审核意见、注册申请文件及相关审核资料报送中国证监会履行发行注册程序。认为发行人不符合发行条件或信息披露要求的，作出终止发行上市审核决定。"},{"i":22,"n":"第二十二条","txt":"证券交易所应当建立健全审核机制，提高审核工作透明度，公开审核工作相关事项，接受社会监督。"},{"i":23,"n":"第二十三条","txt":"中国证监会收到证券交易所报送的审核意见、发行人注册申请文件及相关审核资料后，履行发行注册程序。中国证监会认为存在需要进一步说明或者落实事项的，可以问询或要求证券交易所进一步问询。 中国证监会认为证券交易所的审核意见依据不充分的，可以退回证券交易所补充审核。"},{"i":24,"n":"第二十四条","txt":"证券交易所应当自受理注册申请文件之日起二个月内出具审核意见，中国证监会应当自证券交易所受理注册申请文件之日起三个月内作出同意注册或者不予注册的决定。发行人根据中国证监会、证券交易所要求补充、修改注册申请文件的时间不计算在内。"},{"i":25,"n":"第二十五条","txt":"公开发行公司债券，可以申请一次注册，分期发行。中国证监会同意注册的决定自作出之日起两年内有效，发行人应当在注册决定有效期内发行公司债券，并自主选择发行时点。 公开发行公司债券的募集说明书自最后签署之日起六个月内有效。发行人应当及时更新债券募集说明书等公司债券发行文件，并在每期发行前报证券交易所备案。"},{"i":26,"n":"第二十六条","txt":"中国证监会作出注册决定后，主承销商及证券服务机构应当持续履行尽职调查职责；发生重大事项的，发行人、主承销商、证券服务机构应当及时向证券交易所报告。 证券交易所应当对上述事项及时处理，发现发行人存在重大事项影响发行条件、上市条件的，应当出具明确意见并及时向中国证监会报告。"},{"i":27,"n":"第二十七条","txt":"中国证监会作出注册决定后、发行人公司债券上市前，发现可能影响本次发行的重大事项的，中国证监会可以要求发行人暂缓或者暂停发行、上市；相关重大事项导致发行人不符合发行条件的，可以撤销注册。 中国证监会撤销注册后，公司债券尚未发行的，发行人应当停止发行；公司债券已经发行尚未上市的，发行人应当按照发行价并加算银行同期存款利息返还债券持有人。"},{"i":28,"n":"第二十八条","txt":"中国证监会应当按规定公开公司债券发行注册行政许可事项相关的监管信息。"},{"i":29,"n":"第二十九条","txt":"存在下列情形之一的，发行人、主承销商、证券服务机构应当及时书面报告证券交易所或者中国证监会，证券交易所或者中国证监会应当中止相应发行上市审核程序或者发行注册程序： （一）发行人因涉嫌违法违规被行政机关调查，或者被司法机关侦查，尚未结案，对其公开发行公司债券行政许可影响重大； （二）发行人的主承销商，以及律师事务所、会计师事务所、资信评级机构等证券服务机构因涉嫌公司债券发行业务违法违规，或者其他业务涉嫌违法违规且对市场有重大影响被中国证监会及其派出机构立案调查，或者被司法机关侦查，尚未结案； （三）发行人的主承销商，以及律师事务所、会计师事务所、资信评级机构等证券服务机构的签字人员因涉嫌公司债券发行业务违法违规，或者其他业务涉嫌违法违规且对市场有重大影响被中国证监会及其派出机构立案调查，或者被司法机关侦查，尚未结案； （四）发行人的主承销商，以及律师事务所、会计师事务所、资信评级机构等证"},{"i":30,"n":"第三十条","txt":"存在下列情形之一的，证券交易所或者中国证监会应当终止相应发行上市审核程序或者发行注册程序，并向发行人说明理由： （一）发行人主动要求撤回申请或主承销商申请撤回所出具的核查意见； （二）发行人未在要求的期限内对注册申请文件作出解释说明或者补充、修改； （三）注册申请文件存在虚假记载、误导性陈述或重大遗漏； （四）发行人阻碍或者拒绝中国证监会、证券交易所依法对发行人实施检查、核查； （五）发行人及其关联方以不正当手段严重干扰发行上市审核或者发行注册工作； （六）发行人法人资格终止； （七）发行人注册申请文件内容存在重大缺陷，严重影响投资者理解和发行上市审核或者发行注册工作； （八）发行人中止发行上市审核程序超过证券交易所规定的时限或者中止发行注册程序超过六个月仍未恢复； （九）证券交易所认为发行人不符合发行条件或信息披露要求； （十）中国证监会或证券交易所规定的其他情形。 第三节交易"},{"i":31,"n":"第三十一条","txt":"公开发行的公司债券，应当在证券交易场所交易。 公开发行公司债券并在证券交易场所交易的，应当符合证券交易场所规定的上市、挂牌条件。"},{"i":32,"n":"第三十二条","txt":"证券交易场所应当对公开发行公司债券的上市交易实施分类管理，实行差异化的交易机制，建立相应的投资者适当性管理制度，健全风险控制机制。证券交易场所应当根据债券资信状况的变化及时调整交易机制和投资者适当性安排。"},{"i":33,"n":"第三十三条","txt":"公开发行公司债券申请上市交易的，应当在发行前根据证券交易场所的相关规则，明确交易机制和交易环节投资者适当性安排。发行环节和交易环节的投资者适当性要求应当保持一致。"},{"i":34,"n":"第三十四条","txt":"非公开发行的公司债券应当向专业投资者发行，不得采用广告、公开劝诱和变相公开方式，每次发行对象不得超过二百人。"},{"i":35,"n":"第三十五条","txt":"承销机构应当按照中国证监会、证券自律组织规定的投资者适当性制度，了解和评估投资者对非公开发行公司债券的风险识别和承担能力，确认参与非公开发行公司债券认购的投资者为专业投资者，并充分揭示风险。"},{"i":36,"n":"第三十六条","txt":"非公开发行公司债券，承销机构或依照本办法第三十九条规定自行销售的发行人应当在每次发行完成后五个工作日内向中国证券业协会报备。 中国证券业协会在材料齐备时应当及时予以报备。报备不代表中国证券业协会实行合规性审查，不构成市场准入，也不豁免相关主体的违规责任。"},{"i":37,"n":"第三十七条","txt":"非公开发行公司债券，可以申请在证券交易场所、证券公司柜台转让。 非公开发行公司债券并在证券交易场所转让的，应当遵守证券交易场所制定的业务规则，并经证券交易场所同意。 非公开发行公司债券并在证券公司柜台转让的，应当符合中国证监会的相关规定。"},{"i":38,"n":"第三十八条","txt":"非公开发行的公司债券仅限于专业投资者范围内转让。转让后，持有同次发行债券的投资者合计不得超过二百人。"},{"i":39,"n":"第三十九条","txt":"发行公司债券应当由具有证券承销业务资格的证券公司承销。 取得证券承销业务资格的证券公司、中国证券金融股份有限公司非公开发行公司债券可以自行销售。"},{"i":40,"n":"第四十条","txt":"承销机构承销公司债券，应当依据本办法以及中国证监会、中国证券业协会有关风险管理和内部控制等相关规定，制定严格的风险管理和内部控制制度，明确操作规程，保证人员配备，加强定价和配售等过程管理，有效控制业务风险。 承销机构应当建立健全内部问责机制，相关业务人员因违反公司债券相关规定被采取自律监管措施、自律处分、行政监管措施、市场禁入措施、行政处罚、刑事处罚等的，承销机构应当进行内部问责。 承销机构应当制定合理的薪酬考核体系，不得以业务包干等承包方式开展公司债券承销业务，或者以其他形式实施过度激励。 承销机构应当综合评估项目执行成本与风险责任，合理确定报价，不得以明显低于行业定价水平等不正当竞争方式招揽业务。"},{"i":41,"n":"第四十一条","txt":"主承销商应当遵守业务规则和行业规范，诚实守信、勤勉尽责、保持合理怀疑，按照合理性、必要性和重要性原则，对公司债券发行文件的真实性、准确性和完整性进行审慎核查，并有合理谨慎的理由确信发行文件披露的信息不存在虚假记载、误导性陈述或者重大遗漏。 主承销商对公司债券发行文件中证券服务机构出具专业意见的重要内容存在合理怀疑的，应当履行审慎核查和必要的调查、复核工作，排除合理怀疑。证券服务机构应当配合主承销商的相关核查工作。"},{"i":42,"n":"第四十二条","txt":"承销机构承销公司债券，应当依照《证券法》相关规定采用包销或者代销方式。"},{"i":43,"n":"第四十三条","txt":"发行人和主承销商应当签订承销协议，在承销协议中界定双方的权利义务关系，约定明确的承销基数。采用包销方式的，应当明确包销责任。组成承销团的承销机构应当签订承销团协议，由主承销商负责组织承销工作。公司债券发行由两家以上承销机构联合主承销的，所有担任主承销商的承销机构应当共同承担主承销责任，履行相关义务。承销团由三家以上承销机构组成的，可以设副主承销商，协助主承销商组织承销活动。承销团成员应当按照承销团协议及承销协议的约定进行承销活动，不得进行虚假承销。"},{"i":44,"n":"第四十四条","txt":"公司债券公开发行的价格或利率以询价或公开招标等市场化方式确定。发行人和主承销商应当协商确定公开发行的定价与配售方案并予公告，明确价格或利率确定原则、发行定价流程和配售规则等内容。"},{"i":45,"n":"第四十五条","txt":"发行人和承销机构不得操纵发行定价、暗箱操作；不得以代持、信托等方式谋取不正当利益或向其他相关利益主体输送利益；不得直接或通过其利益相关方向参与认购的投资者提供财务资助；不得有其他违反公平竞争、破坏市场秩序等行为。 发行人不得在发行环节直接或间接认购其发行的公司债券。发行人的董事、监事、高级管理人员、持股比例超过百分之五的股东及其他关联方认购或交易、转让其发行的公司债券的，应当披露相关情况。"},{"i":46,"n":"第四十六条","txt":"公开发行公司债券的，发行人和主承销商应当聘请律师事务所对发行过程、配售行为、参与认购的投资者资质条件、资金划拨等事项进行见证，并出具专项法律意见书。公开发行的公司债券上市后十个工作日内，主承销商应当将专项法律意见、承销总结报告等文件一并报证券交易场所。"},{"i":47,"n":"第四十七条","txt":"发行人和承销机构在推介过程中不得夸大宣传，或以虚假广告等不正当手段诱导、误导投资者，不得披露除债券募集说明书等信息以外的发行人其他信息。承销机构应当保留推介、定价、配售等承销过程中的相关资料，并按相关法律法规规定存档备查，包括推介宣传材料、路演现场录音等，如实、全面反映询价、定价和配售过程。相关推介、定价、配售等的备查资料应当按中国证券业协会的规定制作并妥善保管。"},{"i":48,"n":"第四十八条","txt":"中国证券业协会应当制定非公开发行公司债券承销业务的风险控制管理规定，根据市场风险状况对承销业务范围进行限制并动态调整。"},{"i":49,"n":"第四十九条","txt":"债券募集说明书及其他信息披露文件所引用的审计报告、法律意见书、评级报告及资产评估报告等，应当由符合《证券法》规定的证券服务机构出具。 证券服务机构应当严格遵守法律法规、中国证监会制定的监管规则、执业准则、职业道德守则、证券交易场所制定的业务规则及其他相关规定，建立并保持有效的质量控制体系、独立性管理和投资者保护机制，审慎履行职责，作出专业判断与认定，并对募集说明书或者其他信息披露文件中与其专业职责有关的内容及其出具的文件的真实性、准确性、完整性负责。 证券服务机构及其相关执业人员应当对与本专业相关的业务事项履行特别注意义务，对其他业务事项履行普通注意义务，并承担相应法律责任。 证券服务机构及其执业人员从事证券服务业务应当配合中国证监会的监督管理，在规定的期限内提供、报送或披露相关资料、信息，并保证其提供、报送或披露的资料、信息真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":50,"n":"第五十条","txt":"发行人及其他信息披露义务人应当按照中国证监会及证券自律组织的相关规定履行信息披露义务。"},{"i":51,"n":"第五十一条","txt":"公司债券上市交易的发行人应当按照中国证监会、证券交易所的规定及时披露债券募集说明书，并在债券存续期内披露中期报告和经符合《证券法》规定的会计师事务所审计的年度报告。非公开发行公司债券的发行人信息披露的时点、内容，应当按照募集说明书的约定及证券交易场所的规定履行。 发行人及其控股股东、实际控制人、董事、监事、高级管理人员等作出公开承诺的，应当在募集说明书等文件中披露。"},{"i":52,"n":"第五十二条","txt":"公司债券募集资金的用途应当在债券募集说明书中披露。发行人应当在定期报告中披露公开发行公司债券募集资金的使用情况。非公开发行公司债券的，应当在债券募集说明书中约定募集资金使用情况的披露事宜。"},{"i":53,"n":"第五十三条","txt":"发行人的董事、高级管理人员应当对公司债券发行文件和定期报告签署书面确认意见。 发行人的监事会应当对董事会编制的公司债券发行文件和定期报告进行审核并提出书面审核意见。监事应当签署书面确认意见。 发行人的董事、监事和高级管理人员应当保证发行人及时、公平地披露信息，所披露的信息真实、准确、完整。 董事、监事和高级管理人员无法保证公司债券发行文件和定期报告内容的真实性、准确性、完整性或者有异议的，应当在书面确认意见中发表意见并陈述理由，发行人应当披露。发行人不予披露的，董事、监事和高级管理人员可以直接申请披露。"},{"i":54,"n":"第五十四条","txt":"发生可能对上市交易公司债券的交易价格产生较大影响的重大事件，投资者尚未得知时，发行人应当立即将有关该重大事件的情况向中国证监会、证券交易场所报送临时报告，并予公告，说明事件的起因、目前的状态和可能产生的法律后果。 前款所称重大事件包括： （一）公司股权结构或者生产经营状况发生重大变化； （二）公司债券信用评级发生变化； （三）公司重大资产抵押、质押、出售、转让、报废； （四）公司发生未能清偿到期债务的情况； （五）公司新增借款或者对外提供担保超过上年末净资产的百分之二十； （六）公司放弃债权或者财产超过上年末净资产的百分之十； （七）公司发生超过上年末净资产百分之十的重大损失； （八）公司分配股利，作出减资、合并、分立、解散及申请破产的决定，或者依法进入破产程序、被责令关闭； （九）涉及公司的重大诉讼、仲裁； （十）公司涉嫌犯罪被依法立案调查，公司的控股股东、实际控制人、董事、监事、高"},{"i":55,"n":"第五十五条","txt":"资信评级机构为公开发行公司债券进行信用评级的，应当符合以下规定或约定： （一）将评级信息告知发行人，并及时向市场公布首次评级报告、定期和不定期跟踪评级报告； （二）公司债券的期限为一年以上的，在债券有效存续期间，应当每年至少向市场公布一次定期跟踪评级报告； （三）应充分关注可能影响评级对象信用等级的所有重大因素，及时向市场公布信用等级调整及其他与评级相关的信息变动情况，并向证券交易场所报告。"},{"i":56,"n":"第五十六条","txt":"公开发行公司债券的发行人及其他信息披露义务人应当将披露的信息刊登在其债券交易场所的互联网网站和符合中国证监会规定条件的媒体，同时将其置备于公司住所、证券交易场所，供社会公众查阅。"},{"i":57,"n":"第五十七条","txt":"公开发行公司债券的，发行人应当为债券持有人聘请债券受托管理人，并订立债券受托管理协议；非公开发行公司债券的，发行人应当在募集说明书中约定债券受托管理事项。在债券存续期限内，由债券受托管理人按照规定或协议的约定维护债券持有人的利益。 发行人应当在债券募集说明书中约定，投资者认购或持有本期公司债券视作同意债券受托管理协议、债券持有人会议规则及债券募集说明书中其他有关发行人、债券持有人权利义务的相关约定。"},{"i":58,"n":"第五十八条","txt":"债券受托管理人由本次发行的承销机构或其他经中国证监会认可的机构担任。债券受托管理人应当为中国证券业协会会员。为本次发行提供担保的机构不得担任本次债券发行的受托管理人。债券受托管理人应当勤勉尽责，公正履行受托管理职责，不得损害债券持有人利益。对于债券受托管理人在履行受托管理职责时可能存在的利益冲突情形及相关风险防范、解决机制，发行人应当在债券募集说明书及债券存续期间的信息披露文件中予以充分披露，并同时在债券受托管理协议中载明。"},{"i":59,"n":"第五十九条","txt":"公开发行公司债券的受托管理人应当按规定或约定履行下列职责： （一）持续关注发行人和保证人的资信状况、担保物状况、增信措施及偿债保障措施的实施情况，出现可能影响债券持有人重大权益的事项时，召集债券持有人会议； （二）在债券存续期内监督发行人募集资金的使用情况； （三）对发行人的偿债能力和增信措施的有效性进行全面调查和持续关注，并至少每年向市场公告一次受托管理事务报告； （四）在债券存续期内持续督导发行人履行信息披露义务； （五）预计发行人不能偿还债务时，要求发行人追加担保，并可以依法申请法定机关采取财产保全措施； （六）在债券存续期内勤勉处理债券持有人与发行人之间的谈判或者诉讼事务； （七）发行人为债券设定担保的，债券受托管理人应在债券发行前或债券募集说明书约定的时间内取得担保的权利证明或其他有关文件，并在增信措施有效期内妥善保管； （八）发行人不能按期兑付债券本息或出现募集说明书约定的"},{"i":60,"n":"第六十条","txt":"非公开发行公司债券的，债券受托管理人应当按照债券受托管理协议的约定履行职责。"},{"i":61,"n":"第六十一条","txt":"受托管理人为履行受托管理职责，有权代表债券持有人查询债券持有人名册及相关登记信息、专项账户中募集资金的存储与划转情况。证券登记结算机构应当予以配合。"},{"i":62,"n":"第六十二条","txt":"发行公司债券，应当在债券募集说明书中约定债券持有人会议规则。 债券持有人会议规则应当公平、合理。债券持有人会议规则应当明确债券持有人通过债券持有人会议行使权利的范围，债券持有人会议的召集、通知、决策生效条件与决策程序、决策效力范围和其他重要事项。债券持有人会议按照本办法的规定及会议规则的程序要求所形成的决议对全体债券持有人有约束力，债券持有人会议规则另有约定的除外。"},{"i":63,"n":"第六十三条","txt":"存在下列情形的，债券受托管理人应当按规定或约定召集债券持有人会议： （一）拟变更债券募集说明书的约定； （二）拟修改债券持有人会议规则； （三）拟变更债券受托管理人或受托管理协议的主要内容； （四）发行人不能按期支付本息； （五）发行人减资、合并等可能导致偿债能力发生重大不利变化，需要决定或者授权采取相应措施； （六）发行人分立、被托管、解散、申请破产或者依法进入破产程序； （七）保证人、担保物或者其他偿债保障措施发生重大变化； （八）发行人、单独或合计持有本期债券总额百分之十以上的债券持有人书面提议召开； （九）发行人管理层不能正常履行职责，导致发行人债务清偿能力面临严重不确定性； （十）发行人提出债务重组方案的； （十一）发生其他对债券持有人权益有重大影响的事项。 在债券受托管理人应当召集而未召集债券持有人会议时，单独或合计持有本期债券总额百分之十以上的债券持有人有权自行召集债券持"},{"i":64,"n":"第六十四条","txt":"发行人可采取内外部增信机制、偿债保障措施，提高偿债能力，控制公司债券风险。内外部增信机制、偿债保障措施包括但不限于下列方式： （一）第三方担保； （二）商业保险； （三）资产抵押、质押担保； （四）限制发行人债务及对外担保规模； （五）限制发行人对外投资规模； （六）限制发行人向第三方出售或抵押主要资产； （七）设置债券回售条款。 公司债券增信机构可以成为中国证券业协会会员。"},{"i":65,"n":"第六十五条","txt":"发行人应当在债券募集说明书中约定构成债券违约的情形、违约责任及其承担方式以及公司债券发生违约后的诉讼、仲裁或其他争议解决机制。"},{"i":66,"n":"第六十六条","txt":"中国证监会建立对证券交易场所公司债券业务监管工作的监督机制，持续关注证券交易场所发行审核、发行承销过程及其他公司债券业务监管情况，并开展定期或不定期检查。中国证监会在检查和抽查过程中发现问题的，证券交易场所应当整改。 证券交易场所应当建立定期报告制度，及时总结公司债券发行审核、发行承销过程及其他公司债券业务监管工作情况，并报告中国证监会。"},{"i":67,"n":"第六十七条","txt":"证券交易场所公司债券发行上市审核工作违反本办法规定，有下列情形之一的，由中国证监会责令改正；情节严重的，追究直接责任人员相关责任： （一）未按审核标准开展公司债券发行上市审核工作； （二）未按程序开展公司债券发行上市审核工作； （三）不配合中国证监会对发行上市审核工作、发行承销过程及其他公司债券业务监管工作的检查、抽查，或者不按中国证监会的整改要求进行整改。"},{"i":68,"n":"第六十八条","txt":"违反法律法规及本办法等规定的，中国证监会可以对相关机构和人员采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告等相关监管措施；依法应予行政处罚的，依照《证券法》《行政处罚法》等法律法规和中国证监会的有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":69,"n":"第六十九条","txt":"非公开发行公司债券，发行人及其他信息披露义务人披露的信息存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以对发行人、其他信息披露义务人及其直接负责的主管人员和其他直接责任人员采取本办法第六十八条规定的相关监管措施；情节严重的，依照《证券法》第一百九十七条予以处罚。"},{"i":70,"n":"第七十条","txt":"非公开发行公司债券，发行人违反本办法第十三条规定的，中国证监会可以对发行人及其直接负责的主管人员和其他直接责任人员采取本办法第六十八条规定的相关监管措施；情节严重的，处以警告、罚款。"},{"i":71,"n":"第七十一条","txt":"除中国证监会另有规定外，承销或自行销售非公开发行公司债券未按规定进行报备的，中国证监会可以对承销机构及其直接负责的主管人员和其他直接责任人员采取本办法第六十八条规定的相关监管措施；情节严重的，处以警告、罚款。"},{"i":72,"n":"第七十二条","txt":"承销机构在承销公司债券过程中，有下列行为之一的，中国证监会可以对承销机构及其直接负责的主管人员和其他直接责任人员采取本办法第六十八条规定的相关监管措施；情节严重的，依照《证券法》第一百八十四条予以处罚。 （一）未勤勉尽责，违反本办法第四十一条规定的行为； （二）以不正当竞争手段招揽承销业务； （三）从事本办法第四十五条规定禁止的行为； （四）从事本办法第四十七条规定禁止的行为； （五）未按本办法及相关规定要求披露有关文件； （六）未按照事先披露的原则和方式配售公司债券，或其他未依照披露文件实施的行为； （七）未按照本办法及相关规定要求保留推介、定价、配售等承销过程中相关资料； （八）其他违反承销业务规定的行为。"},{"i":73,"n":"第七十三条","txt":"发行人及其控股股东、实际控制人、债券受托管理人等违反本办法规定，损害债券持有人权益的，中国证监会可以对发行人、发行人的控股股东和实际控制人、受托管理人及其直接负责的主管人员和其他直接责任人员采取本办法第六十八条规定的相关监管措施；情节严重的，处以警告、罚款。"},{"i":74,"n":"第七十四条","txt":"发行人及其控股股东、实际控制人、董事、监事、高级管理人员违反本办法第五条第二款的规定，严重损害债券持有人权益的，中国证监会可以依法限制其市场融资等活动，并将其有关信息纳入证券期货市场诚信档案数据库。"},{"i":75,"n":"第七十五条","txt":"发行人的控股股东滥用公司法人独立地位和股东有限责任，损害债券持有人利益的，应当依法对公司债务承担连带责任。"},{"i":76,"n":"第七十六条","txt":"发行公司债券并在证券交易场所交易或转让的，应当由中国证券登记结算有限责任公司依法集中统一办理登记结算业务。非公开发行公司债券并在证券公司柜台转让的，可以由中国证券登记结算有限责任公司或者其他依法从事证券登记、结算业务的机构办理。"},{"i":77,"n":"第七十七条","txt":"发行公司债券，应当符合地方政府性债务管理的相关规定，不得新增政府债务。"},{"i":78,"n":"第七十八条","txt":"证券公司和其他金融机构次级债券的发行、交易或转让，适用本办法。境外注册公司在中国证监会监管的债券交易场所的债券发行、交易或转让，参照适用本办法。"},{"i":79,"n":"第七十九条","txt":"本办法所称证券自律组织包括证券交易所、全国中小企业股份转让系统、中国证券登记结算有限责任公司、中国证券业协会以及中国证监会认定的其他自律组织。 本办法所称证券交易场所包括证券交易所、全国中小企业股份转让系统。"},{"i":80,"n":"第八十条","txt":"本办法自公布之日起施行。2015年1月15日发布的《公司债券发行与交易管理办法》（证监会令第113号）同时废止。"}],"gongkaimujizhengquantouzijijinxinxipiluguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范公开募集证券投资基金（以下简称基金）信息披露活动，保护投资者及相关当事人的合法权益，根据《证券投资基金法》（以下简称《基金法》），制定本办法。"},{"i":2,"n":"第二条","txt":"基金信息披露义务人应当以保护基金份额持有人利益为根本出发点，按照法律、行政法规和中国证券监督管理委员会（以下简称中国证监会）的规定披露基金信息，并保证所披露信息的真实性、准确性、完整性、及时性、简明性和易得性。 基金信息披露义务人包括基金管理人、基金托管人、召集基金份额持有人大会的基金份额持有人及其日常机构等法律、行政法规和中国证监会规定的自然人、法人和非法人组织。"},{"i":3,"n":"第三条","txt":"基金信息披露义务人应当在中国证监会规定时间内，将应予披露的基金信息通过符合中国证监会规定条件的全国性报刊（以下简称规定报刊）及本办法规定的互联网网站（以下简称规定网站）等媒介披露，并保证投资者能够按照基金合同约定的时间和方式查阅或者复制公开披露的信息资料。 规定网站包括基金管理人网站、基金托管人网站、中国证监会基金电子披露网站。规定网站应当无偿向投资者提供基金信息披露服务。"},{"i":4,"n":"第四条","txt":"基金份额在证券交易所上市交易的，基金信息披露义务人还应当根据证券交易所的自律管理规则披露基金信息。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依法对基金信息披露活动进行监督管理。 中国证监会根据基金信息披露活动情况，及时制定相关的内容与格式准则、编报规则等；根据基金信息披露活动中存在的技术问题，直接做出或授权指定机构做出规范解答。 证券交易所、中国证券投资基金业协会依法对基金信息披露活动进行自律管理。"},{"i":6,"n":"第六条","txt":"公开披露的基金信息包括： （一）基金招募说明书； （二）基金合同； （三）基金托管协议； （四）基金产品资料概要； （五）基金份额发售公告； （六）基金募集情况； （七）基金份额上市交易公告书； （八）基金资产净值、基金份额净值； （九）基金份额申购、赎回价格； （十）基金定期报告，包括年度报告、中期报告和季度报告（含资产组合季度报告）； （十一）临时报告； （十二）基金份额持有人大会决议； （十三）基金管理人、基金托管人的专门基金托管部门的重大人事变动； （十四）涉及基金财产、基金管理业务、基金托管业务的诉讼或者仲裁； （十五）澄清公告； （十六）清算报告； （十七）中国证监会规定的其他信息。"},{"i":7,"n":"第七条","txt":"公开披露基金信息，不得有下列行为： （一）虚假记载、误导性陈述或者重大遗漏； （二）对证券投资业绩进行预测； （三）违规承诺收益或者承担损失； （四）诋毁其他基金管理人、基金托管人或者基金销售机 构； （五）登载任何自然人、法人和非法人组织的祝贺性、恭维性或推荐性文字； （六）中国证监会禁止的其他行为。"},{"i":8,"n":"第八条","txt":"公开披露的基金信息应当采用中文文本。同时采用外文文本的，基金信息披露义务人应当保证不同文本的内容一致。不同文本之间发生歧义的，以中文文本为准。"},{"i":9,"n":"第九条","txt":"公开披露的基金信息应当采用阿拉伯数字；除特别说明外，货币单位应当为人民币元。"},{"i":10,"n":"第十条","txt":"基金募集申请经中国证监会注册后，基金管理人应当在基金份额发售的三日前，将基金份额发售公告、基金招募说明书提示性公告和基金合同提示性公告登载在规定报刊上，将基金份额发售公告、基金招募说明书、基金产品资料概要、基金合同和基金托管协议登载在规定网站上；基金托管人应当同时将基金合同、基金托管协议登载在规定网站上。"},{"i":11,"n":"第十一条","txt":"基金管理人应当在基金合同生效的次日在规定报刊和规定网站上登载基金合同生效公告。"},{"i":12,"n":"第十二条","txt":"基金合同生效后，基金招募说明书、基金产品资料概要的信息发生重大变更的，基金管理人应当在三个工作日内，更新基金招募说明书和基金产品资料概要，并登载在规定网站上。"},{"i":13,"n":"第十三条","txt":"基金份额获准在证券交易所上市交易的，基金管理人应当在基金份额上市交易的三个工作日前，将基金份额上市交易公告书登载在规定网站上，并将上市交易公告书提示性公告登载在规定报刊上。"},{"i":14,"n":"第十四条","txt":"基金管理人应当按照下列要求披露基金净值信息： （一）至少每周在规定网站披露一次封闭式基金资产净值和基金份额净值； （二）开放式基金的基金合同生效后，在开始办理基金份额申购或者赎回前，至少每周在规定网站披露一次基金份额净值和基金份额累计净值； （三）开放式基金在不晚于每个开放日的次日，通过规定网站、基金销售机构网站或者营业网点披露开放日的基金份额净值和基金份额累计净值； （四）在不晚于半年度和年度最后一日的次日，在规定网站披露半年度和年度最后一日的基金份额净值和基金份额累计净值。 中国证监会对特殊基金品种的净值信息披露另有规定的，从其规定。"},{"i":15,"n":"第十五条","txt":"基金管理人应当在开放式基金的基金合同、招募说明书等信息披露文件上载明基金份额申购、赎回价格的计算方式及有关申购、赎回费率，并保证投资者能够在基金销售机构网站或营业网点查阅或者复制前述信息资料。"},{"i":16,"n":"第十六条","txt":"基金管理人应当在每年结束之日起三个月内，编制完成基金年度报告，将年度报告登载在规定网站上，并将年度报告提示性公告登载在规定报刊上。 基金年度报告中的财务会计报告应当经过符合《证券法》规定的会计师事务所审计。"},{"i":17,"n":"第十七条","txt":"基金管理人应当在上半年结束之日起两个月内，编制完成基金中期报告，将中期报告登载在规定网站上，并将中期报告提示性公告登载在规定报刊上。"},{"i":18,"n":"第十八条","txt":"基金管理人应当在季度结束之日起十五个工作日内，编制完成基金季度报告，将季度报告登载在规定网站上，并将季度报告提示性公告登载在规定报刊上。"},{"i":19,"n":"第十九条","txt":"基金合同生效不足两个月的，基金管理人可以不编制当期季度报告、中期报告或者年度报告。"},{"i":20,"n":"第二十条","txt":"基金合同终止的，基金管理人应当依法组织清算组对基金财产进行清算并作出清算报告。清算报告应当经过符合《证券法》规定的会计师事务所审计，并由律师事务所出具法律意见书。清算组应当将清算报告登载在规定网站上，并将清算报告提示性公告登载在规定报刊上。"},{"i":21,"n":"第二十一条","txt":"基金发生重大事件，有关信息披露义务人应当在两日内编制临时报告书，并登载在规定报刊和规定网站上。 前款所称重大事件，是指可能对基金份额持有人权益或者基金份额的价格产生重大影响的下列事件： （一）基金份额持有人大会的召开及决定的事项； （二）基金终止上市交易、基金合同终止、基金清算； （三）基金扩募、延长基金合同期限； （四）转换基金运作方式、基金合并； （五）更换基金管理人、基金托管人、基金份额登记机构，基金改聘会计师事务所； （六）基金管理人委托基金服务机构代为办理基金的份额登记、核算、估值等事项，基金托管人委托基金服务机构代为办理基金的核算、估值、复核等事项； （七）基金管理人、基金托管人的法定名称、住所发生变更； （八）基金管理公司变更持有百分之五以上股权的股东、变更公司的实际控制人； （九）基金募集期延长或提前结束募集； （十）基金管理人高级管理人员、基金经理和基金托管人专门基金"},{"i":22,"n":"第二十二条","txt":"召开基金份额持有人大会的，召集人应当至少提前三十日在规定报刊和规定网站上公告基金份额持有人大会的召开时间、会议形式、审议事项、议事程序和表决方式等事项。 基金份额持有人或基金份额持有人大会的日常机构依法召集持有人大会，基金管理人、基金托管人对基金份额持有人大会决定的事项不依法履行信息披露义务的，召集人应当履行相关信息披露义务。"},{"i":23,"n":"第二十三条","txt":"在基金合同期限内，任何公共媒体中出现的或者在市场上流传的消息可能对基金份额价格产生误导性影响或者引起较大波动，以及可能损害基金份额持有人权益的，相关信息披露义务人知悉后应当立即对该消息进行公开澄清，并将有关情况立即报告中国证监会、基金上市交易的证券交易所。"},{"i":24,"n":"第二十四条","txt":"基金管理人、基金托管人应当建立健全信息披露管理制度，指定专门部门及高级管理人员负责管理信息披露事务。 基金管理人、基金托管人应加强对未公开披露基金信息的管控，并建立基金敏感信息知情人登记制度。基金管理人、基金托管人及相关从业人员不得泄露未公开披露的基金信息。"},{"i":25,"n":"第二十五条","txt":"基金信息披露义务人公开披露基金信息，应当符合中国证监会相关基金信息披露内容与格式准则等法规的规定；特定基金信息披露事项和特殊基金品种的信息披露，应当符合中国证监会相关编报规则等法规的规定。"},{"i":26,"n":"第二十六条","txt":"基金托管人应当按照相关法律、行政法规、中国证监会的规定和基金合同的约定，对基金管理人编制的基金资产净值、基金份额净值、基金份额申购赎回价格、基金定期报告、更新的招募说明书、基金产品资料概要、基金清算报告等公开披露的相关基金信息进行复核、审查，并向基金管理人进行书面或电子确认。"},{"i":27,"n":"第二十七条","txt":"基金管理人、基金托管人应当在规定报刊中选择披露信息的报刊，单只基金只需选择一家报刊。 基金管理人、基金托管人应当向中国证监会基金电子披露网站报送拟披露的基金信息，并保证相关报送信息的真实、准确、完整、及时。"},{"i":28,"n":"第二十八条","txt":"基金管理人应当在基金合同、基金招募说明书、基金份额上市交易公告书等基金信息披露文件中加强风险揭示，对设计复杂、风险较高的基金应以显著、清晰的方式揭示基金投资运作及交易等环节的相关风险。 基金管理人应当规范基金名称，基金名称应显示产品类型、主要投资方向或投资策略等核心特征。采用定期开放式或封闭式、设置投资者最短持有期限的基金，应当在名称中明示产品封闭期限或投资者最短持有期限。"},{"i":29,"n":"第二十九条","txt":"为强化投资者保护，提升信息披露服务质量，基金管理人应当按照中国证监会规定向投资者及时提供对其投资决策有重大影响的信息，基金销售机构、为投资者交易上市基金份额提供经纪服务的证券公司应当按照中国证监会规定做好相关信息传递工作。"},{"i":30,"n":"第三十条","txt":"基金管理人、基金托管人除按法律法规要求披露信息外，也可着眼于为投资者决策提供有用信息的角度，在保证公平对待投资者、不误导投资者、不影响基金正常投资操作的前提下，自主提升信息披露服务的质量。具体应遵循以下要求： （一）可以通过短信、电子邮件、移动客户端、社交平台等方式向投资者提供信息披露服务； （二）可以通过月度报告等方式提高定期报告的披露频率；基金管理人应保持信息披露的持续性和公开性，不得为短期营销行为临时性、选择性披露信息； （三）可以在其他公共媒介披露信息，但不得早于规定媒介和基金上市交易的证券交易所网站，且在不同媒介上披露同一信息的内容应当一致； （四）前述自主披露如产生信息披露费用，该费用不得从基金财产中列支。"},{"i":31,"n":"第三十一条","txt":"为基金信息披露义务人公开披露的基金信息出具审计报告、法律意见书的专业机构，应当制作工作底稿，并将相关档案至少保存到基金合同终止后十年。"},{"i":32,"n":"第三十二条","txt":"依法必须披露的信息发布后，基金管理人、基金托管人应当按照相关法律法规规定将信息置备于公司住所、基金上市交易的证券交易所，供社会公众查阅、复制。"},{"i":33,"n":"第三十三条","txt":"中国证监会及其派出机构对信息披露义务人、基金销售机构、证券公司从事信息披露及相关服务的情况，进行定期或者不定期的现场和非现场检查，相关单位及个人应当予以配合。"},{"i":34,"n":"第三十四条","txt":"中国证监会可以定期评估基金管理人的信息披露质量，并纳入基金管理人分类监管评价指标体系中。基金管理人存在下列情形的，中国证监会可以中止审查，并根据情节轻重，在3-12个月内对该基金管理人提交的基金注册申请不适用简易程序，或者3-12个月内不再受理基金管理人提交的基金注册申请，违反法律法规的，依照相关规定采取措施或予以处罚： （一）基金注册申请材料中基金招募说明书、基金合同、基金产品资料概要等信息披露文件存在明显差错； （二）基金注册申请材料与合同填报指引存在明显差异，且未如实向中国证监会报告； （三）中国证监会认定的其他情形。"},{"i":35,"n":"第三十五条","txt":"基金信息披露义务人、基金销售机构、证券公司及相关人员违反本办法规定的，中国证监会及其派出机构可以采取责令改正、监管谈话、出具警示函、责令定期报告、暂不受理与行政许可有关的文件等行政监管措施；对直接负责的主管人员和其他直接责任人员，可以采取监管谈话、出具警示函、责令参加培训、认定为不适当人选等行政监管措施，记入诚信档案。 基金管理人违反本办法规定构成公司治理结构不健全、内部控制不完善等情形的，依照《基金法》第二十四条采取行政监管措施。"},{"i":36,"n":"第三十六条","txt":"基金信息披露义务人的信息披露活动存在违反本办法的下列情形之一且情节严重的，除法律、行政法规另有规定外，对基金信息披露义务人处以警告、并处三万元以下罚款，对直接负责的主管人员和其他直接责任人员，处以警告、并处三万元以下罚款： （一）违反本办法第二十五条的规定，信息披露文件不符合中国证监会有关规定； （二）违反本办法第二十六条的规定，基金托管人未按规定对公开披露的基金信息进行复核、审查或者确认； （三）违反本办法第二十七条的规定，基金管理人、基金托管人未按规定选择规定报刊，未按规定向中国证监会基金电子披露网站报送信息； （四）违反本办法第二十八条的规定，基金管理人未在基金信息披露文件中揭示相关风险，未在基金名称中显示核心特征或期限； （五）违反本办法第二十九条的规定，基金管理人未按规定向投资者及时提供对其投资决策有重大影响的信息，基金销售机构、证券公司未按规定做好相关信息传递工作； （六）"},{"i":37,"n":"第三十七条","txt":"基金管理人、基金托管人违反本办法第二十四条规定且情节严重的，处以警告、并处三万元以下罚款；对直接负责的主管人员和其他直接责任人员，处以警告、并处三万元以下罚款；构成《基金法》第二十条第（六）项所述情形的，依照《基金法》第一百二十三条进行处罚。"},{"i":38,"n":"第三十八条","txt":"基金发生第二十一条第二款第（十四）项所述重大关联交易事项，且基金信息披露义务人未依法履行信息披露义务的，依照《基金法》第一百二十九条进行处罚。"},{"i":39,"n":"第三十九条","txt":"基金信息披露义务人的信息披露活动存在下列情形之一的，依照《基金法》第一百三十一条进行处罚： （一）违反本办法第三条的规定，未能保证投资者按照基金合同约定的时间和方式查阅或者复制公开披露的信息资料； （二）违反本办法第七条规定； （三）未公开披露本办法第六条、第二十一条第二款规定的基金信息； （四）未按照本办法第十条、第十一条、第十二条、第十三条、第十四条、第十六条、第十七条、第十八条、第二十条、第二十一条规定的时间或规定媒介披露基金信息； （五）违反本办法第十六条、第二十条的规定，年度报告中的财务会计报告未经审计即予披露，清算报告未经审计、未经出具法律意见书即予披露。"},{"i":40,"n":"第四十条","txt":"为基金信息披露义务人公开披露的基金信息出具审计报告、法律意见书等文件的专业机构未勤勉尽责，所出具的文件有虚假记载、误导性陈述或者有重大遗漏的，依照《基金法》第一百四十三条进行处罚。"},{"i":41,"n":"第四十一条","txt":"经中国证监会注册的境外互认基金，涉及境内信息披露业务的，依照本办法执行，法律法规及中国证监会另有规定的除外。 境外互认基金管理人、代理人在从事互认基金信息披露等相关业务活动中，存在违反本办法规定的，中国证监会可以依法对其采取行政监管措施或者行政处罚。"},{"i":42,"n":"第四十二条","txt":"本办法自2019年9月1日起施行。中国证监会发布的《证券投资基金信息披露管理办法》（证监会令第19号）同时废止。"}],"gongkaimujizhengquantouzijijinyunzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范公开募集证券投资基金（以下简称基金）运作活动，保护投资者的合法权益，促进证券投资基金市场健康发展，根据《证券投资基金法》及其他有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于基金的募集，基金份额的申购、赎回和交易，基金财产的投资，基金收益的分配，基金份额持有人大会的召开，以及其他基金运作活动。"},{"i":3,"n":"第三条","txt":"从事基金运作活动，应当遵守法律、行政法规和中国证券监督管理委员会（以下简称中国证监会）的规定，遵循自愿、公平、诚实信用原则，不得损害国家利益和社会公共利益。 基金管理人运用基金财产进行证券投资，应当遵守审慎经营规则，制定科学合理的投资策略和风险管理制度，有效防范和控制风险。"},{"i":4,"n":"第四条","txt":"中国证监会及其派出机构依照法律、行政法规、本办法的规定和审慎监管原则，对基金运作活动实施监督管理。 中国证监会对基金募集的注册审查以要件齐备和内容合规为基础，以充分的信息披露和投资者适当性为核心，以加强投资者利益保护和防范系统性风险为目标。中国证监会不对基金的投资价值及市场前景等作出实质性判断或者保证。投资者应当认真阅读基金招募说明书、基金合同等信息披露文件，自主判断基金的投资价值，自主做出投资决策，自行承担投资风险。"},{"i":5,"n":"第五条","txt":"证券投资基金行业协会（以下简称基金行业协会）依据法律、行政法规、中国证监会的规定和自律规则，对基金运作活动进行自律管理。"},{"i":6,"n":"第六条","txt":"申请募集基金，拟任基金管理人、基金托管人应当具备下列条件： （一）拟任基金管理人为依法设立的基金管理公司或者经中国证监会核准的其他机构，拟任基金托管人为具有基金托管资格的商业银行或者经中国证监会核准的其他金融机构； （二）有符合中国证监会规定的、与管理和托管拟募集基金相适应的基金经理等业务人员； （三）最近一年内没有因重大违法违规行为、重大失信行为受到行政处罚或者刑事处罚； （四）没有因违法违规行为、失信行为正在被监管机构立案调查、司法机关立案侦察，或者正处于整改期间； （五）最近一年内向中国证监会提交的注册基金申请材料不存在虚假记载、误导性陈述或者重大遗漏； （六）不存在对基金运作已经造成或者可能造成不良影响的重大变更事项，或者诉讼、仲裁等其他重大事项； （七）不存在治理结构不健全、经营管理混乱、内部控制和风险管理制度无法得到有效执行、财务状况恶化等重大经营风险； （八）中国证监会根"},{"i":7,"n":"第七条","txt":"申请募集基金，拟募集的基金应当具备下列条件： （一）有明确、合法的投资方向； （二）有明确的基金运作方式； （三）符合中国证监会关于基金品种的规定； （四）基金合同、招募说明书等法律文件草案符合法律、行政法规和中国证监会的规定； （五）基金名称表明基金的类别和投资特征，不存在损害国家利益、社会公共利益，欺诈、误导投资者，或者其他侵犯他人合法权益的内容； （六）招募说明书真实、准确、完整地披露了投资者做出投资决策所需的重要信息，不存在虚假记载、误导性陈述或者重大遗漏，语言简明、易懂、实用，符合投资者的理解能力。 （七）有符合基金特征的投资者适当性管理制度，有明确的投资者定位、识别和评估等落实投资者适当性安排的方法，有清晰的风险警示内容； （八）基金的投资管理、销售、登记和估值等业务环节制度健全，行为规范，技术系统准备充分，不存在影响基金正常运作、损害或者可能损害基金份额持有人合法权益、可"},{"i":8,"n":"第八条","txt":"基金管理人申请募集基金，应当按照《证券投资基金法》和中国证监会的规定提交申请材料。申请材料自被行政受理时点起，基金管理人、基金托管人及相关中介机构即需要对申请材料的真实性、准确性、完整性承担相应的法律责任。 为基金申请材料出具法律意见书等文件的中介机构，应当勤勉尽责，对所依据的文件资料的真实性、准确性、完整性进行核查和验证。 申请材料受理后，相关内容不得随意更改。申请期间申请材料涉及的事项发生重大变化的，基金管理人应当自变化发生之日起五个工作日内向中国证监会提交更新材料。"},{"i":9,"n":"第九条","txt":"中国证监会依照《行政许可法》和《证券投资基金法》第五十五条的规定，受理基金募集注册申请，并进行审查，作出注册或者不予注册的决定，并通知申请人；不予注册的，应当说明理由。"},{"i":10,"n":"第十条","txt":"中国证监会在注册审查中可视情况征求基金行业协会、证券交易所、证券登记结算机构等的意见，供注册审查参考。"},{"i":11,"n":"第十一条","txt":"基金募集期限自基金份额发售之日起不得超过三个月。"},{"i":12,"n":"第十二条","txt":"基金募集期限届满，募集的基金份额总额符合《证券投资基金法》第五十九条的规定，并具备下列条件的，基金管理人应当按照规定办理验资和基金备案手续：基金募集份额总额不少于两亿份，基金募集金额不少于两亿元人民币；基金份额持有人的人数不少于二百人。 发起式基金不受上述限制。发起式基金是指，基金管理人在募集基金时，使用公司股东资金、公司固有资金、公司高级管理人员或者基金经理等人员资金认购基金的金额不少于一千万元人民币，且持有期限不少于三年。发起式基金的基金合同生效三年后，若基金资产净值低于两亿元的，基金合同自动终止。"},{"i":13,"n":"第十三条","txt":"中国证监会自收到基金管理人验资报告和基金备案材料之日起三个工作日内予以书面确认；自中国证监会书面确认之日起，基金备案手续办理完毕，基金合同生效。 基金管理人应当在收到中国证监会确认文件的次日予以公告。"},{"i":14,"n":"第十四条","txt":"基金募集期间的信息披露费、会计师费、律师费以及其他费用，不得从基金财产中列支；基金收取认购费的，可以从认购费中列支。"},{"i":15,"n":"第十五条","txt":"开放式基金的基金合同应当约定，并在招募说明书中载明基金管理人办理基金份额申购、赎回业务的日期（以下简称开放日）和时间。基金管理人在办理基金份额申购、赎回业务时，应当遵循基金份额持有人利益优先原则，发生申购、赎回损害持有人利益的情形时，应当及时暂停申购、赎回业务。"},{"i":16,"n":"第十六条","txt":"开放式基金的基金合同可以约定基金管理人自基金合同生效之日起一定期限内不办理赎回；但约定的期限不得超过三个月，并应当在招募说明书中载明。但中国证监会规定的特殊基金品种除外。"},{"i":17,"n":"第十七条","txt":"开放式基金份额的申购、赎回价格，依据申购、赎回日基金份额净值加、减有关费用计算。开放式基金份额的申购、赎回价格具体计算方法应当在基金合同和招募说明书中载明。 开放式基金份额净值，应当按照每个开放日闭市后，基金资产净值除以当日基金份额的余额数量计算。具体计算方法应当在基金合同和招募说明书中载明。"},{"i":18,"n":"第十八条","txt":"基金管理人不得在基金合同约定之外的日期或者时间办理基金份额的申购、赎回或者转换。 投资者在基金合同约定之外的日期和时间提出申购、赎回或者转换申请的，其基金份额申购、赎回价格为下次办理基金份额申购、赎回时间所在开放日的价格。"},{"i":19,"n":"第十九条","txt":"投资者申购基金份额时，必须全额交付申购款项；投资者交付申购款项，申购成立；基金份额登记机构确认基金份额时，申购生效。基金份额持有人递交赎回申请，赎回成立；基金份额登记机构确认赎回时，赎回生效。但中国证监会规定的特殊基金品种除外。 投资特定指数所对应的组合证券或者基金合同约定的其他投资标的的开放式基金，其基金份额可以用组合证券、现金或者基金合同约定的其他对价进行申购、赎回。基金份额的申购、赎回对价根据基金的资产组合和申购、赎回日基金份额净值确定，具体计算方法应当在基金合同和招募说明书中载明。基金份额的上市交易、申购赎回和资金结算应当符合证券交易所和证券登记结算机构等的有关规定。"},{"i":20,"n":"第二十条","txt":"基金管理人应当自收到投资者申购、赎回申请之日起三个工作日内，对该申购、赎回的有效性进行确认，但中国证监会规定的特殊基金品种除外。 基金管理人应当自接受投资者有效赎回申请之日起七个工作日内支付赎回款项，但中国证监会规定的特殊基金品种除外。"},{"i":21,"n":"第二十一条","txt":"开放式基金的基金合同可以约定基金达到一定的规模后，基金管理人不再接受认购、申购申请，但应当在招募说明书中载明。 基金管理人在基金募集期间不得调整基金合同约定的基金规模。基金合同生效后，基金管理人可以按照基金合同的约定，根据实际情况调整基金规模，但应当提前三日公告，并更新招募说明书。"},{"i":22,"n":"第二十二条","txt":"开放式基金的基金合同可以对单个基金份额持有人持有基金份额的比例或者数量设置限制，但应当在招募说明书中载明。"},{"i":23,"n":"第二十三条","txt":"开放式基金单个开放日净赎回申请超过基金总份额的百分之十的，为巨额赎回，但中国证监会规定的特殊基金品种除外。 开放式基金发生巨额赎回的，基金管理人当日办理的赎回份额不得低于基金总份额的百分之十，对其余赎回申请可以延期办理。"},{"i":24,"n":"第二十四条","txt":"开放式基金发生巨额赎回的，基金管理人对单个基金份额持有人的赎回申请，应当按照其申请赎回份额占当日申请赎回总份额的比例，确定该单个基金份额持有人当日办理的赎回份额。 基金份额持有人可以在申请赎回时选择将当日未获办理部分予以撤销。基金份额持有人未选择撤销的，基金管理人对未办理的赎回份额，可延迟至下一个开放日办理，赎回价格为下一个开放日的价格。"},{"i":25,"n":"第二十五条","txt":"开放式基金发生巨额赎回并延期办理的，基金管理人应当通过邮寄、传真或者招募说明书规定的其他方式，在三个交易日内通知基金份额持有人，说明有关处理方法，同时在指定媒介上予以公告。"},{"i":26,"n":"第二十六条","txt":"开放式基金连续发生巨额赎回，基金管理人可按基金合同的约定和招募说明书的规定，暂停接受赎回申请；已经接受的赎回申请可以延缓支付赎回款项，但延缓期限不得超过二十个工作日，并应当在指定媒介上予以公告。"},{"i":27,"n":"第二十七条","txt":"开放式基金的基金合同可以约定，单个基金份额持有人在单个开放日申请赎回基金份额超过基金总份额一定比例的，基金管理人可以按照本办法第二十六条的规定暂停接受赎回申请或者延缓支付。"},{"i":28,"n":"第二十八条","txt":"开放式基金应当保持不低于基金资产净值百分之五的现金或者到期日在一年以内的政府债券，以备支付基金份额持有人的赎回款项，但中国证监会规定的特殊基金品种除外。"},{"i":29,"n":"第二十九条","txt":"基金份额可以依法在证券交易所上市交易，或者按照法律法规规定和基金合同约定在中国证监会认可的交易场所或者通过其他方式进行转让。"},{"i":30,"n":"第三十条","txt":"基金合同和基金招募说明书应当按照下列规定载明基金的类别： （一）百分之八十以上的基金资产投资于股票的，为股票基金； （二）百分之八十以上的基金资产投资于债券的，为债券基金； （三）仅投资于货币市场工具的，为货币市场基金； （四）百分之八十以上的基金资产投资于其他基金份额的，为基金中基金； （五）投资于股票、债券、货币市场工具或其他基金份额，并且股票投资、债券投资、基金投资的比例不符合第（一）项、第（二）项、第（四）项规定的，为混合基金； （六）中国证监会规定的其他基金类别。"},{"i":31,"n":"第三十一条","txt":"基金名称显示投资方向的，应当有百分之八十以上的非现金基金资产属于投资方向确定的内容。"},{"i":32,"n":"第三十二条","txt":"基金管理人运用基金财产进行证券投资，不得有下列情形： （一）一只基金持有一家公司发行的证券，其市值超过基金资产净值的百分之十； （二）同一基金管理人管理的全部基金持有一家公司发行的证券，超过该证券的百分之十； （三）基金财产参与股票发行申购，单只基金所申报的金额超过该基金的总资产，单只基金所申报的股票数量超过拟发行股票公司本次发行股票的总量； （四）一只基金持有其他基金（不含货币市场基金），其市值超过基金资产净值的百分之十，但基金中基金除外； （五）基金中基金持有其他单只基金，其市值超过基金资产净值的百分之二十，或者投资于其他基金中基金； （六）基金总资产超过基金净资产的百分之一百四十； （七）违反基金合同关于投资范围、投资策略和投资比例等约定； （八）中国证监会规定禁止的其他情形。 完全按照有关指数的构成比例进行证券投资的基金品种可以不受前款第（一）项、第（二）项规定的比例限制。 基"},{"i":33,"n":"第三十三条","txt":"基金管理人运用基金财产买卖基金管理人、基金托管人及其控股股东、实际控制人或者与其有重大利害关系的公司发行的证券或者承销期内承销的证券，或者从事其他重大关联交易的，应当符合基金的投资目标和投资策略，遵循持有人利益优先原则，防范利益冲突，建立健全内部审批机制和评估机制，按照市场公平合理价格执行。相关交易必须事先得到基金托管人的同意，并按法律法规予以披露。重大关联交易应提交基金管理人董事会审议，并经过三分之二以上的独立董事通过。基金管理人董事会应至少每半年对关联交易事项进行审查。"},{"i":34,"n":"第三十四条","txt":"基金管理人应当自基金合同生效之日起六个月内使基金的投资组合比例符合基金合同的有关约定。期间，基金的投资范围、投资策略应当符合基金合同的约定。"},{"i":35,"n":"第三十五条","txt":"因证券市场波动、上市公司合并、基金规模变动等基金管理人之外的因素致使基金投资不符合本办法第三十二条规定的比例或者基金合同约定的投资比例的，基金管理人应当在十个交易日内进行调整，但中国证监会规定的特殊情形除外。"},{"i":36,"n":"第三十六条","txt":"下列与基金有关的费用可以从基金财产中列支： （一）基金管理人的管理费； （二）基金托管人的托管费； （三）基金合同生效后的会计师费和律师费； （四）基金份额持有人大会费用； （五）基金的证券交易费用； （六）按照国家有关规定和基金合同约定，可以在基金财产中列支的其他费用。 基金管理人可以根据与基金份额持有人利益一致的原则，结合产品特点和投资者的需求设置基金管理费率的结构和水平。"},{"i":37,"n":"第三十七条","txt":"封闭式基金的收益分配，每年不得少于一次，封闭式基金年度收益分配比例不得低于基金年度可供分配利润的百分之九十。 开放式基金的收益分配，由基金合同约定。"},{"i":38,"n":"第三十八条","txt":"基金收益分配应当采用现金方式，但中国证监会规定的特殊基金品种除外。 开放式基金的基金份额持有人可以事先选择将所获分配的现金收益，按照基金合同有关基金份额申购的约定转为基金份额；基金份额持有人事先未做出选择的，基金管理人应当支付现金。"},{"i":39,"n":"第三十九条","txt":"基金转换运作方式或者与其他基金合并，应当按照法律法规及基金合同约定的程序进行。实施方案若未在基金合同中明确约定的，应当经基金份额持有人大会审议通过。基金管理人应当提前发布提示性通知，明确有关实施安排，说明对现有基金份额持有人的影响以及基金份额持有人享有的选择权（如赎回、转出或者卖出），并在实施前预留至少二十个开放日或者交易日供基金份额持有人做出选择。"},{"i":40,"n":"第四十条","txt":"基金注册后，如需对原注册事项进行实质性调整，应当依照法律法规和基金合同履行相关手续；继续公开募集资金的，应当在公开募集前按照《行政许可法》的规定向中国证监会提出变更注册事项的申请。未经注册，不得公开或者变相公开募集基金。"},{"i":41,"n":"第四十一条","txt":"按照本办法第十二条第一款成立的开放式基金，基金合同生效后，连续二十个工作日出现基金份额持有人数量不满二百人或者基金资产净值低于五千万元情形的，基金管理人应当在定期报告中予以披露；连续六十个工作日出现前述情形的，基金管理人应当向中国证监会报告并提出解决方案，如转换运作方式、与其他基金合并或者终止基金合同等，并召开基金份额持有人大会进行表决。 按照本办法第十二条第二款成立的发起式基金，在基金合同生效三年后继续存续的，依照前款规定执行。"},{"i":42,"n":"第四十二条","txt":"除《证券投资基金法》第四十八条第（一）项至第（四）项规定的事项外，基金合同还应当按照中国证监会的规定，约定对基金合同当事人权利、义务产生重大影响，须召开基金份额持有人大会的其他事项。"},{"i":43,"n":"第四十三条","txt":"基金份额持有人大会未设立日常机构的，基金托管人认为有必要召开基金份额持有人大会的，应当向基金管理人提出书面提议。基金管理人应当自收到书面提议之日起十日内决定是否召集，并书面告知基金托管人。 基金管理人决定召集的，应当自出具书面决定之日起六十日内召开；基金管理人决定不召集，基金托管人仍认为有必要召开的，应当自行召集，并自出具书面决定之日起六十日内召开并告知基金管理人，基金管理人应当配合。"},{"i":44,"n":"第四十四条","txt":"基金份额持有人大会未设立日常机构的，代表基金份额百分之十以上的基金份额持有人认为有必要召开基金份额持有人大会的，应当向基金管理人提出书面提议。基金管理人应当自收到书面提议之日起十日内决定是否召集，并书面告知提出提议的基金份额持有人代表和基金托管人。 基金管理人决定召集的，应当自出具书面决定之日起六十日内召开；基金管理人决定不召集，代表基金份额百分之十以上的基金份额持有人仍认为有必要召开的，应当向基金托管人提出书面提议。 基金托管人应当自收到书面提议之日起十日内决定是否召集，并书面告知提出提议的基金份额持有人代表和基金管理人；基金托管人决定召集的，应当自出具书面决定之日起六十日内召开。"},{"i":45,"n":"第四十五条","txt":"基金份额持有人大会设立日常机构的，基金管理人、基金托管人或者代表基金份额百分之十以上的基金份额持有人认为有必要召开基金份额持有人大会的，应当向该日常机构提出书面提议。 该日常机构应当自收到书面提议之日起十日内决定是否召集，并书面告知基金管理人、基金托管人和提出提议的基金份额持有人代表。该日常机构决定召集的，应当自出具书面决定之日起六十日内召开；该日常机构决定不召集，基金管理人、基金托管人或者代表基金份额百分之十以上的基金份额持有人仍认为有必要召开的，按照未设立日常机构的相关规定执行。"},{"i":46,"n":"第四十六条","txt":"基金份额持有人大会日常机构、基金管理人和基金托管人都不召集基金份额持有人大会的，基金份额持有人可以按照《证券投资基金法》第八十四条第二款的规定自行召集基金份额持有人大会。 基金份额持有人自行召集基金份额持有人大会的，应当至少提前三十日向中国证监会备案。"},{"i":47,"n":"第四十七条","txt":"基金份额持有人依法自行召集基金份额持有人大会的，基金份额持有人大会日常机构、基金管理人、基金托管人应当配合，不得阻碍、干扰。"},{"i":48,"n":"第四十八条","txt":"基金份额持有人大会可通过现场开会或者通讯开会等基金合同约定的方式召开。基金管理人、基金托管人须为基金份额持有人行使投票权提供便利。 基金份额持有人大会决定的事项自表决通过之日起生效。基金份额持有人大会按照《证券投资基金法》第八十七条的规定表决通过的事项，召集人应当自通过之日起五日内报中国证监会备案。"},{"i":49,"n":"第四十九条","txt":"基金份额持有人大会日常机构、基金管理人、基金托管人和基金份额持有人应当执行生效的基金份额持有人大会的决定。"},{"i":50,"n":"第五十条","txt":"中国证监会及其派出机构对基金管理人、基金托管人从事基金运作活动的情况进行定期或者不定期检查，基金管理人、基金托管人应当予以配合。"},{"i":51,"n":"第五十一条","txt":"基金管理人、基金托管人及其直接负责的主管人员和其他直接责任人员违反本办法规定从事基金运作活动，依法应予以行政处罚的，依照法律、行政法规的规定进行行政处罚；法律、行政法规未做规定的，依照本办法的规定进行行政处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":52,"n":"第五十二条","txt":"基金管理人、基金托管人违反本办法规定的，中国证监会及其派出机构可以采取监管谈话、出具警示函、责令限期整改，整改期间暂停受理及审查基金产品募集申请或者其他业务申请等行政监管措施，记入诚信档案；对直接负责的主管人员和其他直接责任人员，可以采取监管谈话、出具警示函、暂停履行职务、认定为不适宜担任相关职务者等行政监管措施，记入诚信档案。"},{"i":53,"n":"第五十三条","txt":"基金管理人注册基金，向中国证监会提交的申请材料存在信息自相矛盾、或者就同一事实前后存在不同表述且有实质性差异的，中国证监会将中止审查，并在六个月内不再受理基金管理人提交的基金注册申请。 基金管理人注册基金，向中国证监会提交的申请材料存在虚假记载、误导性陈述、重大遗漏的，中国证监会不予受理；已经受理的，不予注册；已经注册，尚未募集的，撤销注册决定；并在一年内不再受理该基金管理人提交的基金注册申请，对该基金管理人及其直接负责的主管人员和其他直接责任人员，采取相关行政监管措施并记入诚信档案；情节严重的，采取单处或者并处警告、三万元以下罚款。已经注册并募集的，依照《证券投资基金法》第一百三十二条的规定处罚。 基金管理人违反本办法第四十条的规定，在公开募集前未变更注册的，依照《证券投资基金法》第一百二十八条的规定处罚。"},{"i":54,"n":"第五十四条","txt":"基金管理人违反本办法第三十二条的规定运用基金财产进行证券投资、情节严重的，或者违反本办法第三十三条的规定从事关联交易的，依照《证券投资基金法》第一百三十条的规定处罚。"},{"i":55,"n":"第五十五条","txt":"基金管理人、基金托管人不按照本办法第四十二条、第四十三条的规定召集基金份额持有人大会的，依照《证券投资基金法》第一百三十三条的规定处罚。"},{"i":56,"n":"第五十六条","txt":"基金管理人从事基金运作活动，有下列情形之一的，中国证监会可以对基金管理人及其直接负责的主管人员和其他直接责任人员，采取相关行政监管措施并记入诚信档案；情节严重的，可单处或者并处警告、三万元以下罚款： （一）未按照本办法第十一条规定发售基金份额； （二）未按照本办法第十二条规定及时办理验资和基金备案手续； （三）未按照本办法第十五条规定办理申购、赎回业务，涉及损害基金财产和基金份额持有人利益的； （四）未按照本办法第十七条的规定计算基金份额申购、赎回价格； （五） 基金管理人违反本办法第十八条的规定，在基金合同约定之外的日期或者时间办理基金份额的申购、赎回或者转换的； （六）未按照本办法第二十条的规定确认申购、赎回的有效性，并支付赎回款项； （七）未按照本办法第二十三条第二款、第二十四条第一款的规定办理赎回申请； （八）未按照本办法第二十八条的规定保持现金或者政府债券； （九）未按照本办"},{"i":57,"n":"第五十七条","txt":"基金管理人、基金托管人有下列情形之一的，中国证监会可以对基金管理人、基金托管人及其直接负责的主管人员和其他直接责任人员，采取相关行政监管措施并记入诚信档案；情节严重的，可单处或者并处警告、三万元以下罚款： （一）未按照本办法第十四条、第三十六条规定列支相关费用； （二）未按照本办法第四十七条规定配合基金份额持有人召集基金份额持有人大会； （三）未按照本办法第四十八条的规定申请备案基金份额持有人大会决定的事项； （四）未按照本办法第四十九条的规定执行基金份额持有人大会的生效决定； （五）未按照本办法第五十条的规定配合中国证监会及其派出机构进行检查。"},{"i":58,"n":"第五十八条","txt":"证券公司管理的投资者超过二百人的集合资产管理计划须遵守《证券投资基金法》关于管理人及从业人员禁止从事利益输送、非公平交易、内幕交易等规定，并参照本办法关于防范利益冲突、保护投资者的相关规定执行。"},{"i":59,"n":"第五十九条","txt":"本办法自2014年8月8日起施行。《证券投资基金运作管理办法》（证监会令第79号）同时废止。"}],"gongkaimujizhengquantouzijijinxiaoshoujigoujiandug8a243a":[{"i":1,"n":"第一条","txt":"为了规范公开募集证券投资基金（以下简称公募基金或基金）销售机构的销售活动，保护投资人的合法权益，促进基金市场健康发展，根据《证券投资基金法》《证券法》及其他有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称基金销售，是指为投资人开立基金交易账户，宣传推介基金，办理基金份额发售、申购、赎回及提供基金交易账户信息查询等活动。 基金销售机构是指经中国证券监督管理委员会（以下简称中国证监会）或者其派出机构注册，取得基金销售业务资格的机构。未经注册，任何单位或者个人不得从事基金销售业务。 基金服务机构从事与基金销售相关的支付、份额登记、信息技术系统等服务，适用本办法。"},{"i":3,"n":"第三条","txt":"基金销售机构及其从业人员从事基金销售业务，基金服务机构及其从业人员从事与基金销售相关的服务业务，应当遵守法律法规、中国证监会规定以及基金合同、基金销售协议等约定，遵循自愿、公平的原则，诚实守信，谨慎勤勉，廉洁从业，恪守职业道德和行为规范，不得损害国家利益、社会公共利益和投资人的合法权益。"},{"i":4,"n":"第四条","txt":"基金销售结算资金属于投资人，基金销售相关机构不得将基金销售结算资金归入其自有财产。禁止任何单位或者个人以任何形式挪用基金销售结算资金。基金销售相关机构破产或者清算时，基金销售结算资金不属于其破产财产或者清算财产。非因投资人本身的债务或者法律法规规定的其他情形，基金销售结算资金不得被查封、冻结、扣划或者强制执行。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依据法律、行政法规和本办法的规定，对基金销售业务及相关服务业务实施监督管理。 中国证券投资基金业协会依据法律法规和自律规则，对基金销售业务及相关服务业务实施自律管理。"},{"i":6,"n":"第六条","txt":"商业银行、证券公司、期货公司、保险公司、保险经纪公司、保险代理公司、证券投资咨询机构、独立基金销售机构从事基金销售业务的，应当向住所地中国证监会派出机构申请注册基金销售业务资格，并申领《经营证券期货业务许可证》（以下简称业务许可证）。"},{"i":7,"n":"第七条","txt":"申请注册基金销售业务资格，应当具备下列条件： （一）财务状况良好，运作规范； （二）有与基金销售业务相适应的营业场所、安全防范等设施，办理基金销售业务的信息管理平台符合中国证监会的规定； （三）具备健全高效的业务管理和风险管理制度，反洗钱、反恐怖融资及非居民金融账户涉税信息尽职调查等制度符合法律法规要求，基金销售结算资金管理、投资者适当性管理、内部控制等制度符合中国证监会的规定； （四）取得基金从业资格的人员不少于20人； （五）最近3年没有受到刑事处罚或者重大行政处罚；最近1年没有因相近业务被采取重大行政监管措施；没有因重大违法违规行为处于整改期间，或者因涉嫌重大违法违规行为正在被监管机构调查；不存在已经影响或者可能影响公司正常运作的重大变更事项，或者重大诉讼、仲裁等事项； （六）中国证监会规定的其他条件。"},{"i":8,"n":"第八条","txt":"商业银行、证券公司、期货公司、保险公司、保险经纪公司、保险代理公司、证券投资咨询机构申请注册基金销售业务资格，应当具备下列条件： （一）本办法第七条规定的条件； （二）有负责基金销售业务的部门； （三）财务风险监控等监管指标符合国家金融监督管理部门的规定； （四）负责基金销售业务的部门取得基金从业资格的人员不低于该部门员工人数的1/2，部门负责人取得基金从业资格，并具备从事基金业务2年以上或者在金融机构5年以上的工作经历；分支机构基金销售业务负责人取得基金从业资格； （五）中国证监会规定的其他条件。"},{"i":9,"n":"第九条","txt":"独立基金销售机构是专业从事公募基金及私募证券投资基金销售业务的机构。独立基金销售机构不得从事其他业务，中国证监会另有规定的除外。 申请注册为独立基金销售机构的，应当具备下列条件： （一）本办法第七条规定的条件； （二）为依法设立的有限责任公司、股份有限公司或者采取符合中国证监会规定的其他组织形式； （三）有符合规定的名称、组织架构和经营范围； （四）股东以自有资金出资，不得以债务资金、委托资金等非自有资金出资，境外股东以可自由兑换货币出资； （五）净资产不低于5000万元人民币； （六）高级管理人员取得基金从业资格，熟悉基金销售业务，符合中国证监会规定的基金行业高级管理人员任职条件； （七）中国证监会规定的其他条件。"},{"i":10,"n":"第十条","txt":"持有独立基金销售机构5%以上股权的股东，应当具备下列条件： （一）股东为法人或者非法人组织的，资产质量良好，除中国证监会另有规定外净资产不低于5000万元人民币；股权结构清晰，可逐层穿透至最终权益持有人；最近3年没有受到刑事处罚或者重大行政处罚；最近1年没有被采取重大行政监管措施；没有因重大违法违规行为处于整改期间，或者因涉嫌重大违法违规行为正在被监管机构调查； （二）股东为自然人的，具备担任证券基金业务部门管理人员5年以上的工作经历或者担任证券基金行业高级管理人员3年以上的工作经历；从业期间没有被金融监管部门采取重大行政监管措施、没有因重大违法违规行为受到行政处罚或者刑事处罚； （三）中国证监会规定的其他条件。 独立基金销售机构的境外股东，还应当具备下列条件： （一）依其所在国家或者地区法律设立，合法存续的具有资产管理或者投资顾问经验的金融机构； （二）其所在国家或者地区的证券监管机"},{"i":11,"n":"第十一条","txt":"独立基金销售机构的控股股东，应当具备下列条件： （一）股东为法人或者非法人组织的，应当核心主业突出，内部控制完善，运作规范稳定，最近3个会计年度连续盈利，净资产不低于2亿元人民币，具有良好的财务状况和资本补充能力；资产负债与杠杆水平适度，净资产不低于实收资本的50%，或有负债未达到净资产的50%，没有数额较大的到期未清偿债务； （二）股东为自然人的，个人金融资产不低于3000万元人民币；具备担任证券基金业务部门管理人员10年以上的工作经历或者担任证券基金行业高级管理人员5年以上的工作经历； （三）制定合理明晰的投资独立基金销售机构的商业计划，对完善独立基金销售机构治理结构、保持独立基金销售机构经营管理的独立性、推动独立基金销售机构长期发展有切实可行的计划安排；对独立基金销售机构可能发生风险导致无法正常经营的情况，制定合理有效的风险处置预案； （四）中国证监会规定的其他条件。"},{"i":12,"n":"第十二条","txt":"独立基金销售机构股东以及股东的控股股东、实际控制人参股独立基金销售机构的数量不得超过2家，其中控制独立基金销售机构的数量不得超过1家。中国证监会另有规定的情形除外。"},{"i":13,"n":"第十三条","txt":"独立基金销售机构应当保持股权结构稳定。股权相关方应当书面承诺，独立基金销售机构取得基金销售业务资格3年内不发生控股股东、实际控制关系的变更。 股东质押所持独立基金销售机构股权的，不得约定由质权人或者其他第三方行使表决权等股东权利，也不得变相转移对独立基金销售机构股权的控制。持有独立基金销售机构5%以上股权的股东，质押股权比例不得超过所持该独立基金销售机构股权比例的50%。"},{"i":14,"n":"第十四条","txt":"基金销售机构申请注册基金销售业务资格，应当按照中国证监会的规定提交申请材料。申请材料应当真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏。申请材料所涉事项发生重大变化的，申请人应当在5个工作日内提交更新材料。 中国证监会派出机构依照《行政许可法》规定受理基金销售业务资格注册申请，并进行审查，作出注册或者不予注册的决定。"},{"i":15,"n":"第十五条","txt":"基金销售机构办理基金销售业务，应当与基金管理人签订书面销售协议，明确双方权利义务。未经签订书面销售协议，基金销售机构不得办理基金的销售。"},{"i":16,"n":"第十六条","txt":"基金销售机构开展基金宣传推介活动，应当坚持长期投资理念和客观、真实、准确的原则。 基金销售机构应当集中统一制作和使用基金宣传推介材料，并对内容的合规性进行内部审查，相关审查材料应当存档备查。基金宣传推介材料的管理规范，由中国证监会另行制定。"},{"i":17,"n":"第十七条","txt":"基金销售机构应当按照中国证监会的规定了解投资人信息，坚持投资人利益优先和风险匹配原则，根据投资人的风险承担能力销售不同风险等级的产品，把合适的基金产品销售给合适的投资人。 基金销售机构应当加强投资者教育，引导投资人充分认识基金产品的风险收益特征。投资人购入基金前，基金销售机构应当提示投资人阅读基金合同、招募说明书、基金产品资料概要，提供有效途径供投资人查询，并以显著、清晰的方式向投资人揭示投资风险。 基金销售机构应当推动定期定额投资、养老储备投资等业务发展，促进投资人稳健投资，杜绝诱导投资人短期申赎、频繁申赎行为。"},{"i":18,"n":"第十八条","txt":"基金销售机构应当根据反洗钱、反恐怖融资及非居民金融账户涉税信息尽职调查等法律法规要求履行相关职责，有效识别投资人身份，核对投资人的有效身份证件，登记投资人身份基本信息，确保基金账户持有人名称与有效身份证件中记载的名称一致，留存有效身份证件的复印件或者影印件，了解投资人资金来源的合法性，向基金管理人提供客户法定基本身份信息等反洗钱必要信息，并为基金管理人履行反洗钱、反恐怖融资及非居民金融账户涉税信息尽职调查等相关职责提供协助。"},{"i":19,"n":"第十九条","txt":"基金销售机构应当按照法律法规、中国证监会的规定和基金合同、份额发售公告、招募说明书等文件的约定，办理基金份额的认购、申购和赎回，不得擅自拒绝接受投资人的申请。 投资人认购、申购基金份额，应当全额交付款项，中国证监会规定的特殊基金品种除外。 投资人在基金合同约定之外的日期和时间提出申购、赎回申请的，作为下一个交易日的交易处理，其基金份额申购、赎回价格为下次办理基金份额申购、赎回时间所在开放日的价格。"},{"i":20,"n":"第二十条","txt":"基金销售机构、基金销售支付机构应当按照法律法规、基金合同和基金销售协议等的规定，归集、划转基金销售结算资金，确保基金销售结算资金安全、及时划付，并将赎回、分红及未成功认购、申购的款项划入投资人认购、申购时使用的结算账户。中国证监会就特殊基金品种、特殊业务类型另有规定的，从其规定。"},{"i":21,"n":"第二十一条","txt":"基金销售机构应当按照法律法规和中国证监会规定以及基金合同、招募说明书和基金销售协议等的约定收取销售费用，并如实核算、记账；未经招募说明书载明，不得对不同投资人适用不同费率。 基金销售机构按照中国证监会的规定，为投资人提供除基金合同、招募说明书约定服务以外的增值服务的，可以向投资人收取增值服务费。"},{"i":22,"n":"第二十二条","txt":"基金销售机构应当按照下列要求持续为投资人提供信息服务： （一）及时告知投资人其认购、申购、赎回的基金名称以及基金份额的确认日期、确认份额和金额等信息； （二）提供有效途径供投资人实时查询其所持基金的基本信息； （三）定期向投资人主动提供基金保有情况信息； （四）按照中国证监会的规定，做好有关信息传递工作，向投资人及时提供对其投资决策有重大影响的信息； （五）中国证监会规定的其他要求。 基金销售机构应当与投资人约定提供前款规定信息的方式。"},{"i":23,"n":"第二十三条","txt":"基金销售机构可以委托其他基金销售机构办理基金销售中后台处理等活动，具体规定由中国证监会另行制定。"},{"i":24,"n":"第二十四条","txt":"基金销售机构及其从业人员从事基金销售业务，不得有下列情形： （一）虚假记载、误导性陈述或者重大遗漏； （二）违规承诺收益、本金不受损失或者限定损失金额、比例； （三）预测基金投资业绩，或者宣传预期收益率； （四）误导投资人购买与其风险承担能力不相匹配的基金产品； （五）未向投资人有效揭示实际承担基金销售业务的主体、所销售的基金产品等重要信息，或者以过度包装服务平台、服务品牌等方式模糊上述重要信息； （六）采取抽奖、回扣或者送实物、保险、基金份额等方式销售基金； （七）在基金募集申请完成注册前，办理基金销售业务，向公众分发、公布基金宣传推介材料或者发售基金份额； （八）未按照法律法规、中国证监会规定、招募说明书和基金份额发售公告规定的时间销售基金，或者未按照规定公告即擅自变更基金份额的发售日期； （九）挪用基金销售结算资金或者基金份额；违规利用基金份额转让等形式规避基金销售结算资金闭环运"},{"i":25,"n":"第二十五条","txt":"基金销售机构应当按照审慎经营的原则，建立健全并有效执行基金销售业务的内部控制与风险管理制度，完善内部责任追究机制，确保基金销售业务符合法律法规和中国证监会的规定。"},{"i":26,"n":"第二十六条","txt":"基金销售机构应当指定专门合规风控人员对基金销售业务的经营运作情况进行审查、监督和检查，并保障合规风控人员履职的独立性和有效性。合规风控人员应当具备与履职相适应的专业知识和技能，不得兼任与合规风控职责相冲突的职务。 合规风控人员应当对基金销售业务内部制度、基金宣传推介材料和新销售产品、新业务方案等进行合规审查，出具合规审查意见，并存档备查。 基金销售机构应当于每一年度结束之日起3个月内完成年度监察稽核报告，并存档备查。"},{"i":27,"n":"第二十七条","txt":"基金销售机构应当对基金管理人、基金产品进行审慎调查和风险评估，充分了解产品的投资范围、投资策略、风险收益特征等，并设立产品准入委员会或者专门小组，对销售产品准入实行集中统一管理。 基金管理人应当制定基金销售机构准入的标准和程序，审慎选择基金销售机构，并定期开展再评估。"},{"i":28,"n":"第二十八条","txt":"基金销售机构应当建立健全投资人基金交易账户和资金账户管理制度，保障投资人信息安全和资金安全。"},{"i":29,"n":"第二十九条","txt":"基金销售机构应当确保基金销售信息管理平台安全、高效运行，建立符合规定的灾难备份系统和应急预案。"},{"i":30,"n":"第三十条","txt":"基金销售机构应当建立健全基金销售业务内部考核机制，坚持以投资人利益为核心和长期投资的理念，将基金销售保有规模、投资人长期投资收益等纳入分支机构和基金销售人员考核评价指标体系，并加大对存量基金产品持续销售、定期定额投资等业务的激励安排，不得将基金销售收入作为主要考核指标，不得实施短期激励，不得针对认购期基金实施特别的考核激励。 基金销售机构应当强化人员资质管理，确保基金销售人员具有基金从业资格。未经基金销售机构聘任，任何人员不得从事基金销售活动，中国证监会另有规定的除外。 基金销售机构应当建立健全基金销售人员持续培训机制，加强对基金销售人员行为的监督和检查，并建立相关人员的离任审计或者离任审查制度。基金销售人员不得从事与基金销售业务有利益冲突的业务活动。"},{"i":31,"n":"第三十一条","txt":"基金销售机构应当建立健全业务范围管控制度，审慎评估基金销售业务与其依法开展或者拟开展的其他业务之间可能存在的利益冲突，完善利益冲突防范机制。 基金销售机构应当采取有效隔离措施，避免因其他业务风险影响基金销售业务稳健运行。 基金销售机构应当保持对基金销售业务的持续投入，确保实质展业及业务连续性。"},{"i":32,"n":"第三十二条","txt":"基金销售机构应当对分支机构基金销售活动、基金销售信息技术系统实行集中统一管理，不得与他人合资、合作经营管理分支机构，不得将分支机构承包或者委托给他人经营管理。"},{"i":33,"n":"第三十三条","txt":"基金销售机构应当建立健全档案管理制度，妥善保管投资人的开户资料和与基金销售业务有关的其他资料。投资人身份资料自业务关系结束当年计起至少保存20年，与基金销售业务有关的其他资料自业务发生当年计起至少保存20年。"},{"i":34,"n":"第三十四条","txt":"独立基金销售机构应当建立健全合规风控管理组织架构，在章程中明确合规风控负责人为高级管理人员，并对其职责、任免条件和程序作出规定。 合规风控负责人应当具有胜任合规风控管理工作需要的专业知识和技能，并具备以下工作经历：从事证券基金工作5年以上，或者从事证券基金工作3年以上并且通过国家法律职业资格考试，或者从事证券基金监管相关工作3年以上。 独立基金销售机构解聘合规风控负责人，应当具有正当理由，并自解聘之日起3个工作日内将解聘事实和理由书面报告住所地中国证监会派出机构。"},{"i":35,"n":"第三十五条","txt":"独立基金销售机构应当设立专门的合规风控管理部门。合规风控管理部门对合规风控负责人负责，按照公司规定和合规风控负责人的安排履行合规风控管理职责。合规风控管理部门不得承担与合规风控管理相冲突的其他职责。 独立基金销售机构应当为合规风控管理部门配备足够的、具备与履行合规风控管理职责相适应的专业知识和技能的合规风控人员。"},{"i":36,"n":"第三十六条","txt":"独立基金销售机构应当确保业务、从业人员、经营场所的独立性，不得与股东、实际控制人、关联方混同，不得允许其他任何机构以其名义对外开展业务。独立基金销售机构从业人员不得在其他机构担任经营性职务，法律法规和中国证监会另有规定的除外。"},{"i":37,"n":"第三十七条","txt":"独立基金销售机构设立分支机构，应当具备下列条件： （一）连续开展基金销售业务3个完整会计年度以上，最近一个会计年度基金销售日均保有量不低于100亿元； （二）具有较强的持续经营能力，内部控制完善，能够有效控制分支机构风险； （三）制定合理明晰的分支机构设立规划； （四）最近3年没有受到刑事处罚或者重大行政处罚；最近1年没有被采取重大行政监管措施；没有因重大违法违规行为处于整改期间，或者因涉嫌重大违法违规行为正在被监管机构调查； （五）拟设立的分支机构具备完善的管理制度，有符合规定的办公场所、安全防范等设施，取得基金从业资格的人员不少于5人； （六）中国证监会规定的其他条件。 独立基金销售机构设立的分支机构，限于住所地所在省、自治区、直辖市范围，中国证监会另有规定的除外。 独立基金销售机构应当完善分支机构管控机制，确保分支机构实质展业及业务连续性。"},{"i":38,"n":"第三十八条","txt":"独立基金销售机构应当制定自有资金运用制度，保持良好的财务状况，满足日常运营和风险防范的需要。 独立基金销售机构可以运用自有资金进行金融资产投资，其中投资于现金、银行存款、国债、基金等高流动性资产的净值不得低于2000万元。独立基金销售机构不得向关联方提供借款、资金垫付或者担保等；不得进行股权投资，法律法规、中国证监会另有规定的除外。"},{"i":39,"n":"第三十九条","txt":"基金销售支付机构受基金销售机构委托，为基金销售机构提供基金销售结算资金划转服务。 基金销售机构应当选择具备下列条件的商业银行或者支付机构办理基金销售支付业务： （一）制定了有效的风险控制制度，有安全、高效的办理支付业务的信息系统； （二）商业银行取得基金销售业务资格，支付机构取得《支付业务许可证》； （三）最近3年没有受到刑事处罚或者重大行政处罚；最近1年没有被采取重大行政监管措施；没有因重大违法违规行为处于整改期间，或者因涉嫌重大违法违规行为正在被监管机构调查； （四）中国证监会规定的其他条件。 支付机构从事基金销售支付业务，应当向中国证监会备案。"},{"i":40,"n":"第四十条","txt":"基金销售结算资金监督机构受基金销售机构、基金销售支付机构等委托，对其开立、使用基金销售结算专用账户的行为和基金销售结算资金划转流程进行监督。 中国证券登记结算有限责任公司（以下简称中国结算）或者取得基金销售业务资格的商业银行可以担任基金销售结算资金监督机构。基金销售机构、基金销售支付机构等应当在基金销售结算资金监督机构开立基金销售结算专用账户，并与基金销售结算资金监督机构签订监督协议，对账户性质、账户功能、资金划转流程、监督方式、账户异常处理等事项做出约定。中国证监会另有规定的，从其规定。"},{"i":41,"n":"第四十一条","txt":"基金管理人可以依照中国证监会的规定委托基金份额登记机构办理基金份额登记业务。基金份额登记机构应当确保基金份额的登记、存管和结算业务处理安全、准确、及时、高效，其主要职责包括： （一）建立并管理投资人基金份额账户； （二）负责基金份额的登记； （三）基金交易确认； （四）代理发放红利； （五）建立并保管基金份额持有人名册； （六）服务协议约定的其他职责； （七）中国证监会规定的其他职责。 基金管理人变更基金份额登记机构的，应当在变更完成10个工作日内向中国证监会报告。"},{"i":42,"n":"第四十二条","txt":"基金销售机构、基金份额登记机构应当通过中国结算建设和运营的基金行业注册登记数据中央交换平台（以下简称中央数据交换平台）对基金的账户和交易信息进行数据交换，数据交换应当符合中央数据交换平台相关规范要求。参与数据交换的相关机构应当按照规定保障信息传输和存储的完整性、准确性、及时性、安全性。 基金份额登记机构应当按照中央数据交换平台相关规范要求报送基金份额登记数据，配合完成基金份额登记数据的集中备份。 中国结算依据中国证监会授权，对相关数据交换及报送实施自律管理。中国结算应当妥善保存相关数据，不得篡改、毁损或者泄露；确有必要向第三方提供的，应当遵守法律法规和中国证监会的规定。中国结算还应当建立健全相关信息统计分析制度，定期向中国证监会报告，并按照中国证监会的要求向投资人提供统一查询等服务。"},{"i":43,"n":"第四十三条","txt":"信息技术系统服务机构受基金销售机构委托，为基金销售机构提供网络空间经营场所租用或者信息技术系统开发等服务。信息技术系统服务机构不得实质介入基金销售业务环节，不得收集、传输、留存投资人基金交易信息。"},{"i":44,"n":"第四十四条","txt":"基金销售机构除开展公募基金销售业务外，依法从事私募基金销售业务的，参照适用本办法第三章、第四章的规定，法律法规及中国证监会另有规定的除外。"},{"i":45,"n":"第四十五条","txt":"基金销售机构应当以非公开方式向合格投资者销售私募基金，不得通过公众传播媒体、互联网、公开营业场所等平台或者手机短信、微信等渠道公开或者变相公开宣传推介私募基金。"},{"i":46,"n":"第四十六条","txt":"基金销售机构销售私募基金，应当充分了解投资人信息，收集、核验投资人资产证明、收入证明或者纳税凭证等材料，对投资人风险识别能力和风险承担能力进行评估，并要求投资人承诺投资资金为自有资金，不存在非法汇集他人资金等情况。 基金销售机构应当就合格投资者确认、投资者适当性匹配、风险揭示、自有资金投资等事项履行投资人签字确认等程序。"},{"i":47,"n":"第四十七条","txt":"基金销售机构应当销售符合法律法规和中国证监会规定的私募基金，对拟销售私募基金进行审慎调查和风险评估，充分了解产品的投资范围、投资策略、投资集中度、杠杆水平、风险收益特征等。销售文件应当按照规定全面说明产品特征并充分揭示风险。基金销售机构不得销售未在产品合同等法律文件中明确限定投资范围、投资集中度、杠杆水平的私募基金。 基金销售机构合规风控人员应当对私募基金销售准入出具专项合规和风险评估报告，签字确认并存档备查。"},{"i":48,"n":"第四十八条","txt":"基金销售机构应当针对私募基金销售业务建立专门的利益冲突识别、评估和防范机制。 基金销售机构应当对存在关联关系的私募基金管理人及私募基金履行严格的利益冲突评估机制，经评估无法有效防范利益冲突的，不得销售相关产品；经评估确定可以销售的，应当以书面形式向投资人充分披露，并在销售行为发生时由投资人签字确认。"},{"i":49,"n":"第四十九条","txt":"基金销售机构应当参照本办法第四十条的规定开立私募基金销售结算专用账户，并参照中国证监会规定的基金销售结算资金划转流程进行资金交收。"},{"i":50,"n":"第五十条","txt":"中国证监会及其派出机构按照审慎监管原则，可以要求基金销售相关机构及其股东、实际控制人报送相关信息、材料，定期或者不定期对基金销售相关机构从事基金销售业务及相关服务业务的情况进行非现场或者现场检查。 基金销售相关机构及其股东、实际控制人、从业人员等应当配合检查、调查，提供的信息、资料应当及时、真实、准确、完整。"},{"i":51,"n":"第五十一条","txt":"独立基金销售机构发生下列事项的，应当在5个工作日内向住所地中国证监会派出机构备案： （一）变更公司章程、名称、住所、组织形式、经营范围、注册资本、高级管理人员； （二）新增持有5%以上股权的股东，变更控股股东、实际控制人； （三）持有5%以上股权的股东变更姓名、名称，或者质押所持独立基金销售机构的股权； （四）设立、撤销分支机构，变更分支机构名称、营业场所； （五）对外进行股权投资或者提供担保； （六）中国证监会规定的其他事项。 住所地中国证监会派出机构收到备案材料后应当进行核查，发现备案事项不符合法律、行政法规及中国证监会规定的，应当责令整改。"},{"i":52,"n":"第五十二条","txt":"基金销售机构的业务许可证自颁发之日起，有效期3年。基金销售机构不存在下列情形的，其业务许可证有效期予以延续，每次延续的有效期为3年： （一）无法持续符合本办法第七条第（一）项至第（四）项规定的基础性展业条件，且未得到有效整改； （二）合规内控严重缺失，被中国证监会或者其派出机构采取责令暂停办理相关业务的行政监管措施，且未在要求期限内有效整改； （三）未实质开展公募基金销售业务，最近一个会计年度基金（货币市场基金除外）销售日均保有量低于5亿元； （四）中国证监会规定的其他情形。 基金销售机构存在本条第一款所列情形的，中国证监会派出机构可作出不予延续其业务许可证有效期的决定。业务许可证有效期届满的基金销售机构，不得继续从事基金销售业务。"},{"i":53,"n":"第五十三条","txt":"基金销售相关机构违反法律、行政法规、本办法及中国证监会其他规定，法律法规有规定的，依照其规定处理；法律法规没有规定的，中国证监会及其派出机构可以采取监管谈话、出具警示函、责令改正、责令处分有关人员、责令暂停办理相关业务等行政监管措施，对相关主管人员、直接责任人员，可以采取监管谈话、出具警示函、公开谴责、认定为不适当人选等行政监管措施，发现违法行为涉嫌犯罪的，移送司法机关处理。"},{"i":54,"n":"第五十四条","txt":"中国证监会及其派出机构依法责令基金销售机构暂停办理相关业务的，可以责令其暂停下列一项或者多项业务： （一）接受新投资人开立交易账户申请； （二）签订新的销售协议，增加销售新产品； （三）办理公募基金份额认购、申购或者私募基金份额参与。 基金销售机构被责令暂停办理相关业务的，可以办理销户、赎回、转托管转出等业务。"},{"i":55,"n":"第五十五条","txt":"基金销售机构申请注册基金销售业务资格，隐瞒有关情况或者提供虚假材料的，中国证监会派出机构不予注册，并给予警告；已经注册的，撤销注册，对相关主管人员和其他直接责任人员给予警告，并处3万元以下罚款。国家金融监督管理部门监管的机构存在上述情况的，移交相关金融监督管理部门处理。"},{"i":56,"n":"第五十六条","txt":"基金销售机构有下列情形的，依照《证券投资基金法》第一百三十七条、第一百三十九条、第一百四十四条规定处理： （一）未向投资人充分揭示投资风险并误导其购买与其风险承担能力不相当的公募基金、私募证券投资基金等产品的； （二）挪用公募基金、私募证券投资基金等产品销售结算资金或者份额的； （三）未按照本办法第四章要求建立风险管理制度和灾难备份系统，存在重大风险隐患、引发重大风险事件或者丧失经营能力的； （四）泄露与公募基金、私募证券投资基金等产品份额持有人、投资运作相关的非公开信息的。"},{"i":57,"n":"第五十七条","txt":"基金销售机构有下列情形之一，且情节严重的，除法律法规另有规定外，给予警告，并处3万元以下罚款；对相关主管人员和其他直接责任人员，给予警告，并处3万元以下罚款： （一）违反本办法第十五条至第二十二条、第二十四条规定从事基金销售业务的； （二）未按照本办法第四章规定建立健全并有效执行基金销售业务内部控制及风险管理制度的； （三）未按照本办法第四十条规定与基金销售结算资金监督机构签订监督协议、开立基金销售结算专用账户的； （四）未按照本办法第四十二条规定进行数据交换和报送的； （五）违反本办法第六章规定销售私募基金的； （六）未按照本办法第五十条、五十一条规定，配合监督检查、履行备案报告义务的。"},{"i":58,"n":"第五十八条","txt":"基金销售机构有下列情形之一的，中国证监会依法注销其业务许可证，并予以公告： （一）业务许可证有效期不予延续且有效期届满的； （二）基金销售业务资格被依法撤销或者终止的； （三）基金销售机构依法终止的； （四）法律法规规定的其他情形。"},{"i":59,"n":"第五十九条","txt":"基金销售机构有下列情形之一的，基金管理人等应当妥善办理有关投资人的赎回、转托管转出等业务，基金销售相关机构应当配合： （一）业务许可证被注销的； （二）丧失经营能力，无法为投资人办理基金销售业务的； （三）中国证监会规定的其他情形。"},{"i":60,"n":"第六十条","txt":"基金销售支付机构从事公募基金、私募证券投资基金销售支付业务有下列情形的，依照《证券投资基金法》第一百三十八条、第一百三十九条、第一百四十四条规定处理： （一）未按照规定划付公募基金、私募证券投资基金等产品销售结算资金的； （二）挪用公募基金、私募证券投资基金等产品销售结算资金或者份额的； （三）未建立风险管理制度和灾难备份系统的； （四）泄露与公募基金、私募证券投资基金等产品份额持有人、投资运作相关的非公开信息的。 基金销售支付机构被停止基金销售支付业务的，基金销售机构和基金销售结算资金监督机构应当妥善处理有关投资人基金份额的赎回、转托管转出等业务。"},{"i":61,"n":"第六十一条","txt":"本办法相关用语的含义如下： （一）基金销售相关机构，包括基金销售机构，以及从事与基金销售相关的支付、份额登记、信息技术系统等服务业务的基金服务机构。 （二）基金销售结算资金，是指由基金销售机构、基金销售支付机构、基金份额登记机构等基金销售相关机构归集的，在投资人结算账户与基金财产托管账户之间划转的基金认购、申购、赎回、分红等资金。 （三）独立基金销售机构高级管理人员，是指总经理、副总经理或者实际履行上述职务的其他人员，以及章程规定的其他人员。 （四）关联方及控制关系，依照《企业会计准则》确定。 （五）基金宣传推介材料，是指为推介基金向公众分发或者公布，使公众可以普遍获得的纸质、电子或者其他介质的信息。 （六）基金销售结算专用账户，是指基金销售机构、基金销售支付机构或者基金份额登记机构用于归集、暂存、划转基金销售结算资金的专用账户。 （七）支付机构，是指依据中国人民银行《非金融机构支付服"},{"i":62,"n":"第六十二条","txt":"基金管理人、证券期货经营机构销售其管理的基金、私募资产管理计划的业务规范、内部控制和风险管理，适用本办法和中国证监会其他相关规定。"},{"i":63,"n":"第六十三条","txt":"本办法自2020年10月1日起施行。《证券投资基金销售管理办法》（证监会令第91号）同时废止。"}],"gongkaimujizhengquantouzijijinfengxianzhunbeijinjifd89a7":[{"i":1,"n":"第一条","txt":"为保护公开募集证券投资基金（以下简称基金）份额持有人的合法权益，增强基金行业风险防范能力，促进基金管理人及托管人规范经营和持续发展，根据《证券投资基金法》及其他有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中国境内依法设立的基金管理人与托管人，应当从基金管理费或者托管费收入中计提风险准备金。"},{"i":3,"n":"第三条","txt":"风险准备金主要用于弥补因基金管理人或托管人违法违规、违反基金合同、操作错误或因技术故障等原因给基金财产或基金份额持有人造成的损失，以及中国证券监督管理委员会（以下简称中国证监会）规定的其他用途。风险准备金不足以赔偿上述损失的，基金管理人与托管人应当使用其他自有财产进行赔偿。"},{"i":4,"n":"第四条","txt":"中国证监会依法对基金管理人与托管人风险准备金提取、投资运作、使用等活动进行监督管理。"},{"i":5,"n":"第五条","txt":"基金管理人应当每月从基金管理费收入中计提风险准备金，计提比例不得低于基金管理费收入的10%。风险准备金余额达到上季末管理基金资产净值的1%时可以不再提取。风险准备金余额高于上季末管理基金资产净值1%的，基金管理人可以申请转出部分资金，但转出后的风险准备金余额不得低于上季末管理基金资产净值的1%。"},{"i":6,"n":"第六条","txt":"基金托管人应当每月从基金托管费收入中计提风险准备金，计提比例不得低于基金托管费收入的2.5%。风险准备金余额达到上季末托管基金资产净值的0.25%时可以不再提取。风险准备金余额高于上季末托管基金资产净值0.25%的，基金托管人可以申请转出部分资金，但转出后的风险准备金余额不得低于上季末托管基金资产净值的0.25%。"},{"i":7,"n":"第七条","txt":"中国证监会可根据对基金管理人的综合评价结果，要求综合评价较低、风险较为突出的基金管理人提高风险准备金的计提比例或一次性补足一定金额的风险准备金。"},{"i":8,"n":"第八条","txt":"基金管理人与托管人应当选定一家具有基金托管资格的商业银行（以下简称存管银行）开立专门的风险准备金账户（以下简称风险准备金专户），用于风险准备金的归集、存放与支付。该账户不得与其他类型账户混用，不得存放其他性质资金。 商业银行基金托管人不得在本行开立风险准备金专户。"},{"i":9,"n":"第九条","txt":"基金管理人应当将风险准备金专户及风险准备金的提取、划转等程序告知相关基金托管人。相关基金托管人应当于每月划付基金管理人管理费用的同时，将计提的风险准备金划入相应的风险准备金专户。 基金托管人应当于每月划付基金托管人托管费用的同时，将计提的风险准备金划入相应的风险准备金专户。"},{"i":10,"n":"第十条","txt":"基金管理人发生需要使用风险准备金的情形时，应当经相关基金托管人复核后，交由风险准备金存管银行办理。基金管理人应在使用风险准备金后2个工作日内将相关情况书面报告中国证监会，并在基金管理人监察稽核季度报告中予以说明。 基金托管人发生需要使用风险准备金的情形时，应当经相关基金管理人复核后，交由风险准备金存管银行办理。基金托管人应在使用风险准备金后2个工作日内将相关情况书面报告中国证监会，并在基金托管人托管业务运营情况季度报告中予以说明。"},{"i":11,"n":"第十一条","txt":"风险准备金被人民法院依法查封、扣押、冻结或强制执行的，风险准备金存管银行以及相关基金管理人与托管人应当立即报告中国证监会。由此影响风险准备金的使用或者风险准备金减少的，基金管理人与托管人应在5个工作日内予以补足。"},{"i":12,"n":"第十二条","txt":"风险准备金属特定用途资金，基金管理人与托管人不得以任何形式擅自占用、挪用或借用。"},{"i":13,"n":"第十三条","txt":"在保证安全性与流动性的前提下，基金管理人与托管人可以对已提取的风险准备金进行自主投资管理或开展一定形式的委托投资。风险准备金投资应遵循分散化组合投资原则，事先约定各投资品种的投资比例等限制。"},{"i":14,"n":"第十四条","txt":"基金管理人风险准备金可投资于银行存款、国债、中央银行票据、中央企业债券、中央级金融机构发行的金融债券，以及中国证监会规定的其他投资品种。风险准备金专户应当保持不低于风险准备金总额10%的现金或者到期日在一年以内的政府债券。 基金托管人风险准备金的投资管理活动在符合所在行业监管机构有关规定的基础上参照上述要求执行。"},{"i":15,"n":"第十五条","txt":"风险准备金投资管理产生的各类投资损益，应纳入风险准备金管理。风险准备金投资运作和使用过程中发生的各项费用和税收，可以由风险准备金承担。"},{"i":16,"n":"第十六条","txt":"风险准备金投资于本管理人管理或本托管人托管的基金，或者用于弥补基金财产相关损失等法定用途的，应当依法在相关基金的定期报告中披露。"},{"i":17,"n":"第十七条","txt":"风险准备金投资于本管理人管理或本托管人托管的基金的，基金管理人或基金托管人依法可以作为基金份额持有人向基金份额持有人大会提出议案，但对涉及本管理人或本托管人利益的表决事项应当回避。"},{"i":18,"n":"第十八条","txt":"基金管理人与托管人应当建立完备的风险准备金管理制度，对风险准备金的提取、划转、投资管理、使用、支付等方面的程序进行规定，并留存备查。"},{"i":19,"n":"第十九条","txt":"基金管理人与托管人应当将风险准备金管理制度及时报送风险准备金存管银行。风险准备金存管银行应当制定完备规范的风险准备金专户监控管理规则，对基金管理人与托管人风险准备金的提取、投资运作和使用等情况进行监督，确保资金存放安全，提取、投资运作和使用符合相关规定。"},{"i":20,"n":"第二十条","txt":"风险准备金存管银行应当于每年结束之日起一个月内，向中国证监会提交上年度所存管风险准备金的提取、投资管理、支付使用、年末结余等情况的专项报告。 基金管理人与托管人应在管理人监察稽核年度报告及托管人托管业务运营情况年度报告中对上年度风险准备金的提取、投资管理、使用、年末结余等情况作专项说明。"},{"i":21,"n":"第二十一条","txt":"对没有按照规定提取、管理或使用风险准备金的基金管理人、托管人，中国证监会可以依法对其采取责令改正、暂不受理与行政许可有关的文件等行政监管措施；对直接负责的主管人员和其他直接责任人员，采取监管谈话、出具警示函、认定为不适当人选等行政监管措施；依法应予行政处罚的，依照有关规定进行行政处罚；涉嫌犯罪的，依法移送司法机关，追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"本办法自2014 年 1月1 日起施行。《关于基金管理公司提取风险准备金有关问题的通知》（证监基金字[2006]154号）、《关于修改〈关于基金管理公司提取风险准备金有关问题的通知〉的决定》（中国证监会公告[2008]46号）同时废止。"}],"guanyuqihuojiaoyiguanlitiaolidiqishitiaodiwuxiangq0614f5":[{"i":1,"n":"第一条","txt":"为防范和打击操纵期货交易价格违法行为，依据《期货交易管理条例》第四十六条和第七十条，制定本规定。"},{"i":2,"n":"第二条","txt":"不以成交为目的，频繁申报、撤单或者大额申报、撤单，影响期货交易价格或者期货交易量，并进行与申报方向相反的交易或者谋取相关利益的，构成操纵。"},{"i":3,"n":"第三条","txt":"编造、传播虚假信息或者误导性信息，影响期货交易价格或者期货交易量，并进行相关交易或者谋取相关利益的，构成操纵。"},{"i":4,"n":"第四条","txt":"对合约或合约标的物作出公开评价、预测或者投资建议，影响期货交易价格或者期货交易量，并进行与其评价、预测或者投资建议方向相反的期货交易的，构成操纵。"},{"i":5,"n":"第五条","txt":"在临近交割月或者交割月，利用不正当手段规避持仓限制，形成持仓优势，影响期货交易价格的，构成操纵。"},{"i":6,"n":"第六条","txt":"任何单位或者个人不得以其他方式操纵期货交易价格。"},{"i":7,"n":"第七条","txt":"任何单位或者个人有本规定行为的，依照《期货交易管理条例》第七十条的规定处理。"},{"i":8,"n":"第八条","txt":"本规定自公布之日起施行。"}],"neidiyuxiangganggupiaoshichangjiaoyihulianhutongjicd51f6":[{"i":1,"n":"第一条","txt":"为了规范内地与香港股票市场交易互联互通机制相关活动，保护投资者合法权益，维护证券市场秩序，根据《证券法》和其他相关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称内地与香港股票市场交易互联互通机制，是指上海证券交易所、深圳证券交易所分别和香港联合交易所有限公司（以下简称香港联合交易所）建立技术连接，使内地和香港投资者可以通过当地证券公司或经纪商买卖规定范围内的对方交易所上市的股票。内地与香港股票市场交易互联互通机制包括沪港股票市场交易互联互通机制（以下简称沪港通）和深港股票市场交易互联互通机制（以下简称深港通）。 沪港通包括沪股通和沪港通下的港股通。沪股通，是指投资者委托香港经纪商，经由香港联合交易所在上海设立的证券交易服务公司，向上海证券交易所进行申报（买卖盘传递），买卖沪港通规定范围内的上海证券交易所上市的股票。沪港通下的港股通，是指投资者委托内地证券公司，经由上海证券交易所在香港设立的证券交易服务公司，向香港联合交易所进行申报（买卖盘传递），买卖沪港通规定范围内的香港联合交易所上市的股票。 深港通包括深股通和深港通下的港股通。深"},{"i":3,"n":"第三条","txt":"内地与香港股票市场交易互联互通机制遵循两地市场现行的交易结算法律法规。 相关交易结算活动遵守交易结算发生地的监管规定及业务规则，上市公司遵守上市地的监管规定及业务规则，证券公司或经纪商遵守所在地的监管规定及业务规则，投资者遵守其委托的证券公司或经纪商所在地的投资者适当性监管规定及业务规则，本规定另有规定的除外。"},{"i":4,"n":"第四条","txt":"中国证券监督管理委员会（以下简称中国证监会）对内地与香港股票市场交易互联互通机制相关业务进行监督管理，并通过监管合作安排与香港证券及期货事务监察委员会和其他有关国家或地区的证券监督管理机构，按照公平、公正、对等的原则，维护投资者跨境投资的合法权益。"},{"i":5,"n":"第五条","txt":"上海证券交易所、深圳证券交易所和香港联合交易所开展内地与香港股票市场交易互联互通机制相关业务，应当履行下列职责： （一）提供必要的场所和设施； （二）上海证券交易所、深圳证券交易所分别在香港设立证券交易服务公司，香港联合交易所分别在上海和深圳设立证券交易服务公司；对证券交易服务公司业务活动进行管理，督促并协助其履行本规定所赋予的职责； （三）制定相关业务规则，对市场主体的相关交易及其他活动进行自律管理，并开展跨市场监管合作； （四）制定证券交易服务公司开展相关业务的技术标准； （五）对相关交易进行实时监控，并建立相应的信息交换制度和联合监控制度，共同监控跨境的不正当交易行为，防范市场风险； （六）管理和发布相关市场信息； （七）中国证监会规定的其他职责。 上海证券交易所、深圳证券交易所应当按照有关监管要求，分别制定港股通投资者适当性管理的具体标准和实施指引，并报中国证监会备案。 上海证"},{"i":6,"n":"第六条","txt":"证券交易服务公司应当按照证券交易所的相关业务规则或通过证券交易所的相关业务安排履行下列职责： （一）上海证券交易所证券交易服务公司提供沪港通下的港股通相关服务，深圳证券交易所证券交易服务公司提供深港通下的港股通相关服务；香港联合交易所在上海设立的证券交易服务公司提供沪股通相关服务；香港联合交易所在深圳设立的证券交易服务公司提供深股通相关服务； （二）提供必要的设施和技术服务； （三）履行沪股通、深股通或港股通额度管理相关职责； （四）制定沪股通、深股通或港股通业务的操作流程和风险控制措施，加强内部控制，防范风险； （五）上海证券交易所、深圳证券交易所设立的证券交易服务公司应当分别制定内地证券公司开展港股通业务的技术标准，并对拟开展业务公司的技术系统进行测试评估；香港联合交易所在上海和深圳设立的证券交易服务公司应当分别制定香港经纪商开展沪股通、深股通业务的技术标准，并对拟开展业务公司的技"},{"i":7,"n":"第七条","txt":"中国证券登记结算有限责任公司（以下简称中国证券登记结算公司）、香港中央结算有限公司（以下简称香港中央结算公司）开展内地与香港股票市场交易互联互通机制相关业务，应当履行下列职责： （一）提供必要的场所和设施； （二）提供登记、存管、结算服务； （三）制定相关业务规则； （四）依法提供名义持有人服务； （五）对登记结算参与机构的相关活动进行自律管理； （六）中国证监会规定的其他职责。"},{"i":8,"n":"第八条","txt":"内地证券公司开展港股通业务，应当遵守法律、行政法规、本规定、中国证监会其他规定及相关业务规则的要求，加强内部控制，防范和控制风险，并根据中国证监会及上海证券交易所、深圳证券交易所投资者适当性管理有关规定，制定相应的实施方案，切实维护客户权益。"},{"i":9,"n":"第九条","txt":"因交易异常情况严重影响内地与香港股票市场交易互联互通机制部分或全部交易正常进行的，上海证券交易所、深圳证券交易所和香港联合交易所可以按照业务规则和合同约定，暂停部分或者全部相关业务活动并予以公告。"},{"i":10,"n":"第十条","txt":"上海证券交易所、深圳证券交易所和香港联合交易所开展内地与香港股票市场交易互联互通机制相关业务，限于规定范围内的股票交易业务和中国证监会认可的其他业务。"},{"i":11,"n":"第十一条","txt":"证券交易服务公司和证券公司或经纪商不得自行撮合投资者通过内地与香港股票市场交易互联互通机制买卖股票的订单成交，不得以其他任何形式在证券交易所以外的场所对通过内地与香港股票市场交易互联互通机制买卖的股票提供转让服务，中国证监会另有规定的除外。"},{"i":12,"n":"第十二条","txt":"境外投资者的境内股票投资，应当遵循下列持股比例限制： （一）单个境外投资者对单个上市公司的持股比例，不得超过该上市公司股份总数的10%； （二）所有境外投资者对单个上市公司A股的持股比例总和，不得超过该上市公司股份总数的30%。 境外投资者依法对上市公司战略投资的，其战略投资的持股不受上述比例限制。 境内有关法律法规和其他有关监管规则对持股比例的最高限额有更严格规定的，从其规定。"},{"i":13,"n":"第十三条","txt":"投资者依法享有通过内地与香港股票市场交易互联互通机制买入的股票的权益。 投资者通过港股通买入的股票应当记录在中国证券登记结算公司在香港中央结算公司开立的证券账户。中国证券登记结算公司应当以自己的名义，通过香港中央结算公司行使对该股票发行人的权利。中国证券登记结算公司行使对该股票发行人的权利，应当通过内地证券公司、托管银行等机构事先征求投资者的意见，并按照其意见办理。 中国证券登记结算公司出具的股票持有记录，是港股通投资者享有该股票权益的合法证明。投资者不能要求提取纸面股票，中国证监会另有规定的除外。 投资者通过沪股通、深股通买入的股票应当登记在香港中央结算公司名下。投资者通过沪股通、深股通买卖股票达到信息披露要求的，应当依法履行报告和信息披露义务。"},{"i":14,"n":"第十四条","txt":"对于通过港股通达成的交易，由中国证券登记结算公司承担股票和资金的清算交收责任。对于通过沪股通、深股通达成的交易，由香港中央结算公司承担股票和资金的清算交收责任。 中国证券登记结算公司及香港中央结算公司，应当按照两地市场结算风险相对隔离、互不传递的原则，互不参加对方市场互保性质的风险基金安排；其他相关风险管理安排应当遵守交易结算发生地的交易结算风险管理有关规定。"},{"i":15,"n":"第十五条","txt":"投资者通过内地与香港股票市场交易互联互通机制买卖股票，应当以人民币与证券公司或经纪商进行交收。使用其它币种进行交收的，以中国人民银行规定为准。"},{"i":16,"n":"第十六条","txt":"对违反法律法规、本规定以及中国证监会其他有关规定的，中国证监会依法采取监督管理措施；依法应予行政处罚的，依照《证券法》、《行政处罚法》等法律法规进行处罚；涉嫌犯罪的，依法移送司法机关，追究刑事责任。 中国证监会与香港证券及期货事务监察委员会和其他有关国家或地区的证券监督管理机构，通过跨境监管合作机制，依法查处内地与香港股票市场交易互联互通机制相关跨境违法违规活动。"},{"i":17,"n":"第十七条","txt":"上海证券交易所、深圳证券交易所和中国证券登记结算公司依照本规定的有关要求，分别制定内地与香港股票市场交易互联互通机制相关业务规则，报中国证监会批准后实施。"},{"i":18,"n":"第十八条","txt":"证券交易所、证券交易服务公司及结算机构应当妥善保存履行本规定所规定的职责形成的各类文件、资料，保存期限不少于20年。"},{"i":19,"n":"第十九条","txt":"本规定自公布之日起施行。《沪港股票市场交易互联互通机制试点若干规定》（证监会令第101号）同时废止。"}],"chuangyebanshangshigongsichixujianguanbanfa":[{"i":1,"n":"第一条","txt":"为了规范企业股票、存托凭证及其衍生品种在深圳证券交易所（以下简称交易所）创业板上市后相关各方的行为，支持引导企业更好地发展，保护投资者合法权益，根据《中华人民共和国证券法》（以下简称《证券法》）、《中华人民共和国公司法》《国务院办公厅转发证监会关于开展创新企业境内发行股票或存托凭证试点若干意见的通知》以及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中国证券监督管理委员会（以下简称中国证监会）根据《证券法》等法律法规、本办法和中国证监会其他相关规定，对创业板上市公司（以下简称上市公司）及相关主体进行监督管理。 中国证监会其他相关规定与本办法规定不一致的，适用本办法。"},{"i":3,"n":"第三条","txt":"交易所根据《证券交易所管理办法》、本办法等有关规定，建立以股票上市规则为中心的创业板持续监管规则体系，在持续信息披露、股份减持、并购重组、股权激励、退市等方面制定具体实施规则。上市公司应当遵守交易所持续监管实施规则。"},{"i":4,"n":"第四条","txt":"上市公司应当保持健全、有效、透明的治理体系和监督机制，保证股东大会、董事会、监事会规范运作，督促董事、监事和高级管理人员履行忠实、勤勉义务，保障全体股东合法权利，积极履行社会责任，保护利益相关者的基本权益。"},{"i":5,"n":"第五条","txt":"上市公司控股股东、实际控制人应当诚实守信，规范行使权利，严格履行承诺，维持公司独立性，维护公司和全体股东的共同利益。"},{"i":6,"n":"第六条","txt":"上市公司应当积极回报股东，根据自身条件和发展阶段，制定并执行现金分红、股份回购等股东回报政策。"},{"i":7,"n":"第七条","txt":"上市公司设置表决权差异安排的，应当在公司章程中规定特别表决权股份的持有人资格、特别表决权股份拥有的表决权数量与普通股份拥有的表决权数量的比例安排、持有人所持特别表决权股份能够参与表决的股东大会事项范围、特别表决权股份锁定安排及转让限制、特别表决权股份与普通股份的转换情形等事项。公司章程有关上述事项的规定，应当符合交易所的有关规定。 上市公司应当在定期报告中持续披露特别表决权安排的情况；特别表决权安排发生重大变化的，应当及时披露。 交易所应当对存在特别表决权股份公司的上市条件、表决权差异的设置、存续、调整、信息披露和投资者保护事项制定有关规定。"},{"i":8,"n":"第八条","txt":"上市公司的控股股东、实际控制人应当配合上市公司履行信息披露义务，不得要求或者协助上市公司隐瞒应当披露的信息。"},{"i":9,"n":"第九条","txt":"上市公司筹划的重大事项存在较大不确定性，立即披露可能会损害公司利益或者误导投资者，且有关内幕信息知情人已书面承诺保密的，上市公司可以暂不披露，但最迟应当在该重大事项形成最终决议、签署最终协议或者交易确定能够达成时对外披露；已经泄密或者确实难以保密的，上市公司应当立即披露该信息。"},{"i":10,"n":"第十条","txt":"上市公司应当结合所属行业的特点，充分披露行业经营信息，尤其是针对性披露技术、产业、业态、模式等能够反映行业竞争力的信息，便于投资者合理决策。"},{"i":11,"n":"第十一条","txt":"上市公司应当充分披露可能对公司核心竞争力、经营活动和未来发展产生重大不利影响的风险因素。 上市公司尚未盈利的，应当充分披露尚未盈利的成因，以及对公司现金流、业务拓展、人才吸引、团队稳定性、研发投入、战略性投入、生产经营可持续性等方面的影响。"},{"i":12,"n":"第十二条","txt":"除依法需要披露的信息之外，上市公司和相关信息披露义务人可以自愿披露与投资者作出价值判断和投资决策有关的信息，但不得与依法披露的信息相冲突，不得误导投资者。 上市公司自愿披露的信息应当真实、准确、完整，简明清晰，通俗易懂，上市公司不得利用该等信息不当影响公司股票价格，并应当按照同一标准披露后续类似信息。"},{"i":13,"n":"第十三条","txt":"上市公司和相关信息披露义务人确有需要的，可以在非交易时段对外发布重大信息，但应当在下一交易时段开始前披露相关公告，不得以新闻发布或者答记者问等形式代替信息披露。"},{"i":14,"n":"第十四条","txt":"上市公司和相关信息披露义务人适用中国证监会、交易所相关信息披露规定，可能导致其难以反映经营活动的实际情况、难以符合行业监管要求或者公司注册地有关规定的，可以依照相关规定暂缓适用或者免于适用，但是应当充分说明原因和替代方案。中国证监会、交易所认为依法不应当调整适用的，上市公司和相关信息披露义务人应当执行相关规定。"},{"i":15,"n":"第十五条","txt":"股份锁定期届满后，上市公司控股股东、实际控制人、董事、监事、高级管理人员及其他股东减持首次公开发行前已发行的股份（以下简称首发前股份）以及上市公司向特定对象发行的股份，应当遵守交易所有关减持方式、程序、价格、比例以及后续转让等事项的规定。"},{"i":16,"n":"第十六条","txt":"上市时未盈利的上市公司，其控股股东、实际控制人、董事、监事、高级管理人员所持首发前股份的锁定期应当适当延长，具体期限由交易所规定。"},{"i":17,"n":"第十七条","txt":"上市公司存在重大违法情形，触及重大违法强制退市标准的，控股股东、实际控制人、董事、监事、高级管理人员应当遵守交易所相关股份转让的规定。"},{"i":18,"n":"第十八条","txt":"上市公司实施重大资产重组或者发行股份购买资产的，标的资产所属行业应当符合创业板定位，或者与上市公司处于同行业或者上下游。"},{"i":19,"n":"第十九条","txt":"上市公司并购重组，涉及发行股票的，由交易所审核通过后报中国证监会注册。 中国证监会收到交易所报送的审核意见等相关文件后，在五个工作日内对上市公司注册申请作出予以注册或者不予注册的决定，按规定应当扣除的时间不计算在本款规定的时限内。"},{"i":20,"n":"第二十条","txt":"上市公司实施重大资产重组的标准，按照《上市公司重大资产重组管理办法》（以下简称《重组办法》）第十二条予以认定，但其中营业收入指标执行下列标准：购买、出售的资产在最近一个会计年度所产生的营业收入占上市公司同期经审计的合并财务会计报告营业收入的比例达到百分之五十以上，且超过五千万元人民币。 上市公司实施重大资产重组，构成《重组办法》第十三条规定的交易情形的，置入资产的具体条件由交易所制定。"},{"i":21,"n":"第二十一条","txt":"上市公司发行股份购买资产的，发行股份的价格不得低于市场参考价的百分之八十。市场参考价为本次发行股份购买资产的董事会决议公告日前二十个交易日、六十个交易日或者一百二十个交易日的公司股票交易均价之一。"},{"i":22,"n":"第二十二条","txt":"实施重大资产重组或者发行股份购买资产的上市公司为创新试点红筹企业，或者上市公司拟购买资产涉及创新试点红筹企业的，在计算重大资产重组认定标准等监管指标时，应当采用根据中国企业会计准则编制或者调整的财务数据。 上市公司中的创新试点红筹企业实施重大资产重组或者发行股份购买资产，可以按照境外注册地法律法规和公司章程履行内部决策程序，并及时披露重组报告书、独立财务顾问报告、法律意见书以及重组涉及的审计报告、资产评估报告或者估值报告。"},{"i":23,"n":"第二十三条","txt":"交易所应当制定符合上市公司特点的并购重组具体实施标准和规则，报中国证监会批准，并依法对信息披露、中介机构督导等进行自律管理。"},{"i":24,"n":"第二十四条","txt":"上市公司发行优先股、定向可转债、定向权证、存托凭证购买资产或者与其他公司合并的，参照适用本办法；本办法没有规定的，适用《重组办法》等有关规定。"},{"i":25,"n":"第二十五条","txt":"上市公司以本公司股票为标的实施股权激励的，应当设置合理的考核指标，有利于公司持续发展。"},{"i":26,"n":"第二十六条","txt":"单独或者合计持有上市公司百分之五以上股份的股东或者实际控制人及其配偶、父母、子女，作为上市公司董事、高级管理人员、核心技术人员或者核心业务人员的，可以成为激励对象。 上市公司应当充分说明上述人员成为激励对象的必要性、合理性。"},{"i":27,"n":"第二十七条","txt":"上市公司授予激励对象的限制性股票，包括符合股权激励计划授予条件的激励对象在满足相应条件后分次获得并登记的本公司股票。 限制性股票的授予和登记，应当遵守交易所和证券登记结算机构的有关规定。"},{"i":28,"n":"第二十八条","txt":"上市公司授予激励对象限制性股票的价格低于市场参考价百分之五十的，应当符合交易所有关规定，并应当说明定价依据及定价方式。 出现前款规定情形的，上市公司应当聘请独立财务顾问，对股权激励计划的可行性、相关定价依据和定价方法的合理性、是否有利于公司持续发展、是否损害股东利益等发表意见。"},{"i":29,"n":"第二十九条","txt":"上市公司全部在有效期内的股权激励计划所涉及的标的股票总数，累计不得超过公司总股本的百分之二十。"},{"i":30,"n":"第三十条","txt":"上市公司应当建立完善募集资金管理使用制度，按照交易所业务规则持续披露募集资金使用情况。"},{"i":31,"n":"第三十一条","txt":"上市公司控股股东、实际控制人质押公司股份的，应当合理使用融入资金，维持公司控制权和生产经营稳定，不得侵害公司利益或者向公司转移风险，并依据中国证监会、交易所的规定履行信息披露义务。"},{"i":32,"n":"第三十二条","txt":"上市公司及其股东、实际控制人、董事、监事、高级管理人员、其他信息披露义务人、内幕信息知情人等相关主体违反本办法的，中国证监会根据《证券法》等法律法规和中国证监会其他有关规定，依法追究其法律责任。"},{"i":33,"n":"第三十三条","txt":"中国证监会将遵守本办法的情况记入证券市场诚信档案，会同有关部门加强信息共享，依法依规实施守信激励与失信惩戒。"},{"i":34,"n":"第三十四条","txt":"上市公司根据自身定位和发展需要，可以申请转板至其他板块上市。具体规则另行制定。"},{"i":35,"n":"第三十五条","txt":"本办法自公布之日起施行。"}],"chuangyebanshangshigongsizhengquanfaxingzhuceguanlefd95f":[{"i":1,"n":"第一条","txt":"为了规范创业板上市公司（以下简称上市公司）证券发行行为，保护投资者合法权益和社会公共利益，根据《中华人民共和国证券法》（以下简称《证券法》）《国务院办公厅关于贯彻实施修订后的证券法有关工作的通知》《国务院办公厅转发证监会关于开展创新企业境内发行股票或存托凭证试点若干意见的通知》（以下简称《若干意见》）及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"上市公司申请在境内发行证券，适用本办法。 本办法所称证券，指下列证券品种： （一）股票； （二）可转换公司债券（以下简称可转债）； （三）存托凭证； （四）中国证券监督管理委员会（以下简称中国证监会）认可的其他品种。 前款所称可转债，是指上市公司依法发行、在一定期间内依据约定的条件可以转换成股份的公司债券。"},{"i":3,"n":"第三条","txt":"上市公司发行证券，可以向不特定对象发行，也可以向特定对象发行。 向不特定对象发行证券包括上市公司向原股东配售股份（以下简称配股）、向不特定对象募集股份（以下简称增发）和向不特定对象发行可转债。 向特定对象发行证券包括上市公司向特定对象发行股票、向特定对象发行可转债。"},{"i":4,"n":"第四条","txt":"上市公司发行证券的，应当符合《证券法》和本办法规定的发行条件和相关信息披露要求，依法经深圳证券交易所（以下简称交易所）发行上市审核并报中国证监会注册，但因依法实行股权激励、公积金转为增加公司资本、分配股票股利的除外。"},{"i":5,"n":"第五条","txt":"上市公司应当诚实守信，依法充分披露投资者作出价值判断和投资决策所必需的信息，所披露信息必须真实、准确、完整，简明清晰、通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 上市公司应当按照保荐人、证券服务机构要求，依法向其提供真实、准确、完整的财务会计资料和其他资料，配合相关机构开展尽职调查和其他相关工作。 上市公司控股股东、实际控制人、董事、监事、高级管理人员应当配合相关机构开展尽职调查和其他相关工作，不得要求或者协助上市公司隐瞒应当提供的资料或者应当披露的信息。"},{"i":6,"n":"第六条","txt":"保荐人应当诚实守信，勤勉尽责，按照依法制定的业务规则和行业自律规范的要求，充分了解上市公司经营情况和风险，对注册申请文件和信息披露资料进行全面核查验证，对上市公司是否符合发行条件独立作出专业判断，审慎作出推荐决定，并对募集说明书或者其他信息披露文件及其所出具的相关文件的真实性、准确性、完整性负责。"},{"i":7,"n":"第七条","txt":"证券服务机构应当严格遵守法律法规、中国证监会制定的监管规则、业务规则和本行业公认的业务标准和道德规范，建立并保持有效的质量控制体系，保护投资者合法权益，审慎履行职责，作出专业判断与认定，并对募集说明书或者其他信息披露文件中与其专业职责有关的内容及其所出具的文件的真实性、准确性、完整性负责。 证券服务机构及其相关执业人员应当对与本专业相关的业务事项履行特别注意义务，对其他业务事项履行普通注意义务，并承担相应法律责任。 证券服务机构及其执业人员从事证券服务业务应当配合中国证监会的监督管理，在规定的期限内提供、报送或披露相关资料、信息，并保证其提供、报送或披露的资料、信息真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 证券服务机构应当妥善保存客户委托文件、核查和验证资料、工作底稿以及与质量控制、内部管理、业务经营有关的信息和资料。"},{"i":8,"n":"第八条","txt":"对上市公司发行证券申请予以注册，不表明中国证监会和交易所对该证券的投资价值或者投资者的收益作出实质性判断或者保证，也不表明中国证监会和交易所对申请文件的真实性、准确性、完整性作出保证。"},{"i":9,"n":"第九条","txt":"上市公司向不特定对象发行股票，应当符合下列规定： （一）具备健全且运行良好的组织机构； （二）现任董事、监事和高级管理人员符合法律、行政法规规定的任职要求； （三）具有完整的业务体系和直接面向市场独立经营的能力，不存在对持续经营有重大不利影响的情形； （四）会计基础工作规范，内部控制制度健全且有效执行，财务报表的编制和披露符合企业会计准则和相关信息披露规则的规定，在所有重大方面公允反映了上市公司的财务状况、经营成果和现金流量，最近三年财务会计报告被出具无保留意见审计报告； （五）最近二年盈利，净利润以扣除非经常性损益前后孰低者为计算依据； （六）除金融类企业外，最近一期末不存在金额较大的财务性投资。"},{"i":10,"n":"第十条","txt":"上市公司存在下列情形之一的，不得向不特定对象发行股票： （一）擅自改变前次募集资金用途未作纠正，或者未经股东大会认可； （二）上市公司及其现任董事、监事和高级管理人员最近三年受到中国证监会行政处罚，或者最近一年受到证券交易所公开谴责，或者因涉嫌犯罪正在被司法机关立案侦查或者涉嫌违法违规正在被中国证监会立案调查； （三）上市公司及其控股股东、实际控制人最近一年存在未履行向投资者作出的公开承诺的情形； （四）上市公司及其控股股东、实际控制人最近三年存在贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的刑事犯罪，或者存在严重损害上市公司利益、投资者合法权益、社会公共利益的重大违法行为。"},{"i":11,"n":"第十一条","txt":"上市公司存在下列情形之一的，不得向特定对象发行股票： （一）擅自改变前次募集资金用途未作纠正，或者未经股东大会认可； （二）最近一年财务报表的编制和披露在重大方面不符合企业会计准则或者相关信息披露规则的规定;最近一年财务会计报告被出具否定意见或者无法表示意见的审计报告;最近一年财务会计报告被出具保留意见的审计报告，且保留意见所涉及事项对上市公司的重大不利影响尚未消除。本次发行涉及重大资产重组的除外； （三）现任董事、监事和高级管理人员最近三年受到中国证监会行政处罚，或者最近一年受到证券交易所公开谴责； （四）上市公司及其现任董事、监事和高级管理人员因涉嫌犯罪正在被司法机关立案侦查或者涉嫌违法违规正在被中国证监会立案调查； （五）控股股东、实际控制人最近三年存在严重损害上市公司利益或者投资者合法权益的重大违法行为； （六）最近三年存在严重损害投资者合法权益或者社会公共利益的重大违法行为。"},{"i":12,"n":"第十二条","txt":"上市公司发行股票，募集资金使用应当符合下列规定： （一）符合国家产业政策和有关环境保护、土地管理等法律、行政法规规定； （二）除金融类企业外，本次募集资金使用不得为持有财务性投资，不得直接或者间接投资于以买卖有价证券为主要业务的公司； （三）募集资金项目实施后，不会与控股股东、实际控制人及其控制的其他企业新增构成重大不利影响的同业竞争、显失公平的关联交易，或者严重影响公司生产经营的独立性。"},{"i":13,"n":"第十三条","txt":"上市公司发行可转债，应当符合下列规定： （一）具备健全且运行良好的组织机构； （二）最近三年平均可分配利润足以支付公司债券一年的利息； （三）具有合理的资产负债结构和正常的现金流量。 除前款规定条件外，上市公司向不特定对象发行可转债，还应当遵守本办法第九条第（二）项至第（六）项、第十条的规定；向特定对象发行可转债，还应当遵守本办法第十一条的规定。但是，按照公司债券募集办法，上市公司通过收购本公司股份的方式进行公司债券转换的除外。"},{"i":14,"n":"第十四条","txt":"上市公司存在下列情形之一的，不得发行可转债： （一）对已公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，仍处于继续状态； （二）违反《证券法》规定，改变公开发行公司债券所募资金用途。"},{"i":15,"n":"第十五条","txt":"上市公司发行可转债，募集资金除不得用于弥补亏损和非生产性支出外，还应当遵守本办法第十二条的规定。"},{"i":16,"n":"第十六条","txt":"上市公司申请发行证券，董事会应当依法就下列事项作出决议，并提请股东大会批准： （一）本次证券发行的方案； （二）本次发行方案的论证分析报告； （三）本次募集资金使用的可行性报告； （四）其他必须明确的事项。 上市公司董事会拟引入战略投资者的，应当将引入战略投资者的事项作为单独议案，就每名战略投资者单独审议，并提交股东大会批准。 董事会依照前二款作出决议，董事会决议日与首次公开发行股票上市日的时间间隔不得少于六个月。"},{"i":17,"n":"第十七条","txt":"董事会在编制本次发行方案的论证分析报告时，应当结合上市公司所处行业和发展阶段、融资规划、财务状况、资金需求等情况进行论证分析，独立董事应当发表专项意见。论证分析报告至少应当包括下列内容： （一）本次发行证券及其品种选择的必要性； （二）本次发行对象的选择范围、数量和标准的适当性； （三）本次发行定价的原则、依据、方法和程序的合理性； （四）本次发行方式的可行性； （五）本次发行方案的公平性、合理性； （六）本次发行对原股东权益或者即期回报摊薄的影响以及填补的具体措施。"},{"i":18,"n":"第十八条","txt":"股东大会就发行证券作出的决定，至少应当包括下列事项： （一）本次发行证券的种类和数量； （二）发行方式、发行对象及向原股东配售的安排； （三）定价方式或者价格区间； （四）募集资金用途； （五）决议的有效期； （六）对董事会办理本次发行具体事宜的授权； （七）其他必须明确的事项。"},{"i":19,"n":"第十九条","txt":"股东大会就发行可转债作出的决定，至少应当包括下列事项： （一）本办法第十八条规定的事项； （二）债券利率； （三）债券期限； （四）赎回条款； （五）回售条款； （六）还本付息的期限和方式； （七）转股期； （八）转股价格的确定和修正。"},{"i":20,"n":"第二十条","txt":"股东大会就发行证券事项作出决议，必须经出席会议的股东所持表决权的三分之二以上通过，中小投资者表决情况应当单独计票。向本公司特定的股东及其关联人发行证券的，股东大会就发行方案进行表决时，关联股东应当回避。股东大会对引入战略投资者议案作出决议的，应当就每名战略投资者单独表决。 上市公司就发行证券事项召开股东大会，应当提供网络投票方式，公司还可以通过其他方式为股东参加股东大会提供便利。"},{"i":21,"n":"第二十一条","txt":"上市公司年度股东大会可以根据公司章程的规定，授权董事会决定向特定对象发行融资总额不超过人民币三亿元且不超过最近一年末净资产百分之二十的股票，该项授权在下一年度股东大会召开日失效。 上市公司年度股东大会给予董事会前款授权的，应当就本办法第十八条规定的事项通过相关决定。"},{"i":22,"n":"第二十二条","txt":"上市公司申请发行证券，应当按照中国证监会有关规定制作注册申请文件，依法由保荐人保荐并向交易所申报。 交易所收到注册申请文件后，五个工作日内作出是否受理的决定。"},{"i":23,"n":"第二十三条","txt":"申请文件受理后，未经中国证监会或者交易所同意，不得改动。 发生重大事项的，上市公司、保荐人、证券服务机构应当及时向交易所报告，并按要求更新申请文件和信息披露资料。"},{"i":24,"n":"第二十四条","txt":"交易所审核部门负责审核上市公司证券发行上市申请；创业板上市委员会负责对上市公司向不特定对象发行证券的申请文件和审核部门出具的审核报告提出审议意见。 交易所主要通过向上市公司提出审核问询、上市公司回答问题方式开展审核工作，判断上市公司发行申请是否符合发行条件和信息披露要求。"},{"i":25,"n":"第二十五条","txt":"上市公司应当向交易所报送审核问询回复的相关文件，并以临时公告的形式披露交易所审核问询回复意见。"},{"i":26,"n":"第二十六条","txt":"交易所按照规定的条件和程序，形成上市公司是否符合发行条件和信息披露要求的审核意见，认为上市公司符合发行条件和信息披露要求的，将审核意见、上市公司注册申请文件及相关审核资料报中国证监会注册；认为上市公司不符合发行条件或者信息披露要求的，作出终止发行上市审核决定。"},{"i":27,"n":"第二十七条","txt":"交易所应当自受理注册申请文件之日起二个月内形成审核意见，但本办法另有规定的除外。 上市公司根据要求补充、修改申请文件，或者交易所按照规定对上市公司实施现场检查，要求保荐人、证券服务机构对有关事项进行专项核查，并要求上市公司补充、修改申请文件的时间不计算在内。"},{"i":28,"n":"第二十八条","txt":"符合相关规定的上市公司按照本办法第二十一条规定申请向特定对象发行股票的，适用简易程序。"},{"i":29,"n":"第二十九条","txt":"交易所采用简易程序的，应当在收到注册申请文件后，二个工作日内作出是否受理的决定，自受理之日起三个工作日内完成审核并形成上市公司是否符合发行条件和信息披露要求的审核意见。 交易所应当制定简易程序的业务规则，并报中国证监会批准。"},{"i":30,"n":"第三十条","txt":"中国证监会依法履行发行注册程序，主要关注交易所发行上市审核内容有无遗漏，审核程序是否符合规定，以及上市公司在发行条件和信息披露要求的重大方面是否符合相关规定。中国证监会认为存在需要进一步说明或者落实事项的，可以要求交易所进一步问询。 中国证监会认为交易所对影响发行条件的重大事项未予关注或者交易所的审核意见依据明显不充分的，可以退回交易所补充审核。交易所补充审核后，认为上市公司符合发行条件和信息披露要求的，重新向中国证监会报送审核意见及相关资料，本办法第三十一条规定的注册期限重新计算。"},{"i":31,"n":"第三十一条","txt":"中国证监会在十五个工作日内对上市公司的注册申请作出予以注册或者不予注册的决定。 上市公司根据要求补充、修改注册申请文件，或者中国证监会要求交易所进一步问询，要求保荐人、证券服务机构等对有关事项进行核查，对上市公司现场检查，并要求上市公司补充、修改申请文件的时间不计算在内。 中国证监会收到交易所依照本办法第二十九条规定报送的审核意见、上市公司注册申请文件及相关审核资料后，三个工作日内作出予以注册或者不予注册的决定。"},{"i":32,"n":"第三十二条","txt":"中国证监会的予以注册决定，自作出之日起一年内有效，上市公司应当在注册决定有效期内发行证券，发行时点由上市公司自主选择。 适用简易程序的，应当在中国证监会作出予以注册决定后十个工作日内完成发行缴款，未完成的，本次发行批文失效。"},{"i":33,"n":"第三十三条","txt":"中国证监会作出予以注册决定后、上市公司证券上市交易前，上市公司应当及时更新信息披露文件；保荐人以及证券服务机构应当持续履行尽职调查职责；发生重大事项的，上市公司、保荐人应当及时向交易所报告。 交易所应当对上述事项及时处理，发现上市公司存在重大事项影响发行条件的，应当出具明确意见并及时向中国证监会报告。"},{"i":34,"n":"第三十四条","txt":"中国证监会作出予以注册决定后、上市公司证券上市交易前，发现可能影响本次发行的重大事项的，中国证监会可以要求上市公司暂缓发行、上市；相关重大事项导致上市公司不符合发行条件的，应当撤销注册。 中国证监会撤销注册后，证券尚未发行的，上市公司应当停止发行；证券已经发行尚未上市的，上市公司应当按照发行价并加算银行同期存款利息返还证券持有人。"},{"i":35,"n":"第三十五条","txt":"交易所认为上市公司不符合发行条件或者信息披露要求，作出终止发行上市审核决定，或者中国证监会作出不予注册决定的，自决定作出之日起六个月后，上市公司可以再次提出证券发行申请。"},{"i":36,"n":"第三十六条","txt":"上市公司证券发行上市审核或者注册程序的中止、终止等情形参照适用《创业板首次公开发行股票注册管理办法（试行）》的相关规定。"},{"i":37,"n":"第三十七条","txt":"中国证监会和交易所可以对上市公司进行现场检查，或者要求保荐人、证券服务机构对有关事项进行专项核查并出具意见。"},{"i":38,"n":"第三十八条","txt":"上市公司发行证券，应当以投资者决策需求为导向，按照中国证监会制定的信息披露规则，编制募集说明书或者其他信息披露文件，依法履行信息披露义务，保证相关信息真实、准确、完整。信息披露内容应当简明清晰，通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 中国证监会制定的信息披露规则是信息披露的最低要求。不论上述规则是否有明确规定，凡是投资者作出价值判断和投资决策所必需的信息，上市公司均应当充分披露，内容应当真实、准确、完整。"},{"i":39,"n":"第三十九条","txt":"中国证监会依法制定募集说明书或者其他证券发行信息披露文件内容与格式准则、编报规则等信息披露规则，对申请文件和信息披露资料的内容、格式、编制要求、披露形式等作出规定。 交易所可以依据中国证监会部门规章和规范性文件，制定信息披露细则或者指引，在中国证监会确定的信息披露内容范围内，对信息披露提出细化和补充要求，报中国证监会批准后实施。"},{"i":40,"n":"第四十条","txt":"上市公司应当在募集说明书或者其他证券发行信息披露文件中，以投资者需求为导向，有针对性地披露业务模式、公司治理、发展战略、经营政策、会计政策、财务状况分析等信息，并充分揭示可能对公司核心竞争力、经营稳定性以及未来发展产生重大不利影响的风险因素。"},{"i":41,"n":"第四十一条","txt":"证券发行议案经董事会表决通过后，应当在二个工作日内披露，并及时公告召开股东大会的通知。 使用募集资金收购资产或者股权的，应当在公告召开股东大会通知的同时，披露该资产或者股权的基本情况、交易价格、定价依据以及是否与公司股东或者其他关联人存在利害关系。"},{"i":42,"n":"第四十二条","txt":"股东大会通过本次发行议案之日起二个工作日内，上市公司应当披露股东大会决议公告。"},{"i":43,"n":"第四十三条","txt":"上市公司提出发行申请后，出现下列情形之一的，应当在次一个工作日予以公告： （一）收到交易所不予受理或者终止发行上市审核决定； （二）收到中国证监会终止发行注册决定； （三）收到中国证监会予以注册或者不予注册的决定； （四）上市公司撤回证券发行申请。"},{"i":44,"n":"第四十四条","txt":"上市公司及其董事、监事、高级管理人员应当在募集说明书或者其他证券发行信息披露文件上签字、盖章，保证信息披露内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，按照诚信原则履行承诺，并声明承担相应的法律责任。 上市公司控股股东、实际控制人应当在募集说明书或者其他证券发行信息披露文件上签字、盖章，确认信息披露内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，按照诚信原则履行承诺，并声明承担相应法律责任。"},{"i":45,"n":"第四十五条","txt":"保荐人及其保荐代表人应当在募集说明书或者其他证券发行信息披露文件上签字、盖章，确认信息披露内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":46,"n":"第四十六条","txt":"为证券发行出具专项文件的律师、注册会计师、资产评估人员、资信评级人员及其所在机构，应当在募集说明书或者其他证券发行信息披露文件上签字、盖章，确认对上市公司信息披露文件引用其出具的专业意见无异议，信息披露文件不因引用其出具的专业意见而出现虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":47,"n":"第四十七条","txt":"募集说明书等证券发行信息披露文件所引用的审计报告、盈利预测审核报告、资产评估报告、资信评级报告，应当由符合规定的证券服务机构出具，并由至少二名有执业资格的人员签署。 募集说明书或者其他证券发行信息披露文件所引用的法律意见书，应当由律师事务所出具，并由至少二名经办律师签署。"},{"i":48,"n":"第四十八条","txt":"募集说明书自最后签署之日起六个月内有效。 募集说明书或者其他证券发行信息披露文件不得使用超过有效期的资产评估报告或者资信评级报告。"},{"i":49,"n":"第四十九条","txt":"向不特定对象发行证券申请经注册后，上市公司应当在证券发行前二至五个工作日内将公司募集说明书刊登在交易所网站和符合中国证监会规定条件的网站，供公众查阅。"},{"i":50,"n":"第五十条","txt":"向特定对象发行证券申请经注册后，上市公司应当在证券发行前将公司募集文件刊登在交易所网站和符合中国证监会规定条件的网站，供公众查阅。 向特定对象发行证券的，上市公司应当在证券发行后的二个工作日内，将发行情况报告书刊登在交易所网站和符合中国证监会规定条件的网站，供公众查阅。"},{"i":51,"n":"第五十一条","txt":"上市公司可以将募集说明书或者其他证券发行信息披露文件、发行情况报告书刊登于其他网站，但不得早于按照本办法第四十九条、第五十条规定披露信息的时间。"},{"i":52,"n":"第五十二条","txt":"上市公司证券发行与承销行为，适用《证券发行与承销管理办法》（以下简称《承销办法》），但本办法另有规定的除外。 交易所可以根据《承销办法》和本办法制定上市公司证券发行承销业务规则，并报中国证监会批准。"},{"i":53,"n":"第五十三条","txt":"上市公司配股的，拟配售股份数量不超过本次配售前股本总额的百分之五十，并应当采用代销方式发行。 控股股东应当在股东大会召开前公开承诺认配股份的数量。控股股东不履行认配股份的承诺，或者代销期限届满，原股东认购股票的数量未达到拟配售数量百分之七十的，上市公司应当按照发行价并加算银行同期存款利息返还已经认购的股东。"},{"i":54,"n":"第五十四条","txt":"上市公司增发的，发行价格应当不低于公告招股意向书前二十个交易日或者前一个交易日公司股票均价。"},{"i":55,"n":"第五十五条","txt":"上市公司向特定对象发行证券，发行对象应当符合股东大会决议规定的条件，且每次发行对象不超过三十五名。"},{"i":56,"n":"第五十六条","txt":"上市公司向特定对象发行股票，发行价格应当不低于定价基准日前二十个交易日公司股票均价的百分之八十。 前款所称“定价基准日”，是指计算发行底价的基准日。"},{"i":57,"n":"第五十七条","txt":"向特定对象发行股票的定价基准日为发行期首日。上市公司应当以不低于发行底价的价格发行股票。 上市公司董事会决议提前确定全部发行对象，且发行对象属于下列情形之一的，定价基准日可以为关于本次发行股票的董事会决议公告日、股东大会决议公告日或者发行期首日： （一）上市公司的控股股东、实际控制人或者其控制的关联人； （二）通过认购本次发行的股票取得上市公司实际控制权的投资者； （三）董事会拟引入的境内外战略投资者。"},{"i":58,"n":"第五十八条","txt":"向特定对象发行股票发行对象属于本办法第五十七条第二款规定以外的情形的，上市公司应当以竞价方式确定发行价格和发行对象。 董事会决议确定部分发行对象的，确定的发行对象不得参与竞价，且应当接受竞价结果，并明确在通过竞价方式未能产生发行价格的情况下，是否继续参与认购、价格确定原则及认购数量。"},{"i":59,"n":"第五十九条","txt":"向特定对象发行的股票,自发行结束之日起六个月内不得转让。发行对象属于本办法第五十七条第二款规定情形的，其认购的股票自发行结束之日起十八个月内不得转让。"},{"i":60,"n":"第六十条","txt":"向特定对象发行股票的定价基准日为本次发行股票的董事会决议公告日或者股东大会决议公告日的，向特定对象发行股票的董事会决议公告后，出现下列情况需要重新召开董事会的，应当由董事会重新确定本次发行的定价基准日： （一）本次发行股票股东大会决议的有效期已过； （二）本次发行方案发生重大变化； （三）其他对本次发行定价具有重大影响的事项。"},{"i":61,"n":"第六十一条","txt":"可转债应当具有期限、面值、利率、评级、债券持有人权利、转股价格及调整原则、赎回及回售、转股价格向下修正等要素。 向不特定对象发行的可转债利率由上市公司与主承销商依法协商确定。 向特定对象发行的可转债应当采用竞价方式确定利率和发行对象。"},{"i":62,"n":"第六十二条","txt":"可转债自发行结束之日起六个月后方可转换为公司股票，转股期限由公司根据可转债的存续期限及公司财务状况确定。 债券持有人对转股或者不转股有选择权，并于转股的次日成为上市公司股东。"},{"i":63,"n":"第六十三条","txt":"向特定对象发行的可转债不得采用公开的集中交易方式转让。 向特定对象发行的可转债转股的，所转股票自可转债发行结束之日起十八个月内不得转让。"},{"i":64,"n":"第六十四条","txt":"向不特定对象发行可转债的转股价格应当不低于募集说明书公告日前二十个交易日上市公司股票交易均价和前一个交易日均价。 向特定对象发行可转债的转股价格应当不低于认购邀请书发出前二十个交易日上市公司股票交易均价和前一个交易日的均价，且不得向下修正。"},{"i":65,"n":"第六十五条","txt":"上市公司发行证券，应当由证券公司承销。上市公司董事会决议提前确定全部发行对象的，可以由上市公司自行销售。"},{"i":66,"n":"第六十六条","txt":"向特定对象发行证券，上市公司及其控股股东、实际控制人、主要股东不得向发行对象做出保底保收益或者变相保底保收益承诺，也不得直接或者通过利益相关方向发行对象提供财务资助或者其他补偿。"},{"i":67,"n":"第六十七条","txt":"上市公司发行证券采用竞价方式的，认购邀请书内容、认购邀请书发送对象范围、发行价格及发行对象的确定原则等应当符合中国证监会及交易所相关规定，上市公司和主承销商的控股股东、实际控制人、董事、监事、高级管理人员及其控制或者施加重大影响的关联方不得参与竞价。"},{"i":68,"n":"第六十八条","txt":"网下投资者应当结合行业监管要求、资产规模等合理确定申购金额，不得超资产规模申购，承销商可以认定超资产规模的申购为无效申购。"},{"i":69,"n":"第六十九条","txt":"上市公司向不特定对象发行证券的，投资者弃购数量占发行总数比例较大的，上市公司和主承销商可以将投资者弃购部分向网下投资者二次配售。比例较大的标准由交易所规定。"},{"i":70,"n":"第七十条","txt":"上市公司和主承销商可以在符合中国证监会和交易所相关规定前提下约定中止发行的情形。"},{"i":71,"n":"第七十一条","txt":"交易所对证券发行承销过程实施监管。发行承销涉嫌违法违规或者存在异常情形的，中国证监会可以要求交易所对相关事项进行调查处理，或者直接责令上市公司和承销商暂停或者中止发行。"},{"i":72,"n":"第七十二条","txt":"中国证监会依法批准交易所制定的创业板上市公司证券发行上市的审核标准、审核程序、信息披露、发行承销等方面的制度规则，指导交易所制定与发行上市审核相关的其他业务规则。"},{"i":73,"n":"第七十三条","txt":"中国证监会建立对交易所发行上市审核工作和发行承销过程监管的监督机制，持续关注交易所审核情况和发行承销过程监管情况，发现交易所自律监管措施或者纪律处分失当的，可以责令交易所改正。"},{"i":74,"n":"第七十四条","txt":"中国证监会对交易所发行上市审核和发行承销过程监管等相关工作进行年度例行检查。在检查过程中，可以调阅审核工作文件，列席相关审核会议。 中国证监会定期或者不定期按一定比例对交易所发行上市审核和发行承销过程监管等相关工作进行抽查。 对于中国证监会在检查和抽查等监督过程中发现的问题，交易所应当整改。"},{"i":75,"n":"第七十五条","txt":"交易所发行上市审核工作违反本办法规定，有下列情形之一的，由中国证监会责令改正；情节严重的，追究直接责任人员相关责任： （一）未按审核标准开展发行上市审核工作； （二）未按审核程序开展发行上市审核工作； （三）不配合中国证监会对发行上市审核工作和发行承销监管工作的检查、抽查，或者不按中国证监会的整改要求进行整改。"},{"i":76,"n":"第七十六条","txt":"上市公司在证券发行文件中隐瞒重要事实或者编造重大虚假内容的，中国证监会采取五年内不接受上市公司发行证券相关文件的监管措施。对相关责任人员，视情节轻重，采取认定为不适当人选的监管措施，或者采取证券市场禁入的措施。"},{"i":77,"n":"第七十七条","txt":"存在下列情形之一的，中国证监会采取三年至五年内不接受上市公司发行证券相关文件的监管措施： （一）申请文件存在虚假记载、误导性陈述或者重大遗漏； （二）上市公司阻碍或者拒绝中国证监会、交易所依法对其实施检查、核查； （三）上市公司及其关联方以不正当手段严重干扰发行上市审核或者发行注册工作； （四）重大事项未报告、未披露； （五）上市公司及其董事、监事、高级管理人员、控股股东、实际控制人的签名、盖章系伪造或者变造。"},{"i":78,"n":"第七十八条","txt":"上市公司控股股东、实际控制人违反本办法的规定，致使上市公司所报送的申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏，或者组织、指使上市公司进行财务造假、利润操纵或者在证券发行文件中隐瞒重要事实或者编造重大虚假内容的，中国证监会视情节轻重，对相关单位和责任人员采取一年到五年内不接受相关单位及其控制的下属单位发行证券相关文件，对责任人员采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。 上市公司董事、监事和高级管理人员违反本办法规定，致使上市公司所报送的申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，对责任人员采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。"},{"i":79,"n":"第七十九条","txt":"保荐人未勤勉尽责，致使上市公司信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，采取暂停保荐人业务资格一年至三年，责令保荐人更换相关负责人的监管措施；情节严重的，撤销保荐人业务资格，对相关责任人员采取证券市场禁入的措施。 保荐代表人未勤勉尽责，致使上市公司信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，按规定认定为不适当人选。 证券服务机构未勤勉尽责，致使上市公司信息披露资料中与其职责有关的内容及其所出具的文件存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，采取三个月至三年内不接受相关单位及其责任人员出具的发行证券专项文件的监管措施；情节严重的，对证券服务机构相关责任人员采取证券市场禁入的措施。"},{"i":80,"n":"第八十条","txt":"保荐人存在下列情形之一的，中国证监会视情节轻重，采取暂停保荐人业务资格三个月至三年的监管措施；情节特别严重的，撤销其业务资格： （一）伪造或者变造签字、盖章； （二）重大事项未报告或者未披露； （三）以不正当手段干扰审核注册工作； （四）不履行其他法定职责。 保荐代表人存在前款规定情形的，视情节轻重，按规定三个月至三年不受理相关保荐代表人具体负责的推荐；情节特别严重的，按规定认定为不适当人选。 证券服务机构及其相关人员存在第一款规定情形的，中国证监会视情节轻重，采取三个月至三年内不接受相关单位及其责任人员出具的发行证券专项文件的监管措施。"},{"i":81,"n":"第八十一条","txt":"保荐人、证券服务机构及其责任人员存在下列情形之一的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、一年内不接受相关单位及其责任人员出具的与注册申请有关的文件等监管措施；情节严重的，可以同时采取三个月至一年内不接受相关单位及其责任人员出具的发行证券专项文件的监管措施： （一）制作或者出具的文件不齐备或者不符合要求； （二）擅自改动申请文件、信息披露资料或者其他已提交文件； （三）申请文件或者信息披露资料存在相互矛盾或者同一事实表述不一致且有实质性差异； （四）文件披露的内容表述不清，逻辑混乱，严重影响阅读理解； （五）对重大事项未及时报告或者未及时披露。 上市公司存在前款规定情形的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、六个月至一年内不接受上市公司发行证券相关文件的监管措施。"},{"i":82,"n":"第八十二条","txt":"按照本办法第二十八条申请注册的，交易所和中国证监会发现上市公司或者相关中介机构及其责任人员存在相关违法违规行为的，中国证监会按照本章规定从重处罚，并采取三年至五年内不接受上市公司和保荐人该类发行证券相关文件的监管措施。"},{"i":83,"n":"第八十三条","txt":"上市公司披露盈利预测，利润实现数如未达到盈利预测的百分之八十的，除因不可抗力外，其法定代表人、财务负责人应当在股东大会以及证券交易所网站、符合中国证监会规定条件的媒体上公开作出解释并道歉；中国证监会可以对法定代表人处以警告。 利润实现数未达到盈利预测百分之五十的，除因不可抗力外，中国证监会在三年内不接受上市公司发行证券相关文件。 注册会计师为上述盈利预测出具审核报告的过程中未勤勉尽责的，中国证监会视情节轻重，对相关机构和责任人员采取监管谈话等监管措施；情节严重的，给予警告等行政处罚。"},{"i":84,"n":"第八十四条","txt":"参与认购的投资者擅自转让限售期限未满的证券的，中国证监会可以责令改正；情节严重的，十二个月内不得作为特定对象认购证券。"},{"i":85,"n":"第八十五条","txt":"相关主体违反本办法第六十六条规定的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、认定为不适当人选、一年至三年内不接受发行证券相关文件的监管措施，以及市场禁入的措施；保荐人、证券服务机构未勤勉尽责的，中国证监会还可以采取一年至三年内不接受相关单位及其责任人员出具的与注册申请有关的文件等监管措施。"},{"i":86,"n":"第八十六条","txt":"上市公司及其控股股东和实际控制人、董事、监事、高级管理人员，保荐人、承销商、证券服务机构及其相关执业人员、参与认购的投资者，在证券发行并上市相关的活动中存在其他违反本办法规定行为的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告、认定为不适当人选、暂不受理与行政许可有关的文件等监管措施，或者采取证券市场禁入的措施。"},{"i":87,"n":"第八十七条","txt":"上市公司及其控股股东、实际控制人、保荐人、证券服务机构及其相关人员违反《证券法》依法应予以行政处罚的，中国证监会依法予以处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":88,"n":"第八十八条","txt":"本办法所称战略投资者，是指符合下列情形之一，且具有同行业或者相关行业较强的重要战略性资源，与上市公司谋求双方协调互补的长期共同战略利益，愿意长期持有上市公司较大比例股份，愿意并且有能力认真履行相应职责，委派董事实际参与公司治理，提升上市公司治理水平，帮助上市公司显著提高公司质量和内在价值，具有良好诚信记录，最近三年未受到中国证监会行政处罚或者被追究刑事责任的投资者： （一）能够给上市公司带来国际国内领先的核心技术资源，显著增强上市公司的核心竞争力和创新能力，带动上市公司的产业技术升级，显著提升上市公司的盈利能力； （二）能够给上市公司带来国际国内领先的市场、渠道、品牌等战略性资源，大幅促进上市公司市场拓展，推动实现上市公司销售业绩大幅提升。 境外战略投资者应当同时遵守国家的相关规定。"},{"i":89,"n":"第八十九条","txt":"符合《若干意见》等规定的红筹企业，首次公开发行股票并在创业板上市后，发行股票还应当符合本办法的规定。 符合《若干意见》等规定的红筹企业，首次公开发行存托凭证并在创业板上市后，发行以红筹企业新增证券为基础证券的存托凭证，适用《证券法》《若干意见》以及本办法关于上市公司发行股票的规定，本办法没有规定的，适用中国证监会关于存托凭证的有关规定。 发行存托凭证的红筹企业境外基础股票配股时，相关方案安排应确保存托凭证持有人实际享有权益与境外基础股票持有人权益相当。"},{"i":90,"n":"第九十条","txt":"上市公司发行优先股、向员工发行证券用于激励的办法，由中国证监会另行规定。"},{"i":91,"n":"第九十一条","txt":"上市公司向特定对象发行股票将导致上市公司控制权发生变化的，还应当符合中国证监会的其他规定。"},{"i":92,"n":"第九十二条","txt":"依据本办法通过向特定对象发行股票取得的上市公司股份，其减持不适用《上市公司股东、董监高减持股份的若干规定》的有关规定。"},{"i":93,"n":"第九十三条","txt":"本办法自公布之日起施行。《创业板上市公司证券发行管理暂行办法》（证监会令第164号）同时废止。"}],"chuangyebanshoucigongkaifaxinggupiaozhuceguanlibanceae1e":[{"i":1,"n":"第一条","txt":"为规范在深圳证券交易所创业板试点注册制首次公开发行股票相关活动，促进成长型创新创业企业的发展，保护投资者合法权益和社会公共利益，根据《中华人民共和国证券法》《国务院办公厅关于贯彻实施修订后的证券法有关工作的通知》《国务院办公厅转发证监会关于开展创新企业境内发行股票或存托凭证试点若干意见的通知》（以下简称《若干意见》）及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内首次公开发行并在深圳证券交易所创业板（以下简称创业板）上市的股票的发行注册，适用本办法。"},{"i":3,"n":"第三条","txt":"发行人申请首次公开发行股票并在创业板上市，应当符合创业板定位。 创业板深入贯彻创新驱动发展战略，适应发展更多依靠创新、创造、创意的大趋势，主要服务成长型创新创业企业，支持传统产业与新技术、新产业、新业态、新模式深度融合。"},{"i":4,"n":"第四条","txt":"中国证券监督管理委员会（以下简称中国证监会）加强对审核注册工作的统筹指导，统一审核理念，统一审核标准，定期检查深圳证券交易所（以下简称交易所）审核标准、制度的执行情况。"},{"i":5,"n":"第五条","txt":"首次公开发行股票并在创业板上市，应当符合发行条件、上市条件以及相关信息披露要求，依法经交易所发行上市审核，并报中国证监会注册。"},{"i":6,"n":"第六条","txt":"发行人应当诚实守信，依法充分披露投资者作出价值判断和投资决策所必需的信息，所披露信息必须真实、准确、完整，简明清晰、通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 发行人应当按保荐人、证券服务机构要求，依法向其提供真实、准确、完整的财务会计资料和其他资料，配合相关机构开展尽职调查和其他相关工作。 发行人的控股股东、实际控制人、董事、监事、高级管理人员应当配合相关机构开展尽职调查和其他相关工作，不得要求或者协助发行人隐瞒应当提供的资料或者应当披露的信息。"},{"i":7,"n":"第七条","txt":"保荐人应当诚实守信，勤勉尽责，按照依法制定的业务规则和行业自律规范的要求，充分了解发行人经营情况和风险，对注册申请文件和信息披露资料进行全面核查验证，对发行人是否符合发行条件、上市条件独立作出专业判断，审慎作出推荐决定，并对招股说明书及其所出具的相关文件的真实性、准确性、完整性负责。"},{"i":8,"n":"第八条","txt":"证券服务机构应当严格遵守法律法规、中国证监会制定的监管规则、业务规则和本行业公认的业务标准和道德规范，建立并保持有效的质量控制体系，保护投资者合法权益，审慎履行职责，作出专业判断与认定，并对招股说明书或者其他信息披露文件中与其专业职责有关的内容及其所出具的文件的真实性、准确性、完整性负责。 证券服务机构及其相关执业人员应当对与本专业相关的业务事项履行特别注意义务，对其他业务事项履行普通注意义务，并承担相应法律责任。 证券服务机构及其执业人员从事证券服务应当配合中国证监会的监督管理，在规定的期限内提供、报送或披露相关资料、信息，并保证其提供、报送或披露的资料、信息真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 证券服务机构应当妥善保存客户委托文件、核查和验证资料、工作底稿以及与质量控制、内部管理、业务经营有关的信息和资料。"},{"i":9,"n":"第九条","txt":"对发行人首次公开发行股票申请予以注册，不表明中国证监会和交易所对该股票的投资价值或者投资者的收益作出实质性判断或者保证，也不表明中国证监会和交易所对注册申请文件的真实性、准确性、完整性作出保证。"},{"i":10,"n":"第十条","txt":"发行人是依法设立且持续经营三年以上的股份有限公司，具备健全且运行良好的组织机构，相关机构和人员能够依法履行职责。 有限责任公司按原账面净资产值折股整体变更为股份有限公司的，持续经营时间可以从有限责任公司成立之日起计算。"},{"i":11,"n":"第十一条","txt":"发行人会计基础工作规范，财务报表的编制和披露符合企业会计准则和相关信息披露规则的规定，在所有重大方面公允地反映了发行人的财务状况、经营成果和现金流量，最近三年财务会计报告由注册会计师出具无保留意见的审计报告。 发行人内部控制制度健全且被有效执行，能够合理保证公司运行效率、合法合规和财务报告的可靠性，并由注册会计师出具无保留结论的内部控制鉴证报告。"},{"i":12,"n":"第十二条","txt":"发行人业务完整，具有直接面向市场独立持续经营的能力： （一）资产完整，业务及人员、财务、机构独立，与控股股东、实际控制人及其控制的其他企业间不存在对发行人构成重大不利影响的同业竞争，不存在严重影响独立性或者显失公平的关联交易； （二）主营业务、控制权和管理团队稳定，最近二年内主营业务和董事、高级管理人员均没有发生重大不利变化；控股股东和受控股股东、实际控制人支配的股东所持发行人的股份权属清晰，最近二年实际控制人没有发生变更，不存在导致控制权可能变更的重大权属纠纷； （三）不存在涉及主要资产、核心技术、商标等的重大权属纠纷，重大偿债风险，重大担保、诉讼、仲裁等或有事项，经营环境已经或者将要发生重大变化等对持续经营有重大不利影响的事项。"},{"i":13,"n":"第十三条","txt":"发行人生产经营符合法律、行政法规的规定，符合国家产业政策。 最近三年内，发行人及其控股股东、实际控制人不存在贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的刑事犯罪，不存在欺诈发行、重大信息披露违法或者其他涉及国家安全、公共安全、生态安全、生产安全、公众健康安全等领域的重大违法行为。 董事、监事和高级管理人员不存在最近三年内受到中国证监会行政处罚，或者因涉嫌犯罪正在被司法机关立案侦查或者涉嫌违法违规正在被中国证监会立案调查且尚未有明确结论意见等情形。"},{"i":14,"n":"第十四条","txt":"发行人董事会应当依法就本次发行股票的具体方案、本次募集资金使用的可行性及其他必须明确的事项作出决议，并提请股东大会批准。"},{"i":15,"n":"第十五条","txt":"发行人股东大会应当就本次发行股票作出决议，决议至少应当包括下列事项： （一）本次公开发行股票的种类和数量； （二）发行对象； （三）定价方式； （四）募集资金用途； （五）发行前滚存利润的分配方案； （六）决议的有效期； （七）对董事会办理本次发行具体事宜的授权； （八）其他必须明确的事项。"},{"i":16,"n":"第十六条","txt":"发行人申请首次公开发行股票并在创业板上市，应当按照中国证监会有关规定制作注册申请文件，依法由保荐人保荐并向交易所申报。 交易所收到注册申请文件后，五个工作日内作出是否受理的决定。"},{"i":17,"n":"第十七条","txt":"注册申请文件受理后，未经中国证监会或者交易所同意，不得改动。 发生重大事项的，发行人、保荐人、证券服务机构应当及时向交易所报告，并按要求更新注册申请文件和信息披露资料。"},{"i":18,"n":"第十八条","txt":"交易所设立独立的审核部门，负责审核发行人公开发行并上市申请；设立行业咨询专家库，负责为创业板建设和发行上市审核提供专业咨询和政策建议；设立创业板上市委员会，负责对审核部门出具的审核报告和发行人的申请文件提出审议意见。 交易所主要通过向发行人提出审核问询、发行人回答问题方式开展审核工作，判断发行人是否符合发行条件、上市条件和信息披露要求。"},{"i":19,"n":"第十九条","txt":"交易所按照规定的条件和程序，形成发行人是否符合发行条件和信息披露要求的审核意见。认为发行人符合发行条件和信息披露要求的，将审核意见、发行人注册申请文件及相关审核资料报中国证监会注册；认为发行人不符合发行条件或者信息披露要求的，作出终止发行上市审核决定。"},{"i":20,"n":"第二十条","txt":"交易所应当自受理注册申请文件之日起在规定的时限内形成审核意见。发行人根据要求补充、修改注册申请文件，或者交易所按照规定对发行人实施现场检查，要求保荐人、证券服务机构对有关事项进行专项核查，并要求发行人补充、修改申请文件的时间不计算在内。"},{"i":21,"n":"第二十一条","txt":"交易所应当提高审核工作透明度，接受社会监督，公开下列事项： （一）发行上市审核标准和程序等发行上市审核业务规则和相关业务细则； （二）在审企业名单、企业基本情况及审核工作进度； （三）发行上市审核问询及回复情况，但涉及国家秘密或者发行人商业秘密的除外； （四）上市委员会会议的时间、参会委员名单、审议的发行人名单、审议结果及现场问询问题； （五）对股票公开发行并上市相关主体采取的自律监管措施或者纪律处分； （六）交易所规定的其他事项。"},{"i":22,"n":"第二十二条","txt":"中国证监会依法履行发行注册程序，发行注册主要关注交易所发行上市审核内容有无遗漏，审核程序是否符合规定，以及发行人在发行条件和信息披露要求的重大方面是否符合相关规定。中国证监会认为存在需要进一步说明或者落实事项的，可以要求交易所进一步问询。 中国证监会认为交易所对影响发行条件的重大事项未予关注或者交易所的审核意见依据明显不充分的，可以退回交易所补充审核。交易所补充审核后，认为发行人符合发行条件和信息披露要求的，重新向中国证监会报送审核意见及相关资料，本办法第二十三条规定的注册期限重新计算。"},{"i":23,"n":"第二十三条","txt":"中国证监会在二十个工作日内对发行人的注册申请作出予以注册或者不予注册的决定。发行人根据要求补充、修改注册申请文件，或者中国证监会要求交易所进一步问询，要求保荐人、证券服务机构等对有关事项进行核查，对发行人现场检查，并要求发行人补充、修改申请文件的时间不计算在内。"},{"i":24,"n":"第二十四条","txt":"中国证监会的予以注册决定，自作出之日起一年内有效，发行人应当在注册决定有效期内发行股票，发行时点由发行人自主选择。"},{"i":25,"n":"第二十五条","txt":"中国证监会作出予以注册决定后、发行人股票上市交易前，发行人应当及时更新信息披露文件内容，财务报表已过有效期的，发行人应当补充财务会计报告等文件；保荐人以及证券服务机构应当持续履行尽职调查职责；发生重大事项的，发行人、保荐人应当及时向交易所报告。 交易所应当对上述事项及时处理，发现发行人存在重大事项影响发行条件、上市条件的，应当出具明确意见并及时向中国证监会报告。"},{"i":26,"n":"第二十六条","txt":"中国证监会作出予以注册决定后、发行人股票上市交易前，发现可能影响本次发行的重大事项的，中国证监会可以要求发行人暂缓发行、上市；相关重大事项导致发行人不符合发行条件的，应当撤销注册。中国证监会撤销注册后，股票尚未发行的，发行人应当停止发行；股票已经发行尚未上市的，发行人应当按照发行价并加算银行同期存款利息返还股票持有人。"},{"i":27,"n":"第二十七条","txt":"交易所认为发行人不符合发行条件或者信息披露要求，作出终止发行上市审核决定，或者中国证监会作出不予注册决定的，自决定作出之日起六个月后，发行人可以再次提出公开发行股票并上市申请。"},{"i":28,"n":"第二十八条","txt":"中国证监会应当按规定公开股票发行注册行政许可事项相关的监管信息。"},{"i":29,"n":"第二十九条","txt":"存在下列情形之一的，发行人、保荐人应当及时书面报告交易所或者中国证监会，交易所或者中国证监会应当中止相应发行上市审核程序或者发行注册程序： （一）相关主体涉嫌违反本办法第十三条第二款规定，被立案调查或者被司法机关侦查，尚未结案； （二）发行人的保荐人以及律师事务所、会计师事务所等证券服务机构因首次公开发行股票、上市公司证券发行、并购重组业务涉嫌违法违规，或者其他业务涉嫌违法违规且对市场有重大影响，正在被中国证监会立案调查，或者正在被司法机关侦查，尚未结案； （三）发行人的签字保荐代表人以及签字律师、签字会计师等证券服务机构签字人员因首次公开发行股票、上市公司证券发行、并购重组业务涉嫌违法违规，或者其他业务涉嫌违法违规且对市场有重大影响，正在被中国证监会立案调查，或者正在被司法机关侦查，尚未结案； （四）发行人的保荐人以及律师事务所、会计师事务所等证券服务机构被中国证监会依法采取限制业务"},{"i":30,"n":"第三十条","txt":"存在下列情形之一的，交易所或者中国证监会应当终止相应发行上市审核程序或者发行注册程序，并向发行人说明理由： （一）发行人撤回注册申请或者保荐人撤销保荐； （二）发行人未在要求的期限内对注册申请文件作出解释说明或者补充、修改； （三）注册申请文件存在虚假记载、误导性陈述或者重大遗漏； （四）发行人阻碍或者拒绝中国证监会、交易所依法对发行人实施检查、核查； （五）发行人及其关联方以不正当手段严重干扰发行上市审核或者发行注册工作； （六）发行人法人资格终止； （七）注册申请文件内容存在重大缺陷，严重影响投资者理解和发行上市审核或者发行注册工作； （八）发行人注册申请文件中记载的财务资料已过有效期且逾期三个月未更新； （九）发行人发行上市审核程序中止超过交易所规定的时限或者发行注册程序中止超过三个月仍未恢复； （十）交易所认为发行人不符合发行条件或者信息披露要求； （十一）中国证监会规定的其他"},{"i":31,"n":"第三十一条","txt":"中国证监会和交易所可以对发行人进行现场检查，可以要求保荐人、证券服务机构对有关事项进行专项核查并出具意见。 中国证监会和交易所应当建立健全信息披露质量现场检查以及对保荐业务、发行承销业务的常态化检查制度。"},{"i":32,"n":"第三十二条","txt":"中国证监会与交易所建立全流程电子化审核注册系统，实现电子化受理、审核，发行注册各环节实时信息共享，并依法向社会公开相关信息。"},{"i":33,"n":"第三十三条","txt":"发行人申请首次公开发行股票并在创业板上市，应当按照中国证监会制定的信息披露规则，编制并披露招股说明书，保证相关信息真实、准确、完整。信息披露内容应当简明清晰，通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 中国证监会制定的信息披露规则是信息披露的最低要求。不论上述规则是否有明确规定，凡是投资者作出价值判断和投资决策所必需的信息，发行人均应当充分披露，内容应当真实、准确、完整。"},{"i":34,"n":"第三十四条","txt":"中国证监会依法制定招股说明书内容与格式准则、编报规则等信息披露规则，对相关信息披露文件的内容、格式、编制要求、披露形式等作出规定。 交易所可以依据中国证监会部门规章和规范性文件，制定信息披露细则或指引，在中国证监会确定的信息披露内容范围内，对信息披露提出细化和补充要求，报中国证监会批准后实施。"},{"i":35,"n":"第三十五条","txt":"发行人及其董事、监事、高级管理人员应当在招股说明书上签字、盖章，保证招股说明书的内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，按照诚信原则履行承诺，并声明承担相应法律责任。 发行人控股股东、实际控制人应当在招股说明书上签字、盖章，确认招股说明书的内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，按照诚信原则履行承诺，并声明承担相应法律责任。"},{"i":36,"n":"第三十六条","txt":"保荐人及其保荐代表人应当在招股说明书上签字、盖章，确认招股说明书的内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":37,"n":"第三十七条","txt":"为证券发行出具专项文件的律师、注册会计师、资产评估人员、资信评级人员以及其所在机构，应当在招股说明书上签字、盖章，确认对发行人信息披露文件引用其出具的专业意见无异议，信息披露文件不因引用其出具的专业意见而出现虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":38,"n":"第三十八条","txt":"发行人应当以投资者需求为导向，结合所属行业的特点和发展趋势，充分披露自身的创新、创造、创意特征，针对性披露科技创新、模式创新或者业态创新情况，以及对新旧产业融合的促进作用，充分披露业务模式、公司治理、发展战略、经营政策、会计政策、财务状况分析等信息。"},{"i":39,"n":"第三十九条","txt":"发行人应当以投资者需求为导向，精准清晰充分地披露可能对公司经营业绩、核心竞争力、业务稳定性以及未来发展产生重大不利影响的各种风险因素。"},{"i":40,"n":"第四十条","txt":"发行人尚未盈利的，应当充分披露尚未盈利的成因，以及对公司现金流、业务拓展、人才吸引、团队稳定性、研发投入、战略性投入、生产经营可持续性等方面的影响。"},{"i":41,"n":"第四十一条","txt":"发行人应当披露募集资金的投向和使用管理制度，披露募集资金对发行人主营业务发展的贡献、未来经营战略的影响以及发行人业务创新、创造、创意性的支持作用。"},{"i":42,"n":"第四十二条","txt":"符合相关规定、存在特别表决权股份的企业申请首次公开发行股票并在创业板上市的，发行人应当在招股说明书等公开发行文件中，披露并特别提示差异化表决安排的主要内容、相关风险和对公司治理的影响，以及依法落实保护投资者合法权益的各项措施。 保荐人和发行人律师应当就公司章程规定的特别表决权股份的持有人资格、特别表决权股份拥有的表决权数量与普通股份拥有的表决权数量的比例安排、持有人所持特别表决权股份能够参与表决的股东大会事项范围、特别表决权股份锁定安排以及转让限制等事项是否符合有关规定发表专业意见。"},{"i":43,"n":"第四十三条","txt":"发行人应当在招股说明书中披露公开发行股份前已发行股份的锁定期安排，特别是尚未盈利情况下发行人控股股东、实际控制人、董事、监事、高级管理人员股份的锁定期安排。 保荐人和发行人律师应当就前款事项是否符合有关规定发表专业意见。"},{"i":44,"n":"第四十四条","txt":"招股说明书的有效期为六个月，自公开发行前最后一次签署之日起算。 招股说明书引用经审计的财务报表在其最近一期截止日后六个月内有效，特殊情况下发行人可申请适当延长，但至多不超过三个月。财务报表应当以年度末、半年度末或者季度末为截止日。"},{"i":45,"n":"第四十五条","txt":"交易所受理注册申请文件后，发行人应当按规定，将招股说明书、发行保荐书、上市保荐书、审计报告和法律意见书等文件在交易所网站预先披露。"},{"i":46,"n":"第四十六条","txt":"预先披露的招股说明书及其他注册申请文件不能含有价格信息，发行人不得据此发行股票。 发行人应当在预先披露的招股说明书显要位置作如下声明：“本公司的发行申请尚需经深圳证券交易所和中国证监会履行相应程序。本招股说明书不具有据以发行股票的法律效力，仅供预先披露之用。投资者应当以正式公告的招股说明书作为投资决定的依据。”"},{"i":47,"n":"第四十七条","txt":"交易所认为发行人符合发行条件和信息披露要求，将发行人注册申请文件报送中国证监会时，招股说明书、发行保荐书、上市保荐书、审计报告和法律意见书等文件应当同步在交易所网站和中国证监会网站公开。"},{"i":48,"n":"第四十八条","txt":"发行人在发行股票前应当在交易所网站和符合中国证监会规定条件的网站全文刊登招股说明书，同时在符合中国证监会规定条件的报刊刊登提示性公告，告知投资者网上刊登的地址及获取文件的途径。 发行人可以将招股说明书以及有关附件刊登于其他网站，但披露内容应当完全一致，且不得早于在交易所网站、符合中国证监会规定条件的网站的披露时间。 保荐人出具的发行保荐书、证券服务机构出具的文件以及其他与发行有关的重要文件应当作为招股说明书的附件。"},{"i":49,"n":"第四十九条","txt":"首次公开发行股票并在创业板上市的发行与承销行为，适用《证券发行与承销管理办法》，本办法和《创业板首次公开发行证券发行与承销特别规定》另有规定的除外。"},{"i":50,"n":"第五十条","txt":"交易所应当根据《证券发行与承销管理办法》、本办法以及中国证监会相关规定制定创业板股票发行承销业务规则，并报中国证监会批准。 创业板首次公开发行股票的定价方式、投资者报价要求、最高报价剔除比例、发行价格确定、网下初始配售比例、网下优先配售比例、网上网下回拨机制、网下分类配售安排、网下配售锁定安排、战略配售、超额配售选择权等事项，应当同时遵守交易所相关规定。"},{"i":51,"n":"第五十一条","txt":"首次公开发行股票采用询价方式的，应当向证券公司、基金管理公司、信托公司、财务公司、保险公司、合格境外机构投资者和私募基金管理人等专业机构投资者（以下统称网下投资者）询价。网下投资者参与询价，应当向中国证券业协会注册，并接受自律管理。 发行人和主承销商可以在符合中国证监会相关规定和证券交易所、中国证券业协会自律规则前提下，协商设置参与询价的网下投资者具体条件，并在发行公告中预先披露。"},{"i":52,"n":"第五十二条","txt":"战略投资者在承诺的持有期限内，可以按规定向证券金融公司借出获得配售的股票。借出期限届满后，证券金融公司应当将借入的股票返还给战略投资者。"},{"i":53,"n":"第五十三条","txt":"保荐人的相关子公司或者保荐人所属证券公司的相关子公司参与发行人股票配售的具体规则由交易所另行规定。"},{"i":54,"n":"第五十四条","txt":"中国证监会作出予以注册的决定后，发行人与主承销商应当及时向交易所报备发行与承销方案。交易所在五个工作日内无异议的，发行人与主承销商可以依法刊登招股意向书，启动发行工作。"},{"i":55,"n":"第五十五条","txt":"交易所对证券发行承销过程实施监管。发行承销涉嫌违法违规或者存在异常情形的，中国证监会可以要求交易所进行调查处理，或者直接责令发行人和承销商暂停或者中止发行。"},{"i":56,"n":"第五十六条","txt":"中国证监会负责建立健全以信息披露为中心的注册制规则体系，制定股票发行注册并上市的规章规则，依法批准交易所制定的有关业务规则，并监督相关业务规则执行情况。"},{"i":57,"n":"第五十七条","txt":"中国证监会建立对交易所发行上市审核工作和发行承销过程监管的监督机制，持续关注交易所审核情况和发行承销过程监管情况。"},{"i":58,"n":"第五十八条","txt":"中国证监会对交易所发行上市审核和发行承销过程监管等相关工作进行年度例行检查，在检查过程中，可以调阅审核工作文件，列席相关审核会议。 中国证监会定期或者不定期按一定比例对交易所发行上市审核和发行承销过程监管等相关工作进行抽查。 对于中国证监会在检查和抽查等监督过程中发现的问题，交易所应当整改。"},{"i":59,"n":"第五十九条","txt":"中国证监会建立对发行上市监管全流程的权力运行监督制约机制，对发行上市审核程序和发行注册程序相关内控制度运行情况进行督导督察，对廉政纪律执行情况和相关人员的履职尽责情况进行监督监察。"},{"i":60,"n":"第六十条","txt":"交易所应当建立内部防火墙制度，发行上市审核部门、发行承销监管部门与其他部门隔离运行。参与发行上市审核的人员，不得与发行人及其控股股东、实际控制人、相关保荐人、证券服务机构有利害关系，不得直接或者间接与发行人、保荐人、证券服务机构有利益往来，不得持有发行人股票，不得私下与发行人接触。"},{"i":61,"n":"第六十一条","txt":"交易所应当建立定期报告制度，及时总结发行上市审核和发行承销监管的工作情况，并报告中国证监会。"},{"i":62,"n":"第六十二条","txt":"交易所发行上市审核工作违反本办法规定，有下列情形之一的，由中国证监会责令改正；情节严重的，追究直接责任人员相关责任： （一）未按审核标准开展发行上市审核工作； （二）未按审核程序开展发行上市审核工作； （三）不配合中国证监会对发行上市审核工作和发行承销监管工作的检查、抽查，或者不按中国证监会的整改要求进行整改。"},{"i":63,"n":"第六十三条","txt":"发行人在证券发行文件中隐瞒重要事实或者编造重大虚假内容的，中国证监会采取五年内不接受发行人公开发行证券相关文件的监管措施；对相关责任人员，视情节轻重，采取认定为不适当人选的监管措施，或者采取证券市场禁入的措施。"},{"i":64,"n":"第六十四条","txt":"发行人存在本办法第三十条第（三）项、第（四）项、第（五）项规定的情形，重大事项未报告、未披露，或者发行人及其董事、监事、高级管理人员、控股股东、实际控制人的签字、盖章系伪造或者变造的，中国证监会采取三年至五年内不接受发行人公开发行证券相关文件的监管措施。"},{"i":65,"n":"第六十五条","txt":"发行人的控股股东、实际控制人违反本办法规定，致使发行人所报送的注册申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏，或者组织、指使发行人进行财务造假、利润操纵或者在证券发行文件中隐瞒重要事实或编造重大虚假内容的，中国证监会视情节轻重，对相关单位和责任人员采取一年到五年内不接受相关单位及其控制的下属单位公开发行证券相关文件，对责任人员采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。 发行人的董事、监事和高级管理人员违反本办法规定，致使发行人所报送的注册申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，对责任人员采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。"},{"i":66,"n":"第六十六条","txt":"保荐人未勤勉尽责，致使发行人信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，采取暂停保荐人业务资格一年到三年，或者责令保荐人更换相关负责人的监管措施；情节严重的，撤销保荐人业务资格，并对相关责任人员采取证券市场禁入的措施。 保荐代表人未勤勉尽责，致使发行人信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，按规定认定为不适当人选。 证券服务机构未勤勉尽责，致使发行人信息披露资料中与其职责有关的内容及其所出具的文件存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，采取三个月至三年不接受相关单位及其责任人员出具的发行证券专项文件的监管措施；情节严重的，对证券服务机构相关责任人员采取证券市场禁入的措施。"},{"i":67,"n":"第六十七条","txt":"保荐人存在下列情形之一的，中国证监会视情节轻重，采取暂停保荐人业务资格三个月至三年的监管措施；情节特别严重的，撤销其业务资格： （一）伪造或者变造签字、盖章； （二）重大事项未报告、未披露； （三）以不正当手段干扰审核注册工作； （四）不履行其他法定职责。 保荐代表人存在前款规定情形之一的，中国证监会视情节轻重，三个月至三年不受理其具体负责的推荐；情节严重的，认定为不适当人选。 证券服务机构及其相关人员存在第一款规定情形的，中国证监会视情节轻重，采取三个月至三年不接受相关单位及其责任人员出具的发行证券专项文件的监管措施。"},{"i":68,"n":"第六十八条","txt":"保荐人、证券服务机构存在以下情形之一的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、一年内不接受相关单位及其责任人员出具的与注册申请有关的文件等监管措施；情节严重的，可以同时采取三个月到一年内不接受相关单位及其责任人员出具的发行证券专项文件的监管措施： （一）制作或者出具的文件不齐备或者不符合要求； （二）擅自改动注册申请文件、信息披露资料或者其他已提交文件； （三）注册申请文件或者信息披露资料存在相互矛盾或者同一事实表述不一致且有实质性差异； （四）文件披露的内容表述不清，逻辑混乱，严重影响投资者理解； （五）未及时报告或者未及时披露重大事项。 发行人存在前款规定情形的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、六个月至一年内不接受发行人公开发行证券相关文件的监管措施。"},{"i":69,"n":"第六十九条","txt":"发行人披露盈利预测，利润实现数如未达到盈利预测的百分之八十的，除因不可抗力外，其法定代表人、财务负责人应当在股东大会以及证券交易所网站、符合中国证监会规定条件的媒体上公开作出解释并道歉；中国证监会可以对法定代表人处以警告。 利润实现数未达到盈利预测的百分之五十的，除因不可抗力外，中国证监会在三年内不受理该公司的公开发行证券申请。 注册会计师为上述盈利预测出具审核报告的过程中未勤勉尽责的，中国证监会视情节轻重，对相关机构和责任人员采取监管谈话等监管措施；情节严重的，给予警告等行政处罚。"},{"i":70,"n":"第七十条","txt":"发行人及其控股股东和实际控制人、董事、监事、高级管理人员，保荐人、承销商、证券服务机构及其相关执业人员，在股票公开发行并上市相关的活动中存在其他违反本办法规定行为的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告、认定为不适当人选、暂不受理与行政许可有关的文件等监管措施，或者采取证券市场禁入的措施。"},{"i":71,"n":"第七十一条","txt":"发行人及其控股股东、实际控制人、保荐人、证券服务机构及其相关人员违反《中华人民共和国证券法》依法应予以行政处罚的，中国证监会将依法予以处罚。涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":72,"n":"第七十二条","txt":"交易所负责对发行人及其控股股东、实际控制人、保荐人、承销商、证券服务机构等进行自律监管。 中国证券业协会负责制定保荐业务、发行承销自律监管规则，对保荐人、承销商、保荐代表人、网下投资者进行自律监管。 交易所和中国证券业协会应当对发行上市过程中违反自律监管规则的行为采取自律监管措施或者给予纪律处分。"},{"i":73,"n":"第七十三条","txt":"中国证监会将遵守本办法的情况记入证券市场诚信档案，会同有关部门加强信息共享，依法实施守信激励与失信惩戒。"},{"i":74,"n":"第七十四条","txt":"符合《若干意见》等规定的红筹企业，申请首次公开发行股票并在创业板上市，应当同时符合本办法的规定，但公司形式可以适用其注册地法律规定；申请发行存托凭证并在创业板上市的，发行上市审核注册程序适用本办法的规定。 前款规定的红筹企业在创业板发行上市，适用《若干意见》“营业收入快速增长，拥有自主研发、国际领先技术，同行业竞争中处于相对优势地位”的具体标准由交易所制定，并报中国证监会批准。"},{"i":75,"n":"第七十五条","txt":"本办法自公布之日起施行。《首次公开发行股票并在创业板上市管理办法》（证监会令第142号）同时废止。"}],"beijingzhengquanjiaoyisuoshangshigongsichixujiangu93471d":[{"i":1,"n":"第一条","txt":"为了规范企业股票在北京证券交易所（以下简称北交所）上市后相关各方的行为，支持引导创新型中小企业更好地发展，保护投资者合法权益，根据《中华人民共和国证券法》（以下简称《证券法》）、《中华人民共和国公司法》以及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中国证券监督管理委员会（以下简称中国证监会）根据《证券法》等法律法规、本办法和中国证监会的其他相关规定，对北交所上市公司（以下简称上市公司）及相关主体进行监督管理。 中国证监会其他相关规定与本办法规定不一致的，适用本办法。 中国证监会根据北交所以服务创新型中小企业为主的特点和市场运行情况，适时完善相关具体制度安排。"},{"i":3,"n":"第三条","txt":"北交所根据《证券交易所管理办法》、本办法等有关规定，建立以上市规则为中心的持续监管规则体系，在公司治理、持续信息披露、股份减持、股权激励、员工持股计划、重大资产重组、退市等方面制定具体实施规则。上市公司应当遵守北交所持续监管实施规则。 北交所应当履行一线监管职责，加强信息披露与二级市场交易监管联动，加大现场检查力度，强化监管问询，切实防范和打击内幕交易与操纵市场行为，督促上市公司提高信息披露质量。"},{"i":4,"n":"第四条","txt":"上市公司应当增强公众公司意识，保持健全、有效、透明的治理体系和监督机制，保证股东大会、董事会、监事会规范运作，督促董事、监事和高级管理人员履行忠实、勤勉义务，明确纠纷解决机制，保障全体股东合法权利，积极履行社会责任，保护利益相关者的基本权益。 上市公司控股股东、实际控制人应当诚实守信，依法行使权利，严格履行承诺，维持公司独立性，维护公司和全体股东的共同利益。"},{"i":5,"n":"第五条","txt":"上市公司设独立董事，独立董事的选任、履职应当符合中国证监会和北交所的有关规定。"},{"i":6,"n":"第六条","txt":"鼓励上市公司根据需要设立审计、战略、提名、薪酬与考核等专门委员会，专门委员会对董事会负责，依照公司章程和董事会授权履行职责。专门委员会成员全部由董事构成，其中审计委员会、提名委员会、薪酬与考核委员会中独立董事应当占多数并担任召集人，审计委员会的召集人应当为会计专业人士。"},{"i":7,"n":"第七条","txt":"上市公司应当积极回报股东，根据自身条件和发展阶段，在公司章程中规定现金分红、股份回购等股东回报政策并严格执行。北交所可以制定股东回报相关规则。"},{"i":8,"n":"第八条","txt":"上市公司应当建立完善募集资金管理使用制度。募集资金的存放、使用、变更和持续披露等具体规则由北交所制定。"},{"i":9,"n":"第九条","txt":"上市公司存在特别表决权股份的，应当在公司章程中规定特别表决权股份的持有人资格、特别表决权股份拥有的表决权数量与普通股份拥有的表决权数量的比例安排、持有人所持特别表决权股份能够参与表决的股东大会事项范围、特别表决权股份锁定安排及转让限制、特别表决权股份与普通股份的转换情形等事项。 上市公司应当在定期报告中持续披露特别表决权安排的情况；特别表决权安排发生重大变化的，应当及时披露。 北交所应对存在特别表决权股份公司的上市条件、表决权差异的设置、存续、调整、信息披露和投资者保护事项制定有关规定。"},{"i":10,"n":"第十条","txt":"上市公司和相关信息披露义务人应当及时、公平地披露所有可能对证券交易价格或者投资决策有较大影响的事项，保证所披露信息的真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏。 上市公司应当建立并执行信息披露事务管理制度，增强信息披露的透明度。上市公司董事长对信息披露事务管理承担首要责任，董事会秘书负责组织和协调公司信息披露事务、办理信息对外公布等相关事宜。"},{"i":11,"n":"第十一条","txt":"上市公司筹划的重大事项存在较大不确定性，立即披露可能会损害公司利益或者误导投资者，且有关内幕信息知情人已书面承诺保密的，上市公司可以暂不披露，但最迟应当在该重大事项形成最终决议、签署最终协议或者交易确定能够达成时对外披露；已经泄密或者确实难以保密的，上市公司应当立即披露该信息。"},{"i":12,"n":"第十二条","txt":"上市公司应当结合所属行业的特点，充分披露行业经营信息，便于投资者合理决策。"},{"i":13,"n":"第十三条","txt":"上市公司应当充分披露可能对公司核心竞争力、经营活动和未来发展产生重大不利影响的风险因素。 上市公司尚未盈利的，应当充分披露尚未盈利的成因，以及对公司现金流、业务拓展、人才吸引、团队稳定性、研发投入、战略性投入、生产经营可持续性等方面的影响。"},{"i":14,"n":"第十四条","txt":"上市公司和相关信息披露义务人确有需要的，可以在非交易时段对外发布重大信息，但应当在下一交易时段开始前披露相关公告，不得以新闻发布或者答记者问等形式代替信息披露。"},{"i":15,"n":"第十五条","txt":"上市公司和相关信息披露义务人适用中国证监会、北交所相关信息披露规定，可能导致其难以反映经营活动的实际情况、难以符合行业监管要求等有关规定的，可以依照相关规定暂缓适用或者免于适用，但是应当充分说明原因和替代方案。中国证监会、北交所认为依法不应当调整适用的，上市公司和相关信息披露义务人应当执行相关规定。"},{"i":16,"n":"第十六条","txt":"上市公司的控股股东、实际控制人应当配合上市公司履行信息披露义务，不得要求或者协助上市公司隐瞒应当披露的信息。"},{"i":17,"n":"第十七条","txt":"上市公司应当在符合《证券法》规定的信息披露平台发布信息，在其他媒体披露信息的时间不得早于在符合《证券法》规定的信息披露平台披露的时间，并确保披露内容的一致性。"},{"i":18,"n":"第十八条","txt":"股份锁定期届满后，上市公司控股股东、实际控制人、董事、监事、高级管理人员及其他股东减持向不特定合格投资者公开发行并上市前的股份以及上市公司向特定对象发行的股份，应当遵守北交所有关减持方式、程序、价格、比例以及后续转让等事项的规定。"},{"i":19,"n":"第十九条","txt":"上市时未盈利的公司，其控股股东、实际控制人、董事、监事、高级管理人员所持向不特定合格投资者公开发行并上市前的股份锁定期应当适当延长，具体期限由北交所规定。"},{"i":20,"n":"第二十条","txt":"上市公司股东、实际控制人、董事、监事、高级管理人员减持股份应当按照中国证监会和北交所的要求及时履行信息披露义务。 持股百分之五以上股东、实际控制人、董事、监事、高级管理人员计划通过北交所集中竞价交易减持股份，应当在首次卖出的十五个交易日前预先披露减持计划，并按照北交所的规定披露减持计划实施情况；拟在三个月内减持股份的总数超过公司股份总数百分之一的，还应当在首次卖出的三十个交易日前预先披露减持计划。 持股百分之五以上股东、实际控制人减持其通过北交所和全国股转系统竞价或做市交易买入的上市公司股份，不适用前款规定。"},{"i":21,"n":"第二十一条","txt":"上市公司以本公司股票为标的实施股权激励的，应当设置合理的考核指标，有利于促进公司持续发展。"},{"i":22,"n":"第二十二条","txt":"单独或合计持有上市公司百分之五以上股份的股东或实际控制人及其配偶、父母、子女，作为董事、高级管理人员、核心技术人员或者核心业务人员的，可以成为激励对象。 上市公司应当充分说明前款规定人员成为激励对象的必要性、合理性。"},{"i":23,"n":"第二十三条","txt":"上市公司向激励对象授予的限制性股票的价格低于市场参考价百分之五十的，或者股票期权的行权价格低于市场参考价的，应当符合北交所相关规定，并应当说明定价依据及定价方式。 出现前款规定情形的，上市公司应当聘请独立财务顾问，对股权激励计划的可行性、相关定价依据和定价方法的合理性、是否有利于公司持续发展、是否损害股东利益等发表意见。"},{"i":24,"n":"第二十四条","txt":"上市公司全部在有效期内的股权激励计划所涉及的标的股票总数，累计不得超过公司股本总额的百分之三十。经股东大会特别决议批准，单个激励对象通过全部在有效期内的股权激励计划获授的本公司股票，累计可以超过公司股本总额的百分之一。"},{"i":25,"n":"第二十五条","txt":"上市公司开展员工持股计划的具体实施规则，由北交所根据中国证监会的相关规定另行制定。"},{"i":26,"n":"第二十六条","txt":"上市公司实施重大资产重组或者发行股份购买资产的，标的资产应当符合北交所相关行业要求，或者与上市公司处于同行业或上下游。"},{"i":27,"n":"第二十七条","txt":"上市公司实施重大资产重组的标准，按照《上市公司重大资产重组管理办法》（以下简称《重组办法》）第十二条予以认定，其中营业收入指标执行下列标准：购买、出售的资产在最近一个会计年度所产生的营业收入占上市公司同期经审计的合并财务会计报告营业收入的比例达到百分之五十以上，且超过五千万元人民币。 上市公司实施重大资产重组，构成《重组办法》第十三条规定的交易情形的，置入资产的具体条件由北交所制定。"},{"i":28,"n":"第二十八条","txt":"上市公司发行股份购买资产的，发行股份的价格不得低于市场参考价的百分之八十，市场参考价按照《重组办法》的规定计算。"},{"i":29,"n":"第二十九条","txt":"北交所对重大资产重组进行审核，并对信息披露、持续督导等进行自律管理。 涉及发行股份购买资产的，北交所审核通过后，报中国证监会履行注册程序。"},{"i":30,"n":"第三十条","txt":"上市公司控股股东、实际控制人质押公司股份的，应当合理使用融入资金，维持公司控制权和生产经营稳定，不得侵害公司利益或者向公司转移风险，并依据中国证监会、北交所的规定履行信息披露义务。"},{"i":31,"n":"第三十一条","txt":"上市公司及其股东、实际控制人、董事、监事、高级管理人员、其他信息披露义务人、内幕信息知情人等相关主体违反本办法，证券公司、证券服务机构及其人员未勤勉尽责且情节严重的，中国证监会根据《证券法》等法律法规和中国证监会其他有关规定，依法追究其法律责任。"},{"i":32,"n":"第三十二条","txt":"中国证监会将遵守本办法的情况记入证券市场诚信档案，会同有关部门加强信息共享，依法依规实施守信激励与失信惩戒。"},{"i":33,"n":"第三十三条","txt":"本办法自2021年11月15日起施行。"}],"beijingzhengquanjiaoyisuoshangshigongsizhengquanfa93493d":[{"i":1,"n":"第一条","txt":"为了规范北京证券交易所上市公司（以下简称上市公司）证券发行行为，保护投资者合法权益和社会公共利益，根据《中华人民共和国证券法》（以下简称《证券法》）《国务院办公厅关于贯彻实施修订后的证券法有关工作的通知》及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"上市公司申请在境内发行股票、可转换为股票的公司债券及中国证券监督管理委员会（以下简称中国证监会）认可的其他证券品种，适用本办法。"},{"i":3,"n":"第三条","txt":"上市公司发行证券，可以向不特定合格投资者公开发行，也可以向特定对象发行。"},{"i":4,"n":"第四条","txt":"上市公司发行证券的，应当符合《证券法》和本办法规定的发行条件和相关信息披露要求，依法经北京证券交易所（以下简称北交所）发行上市审核，并报中国证监会注册，但因依法实行股权激励、公积金转为增加公司资本、分配股票股利的除外。"},{"i":5,"n":"第五条","txt":"上市公司应当诚实守信，依法充分披露投资者作出价值判断和投资决策所必需的信息，所披露信息必须真实、准确、完整，简明清晰、通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 上市公司应当按照保荐人、证券服务机构要求，依法向其提供真实、准确、完整的财务会计资料和其他资料，配合相关机构开展尽职调查和其他相关工作。 上市公司的控股股东、实际控制人、董事、监事、高级管理人员应当配合相关机构开展尽职调查和其他相关工作，不得要求或者协助上市公司隐瞒应当提供的资料或者应当披露的信息。"},{"i":6,"n":"第六条","txt":"保荐人应当诚实守信，勤勉尽责，按照依法制定的业务规则和行业自律规范的要求，充分了解上市公司经营情况和风险，对注册申请文件和信息披露资料进行全面核查验证，对上市公司是否符合发行条件独立作出专业判断，审慎作出保荐决定，并对募集说明书、发行情况报告书或者其他信息披露文件及其所出具的相关文件的真实性、准确性、完整性负责。"},{"i":7,"n":"第七条","txt":"证券服务机构应当严格遵守法律法规、中国证监会制定的监管规则、业务规则和本行业公认的业务标准和道德规范，建立并保持有效的质量控制体系，保护投资者合法权益，审慎履行职责，作出专业判断与认定，并对募集说明书、发行情况报告书或者其他信息披露文件中与其专业职责有关的内容及其所出具文件的真实性、准确性、完整性负责。 证券服务机构及其相关执业人员应当对与本专业相关的业务事项履行特别注意义务，对其他业务事项履行普通注意义务，并承担相应法律责任。 证券服务机构及其执业人员从事证券服务应当配合中国证监会的监督管理，在规定的期限内提供、报送或披露相关资料、信息，并保证其提供、报送或披露的资料、信息真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 证券服务机构应当妥善保存客户委托文件、核查和验证资料、工作底稿以及与质量控制、内部管理、业务经营有关的信息和资料。"},{"i":8,"n":"第八条","txt":"对上市公司发行证券申请予以注册，不表明中国证监会和北交所对该证券的投资价值或者投资者的收益作出实质性判断或者保证，也不表明中国证监会和北交所对申请文件的真实性、准确性、完整性作出保证。"},{"i":9,"n":"第九条","txt":"上市公司向特定对象发行股票，应当符合下列规定： （一）具备健全且运行良好的组织机构。 （二）具有独立、稳定经营能力，不存在对持续经营有重大不利影响的情形。 （三）最近一年财务会计报告无虚假记载，未被出具否定意见或无法表示意见的审计报告；最近一年财务会计报告被出具保留意见的审计报告，保留意见所涉及事项对上市公司的重大不利影响已经消除。本次发行涉及重大资产重组的除外。 （四）合法规范经营，依法履行信息披露义务。"},{"i":10,"n":"第十条","txt":"上市公司存在下列情形之一的，不得向特定对象发行股票： （一）上市公司或其控股股东、实际控制人最近三年内存在贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的刑事犯罪，存在欺诈发行、重大信息披露违法或者其他涉及国家安全、公共安全、生态安全、生产安全、公众健康安全等领域的重大违法行为。 （二）上市公司或其控股股东、实际控制人，现任董事、监事、高级管理人员最近一年内受到中国证监会行政处罚、北交所公开谴责；或因涉嫌犯罪正被司法机关立案侦查或者涉嫌违法违规正被中国证监会立案调查，尚未有明确结论意见。 （三）擅自改变募集资金用途，未作纠正或者未经股东大会认可。 （四）上市公司或其控股股东、实际控制人被列入失信被执行人名单且情形尚未消除。 （五）上市公司利益严重受损的其他情形。"},{"i":11,"n":"第十一条","txt":"上市公司向不特定合格投资者公开发行股票的，除应当符合本办法第九条、第十条规定的条件外，还应当符合《北京证券交易所向不特定合格投资者公开发行股票注册管理办法（试行）》规定的其他条件。"},{"i":12,"n":"第十二条","txt":"上市公司发行可转换为股票的公司债券，应当符合下列规定： （一）具备健全且运行良好的组织机构； （二）最近三年平均可分配利润足以支付公司债券一年的利息； （三）具有合理的资产负债结构和正常的现金流量。 除前款规定条件外，上市公司向特定对象发行可转换为股票的公司债券，还应当遵守本办法第九条、第十条的规定；向不特定合格投资者公开发行可转换为股票的公司债券，还应当遵守本办法第十一条的规定。但上市公司通过收购本公司股份的方式进行公司债券转换的除外。"},{"i":13,"n":"第十三条","txt":"上市公司存在下列情形之一的，不得发行可转换为股票的公司债券： （一）对已公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，仍处于继续状态； （二）违反《证券法》规定，改变公开发行公司债券所募资金用途。"},{"i":14,"n":"第十四条","txt":"上市公司及其控股股东、实际控制人、主要股东不得向发行对象做出保底保收益或者变相保底保收益承诺，也不得直接或者通过利益相关方向发行对象提供财务资助或者其他补偿。"},{"i":15,"n":"第十五条","txt":"上市公司最近一期末存在持有金额较大的财务性投资的，保荐人应当对上市公司本次募集资金的必要性和合理性审慎发表核查意见。"},{"i":16,"n":"第十六条","txt":"董事会应当依法就本次发行证券的具体方案、本次募集资金使用的可行性及其他必须明确的事项作出决议，并提请股东大会批准。 独立董事应当就证券发行事项的必要性、合理性、可行性、公平性发表专项意见。"},{"i":17,"n":"第十七条","txt":"监事会应当对董事会编制的募集说明书等文件进行审核并提出书面审核意见。"},{"i":18,"n":"第十八条","txt":"股东大会就本次发行证券作出决议，决议至少应当包括下列事项： （一）本次发行证券的种类和数量（数量上限）； （二）发行方式、发行对象或范围、现有股东的优先认购安排（如有）； （三）定价方式或发行价格（区间）； （四）限售情况（如有）； （五）募集资金用途； （六）决议的有效期； （七）对董事会办理本次发行具体事宜的授权； （八）发行前滚存利润的分配方案； （九）其他必须明确的事项。"},{"i":19,"n":"第十九条","txt":"股东大会就发行可转换为股票的公司债券作出决议，除应当符合本办法第十八条的规定外，还应当就债券利率、债券期限、赎回条款、回售条款、还本付息的期限和方式、转股期、转股价格的确定和修正等事项作出决议。"},{"i":20,"n":"第二十条","txt":"股东大会就发行证券事项作出决议，必须经出席会议的股东所持表决权的 2/3 以上通过。上市公司应当对出席会议的持股比例在5%以下的中小股东表决情况单独计票并予以披露。 上市公司就发行证券事项召开股东大会，应当提供网络投票的方式，上市公司还可以通过其他方式为股东参加股东大会提供便利。"},{"i":21,"n":"第二十一条","txt":"董事会、股东大会就向特定对象发行证券事项作出决议，应当按要求履行表决权回避制度，上市公司向原股东配售股份的除外。"},{"i":22,"n":"第二十二条","txt":"上市公司拟引入战略投资者的，董事会、股东大会应当将引入战略投资者的事项作为单独议案，就每名战略投资者单独审议。"},{"i":23,"n":"第二十三条","txt":"根据公司章程的规定，上市公司年度股东大会可以授权董事会向特定对象发行累计融资额低于一亿元且低于公司最近一年末净资产20%的股票（以下简称授权发行），该项授权的有效期不得超过上市公司下一年度股东大会召开日。"},{"i":24,"n":"第二十四条","txt":"上市公司申请发行证券，应当按照中国证监会有关规定制作注册申请文件，依法由保荐人保荐并向北交所申报。北交所收到注册申请文件后，应当在五个工作日内作出是否受理的决定，本办法另有规定的除外。"},{"i":25,"n":"第二十五条","txt":"自注册申请文件申报之日起，上市公司及其控股股东、实际控制人、董事、监事、高级管理人员，以及与本次证券发行相关的保荐人、证券服务机构及相关责任人员，即承担相应法律责任。"},{"i":26,"n":"第二十六条","txt":"注册申请文件受理后，未经中国证监会或者北交所同意，不得改动。 发生重大事项的，上市公司、保荐人、证券服务机构应当及时向北交所报告，并按要求更新注册申请文件和信息披露资料。"},{"i":27,"n":"第二十七条","txt":"上市公司发行证券，不属于本办法第二十八条规定情形的，保荐人应当指定保荐代表人负责具体保荐工作。 保荐人持续督导期间为证券上市当年剩余时间及其后两个完整会计年度。 保荐人及保荐代表人应当按照本办法及《证券发行上市保荐业务管理办法》的规定履行职责，并依法承担相应的责任。"},{"i":28,"n":"第二十八条","txt":"上市公司向前十名股东、实际控制人、董事、监事、高级管理人员及核心员工发行股票，连续12个月内发行的股份未超过公司总股本10%且融资总额不超过2000万元的，无需提供保荐人出具的保荐文件以及律师事务所出具的法律意见书。 按照前款规定发行股票的，董事会决议中应当明确发行对象、发行价格和发行数量，且不得存在以下情形： （一）上市公司采用授权发行方式发行； （二）认购人以非现金资产认购； （三）发行股票导致上市公司控制权发生变动； （四）本次发行中存在特殊投资条款安排； （五）上市公司或其控股股东、实际控制人，现任董事、监事、高级管理人员最近一年内被中国证监会给予行政处罚或采取监管措施、被北交所采取纪律处分。"},{"i":29,"n":"第二十九条","txt":"北交所审核部门负责审核上市公司证券发行申请；北交所上市委员会负责对上市公司向不特定合格投资者公开发行证券的申请文件和审核部门出具的审核报告提出审议意见。 北交所应当根据本办法制定上市公司证券发行审核业务规则，并报中国证监会批准。"},{"i":30,"n":"第三十条","txt":"北交所主要通过向上市公司提出审核问询、上市公司回答问题方式开展审核工作，判断上市公司是否符合发行条件和信息披露要求。"},{"i":31,"n":"第三十一条","txt":"北交所按照规定的条件和程序，形成上市公司是否符合发行条件和信息披露要求的审核意见。认为上市公司符合发行条件和信息披露要求的，将审核意见、上市公司注册申请文件及相关审核资料报送中国证监会注册；认为上市公司不符合发行条件或者信息披露要求的，作出终止发行上市审核决定。"},{"i":32,"n":"第三十二条","txt":"北交所应当自受理注册申请文件之日起两个月内形成审核意见。 上市公司采用授权发行方式向特定对象发行股票且按照竞价方式确定发行价格和发行对象的，北交所应当在两个工作日内作出是否受理的决定，并自受理注册申请文件之日起三个工作日内形成审核意见。 通过对上市公司实施现场检查、对保荐人实施现场督导、要求保荐人和证券服务机构对有关事项进行专项核查等方式要求上市公司补充、修改申请文件的时间不计算在内。"},{"i":33,"n":"第三十三条","txt":"中国证监会收到北交所报送的审核意见、上市公司注册申请文件及相关审核资料后，履行发行注册程序。发行注册主要关注北交所发行上市审核内容有无遗漏，审核程序是否符合规定，以及上市公司在发行条件和信息披露要求的重大方面是否符合相关规定。中国证监会认为存在需要进一步说明或者落实事项的，可以要求北交所进一步问询。 中国证监会认为北交所对影响发行条件的重大事项未予关注或者北交所的审核意见依据明显不充分的，可以退回北交所补充审核。北交所补充审核后，认为上市公司符合发行条件和信息披露要求的，重新向中国证监会报送审核意见及相关资料，本办法第三十四条规定的注册期限重新计算。"},{"i":34,"n":"第三十四条","txt":"中国证监会在十五个工作日内对上市公司的注册申请作出同意注册或不予注册的决定。通过要求北交所进一步问询、要求保荐人和证券服务机构等对有关事项进行核查、对发行人现场检查等方式要求发行人补充、修改申请文件的时间不计算在内。"},{"i":35,"n":"第三十五条","txt":"中国证监会的予以注册决定，自作出之日起一年内有效，上市公司应当在注册决定有效期内发行证券，发行时点由上市公司自主选择。"},{"i":36,"n":"第三十六条","txt":"中国证监会作出予以注册决定后、上市公司证券上市交易前，上市公司应当及时更新信息披露文件；保荐人以及证券服务机构应当持续履行尽职调查职责；发生重大事项的，上市公司、保荐人应当及时向北交所报告。北交所应当对上述事项及时处理，发现上市公司存在重大事项影响发行条件的，应当出具明确意见并及时向中国证监会报告。 中国证监会作出予以注册决定后、上市公司证券上市交易前，发生可能影响本次发行的重大事项的，中国证监会可以要求上市公司暂缓发行、上市；相关重大事项导致上市公司不符合发行条件的，应当撤销注册。中国证监会撤销注册后，证券尚未发行的，上市公司应当停止发行；证券已经发行尚未上市的，上市公司应当按照发行价并加算银行同期存款利息返还证券持有人。"},{"i":37,"n":"第三十七条","txt":"上市公司申请向特定对象发行股票，可申请一次注册，分期发行。自中国证监会予以注册之日起，公司应当在三个月内首期发行，剩余数量应当在十二个月内发行完毕。首期发行数量应当不少于总发行数量的50%，剩余各期发行的数量由公司自行确定，每期发行后5个工作日内将发行情况报北交所备案。"},{"i":38,"n":"第三十八条","txt":"北交所认为上市公司不符合发行条件或者信息披露要求，作出终止发行上市审核决定，或者中国证监会作出不予注册决定的，自决定作出之日起六个月后，上市公司可以再次提出证券发行申请。"},{"i":39,"n":"第三十九条","txt":"上市公司证券发行上市审核或者注册程序的中止、终止等情形参照适用《北京证券交易所向不特定合格投资者公开发行股票注册管理办法（试行）》的相关规定。"},{"i":40,"n":"第四十条","txt":"中国证监会和北交所可以对上市公司进行现场检查，可以要求保荐人、证券服务机构对有关事项进行专项核查并出具意见。"},{"i":41,"n":"第四十一条","txt":"上市公司发行证券，应当聘请具有证券承销业务资格的证券公司承销，但上市公司向特定对象发行证券且董事会提前确定全部发行对象的除外。 上市公司向不特定合格投资者公开发行股票的，发行承销的具体要求参照适用《北京证券交易所向不特定合格投资者公开发行股票注册管理办法（试行）》的相关规定，本办法另有规定的除外。 上市公司向特定对象发行证券的发行承销行为，适用本章规定。"},{"i":42,"n":"第四十二条","txt":"上市公司向原股东配售股份的，应当采用代销方式发行。 控股股东应当在股东大会召开前公开承诺认配股份的数量。控股股东不履行认配股份的承诺，或者代销期限届满，原股东认购股票的数量未达到拟配售数量70%的，上市公司应当按照发行价并加算银行同期存款利息返还已经认购的股东。"},{"i":43,"n":"第四十三条","txt":"上市公司向不特定合格投资者公开发行股票的，发行价格应当不低于公告招股意向书前二十个交易日或者前一个交易日公司股票均价。"},{"i":44,"n":"第四十四条","txt":"上市公司向特定对象发行股票的，发行价格应当不低于定价基准日前二十个交易日公司股票均价的80%。 向特定对象发行股票的定价基准日为发行期首日。 上市公司董事会决议提前确定全部发行对象，且发行对象属于下列情形之一的，定价基准日可以为关于本次发行股票的董事会决议公告日、股东大会决议公告日或者发行期首日： （一）上市公司的控股股东、实际控制人或者其控制的关联方； （二）按照本办法第二十八条规定参与认购的上市公司前十名股东、董事、监事、高级管理人员及核心员工； （三）通过认购本次发行的股票成为上市公司控股股东或实际控制人的投资者； （四）董事会拟引入的境内外战略投资者。"},{"i":45,"n":"第四十五条","txt":"上市公司向特定对象发行股票的，发行对象属于本办法第四十四条第三款规定以外情形的，上市公司应当以竞价方式确定发行价格和发行对象。 上市公司向特定对象发行可转换为股票的公司债券的，上市公司应当采用竞价方式确定利率和发行对象，本次发行涉及发行可转换为股票的公司债券购买资产的除外。 董事会决议确定部分发行对象的，确定的发行对象不得参与竞价，且应当接受竞价结果，并明确在通过竞价方式未能产生发行价格的情况下，是否继续参与认购、价格确定原则及认购数量。 上市公司发行证券采用竞价方式的，上市公司和承销商的控股股东、实际控制人、董事、监事、高级管理人员及其控制或者施加重大影响的关联方不得参与竞价。"},{"i":46,"n":"第四十六条","txt":"上市公司以竞价方式向特定对象发行股票的，在发行期首日前一工作日，上市公司及承销商可以向符合条件的特定对象提供认购邀请书。认购邀请书发送对象至少应当包括： （一）已经提交认购意向书的投资者； （二）上市公司前二十名股东； （三）合计不少于十家证券投资基金管理公司、证券公司或保险机构。 认购邀请书发送后，上市公司及承销商应当在认购邀请书约定的时间内收集特定投资者签署的申购报价表。 在申购报价期间，上市公司及承销商应当确保任何工作人员不泄露发行对象的申购报价情况。 申购报价结束后，上市公司及承销商应当对有效申购按照报价高低进行累计统计，按照价格优先等董事会确定的原则合理确定发行对象、发行价格和发行股数。"},{"i":47,"n":"第四十七条","txt":"上市公司向特定对象发行证券的，发行对象确定后，上市公司应当与发行对象签订认购合同，上市公司向原股东配售股份的除外。"},{"i":48,"n":"第四十八条","txt":"向特定对象发行的股票，自发行结束之日起六个月内不得转让，做市商为取得做市库存股参与发行认购的除外，但做市商应当承诺自发行结束之日起六个月内不得申请退出为上市公司做市。 发行对象属于本办法第四十四条第三款规定情形的，其认购的股票自发行结束之日起十二个月内不得转让。法律法规、部门规章对前述股票的限售期另有规定的，同时还应当遵守相关规定。"},{"i":49,"n":"第四十九条","txt":"上市公司向原股东配售股份的，应当向股权登记日在册的股东配售，且配售比例应当相同。 向原股东配售股份的价格由上市公司和承销商协商确定，豁免适用本节关于向特定对象发行股票定价与限售的相关规定。"},{"i":50,"n":"第五十条","txt":"上市公司在证券发行过程中触及北交所规定的终止上市情形的，应当终止发行。"},{"i":51,"n":"第五十一条","txt":"上市公司应当按照中国证监会制定的信息披露规则，编制并披露募集说明书、发行情况报告书等信息披露文件。 上市公司应当以投资者需求为导向，根据自身特点，有针对性地披露上市公司基本信息、本次发行情况以及本次发行对上市公司的影响。 中国证监会制定的信息披露规则是信息披露的最低要求。不论上述规则是否有明确规定，凡是投资者作出价值判断和投资决策所必需的信息，上市公司均应当充分披露。"},{"i":52,"n":"第五十二条","txt":"中国证监会依法制定募集说明书、发行情况报告书内容与格式准则等信息披露规则，对相关信息披露文件的内容、格式等作出规定。 北交所可以依据中国证监会部门规章和规范性文件，制定信息披露细则或指引，在中国证监会确定的信息披露内容范围内，对信息披露提出细化和补充要求。"},{"i":53,"n":"第五十三条","txt":"上市公司应当结合现有主营业务、生产经营规模、财务状况、技术条件、发展目标、前次发行募集资金使用情况等因素合理确定募集资金规模，充分披露本次募集资金的必要性和合理性。"},{"i":54,"n":"第五十四条","txt":"上市公司应当按照中国证监会和北交所有关规定及时披露董事会决议、股东大会通知、股东大会决议、受理通知、审核决定、注册决定等发行进展公告。"},{"i":55,"n":"第五十五条","txt":"北交所认为上市公司符合发行条件和信息披露要求，将上市公司注册申请文件报送中国证监会时，募集说明书等文件应当同步在北交所网站和中国证监会网站公开。"},{"i":56,"n":"第五十六条","txt":"上市公司应当在发行证券前在符合《证券法》规定的信息披露平台刊登经注册生效的募集说明书，同时将其置备于公司住所、北交所，供社会公众查阅。"},{"i":57,"n":"第五十七条","txt":"向特定对象发行证券的，上市公司应当在发行结束后，按照中国证监会和北交所的有关要求编制并披露发行情况报告书。 申请分期发行的上市公司应在每期发行后，按照中国证监会和北交所的有关要求进行披露，并在全部发行结束或者超过注册文件有效期后按照中国证监会的有关要求编制并披露发行情况报告书。"},{"i":58,"n":"第五十八条","txt":"上市公司可以将募集说明书以及有关附件刊登于其他报刊、网站，但披露内容应当完全一致，且不得早于在符合《证券法》规定的信息披露平台的披露时间。"},{"i":59,"n":"第五十九条","txt":"中国证监会建立对北交所发行上市审核工作和发行承销过程监管的监督机制，可以对北交所相关工作进行检查或抽查。对于中国证监会监督过程中发现的问题，北交所应当整改。"},{"i":60,"n":"第六十条","txt":"北交所应当发挥自律管理作用，对证券发行相关行为进行监督。发现上市公司及其控股股东、实际控制人、董事、监事、高级管理人员以及保荐人、承销商、证券服务机构及其相关执业人员等违反法律、行政法规和中国证监会相关规定的，应当向中国证监会报告，并采取自律管理措施。 北交所对证券发行承销过程实施自律管理。发现异常情形或者涉嫌违法违规的，中国证监会可以要求北交所对相关事项进行调查处理，或者直接责令上市公司、承销商暂停或中止发行。"},{"i":61,"n":"第六十一条","txt":"中国证券业协会应当发挥自律管理作用，对从事证券发行业务的保荐人进行监督，督促其勤勉尽责地履行尽职调查和督导职责。发现保荐人有违反法律、行政法规和中国证监会相关规定的行为，应当向中国证监会报告，并采取自律管理措施。 中国证券业协会应当建立对承销商询价、定价、配售行为和询价投资者报价行为的自律管理制度，并加强相关行为的监督检查，发现违规情形的，应当及时采取自律管理措施。"},{"i":62,"n":"第六十二条","txt":"北交所发行上市审核工作存在下列情形之一的，由中国证监会责令改正；情节严重的，追究直接责任人员相关责任： （一）未按审核标准开展发行上市审核工作； （二）未按审核程序开展发行上市审核工作； （三）不配合中国证监会对发行上市审核工作和发行承销监管工作的检查、抽查，或者不按中国证监会的整改要求进行整改。"},{"i":63,"n":"第六十三条","txt":"上市公司在证券发行文件中隐瞒重要事实或者编造重大虚假内容的，中国证监会可以视情节轻重，对上市公司及相关责任人员依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。"},{"i":64,"n":"第六十四条","txt":"上市公司的控股股东、实际控制人违反本办法规定，致使上市公司报送的注册申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏，或者组织、指使上市公司进行财务造假、利润操纵或者在发行证券文件中隐瞒重要事实或编造重大虚假内容的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。 上市公司的董事、监事和高级管理人员违反本办法规定，致使上市公司报送的注册申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。"},{"i":65,"n":"第六十五条","txt":"保荐人未勤勉尽责，致使上市公司信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以视情节轻重，对保荐人及相关责任人员依法采取责令改正、监管谈话、出具警示函、暂停保荐业务资格一年到三年、证券市场禁入等措施。 证券服务机构未勤勉尽责，致使上市公司信息披露资料中与其职责有关的内容及其所出具的文件存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以视情节轻重，对证券服务机构及相关责任人员，依法采取责令改正、监管谈话、出具警示函、证券市场禁入等措施。"},{"i":66,"n":"第六十六条","txt":"保荐人存在下列情形之一的，中国证监会可以视情节轻重，采取暂停保荐业务资格三个月至三年的监管措施；情节特别严重的，撤销其业务资格： （一）伪造或者变造签字、盖章； （二）重大事项未报告、未披露； （三）以不正当手段干扰审核注册工作； （四）不履行其他法定职责。"},{"i":67,"n":"第六十七条","txt":"上市公司、保荐人、证券服务机构存在以下情形之一的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施： （一）制作或者出具的文件不齐备或者不符合要求； （二）擅自改动注册申请文件、信息披露资料或者其他已提交文件； （三）注册申请文件或者信息披露资料存在相互矛盾或者同一事实表述不一致且有实质性差异； （四）文件披露的内容表述不清，逻辑混乱，严重影响投资者理解； （五）未及时报告或者未及时披露重大事项。"},{"i":68,"n":"第六十八条","txt":"承销商及其直接负责的主管人员和其他责任人员在承销证券过程中，存在违法违规行为的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。"},{"i":69,"n":"第六十九条","txt":"北交所按照本办法第三十二条第二款开展审核工作的，北交所和中国证监会发现上市公司或者相关中介机构及其责任人员存在相关违法违规行为的，中国证监会按照本章规定从重处罚。"},{"i":70,"n":"第七十条","txt":"参与认购的投资者擅自转让限售期限未满的证券的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施。"},{"i":71,"n":"第七十一条","txt":"相关主体违反本办法第十四条规定的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。"},{"i":72,"n":"第七十二条","txt":"上市公司及其控股股东和实际控制人、董事、监事、高级管理人员，保荐人、承销商、证券服务机构及其相关执业人员，在证券发行活动中存在其他违反本办法规定行为的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告等监管措施，或者采取证券市场禁入的措施。 上市公司及其控股股东、实际控制人、董事、监事、高级管理人员以及保荐人、承销商、证券服务机构及其相关执业人员等违反《证券法》依法应予以行政处罚的，中国证监会将依法予以处罚。涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":73,"n":"第七十三条","txt":"中国证监会将遵守本办法的情况记入证券市场诚信档案，会同有关部门加强信息共享，依法实施守信激励与失信惩戒。"},{"i":74,"n":"第七十四条","txt":"本办法所称战略投资者，是指符合下列情形之一，且与上市公司具有协同效应，愿意长期持有上市公司较大比例股份，愿意且有能力协助上市公司提高公司治理质量，具有良好诚信记录，最近三年未受到中国证监会行政处罚或被追究刑事责任的投资者： （一）能够为上市公司带来领先的技术资源，增强上市公司的核心竞争力和创新能力，带动上市公司产业技术升级，提升上市公司盈利能力； （二）能够为上市公司带来市场渠道、品牌等战略性资源，促进上市公司市场拓展，推动实现上市公司销售业绩提升； （三）具备相关产业投资背景，且自愿设定二十四个月及以上限售期的其他长期投资者。 境外战略投资者应当同时遵守国家的相关规定。"},{"i":75,"n":"第七十五条","txt":"本办法所称的核心员工，应当由上市公司董事会提名，并向全体员工公示和征求意见，由监事会发表明确意见后，经股东大会审议批准。"},{"i":76,"n":"第七十六条","txt":"上市公司向不特定合格投资者公开发行可转换为股票的公司债券的，还应当遵守中国证监会的相关规定。 上市公司发行优先股的，其申请、审核、注册、发行等相关程序，参照本办法相关规定执行。"},{"i":77,"n":"第七十七条","txt":"本办法自2021年11月15日起施行。"}],"beijingzhengquanjiaoyisuoxiangbutedinghegetouzizheae8f44":[{"i":1,"n":"第一条","txt":"为了规范北京证券交易所（以下简称北交所）试点注册制向不特定合格投资者公开发行股票相关活动，保护投资者合法权益和社会公共利益，根据《中华人民共和国证券法》（以下简称《证券法》）《国务院办公厅关于贯彻实施修订后的证券法有关工作的通知》及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"股票向不特定合格投资者公开发行（以下简称公开发行）并在北交所上市的发行注册，适用本办法。 前款所称的合格投资者应当符合中国证券监督管理委员会（以下简称中国证监会）和北交所的投资者适当性管理规定。"},{"i":3,"n":"第三条","txt":"北交所充分发挥对全国中小企业股份转让系统（以下简称全国股转系统）的示范引领作用，深入贯彻创新驱动发展战略，聚焦实体经济，主要服务创新型中小企业，重点支持先进制造业和现代服务业等领域的企业，推动传统产业转型升级，培育经济发展新动能，促进经济高质量发展。"},{"i":4,"n":"第四条","txt":"公开发行股票并在北交所上市，应当符合发行条件、上市条件以及相关信息披露要求，依法经北交所发行上市审核，并报中国证监会注册。"},{"i":5,"n":"第五条","txt":"发行人应当诚实守信，依法充分披露投资者作出价值判断和投资决策所必需的信息，所披露信息必须真实、准确、完整，简明清晰、通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 发行人应当按保荐人、证券服务机构要求，依法向其提供真实、准确、完整的财务会计资料和其他资料，配合相关机构开展尽职调查和其他相关工作。 发行人的控股股东、实际控制人、董事、监事、高级管理人员应当配合相关机构开展尽职调查和其他相关工作，不得要求或者协助发行人隐瞒应当提供的资料或者应当披露的信息。"},{"i":6,"n":"第六条","txt":"保荐人应当诚实守信，勤勉尽责，按照依法制定的业务规则和行业自律规范的要求，充分了解发行人经营情况和风险，对注册申请文件和信息披露资料进行全面核查验证，对发行人是否符合发行条件、上市条件独立作出专业判断，审慎作出保荐决定，并对招股说明书及其所出具的相关文件的真实性、准确性、完整性负责。"},{"i":7,"n":"第七条","txt":"证券服务机构应当严格遵守法律法规、中国证监会制定的监管规则、业务规则和本行业公认的业务标准和道德规范，建立并保持有效的质量控制体系，保护投资者合法权益，审慎履行职责，作出专业判断与认定，并对招股说明书或者其他信息披露文件中与其专业职责有关的内容及其所出具的文件的真实性、准确性、完整性负责。 证券服务机构及其相关执业人员应当对与本专业相关的业务事项履行特别注意义务，对其他业务事项履行普通注意义务，并承担相应法律责任。 证券服务机构及其执业人员从事证券服务应当配合中国证监会的监督管理，在规定的期限内提供、报送或披露相关资料、信息，并保证其提供、报送或披露的资料、信息真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 证券服务机构应当妥善保存客户委托文件、核查和验证资料、工作底稿以及与质量控制、内部管理、业务经营有关的信息和资料。"},{"i":8,"n":"第八条","txt":"对发行人公开发行股票申请予以注册，不表明中国证监会和北交所对该股票的投资价值或者投资者的收益作出实质性判断或者保证，也不表明中国证监会和北交所对注册申请文件的真实性、准确性、完整性作出保证。"},{"i":9,"n":"第九条","txt":"发行人应当为在全国股转系统连续挂牌满十二个月的创新层挂牌公司。"},{"i":10,"n":"第十条","txt":"发行人申请公开发行股票，应当符合下列规定： （一）具备健全且运行良好的组织机构； （二）具有持续经营能力，财务状况良好； （三）最近三年财务会计报告无虚假记载，被出具无保留意见审计报告； （四）依法规范经营。"},{"i":11,"n":"第十一条","txt":"发行人及其控股股东、实际控制人存在下列情形之一的，发行人不得公开发行股票： （一）最近三年内存在贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的刑事犯罪； （二）最近三年内存在欺诈发行、重大信息披露违法或者其他涉及国家安全、公共安全、生态安全、生产安全、公众健康安全等领域的重大违法行为； （三）最近一年内受到中国证监会行政处罚。"},{"i":12,"n":"第十二条","txt":"发行人董事会应当依法就本次股票发行的具体方案、本次募集资金使用的可行性及其他必须明确的事项作出决议，并提请股东大会批准。 发行人监事会应当对董事会编制的招股说明书等文件进行审核并提出书面审核意见。"},{"i":13,"n":"第十三条","txt":"发行人股东大会就本次股票发行作出决议，至少应当包括下列事项： （一）本次公开发行股票的种类和数量； （二）发行对象的范围； （三）定价方式、发行价格（区间）或发行底价； （四）募集资金用途； （五）决议的有效期； （六）对董事会办理本次发行具体事宜的授权； （七）发行前滚存利润的分配方案； （八）其他必须明确的事项。"},{"i":14,"n":"第十四条","txt":"发行人股东大会就本次股票发行事项作出决议，必须经出席会议的股东所持表决权的 2/3 以上通过。发行人应当对出席会议的持股比例在5%以下的中小股东表决情况单独计票并予以披露。 发行人就本次股票发行事项召开股东大会，应当提供网络投票的方式，发行人还可以通过其他方式为股东参加股东大会提供便利。"},{"i":15,"n":"第十五条","txt":"发行人申请公开发行股票，应当按照中国证监会有关规定制作注册申请文件，依法由保荐人保荐并向北交所申报。北交所收到注册申请文件后，应当在五个工作日内作出是否受理的决定。 保荐人应当指定保荐代表人负责具体保荐工作。"},{"i":16,"n":"第十六条","txt":"自注册申请文件申报之日起，发行人及其控股股东、实际控制人、董事、监事、高级管理人员，以及与本次股票公开发行相关的保荐人、证券服务机构及相关责任人员，即承担相应法律责任。"},{"i":17,"n":"第十七条","txt":"注册申请文件受理后，未经中国证监会或者北交所同意，不得改动。 发生重大事项的，发行人、保荐人、证券服务机构应当及时向北交所报告，并按要求更新注册申请文件和信息披露资料。"},{"i":18,"n":"第十八条","txt":"北交所设立独立的审核部门，负责审核发行人公开发行并上市申请；设立上市委员会，负责对审核部门出具的审核报告和发行人的申请文件提出审议意见。北交所可以设立行业咨询委员会，负责为发行上市审核提供专业咨询和政策建议。 北交所应当根据本办法制定发行上市审核业务规则，并报中国证监会批准。"},{"i":19,"n":"第十九条","txt":"北交所主要通过向发行人提出审核问询、发行人回答问题方式开展审核工作，判断发行人是否符合发行条件、上市条件和信息披露要求。"},{"i":20,"n":"第二十条","txt":"北交所按照规定的条件和程序，形成发行人是否符合发行条件和信息披露要求的审核意见。认为发行人符合发行条件和信息披露要求的，将审核意见、发行人注册申请文件及相关审核资料报送中国证监会注册；认为发行人不符合发行条件或者信息披露要求的，作出终止发行上市审核决定。"},{"i":21,"n":"第二十一条","txt":"北交所应当自受理注册申请文件之日起两个月内形成审核意见，通过对发行人实施现场检查、对保荐人实施现场督导、要求保荐人和证券服务机构对有关事项进行专项核查等方式要求发行人补充、修改申请文件的时间不计算在内。"},{"i":22,"n":"第二十二条","txt":"中国证监会收到北交所报送的审核意见、发行人注册申请文件及相关审核资料后，履行发行注册程序。发行注册主要关注北交所发行上市审核内容有无遗漏，审核程序是否符合规定，以及发行人在发行条件和信息披露要求的重大方面是否符合相关规定。中国证监会认为存在需要进一步说明或者落实事项的，可以要求北交所进一步问询。 中国证监会认为北交所对影响发行条件的重大事项未予关注或者北交所的审核意见依据明显不充分的，可以退回北交所补充审核。北交所补充审核后，认为发行人符合发行条件和信息披露要求的，重新向中国证监会报送审核意见及相关资料，本办法第二十三条规定的注册期限重新计算。"},{"i":23,"n":"第二十三条","txt":"中国证监会在二十个工作日内对发行人的注册申请作出同意注册或不予注册的决定，通过要求北交所进一步问询、要求保荐人和证券服务机构等对有关事项进行核查、对发行人现场检查等方式要求发行人补充、修改申请文件的时间不计算在内。"},{"i":24,"n":"第二十四条","txt":"中国证监会的予以注册决定，自作出之日起一年内有效，发行人应当在注册决定有效期内发行股票，发行时点由发行人自主选择。"},{"i":25,"n":"第二十五条","txt":"中国证监会作出予以注册决定后、发行人股票上市交易前，发行人应当及时更新信息披露文件内容，财务报表已过有效期的，发行人应当补充财务会计报告等文件；保荐人以及证券服务机构应当持续履行尽职调查责任；发生重大事项的，发行人、保荐人应当及时向北交所报告。北交所应当对上述事项及时处理，发现发行人存在重大事项影响发行条件、上市条件的，应当出具明确意见并及时向中国证监会报告。 中国证监会作出予以注册决定后、发行人股票上市交易前，发生可能影响本次发行的重大事项的，中国证监会可以要求发行人暂缓发行、上市；相关重大事项导致发行人不符合发行条件的，应当撤销注册。中国证监会撤销注册后，股票尚未发行的，发行人应当停止发行；股票已经发行尚未上市的，发行人应当按照发行价并加算银行同期存款利息返还股票持有人。"},{"i":26,"n":"第二十六条","txt":"北交所认为发行人不符合发行条件或者信息披露要求，作出终止发行上市审核决定，或者中国证监会作出不予注册决定的，自决定作出之日起六个月后，发行人可以再次提出公开发行股票并上市申请。"},{"i":27,"n":"第二十七条","txt":"北交所应当提高审核工作透明度，接受社会监督，公开下列事项： （一）发行上市审核标准和程序等发行上市审核业务规则和相关业务细则； （二）在审企业名单、企业基本情况及审核工作进度； （三）发行上市审核问询及回复情况，但涉及国家秘密或者发行人商业秘密的除外； （四）上市委员会会议的时间、参会委员名单、审议的发行人名单、审议结果及现场问询问题； （五）对股票公开发行并上市相关主体采取的自律监管措施或者纪律处分； （六）北交所规定的其他事项。 中国证监会应当按规定公开股票发行注册相关的监管信息。"},{"i":28,"n":"第二十八条","txt":"存在下列情形之一的，发行人、保荐人应当及时书面报告北交所或者中国证监会，北交所或者中国证监会应当中止相应发行上市审核程序或者发行注册程序： （一）发行人及其控股股东、实际控制人涉嫌贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的犯罪，或者涉嫌欺诈发行、重大信息披露违法或其他涉及国家安全、公共安全、生态安全、生产安全、公众健康安全等领域的重大违法行为，被立案调查或者被司法机关侦查，尚未结案； （二）发行人的保荐人或者签字保荐代表人以及律师事务所、会计师事务所等证券服务机构或者相关签字人员因公开发行股票并上市、上市公司证券发行、并购重组业务涉嫌违法违规，或者其他业务涉嫌违法违规且对市场有重大影响，正在被中国证监会立案调查，或者正在被司法机关侦查，尚未结案； （三）发行人的保荐人以及律师事务所、会计师事务所等证券服务机构被中国证监会依法采取限制业务活动、责令停业整顿、指定其他机构"},{"i":29,"n":"第二十九条","txt":"存在下列情形之一的，北交所或者中国证监会应当终止相应发行上市审核程序或者发行注册程序，并向发行人说明理由： （一）发行人撤回注册申请或者保荐人撤销保荐； （二）发行人未在要求的期限内对注册申请文件作出解释说明或者补充、修改； （三）注册申请文件存在虚假记载、误导性陈述或者重大遗漏； （四）发行人阻碍或者拒绝中国证监会、北交所依法对发行人实施检查、核查； （五）发行人及其关联方以不正当手段严重干扰发行上市审核或者发行注册工作； （六）发行人法人资格终止； （七）注册申请文件内容存在重大缺陷，严重影响投资者理解和发行上市审核或者发行注册工作； （八）发行人注册申请文件中记载的财务资料已过有效期且逾期三个月未更新； （九）发行人发行上市审核程序中止超过北交所规定的时限或者发行注册程序中止超过三个月仍未恢复； （十）北交所认为发行人不符合发行条件或者信息披露要求； （十一）中国证监会规定的其他"},{"i":30,"n":"第三十条","txt":"中国证监会和北交所可以对发行人进行现场检查，可以要求保荐人、证券服务机构对有关事项进行专项核查并出具意见。"},{"i":31,"n":"第三十一条","txt":"发行人应当按照中国证监会制定的信息披露规则，编制并披露招股说明书。 发行人应当以投资者需求为导向，结合所属行业的特点和发展趋势，充分披露自身的创新特征。 中国证监会制定的信息披露规则是信息披露的最低要求。不论上述规则是否有明确规定，凡是投资者作出价值判断和投资决策所必需的信息，发行人均应当充分披露。"},{"i":32,"n":"第三十二条","txt":"中国证监会依法制定招股说明书内容与格式准则等信息披露规则，对相关信息披露文件的内容、格式等作出规定。 北交所可以依据中国证监会部门规章和规范性文件，制定信息披露细则或指引，在中国证监会确定的信息披露内容范围内，对信息披露提出细化和补充要求。"},{"i":33,"n":"第三十三条","txt":"北交所受理注册申请文件后，发行人应当按规定将招股说明书、发行保荐书、上市保荐书、审计报告和法律意见书等文件在北交所网站预先披露。 北交所将发行人注册申请文件报送中国证监会时，前款规定的文件应当同步在北交所网站和中国证监会网站公开。 预先披露的招股说明书及其他注册申请文件不能含有价格信息，发行人不得据此发行股票。"},{"i":34,"n":"第三十四条","txt":"发行人在发行股票前应当在符合《证券法》规定的信息披露平台刊登经注册生效的招股说明书，同时将其置备于公司住所、北交所，供社会公众查阅。 发行人可以将招股说明书以及有关附件刊登于其他报刊、网站，但披露内容应当完全一致，且不得早于在符合《证券法》规定的信息披露平台的披露时间。"},{"i":35,"n":"第三十五条","txt":"公开发行股票并在北交所上市保荐业务，适用《证券发行上市保荐业务管理办法》（以下简称《保荐办法》），本办法另有规定的除外。 北交所应当根据《保荐办法》和本办法制定发行保荐业务规则，并报中国证监会批准。"},{"i":36,"n":"第三十六条","txt":"保荐人应当按照中国证监会和北交所的规定制作、报送和披露发行保荐书、上市保荐书、回复意见等相关文件，遵守中国证监会和北交所的规定，配合中国证监会和北交所工作，自提交保荐文件之日起，保荐人及其保荐代表人应承担相应的责任。"},{"i":37,"n":"第三十七条","txt":"保荐人持续督导期间为公开发行股票上市当年剩余时间及其后三个完整会计年度。"},{"i":38,"n":"第三十八条","txt":"公开发行股票并在北交所上市的发行与承销行为，适用本办法。 北交所应当根据本办法制定发行承销业务规则，并报中国证监会批准。"},{"i":39,"n":"第三十九条","txt":"发行人公开发行股票，应当聘请具有证券承销业务资格的证券公司承销，按照《证券法》有关规定签订承销协议，确定采取代销或包销方式。"},{"i":40,"n":"第四十条","txt":"证券公司承销公开发行股票，应当依据本办法以及依法制定的业务规则和行业自律规范的有关风险控制和内部控制等相关规定，制定严格的风险管理制度和内部控制制度，加强定价和配售过程管理，落实承销责任。为股票发行出具相关文件的证券服务机构和人员，应当按照行业公认的业务标准和道德规范，严格履行法定职责，对其所出具文件的真实性、准确性和完整性承担责任。"},{"i":41,"n":"第四十一条","txt":"发行人可以与主承销商自主协商直接定价，也可以通过合格投资者网上竞价，或者网下询价等方式确定股票发行价格和发行对象。发行人和主承销商应当在招股说明书和发行公告中披露本次发行股票采用的定价方式。 发行人应当对定价依据及定价方式、定价的合理性作出充分说明并披露，主承销商应当对本次发行价格的合理性、 相关定价依据和定价方法的合理性，是否损害现有股东利益等发表意见。"},{"i":42,"n":"第四十二条","txt":"发行人通过网下询价方式确定股票发行价格和发行对象的，询价对象应当是经中国证券业协会注册的网下投资者。 发行人和主承销商可以根据北交所和中国证券业协会相关自律规则的规定，设置网下投资者的具体条件，并在发行公告中预先披露。"},{"i":43,"n":"第四十三条","txt":"获中国证监会同意注册后，发行人与主承销商应当及时向北交所报送发行与承销方案。"},{"i":44,"n":"第四十四条","txt":"公开发行股票可以向战略投资者配售。发行人的高级管理人员、核心员工可以参与战略配售。 前款所称的核心员工，应当由公司董事会提名，并向全体员工公示和征求意见，由监事会发表明确意见后，经股东大会审议批准。 发行人应当与战略投资者事先签署配售协议。发行人和主承销商应当在发行公告中披露战略投资者的选择标准、向战略投资者配售的股票总量、占本次发行股票的比例以及持有期限等。"},{"i":45,"n":"第四十五条","txt":"发行人、承销机构及相关人员不得存在以下行为： （一）泄露询价或定价信息； （二）以任何方式操纵发行定价； （三）夸大宣传，或以虚假广告等不正当手段诱导、误导投资者； （四）向投资者提供除招股意向书等公开信息以外的公司信息； （五）以提供透支、回扣或者中国证监会认定的其他不正当手段诱使他人申购股票； （六）以代持、信托持股等方式谋取不正当利益或向其他相关利益主体输送利益； （七）直接或通过其利益相关方向参与申购的投资者提供财务资助或者补偿； （八）以自有资金或者变相通过自有资金参与网下配售； （九）与投资者互相串通，协商报价和配售； （十）收取投资者回扣或其他相关利益； （十一）中国证监会规定的其他情形。"},{"i":46,"n":"第四十六条","txt":"中国证监会建立对北交所发行上市审核工作和发行承销过程监管的监督机制，可以对北交所相关工作进行检查或抽查。对于中国证监会监督过程中发现的问题，北交所应当整改。"},{"i":47,"n":"第四十七条","txt":"北交所应当发挥自律管理作用，对公开发行并上市相关行为进行监督。发现发行人及其控股股东、实际控制人、董事、监事、高级管理人员以及保荐人、承销商、证券服务机构及其相关执业人员等违反法律、行政法规和中国证监会相关规定的，应当向中国证监会报告，并采取自律管理措施。 北交所对股票发行承销过程实施自律管理。发现异常情形或者涉嫌违法违规的，中国证监会可以要求北交所对相关事项进行调查处理，或者直接责令发行人、承销商暂停或中止发行。"},{"i":48,"n":"第四十八条","txt":"中国证券业协会应当发挥自律管理作用，对从事股票公开发行业务的保荐人进行监督，督促其勤勉尽责地履行尽职调查和督导职责。发现保荐人有违反法律、行政法规和中国证监会相关规定的行为，应当向中国证监会报告，并采取自律管理措施。 中国证券业协会应当建立对承销商询价、定价、配售行为和询价投资者报价行为的自律管理制度，并加强相关行为的监督检查，发现违规情形的，应当及时采取自律管理措施。"},{"i":49,"n":"第四十九条","txt":"北交所发行上市审核工作存在下列情形之一的，由中国证监会责令改正；情节严重的，追究直接责任人员相关责任： （一）未按审核标准开展发行上市审核工作； （二）未按审核程序开展发行上市审核工作； （三）不配合中国证监会对发行上市审核工作和发行承销监管工作的检查、抽查，或者不按中国证监会的整改要求进行整改。"},{"i":50,"n":"第五十条","txt":"发行人在发行股票文件中隐瞒重要事实或者编造重大虚假内容的，中国证监会可以视情节轻重，对发行人及相关责任人员依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。"},{"i":51,"n":"第五十一条","txt":"发行人的控股股东、实际控制人违反本办法规定，致使发行人所报送的注册申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏，或者组织、指使发行人进行财务造假、利润操纵或者在发行股票文件中隐瞒重要事实或编造重大虚假内容的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。 发行人的董事、监事和高级管理人员违反本办法规定，致使发行人所报送的注册申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。"},{"i":52,"n":"第五十二条","txt":"保荐人未勤勉尽责，致使发行人信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以视情节轻重，对保荐人及相关责任人员依法采取责令改正、监管谈话、出具警示函、暂停保荐业务资格一年到三年、撤销保荐业务资格、证券市场禁入等措施。 证券服务机构未勤勉尽责，致使发行人信息披露资料中与其职责有关的内容及其所出具的文件存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以视情节轻重，对证券服务机构及相关责任人员依法采取责令改正、监管谈话、出具警示函、证券市场禁入等措施。"},{"i":53,"n":"第五十三条","txt":"保荐人存在下列情形之一的，中国证监会可以视情节轻重，采取暂停保荐业务资格三个月至三年的监管措施；情节特别严重的，撤销其业务资格： （一）伪造或者变造签字、盖章； （二）重大事项未报告、未披露； （三）以不正当手段干扰审核注册工作； （四）不履行其他法定职责。"},{"i":54,"n":"第五十四条","txt":"发行人、保荐人、证券服务机构存在以下情形之一的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施： （一）制作或者出具的文件不齐备或者不符合要求； （二）擅自改动注册申请文件、信息披露资料或者其他已提交文件； （三）注册申请文件或者信息披露资料存在相互矛盾或者同一事实表述不一致且有实质性差异； （四）文件披露的内容表述不清，逻辑混乱，严重影响投资者理解； （五）未及时报告或者未及时披露重大事项。"},{"i":55,"n":"第五十五条","txt":"承销商及其直接负责的主管人员和其他责任人员在承销证券过程中，违反本办法第四十五条规定的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施，或者采取证券市场禁入的措施。"},{"i":56,"n":"第五十六条","txt":"发行人及其控股股东和实际控制人、董事、监事、高级管理人员，保荐人、承销商、证券服务机构及其相关执业人员，在股票公开发行并上市相关的活动中存在其他违反本办法规定行为的，中国证监会可以视情节轻重，依法采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告等监管措施，或者采取证券市场禁入的措施。 发行人及其控股股东、实际控制人、董事、监事、高级管理人员以及保荐人、承销商、证券服务机构及其相关执业人员等违反《证券法》依法应予以行政处罚的，中国证监会将依法予以处罚。涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":57,"n":"第五十七条","txt":"中国证监会将遵守本办法的情况记入证券市场诚信档案，会同有关部门加强信息共享，依法实施守信激励与失信惩戒。"},{"i":58,"n":"第五十八条","txt":"本办法自2021年11月15日起施行。"}],"quyuxingguquanshichangjianduguanlishixingbanfa":[{"i":1,"n":"第一条","txt":"为了规范区域性股权市场的活动，保护投资者合法权益，防范区域性股权市场风险，促进区域性股权市场健康发展，根据《中华人民共和国证券法》《中华人民共和国公司法》《国务院办公厅关于规范发展区域性股权市场的通知》等规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在区域性股权市场非公开发行、转让中小微企业股票、可转换为股票的公司债券和国务院有关部门认可的其他证券，以及相关活动，适用本办法。"},{"i":3,"n":"第三条","txt":"区域性股权市场是为其所在省级行政区域内中小微企业证券非公开发行、转让及相关活动提供设施与服务的场所。 除区域性股权市场外，地方其他各类交易场所不得组织证券发行和转让活动。"},{"i":4,"n":"第四条","txt":"在区域性股权市场内的证券发行、转让及相关活动，应当遵守法律、行政法规和规章等规定，遵循公平自愿、诚实信用、风险自担的原则。禁止欺诈、内幕交易、操纵市场、非法集资行为。"},{"i":5,"n":"第五条","txt":"省级人民政府依法对区域性股权市场进行监督管理，负责风险处置。 省级人民政府指定地方金融监管部门承担对区域性股权市场的日常监督管理职责，依法查处违法违规行为，组织开展风险防范、处置工作。 省级人民政府根据法律、行政法规、国务院有关规定和本办法，制定区域性股权市场监督管理的实施细则和操作办法。"},{"i":6,"n":"第六条","txt":"中国证券监督管理委员会（以下简称中国证监会）及其派出机构对地方金融监管部门的区域性股权市场监督管理工作进行指导、协调和监督，对市场规范运作情况进行监督检查，对市场风险进行预警提示和处置督导。 地方金融监管部门与中国证监会派出机构应当建立区域性股权市场监管合作及信息共享机制。"},{"i":7,"n":"第七条","txt":"区域性股权市场运营机构（以下简称运营机构）负责组织区域性股权市场的活动，对市场参与者进行自律管理。 各省、自治区、直辖市、计划单列市行政区域内设立的运营机构不得超过一家。"},{"i":8,"n":"第八条","txt":"运营机构应当具备下列条件： （一）依法设立的法人； （二）开展业务活动所必需的营业场所、业务设施、营运资金、专业人员； （三）健全的法人治理结构； （四）完善的风险管理与内部控制制度； （五）法律、行政法规和中国证监会规定的其他条件。 证券公司可以参股、控股运营机构。 有《中华人民共和国证券法》第一百零八条规定的情形，或者被中国证监会采取证券市场禁入措施且仍处于禁入期间的，不得担任运营机构的负责人。"},{"i":9,"n":"第九条","txt":"省级人民政府对运营机构实施监督管理，向社会公告运营机构名单，并报中国证监会备案。未经公告并备案，任何单位和个人不得组织、开展区域性股权市场相关活动。"},{"i":10,"n":"第十条","txt":"企业在区域性股权市场发行股票，应当符合下列条件： （一）有符合《中华人民共和国公司法》规定的治理结构； （二）最近一个会计年度的财务会计报告无虚假记载； （三）没有处于持续状态的重大违法行为； （四）法律、行政法规和中国证监会规定的其他条件。"},{"i":11,"n":"第十一条","txt":"企业在区域性股权市场发行可转换为股票的公司债券，应当符合下列条件： （一）本办法第十条规定的条件； （二）债券募集说明书中有具体的公司债券转换为股票的办法； （三）本公司已发行的公司债券或者其他债务没有处于持续状态的违约或者迟延支付本息的情形； （四）法律、行政法规和中国证监会规定的其他条件。"},{"i":12,"n":"第十二条","txt":"未经国务院有关部门认可，不得在区域性股权市场发行除股票、可转换为股票的公司债券之外的其他证券。"},{"i":13,"n":"第十三条","txt":"在区域性股权市场发行证券，应当向合格投资者发行。单只证券持有人数量累计不得超过200人，法律、行政法规另有规定的除外。 前款所称合格投资者，应当具有较强风险识别和承受能力，并符合下列条件之一： （一）证券公司、期货公司、基金管理公司及其子公司、商业银行、保险公司、信托公司、财务公司等依法经批准设立的金融机构，以及依法备案或者登记的证券公司子公司、期货公司子公司、私募基金管理人； （二）证券公司资产管理产品、基金管理公司及其子公司产品、期货公司资产管理产品、银行理财产品、保险产品、信托产品等金融机构依法管理的投资性计划； （三）社会保障基金，企业年金等养老基金，慈善基金等社会公益基金，以及依法备案的私募基金； （四）依法设立且净资产不低于一定指标的法人或者其他组织； （五）在一定时期内拥有符合中国证监会规定的金融资产价值不低于人民币50万元，且具有2年以上金融产品投资经历或者2年以上金融"},{"i":14,"n":"第十四条","txt":"在区域性股权市场发行证券，不得通过拆分、代持等方式变相突破合格投资者标准。有下列情形之一的，应当穿透核查最终投资者是否为合格投资者，并合并计算投资者人数： （一）以理财产品、合伙企业等形式汇集多个投资者资金直接或者间接投资于证券的； （二）将单只证券分期发行的。 理财产品、合伙企业等投资者符合本办法第十三条第二款第（二）项、第（三）项规定的除外。"},{"i":15,"n":"第十五条","txt":"在区域性股权市场发行证券，不得采用广告、公开劝诱等公开或者变相公开方式。 通过互联网络、广播电视、报刊等向社会公众发布招股说明书、债券募集说明书、拟转让证券数量和价格等有关证券发行或者转让信息的，属于前款规定的公开或者变相公开方式；但符合下列条件的除外： （一）通过运营机构的信息系统等网络平台向在本市场开户的合格投资者发布证券发行或者转让信息； （二）投资者需凭用户名和密码等身份认证方式登录后才能查看。"},{"i":16,"n":"第十六条","txt":"在区域性股权市场挂牌转让证券的企业（以下简称挂牌公司），应当符合本办法第十条规定的条件。"},{"i":17,"n":"第十七条","txt":"在区域性股权市场转让证券的，应当符合本办法第十二条、第十三条、第十四条、第十五条规定，不得采取集中竞价、连续竞价、做市商等集中交易方式。 投资者在区域性股权市场买入后卖出或者卖出后买入同一证券的时间间隔不得少于5个交易日。"},{"i":18,"n":"第十八条","txt":"符合下列情形之一的，不受本办法第十三条规定的限制： （一）证券发行人、挂牌公司实施股权激励计划； （二）证券发行人、挂牌公司的董事、监事、高级管理人员及发行、挂牌前已持有股权的股东认购或者受让本发行人、挂牌公司证券； （三）因继承、赠与、司法裁决、企业并购等非交易行为获得证券。"},{"i":19,"n":"第十九条","txt":"运营机构依法对证券发行、挂牌转让申请文件进行审查，出具审查意见，并在发行、挂牌完成后5个工作日内报地方金融监管部门和中国证监会派出机构备案。"},{"i":20,"n":"第二十条","txt":"运营机构应当在每个交易日发布证券挂牌转让的最新价格行情。"},{"i":21,"n":"第二十一条","txt":"证券发行人、挂牌公司及区域性股权市场的其他参与者应当按照规定和协议约定，真实、准确、完整地向投资者披露信息，不得有虚假记载、误导性陈述或者重大遗漏。 运营机构应当建立信息披露网络平台，供信息披露义务人按照规定披露信息。"},{"i":22,"n":"第二十二条","txt":"证券发行人应当披露招股说明书、债券募集说明书，并在发生可能对已发行证券产生较大影响的重要事件时，披露临时报告。 挂牌公司应当在每一会计年度结束之日起4个月内编制并披露年度报告，并在发生可能对证券转让价格产生较大影响的重要事件时，披露临时报告。 招股说明书、债券募集说明书、年度报告应当包括公司基本情况、公司治理、控股股东和实际控制人情况、业务概况、财务会计报告以及可能对证券发行或者转让具有较大影响的其他情况。"},{"i":23,"n":"第二十三条","txt":"投资者在区域性股权市场买卖证券，应当向办理登记结算业务的机构申请开立证券账户。办理登记结算业务的机构可以直接为投资者开立证券账户，也可以委托参与本市场的证券公司代为办理。 开立证券账户的机构应当对申请人是否符合本办法规定的合格投资者条件进行审查，对不符合规定条件的申请人，不得为其开立证券账户。申请人为自然人的，还应当在为其开立证券账户前，通过书面或者电子形式向其揭示风险，并要求其确认。 本办法施行前已开立证券账户但不符合本办法规定的合格投资者条件的投资者，不得认购和受让证券；已经认购或者受让证券的，只能继续持有或者卖出。"},{"i":24,"n":"第二十四条","txt":"投资者在区域性股权市场内买卖证券的资金，应当专户存放在商业银行或者国务院金融监督管理机构批准的具有证券期货保证金存管业务资格的机构。任何单位和个人不得以任何形式挪用投资者资金。 省级人民政府制定投资者在区域性股权市场内买卖证券资金的管理细则，明确投资者资金的动用情形、划转路径和有关各方的职责。 运营机构应当每日监测投资者资金的变动情况，发现异常情形及时处理并向地方金融监管部门和中国证监会派出机构报告。"},{"i":25,"n":"第二十五条","txt":"区域性股权市场的登记结算业务，应当由运营机构或者中国证监会认可的登记结算机构办理。 在区域性股权市场内发行、转让的证券，应当在办理登记结算业务的机构集中存管和登记。办理登记结算业务的机构应当根据证券登记结算的结果，确认证券持有人持有证券的事实，提供证券持有人登记资料。 办理登记结算业务的机构应当妥善保存登记、结算的原始凭证及有关文件和资料，保存期限不得少于20年。"},{"i":26,"n":"第二十六条","txt":"办理登记结算业务的机构应当按照规定办理证券账户开立、变更、注销和证券登记、结算，保证证券持有人名册和登记过户记录真实、准确、完整，证券和资金的清算交收有序进行。 办理登记结算业务的机构不得挪用投资者的证券。 办理登记结算业务的机构与中国证券登记结算有限责任公司应当建立证券账户对接机制，将区域性股权市场证券账户纳入到资本市场统一证券账户体系。"},{"i":27,"n":"第二十七条","txt":"中介机构及其业务人员在区域性股权市场从事相关业务活动的，应当诚实守信、勤勉尽责，遵守法律、行政法规、中国证监会和有关省级人民政府规定等，遵守行业规范，对其业务行为承担责任。"},{"i":28,"n":"第二十八条","txt":"运营机构可以自行或者组织有关中介机构开展下列业务活动： （一）为参与本市场的企业提供改制辅导、管理培训、管理咨询、财务顾问服务； （二）为证券的非公开发行组织合格投资者进行路演推介或者其他促成投融资需求对接的活动； （三）为合格投资者提供企业研究报告和尽职调查信息； （四）为在本市场开户的合格投资者买卖证券提供居间介绍服务； （五）与商业银行、小额贷款公司等开展业务合作，支持其为参与本市场的企业提供融资服务； （六）中国证监会规定的其他业务。"},{"i":29,"n":"第二十九条","txt":"运营机构开展本办法第二十八条规定的业务活动，应当按照下列规定采取有效措施，防范运营机构与市场参与者、不同参与者之间的利益冲突： （一）为参与本市场的企业提供服务的，应当采取业务隔离措施，避免与投资者的利益冲突； （二）为合格投资者提供企业研究报告和尽职调查信息的，应当遵循独立、客观的原则，不得提供证券投资建议，不得提供虚假、不实、误导性信息； （三）为合格投资者买卖证券提供居间介绍服务的，应当公平对待买卖双方，不得损害任何一方的利益； （四）向服务对象收取费用的，应当符合有关规定并披露收费标准。"},{"i":30,"n":"第三十条","txt":"区域性股权市场应当作为地方人民政府扶持中小微企业政策措施的综合运用平台，为地方人民政府市场化运用贴息、投资等资金扶持中小微企业发展提供服务。"},{"i":31,"n":"第三十一条","txt":"区域性股权市场可以在依法合规、风险可控前提下，开展业务、产品、运营模式和服务方式创新，为中小微企业提供多样化、个性化的服务。 区域性股权市场可以按照规定为中小微企业信息展示提供服务。"},{"i":32,"n":"第三十二条","txt":"区域性股权市场不得为其所在省级行政区域外企业证券的发行、转让或者登记存管提供服务。"},{"i":33,"n":"第三十三条","txt":"区域性股权市场可以与证券期货交易所、全国中小企业股份转让系统、机构间私募产品报价与服务系统、证券期货经营机构、证券期货服务机构、证券期货行业自律组织，建立合作机制。但是，有违反本办法第三十二条规定情形的除外。 符合中国证监会规定条件的运营机构，可以开展全国中小企业股份转让系统的推荐业务试点。"},{"i":34,"n":"第三十四条","txt":"运营机构应当负责区域性股权市场信息系统的开发、运行、维护，以及信息安全的管理，保证区域性股权市场信息系统安全稳定运行。 区域性股权市场的信息系统应当符合有关法律法规和信息技术管理规范，并通过中国证监会组织的合规性、安全性评估；未通过评估的，应当限期整改。 区域性股权市场的信息技术管理规范，由中国证监会另行制定。"},{"i":35,"n":"第三十五条","txt":"运营机构、办理登记结算业务的机构应当将证券交易、登记、结算等信息系统与中国证监会指定的监管信息系统进行对接。 运营机构应当自每个月结束之日起7个工作日内，向地方金融监管部门和中国证监会派出机构报送区域性股权市场有关信息；发生影响或者可能影响区域性股权市场安全稳定运行的重大事件的，应当立即报告。 运营机构报送的信息必须真实、准确、完整，指标、格式、统计方法应当规范、统一，具体办法由中国证监会另行制定。"},{"i":36,"n":"第三十六条","txt":"运营机构、办理登记结算业务的机构制定的业务操作细则和自律管理规则，应当符合法律、行政法规、中国证监会规章和规范性文件、有关省级人民政府的监管细则等规定，并报地方金融监管部门和中国证监会派出机构备案。 地方金融监管部门和中国证监会派出机构发现业务操作细则和自律管理规则违反相关规定的，可以责令其修改。"},{"i":37,"n":"第三十七条","txt":"运营机构应当按照规定对区域性股权市场参与者的违法行为及违反自律管理规则的行为，采取自律管理措施，并向地方金融监管部门和中国证监会派出机构报告。 运营机构应当畅通投诉渠道，妥善处理投资者投诉，保护投资者合法权益。"},{"i":38,"n":"第三十八条","txt":"运营机构应当对区域性股权市场进行风险监测、评估、预警和采取有关处置措施，防范和化解市场风险。"},{"i":39,"n":"第三十九条","txt":"运营机构可以以特别会员方式加入中国证券业协会，接受中国证券业协会的自律管理和服务。 证券公司作为运营机构股东或者在区域性股权市场从事相关业务活动的，应当遵守证券行业监管和自律规则。 中国证券业协会督促引导证券公司为区域性股权市场的投融资活动提供优质高效低廉服务。鼓励证券公司为区域性股权市场提供业务、技术等支持。"},{"i":40,"n":"第四十条","txt":"地方金融监管部门实施现场检查，可以采取下列措施： （一）进入运营机构或者区域性股权市场有关参与者的办公场所或者营业场所进行检查； （二）询问运营机构或者区域性股权市场有关参与者的负责人、工作人员，要求其对有关检查事项做出说明； （三）查阅、复制与检查事项有关的文件、资料，对可能被转移、隐匿或者毁损的文件、资料、电子设备予以封存； （四）检查运营机构或者区域性股权市场有关参与者的信息系统，复制有关数据资料； （五）法律、行政法规和中国证监会规定的其他措施。 中国证监会派出机构可以采取前款规定的措施，对区域性股权市场规范运作情况进行现场检查。"},{"i":41,"n":"第四十一条","txt":"地方金融监管部门和中国证监会派出机构依法履行职责，被检查、调查的单位和个人应当配合，如实提供有关文件和资料，不得拒绝、阻碍和隐瞒。"},{"i":42,"n":"第四十二条","txt":"运营机构违法违规经营或者出现重大风险，严重危害区域性股权市场秩序、损害投资者利益的，由地方金融监管部门责令停业整顿，并更换有关责任人员。"},{"i":43,"n":"第四十三条","txt":"运营机构或者区域性股权市场参与者违反本办法规定的，地方金融监管部门可以采取责令改正、监管谈话、出具警示函、责令参加培训、责令定期报告、认定为不适当人选等监督管理措施；依法应予行政处罚的，给予警告，并处以3 万元以下罚款。具体实施细则由省级人民政府制定。 对违反本办法规定的行为，法律、行政法规或者国务院另有规定的，依照其规定处理。"},{"i":44,"n":"第四十四条","txt":"运营机构从业人员或者其他参与区域性股权市场的人员违反法律、行政法规或者本办法规定，情节严重的，中国证监会可以依法采取证券市场禁入的措施。"},{"i":45,"n":"第四十五条","txt":"对运营机构或者区域性股权市场参与者从事内幕交易、操纵市场等严重扰乱市场秩序行为的，依法从严查处。"},{"i":46,"n":"第四十六条","txt":"中国证监会派出机构发现违反本办法行为的线索，应当移送地方金融监管部门处理。"},{"i":47,"n":"第四十七条","txt":"地方金融监管部门未按照规定对违反本办法行为进行查处的，中国证监会派出机构应当予以指导、协调和监督。"},{"i":48,"n":"第四十八条","txt":"中国证监会派出机构对地方金融监管部门的监管能力和条件进行审慎评估，加强监管培训，采取有效措施，促使地方监管能力与市场发展状况相适应。"},{"i":49,"n":"第四十九条","txt":"中国证监会派出机构可以对区域性股权市场的安全规范运行情况、风险管理能力等进行监测评估。 评估结果应当作为区域性股权市场开展先行先试相关业务的审慎性条件。"},{"i":50,"n":"第五十条","txt":"违反本办法第三条第二款规定，组织证券发行和转让活动，或者违反本办法第九条规定，擅自组织开展区域性股权市场活动的，按照《国务院关于清理整顿各类交易场所 切实防范金融风险的决定》（国发〔2011〕38号）和《国务院办公厅关于清理整顿各类交易场所的实施意见》（国办发〔2012〕37号）规定予以清理，并依法追究法律责任。"},{"i":51,"n":"第五十一条","txt":"运营机构应当建立区域性股权市场诚信档案，并按照规定提供诚信信息的查询和公示。 运营机构和区域性股权市场参与者及其相关人员的诚信信息，应当同时按照规定记入中国证监会证券期货市场诚信档案数据库。"},{"i":52,"n":"第五十二条","txt":"区域性股权市场为其所在省级行政区域内的有限责任公司股权融资或者转让提供服务的，参照适用本办法。"},{"i":53,"n":"第五十三条","txt":"本办法自2017年7月1日起施行。《关于规范证券公司参与区域性股权交易市场的指导意见（试行）》（证监会公告〔2012〕20号）同时废止。"}],"kezhuanhuangongsizhaiquanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范可转换公司债券（以下简称可转债）的交易行为，保护投资者合法权益，维护市场秩序和社会公共利益，根据《证券法》《公司法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"可转债在证券交易所或者国务院批准的其他全国性证券交易场所（以下简称证券交易场所）的交易、转让、信息披露、转股、赎回与回售等相关活动，适用本办法。 本办法所称可转债，是指公司依法发行、在一定期间内依据约定的条件可以转换成本公司股票的公司债券，属于《证券法》规定的具有股权性质的证券。"},{"i":3,"n":"第三条","txt":"向不特定对象发行的可转债应当在依法设立的证券交易所上市交易或者在国务院批准的其他全国性证券交易场所交易。 证券交易场所应当根据可转债的风险和特点，完善交易规则，防范和抑制过度投机。 进行可转债程序化交易的，应当符合中国证监会的规定，并向证券交易所报告，不得影响证券交易所系统安全或者正常交易秩序。"},{"i":4,"n":"第四条","txt":"发行人向特定对象发行的可转债不得采用公开的集中交易方式转让。 上市公司向特定对象发行的可转债转股的，所转换股票自可转债发行结束之日起十八个月内不得转让。"},{"i":5,"n":"第五条","txt":"证券交易场所应当根据可转债的特点及正股所属板块的投资者适当性要求，制定相应的投资者适当性管理规则。 证券公司应当充分了解客户，对客户是否符合可转债投资者适当性要求进行核查和评估，不得接受不符合适当性要求的客户参与可转债交易。证券公司应当引导客户理性、规范地参与可转债交易。"},{"i":6,"n":"第六条","txt":"证券交易场所应当加强对可转债的风险监测，建立跨正股与可转债的监测机制，并根据可转债的特点制定针对性的监测指标。 可转债交易出现异常波动时，证券交易场所可以根据业务规则要求发行人进行核查、披露异常波动公告，向市场充分提示风险，也可以根据业务规则采取临时停牌等处置措施。"},{"i":7,"n":"第七条","txt":"发生可能对可转债的交易转让价格产生较大影响的重大事件，投资者尚未得知时，发行人应当立即将有关该重大事件的情况向中国证监会和证券交易场所报送临时报告，并予公告，说明事件的起因、目前的状态和可能产生的法律后果。 前款所称重大事件包括： （一）《证券法》第八十条第二款、第八十一条第二款规定的重大事件； （二）因配股、增发、送股、派息、分立、减资及其他原因引起发行人股份变动，需要调整转股价格，或者依据募集说明书约定的转股价格向下修正条款修正转股价格； （三）募集说明书约定的赎回条件触发，发行人决定赎回或者不赎回； （四）可转债转换为股票的数额累计达到可转债开始转股前公司已发行股票总额的百分之十； （五）未转换的可转债总额少于三千万元； （六）可转债担保人发生重大资产变动、重大诉讼、合并、分立等情况； （七）中国证监会规定的其他事项。"},{"i":8,"n":"第八条","txt":"可转债自发行结束之日起不少于六个月后方可转换为公司股票，转股期限由公司根据可转债的存续期限及公司财务状况确定。 可转债持有人对转股或者不转股有选择权，并于转股的次日成为发行人股东。"},{"i":9,"n":"第九条","txt":"上市公司向不特定对象发行可转债的转股价格应当不低于募集说明书公告日前二十个交易日发行人股票交易均价和前一个交易日均价，且不得向上修正。 上市公司向特定对象发行可转债的转股价格应当不低于认购邀请书发出前二十个交易日发行人股票交易均价和前一个交易日均价，且不得向下修正。"},{"i":10,"n":"第十条","txt":"募集说明书应当约定转股价格调整的原则及方式。发行可转债后，因配股、增发、送股、派息、分立、减资及其他原因引起发行人股份变动的，应当同时调整转股价格。 上市公司可转债募集说明书约定转股价格向下修正条款的，应当同时约定： （一）转股价格修正方案须提交发行人股东大会表决，且须经出席会议的股东所持表决权的三分之二以上同意，持有发行人可转债的股东应当回避； （二）修正后的转股价格不低于前项通过修正方案的股东大会召开日前二十个交易日该发行人股票交易均价和前一个交易日均价。"},{"i":11,"n":"第十一条","txt":"募集说明书可以约定赎回条款，规定发行人可按事先约定的条件和价格赎回尚未转股的可转债。 募集说明书可以约定回售条款，规定可转债持有人可按事先约定的条件和价格将所持可转债回售给发行人。募集说明书应当约定，发行人改变募集资金用途的，赋予可转债持有人一次回售的权利。"},{"i":12,"n":"第十二条","txt":"发行人在决定是否行使赎回权或者对转股价格进行调整、修正时，应当遵守诚实信用的原则，不得误导投资者或者损害投资者的合法权益。保荐人应当在持续督导期内对上述行为予以监督。"},{"i":13,"n":"第十三条","txt":"在可转债存续期内，发行人应当持续关注赎回条件是否满足，预计可能满足赎回条件的，应当在赎回条件满足的五个交易日前及时披露，向市场充分提示风险。"},{"i":14,"n":"第十四条","txt":"发行人应当在赎回条件满足后及时披露，明确说明是否行使赎回权。 发行人决定行使赎回权的，应当披露赎回公告，明确赎回的期间、程序、价格等内容，并在赎回期结束后披露赎回结果公告。 发行人决定不行使赎回权的，在证券交易场所规定的期限内不得再次行使赎回权。 发行人决定行使或者不行使赎回权的，还应当充分披露其实际控制人、控股股东、持股百分之五以上的股东、董事、监事、高级管理人员在赎回条件满足前的六个月内交易该可转债的情况，上述主体应当予以配合。"},{"i":15,"n":"第十五条","txt":"发行人应当在回售条件满足后披露回售公告，明确回售的期间、程序、价格等内容，并在回售期结束后披露回售结果公告。"},{"i":16,"n":"第十六条","txt":"向不特定对象发行可转债的，发行人应当为可转债持有人聘请受托管理人，并订立可转债受托管理协议。向特定对象发行可转债的，发行人应当在募集说明书中约定可转债受托管理事项。 可转债受托管理人应当按照《公司债券发行与交易管理办法》的规定以及可转债受托管理协议的约定履行受托管理职责。"},{"i":17,"n":"第十七条","txt":"募集说明书应当约定可转债持有人会议规则。可转债持有人会议规则应当公平、合理。 可转债持有人会议规则应当明确可转债持有人通过可转债持有人会议行使权利的范围，可转债持有人会议的召集、通知、决策机制和其他重要事项。 可转债持有人会议按照本办法的规定及会议规则的程序要求所形成的决议对全体可转债持有人具有约束力。"},{"i":18,"n":"第十八条","txt":"可转债受托管理人应当按照《公司债券发行与交易管理办法》规定或者有关约定及时召集可转债持有人会议。 在可转债受托管理人应当召集而未召集可转债持有人会议时，单独或合计持有本期可转债总额百分之十以上的持有人有权自行召集可转债持有人会议。"},{"i":19,"n":"第十九条","txt":"发行人应当在募集说明书中约定构成可转债违约的情形、违约责任及其承担方式以及可转债发生违约后的诉讼、仲裁或其他争议解决机制。"},{"i":20,"n":"第二十条","txt":"违反本办法规定的，中国证监会可以对当事人采取责令改正、监管谈话、出具警示函以及中国证监会规定的相关监管措施；依法应予行政处罚的，依照《证券法》《公司法》等法律法规和中国证监会的有关规定进行处罚；情节严重的，对有关责任人员采取证券市场禁入措施；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":21,"n":"第二十一条","txt":"可转债的发行活动，适用中国证监会有关发行的相关规定。 在并购重组活动中发行的可转债适用本办法，其重组报告书、财务顾问适用本办法关于募集说明书、保荐人的要求；中国证监会另有规定的，从其规定。"},{"i":22,"n":"第二十二条","txt":"对于本办法施行日以前已经核准注册发行或者尚未核准注册但发行申请已被受理的可转债，其募集说明书、重组报告书的内容要求按照本办法施行日以前的规则执行。"},{"i":23,"n":"第二十三条","txt":"本办法自2021年1月31日起施行。"}],"hegejingneijigoutouzizhejingwaizhengquantouziguanlfcf19f":[{"i":1,"n":"第一条","txt":"为了规范合格境内机构投资者境外证券投资行为，保护投资人合法权益，根据《证券投资基金法》、《证券法》和其他有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称合格境内机构投资者（以下简称境内机构投资者），是指符合本办法规定的条件，经中国证券监督管理委员会（以下简称中国证监会）批准在中华人民共和国境内募集资金，运用所募集的部分或者全部资金以资产组合方式进行境外证券投资管理的境内基金管理公司和证券公司等证券经营机构。"},{"i":3,"n":"第三条","txt":"境内机构投资者开展境外证券投资业务，应当由境内商业银行负责资产托管业务，可以委托境外证券服务机构代理买卖证券。"},{"i":4,"n":"第四条","txt":"中国证监会和国家外汇管理局（以下简称国家外汇局）依法按照各自职能对境内机构投资者境外证券投资实施监督管理。"},{"i":5,"n":"第五条","txt":"申请境内机构投资者资格，应当具备下列条件： （一）申请人的财务稳健，资信良好，资产管理规模、经营年限等符合中国证监会的规定； （二）拥有符合规定的具有境外投资管理相关经验的人员； （三）具有健全的治理结构和完善的内控制度，经营行为规范； （四）最近3年没有受到监管机构的重大处罚，没有重大事项正在接受司法部门、监管机构的立案调查； （五）中国证监会根据审慎监管原则规定的其他条件。"},{"i":6,"n":"第六条","txt":"第五条第（一）项所指的条件是： （一）基金管理公司：净资产不少于2亿元人民币；经营证券投资基金（以下简称基金）管理业务达2年以上；在最近一个季度末资产管理规模不少于200亿元人民币或等值外汇资产； （二）证券公司：各项风险控制指标符合规定标准；净资本不低于8亿元人民币；净资本与净资产比例不低于70％；经营集合资产管理计划（以下简称集合计划）业务达1年以上；在最近一个季度末资产管理规模不少于20亿元人民币或等值外汇资产。"},{"i":7,"n":"第七条","txt":"第五条第（二）项所指的条件是：具有5年以上境外证券市场投资管理经验和相关专业资质的中级以上管理人员不少于1名，具有3年以上境外证券市场投资管理相关经验的人员不少于3名。"},{"i":8,"n":"第八条","txt":"申请境内机构投资者资格的，应当向中国证监会报送下列文件（一份正本、一份副本）： （一）申请表； （二）符合本办法第五条规定的证明文件； （三）中国证监会要求的其他文件。"},{"i":9,"n":"第九条","txt":"中国证监会收到完整的资格申请文件后对申请材料进行审核，做出批准或者不批准的决定。决定批准的，颁发境外证券投资业务许可文件；决定不批准的，书面通知申请人。"},{"i":10,"n":"第十条","txt":"申请人可在取得境内机构投资者资格后，向中国证监会报送产品募集申请文件。"},{"i":11,"n":"第十一条","txt":"中国证监会自收到完整的产品募集申请文件后对申请材料进行审核，做出批准或者不批准的决定，并书面通知申请人。"},{"i":12,"n":"第十二条","txt":"境内机构投资者应当依照有关规定向国家外汇局申请经营外汇业务资格。"},{"i":13,"n":"第十三条","txt":"本办法所称境外投资顾问（以下简称投资顾问）是指符合本办法规定的条件，根据合同为境内机构投资者境外证券投资提供证券买卖建议或投资组合管理等服务并取得收入的境外金融机构。"},{"i":14,"n":"第十四条","txt":"境内机构投资者可以委托符合下列条件的投资顾问进行境外证券投资： （一）在境外设立，经所在国家或地区监管机构批准从事投资管理业务； （二）所在国家或地区证券监管机构已与中国证监会签订双边监管合作谅解备忘录，并保持着有效的监管合作关系； （三）经营投资管理业务达5年以上，最近一个会计年度管理的证券资产不少于100亿美元或等值货币； （四）有健全的治理结构和完善的内控制度，经营行为规范，最近5年没有受到所在国家或地区监管机构的重大处罚，没有重大事项正在接受司法部门、监管机构的立案调查。 境内证券公司在境外设立的分支机构担任投资顾问的，可以不受前款第（三）项规定的限制。"},{"i":15,"n":"第十五条","txt":"境内机构投资者应当承担受信责任，在挑选、委托投资顾问过程中，履行尽职调查义务。"},{"i":16,"n":"第十六条","txt":"投资顾问应当严格遵守境内有关法律法规、基金合同和集合资产管理合同的规定，始终将基金、集合计划持有人的利益置于首位，以合理的依据提出投资建议，寻求基金、集合计划的最佳交易执行，公平客观对待所有客户，始终按照基金、集合计划的投资目标、策略、政策、指引和限制实施投资决定，充分披露一切涉及利益冲突的重要事实，尊重客户信息的机密性。"},{"i":17,"n":"第十七条","txt":"境内机构投资者授权投资顾问负责投资决策的，应当在协议中明确投资顾问由于本身差错、疏忽、未履行职责等原因而导致财产受损时应当承担相应责任。"},{"i":18,"n":"第十八条","txt":"境内机构投资者开展境外证券投资业务时，应当由具有证券投资基金托管资格的银行（以下简称托管人）负责资产托管业务。"},{"i":19,"n":"第十九条","txt":"托管人可以委托符合下列条件的境外资产托管人负责境外资产托管业务： （一）在中国大陆以外的国家或地区设立，受当地政府、金融或证券监管机构的监管； （二）最近一个会计年度实收资本不少于10亿美元或等值货币或托管资产规模不少于1000亿美元或等值货币； （三）有足够的熟悉境外托管业务的专职人员； （四）具备安全保管资产的条件； （五）具备安全、高效的清算、交割能力； （六）最近3年没有受到监管机构的重大处罚，没有重大事项正在接受司法部门、监管机构的立案调查。"},{"i":20,"n":"第二十条","txt":"托管人应当按照有关法律法规履行下列受托人职责： （一）保护持有人利益，按照规定对基金、集合计划日常投资行为和资金汇出入情况实施监督，如发现投资指令或资金汇出入违法、违规，应当及时向中国证监会、国家外汇局报告； （二）安全保护基金、集合计划财产，准时将公司行为信息通知境内机构投资者，确保基金、集合计划及时收取所有应得收入； （三）确保基金、集合计划按照有关法律法规、基金合同和集合资产管理合同约定的投资目标和限制进行管理； （四）按照有关法律法规、基金合同和集合资产管理合同的约定执行境内机构投资者、投资顾问的指令，及时办理清算、交割事宜； （五）确保基金、集合计划的份额净值按照有关法律法规、基金合同和集合资产管理合同规定的方法进行计算； （六）确保基金、集合计划按照有关法律法规、基金合同和集合资产管理合同的规定进行申购、认购、赎回等日常交易； （七）确保基金、集合计划根据有关法律法规、基金"},{"i":21,"n":"第二十一条","txt":"对基金、集合计划的境外财产，托管人可授权境外托管人代为履行其承担的受托人职责。境外托管人在履行职责过程中，因本身过错、疏忽等原因而导致基金、集合计划财产受损的，托管人应当承担相应责任。"},{"i":22,"n":"第二十二条","txt":"托管人应当按照有关法律法规履行下列托管职责： （一）安全保管基金、集合计划资产，开设资金账户和证券账户； （二）办理境内机构投资者的有关结汇、售汇、收汇、付汇和人民币资金结算业务； （三）保存境内机构投资者的资金汇出、汇入、兑换、收汇、付汇、资金往来、委托及成交记录等相关资料，其保存的时间应当不少于20年； （四）中国证监会和国家外汇局根据审慎监管原则规定的其他职责。"},{"i":23,"n":"第二十三条","txt":"托管人、境外托管人应当将其自有资产和境内机构投资者管理的财产严格分开。"},{"i":24,"n":"第二十四条","txt":"取得境内机构投资者资格的基金管理公司可以根据有关法律法规通过公开发售基金份额募集基金，运用基金财产投资于境外证券市场。基金管理公司申请募集基金，应当根据有关法律法规规定提交申请材料。"},{"i":25,"n":"第二十五条","txt":"取得境内机构投资者资格的证券公司可以通过设立集合计划等方式募集资金，运用所募集的资金投资于境外证券市场。设立集合计划的，应当按照有关规定提交申请材料，进行资金募集和投资运作。"},{"i":26,"n":"第二十六条","txt":"申请募集的基金应当根据有关规定选择投资业绩比较基准。"},{"i":27,"n":"第二十七条","txt":"基金、集合计划应当投资于中国证监会规定的金融产品或工具。"},{"i":28,"n":"第二十八条","txt":"基金、集合计划应当遵守有关投资比例限制的规定。"},{"i":29,"n":"第二十九条","txt":"境内机构投资者、投资顾问挑选、委托境外证券服务机构代理买卖证券的，应当严格履行受信责任，并按照有关规定对投资交易的流程、信息披露、记录保存进行管理。"},{"i":30,"n":"第三十条","txt":"境内机构投资者、投资顾问与境外证券服务机构之间的证券交易和研究服务安排，应当按照以下原则进行： （一）交易佣金属于基金、集合计划持有人的财产； （二）境内机构投资者、投资顾问有责任代表持有人确保交易质量，包括但不限于： 1.寻求最佳交易执行； 2.力求交易成本最小化； 3.使用持有人的交易佣金使持有人受益。"},{"i":31,"n":"第三十一条","txt":"境内机构投资者的境外证券投资，应当遵守当地监管机构、交易所的有关法律法规规定。"},{"i":32,"n":"第三十二条","txt":"境内机构投资者、托管人等信息披露义务人应当严格按照有关法律法规规定的要求进行信息披露。"},{"i":33,"n":"第三十三条","txt":"境内机构投资者应当根据市场情况、产品特性等在募集方案中设定合理的额度规模上限，向国家外汇局备案，并按照有关规定到国家外汇局办理相关手续。基金、集合计划存续期内的额度规模管理应当按照有关规定进行。"},{"i":34,"n":"第三十四条","txt":"境内机构投资者应当在托管人处开立托管账户，托管基金、集合计划的全部资产。"},{"i":35,"n":"第三十五条","txt":"托管人应当为基金、集合计划开立结算账户和证券托管账户，用于与证券登记结算等机构之间的资金结算业务和证券托管业务。"},{"i":36,"n":"第三十六条","txt":"托管账户、结算账户和证券托管账户的收入、支出范围应当符合有关规定,账户内的资金不得向他人贷款或提供担保。"},{"i":37,"n":"第三十七条","txt":"境内机构投资者应当定期向国家外汇局报告其额度使用及资金汇出入情况。"},{"i":38,"n":"第三十八条","txt":"中国证监会和国家外汇局可以要求境内机构投资者、托管人提供境内机构投资者境外投资活动有关资料；必要时，可以进行现场检查。"},{"i":39,"n":"第三十九条","txt":"境内机构投资者有下列情形之一的，应当在其发生后5个工作日内报中国证监会备案并公告： （一）变更托管人或境外托管人； （二）变更投资顾问； （三）境外涉及诉讼及其他重大事件； （四）中国证监会规定的其他情形。 托管人或境外托管人发生变更的，境内机构投资者应当同时报国家外汇局备案。"},{"i":40,"n":"第四十条","txt":"境内机构投资者有下列情形之一的，应当在其发生后60个工作日内重新申请境外证券投资业务资格，并向国家外汇局重新办理经营外汇业务资格申请、投资额度备案手续： （一）变更机构名称； （二）被其他机构吸收合并； （三）中国证监会、国家外汇局规定的其他情形。"},{"i":41,"n":"第四十一条","txt":"境内机构投资者运用基金、集合计划财产进行证券投资，发生重大违法、违规行为的，中国证监会可以依法采取限制交易行为等措施，国家外汇局可以依法采取限制其资金汇出入等措施。"},{"i":42,"n":"第四十二条","txt":"托管人违法、违规严重的，中国证监会可以依法做出限制其托管业务的决定。"},{"i":43,"n":"第四十三条","txt":"境内机构投资者、托管人等违反本办法的，由中国证监会、国家外汇局依法进行相应的行政处罚。"},{"i":44,"n":"第四十四条","txt":"境内机构投资者投资于香港特别行政区、澳门特别行政区的金融产品或工具，参照本办法执行。"},{"i":45,"n":"第四十五条","txt":"取得境内机构投资者资格的基金管理公司向特定对象募集资金或者接受特定对象财产委托投资于境外证券市场的，参照本办法执行。"},{"i":46,"n":"第四十六条","txt":"取得境内机构投资者资格的证券公司办理定向资产管理、专项资产管理业务，运用所管理的资金投资于境外证券市场的，参照本办法执行。"},{"i":47,"n":"第四十七条","txt":"本办法自2007年7月5日起施行。"}],"hegejingwaijigoutouzizheherenminbihegejingwaijigoub7f592":[{"i":1,"n":"第一条","txt":"为规范合格境外机构投资者和人民币合格境外机构投资者在境内证券期货市场的投资行为，促进证券期货市场稳定健康发展，根据有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称合格境外机构投资者和人民币合格境外机构投资者（以下统称合格境外投资者），是指经中国证券监督管理委员会（以下简称中国证监会）批准，使用来自境外的资金进行境内证券期货投资的境外机构投资者，包括境外基金管理公司、商业银行、保险公司、证券公司、期货公司、信托公司、政府投资机构、主权基金、养老基金、慈善基金、捐赠基金、国际组织等中国证监会认可的机构。 鼓励使用来自境外的人民币资金进行境内证券期货投资。"},{"i":3,"n":"第三条","txt":"合格境外投资者应当委托符合要求的境内机构作为托管人托管资产，依法委托境内证券公司、期货公司办理在境内的证券期货交易活动。"},{"i":4,"n":"第四条","txt":"合格境外投资者应当建立并实施有效的内部控制和合规管理制度，确保投资运作、资金管理等行为符合境内法律法规和其他有关规定。"},{"i":5,"n":"第五条","txt":"中国证监会、中国人民银行（以下简称人民银行）依法对合格境外投资者的境内证券期货投资实施监督管理，人民银行、国家外汇管理局（以下简称外汇局）依法对合格境外投资者境内银行账户、资金汇兑等实施监督管理。 合格境外投资者可参与的金融衍生品等交易品种和交易方式，由中国证监会商人民银行、外汇局同意后公布。"},{"i":6,"n":"第六条","txt":"申请合格境外投资者资格，应当具备下列条件： （一）财务稳健，资信良好，具备证券期货投资经验； （二）境内投资业务主要负责人员符合申请人所在境外国家或者地区有关从业资格的要求（如有）； （三）治理结构、内部控制和合规管理制度健全有效，按照规定指定督察员负责对申请人境内投资行为的合法合规性进行监督； （四）经营行为规范，近3年或者自成立以来未受到监管机构的重大处罚； （五）不存在对境内资本市场运行产生重大影响的情形。"},{"i":7,"n":"第七条","txt":"申请人应当通过托管人向中国证监会报送合格境外投资者资格申请文件。 中国证监会自受理申请文件之日起10个工作日内，对申请材料进行审核，并作出批准或者不予批准的决定。决定批准的，作出书面批复，并颁发经营证券期货业务许可证（以下简称许可证）；决定不予批准的，书面通知申请人。"},{"i":8,"n":"第八条","txt":"托管人首次开展合格境外投资者资产托管业务的，应当自签订托管协议之日起5个工作日内，报中国证监会备案。"},{"i":9,"n":"第九条","txt":"托管人应当履行下列职责： （一）安全保管合格境外投资者托管的全部资产； （二）办理合格境外投资者的有关交易清算、交收、结汇、售汇、收汇、付汇和人民币资金结算业务； （三）监督合格境外投资者的投资运作，发现其投资指令违法、违规的，及时向中国证监会、人民银行和外汇局报告； （四）根据中国证监会、人民银行和外汇局的要求，报送合格境外投资者的开销户信息、资金跨境收付信息、境内证券期货投资资产配置情况信息等相关业务报告和报表，并进行国际收支统计申报； （五）保存合格境外投资者的资金汇入、汇出、兑换、收汇、付汇和资金往来记录等相关资料，保存期限不少于20年； （六）中国证监会、人民银行和外汇局根据审慎监管原则规定的其他职责。"},{"i":10,"n":"第十条","txt":"托管人应当持续符合下列要求： （一）有专门的资产托管部门和符合托管业务需要的人员、系统、制度； （二）具有经营外汇业务和人民币业务的资格； （三）未发生影响托管业务的重大违法违规行为； （四）中国证监会、人民银行和外汇局根据审慎监管原则规定的其他要求。"},{"i":11,"n":"第十一条","txt":"托管人应当将其自有资产和受托资产严格分开，对受托资产实行分账托管。"},{"i":12,"n":"第十二条","txt":"合格境外投资者委托2个以上托管人的，应当指定1个主报告人，负责代其统一办理资格申请、重大事项报告、主体信息登记等事项。合格境外投资者应当在指定主报告人之日起5个工作日内，通过主报告人将所有托管人信息报中国证监会、外汇局备案。 合格境外投资者可以更换托管人。中国证监会、外汇局根据审慎监管原则可以要求合格境外投资者更换托管人。"},{"i":13,"n":"第十三条","txt":"合格境外投资者应当依法申请开立证券期货账户。 合格境外投资者进行证券期货交易，应当委托具有相应结算资格的机构结算。"},{"i":14,"n":"第十四条","txt":"合格境外投资者的投资本金及在境内的投资收益可以投资于符合规定的金融工具。 合格境外投资者投资银行间债券市场，参与境内外汇市场业务，应当根据人民银行、外汇局相关规定办理。"},{"i":15,"n":"第十五条","txt":"合格境外投资者开展境内证券投资，应当遵守中国证监会规定的证券投资比例限制和国家其他有关规定。"},{"i":16,"n":"第十六条","txt":"合格境外投资者履行信息披露义务时，应当依法合并计算其拥有的同一公司境内上市或者挂牌股票和境外上市外资股的权益，并遵守信息披露有关规则。 合格境外投资者应当按照信息披露规则合并披露一致行动人的相关证券投资信息。"},{"i":17,"n":"第十七条","txt":"证券公司、期货公司等机构保存合格境外投资者的委托记录、交易记录等资料的期限应当不少于20年。"},{"i":18,"n":"第十八条","txt":"合格境外投资者的境内证券期货投资活动，应当遵守证券期货交易场所、证券登记结算机构、证券期货市场监测监控机构的有关规定。"},{"i":19,"n":"第十九条","txt":"合格境外投资者应当在托管人处开立外汇账户和（或）人民币专用存款账户，收支范围应当符合人民银行、外汇局的有关规定。"},{"i":20,"n":"第二十条","txt":"合格境外投资者应当按照人民银行、外汇局相关规定汇入本金，以外汇形式汇入的本金应当是在中国外汇市场可挂牌交易的货币。 合格境外投资者可以按照人民银行、外汇局相关规定汇出资金。"},{"i":21,"n":"第二十一条","txt":"中国证监会、人民银行和外汇局依法可以要求合格境外投资者、托管人、证券公司、期货公司等机构提供合格境外投资者的有关资料，并进行必要的询问、检查。"},{"i":22,"n":"第二十二条","txt":"合格境外投资者有下列情形之一的，应当在相关情形发生之日起5个工作日内报中国证监会、人民银行和外汇局备案： （一）变更托管人； （二）控股股东、实际控制人变更； （三）涉及重大诉讼及其他重大事件； （四）在境外受到重大处罚； （五）中国证监会、人民银行和外汇局规定的其他情形。"},{"i":23,"n":"第二十三条","txt":"合格境外投资者有下列情形之一的，应当申请变更或者换领许可证： （一）许可证信息发生变更； （二）被其他机构吸收合并； （三）中国证监会、人民银行和外汇局规定的其他情形。 变更或者换领许可证期间，合格境外投资者可以继续进行证券期货交易，但中国证监会根据审慎监管原则认为需要暂停的除外。"},{"i":24,"n":"第二十四条","txt":"合格境外投资者有下列情形之一的，应当将许可证交还中国证监会，由中国证监会注销其业务许可： （一）机构解散、进入破产程序或者由接管人接管； （二）申请注销业务许可； （三）中国证监会、人民银行和外汇局认定的其他情形。"},{"i":25,"n":"第二十五条","txt":"合格境外投资者有下列情形之一的，中国证监会、人民银行和外汇局可以对其采取责令改正、监管谈话、出具警示函等监管措施；对直接负责的主管人员和其他直接责任人员，可以采取监管谈话、出具警示函、责令定期报告等监管措施： （一）未按规定开立账户； （二）未按规定开展境内证券期货投资； （三）未按规定履行信息披露义务； （四）未按规定有效实施内部控制和合规管理制度； （五）未按规定变更、换领或者交还许可证； （六）未按规定办理资金汇入、汇出、结汇或者收汇、付汇； （七）未按规定报送有关报告、材料或者相关内容存在虚假记载、误导性陈述或者重大遗漏； （八）不配合有关检查，拒绝、拖延提供有关资料； （九）违反本办法规定的其他行为。 合格境外投资者违反《中华人民共和国证券法》、《期货交易管理条例》、《中华人民共和国外汇管理条例》等法律、行政法规的，按照有关规定实施行政处罚。涉嫌犯罪的，依法将案件移送司法机关"},{"i":26,"n":"第二十六条","txt":"合格境外投资者在开展境内证券期货投资过程中发生重大违法违规行为的，中国证监会可以依法采取限制相关证券期货账户交易等措施。"},{"i":27,"n":"第二十七条","txt":"托管人未按照规定进行备案，未履行本办法第九条规定的职责，或者违反本办法第十条等规定的，中国证监会可以对其采取责令改正、监管谈话、出具警示函等监管措施；对直接负责的主管人员和其他直接责任人员，可以采取监管谈话、出具警示函、责令定期报告等监管措施。违反有关法律、行政法规的，按照有关规定实施行政处罚。涉嫌犯罪的，依法将案件移送司法机关追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"在香港特别行政区、澳门特别行政区设立的机构投资者到内地从事证券期货投资，在台湾地区设立的机构投资者到大陆从事证券期货投资，适用本办法。"},{"i":29,"n":"第二十九条","txt":"本办法自2020年11月1日起施行。2006年8月24日中国证监会、人民银行、外汇局公布的《合格境外机构投资者境内证券投资管理办法》和2013年3月1日中国证监会公布的《人民币合格境外机构投资者境内证券投资试点办法》同时废止。"}],"jingwaijiaoyizhehejingwaijingjijigoucongshijingnei15a022":[{"i":1,"n":"第一条","txt":"为了促进期货市场创新发展和对外开放，加强对境外交易者和境外经纪机构从事境内特定品种期货交易的管理，维护期货市场秩序，保护交易者合法权益，根据《期货交易管理条例》及有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"境外交易者、境外经纪机构从事我国境内特定品种期货交易及其相关业务活动，应当遵守本办法。 本办法所称境外交易者，是指从事期货交易并承担交易结果，在中华人民共和国境外依法成立的法人、其他经济组织，或者依法拥有境外公民身份的自然人。 本办法所称境外经纪机构，是指在中华人民共和国境外依法设立、具有所在国（地区）期货监管机构认可的可以接受交易者资金和交易指令并以自己名义为交易者进行期货交易资质的金融机构。 本办法所称境内特定品种由中国证券监督管理委员会（以下简称中国证监会）确定并公布。"},{"i":3,"n":"第三条","txt":"中国证监会及其派出机构依法对境外交易者和境外经纪机构从事境内特定品种期货交易实行监督管理。 期货交易所依据自律规则对境内特定品种期货交易及相关业务活动实行自律管理。 中国期货业协会依据自律规则对境内特定品种期货交易及相关业务活动实行行业自律管理。 中国期货市场监控中心有限责任公司依法对境内特定品种期货交易及相关业务活动实施监测监控。"},{"i":4,"n":"第四条","txt":"境外交易者和境外经纪机构应当遵守中华人民共和国法律法规和本办法，并履行反洗钱、反恐融资、反逃税等义务。"},{"i":5,"n":"第五条","txt":"境外交易者可以委托境内期货公司（以下简称期货公司)或者境外经纪机构参与境内特定品种期货交易。 经期货交易所批准，符合条件的境外交易者可以直接在期货交易所从事境内特定品种期货交易。 前款所述直接入场交易的境外交易者应当具备下列条件： （一）所在国（地区）具有完善的法律和监管制度； （二）财务稳健，资信良好，具备充足的流动资本； （三）具有健全的治理结构和完善的内部控制制度，经营行为规范； （四）期货交易所规定的其他条件。"},{"i":6,"n":"第六条","txt":"境外经纪机构在接受境外交易者委托后，可以委托期货公司进行境内特定品种期货交易。期货公司接受委托后，以自己的名义为该境外经纪机构进行交易。 经期货交易所批准，符合条件的境外经纪机构可以接受境外交易者委托，直接在期货交易所以自己的名义为境外交易者进行境内特定品种期货交易。 前款所述直接入场交易的境外经纪机构应当符合本办法第五条第三款的规定，且其所在国（地区）期货监管机构已与中国证监会签署监管合作谅解备忘录。"},{"i":7,"n":"第七条","txt":"境外经纪机构不得接受境内交易者和《期货交易管理条例》第二十六条规定的单位和个人的委托，为其进行境内期货交易。"},{"i":8,"n":"第八条","txt":"对直接入场交易的境外交易者和境外经纪机构，期货交易所应当规定其资格取得与终止的条件和程序，明确其权利和义务。"},{"i":9,"n":"第九条","txt":"境外交易者从事境内特定品种期货交易，应当遵守期货交易所的自律规则，遵守“买卖自愿、风险自担、盈亏自负”的原则，承担期货交易的履约责任和交易结果。"},{"i":10,"n":"第十条","txt":"境外交易者应当以真实合法身份办理开户，如实提供境外公民身份证明、境外法人资格或者其他经济组织资格的合法有效证明文件。境外交易者的身份证明文件及要求由中国期货市场监控中心有限责任公司另行规定。"},{"i":11,"n":"第十一条","txt":"境外经纪机构接受境外交易者委托进行境内特定品种期货交易的，应当按照《期货市场客户开户管理规定》和中国期货市场监控中心有限责任公司的业务规则，为境外交易者办理账户开立等手续，并为每个境外交易者单独申请交易编码，不得进行混码交易。 接受境外经纪机构委托的期货公司，应当按照中国期货市场监控中心有限责任公司的业务规则，为境外经纪机构办理前款所述手续提供必要的协助。 直接入场交易的境外交易者应当向期货交易所办理账户开立等手续并申请交易编码，期货交易所应当在其开始交易之前将有关材料报中国期货市场监控中心有限责任公司备案。"},{"i":12,"n":"第十二条","txt":"境内特定品种期货交易实行交易者适当性制度。期货交易所、期货公司和境外经纪机构应当执行交易者适当性制度。境外交易者应当遵守交易者适当性制度。"},{"i":13,"n":"第十三条","txt":"境外经纪机构接受境外交易者委托的，应当事先向境外交易者出示风险说明书，与境外交易者签订书面合同，不得未经境外交易者委托或者不按照境外交易者委托内容，擅自进行期货交易，不得隐瞒重要事项或者使用其他不正当手段诱骗境外交易者发出交易指令。"},{"i":14,"n":"第十四条","txt":"直接入场交易的境外经纪机构应当建立健全并严格执行业务管理规则、风险管理制度，遵守信息披露制度，保障境外交易者保证金的存管安全。"},{"i":15,"n":"第十五条","txt":"承担结算职能的期货交易所作为中央对手方，统一组织境内特定品种期货交易的结算。境外交易者、境外经纪机构应当根据期货交易所的规定委托具有结算资格的期货公司或者其他机构进行结算，并适用《期货交易管理条例》第二十九条、第三十四条、第三十五条、第三十七条对客户和期货公司的规定。 前款所称中央对手方，是指期货交易达成后介入期货交易双方，成为所有买方的卖方和所有卖方的买方，以净额方式结算，为期货交易提供集中履约保障的法人。"},{"i":16,"n":"第十六条","txt":"直接入场交易的境外交易者和境外经纪机构，以及委托期货公司进行境内特定品种期货交易的境外交易者和境外经纪机构，应当在境内开立符合条件的银行账户，并将其设定为期货结算账户。"},{"i":17,"n":"第十七条","txt":"境外交易者和境外经纪机构应当遵守中国证监会关于保证金安全存管的规定。 期货公司应当将向委托其结算的境外交易者和境外经纪机构收取的保证金存放在期货公司的保证金专用账户。期货公司应当将来源于境内和境外的保证金按币种分账户管理。 期货交易所、期货公司、本办法第十六条所指的境外交易者和境外经纪机构之间的境内账户资金划转，应当通过专用结算账户、保证金专用账户和期货结算账户进行。"},{"i":18,"n":"第十八条","txt":"境外交易者和境外经纪机构持仓达到期货交易所规定的持仓报告标准的，境外交易者和境外经纪机构应当向期货交易所报告。境外交易者未报告的，受托交易的期货公司、境外经纪机构应当向期货交易所报告。"},{"i":19,"n":"第十九条","txt":"保证金只能用于担保期货合约或者期权合约的履行，除法定情形外，严禁挪作他用。 境外交易者和境外经纪机构被接管、破产或者清算的，其保证金均应当优先用于履行在期货交易所未了结的期货合约或期权合约。"},{"i":20,"n":"第二十条","txt":"期货市场出现《期货交易所管理办法》第八十五条、第八十七条规定情形的，期货交易所可以按照对客户和会员的规定，对境外交易者和境外经纪机构采取措施。"},{"i":21,"n":"第二十一条","txt":"期货公司与境外交易者或者境外经纪机构发生期货业务纠纷的，可以提请中国期货业协会、期货交易所以及其他调解组织调解处理。"},{"i":22,"n":"第二十二条","txt":"期货公司应当在月度、年度报告中报送接受境外交易者和境外经纪机构委托进行境内特定品种期货交易的情况。 期货公司首席风险官应当负责对本公司境内特定品种期货交易相关业务活动进行监督和检查，并履行督促整改和报告等义务。"},{"i":23,"n":"第二十三条","txt":"中国证监会及其派出机构可以根据监管职责要求期货公司、境外交易者和境外经纪机构提供下列信息或者书面资料，并进行必要的询问和检查： （一）境外交易者和境外经纪机构的账户、所有子账户的最终受益人姓名（名称）、国籍、有效身份证件（号码）、联系方式及相关信息、资金来源等； （二）境外交易者和境外经纪机构的账户、所有子账户的指令下达人姓名、国籍、有效身份证件（号码）、联系方式及相关信息等； （三）境外交易者和境外经纪机构的账户、所有子账户资金划拨、使用的明细资料； （四）境外交易者和境外经纪机构的账户、所有子账户交易的明细资料； （五）中国证监会根据审慎监管原则要求的其他材料。"},{"i":24,"n":"第二十四条","txt":"发生下列重大情形之一的，期货公司应当在知情后5个工作日内或者按照规定向其住所地的中国证监会派出机构报告： （一）境外交易者或者境外经纪机构发生违规、被接管、破产或者其他风险事件； （二）发生涉及境外交易者或者境外经纪机构的期货纠纷、仲裁或者诉讼； （三）其他影响境外交易者或者境外经纪机构从事境内特定品种期货交易的情形。 期货公司的报告应当包括事件的起因、目前的状态、可能发生的后果以及应对方案或者措施等内容。"},{"i":25,"n":"第二十五条","txt":"期货公司及其从业人员违反本办法的，依照《期货交易管理条例》的有关规定，采取责令限期整改、监管谈话、责令更换有关责任人员等监管措施，并记入诚信档案。"},{"i":26,"n":"第二十六条","txt":"直接入场交易的境外交易者和境外经纪机构的交易结算软件，应当满足期货交易所风险管理以及中国证监会有关保证金安全存管监控规定的要求。不符合要求的，中国证监会有权要求直接入场交易的境外交易者和境外经纪机构予以改进或者更换。 中国证监会可以要求直接入场交易的境外交易者和境外经纪机构的交易软件、结算软件的供应商提供该软件的相关资料，供应商应当予以配合。中国证监会对供应商提供的相关资料负有保密义务。"},{"i":27,"n":"第二十七条","txt":"中国证监会及其派出机构可以根据监管职责对境外交易者或者境外经纪机构进行境内特定品种期货交易及相关业务活动进行定期或者不定期现场检查。"},{"i":28,"n":"第二十八条","txt":"期货交易所违反规定接纳直接入场交易的境外交易者或者境外经纪机构的，依照《期货交易管理条例》第六十五条的规定处罚、处分。 期货交易所允许直接入场交易的境外交易者或者境外经纪机构在保证金不足的情况下进行期货交易的，依照《期货交易管理条例》第六十六条的规定处罚、处分。"},{"i":29,"n":"第二十九条","txt":"境外经纪机构有《期货交易管理条例》第六十七条第一款第一项、第七项至第九项、第十一项、第十四项至第十六项所列行为之一的，依照《期货交易管理条例》第六十七条第一款规定处罚。 境外经纪机构有《期货交易管理条例》第六十八条第一款所列欺诈行为的，依照《期货交易管理条例》第六十八条第一款的规定处罚。"},{"i":30,"n":"第三十条","txt":"直接入场交易的境外交易者或者境外经纪机构的交易软件、结算软件供应商拒不配合中国证监会及其派出机构调查，或者未按照规定向中国证监会及其派出机构提供相关软件资料，或者提供的软件资料有虚假、重大遗漏的，依照《期货交易管理条例》第七十六条的规定处罚。"},{"i":31,"n":"第三十一条","txt":"期货交易所、期货公司、境外交易者或者境外经纪机构违法经营或者出现重大经营风险，严重危害中国期货市场秩序、损害交易者合法权益，依法应予以行政处罚的，依照《期货交易管理条例》进行处罚；涉嫌犯罪的，依法移送司法机关，追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"境外交易者或者境外经纪机构违反《期货交易管理条例》和中国证监会有关规定的，中国证监会依法进行查处。需要境外交易者或者境外经纪机构所在地监管机构协助的，中国证监会可以根据与其签署的双边或者多边监管合作谅解备忘录等跨境监管合作机制进行跨境监管合作。"},{"i":33,"n":"第三十三条","txt":"在中国证监会批准的其他期货交易场所从事境内特定品种期货交易及相关业务活动的，适用本办法。"},{"i":34,"n":"第三十四条","txt":"香港、澳门特别行政区和台湾地区设立的法人、其他经济组织，或者拥有香港、澳门特别行政区和台湾地区居民身份的自然人从事境内特定品种期货交易的，适用本办法。"},{"i":35,"n":"第三十五条","txt":"本办法自2015年8月1日起施行。"}],"jingwaizhengquanqihuojiaoyisuozhuhuadaibiaojigouguc5a9ff":[{"i":1,"n":"第一条","txt":"为规范境外交易所驻华代表机构的设立及其活动，根据《中华人民共和国证券法》《期货交易管理条例》《外国企业常驻代表机构登记管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称境外交易所，包括境外证券交易所、期货交易所、证券期货自动报价或者电子交易系统或者市场，以及中国证券监督管理委员会（以下简称中国证监会）认定的其他境外交易所。 本办法所称境外交易所驻华代表机构（以下简称代表处），是指境外交易所在中国境内依法设立并专门从事联络、调研等非营利性活动的常驻代表机构，以及中国证监会认定的其他代表机构。"},{"i":3,"n":"第三条","txt":"中国证监会根据审慎监管的原则，依法对代表处进行监管。中国证监会派出机构在中国证监会授权范围内对本辖区的代表处进行监管。 代表处自愿加入证券、期货行业组织，接受自律管理。"},{"i":4,"n":"第四条","txt":"境外交易所应当在代表处完成登记注册后5个工作日内向其所在地中国证监会派出机构提交下列备案材料，并对材料真实、准确与完整负责： （一）境外交易所出具的致中国证监会的备案申请书； （二）所在国家或者地区有关主管当局核发的、经中国驻该国使（领）馆认证的营业执照或者合法开业证明等复印件；中国缔结或者参加的国际条约另有规定的除外； （三）境外交易所章程、管理架构、股权结构图、业务范围、主要业务规则、管理制度、内控机制等说明以及董事会（理事会）成员、管理层人员名单及简介； （四）境外交易所提交备案材料之日起过往3年的年报； （五）境外交易所出具的首席代表授权书； （六）就拟任首席代表最近3年是否存在重大违法违规行为受到处罚情形的声明； （七）拟任首席代表的身份证明、简历、联系方式及家庭住址等信息； （八）由拟任首席代表签署的致中国证监会的承诺书； （九）代表处登记证复印件； （十）代表处基本信息，"},{"i":5,"n":"第五条","txt":"备案材料齐备的，代表处所在地中国证监会派出机构应当将备案材料及时报送中国证监会，中国证监会应当在5个工作日内对备案代表处的名称、变更、撤销及相关材料等信息予以公示；备案材料不齐备的，代表处所在地中国证监会派出机构应当要求境外交易所补充齐备。"},{"i":6,"n":"第六条","txt":"代表处主要负责人为首席代表。首席代表不得由境外交易所总部或者地区总部人员兼任，也不得在中国境内任何营利性机构任职。首席代表有兼职行为的，境外交易所应当更换首席代表。"},{"i":7,"n":"第七条","txt":"代表处变更名称，应当向其所在地中国证监会派出机构提交境外交易所出具的书面报告，说明更名原因，并提交代表处更名后的登记证及中国证监会要求的其他文件。境外交易所因控制股权发生变更、合并、重组、被接管等原因导致代表处更名，境外交易所应当按本办法第四条要求重新备案。 代表处变更首席代表，应当在市场监督管理部门办理变更登记手续后向其所在地中国证监会派出机构书面报告并提交本办法第四条（五）至（九）项规定的材料。 代表处变更办公场所，自变更之日起5个工作日内，应当向其所在地中国证监会派出机构书面报告新办公场所电话、传真、通信地址。"},{"i":8,"n":"第八条","txt":"代表处撤销，应当在启动撤销工作前20个工作日向其所在地中国证监会派出机构书面报告，撤销报告应当由境外交易所出具，并在市场监督管理部门办理注销登记后5个工作日内向其所在地中国证监会派出机构书面报告。 代表处撤销后，未了事宜由其境外交易所承担责任。"},{"i":9,"n":"第九条","txt":"代表处及其工作人员不得与法人或者自然人签订可能给代表处或者其境外交易所带来收入的协议或者合同，不得从事或者变相从事任何营利性活动，不得向境内单位或者个人提供交易直接接入服务，不得通过境外交易所会员等机构以任何形式向境内单位或者个人提供交易服务以及其他法律、法规规定的禁止性活动。"},{"i":10,"n":"第十条","txt":"代表处及其工作人员只可面向机构或者企业进行市场介绍。 市场介绍指代表处及其工作人员对机构或者企业举办的培训、会议、座谈等非营利性活动。代表处举办面向机构或者企业的市场介绍，应当在活动结束后5个工作日内将有关情况报送代表处所在地中国证监会派出机构。 代表处及其工作人员进行市场介绍时，不得涉及具体产品；不得介绍开户、交易方式、交易费用等具有交易导向的内容；不得提出或者接受买卖任何证券、期货合约和其他金融产品的要约。"},{"i":11,"n":"第十一条","txt":"代表处应当于每一年度结束之日起4个月内，向其所在地中国证监会派出机构报送上年度中文工作报告，工作报告包括但不限于其交易所上市交易的中国公司、中资会员的情况。 代表处应当在其境外交易所会计年度结束之日起4个月内向其所在地中国证监会派出机构报送其境外交易所上一年度年报。"},{"i":12,"n":"第十二条","txt":"境外交易所有下列情形之一的，代表处应当自事件发生之日起10个工作日内，向其所在地中国证监会派出机构提交中文书面报告： （一）章程、业务许可、名称、注册资本或者注册地址变更； （二）分立、合并或者其他重大并购重组活动； （三）董事长（理事长）、总经理、法定代表人或者主要负责人变动； （四）经营严重亏损或者财务严重困难； （五）所在国家或者地区的金融监管当局对其采取调查、处罚、纪律处分或者和解等措施； （六）对经营有重大影响的其他事项。"},{"i":13,"n":"第十三条","txt":"中国证监会或者其派出机构可以对代表处进行定期或者不定期现场或者非现场检查。 代表处违反本办法，中国证监会或者其派出机构可以对代表处的首席代表和其他直接责任人员采取责令整改、监管谈话、出具警示函等监管措施；情节严重的，中国证监会或者其派出机构可以对代表处的首席代表和其他直接责任人员采取证券期货市场禁入的措施。"},{"i":14,"n":"第十四条","txt":"境外交易所未经省、自治区、直辖市人民政府市场监督管理部门登记而在中国境内设立代表处或者从事代表处活动的，中国证监会派出机构通知当地市场监督管理部门依法予以处理。境外交易所在市场监督管理部门办理代表处登记注册后，未向其代表处所在地中国证监会派出机构备案或者逾期未提交备案材料，由中国证监会或者其派出机构责令改正；逾期不改正的，给予警告并处以3万元以下罚款。"},{"i":15,"n":"第十五条","txt":"代表处及其工作人员非法经营证券期货业务的，由中国证监会或者其派出机构按照《中华人民共和国证券法》《期货交易管理条例》等法律、法规进行处罚。 代表处及其工作人员违法从事证券期货业务以外营利性活动的，中国证监会派出机构通知市场监督管理等相关部门依法予以处理。"},{"i":16,"n":"第十六条","txt":"代表处登记注册后，代表处及其工作人员违反本办法规定，有下列行为之一的，由中国证监会或者其派出机构责令改正，给予警告并处以3万元以下罚款；情节严重的，由中国证监会取消备案： （一）提交虚假材料或者采取其他欺诈手段隐瞒真实情况，进行代表处备案的； （二）未按规定向中国证监会派出机构报送报告、资料或者报送的报告、资料隐瞒真实情况、弄虚作假的； （三）开展市场介绍未按规定报告的； （四）拒绝、阻碍中国证监会或者其派出机构检查、监管或者不如实提供文件、资料的； （五）其他违反法律、法规的行为。"},{"i":17,"n":"第十七条","txt":"中国证监会依据本办法相关规定，将代表处及其工作人员的违法违规失信行为纳入证券期货诚信档案数据库，依据相关规定予以公示，并通报境外监管当局。"},{"i":18,"n":"第十八条","txt":"本办法自公布之日起施行。香港特别行政区、澳门特别行政区的交易所在内地和台湾地区的交易所在大陆设立代表处，参照本办法办理。原《境外证券交易所驻华代表机构管理办法》（证监会令第44号）同时废止。 自本办法施行起12个月以内，已在境内设立办事机构或者从事代表处活动的境外交易所，应当向中国证监会相关派出机构进行备案。"}],"waishangtouziqihuogongsiguanlibanfa":[{"i":1,"n":"第一条","txt":"为适应期货市场对外开放需要，加强和完善对外商投资期货公司的监督管理，根据《中华人民共和国公司法》、《期货交易管理条例》有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称外商投资期货公司是指单一或有关联关系的多个境外股东直接持有或间接控制公司5%以上股权的期货公司。"},{"i":3,"n":"第三条","txt":"中国证券监督管理委员会（以下简称中国证监会）及其派出机构依法对外商投资期货公司实施监督管理。"},{"i":4,"n":"第四条","txt":"外商投资期货公司的名称、组织形式、注册资本、组织机构的设立及职责等，应当符合《中华人民共和国公司法》、《期货交易管理条例》、《期货公司监督管理办法》等法律、行政法规和中国证监会的有关规定。"},{"i":5,"n":"第五条","txt":"直接持有期货公司5%以上股权的境外股东，除应当符合《期货公司监督管理办法》第七条和第九条规定的条件外，还应当具备下列条件： （一）持续经营5年以上，近3年未受到所在国家或者地区监管机构或者行政、司法机关的重大处罚； （二）管理层具有良好的专业素质和管理能力； （三）具有健全的内部控制制度和风险管理体系； （四）具有良好的国际声誉和经营业绩，近3年业务规模、收入、利润居于国际前列，近3年长期信用均保持在高水平； （五）中国证监会规定的其他审慎性条件。 有关联关系的多个境外股东合计持有期货公司5%以上股权的，每个境外股东均应具备上款所列条件。"},{"i":6,"n":"第六条","txt":"除通过中国境内证券公司间接持有期货公司股权及中国证监会规定的其他情形外，境外投资者通过投资关系、协议或其他安排，实际控制期货公司5%以上股权的，应当转为直接持股。 单独或与关联方、一致行动人共同实际控制期货公司5%以上股权的境外投资者，应当具备本办法第五条规定的条件。"},{"i":7,"n":"第七条","txt":"境外股东应当以自由兑换货币出资。境外股东累计持有的（包括直接持有和间接控制）外商投资期货公司股权比例，应当符合国家关于期货业对外开放的安排。"},{"i":8,"n":"第八条","txt":"外商投资期货公司的董事、监事和高级管理人员应当具备中国证监会规定的任职条件。 外商投资期货公司的高级管理人员须在中国境内实地履职。"},{"i":9,"n":"第九条","txt":"境外机构设立外商投资期货公司，应当在公司登记机关登记注册，并向中国证监会提出申请。除应当向中国证监会提交《期货公司监督管理办法》规定的申请文件外，还应当提交下列文件： （一）申请前3年该境外机构经审计的财务报表； （二）该境外机构所在国家或者地区相关监管机构或者中国证监会认可的机构出具的关于该境外机构是否具备本办法第五条第一款第一项及《期货公司监督管理办法》第七条第五项、第九条第一款第二项规定条件的说明函； （三）该境外机构是否具备本办法第五条第一款第二项、第三项规定条件的说明材料； （四）该境外机构是否具备本办法第五条第一款第四项规定条件的证明文件； （五）由中国境内律师事务所出具的法律意见书； （六）中国证监会规定的其他申请文件。 境外股东变更股权属《期货公司监督管理办法》第十七条 规定情形的，应当向中国证监会提出申请，申请文件适用前款规定。"},{"i":10,"n":"第十条","txt":"获得中国证监会批准设立的外商投资期货公司，应当按国家外汇管理部门的规定办理相关业务登记手续，足额缴付出资或者提供约定的合作条件。"},{"i":11,"n":"第十一条","txt":"外商投资期货公司申请颁发或换发《经营证券期货业务许可证》，应当向中国证监会提交下列文件： （一）营业执照副本复印件； （二）公司章程； （三）由中国境内具有期货相关业务资格的会计师事务所出具的验资报告； （四）董事、监事、高级管理人员和主要业务人员的名单，符合任职条件证明文件及期货从业资格证明文件； （五）高级管理人员在中国境内实地履职的说明文件； （六）内部控制制度和风险管理制度文本； （七）营业场所和业务设施情况说明书； （八）中国证监会要求的其他文件。 申请换发《经营证券期货业务许可证》的，还应当提交公司原有《经营证券期货业务许可证》。 未取得中国证监会颁发的《经营证券期货业务许可证》，外商投资期货公司不得经营期货业务。"},{"i":12,"n":"第十二条","txt":"外商投资期货公司合并或者分立后设立的外商投资期货公司，其股权变动应当符合本办法的规定。"},{"i":13,"n":"第十三条","txt":"境外投资者依法通过证券交易所的证券交易持有或者通过协议、其他安排与他人共同持有上市期货公司股份达到5%以上的，应当具备本办法第五条规定的条件，并遵守法律、行政法规和中国证监会关于上市公司收购、期货公司变更审批的有关规定。"},{"i":14,"n":"第十四条","txt":"外商投资期货公司及其境外股东向中国证监会提交的申请文件，以及向中国证监会及其派出机构报送的文件、资料，必须使用中文。境外股东及其所在国家或者地区相关监管机构或者中国证监会认可的机构出具的文件、资料，以及外商投资期货公司股东会、董事会、监事会、总经理办公会相关文件、资料使用外文的，应当附有与原文内容一致的中文译本。 申请人提交的文件及报送的材料，不能充分说明申请人状况的，中国证监会可以要求申请人作出补充说明。"},{"i":15,"n":"第十五条","txt":"外商投资期货公司交易、结算、风险控制等信息系统的核心服务器以及记录、存储客户信息的数据设备，应当设置在中国境内。 在符合法律、行政法规和中国证监会有关规定的前提下，外商投资期货公司可以利用境外股东的资源和技术，提升信息系统的效率和安全水平。"},{"i":16,"n":"第十六条","txt":"外商投资期货公司及其股东、董事、监事、高级管理人员违反本办法规定的，中国证监会及其派出机构可以依照《期货交易管理条例》、《期货公司监督管理办法》、《期货公司董事、监事和高级管理人员任职资格管理办法》等相关规定采取行政监管措施或予以处罚。"},{"i":17,"n":"第十七条","txt":"香港特别行政区、澳门特别行政区和台湾地区的投资者投资期货公司的，参照适用本办法。国家另有规定的，从其规定。"},{"i":18,"n":"第十八条","txt":"外商投资期货公司的设立、变更、终止、业务活动及监督管理事项，本办法未作规定的，适用中国证监会的其他有关规定。"},{"i":19,"n":"第十九条","txt":"本办法自公布之日起施行。"}],"waishangtouzizhengquangongsiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了适应证券市场对外开放的需要，加强和完善对外商投资证券公司的监督管理，明确外商投资证券公司的设立条件和程序，根据《中华人民共和国公司法》（以下简称公司法）和《中华人民共和国证券法》（以下简称证券法）有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称外商投资证券公司是指： （一）境外股东与境内股东依法共同出资设立的证券公司； （二）境外投资者依法受让、认购内资证券公司股权，内资证券公司依法变更的证券公司； （三）内资证券公司股东的实际控制人变更为境外投资者，内资证券公司依法变更的证券公司。"},{"i":3,"n":"第三条","txt":"中国证券监督管理委员会（以下简称中国证监会）负责对外商投资证券公司的审批和监督管理。"},{"i":4,"n":"第四条","txt":"外商投资证券公司的名称、组织形式、注册资本、业务范围、组织机构的设立及职责以及股东、董事、监事、高级管理人员等，应当符合公司法、证券法等法律、法规和中国证监会的有关规定。"},{"i":5,"n":"第五条","txt":"设立外商投资证券公司除应当符合公司法、证券法、《证券公司监督管理条例》和经国务院批准的中国证监会规定的证券公司设立条件外，还应当符合下列条件： （一）境外股东具备本办法规定的资格条件，其出资比例、出资方式符合本办法的规定； （二）初始业务范围与控股股东或者第一大股东的经营证券业务经验相匹配； （三）中国证监会规定的其他审慎性条件。"},{"i":6,"n":"第六条","txt":"外商投资证券公司的境外股东，应当具备下列条件： （一）所在国家或者地区具有完善的证券法律和监管制度，相关金融监管机构已与中国证监会或者中国证监会认可的机构签定证券监管合作谅解备忘录，并保持着有效的监管合作关系； （二）为在所在国家或者地区合法成立的金融机构，近3年各项财务指标符合所在国家或者地区法律的规定和监管机构的要求； （三）持续经营证券业务5年以上，近3年未受到所在国家或者地区监管机构或者行政、司法机关的重大处罚，无因涉嫌重大违法违规正受到有关机关调查的情形； （四）具有完善的内部控制制度； （五）具有良好的国际声誉和经营业绩，近3年业务规模、收入、利润居于国际前列，近3年长期信用均保持在高水平； （六）中国证监会规定的其他审慎性条件。"},{"i":7,"n":"第七条","txt":"境外股东应当以自由兑换货币出资。 境外股东累计持有的（包括直接持有和间接控制）外商投资证券公司股权比例，应当符合国家关于证券业对外开放的安排。"},{"i":8,"n":"第八条","txt":"申请设立外商投资证券公司，应当由全体股东共同指定的代表或者委托的代理人向中国证监会提交下列文件： （一）境内外股东的法定代表人或者授权代表共同签署的申请表； （二）关于设立外商投资证券公司的合同及章程草案； （三）外商投资证券公司拟任董事长、总经理、合规负责人简历； （四）股东的营业执照或者注册证书、证券业务资格证书复印件； （五）申请前3年境内外股东经审计的财务报表； （六）境外股东所在国家或者地区相关监管机构或者中国证监会认可的境外机构出具的关于该境外股东是否具备本办法第六条第（二）项、第（三）项规定的条件的说明函； （七）境外股东具有良好的国际声誉和经营业绩，近3年业务规模、收入、利润居于国际前列以及近3年长期信用情况的证明文件； （八）由中国境内律师事务所出具的法律意见书； （九）中国证监会要求的其他文件。"},{"i":9,"n":"第九条","txt":"中国证监会依照有关法律、行政法规和本办法对第八条规定的申请文件进行审查，并在规定期限内作出是否批准的决定，书面通知申请人。不予批准的，书面说明理由。"},{"i":10,"n":"第十条","txt":"股东应当自中国证监会的批准文件签发之日起6个月内足额缴付出资或者提供约定的合作条件，选举董事、监事，聘任高级管理人员，并向公司登记机关申请设立登记，领取营业执照。"},{"i":11,"n":"第十一条","txt":"外商投资证券公司应当自营业执照签发之日起15个工作日内，向中国证监会提交下列文件，申请经营证券业务许可证： （一）营业执照副本复印件； （二）公司章程； （三）由中国境内符合证券法规定的会计师事务所出具的验资报告； （四）董事、监事、高级管理人员和主要业务人员的名单以及符合规定的说明； （五）内部控制制度文本； （六）营业场所和业务设施情况说明书； （七）中国证监会要求的其他文件。"},{"i":12,"n":"第十二条","txt":"中国证监会依照有关法律、行政法规和本办法对第十一条规定的申请文件进行审查，并自接到符合要求的申请文件之日起15个工作日内作出决定。对符合规定条件的，颁发经营证券业务许可证；对不符合规定条件的，不予颁发，并书面说明理由。"},{"i":13,"n":"第十三条","txt":"未取得中国证监会颁发的经营证券业务许可证，外商投资证券公司不得开业，不得经营证券业务。"},{"i":14,"n":"第十四条","txt":"内资证券公司申请变更为外商投资证券公司的，应当具备本办法第五条规定的条件。 收购或者参股内资证券公司的境外股东应当具备本办法第六条规定的条件，其收购的股权比例或者出资比例应当符合本办法第七条的规定。 内资证券公司股东的实际控制人变更为境外投资者，应当具备本办法第六条规定的条件，其间接控制的证券公司股权比例应当符合本办法第七条的规定。不具备条件或者间接控制证券公司股权比例不符合规定的，应当在3个月内完成规范整改。"},{"i":15,"n":"第十五条","txt":"内资证券公司申请变更为外商投资证券公司，应当向中国证监会提交下列文件： （一）法定代表人签署的申请表； （二）股东（大）会关于变更为外商投资证券公司的决议； （三）公司章程修改草案； （四）股权转让协议或者出资协议（股份认购协议）； （五）拟在该证券公司任职的境外投资者委派人员的名单、简历以及符合规定的说明； （六）境外股东的营业执照或者注册证书、相关业务资格证书复印件； （七）申请前3年境外股东经审计的财务报表； （八）境外股东所在国家或者地区相关监管机构或者中国证监会认可的境外机构出具的关于该境外股东是否具备本办法第六条第（二）项、第（三）项规定条件的说明函； （九）境外股东具有良好的国际声誉和经营业绩，近3年业务规模、收入、利润居于国际前列以及近3年长期信用情况的证明文件； （十）由中国境内律师事务所出具的法律意见书； （十一）中国证监会要求的其他文件。"},{"i":16,"n":"第十六条","txt":"中国证监会依照有关法律、行政法规和本办法对第十五条规定的申请文件进行审查，并在规定期限内作出是否批准的决定，书面通知申请人。不予批准的，书面说明理由。"},{"i":17,"n":"第十七条","txt":"获准变更的证券公司，应当自中国证监会的批准文件签发之日起6个月内，办理股权转让或者增资事宜，向公司登记机关申请变更登记，换领营业执照。"},{"i":18,"n":"第十八条","txt":"获准变更的证券公司应当自变更登记之日起15个工作日内，向中国证监会提交下列文件，申请换发经营证券业务许可证： （一）营业执照副本复印件； （二）外商投资证券公司章程； （三）公司原有经营证券业务许可证及其副本； （四）由中国境内符合证券法规定的会计师事务所出具的验资报告； （五）中国证监会要求的其他文件。"},{"i":19,"n":"第十九条","txt":"中国证监会依照有关法律、行政法规和本办法对第十八条规定的申请文件进行审查，并自接到符合要求的申请文件之日起15个工作日内作出决定。对符合规定条件的，换发经营证券业务许可证；对不符合规定条件的，不予换发，并书面说明理由。"},{"i":20,"n":"第二十条","txt":"外商投资证券公司合并或者外商投资证券公司与内资证券公司合并后新设或者存续的证券公司，应当具备本办法规定的外商投资证券公司的设立条件；其境外股东持股比例应当符合本办法的规定。 外商投资证券公司分立后设立的证券公司，股东中有境外股东的，其境外股东持股比例应当符合本办法的规定。"},{"i":21,"n":"第二十一条","txt":"境外投资者可以依法通过证券交易所的证券交易持有上市内资证券公司股份，或者与上市内资证券公司建立战略合作关系并经中国证监会批准持有上市内资证券公司股份。 境外投资者依法通过证券交易所的证券交易持有或者通过协议、其他安排与他人共同持有上市内资证券公司5%以上股份的，应当符合本办法第六条规定的条件，并遵守证券法和中国证监会关于上市公司收购和证券公司变更审批的有关规定。"},{"i":22,"n":"第二十二条","txt":"按照本办法规定提交中国证监会的申请文件及报送中国证监会的资料，必须使用中文。境外股东及其所在国家或者地区相关监管机构或者中国证监会认可的境外机构出具的文件、资料使用外文的，应当附有与原文内容一致的中文译本。 申请人提交的文件及报送的材料，不能充分说明申请人的状况的，中国证监会可以要求申请人作出补充说明。"},{"i":23,"n":"第二十三条","txt":"外商投资证券公司涉及国家安全审查的，按照国家有关规定办理。"},{"i":24,"n":"第二十四条","txt":"香港特别行政区、澳门特别行政区和台湾地区的投资者投资证券公司的，参照适用本办法。国家另有规定的，从其规定。"},{"i":25,"n":"第二十五条","txt":"外商投资证券公司的设立、变更、终止、业务活动及监督管理事项，本办法未作规定的，适用中国证监会的其他有关规定。"},{"i":26,"n":"第二十六条","txt":"本办法自公布之日起施行。《外资参股证券公司设立规则》同时废止。"}],"cuntuopingzhengfaxingyujiaoyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范存托凭证发行和交易行为，保护投资者合法权益，维护证券市场秩序，根据《中华人民共和国证券法》（以下简称《证券法》）、《中华人民共和国证券投资基金法》、《关于开展创新企业境内发行股票或存托凭证试点的若干意见》（以下简称《若干意见》）以及相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称存托凭证是指由存托人签发、以境外证券为基础在中国境内发行、代表境外基础证券权益的证券。 存托凭证的发行和交易，适用《证券法》《若干意见》、本办法以及中国证监会的其他规定。存托凭证的境外基础证券发行人应当参与存托凭证发行，依法履行发行人、上市公司的义务，承担相应的法律责任。"},{"i":3,"n":"第三条","txt":"境外基础证券发行人的股权结构、公司治理、运行规范等事项适用境外注册地公司法等法律法规规定的，应当保障对中国境内投资者权益的保护总体上不低于中国法律、行政法规以及中国证监会规定的要求，并保障存托凭证持有人实际享有的权益与境外基础证券持有人的权益相当，不得存在跨境歧视。"},{"i":4,"n":"第四条","txt":"中国证监会依照上市公司监管的相关规定，对发行存托凭证的境外基础证券发行人进行持续监督管理。法律、行政法规或者中国证监会另有规定的除外。 证券交易所依据章程、协议和业务规则，对存托凭证上市、交易活动、境外基础证券发行人及其他信息披露义务人的信息披露行为等进行自律监管。"},{"i":5,"n":"第五条","txt":"公开发行以股票为基础证券的存托凭证的，境外基础证券发行人应当符合下列条件： （一）《证券法》第十三条第（一）项至第（三）项关于股票公开发行的基本条件； （二）为依法设立且持续经营三年以上的公司，公司的主要资产不存在重大权属纠纷； （三）最近三年内实际控制人未发生变更，且控股股东和受控股股东、实际控制人支配的股东持有的境外基础证券发行人股份不存在重大权属纠纷； （四）境外基础证券发行人及其控股股东、实际控制人最近三年内不存在损害投资者合法权益和社会公共利益的重大违法行为； （五）会计基础工作规范、内部控制制度健全； （六）董事、监事和高级管理人员应当信誉良好，符合公司注册地法律规定的任职要求，近期无重大违法失信记录； （七）中国证监会规定的其他条件。"},{"i":6,"n":"第六条","txt":"公开发行以股票为基础证券的存托凭证的，境外基础证券发行人应当按照中国证监会规定的格式和内容，向中国证监会报送发行申请文件。"},{"i":7,"n":"第七条","txt":"申请公开发行存托凭证的，境外基础证券发行人应当依照《证券法》《若干意见》以及中国证监会规定，报请中国证监会核准。 中国证监会发行审核委员会依照《证券法》第二十三条以及中国证监会规定，审核存托凭证发行申请。 仅面向符合适当性管理要求的合格投资者公开发行存托凭证的，可以简化核准程序，具体程序由中国证监会另行规定。"},{"i":8,"n":"第八条","txt":"申请存托凭证公开发行并上市的，境外基础证券发行人应当依照《证券法》第十一条、第四十九条的规定，聘请具有保荐资格的机构担任保荐人。保荐人应当依照法律、行政法规以及中国证监会规定尽职履行存托凭证发行上市推荐和持续督导职责。 公开发行存托凭证的，应当依照《证券法》第二十八条至第三十六条的规定，由证券公司承销，但投资者购买以非新增证券为基础证券的存托凭证以及中国证监会规定无需由证券公司承销的其他情形除外。"},{"i":9,"n":"第九条","txt":"存托凭证在中国境内首次公开发行并上市后，拟发行以境外基础证券发行人新增证券为基础证券的存托凭证的，适用《证券法》《若干意见》以及中国证监会关于上市公司证券发行的规定。"},{"i":10,"n":"第十条","txt":"依法公开发行的存托凭证应当在中国境内证券交易所上市交易。境外基础证券发行人申请存托凭证上市的，应当符合证券交易所业务规则规定的上市条件，并按照证券交易所的规定提出上市申请，证券交易所审核同意后，双方签订上市协议。 证券交易所应当依据《证券法》《若干意见》以及中国证监会规定制定存托凭证上市的相关业务规则。"},{"i":11,"n":"第十一条","txt":"存托凭证的交易应当遵守法律、行政法规、中国证监会规定以及证券交易所业务规则的规定。 存托凭证的交易可以按照有关规定采取做市商交易方式。 证券交易所应当按照《证券法》第一百一十五条规定，对存托凭证交易实行实时监控，并可以根据需要，对出现重大异常交易情况的证券账户限制交易。"},{"i":12,"n":"第十二条","txt":"境外基础证券发行人的股东、实际控制人、董事、监事、高级管理人员和存托凭证的其他投资者在中国境内减持其持有的存托凭证的，应当遵守法律、行政法规、中国证监会规定以及证券交易所业务规则的规定。"},{"i":13,"n":"第十三条","txt":"境外基础证券发行人的收购及相关股份权益变动活动应当遵守法律、行政法规以及中国证监会规定。"},{"i":14,"n":"第十四条","txt":"境外基础证券发行人实施重大资产重组、发行存托凭证购买资产的，应当符合法律、行政法规以及中国证监会规定。境外基础证券发行人不得通过发行存托凭证在中国境内重组上市。"},{"i":15,"n":"第十五条","txt":"存托凭证应当在中国证券登记结算有限责任公司集中登记、存管和结算。 中国证券登记结算有限责任公司应当依据《证券法》《若干意见》以及中国证监会规定制定存托凭证登记结算业务规则。"},{"i":16,"n":"第十六条","txt":"境外基础证券发行人及其控股股东、实际控制人等信息披露义务人应当依照《证券法》《若干意见》、中国证监会规定以及证券交易所业务规则，及时、公平地履行信息披露义务，所披露的信息必须真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 境外基础证券发行人的董事、监事、高级管理人员应当忠实、勤勉地履行职责，保证境外基础证券发行人所披露的信息真实、准确、完整。 证券交易所对境外基础证券发行人及其他信息披露义务人披露信息进行监督，督促其依法及时、准确地披露信息。"},{"i":17,"n":"第十七条","txt":"境外基础证券发行人应当按照中国证监会、证券交易所的规定编制并披露招股说明书、上市公告书，披露存托协议、托管协议等文件。 境外基础证券发行人应当在招股说明书中，充分披露境外注册地公司法律制度及其公司章程或者章程性文件的主要规定与《中华人民共和国公司法》等法律制度的主要差异，以及该差异对存托凭证在中国境内发行、上市和对投资者保护的影响。 境外基础证券发行人具有股东投票权差异、企业协议控制架构或者类似特殊安排的，应当在招股说明书等公开发行文件显要位置充分、详细披露相关情况特别是风险、公司治理等信息，并以专章说明依法落实保护投资者合法权益规定的各项措施。 境外基础证券发行人的董事、高级管理人员应当对招股说明书签署书面确认意见。"},{"i":18,"n":"第十八条","txt":"境外基础证券发行人应当按照《证券法》《若干意见》、中国证监会规定以及证券交易所业务规则，按时披露定期报告，并及时就可能对基础证券、存托凭证及其衍生品种交易价格产生较大影响的重大事件披露临时报告。"},{"i":19,"n":"第十九条","txt":"境外基础证券发行人应当按照中国证监会规定的内容和格式要求，编制并披露定期报告。 境外基础证券发行人具有股东投票权差异、企业协议控制架构或者类似特殊安排的，应当在定期报告中披露相关情形及其对中国境内投资者带来的重大影响和风险。 境外基础证券发行人的董事、高级管理人员应当对定期报告签署书面确认意见。"},{"i":20,"n":"第二十条","txt":"发生《证券法》第六十七条以及《上市公司信息披露管理办法》第三十条规定的重大事件，投资者尚未得知时，境外基础证券发行人应当立即披露，说明事件的起因、目前的状态和可能产生的法律后果。 持有或者通过持有境内外存托凭证而间接持有境外基础证券发行人发行的股份合计达到百分之五以上的投资者，属于《证券法》第六十七条第二款第（八）项以及《上市公司信息披露管理办法》第三十条第二款第（八）项规定的持有公司百分之五以上股份的股东。 《上市公司信息披露管理办法》第三十条第二款第（十四）项规定的任一股东所持公司百分之五以上股份，包括持有或者通过持有境内外存托凭证而间接持有境外基础证券发行人发行的股份合计达到百分之五。 《上市公司信息披露管理办法》第三十条第二款第（十五）项规定的主要资产包括境外基础证券发行人境内实体运营企业的主要资产。"},{"i":21,"n":"第二十一条","txt":"发生以下情形之一的，境外基础证券发行人应当及时进行披露： （一）存托人、托管人发生变化； （二）存托的基础财产发生被质押、挪用、司法冻结或者发生其他权属变化； （三）对存托协议作出重大修改； （四）对托管协议作出重大修改； （五）对股东投票权差异、企业协议控制架构或者类似特殊安排作出重大调整； （六）中国证监会规定的其他情形。"},{"i":22,"n":"第二十二条","txt":"境外基础证券发行人及其控股股东、实际控制人等信息披露义务人应当保证其在境外市场披露的信息同步在境内市场披露。"},{"i":23,"n":"第二十三条","txt":"中国证监会、证券交易所对证券已在境外上市的基础证券发行人及其控股股东、实际控制人等信息披露义务人，可以根据境外上市地的监管水平以及境外基础证券发行人公司治理、信息披露等合规运作情况，对其信息披露事项作出具体规定。 除前款规定外，境外基础证券发行人及其控股股东、实际控制人等信息披露义务人有其他需要免予披露或者暂缓披露相关信息特殊情况的，可以根据中国证监会规定以及证券交易所业务规则免予披露或者暂缓披露相关信息，但应当说明原因，并聘请律师事务所就上述事项出具法律意见。 免予披露或者暂缓披露相关信息的原因和律师事务所出具的法律意见应当及时披露。"},{"i":24,"n":"第二十四条","txt":"境外基础证券发行人或者其他信息披露义务人向中国证监会、证券交易所提供的文件或者信息披露文件应当使用中文，文件内容应当与其在境外市场提供的文件或者所披露的文件的内容一致。上述文件内容不一致时，以中文文件为准。"},{"i":25,"n":"第二十五条","txt":"境外基础证券发行人应当在中国境内设立证券事务机构，聘任熟悉境内信息披露规定和要求的信息披露境内代表，负责存托凭证上市期间的信息披露与监管联络事宜。"},{"i":26,"n":"第二十六条","txt":"下列机构可以依法担任存托人： （一）中国证券登记结算有限责任公司及其子公司； （二）经国务院银行业监督管理机构批准的商业银行； （三）证券公司。 担任存托人的机构应当符合下列条件： （一）组织机构健全，内部控制规范，风险管理有效； （二）财务状况良好，净资产或者资本净额符合规定； （三）信誉良好，最近三年内无重大违法行为； （四）拥有与开展存托业务相适应的从业人员、机构配置和业务设施； （五）法律、行政法规和规章规定的其他条件。"},{"i":27,"n":"第二十七条","txt":"存托人应当承担以下职责： （一）与境外基础证券发行人签署存托协议，并根据存托协议约定协助完成存托凭证的发行上市； （二）安排存放存托凭证基础财产，可以委托具有相应业务资质、能力和良好信誉的托管人管理存托凭证基础财产，并与其签订托管协议，督促其履行基础财产的托管职责。存托凭证基础财产因托管人过错受到损害的，存托人承担连带赔偿责任； （三）建立并维护存托凭证持有人名册； （四）办理存托凭证的签发与注销； （五）按照中国证监会规定和存托协议约定，向存托凭证持有人发送通知等文件； （六）按照存托协议约定，向存托凭证持有人派发红利、股息等权益，根据存托凭证持有人意愿行使表决权等权利； （七）境外基础证券发行人股东大会审议有关存托凭证持有人权利义务的议案时，存托人应当参加股东大会并为存托凭证持有人权益行使表决权； （八）中国证监会规定和存托协议约定的其他职责。"},{"i":28,"n":"第二十八条","txt":"境外基础证券发行人、存托人和存托凭证持有人通过存托协议明确存托凭证所代表权益和各方权利义务。投资者持有存托凭证即成为存托协议当事人，视为其同意并遵守存托协议约定。 存托协议应当符合法律、行政法规以及中国证监会规定，并包括以下条款： （一）境外基础证券发行人、存托人的名称、注册地、成立依据的法律和主要经营场所； （二）基础证券的种类； （三）发行存托凭证的数量安排； （四）存托凭证的签发、注销等安排； （五）基础财产的存放和托管安排； （六）境外基础证券发行人的权利和义务； （七）存托人的权利和义务； （八）存托凭证持有人的权利和义务； （九）基础证券涉及的分红权、表决权等相应权利的具体行使方式和程序； （十）存托凭证持有人的保护机制； （十一）存托凭证涉及收费标准、收费对象和税费处理； （十二）约定事项的变更方式； （十三）存托凭证终止上市的安排； （十四）违约责任； （十五）解决争议"},{"i":29,"n":"第二十九条","txt":"存托人可以委托境外金融机构担任托管人。存托人委托托管人的，应当在存托协议中明确基础财产由托管人托管。托管人应当承担下列职责： （一）托管基础财产； （二）按照托管协议约定，协助办理分红派息、投票等相关事项； （三）向存托人提供基础证券的市场信息； （四）中国证监会规定和托管协议约定的其他职责。"},{"i":30,"n":"第三十条","txt":"存托人与托管人签订的托管协议，应当包括下列条款： （一）协议当事人的名称、注册地和主要经营场所； （二）基础证券种类和数量； （三）存托人指令的发送、确认和执行的程序； （四）基础财产不得作为托管人破产财产或者清算财产，及相关资产隔离措施； （五）托管人的报酬计算方法与支付方式； （六）基础财产托管及解除托管的程序； （七）约定事项的变更方式； （八）违约责任； （九）解决争议的方法； （十）其他重要事项。 境外基础证券发行人应当向中国证监会提交存托人与托管人签署的托管协议，作为其发行申请文件。托管协议修改的，存托人应当及时告知境外基础证券发行人，并由境外基础证券发行人向中国证监会报告。"},{"i":31,"n":"第三十一条","txt":"存托人、托管人应当忠实、勤勉地履行各项职责和义务，不得损害存托凭证持有人的合法权益。 存托人行使境外基础证券相应权利，应当按照存托协议约定的方式事先征求存托凭证持有人的意愿并按其意愿办理，不得擅自行使相应权利或者处分相应存托凭证基础财产。"},{"i":32,"n":"第三十二条","txt":"存托人应当为存托凭证基础财产单独立户，将存托凭证基础财产与其自有财产有效隔离、分别管理、分别记账，不得将存托凭证基础财产归入其自有财产，不得侵占、挪用存托凭证基础财产。"},{"i":33,"n":"第三十三条","txt":"存托人不得买卖其签发的存托凭证，不得兼任其履行存托职责的存托凭证的保荐人。"},{"i":34,"n":"第三十四条","txt":"向投资者销售存托凭证或者提供相关服务的机构，应当遵守中国证监会关于投资者适当性管理的规定。 证券交易所应当在业务规则中明确存托凭证投资者适当性管理的相关事项。"},{"i":35,"n":"第三十五条","txt":"境外基础证券发行人应当确保存托凭证持有人实际享有的资产收益、参与重大决策、剩余财产分配等权益与境外基础证券持有人权益相当。境外基础证券发行人不得作出任何损害存托凭证持有人合法权益的行为。 法律、行政法规以及中国证监会规定对投资者保护有强制性规定的，应当适用其规定。"},{"i":36,"n":"第三十六条","txt":"境外基础证券发行人、存托人应当按照存托协议约定，采用安全、经济、便捷的网络或者其他方式为存托凭证持有人行使权利提供便利。"},{"i":37,"n":"第三十七条","txt":"中证中小投资者服务中心有限责任公司可以购买最小交易份额的存托凭证，依法行使存托凭证持有人的各项权利。 中证中小投资者服务中心有限责任公司可以接受存托凭证持有人的委托，代为行使存托凭证持有人的各项权利。 中证中小投资者服务中心有限责任公司可以支持受损害的存托凭证持有人依法向人民法院提起民事诉讼。"},{"i":38,"n":"第三十八条","txt":"境外基础证券发行人与其境内实体运营企业之间的关系安排，不得损害存托凭证持有人等投资者的合法权益。"},{"i":39,"n":"第三十九条","txt":"境外基础证券发行人具有股东投票权差异等特殊架构的，其持有特别投票权的股东应当按照所适用的法律以及公司章程行使权利，不得滥用特别投票权，不得损害存托凭证持有人等投资者的合法权益。 出现前款情形，损害存托凭证持有人等投资者合法权益的，境外基础证券发行人及特别投票权股东应当改正，并依法承担对投资者的损害赔偿责任。"},{"i":40,"n":"第四十条","txt":"存托凭证暂停、终止上市的情形和程序，由证券交易所业务规则规定。 存托凭证出现终止上市情形的，存托人应当根据存托协议的约定，为存托凭证持有人的权利行使提供必要保障。 存托凭证终止上市的，存托人应当根据存托协议的约定卖出基础证券，并将卖出所得扣除税费后及时分配给存托凭证持有人。基础证券无法卖出的，境外基础证券发行人应当在存托协议中作出合理安排，保障存托凭证持有人的合法权益。"},{"i":41,"n":"第四十一条","txt":"存托凭证持有人与境外基础证券发行人、存托人、证券服务机构等主体发生纠纷的，可以向中证中小投资者服务中心有限责任公司及其他依法设立的调解组织申请调解。"},{"i":42,"n":"第四十二条","txt":"投资者通过证券投资基金投资存托凭证的，基金管理人应当制定严格的投资决策流程和风险管理制度，做好制度、业务流程、技术系统等方面准备工作。 基金管理人应当根据审慎原则合理控制基金投资存托凭证的比例，在基金合同、招募说明书中明确投资存托凭证的比例、策略等，并充分揭示风险。 基金托管人应当加强对基金投资存托凭证的监督，切实保护基金份额持有人的合法权益。"},{"i":43,"n":"第四十三条","txt":"已经获得中国证监会核准或者准予注册的公开募集证券投资基金投资存托凭证，应当遵守以下规定： （一）基金合同已明确约定基金可投资境内上市交易的股票的，基金管理人可以投资存托凭证； （二）基金合同没有明确约定基金可投资境内上市交易的股票的，如果投资存托凭证，基金管理人应当召开基金份额持有人大会进行表决。 公开募集证券投资基金投资存托凭证的比例限制、估值核算、信息披露等依照境内上市交易的股票执行。"},{"i":44,"n":"第四十四条","txt":"合格境外机构投资者和人民币合格境外机构投资者投资存托凭证的比例限制按照有关管理规定执行,计算基础为境内上市的存托凭证。"},{"i":45,"n":"第四十五条","txt":"中国证监会依法履行职责，对境外基础证券发行人及其控股股东、实际控制人、境内实体运营企业、存托人、托管人、保荐人、承销机构、证券服务机构及其他主体采取进行现场检查、进入涉嫌违法行为发生场所调查取证等措施的，适用《证券法》第一百八十条规定。"},{"i":46,"n":"第四十六条","txt":"存托凭证的发行、交易等活动违反本办法规定的，中国证监会可以采取以下监管措施： （一）责令改正； （二）监管谈话； （三）出具警示函； （四）认定为不适当人选； （五）依法可以采取的其他监管措施。"},{"i":47,"n":"第四十七条","txt":"有下列行为的，中国证监会依据《证券法》相关规定进行行政处罚；构成犯罪的，依法追究刑事责任： （一）未经中国证监会核准，擅自公开或者变相公开发行存托凭证； （二）不符合发行条件的境外基础证券发行人以欺骗手段骗取存托凭证发行核准； （三）保荐人在存托凭证发行、上市中出具有虚假记载、误导性陈述或者重大遗漏的保荐书，或者不履行其他法定职责； （四）境外基础证券发行人或者其他信息披露义务人未按照规定披露信息、报送有关报告，或者所披露的信息、报送的报告有虚假记载、误导性陈述或者重大遗漏； （五）内幕信息知情人和非法获取内幕信息的人利用内幕信息买卖存托凭证、泄露内幕信息、建议他人买卖存托凭证； （六）违反《证券法》的规定操纵存托凭证市场； （七）证券服务机构在为存托凭证的发行、交易等证券业务活动提供服务中，未勤勉尽责，所制作、出具的文件有虚假记载、误导性陈述或者重大遗漏； （八）《证券法》规定的其他"},{"i":48,"n":"第四十八条","txt":"境外基础证券发行人的股东、实际控制人、董事、监事、高级管理人员和存托凭证的其他投资者违反本办法第十二条的规定，在中国境内减持其持有的存托凭证的，责令改正，给予警告，没收违法所得，并处三万元罚款。"},{"i":49,"n":"第四十九条","txt":"法律、行政法规禁止参与股票交易的人员，直接或者以化名、借他人名义持有、买卖、接受他人赠送存托凭证的，依照《证券法》第一百九十九条的规定进行行政处罚。属于国家工作人员的，还应当依法给予行政处分。"},{"i":50,"n":"第五十条","txt":"有下列行为的，依照《证券法》第二百零一条的规定进行行政处罚： （一）为存托凭证的发行出具审计报告、资产评估报告或者法律意见书等文件的证券服务机构和人员，在该存托凭证承销期内和期满后六个月内，买卖该存托凭证； （二）为境外基础证券发行人出具审计报告、资产评估报告或者法律意见书等文件的证券服务机构和人员，自接受境外基础证券发行人委托之日起至上述文件公开后五日内，买卖该存托凭证。"},{"i":51,"n":"第五十一条","txt":"境外基础证券发行人的董事、监事、高级管理人员、通过存托凭证或者其他方式持有境外基础证券发行人发行的股份百分之五以上的投资者，将其持有的存托凭证在买入后六个月内卖出，或者在卖出后六个月内又买入的，依照《证券法》第一百九十五条的规定处罚。但是证券公司因包销购入售后剩余存托凭证对应境外基础证券发行人已发行股份达到百分之五以上的除外。"},{"i":52,"n":"第五十二条","txt":"收购人违反本办法第十三条规定的，依照《证券法》第二百一十三条的规定处罚。 收购人或者收购人的控股股东，利用对境外基础证券发行人的收购，损害被收购境外基础证券发行人及其投资者的合法权益的，依照《证券法》第二百一十四条的规定处罚。"},{"i":53,"n":"第五十三条","txt":"存托人、托管人违反本办法规定的，责令改正，给予警告，没收违法所得，并处三万元罚款。对直接负责的主管人员和其他直接责任人员给予警告，没收违法所得，并处三万元罚款。 经中国证监会责令改正后拒不改正或者违法违规情节严重的，中国证监会可以采取责令境外基础证券发行人更换存托人、责令存托人更换托管人、三十六个月内不受理由其担任存托人的申请文件、取消存托人资质等监管措施。 存托人中参与存托业务的人员，在任期内，直接或者以化名、借他人名义持有、买卖、接受他人赠送存托凭证的，责令改正，给予警告，没收违法所得，并处三万元罚款。"},{"i":54,"n":"第五十四条","txt":"违反本办法情节严重的，中国证监会可以对有关责任人员采取证券市场禁入的措施。"},{"i":55,"n":"第五十五条","txt":"境外基础证券发行人及其控股股东、实际控制人、存托人、托管人、保荐人、承销机构、证券服务机构等违反本办法规定，导致存托凭证持有人等投资者合法权益受到损害的，应当依法承担赔偿责任。"},{"i":56,"n":"第五十六条","txt":"境内企业在境外发行存托凭证适用《证券法》等法律、行政法规以及中国证监会关于境内企业到境外发行证券或者将其证券在境外上市交易的规定。境内上市公司以新增证券为基础在境外发行存托凭证的，还应当同时符合有关上市公司证券发行的规定。"},{"i":57,"n":"第五十七条","txt":"存托凭证与基础证券之间的转换应当符合国家有关规定。 境内证券交易所与境外证券交易所之间互联互通业务中涉及的存托凭证发行、交易、信息披露和投资者保护等事宜，中国证监会或者证券交易所另有规定的，从其规定。"},{"i":58,"n":"第五十八条","txt":"中国证监会与有关国家或者地区的证券监督管理机构加强跨境监管执法合作，依法查处存托凭证业务相关跨境违法违规行为。"},{"i":59,"n":"第五十九条","txt":"本办法下列用语具有如下含义： （一）基础证券，是指存托凭证代表的由境外基础证券发行人在境外发行的证券； （二）基础财产，是指基础证券及其衍生权益； （三）存托人，是指按照存托协议的约定持有境外基础证券，并相应签发代表境外基础证券权益的存托凭证的中国境内法人； （四）托管人，是指受存托人委托，按照托管协议托管存托凭证所代表的基础证券的金融机构； （五）控股股东，是指通过存托凭证或者其他方式持有境外基础证券发行人发行的股份合计达到百分之五十以上的股东；持有股份的比例虽然不足百分之五十，但依其持有的股份所享有的表决权已足以对股东大会或者董事会的决议产生重大影响的股东； （六）实际控制人，是指虽不是境外基础证券发行人的股东，但通过投资关系、协议或者其他安排，能够实际支配境外基础证券发行人的人； （七）董事、监事、高级管理人员，是指境外基础证券发行人的董事、监事、高级管理人员或者执行类似职权的人"},{"i":60,"n":"第六十条","txt":"本办法自公布之日起施行。"}],"kehujiaoyijiesuanzijinguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范证券交易结算资金的管理，保护投资者利益，根据《中华人民共和国证券法》（以下简称《证券法》），制定本办法。"},{"i":2,"n":"第二条","txt":"客户交易结算资金必须全额存入指定的从事证券交易结算资金存管业务的商业银行，单独立户管理。严禁挪用客户交易结算资金。"},{"i":3,"n":"第三条","txt":"从事证券交易结算资金存管业务的商业银行、证券登记结算公司（以下简称结算公司）依照本办法对客户交易结算资金、清算备付金的定向划转实行监督。"},{"i":4,"n":"第四条","txt":"中国证券监督管理委员会（以下简称证监会）依照本办法对证券公司、结算公司和商业银行的证券交易结算资金存管业务活动进行监督管理。"},{"i":5,"n":"第五条","txt":"证券公司及其证券营业部必须将客户交易结算资金全额存放于客户交易结算资金专用存款账户和清算备付金账户。 结算公司必须将证券公司存入的清算备付金全额存入清算备付金专用存款账户。"},{"i":6,"n":"第六条","txt":"证券公司根据业务需要可在多家存管银行存放客户交易结算资金，但必须确定一家存管银行为主办存管银行。"},{"i":7,"n":"第七条","txt":"证券公司应当在存管银行开立客户交易结算资金专用存款账户，在主办存管银行开立自有资金专用存款账户。 证券公司下属证券营业部应当在证券公司所确定的存管银行设在当地的分支机构开立客户交易结算资金专用存款账户。 结算公司应当在结算银行开立清算备付金专用存款账户、自有资金专用存款账户、验资专户。"},{"i":8,"n":"第八条","txt":"证券公司在同一家存管银行只能开立一个客户交易结算资金专用存款账户，在主办存管银行只能开立一个自有资金专用存款账户。 一个证券营业部只能在同一家存管银行设在当地的分支机构开立一个客户交易结算资金专用存款账户。 结算公司在同一家结算银行只能开立一个清算备付金专用存款账户和一个自有资金专用存款账户，一个验资专户。"},{"i":9,"n":"第九条","txt":"证券公司及其证券营业部开立的客户交易结算资金专用存款账户，证券公司开立的自有资金专用存款账户，结算公司开立的清算备付金专用存款账户、自有资金专用存款账户、验资专户，应在开立后三个工作日内向证监会报备，在获得账户备案回执之前，不得使用。"},{"i":10,"n":"第十条","txt":"证券公司获得证监会的账户备案回执后，应当通知其存管银行及结算公司。 结算公司在获得证监会账户备案回执后，应当通知结算银行及证券公司。"},{"i":11,"n":"第十一条","txt":"证券公司不再使用的客户交易结算资金专用存款账户，应当在向证监会报备后注销，并同时通知有关存管银行、结算公司。 结算公司不再使用的清算备付金专用存款账户、验资专户，应当在向证监会报备后注销，并同时通知有关证券公司、存管银行。 证券公司、结算公司不再使用的自有资金专用存款账户，应当在向证监会报备后注销。其中证券公司注销自有资金专用存款账户的，应通知结算公司；结算公司注销自有资金专用存款账户的，应通知结算银行。"},{"i":12,"n":"第十二条","txt":"证券公司、证券营业部出现迁址、终止营业等情形，应当及时注销不再使用的客户交易结算资金专用存款账户、自有资金专用存款账户。"},{"i":13,"n":"第十三条","txt":"客户交易结算资金专用存款账户、清算备付金专用存款账户、自有资金专用存款账户发生变更的，视同注销旧户，开设新户。"},{"i":14,"n":"第十四条","txt":"综合类证券公司必须将客户交易结算资金和其证券自营资金分开办理，其业务人员、财务账户均应分开，不得混合操作。"},{"i":15,"n":"第十五条","txt":"存管银行、结算公司在确认证券公司申请划款的账户已经在证监会备案，自有资金专用存款账户的使用符合本办法要求后，方可将资金划入该账户。 结算银行在确认结算公司申请划款的账户已经在证监会备案、自有资金专用存款账户的使用符合本法规定后，方可将资金划入该账户。"},{"i":16,"n":"第十六条","txt":"客户交易结算资金只能在客户交易结算资金专用存款账户和清算备付金账户之间划转，但客户提款、证券公司将收取客户的费用转入自有资金专用存款账户等业务除外。"},{"i":17,"n":"第十七条","txt":"综合类证券公司向客户收取佣金等费用、以自有资金补充清算备付金，应当集中通过清算备付金账户和自有资金专用存款账户划拨。 经纪类证券公司向客户收取佣金等费用，应当从一个固定的客户交易结算资金专用存款账户集中向证券公司自有资金账户划拨。 结算公司向证券公司收取手续费等费用，应当从清算备付金专用存款账户向结算公司自有资金专用存款账户划拨。"},{"i":18,"n":"第十八条","txt":"通过证券交易所发行有价证券时，验资专户里的申购资金必须通过清算备付金账户进行划拨。 证券公司承销非上市证券从客户处所筹集的资金，应当通过证券公司在主办存管银行的客户交易结算资金专用存款账户划拨给发行人。"},{"i":19,"n":"第十九条","txt":"证券公司自营证券账户应当向证监会和结算公司备案，结算公司应当根据证券公司备案的自营证券账户、经纪证券账户的净交收额及资金存取变动情况，定期计算每个交易日清算备付金账户中每家证券公司自营资金、经纪资金的余额，并保留有关记录。 结算公司如果发现证券公司有大量挪用客户交易结算资金情况，要及时向证监会报告。"},{"i":20,"n":"第二十条","txt":"证券公司应当按月向证监会报告客户交易结算资金账面余额。同时，抄送结算公司。 结算公司应当按月向证监会报告各证券公司清算备付金中的经纪资金、自营资金及所收到证券公司清算备付金以及验资专户申购资金的账面余额。 存管银行应当按月向证监会报告所辖客户交易结算资金专用存款账户余额。 结算银行应当按月向证监会报告所辖清算备付金专用存款账户、验资专户余额。 证监会根据监管需要，可以调整上述报告周期。"},{"i":21,"n":"第二十一条","txt":"证券公司、结算公司、存管银行、结算银行根据证监会要求或遇到客户交易结算资金专用存款账户、清算备付金专用存款账户、验资专户出现重大异常情况时，应当及时向证监会报告。"},{"i":22,"n":"第二十二条","txt":"证券公司应当对客户交易结算资金集中统一管理。 证券公司下属证券营业部收到的客户交易结算资金，除留足日常备付的部分外，应当交由证券公司管理。"},{"i":23,"n":"第二十三条","txt":"客户交易结算资金只能用于客户的证券交易结算和客户提款。 证券公司和结算公司不得以客户交易结算资金、清算备付金为他人提供担保。"},{"i":24,"n":"第二十四条","txt":"存管银行、结算银行、结算公司及其工作人员应当对证券交易结算资金的情况保密。 存管银行、结算银行和结算公司有权拒绝任何单位或个人的查询，但法律、法规另有规定以及证监会、开户证券公司和结算公司根据预定的程序所作的查询除外。"},{"i":25,"n":"第二十五条","txt":"从事客户交易结算资金存管业务的商业银行应当符合下列条件： （一） 经中国人民银行认定具有足够的抗风险能力和良好的经营业绩的商业银行； （二） 具有及时、安全、高效的资金汇划系统，能够保证本行系统内证券交易结算资金汇划在两小时内到账； （三） 有健全的证券交易结算资金存管业务操作办法和规程，有相应的业务部门和人员； （四） 能够按证监会规定的格式和时间报送证券交易结算资金账户的有关资料； （五） 符合证监会认定的其他条件。"},{"i":26,"n":"第二十六条","txt":"从事客户交易结算资金存管业务的商业银行，按业务对象分为存管银行和结算银行。"},{"i":27,"n":"第二十七条","txt":"证券公司与其确定的存管银行、主办存管银行，结算公司与其确定的结算银行应当签定有关资金存管及代理结算业务的合同，明确双方的权利和义务，并报证监会备案。"},{"i":28,"n":"第二十八条","txt":"存管银行、结算银行应当为证券交易结算资金清算提供快捷、安全、准确的结算服务。"},{"i":29,"n":"第二十九条","txt":"证券公司、证券营业部有下列行为之一的，责令限期改正，给予通报批评，单处或者并处警告、三万元以下罚款： （一）未按本办法制定客户交易结算资金操作办法和规程； （二）违规开立客户交易结算资金专用存款账户、自有资金专用存款账户； （三）未在规定时间内向证监会报备存管银行、客户交易结算资金专用存款账户、自有资金专用存款账户； （四）未及时注销不再使用的客户交易结算资金专用存款账户、自有资金专用存款账户； （五）未按期向证监会报告客户交易结算资金账面余额； （六）其他违反本办法的行为。 对有前款规定行为的有关责任人员，给予通报批评，单处或者并处警告、三万元以下罚款。"},{"i":30,"n":"第三十条","txt":"证券公司、证券营业部有下列行为之一的，责令限期改正，给予通报批评，单处或者并处警告、三万元以下罚款，情节严重的，按照《证券法》第二百零八条处罚： （一）以伪造、变造证监会账户备案回执等欺骗手段，取得存管银行或者结算公司资金划拨许可； （二）违反本办法，在客户交易结算资金专用存款账户、清算备付金账户之外存放客户交易结算资金； （三）以客户交易结算资金为他人提供担保； （四）其他违反本办法的行为。 对有前款规定行为的有关责任人员，给予通报批评，单处或者并处警告、三万元以下罚款，情节严重的，按照《证券法》第二百零八条处罚。"},{"i":31,"n":"第三十一条","txt":"结算公司有下列行为之一的，责令限期改正，给予通报批评，单处或者并处警告、三万元以下罚款： （一）违反本办法，未能对客户交易结算资金划拨进行有效监督； （二）违规开立清算备付金专用存款账户或者自有资金专用存款账户； （三）未在规定时间内向证监会报备结算银行、清算备付金专用存款账户、自有资金专用存款账户、验资专户； （四）未及时注销不再使用的清算专户、自有资金专用存款账户； （五）未按期向证监会报告有关清算备付金账户及验资专户的账面余额； （六）其他违反本办法的行为。 对有前款规定行为的有关责任人员，给予通报批评，单处或者并处警告、三万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"结算公司有下列行为之一的，责令限期改正，给予通报批评，单处或者并处警告、三万元以下罚款，情节严重的，按照《证券法》第二百零八条处罚： （一）违反本办法，在清算备付金专用存款账户外存放清算备付金； （二）以清算备付金为他人提供担保； （三）违反本办法第十八条第一款的规定； （四）其他违反本办法的行为。 对有前款规定行为的有关责任人员，给予通报批评，单处或者并处警告、三万元以下罚款，情节严重的，按照《证券法》第二百零八条处罚。"},{"i":33,"n":"第三十三条","txt":"存管银行或其分支机构、结算银行有下列行为之一的，责令限期改正，给予通报批评，单处或者并处警告、三万元以下罚款，情节严重的，按照《证券公司监督管理条例》第八十七条处理： （一）违反本办法，未能对客户交易结算资金划拨进行有效监督； （二）未按照本办法规定，向证监会报送客户交易结算资金专用存款账户、清算备付金专用存款账户和验资专户的有关资料； （三）其他违反本办法的行为。 对有前款规定行为的有关责任人员，给予通报批评，单处或者并处警告、三万元以下罚款。"},{"i":34,"n":"第三十四条","txt":"证券公司、结算公司、存管银行、结算银行违反本办法第二十一条规定，不向证监会及时报告的，予以通报批评，单处或者并处警告、三万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"存管银行、结算公司工作人员泄露证券交易结算资金秘密的，按有关法律、法规、规章进行处罚。"},{"i":36,"n":"第三十六条","txt":"释义： （一）证券交易结算资金，是客户交易结算资金、证券公司自营资金、其他用于证券交易资金的统称。 （二）客户交易结算资金，包括客户为保证足额交收而存入的资金，出售有价证券所得到的所有款项（减去经纪佣金和其他正当费用），持有证券所获得的股息、现金股利、债券利息，上述资金获得的利息，以及证监会认定的其他资金。 （三）指定的从事客户交易结算资金存管业务的商业银行，指符合本办法规定并由证监会和银保监会确定并公告的，办理证券交易结算资金存取、划转并履行监督职能的商业银行。 （四）存管银行，指证券公司在指定的从事证券交易结算资金存管业务的商业银行中确定的，存放其客户交易结算资金的商业银行。 （五）主办存管银行，指证券公司在存管银行范围内确定的，通过其办理证券交易法人结算业务的商业银行。 （六）结算银行，指结算公司在指定的从事证券交易结算资金存管业务的商业银行中确定的，办理证券交易结算资金结算业务"},{"i":37,"n":"第三十七条","txt":"证券公司应当按照本办法制定客户交易结算资金操作办法和规程，报证监会备案。"},{"i":38,"n":"第三十八条","txt":"证券公司开展资产管理业务接受客户存入的委托资金，在本办法中视同客户交易结算资金进行管理。"},{"i":39,"n":"第三十九条","txt":"信托投资公司证券业务客户交易结算资金的管理参照本办法执行。"},{"i":40,"n":"第四十条","txt":"境内上市外资股客户交易结算资金管理办法，另行制定。"},{"i":41,"n":"第四十一条","txt":"本办法自2002年1月1日起施行。"}],"qihuojiaoyisuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对期货交易所的监督管理，明确期货交易所职责，维护期货市场秩序，促进期货市场积极稳妥发展，根据《期货交易管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内设立的期货交易所。"},{"i":3,"n":"第三条","txt":"本办法所称期货交易所是指依照《期货交易管理条例》和本办法规定设立，不以营利为目的，履行《期货交易管理条例》和本办法规定的职责，按照章程和交易规则，实行自律管理的法人。"},{"i":4,"n":"第四条","txt":"经中国证券监督管理委员会（以下简称中国证监会）批准，期货交易所可以采取会员制或者公司制的组织形式。 会员制期货交易所的注册资本划分为均等份额，由会员出资认缴。 公司制期货交易所采用股份有限公司的组织形式。"},{"i":5,"n":"第五条","txt":"中国证监会依法对期货交易所实行集中统一的监督管理。"},{"i":6,"n":"第六条","txt":"设立期货交易所，由中国证监会审批。未经国务院或者中国证监会批准，任何单位或者个人不得设立期货交易场所或者以任何形式组织期货交易及其相关活动。"},{"i":7,"n":"第七条","txt":"经中国证监会批准设立的期货交易所，应当标明“商品交易所”、“期货交易所”字样。其他任何单位或者个人不得使用“期货交易所”或者近似的名称。"},{"i":8,"n":"第八条","txt":"期货交易所除履行《期货交易管理条例》规定的职责外，还应当履行下列职责： （一）制定并实施期货交易所的交易规则及其实施细则； （二）发布市场信息； （三）监管会员及其客户、指定交割仓库、期货保证金存管银行及期货市场其他参与者的期货业务； （四）查处违规行为。"},{"i":9,"n":"第九条","txt":"申请设立期货交易所，应当向中国证监会提交下列文件和材料： （一）申请书； （二）章程和交易规则草案； （三）期货交易所的经营计划； （四）拟加入会员或者股东名单； （五）理事会成员候选人或者董事会和监事会成员名单及简历； （六）拟任用高级管理人员的名单及简历； （七）场地、设备、资金证明文件及情况说明； （八）中国证监会规定的其他文件、材料。"},{"i":10,"n":"第十条","txt":"期货交易所章程应当载明下列事项： （一）设立目的和职责； （二）名称、住所和营业场所； （三）注册资本及其构成； （四）营业期限； （五）组织机构的组成、职责、任期和议事规则； （六）管理人员的产生、任免及其职责； （七）基本业务制度； （八）风险准备金管理制度； （九）财务会计、内部控制制度； （十）变更、终止的条件、程序及清算办法； （十一）章程修改程序； （十二）需要在章程中规定的其他事项。"},{"i":11,"n":"第十一条","txt":"除本办法第十条规定的事项外，会员制期货交易所章程还应当载明下列事项： （一）会员资格及其管理办法； （二）会员的权利和义务； （三）对会员的纪律处分。"},{"i":12,"n":"第十二条","txt":"期货交易所交易规则应当载明下列事项： （一）期货交易、结算和交割制度； （二）风险管理制度和交易异常情况的处理程序； （三）保证金的管理和使用制度； （四）期货交易信息的发布办法； （五）违规、违约行为及其处理办法； （六）交易纠纷的处理方式； （七）需要在交易规则中载明的其他事项。 公司制期货交易所还应当在交易规则中载明本办法第十一条规定的事项。"},{"i":13,"n":"第十三条","txt":"期货交易所变更名称、注册资本的，应当事前向中国证监会报告。"},{"i":14,"n":"第十四条","txt":"期货交易所合并、分立或者变更组织形式的，应当事前向中国证监会报告。 期货交易所合并可以采取吸收合并和新设合并两种方式，合并前各方的债权、债务由合并后存续或者新设的期货交易所承继。 期货交易所分立的，其债权、债务由分立后的期货交易所承继。"},{"i":15,"n":"第十五条","txt":"期货交易所联网交易的，应当于决定之日起10日内报告中国证监会。"},{"i":16,"n":"第十六条","txt":"未经中国证监会批准，期货交易所不得设立分所或者其他任何期货交易场所。"},{"i":17,"n":"第十七条","txt":"期货交易所因下列情形之一解散： （一）章程规定的营业期限届满； （二）会员大会或者股东大会决定解散； （三）中国证监会决定关闭。 期货交易所因前款第（一）项、第（二）项情形解散的，应当事前向中国证监会报告。"},{"i":18,"n":"第十八条","txt":"期货交易所因合并、分立或者解散而终止的，由中国证监会予以公告。 期货交易所终止的，应当成立清算组进行清算。清算组制定的清算方案，应当事前向中国证监会报告。"},{"i":19,"n":"第十九条","txt":"会员制期货交易所设会员大会。会员大会是期货交易所的权力机构，由全体会员组成。"},{"i":20,"n":"第二十条","txt":"会员大会行使下列职权： （一）审定期货交易所章程、交易规则及其修改草案； （二）选举、更换会员理事； （三）审议批准理事会和总经理的工作报告； （四）审议批准期货交易所的财务预算方案、决算报告； （五）审议期货交易所风险准备金使用情况； （六）决定增加或者减少期货交易所注册资本； （七）决定期货交易所的合并、分立、解散和清算事项； （八）决定期货交易所理事会提交的其他重大事项； （九）期货交易所章程规定的其他职权。"},{"i":21,"n":"第二十一条","txt":"会员大会由理事会召集，每年召开一次。 有下列情形之一的，应当召开临时会员大会： （一）会员理事不足期货交易所章程规定人数的2/3； （二）1/3以上会员联名提议； （三）理事会认为必要。"},{"i":22,"n":"第二十二条","txt":"会员大会由理事长主持。召开会员大会，应当将会议审议的事项于会议召开10日前通知会员。临时会员大会不得对通知中未列明的事项作出决议。"},{"i":23,"n":"第二十三条","txt":"会员大会有2/3以上会员参加方为有效。会员大会应当对表决事项制作会议纪要，由出席会议的理事签名。 会员大会结束之日起10日内，期货交易所应当将大会全部文件报告中国证监会。"},{"i":24,"n":"第二十四条","txt":"期货交易所设理事会，每届任期3年。理事会是会员大会的常设机构，对会员大会负责。"},{"i":25,"n":"第二十五条","txt":"理事会行使下列职权： （一）召集会员大会，并向会员大会报告工作； （二）拟订期货交易所章程、交易规则及其修改草案，提交会员大会审定； （三）审议总经理提出的财务预算方案、决算报告，提交会员大会通过； （四）审议期货交易所合并、分立、解散和清算的方案，提交会员大会通过； （五）决定专门委员会的设置； （六）决定会员的接纳和退出； （七）决定对违规行为的纪律处分； （八）决定期货交易所变更名称、住所或者营业场所； （九）审议批准根据章程和交易规则制定的细则和办法； （十）审议结算担保金的使用情况； （十一）审议批准风险准备金的使用方案； （十二）审议批准总经理提出的期货交易所发展规划和年度工作计划； （十三）审议批准期货交易所对外投资计划； （十四）监督总经理组织实施会员大会和理事会决议的情况； （十五）监督期货交易所高级管理人员和其他工作人员遵守国家有关法律、行政法规、规章、政策和期货交"},{"i":26,"n":"第二十六条","txt":"理事会由会员理事和非会员理事组成；其中会员理事由会员大会选举产生，非会员理事由中国证监会委派。"},{"i":27,"n":"第二十七条","txt":"理事会设理事长1人、副理事长1至2人。理事长、副理事长的任免，由中国证监会提名，理事会通过。理事长不得兼任总经理。"},{"i":28,"n":"第二十八条","txt":"理事长行使下列职权： （一）主持会员大会、理事会会议和理事会日常工作； （二）组织协调专门委员会的工作； （三）检查理事会决议的实施情况并向理事会报告。 副理事长协助理事长工作。理事长因故临时不能履行职权的，由理事长指定的副理事长或者理事代其履行职权。"},{"i":29,"n":"第二十九条","txt":"理事会会议至少每半年召开一次。每次会议应当于会议召开10日前通知全体理事。 有下列情形之一的，应当召开理事会临时会议： （一）1/3以上理事联名提议； （二）期货交易所章程规定的情形； （三）中国证监会提议。 理事会召开临时会议，可以另定召集理事会临时会议的通知方式和通知时限。"},{"i":30,"n":"第三十条","txt":"理事会会议须有2/3以上理事出席方为有效，其决议须经全体理事1/2以上表决通过。 理事会会议结束之日起10日内，理事会应当将会议决议及其他会议文件报告中国证监会。"},{"i":31,"n":"第三十一条","txt":"理事会会议应当由理事本人出席。理事因故不能出席的，应当以书面形式委托其他理事代为出席；委托书中应当载明授权范围。每位理事只能接受一位理事的委托。 理事会应当对会议表决事项作成会议记录，由出席会议的理事和记录员在会议记录上签名。"},{"i":32,"n":"第三十二条","txt":"理事会可以根据需要设立监察、交易、结算、交割、会员资格审查、纪律处分、调解、财务和技术等专门委员会。 各专门委员会对理事会负责，其职责、任期和人员组成等事项由理事会规定。"},{"i":33,"n":"第三十三条","txt":"期货交易所设总经理1人、副总经理若干人。总经理、副总经理由中国证监会任免。总经理每届任期3年，连任不得超过两届。 总经理是期货交易所的法定代表人，总经理是当然理事。"},{"i":34,"n":"第三十四条","txt":"总经理行使下列职权： （一）组织实施会员大会、理事会通过的制度和决议； （二）主持期货交易所的日常工作； （三）根据章程和交易规则拟订有关细则和办法； （四）决定结算担保金的使用； （五）拟订风险准备金的使用方案； （六）拟订并实施经批准的期货交易所发展规划、年度工作计划； （七）拟订并实施经批准的期货交易所对外投资计划； （八）拟订期货交易所财务预算方案、决算报告； （九）拟订期货交易所合并、分立、解散和清算的方案； （十）拟订期货交易所变更名称、住所或者营业场所的方案； （十一）决定期货交易所机构设置方案，聘任和解聘工作人员； （十二）决定期货交易所员工的工资和奖惩； （十三）期货交易所章程规定的或者理事会授予的其他职权。 总经理因故临时不能履行职权的，由总经理指定的副总经理代其履行职权。"},{"i":35,"n":"第三十五条","txt":"期货交易所任免中层管理人员，应当在决定之日起10日内向中国证监会报告。"},{"i":36,"n":"第三十六条","txt":"公司制期货交易所设股东大会。股东大会是期货交易所的权力机构，由全体股东组成。"},{"i":37,"n":"第三十七条","txt":"股东大会行使下列职权： （一）本办法第二十条第（一）项、第（四）项至第（七）项规定的职权； （二）选举和更换非由职工代表担任的董事、监事； （三）审议批准董事会、监事会和总经理的工作报告； （四）决定期货交易所董事会提交的其他重大事项； （五）期货交易所章程规定的其他职权。"},{"i":38,"n":"第三十八条","txt":"股东大会会议的召开及议事规则应当符合期货交易所章程的规定。 会议结束之日起10日内，期货交易所应当将会议全部文件报告中国证监会。"},{"i":39,"n":"第三十九条","txt":"期货交易所设董事会，每届任期3年。"},{"i":40,"n":"第四十条","txt":"董事会对股东大会负责，行使下列职权： （一）召集股东大会会议，并向股东大会报告工作； （二）拟订期货交易所章程、交易规则及其修改草案，提交股东大会审定； （三）审议总经理提出的财务预算方案、决算报告，提交股东大会通过； （四）审议期货交易所合并、分立、解散和清算的方案，提交股东大会通过； （五）监督总经理组织实施股东大会和董事会决议的情况； （六）本办法第二十五条第（五）项至第（十三）项、第（十五）项、第（十六）项规定的职权； （七）期货交易所章程规定和股东大会授予的其他职权。"},{"i":41,"n":"第四十一条","txt":"期货交易所设董事长1人、副董事长1至2人。董事长、副董事长的任免，由中国证监会提名，董事会通过。董事长不得兼任总经理。"},{"i":42,"n":"第四十二条","txt":"董事长行使下列职权： （一）主持股东大会、董事会会议和董事会日常工作； （二）组织协调专门委员会的工作； （三）检查董事会决议的实施情况并向董事会报告。 副董事长协助董事长工作。董事长因故临时不能履行职权的，由董事长指定的副董事长或者董事代其履行职权。"},{"i":43,"n":"第四十三条","txt":"董事会会议的召开和议事规则应当符合期货交易所章程的规定。 董事会会议结束之日起10日内，董事会应当将会议决议及其他会议文件报告中国证监会。"},{"i":44,"n":"第四十四条","txt":"董事会可以根据需要设立本办法第三十二条规定的专门委员会。各专门委员会对董事会负责，其职责、任期和人员组成等事项由董事会规定。"},{"i":45,"n":"第四十五条","txt":"期货交易所应当设独立董事。独立董事由中国证监会提名，股东大会通过。"},{"i":46,"n":"第四十六条","txt":"期货交易所可以设董事会秘书。董事会秘书由中国证监会提名，董事会通过。 董事会秘书负责期货交易所股东大会和董事会会议的筹备、文件保管以及期货交易所股东资料的管理等事宜。"},{"i":47,"n":"第四十七条","txt":"期货交易所设总经理1人、副总经理若干人。总经理、副总经理由中国证监会任免。总经理每届任期3年，连任不得超过两届。 总经理是期货交易所的法定代表人，应当由董事担任。"},{"i":48,"n":"第四十八条","txt":"总经理行使下列职权： （一）组织实施股东大会、董事会通过的制度和决议； （二）本办法第三十四条第（二）项至第（十二）项规定的职权； （三）期货交易所章程规定或者董事会授予的其他职权。 总经理因故临时不能履行职权的，由总经理指定的副总经理代其履行职权。"},{"i":49,"n":"第四十九条","txt":"期货交易所设监事会，每届任期3年。监事会成员不得少于3人。监事会设主席1人、副主席1至2人。监事会主席、副主席的任免，由中国证监会提名，监事会通过。"},{"i":50,"n":"第五十条","txt":"监事会行使下列职权： （一）检查期货交易所财务； （二）监督期货交易所董事、高级管理人员执行职务行为； （三）向股东大会提出提案； （四）期货交易所章程规定的其他职权。"},{"i":51,"n":"第五十一条","txt":"监事会会议的召开和议事规则应当符合期货交易所章程的规定。 监事会会议结束之日起10日内，监事会应当将会议决议及其他会议文件报告中国证监会。"},{"i":52,"n":"第五十二条","txt":"本办法第三十五条的规定适用于公司制期货交易所。"},{"i":53,"n":"第五十三条","txt":"期货交易所会员应当是在中华人民共和国境内登记注册的法人或者非法人组织。"},{"i":54,"n":"第五十四条","txt":"取得期货交易所会员资格，应当经期货交易所批准。 期货交易所批准、取消会员的会员资格，应当向中国证监会报告。"},{"i":55,"n":"第五十五条","txt":"期货交易所应当制定会员管理办法，规定会员资格的取得与终止的条件和程序、对会员的监督管理等内容。"},{"i":56,"n":"第五十六条","txt":"会员制期货交易所会员享有下列权利： （一）参加会员大会，行使选举权、被选举权和表决权； （二）在期货交易所从事规定的交易、结算和交割等业务； （三）使用期货交易所提供的交易设施，获得有关期货交易的信息和服务； （四）按规定转让会员资格； （五）联名提议召开临时会员大会； （六）按照期货交易所章程和交易规则行使申诉权； （七）期货交易所章程规定的其他权利。"},{"i":57,"n":"第五十七条","txt":"会员制期货交易所会员应当履行下列义务： （一）遵守国家有关法律、行政法规、规章和政策； （二）遵守期货交易所的章程、交易规则及其实施细则及有关决定； （三）按规定缴纳各种费用； （四）执行会员大会、理事会的决议； （五）接受期货交易所监督管理。"},{"i":58,"n":"第五十八条","txt":"公司制期货交易所会员享有下列权利： （一）本办法第五十六条第（二）项和第（三）项规定的权 利； （二）按照交易规则行使申诉权； （三）期货交易所交易规则规定的其他权利。"},{"i":59,"n":"第五十九条","txt":"公司制期货交易所会员应当履行本办法第五十七条第（一）项至第（三）项、第（五）项规定的义务。"},{"i":60,"n":"第六十条","txt":"期货交易所应当每年对会员遵守期货交易所交易规则及其实施细则的情况进行抽样或者全面检查，并将检查结果报送中国证监会。 期货交易所行使监管职权时，可以按照期货交易所章程和交易规则及其实施细则规定的权限和程序对会员进行调查取证，会员应当予以配合。"},{"i":61,"n":"第六十一条","txt":"期货交易所实行全员结算制度或者会员分级结算制度，应当事前向中国证监会报告。"},{"i":62,"n":"第六十二条","txt":"实行全员结算制度的期货交易所会员均具有与期货交易所进行结算的资格。"},{"i":63,"n":"第六十三条","txt":"实行全员结算制度的期货交易所会员由期货公司会员和非期货公司会员组成。期货公司会员按照中国证监会批准的业务范围开展相关业务；非期货公司会员不得从事《期货交易管理条例》规定的期货公司业务。"},{"i":64,"n":"第六十四条","txt":"实行全员结算制度的期货交易所对会员结算，会员对其受托的客户结算。"},{"i":65,"n":"第六十五条","txt":"实行会员分级结算制度的期货交易所会员由结算会员和非结算会员组成。结算会员具有与期货交易所进行结算的资格，非结算会员不具有与期货交易所进行结算的资格。 期货交易所对结算会员结算，结算会员对非结算会员结算，非结算会员对其受托的客户结算。"},{"i":66,"n":"第六十六条","txt":"结算会员由交易结算会员、全面结算会员和特别结算会员组成。 全面结算会员、特别结算会员可以为与其签订结算协议的非结算会员办理结算业务。交易结算会员不得为非结算会员办理结算业务。"},{"i":67,"n":"第六十七条","txt":"实行会员分级结算制度的期货交易所可以根据结算会员资信和业务开展情况，限制结算会员的结算业务范围，但应当于3日内报告中国证监会。"},{"i":68,"n":"第六十八条","txt":"期货交易所向会员收取的保证金，只能用于担保期货合约的履行，不得查封、冻结、扣划或者强制执行。期货交易所应当在期货保证金存管银行开立专用结算账户，专户存储保证金，不得挪用。 保证金分为结算准备金和交易保证金。结算准备金是指未被合约占用的保证金；交易保证金是指已被合约占用的保证金。 实行会员分级结算制度的期货交易所只向结算会员收取保证金。"},{"i":69,"n":"第六十九条","txt":"期货交易所应当建立保证金管理制度，保证金管理制度应当包括下列内容： （一）向会员收取保证金的标准和形式； （二）专用结算账户中会员结算准备金最低余额； （三）当会员结算准备金余额低于期货交易所规定最低余额时的处置方法。 会员结算准备金最低余额由会员以自有资金向期货交易所缴纳。"},{"i":70,"n":"第七十条","txt":"期货交易所可以接受以下有价证券作为保证金： （一）经期货交易所认定的标准仓单； （二）可流通的国债； （三）中国证监会认定的其他有价证券。 以前款规定的有价证券作为保证金的，其期限不得超过该有价证券的有效期限。"},{"i":71,"n":"第七十一条","txt":"期货交易所应当制定有价证券作为保证金的规则，明确可以作为保证金的有价证券的种类、基准计算价值、折扣率等内容。 期货交易所可以根据市场情况对作为保证金的有价证券的基准计算价值进行调整。"},{"i":72,"n":"第七十二条","txt":"有价证券作为保证金的金额不得高于会员在期货交易所专用结算账户中的实有货币资金的4倍。"},{"i":73,"n":"第七十三条","txt":"期货交易的相关亏损、费用、货款和税金等款项，应当以货币资金支付。"},{"i":74,"n":"第七十四条","txt":"客户以有价证券作为保证金的，会员应当将收到的有价证券提交期货交易所。 非结算会员的客户以有价证券作为保证金的，非结算会员应将收到的有价证券提交结算会员，由结算会员提交期货交易所。"},{"i":75,"n":"第七十五条","txt":"客户以有价证券作为保证金的，期货交易所应当将有价证券的种类和数量如实反映在该客户的交易编码下。"},{"i":76,"n":"第七十六条","txt":"实行会员分级结算制度的期货交易所应当建立结算担保金制度。结算担保金包括基础结算担保金和变动结算担保金。 结算担保金由结算会员以自有资金向期货交易所缴纳。结算担保金属于结算会员所有，用于应对结算会员违约风险。期货交易所应当按照有关规定管理和使用，不得挪作他用。 期货交易所调整基础结算担保金标准的，应当在调整前报告中国证监会。"},{"i":77,"n":"第七十七条","txt":"期货交易所应当按照手续费收入的20%的比例提取风险准备金，风险准备金应当单独核算，专户存储。 中国证监会可以根据期货交易所业务规模、发展计划以及潜在的风险决定风险准备金的规模。"},{"i":78,"n":"第七十八条","txt":"期货交易实行客户交易编码制度。会员和客户应当遵守一户一码制度，不得混码交易。"},{"i":79,"n":"第七十九条","txt":"期货交易实行限仓制度和套期保值审批制度。"},{"i":80,"n":"第八十条","txt":"期货交易实行大户持仓报告制度。会员或者客户持仓达到期货交易所规定的持仓报告标准的，会员或者客户应当向期货交易所报告。客户未报告的，会员应当向期货交易所报告。 期货交易所可以根据市场风险状况制定并调整持仓报告标准。"},{"i":81,"n":"第八十一条","txt":"期货交易实行当日无负债结算制度。期货交易所在规定的交易时间结束后，对应收应付的款项实行净额结算。 承担期货结算职责的期货交易所是期货交易的中央对手方，自期货交易达成后介入期货交易双方，成为所有买方的卖方和所有卖方的买方，承继双方在期货交易中的权利和义务，为期货交易提供集中履约保障。"},{"i":82,"n":"第八十二条","txt":"实行全员结算制度的期货交易所对会员进行风险管理，会员对其受托的客户进行风险管理。 实行会员分级结算制度的期货交易所对结算会员进行风险管理，结算会员对与其签订结算协议的非结算会员、进行风险管理，会员对其受托的客户进行风险管理。"},{"i":83,"n":"第八十三条","txt":"会员在期货交易中违约的，应当承担违约责任。 期货交易所先以违约会员的保证金承担该会员违约责任。保证金不足的，实行全员结算制度的期货交易所应当以违约会员的自有资金、期货交易所风险准备金和期货交易所自有资金承担；实行会员分级结算制度的期货交易所应当以违约会员的自有资金、结算担保金期货交易所风险准备金和期货交易所自有资金承担。 期货交易所以结算担保金、期货交易所风险准备金和期货交易所自有资金代为承担责任后，由此取得对违约会员的相应追偿权。"},{"i":84,"n":"第八十四条","txt":"有根据认为会员或者客户违反期货交易所交易规则及其实施细则并且对市场正在产生或者即将产生重大影响，为防止违规行为后果进一步扩大，期货交易所可以对会员或者客户采取下列临时处置措施： （一）限制入金； （二）限制出金； （三）限制开仓； （四）提高保证金标准； （五）限期平仓； （六）强行平仓。 期货交易所按交易规则及其实施细则规定的程序采取前款第（四）项、第（五）项或者第（六）项措施的，应当在采取措施后及时报告中国证监会。 期货交易所对会员或者客户采取临时处置措施，应当按照期货交易所交易规则及其实施细则规定的方式通知会员或者客户，并列明采取临时处置措施的根据。"},{"i":85,"n":"第八十五条","txt":"期货价格出现同方向连续涨跌停板的，期货交易所可以采用调整涨跌停板幅度、提高交易保证金标准及按一定原则减仓等措施化解风险。"},{"i":86,"n":"第八十六条","txt":"期货交易所实行风险警示制度。期货交易所认为必要的，可以分别或同时采取要求会员和客户报告情况、谈话提醒、发布风险提示函等措施，以警示和化解风险。"},{"i":87,"n":"第八十七条","txt":"在期货交易过程中出现以下情形之一的，期货交易所可以宣布进入异常情况，采取紧急措施化解风险： （一）地震、水灾、火灾等不可抗力或者计算机系统故障等不可归责于期货交易所的原因导致交易无法正常进行； （二）会员出现结算、交割危机，对市场正在产生或者即将产生重大影响； （三）出现本办法第八十五条规定的情形经采取相应措施后仍未化解风险； （四）期货交易所交易规则及其实施细则中规定的其他情形。 期货交易所宣布进入异常情况并决定采取紧急措施前应当报告中国证监会。"},{"i":88,"n":"第八十八条","txt":"期货交易所宣布进入异常情况并决定暂停交易的，暂停交易的期限不得超过3个交易日，但经中国证监会批准延长的除外。"},{"i":89,"n":"第八十九条","txt":"期货交易所应当以适当方式发布下列信息： （一）即时行情； （二）持仓量、成交量排名情况； （三）期货交易所交易规则及其实施细则规定的其他信息。 期货交易涉及商品实物交割的，期货交易所还应当发布标准仓单数量和可用库容情况。"},{"i":90,"n":"第九十条","txt":"期货交易所应当编制交易情况周报表、月报表和年报表，并及时公布。"},{"i":91,"n":"第九十一条","txt":"期货交易所对期货交易、结算、交割资料的保存期限应当不少于20年。"},{"i":92,"n":"第九十二条","txt":"期货交易所制定或者修改章程、交易规则，上市、中止、取消或者恢复交易品种，应当经中国证监会批准。期货交易所上市、修改或者终止合约，应当事前向中国证监会报告。"},{"i":93,"n":"第九十三条","txt":"期货交易所应当对违反期货交易所交易规则及其实施细则的行为制定查处办法，并事前向中国证监会报告。 期货交易所对会员及其客户、指定交割仓库、期货保证金存管银行及期货市场其他参与者与期货业务有关的违规行为，应当在前款所称办法规定的职责范围内及时予以查处；超出前款所称办法规定的职责范围的，应当向中国证监会报告。"},{"i":94,"n":"第九十四条","txt":"期货交易所制定或者修改交易规则的实施细则，应当事前向中国证监会报告。"},{"i":95,"n":"第九十五条","txt":"期货交易所的交易结算系统和交易结算业务应当满足期货保证金安全存管监控的要求，真实、准确和完整地反映会员保证金的变动情况。"},{"i":96,"n":"第九十六条","txt":"期货交易所应当按照中国证监会有关期货保证金安全存管监控的规定，向期货保证金安全存管监控机构报送相关信息。"},{"i":97,"n":"第九十七条","txt":"公司制期货交易所收购本期货交易所股份、股东转让所持股份或者对其股份进行其他处置，应当按照中国证监会有关规定进行事前报告。"},{"i":98,"n":"第九十八条","txt":"期货交易所的高级管理人员应当具备中国证监会要求的条件。未经中国证监会批准，期货交易所的理事长、副理事长、董事长、副董事长、监事会主席、监事会副主席、总经理、副总经理、董事会秘书不得在任何营利性组织中兼职。 未经批准，期货交易所的其他工作人员和非会员理事不得以任何形式在期货交易所会员单位及其他与期货交易有关的营利性组织兼职。"},{"i":99,"n":"第九十九条","txt":"期货交易所工作人员应当自觉遵守有关法律、行政法规、规章和政策，恪尽职守，勤勉尽责，诚实信用，具有良好的职业操守。 期货交易所工作人员不得从事期货交易，不得泄漏内幕消息或者利用内幕消息获得非法利益，不得从期货交易所会员和客户处谋取利益。 期货交易所工作人员履行职务，遇有与本人或者其亲属有利害关系的情形时，应当回避。"},{"i":100,"n":"第一百条","txt":"期货交易所的所得收益按照国家有关规定管理和使用，但应当首先用于保证期货交易场所、设施的运行和改善。"},{"i":101,"n":"第一百零一条","txt":"期货交易所应当向中国证监会履行下列报告义务： （一）每一年度结束后4个月内提交符合规定的会计师事务所审计的年度财务报告； （二）每一季度结束后15日内、每一年度结束后30日内提交有关经营情况和有关法律、行政法规、规章、政策执行情况的季度和年度工作报告； （三）中国证监会规定的其他事项。"},{"i":102,"n":"第一百零二条","txt":"发生下列重大事项，期货交易所应当及时向中国证监会报告： （一）发现期货交易所工作人员存在或者可能存在严重违反国家有关法律、行政法规、规章、政策的行为； （二）期货交易所涉及占其净资产10%以上或者对其经营风险有较大影响的诉讼； （三）期货交易所的重大财务支出、投资事项以及可能带来较大财务或者经营风险的重大财务决策； （四）中国证监会规定的其他事项。"},{"i":103,"n":"第一百零三条","txt":"中国证监会可以根据市场情况调整期货交易所收取的保证金标准，暂停、恢复或者取消某一期货交易品种的交易。"},{"i":104,"n":"第一百零四条","txt":"中国证监会认为期货市场出现异常情况的，可以决定采取延迟开市、暂停交易、提前闭市等必要的风险处置措施。"},{"i":105,"n":"第一百零五条","txt":"中国证监会认为有必要的，可以对期货交易所高级管理人员实施提示。"},{"i":106,"n":"第一百零六条","txt":"中国证监会派出机构对期货交易所会员进行风险处置，采取监管措施的，经中国证监会批准，期货交易所应当在限制会员资金划转、限制会员开仓、移仓和强行平仓等方面予以配合。"},{"i":107,"n":"第一百零七条","txt":"中国证监会可以向期货交易所派驻督察员。督察员依照中国证监会的有关规定履行职责。 督察员履行职责，期货交易所应当予以配合。"},{"i":108,"n":"第一百零八条","txt":"期货交易所应当按照国家有关规定及时缴纳期货市场监管费。"},{"i":109,"n":"第一百零九条","txt":"期货交易所未按照本办法第十五条、第三十五条、第五十二条、第六十七条、第八十七条、第九十四条、第一百零一条和第一百零二条的规定履行报告义务，或者未按照本办法第二十三条、第三十条、第三十八条、第四十三条、第五十一条和第九十六条的规定报送有关文件、资料和信息的，根据《期货交易管理条例》第六十四条处罚。"},{"i":110,"n":"第一百一十条","txt":"期货交易所有下列行为之一的，根据《期货交易管理条例》第六十五条处罚： （一）未经报告变更名称或者注册资本； （二）未经批准设立分所或者其他任何交易场所； （三）违反有价证券作为保证金规定； （四）不按照规定对会员进行检查； （五）未建立或者未执行客户交易编码制度、保证金管理制度； （六）交易结算系统和交易结算业务不符合本办法第九十五条的规定。"},{"i":111,"n":"第一百一十一条","txt":"期货交易所工作人员违反本办法第九十九条规定的，根据《期货交易管理条例》第七十八条处罚。"},{"i":112,"n":"第一百一十二条","txt":"在中国证监会批准的其他交易场所进行期货交易的，依照本办法的有关规定执行。"},{"i":113,"n":"第一百一十三条","txt":"本办法自2007年4月15日起施行。2002年5月17日发布的《期货交易所管理办法》（中国证券监督管理委员会令第6号）同时废止。"}],"qihuocongyerenyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强期货从业人员的资格管理，规范期货从业人员的执业行为，根据《期货交易管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"申请期货从业人员资格（以下简称从业资格），从事期货经营业务的机构（以下简称机构）任用期货从业人员，以及期货从业人员从事期货业务的，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称机构是指： （一）期货公司； （二）期货交易所的非期货公司结算会员； （三）期货投资咨询机构； （四）为期货公司提供中间介绍业务的机构； （五）中国证券监督管理委员会（以下简称中国证监会）规定的其他机构。"},{"i":4,"n":"第四条","txt":"本办法所称期货从业人员是指： （一）期货公司的管理人员和专业人员； （二）期货交易所的非期货公司结算会员中从事期货结算业务的管理人员和专业人员； （三）期货投资咨询机构中从事期货投资咨询业务的管理人员和专业人员； （四）为期货公司提供中间介绍业务的机构中从事期货经营业务的管理人员和专业人员； （五）中国证监会规定的其他人员。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依法对期货从业人员进行监督管理。 中国期货业协会（以下简称协会）依法对期货从业人员实行自律管理，负责从业资格的认定、管理及撤销。"},{"i":6,"n":"第六条","txt":"协会负责组织从业资格考试。"},{"i":7,"n":"第七条","txt":"参加从业资格考试的，应当符合下列条件： （一）年满18周岁； （二）具有完全民事行为能力； （三）具有高中以上文化程度； （四）中国证监会规定的其他条件。"},{"i":8,"n":"第八条","txt":"通过从业资格考试的，取得协会颁发的从业资格考试合格证明。"},{"i":9,"n":"第九条","txt":"取得从业资格考试合格证明的人员从事期货业务的，应当事先通过其所在机构向协会申请从业资格。 未取得从业资格的人员，不得在机构中开展期货业务活动。"},{"i":10,"n":"第十条","txt":"机构任用具有从业资格考试合格证明且符合下列条件的人员从事期货业务的，应当为其办理从业资格申请： （一）品行端正，具有良好的职业道德； （二）已被本机构聘用； （三）最近3年内未受过刑事处罚或者中国证监会等金融监管机构的行政处罚； （四）未被中国证监会等金融监管机构采取市场禁入措施，或者禁入期已经届满； （五）最近3年内未因违法违规行为被撤销证券、期货从业资格； （六）中国证监会规定的其他条件。 机构不得任用无从业资格的人员从事期货业务，不得在办理从业资格申请过程中弄虚作假。"},{"i":11,"n":"第十一条","txt":"期货从业人员辞职、被解聘或者死亡的，机构应当自上述情形发生之日起10个工作日内向协会报告，由协会注销其从业资格。 机构的相关期货业务许可被注销的，由协会注销该机构中从事相应期货业务的期货从业人员的从业资格。"},{"i":12,"n":"第十二条","txt":"取得从业资格考试合格证明或者被注销从业资格的人员连续2年未在机构中执业的，在申请从业资格前应当参加协会组织的后续职业培训。"},{"i":13,"n":"第十三条","txt":"期货从业人员必须遵守有关法律、行政法规和中国证监会的规定，遵守协会和期货交易所的自律规则，不得从事或者协同他人从事欺诈、内幕交易、操纵期货交易价格、编造并传播有关期货交易的虚假信息等违法违规行为。"},{"i":14,"n":"第十四条","txt":"期货从业人员应当遵守下列执业行为规范： （一）诚实守信，恪尽职守，促进机构规范运作，维护期货行业声誉； （二）以专业的技能，谨慎、勤勉尽责地为客户提供服务，保守客户的商业秘密，维护客户的合法权益； （三）向客户提供专业服务时，充分揭示期货交易风险，不得作出不当承诺或者保证； （四）当自身利益或者相关方利益与客户的利益发生冲突或者存在潜在利益冲突时，及时向客户进行披露，并且坚持客户合法利益优先的原则； （五）具有良好的职业道德与守法意识，抵制商业贿赂，不得从事不正当竞争行为和不正当交易行为； （六）不得为迎合客户的不合理要求而损害社会公共利益、所在机构或者他人的合法权益； （七）不得以本人或者他人名义从事期货交易； （八）协会规定的其他执业行为规范。"},{"i":15,"n":"第十五条","txt":"期货公司的期货从业人员不得有下列行为： （一）进行虚假宣传，诱骗客户参与期货交易； （二）挪用客户的期货保证金或者其他资产； （三）中国证监会禁止的其他行为。"},{"i":16,"n":"第十六条","txt":"期货交易所的非期货公司结算会员的期货从业人员不得有下列行为： （一）利用结算业务关系及由此获得的结算信息损害非结算会员及其客户的合法权益； （二）代理客户从事期货交易； （三）中国证监会禁止的其他行为。"},{"i":17,"n":"第十七条","txt":"期货投资咨询机构的期货从业人员不得有下列行为： （一）利用传播媒介或者通过其他方式提供、传播虚假或者误导客户的信息； （二）代理客户从事期货交易； （三）中国证监会禁止的其他行为。"},{"i":18,"n":"第十八条","txt":"为期货公司提供中间介绍业务的机构的期货从业人员不得有下列行为： （一）收付、存取或者划转期货保证金； （二）代理客户从事期货交易； （三）中国证监会禁止的其他行为。"},{"i":19,"n":"第十九条","txt":"机构或者其管理人员对期货从业人员发出违法违规指令的，期货从业人员应当予以抵制，并及时按照所在机构内部程序向高级管理人员或者董事会报告。机构应当及时采取措施妥善处理。 机构未妥善处理的，期货从业人员应当及时向中国证监会或者协会报告。中国证监会和协会应当对期货从业人员的报告行为保密。 机构的管理人员及其他相关人员不得对期货从业人员的上述报告行为打击报复。"},{"i":20,"n":"第二十条","txt":"中国证监会指导和监督协会对期货从业人员的自律管理活动。"},{"i":21,"n":"第二十一条","txt":"协会应当建立期货从业人员信息数据库，公示并且及时更新从业资格注册、诚信记录等信息。 中国证监会及其派出机构履行监管职责，需要协会提供期货从业人员信息和资料的，协会应当按照要求及时提供。"},{"i":22,"n":"第二十二条","txt":"协会应当组织期货从业人员后续职业培训，提高期货从业人员的职业道德和专业素质。 期货从业人员应当按照有关规定参加后续职业培训，其所在机构应予以支持并提供必要保障。"},{"i":23,"n":"第二十三条","txt":"协会应当对期货从业人员的执业行为进行定期或者不定期检查，期货从业人员及其所在机构应当予以配合。"},{"i":24,"n":"第二十四条","txt":"期货从业人员违反本办法以及协会自律规则的，协会应当进行调查、给予纪律惩戒。 期货从业人员涉嫌违法违规需要中国证监会给予行政处罚的，协会应当及时移送中国证监会处理。"},{"i":25,"n":"第二十五条","txt":"协会应当设立专门的纪律惩戒及申诉机构，制订相关制度和工作规程，按照规定程序对期货从业人员进行纪律惩戒，并保障当事人享有申诉等权利。"},{"i":26,"n":"第二十六条","txt":"协会应当自对期货从业人员作出纪律惩戒决定之日起10个工作日内，向中国证监会及其有关派出机构报告，并及时在协会网站公示。"},{"i":27,"n":"第二十七条","txt":"期货从业人员受到机构处分，或者从事的期货业务行为涉嫌违法违规被调查处理的，机构应当在作出处分决定、知悉或者应当知悉该期货从业人员违法违规被调查处理事项之日起10个工作日内向协会报告。"},{"i":28,"n":"第二十八条","txt":"协会应当定期向中国证监会报告期货从业人员管理的有关情况。"},{"i":29,"n":"第二十九条","txt":"期货从业人员违反本办法规定的，中国证监会及其派出机构可以采取责令改正、监管谈话、出具警示函等监管措施。"},{"i":30,"n":"第三十条","txt":"期货从业人员自律管理的具体办法，包括从业资格考试、从业资格注册和公示、执业行为准则、后续职业培训、执业检查、纪律惩戒和申诉等，由协会制订，报中国证监会核准。"},{"i":31,"n":"第三十一条","txt":"未取得从业资格，擅自从事期货业务的，中国证监会责令改正，给予警告，单处或者并处3万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"有下列行为之一的，中国证监会根据《期货交易管理条例》第七十条处罚： （一）任用无从业资格的人员从事期货业务； （二）在办理从业资格申请过程中弄虚作假； （三）不履行本办法第二十三条规定的配合义务； （四）不按照本办法第二十七条的规定履行报告义务或者报告材料存在虚假内容。"},{"i":33,"n":"第三十三条","txt":"违反本办法第十九条的规定，对期货从业人员进行打击报复的，中国证监会根据《期货交易管理条例》第七十条、第八十一条处罚。"},{"i":34,"n":"第三十四条","txt":"期货从业人员违法违规的，中国证监会依法给予行政处罚。但因被迫执行违法违规指令而按照本办法第十九条第二款的规定履行了报告义务的，可以从轻、减轻或者免予行政处罚。"},{"i":35,"n":"第三十五条","txt":"协会工作人员不按本办法规定履行职责，徇私舞弊、玩忽职守或者故意刁难有关当事人的，协会应当给予纪律处分。"},{"i":36,"n":"第三十六条","txt":"本办法自公布之日起施行。2002年1月23日发布的《期货从业人员资格管理办法（修订）》（证监发[2002]6号）同时废止。"}],"qihuogongsiqihuotouzizixunyewushixingbanfa":[{"i":1,"n":"第一条","txt":"为了规范期货公司期货投资咨询业务活动，提高期货公司专业化服务能力，保护客户合法权益，促进期货市场更好地服务国民经济发展，根据《期货交易管理条例》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称期货公司期货投资咨询业务，是指期货公司基于客户委托从事的下列营利性活动： （一）协助客户建立风险管理制度、操作流程，提供风险管理咨询、专项培训等风险管理顾问服务； （二）收集整理期货市场信息及各类相关经济信息，研究分析期货市场及相关现货市场的价格及其相关影响因素，制作、提供研究分析报告或者资讯信息的研究分析服务； （三）为客户设计套期保值、套利等投资方案，拟定期货交易策略等交易咨询服务； （四）中国证券监督管理委员会（以下简称中国证监会）规定的其他活动。"},{"i":3,"n":"第三条","txt":"期货公司从事期货投资咨询业务，应当经中国证监会批准取得期货投资咨询业务资格；期货公司从事期货投资咨询业务的人员应当取得期货投资咨询业务从业资格。 未取得规定资格的期货公司及其从业人员不得从事期货投资咨询业务活动。"},{"i":4,"n":"第四条","txt":"期货公司及其从业人员从事期货投资咨询业务，应当遵守有关法律、法规、规章和本办法规定，遵循诚实信用原则，基于独立、客观的立场，公平对待客户，避免利益冲突。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依法对期货公司及其从业人员从事期货投资咨询业务实行监督管理。 中国期货业协会对期货公司及其从业人员从事期货投资咨询业务实行自律管理。"},{"i":6,"n":"第六条","txt":"期货公司申请从事期货投资咨询业务，应当具备下列条件： （一）注册资本不低于人民币1亿元，且净资本不低于人民币8000万元； （二）申请日前6个月的风险监管指标持续符合监管要求； （三）具有3年以上期货从业经历并取得期货投资咨询从业资格的高级管理人员不少于1名，具有2年以上期货从业经历并取得期货投资咨询从业资格的业务人员不少于5名，且前述高级管理人员和业务人员最近3年内无不良诚信记录，未受到行政、刑事处罚，且不存在因涉嫌违法违规正被有权机关调查的情形； （四）具有完备的期货投资咨询业务管理制度； （五）近3年内未因违法违规经营受到行政、刑事处罚，且不存在因涉嫌重大违法违规正被有权机关调查的情形； （六）近1年内不存在被监管机构采取《期货交易管理条例》第五十九条第二款、第六十条规定的监管措施的情形； （七）中国证监会根据审慎监管原则规定的其他条件。"},{"i":7,"n":"第七条","txt":"期货公司申请期货投资咨询业务资格，应当提交下列申请材料： （一）期货投资咨询业务资格申请书； （二）股东会关于申请期货投资咨询业务的决议文件； （三）申请日前6个月的期货公司风险监管报表； （四）期货投资咨询业务管理制度文本，内容包括部门和人员管理、业务操作、合规检查、客户回访与投诉等； （五）最近3年的期货公司合规经营情况说明； （六）拟从事期货投资咨询业务的高级管理人员和业务人员的名单、简历、相关任职资格和从业资格证明，以及公司出具的诚信合规证明材料； （七）加盖公司公章的《企业法人营业执照》复印件、《经营期货业务许可证》复印件； （八）经具有证券、期货相关业务资格的会计师事务所审计的前一年度财务报告；申请日在下半年的，还应当提供经审计的半年度财务报告； （九）律师事务所就期货公司是否符合本办法第六条第（三）、（五）项规定的条件，以及股东会决议是否合法出具的法律意见书； （十）中国"},{"i":8,"n":"第八条","txt":"中国证监会自受理期货公司期货投资咨询业务资格申请之日起2个月内，作出批准或者不予批准的决定。"},{"i":9,"n":"第九条","txt":"中国期货业协会负责期货投资咨询业务从业人员的资格考试、资格认定、日常管理等相关工作，相关自律管理办法由中国期货业协会制定。"},{"i":10,"n":"第十条","txt":"期货公司及其从业人员应当以专业的技能，谨慎、勤勉、尽责地为客户提供期货投资咨询服务，保守客户的商业秘密，维护客户合法权益。 期货公司及其从业人员不得对期货投资咨询服务能力进行虚假、误导性的宣传，不得欺诈或者误导客户。"},{"i":11,"n":"第十一条","txt":"期货公司应当按照信息公示有关规定，在营业场所、公司网站和中国期货业协会网站上公示公司的业务资格、人员的从业资格、服务内容、投诉方式等相关信息。"},{"i":12,"n":"第十二条","txt":"期货公司开展期货投资咨询业务活动，应当遵循具体的业务操作规范，并应与自身的管理能力、业务水平和人员配置相适应，有效执行期货投资咨询业务管理制度，加强合规检查，防范业务风险。"},{"i":13,"n":"第十三条","txt":"期货公司及其从业人员在开展期货投资咨询服务时，不得从事下列行为： （一）向客户做获利保证，或者约定分享收益或共担风险； （二）以虚假信息、市场传言或者内幕信息为依据向客户提供期货投资咨询服务； （三）利用期货投资咨询活动操纵期货交易价格、进行内幕交易，或者传播虚假、误导性信息； （四）以个人名义收取服务报酬； （五）期货法规、规章禁止的其他行为。 期货投资咨询业务人员在开展期货投资咨询服务时，不得接受客户委托代为从事期货交易。"},{"i":14,"n":"第十四条","txt":"期货公司应当事前了解客户的身份、财务状况、投资经验等情况，认真评估客户的风险偏好、风险承受能力和服务需求，并以书面和电子形式保存客户相关信息。 期货公司应当针对客户期货投资咨询具体服务需求，揭示期货市场风险，明确告知客户独立承担期货市场风险。"},{"i":15,"n":"第十五条","txt":"期货公司应当与客户签订期货投资咨询服务合同，明确约定服务的具体内容和费用标准等相关事项。 期货投资咨询服务合同指引和风险揭示书格式，由中国期货业协会制定。"},{"i":16,"n":"第十六条","txt":"期货公司提供风险管理服务时，应当发挥自身专业优势，为客户制定符合其需要的风险管理制度或者操作流程，提供有针对性的风险管理咨询或者培训，不得夸大期货的风险管理功能。 期货公司应当定期评估风险管理服务效果和客户反馈意见，不断改进风险管理服务能力。"},{"i":17,"n":"第十七条","txt":"期货公司提供研究分析服务时，应当公平对待委托客户，并采取有效措施，保证研究分析人员独立形成研究分析意见和结论。 期货公司应当建立研究分析报告和资讯信息的审阅、管理及使用机制，对研究分析报告、资讯信息的使用进行审阅和合规检查。 期货公司应当采取有效措施，防止研究分析人员以及公司内部其他人员利用研究报告、资讯信息为自身及其他利益相关方谋取不当利益。"},{"i":18,"n":"第十八条","txt":"研究分析人员应当对研究分析报告的内容和观点负责，保证信息来源合法合规，研究方法专业审慎，分析结论合理。 研究分析报告应当制作形成适当的书面或者电子文本形式，载明期货公司名称及其业务资格、研究分析人员姓名、从业证号、制作日期等内容，同时注明相关信息资料的来源、研究分析意见的局限性与使用者风险提示。 期货公司制作、提供的研究分析报告不得侵犯他人的知识产权。"},{"i":19,"n":"第十九条","txt":"期货公司提供交易咨询服务时，应当向客户明示有无利益冲突，提示潜在的市场变化和投资风险，不得就市场行情做出确定性判断。 期货公司提供的投资方案或者期货交易策略应当以本公司的研究报告、合法取得的研究报告、相关行业信息资料以及公开发布的相关信息等为主要依据。 期货公司应当告知客户自主做出期货交易决策，独立承担期货交易后果，并不得泄露客户的投资决策计划信息。"},{"i":20,"n":"第二十条","txt":"期货公司以期货交易软件、终端设备为载体，向客户提供交易咨询服务或者具有类似功能服务的，应当执行本办法，并向客户说明交易软件、终端设备的基本功能，揭示使用局限性，说明相关数据信息来源，不得对交易软件、终端设备的使用价值或功能作出虚假、误导性宣传。"},{"i":21,"n":"第二十一条","txt":"期货公司应当对期货投资咨询业务操作实行留痕管理，并按照中国证监会规定的保存年限和要求，妥善保存期货投资咨询业务的风险揭示书、合同、风险管理意见、研究分析报告、交易咨询建议、期货交易软件或者终端设备说明等业务材料。"},{"i":22,"n":"第二十二条","txt":"期货公司应当有效执行期货投资咨询业务管理制度中的客户回访与投诉规定，明确客户回访与投诉的内容、要求、程序，及时、妥善处理客户投诉事项。"},{"i":23,"n":"第二十三条","txt":"期货公司应当制定防范期货投资咨询业务与其他期货业务之间利益冲突的管理制度，建立健全信息隔离机制，并保持办公场所和办公设备相对独立。 期货投资咨询业务活动之间可能发生利益冲突的，期货公司应当作出必要的岗位独立、信息隔离和人员回避等工作安排。 期货公司首席风险官应当对前款规定事项进行检查落实。"},{"i":24,"n":"第二十四条","txt":"期货公司及其从业人员与客户之间可能发生利益冲突的，应当遵循客户利益优先的原则予以处理；不同客户之间存在利益冲突的，应当遵循公平对待的原则予以处理。"},{"i":25,"n":"第二十五条","txt":"期货公司总部应当设立独立的部门，对期货投资咨询业务实行统一管理。 期货公司营业部应当在公司总部的统一管理下对外提供期货投资咨询服务。"},{"i":26,"n":"第二十六条","txt":"期货投资咨询业务人员应当以期货公司名义开展期货投资咨询业务活动，不得以个人名义为客户提供期货投资咨询服务。"},{"i":27,"n":"第二十七条","txt":"期货投资咨询业务人员应当与交易、结算、风险控制、财务、技术等业务人员岗位独立，职责分离。"},{"i":28,"n":"第二十八条","txt":"期货公司应当按照规定的内容与格式要求，每月向住所地中国证监会派出机构报送期货投资咨询业务信息。"},{"i":29,"n":"第二十九条","txt":"期货公司首席风险官负责监督期货投资咨询业务管理制度的制定和执行，对期货投资咨询业务的合规性定期检查，并依法履行督促整改和报告职责。 期货公司首席风险官向住所地中国证监会派出机构报送的季度报告、年度报告中，应当包括本公司期货投资咨询业务的合规性及其检查情况，并重点就防范利益冲突作出说明。"},{"i":30,"n":"第三十条","txt":"中国证监会及其派出机构按照审慎监管原则，定期或者不定期对期货公司期货投资咨询业务进行检查。"},{"i":31,"n":"第三十一条","txt":"期货公司未取得规定资格从事期货投资咨询业务活动的，或者任用不具备相应资格的人员从事期货投资咨询业务活动的，责令改正；情节严重的，根据《期货交易管理条例》第七十条的规定处罚。"},{"i":32,"n":"第三十二条","txt":"期货公司或其从业人员开展期货投资咨询业务出现下列情形之一的，中国证监会及其派出机构可以针对具体情况，根据《期货交易管理条例》第五十九条的规定采取相应监管措施： （一）对期货投资咨询服务能力进行虚假、误导性宣传，欺诈或者误导客户； （二）高级管理人员缺位或者业务部门人员低于规定要求； （三）以个人名义为客户提供期货投资咨询服务； （四）违反本办法第十三条规定； （五）未按照规定建立防范利益冲突的管理制度、机制； （六）未有效执行防范利益冲突管理制度、机制且处置失当，导致发生重大利益冲突事件； （七）利用研究报告、资讯信息为自身及其他利益相关方谋取不当利益； （八）其他不符合本办法规定的情形。 期货公司或其从业人员出现前款所列情形之一，情节严重的，根据《期货交易管理条例》第七十条、第七十一条、第七十三条、第七十四条相关规定处罚；涉嫌犯罪的，依法移送司法机关。"},{"i":33,"n":"第三十三条","txt":"期货公司基于期货经纪业务向客户提供咨询、培训等附属服务的，应当遵守期货法规、规章的相关规定。"},{"i":34,"n":"第三十四条","txt":"期货公司及其从业人员通过报刊、电视、电台和网络等公共媒体开展期货行情分析等信息传播活动的，应当取得期货投资咨询业务资格及从业资格，遵守金融信息传播相关规定，保护他人的知识产权；在开展期货信息传播活动前，期货公司及其从业人员应当向住所地的中国证监会派出机构备案。"},{"i":35,"n":"第三十五条","txt":"证券经营机构从事期货投资咨询业务活动的资格条件和监管要求等由中国证监会另行规定。"},{"i":36,"n":"第三十六条","txt":"本办法自2011年5月1日起施行。"}],"qihuogongsijianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范期货公司经营活动，加强对期货公司监督管理，保护客户合法权益，推进期货市场建设，根据《公司法》和《期货交易管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立的期货公司，适用本办法。"},{"i":3,"n":"第三条","txt":"期货公司应当遵守法律、行政法规和中国证券监督管理委员会（以下简称中国证监会）的规定，审慎经营，防范利益冲突，履行对客户的诚信义务。"},{"i":4,"n":"第四条","txt":"期货公司的股东、实际控制人和其他关联人不得滥用权利，不得占用期货公司资产或者挪用客户资产，不得侵害期货公司、客户的合法权益。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依法对期货公司及其分支机构实行监督管理。 中国期货业协会、期货交易所按照自律规则对期货公司实行自律管理。 期货保证金安全存管监控机构依法对客户保证金安全实施监控。"},{"i":6,"n":"第六条","txt":"申请设立期货公司，除应当符合《期货交易管理条例》第十六条规定的条件外，还应当具备下列条件： （一）注册资本不低于人民币1亿元； （二）具有期货从业人员资格的人员不少于15人； （三）具备任职条件的高级管理人员不少于3人。"},{"i":7,"n":"第七条","txt":"期货公司主要股东为法人或者非法人组织的，应当具备下列条件： （一）实收资本和净资产均不低于人民币1亿元； （二）净资产不低于实收资本的50%，或有负债低于净资产的50%，不存在对财务状况产生重大不确定影响的其他风险； （三）具备持续盈利能力，持续经营3个以上完整的会计年度，最近3个会计年度连续盈利； （四）出资额不得超过其净资产，且资金来源真实合法，不得以委托资金、负债资金等入股期货公司； （五）信誉良好、公司治理规范、组织架构清晰、股权结构透明，主营业务性质与期货公司具有相关性； （六）没有较大数额的到期未清偿债务； （七）近3年未因重大违法违规行为受到行政处罚或者刑事处罚； （八）未因涉嫌重大违法违规正在被有权机关立案调查或者采取强制措施； （九）近3年作为公司（含金融机构）的股东或者实际控制人，未有滥用股东权利、逃避股东义务等不诚信行为； （十）不存在中国证监会根据审慎监管原则认"},{"i":8,"n":"第八条","txt":"期货公司主要股东为自然人的，除应当符合本办法第七条第（四）项、第（六）项至第（十）项规定的条件外，还应当具备下列条件： （一）个人金融资产不低于人民币3000万元； （二）信誉良好，不存在对所投资企业经营失败或重大违法违规行为负有直接责任未逾3年的情形。 间接持有期货公司5%以上股权的自然人应当符合前款规定。"},{"i":9,"n":"第九条","txt":"期货公司控股股东、第一大股东除应当符合本办法第七条、第八条规定的条件外，还应当具备下列条件： （一）净资本不低于人民币5亿元；股东不适用净资本或者类似指标的，净资产不低于人民币10亿元； （二）在技术能力、管理服务、人员培训或营销渠道等方面具有较强优势； （三）具备对期货公司持续的资本补充能力，对期货公司可能发生风险导致无法正常经营的情况具有妥善处置的能力； （四）中国证监会根据审慎监管原则规定的其他条件。"},{"i":10,"n":"第十条","txt":"非金融企业入股期货公司成为主要股东或者控股股东、第一大股东的，除应当符合本办法第七条、第九条规定的相关条件外，还应当具备下列条件： （一）符合国家关于加强非金融企业投资金融机构监管的有关规定和相关指导意见； （二）中国证监会根据审慎监管原则规定的其他条件。"},{"i":11,"n":"第十一条","txt":"期货公司主要股东、控股股东、第一大股东为境外股东的，除应当符合本办法第七条、第九条规定的条件外，还应当具备下列条件： （一）依其所在国家或者地区法律设立、合法存续的金融机构； （二）近3年各项财务指标及监管指标符合所在国家或者地区法律的规定和监管机构的要求； （三）所在国家或者地区具有完善的期货法律和监督管理制度，其期货监管机构已与中国证监会签订监管合作备忘录，并保持有效的监管合作关系； （四）期货公司外资持股比例或者拥有的权益比例，累计（包括直接持有和间接持有）不得超过我国期货业对外或者对我国香港特别行政区、澳门特别行政区和台湾地区开放所作的承诺。 境外股东应当以可自由兑换货币或者合法取得的人民币出资。 （五）中国证监会根据审慎监管原则规定的其他条件。"},{"i":12,"n":"第十二条","txt":"期货公司有关联关系的股东持股比例合计达到5%的，持股比例最高的股东应当符合本办法第七条、第八条和第十一条规定的条件。 期货公司有关联关系的股东、一致行动人持股比例合计达到成为期货公司控股股东、第一大股东的，持股比例最高的股东应当符合本办法第九条、第十一条规定的条件。涉及的非金融企业股东应当符合本办法第十条、第十一条规定的条件。"},{"i":13,"n":"第十三条","txt":"申请设立期货公司，应当向中国证监会提交下列申请材料： （一）申请书； （二）发起协议； （三）非自然人股东按照其自身决策程序同意出资设立期货公司的决定文件； （四）公司章程草案； （五）经营计划； （六）发起人名单及其最近3年经会计师事务所审计的财务报告或者个人金融资产证明以及不存在对所投资企业经营失败或重大违法违规行为负有直接责任未逾3年的说明； （七）拟任用高级管理人员和从业人员名单、简历、相关任职条件证明和相关资格证书； （八）拟订的期货业务制度、内部控制制度和风险管理制度文本； （九）场地、设备、资金来源证明文件； （十）股权结构及股东间关联关系、一致行动人关系的说明； （十一）资本补充方案及风险处置预案； （十二）律师事务所出具的法律意见书； （十三）中国证监会规定的其他申请材料。 期货公司单个境外股东的持股比例或者有关联关系的境外股东合计持股比例达到5%以上的，还应当提交下"},{"i":14,"n":"第十四条","txt":"外资持有股权的期货公司，应当按照法律、行政法规的规定，向国务院商务主管部门和外汇管理部门申请办理相关手续。"},{"i":15,"n":"第十五条","txt":"按照本办法设立的期货公司，可以依法从事商品期货经纪业务；从事金融期货经纪、境外期货经纪、期货投资咨询的，应当取得相应业务资格。从事资产管理业务的，应当依法登记备案。 期货公司经批准或者备案可以从事中国证监会规定的其他业务。"},{"i":16,"n":"第十六条","txt":"期货公司申请金融期货经纪业务资格，应当具备下列条件： （一）申请日前2个月风险监管指标持续符合规定标准； （二）具有健全的公司治理、风险管理制度和内部控制制度，并有效执行； （三）符合中国证监会期货保证金安全存管监控的规定； （四）业务设施和技术系统符合相关技术规范且运行状况良好； （五）高级管理人员近2年内未受到刑事处罚，未因违法违规经营受到行政处罚，无不良信用记录，且不存在因涉嫌违法违规经营正在被有权机关调查的情形； （六）不存在被中国证监会及其派出机构采取《期货交易管理条例》第五十五条第二款、第五十六条规定的监管措施的情形； （七）不存在因涉嫌违法违规正在被有权机关立案调查的情形； （八）近2年内未因违法违规行为受过刑事处罚或者行政处罚。但期货公司控股股东或者实际控制人变更，高级管理人员变更比例超过50%，对出现上述情形负有责任的高级管理人员和业务负责人已不在公司任职，且已整改完"},{"i":17,"n":"第十七条","txt":"期货公司申请金融期货经纪业务资格，应当向中国证监会提交下列申请材料： （一）申请书； （二）加盖公司公章的营业执照和业务许可证复印件； （三）股东会或者董事会决议文件； （四）申请日前2个月风险监管报表； （五）公司治理、风险管理制度和内部控制制度执行情况报告； （六）业务设施和技术系统运行情况报告，以及信息系统内部审计报告等网络安全相关材料； （七）律师事务所出具的法律意见书； （八）若存在本办法第十六条第（八）项规定情形的，还应提供期货公司住所地中国证监会派出机构出具的整改验收合格意见书； （九）中国证监会规定的其他申请材料。"},{"i":18,"n":"第十八条","txt":"期货公司申请境外期货经纪、期货投资咨询以及经批准或者备案的其他业务的条件，由中国证监会另行规定。"},{"i":19,"n":"第十九条","txt":"期货公司变更股权有下列情形之一的，应当经中国证监会批准： （一）变更控股股东、第一大股东； （二）单个股东的持股比例或者有关联关系的股东合计持股比例增加到5%以上，且涉及境外股东的。 除前款规定情形外，期货公司单个股东的持股比例或者有关联关系的股东合计持股比例增加到5%以上，应当经期货公司住所地中国证监会派出机构批准。"},{"i":20,"n":"第二十条","txt":"期货公司变更股权有本办法第十九条所列情形的，应当具备下列条件： （一）拟变更的股权不存在被冻结等情形； （二）期货公司与股东之间不存在交叉持股的情形，期货公司不存在为股权受让方提供任何形式财务支持的情形； （三）涉及的股东符合本办法第七条至第十二条规定的条件。"},{"i":21,"n":"第二十一条","txt":"期货公司变更股权，有本办法第十九条所列情形的，应当提交下列相关申请材料： （一）申请书； （二）关于变更股权的决议文件； （三）股权转让或者变更出资合同，以及有限责任公司其他股东放弃优先购买权的承诺书； （四）所涉及股东的基本情况报告、变更后期货公司股东股权背景情况图以及期货公司关于变更后股东是否存在关联关系、期货公司是否为股权受让方提供任何形式财务支持的情况说明； （五）所涉及股东的股东会、董事会或者其他决策机构做出的相关决议； （六）所涉及股东的最近3年经会计师事务所审计的财务报告或者个人金融资产证明以及不存在对所投资企业经营失败或重大违法违规行为负有直接责任未逾3年的说明； （七）律师事务所出具的法律意见书； （八）中国证监会规定的其他材料。 期货公司单个境外股东的持股比例或者有关联关系的境外股东合计持股比例增加到5%以上的，还应当提交本办法第十三条第二款所规定的申请材料。 存在"},{"i":22,"n":"第二十二条","txt":"期货公司股东应当秉承长期投资理念，依法行使股东权利，履行股东义务，督促期货公司完善治理结构、风险管理与内部控制制度，实现持续、健康发展。"},{"i":23,"n":"第二十三条","txt":"期货公司拟入股股东应当充分了解期货公司股东条件、权利和义务，入股期货公司的程序应当完备合法，不得存在损害期货公司其他股东或者客户的合法权益以及通过隐瞒等方式规避期货公司股东资格审批或者监管的情况。"},{"i":24,"n":"第二十四条","txt":"期货公司股权出让方在股权转让期间，应当支持并配合期货公司董事会、监事会和高级管理人员依法履行职责，不得在股权转让完成前推荐股权受让方相关人员担任期货公司董事、监事、高级管理人员。 期货公司股东出让股权依法应经中国证监会批准的，在批准前，股权出让方应当继续独立行使表决权及其他股东权利，不得以任何形式变相让渡表决权予股权受让方。"},{"i":25,"n":"第二十五条","txt":"期货公司变更法定代表人，拟任法定代表人应当具备任职条件。期货公司应当自完成相关工商变更登记之日起5个工作日内向住所地中国证监会派出机构提交下列备案材料： （一）备案报告； （二）变更后的营业执照副本复印件； （三）公司决议文件； （四）法定代表人期货从业资格证书、任职条件证明； （五）期货公司原《经营证券期货业务许可证》正、副本原件； （六）中国证监会要求提交的其他文件。"},{"i":26,"n":"第二十六条","txt":"期货公司变更住所或营业场所，应当妥善处理客户资产，拟迁入的住所和拟使用的设施应当符合业务需要，并自完成相关工商变更登记之日起5个工作日内向住所地中国证监会派出机构报备。期货公司在中国证监会不同派出机构辖区变更住所的，还应当符合下列条件： （一）符合持续性经营规则； （二）近2年未因重大违法违规行为受到行政处罚或者刑事处罚； （三）中国证监会根据审慎监管原则规定的其他条件。"},{"i":27,"n":"第二十七条","txt":"期货公司变更住所或营业场所，应当向拟迁入地中国证监会派出机构提交下列备案材料： （一）备案报告； （二）变更后的营业执照副本复印件； （三）公司决议文件； （四）关于客户资产处理情况，变更后住所和使用的设施符合期货业务需要的说明； （五）变更后住所所有权或者使用权证明； （六）首席风险官出具的公司符合相关条件的意见； （七）期货公司原《经营证券期货业务许可证》正、副本原件； （八）中国证监会要求提交的其他文件。 期货公司在提交备案材料时，应当将备案材料同时抄报拟迁出地中国证监会派出机构。"},{"i":28,"n":"第二十八条","txt":"期货公司设立营业部、分公司等境内分支机构，应当自完成相关工商设立登记之日起5个工作日内向公司住所地中国证监会派出机构报备。 期货公司设立境内分支机构，应当具备下列条件： （一）公司治理健全，内部控制制度符合有关规定并有效执行； （二）申请日前3个月符合风险监管指标标准； （三）符合有关客户资产保护和期货保证金安全存管监控的规定； （四）未因涉嫌违法违规经营正在被有权机关调查，近1年内未因违法违规经营受到行政处罚或者刑事处罚； （五）具有符合业务发展需要的分支机构设立方案和稳定的经营计划； （六）中国证监会根据审慎监管原则规定的其他条件。"},{"i":29,"n":"第二十九条","txt":"期货公司设立境内分支机构，应当向公司住所地中国证监会派出机构提交下列备案材料： （一）备案报告； （二）分支机构营业执照副本复印件； （三）公司决议文件； （四）分支机构负责人任职条件证明； （五）分支机构从业人员名册及期货从业资格证书； （六）营业场所所有权或者使用权证明； （七）首席风险官出具的公司符合相关条件的意见； （八）中国证监会要求提交的其他文件。 期货公司在提交备案材料时，应当将备案材料同时抄报拟设立分支机构所在地的中国证监会派出机构。"},{"i":30,"n":"第三十条","txt":"期货公司变更分支机构营业场所的，应当妥善处理客户资产，拟迁入的营业场所和拟使用的设施应当满足业务需要。 本办法所称期货公司变更分支机构营业场所仅限于在中国证监会同一派出机构辖区内变更营业场所。"},{"i":31,"n":"第三十一条","txt":"期货公司终止境内分支机构的，应当先行妥善处理该分支机构客户资产，结清分支机构业务并终止经营活动，并自完成上述工作之日起5个工作日内向分支机构所在地中国证监会派出机构提交下列备案材料： （一）备案报告； （二）公司决议文件； （三）关于处理分支机构客户资产、结清期货业务并终止经营活动情况的说明； （四）在中国证监会指定报刊上的公告证明； （五）首席风险官出具的公司符合相关条件的意见； （六）期货公司分支机构《经营证券期货业务许可证》正、副本原件； （七）中国证监会要求提交的其他文件。 期货公司在提交备案材料时，应当将备案材料同时抄报公司住所地的中国证监会派出机构。"},{"i":32,"n":"第三十二条","txt":"期货公司设立、收购、参股境外经营机构，应当具备下列条件，并应当自公司决议生效之日起5个工作日内向中国证监会报备： （一）申请日前6个月符合风险监管指标标准； （二）最近一次期货公司分类监管评级不低于B类BB级； （三）近3年内未因重大违法违规行为受到行政处罚或者刑事处罚，近1年未因治理结构不健全、内部控制不完善等原因被采取监管措施，不存在因涉嫌重大违法违规行为正在被立案调查或者正处于整改期间的情形； （四）具有完备的境外机构管理制度，能够有效隔离风险； （五）拟设立、收购或者参股机构所在国家或者地区的期货监管机构已与中国证监会签署监管合作备忘录； （六）中国证监会根据审慎监管原则规定的其他条件。"},{"i":33,"n":"第三十三条","txt":"期货公司设立、收购、参股境外经营机构，应当自获得境外有关监管机构核准文件之日起5个工作日内向中国证监会提交下列备案材料： （一）备案报告； （二）境外经营机构的章程； （三）境外有关监管机构核准文件； （四）中国证监会要求的其他资料。 期货公司变更境外经营机构注册资本或股权以及终止境外经营机构的，应当自获得境外有关监管机构核准文件之日起5个工作日内向中国证监会提交下列备案材料： （一）备案报告； （二）最近一年经具有证券、期货相关业务资格的会计师事务所审计的境外经营机构的财务报告； （三）中国证监会要求的其他资料。"},{"i":34,"n":"第三十四条","txt":"期货公司申请设立、收购或者参股境外经营机构，应当按照外汇管理部门相关规定办理有关手续。"},{"i":35,"n":"第三十五条","txt":"期货公司因遭遇不可抗力等正当事由申请停业的，应当妥善处理客户资产，清退或者转移客户。 期货公司恢复营业的，应当符合期货公司持续性经营规则。停业期限届满后，期货公司未能恢复营业或者不符合持续性经营规则的，中国证监会可以根据《期货交易管理条例》第二十条第一款规定注销其期货业务许可证。"},{"i":36,"n":"第三十六条","txt":"期货公司停业的，应当向中国证监会提交下列申请材料： （一）申请书； （二）停业决议文件； （三）关于处理客户资产、处置或者清退客户情况的报告； （四）中国证监会规定的其他材料。"},{"i":37,"n":"第三十七条","txt":"期货公司被撤销所有期货业务许可的，应当妥善处理客户资产，结清期货业务；公司继续存续的，应当依法办理名称、营业范围和公司章程等工商变更登记，存续公司不得继续以期货公司名义从事业务，其名称中不得有“期货”或者近似字样。 期货公司解散、破产的，应当先行妥善处理客户资产，结清业务。"},{"i":38,"n":"第三十八条","txt":"期货公司设立、变更、停业、解散、破产、被撤销期货业务许可或者其分支机构设立、变更、终止的，期货公司应当在中国证监会指定的媒体上公告。"},{"i":39,"n":"第三十九条","txt":"期货公司及其分支机构的许可证由中国证监会统一印制。许可证正本或者副本遗失或者灭失的，期货公司应当在30个工作日内在中国证监会指定的媒体上声明作废，并持登载声明向中国证监会或期货公司分支机构所在地派出机构重新申领。"},{"i":40,"n":"第四十条","txt":"期货公司应当按照明晰职责、强化制衡、加强风险管理的原则，建立并完善公司治理。"},{"i":41,"n":"第四十一条","txt":"期货公司与其股东、实际控制人及其他关联人在业务、人员、资产、财务等方面应当严格分开，独立经营，独立核算。 未依法经期货公司股东会或者董事会决议，期货公司股东、实际控制人不得任免期货公司的董事、监事、高级管理人员，或者非法干预期货公司经营管理活动。 期货公司向股东、实际控制人及其关联人提供服务的，不得降低风险管理要求。"},{"i":42,"n":"第四十二条","txt":"期货公司应当加强关联交易管理，准确识别关联方，严格落实关联交易审批和信息披露制度，及时向公司住所地中国证监会派出机构报告关联交易情况。 期货公司股东、实际控制人和其他关联人应当遵守法律、行政法规和中国证监会关于关联交易的相关规定，不得与期货公司进行不当的关联交易，不得利用其对期货公司经营管理的影响力获取不当利益。"},{"i":43,"n":"第四十三条","txt":"期货公司控股股东、第一大股东应当每年对自身遵守法律法规及监管规定情况、经营状况、履行对期货公司承诺事项和期货公司章程的情况进行自查自评，每年度结束之日起4个月内将评估报告通过期货公司报送期货公司住所地中国证监会派出机构。"},{"i":44,"n":"第四十四条","txt":"期货公司主要股东或者实际控制人出现下列情形之一的，应当主动、准确、完整地在3个工作日内通知期货公司： （一）所持有的期货公司股权被冻结或者被强制执行； （二）质押或解除质押所持有的期货公司股权； （三）决定转让所持有的期货公司股权； （四）不能正常行使股东权利或者承担股东义务，可能造成期货公司治理的重大缺陷； （五）股权变更或者业务范围、经营管理发生重大变化； （六）董事长、总经理或者代为履行相应职务的董事、高级管理人员等发生变动； （七）因国家法律法规、重大政策调整或者不可抗力等因素，可能对公司经营管理产生重大不利影响； （八）涉嫌重大违法违规被有权机关调查或者采取强制措施； （九）因重大违法违规行为受到行政处罚或者刑事处罚； （十）变更名称； （十一）合并、分立或者进行重大资产、债务重组； （十二）被采取停业整顿、撤销、接管、托管等监管措施，或者进入解散、破产、关闭程序； （十三）"},{"i":45,"n":"第四十五条","txt":"期货公司有下列情形之一的，应当立即书面通知全体股东或进行公告，并向住所地中国证监会派出机构报告： （一）公司或者其董事、监事、高级管理人员因涉嫌违法违规被有权机关立案调查或者采取强制措施； （二）公司或者其董事、监事、高级管理人员因违法违规行为受到行政处罚或者刑事处罚； （三）风险监管指标不符合规定标准； （四）客户发生重大透支、穿仓，可能影响期货公司持续经营； （五）发生突发事件，对期货公司或者客户利益产生或者可能产生重大不利影响； （六）其他可能影响期货公司持续经营的情形。 中国证监会及其派出机构对期货公司及其分支机构采取《期货交易管理条例》第五十五条第二款、第四款或者第五十六条规定的监管措施或者作出行政处罚，期货公司应当书面通知全体股东或进行公告。"},{"i":46,"n":"第四十六条","txt":"期货公司股东会或股东大会应当按照《公司法》和公司章程，对职权范围内的事项进行审议和表决。股东会或股东大会每年应当至少召开一次会议。期货公司股东应当按照出资比例或者所持股份比例行使表决权。"},{"i":47,"n":"第四十七条","txt":"期货公司应当设立董事会，并按照《公司法》的规定设立监事会或监事，切实保障监事会和监事对公司经营情况的知情权。 期货公司可以设立独立董事，期货公司的独立董事不得在期货公司担任董事会以外的职务，不得与本期货公司存在可能妨碍其作出独立、客观判断的关系。"},{"i":48,"n":"第四十八条","txt":"期货公司应当设首席风险官，对期货公司经营管理行为的合法合规性、风险管理进行监督、检查。 首席风险官发现涉嫌占用、挪用客户保证金等违法违规行为或者可能发生风险的，应当立即向住所地中国证监会派出机构和公司董事会报告。 期货公司拟解聘首席风险官的，应当有正当理由，并向住所地中国证监会派出机构报告。"},{"i":49,"n":"第四十九条","txt":"期货公司的董事长、总经理、首席风险官之间不得存在近亲属关系。"},{"i":50,"n":"第五十条","txt":"期货公司应当合理设置业务部门及其职能，建立岗位责任制度，不相容岗位应当分离。交易、结算、财务业务应当由不同部门和人员分开办理。 期货公司应当设立风险管理部门或者岗位，管理和控制期货公司的经营风险。 期货公司应当设立合规审查部门或者岗位，审查和稽核期货公司经营管理的合法合规性。"},{"i":51,"n":"第五十一条","txt":"期货公司应当建立健全并持续完善覆盖境内外分支机构、子公司及其业务的合规管理、风险管理和内部控制体系，贯穿决策、执行、监督、反馈等各个环节，实现风险管理全覆盖。"},{"i":52,"n":"第五十二条","txt":"期货公司应当对分支机构实行集中统一管理，不得与他人合资、合作经营管理分支机构，不得将分支机构承包、租赁或者委托给他人经营管理。 分支机构经营的业务不得超出期货公司的业务范围，并应当符合中国证监会对相关业务的规定。 期货公司应当按照规定对分支机构实行统一结算、统一风险管理、统一资金调拨、统一财务管理和会计核算。"},{"i":53,"n":"第五十三条","txt":"期货公司设立、收购、参股的境外经营机构发生下列事项的，期货公司应当在5个工作日内向公司住所地中国证监会派出机构书面报告： （一）注册登记、取得业务资格、设立子公司； （二）变更名称、变更业务范围以及修改章程重要条款等； （三）取得、变更或者注销交易所、协会等会员资格； （四）变更董事长、总经理、合规负责人和风险管理负责人； （五）机构或其从业人员受到境外监管机构或交易所的调查、纪律处分或处罚； （六）预计发生重大亏损或者遭受超过净资产10％的重大损失； （七）与期货公司及其关联方发生重大关联交易； （八）按规定应当向境外监管机构报告的重大事项； （九）中国证监会规定的其他重大事项。"},{"i":54,"n":"第五十四条","txt":"期货公司应当在每月结束之日起7个工作日内报送设立、收购的境外经营机构的上一月度主要财务数据及业务情况。 期货公司应当在每会计年度结束之日起4个月内报送上一年度境外经营机构经审计的财务报告、审计报告以及年度工作报告，年度工作报告的内容包括但不限于：持牌情况、业务开展情况、财务状况、下属机构以及被境外监管机构采取监管措施或处罚等情况。"},{"i":55,"n":"第五十五条","txt":"期货公司可以按照规定，运用自有资金投资于股票、投资基金、债券等金融类资产，与业务相关的股权以及中国证监会规定的其他业务，但不得从事《期货交易管理条例》禁止的业务。"},{"i":56,"n":"第五十六条","txt":"期货公司应当建立并有效执行风险管理、内部控制、期货保证金存管等业务制度和流程，有效隔离不同业务之间的风险，确保客户资产安全和交易安全。"},{"i":57,"n":"第五十七条","txt":"期货公司应当按照规定实行投资者适当性管理制度，建立执业规范和内部问责机制，了解客户的经济实力、专业知识、投资经历和风险偏好等情况，审慎评估客户的风险承受能力，提供与评估结果相适应的产品或者服务。 期货公司应当向客户全面客观介绍相关法律法规、业务规则、产品或者服务的特征，充分揭示风险，并按照合同的约定，如实向客户提供相关的资料、信息，不得欺诈或者误导客户。 期货公司应充分了解和评估客户风险承受能力，加强对客户的管理。 期货公司应当承担各项产品和服务的投资者教育义务，保障必要费用和人员配备，将投资者教育纳入各业务环节。"},{"i":58,"n":"第五十八条","txt":"期货公司应当在本公司网站、营业场所等公示业务流程。 期货公司应当提供从业人员资格证书等资料供客户查阅，并在本公司网站和营业场所提示客户可以通过中国期货业协会网站查询。"},{"i":59,"n":"第五十九条","txt":"期货公司应当承担投资者投诉处理的首要责任，建立、健全客户投诉处理制度，公开投诉处理流程，妥善处理客户投诉及与客户的纠纷。"},{"i":60,"n":"第六十条","txt":"期货公司应当建立数据备份制度，对交易、结算、财务等数据进行备份管理。 期货公司应当妥善保存客户开户资料、委托记录、交易记录和与内部管理、业务经营有关的各项资料，任何人不得隐匿、伪造、篡改或者毁损，除依法接受调查和检查外，应当为客户保密，不得非法提供给他人。客户资料保存期限自账户销户之日起不得少于20年。"},{"i":61,"n":"第六十一条","txt":"期货公司不得接受下列单位和个人的委托，为其进行期货交易： （一）国家机关和事业单位； （二）中国证监会及其派出机构、期货交易所、期货保证金安全存管监控机构、中国期货业协会工作人员及其配偶； （三）期货公司工作人员及其配偶； （四）证券、期货市场禁止进入者； （五）未能提供开户证明材料的单位和个人； （六）中国证监会规定的不得从事期货交易的其他单位和个人。"},{"i":62,"n":"第六十二条","txt":"客户应当以自己的名义向期货公司提出开户申请，出具合法有效的单位、个人身份证明或者其他证明材料，如实提供相关信息和材料，承诺资金来源合法，对拟开立的账户与其他账户存在实际控制关系的，应当在开户时向期货公司披露。期货公司应当及时向期货交易所、期货保证金安全存管监控机构报告。 期货公司应当充分告知客户有关实际控制关系账户管理的规定，对客户实际控制关系账户的申报和变更进行管理。"},{"i":63,"n":"第六十三条","txt":"期货公司应当对客户开户信息和资料进行审核。开户信息和资料不真实、不准确和不完整的，期货公司不得为其办理开户手续。"},{"i":64,"n":"第六十四条","txt":"期货公司在为客户开立期货经纪账户前，应当向客户出示《期货交易风险说明书》，由客户签字确认，并签订期货经纪合同。 《〈期货经纪合同〉指引》和《期货交易风险说明书》由中国期货业协会制定。"},{"i":65,"n":"第六十五条","txt":"客户可以通过书面、电话、计算机、互联网等委托方式下达交易指令。 期货公司应当建立交易指令委托管理制度，并与客户就委托方式和程序进行约定。期货公司应当按照客户委托下达交易指令，不得未经客户委托或者未按客户委托内容，擅自进行期货交易。期货公司从业人员不得私下接受客户委托进行期货交易。 以书面方式下达交易指令的，客户应当填写书面交易指令单；以电话方式下达交易指令的，期货公司应当同步录音；以计算机、互联网等委托方式下达交易指令的，期货公司应当以适当方式保存。以互联网方式下达交易指令的，期货公司应当对互联网交易风险进行特别提示。"},{"i":66,"n":"第六十六条","txt":"期货公司应当进行客户交易指令审核。期货公司应当在传递交易指令前对客户账户资金和持仓进行验证。 期货公司应当按照时间优先的原则传递客户交易指令。"},{"i":67,"n":"第六十七条","txt":"期货公司应当建立健全客户交易行为管理制度，发现客户交易指令涉嫌违法违规或者出现交易异常的，应当及时向期货交易所、期货保证金安全存管监控机构及住所地中国证监会派出机构报告。"},{"i":68,"n":"第六十八条","txt":"期货公司应当在每日结算后为客户提供交易结算报告，并提示客户可以通过期货保证金安全存管监控机构进行查询。客户应当按照期货经纪合同约定方式对交易结算报告内容进行确认。 客户对交易结算报告有异议的，应当在期货经纪合同约定的时间内以书面方式提出，期货公司应当在约定时间内进行核实。客户未在约定时间内提出异议的，视为对交易结算报告内容的确认。"},{"i":69,"n":"第六十九条","txt":"期货公司应当制定并执行错单处理业务规则。"},{"i":70,"n":"第七十条","txt":"期货公司应当按照规定为客户申请、注销交易编码。客户与期货公司的委托关系终止的，应当办理销户手续。期货公司不得将客户未注销的资金账号、交易编码借给他人使用。"},{"i":71,"n":"第七十一条","txt":"期货公司为境外交易者和境外经纪机构提供境内特定品种期货交易、结算服务的，应当遵守法律、行政法规及中国证监会的有关规定。"},{"i":72,"n":"第七十二条","txt":"期货公司可以按照规定委托其他机构或者接受其他机构委托从事中间介绍业务。"},{"i":73,"n":"第七十三条","txt":"期货公司可以依法从事期货投资咨询业务，接受客户委托，向客户提供风险管理顾问、研究分析、交易咨询等服务。"},{"i":74,"n":"第七十四条","txt":"期货公司从事期货投资咨询业务，应当与客户签订服务合同，明确约定服务内容、收费标准及纠纷处理方式等事项。"},{"i":75,"n":"第七十五条","txt":"期货公司及其从业人员从事期货投资咨询业务，不得有下列行为： （一）向客户做出保证其资产本金不受损失或者取得最低收益的承诺； （二）以虚假信息、市场传言或者内幕信息为依据向客户提供期货投资咨询服务； （三）对价格涨跌或者市场走势做出确定性的判断； （四）利用向客户提供投资建议谋取不正当利益； （五）利用期货投资咨询活动传播虚假、误导性信息； （六）以个人名义收取服务报酬； （七）法律、行政法规和中国证监会规定禁止的其他行为。"},{"i":76,"n":"第七十六条","txt":"期货公司可以依法从事资产管理业务，接受客户委托，运用客户资产进行投资。投资收益由客户享有，损失由客户承担。"},{"i":77,"n":"第七十七条","txt":"期货公司从事资产管理业务，应当与客户签订资产管理合同，通过专门账户提供服务。"},{"i":78,"n":"第七十八条","txt":"期货公司可以依法从事下列资产管理业务： （一）为单一客户办理资产管理业务； （二）为特定多个客户办理资产管理业务。"},{"i":79,"n":"第七十九条","txt":"期货公司及其从业人员从事资产管理业务，不得有下列行为： （一）以欺诈手段或者其他不当方式误导、诱导客户； （二）向客户做出保证其资产本金不受损失或者取得最低收益的承诺； （三）接受客户委托的初始资产低于中国证监会规定的最低限额； （四）占用、挪用客户委托资产； （五）以转移资产管理账户收益或者亏损为目的，在不同账户之间进行买卖，损害客户利益； （六）以获取佣金或者其他利益为目的，使用客户资产进行不必要的交易； （七）利用管理的客户资产为第三方谋取不正当利益，进行利益输送； （八）利用或协助客户利用资管账户规避期货交易所限仓管理规定； （九）违反投资者适当性要求，通过拆分资产管理产品等方式，向风险承受能力低于产品风险等级的投资者销售资产管理产品； （十）法律、行政法规以及中国证监会规定禁止的其他行为。"},{"i":80,"n":"第八十条","txt":"期货公司从事资产管理业务，除应当符合本办法规定外，还应当符合中国证监会关于期货公司从事资产管理业务的其他规定。"},{"i":81,"n":"第八十一条","txt":"客户的保证金和委托资产属于客户资产，归客户所有。客户资产应当与期货公司的自有资产相互独立、分别管理。非因客户本身的债务或者法律、行政法规规定的其他情形，不得查封、冻结、扣划或者强制执行客户资产。期货公司破产或者清算时，客户资产不属于破产财产或者清算财产。"},{"i":82,"n":"第八十二条","txt":"期货公司应当在期货保证金存管银行开立期货保证金账户。 期货公司开立、变更或者撤销期货保证金账户的，应于当日向期货保证金安全存管监控机构备案，并通过规定方式向客户披露账户开立、变更或者撤销情况。"},{"i":83,"n":"第八十三条","txt":"客户应当向期货公司登记以本人名义开立的用于存取期货保证金的结算账户。 期货公司和客户应当通过备案的期货保证金账户和登记的期货结算账户转账存取保证金。"},{"i":84,"n":"第八十四条","txt":"期货公司存管的客户保证金应当全额存放在期货保证金账户和期货交易所专用结算账户内，严禁在期货保证金账户和期货交易所专用结算账户之外存放。"},{"i":85,"n":"第八十五条","txt":"期货公司应当按照规定及时向期货保证金安全存管监控机构报送信息。"},{"i":86,"n":"第八十六条","txt":"期货保证金存管银行未按规定向期货保证金安全存管监控机构报送信息，被期货交易所采取自律监管措施或者被中国证监会采取监管措施、处以行政处罚的，期货公司应当暂停在该存管银行开立期货保证金账户，并将期货保证金转存至其他符合规定的期货保证金存管银行。"},{"i":87,"n":"第八十七条","txt":"期货公司应当按照期货交易所规则，缴存结算担保金，并维持最低数额的结算准备金等专用资金，确保客户正常交易。"},{"i":88,"n":"第八十八条","txt":"除依据《期货交易管理条例》第二十八条划转外，任何单位或者个人不得以任何形式占用、挪用客户保证金。 客户在期货交易中违约造成保证金不足的，期货公司应当以风险准备金和自有资金垫付，不得占用其他客户保证金。 期货公司应当按照规定提取、管理和使用风险准备金，不得挪作他用。"},{"i":89,"n":"第八十九条","txt":"期货公司应当具有符合行业标准和自身业务发展需要的信息系统，制定信息技术管理制度，按照规定设置信息技术部门或岗位，保障信息系统安全运行。"},{"i":90,"n":"第九十条","txt":"期货公司应当将合规与风险管理贯穿信息技术管理的各个环节，建立相应的审查、测试、监测和应急处置机制。"},{"i":91,"n":"第九十一条","txt":"期货公司运用信息系统从事期货业务活动前，应当进行内部审查，验证下列事项并建立存档记录： （一）信息系统的功能设计与技术实现应当遵循业务合规的原则，各项功能符合法律、行政法规以及中国证监会的规定； （二）风险管理系统功能完备、权限清晰，能够正常运行； （三）信息系统的安全防护措施能够保障经营数据和客户信息的安全、完整； （四）期货公司运行管理能力和信息系统备份能力能够保障信息系统的安全运行； （五）可能影响信息系统运行连续性、合规性、安全性的其他事项。"},{"i":92,"n":"第九十二条","txt":"期货公司应当建立独立于生产环境的专用信息系统开发测试环境，运用信息系统从事期货业务活动前应当进行测试。"},{"i":93,"n":"第九十三条","txt":"期货公司应当通过自身具有管理权限的信息系统直接接受客户交易指令，不得允许或者配合其他机构、个人截取、留存客户信息，不得以任何方式向其他机构、个人违规提供客户信息，法律、行政法规以及中国证监会另有规定的除外。 期货公司发现其他机构、个人违规传输、转发、存储或者使用本公司经营数据和客户信息的，应当及时向公司住所地中国证监会派出机构报告，并评估影响范围、排查泄露途径。如涉及业务合作机构的，期货公司应当立即终止与其合作。"},{"i":94,"n":"第九十四条","txt":"期货公司应当建立健全信息系统安全监测机制，设立监测指标并持续监测重要信息系统的运行状况。 期货公司应当跟踪监测发现的异常情形，及时处理并定期开展评估分析。"},{"i":95,"n":"第九十五条","txt":"期货公司应当建立信息系统安全应急处置和报告机制，及时处置重大异常情况和突发信息安全事件，尽快恢复信息系统的正常运行，并向中国证监会及其派出机构和期货交易所报告。"},{"i":96,"n":"第九十六条","txt":"期货公司重要信息系统部署以及所承载数据的管理，应当符合法律法规等规定。"},{"i":97,"n":"第九十七条","txt":"期货公司应当建立健全外部接入信息系统管理制度。期货公司信息系统接入外部信息系统的，应当对接入的外部信息系统开展合规评估、风险评估和技术系统测试，保证接入的外部信息系统的合规性和安全性，并按照期货交易所、中国期货业协会的要求报告接入方及接入信息系统情况，不得违规为客户提供信息系统外部接入服务。"},{"i":98,"n":"第九十八条","txt":"期货公司委托信息技术服务机构提供信息技术服务，应当建立内部审查、评估和管理机制。期货公司依法应当承担的相应责任不因委托而免除或减轻。 期货信息技术服务机构应当遵守法律、行政法规及中国证监会的相关规定。"},{"i":99,"n":"第九十九条","txt":"期货公司应当按照规定报送年度报告、月度报告等资料。 期货公司法定代表人、经营管理主要负责人、首席风险官、财务负责人应当对年度报告和月度报告签署确认意见；监事会或监事应对年度报告进行审核并提出书面审核意见；期货公司董事应当对年度报告签署确认意见。 期货公司年度报告、月度报告签字人员应当保证报告内容真实、准确、完整；对报告内容有异议的，应当注明意见和理由。"},{"i":100,"n":"第一百条","txt":"中国证监会及其派出机构可以要求下列机构或者个人，在指定期限内报送与期货公司经营相关的资料： （一）期货公司及其董事、监事、高级管理人员及其他工作人员； （二）期货公司股东、实际控制人或者其他关联人； （三）期货公司控股、参股或者实际控制的企业； （四）为期货公司提供相关服务的会计师事务所、律师事务所、资产评估机构等中介服务机构。 报送、提供或者披露的资料、信息应当真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":101,"n":"第一百零一条","txt":"期货公司主要股东、实际控制人或者其他关联人在期货公司从事期货交易的，期货公司应当自开户之日起5个工作日内向住所地中国证监会派出机构报告开户情况，并定期报告交易情况。"},{"i":102,"n":"第一百零二条","txt":"发生下列事项之一的，期货公司应当在5个工作日内向住所地中国证监会派出机构书面报告： （一）变更公司名称、形式、章程； （二）同比例增减资； （三）变更股权或注册资本，且不涉及新增持有5%以上股权的股东； （四）变更分支机构负责人或者营业场所； （五）作出终止业务等重大决议； （六）被有权机关立案调查或者采取强制措施； （七）发生影响或者可能影响期货公司经营管理、财务状况或者客户资产安全等重大事件； （八）中国证监会规定的其他事项。 上述事项涉及期货公司分支机构的，期货公司应当同时向分支机构住所地中国证监会派出机构书面报告。"},{"i":103,"n":"第一百零三条","txt":"期货公司聘请或者解聘会计师事务所的，应当自作出决定之日起5个工作日内向住所地中国证监会派出机构报告；解聘会计师事务所的，应当说明理由。"},{"i":104,"n":"第一百零四条","txt":"期货公司应当按照规定，公示基本情况、历史情况、分支机构基本情况、董事及监事信息、高级管理人员及从业人员信息、公司股东信息、公司诚信记录以及中国证监会要求的其他信息。 期货公司公示信息及其他重大事项发生变更的，应当自变更之日起5个工作日内在中国证监会有关监管信息系统中进行更新。"},{"i":105,"n":"第一百零五条","txt":"中国证监会可以按照规定对期货公司进行分类监管。"},{"i":106,"n":"第一百零六条","txt":"中国证监会及其派出机构可以对期货公司及其分支机构进行定期或者不定期现场检查。 中国证监会及其派出机构依法进行现场检查时，检查人员不得少于2人，并应当出示合法证件和检查通知书，必要时可以聘请外部专业人士协助检查。 中国证监会及其派出机构可以对期货公司子公司以及期货公司的股东、实际控制人进行延伸检查。"},{"i":107,"n":"第一百零七条","txt":"中国证监会及其派出机构对期货公司及其分支机构进行检查，有权采取下列措施： （一）询问期货公司及其分支机构的工作人员，要求其对被检查事项作出解释、说明； （二）查阅、复制与被检查事项有关的文件、资料； （三）查询期货公司及其分支机构的客户资产账户； （四）检查期货公司及其分支机构的信息系统，调阅交易、结算及财务数据。"},{"i":108,"n":"第一百零八条","txt":"中国证监会及其派出机构认为期货公司可能存在下列情形之一的，可以要求其聘请中介服务机构进行专项审计、评估或者出具法律意见： （一）期货公司年度报告、月度报告或者临时报告等存在虚假记载、误导性陈述或者重大遗漏； （二）违反客户资产保护、期货保证金安全存管监控规定或者风险监管指标管理规定； （三）中国证监会根据审慎监管原则认定的其他情形。 期货公司应当配合中介服务机构工作。"},{"i":109,"n":"第一百零九条","txt":"期货公司及其分支机构、期货公司负有责任的董事、监事、高级管理人员以及其他直接责任人员违反本办法有关规定的，中国证监会及其派出机构可以对其采取监管谈话、责令改正、出具警示函等监管措施。"},{"i":110,"n":"第一百一十条","txt":"期货公司或其分支机构有下列情形之一的，中国证监会及其派出机构可以依据《期货交易管理条例》第五十五条规定采取监管措施： （一）公司治理不健全，部门或者岗位设置存在较大缺陷，关键业务岗位人员缺位或者未履行职责，可能影响期货公司持续经营； （二）业务规则不健全或者未有效执行，风险管理或者内部控制等存在较大缺陷，经营管理混乱，可能影响期货公司持续经营或者可能损害客户合法权益； （三）不符合有关客户资产保护或者期货保证金安全存管监控规定，可能影响客户资产安全； （四）未按规定执行分支机构统一管理制度，经营管理存在较大风险或者风险隐患； （五）未按规定实行投资者适当性管理制度，存在较大风险或者风险隐患； （六）未按规定委托或者接受委托从事中间介绍业务； （七）交易、结算或者财务信息系统存在重大缺陷，可能造成有关数据失真或者损害客户合法权益； （八）信息系统不符合规定或者未按照规定要求实施信息系统管"},{"i":111,"n":"第一百一十一条","txt":"期货公司股东、实际控制人、其他关联人，为期货公司提供相关服务的会计师事务所、律师事务所、资产评估机构等中介服务机构违反本办法规定的，中国证监会及其派出机构可以对其采取监管谈话、责令改正、出具警示函等监管措施。"},{"i":112,"n":"第一百一十二条","txt":"期货公司的股东、实际控制人或者其他关联人有下列情形之一的，中国证监会及其派出机构可以责令其限期整改： （一）虚假出资、出资不实、抽逃出资的； （二）违规使用委托资金、负债资金等投资入股的； （三）股权转让过程中，在股权转让完成前推荐股权受让方相关人员担任期货公司董事、监事、高级管理人员或者出让股权依法应经中国证监会批准的，在批准前，让渡或者变相让渡表决权予股权受让方； （四）占用期货公司资产； （五）直接任免期货公司董事、监事、高级管理人员，或者非法干预期货公司经营管理活动； （六）股东未按照出资比例或者所持股份比例行使表决权； （七）报送、提供或者出具的材料、信息或者报告等存在虚假记载、误导性陈述或者重大遗漏； （八）违规开展关联交易； （九）拒绝或阻碍中国证监会或其派出机构进行调查核实； （十）不配合中国证监会或其派出机构开展风险处置； （十一）其他损害期货公司及其客户合法利益，扰"},{"i":113,"n":"第一百一十三条","txt":"未经中国证监会或其派出机构批准，任何个人或者单位及其关联人擅自持有期货公司5%以上股权，或者通过提供虚假申请材料等方式成为期货公司股东的，中国证监会或其派出机构可以责令其限期转让股权。该股权在转让之前，不具有表决权、分红权。"},{"i":114,"n":"第一百一十四条","txt":"期货公司及其分支机构接受未办理开户手续的单位或者个人委托进行期货交易，或者将客户的资金账号、交易编码借给其他单位或者个人使用的，给予警告，单处或者并处3万元以下罚款。"},{"i":115,"n":"第一百一十五条","txt":"期货公司及其分支机构有下列行为之一的，根据《期货交易管理条例》第六十六条处罚： （一）未按规定实行投资者适当性管理制度，损害客户合法权益； （二）未按规定将客户资产与期货公司自有资产相互独立、分别管理； （三）在期货保证金账户和期货交易所专用结算账户之外存放客户保证金； （四）占用客户保证金； （五）向期货保证金安全存管监控机构报送的信息存在虚假记载、误导性陈述或者重大遗漏； （六）违反期货保证金安全存管监控管理相关规定，损害客户合法权益； （七）未按规定缴存结算担保金，或者未能维持最低数额的结算准备金等专用资金； （八）在传递交易指令前未对客户账户资金和持仓进行验证； （九）违反中国证监会有关结算业务管理规定，损害其他期货公司及其客户合法权益； （十）信息系统不符合规定或者未按照规定要求实施信息系统管理，损害客户合法权益或者扰乱期货市场秩序； （十一）未按规定实施外部接入信息系统管理"},{"i":116,"n":"第一百一十六条","txt":"期货公司及其分支机构有下列情形之一的，根据《期货交易管理条例》第六十七条处罚： （一）发布虚假广告或者进行虚假宣传，诱骗客户参与期货交易； （二）不按照规定变更或者撤销期货保证金账户，或者不按照规定方式向客户披露期货保证金账户信息。"},{"i":117,"n":"第一百一十七条","txt":"期货公司因治理结构不健全、内部控制不完善，未按有关规定履行对子公司的管理职责，导致子公司违法经营或者出现重大风险的，对期货公司及其直接负责的董事、监事、高级管理人员和其他直接责任人员，依照《期货交易管理条例》第六十六条处罚。"},{"i":118,"n":"第一百一十八条","txt":"会计师事务所、律师事务所、资产评估机构等中介服务机构不按照规定履行报告义务，提供或者出具的材料、报告、意见不完整，责令改正，没收业务收入，单处或者并处3万元以下罚款。对直接负责的主管人员和其他责任人员给予警告，并处3万元以下罚款。"},{"i":119,"n":"第一百一十九条","txt":"未经中国证监会或其派出机构批准，任何个人或者单位及其关联人擅自持有期货公司5%以上股权，或者通过提供虚假申请材料等方式成为期货公司股东，情节严重的，给予警告，单处或者并处3万元以下罚款。"},{"i":120,"n":"第一百二十条","txt":"期货公司股东、实际控制人或者其他关联人等有下列情形之一，除法律、行政法规另有规定外，给予警告，单独或者并处三万元以下罚款。对直接负责的主管人员和其他直接责任人员，给予警告，单独或者并处三万元以下罚款： （一）违规使用委托资金、负债资金等投资入股，情节严重的； （二）股权转让过程中，在股权转让完成前推荐股权受让方相关人员担任期货公司董事、监事、高级管理人员或者出让股权依法应经中国证监会批准的，在批准前，让渡或者变相让渡表决权予股权受让方，情节严重的； （三）占用期货公司资产； （四）直接任免期货公司董事、监事、高级管理人员，或者非法干预期货公司经营管理活动，情节严重的； （五）股东未按照出资比例或者所持股份比例行使表决权，情节严重的； （六）违规开展关联交易，情节严重的； （七）其他损害期货公司及其客户合法利益，严重扰乱期货市场秩序的行为。"},{"i":121,"n":"第一百二十一条","txt":"经中国证监会批准，其他期货经营机构可以从事特定期货业务。具体办法由中国证监会另行制定。"},{"i":122,"n":"第一百二十二条","txt":"期货公司参与其他交易场所交易的，应当遵守法律、行政法规、中国证监会的规定及其他交易场所业务规则的规定。"},{"i":123,"n":"第一百二十三条","txt":"本办法下列用语的含义： （一）期货公司主要股东，是指持有期货公司5%以上股权的法人、非法人组织或者自然人。 （二）外部接入信息系统，是指通过期货公司交易信息系统接口或其他信息技术手段接入期货公司交易信息系统，且期货公司不具有管理权限的客户交易系统。"},{"i":124,"n":"第一百二十四条","txt":"本办法中所称金融资产包括银行存款、股票、债券、基金份额、资产管理计划、银行理财产品、信托计划、保险产品、期货权益等。"},{"i":125,"n":"第一百二十五条","txt":"本办法自公布之日起施行。2014年10月29日发布的《期货公司监督管理办法》（证监会令第110号）同时废止。"}],"qihuogongsidongshijianshihegaojiguanlirenyuanrenzhaab5a8":[{"i":1,"n":"第一条","txt":"为了加强对期货公司董事、监事和高级管理人员的任职管理，规范期货公司运作，防范经营风险，根据《公司法》和《期货交易管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"期货公司董事、监事和高级管理人员的任职管理，适用本办法。 本办法所称高级管理人员，是指期货公司的总经理、副总经理、首席风险官（以下简称经理层人员），财务负责人以及实际履行上述职务的人员。 期货公司分支机构负责人的管理参照本办法有关高级管理人员的相关规定执行。"},{"i":3,"n":"第三条","txt":"期货公司董事、监事和高级管理人员应当符合中国证券监督管理委员会（以下简称中国证监会）规定的任职条件。 期货公司不得任用不符合任职条件的人员担任董事、监事和高级管理人员。 期货公司不得授权董事、监事和高级管理人员之外的人员实际履行相关职责，本办法另有规定的除外。"},{"i":4,"n":"第四条","txt":"期货公司董事、监事和高级管理人员应当遵守法律、行政法规和中国证监会的规定，遵守自律规则、行业规范和公司章程，恪守诚信，勤勉尽责。"},{"i":5,"n":"第五条","txt":"中国证监会依法对期货公司董事、监事和高级管理人员进行监督管理。 中国证监会派出机构依照本办法和中国证监会的授权对期货公司董事、监事和高级管理人员进行监督管理。 中国期货业协会、期货交易所依法对期货公司董事、监事和高级管理人员进行自律管理。"},{"i":6,"n":"第六条","txt":"期货公司董事、监事和高级管理人员应当具有诚实守信的品质、良好的职业道德和履行职责所必需的经营管理能力。"},{"i":7,"n":"第七条","txt":"担任除董事长、监事会主席、独立董事以外的期货公司董事、监事的，应当具备下列条件： （一）具有从事期货、证券等金融业务或者法律、会计业务3年以上经验，或者经济管理工作5年以上经验； （二）具有大学专科以上学历。"},{"i":8,"n":"第八条","txt":"担任期货公司独立董事的，应当具备下列条件： （一）具有从事期货、证券等金融业务或者法律、会计业务5年以上经验，或者具有相关学科教学、研究的高级职称； （二）具有大学本科以上学历，并且取得学士以上学位； （三）熟悉期货法律、行政法规和中国证监会的规定，具备期货专业能力； （四）有履行职责所必需的时间和精力。"},{"i":9,"n":"第九条","txt":"独立董事不得与所任职期货公司存在可能妨碍其作出独立、客观判断的关系。 下列人员不得担任期货公司独立董事： （一）在期货公司或者其关联方任职的人员及其近亲属和主要社会关系人员； （二）在下列机构任职的人员及其近亲属和主要社会关系人员：持有或者控制期货公司5%以上股权的单位、期货公司前5名股东单位、与期货公司存在业务联系或者利益关系的机构； （三）直接或间接持有上市期货公司已发行股份1%以上或者是上市期货公司前十名股东中的自然人股东及其近亲属； （四）为期货公司及其关联方提供财务、法律、咨询等服务的人员及其近亲属； （五）最近1年内曾经具有前四项所列举情形之一的人员； （六）在其他期货公司担任除独立董事以外职务的人员； （七）中国证监会规定的其他人员。"},{"i":10,"n":"第十条","txt":"担任期货公司董事长和监事会主席的，应当具备下列条件： （一）具有从事期货业务3年以上经验，或者其他金融业务4年以上经验，或者法律、会计业务5年以上经验，或者经济管理工作10年以上经验； （二）具有大学本科以上学历或者取得学士以上学位； （三）熟悉期货法律、行政法规和中国证监会的规定，具备期货专业能力。"},{"i":11,"n":"第十一条","txt":"担任期货公司经理层人员的，应当具备下列条件： （一）具有期货从业人员资格； （二）具有大学本科以上学历或者取得学士以上学位； （三）熟悉期货法律、行政法规和中国证监会的规定，具备期货专业能力。"},{"i":12,"n":"第十二条","txt":"担任期货公司总经理、副总经理的，除具备第十一条规定条件外，还应当具备下列条件： （一）具有从事期货业务3年以上经验，或者其他金融业务4年以上经验，或者法律、会计业务5年以上经验，或者经济管理工作10年以上经验； （二）担任期货公司、证券公司等金融机构部门负责人以上职务不少于2年，或者具有相当职位管理工作经历。"},{"i":13,"n":"第十三条","txt":"担任期货公司首席风险官的，除具备第十一条规定条件外，还应当具有从事期货业务3年以上经验，并担任期货公司交易、结算、风险管理或者合规负责人职务不少于2年；或者具有从事期货业务1年以上经验，并具有在证券公司等金融机构从事风险管理、合规业务3年以上经验。 首席风险官的任职、履职以及考核应当保持独立性。"},{"i":14,"n":"第十四条","txt":"担任期货公司财务负责人的，应当具备下列条件： （一）具有期货从业人员资格； （二）具有大学本科以上学历或者取得学士以上学位； （三）具有会计师以上职称或者注册会计师资格。 担任期货公司分支机构负责人的，除具备上述第（一）项、第（二）项条件外，还应当具有从事期货业务3年以上经验，或者其他金融业务4年以上经验，或者经济管理工作5年以上经验。"},{"i":15,"n":"第十五条","txt":"期货公司法定代表人应当具有期货从业人员资格。"},{"i":16,"n":"第十六条","txt":"具有从事期货业务10年以上经验或者曾担任金融机构部门负责人以上职务8年以上的人员，担任期货公司董事长、监事会主席、高级管理人员的，学历可以放宽至大学专科。"},{"i":17,"n":"第十七条","txt":"具有期货等金融或者法律、会计专业硕士研究生以上学历的人员，担任期货公司董事、监事和高级管理人员的，从事除期货以外的其他金融业务，或者法律、会计业务的年限可以放宽1年。"},{"i":18,"n":"第十八条","txt":"在期货监管机构、自律机构以及其他承担期货监管职能的专业监管岗位任职8年以上的人员，担任期货公司高级管理人员的，可以免试取得期货从业人员资格。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，不得担任期货公司董事、监事和高级管理人员： （一）《公司法》第一百四十六条规定的情形； （二）因违法行为或者违纪行为被解除职务的期货交易所、证券交易所、证券登记结算机构的负责人，或者期货公司、证券公司、基金管理公司的董事、监事、高级管理人员，自被解除职务之日起未逾5年； （三）因违法行为或者违纪行为被撤销资格的律师、注册会计师或者投资咨询机构、财务顾问机构、资信评级机构、资产评估机构、验证机构的专业人员，自被撤销资格之日起未逾5年； （四）因违法行为或者违纪行为被开除的期货交易所、证券交易所、证券登记结算机构、证券服务机构、期货公司、证券公司、基金管理公司的从业人员和被开除的国家机关工作人员，自被开除之日起未逾5年； （五）国家机关工作人员和法律、行政法规规定的禁止在公司中兼职的其他人员； （六）因重大违法违规行为受到金融监管部门的行政处罚，执行期满未逾3年； （七）"},{"i":20,"n":"第二十条","txt":"期货公司董事、监事和高级管理人员的任职，由期货公司住所地的中国证监会派出机构依法备案。 分支机构负责人的任职由期货公司分支机构所在地的中国证监会派出机构依法备案，并抄报期货公司住所地的中国证监会派出机构。"},{"i":21,"n":"第二十一条","txt":"期货公司董事长、监事会主席、独立董事的任职，应当由任职期货公司自作出决定之日起5个工作日内，向中国证监会派出机构备案，并根据任职条件提交下列备案材料： （一）备案报告书； （二）任职条件表； （三）身份、学历、学位证明； （四）中国证监会规定的其他材料。 独立董事的任职，还应当提供任职人员关于独立性的声明，声明应当重点说明其本人是否存在本办法第九条所列举的情形。"},{"i":22,"n":"第二十二条","txt":"期货公司经理层人员的任职，应当由任职期货公司自作出决定之日起5个工作日内，向中国证监会派出机构备案，并提交下列备案材料： （一）备案报告书； （二）任职条件表； （三）身份、学历、学位证明； （四）期货从业人员资格证明； （五）高级管理人员职责范围的说明； （六）中国证监会规定的其他材料。"},{"i":23,"n":"第二十三条","txt":"除董事长、监事会主席、独立董事以外的董事、监事的任职，应当由任职期货公司自作出决定之日起5个工作日内，向中国证监会派出机构备案，并根据任职条件提交下列备案材料： （一）备案报告书； （二）任职条件表； （三）身份、学历、学位证明； （四）中国证监会规定的其他材料。"},{"i":24,"n":"第二十四条","txt":"财务负责人的任职，应当由任职期货公司自作出决定之日起5个工作日内，向中国证监会派出机构备案，并提交下列备案材料： （一）备案报告书； （二）任职条件表； （三）身份、学历、学位证明； （四）期货从业人员资格证明； （五）高级管理人员职责范围的说明； （六）会计师以上职称或者注册会计师资格的证明； （七）中国证监会规定的其他材料。 分支机构负责人的任职，应当由任职期货公司自作出决定之日起5个工作日内，向中国证监会派出机构备案，并提交第一款中第（一）项至第（四）项、第（七）项备案材料。"},{"i":25,"n":"第二十五条","txt":"备案人提交境外大学或者高等教育机构学位证书或者高等教育文凭，或者非学历教育文凭的，应当同时提交国务院教育行政部门对任职人员所获教育文凭的学历学位认证文件。"},{"i":26,"n":"第二十六条","txt":"中国证监会派出机构通过审核材料、考察谈话、调查从业经历等方式，对任职人员是否符合任职条件进行核查。"},{"i":27,"n":"第二十七条","txt":"期货公司免除董事、监事、高级管理人员和分支机构负责人的职务，应当自作出决定之日起5个工作日内，向任职备案时备案及抄报的中国证监会派出机构报告，并提交下列材料： （一）免职决定文件； （二）相关会议的决议； （三）中国证监会规定的其他材料。 期货公司拟免除首席风险官的职务，应当在作出决定前10个工作日将免职理由及其履行职责情况向公司住所地的中国证监会派出机构报告。"},{"i":28,"n":"第二十八条","txt":"期货公司董事、监事和高级管理人员不得在党政机关兼职。 期货公司高级管理人员最多可以在期货公司参股的2家公司兼任董事、监事，但不得在上述公司兼任董事、监事之外的职务，不得在其他营利性机构兼职或者从事其他经营性活动。 期货公司高级管理人员在期货公司全资或控股子公司兼职的，不受上述限制，但应当遵守中国证监会的有关规定。 期货公司营业部负责人不得兼任其他营业部负责人。 符合任职条件的人员最多可以在2家期货公司兼任独立董事。 期货公司董事、监事和高级管理人员兼职的，应当自有关情况发生之日起5个工作日内向中国证监会相关派出机构报告。"},{"i":29,"n":"第二十九条","txt":"期货公司董事、监事和高级管理人员改任的，应当按规定备案。 有以下情形的，期货公司应当自作出改任决定之日起5个工作日内，向中国证监会派出机构报告，不需备案： （一）期货公司除董事长、监事会主席、独立董事以外的董事、监事，在同一期货公司内由董事改任监事或者由监事改任董事； （二）在同一期货公司内，董事长改任监事会主席，或者监事会主席改任董事长，或者董事长、监事会主席改任除独立董事之外的其他董事、监事； （三）在同一期货公司内，经理层人员改任董事（不包括独立董事）、监事； （四）在同一期货公司内，分支机构负责人改任同一中国证监会派出机构监管辖区内的其他分支机构负责人。"},{"i":30,"n":"第三十条","txt":"期货公司董事长、监事会主席、独立董事离任后12个月内到其他期货公司担任董事长、监事会主席、独立董事，且未出现本办法第十九条规定情形的，新任职期货公司应当提交下列备案材料： （一）备案报告书； （二）任职条件表； （三）任职人员在原任职期货公司任职情况的陈述； （四）中国证监会规定的其他材料。"},{"i":31,"n":"第三十一条","txt":"期货公司董事应当按照公司章程的规定出席董事会会议，参加公司的活动，切实履行职责。"},{"i":32,"n":"第三十二条","txt":"期货公司独立董事应当重点关注和保护客户、中小股东的合法利益，发表客观、公正的独立意见。"},{"i":33,"n":"第三十三条","txt":"期货公司高级管理人员应当遵循诚信原则，谨慎地在职权范围内行使职权，维护客户和公司的合法利益，不得从事或者配合他人从事损害客户和公司利益的活动，不得利用职务之便为自己或者他人谋取属于本公司的商业机会。"},{"i":34,"n":"第三十四条","txt":"期货公司董事、监事和高级管理人员的近亲属在期货公司从事期货交易的，有关董事、监事和高级管理人员应当在知悉或者应当知悉之日起5个工作日内向公司报告，并遵循回避原则。公司应当在接到报告之日起5个工作日内向中国证监会相关派出机构备案，并每季度报告相关交易情况。"},{"i":35,"n":"第三十五条","txt":"期货公司总经理应当认真执行董事会决议，有效执行公司制度，防范和化解经营风险，确保经营业务的稳健运行和客户保证金安全完整。副总经理应当协助总经理工作，忠实履行职责。"},{"i":36,"n":"第三十六条","txt":"期货公司董事、监事和高级管理人员不得收受或进行商业贿赂，不得利用职务之便牟取其他非法利益。"},{"i":37,"n":"第三十七条","txt":"期货公司董事长、监事会主席、独立董事和经理层人员依法参加中国期货业协会组织的非准入型专业能力水平评价测试，保障和提高自身专业能力水平。"},{"i":38,"n":"第三十八条","txt":"期货公司董事长、总经理、首席风险官、分支机构负责人在失踪、死亡、丧失行为能力等特殊情形下不能履行职责的，期货公司可以按照公司章程等规定临时决定由符合相应任职条件的人员代为履行职责，并自作出决定之日起3个工作日内向中国证监会派出机构报告。 公司决定的人员不符合条件的，中国证监会派出机构可以责令公司更换代为履行职责的人员。 代为履行职责的时间不得超过6个月。公司应当在6个月内任用符合任职条件的人员担任董事长、总经理、首席风险官、分支机构负责人。"},{"i":39,"n":"第三十九条","txt":"期货公司调整高级管理人员职责分工的，应当在5个工作日内向中国证监会相关派出机构报告。"},{"i":40,"n":"第四十条","txt":"期货公司董事、监事和高级管理人员因涉嫌违法违规行为被有权机关立案调查或者采取强制措施的，期货公司应当立即向中国证监会相关派出机构报告。"},{"i":41,"n":"第四十一条","txt":"期货公司对董事、监事和高级管理人员给予处分的，应当自作出决定之日起5个工作日内向中国证监会相关派出机构报告。"},{"i":42,"n":"第四十二条","txt":"期货公司董事、监事和高级管理人员受到非法或者不当干预，不能正常依法履行职责，导致或者可能导致期货公司发生违规行为或者出现风险的，该人员应当及时向中国证监会相关派出机构报告。"},{"i":43,"n":"第四十三条","txt":"期货公司有下列情形之一的，中国证监会及其派出机构可以责令改正，并对负有责任的主管人员和其他直接责任人员采取监管谈话、出具警示函等监管措施： （一）任用的董事、监事和高级管理人员不符合任职条件； （二）未按规定备案或报告董事、监事和高级管理人员任免情况； （三）法人治理结构、内部控制存在重大隐患； （四）未按规定报告高级管理人员职责分工调整的情况； （五）未按规定报告相关人员代为履行职责的情况； （六）未按规定备案或报告董事、监事和高级管理人员的近亲属在本公司从事期货交易的情况； （七）未按规定对离任人员进行离任审计； （八）违反规定授权董事、监事和高级管理人员之外的人员实际行使相关职权； （九）中国证监会规定的其他情形。"},{"i":44,"n":"第四十四条","txt":"期货公司董事、监事和高级管理人员有下列情形之一的，中国证监会及其派出机构可以责令改正，并对其采取监管谈话、出具警示函等监管措施： （一）未按规定履行职责； （二）违规兼职或者未按规定报告兼职情况； （三）未按规定报告近亲属在本公司从事期货交易的情况； （四）中国证监会规定的其他情形。"},{"i":45,"n":"第四十五条","txt":"期货公司董事、监事和高级管理人员在任职期间出现下列情形之一的，中国证监会及其派出机构可以将其认定为不适当人选： （一）向中国证监会及其派出机构提供虚假信息或者隐瞒重大事项，造成严重后果； （二）拒绝配合中国证监会及其派出机构依法履行监管职责，造成严重后果； （三）擅离职守，造成严重后果； （四）1年内累计3次被中国证监会及其派出机构进行监管谈话； （五）累计3次被行业自律组织纪律处分； （六）对期货公司出现违法违规行为或者重大风险负有责任； （七）中国证监会规定的其他情形。"},{"i":46,"n":"第四十六条","txt":"期货公司董事、监事和高级管理人员被中国证监会及其派出机构认定为不适当人选的，期货公司应当将该人员免职。"},{"i":47,"n":"第四十七条","txt":"期货公司董事、监事和高级管理人员的诚信信息，记入证券期货市场诚信档案数据库（以下简称诚信档案）。"},{"i":48,"n":"第四十八条","txt":"期货公司董事长、总经理辞职，或者被认定为不适当人选而被解除职务的，期货公司应当委托符合规定的会计师事务所对其进行离任审计，并自其离任之日起3个月内将审计报告报中国证监会及其派出机构备案。 期货公司无故拖延或者拒不审计的，中国证监会及其派出机构可以指定符合规定的会计师事务所进行审计。有关审计费用由期货公司承担。"},{"i":49,"n":"第四十九条","txt":"期货公司或者任职人员隐瞒有关情况或者提供虚假材料的，责令改正，记入诚信档案；拒不改正的，依法予以警告，并处3万元以下罚款。"},{"i":50,"n":"第五十条","txt":"期货公司或者任职人员以欺骗、贿赂等不正当手段完成任职备案的，责令改正，记入诚信档案，对负有责任的公司和人员予以警告，并处3万元以下罚款。"},{"i":51,"n":"第五十一条","txt":"期货公司有下列情形之一的，根据《期货交易管理条例》第六十六条处罚： （一）任用不符合任职条件的人员担任董事、监事和高级管理人员且拒不改正； （二）任用中国证监会及其派出机构认定的不适当人选担任董事、监事和高级管理人员； （三）未按规定备案或报告董事、监事和高级管理人员的任免情况造成严重后果，或者报送的材料存在虚假记载、误导性陈述或者重大遗漏； （四）未按规定报告董事、监事和高级管理人员的处分情况； （五）董事、监事和高级管理人员被有权机关立案调查或者采取强制措施的，未按规定履行报告义务； （六）未按照中国证监会的要求更换或者调整董事、监事和高级管理人员。"},{"i":52,"n":"第五十二条","txt":"期货公司董事、监事和高级管理人员收受或进行商业贿赂，或者利用职务之便牟取其他非法利益的，依法追究行政责任。"},{"i":53,"n":"第五十三条","txt":"违反本办法，涉嫌犯罪的，依法移送司法机关，追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"本办法自公布之日起施行。中国证监会发布的《期货经纪公司高级管理人员任职资格管理办法（修订）》（证监发〔2002〕6号）、《关于期货经纪公司高级管理人员任职资格审核有关问题的通知》（证监期货字〔2004〕67号）、《期货经纪公司高级管理人员任职资格年检工作细则》（证监期货字〔2003〕110号）、《关于落实对涉嫌违法违规期货公司高管人员及相关人员责任追究的通知》（证监期货字〔2005〕159号）同时废止。"}],"qihuogongsifengxianjianguanzhibiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强期货公司监督管理，促进期货公司加强内部控制、防范风险、稳健发展，根据《期货交易管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"期货公司应当按照中国证券监督管理委员会（以下简称中国证监会）的有关规定计算风险监管指标。"},{"i":3,"n":"第三条","txt":"中国证监会可以根据审慎监管原则，结合期货市场与期货行业发展状况，在征求行业意见基础上对期货公司风险监管指标标准及计算要求进行动态调整，并为调整事项的实施作出过渡性安排。"},{"i":4,"n":"第四条","txt":"期货公司应当建立与风险监管指标相适应的内部控制制度及风险管理制度，建立动态的风险监控和资本补充机制，确保净资本等风险监管指标持续符合标准。"},{"i":5,"n":"第五条","txt":"期货公司应当及时根据监管要求、市场变化及业务发展情况对公司风险监管指标进行压力测试。 压力测试结果显示潜在风险超过期货公司承受能力的，期货公司应当采取有效措施，及时补充资本或控制业务规模，将风险控制在可承受范围内。"},{"i":6,"n":"第六条","txt":"期货公司应当聘请具备证券、期货相关业务资格的会计师事务所对期货公司年度风险监管报表进行审计。 会计师事务所及其注册会计师应当勤勉尽责，对出具报告所依据的文件资料内容的真实性、准确性和完整性进行核查和验证，并对出具审计报告的合法性和真实性负责。"},{"i":7,"n":"第七条","txt":"中国证监会及其派出机构按照法律、行政法规及本办法的规定，对期货公司风险监管指标是否符合标准，期货公司编制、报送风险监管报表相关活动实施监督管理。"},{"i":8,"n":"第八条","txt":"期货公司应当持续符合以下风险监管指标标准： （一）净资本不得低于人民币3000万元； （二）净资本与公司风险资本准备的比例不得低于100%； （三）净资本与净资产的比例不得低于20%； （四）流动资产与流动负债的比例不得低于100%； （五）负债与净资产的比例不得高于150%； （六）规定的最低限额结算准备金要求。"},{"i":9,"n":"第九条","txt":"中国证监会对风险监管指标设置预警标准。规定“不得低于”一定标准的风险监管指标，其预警标准是规定标准的120%；规定“不得高于”一定标准的风险监管指标，其预警标准是规定标准的80%。 最低限额结算准备金不设预警标准。"},{"i":10,"n":"第十条","txt":"期货公司净资本是在净资产基础上，按照变现能力对资产负债项目及其他项目进行风险调整后得出的综合性风险监管指标。 净资本的计算公式为：净资本＝净资产－资产调整值＋负债调整值－/＋其他调整项。"},{"i":11,"n":"第十一条","txt":"期货公司风险资本准备是指期货公司在开展各项业务过程中，为应对可能发生的风险损失所需要的资本。"},{"i":12,"n":"第十二条","txt":"最低限额结算准备金是指期货公司按照交易所及登记结算机构的有关要求以自有资金缴存用于履约担保的最低金额。"},{"i":13,"n":"第十三条","txt":"期货公司计算净资本时，应当按照企业会计准则的规定充分计提资产减值准备、确认预计负债。 中国证监会派出机构可以要求期货公司对资产减值准备计提的充足性和合理性、预计负债确认的完整性进行专项说明，并要求期货公司聘请具有证券、期货业务资格的会计师事务所出具鉴证意见；有证据表明期货公司未能充分计提资产减值准备或未能准确确认预计负债的，中国证监会派出机构应当要求期货公司相应核减净资本金额。"},{"i":14,"n":"第十四条","txt":"期货公司应当根据期末未决诉讼、未决仲裁等或有事项的性质、涉及金额、形成原因、进展情况、可能发生的损失和预计损失进行会计处理，在计算净资本时按照一定比例扣减，并在风险监管报表附注中予以说明。"},{"i":15,"n":"第十五条","txt":"期货公司借入次级债务、向股东或者其关联企业借入具有次级债务性质的长期借款以及其他清偿顺序在普通债之后的债务，可以按照规定计入净资本。 期货公司应当在相关事项完成后5个工作日内向住所地中国证监会派出机构报告。 期货公司不得互相持有次级债务。"},{"i":16,"n":"第十六条","txt":"中国证监会及其派出机构认为期货公司开展某项业务存在未预期风险特征的，可以根据潜在风险状况确定所需资本规模，并要求期货公司补充计提风险资本准备。"},{"i":17,"n":"第十七条","txt":"期货公司应当按照中国证监会规定的方式编制并报送风险监管报表。中国证监会可以根据监管需要及行业发展情况调整风险监管报表的编制及报送要求。 中国证监会派出机构可以根据审慎监管原则，要求期货公司不定期编制并报送风险监管报表，或要求期货公司在一段时期内提高风险监管报表的报送频率。"},{"i":18,"n":"第十八条","txt":"期货公司法定代表人、经营管理主要负责人、首席风险官、财务负责人应当在风险监管报表上签字确认，并应当保证其真实、准确、完整。上述人员对风险监管报表内容持有异议的，应当书面说明意见和理由，向期货公司住所地中国证监会派出机构报告。"},{"i":19,"n":"第十九条","txt":"期货公司应当保留书面月度及年度风险监管报表，法定代表人、经营管理主要负责人、首席风险官、财务负责人等责任人员应当在书面报表上签字，并加盖公司印章。风险监管报表的保存期限应当不少于5年。"},{"i":20,"n":"第二十条","txt":"期货公司应当每半年向公司董事会提交书面报告，说明各项风险监管指标的具体情况，该报告应当经期货公司法定代表人签字确认。该报告经董事会审议通过后，应当向期货公司全体股东提交或进行信息披露。"},{"i":21,"n":"第二十一条","txt":"净资本与风险资本准备的比例与上月相比向不利方向变动超过20%的，期货公司应当向公司住所地中国证监会派出机构提交书面报告，说明原因，并在5个工作日内向全体董事提交书面报告。"},{"i":22,"n":"第二十二条","txt":"期货公司风险监管指标达到预警标准的，期货公司应当于当日向全体董事提交书面报告，详细说明原因、对期货公司的影响、解决问题的具体措施和期限，书面报告应当同时抄送期货公司住所地中国证监会派出机构。 期货公司风险监管指标不符合规定标准的，期货公司除履行上述程序外，还应当及时向全体股东报告或进行信息披露。"},{"i":23,"n":"第二十三条","txt":"中国证监会派出机构应当对期货公司风险监管指标的计算过程及计算结果的真实性、准确性、完整性进行定期或者不定期检查。 中国证监会派出机构可以根据监管需要，要求期货公司聘请具有证券、期货相关业务资格的会计师事务所对其风险监管报表进行专项审计。"},{"i":24,"n":"第二十四条","txt":"期货公司的风险监管报表被相关会计师事务所出具了保留意见、带强调事项段或其他事项段无保留意见的，期货公司应当自审计意见出具的5个工作日内就涉及事项对风险监管指标的影响进行专项说明，并向住所地中国证监会派出机构进行书面报告。中国证监会派出机构可以视情况要求期货公司限期改正并重新编制风险监管报表；期货公司未限期改正的，中国证监会派出机构可以认定其风险监管指标不符合规定标准。 期货公司的风险监管报表被相关会计师事务所出具了无法表示意见或者否定意见的，中国证监会派出机构可以认定其风险监管指标不符合规定标准。"},{"i":25,"n":"第二十五条","txt":"期货公司未按期报送风险监管报表或者报送的风险监管报表存在虚假记载、误导性陈述、重大遗漏的，中国证监会派出机构应当要求期货公司限期报送或者补充更正。 期货公司未在限期内报送或者补充更正的，公司住所地中国证监会派出机构应当进行现场检查；发现期货公司违反企业会计准则和本办法有关规定的，可以认定其风险监管指标不符合规定标准。"},{"i":26,"n":"第二十六条","txt":"期货公司报送的风险监管报表存在漏报、错报，影响中国证监会及其派出机构对期货公司风险状况判断的，中国证监会派出机构应当要求期货公司立即报送更正的风险监管报表，并可以视情况采取出具警示函、监管谈话等监管措施。"},{"i":27,"n":"第二十七条","txt":"期货公司风险监管指标达到预警标准的，进入风险预警期。风险预警期内，中国证监会派出机构可视情况采取以下措施： （一）要求期货公司制定风险监管指标改善方案并定期对监管指标的改善情况进行书面报告； （二）要求期货公司进行重大业务决策时，应当至少提前5个工作日向住所地中国证监会派出机构报送临时报告，说明有关业务对风险监管指标的影响； （三）要求期货公司增加内部合规检查的频率，并提交合规检查报告。 期货公司未能有效履行相关要求的，中国证监会派出机构可以视情况采取出具警示函、监管谈话等监管措施。"},{"i":28,"n":"第二十八条","txt":"期货公司风险监管指标优于预警标准并连续保持3个月的，风险预警期结束。"},{"i":29,"n":"第二十九条","txt":"期货公司风险监管指标不符合规定标准的，中国证监会派出机构应当在知晓相关情况后2个工作日内对期货公司不符合规定标准的情况和原因进行核实，视情况对期货公司及其董事、监事和高级管理人员采取谈话、提示、记入信用记录等监管措施，并责令期货公司限期整改，整改期限不得超过20个工作日。"},{"i":30,"n":"第三十条","txt":"经过整改，期货公司风险监管指标符合规定标准的，应当向住所地中国证监会派出机构报告，中国证监会派出机构应当进行验收。 期货公司风险监管指标符合规定标准的，中国证监会派出机构应当自验收合格之日起3个工作日内解除对期货公司采取的有关措施。"},{"i":31,"n":"第三十一条","txt":"期货公司逾期未改正或者经过整改风险监管指标仍不符合规定标准的，中国证监会及其派出机构可以依据《期货交易管理条例》第五十五条采取监管措施。"},{"i":32,"n":"第三十二条","txt":"期货公司违反本办法规定的，中国证监会及其派出机构可以依据《期货交易管理条例》第六十六条的规定处罚。"},{"i":33,"n":"第三十三条","txt":"本办法相关用语含义如下： （一）风险监管报表是期货公司编制的反映各项风险监管指标计算过程及计算结果的报表。 （二）资产、流动资产是指期货公司的自身资产，不含客户保证金。 （三）负债、流动负债是指期货公司的对外负债，不含客户权益。 （四）重大业务，是指可能导致期货公司风险监管指标发生10%以上变化的业务。"},{"i":34,"n":"第三十四条","txt":"本办法自2017年10月1日起施行。《期货公司风险监管指标管理试行办法》（证监发〔2007〕55号公布、证监会公告〔2013〕12号修订）、《关于期货公司风险资本准备计算标准的规定》（证监会公告〔2013〕13号）同时废止。"}],"qihuotouzizhebaozhangjijinguanlibanfa":[{"i":1,"n":"第一条","txt":"为保护期货投资者的合法权益，根据《期货交易管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"期货投资者保障基金（以下简称保障基金）是在期货公司严重违法违规或者风险控制不力等导致保证金出现缺口，可能严重危及社会稳定和期货市场安全时，补偿投资者保证金损失的专项基金。"},{"i":3,"n":"第三条","txt":"期货交易活动实行公开、公平、公正和投资者投资决策自主、投资风险自担的原则。 投资者在期货投资活动中因期货市场波动或者投资品种价值本身发生变化所导致的损失，由投资者自行负担。"},{"i":4,"n":"第四条","txt":"保障基金按照取之于市场、用之于市场的原则筹集。保障基金的规模应当与期货市场的发展状况、市场风险水平相适应。"},{"i":5,"n":"第五条","txt":"保障基金由中国证监会集中管理、统筹使用。"},{"i":6,"n":"第六条","txt":"保障基金的管理和运用遵循公开、合理、有效的原则。"},{"i":7,"n":"第七条","txt":"保障基金的使用遵循保障投资者合法权益和公平救助原则，实行比例补偿。"},{"i":8,"n":"第八条","txt":"保障基金管理机构应当以保障基金名义设立资金专用账户，专户存储保障基金。"},{"i":9,"n":"第九条","txt":"保障基金的启动资金由期货交易所从其积累的风险准备金中按照截至2006年12月31日风险准备金账户总额的百分之十五缴纳形成。 保障基金的后续资金来源包括： （一）期货交易所按其向期货公司会员收取的交易手续费的一定比例缴纳； （二）期货公司从其收取的交易手续费中按照代理交易额的一定比例缴纳； （三）保障基金管理机构追偿或者接受的其他合法财产。 保障基金的后续资金缴纳比例，由中国证监会和财政部确定，并可根据期货市场发展状况、市场风险水平等情况进行调整。 对于因财务状况恶化、风险控制不力等存在较高风险的期货公司，应当按照较高比例缴纳保障基金，各期货公司的具体缴纳比例由中国证监会根据期货公司风险状况确定。期货交易所、期货公司缴纳的保障基金在其营业成本中列支。"},{"i":10,"n":"第十条","txt":"期货交易所、期货公司应当按年度缴纳保障基金。期货交易所应当在每年度结束后30个工作日内，缴纳前一年度应当缴纳的保障基金，并按照中国证监会和财政部确定的比例代扣代缴期货公司应当缴纳的保障基金。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，经中国证监会、财政部批准，期货交易所、期货公司可以暂停缴纳保障基金： （一）保障基金总额足以覆盖市场风险； （二）期货交易所、期货公司遭受重大突发市场风险或者不可抗力。 当前款情形消除后，经中国证监会、财政部批准，应当恢复缴纳。"},{"i":12,"n":"第十二条","txt":"对于新设立的期货公司，应当自产生经纪业务收入后纳入保障基金缴纳范围；公司停止经营的，应当告知期货交易所，对其当年应缴纳的保障基金份额进行扣缴。"},{"i":13,"n":"第十三条","txt":"鼓励保障基金来源多元化，保障基金可以接受社会捐赠和其他合法财产。 保障基金产生的利息以及运用所产生的各种收益等孳息归属保障基金。"},{"i":14,"n":"第十四条","txt":"中国证监会、财政部可以指定相关机构作为保障基金管理机构，代为管理保障基金。"},{"i":15,"n":"第十五条","txt":"对保障基金的管理应当遵循安全、稳健的原则，保证保障基金的安全。 保障基金的资金运用限于银行存款、购买国债、中央银行债券（包括中央银行票据）和中央级金融机构发行的金融债券，以及中国证监会和财政部批准的其他资金运用方式。"},{"i":16,"n":"第十六条","txt":"保障基金应当实行独立核算，分别管理，并与保障基金管理机构管理的其他资产有效隔离。 保障基金管理机构应当定期编报保障基金的筹集、管理、使用报告，经会计师事务所审计后，报送中国证监会和财政部。"},{"i":17,"n":"第十七条","txt":"保障基金管理机构、期货交易所及期货公司，应当妥善保存有关保障基金的财务凭证、账簿和报表等资料，确保财务记录和档案完整、真实。"},{"i":18,"n":"第十八条","txt":"财政部负责保障基金财务监管。保障基金的年度收支计划和决算报财政部批准。"},{"i":19,"n":"第十九条","txt":"中国证监会负责保障基金业务监管，对保障基金的筹集、管理和使用等情况进行定期核查。 中国证监会定期向保障基金管理机构通报期货公司总体风险状况。存在较高风险的期货公司应当每月向保障基金管理机构提供财务监管报表。"},{"i":20,"n":"第二十条","txt":"期货公司因严重违法违规或者风险控制不力等导致保证金出现缺口的，中国证监会可以按照本办法规定决定使用保障基金，对不能清偿的投资者保证金损失予以补偿。"},{"i":21,"n":"第二十一条","txt":"对期货投资者的保证金损失，保障基金按照下列原则予以补偿： （一）对每位个人投资者的保证金损失在10万元以下（含10万元）的部分全额补偿，超过10万元的部分按百分之九十补偿； （二）对每位机构投资者的保证金损失在10万元以下（含10万元）的部分全额补偿，超过10万元的部分按百分之八十补偿。 现有保障基金不足补偿的，由后续缴纳的保障基金补偿。"},{"i":22,"n":"第二十二条","txt":"使用保障基金前，中国证监会和保障基金管理机构应当监督期货公司核实投资者保证金权益及损失，积极清理资产并变现处置，应当先以自有资金和变现资产弥补保证金缺口。不足弥补或者情况危急的，方能决定使用保障基金。"},{"i":23,"n":"第二十三条","txt":"对投资者因参与非法期货交易而遭受的保证金损失，保障基金不予补偿。 对机构投资者以个人名义参与期货交易的，按照机构投资者补偿规则进行补偿。"},{"i":24,"n":"第二十四条","txt":"动用保障基金对期货投资者的保证金损失进行补偿后，保障基金管理机构依法取得相应的受偿权，可以依法参与期货公司清算。"},{"i":25,"n":"第二十五条","txt":"保障基金管理机构应当及时将保障基金的使用、补偿、追偿等情况报告中国证监会和财政部。"},{"i":26,"n":"第二十六条","txt":"期货公司因严重违法违规或者风险控制不力等导致保证金出现缺口的，中国证监会根据《期货交易管理条例》第六十六条、第六十七条进行处罚，吊销期货业务许可证。涉嫌犯罪的，依法移送司法机关。"},{"i":27,"n":"第二十七条","txt":"期货交易所、期货公司违反本办法规定，延期缴纳或者拒不缴纳保障基金以及不按规定保存、报送有关信息和资料的，中国证监会根据《期货交易管理条例》第六十四条、第六十六条进行处罚。"},{"i":28,"n":"第二十八条","txt":"对挪用、侵占、骗取保障基金的违法行为，依法查处；对有关失职人员，依法追究法律责任；涉嫌犯罪的，依法移送司法机关。"},{"i":29,"n":"第二十九条","txt":"本办法自2007年8月1日起施行。"}],"simutouzijijinjianduguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了规范私募投资基金活动，保护投资者及相关当事人的合法权益，促进私募投资基金行业健康发展，根据《证券投资基金法》、《国务院关于进一步促进资本市场健康发展的若干意见》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称私募投资基金（以下简称私募基金），是指在中华人民共和国境内，以非公开方式向投资者募集资金设立的投资基金。 私募基金财产的投资包括买卖股票、股权、债券、期货、期权、基金份额及投资合同约定的其他投资标的。 非公开募集资金，以进行投资活动为目的设立的公司或者合伙企业，资产由基金管理人或者普通合伙人管理的，其登记备案、资金募集和投资运作适用本办法。 证券公司、基金管理公司、期货公司及其子公司从事私募基金业务适用本办法，其他法律法规和中国证券监督管理委员会（以下简称中国证监会）有关规定对上述机构从事私募基金业务另有规定的，适用其规定。"},{"i":3,"n":"第三条","txt":"从事私募基金业务，应当遵循自愿、公平、诚实信用原则，维护投资者合法权益，不得损害国家利益和社会公共利益。"},{"i":4,"n":"第四条","txt":"私募基金管理人和从事私募基金托管业务的机构（以下简称私募基金托管人）管理、运用私募基金财产，从事私募基金销售业务的机构（以下简称私募基金销售机构）及其他私募服务机构从事私募基金服务活动，应当恪尽职守，履行诚实信用、谨慎勤勉的义务。 私募基金从业人员应当遵守法律、行政法规，恪守职业道德和行为规范。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依照《证券投资基金法》、本办法和中国证监会的其他有关规定，对私募基金业务活动实施监督管理。 设立私募基金管理机构和发行私募基金不设行政审批，允许各类发行主体在依法合规的基础上，向累计不超过法律规定数量的投资者发行私募基金。建立健全私募基金发行监管制度，切实强化事中事后监管，依法严厉打击以私募基金为名的各类非法集资活动。 建立促进经营机构规范开展私募基金业务的风险控制和自律管理制度，以及各类私募基金的统一监测系统。"},{"i":6,"n":"第六条","txt":"中国证券投资基金业协会（以下简称基金业协会）依照《证券投资基金法》、本办法、中国证监会其他有关规定和基金业协会自律规则，对私募基金业开展行业自律，协调行业关系，提供行业服务，促进行业发展。"},{"i":7,"n":"第七条","txt":"各类私募基金管理人应当根据基金业协会的规定，向基金业协会申请登记，报送以下基本信息： （一）工商登记和营业执照正副本复印件; （二）公司章程或者合伙协议； （三）主要股东或者合伙人名单； （四）高级管理人员的基本信息； （五）基金业协会规定的其他信息。 基金业协会应当在私募基金管理人登记材料齐备后的20个工作日内，通过网站公告私募基金管理人名单及其基本情况的方式，为私募基金管理人办结登记手续。"},{"i":8,"n":"第八条","txt":"各类私募基金募集完毕，私募基金管理人应当根据基金业协会的规定，办理基金备案手续，报送以下基本信息： （一）主要投资方向及根据主要投资方向注明的基金类别； （二）基金合同、公司章程或者合伙协议。资金募集过程中向投资者提供基金招募说明书的，应当报送基金招募说明书。以公司、合伙等企业形式设立的私募基金，还应当报送工商登记和营业执照正副本复印件； （三）采取委托管理方式的，应当报送委托管理协议。委托托管机构托管基金财产的，还应当报送托管协议； （四）基金业协会规定的其他信息。 基金业协会应当在私募基金备案材料齐备后的20个工作日内，通过网站公告私募基金名单及其基本情况的方式，为私募基金办结备案手续。"},{"i":9,"n":"第九条","txt":"基金业协会为私募基金管理人和私募基金办理登记备案不构成对私募基金管理人投资能力、持续合规情况的认可；不作为对基金财产安全的保证。"},{"i":10,"n":"第十条","txt":"私募基金管理人依法解散、被依法撤销、或者被依法宣告破产的，其法定代表人或者普通合伙人应当在20个工作日内向基金业协会报告，基金业协会应当及时注销基金管理人登记并通过网站公告。"},{"i":11,"n":"第十一条","txt":"私募基金应当向合格投资者募集，单只私募基金的投资者人数累计不得超过《证券投资基金法》、《公司法》、《合伙企业法》等法律规定的特定数量。 投资者转让基金份额的，受让人应当为合格投资者且基金份额受让后投资者人数应当符合前款规定。"},{"i":12,"n":"第十二条","txt":"私募基金的合格投资者是指具备相应风险识别能力和风险承担能力，投资于单只私募基金的金额不低于100万元且符合下列相关标准的单位和个人： （一）净资产不低于1000万元的单位； （二）金融资产不低于300万元或者最近三年个人年均收入不低于50万元的个人。 前款所称金融资产包括银行存款、股票、债券、基金份额、资产管理计划、银行理财产品、信托计划、保险产品、期货权益等。"},{"i":13,"n":"第十三条","txt":"下列投资者视为合格投资者： 社会保障基金、企业年金等养老基金，慈善基金等社会公益基金； 依法设立并在基金业协会备案的投资计划； 投资于所管理私募基金的私募基金管理人及其从业人员； （四）中国证监会规定的其他投资者。 以合伙企业、契约等非法人形式，通过汇集多数投资者的资金直接或者间接投资于私募基金的，私募基金管理人或者私募基金销售机构应当穿透核查最终投资者是否为合格投资者，并合并计算投资者人数。但是，符合本条第（一）、（二）、（四）项规定的投资者投资私募基金的，不再穿透核查最终投资者是否为合格投资者和合并计算投资者人数。"},{"i":14,"n":"第十四条","txt":"私募基金管理人、私募基金销售机构不得向合格投资者之外的单位和个人募集资金，不得通过报刊、电台、电视、互联网等公众传播媒体或者讲座、报告会、分析会和布告、传单、手机短信、微信、博客和电子邮件等方式，向不特定对象宣传推介。"},{"i":15,"n":"第十五条","txt":"私募基金管理人、私募基金销售机构不得向投资者承诺投资本金不受损失或者承诺最低收益。"},{"i":16,"n":"第十六条","txt":"私募基金管理人自行销售私募基金的，应当采取问卷调查等方式，对投资者的风险识别能力和风险承担能力进行评估，由投资者书面承诺符合合格投资者条件；应当制作风险揭示书，由投资者签字确认。 私募基金管理人委托销售机构销售私募基金的，私募基金销售机构应当采取前款规定的评估、确认等措施。 投资者风险识别能力和承担能力问卷及风险揭示书的内容与格式指引，由基金业协会按照不同类别私募基金的特点制定。"},{"i":17,"n":"第十七条","txt":"私募基金管理人自行销售或者委托销售机构销售私募基金，应当自行或者委托第三方机构对私募基金进行风险评级，向风险识别能力和风险承担能力相匹配的投资者推介私募基金。"},{"i":18,"n":"第十八条","txt":"投资者应当如实填写风险识别能力和承担能力问卷，如实承诺资产或者收入情况，并对其真实性、准确性和完整性负责。填写虚假信息或者提供虚假承诺文件的，应当承担相应责任。"},{"i":19,"n":"第十九条","txt":"投资者应当确保投资资金来源合法，不得非法汇集他人资金投资私募基金。"},{"i":20,"n":"第二十条","txt":"募集私募证券基金，应当制定并签订基金合同、公司章程或者合伙协议（以下统称基金合同）。基金合同应当符合《证券投资基金法》第九十三条、第九十四条规定。 募集其他种类私募基金，基金合同应当参照《证券投资基金法》第九十三条、第九十四条规定，明确约定各方当事人的权利、义务和相关事宜。"},{"i":21,"n":"第二十一条","txt":"除基金合同另有约定外，私募基金应当由基金托管人托管。 基金合同约定私募基金不进行托管的，应当在基金合同中明确保障私募基金财产安全的制度措施和纠纷解决机制。"},{"i":22,"n":"第二十二条","txt":"同一私募基金管理人管理不同类别私募基金的，应当坚持专业化管理原则；管理可能导致利益输送或者利益冲突的不同私募基金的，应当建立防范利益输送和利益冲突的机制。"},{"i":23,"n":"第二十三条","txt":"私募基金管理人、私募基金托管人、私募基金销售机构及其他私募服务机构及其从业人员从事私募基金业务，不得有以下行为： （一）将其固有财产或者他人财产混同于基金财产从事投资活动； （二）不公平地对待其管理的不同基金财产； （三）利用基金财产或者职务之便，为本人或者投资者以外的人牟取利益，进行利益输送； （四）侵占、挪用基金财产； （五）泄露因职务便利获取的未公开信息，利用该信息从事或者明示、暗示他人从事相关的交易活动； （六）从事损害基金财产和投资者利益的投资活动； （七）玩忽职守，不按照规定履行职责； （八）从事内幕交易、操纵交易价格及其他不正当交易活动； （九）法律、行政法规和中国证监会规定禁止的其他行为。"},{"i":24,"n":"第二十四条","txt":"私募基金管理人、私募基金托管人应当按照合同约定，如实向投资者披露基金投资、资产负债、投资收益分配、基金承担的费用和业绩报酬、可能存在的利益冲突情况以及可能影响投资者合法权益的其他重大信息，不得隐瞒或者提供虚假信息。信息披露规则由基金业协会另行制定。"},{"i":25,"n":"第二十五条","txt":"私募基金管理人应当根据基金业协会的规定，及时填报并定期更新管理人及其从业人员的有关信息、所管理私募基金的投资运作情况和杠杆运用情况，保证所填报内容真实、准确、完整。发生重大事项的，应当在10个工作日内向基金业协会报告。 私募基金管理人应当于每个会计年度结束后的4个月内，向基金业协会报送经会计师事务所审计的年度财务报告和所管理私募基金年度投资运作基本情况。"},{"i":26,"n":"第二十六条","txt":"私募基金管理人、私募基金托管人及私募基金销售机构应当妥善保存私募基金投资决策、交易和投资者适当性管理等方面的记录及其他相关资料，保存期限自基金清算终止之日起不得少于10年。"},{"i":27,"n":"第二十七条","txt":"基金业协会应当建立私募基金管理人登记、私募基金备案管理信息系统。 基金业协会应当对私募基金管理人和私募基金信息严格保密。除法律法规另有规定外，不得对外披露。"},{"i":28,"n":"第二十八条","txt":"基金业协会应当建立与中国证监会及其派出机构和其他相关机构的信息共享机制，定期汇总分析私募基金情况，及时提供私募基金相关信息。"},{"i":29,"n":"第二十九条","txt":"基金业协会应当制定和实施私募基金行业自律规则，监督、检查会员及其从业人员的执业行为。 会员及其从业人员违反法律、行政法规、本办法规定和基金业协会自律规则的，基金业协会可以视情节轻重，采取自律管理措施，并通过网站公开相关违法违规信息。会员及其从业人员涉嫌违法违规的，基金业协会应当及时报告中国证监会。"},{"i":30,"n":"第三十条","txt":"基金业协会应当建立投诉处理机制，受理投资者投诉，进行纠纷调解。"},{"i":31,"n":"第三十一条","txt":"中国证监会及其派出机构依法对私募基金管理人、私募基金托管人、私募基金销售机构及其他私募服务机构开展私募基金业务情况进行统计监测和检查，依照《证券投资基金法》第一百一十四条规定采取有关措施。"},{"i":32,"n":"第三十二条","txt":"中国证监会将私募基金管理人、私募基金托管人、私募基金销售机构及其他私募服务机构及其从业人员诚信信息记入证券期货市场诚信档案数据库；根据私募基金管理人的信用状况，实施差异化监管。"},{"i":33,"n":"第三十三条","txt":"私募基金管理人、私募基金托管人、私募基金销售机构及其他私募服务机构及其从业人员违反法律、行政法规及本办法规定，中国证监会及其派出机构可以对其采取责令改正、监管谈话、出具警示函、公开谴责等行政监管措施。"},{"i":34,"n":"第三十四条","txt":"本办法所称创业投资基金，是指主要投资于未上市创业企业普通股或者依法可转换为普通股的优先股、可转换债券等权益的股权投资基金。"},{"i":35,"n":"第三十五条","txt":"鼓励和引导创业投资基金投资创业早期的小微企业。 享受国家财政税收扶持政策的创业投资基金，其投资范围应当符合国家相关规定。"},{"i":36,"n":"第三十六条","txt":"基金业协会在基金管理人登记、基金备案、投资情况报告要求和会员管理等环节，对创业投资基金采取区别于其他私募基金的差异化行业自律，并提供差异化会员服务。"},{"i":37,"n":"第三十七条","txt":"中国证监会及其派出机构对创业投资基金在投资方向检查等环节，采取区别于其他私募基金的差异化监督管理；在账户开立、发行交易和投资退出等方面，为创业投资基金提供便利服务。"},{"i":38,"n":"第三十八条","txt":"私募基金管理人、私募基金托管人、私募基金销售机构及其他私募服务机构及其从业人员违反本办法第七条、第八条、第十一条、第十四条至第十七条、第二十四条至第二十六条规定的，以及有本办法第二十三条第一项至第七项和第九项所列行为之一的，责令改正，给予警告并处三万元以下罚款；对直接负责的主管人员和其他直接责任人员，给予警告并处三万元以下罚款；有本办法第二十三条第八项行为的，按照《证券法》和《期货交易管理条例》的有关规定处罚；构成犯罪的，依法移交司法机关追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"私募基金管理人、私募基金托管人、私募基金销售机构及其他私募服务机构及其从业人员违反法律法规和本办法规定，情节严重的，中国证监会可以依法对有关责任人员采取市场禁入措施。"},{"i":40,"n":"第四十条","txt":"私募证券基金管理人及其从业人员违反《证券投资基金法》有关规定的，按照《证券投资基金法》有关规定处罚。"},{"i":41,"n":"第四十一条","txt":"本办法自公布之日起施行。"}],"kechuangbanshangshigongsichixujianguanbanfa":[{"i":1,"n":"第一条","txt":"为了规范科创企业股票、存托凭证在上海证券交易所（以下简称交易所）科创板上市后相关各方的行为，支持引导科技创新企业更好地发展，保护投资者合法权益，根据《中华人民共和国证券法》（以下简称《证券法》）、《中华人民共和国公司法》、《国务院办公厅转发证监会关于开展创新企业境内发行股票或存托凭证试点若干意见的通知》、《关于在上海证券交易所设立科创板并试点注册制的实施意见》（以下简称《实施意见》）以及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中国证券监督管理委员会（以下简称中国证监会）根据《证券法》等法律法规、《实施意见》、本办法和中国证监会其他相关规定，对科创板上市公司（以下简称科创公司）及相关主体进行监督管理。中国证监会其他相关规定与本办法规定不一致的，适用本办法。"},{"i":3,"n":"第三条","txt":"交易所根据《实施意见》、《证券交易所管理办法》、本办法等有关规定，建立以上市规则为中心的科创板持续监管规则体系，在持续信息披露、股份减持、并购重组、股权激励、退市等方面制定符合科创公司特点的具体实施规则。科创公司应当遵守交易所持续监管实施规则。 交易所应当履行一线监管职责，加强信息披露与二级市场交易监管联动，加大现场检查力度，强化监管问询，切实防范和打击内幕交易与操纵市场行为，督促科创公司提高信息披露质量。"},{"i":4,"n":"第四条","txt":"科创公司应当保持健全、有效、透明的治理体系和监督机制，保证股东大会、董事会、监事会规范运作，督促董事、监事和高级管理人员履行忠实、勤勉义务，保障全体股东合法权利，积极履行社会责任，保护利益相关者的基本权益。"},{"i":5,"n":"第五条","txt":"科创公司控股股东、实际控制人应当诚实守信，依法行使权利，严格履行承诺，维持公司独立性，维护公司和全体股东的共同利益。"},{"i":6,"n":"第六条","txt":"科创公司应当积极回报股东，根据自身条件和发展阶段，制定并执行现金分红、股份回购等股东回报政策。交易所可以制定股东回报相关规则。"},{"i":7,"n":"第七条","txt":"存在特别表决权股份的科创公司，应当在公司章程中规定特别表决权股份的持有人资格、特别表决权股份拥有的表决权数量与普通股份拥有的表决权数量的比例安排、持有人所持特别表决权股份能够参与表决的股东大会事项范围、特别表决权股份锁定安排及转让限制、特别表决权股份与普通股份的转换情形等事项。公司章程有关上述事项的规定，应当符合交易所的有关规定。 科创公司应当在定期报告中持续披露特别表决权安排的情况；特别表决权安排发生重大变化的，应当及时披露。 交易所应对存在特别表决权股份科创公司的上市条件、表决权差异的设置、存续、调整、信息披露和投资者保护事项制定有关规定。"},{"i":8,"n":"第八条","txt":"科创公司和相关信息披露义务人应当及时、公平地披露所有可能对证券交易价格或者投资决策有较大影响的事项，保证所披露信息的真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏。"},{"i":9,"n":"第九条","txt":"控股股东和实际控制人应当积极配合科创公司履行信息披露义务，不得要求或者协助科创公司隐瞒应当披露的信息。"},{"i":10,"n":"第十条","txt":"科创公司筹划的重大事项存在较大不确定性，立即披露可能会损害公司利益或者误导投资者，且有关内幕信息知情人已书面承诺保密的，公司可以暂不披露，但最迟应在该重大事项形成最终决议、签署最终协议、交易确定能够达成时对外披露。已经泄密或确实难以保密的，科创公司应当立即披露该信息。"},{"i":11,"n":"第十一条","txt":"科创公司应当结合所属行业特点，充分披露行业经营信息，尤其是科研水平、科研人员、科研投入等能够反映行业竞争力的信息以及核心技术人员任职及持股情况，便于投资者合理决策。"},{"i":12,"n":"第十二条","txt":"科创公司应当充分披露可能对公司核心竞争力、经营活动和未来发展产生重大不利影响的风险因素。 科创公司尚未盈利的，应当充分披露尚未盈利的成因，以及对公司现金流、业务拓展、人才吸引、团队稳定性、研发投入、战略性投入、生产经营可持续性等方面的影响。"},{"i":13,"n":"第十三条","txt":"科创公司和相关信息披露义务人认为相关信息有助于投资者决策，但不属于依法应当披露信息的，可以自愿披露。 科创公司自愿披露的信息应当真实、准确、完整，科创公司不得利用该等信息不当影响公司股票价格，并应当按照同一标准披露后续类似事件。"},{"i":14,"n":"第十四条","txt":"科创公司和信息披露义务人确有需要的，可以在非交易时段对外发布重大信息，但应当在下一交易时段开始前披露相关公告，不得以新闻发布或者答记者问等形式代替信息披露。"},{"i":15,"n":"第十五条","txt":"科创公司和相关信息披露义务人适用中国证监会、交易所相关信息披露规定，可能导致其难以反映经营活动的实际情况、难以符合行业监管要求或者公司注册地有关规定的，可以依照有关规定暂缓适用或免于适用，但是应当充分说明原因和替代方案，并聘请律师事务所出具法律意见。中国证监会、交易所认为依法不应调整适用的，科创公司和相关信息披露义务人应当执行相关规定。"},{"i":16,"n":"第十六条","txt":"股份锁定期届满后，科创公司控股股东、实际控制人、董事、监事、高级管理人员、核心技术人员及其他股东减持首次公开发行前已发行的股份（以下简称首发前股份）以及通过非公开发行方式取得的股份的，应当遵守交易所有关减持方式、程序、价格、比例以及后续转让等事项的规定。"},{"i":17,"n":"第十七条","txt":"上市时未盈利的科创公司，其控股股东、实际控制人、董事、监事、高级管理人员、核心技术人员所持首发前股份的股份锁定期应适当延长，具体期限由交易所规定。"},{"i":18,"n":"第十八条","txt":"科创公司核心技术人员所持首发前股份的股份锁定期应适当延长，具体期限由交易所规定。"},{"i":19,"n":"第十九条","txt":"科创公司并购重组，由交易所统一审核；涉及发行股票的，由交易所审核通过后报经中国证监会履行注册程序。审核标准等事项由交易所规定。"},{"i":20,"n":"第二十条","txt":"科创公司重大资产重组或者发行股份购买资产，标的资产应当符合科创板定位，并与公司主营业务具有协同效应。"},{"i":21,"n":"第二十一条","txt":"科创公司以本公司股票为标的实施股权激励的，应当设置合理的公司业绩和个人绩效等考核指标，有利于公司持续发展。"},{"i":22,"n":"第二十二条","txt":"单独或合计持有科创公司5%以上股份的股东或实际控制人及其配偶、父母、子女，作为董事、高级管理人员、核心技术人员或者核心业务人员的，可以成为激励对象。 科创公司应当充分说明前款规定人员成为激励对象的必要性、合理性。"},{"i":23,"n":"第二十三条","txt":"科创公司授予激励对象的限制性股票，包括符合股权激励计划授予条件的激励对象在满足相应条件后分次获得并登记的本公司股票。 限制性股票的授予和登记等事项，应当遵守交易所和证券登记结算机构的有关规定。"},{"i":24,"n":"第二十四条","txt":"科创公司授予激励对象限制性股票的价格，低于市场参考价50%的，应符合交易所有关规定，并应说明定价依据及定价方式。 出现前款规定情形的，科创公司应当聘请独立财务顾问，对股权激励计划的可行性、相关定价依据和定价方法的合理性、是否有利于公司持续发展、是否损害股东利益等发表意见。"},{"i":25,"n":"第二十五条","txt":"科创公司全部在有效期内的股权激励计划所涉及的标的股票总数，累计不得超过公司总股本的20%。"},{"i":26,"n":"第二十六条","txt":"科创公司触及终止上市标准的，股票直接终止上市，不再适用暂停上市、恢复上市、重新上市程序。"},{"i":27,"n":"第二十七条","txt":"科创公司构成欺诈发行、重大信息披露违法或者其他涉及国家安全、公共安全、生态安全、生产安全和公众健康安全等领域的重大违法行为的，股票应当终止上市。"},{"i":28,"n":"第二十八条","txt":"科创公司股票交易量、股价、市值、股东人数等交易指标触及终止上市标准的，股票应当终止上市，具体标准由交易所规定。"},{"i":29,"n":"第二十九条","txt":"科创公司丧失持续经营能力，财务指标触及终止上市标准的，股票应当终止上市。 科创板不适用单一的连续亏损终止上市指标，交易所应当设置能够反映公司持续经营能力的组合终止上市指标。"},{"i":30,"n":"第三十条","txt":"科创公司信息披露或者规范运作方面存在重大缺陷，严重损害投资者合法权益、严重扰乱证券市场秩序的，其股票应当终止上市。交易所可依据《证券法》在上市规则中作出具体规定。"},{"i":31,"n":"第三十一条","txt":"达到一定规模的上市公司，可以依据法律法规、中国证监会和交易所有关规定，分拆业务独立、符合条件的子公司在科创板上市。"},{"i":32,"n":"第三十二条","txt":"科创公司应当建立完善募集资金管理使用制度，按照交易所规定持续披露募集资金使用情况和募集资金重点投向科技创新领域的具体安排。"},{"i":33,"n":"第三十三条","txt":"科创公司控股股东、实际控制人质押公司股份的，应当合理使用融入资金，维持科创公司控制权和生产经营稳定，不得侵害科创公司利益或者向科创公司转移风险，并依据中国证监会、交易所的规定履行信息披露义务。"},{"i":34,"n":"第三十四条","txt":"科创公司及其股东、实际控制人、董事、监事、高级管理人员、其他信息披露义务人、内幕信息知情人等相关主体违反本办法的，中国证监会根据《证券法》等法律法规和中国证监会其他有关规定，依法追究其法律责任。"},{"i":35,"n":"第三十五条","txt":"中国证监会会同有关部门，加强对科创公司等相关市场主体的诚信信息共享，完善失信联合惩戒机制。"},{"i":36,"n":"第三十六条","txt":"本办法自公布之日起施行。"}],"kechuangbanshangshigongsizhengquanfaxingzhuceguanl32cb50":[{"i":1,"n":"第一条","txt":"为了规范科创板上市公司（以下简称上市公司）证券发行行为，保护投资者合法权益和社会公共利益，根据《中华人民共和国证券法》（以下简称《证券法》）《国务院办公厅关于贯彻实施修订后的证券法有关工作的通知》《关于在上海证券交易所设立科创板并试点注册制的实施意见》《国务院办公厅转发证监会关于开展创新企业境内发行股票或存托凭证试点若干意见的通知》（以下简称《若干意见》）及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"上市公司申请在境内发行证券，适用本办法。 本办法所称证券，指下列证券品种： （一）股票； （二）可转换公司债券（以下简称可转债）； （三）存托凭证； （四）中国证券监督管理委员会（以下简称中国证监会）认可的其他品种。 前款所称可转债，是指上市公司依法发行、在一定期间内依据约定的条件可以转换成股份的公司债券。"},{"i":3,"n":"第三条","txt":"上市公司发行证券，可以向不特定对象发行，也可以向特定对象发行。 向不特定对象发行证券包括上市公司向原股东配售股份（以下简称配股）、向不特定对象募集股份（以下简称增发）和向不特定对象发行可转债。 向特定对象发行证券包括上市公司向特定对象发行股票、向特定对象发行可转债。"},{"i":4,"n":"第四条","txt":"上市公司发行证券的，应当符合《证券法》和本办法规定的发行条件和相关信息披露要求，依法经上海证券交易所（以下简称交易所）发行上市审核并报经中国证监会注册，但因依法实行股权激励、公积金转为增加公司资本、分配股票股利的除外。"},{"i":5,"n":"第五条","txt":"上市公司应当诚实守信，依法充分披露投资者作出价值判断和投资决策所必需的信息，所披露信息必须真实、准确、完整，简明清晰、通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 上市公司应当按照保荐人、证券服务机构要求，依法向其提供真实、准确、完整的财务会计资料和其他资料，配合相关机构开展尽职调查和其他相关工作。 上市公司控股股东、实际控制人、董事、监事、高级管理人员应当配合相关机构开展尽职调查和其他相关工作，不得要求或者协助上市公司隐瞒应当提供的资料或者应当披露的信息。"},{"i":6,"n":"第六条","txt":"保荐人应当诚实守信，勤勉尽责，按照依法制定的业务规则和行业自律规范的要求，充分了解上市公司经营情况和风险，对注册申请文件和信息披露资料进行全面核查验证，对上市公司是否符合发行条件独立作出专业判断，审慎作出推荐决定，并对募集说明书或者其他信息披露文件及其所出具的相关文件的真实性、准确性、完整性负责。"},{"i":7,"n":"第七条","txt":"证券服务机构应当严格遵守法律法规、中国证监会制定的监管规则、业务规则和本行业公认的业务标准和道德规范，建立并保持有效的质量控制体系，保护投资者合法权益，审慎履行职责，作出专业判断与认定，并对募集说明书或者其他信息披露文件中与其专业职责有关的内容及其所出具的文件的真实性、准确性、完整性负责。 证券服务机构及其相关执业人员应当对与本专业相关的业务事项履行特别注意义务，对其他业务事项履行普通注意义务，并承担相应法律责任。 证券服务机构及其执业人员从事证券服务业务应当配合中国证监会的监督管理，在规定的期限内提供、报送或披露相关资料、信息，并保证其提供、报送或披露的资料、信息真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 证券服务机构应当妥善保存客户委托文件、核查和验证资料、工作底稿以及与质量控制、内部管理、业务经营有关的信息和资料。"},{"i":8,"n":"第八条","txt":"对上市公司发行证券申请予以注册，不表明中国证监会和交易所对该证券的投资价值或者投资者的收益作出实质性判断或者保证，也不表明中国证监会和交易所对申请文件的真实性、准确性、完整性作出保证。"},{"i":9,"n":"第九条","txt":"上市公司向不特定对象发行股票，应当符合下列规定： （一）具备健全且运行良好的组织机构； （二）现任董事、监事和高级管理人员具备法律、行政法规规定的任职要求； （三）具有完整的业务体系和直接面向市场独立经营的能力，不存在对持续经营有重大不利影响的情形； （四）会计基础工作规范，内部控制制度健全且有效执行，财务报表的编制和披露符合企业会计准则和相关信息披露规则的规定，在所有重大方面公允反映了上市公司的财务状况、经营成果和现金流量，最近三年财务会计报告被出具无保留意见审计报告； （五）除金融类企业外，最近一期末不存在金额较大的财务性投资。"},{"i":10,"n":"第十条","txt":"上市公司存在下列情形之一的，不得向不特定对象发行股票： （一）擅自改变前次募集资金用途未作纠正，或者未经股东大会认可； （二）上市公司及其现任董事、监事和高级管理人员最近三年受到中国证监会行政处罚，或者最近一年受到证券交易所公开谴责，或者因涉嫌犯罪正被司法机关立案侦查或者涉嫌违法违规正在被中国证监会立案调查； （三）上市公司及其控股股东、实际控制人最近一年存在未履行向投资者作出的公开承诺的情形； （四）上市公司及其控股股东、实际控制人最近三年存在贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的刑事犯罪，或者存在严重损害上市公司利益、投资者合法权益、社会公共利益的重大违法行为。"},{"i":11,"n":"第十一条","txt":"上市公司存在下列情形之一的，不得向特定对象发行股票： （一）擅自改变前次募集资金用途未作纠正，或者未经股东大会认可； （二）最近一年财务报表的编制和披露在重大方面不符合企业会计准则或者相关信息披露规则的规定;最近一年财务会计报告被出具否定意见或者无法表示意见的审计报告;最近一年财务会计报告被出具保留意见的审计报告，且保留意见所涉及事项对上市公司的重大不利影响尚未消除。本次发行涉及重大资产重组的除外； （三）现任董事、监事和高级管理人员最近三年受到中国证监会行政处罚，或者最近一年受到证券交易所公开谴责； （四）上市公司及其现任董事、监事和高级管理人员因涉嫌犯罪正在被司法机关立案侦查或者涉嫌违法违规正被中国证监会立案调查； （五）控股股东、实际控制人最近三年存在严重损害上市公司利益或者投资者合法权益的重大违法行为； （六）最近三年存在严重损害投资者合法权益或者社会公共利益的重大违法行为。"},{"i":12,"n":"第十二条","txt":"上市公司发行股票，募集资金使用应当符合下列规定： （一）应当投资于科技创新领域的业务； （二）符合国家产业政策和有关环境保护、土地管理等法律、行政法规规定； （三）募集资金项目实施后，不会与控股股东、实际控制人及其控制的其他企业新增构成重大不利影响的同业竞争、显失公平的关联交易，或者严重影响公司生产经营的独立性。"},{"i":13,"n":"第十三条","txt":"上市公司发行可转债，应当符合下列规定： （一）具备健全且运行良好的组织机构； （二）最近三年平均可分配利润足以支付公司债券一年的利息； （三）具有合理的资产负债结构和正常的现金流量。 除前款规定条件外，上市公司向不特定对象发行可转债，还应当遵守本办法第九条第（二）项至第（五）项、第十条的规定；向特定对象发行可转债，还应当遵守本办法第十一条的规定。但是，按照公司债券募集办法，上市公司通过收购本公司股份的方式进行公司债券转换的除外。"},{"i":14,"n":"第十四条","txt":"上市公司存在下列情形之一的，不得发行可转债： （一）对已公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，仍处于继续状态； （二）违反《证券法》规定，改变公开发行公司债券所募资金用途。"},{"i":15,"n":"第十五条","txt":"上市公司发行可转债，募集资金除不得用于弥补亏损和非生产性支出外，还应当遵守本办法第十二条的规定。"},{"i":16,"n":"第十六条","txt":"上市公司申请发行证券，董事会应当依法就下列事项作出决议，并提请股东大会批准： （一）本次证券发行的方案； （二）本次发行方案的论证分析报告； （三）本次募集资金使用的可行性报告； （四）其他必须明确的事项。 上市公司董事会拟引入战略投资者的，应当将引入战略投资者的事项作为单独议案，就每名战略投资者单独审议，并提交股东大会批准。 董事会依照前二款作出决议，董事会决议日与首次公开发行股票上市日的时间间隔不得少于六个月。"},{"i":17,"n":"第十七条","txt":"董事会在编制本次发行方案的论证分析报告时，应当结合上市公司所处行业和发展阶段、融资规划、财务状况、资金需求等情况进行论证分析，独立董事应当发表专项意见。论证分析报告至少应当包括下列内容： （一）本次发行证券及其品种选择的必要性； （二）本次发行对象的选择范围、数量和标准的适当性； （三）本次发行定价的原则、依据、方法和程序的合理性； （四）本次发行方式的可行性； （五）本次发行方案的公平性、合理性； （六）本次发行对原股东权益或者即期回报摊薄的影响以及填补的具体措施。"},{"i":18,"n":"第十八条","txt":"股东大会就发行证券作出的决定，至少应当包括下列事项： （一）本次发行证券的种类和数量； （二）发行方式、发行对象及向原股东配售的安排； （三）定价方式或者价格区间； （四）募集资金用途； （五）决议的有效期； （六）对董事会办理本次发行具体事宜的授权； （七）其他必须明确的事项。"},{"i":19,"n":"第十九条","txt":"股东大会就发行可转债作出的决定，至少应当包括下列事项： （一）本办法第十八条规定的事项； （二）债券利率； （三）债券期限； （四）赎回条款； （五）回售条款； （六）还本付息的期限和方式； （七）转股期； （八）转股价格的确定和修正。"},{"i":20,"n":"第二十条","txt":"股东大会就发行证券事项作出决议，必须经出席会议的股东所持表决权的三分之二以上通过，中小投资者表决情况应当单独计票。向本公司特定的股东及其关联人发行证券的，股东大会就发行方案进行表决时，关联股东应当回避。股东大会对引入战略投资者议案作出决议的，应当就每名战略投资者单独表决。 上市公司就发行证券事项召开股东大会，应当提供网络投票方式，公司还可以通过其他方式为股东参加股东大会提供便利。"},{"i":21,"n":"第二十一条","txt":"上市公司年度股东大会可以根据公司章程的规定，授权董事会决定向特定对象发行融资总额不超过人民币三亿元且不超过最近一年末净资产百分之二十的股票，该项授权在下一年度股东大会召开日失效。 上市公司年度股东大会给予董事会前款授权的，应当就本办法第十八条规定的事项通过相关决定。"},{"i":22,"n":"第二十二条","txt":"上市公司申请发行证券，应当按照中国证监会有关规定制作注册申请文件，依法由保荐人保荐并向交易所申报。 交易所收到注册申请文件后，五个工作日内作出是否受理的决定。"},{"i":23,"n":"第二十三条","txt":"申请文件受理后，未经中国证监会或者交易所同意，不得改动。 发生重大事项的，上市公司、保荐人、证券服务机构应当及时向交易所报告，并按要求更新申请文件和信息披露资料。"},{"i":24,"n":"第二十四条","txt":"交易所审核部门负责审核上市公司证券发行上市申请；科创板上市委员会负责对上市公司向不特定对象发行证券的申请文件和审核部门出具的审核报告提出审议意见。 交易所主要通过向上市公司提出审核问询、上市公司回答问题方式开展审核工作，判断上市公司发行申请是否符合发行条件和信息披露要求。"},{"i":25,"n":"第二十五条","txt":"上市公司应当向交易所报送审核问询回复的相关文件，并以临时公告的形式披露交易所审核问询回复意见。"},{"i":26,"n":"第二十六条","txt":"交易所按照规定的条件和程序，形成上市公司是否符合发行条件和信息披露要求的审核意见，认为上市公司符合发行条件和信息披露要求的，将审核意见、上市公司注册申请文件及相关审核资料报中国证监会注册；认为上市公司不符合发行条件或者信息披露要求的，作出终止发行上市审核决定。"},{"i":27,"n":"第二十七条","txt":"交易所应当自受理注册申请文件之日起二个月内形成审核意见，但本办法另有规定的除外。 上市公司根据要求补充、修改申请文件，或者交易所按照规定对上市公司实施现场检查，要求保荐人、证券服务机构对有关事项进行专项核查，并要求上市公司补充、修改申请文件的时间不计算在内。"},{"i":28,"n":"第二十八条","txt":"符合相关规定的上市公司按照本办法第二十一条规定申请向特定对象发行股票的，适用简易程序。"},{"i":29,"n":"第二十九条","txt":"交易所采用简易程序的，应当在收到注册申请文件后，二个工作日内作出是否受理的决定，自受理之日起三个工作日内完成审核并形成上市公司是否符合发行条件和信息披露要求的审核意见。 交易所应当制定简易程序的业务规则，并报中国证监会批准。"},{"i":30,"n":"第三十条","txt":"中国证监会依法履行发行注册程序，主要关注交易所发行上市审核内容有无遗漏，审核程序是否符合规定，以及上市公司在发行条件和信息披露要求的重大方面是否符合相关规定。中国证监会认为存在需要进一步说明或者落实事项的，可以要求交易所进一步问询。 中国证监会认为交易所对影响发行条件的重大事项未予关注或者交易所的审核意见依据明显不充分的，可以退回交易所补充审核。交易所补充审核后，认为上市公司符合发行条件和信息披露要求的，重新向中国证监会报送审核意见及相关资料，本办法第三十一条规定的注册期限重新计算。"},{"i":31,"n":"第三十一条","txt":"中国证监会在十五个工作日内对上市公司的注册申请作出予以注册或者不予注册的决定。 上市公司根据要求补充、修改注册申请文件，或者中国证监会要求交易所进一步问询，要求保荐人、证券服务机构等对有关事项进行核查，对上市公司现场检查，并要求上市公司补充、修改申请文件的时间不计算在内。 中国证监会收到交易所依照本办法第二十九条规定报送的审核意见、上市公司注册申请文件及相关审核资料后，三个工作日内作出予以注册或者不予注册的决定。"},{"i":32,"n":"第三十二条","txt":"中国证监会的予以注册决定，自作出之日起一年内有效，上市公司应当在注册决定有效期内发行证券，发行时点由上市公司自主选择。 适用简易程序的，应当在中国证监会作出予以注册决定后十个工作日内完成发行缴款，未完成的，本次发行批文失效。"},{"i":33,"n":"第三十三条","txt":"中国证监会作出予以注册决定后、上市公司证券上市交易前，上市公司应当及时更新信息披露文件；保荐人以及证券服务机构应当持续履行尽职调查职责；发生重大事项的，上市公司、保荐人应当及时向交易所报告。 交易所应当对上述事项及时处理，发现上市公司存在重大事项影响发行条件的，应当出具明确意见并及时向中国证监会报告。"},{"i":34,"n":"第三十四条","txt":"中国证监会作出予以注册决定后、上市公司证券上市交易前，发现可能影响本次发行的重大事项的，中国证监会可以要求上市公司暂缓发行、上市；相关重大事项导致上市公司不符合发行条件的，应当撤销注册。 中国证监会撤销注册后，证券尚未发行的，上市公司应当停止发行；证券已经发行尚未上市的，上市公司应当按照发行价并加算银行同期存款利息返还证券持有人。"},{"i":35,"n":"第三十五条","txt":"交易所认为上市公司不符合发行条件或者信息披露要求，作出终止发行上市审核决定，或者中国证监会作出不予注册决定的，自决定作出之日起六个月后，上市公司可以再次提出证券发行申请。"},{"i":36,"n":"第三十六条","txt":"上市公司证券发行上市审核或者注册程序的中止、终止等情形参照适用《科创板首次公开发行股票注册管理办法（试行）》的相关规定。"},{"i":37,"n":"第三十七条","txt":"中国证监会和交易所可以对上市公司进行现场检查，或者要求保荐人、证券服务机构对有关事项进行专项核查并出具意见。"},{"i":38,"n":"第三十八条","txt":"上市公司发行证券，应当以投资者决策需求为导向，按照中国证监会制定的信息披露规则，编制募集说明书或者其他信息披露文件，依法履行信息披露义务，保证相关信息真实、准确、完整。信息披露内容应当简明清晰，通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。 中国证监会制定的信息披露规则是信息披露的最低要求。不论上述规则是否有明确规定，凡是投资者作出价值判断和投资决策所必需的信息，上市公司均应当充分披露，内容应当真实、准确、完整。"},{"i":39,"n":"第三十九条","txt":"中国证监会依法制定募集说明书或者其他证券发行信息披露文件内容与格式准则、编报规则等信息披露规则，对申请文件和信息披露资料的内容、格式、编制要求、披露形式等作出规定。 交易所可以依据中国证监会部门规章和规范性文件，制定信息披露细则或者指引，在中国证监会确定的信息披露内容范围内，对信息披露提出细化和补充要求，报中国证监会批准后实施。"},{"i":40,"n":"第四十条","txt":"上市公司应当在募集说明书或者其他证券发行信息披露文件中，以投资者需求为导向，有针对性地披露行业特点、业务模式、公司治理、发展战略、经营政策、会计政策，充分披露科研水平、科研人员、科研资金投入等相关信息，并充分揭示可能对公司核心竞争力、经营稳定性以及未来发展产生重大不利影响的风险因素。"},{"i":41,"n":"第四十一条","txt":"证券发行议案经董事会表决通过后，应当在二个工作日内披露，并及时公告召开股东大会的通知。 使用募集资金收购资产或者股权的，应当在公告召开股东大会通知的同时，披露该资产或者股权的基本情况、交易价格、定价依据以及是否与公司股东或者其他关联人存在利害关系。"},{"i":42,"n":"第四十二条","txt":"股东大会通过本次发行议案之日起二个工作日内，上市公司应当披露股东大会决议公告。"},{"i":43,"n":"第四十三条","txt":"上市公司提出发行申请后，出现下列情形之一的，应当在次一个工作日予以公告： （一）收到交易所不予受理或者终止发行上市审核决定； （二）收到中国证监会终止发行注册决定； （三）收到中国证监会予以注册或者不予注册的决定； （四）上市公司撤回证券发行申请。"},{"i":44,"n":"第四十四条","txt":"上市公司及其董事、监事、高级管理人员应当在募集说明书或者其他证券发行信息披露文件上签字、盖章，保证信息披露内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，按照诚信原则履行承诺，并声明承担相应的法律责任。 上市公司控股股东、实际控制人应当在募集说明书或者其他证券发行信息披露文件上签字、盖章，确认信息披露内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，按照诚信原则履行承诺，并声明承担相应法律责任。"},{"i":45,"n":"第四十五条","txt":"保荐人及其保荐代表人应当在募集说明书或者其他证券发行信息披露文件上签字、盖章，确认信息披露内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":46,"n":"第四十六条","txt":"为证券发行出具专项文件的律师、注册会计师、资产评估人员、资信评级人员及其所在机构，应当在募集说明书或者其他证券发行信息披露文件上签字、盖章，确认对上市公司信息披露文件引用其出具的专业意见无异议，信息披露文件不因引用其出具的专业意见而出现虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":47,"n":"第四十七条","txt":"募集说明书等证券发行信息披露文件所引用的审计报告、盈利预测审核报告、资产评估报告、资信评级报告，应当由符合规定的证券服务机构出具，并由至少二名有执业资格的人员签署。 募集说明书或者其他证券发行信息披露文件所引用的法律意见书，应当由律师事务所出具，并由至少二名经办律师签署。"},{"i":48,"n":"第四十八条","txt":"募集说明书自最后签署之日起六个月内有效。 募集说明书或者其他证券发行信息披露文件不得使用超过有效期的资产评估报告或者资信评级报告。"},{"i":49,"n":"第四十九条","txt":"向不特定对象发行证券申请经注册后，上市公司应当在证券发行前二至五个工作日内将公司募集说明书刊登在交易所网站和符合中国证监会规定条件的网站，供公众查阅。"},{"i":50,"n":"第五十条","txt":"向特定对象发行证券申请经注册后，上市公司应当在证券发行前将公司募集文件刊登在交易所网站和符合中国证监会规定条件的网站，供公众查阅。 向特定对象发行证券的，上市公司应当在证券发行后的二个工作日内，将发行情况报告书刊登在交易所网站和符合中国证监会规定条件的网站，供公众查阅。"},{"i":51,"n":"第五十一条","txt":"上市公司可以将募集说明书或者其他证券发行信息披露文件、发行情况报告书刊登于其他网站，但不得早于按照本办法第四十九条、第五十条规定披露信息的时间。"},{"i":52,"n":"第五十二条","txt":"上市公司证券发行与承销行为，适用《证券发行与承销管理办法》（以下简称《承销办法》），但本办法另有规定的除外。 交易所可以根据《承销办法》和本办法制定上市公司证券发行承销业务规则，并报中国证监会批准。"},{"i":53,"n":"第五十三条","txt":"上市公司配股的，拟配售股份数量不超过本次配售前股本总额的百分之五十，并应当采用代销方式发行。 控股股东应当在股东大会召开前公开承诺认配股份的数量。控股股东不履行认配股份的承诺，或者代销期限届满，原股东认购股票的数量未达到拟配售数量百分之七十的，上市公司应当按照发行价并加算银行同期存款利息返还已经认购的股东。"},{"i":54,"n":"第五十四条","txt":"上市公司增发的，发行价格应当不低于公告招股意向书前二十个交易日或者前一个交易日公司股票均价。"},{"i":55,"n":"第五十五条","txt":"上市公司向特定对象发行证券，发行对象应当符合股东大会决议规定的条件，且每次发行对象不超过三十五名。"},{"i":56,"n":"第五十六条","txt":"上市公司向特定对象发行股票，发行价格应当不低于定价基准日前二十个交易日公司股票均价的百分之八十。 前款所称“定价基准日”，是指计算发行底价的基准日。"},{"i":57,"n":"第五十七条","txt":"向特定对象发行股票的定价基准日为发行期首日。上市公司应当以不低于发行底价的价格发行股票。 上市公司董事会决议提前确定全部发行对象，且发行对象属于下列情形之一的，定价基准日可以为关于本次发行股票的董事会决议公告日、股东大会决议公告日或者发行期首日： （一）上市公司的控股股东、实际控制人或者其控制的关联人； （二）通过认购本次发行的股票取得上市公司实际控制权的投资者； （三）董事会拟引入的境内外战略投资者。"},{"i":58,"n":"第五十八条","txt":"向特定对象发行股票发行对象属于本办法第五十七条第二款规定以外的情形的，上市公司应当以竞价方式确定发行价格和发行对象。 董事会决议确定部分发行对象的，确定的发行对象不得参与竞价，且应当接受竞价结果，并明确在通过竞价方式未能产生发行价格的情况下，是否继续参与认购、价格确定原则及认购数量。"},{"i":59,"n":"第五十九条","txt":"向特定对象发行的股票,自发行结束之日起六个月内不得转让。发行对象属于本办法第五十七条第二款规定情形的，其认购的股票自发行结束之日起十八个月内不得转让。"},{"i":60,"n":"第六十条","txt":"向特定对象发行股票的定价基准日为本次发行股票的董事会决议公告日或者股东大会决议公告日的，向特定对象发行股票的董事会决议公告后，出现下列情况需要重新召开董事会的，应当由董事会重新确定本次发行的定价基准日： （一）本次发行股票股东大会决议的有效期已过； （二）本次发行方案发生重大变化； （三）其他对本次发行定价具有重大影响的事项。"},{"i":61,"n":"第六十一条","txt":"可转债应当具有期限、面值、利率、评级、债券持有人权利、转股价格及调整原则、赎回及回售、转股价格向下修正等要素。 向不特定对象发行的可转债利率由上市公司与主承销商依法协商确定。 向特定对象发行的可转债应当采用竞价方式确定利率和发行对象。"},{"i":62,"n":"第六十二条","txt":"可转债自发行结束之日起六个月后方可转换为公司股票，转股期限由公司根据可转债的存续期限及公司财务状况确定。 债券持有人对转股或者不转股有选择权，并于转股的次日成为上市公司股东。"},{"i":63,"n":"第六十三条","txt":"向特定对象发行的可转债不得采用公开的集中交易方式转让。 向特定对象发行的可转债转股的，所转股票自可转债发行结束之日起十八个月内不得转让。"},{"i":64,"n":"第六十四条","txt":"向不特定对象发行可转债的转股价格应当不低于募集说明书公告日前二十个交易日上市公司股票交易均价和前一个交易日均价。 向特定对象发行可转债的转股价格应当不低于认购邀请书发出前二十个交易日上市公司股票交易均价和前一个交易日的均价，且不得向下修正。"},{"i":65,"n":"第六十五条","txt":"上市公司发行证券，应当由证券公司承销。上市公司董事会决议提前确定全部发行对象的，可以由上市公司自行销售。"},{"i":66,"n":"第六十六条","txt":"向特定对象发行证券，上市公司及其控股股东、实际控制人、主要股东不得向发行对象做出保底保收益或者变相保底保收益承诺，也不得直接或者通过利益相关方向发行对象提供财务资助或者其他补偿。"},{"i":67,"n":"第六十七条","txt":"上市公司发行证券采用竞价方式的，认购邀请书内容、认购邀请书发送对象范围、发行价格及发行对象的确定原则等应当符合中国证监会及交易所相关规定，上市公司和主承销商的控股股东、实际控制人、董事、监事、高级管理人员及其控制或者施加重大影响的关联方不得参与竞价。"},{"i":68,"n":"第六十八条","txt":"网下投资者应当结合行业监管要求、资产规模等合理确定申购金额，不得超资产规模申购，承销商可以认定超资产规模的申购为无效申购。"},{"i":69,"n":"第六十九条","txt":"上市公司向不特定对象发行证券的，投资者弃购数量占发行总数比例较大的，上市公司和主承销商可以将投资者弃购部分向网下投资者二次配售。比例较大的标准由交易所规定。"},{"i":70,"n":"第七十条","txt":"上市公司和主承销商可以在符合中国证监会和交易所相关规定前提下约定中止发行的情形。"},{"i":71,"n":"第七十一条","txt":"交易所对证券发行承销过程实施监管。发行承销涉嫌违法违规或者存在异常情形的，中国证监会可以要求交易所对相关事项进行调查处理，或者直接责令上市公司和承销商暂停或者中止发行。"},{"i":72,"n":"第七十二条","txt":"中国证监会依法批准交易所制定的科创板上市公司证券发行上市的审核标准、审核程序、信息披露、发行承销等方面的制度规则，指导交易所制定与发行上市审核相关的其他业务规则。"},{"i":73,"n":"第七十三条","txt":"中国证监会建立对交易所发行上市审核工作和发行承销过程监管的监督机制，持续关注交易所审核情况和发行承销过程监管情况，发现交易所自律监管措施或者纪律处分失当的，可以责令交易所改正。"},{"i":74,"n":"第七十四条","txt":"中国证监会对交易所发行上市审核和发行承销过程监管等相关工作进行年度例行检查。在检查过程中，可以调阅审核工作文件，列席相关审核会议。 中国证监会定期或者不定期按一定比例对交易所发行上市审核和发行承销过程监管等相关工作进行抽查。 对于中国证监会在检查和抽查等监督过程中发现的问题，交易所应当整改。"},{"i":75,"n":"第七十五条","txt":"交易所发行上市审核工作违反本办法规定，有下列情形之一的，由中国证监会责令改正；情节严重的，追究直接责任人员相关责任： （一）未按审核标准开展发行上市审核工作； （二）未按审核程序开展发行上市审核工作； （三）不配合中国证监会对发行上市审核工作和发行承销监管工作的检查、抽查，或者不按中国证监会的整改要求进行整改。"},{"i":76,"n":"第七十六条","txt":"上市公司在证券发行文件中隐瞒重要事实或者编造重大虚假内容的，中国证监会采取五年内不接受上市公司发行证券相关文件的监管措施。对相关责任人员，视情节轻重，采取认定为不适当人选的监管措施，或者采取证券市场禁入的措施。"},{"i":77,"n":"第七十七条","txt":"存在下列情形之一的，中国证监会采取三年至五年内不接受上市公司发行证券相关文件的监管措施： （一）申请文件存在虚假记载、误导性陈述或者重大遗漏； （二）上市公司阻碍或者拒绝中国证监会、交易所依法对其实施检查、核查； （三）上市公司及其关联方以不正当手段严重干扰发行上市审核或者发行注册工作； （四）重大事项未报告、未披露； （五）上市公司及其董事、监事、高级管理人员、控股股东、实际控制人的签名、盖章系伪造或者变造。"},{"i":78,"n":"第七十八条","txt":"上市公司控股股东、实际控制人违反本办法的规定，致使上市公司所报送的申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏，或者组织、指使上市公司进行财务造假、利润操纵或者在证券发行文件中隐瞒重要事实或者编造重大虚假内容的，中国证监会视情节轻重，对相关单位和责任人员采取一年到五年内不接受相关单位及其控制的下属单位发行证券相关文件，对责任人员采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。 上市公司董事、监事和高级管理人员违反本办法规定，致使上市公司所报送的申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，对责任人员采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。"},{"i":79,"n":"第七十九条","txt":"保荐人未勤勉尽责，致使上市公司信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，采取暂停保荐人业务资格一年至三年，责令保荐人更换相关负责人的监管措施；情节严重的，撤销保荐人业务资格，对相关责任人员采取证券市场禁入的措施。 保荐代表人未勤勉尽责，致使上市公司信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，按规定认定为不适当人选。 证券服务机构未勤勉尽责，致使上市公司信息披露资料中与其职责有关的内容及其所出具的文件存在虚假记载、误导性陈述或者重大遗漏的，中国证监会视情节轻重，采取三个月至三年内不接受相关单位及其责任人员出具的发行证券专项文件的监管措施；情节严重的，对证券服务机构相关责任人员采取证券市场禁入的措施。"},{"i":80,"n":"第八十条","txt":"保荐人存在下列情形之一的，中国证监会视情节轻重，采取暂停保荐人业务资格三个月至三年的监管措施；情节特别严重的，撤销其业务资格： （一）伪造或者变造签字、盖章； （二）重大事项未报告或者未披露； （三）以不正当手段干扰审核注册工作； （四）不履行其他法定职责。 保荐代表人存在前款规定情形的，视情节轻重，按规定三个月至三年不受理相关保荐代表人具体负责的推荐；情节特别严重的，按规定认定为不适当人选。 证券服务机构及其相关人员存在第一款规定情形的，中国证监会视情节轻重，采取三个月至三年内不接受相关单位及其责任人员出具的发行证券专项文件的监管措施。"},{"i":81,"n":"第八十一条","txt":"保荐人、证券服务机构及其责任人员存在下列情形之一的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、一年内不接受相关单位及其责任人员出具的与注册申请有关的文件等监管措施；情节严重的，可以同时采取三个月至一年内不接受相关单位及其责任人员出具的发行证券专项文件的监管措施： （一）制作或者出具的文件不齐备或者不符合要求； （二）擅自改动申请文件、信息披露资料或者其他已提交文件； （三）申请文件或者信息披露资料存在相互矛盾或者同一事实表述不一致且有实质性差异； （四）文件披露的内容表述不清，逻辑混乱，严重影响阅读理解； （五）对重大事项未及时报告或者未及时披露。 上市公司存在前款规定情形的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、六个月至一年内不接受上市公司发行证券相关文件的监管措施。"},{"i":82,"n":"第八十二条","txt":"按照本办法第二十八条申请注册的，交易所和中国证监会发现上市公司或者相关中介机构及其责任人员存在相关违法违规行为的，中国证监会按照本章规定从重处罚，并采取三年至五年内不接受上市公司和保荐人该类发行证券相关文件的监管措施。"},{"i":83,"n":"第八十三条","txt":"上市公司披露盈利预测的，利润实现数如未达到盈利预测的百分之八十，除因不可抗力外，其法定代表人、财务负责人应当在股东大会以及证券交易所网站、符合中国证监会规定条件的媒体上公开作出解释并道歉；中国证监会可以对法定代表人处以警告。 利润实现数未达到盈利预测百分之五十的，除因不可抗力外，中国证监会在三年内不接受上市公司发行证券相关文件。 注册会计师为上述盈利预测出具审核报告的过程中未勤勉尽责的，中国证监会视情节轻重，对相关机构和责任人员采取监管谈话等监管措施；情节严重的，给予警告等行政处罚。"},{"i":84,"n":"第八十四条","txt":"参与认购的投资者擅自转让限售期限未满的证券的，中国证监会可以责令改正；情节严重的，十二个月内不得作为特定对象认购证券。"},{"i":85,"n":"第八十五条","txt":"相关主体违反本办法第六十六条规定的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、认定为不适当人选、一年至三年内不接受发行证券相关文件的监管措施，以及市场禁入的措施；保荐人、证券服务机构未勤勉尽责的，中国证监会还可以采取一年至三年内不接受相关单位及其责任人员出具的与注册申请有关的文件等监管措施。"},{"i":86,"n":"第八十六条","txt":"上市公司及其控股股东和实际控制人、董事、监事、高级管理人员，保荐人、承销商、证券服务机构及其相关执业人员、参与认购的投资者，在证券发行并上市相关的活动中存在其他违反本办法规定行为的，中国证监会视情节轻重，采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告、认定为不适当人选、暂不受理与行政许可有关的文件等监管措施，或者采取证券市场禁入的措施。"},{"i":87,"n":"第八十七条","txt":"上市公司及其控股股东、实际控制人、保荐人、证券服务机构及其相关执业人员违反《证券法》依法应予以行政处罚的，中国证监会依法予以处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":88,"n":"第八十八条","txt":"本办法所称战略投资者，是指符合下列情形之一，且具有同行业或者相关行业较强的重要战略性资源，与上市公司谋求双方协调互补的长期共同战略利益，愿意长期持有上市公司较大比例股份，愿意并且有能力认真履行相应职责，委派董事实际参与公司治理，提升上市公司治理水平，帮助上市公司显著提高公司质量和内在价值，具有良好诚信记录，最近三年未受到中国证监会行政处罚或者被追究刑事责任的投资者： （一）能够给上市公司带来国际国内领先的核心技术资源，显著增强上市公司的核心竞争力和创新能力，带动上市公司的产业技术升级，显著提升上市公司的盈利能力； （二）能够给上市公司带来国际国内领先的市场、渠道、品牌等战略性资源，大幅促进上市公司市场拓展，推动实现上市公司销售业绩大幅提升； 境外战略投资者应当同时遵守国家的相关规定。"},{"i":89,"n":"第八十九条","txt":"符合《若干意见》等规定的红筹企业，首次公开发行股票并在科创板上市后，发行股票还应当符合本办法的规定。 符合《若干意见》等规定的红筹企业，首次公开发行存托凭证并在科创板上市后，发行以红筹企业新增证券为基础证券的存托凭证，适用《证券法》《若干意见》以及本办法关于上市公司发行股票的规定，本办法没有规定的，适用中国证监会关于存托凭证的有关规定。 发行存托凭证的红筹企业境外基础股票配股时，相关方案安排应确保存托凭证持有人实际享有权益与境外基础股票持有人权益相当。"},{"i":90,"n":"第九十条","txt":"上市公司发行优先股、向员工发行证券用于激励的办法，由中国证监会另行规定。"},{"i":91,"n":"第九十一条","txt":"上市公司向特定对象发行股票将导致上市公司控制权发生变化的，还应当符合中国证监会的其他规定。"},{"i":92,"n":"第九十二条","txt":"依据本办法通过向特定对象发行股票取得的上市公司股份，其减持不适用《上市公司股东、董监高减持股份的若干规定》的有关规定。"},{"i":93,"n":"第九十三条","txt":"本办法自公布之日起施行。"}],"kechuangbanshoucigongkaifaxinggupiaozhuceguanlibana32575":[{"i":1,"n":"第一条","txt":"为规范在上海证券交易所科创板试点注册制首次公开发行股票相关活动，保护投资者合法权益和社会公共利益，根据《中华人民共和国证券法》《中华人民共和国公司法》《全国人民代表大会常务委员会关于授权国务院在实施股票发行注册制改革中调整适用〈中华人民共和国证券法〉有关规定的决定》《全国人民代表大会常务委员会关于延长授权国务院在实施股票发行注册制改革中调整适用〈中华人民共和国证券法〉有关规定期限的决定》《关于在上海证券交易所设立科创板并试点注册制的实施意见》及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内首次公开发行股票并在上海证券交易所科创板（以下简称科创板）上市，适用本办法。"},{"i":3,"n":"第三条","txt":"发行人申请首次公开发行股票并在科创板上市，应当符合科创板定位，面向世界科技前沿、面向经济主战场、面向国家重大需求。优先支持符合国家战略，拥有关键核心技术，科技创新能力突出，主要依靠核心技术开展生产经营，具有稳定的商业模式，市场认可度高，社会形象良好，具有较强成长性的企业。"},{"i":4,"n":"第四条","txt":"首次公开发行股票并在科创板上市，应当符合发行条件、上市条件以及相关信息披露要求，依法经上海证券交易所（以下简称交易所）发行上市审核并报经中国证券监督管理委员会（以下简称中国证监会）履行发行注册程序。"},{"i":5,"n":"第五条","txt":"发行人作为信息披露第一责任人，应当诚实守信，依法充分披露投资者作出价值判断和投资决策所必需的信息，所披露信息必须真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 发行人应当为保荐人、证券服务机构及时提供真实、准确、完整的财务会计资料和其他资料，全面配合相关机构开展尽职调查和其他相关工作。 发行人的控股股东、实际控制人应当全面配合相关机构开展尽职调查和其他相关工作，不得要求或者协助发行人隐瞒应当披露的信息。"},{"i":6,"n":"第六条","txt":"保荐人应当诚实守信，勤勉尽责，按照依法制定的业务规则和行业自律规范的要求，充分了解发行人经营情况和风险，对注册申请文件和信息披露资料进行全面核查验证，对发行人是否符合发行条件、上市条件独立作出专业判断，审慎作出推荐决定，并对招股说明书及其所出具的相关文件的真实性、准确性、完整性负责。"},{"i":7,"n":"第七条","txt":"证券服务机构应当严格按照依法制定的业务规则和行业自律规范，审慎履行职责，作出专业判断与认定，并对招股说明书中与其专业职责有关的内容及其所出具的文件的真实性、准确性、完整性负责。 证券服务机构及其相关执业人员应当对与本专业相关的业务事项履行特别注意义务，对其他业务事项履行普通注意义务，并承担相应法律责任。"},{"i":8,"n":"第八条","txt":"同意发行人首次公开发行股票注册，不表明中国证监会和交易所对该股票的投资价值或者投资者的收益作出实质性判断或者保证，也不表明中国证监会和交易所对注册申请文件的真实性、准确性、完整性作出保证。"},{"i":9,"n":"第九条","txt":"股票依法发行后，因发行人经营与收益的变化引致的投资风险，由投资者自行负责。 第二章发行条件"},{"i":10,"n":"第十条","txt":"发行人是依法设立且持续经营3年以上的股份有限公司，具备健全且运行良好的组织机构，相关机构和人员能够依法履行职责。 有限责任公司按原账面净资产值折股整体变更为股份有限公司的，持续经营时间可以从有限责任公司成立之日起计算。"},{"i":11,"n":"第十一条","txt":"发行人会计基础工作规范，财务报表的编制和披露符合企业会计准则和相关信息披露规则的规定，在所有重大方面公允地反映了发行人的财务状况、经营成果和现金流量，并由注册会计师出具标准无保留意见的审计报告。 发行人内部控制制度健全且被有效执行，能够合理保证公司运行效率、合法合规和财务报告的可靠性，并由注册会计师出具无保留结论的内部控制鉴证报告。"},{"i":12,"n":"第十二条","txt":"发行人业务完整，具有直接面向市场独立持续经营的能力： （一）资产完整，业务及人员、财务、机构独立，与控股股东、实际控制人及其控制的其他企业间不存在对发行人构成重大不利影响的同业竞争，不存在严重影响独立性或者显失公平的关联交易。 （二）发行人主营业务、控制权、管理团队和核心技术人员稳定，最近2年内主营业务和董事、高级管理人员及核心技术人员均没有发生重大不利变化；控股股东和受控股股东、实际控制人支配的股东所持发行人的股份权属清晰，最近2年实际控制人没有发生变更，不存在导致控制权可能变更的重大权属纠纷。 （三）发行人不存在主要资产、核心技术、商标等的重大权属纠纷，重大偿债风险，重大担保、诉讼、仲裁等或有事项，经营环境已经或者将要发生重大变化等对持续经营有重大不利影响的事项。"},{"i":13,"n":"第十三条","txt":"发行人生产经营符合法律、行政法规的规定，符合国家产业政策。 最近3年内，发行人及其控股股东、实际控制人不存在贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的刑事犯罪，不存在欺诈发行、重大信息披露违法或者其他涉及国家安全、公共安全、生态安全、生产安全、公众健康安全等领域的重大违法行为。 董事、监事和高级管理人员不存在最近3年内受到中国证监会行政处罚，或者因涉嫌犯罪被司法机关立案侦查或者涉嫌违法违规被中国证监会立案调查，尚未有明确结论意见等情形。 第三章注册程序"},{"i":14,"n":"第十四条","txt":"发行人董事会应当依法就本次股票发行的具体方案、本次募集资金使用的可行性及其他必须明确的事项作出决议，并提请股东大会批准。"},{"i":15,"n":"第十五条","txt":"发行人股东大会就本次发行股票作出的决议，至少应当包括下列事项： （一）本次公开发行股票的种类和数量； （二）发行对象； （三）定价方式； （四）募集资金用途； （五）发行前滚存利润的分配方案； （六）决议的有效期； （七）对董事会办理本次发行具体事宜的授权； （八）其他必须明确的事项。"},{"i":16,"n":"第十六条","txt":"发行人申请首次公开发行股票并在科创板上市，应当按照中国证监会有关规定制作注册申请文件，由保荐人保荐并向交易所申报。 交易所收到注册申请文件后，5个工作日内作出是否受理的决定。"},{"i":17,"n":"第十七条","txt":"自注册申请文件受理之日起，发行人及其控股股东、实际控制人、董事、监事、高级管理人员，以及与本次股票公开发行并上市相关的保荐人、证券服务机构及相关责任人员，即承担相应法律责任。"},{"i":18,"n":"第十八条","txt":"注册申请文件受理后，未经中国证监会或者交易所同意，不得改动。 发生重大事项的，发行人、保荐人、证券服务机构应当及时向交易所报告，并按要求更新注册申请文件和信息披露资料。"},{"i":19,"n":"第十九条","txt":"交易所设立独立的审核部门，负责审核发行人公开发行并上市申请；设立科技创新咨询委员会，负责为科创板建设和发行上市审核提供专业咨询和政策建议；设立科创板股票上市委员会，负责对审核部门出具的审核报告和发行人的申请文件提出审议意见。 交易所主要通过向发行人提出审核问询、发行人回答问题方式开展审核工作，基于科创板定位，判断发行人是否符合发行条件、上市条件和信息披露要求。"},{"i":20,"n":"第二十条","txt":"交易所按照规定的条件和程序，作出同意或者不同意发行人股票公开发行并上市的审核意见。同意发行人股票公开发行并上市的，将审核意见、发行人注册申请文件及相关审核资料报送中国证监会履行发行注册程序。不同意发行人股票公开发行并上市的，作出终止发行上市审核决定。"},{"i":21,"n":"第二十一条","txt":"交易所应当自受理注册申请文件之日起3个月内形成审核意见。发行人根据要求补充、修改注册申请文件，以及交易所按照规定对发行人实施现场检查，或者要求保荐人、证券服务机构对有关事项进行专项核查的时间不计算在内。"},{"i":22,"n":"第二十二条","txt":"交易所应当提高审核工作透明度，接受社会监督，公开下列事项： （一）发行上市审核标准和程序等发行上市审核业务规则，以及相关监管问答； （二）在审企业名单、企业基本情况及审核工作进度； （三）发行上市审核问询及回复情况，但涉及国家秘密或者发行人商业秘密的除外； （四）上市委员会会议的时间、参会委员名单、审议的发行人名单、审议结果及现场问询问题； （五）对股票公开发行并上市相关主体采取的自律监管措施或者纪律处分； （六）交易所规定的其他事项。"},{"i":23,"n":"第二十三条","txt":"中国证监会收到交易所报送的审核意见、发行人注册申请文件及相关审核资料后，履行发行注册程序。发行注册主要关注交易所发行上市审核内容有无遗漏，审核程序是否符合规定，以及发行人在发行条件和信息披露要求的重大方面是否符合相关规定。中国证监会认为存在需要进一步说明或者落实事项的，可以要求交易所进一步问询。 中国证监会认为交易所对影响发行条件的重大事项未予关注或者交易所的审核意见依据明显不充分的，可以退回交易所补充审核。交易所补充审核后，同意发行人股票公开发行并上市的，重新向中国证监会报送审核意见及相关资料，本办法第二十四条规定的注册期限重新计算。"},{"i":24,"n":"第二十四条","txt":"中国证监会在20个工作日内对发行人的注册申请作出同意注册或者不予注册的决定。发行人根据要求补充、修改注册申请文件，中国证监会要求交易所进一步问询，以及中国证监会要求保荐人、证券服务机构等对有关事项进行核查的时间不计算在内。"},{"i":25,"n":"第二十五条","txt":"中国证监会同意注册的决定自作出之日起1年内有效，发行人应当在注册决定有效期内发行股票，发行时点由发行人自主选择。"},{"i":26,"n":"第二十六条","txt":"中国证监会作出注册决定后、发行人股票上市交易前，发行人应当及时更新信息披露文件内容，财务报表过期的，发行人应当补充财务会计报告等文件；保荐人及证券服务机构应当持续履行尽职调查职责；发生重大事项的，发行人、保荐人应当及时向交易所报告。 交易所应当对上述事项及时处理，发现发行人存在重大事项影响发行条件、上市条件的，应当出具明确意见并及时向中国证监会报告。"},{"i":27,"n":"第二十七条","txt":"中国证监会作出注册决定后、发行人股票上市交易前，发现可能影响本次发行的重大事项的，中国证监会可以要求发行人暂缓或者暂停发行、上市；相关重大事项导致发行人不符合发行条件的，可以撤销注册。 中国证监会撤销注册后，股票尚未发行的，发行人应当停止发行；股票已经发行尚未上市的，发行人应当按照发行价并加算银行同期存款利息返还股票持有人。"},{"i":28,"n":"第二十八条","txt":"交易所因不同意发行人股票公开发行并上市，作出终止发行上市审核决定，或者中国证监会作出不予注册决定的，自决定作出之日起6个月后，发行人可以再次提出公开发行股票并上市申请。"},{"i":29,"n":"第二十九条","txt":"中国证监会应当按规定公开股票发行注册行政许可事项相关的监管信息。"},{"i":30,"n":"第三十条","txt":"存在下列情形之一的，发行人、保荐人应当及时书面报告交易所或者中国证监会，交易所或者中国证监会应当中止相应发行上市审核程序或者发行注册程序： （一）相关主体涉嫌违反本办法第十三条第二款规定，被立案调查或者被司法机关侦查，尚未结案； （二）发行人的保荐人，以及律师事务所、会计师事务所等证券服务机构因首次公开发行股票、上市公司证券发行、并购重组业务涉嫌违法违规，或者其他业务涉嫌违法违规且对市场有重大影响被中国证监会立案调查，或者被司法机关侦查，尚未结案； （三）发行人的签字保荐代表人，以及签字律师、签字会计师等证券服务机构签字人员因首次公开发行股票、上市公司证券发行、并购重组业务涉嫌违法违规，或者其他业务涉嫌违法违规且对市场有重大影响被中国证监会立案调查，或者被司法机关侦查，尚未结案； （四）发行人的保荐人，以及律师事务所、会计师事务所等证券服务机构被中国证监会依法采取限制业务活动、责令停业"},{"i":31,"n":"第三十一条","txt":"存在下列情形之一的，交易所或者中国证监会应当终止相应发行上市审核程序或者发行注册程序，并向发行人说明理由： （一）发行人撤回注册申请文件或者保荐人撤销保荐； （二）发行人未在要求的期限内对注册申请文件作出解释说明或者补充、修改； （三）注册申请文件存在虚假记载、误导性陈述或者重大遗漏； （四）发行人阻碍或者拒绝中国证监会、交易所依法对发行人实施检查、核查； （五）发行人及其关联方以不正当手段严重干扰发行上市审核或者发行注册工作； （六）发行人法人资格终止； （七）注册申请文件内容存在重大缺陷，严重影响投资者理解和发行上市审核或者发行注册工作； （八）发行人注册申请文件中记载的财务资料已过有效期且逾期3个月未更新； （九）发行人中止发行上市审核程序超过交易所规定的时限或者中止发行注册程序超过3个月仍未恢复； （十）交易所不同意发行人公开发行股票并上市； （十一）中国证监会规定的其他情形。"},{"i":32,"n":"第三十二条","txt":"中国证监会和交易所可以对发行人进行现场检查，可以要求保荐人、证券服务机构对有关事项进行专项核查并出具意见。 中国证监会和交易所应当建立健全信息披露质量现场检查制度，以及对保荐业务、发行承销业务的常态化检查制度，具体制度另行规定。"},{"i":33,"n":"第三十三条","txt":"中国证监会与交易所建立全流程电子化审核注册系统，实现电子化受理、审核，以及发行注册各环节实时信息共享，并满足依法向社会公开相关信息的需要。 第四章信息披露"},{"i":34,"n":"第三十四条","txt":"发行人申请首次公开发行股票并在科创板上市，应当按照中国证监会制定的信息披露规则，编制并披露招股说明书，保证相关信息真实、准确、完整。信息披露内容应当简明易懂，语言应当浅白平实，以便投资者阅读、理解。 中国证监会制定的信息披露规则是信息披露的最低要求。不论上述规则是否有明确规定，凡是对投资者作出价值判断和投资决策有重大影响的信息，发行人均应当予以披露。"},{"i":35,"n":"第三十五条","txt":"中国证监会依法制定招股说明书内容与格式准则、编报规则，对注册申请文件和信息披露资料的内容、格式、编制要求、披露形式等作出规定。 交易所可以依据中国证监会部门规章和规范性文件，制定信息披露细则或者指引，在中国证监会确定的信息披露内容范围内，对信息披露提出细化和补充要求，报中国证监会批准后实施。"},{"i":36,"n":"第三十六条","txt":"发行人及其董事、监事、高级管理人员应当在招股说明书上签字、盖章，保证招股说明书的内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，并声明承担相应法律责任。 发行人控股股东、实际控制人应当在招股说明书上签字、盖章，确认招股说明书的内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，并声明承担相应法律责任。"},{"i":37,"n":"第三十七条","txt":"保荐人及其保荐代表人应当在招股说明书上签字、盖章，确认招股说明书的内容真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":38,"n":"第三十八条","txt":"为证券发行出具专项文件的律师、注册会计师、资产评估人员、资信评级人员及其所在机构，应当在招股说明书上签字、盖章，确认对发行人信息披露文件引用其出具的专业意见无异议，信息披露文件不因引用其出具的专业意见而出现虚假记载、误导性陈述或者重大遗漏，并声明承担相应的法律责任。"},{"i":39,"n":"第三十九条","txt":"发行人应当根据自身特点，有针对性地披露行业特点、业务模式、公司治理、发展战略、经营政策、会计政策，充分披露科研水平、科研人员、科研资金投入等相关信息，并充分揭示可能对公司核心竞争力、经营稳定性以及未来发展产生重大不利影响的风险因素。 发行人尚未盈利的，应当充分披露尚未盈利的成因，以及对公司现金流、业务拓展、人才吸引、团队稳定性、研发投入、战略性投入、生产经营可持续性等方面的影响。"},{"i":40,"n":"第四十条","txt":"发行人应当披露其募集资金使用管理制度，以及募集资金重点投向科技创新领域的具体安排。"},{"i":41,"n":"第四十一条","txt":"存在特别表决权股份的境内科技创新企业申请首次公开发行股票并在科创板上市的，发行人应当在招股说明书等公开发行文件中，披露并特别提示差异化表决安排的主要内容、相关风险和对公司治理的影响，以及依法落实保护投资者合法权益的各项措施。 保荐人和发行人律师应当就公司章程规定的特别表决权股份的持有人资格、特别表决权股份拥有的表决权数量与普通股份拥有的表决权数量的比例安排、持有人所持特别表决权股份能够参与表决的股东大会事项范围、特别表决权股份锁定安排及转让限制等事项是否符合有关规定发表专业意见。"},{"i":42,"n":"第四十二条","txt":"发行人应当在招股说明书中披露公开发行股份前已发行股份的锁定期安排，特别是核心技术人员股份的锁定期安排以及尚未盈利情况下发行人控股股东、实际控制人、董事、监事、高级管理人员股份的锁定期安排。 保荐人和发行人律师应当就前款事项是否符合有关规定发表专业意见。"},{"i":43,"n":"第四十三条","txt":"招股说明书的有效期为6个月，自公开发行前最后一次签署之日起计算。 招股说明书引用经审计的财务报表在其最近一期截止日后6个月内有效，特殊情况下发行人可申请适当延长，但至多不超过3个月。财务报表应当以年度末、半年度末或者季度末为截止日。"},{"i":44,"n":"第四十四条","txt":"交易所受理注册申请文件后，发行人应当按交易所规定，将招股说明书、发行保荐书、上市保荐书、审计报告和法律意见书等文件在交易所网站预先披露。"},{"i":45,"n":"第四十五条","txt":"预先披露的招股说明书及其他注册申请文件不能含有价格信息，发行人不得据此发行股票。 发行人应当在预先披露的招股说明书显要位置作如下声明：“本公司的发行申请尚需经上海证券交易所和中国证监会履行相应程序。本招股说明书不具有据以发行股票的法律效力，仅供预先披露之用。投资者应当以正式公告的招股说明书作为投资决定的依据。”"},{"i":46,"n":"第四十六条","txt":"交易所审核同意后，将发行人注册申请文件报送中国证监会时，招股说明书、发行保荐书、上市保荐书、审计报告和法律意见书等文件应在交易所网站和中国证监会网站公开。"},{"i":47,"n":"第四十七条","txt":"发行人股票发行前应当在交易所网站和中国证监会指定网站全文刊登招股说明书，同时在中国证监会指定报刊刊登提示性公告，告知投资者网上刊登的地址及获取文件的途径。 发行人可以将招股说明书以及有关附件刊登于其他报刊和网站，但披露内容应当完全一致，且不得早于在交易所网站、中国证监会指定报刊和网站的披露时间。"},{"i":48,"n":"第四十八条","txt":"保荐人出具的发行保荐书、证券服务机构出具的文件及其他与发行有关的重要文件应当作为招股说明书的附件，在交易所网站和中国证监会指定的网站披露，以备投资者查阅。 第五章发行与承销的特别规定"},{"i":49,"n":"第四十九条","txt":"首次公开发行股票并在科创板上市的发行与承销行为，适用《证券发行与承销管理办法》，本办法另有规定的除外。"},{"i":50,"n":"第五十条","txt":"首次公开发行股票，应当向经中国证券业协会注册的证券公司、基金管理公司、信托公司、财务公司、保险公司、合格境外机构投资者和私募基金管理人等专业机构投资者（以下统称网下投资者）询价确定股票发行价格。 发行人和主承销商可以根据自律规则，设置网下投资者的具体条件，并在发行公告中预先披露。"},{"i":51,"n":"第五十一条","txt":"网下投资者可以按照管理的不同配售对象账户分别申报价格，每个报价应当包含配售对象信息、每股价格和该价格对应的拟申购股数。 首次公开发行股票价格（或者发行价格区间）确定后，提供有效报价的网下投资者方可参与新股申购。"},{"i":52,"n":"第五十二条","txt":"交易所应当根据《证券发行与承销管理办法》和本办法制定科创板股票发行承销业务规则。 投资者报价要求、最高报价剔除比例、网下初始配售比例、网下优先配售比例、网下网上回拨机制、网下分类配售安排、战略配售、超额配售选择权等事项适用交易所相关规定。 《证券发行与承销管理办法》规定的战略投资者在承诺的持有期限内，可以按规定向证券金融公司借出获得配售的股票。借出期限届满后，证券金融公司应当将借入的股票返还给战略投资者。"},{"i":53,"n":"第五十三条","txt":"保荐人的相关子公司或者保荐人所属证券公司的相关子公司参与发行人股票配售的具体规则由交易所另行规定。"},{"i":54,"n":"第五十四条","txt":"获中国证监会同意注册后，发行人与主承销商应当及时向交易所报备发行与承销方案。交易所5个工作日内无异议的，发行人与主承销商可依法刊登招股意向书，启动发行工作。"},{"i":55,"n":"第五十五条","txt":"交易所对证券发行承销过程实施监管。发行承销涉嫌违法违规或者存在异常情形的，中国证监会可以要求交易所对相关事项进行调查处理，或者直接责令发行人和承销商暂停或者中止发行。 第六章发行上市保荐的特别规定"},{"i":56,"n":"第五十六条","txt":"首次公开发行股票并在科创板上市保荐业务，适用《证券发行上市保荐业务管理办法》，本办法另有规定的除外。"},{"i":57,"n":"第五十七条","txt":"保荐人应当根据科创板企业特点和注册制要求对科创板保荐工作内部控制做出合理安排，有效控制风险，切实提高执业质量。"},{"i":58,"n":"第五十八条","txt":"保荐人应当按照中国证监会和交易所的规定制作、报送和披露发行保荐书、上市保荐书、回复意见及其他发行上市相关文件，遵守交易所和中国证监会的发行上市审核及发行注册程序，配合交易所和中国证监会的发行上市审核及发行注册工作，并承担相应工作。"},{"i":59,"n":"第五十九条","txt":"首次公开发行股票并在科创板上市的，持续督导的期间为证券上市当年剩余时间及其后3个完整会计年度。 交易所可以对保荐人持续督导内容、履责要求、发行人通知报告事项等作出规定。 第七章监督管理和法律责任"},{"i":60,"n":"第六十条","txt":"中国证监会负责建立健全以信息披露为中心的注册制规则体系，制定股票发行注册并上市的规章规则，依法批准交易所制定的上市条件、审核标准、审核程序、上市委员会制度、信息披露、保荐、发行承销等方面的制度规则，指导交易所制定与发行上市审核相关的其他业务规则。"},{"i":61,"n":"第六十一条","txt":"中国证监会建立对交易所发行上市审核工作和发行承销过程监管的监督机制，持续关注交易所审核情况和发行承销过程监管情况；发现交易所自律监管措施或者纪律处分失当的，可以责令交易所改正。"},{"i":62,"n":"第六十二条","txt":"中国证监会对交易所发行上市审核和发行承销过程监管等相关工作进行年度例行检查。在检查过程中，可以调阅审核工作文件，列席相关审核会议。 中国证监会定期或者不定期按一定比例对交易所发行上市审核和发行承销过程监管等相关工作进行抽查。 中国证监会在检查和抽查过程中发现问题的，交易所应当整改。"},{"i":63,"n":"第六十三条","txt":"中国证监会建立对发行上市监管全流程的权力运行监督制约机制，对发行上市审核程序和发行注册程序相关内控制度运行情况进行督导督察，对廉政纪律执行情况和相关人员的履职尽责情况进行监督监察。"},{"i":64,"n":"第六十四条","txt":"交易所应当建立内部防火墙制度，发行上市审核部门、发行承销监管部门与其他部门隔离运行。参与发行上市审核的人员，不得与发行人及其控股股东、实际控制人、相关保荐人、证券服务机构有利害关系，不得直接或者间接与发行人、保荐人、证券服务机构有利益往来，不得持有发行人股票，不得私下与发行人接触。"},{"i":65,"n":"第六十五条","txt":"交易所应当建立定期报告制度，及时总结发行上市审核和发行承销监管的工作情况，并报告中国证监会。"},{"i":66,"n":"第六十六条","txt":"交易所发行上市审核工作违反本办法规定，有下列情形之一的，由中国证监会责令改正；情节严重的，追究直接责任人员相关责任： （一）未按审核标准开展发行上市审核工作； （二）未按审核程序开展发行上市审核工作； （三）不配合中国证监会对发行上市审核工作和发行承销监管工作的检查、抽查，或者不按中国证监会的整改要求进行整改。"},{"i":67,"n":"第六十七条","txt":"发行人不符合发行上市条件，以欺骗手段骗取发行注册的，中国证监会将自确认之日起采取5年内不接受发行人公开发行证券相关文件的监管措施。对相关责任人员，视情节轻重，采取认定为不适当人选的监管措施，或者采取证券市场禁入的措施。"},{"i":68,"n":"第六十八条","txt":"对发行人存在本办法第六十七条规定的行为并已经发行上市的，可以依照有关规定责令上市公司及其控股股东、实际控制人在一定期间从投资者手中购回本次公开发行的股票。"},{"i":69,"n":"第六十九条","txt":"发行人存在本办法第三十一条第（三）项、第（四）项、第（五）项规定的情形，重大事项未报告、未披露，或者发行人及其董事、监事、高级管理人员、控股股东、实际控制人的签字、盖章系伪造或者变造的，中国证监会将自确认之日起采取3年至5年内不接受发行人公开发行证券相关文件的监管措施。"},{"i":70,"n":"第七十条","txt":"发行人的控股股东、实际控制人违反本办法规定，致使发行人所报送的注册申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏，或者纵容、指使、协助发行人进行财务造假、利润操纵或者有意隐瞒其他重要信息等骗取发行注册行为的，中国证监会可以视情节轻重，对相关单位和责任人员自确认之日起采取1年到5年内不接受相关单位及其控制的下属单位公开发行证券相关文件，对责任人员采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。 发行人的董事、监事和高级管理人员违反本办法规定，致使发行人所报送的注册申请文件和披露的信息存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以视情节轻重，对责任人员采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。"},{"i":71,"n":"第七十一条","txt":"保荐人未勤勉尽责，致使发行人信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，中国证监会将视情节轻重，自确认之日起采取暂停保荐人业务资格1年到3年，责令保荐人更换相关负责人的监管措施；情节严重的，撤销保荐人业务资格，对相关责任人员采取证券市场禁入的措施。 保荐代表人未勤勉尽责，致使发行人信息披露资料存在虚假记载、误导性陈述或者重大遗漏的，按规定撤销保荐代表人资格。 证券服务机构未勤勉尽责，致使发行人信息披露资料中与其职责有关的内容及其所出具的文件存在虚假记载、误导性陈述或者重大遗漏的，中国证监会可以视情节轻重，自确认之日起采取3个月至3年不接受相关单位及其责任人员出具的发行证券专项文件的监管措施；情节严重的，对证券服务机构相关责任人员采取证券市场禁入的措施。"},{"i":72,"n":"第七十二条","txt":"保荐人存在下列情形的，中国证监会可以视情节轻重，自确认之日起采取暂停保荐人业务资格3个月至3年的监管措施；情节特别严重的，撤销其业务资格： （一）伪造或者变造签字、盖章； （二）重大事项未报告、未披露； （三）以不正当手段干扰审核注册工作； （四）不履行其他法定职责。 保荐代表人存在前款规定情形的，视情节轻重，按规定暂停保荐代表人资格3个月至3年；情节严重的，按规定撤销保荐代表人资格。 证券服务机构及其相关人员存在第一款规定情形的，中国证监会可以视情节轻重，自确认之日起，采取3个月至3年不接受相关单位及其责任人员出具的发行证券专项文件的监管措施。"},{"i":73,"n":"第七十三条","txt":"发行人公开发行证券上市当年即亏损的，中国证监会自确认之日起暂停保荐人的保荐人资格3个月，撤销相关人员的保荐代表人资格，尚未盈利的企业或者已在证券发行募集文件中充分分析并揭示相关风险的除外。"},{"i":74,"n":"第七十四条","txt":"保荐人、证券服务机构存在以下情形的，中国证监会可以视情节轻重，采取责令改正、监管谈话、出具警示函、1年内不接受相关单位及其责任人员出具的与注册申请有关的文件等监管措施；情节严重的，可以同时采取3个月到1年内不接受相关单位及其责任人员出具的发行证券专项文件的监管措施： （一）制作或者出具的文件不齐备或者不符合要求； （二）擅自改动注册申请文件、信息披露资料或者其他已提交文件； （三）注册申请文件或者信息披露资料存在相互矛盾或者同一事实表述不一致且有实质性差异； （四）文件披露的内容表述不清，逻辑混乱，严重影响投资者理解； （五）未及时报告或者未及时披露重大事项。 发行人存在前款规定情形的，中国证监会可视情节轻重，采取责令改正、监管谈话、出具警示函、6个月至1年内不接受发行人公开发行证券相关文件的监管措施。"},{"i":75,"n":"第七十五条","txt":"发行人披露盈利预测的，利润实现数如未达到盈利预测的80%，除因不可抗力外，其法定代表人、财务负责人应当在股东大会及中国证监会指定报刊上公开作出解释并道歉；中国证监会可以对法定代表人处以警告。 利润实现数未达到盈利预测的50%的，除因不可抗力外，中国证监会在3年内不受理该公司的公开发行证券申请。 注册会计师为上述盈利预测出具审核报告的过程中未勤勉尽责的，中国证监会将视情节轻重，对相关机构和责任人员采取监管谈话等监管措施，记入诚信档案并公布；情节严重的，给予警告等行政处罚。"},{"i":76,"n":"第七十六条","txt":"发行人及其控股股东和实际控制人、董事、监事、高级管理人员，保荐人、承销商、证券服务机构及其相关执业人员，在股票公开发行并上市相关的活动中存在其他违反本办法规定行为的，中国证监会可以视情节轻重，采取责令改正、监管谈话、出具警示函、责令公开说明、责令参加培训、责令定期报告、认定为不适当人选、暂不受理与行政许可有关的文件等监管措施，或者采取证券市场禁入的措施。"},{"i":77,"n":"第七十七条","txt":"发行人及其控股股东、实际控制人、保荐人、证券服务机构及其相关人员违反《中华人民共和国证券法》依法应予以行政处罚的，中国证监会将依法予以处罚；对欺诈发行、虚假陈述负有责任的发行人、保荐人、会计师事务所、律师事务所、资产评估机构及其责任人员依法从重处罚。涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":78,"n":"第七十八条","txt":"交易所负责对发行人及其控股股东、实际控制人、保荐人、承销商、证券服务机构等进行自律监管。 中国证券业协会负责制定保荐业务、发行承销自律监管规则，对保荐人、承销商、保荐代表人、网下投资者进行自律监管。 交易所和中国证券业协会应当对发行上市过程中违反自律监管规则的行为采取自律监管措施或者给予纪律处分。"},{"i":79,"n":"第七十九条","txt":"中国证监会会同有关部门，加强对发行人等相关市场主体的监管信息共享，完善失信联合惩戒机制。 第八章附则"},{"i":80,"n":"第八十条","txt":"符合《国务院办公厅转发证监会关于开展创新企业境内发行股票或存托凭证试点若干意见的通知》（国办发〔2018〕21号，以下简称《若干意见》）等规定的红筹企业，申请首次公开发行股票并在科创板上市，还应当符合本办法相关规定，但公司形式可适用其注册地法律规定；申请发行存托凭证并在科创板上市的，适用本办法关于发行上市审核注册程序的规定。 前款规定的红筹企业在科创板发行上市，适用《若干意见》“营业收入快速增长，拥有自主研发、国际领先技术，同行业竞争中处于相对优势地位”的具体标准，由交易所制定具体规则，并报中国证监会批准。"},{"i":81,"n":"第八十一条","txt":"本办法自公布之日起施行。"}],"gupiaoqiquanjiaoyishidianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范股票期权交易试点，维护股票期权市场秩序，防范市场风险，保护股票期权交易各方的合法权益，促进资本市场健康发展，根据《证券法》、《期货交易管理条例》、《证券公司监督管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"任何单位和个人从事股票期权交易及其相关活动，应当遵守本办法。 本办法所称股票期权交易，是指采用公开的集中交易方式或者中国证券监督管理委员会（以下简称中国证监会）批准的其他方式进行的以股票期权合约为交易标的的交易活动。 本办法所称股票期权合约，是指由证券交易所统一制定的、规定买方有权在将来特定时间按照特定价格买入或者卖出约定股票、跟踪股票指数的交易型开放式指数基金等标的证券的标准化合约。"},{"i":3,"n":"第三条","txt":"从事股票期权交易活动，应当遵循公开、公平、公正和诚实信用的原则。禁止欺诈、内幕交易、操纵股票期权市场以及利用股票期权交易从事跨市场操纵、内幕交易等违法行为。"},{"i":4,"n":"第四条","txt":"中国证监会对股票期权市场实行集中统一的监督管理。 证券交易所、证券登记结算机构、相关行业协会按照章程及业务规则，分别对股票期权交易活动及经营机构实行自律管理。"},{"i":5,"n":"第五条","txt":"证券交易所经中国证监会批准可以开展股票期权交易。 股票期权交易品种的上市、中止、取消或者恢复应当经中国证监会批准。 股票期权交易品种应当具有充分的现货交易基础，市场竞争充分，可供交割量充足等，适于进行股票期权交易。"},{"i":6,"n":"第六条","txt":"证券登记结算机构经中国证监会批准可以履行在证券交易所开展的股票期权交易的结算职能，并承担相应法律责任。 证券登记结算机构作为股票期权结算参与人（以下简称结算参与人）的共同对手方，为股票期权业务提供多边净额结算服务，并按照货银对付原则实施期权行权结算。"},{"i":7,"n":"第七条","txt":"证券公司可以从事股票期权经纪业务、自营业务、做市业务，期货公司可以从事股票期权经纪业务、与股票期权备兑开仓以及行权相关的证券现货经纪业务。 证券公司、期货公司等股票期权经营机构（以下简称经营机构）依法从事前款规定的股票期权相关业务，应当遵守法律、行政法规以及中国证监会的相关规定，具体办法由中国证监会另行制定。"},{"i":8,"n":"第八条","txt":"股票期权交易可以实行做市商制度。 股票期权做市商（以下简称做市商）应当依据证券交易所的相关业务规则，承担为股票期权合约提供双边报价等义务，并享有相应的权利。 做市商从事做市业务，应当严格遵守法律法规、行政规章和证券交易所有关规定；建立健全信息隔离制度，防范做市业务与其他业务之间的利益冲突；不得利用从事做市业务的机会，进行内幕交易、市场操纵等违法违规行为，或者谋取其他不正当利益。"},{"i":9,"n":"第九条","txt":"中国证券投资者保护基金公司、中国期货保证金监控中心公司作为保证金安全存管监控机构，依照有关规定分别负责对证券公司、期货公司开展股票期权业务涉及的投资者资金安全存管实施监控。"},{"i":10,"n":"第十条","txt":"证券交易所、证券登记结算机构应当根据各自职责，分别制定股票期权交易、结算规则及相应实施细则。交易规则和结算规则的制定或者修改应当报中国证监会批准。实施细则的制定或者修改应当征求中国证监会意见，并在正式发布实施前，报告中国证监会。 经营机构、结算参与人、投资者以及其他股票期权交易参与主体应当遵守证券交易所、证券登记结算机构及保证金安全存管监控机构的业务规则。"},{"i":11,"n":"第十一条","txt":"股票期权交易实行投资者适当性制度。 证券交易所应当制定股票期权投资者的具体标准和实施指引。 投资者参与股票期权交易，应当对股票期权产品及市场环境的变化自主承担风险。"},{"i":12,"n":"第十二条","txt":"经营机构应当按照证券交易所投资者适当性管理要求对投资者的身份和风险承受能力进行审慎评估，根据投资者的风险承受和风险识别能力决定是否推荐其参与股票期权交易，并应当事先对产品、服务以及可能影响投资者权利义务的信息进行恰当说明，充分揭示风险，经投资者签署风险揭示书后，与投资者签订经纪合同，不得误导、欺诈投资者。 经纪合同中应当包括经营机构对投资者采取的风险管理措施、投资者出现交收违约或者保证金不足情形的处理方式以及强行平仓和行权操作等事项。 经营机构应当对投资者与其发生纠纷时的处理规则和程序、投资者投诉的方式和渠道以及投资者权益保障等事项进行说明和公示。"},{"i":13,"n":"第十三条","txt":"经营机构从事股票期权经纪业务，接受投资者委托，以自己的名义为投资者进行股票期权交易，交易结果由投资者承担。"},{"i":14,"n":"第十四条","txt":"证券登记结算机构负责投资者衍生品合约账户的统一管理。经营机构应当根据投资者的申请，按照证券登记结算机构业务规则为投资者开立衍生品合约账户。 证券登记结算机构负责统一为经营机构分配、发放投资者衍生品合约账户号码。 经营机构应当明确提示投资者如实提供开户信息。投资者应当如实申报开户材料，不得采用虚假申报等手段规避投资者适当性制度要求。投资者衍生品合约账户应当与其人民币普通股票账户的相关注册信息一致。"},{"i":15,"n":"第十五条","txt":"股票期权买方应当支付权利金。股票期权卖方收取权利金，并应当根据证券交易所、证券登记结算机构的规定交纳保证金。 保证金以现金、证券交易所及证券登记结算机构认可的证券方式交纳。 经营机构向投资者收取的保证金以及投资者存放于经营机构的权利金、行权资金，属于投资者所有，除按照相关规定可划转的情形外，严禁挪作他用。"},{"i":16,"n":"第十六条","txt":"证券公司应当在存管银行开设投资者股票期权保证金账户，用于存放投资者股票期权交易的权利金、行权资金、以现金形式提交的保证金。 期货公司应当将投资者股票期权交易的权利金、行权资金、以现金形式提交的保证金存放于期货保证金账户。期货公司开展与股票期权备兑开仓以及行权相关的证券现货经纪业务的，还应当在存管银行单独开立相关现货资金账户。 经营机构应当对向投资者收取的资金实行分账管理，妥善记载单个投资者的资金明细数据，并且与经营机构自有资金、证券现货交易结算资金实行分户管理，相关资金的划转应当符合中国证监会相关规定。"},{"i":17,"n":"第十七条","txt":"结算参与人应当根据相关业务规则的规定，在证券登记结算机构开立股票期权资金保证金账户，用于存放结算参与人股票期权交易的权利金、行权资金、以现金形式提交的保证金。证券登记结算机构应当对结算参与人存放的投资者股票期权交易的权利金、行权资金、以现金形式提交的保证金与结算参与人存放的自有资金实行分户管理。 结算参与人可以根据相关业务规则的规定，在证券登记结算机构开立股票期权证券保证金账户，用于存放以证券形式提交的保证金，具体事宜由证券交易所、证券登记结算机构另行规定。"},{"i":18,"n":"第十八条","txt":"股票期权买方有权决定在合约规定期间内是否行权。股票期权买方提出行权时，股票期权卖方应当按照有关规定履行相应义务。 投资者可以根据证券交易所业务规则的规定，采用自有资金、证券或依法借入的资金、证券进行行权结算。 经营机构可以在经纪合同中与投资者约定为其提供协议行权服务。提供协议行权服务的，经营机构应当在经纪合同中对触发条件、行权数量、操作流程以及该项服务可能产生的风险等内容进行详细约定并向投资者作充分说明，经营机构还应当对该项服务的实际操作流程进行记录，相关记录保存期限不得少于20年。 股票期权合约到期前，经营机构应当采取网络、电话、短信、电子邮件或者其他适当方式中的至少一种醒投资者妥善处理股票期权交易持仓，并对提醒情况进行记录，相关记录保存期限不得少于20年。"},{"i":19,"n":"第十九条","txt":"股票期权交易实行当日无负债结算制度。 证券登记结算机构应当在当日及时将结算结果通知结算参与人，结算参与人据此对投资者进行结算，并应当将结算结果按照与投资者约定的方式及时通知投资者。 投资者应当及时查询并妥善处理自己的交易持仓。"},{"i":20,"n":"第二十条","txt":"结算参与人出现保证金不足、交收违约情形的，证券登记结算机构有权按照业务规则的规定，对其采取直接扣款，处置结算参与人期权保证金，暂不交付并处置其应收证券、资金或者担保证券，扣划其自营证券，收取违约金等措施。 投资者出现保证金不足、交收违约情形的，经营机构可以根据相关业务规则及经纪合同的规定，对其采取处置投资者期权保证金，暂不交付并处置其应收证券、资金或者担保证券，收取违约金等措施。 结算参与人可以委托证券登记结算机构将暂不交付给投资者的证券划付至结算参与人的证券处置账户内进行处置。"},{"i":21,"n":"第二十一条","txt":"证券交易所开展股票期权交易活动，应当建立保证金、涨跌停板、持仓限额、大户持仓报告、风险准备金、风险警示制度以及中国证监会规定的其他风险管理制度，并在业务规则中明确上市公司董事、监事、高级管理人员以及持股达到一定比例的股东等相关主体从事股票期权交易的规范要求。 证券登记结算机构开展股票期权交易活动，应当建立保证金、当日无负债结算、强行平仓、结算担保金、风险准备金以及中国证监会规定的其他风险管理制度。 证券交易所、证券登记结算机构建立相同的风险管理制度的，应当在业务规则中明确各自的职责分工。 经营机构应当遵守中国证监会、证券交易所、证券登记结算机构以及行业自律组织规定的风险管理制度，建立健全并严格执行股票期权业务合规管理及风险管理制度，保障投资者保证金的存管安全，按照规定提取、管理和使用风险准备金，按照证券交易所的规定，向其报告大户名单、交易情况。"},{"i":22,"n":"第二十二条","txt":"结算参与人的保证金不足且未在证券登记结算机构规定时间内追加保证金或者自行平仓的，证券登记结算机构应当按照《期货交易管理条例》以及业务规则的规定将该结算参与人负责结算的合约强行平仓。 投资者保证金不足且未在经营机构规定时间内追加保证金或者自行平仓的，经营机构应当按照《期货交易管理条例》、相关业务规则以及经纪合同的规定将该投资者的合约强行平仓。 因强行平仓发生的有关费用和损失由相关主体根据相关业务规则、经纪合同的规定承担。"},{"i":23,"n":"第二十三条","txt":"当出现不可抗力、市场操纵、技术系统故障等异常情况，影响股票期权交易正常秩序时，证券交易所可以按照业务规则规定的权限和程序，决定采取下列紧急措施： （一）调整保证金； （二）调整涨跌停板幅度； （三）调整经营机构或者投资者的持仓限额； （四）限制经营机构或投资者开仓，或要求其限期平仓； （五）暂时停止股票期权合约的交易； （六）其他紧急措施。 出现前款所述情形，导致或者可能导致股票期权重大结算风险时，证券登记结算机构可以按照业务规则规定的权限和程序，决定采取限制出金或入金、强行平仓或其他紧急措施。 证券交易所、证券登记结算机构根据本条规定采取上述措施，应当立即报告中国证监会、向市场公告，并积极协助、配合对方履行相应职责。因采取上述措施发生的有关费用、损失，由相关主体根据相关业务规则、经纪合同的规定承担。"},{"i":24,"n":"第二十四条","txt":"证券交易所、证券登记结算机构、保证金安全存管监控机构应当根据各自职责，建立股票期权市场与其他证券、期货等相关市场以及监管机构之间的信息共享、市场监测、风险控制、打击违法违规等协作机制。 证券交易所、证券登记结算机构、保证金安全存管监控机构发现股票期权交易活动中存在违法违规行为的，应当及时向中国证监会报告，并按照有关规定通报中国证监会派出机构。"},{"i":25,"n":"第二十五条","txt":"任何单位或者个人不得编造、传播有关股票期权交易的虚假信息扰乱市场秩序，不得通过《期货交易管理条例》第七十一条规定的手段以及操纵相关标的证券市场等手段操纵股票期权市场，不得利用《期货交易管理条例》第八十二条第（十一）项规定的内幕信息、相关标的证券市场的内幕信息以及其他未公开信息从事股票期权交易，或者向他人泄露上述信息、使他人利用上述信息从事股票期权交易。 任何单位或者个人不得通过操纵股票期权市场等手段操纵相关标的证券市场，不得利用股票期权市场的内幕信息从事相关标的证券交易，或者向他人泄露上述信息、使他人利用上述信息从事相关标的证券交易。"},{"i":26,"n":"第二十六条","txt":"证券交易所、证券登记结算机构开展股票期权交易与结算业务时，相关业务活动依照《期货交易管理条例》关于期货交易所开展期货交易的有关监管要求和法律责任执行。 除法律法规及中国证监会另有规定外，证券公司从事股票期权经纪业务时，相关业务活动参照适用期货公司从事期货经纪业务的有关监管要求和法律责任；期货公司从事与股票期权备兑开仓以及行权相关的证券现货经纪业务时，相关业务活动参照适用证券公司从事证券经纪业务的有关监管要求和法律责任。"},{"i":27,"n":"第二十七条","txt":"任何单位或者个人违反期货法律、法规、规章以及本办法，中国证监会及其派出机构按照《期货交易管理条例》以及中国证监会的相关规定对其采取责令改正、监管谈话、出具警示函等监管措施；应当给予处罚的，按照《期货交易管理条例》以及中国证监会的相关规定进行处罚；涉嫌犯罪的，依法移送司法机关追究刑事责任。 任何单位或者个人违反本办法第二十五条第二款的规定，操纵相关标的证券市场或者进行相关标的证券内幕交易的，中国证监会及其派出机构按照《证券法》以及中国证监会的相关规定对其采取责令改正、监管谈话、出具警示函等监管措施；应当给予处罚的，按照《证券法》以及中国证监会的相关规定进行处罚；涉嫌犯罪的，依法移送司法机关追究刑事责任。 任何单位或者个人违反本办法以及《期货交易管理条例》的规定，在股票期权交易中从事违法违规行为，给投资者造成损失的，应当依法承担赔偿责任。"},{"i":28,"n":"第二十八条","txt":"本办法下列用语具有如下含义： 保证金安全存管监控机构，是指中国证券投资者保护基金公司、中国期货保证金监控中心公司或者中国证监会批准的其他保证金安全存管监控机构。 股票期权经营机构，是指经中国证监会批准经营股票期权业务的证券公司、期货公司等金融机构。 股票期权结算参与人，是指具有证券登记结算机构股票期权结算业务结算参与人资格的机构。 做市商，是指经证券交易所认可、为其上市交易的股票期权合约提供双边持续报价或者双边回应报价等服务的机构。 权利金，是指股票期权买方向卖方支付的用于购买股票期权合约的资金。 保证金，是指用于结算和保证股票期权合约履行的现金或者证券。 衍生品合约账户，是指经营机构按照证券登记结算机构业务规则，为投资者开立的用于股票期权合约交易、行权申报及记录投资者持有的股票期权合约及其变动情况的账户。 股票期权买方，是指持有股票期权合约权利仓的投资者。权利仓指股票期权合约买入开仓"},{"i":29,"n":"第二十九条","txt":"其他交易场所经中国证监会批准可以开展股票期权交易，具体业务规范参照本办法的有关规定执行。"},{"i":30,"n":"第三十条","txt":"本办法自公布之日起施行。"}],"xingzhenghejieshidianshishibanfa":[{"i":1,"n":"第一条","txt":"为了试点开展证券期货领域行政和解工作，规范行政和解实施行为，保护投资者的合法权益，根据有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称行政和解，是指中国证券监督管理委员会（以下简称中国证监会）在对公民、法人或者其他组织（以下简称行政相对人）涉嫌违反证券期货法律、行政法规和相关监管规定行为进行调查执法过程中，根据行政相对人的申请，与其就改正涉嫌违法行为，消除涉嫌违法行为不良后果，交纳行政和解金补偿投资者损失等进行协商达成行政和解协议，并据此终止调查执法程序的行为。"},{"i":3,"n":"第三条","txt":"实施行政和解，应当依照本办法规定的条件、程序和期限。"},{"i":4,"n":"第四条","txt":"实施行政和解，应当遵循公平、自愿、协商、效能原则。中国证监会不得向行政相对人主动或者变相主动提出行政和解建议，或者强制行政相对人进行行政和解。"},{"i":5,"n":"第五条","txt":"行政和解协议的订立和履行，不得损害国家和社会公共利益，不得损害他人合法权益。"},{"i":6,"n":"第六条","txt":"行政相对人涉嫌实施虚假陈述、内幕交易、操纵市场或者欺诈客户等违反证券期货法律、行政法规和相关监管规定的行为，案件符合下列情形的，可以适用行政和解程序： （一）中国证监会已经正式立案，且经过了必要调查程序，但案件事实或者法律关系尚难完全明确； （二）采取行政和解方式执法有利于实现监管目的，减少争议，稳定和明确市场预期，恢复市场秩序，保护投资者合法权益； （三）行政相对人愿意采取有效措施补偿因其涉嫌违法行为受到损失的投资者； （四）以行政和解方式结案不违反法律、行政法规的禁止性规定，不损害社会公共利益和他人合法权益。 中国证监会派出机构负责查处的案件，试点期间不适用行政和解程序。"},{"i":7,"n":"第七条","txt":"案件有下列情形之一的，中国证监会不得与行政相对人进行行政和解： （一）行政相对人违法行为的事实清楚，证据充分，法律适用明确，依法应当给予行政处罚的； （二）行政相对人涉嫌犯罪，依法应当移送司法机关处理的； （三）中国证监会基于审慎监管原则认定不适宜行政和解的。"},{"i":8,"n":"第八条","txt":"中国证监会实施行政和解，由专门的行政和解实施部门（以下简称和解实施部门）负责，与中国证监会的案件调查部门（以下简称案件调查部门）、案件审理部门（以下简称案件审理部门）相互独立。"},{"i":9,"n":"第九条","txt":"行政相对人自收到中国证监会送达的案件调查通知书之日起，至中国证监会作出行政处罚决定前，可以向中国证监会提出行政和解申请。"},{"i":10,"n":"第十条","txt":"行政相对人提出行政和解申请的，应当提交申请书及相关申请材料。申请书应当载明以下事项： （一）申请人的基本情况； （二）申请行政和解的主要事实和理由； （三）申请人就其涉嫌违法行为提出改正或者减轻、消除危害后果的方案； （四）中国证监会要求载明的其他事项。 行政相对人为法人或者其他组织的，应当提交其依据《中华人民共和国公司法》、《中华人民共和国合伙企业法》等法律、行政法规以及公司章程、合伙协议规定所作出的关于申请行政和解的内部决定。"},{"i":11,"n":"第十一条","txt":"行政相对人申请行政和解，应当如实向中国证监会提交有关材料，并对其申请材料的真实性、准确性负责。"},{"i":12,"n":"第十二条","txt":"对于行政相对人提交的行政和解申请书及相关申请材料，和解实施部门应当办理登记手续，并向行政相对人出具行政和解申请接收凭证。需要行政相对人补正申请材料的，申请人应当按照和解实施部门要求提交全部补正材料，和解实施部门在申请人提交全部补正材料后出具行政和解申请接收凭证。"},{"i":13,"n":"第十三条","txt":"和解实施部门应当在出具行政和解申请接收凭证之日起5个工作日内就案件是否符合本办法第六条规定的条件、是否存在本办法第七条规定的情形等书面征求案件调查部门的意见。"},{"i":14,"n":"第十四条","txt":"案件调查部门应当自收到和解实施部门征求意见书面材料之日起20个工作日内书面反馈意见。反馈意见应当包括以下内容及相关材料： （一）案件是否符合本办法第六条规定条件、是否存在本办法第七条规定情形的明确意见； （二）截至反馈意见时，案件调查的具体情况以及是否掌握行政相对人涉嫌违法的部分证据或者证据线索的材料； （三）其他需要提交的材料。 案件调查部门在向和解实施部门书面反馈意见后，行政和解申请受理前，发现新的事实、证据，认为案件不再符合行政和解受理条件的，应当及时告知和解实施部门。"},{"i":15,"n":"第十五条","txt":"行政相对人在案件移送案件审理部门后，作出行政处罚决定前提出行政和解申请的，和解实施部门除依照本办法第十三条的规定征求案件调查部门意见外，还应当按照相同程序和时限征求案件审理部门的意见。"},{"i":16,"n":"第十六条","txt":"案件审理部门应当在收到和解实施部门征求意见书面材料之日起20个工作日内书面反馈意见。反馈意见应当包括以下内容及相关材料： （一）案件是否符合本办法第六条规定条件、是否存在本办法第七条规定情形的明确意见； （二）截至反馈意见时，案件审理的具体情况； （三）其他需要提交的材料。"},{"i":17,"n":"第十七条","txt":"行政相对人的行政和解申请符合本办法第六条规定条件的，由和解实施部门自向行政相对人出具行政和解申请接收凭证之日起40个工作日内向行政相对人出具受理通知，并抄送案件调查部门、案件审理部门、行政和解金管理机构。 不符合本办法第六条规定条件，或者存在本办法第七条规定情形的，由和解实施部门自向行政相对人出具行政和解申请接收凭证之日起40个工作日内向行政相对人出具不予受理通知，并抄送案件调查部门、案件审理部门。"},{"i":18,"n":"第十八条","txt":"立案调查不满3个月的案件，行政相对人提出行政和解申请的，不予受理，但有特殊情况经中国证监会主要负责人批准的除外。"},{"i":19,"n":"第十九条","txt":"中国证监会受理行政和解申请后，在与行政相对人达成行政和解协议之前，不中止对行政相对人所涉案件的调查工作。受理的行政和解申请案件已经移送案件审理部门审理的，案件审理部门应当中止对案件的审理。"},{"i":20,"n":"第二十条","txt":"行政相对人在提交行政和解申请后，中国证监会正式受理前，可以申请撤回行政和解申请。"},{"i":21,"n":"第二十一条","txt":"和解实施部门自作出受理行政和解申请决定之日起，可以与行政相对人就以下事项进行沟通和协商： （一）行政相对人涉嫌违法行为的情况； （二）行政相对人涉嫌违法行为可能给社会造成的危害、给投资者造成的损失； （三）行政相对人愿意承担的行政和解金数额及交纳时限； （四）行政相对人可以采取的其他纠正涉嫌违法行为以及积极消除、减轻涉嫌违法行为危害后果的措施； （五）行政和解协议的具体内容； （六）行政和解协议的执行保障措施； （七）其他事项。"},{"i":22,"n":"第二十二条","txt":"行政和解协商应当以当面协商的形式进行。中国证监会进行协商的工作人员不得少于两人，并应当向行政相对人出示执法证件。"},{"i":23,"n":"第二十三条","txt":"和解实施部门与行政相对人进行行政和解协商的期限为三个月。经中国证监会主要负责人批准，可以延期。"},{"i":24,"n":"第二十四条","txt":"行政和解协商实行回避制度。实施行政和解的工作人员有下列情形之一的，应当回避： （一）是行政相对人的配偶、父母、子女等近亲属； （二）与案件有利害关系； （三）与行政相对人或者案件有其他关系，可能影响案件的公正处理。 行政相对人有权通过口头或者书面方式申请上述工作人员回避。"},{"i":25,"n":"第二十五条","txt":"中国证监会在与行政相对人进行行政和解协商过程中，可以就所涉及的专业问题征求证券交易所、期货交易所、登记结算机构等相关机构或者有关专家学者的意见。"},{"i":26,"n":"第二十六条","txt":"中国证监会与行政相对人就涉嫌违法行为的处理进行沟通、协商，达成一致的，签订行政和解协议。行政和解协议应当载明以下事项： （一）行政和解的事由； （二）行政相对人交纳行政和解金的数额、方式； （三）行政相对人对涉嫌违法行为进行整改以及消除、减轻涉嫌违法行为所造成危害后果的其他具体措施； （四）行政相对人履行行政和解协议的期限； （五）需要载明的其他事项。 行政相对人为法人或者其他组织的，其关于签订行政和解协议的决定，应当履行《中华人民共和国公司法》、《中华人民共和国合伙企业法》等相关法律、行政法规规定及公司章程、合伙协议规定的决策程序。"},{"i":27,"n":"第二十七条","txt":"行政和解金数额的确定应当考虑下列情形： （一）行政相对人涉嫌违法行为如被查实依法可处以罚款或者没收违法所得的金额； （二）行政相对人因涉嫌违法行为所获收益、所避免的损失； （三）其他人因涉案违法行为所遭受的损失； （四）需要考虑的其他情形。 中国证监会在就行政和解金的数额与行政相对人进行协商的过程中，可以采取适当方式，就投资者损失情况听取投资者的意见。"},{"i":28,"n":"第二十八条","txt":"中国证监会应当依照规定公开行政和解协议的主要内容。 达成行政和解协议的行政相对人为上市公司、非上市公众公司及其董事、监事、高级管理人员、控股股东、实际控制人的，应当按照中国证监会及证券交易场所的相关规定履行信息披露义务。"},{"i":29,"n":"第二十九条","txt":"行政和解协议达成后，由和解实施部门监督行政相对人在协议规定的时限内履行协议规定的义务。 和解实施部门应当在行政和解协议达成后2个工作日内将达成行政和解协议的情况书面告知案件调查部门、案件审理部门、行政和解金管理机构。案件调查部门在收到书面告知后应当中止案件调查。 行政相对人履行全部义务后，和解实施部门应当向行政相对人出具行政和解结案通知，并抄送案件调查部门、案件审理部门、行政和解金管理机构。案件调查部门、案件审理部门应当依照规定终止案件的调查、审理。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，中国证监会应当终止行政和解程序： （一）中国证监会在受理行政相对人的行政和解申请后，达成行政和解协议前，经调查发现新的事实、证据，认为案件不再符合行政和解受理条件的； （二）未能在本办法第二十三条规定的期限内达成行政和解协议的； （三）行政和解协议达成后，行政相对人不履行行政和解协议的； （四）中国证监会在受理行政相对人的行政和解申请后，行政和解协议执行完毕前，发现行政相对人存在所提供的行政和解材料有虚假记载或者重大遗漏等情形的； （五）中国证监会基于审慎监管原则认为有必要终止行政和解程序的。 有前款规定情形的，和解实施部门应当向行政相对人出具行政和解程序终止通知，并抄送案件调查部门、案件审理部门、行政和解金管理机构。已中止调查、审理的案件，案件调查部门、案件审理部门应当及时恢复调查、审理程序。"},{"i":31,"n":"第三十一条","txt":"行政和解协议达成后，行政相对人不履行行政和解协议的，行政和解协议无效。"},{"i":32,"n":"第三十二条","txt":"行政相对人未能在规定期限内与中国证监会达成行政和解协议的，中国证监会在继续调查、恢复审理时不得再次适用行政和解程序；行政相对人未按照约定履行行政和解协议的，中国证监会在恢复调查、审理后不得再次适用行政和解程序。"},{"i":33,"n":"第三十三条","txt":"中国证监会在向行政相对人出具行政和解结案通知后，发现行政相对人存在所提供的行政和解材料有虚假记载或者重大遗漏等情形的，重新启动案件调查、审理程序。行政相对人已根据行政和解协议交纳的行政和解金，不予返还。 出现前款所规定情形的，和解实施部门应当及时告知行政相对人。"},{"i":34,"n":"第三十四条","txt":"行政相对人交纳的行政和解金由行政和解金管理机构进行专户管理。"},{"i":35,"n":"第三十五条","txt":"行政相对人因其涉嫌违法行为造成投资者损失的，投资者可以向行政和解金管理机构申请补偿。 投资者可以通过行政和解金补偿程序获得补偿，或者按照《中华人民共和国民事诉讼法》的规定对行政相对人提起民事损害赔偿诉讼请求赔偿。但投资者已通过行政和解金补偿程序获得补偿的，不应就已获得补偿部分再行请求民事损害赔偿。"},{"i":36,"n":"第三十六条","txt":"行政和解金管理和使用的具体办法由中国证监会会同财政部另行制定。"},{"i":37,"n":"第三十七条","txt":"中国证监会及其工作人员应当对行政和解工作情况严格保密，但法律、行政法规和本办法另有规定的除外。"},{"i":38,"n":"第三十八条","txt":"中国证监会的工作人员违反本办法相关规定，滥用职权，玩忽职守，利用职务便利牟取不正当利益，泄露所知悉的有关单位或者个人的秘密，或者主动、变相主动提出行政和解、违反程序实施行政和解的，根据情节轻重，给予处分；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"本办法自2015年3月29日起施行。"}],"zhengquanyecongyerenyuanzigeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强证券业从业人员资格管理，促进证券市场规范发展，保护投资者合法权益，根据《中华人民共和国证券法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在依法从事证券业务的机构（以下简称“机构”）中从事证券业务的专业人员，应当按照本办法规定，取得从业资格和执业证书。"},{"i":3,"n":"第三条","txt":"本办法所称机构是指： （一）证券公司； （二）基金管理公司、基金托管机构、基金销售机构； （三）证券投资咨询机构； （四）证券资信评估机构； （五）中国证券监督管理委员会（以下简称“中国证监会”）规定的其他从事证券业务的机构。"},{"i":4,"n":"第四条","txt":"本办法所称从事证券业务的专业人员是指： （一）证券公司中从事自营、经纪、承销、投资咨询、受托投资管理等业务的专业人员，包括相关业务部门的管理人员； （二）基金管理公司、基金托管机构中从事基金销售、研究分析、投资管理、交易、监察稽核等业务的专业人员，包括相关业务部门的管理人员；基金销售机构中从事基金宣传、推销、咨询等业务的专业人员，包括相关业务部门的管理人员； （三）证券投资咨询机构中从事证券投资咨询业务的专业人员及其管理人员； （四）证券资信评估机构中从事证券资信评估业务的专业人员及其管理人员； （五）中国证监会规定需要取得从业资格和执业证书的其他人员。"},{"i":5,"n":"第五条","txt":"中国证券业协会（以下简称“协会”）依据本办法负责从业人员从业资格考试、执业证书发放以及执业注册登记等工作。"},{"i":6,"n":"第六条","txt":"中国证监会对协会有关证券业从业人员资格管理的工作进行指导和监督。"},{"i":7,"n":"第七条","txt":"参加资格考试的人员，应当年满18周岁，具有高中以上文化程度和完全民事行为能力。"},{"i":8,"n":"第八条","txt":"资格考试由协会统一组织。参加考试的人员考试合格的，取得从业资格。"},{"i":9,"n":"第九条","txt":"从业资格不实行专业分类考试。资格考试内容包括一门基础性科目和一门专业性科目。 根据证券市场发展的需要，协会可在资格考试之外另行组织各项专业的水平考试，但不作为法定考试内容，由从业人员自行选择，供机构用人时参考。"},{"i":10,"n":"第十条","txt":"取得从业资格的人员，符合下列条件的，可以通过机构申请执业证书： （一）已被机构聘用； （二）最近三年未受过刑事处罚； （三）不存在《中华人民共和国证券法》第一百二十六条规定的情形； （四）未被中国证监会认定为证券市场禁入者，或者已过禁入期的； （五）品行端正，具有良好的职业道德； （六）法律、行政法规和中国证监会规定的其他条件。 申请执业证券投资咨询以及证券资信评估业务的，申请人应当同时符合《中华人民共和国证券法》第一百五十八条，以及其他相关规定。"},{"i":11,"n":"第十一条","txt":"申请人符合本办法规定条件的，协会应当自收到申请之日起三十日内，向中国证监会备案，颁发执业证书；不符合本办法规定条件的，不予颁发执业证书，并应当自收到申请之日起三十日内书面通知申请人或者机构，并书面说明理由。"},{"i":12,"n":"第十二条","txt":"执业证书不实行分类。取得执业证书的人员，经机构委派，可以代表聘用机构对外开展本机构经营的证券业务。"},{"i":13,"n":"第十三条","txt":"取得执业证书的人员，连续三年不在机构从业的，由协会注销其执业证书；重新执业的，应当参加协会组织的执业培训，并重新申请执业证书。"},{"i":14,"n":"第十四条","txt":"从业人员取得执业证书后，辞职或者不为原聘用机构所聘用的，或者其他原因与原聘用机构解除劳动合同的，原聘用机构应当在上述情形发生后十日内向协会报告，由协会变更该人员执业注册登记。 取得执业证书的从业人员变更聘用机构的，新聘用机构应当在上述情形发生后十日内向协会报告，由协会变更该人员执业注册登记。"},{"i":15,"n":"第十五条","txt":"机构不得聘用未取得执业证书的人员对外开展证券业务。"},{"i":16,"n":"第十六条","txt":"从业人员在执业过程中违反有关证券法律、行政法规以及中国证监会有关规定，受到聘用机构处分的，该机构应当在处分后十日内向协会报告。"},{"i":17,"n":"第十七条","txt":"协会、机构应当定期组织取得执业证书的人员进行后续职业培训，提高从业人员的职业道德和专业素质。"},{"i":18,"n":"第十八条","txt":"协会依据本办法及中国证监会有关规定制定的从业资格考试办法、考试大纲、执业证书管理办法以及执业行为准则等，应当报中国证监会核准。"},{"i":19,"n":"第十九条","txt":"协会应当建立从业人员资格管理数据库，进行资格公示和执业注册登记管理。"},{"i":20,"n":"第二十条","txt":"参加资格考试的人员，违反考场规则，扰乱考场秩序的，在两年内不得参加资格考试。"},{"i":21,"n":"第二十一条","txt":"取得从业资格的人员提供虚假材料，申请执业证书的，不予颁发执业证书；已颁发执业证书的，由协会注销其执业证书。"},{"i":22,"n":"第二十二条","txt":"机构办理执业证书申请过程中，弄虚作假、徇私舞弊、故意刁难有关当事人的，或者不按规定履行报告义务的，由协会责令改正；拒不改正的，由协会对机构及其直接责任人员给予纪律处分；情节严重的，由中国证监会单处或者并处警告、3万元以下罚款。"},{"i":23,"n":"第二十三条","txt":"机构聘用未取得执业证书的人员对外开展证券业务的，由协会责令改正；拒不改正的，给予纪律处分；情节严重的，由中国证监会单处或者并处警告、3万元以下罚款。"},{"i":24,"n":"第二十四条","txt":"从业人员拒绝协会调查或者检查的，或者所聘用机构拒绝配合调查的，由协会责令改正；拒不改正的，给予纪律处分；情节严重的，由中国证监会给予从业人员暂停执业3个月至12个月，或者吊销其执业证书的处罚；对机构单处或者并处警告、3万元以下罚款。"},{"i":25,"n":"第二十五条","txt":"被中国证监会依法吊销执业证书或者因违反本办法被协会注销执业证书的人员，协会可在3年内不受理其执业证书申请。"},{"i":26,"n":"第二十六条","txt":"协会工作人员不按本办法规定履行职责，徇私舞弊、玩忽职守或者故意刁难有关当事人的，协会应当给予纪律处分。"},{"i":27,"n":"第二十七条","txt":"本办法实施前，持有协会颁发的证券经纪资格证书、证券代理发行资格证书、证券投资咨询资格证书和基金从业人员资格证书的，可以直接申请取得执业证书。 持有上述两个或者两个以上证书的，可以根据协会规定，取得专业水平级别认证。"},{"i":28,"n":"第二十八条","txt":"机构高级管理人员的资格管理由中国证监会另行规定。"},{"i":29,"n":"第二十九条","txt":"本办法自2003年2月1日起施行。1995年发布的《证券业从业人员资格管理暂行规定》同时废止。"}],"zhengquanjiaoyisuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对证券交易所的管理，促进证券交易所依法全面履行一线监管职能和服务职能，维护证券市场的正常秩序，保护投资者的合法权益，促进证券市场的健康稳定发展，根据《中华人民共和国证券法》（以下简称《证券法》）、《中华人民共和国公司法》（以下简称《公司法》），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的证券交易所是指经国务院决定设立的证券交易所。"},{"i":3,"n":"第三条","txt":"证券交易所根据《中国共产党章程》设立党组织，发挥领导作用，把方向、管大局、保落实，依照规定讨论和决定交易所重大事项，保证监督党和国家的方针、政策在交易所得到全面贯彻落实。"},{"i":4,"n":"第四条","txt":"证券交易所由中国证券监督管理委员会（以下简称中国证监会）监督管理。"},{"i":5,"n":"第五条","txt":"证券交易所的名称，应当标明证券交易所字样。其他任何单位和个人不得使用证券交易所或者近似名称。"},{"i":6,"n":"第六条","txt":"证券交易所组织和监督证券交易，实施自律管理，应当遵循社会公共利益优先原则，维护市场的公平、有序、透明。"},{"i":7,"n":"第七条","txt":"证券交易所的职能包括： （一）提供证券交易的场所、设施和服务； （二）制定和修改证券交易所的业务规则； （三）依法审核公开发行证券申请； （四）审核、安排证券上市交易，决定证券终止上市和重新上市； （五）提供非公开发行证券转让服务； （六）组织和监督证券交易； （七）对会员进行监管； （八）对证券上市交易公司及相关信息披露义务人进行监管； （九）对证券服务机构为证券上市、交易等提供服务的行为进行监管； （十）管理和公布市场信息； （十一）开展投资者教育和保护； （十二）法律、行政法规规定的以及中国证监会许可、授权或者委托的其他职能。"},{"i":8,"n":"第八条","txt":"证券交易所不得直接或者间接从事： （一）新闻出版业； （二）发布对证券价格进行预测的文字和资料； （三）为他人提供担保； （四）未经中国证监会批准的其他业务。"},{"i":9,"n":"第九条","txt":"证券交易所可以根据证券市场发展的需要，创新交易品种和交易方式，设立不同的市场层次。"},{"i":10,"n":"第十条","txt":"证券交易所制定或者修改业务规则，应当符合法律、行政法规、部门规章对其自律管理职责的要求。 证券交易所制定或者修改下列业务规则时，应当由证券交易所理事会或者董事会通过，并报中国证监会批准： （一）证券交易、上市、会员管理和其他有关业务规则； （二）涉及上市新的证券交易品种或者对现有上市证券交易品种作出较大调整； （三）以联网等方式为非本所上市的品种提供交易服务； （四）涉及证券交易方式的重大创新或者对现有证券交易方式作出较大调整； （五）涉及港澳台及境外机构的重大事项； （六）中国证监会认为需要批准的其他业务规则。 对于非会员理事的反对或者弃权表决意见，证券交易所应当在向中国证监会报送的请示或者报告中作出说明。"},{"i":11,"n":"第十一条","txt":"证券交易所制定的业务规则对证券交易业务活动的各参与主体具有约束力。对违反业务规则的行为，证券交易所给予纪律处分或者采取其他自律管理措施。"},{"i":12,"n":"第十二条","txt":"证券交易所应当按照章程、协议以及业务规则的规定，对违法违规行为采取自律监管措施或者纪律处分，履行自律管理职责。"},{"i":13,"n":"第十三条","txt":"证券交易所应当在业务规则中明确自律监管措施或者纪律处分的具体类型、适用情形和适用程序。 证券交易所采取纪律处分的，应当依据纪律处分委员会的审核意见作出。纪律处分决定作出前，当事人按照业务规则的规定申请听证的，证券交易所应当组织听证。"},{"i":14,"n":"第十四条","txt":"市场参与主体对证券交易所作出的相关自律监管措施或者纪律处分不服的，可以按照证券交易所业务规则的规定申请复核。 证券交易所应当设立复核委员会，依据其审核意见作出复核决定。"},{"i":15,"n":"第十五条","txt":"证券交易所应当建立风险管理和风险监测机制，依法监测、监控、预警并防范市场风险，维护证券市场安全稳定运行。 证券交易所应当以风险基金、一般风险准备等形式储备充足的风险准备资源，用于垫付或者弥补因技术故障、操作失误、不可抗力及其他风险事件造成的损失。"},{"i":16,"n":"第十六条","txt":"证券交易所应当同其他交易场所、登记结算机构、行业协会等证券期货业组织建立资源共享、相互配合的长效合作机制，联合依法监察证券市场违法违规行为。"},{"i":17,"n":"第十七条","txt":"实行会员制的证券交易所设会员大会、理事会、总经理和监事会。 实行有限责任公司制的证券交易所设股东会、董事会、总经理和监事会。证券交易所为一人有限责任公司的，不设股东会，由股东行使股东会的职权。"},{"i":18,"n":"第十八条","txt":"会员大会为会员制证券交易所的最高权力机构。会员大会行使下列职权： （一）制定和修改证券交易所章程； （二）选举和罢免会员理事、会员监事； （三）审议和通过理事会、监事会和总经理的工作报告； （四）审议和通过证券交易所的财务预算、决算报告； （五）法律、行政法规、部门规章和证券交易所章程规定的其他重大事项。 股东会为公司制证券交易所的最高权力机构。股东会行使下列职权： （一）修改证券交易所章程； （二）选举和更换非由职工代表担任的董事、监事； （三）审议和通过董事会、监事会的工作报告； （四）审议和通过证券交易所的财务预算、决算报告； （五）法律、行政法规、部门规章和证券交易所章程规定的其他职权。"},{"i":19,"n":"第十九条","txt":"会员制证券交易所章程应当包括下列事项： （一）设立目的； （二）名称； （三）主要办公及交易场所和设施所在地； （四）职能范围； （五）会员的资格和加入、退出程序； （六）会员的权利和义务； （七）对会员的纪律处分； （八）组织机构及其职权； （九）理事、监事、高级管理人员的产生、任免及其职责； （十）资本和财务事项； （十一）解散的条件和程序； （十二）其他需要在章程中规定的事项。 公司制证券交易所章程应当包括下列事项： （一）前款第（一）项至第（四）项、第（八）项、第（十）项和第（十一）项规定的事项； （二）董事、监事、高级管理人员的产生、任免及其职责； （三）其他需要在章程中规定的事项。 会员制证券交易所章程的制定和修改经会员大会通过后，报中国证监会批准。公司制证券交易所的章程由股东共同制定，并报中国证监会批准；章程的修改由股东会通过后，报中国证监会批准。"},{"i":20,"n":"第二十条","txt":"会员大会每年召开一次，由理事会召集，理事长主持。理事长因故不能履行职责时，由理事长指定的副理事长或者其他理事主持。有下列情形之一的，应当召开临时会员大会： （一）理事人数不足本办法规定的最低人数； （二）三分之一以上会员提议； （三）理事会或者监事会认为必要。 股东会会议由董事会召集。股东会会议的召开应当符合证券交易所章程的规定。"},{"i":21,"n":"第二十一条","txt":"会员大会应当有三分之二以上的会员出席，其决议须经出席会议的会员过半数表决通过。 股东会会议的议事规则应当符合证券交易所章程的规定。 会员大会或者股东会会议结束后十个工作日内，证券交易所应当将大会全部文件及有关情况向中国证监会报告。"},{"i":22,"n":"第二十二条","txt":"理事会是会员制证券交易所的决策机构，行使下列职权： （一）召集会员大会，并向会员大会报告工作； （二）执行会员大会的决议； （三）审定总经理提出的工作计划； （四）审定总经理提出的年度财务预算、决算方案； （五）审定对会员的接纳和退出； （六）审定取消会员资格的纪律处分； （七）审定证券交易所业务规则； （八）审定证券交易所上市新的证券交易品种或者对现有上市证券交易品种作出较大调整； （九）审定证券交易所收费项目、收费标准及收费管理办法； （十）审定证券交易所重大财务管理事项； （十一）审定证券交易所重大风险管理和处置事项，管理证券交易所风险基金； （十二）审定重大投资者教育和保护工作事项； （十三）决定高级管理人员的聘任、解聘及薪酬事项，但中国证监会任免的除外； （十四）会员大会授予和证券交易所章程规定的其他职权。 董事会是公司制证券交易所的决策机构,行使下列职权： （一）召集股东会"},{"i":23,"n":"第二十三条","txt":"证券交易所理事会由七至十三人组成，其中非会员理事人数不少于理事会成员总数的三分之一，不超过理事会成员总数的二分之一。 理事每届任期三年。会员理事由会员大会选举产生，非会员理事由中国证监会委派。 董事会由三至十三人组成。董事每届任期不得超过三年。"},{"i":24,"n":"第二十四条","txt":"理事会会议至少每季度召开一次。会议须有三分之二以上理事出席，其决议应当经出席会议的三分之二以上理事表决同意方为有效。理事会决议应当在会议结束后两个工作日内向中国证监会报告。 董事会会议的召开和议事规则应当符合证券交易所章程的规定。董事会决议应当在会议结束后两个工作日内向中国证监会报告。"},{"i":25,"n":"第二十五条","txt":"理事会设理事长一人，可以设副理事长一至二人。总经理应当是理事会成员。 董事会设董事长一人，可以设副董事长一至二人。总经理应当是董事会成员。董事长、副董事长的任免，由中国证监会提名，董事会通过。 理事长、董事长是证券交易所的法定代表人。"},{"i":26,"n":"第二十六条","txt":"理事长负责召集和主持理事会会议。理事长因故临时不能履行职责时，由副理事长或者其他理事代其履行职责。 董事长负责召集和主持董事会会议。董事长因故临时不能履行职责时，由副董事长代为履行职责；副董事长不能履行职责时，由半数以上董事共同推举一名董事召集和主持。 理事长、董事长不得兼任证券交易所总经理。"},{"i":27,"n":"第二十七条","txt":"证券交易所的总经理、副总经理、首席专业技术管理人员每届任期三年。总经理由中国证监会任免。副总经理按照中国证监会相关规定任免或者聘任。 总经理因故临时不能履行职责时，由总经理指定的副总经理代其履行职责。"},{"i":28,"n":"第二十八条","txt":"会员制证券交易所的总经理行使下列职权： （一）执行会员大会和理事会决议，并向其报告工作； （二）主持证券交易所的日常工作； （三）拟订并组织实施证券交易所工作计划； （四）拟订证券交易所年度财务预算、决算方案； （五）审定业务细则及其他制度性规定； （六）审定除取消会员资格以外的其他纪律处分； （七）审定除应当由理事会审定外的其他财务管理事项； （八）理事会授予和证券交易所章程规定的其他职权。 公司制证券交易所的总经理行使下列职权： （一）执行董事会决议，并向其报告工作； （二）前款第（二）项至第（六）项规定的职权； （三）审定除应当由董事会审定外的其他财务管理事项； （四）董事会授予和证券交易所章程规定的其他职权。"},{"i":29,"n":"第二十九条","txt":"监事会是证券交易所的监督机构，行使下列职权： （一）检查证券交易所财务； （二）检查证券交易所风险基金的使用和管理； （三）监督证券交易所理事或者董事、高级管理人员执行职务行为； （四）监督证券交易所遵守法律、行政法规、部门规章和证券交易所章程、协议、业务规则以及风险预防与控制的情况； （五）当理事或者董事、高级管理人员的行为损害证券交易所利益时，要求理事或者董事、高级管理人员予以纠正； （六）提议召开临时会员大会或者股东会会议； （七）提议会员制证券交易所召开临时理事会； （八）向会员大会或者股东会会议提出提案； （九）会员大会或者股东会授予和证券交易所章程规定的其他职权。"},{"i":30,"n":"第三十条","txt":"证券交易所监事会人员不得少于五人，其中职工监事不得少于两名，专职监事不得少于一名。 监事每届任期三年。职工监事由职工大会、职工代表大会或者其他形式民主选举产生，专职监事由中国证监会委派。证券交易所理事或者董事、高级管理人员不得兼任监事。 会员制证券交易所的监事会，会员监事不得少于两名，由会员大会选举产生。"},{"i":31,"n":"第三十一条","txt":"监事会设监事长一人，由中国证监会提名，监事会通过。 监事长负责召集和主持监事会会议。会员制证券交易所监事长因故不能履行职责时，由其指定的专职监事或者其他监事代为履行职务。公司制证券交易所监事长因故不能履行职责时，由半数以上监事共同推举一名监事代为履行职务。"},{"i":32,"n":"第三十二条","txt":"会员制证券交易所的监事会至少每六个月召开一次会议。监事长、三分之一以上监事可以提议召开临时监事会会议。监事会决议应当经半数以上监事通过。 公司制证券交易所监事会会议的召开和议事规则应当符合《公司法》及证券交易所章程的规定。 监事会决议应当在会议结束后两个工作日内向中国证监会报告。"},{"i":33,"n":"第三十三条","txt":"理事会、董事会、监事会根据需要设立专门委员会。各专门委员会的职责、任期和人员组成等事项，由证券交易所章程具体规定。 各专门委员会的经费应当纳入证券交易所的预算。"},{"i":34,"n":"第三十四条","txt":"证券交易所的从业人员应当正直诚实、品行良好、具备履行职责所必需的专业知识与能力。因违法行为或者违纪行为被开除的证券交易场所、证券公司、证券登记结算机构、证券服务机构的从业人员和被开除的国家机关工作人员，不得招聘为证券交易所的从业人员。 有《公司法》第一百四十六条规定的情形或者下列情形之一的，不得担任证券交易所理事、董事、监事、高级管理人员： （一）犯有贪污、贿赂、侵占财产、挪用财产罪或者破坏社会经济秩序罪，或者因犯罪被剥夺政治权利； （二）因违法行为或者违纪行为被解除职务的证券交易场所、证券登记结算机构的负责人，自被解除职务之日起未逾五年； （三）因违法行为或者违纪行为被解除职务的证券公司董事、监事、高级管理人员，自被解除职务之日起未逾五年； （四）因违法行为或者违纪行为被吊销执业证书或者被取消资格的律师、注册会计师或者其他证券服务机构的专业人员，自被吊销执业证书或者被取消资格之日起未"},{"i":35,"n":"第三十五条","txt":"证券交易所理事、董事、监事、高级管理人员的产生、聘任有不正当情况，或者前述人员在任期内有违反法律、行政法规、部门规章和证券交易所章程、业务规则的行为，或者由于其他原因，不适宜继续担任其所担任的职务时，中国证监会有权解除或者提议证券交易所解除有关人员的职务，并按照规定任命新的人选。"},{"i":36,"n":"第三十六条","txt":"证券交易所应当制定具体的交易规则。其内容包括： （一）证券交易的基本原则； （二）证券交易的场所、品种和时间； （三）证券交易方式、交易流程、风险控制和规范事项； （四）证券交易监督； （五）清算交收事项； （六）交易纠纷的解决； （七）暂停、恢复与取消交易； （八）交易异常情况的认定和处理； （九）投资者准入和适当性管理的基本要求； （十）对违反交易规则行为的处理规定； （十一）证券交易信息的提供和管理； （十二）指数的编制方法和公布方式； （十三）其他需要在交易规则中规定的事项。"},{"i":37,"n":"第三十七条","txt":"参与证券交易所集中交易的，必须是证券交易所的会员，非会员不得直接参与股票的集中交易。会员应当依据证券交易所相关业务规则，对客户证券交易行为进行管理。"},{"i":38,"n":"第三十八条","txt":"证券交易所应当实时公布即时行情，并按日制作证券市场行情表，记载并公布下列事项： （一）上市证券的名称； （二）开盘价、最高价、最低价、收盘价； （三）与前一交易日收盘价比较后的涨跌情况； （四）成交量、成交金额的分计及合计； （五）证券交易所市场基准指数及其涨跌情况； （六）中国证监会要求公布或者证券交易所认为需要公布的其他事项。 证券交易所即时行情的权益由证券交易所依法享有。证券交易所对市场交易形成的基础信息和加工产生的信息产品享有专属权利。未经证券交易所同意，任何单位和个人不得发布证券交易即时行情，不得以商业目的使用。经许可使用交易信息的机构和个人，未经证券交易所同意，不得将该信息提供给其他机构和个人使用。"},{"i":39,"n":"第三十九条","txt":"证券交易所应当就其市场内的成交情况编制日报表、周报表、月报表和年报表，并及时向市场公布。 证券交易所可以根据监管需要，对其市场内特定证券的成交情况进行分类统计，并向市场公布。"},{"i":40,"n":"第四十条","txt":"证券交易所应当保证投资者有平等机会获取证券市场的交易行情和其他公开披露的信息，并有平等的交易机会。"},{"i":41,"n":"第四十一条","txt":"因不可抗力、意外事件、重大技术故障、重大人为差错等突发性事件而影响证券交易正常进行时，为维护证券交易正常秩序和市场公平，证券交易所可以按照业务规则采取技术性停牌、临时停市等处置措施，并应当及时向中国证监会报告。 因前款规定的突发性事件导致证券交易结果出现重大异常，按交易结果进行交收将对证券交易正常秩序和市场公平造成重大影响的，证券交易所按照业务规则可以采取取消交易、通知证券登记结算机构暂缓交收等措施，并应当及时向中国证监会报告并公告。"},{"i":42,"n":"第四十二条","txt":"证券交易所对证券交易进行实时监控，及时发现和处理违反业务规则的异常交易行为。 证券交易所应当对可能误导投资者投资决策、可能对证券交易价格或证券交易量产生不当影响等异常交易行为进行重点监控。"},{"i":43,"n":"第四十三条","txt":"证券交易所应当按照维护市场交易秩序，保障市场稳定运行，保证投资者公平交易机会，防范和化解市场风险的原则，制定异常交易行为认定和处理的业务规则，并报中国证监会批准。"},{"i":44,"n":"第四十四条","txt":"对于严重影响证券交易秩序或者交易公平的异常交易行为，证券交易所可以按照业务规则实施限制投资者交易等措施，并向中国证监会报告。 证券交易所发现异常交易行为涉嫌违反法律、行政法规、部门规章的，应当及时向中国证监会报告。"},{"i":45,"n":"第四十五条","txt":"证券交易所应当加强对证券交易的风险监测。出现重大异常波动的，证券交易所可以按照业务规则采取限制交易、强制停牌等处置措施，并向中国证监会报告；严重影响证券市场稳定的，证券交易所可以按照业务规则采取临时停市等处置措施并公告。"},{"i":46,"n":"第四十六条","txt":"证券交易所应当妥善保存证券交易中产生的交易记录，并制定相应的保密管理措施。交易记录等重要文件的保存期不少于二十年。 证券交易所应当要求并督促会员妥善保存与证券交易有关的委托资料、交易记录、清算文件等，并建立相应的查询和保密制度。"},{"i":47,"n":"第四十七条","txt":"证券交易所应当建立符合证券市场监管和实时监控要求的技术系统，并设立负责证券市场监管工作的专门机构。 证券交易所应当保障交易系统、通信系统及相关信息技术系统的安全、稳定和持续运行。"},{"i":48,"n":"第四十八条","txt":"通过计算机程序自动生成或者下达交易指令进行程序化交易的，应当符合中国证监会的规定，并向证券交易所报告，不得影响证券交易所系统安全或者正常交易秩序。证券交易所应当制定业务规则，对程序化交易进行监管。"},{"i":49,"n":"第四十九条","txt":"证券交易所应当制定会员管理规则。其内容包括： （一）会员资格的取得和管理； （二）席位（如有）与交易单元管理； （三）与证券交易业务有关的会员合规管理及风险控制要求； （四）会员客户交易行为管理、适当性管理及投资者教育要求； （五）会员业务报告制度； （六）对会员的日常管理和监督检查； （七）对会员采取的收取惩罚性违约金、取消会员资格等自律监管措施和纪律处分； （八）其他需要在会员管理规则中规定的事项。"},{"i":50,"n":"第五十条","txt":"证券交易所接纳的会员应当是经批准设立并具有法人地位的境内证券经营机构。 境外证券经营机构设立的驻华代表处，经申请可以成为证券交易所的特别会员。 证券交易所的会员种类，会员资格及权利、义务由证券交易所章程和业务规则规定。"},{"i":51,"n":"第五十一条","txt":"证券交易所决定接纳或者开除会员应当在决定后的五个工作日内向中国证监会报告。"},{"i":52,"n":"第五十二条","txt":"证券交易所应当限定席位（如有）的数量。 会员可以通过购买或者受让的方式取得席位。经证券交易所同意，席位可以转让，但不得用于出租和质押。"},{"i":53,"n":"第五十三条","txt":"证券交易所应当对交易单元实施严格管理，设定、调整和限制会员参与证券交易的品种及方式。 会员参与证券交易的，应当向证券交易所申请设立交易单元。经证券交易所同意，会员将交易单元提供给他人使用的，会员应当对其进行管理。会员不得允许他人以其名义直接参与证券的集中交易。具体管理办法由证券交易所规定。"},{"i":54,"n":"第五十四条","txt":"证券交易所应当制定技术管理规范，明确会员交易系统接入证券交易所和运行管理等技术要求，督促会员按照技术要求规范运作，保障交易及相关系统的安全稳定。 证券交易所为了防范系统性风险，可以要求会员建立和实施相应的风险控制系统和监测模型。"},{"i":55,"n":"第五十五条","txt":"证券交易所应当按照章程、业务规则的规定，对会员遵守证券交易所章程和业务规则的情况进行检查，并将检查结果报告中国证监会。 证券交易所可以根据章程、业务规则要求会员提供与证券交易活动有关的业务报表、账册、交易记录和其他文件资料。"},{"i":56,"n":"第五十六条","txt":"证券交易所应当建立会员客户交易行为管理制度，要求会员了解客户并在协议中约定对委托交易指令的核查和对异常交易指令的拒绝等内容，指导和督促会员完善客户交易行为监控系统，并定期进行考核评价。 会员管理的客户出现严重异常交易行为或者在一定时期内多次出现异常交易行为的，证券交易所应当对会员客户交易行为管理情况进行现场或者非现场检查，并将检查结果报告中国证监会。 会员未按规定履行客户管理职责的，证券交易所可以采取自律监管措施或者纪律处分。"},{"i":57,"n":"第五十七条","txt":"证券交易所应当按照章程、业务规则对会员通过证券自营及资产管理等业务进行的证券交易实施监管。 证券交易所应当按照章程、业务规则要求会员报备其通过自营及资产管理账户开展产品业务创新的具体情况以及账户实际控制人的有关文件资料。"},{"i":58,"n":"第五十八条","txt":"证券交易所应当督促会员建立并执行客户适当性管理制度，要求会员向客户推荐产品或者服务时充分揭示风险，并不得向客户推荐与其风险承受能力不适应的产品或者服务。"},{"i":59,"n":"第五十九条","txt":"会员出现违法违规行为的，证券交易所可以按照章程、业务规则的规定采取暂停受理或者办理相关业务、限制交易权限、收取惩罚性违约金、取消会员资格等自律监管措施或者纪律处分。"},{"i":60,"n":"第六十条","txt":"证券交易所会员应当接受证券交易所的监管，并主动报告有关问题。"},{"i":61,"n":"第六十一条","txt":"证券交易所应当制定证券上市规则。其内容包括： （一）证券上市的条件、程序和披露要求； （二）信息披露的主体、内容及具体要求； （三）证券停牌、复牌的标准和程序； （四）终止上市、重新上市的条件和程序； （五）对违反上市规则行为的处理规定； （六）其他需要在上市规则中规定的事项。"},{"i":62,"n":"第六十二条","txt":"证券交易所应当与申请证券上市交易的公司订立上市协议，确定相互间的权利义务关系。上市协议的内容与格式应当符合法律、行政法规、部门规章的规定。 上市协议应当包括下列内容： （一）上市证券的品种、名称、代码、数量和上市时间； （二）上市费用的收取； （三）证券交易所对证券上市交易公司及相关主体进行自律管理的主要手段和方式，包括现场和非现场检查等内容； （四）违反上市协议的处理，包括惩罚性违约金等内容； （五）上市协议的终止情形； （六）争议解决方式； （七）证券交易所认为需要在上市协议中明确的其他内容。"},{"i":63,"n":"第六十三条","txt":"证券交易所应当依法建立上市保荐制度。 证券交易所应当监督保荐人及相关人员的业务行为，督促其切实履行法律、行政法规、部门规章以及业务规则中规定的相关职责。"},{"i":64,"n":"第六十四条","txt":"证券交易所按照章程、协议以及上市规则决定证券终止上市和重新上市。 证券交易所按照业务规则对出现终止上市情形的证券实施退市，督促证券上市交易公司充分揭示终止上市风险，并应当及时公告，报中国证监会备案。"},{"i":65,"n":"第六十五条","txt":"证券交易所应当按照章程、协议以及业务规则，督促证券上市交易公司及相关信息披露义务人依法披露上市公告书、定期报告、临时报告等信息披露文件。 证券交易所对信息披露文件进行审核，可以要求证券上市交易公司及相关信息披露义务人、上市保荐人、证券服务机构等作出补充说明并予以公布，发现问题应当按照有关规定及时处理，情节严重的，报告中国证监会。"},{"i":66,"n":"第六十六条","txt":"证券交易所应当依据业务规则和证券上市交易公司的申请，决定上市交易证券的停牌或者复牌。证券上市交易的公司不得滥用停牌或复牌损害投资者合法权益。 证券交易所为维护市场秩序可以根据业务规则拒绝证券上市交易公司的停复牌申请，或者决定证券强制停复牌。 中国证监会为维护市场秩序可以要求证券交易所对证券实施停复牌。"},{"i":67,"n":"第六十七条","txt":"证券交易所应当按照章程、协议以及业务规则，对上市公司控股股东、持股百分之五以上股东、其他相关股东以及董事、监事、高级管理人员等持有本公司股票的变动及信息披露情况进行监管。"},{"i":68,"n":"第六十八条","txt":"发行人、证券上市交易公司及相关信息披露义务人等出现违法违规行为的，证券交易所可以按照章程、协议以及业务规则的规定，采取通报批评、公开谴责、收取惩罚性违约金、向相关主管部门出具监管建议函等自律监管措施或者纪律处分。"},{"i":69,"n":"第六十九条","txt":"证券交易所应当比照本章的有关规定，对证券在本证券交易所发行或者交易的其他主体进行监管。"},{"i":70,"n":"第七十条","txt":"证券交易所不得以任何方式转让其依照本办法取得的设立及业务许可。"},{"i":71,"n":"第七十一条","txt":"证券交易所的理事、董事、监事、高级管理人员对其任职机构负有诚实信用的义务。 证券交易所的总经理离任时，应当按照有关规定接受离任审计。"},{"i":72,"n":"第七十二条","txt":"证券交易所的总经理、副总经理未经批准，不得在任何营利性组织、团体和机构以及公益性社会团体、基金会、高等院校和科研院所中兼职。会员制证券交易所的非会员理事和非会员监事、公司制证券交易所的董事和监事以及其他工作人员不得以任何形式在证券交易所会员公司兼职。"},{"i":73,"n":"第七十三条","txt":"证券交易所的理事、董事、监事、高级管理人员及其他工作人员不得以任何方式泄露或者利用内幕信息，不得以任何方式违规从证券交易所的会员、证券上市交易公司获取利益。"},{"i":74,"n":"第七十四条","txt":"证券交易所的理事、董事、监事、高级管理人员及其他工作人员在履行职责时，遇到与本人或者其亲属等有利害关系情形的，应当回避。具体回避事项由其章程、业务规则规定。"},{"i":75,"n":"第七十五条","txt":"证券交易所应当建立健全财务管理制度，收取的各种资金和费用应当严格按照规定用途使用，不得挪作他用。 证券交易所的各项收益安排应当以保证交易场所和设施安全运行为前提，合理设置利润留成项目，做好长期资金安排。 会员制证券交易所的收支结余不得分配给会员。"},{"i":76,"n":"第七十六条","txt":"证券交易所应当履行下列报告义务： （一）证券交易所经符合《证券法》规定的会计师事务所审计的年度财务报告，该报告应于每一财政年度终了后三个月内向中国证监会提交； （二）关于业务情况的季度和年度工作报告，应当分别于每一季度结束后十五日内和每一年度结束后三十日内向中国证监会报告； （三）法律、行政法规、部门规章及本办法其他条款中规定的报告事项； （四）中国证监会要求报告的其他事项。"},{"i":77,"n":"第七十七条","txt":"遇有重大事项，证券交易所应当随时向中国证监会报告。 前款所称重大事项包括： （一）发现证券交易所会员、证券上市交易公司、投资者和证券交易所工作人员存在或者可能存在严重违反法律、行政法规、部门规章的行为； （二）发现证券市场中存在产生严重违反法律、行政法规、部门规章行为的潜在风险； （三）证券市场中出现法律、行政法规、部门规章未作明确规定，但会对证券市场产生重大影响的事项； （四）执行法律、行政法规、部门规章过程中，需由证券交易所作出重大决策的事项； （五）证券交易所认为需要报告的其他事项； （六）中国证监会规定的其他事项。"},{"i":78,"n":"第七十八条","txt":"遇有以下事项之一的，证券交易所应当及时向中国证监会报告，同时抄报交易所所在地人民政府，并采取适当方式告知交易所会员和投资者： （一）发生影响证券交易所安全运转的情况； （二）因不可抗力、意外事件、重大技术故障、重大人为差错等突发性事件而影响证券交易正常进行时，证券交易所为维护证券交易正常秩序和市场公平采取技术性停牌、临时停市、取消交易或者通知证券登记结算机构暂缓交收等处理措施； （三）因重大异常波动，证券交易所为维护市场稳定，采取限制交易、强制停牌、临时停市等处置措施。"},{"i":79,"n":"第七十九条","txt":"中国证监会有权要求证券交易所提供证券市场信息、业务文件以及其他有关的数据、资料。"},{"i":80,"n":"第八十条","txt":"中国证监会有权要求证券交易所对其章程和业务规则进行修改。"},{"i":81,"n":"第八十一条","txt":"中国证监会有权对证券交易所业务规则制定与执行情况、自律管理职责的履行情况、信息技术系统建设维护情况以及财务和风险管理等制度的建立及执行情况进行评估和检查。 中国证监会开展前款所述评估和检查，可以采取要求证券交易所进行自查、要求证券交易所聘请中国证监会认可的专业机构进行核查、中国证监会组织现场核查等方式进行。"},{"i":82,"n":"第八十二条","txt":"中国证监会依法查处证券市场的违法违规行为时，证券交易所应当予以配合。"},{"i":83,"n":"第八十三条","txt":"证券交易所涉及诉讼或者证券交易所理事、董事、监事、高级管理人员因履行职责涉及诉讼或者依照法律、行政法规、部门规章应当受到解除职务的处分时，证券交易所应当及时向中国证监会报告。"},{"i":84,"n":"第八十四条","txt":"证券交易所违反本办法第八条的规定，从事未经中国证监会批准的其他业务的，由中国证监会责令限期改正；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":85,"n":"第八十五条","txt":"证券交易所违反本办法第十条的规定，上市新的证券交易品种或者对现有上市证券交易品种作出较大调整未制定修改业务规则或者未履行相关程序的，由中国证监会责令停止该交易品种的交易，并对有关负责人采取处理措施。"},{"i":86,"n":"第八十六条","txt":"证券交易所违反本办法第十条的规定，制定或者修改业务规则应当报中国证监会批准而未履行相关程序的，中国证监会有权要求证券交易所进行修改、暂停适用或者予以废止，并对有关负责人采取处理措施。"},{"i":87,"n":"第八十七条","txt":"证券交易所违反规定，允许非会员直接参与股票集中交易的，中国证监会依据《证券法》作出行政处罚。"},{"i":88,"n":"第八十八条","txt":"证券交易所违反本办法规定，在监管工作中不履行职责，或者不履行本办法规定的有关报告义务，中国证监会可以采取监管谈话、出具警示函、通报批评、责令限期改正等监管措施。"},{"i":89,"n":"第八十九条","txt":"证券交易所存在下列情况时，由中国证监会对有关高级管理人员视情节轻重分别给予警告、记过、记大过、撤职等行政处分，并责令证券交易所对有关的业务部门负责人给予纪律处分；造成严重后果的，由中国证监会按本办法第三十五条的规定处理；构成犯罪的，由司法机关依法追究有关责任人员的刑事责任： （一）对国家有关法律、法规、规章、政策和中国证监会颁布的制度、办法、规定不传达、不执行； （二）对工作不负责任，管理混乱，致使有关业务制度和操作规程不健全、不落实； （三）对中国证监会的监督检查工作不接受、不配合，对工作中发现的重大隐患、漏洞不重视、不报告、不及时解决； （四）对在证券交易所内发生的违规行为未能及时采取有效措施予以制止或者查处不力。"},{"i":90,"n":"第九十条","txt":"证券交易所的任何工作人员有责任拒绝执行任何人员向其下达的违反法律、行政法规、部门规章和证券交易所有关规定的工作任务，并有责任向其更高一级领导和中国证监会报告具体情况。没有拒绝执行上述工作任务，或者虽拒绝执行但没有报告的，应当承担相应责任。"},{"i":91,"n":"第九十一条","txt":"证券交易所会员、证券上市交易公司违反法律、行政法规、部门规章和证券交易所章程、业务规则的规定，并且证券交易所没有履行规定的监管责任的，中国证监会有权按照本办法的有关规定，追究证券交易所和证券交易所有关理事、董事、监事、高级管理人员和直接责任人的责任。"},{"i":92,"n":"第九十二条","txt":"证券交易所应当在其职责范围内，及时向中国证监会报告其会员、证券上市交易公司及其他人员违反法律、行政法规、部门规章的情况；按照证券交易所章程、业务规则等证券交易所可以采取自律监管措施和纪律处分的，证券交易所有权按照有关规定予以处理，并报中国证监会备案；法律、行政法规、部门规章规定由中国证监会处罚的，证券交易所可以向中国证监会提出处罚建议。 中国证监会可以要求证券交易所按照业务规则对其会员、证券上市交易公司等采取自律监管措施或者纪律处分。"},{"i":93,"n":"第九十三条","txt":"证券交易所、证券交易所会员、证券上市交易公司违反本办法规定，直接责任人以及与直接责任人有直接利益关系者因此而形成非法获利或者避损的，由中国证监会依法予以行政处罚。"},{"i":94,"n":"第九十四条","txt":"本办法由中国证监会负责解释。"},{"i":95,"n":"第九十五条","txt":"本办法自公布之日起施行。2017年11月17日中国证监会公布的《证券交易所管理办法》同时废止。"}],"zhengquangongsihezhengquantouzijijinguanligongsihedc2686":[{"i":1,"n":"第一条","txt":"为了促进证券公司和证券投资基金管理公司加强内部合规管理，实现持续规范发展，根据《中华人民共和国公司法》《中华人民共和国证券法》《中华人民共和国证券投资基金法》和《证券公司监督管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立的证券公司和证券投资基金管理公司（以下统称证券基金经营机构）应当按照本办法实施合规管理。 本办法所称合规，是指证券基金经营机构及其工作人员的经营管理和执业行为符合法律、法规、规章及规范性文件、行业规范和自律规则、公司内部规章制度，以及行业普遍遵守的职业道德和行为准则（以下统称法律法规和准则）。 本办法所称合规管理，是指证券基金经营机构制定和执行合规管理制度，建立合规管理机制，防范合规风险的行为。 本办法所称合规风险，是指因证券基金经营机构或其工作人员的经营管理或执业行为违反法律法规和准则而使证券基金经营机构被依法追究法律责任、采取监管措施、给予纪律处分、出现财产损失或商业信誉损失的风险。"},{"i":3,"n":"第三条","txt":"证券基金经营机构的合规管理应当覆盖所有业务，各部门、各分支机构、各层级子公司和全体工作人员，贯穿决策、执行、监督、反馈等各个环节。"},{"i":4,"n":"第四条","txt":"证券基金经营机构应当树立全员合规、合规从管理层做起、合规创造价值、合规是公司生存基础的理念，倡导和推进合规文化建设，培育全体工作人员合规意识，提升合规管理人员职业荣誉感和专业化、职业化水平。"},{"i":5,"n":"第五条","txt":"中国证券监督管理委员会（以下简称中国证监会）依法对证券基金经营机构合规管理工作实施监督管理。中国证监会派出机构按照授权履行监督管理职责。 中国证券业协会、中国证券投资基金业协会等自律组织（以下简称协会）依照本办法制定实施细则，对证券基金经营机构合规管理工作实施自律管理。"},{"i":6,"n":"第六条","txt":"证券基金经营机构开展各项业务，应当合规经营、勤勉尽责，坚持客户利益至上原则，并遵守下列基本要求： （一）充分了解客户的基本信息、财务状况、投资经验、投资目标、风险偏好、诚信记录等信息并及时更新。 （二）合理划分客户类别和产品、服务风险等级，确保将适当的产品、服务提供给适合的客户，不得欺诈客户。 （三）持续督促客户规范证券发行行为，动态监控客户交易活动，及时报告、依法处置重大异常行为，不得为客户违规从事证券发行、交易活动提供便利。 （四）严格规范工作人员执业行为，督促工作人员勤勉尽责，防范其利用职务便利从事违法违规、超越权限或者其他损害客户合法权益的行为。 （五）有效管理内幕信息和未公开信息，防范公司及其工作人员利用该信息买卖证券、建议他人买卖证券，或者泄露该信息。 （六）及时识别、妥善处理公司与客户之间、不同客户之间、公司不同业务之间的利益冲突，切实维护客户利益，公平对待客户。 （七）"},{"i":7,"n":"第七条","txt":"证券基金经营机构董事会决定本公司的合规管理目标，对合规管理的有效性承担责任，履行下列合规管理职责： （一）审议批准合规管理的基本制度； （二）审议批准年度合规报告； （三）决定解聘对发生重大合规风险负有主要责任或者领导责任的高级管理人员； （四）决定聘任、解聘、考核合规负责人，决定其薪酬待遇； （五）建立与合规负责人的直接沟通机制； （六）评估合规管理有效性，督促解决合规管理中存在的问题； （七）公司章程规定的其他合规管理职责。"},{"i":8,"n":"第八条","txt":"证券基金经营机构的监事会或者监事履行下列合规管理职责： （一）对董事、高级管理人员履行合规管理职责的情况进行监督； （二）对发生重大合规风险负有主要责任或者领导责任的董事、高级管理人员提出罢免的建议； （三）公司章程规定的其他合规管理职责。"},{"i":9,"n":"第九条","txt":"证券基金经营机构的高级管理人员负责落实合规管理目标，对合规运营承担责任，履行下列合规管理职责： （一）建立健全合规管理组织架构，遵守合规管理程序，配备充足、适当的合规管理人员，并为其履行职责提供充分的人力、物力、财力、技术支持和保障； （二）发现违法违规行为及时报告、整改，落实责任追究； （三）公司章程规定或者董事会确定的其他合规管理职责。"},{"i":10,"n":"第十条","txt":"证券基金经营机构各部门、各分支机构和各层级子公司（以下统称下属各单位）负责人负责落实本单位的合规管理目标，对本单位合规运营承担责任。 证券基金经营机构全体工作人员应当遵守与其执业行为有关的法律、法规和准则，主动识别、控制其执业行为的合规风险，并对其执业行为的合规性承担责任。 下属各单位及工作人员发现违法违规行为或者合规风险隐患时，应当主动及时向合规负责人报告。"},{"i":11,"n":"第十一条","txt":"证券基金经营机构设合规负责人。合规负责人是高级管理人员，直接向董事会负责，对本公司及其工作人员的经营管理和执业行为的合规性进行审查、监督和检查。 合规负责人不得兼任与合规管理职责相冲突的职务，不得负责管理与合规管理职责相冲突的部门。 证券基金经营机构的章程应当对合规负责人的职责、任免条件和程序等作出规定。"},{"i":12,"n":"第十二条","txt":"证券基金经营机构合规负责人应当组织拟定合规管理的基本制度和其他合规管理制度，督导下属各单位实施。 合规管理的基本制度应当明确合规管理的目标、基本原则、机构设置及其职责，违法违规行为及合规风险隐患的报告、处理和责任追究等内容。 法律法规和准则发生变动的，合规负责人应当及时建议董事会或高级管理人员并督导有关部门，评估其对合规管理的影响，修改、完善有关制度和业务流程。"},{"i":13,"n":"第十三条","txt":"合规负责人应当对证券基金经营机构内部规章制度、重大决策、新产品和新业务方案等进行合规审查，并出具书面合规审查意见。 中国证监会及其派出机构、自律组织要求对证券基金经营机构报送的申请材料或报告进行合规审查的，合规负责人应当审查，并在该申请材料或报告上签署合规审查意见。其他相关高级管理人员等人员应当对申请材料或报告中基本事实和业务数据的真实性、准确性及完整性负责。 证券基金经营机构不采纳合规负责人的合规审查意见的，应当将有关事项提交董事会决定。"},{"i":14,"n":"第十四条","txt":"合规负责人应当按照中国证监会及其派出机构的要求和公司规定，对证券基金经营机构及其工作人员经营管理和执业行为的合规性进行监督检查。 合规负责人应当协助董事会和高级管理人员建立和执行信息隔离墙、利益冲突管理和反洗钱制度，按照公司规定为高级管理人员、下属各单位提供合规咨询、组织合规培训，指导和督促公司有关部门处理涉及公司和工作人员违法违规行为的投诉和举报。"},{"i":15,"n":"第十五条","txt":"合规负责人应当按照公司规定，向董事会、经营管理主要负责人报告证券基金经营机构经营管理合法合规情况和合规管理工作开展情况。 合规负责人发现证券基金经营机构存在违法违规行为或合规风险隐患的，应当依照公司章程规定及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改。合规负责人应当同时督促公司及时向中国证监会相关派出机构报告；公司未及时报告的，应当直接向中国证监会相关派出机构报告；有关行为违反行业规范和自律规则的，还应当向有关自律组织报告。"},{"i":16,"n":"第十六条","txt":"合规负责人应当及时处理中国证监会及其派出机构和自律组织要求调查的事项，配合中国证监会及其派出机构和自律组织对证券基金经营机构的检查和调查，跟踪和评估监管意见和监管要求的落实情况。"},{"i":17,"n":"第十七条","txt":"合规负责人应当将出具的合规审查意见、提供的合规咨询意见、签署的公司文件、合规检查工作底稿等与履行职责有关的文件、资料存档备查，并对履行职责的情况作出记录。"},{"i":18,"n":"第十八条","txt":"合规负责人应当通晓相关法律法规和准则，诚实守信，熟悉证券、基金业务，具有胜任合规管理工作需要的专业知识和技能，并具备下列任职条件： （一）从事证券、基金工作10年以上，并且通过中国证券业协会或中国证券投资基金业协会组织的合规管理人员胜任能力考试；或者从事证券、基金工作5年以上，并且通过法律职业资格考试；或者在证券监管机构、证券基金业自律组织任职5年以上； （二）最近3年未被金融监管机构实施行政处罚或采取重大行政监管措施； （三）中国证监会规定的其他条件。"},{"i":19,"n":"第十九条","txt":"证券基金经营机构聘任合规负责人，应当向中国证监会相关派出机构报送人员简历及有关证明材料。证券公司合规负责人应当经中国证监会相关派出机构认可后方可任职。 合规负责人任期届满前，证券基金经营机构解聘的，应当有正当理由，并在有关董事会会议召开10个工作日前将解聘理由书面报告中国证监会相关派出机构。 前款所称正当理由，包括合规负责人本人申请，或被中国证监会及其派出机构责令更换，或确有证据证明其无法正常履职、未能勤勉尽责等情形。"},{"i":20,"n":"第二十条","txt":"合规负责人不能履行职务或缺位时，应当由证券基金经营机构董事长或经营管理主要负责人代行其职务，并自决定之日起3个工作日内向中国证监会相关派出机构书面报告，代行职务的时间不得超过6个月。 合规负责人提出辞职的，应当提前1个月向公司董事会提出申请，并向中国证监会相关派出机构报告。在辞职申请获得批准之前，合规负责人不得自行停止履行职责。 合规负责人缺位的，公司应当在6个月内聘请符合本办法第十八条规定的人员担任合规负责人。"},{"i":21,"n":"第二十一条","txt":"证券基金经营机构应当设立合规部门。合规部门对合规负责人负责，按照公司规定和合规负责人的安排履行合规管理职责。合规部门不得承担与合规管理相冲突的其他职责。 证券基金经营机构应当明确合规部门与其他内部控制部门之间的职责分工，建立内部控制部门协调互动的工作机制。"},{"i":22,"n":"第二十二条","txt":"证券基金经营机构应当为合规部门配备足够的、具备与履行合规管理职责相适应的专业知识和技能的合规管理人员。合规部门中具备3年以上证券、金融、法律、会计、信息技术等有关领域工作经历的合规管理人员数量不得低于公司总部人数的一定比例，具体比例由协会规定。"},{"i":23,"n":"第二十三条","txt":"证券基金经营机构各业务部门、各分支机构应当配备符合本办法第二十二条规定的合规管理人员。 合规管理人员可以兼任与合规管理职责不相冲突的职务。合规风险管控难度较大的部门和分支机构应当配备专职合规管理人员。"},{"i":24,"n":"第二十四条","txt":"证券基金经营机构应当将各层级子公司的合规管理纳入统一体系，明确子公司向母公司报告的合规管理事项，对子公司的合规管理制度进行审查，对子公司经营管理行为的合规性进行监督和检查，确保子公司合规管理工作符合母公司的要求。 从事另类投资、私募基金管理、基金销售等活动的子公司，应当由证券基金经营机构选派人员作为子公司高级管理人员负责合规管理工作，并由合规负责人考核和管理。"},{"i":25,"n":"第二十五条","txt":"证券基金经营机构应当保障合规负责人和合规管理人员充分履行职责所需的知情权和调查权。 证券基金经营机构召开董事会会议、经营决策会议等重要会议以及合规负责人要求参加或者列席的会议的，应当提前通知合规负责人。合规负责人有权根据履职需要参加或列席有关会议，查阅、复制有关文件、资料。 合规负责人根据履行职责需要，有权要求证券基金经营机构有关人员对相关事项作出说明，向为公司提供审计、法律等中介服务的机构了解情况。 合规负责人认为必要时，可以证券基金经营机构名义直接聘请外部专业机构或人员协助其工作，费用由公司承担。"},{"i":26,"n":"第二十六条","txt":"证券基金经营机构应当保障合规负责人和合规管理人员的独立性。 证券基金经营机构的股东、董事和高级管理人员不得违反规定的职责和程序，直接向合规负责人下达指令或者干涉其工作。 证券基金经营机构的董事、监事、高级管理人员和下属各单位应当支持和配合合规负责人、合规部门及本单位合规管理人员的工作，不得以任何理由限制、阻挠合规负责人、合规部门和合规管理人员履行职责。"},{"i":27,"n":"第二十七条","txt":"合规部门及专职合规管理人员由合规负责人考核。对兼职合规管理人员进行考核时，合规负责人所占权重应当超过50%。证券基金经营机构应当制定合规负责人、合规部门及专职合规管理人员的考核管理制度，不得采取其他部门评价、以业务部门的经营业绩为依据等不利于合规独立性的考核方式。 证券基金经营机构董事会对合规负责人进行年度考核时，应当就其履行职责情况及考核意见书面征求中国证监会相关派出机构的意见，中国证监会相关派出机构可以根据掌握的情况建议董事会调整考核结果。 证券基金经营机构对高级管理人员和下属各单位的考核应当包括合规负责人对其合规管理有效性、经营管理和执业行为合规性的专项考核内容。合规性专项考核占总考核结果的比例不得低于协会的规定。"},{"i":28,"n":"第二十八条","txt":"证券基金经营机构应当制定合规负责人与合规管理人员的薪酬管理制度。合规负责人工作称职的，其年度薪酬收入总额在公司高级管理人员年度薪酬收入总额中的排名不得低于中位数；合规管理人员工作称职的，其年度薪酬收入总额不得低于公司同级别人员的平均水平。"},{"i":29,"n":"第二十九条","txt":"中国证监会及其派出机构和自律组织支持证券基金经营机构合规负责人依法开展工作，组织行业合规培训和交流，并督促证券基金经营机构为合规负责人提供充足的履职保障。"},{"i":30,"n":"第三十条","txt":"证券基金经营机构应当在报送年度报告的同时向中国证监会相关派出机构报送年度合规报告。年度合规报告包括下列内容： （一）证券基金经营机构和各层级子公司合规管理的基本情况； （二）合规负责人履行职责情况； （三）违法违规行为、合规风险隐患的发现及整改情况； （四）合规管理有效性的评估及整改情况； （五）中国证监会及其派出机构要求或证券基金经营机构认为需要报告的其他内容。 证券基金经营机构的董事、高级管理人员应当对年度合规报告签署确认意见，保证报告的内容真实、准确、完整；对报告内容有异议的，应当注明意见和理由。"},{"i":31,"n":"第三十一条","txt":"证券基金经营机构应当组织内部有关机构和部门或者委托具有专业资质的外部专业机构对公司合规管理的有效性进行评估，及时解决合规管理中存在的问题。对合规管理有效性的全面评估，每年不得少于1次。委托具有专业资质的外部专业机构进行的全面评估，每3年至少进行1次。 中国证监会及其派出机构发现证券基金经营机构存在违法违规行为或重大合规风险隐患的，可以要求证券基金经营机构委托指定的具有专业资质的外部专业机构对公司合规管理的有效性进行评估，并督促其整改。"},{"i":32,"n":"第三十二条","txt":"证券基金经营机构违反本办法规定的，中国证监会可以采取出具警示函、责令定期报告、责令改正、监管谈话等行政监管措施；对直接负责的董事、监事、高级管理人员和其他责任人员，可以采取出具警示函、责令参加培训、责令改正、监管谈话、认定为不适当人选等行政监管措施。 证券基金经营机构违反本办法规定导致公司出现治理结构不健全、内部控制不完善等情形的，对证券基金经营机构及其直接负责的董事、监事、高级管理人员和其他直接责任人员，依照《中华人民共和国证券投资基金法》第二十四条、《证券公司监督管理条例》第七十条采取行政监管措施。"},{"i":33,"n":"第三十三条","txt":"合规负责人违反本办法规定的，中国证监会可以采取出具警示函、责令参加培训、责令改正、监管谈话、认定为不适当人选等行政监管措施。"},{"i":34,"n":"第三十四条","txt":"证券基金经营机构的董事、监事、高级管理人员未能勤勉尽责，致使公司存在重大违法违规行为或者重大合规风险的，依照《中华人民共和国证券法》第一百四十条、第一百四十二条、《中华人民共和国证券投资基金法》第二十五条采取行政监管措施。"},{"i":35,"n":"第三十五条","txt":"证券基金经营机构违反本办法第十八条、第十九条、第二十条、第二十一条、第二十二条、第二十三条、第二十四条、第二十五条、第二十六条、第二十七条、第二十八条规定，情节严重的，对证券基金经营机构及其直接负责的董事、监事、高级管理人员和其他直接责任人员，处以警告、3万元以下罚款。 合规负责人未按照本办法第十五条第二款的规定及时向中国证监会相关派出机构报告重大违法违规行为的，处以警告、3万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"证券基金经营机构通过有效的合规管理，主动发现违法违规行为或合规风险隐患，积极妥善处理，落实责任追究，完善内部控制制度和业务流程并及时向中国证监会或其派出机构报告的，依法从轻、减轻处理；情节轻微并及时纠正违法违规行为或避免合规风险，没有造成危害后果的，不予追究责任。 对于证券基金经营机构的违法违规行为，合规负责人已经按照本办法的规定尽职履行审查、监督、检查和报告职责的，不予追究责任。"},{"i":37,"n":"第三十七条","txt":"本办法下列用语的含义： （一）合规负责人，包括证券公司的合规总监和证券投资基金管理公司的督察长。 （二）中国证监会相关派出机构，包括证券公司住所地的中国证监会派出机构，和证券投资基金管理公司住所地或者经营所在地的中国证监会派出机构。"},{"i":38,"n":"第三十八条","txt":"中国证监会根据审慎监管的原则，可以提高对行业重要性证券基金经营机构的合规管理要求，并可以采取增加现场检查频率、强化合规负责人任职监管、委托外部专业机构协助开展工作等方式加强合规监管。 前款所称行业重要性证券基金经营机构，是指中国证监会认定的，公司内部经营活动可能导致证券基金行业、证券市场产生重大风险的证券基金经营机构。"},{"i":39,"n":"第三十九条","txt":"开展公开募集证券投资基金管理业务的保险资产管理机构、私募资产管理机构等，参照本办法执行。"},{"i":40,"n":"第四十条","txt":"本办法自2017年10月1日起施行。《证券投资基金管理公司督察长管理规定》（证监基金字〔2006〕85号）、《证券公司合规管理试行规定》（证监会公告〔2008〕30号）同时废止。"}],"zhengquangongsihezhengquantouzijijinguanligongsiji2b23b3":[{"i":1,"n":"第一条","txt":"为了规范证券公司、证券投资基金管理公司（以下统称证券基金经营机构）在境外设立、收购子公司或者参股经营机构的行为，根据《中华人民共和国证券法》《中华人民共和国证券投资基金法》《证券公司监督管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"证券基金经营机构在境外设立、收购子公司或者参股经营机构，适用本办法。 境外子公司和参股经营机构在境外的注册登记、变更、终止以及开展业务活动等事项，应当遵守所在国家或者地区的法律法规和监管要求。"},{"i":3,"n":"第三条","txt":"证券基金经营机构在境外设立、收购子公司或者参股经营机构，应当对境外市场状况、法律法规、监管环境等进行必要的调查研究，综合考虑自身财务状况、公司治理情况、内部控制和风险管理水平、对子公司的管理和控制能力、发展规划等因素，全面评估论证，合理审慎决策。"},{"i":4,"n":"第四条","txt":"证券基金经营机构在境外设立、收购子公司或者参股经营机构，不得从事危害中华人民共和国主权、安全和社会公共利益的行为，不得违反反洗钱等相关法律法规的规定。"},{"i":5,"n":"第五条","txt":"境外子公司、参股经营机构依照属地监管原则由境外监督管理机构监管。中国证券监督管理委员会（以下简称中国证监会）与境外监督管理机构建立跨境监督管理合作机制，加强监管信息交流和执法合作，督促证券基金经营机构依法履行对境外子公司、参股经营机构的管理职责。"},{"i":6,"n":"第六条","txt":"证券基金经营机构应当按照国家外汇管理部门和中国证监会的相关规定，建立完备的外汇资产负债风险管理系统，依法办理外汇资金进出相关手续。"},{"i":7,"n":"第七条","txt":"证券公司在境外设立、收购子公司或者参股经营机构，应当向中国证监会备案；证券投资基金管理公司在境外设立、收购子公司或者参股经营机构，应当经中国证监会批准。"},{"i":8,"n":"第八条","txt":"证券基金经营机构在境外设立、收购子公司或者参股经营机构开展业务活动，应当与其治理结构、内部控制、合规管理、风险管理以及风险控制指标、从业人员构成等情况相适应，符合审慎监管和保护投资者合法权益的要求。存在下列情形之一的，不得在境外设立、收购子公司或者参股经营机构： （一）最近3年因重大违法违规行为受到行政或刑事处罚，最近1年被采取重大监管措施或因风险控制指标不符合规定被采取监管措施，因涉嫌重大违法违规行为正在被立案调查或者正处于整改期间； （二）拟设立、收购子公司和参股经营机构所在国家或者地区未建立完善的证券法律和监管制度，或者该国家或者地区相关金融监管机构未与中国证监会或者中国证监会认可的机构签定监管合作谅解备忘录，并保持有效的监管合作关系； （三）中国证监会规定的其他情形。 证券投资基金管理公司在境外设立、收购子公司或者参股经营机构的，净资产应当不低于6亿元，持续经营应当原则上满2年"},{"i":9,"n":"第九条","txt":"证券基金经营机构设立境外子公司的，应当财务状况及资产质量良好，具备对子公司的出资能力且全资设立，中国证监会认可的除外。"},{"i":10,"n":"第十条","txt":"证券投资基金管理公司在境外设立、收购子公司或者参股经营机构，应当向中国证监会提交下列申请材料： （一）法定代表人签署的申请报告； （二）在境外设立、收购子公司或者参股经营机构的相关决议文件； （三）拟设立、收购子公司或者参股经营机构的章程（草案）； （四）符合在境外设立、收购子公司和参股经营机构条件的说明； （五）与境外子公司、参股经营机构之间防范风险传递、利益冲突和利益输送的相关措施安排及说明； （六）能够对境外子公司和参股经营机构有效管理的说明，内容应当包括对现有境内子公司的风险管理和内部控制安排及实施效果，拟对境外子公司的管控安排，拟对境外参股经营机构相关表决权的实施机制等； （七）在境外设立、收购子公司或者参股经营机构的协议（如适用）； （八）可行性研究报告，内容至少包括：在境外设立、收购子公司或者参股经营机构的必要性及可行性，外汇资金来源的说明，境外子公司或者参股经营机构的名"},{"i":11,"n":"第十一条","txt":"境外子公司或者参股经营机构应当从事证券、期货、资产管理或者中国证监会认可的其他金融业务，以及金融业务中间介绍、金融信息服务、金融信息技术系统服务、为特定金融业务及产品提供后台支持服务等中国证监会认可的金融相关业务，不得从事与金融无关的业务。"},{"i":12,"n":"第十二条","txt":"境外子公司应当具有简明、清晰、可穿透的股权架构，法人层级应当与境外子公司资本规模、经营管理能力和风险管控水平相适应。 境外子公司可以设立专业孙公司开展金融业务和金融相关业务。除确有需要外，上述孙公司不得再设立机构。 境外子公司再设立、收购、参股经营机构，应当按照国家有关规定履行相关的审批或者备案手续。"},{"i":13,"n":"第十三条","txt":"境外子公司不得直接或者间接在境内从事经营性活动，为境外子公司提供后台支持或者辅助等中国证监会认可的活动除外。 境外子公司在境内设立机构，从事后台支持或者辅助等中国证监会认可活动的，证券基金经营机构应当报中国证监会备案。"},{"i":14,"n":"第十四条","txt":"证券基金经营机构应当充分履行股东职责，依法参与境外子公司的法人治理，健全对境外子公司的风险管控，形成权责明确、流程清晰、制衡有效的管理机制。"},{"i":15,"n":"第十五条","txt":"证券基金经营机构应当指派分管境外机构的高级管理人员作为股东代表出席股东（大）会。股东代表因故不能出席时，应当书面授权证券基金经营机构相关部门负责人代为出席。"},{"i":16,"n":"第十六条","txt":"证券基金经营机构在境外设立、收购子公司，应当确保对子公司董事会具有影响力。仅设执行董事的，执行董事应当由证券基金经营机构提名。证券基金经营机构应当履行内部程序确定提名人选，所提名的董事应当符合以下条件： （一）熟悉中国证监会及境外机构所在地相关法律法规和业务规范，具备良好的职业操守，最近3年无相关违法违规记录； （二）具备5年以上证券、基金等金融领域的工作经历； （三）具备履行职责所必需的时间和精力； （四）中国证监会规定的其他条件。"},{"i":17,"n":"第十七条","txt":"证券基金经营机构应当通过股东提案等方式，在境外子公司章程中明确下列事项由境外子公司股东会审议： （一）决定经营方针和投资计划，决定年度财务预算方案、决算方案； （二）选举和更换董事； （三）变更业务范围、股权或注册资本，修改章程； （四）合并、分立、解散或者清算； （五）购买、出售资产或者投资、借贷、关联交易、担保等的金额达到或超过净资产的10%； （六）设立、收购、参股经营机构； （七）其他应当由股东会审议的事项。"},{"i":18,"n":"第十八条","txt":"证券基金经营机构应当通过股东提案等方式，在境外子公司章程中明确下列事项由境外子公司董事会审议： （一）购买、出售资产或者投资、借贷、关联交易、担保等的金额超过净资产的5%但不足10%，且不低于500万元人民币； （二）内部管理机构的设置； （三）聘任或者解聘境外子公司经营管理负责人、合规管理负责人、风险管理负责人、财务负责人等经营管理层人员，决定上述人员的考核结果和薪酬； （四）涉及合规管理、内部控制、风险防范的重大事项； （五）其他应当由董事会审议的事项。"},{"i":19,"n":"第十九条","txt":"股东代表和提名的董事应当在收到相关会议议案后，及时向证券基金经营机构报告，并提交议案事项涉及的相关材料。 涉及本办法第十七条、第十八条股东会和董事会审议事项的相关议案，证券基金经营机构应当按照公司章程，提交证券基金经营机构股东会、董事会或者经营决策机构集体讨论，合规负责人应当进行合规审查，出具书面合规审查意见。集体决策的意见应当反馈给其委派的股东代表和提名的董事贯彻落实。"},{"i":20,"n":"第二十条","txt":"证券基金经营机构应当采取有效措施，建立决策事项落实跟踪制度及决策效果评估制度，督促其委派的股东代表和提名的董事根据证券基金经营机构的意见履行职责，事后及时评估决策效果，不断改进提升决策质量。"},{"i":21,"n":"第二十一条","txt":"证券基金经营机构应当建立境外机构、股东代表及所提名董事等相关人员的重大事项报告机制，明确报告的事项范围、时间要求和报告路径，确保证券基金经营机构能够及时知悉并处理境外机构经营管理等重大事项，有效防范、评估和化解风险。"},{"i":22,"n":"第二十二条","txt":"证券基金经营机构应当建立健全对境外子公司的内部稽核和外部审计制度，完善对境外子公司的财务稽核、业务稽核、风险控制监督等，检查和评估境外子公司内部控制的有效性、财务运营的稳健性等。外部审计每年不少于一次，内部稽核定期进行。"},{"i":23,"n":"第二十三条","txt":"证券基金经营机构应当建立与境外子公司、参股经营机构之间有效的信息隔离和风险隔离制度，控制内幕信息和未公开信息等敏感信息的不当流动和使用，有效防范风险传递和利益输送。"},{"i":24,"n":"第二十四条","txt":"证券基金经营机构应当加强与境外子公司之间交易的管理，发生此类交易的，证券基金经营机构应当履行必要的内部程序并在公司年度报告以及监察稽核报告中说明；依照法律法规应当对外信息披露的，应当严格履行信息披露义务。 证券基金经营机构应当通过股东提案等方式，明确境外子公司、参股经营机构的关联交易管理制度，对关联交易行为认定标准、交易定价方法、交易审批程序等进行规范，保证关联交易决策的独立性，严格防范非公平关联交易风险。"},{"i":25,"n":"第二十五条","txt":"证券基金经营机构应当通过股东提案等方式，在境外子公司章程中明确境外子公司高级管理人员应当符合以下条件： （一）熟悉相关法律法规和业务规范，最近3年无相关违法违规记录； （二）具备5年以上证券、基金等金融领域的工作经历和履行职责所必需的经营管理能力； （三）中国证监会规定的其他条件。 证券基金经营机构的董事、监事、高级管理人员等在境外子公司、参股经营机构兼职的，应当遵守境内外相关规定，不得兼任与现有职责相冲突的职务。证券基金经营机构应当参照境内证券基金行业人员离任审计或离任审查的相关管理规定，对境外子公司的董事、高级管理人员和重要岗位人员开展离任审计或离任审查。"},{"i":26,"n":"第二十六条","txt":"证券基金经营机构应当建立健全境外子公司激励约束机制，督促境外子公司完善绩效年薪制度。激励机制应当合理、均衡、有效，达到鼓励合规、稳健经营、长期有效的目的，不得过度激励、短期激励。 证券基金经营机构应当建立健全履职评价和责任追究机制，对损害境外子公司、参股经营机构合法权益，导致境外子公司、参股经营机构出现经营风险或者违法违规问题的人员依法追究责任。"},{"i":27,"n":"第二十七条","txt":"证券基金经营机构应当建立并持续完善覆盖境外机构的合规管理、风险管理和内部控制体系。 证券基金经营机构应当要求境外子公司的合规负责人和风险管理负责人每年度结束后30个工作日内，向证券基金经营机构报送年度合规专报和风险测评专报。证券基金经营机构的合规负责人、风险管理负责人应当对上述专报进行审查，并签署审查意见。"},{"i":28,"n":"第二十八条","txt":"证券基金经营机构对境外子公司增资，或者依法为境外子公司提供融资、担保以及其他类似增信措施的，应当履行内部的决策程序，并在作出决议之日起5个工作日内向中国证监会备案；依法为境外子公司出具不具有实质性担保义务的安慰函以及其他类似文件的，应当于出具文件的次月前5个工作日内向中国证监会备案。"},{"i":29,"n":"第二十九条","txt":"证券基金经营机构在境外参股经营机构的，应当依法参与经营管理，充分行使股东权利，积极履行股东义务。"},{"i":30,"n":"第三十条","txt":"证券基金经营机构应当在每月前10个工作日内，通过中国证监会有关监管信息平台报送上一月度境外子公司的主要财务数据及业务情况。 证券基金经营机构应当在每年4月底之前通过中国证监会有关监管信息平台报送上一年度境外机构经审计的财务报告、审计报告以及年度工作报告，年度工作报告的内容包括但不限于：持牌情况、获得交易所等会员资格情况、业务开展情况、财务状况、法人治理情况、岗位设置和人员配备情况、下属机构情况、配合调查情况、被境外监管机构采取监管措施或者处罚情况等。 中国证监会派出机构应当每月对辖区内证券基金经营机构报送的境外机构有关文件进行分析，并在每季度结束后15个工作日内，向中国证监会报告辖区内证券基金经营机构境外机构的经营管理、内控合规和风险管理等情况。"},{"i":31,"n":"第三十一条","txt":"证券基金经营机构境外子公司发生下列事项的，证券基金经营机构应当在5个工作日内向中国证监会及相关派出机构书面报告： （一）注册登记、取得业务资格、经营非持牌业务； （二）作出变更名称、股权或注册资本，修改章程重要条款，分立、合并或者解散等的决议； （三）取得、变更或者注销交易所等会员资格； （四）变更董事长、总经理、合规负责人和风险管理负责人； （五）机构或其从业人员受到境外监管机构或交易所的现场检查、调查、纪律处分或处罚； （六）预计发生重大亏损、遭受超过净资产10%的重大损失以及公司财务状况发生其他重大不利变化； （七）与证券基金经营机构及其关联方发生重大关联交易； （八）按规定应当向境外监管机构报告的重大事项。"},{"i":32,"n":"第三十二条","txt":"证券基金经营机构在境外设立、收购子公司或者参股经营机构，以及对境外子公司和参股经营机构的管理，违反法律、行政法规和本办法规定的，中国证监会及相关派出机构可以对证券基金经营机构采取出具警示函、责令定期报告、责令改正、监管谈话等行政监管措施；对直接负责的董事、监事、高级管理人员和其他责任人员，可以采取出具警示函、责令改正、监管谈话、认定为不适当人选等行政监管措施。"},{"i":33,"n":"第三十三条","txt":"证券基金经营机构因治理结构不健全、内部控制不完善，未按本办法履行对境外机构的管理和控制职责，导致境外机构违法违规经营或者出现重大风险的，对证券基金经营机构及其直接负责的董事、监事、高级管理人员和其他直接责任人员，依照《中华人民共和国证券投资基金法》第二十四条、《证券公司监督管理条例》第七十条采取行政监管措施。"},{"i":34,"n":"第三十四条","txt":"证券基金经营机构违反本办法规定，依法应予处罚的，对证券基金经营机构及其直接负责的主管人员和其他直接责任人员，按照相关法律法规的规定进行处罚。相关法律法规没有规定的，处以警告、3万元以下罚款。涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"本办法所称收购，指通过购买境外已设立机构股权等方式控制该机构。"},{"i":36,"n":"第三十六条","txt":"境外子公司、参股经营机构所在地法律法规以及关于上市公司的相关监管政策和自律规则对其外资比例、章程内容、法人治理等方面的规定与本办法存在不一致的，从其规定。"},{"i":37,"n":"第三十七条","txt":"本办法施行前，证券基金经营机构已经获准设立、收购子公司或者参股经营机构的，应当在本办法施行后36个月内，逐步规范，达到本办法的相关要求。逾期未达到要求的，中国证监会及相关派出机构依法采取行政监管措施。其中，对于已经存在的股权架构不符合要求的，证券基金经营机构应当降低组织架构复杂程度，简化法人层级，并报中国证监会备案认可。 证券基金经营机构不得在境外经营放债或类似业务。已经开展上述业务的，自本办法施行之日起，不得新增上述业务，存量业务到期终结。"},{"i":38,"n":"第三十八条","txt":"本办法自公布之日起施行。中国证监会发布的《关于证券投资基金管理公司在香港设立机构的规定》（证监会公告〔2008〕12号）同时废止。"}],"zhengquangongsiguquanguanliguiding":[{"i":1,"n":"第一条","txt":"为加强证券公司股权管理，保护证券公司股东、客户及其他利益相关者的合法权益，促进证券公司持续健康发展，根据《中华人民共和国公司法》《中华人民共和国证券法》（以下简称《证券法》）《证券公司监督管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国境内依法设立的证券公司。"},{"i":3,"n":"第三条","txt":"证券公司股权管理应当遵循分类管理、资质优良、权责明确、结构清晰、变更有序、公开透明的原则。"},{"i":4,"n":"第四条","txt":"证券公司股东应当遵守法律法规、中国证券监督管理委员会（以下简称中国证监会）规定和公司章程，秉承长期投资理念，依法行使股东权利，履行股东义务。 证券公司应当加强对股权事务的管理，完善公司治理结构，健全风险管理与内部控制制度。 中国证监会及其派出机构遵循审慎监管原则，依法对证券公司股权实施穿透式监管和分类监管。"},{"i":5,"n":"第五条","txt":"根据持股比例和对证券公司经营管理的影响，证券公司股东包括以下三类： （一）控股股东，指持有证券公司50%以上股权的股东或者虽然持股比例不足50%，但其所享有的表决权足以对证券公司股东（大）会的决议产生重大影响的股东； （二）主要股东，指持有证券公司5%以上股权的股东； （三）持有证券公司5%以下股权的股东。"},{"i":6,"n":"第六条","txt":"证券公司设立时，中国证监会依照规定核准其注册资本及股权结构。 证券公司变更主要股东或者公司的实际控制人，应当依法报中国证监会核准。 证券公司的控股股东、实际控制人实际控制证券公司的股权比例增至100%的，证券公司应当在公司登记机关办理变更登记之日起（依法不需办理公司变更登记的，自相关确权登记之日起）5个工作日内，向中国证监会备案。 证券公司变更注册资本、股权或者5%以上股权的实际控制人，不涉及本条第二、三款所列情形的，应当在公司登记机关办理变更登记之日起（依法不需办理公司变更登记的，自相关确权登记之日起）5个工作日内，向公司住所地中国证监会派出机构备案。证券公司公开发行股份或者在证券交易所、全国中小企业股份转让系统（以下简称股份转让系统）发生的股权变更，不适用本款规定。"},{"i":7,"n":"第七条","txt":"持有证券公司5%以下股权的股东，应当符合下列要求： （一）自身及所控制的机构信誉良好，最近3年无重大违法违规记录或重大不良诚信记录；不存在因故意犯罪被判处刑罚、刑罚执行完毕未逾3年的情形；没有因涉嫌重大违法违规正在被调查或处于整改期间； （二）不存在长期未实际开展业务、停业、破产清算、治理结构缺失、内部控制失效等影响履行股东权利和义务的情形；不存在可能严重影响持续经营的担保、诉讼、仲裁或者其他重大事项； （三）不存在股权结构不清晰，无法逐层穿透至最终权益持有人的情形；股权结构中原则不允许存在理财产品，中国证监会认可的情形除外； （四）自身及所控制的机构不存在因不诚信或者不合规行为引发社会重大质疑或产生严重社会负面影响且影响尚未消除的情形；不存在对所投资企业经营失败负有重大责任且经营失败未逾3年的情形； （五）中国证监会基于审慎监管原则规定的其他要求。 通过证券交易所、股份转让系统交易或"},{"i":8,"n":"第八条","txt":"证券公司的主要股东，应当符合下列条件： （一）本规定第七条规定的要求； （二）财务状况良好，资产负债和杠杆水平适度，净资产不低于5000万元人民币，具备与证券公司经营业务相匹配的持续资本补充能力； （三）公司治理规范，管理能力达标，风险管控良好； （四）不存在净资产低于实收资本50%、或有负债达到净资产50%或者不能清偿到期债务的情形； （五）能够为提升证券公司的综合竞争力提供支持。"},{"i":9,"n":"第九条","txt":"证券公司的第一大股东、控股股东，应当符合下列条件： （一）本规定第八条规定的条件； （二）开展金融相关业务经验与证券公司业务范围相匹配； （三）入股证券公司与其长期战略协调一致，有利于服务其主营业务发展； （四）对完善证券公司治理结构、推动证券公司长期发展有切实可行的计划安排； （五）对保持证券公司经营管理的独立性和防范风险传递、不当利益输送，有明确的自我约束机制； （六）对证券公司可能发生风险导致无法正常经营的情况，制定合理有效的风险处置预案。"},{"i":10,"n":"第十条","txt":"证券公司从事的业务具有显著杠杆性质，且多项业务之间存在交叉风险的，其第一大股东、控股股东还应当符合下列条件： （一）最近3年持续盈利，不存在未弥补亏损； （二）最近3年长期信用均保持在高水平，最近3年规模、收入、利润、市场占有率等指标居于行业前列。 控股股东还应当符合下列条件： （一）总资产不低于500亿元人民币，净资产不低于200亿元人民币； （二）核心主业突出，主营业务最近5年持续盈利。 证券公司合并或者因重大风险被接管托管等中国证监会认可的特殊情形不适用本条规定。"},{"i":11,"n":"第十一条","txt":"具有关联关系或者一致行动人关系的股东持有证券公司的股权比例应当合并计算；其中持股比例最高的股东或者在关联关系、一致行动人关系中居于控制、主导地位的股东应当符合合计持股比例对应类别的股东条件。 股东入股证券公司后，因证券公司股权结构调整导致股东类别变化的，应当符合变更后对应类别的股东条件。"},{"i":12,"n":"第十二条","txt":"证券公司5%以上股权的实际控制人，应当符合本规定第七条、第八条第（四）项规定的要求。证券公司的实际控制人及第一大股东的控股股东、实际控制人，还应当符合本规定第九条第（四）至（六）项规定的要求。"},{"i":13,"n":"第十三条","txt":"有限合伙企业入股证券公司的，还应当符合下列要求： （一）单个有限合伙企业控制证券公司的股权比例不得达到5%，中国证监会认可的情形除外。两个以上有限合伙企业的执行事务合伙人或者第一大有限合伙人相同或者存在其他关联关系、一致行动人关系的，持股比例合并计算。 （二）负责执行有限合伙企业事务的普通合伙人以及第一大有限合伙人应当符合本规定第七条的要求，有限合伙企业通过证券交易所、股份转让系统交易或者认购证券公司公开发行股份入股证券公司的情形除外。"},{"i":14,"n":"第十四条","txt":"公司制基金入股证券公司且委托基金管理人管理证券公司股权的，该基金应当属于政府实际控制的产业投资基金且已经国家有关部门备案登记，并参照适用本规定第十三条的规定。"},{"i":15,"n":"第十五条","txt":"非金融企业入股证券公司的，还应当符合下列要求： （一）符合国家关于加强非金融企业投资金融机构监管的有关指导意见; （二）单个非金融企业实际控制证券公司股权的比例原则上不得超过50%，为处置证券公司风险等中国证监会认可的情形除外。"},{"i":16,"n":"第十六条","txt":"证券公司董事会办公室是证券公司股权管理事务的办事机构，组织实施股权管理事务相关工作。 证券公司董事长是证券公司股权管理事务的第一责任人。证券公司董事会秘书协助董事长工作，是证券公司股权管理事务的直接责任人。"},{"i":17,"n":"第十七条","txt":"证券公司变更注册资本或者股权，应当制定工作方案和股东筛选标准等。证券公司、股权转让方应当事先向意向参与方告知证券公司股东条件、须履行的程序并向符合股东筛选标准的意向参与方告知证券公司的经营情况和潜在风险等信息。 证券公司、股权转让方应当对意向参与方做好尽职调查，约定意向参与方不符合条件的后续处理措施。发现不符合条件的，不得与其签订协议。相关事项须经中国证监会核准的，应当约定核准后协议方可生效。"},{"i":18,"n":"第十八条","txt":"证券公司变更注册资本或者股权过程中，对于可能出现的违反规定或者承诺的行为，证券公司应当与相关主体事先约定处理措施，明确对责任人的责任追究机制，并配合监管机构调查处理。"},{"i":19,"n":"第十九条","txt":"证券公司应当对变更注册资本或者股权期间的风险防范作出安排，保证公司正常经营以及客户利益不受损害。 依法须经中国证监会核准的，在核准前，证券公司股东应当按照所持股权比例继续独立行使表决权，股权转让方不得推荐股权受让方相关人员担任证券公司董事、监事、高级管理人员，不得以任何形式变相让渡表决权。"},{"i":20,"n":"第二十条","txt":"证券公司股东应当充分了解证券公司股东条件以及股东权利和义务，充分知悉证券公司经营管理状况和潜在风险等信息，投资预期合理，出资意愿真实，并且履行必要的内部决策程序。 不得签订在未来证券公司不符合特定条件时，由证券公司或者其他指定主体向特定股东赎回、受让股权等具有“对赌”性质的协议或者形成相关安排。"},{"i":21,"n":"第二十一条","txt":"证券公司股东应当严格按照法律法规和中国证监会规定履行出资义务。 证券公司股东应当使用自有资金入股证券公司，资金来源合法，不得以委托资金等非自有资金入股，法律法规和中国证监会认可的情形除外。"},{"i":22,"n":"第二十二条","txt":"证券公司股东应当真实、准确、完整地说明股权结构直至实际控制人、最终权益持有人，以及与其他股东的关联关系或者一致行动人关系，不得通过隐瞒、欺骗等方式规避证券公司股东资格审批或者监管。"},{"i":23,"n":"第二十三条","txt":"证券公司股东以及股东的控股股东、实际控制人参股证券公司的数量不得超过2家，其中控制证券公司的数量不得超过1家。下列情形不计入参股、控制证券公司的数量范围： （一）直接持有及间接控制证券公司股权比例低于5%； （二）通过所控制的证券公司入股其他证券公司； （三）证券公司控股其他证券公司； （四）为实施证券公司并购重组所做的过渡期安排； （五）国务院授权持有证券公司股权； （六）中国证监会认定的其他情形。"},{"i":24,"n":"第二十四条","txt":"证券公司应当保持股权结构稳定。证券公司股东的持股期限应当符合法律、行政法规和中国证监会的有关规定，证券公司股东通过换股等方式取得其他证券公司股权的，持股时间可连续计算。 证券公司股东的主要资产为证券公司股权的，该股东的控股股东、实际控制人对所控制的证券公司股权应当遵守与证券公司股东相同的锁定期，中国证监会依法认可的情形除外。"},{"i":25,"n":"第二十五条","txt":"证券公司股东在股权锁定期内不得质押所持证券公司股权。股权锁定期满后，证券公司股东质押所持证券公司的股权比例不得超过所持该证券公司股权比例的50%。 股东质押所持证券公司股权的，不得损害其他股东和证券公司的利益，不得约定由质权人或其他第三方行使表决权等股东权利，也不得变相转移证券公司股权的控制权。 上市证券公司以及在股份转让系统挂牌的证券公司持有5%以下股权的股东不适用本条第一款规定。"},{"i":26,"n":"第二十六条","txt":"证券公司应当加强对股东资质的审查，对股东及其控股股东、实际控制人、关联方、一致行动人、最终权益持有人信息进行核实并掌握其变动情况，就股东对证券公司经营管理的影响进行判断，依法及时、准确、完整地报告或披露相关信息，必要时履行报批或者备案程序。"},{"i":27,"n":"第二十七条","txt":"证券公司应当将股东的权利义务、股权锁定期、股权管理事务责任人等关于股权管理的监管要求写入公司章程，并在公司章程中载明下列内容： （一）主要股东、控股股东应当在必要时向证券公司补充资本； （二）应经但未经监管部门核准或未向监管部门备案的股东，或者尚未完成整改的股东，不得行使股东（大）会召开请求权、表决权、提名权、提案权、处分权等权利； （三）存在虚假陈述、滥用股东权利或其他损害证券公司利益行为的股东，不得行使股东（大）会召开请求权、表决权、提名权、提案权、处分权等权利； （四）发生违反法律、行政法规和监管要求等与股权管理事务相关的不法或不当行为，对股东、证券公司、股权管理事务责任人及相关人员的处理措施。"},{"i":28,"n":"第二十八条","txt":"证券公司应当加强关联交易管理，准确识别关联方，严格落实关联交易审批制度和信息披露制度，避免损害证券公司及其客户的合法权益，并及时向中国证监会及其派出机构报告关联交易情况。 证券公司应当按照穿透原则将股东及其控股股东、实际控制人、关联方、一致行动人、最终权益持有人作为自身的关联方进行管理。 本条第二款规定的股东不含上市证券公司以及在股份转让系统挂牌的证券公司持有5%以下股权的股东。"},{"i":29,"n":"第二十九条","txt":"证券公司股东及其控股股东、实际控制人不得有下列行为： （一）对证券公司虚假出资、出资不实、抽逃出资或者变相抽逃出资； （二）违反法律、行政法规和公司章程的规定干预证券公司的经营管理活动； （三）滥用权利或影响力，占用证券公司或者客户的资产，进行利益输送，损害证券公司、其他股东或者客户的合法权益； （四）违规要求证券公司为其或其关联方提供融资或者担保，或者强令、指使、协助、接受证券公司以其证券经纪客户或者证券资产管理客户的资产提供融资或者担保； （五）与证券公司进行不当关联交易，利用对证券公司经营管理的影响力获取不正当利益； （六）未经批准，委托他人或接受他人委托持有或管理证券公司股权，变相接受或让渡证券公司股权的控制权； （七）中国证监会禁止的其他行为。 证券公司及其董事、监事、高级管理人员等相关主体不得配合证券公司的股东及其控股股东、实际控制人发生上述情形。 证券公司发现股东及其控股"},{"i":30,"n":"第三十条","txt":"未履行法定核准程序，证券公司擅自变更股权相关事项的，中国证监会或其派出机构依照《证券法》第二百零四条的规定处理。"},{"i":31,"n":"第三十一条","txt":"任何单位或者个人持有或者实际控制证券公司相关股权不符合本规定的，中国证监会或其派出机构依照《证券公司监督管理条例》第七十一条的规定处理。 任何单位或者个人未经批准，委托他人或者接受他人委托持有或者管理证券公司的股权，或者认购、受让或者实际控制证券公司的股权的，中国证监会或其派出机构依照《证券公司监督管理条例》第八十六条的规定处理。"},{"i":32,"n":"第三十二条","txt":"证券公司的股东有虚假出资、出资不实、抽逃出资或者变相抽逃出资的，中国证监会或其派出机构依照《证券法》第一百四十一条的规定处理。"},{"i":33,"n":"第三十三条","txt":"在行政许可过程中，相关主体隐瞒有关情况或者提供虚假材料的，中国证监会或其派出机构依照《行政许可法》第七十八条的规定处理。 相关主体以隐瞒、欺骗等不正当手段获得证券公司股权相关行政许可批复的，中国证监会或其派出机构依照《行政许可法》第六十九条、第七十九条的规定处理。"},{"i":34,"n":"第三十四条","txt":"证券公司或其主要股东、实际控制人违反规定，未按规定报告有关事项，或者报送的信息有虚假记载、误导性陈述或者重大遗漏的，中国证监会或其派出机构依照《证券法》第二百一十一条的规定处理。"},{"i":35,"n":"第三十五条","txt":"证券公司违规为其股东或者股东的关联人提供融资或者担保的，中国证监会或其派出机构依照《证券法》第二百零五条的规定处理。 证券公司的股东、实际控制人强令、指使、协助、接受证券公司以证券经纪客户或者证券资产管理客户的资产提供融资或者担保的，中国证监会或其派出机构依照《证券公司监督管理条例》第八十六条的规定处理。"},{"i":36,"n":"第三十六条","txt":"证券公司及其股东、股东的实际控制人或其他相关主体违反本规定，致使证券公司治理结构不健全、内部控制不完善、经营管理混乱、违法违规的，中国证监会或其派出机构依照《证券公司监督管理条例》第七十条的规定处理；致使证券公司的治理结构、合规管理、风险控制指标不符合规定，严重危及证券公司稳健运行、损害客户合法权益的，依照《证券法》第一百四十条的规定处理；致使证券公司违法经营或者出现重大风险，严重危害证券市场秩序、损害投资者利益的，依照《证券法》第一百四十三条的规定处理。 证券公司的董事、监事、高级管理人员违反本规定，致使证券公司存在重大违法违规行为或重大风险的，中国证监会或其派出机构依照《证券法》第一百四十二条的规定处理。"},{"i":37,"n":"第三十七条","txt":"证券公司及其股东、股东的实际控制人或其他相关主体违反本规定，《证券法》《证券公司监督管理条例》等法律、行政法规没有规定相应处理措施或罚则的，中国证监会或其派出机构可以采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告等监管措施；对直接负责的董事、监事、高级管理人员和其他责任人员，可以采取责令改正、监管谈话、出具警示函、认定为不适当人选等监管措施；并可以视情节对相关主体处以警告、3万元以下罚款；涉嫌犯罪的，依法移送司法机关。"},{"i":38,"n":"第三十八条","txt":"中国证监会及其派出机构应当将证券公司及其董事、监事、高级管理人员，股东及其控股股东、实际控制人、相关中介机构等相关机构和人员的失信行为按照中国证监会诚信监督管理相关规定记入资本市场诚信档案数据库，通过全国信用信息共享平台与其他政府机构共享信息。"},{"i":39,"n":"第三十九条","txt":"证券公司未遵守本规定进行股权管理的，中国证监会可以调整该证券公司分类监管评价类别。"},{"i":40,"n":"第四十条","txt":"本规定所称“以上”“不低于”包括本数，“以下”“超过”不包括本数。"},{"i":41,"n":"第四十一条","txt":"证券公司变更主要股东，指证券公司新增主要股东，或者证券公司第一大股东、控股股东发生变化。 证券公司变更5%以上股权的实际控制人，指证券公司新增持有5%以上股权的实际控制人，或者证券公司的实际控制人发生变化。"},{"i":42,"n":"第四十二条","txt":"本规定所称证券公司第一大股东，指持有证券公司5%以上股权的第一大股东。"},{"i":43,"n":"第四十三条","txt":"国家对证券公司国有股权行政划转另有规定的，相关要求从其规定。 入股证券公司涉及金融业综合经营、国有资产或者其他金融监管部门职责的，应当符合国家关于金融业综合经营相关政策、国有资产管理和其他金融监管部门的相关规定。 外商投资证券公司的股东，还应当符合中国证监会关于外商投资证券公司管理的相关规定。"},{"i":44,"n":"第四十四条","txt":"投资者通过证券交易所购买证券公司股份使其累计持有的证券公司股份达到5%的，应当依法举牌并报中国证监会核准。获得核准前，投资者不得继续增持该公司股份。中国证监会不予核准的，投资者应当在自不予核准之日起50个交易日（不含停牌时间，持股不足6个月的，应当自持股满6个月后）内依法改正。 投资者通过股份转让系统购买证券公司股份使其累计持有的证券公司股份达到5%以上的，参照适用第一款规定。 投资者认购证券公司公开发行股份或者通过证券交易所、股份转让系统转让证券公司股份，且所涉认购或股权变更事项不需审批或备案的，豁免本规定第十七条、第十八条规定的要求。"},{"i":45,"n":"第四十五条","txt":"本规定自公布之日起施行。本规定施行前，中国证监会有关证券公司股权管理的规定与本规定不一致的，按照本规定执行。"}],"zhengquangongsidongshijianshihegaojiguanlirenyuanr180e2b":[{"i":1,"n":"第一条","txt":"为了规范证券公司董事、监事、高级管理人员和分支机构负责人任职资格监管，提高董事、监事、高级管理人员和分支机构负责人的专业素质，保障证券公司依法合规经营，根据《公司法》、《证券法》、《行政许可法》、《证券公司监督管理条例》等法律、行政法规的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"证券公司董事、监事、高级管理人员和分支机构负责人的任职资格监管适用本办法。 本办法所称证券公司高级管理人员（以下简称高管人员），是指证券公司的总经理、副总经理、财务负责人、合规负责人、董事会秘书以及实际履行上述职务的人员。 证券公司行使经营管理职责的管理委员会、执行委员会以及类似机构的成员为高管人员。"},{"i":3,"n":"第三条","txt":"证券公司董事、监事、高管人员和分支机构负责人应当在任职前取得中国证券监督管理委员会（以下简称中国证监会）核准的任职资格。 证券公司不得聘任未取得任职资格的人员担任董事、监事、高管人员和分支机构负责人，不得违反规定授权不具备任职资格的人员实际行使职责。"},{"i":4,"n":"第四条","txt":"证券公司董事、监事、高管人员和分支机构负责人应当遵守法律、行政法规和中国证监会的规章、规范性文件，遵守公司章程和行业规范，恪守诚信，勤勉尽责。"},{"i":5,"n":"第五条","txt":"中国证监会依法对证券公司董事、监事、高管人员和分支机构负责人进行监督管理。 证券公司董事、监事、高管人员和分支机构负责人的任职资格由中国证监会授权中国证监会派出机构（以下简称派出机构）依法核准。"},{"i":6,"n":"第六条","txt":"中国证券业协会、证券交易所依法对证券公司董事、监事、高管人员和分支机构负责人进行自律管理。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，不得担任证券公司董事、监事、高管人员和分支机构负责人： （一）《证券法》第一百三十一条第二款、第一百三十二条、第一百三十三条规定的情形； （二）因重大违法违规行为受到金融监管部门的行政处罚，执行期满未逾3年； （三）自被中国证监会撤销任职资格之日起未逾3年； （四）自被中国证监会认定为不适当人选之日起未逾2年； （五）中国证监会认定的其他情形。"},{"i":8,"n":"第八条","txt":"取得证券公司董事、监事、高管人员和分支机构负责人任职资格，应当具备以下基本条件： （一）正直诚实，品行良好； （二）熟悉证券法律、行政法规、规章以及其他规范性文件，具备履行职责所必需的经营管理能力。"},{"i":9,"n":"第九条","txt":"取得董事、监事任职资格，除应当具备本办法第八条规定的基本条件外，还应当具备以下条件： （一）从事证券、金融、法律、会计工作3年以上或者经济工作5年以上； （二）具有大专以上学历。"},{"i":10,"n":"第十条","txt":"取得独立董事任职资格，除应当具备本办法第八条规定的基本条件外，还应当具备以下条件： （一）从事证券、金融、法律、会计工作5年以上； （二）具有大学本科以上学历，并且具有学士以上学位； （三）有履行职责所必需的时间和精力。"},{"i":11,"n":"第十一条","txt":"独立董事不得与证券公司存在关联关系、利益冲突或者存在其他可能妨碍独立客观判断的情形。 下列人员不得担任证券公司独立董事： （一）在证券公司或其关联方任职的人员及其近亲属和主要社会关系人员； （二）在下列机构任职的人员及其近亲属和主要社会关系人员：持有或控制证券公司5%以上股权的单位、证券公司前5名股东单位、与证券公司存在业务联系或利益关系的机构； （三）持有或控制上市证券公司1%以上股权的自然人，上市证券公司前10名股东中的自然人股东，或者控制证券公司5%以上股权的自然人，及其上述人员的近亲属； （四）为证券公司及其关联方提供财务、法律、咨询等服务的人员及其近亲属； （五）最近1年内曾经具有前四项所列举情形之一的人员； （六）在其他证券公司担任除独立董事以外职务的人员； （七）中国证监会认定的其他人员。"},{"i":12,"n":"第十二条","txt":"取得董事长、副董事长和监事会主席任职资格，除应当具备本办法第八条规定的基本条件外，还应当具备以下条件： （一）从事证券工作3年以上，或者金融、法律、会计工作5年以上，或者经济工作10年以上； （二）具有大学本科以上学历或取得学士以上学位； （三）通过中国证监会认可的资质测试。"},{"i":13,"n":"第十三条","txt":"取得总经理、副总经理、财务负责人、合规负责人、董事会秘书，以及证券公司管理委员会、执行委员会和类似机构的成员（以下简称经理层人员）任职资格，除应当具备本办法第八条规定的基本条件外，还应当具备以下条件： （一）从事证券工作3年以上，或者金融、法律、会计工作5年以上； （二）具有证券从业资格； （三）具有大学本科以上学历或取得学士以上学位； （四）曾担任证券机构部门负责人以上职务不少于2年，或者曾担任金融机构部门负责人以上职务不少于4年，或者具有相当职位管理工作经历； （五）通过中国证监会认可的资质测试。"},{"i":14,"n":"第十四条","txt":"取得分支机构负责人任职资格，除应当具备本办法第八条规定的基本条件外，还应当具备以下条件： （一）从事证券工作3年以上或经济工作5年以上； （二）具有证券从业资格； （三）具有大学本科以上学历或取得学士以上学位。"},{"i":15,"n":"第十五条","txt":"证券公司法定代表人应当具有证券从业资格。"},{"i":16,"n":"第十六条","txt":"证券公司董事、监事以及其他人员行使高管人员职责的，应当取得高管人员的任职资格。"},{"i":17,"n":"第十七条","txt":"从事证券工作10年以上或曾担任金融机构部门负责人以上职务8年以上的人员，申请证券公司董事长、副董事长、独立董事、监事会主席、高管人员和分支机构负责人的任职资格的，学历要求可以放宽至大专。"},{"i":18,"n":"第十八条","txt":"具有证券、金融、经济管理、法律、会计、投资类专业硕士研究生以上学历的人员，申请证券公司董事、监事、高管人员和分支机构负责人任职资格的，从事证券、金融、经济、法律、会计工作的年限可以适当放宽。"},{"i":19,"n":"第十九条","txt":"在证券监管机构、自律机构以及其他承担证券监管职能的专业监管岗位任职8年以上的人员，申请高管人员和分支机构负责人的任职资格，可以豁免证券从业资格的要求。"},{"i":20,"n":"第二十条","txt":"申请董事长、副董事长、监事会主席任职资格的，应当由拟任职的证券公司向证券公司注册地派出机构提出申请，申请经理层人员任职资格应当由本人向其住所地派出机构或由拟任职的证券公司向公司注册地派出机构提出申请，并提交以下材料： （一）申请表； （二）2名推荐人的书面推荐意见； （三）身份、学历、学位证明文件； （四）资质测试合格证明； （五）最近3年曾任职单位鉴定意见； （六）最近3年担任单位主要负责人的，应提交离任审计报告； （七）最近3年内在金融机构任职且被纳入监管范围的，应提交监管部门的监管意见； （八）中国证监会要求提交的其他材料。 申请经理层人员任职资格的，还应当提交证券从业资格证书。"},{"i":21,"n":"第二十一条","txt":"推荐人应当是任职1年以上的证券公司现任董事长、副董事长、监事会主席或经理层人员。 申请人或拟任人不具有证券行业工作经历的，其推荐人中可有1名是其原任职单位的负责人。申请人或拟任人为境外人士的，推荐人中至少有1名为符合本办法规定的人员，另1名可以为申请人或拟任人曾任职的境外证券类机构的高管人员。 推荐人应当对申请人或拟任人是否存在本办法第七条所列举的情形作出说明，并对其个人品行、遵纪守法、从业经历、业务水平、管理能力等发表明确的推荐意见。 推荐人每个自然年度最多只能推荐3人申请证券公司董事长、副董事长、监事会主席或经理层人员的任职资格。"},{"i":22,"n":"第二十二条","txt":"申请除董事长、副董事长、监事会主席以外董事、监事的任职资格，应当由拟任职的证券公司向公司注册地派出机构提出申请，并提交以下材料： （一）申请表； （二）证券公司或股东单位的推荐意见； （三）身份、学历、学位证明文件； （四）最近3年内曾任职单位的鉴定意见； （五）中国证监会要求提交的其他材料。"},{"i":23,"n":"第二十三条","txt":"股东单位推荐的前条所述董事、监事人选，由股东单位出具推荐意见；独立董事人选以及作为职工代表的董事、监事，应当由证券公司出具推荐意见。推荐意见至少包括以下内容： （一）拟任人是否存在本办法第七条所列举的情形； （二）拟任人遵守证券法律、行政法规、中国证监会有关规定以及自律组织规则的情况； （三）拟任人的职业道德水准和诚信表现； （四）拟任人的管理能力和业务能力； （五）拟任人是否有足够的时间和精力履行职责。"},{"i":24,"n":"第二十四条","txt":"申请独立董事任职资格，还应当提供拟任人具有5年以上证券、金融、法律或者会计工作经历的证明，以及拟任人关于独立性的声明。声明应重点说明其本人是否存在本办法第十一条所列举的情形。"},{"i":25,"n":"第二十五条","txt":"已经取得董事长、副董事长、监事会主席任职资格的人员，自离开原任职公司之日起12个月内到其他证券公司担任董事长、副董事长、监事会主席，且未出现本办法第七条规定情形的，拟任职公司应当向公司注册地派出机构提交以下申请材料： （一）申请表； （二）原任职公司的离任审计报告； （三）中国证监会要求的其他材料。"},{"i":26,"n":"第二十六条","txt":"申请分支机构负责人任职资格的，应当由拟任职的证券公司向分支机构所在地派出机构提出申请，并提交以下材料： （一）申请表； （二）证券公司的推荐意见； （三）身份、学历、学位、证券从业资格的证明文件； （四）最近3年曾任职单位的鉴定意见； （五）最近3年内曾在金融机构任职且被纳入监管范围的，应提交监管部门的监管意见； （六）中国证监会要求提交的其他材料。"},{"i":27,"n":"第二十七条","txt":"申请人提交学历、学位证明文件复印件的，应当加盖颁发单位或出具单位的公章，或出具公证机关的公证文书或律师的认证文件，以证明复印件与原件一致；提交国外和中国香港、澳门特别行政区及台湾地区大学或高等教育机构学位证书或高等教育文凭，或者非学历教育文凭的，应当同时提交国务院教育行政部门对其所获教育文凭的学历学位认证文件。"},{"i":28,"n":"第二十八条","txt":"申请人提交的最近3年曾任职单位的鉴定意见，应当详细说明申请人或拟任人在曾任职单位的职责范围、履职情况以及是否受到纪律处分等情况。"},{"i":29,"n":"第二十九条","txt":"派出机构根据《行政许可法》第三十二条和中国证监会行政许可实施程序的有关规定，对申请人提出的任职资格申请作出处理。"},{"i":30,"n":"第三十条","txt":"派出机构认为有必要时，可以对申请人或拟任人进行考察、谈话。"},{"i":31,"n":"第三十一条","txt":"申请人或拟任人有下列情形之一的，派出机构可以作出终止审查的决定： （一）申请人或拟任人死亡或者丧失行为能力的； （二）申请人依法终止的； （三）申请人主动要求撤回申请材料的； （四）申请人未在规定期限内针对反馈意见作出进一步说明、解释的； （五）申请人或拟任人因涉嫌违法违规行为被行政机关立案调查的； （六）申请人被依法采取停业整顿、托管、接管、限制业务等监管措施的； （七）申请人或拟任人因涉嫌犯罪被司法机关立案侦查的； （八）中国证监会认定的其他情形。"},{"i":32,"n":"第三十二条","txt":"派出机构应当在规定期限内对证券公司董事、监事、高管人员和分支机构负责人的任职资格申请作出是否核准的决定。不予核准的，应当说明理由。"},{"i":33,"n":"第三十三条","txt":"证券公司应当自拟任董事、监事取得任职资格之日起30日内，按照公司章程等有关规定办理上述人员的任职手续。自取得任职资格之日起30日内，上述人员未在证券公司任职或履行相关职务的，除有正当理由并经相关派出机构认可的，其任职资格自动失效。"},{"i":34,"n":"第三十四条","txt":"证券公司任免董事、监事、高管人员和分支机构负责人的，应当自作出决定之日起5日内，将有关人员的变动情况以及高管人员的职责范围在公司公告，并向相关派出机构报告，提交以下材料： （一）任职、免职决定文件； （二）相关会议的决议； （三）相关人员的任职资格核准文件； （四）相关人员签署的诚信经营承诺书； （五）高管人员职责范围的说明； （六）中国证监会规定的其他材料。 证券公司未按要求履行公告、报告义务的，相关人员应当在2日内向相关派出机构报告。"},{"i":35,"n":"第三十五条","txt":"证券公司任免董事、监事、高管人员和分支机构负责人的，中国证监会及相关派出机构可以对有关人员进行任职谈话。证券公司选任的董事、监事、高管人员和分支机构负责人不符合规定的条件的，中国证监会及相关派出机构应当责令证券公司限期更换人员。"},{"i":36,"n":"第三十六条","txt":"内资证券公司境外人士担任经理层人员职务的比例最多可以达到公司该类人员总数的30%；外资参股证券公司境外人士担任经理层人员职务的比例最多可以达到公司该类人员总数的50%。"},{"i":37,"n":"第三十七条","txt":"证券公司高管人员和分支机构负责人最多可以在证券公司参股的2家公司兼任董事、监事，但不得在上述公司兼任董事、监事以外的职务，不得在其他营利性机构兼职或者从事其他经营性活动。 证券公司高管人员在证券公司全资或控股子公司兼职的，不受上述限制，但应当遵守中国证监会有关规定。 证券公司分支机构负责人不得兼任其他同类分支机构负责人。 任何人员最多可以在2家证券公司担任独立董事。 证券公司董事、监事、高管人员和分支机构负责人兼职的，应自有关情况发生之日起5日内向相关派出机构报告。"},{"i":38,"n":"第三十八条","txt":"取得经理层人员任职资格的人员，担任除独立董事之外的其他职务，不需重新申请任职资格，由拟任职的证券公司按照规定依法办理其任职手续。 取得分支机构负责人任职资格的人员，改任同一公司其他分支机构负责人或者其他公司分支机构负责人的，不需重新申请任职资格，由拟任职的证券公司按照规定依法办理其任职手续。"},{"i":39,"n":"第三十九条","txt":"证券公司董事、监事离任的，其任职资格自离任之日起自动失效。 有以下情形的，不受前款规定限制： （一）证券公司董事（不包括独立董事）、监事在同一公司相互改任； （二）证券公司董事长、副董事长、监事会主席，在同一公司改任除独立董事之外的其他董事、监事。"},{"i":40,"n":"第四十条","txt":"证券公司变更法定代表人、主要负责人及分支机构负责人的，应当自作出有关任职决定之日起20日内办理证券业务许可证的变更手续。"},{"i":41,"n":"第四十一条","txt":"证券公司董事、监事、高管人员和分支机构负责人应当按照法律、行政法规、中国证监会的规定和公司章程行使职权，不得授权未取得任职资格的人员代为行使职权。"},{"i":42,"n":"第四十二条","txt":"高管人员职责分工发生调整的，证券公司应当在5日内在公司公告，并向相关派出机构报告。同时，证券公司应当将上述事项及时告知相关高管人员。证券公司未按要求履行公告、报告义务的，相关高管人员应当在2日内向相关派出机构报告。"},{"i":43,"n":"第四十三条","txt":"证券公司董事、监事、高管人员和分支机构负责人应当拒绝执行任何机构、个人侵害公司利益或者客户合法权益等的指令或者授意，发现有侵害客户合法权益的违法违规行为的，应当及时向中国证监会及相关派出机构报告。 中国证监会及其派出机构依法保护因依法履行职责、切实维护客户利益而受到不公正待遇的董事、监事、高管人员和分支机构负责人的合法权益。"},{"i":44,"n":"第四十四条","txt":"禁止证券公司董事、监事、高管人员和分支机构负责人从事下列行为： （一）利用职权收受贿赂或者获取其他非法收入； （二）挪用或侵占公司或者客户资产； （三）违法将公司或者客户资金借贷给他人； （四）以客户资产为本公司、公司股东或者其他机构、个人债务提供担保。"},{"i":45,"n":"第四十五条","txt":"中国证监会对取得经理层人员任职资格但未在证券公司担任经理层人员职务的人员进行资格年检。 中国证监会对取得分支机构负责人任职资格但未在证券公司担任分支机构负责人职务的人员进行资格年检。 上述人员应当自取得任职资格的下一个年度起，在每年第一季度向住所地派出机构提交由单位负责人或推荐人签署意见的年检登记表。"},{"i":46,"n":"第四十六条","txt":"取得经理层人员任职资格而不在证券公司担任经理层人员职务的人员，未按规定参加资格年检，或未通过资格年检，或自取得任职资格之日起连续5年未在证券公司任职的，应当在任职前重新申请取得经理层人员的任职资格。 取得分支机构负责人任职资格而不在证券公司担任分支机构负责人职务的人员，未按规定参加资格年检，或未通过资格年检，或连续5年未在证券公司任职的，应当在任职前重新申请取得分支机构负责人的任职资格。"},{"i":47,"n":"第四十七条","txt":"中国证监会建立数据库，记录取得经理层人员任职资格的人员信息。证券公司选聘经理层人员，可以从中查询相关信息。 中国证监会将证券公司董事长、副董事长、监事会主席的有关信息录入数据库。"},{"i":48,"n":"第四十八条","txt":"取得董事、监事、经理层人员任职资格的人员应当至少每3年参加1次中国证监会认可的业务培训，取得培训合格证书。 取得分支机构负责人任职资格的人员应当至少每3年参加1次所在地派出机构认可的业务培训，取得培训合格证书。"},{"i":49,"n":"第四十九条","txt":"证券公司董事长、总经理不能履行职务或者缺位时，公司可以按公司章程等规定临时决定符合第八条规定的人员代为履行职务，并在作出决定之日起3日内向中国证监会及注册地派出机构报告。 公司决定的人员不符合条件的，中国证监会及相关派出机构可以责令公司限期另行决定代为履行职务的人员，并责令原代为履行职务人员停止履行职务。 代为履行职务的时间不得超过6个月。公司应当在6个月内选聘具有任职资格的人员担任董事长、总经理。"},{"i":50,"n":"第五十条","txt":"证券公司董事、监事、高管人员和分支机构负责人涉嫌重大违法犯罪，被行政机关立案调查或司法机关立案侦查的，证券公司应当暂停相关人员的职务。"},{"i":51,"n":"第五十一条","txt":"有下列情形之一的，相关派出机构应当对负有直接责任或领导责任的董事、监事、高管人员和分支机构负责人进行监管谈话： （一）证券公司或本人涉嫌违反法律、行政法规或者中国证监会规定； （二）证券公司法人治理结构、内部控制存在重大隐患； （三）证券公司财务指标不符合中国证监会规定的风险控制指标； （四）证券公司聘任不具有任职资格的人员担任董事、监事、高管人员和分支机构负责人或者违反本办法规定授权不具备任职资格的人员实际履行上述职务； （五）违反本办法第三十四条、第四十二条规定，未履行公告义务； （六）董事、监事、高管人员和分支机构负责人不遵守承诺； （七）违反本办法第四十一条、第四十三条、第四十八条、第五十条规定； （八）自签署推荐意见之日起1年内所推荐的人员被认定为不适当人选或被撤销任职资格； （九）所出具的推荐意见存在虚假内容； （十）对公司及其股东、其他董事、监事、高管人员和分支机构负责人"},{"i":52,"n":"第五十二条","txt":"证券公司净资本或其他风险控制指标不符合规定，被中国证监会责令限期改正而逾期未改正的，或其行为严重危及证券公司的稳健运行、损害客户合法权益的，中国证监会可以限制公司向董事、监事、高管人员和分支机构负责人支付报酬、提供福利，或暂停相关人员职务，或责令更换董事、监事、高管人员和分支机构负责人。 董事、监事、高管人员和分支机构负责人被暂停职务期间，不得离职。"},{"i":53,"n":"第五十三条","txt":"证券公司董事、监事、高管人员和分支机构负责人在任职期间出现下列情形之一的，中国证监会及相关派出机构可以将其认定为不适当人选： （一）向证券监管机构提供虚假信息、隐瞒重大事项； （二）拒绝配合证券监管机构依法履行监管职责； （三）擅离职守； （四）1年内累计3次被证券监管机构按照本办法第五十一条的规定进行监管谈话； （五）累计3次被自律组织纪律处分； （六）累计3次对公司受到行政处罚负有领导责任； （七）累计5次对公司受到纪律处分负有领导责任； （八）中国证监会根据审慎监管原则认定的其他情形。"},{"i":54,"n":"第五十四条","txt":"自被中国证监会及相关派出机构认定为不适当人选之日起2年内，任何证券公司不得聘用该人员担任董事、监事、高管人员和分支机构负责人。"},{"i":55,"n":"第五十五条","txt":"证券公司董事、监事和高管人员未能勤勉尽责，致使证券公司存在重大违法违规行为或者重大风险的，中国证监会及相关派出机构可以撤销相关人员的任职资格，并责令公司限期更换董事、监事和高管人员。 分支机构负责人未能勤勉尽责，致使证券公司存在重大违法违规行为或者重大风险的，应当依据有关规定处理。"},{"i":56,"n":"第五十六条","txt":"自推荐人签署推荐意见之日起1年内，被推荐人被认定为不适当人选或被撤销任职资格的，自作出有关决定之日起2年内不受理该推荐人的推荐意见和签署意见的年检登记表。"},{"i":57,"n":"第五十七条","txt":"法定代表人、高管人员和分支机构负责人辞职，或被认定为不适当人选而被解除职务，或被撤销任职资格的，证券公司应当按照规定对其进行离任审计，并且自离任之日起2个月内将审计报告报相关派出机构备案。"},{"i":58,"n":"第五十八条","txt":"法定代表人、高管人员、分支机构负责人离任审计期间，不得在其他证券公司担任董事、监事、高管人员和分支机构负责人。"},{"i":59,"n":"第五十九条","txt":"证券公司董事、监事、高管人员和分支机构负责人违反法律、行政法规和中国证监会的规定，依法应予以行政处罚的，依照有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究刑事责任。"},{"i":60,"n":"第六十条","txt":"申请人或拟任人隐瞒有关情况或者提供虚假材料申请任职资格的，证券监管机构不予受理或者不予行政许可，并依法给予警告。"},{"i":61,"n":"第六十一条","txt":"申请人或拟任人以欺骗、贿赂等不正当手段取得任职资格的，应当予以撤销，对公司和负有责任的人员予以警告，并处以罚款。"},{"i":62,"n":"第六十二条","txt":"证券公司违反本办法规定，聘任不具有任职资格的人员担任相应职务的，中国证监会根据《证券法》第一百九十八条的规定给予行政处罚。"},{"i":63,"n":"第六十三条","txt":"有下列情形之一的，责令改正，对证券公司和负有责任的人员依据法律法规和部门规章的规定进行处罚： （一）违反本办法第三十七条、第四十四条和第四十九条规定； （二）对中国证监会依据本办法第三十五条、第五十四条作出的监管要求，公司未按规定作出相应处理； （三）证券公司及相关人员未按规定履行报告义务或者报送的材料存在虚假记载、误导性陈述或者重大遗漏的。"},{"i":64,"n":"第六十四条","txt":"本办法所称分支机构负责人是指证券公司在境内设立的分公司、证券营业部以及中国证监会规定可以从事业务经营活动的证券公司下属其他非法人机构的经理及实际履行经理职务的人员。"},{"i":65,"n":"第六十五条","txt":"本办法所称金融工作是指除证券以外的其他金融工作。 在上市公司从事证券相关工作的,视为从事证券工作。"},{"i":66,"n":"第六十六条","txt":"本办法规定的期限以工作日计算，不含法定节假日。"},{"i":67,"n":"第六十七条","txt":"本办法自2006年12月1日起施行。中国证监会发布的《证券经营机构高级管理人员任职资格管理暂行办法》（证监机字〔1998〕46号）、《证券公司高级管理人员管理办法》（证监会令第24号）同时废止。"}],"zhengquangongsirongzirongquanyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范证券公司融资融券业务活动，完善证券交易机制，防范证券公司的风险，保护证券投资者的合法权益和社会公共利益，促进证券市场平稳健康发展，制定本办法。"},{"i":2,"n":"第二条","txt":"证券公司开展融资融券业务，应当遵守法律、行政法规和本办法的规定，加强内部控制，严格防范和控制风险，切实维护客户合法权益。 本办法所称融资融券业务，是指向客户出借资金供其买入证券或者出借证券供其卖出，并收取担保物的经营活动。"},{"i":3,"n":"第三条","txt":"证券公司开展融资融券业务，必须经中国证券监督管理委员会（以下简称证监会）批准。未经证监会批准，任何证券公司不得向客户融资、融券，也不得为客户与客户、客户与他人之间的融资融券活动提供任何便利和服务。"},{"i":4,"n":"第四条","txt":"证券公司经营融资融券业务不得有以下行为： （一）诱导不适当的客户开展融资融券业务； （二）未向客户充分揭示风险； （三）违规挪用客户担保物； （四）进行利益输送和商业贿赂； （五）为客户进行内幕交易、操纵市场、规避信息披露义务及其他不正当交易活动提供便利； （六）法律、行政法规和证监会规定禁止的其他行为。"},{"i":5,"n":"第五条","txt":"证监会及其派出机构依照法律、行政法规和本办法的规定，对证券公司融资融券业务活动进行监督管理。 中国证券业协会、证券交易所、证券登记结算机构按照本机构的章程和规则，对证券公司融资融券业务活动进行自律管理。中国证券金融公司对证券公司融资融券业务和客户融资融券交易情况进行监测监控。"},{"i":6,"n":"第六条","txt":"证监会建立健全融资融券业务的逆周期调节机制，对融资融券业务实施宏观审慎管理。 证券交易所建立融资融券业务风险控制指标浮动管理机制，对融资融券业务实施逆周期调节。"},{"i":7,"n":"第七条","txt":"证券公司申请融资融券业务资格，应当具备下列条件： （一）具有证券经纪业务资格； （二）公司治理健全，内部控制有效，能有效识别、控制和防范业务经营风险和内部管理风险； （三）公司最近2年内不存在因涉嫌违法违规正被证监会立案调查或者正处于整改期间的情形； （四）财务状况良好，最近2年各项风险控制指标持续符合规定，注册资本和净资本符合增加融资融券业务后的规定； （五）客户资产安全、完整，客户交易结算资金第三方存管有效实施，客户资料完整真实； （六）已建立完善的客户投诉处理机制，能够及时、妥善处理与客户之间的纠纷； （七）已建立符合监管规定和自律要求的客户适当性制度，实现客户与产品的适当性匹配管理； （八）信息系统安全稳定运行，最近1年未发生因公司管理问题导致的重大事件，融资融券业务技术系统已通过证券交易所、证券登记结算机构组织的测试； （九）有拟负责融资融券业务的高级管理人员和适当数量的专业"},{"i":8,"n":"第八条","txt":"证券公司申请融资融券业务资格，应当向证监会提交下列材料，同时抄报住所地证监会派出机构： （一）融资融券业务资格申请书； （二）股东会（股东大会）关于经营融资融券业务的决议； （三）融资融券业务方案、内部管理制度文本和按照本办法第十二条制定的选择客户的标准； （四）负责融资融券业务的高级管理人员与业务人员的名册及资格证明文件； （五）证券交易所、证券登记结算机构出具的关于融资融券业务技术系统已通过测试的证明文件； （六）证监会要求提交的其他文件。 证券公司的法定代表人和经营管理的主要负责人应当在融资融券业务资格申请书上签字，承诺申请材料的内容真实、准确、完整，并对申请材料中存在的虚假记载、误导性陈述和重大遗漏承担相应的法律责任。"},{"i":9,"n":"第九条","txt":"获得批准的证券公司应当按照规定，向公司登记机关申请业务范围变更登记，向证监会申请换发《经营证券业务许可证》。 取得证监会换发的《经营证券业务许可证》后，证券公司方可开展融资融券业务。"},{"i":10,"n":"第十条","txt":"证券公司经营融资融券业务，应当以自己的名义，在证券登记结算机构分别开立融券专用证券账户、客户信用交易担保证券账户、信用交易证券交收账户和信用交易资金交收账户。 融券专用证券账户用于记录证券公司持有的拟向客户融出的证券和客户归还的证券，不得用于证券买卖；客户信用交易担保证券账户用于记录客户委托证券公司持有、担保证券公司因向客户融资融券所生债权的证券；信用交易证券交收账户用于客户融资融券交易的证券结算；信用交易资金交收账户用于客户融资融券交易的资金结算。"},{"i":11,"n":"第十一条","txt":"证券公司经营融资融券业务，应当以自己的名义，在商业银行分别开立融资专用资金账户和客户信用交易担保资金账户。 融资专用资金账户用于存放证券公司拟向客户融出的资金及客户归还的资金；客户信用交易担保资金账户用于存放客户交存的、担保证券公司因向客户融资融券所生债权的资金。"},{"i":12,"n":"第十二条","txt":"证券公司在向客户融资、融券前，应当办理客户征信，了解客户的身份、财产与收入状况、证券投资经验和风险偏好、诚信合规记录等情况，做好客户适当性管理工作，并以书面或者电子方式予以记载、保存。 对未按照要求提供有关情况、从事证券交易时间不足半年、缺乏风险承担能力、最近20个交易日日均证券类资产低于50万元或者有重大违约记录的客户，以及本公司的股东、关联人，证券公司不得为其开立信用账户。 专业机构投资者参与融资、融券，可不受前款从事证券交易时间、证券类资产的条件限制。 本条第二款所称股东，不包括仅持有上市证券公司5%以下流通股份的股东。 证券公司应当按照适当性制度要求，制定符合本条规定的选择客户的具体标准。"},{"i":13,"n":"第十三条","txt":"证券公司在向客户融资、融券前，应当与其签订载有中国证券业协会规定的必备条款的融资融券合同，明确约定下列事项： （一）融资、融券的额度、期限、利率（费率）、利息（费用）的计算方式； （二）保证金比例、维持担保比例、可充抵保证金的证券的种类及折算率、担保债权范围； （三）追加保证金的通知方式、追加保证金的期限； （四）客户清偿债务的方式及证券公司对担保物的处分权利； （五）融资买入证券和融券卖出证券的权益处理； （六）违约责任； （七）纠纷解决途径； （八）其他有关事项。"},{"i":14,"n":"第十四条","txt":"融资融券合同应当约定，证券公司客户信用交易担保证券账户内的证券和客户信用交易担保资金账户内的资金，为担保证券公司因融资融券所生对客户债权的信托财产。 证券公司与客户约定的融资、融券期限不得超过证券交易所规定的期限；融资利率、融券费率由证券公司与客户自主商定。 合约到期前，证券公司可以根据客户的申请为客户办理展期，每次展期期限不得超过证券交易所规定的期限。 证券公司在为客户办理合约展期前，应当对客户的信用状况、负债情况、维持担保比例水平等进行评估。"},{"i":15,"n":"第十五条","txt":"证券公司与客户签订融资融券合同前，应当采用适当的方式向客户讲解业务规则和合同内容，明确告知客户权利、义务及风险，特别是关于违约处置的风险控制安排，并将融资融券交易风险揭示书交由客户书面确认。"},{"i":16,"n":"第十六条","txt":"证券公司与客户签订融资融券合同后，应当根据客户的申请，按照证券登记结算机构的规定，为其开立实名信用证券账户。客户信用证券账户与其普通证券账户的开户人姓名或者名称应当一致。 客户信用证券账户是证券公司客户信用交易担保证券账户的二级账户，用于记载客户委托证券公司持有的担保证券的明细数据。 证券公司应当委托证券登记结算机构根据清算、交收结果等，对客户信用证券账户内的数据进行变更。"},{"i":17,"n":"第十七条","txt":"证券公司应当参照客户交易结算资金第三方存管的方式，与其客户及商业银行签订客户信用资金存管协议。 证券公司在与客户签订融资融券合同后，应当通知商业银行根据客户的申请，为其开立实名信用资金账户。 客户信用资金账户是证券公司客户信用交易担保资金账户的二级账户，用于记载客户交存的担保资金的明细数据。 商业银行根据证券公司提供的清算、交收结果等，对客户信用资金账户内的数据进行变更。"},{"i":18,"n":"第十八条","txt":"证券公司向客户融资，只能使用融资专用资金账户内的资金；向客户融券，只能使用融券专用证券账户内的证券。 客户融资买入、融券卖出的证券，不得超出证券交易所规定的范围。 客户在融券期间卖出其持有的、与所融入证券相同的证券的，应当符合证券交易所的规定，不得以违反规定卖出该证券的方式操纵市场。"},{"i":19,"n":"第十九条","txt":"证券公司经营融资融券业务，按照客户委托发出证券交易、证券划转指令的，应当保证指令真实、准确。因证券公司的过错导致指令错误，造成客户损失的，客户可以依法要求证券公司赔偿，但不影响证券交易所、证券登记结算机构正在执行或者已经完成的业务操作。"},{"i":20,"n":"第二十条","txt":"证券公司融资融券的金额不得超过其净资本的4倍。 证券公司向单一客户或者单一证券的融资、融券的金额占其净资本的比例等风险控制指标，应当符合证监会和证券交易所的规定。"},{"i":21,"n":"第二十一条","txt":"客户融资买入证券的，应当以卖券还款或者直接还款的方式偿还向证券公司融入的资金。 客户融券卖出的，应当以买券还券或者直接还券的方式偿还向证券公司融入的证券。 客户融券卖出的证券暂停交易的，可以按照约定以现金等方式偿还向证券公司融入的证券。"},{"i":22,"n":"第二十二条","txt":"客户融资买入或者融券卖出的证券暂停交易，且交易恢复日在融资融券债务到期日之后的，融资融券的期限顺延。融资融券合同另有约定的，从其约定。"},{"i":23,"n":"第二十三条","txt":"客户融资买入或者融券卖出的证券预定终止交易，且最后交易日在融资融券债务到期日之前的，融资融券的期限缩短至最后交易日的前一交易日。融资融券合同另有约定的，从其约定。"},{"i":24,"n":"第二十四条","txt":"证券公司向客户融资、融券，应当向客户收取一定比例的保证金。保证金可以证券充抵。"},{"i":25,"n":"第二十五条","txt":"证券公司应当将收取的保证金以及客户融资买入的全部证券和融券卖出所得全部价款，分别存放在客户信用交易担保证券账户和客户信用交易担保资金账户，作为对该客户融资融券所生债权的担保物。"},{"i":26,"n":"第二十六条","txt":"证券公司应当在符合证券交易所规定的前提下，根据客户信用状况、担保物质量等情况，与客户约定最低维持担保比例、补足担保物的期限以及违约处置方式等。 证券公司应当逐日计算客户交存的担保物价值与其所欠债务的比例。当该比例低于约定的维持担保比例时，应当通知客户在约定的期限内补交担保物，客户经证券公司认可后，可以提交除可充抵保证金证券以外的其他证券、不动产、股权等资产。 客户未能按期交足担保物或者到期未偿还债务的，证券公司可以按照约定处分其担保物。"},{"i":27,"n":"第二十七条","txt":"本办法第二十四条规定的保证金比例和可充抵保证金的证券的种类、折算率，第二十六条规定的最低维持担保比例和客户补交担保物的期限，由证券交易所规定。 证券交易所应当对可充抵保证金的各类证券制定不同的折算率要求。 证券公司在符合证券交易所规定的前提下，应当对可充抵保证金的证券折算率实行动态管理和差异化控制。"},{"i":28,"n":"第二十八条","txt":"除下列情形外，任何人不得动用证券公司客户信用交易担保证券账户内的证券和客户信用交易担保资金账户内的资金： （一）为客户进行融资融券交易的结算； （二）收取客户应当归还的资金、证券； （三）收取客户应当支付的利息、费用、税款； （四）按照本办法的规定以及与客户的约定处分担保物； （五）收取客户应当支付的违约金； （六）客户提取还本付息、支付税费及违约金后的剩余证券和资金； （七）法律、行政法规和本办法规定的其他情形。"},{"i":29,"n":"第二十九条","txt":"客户交存的担保物价值与其债务的比例，超过证券交易所规定水平的，客户可以按照证券交易所的规定和融资融券合同的约定，提取担保物。"},{"i":30,"n":"第三十条","txt":"司法机关依法对客户信用证券账户或者信用资金账户记载的权益采取财产保全或者强制执行措施的，证券公司应当处分担保物，实现因向客户融资融券所生债权，并协助司法机关执行。"},{"i":31,"n":"第三十一条","txt":"证券登记结算机构依据证券公司客户信用交易担保证券账户内的记录，确认证券公司受托持有证券的事实，并以证券公司为名义持有人，登记于证券持有人名册。"},{"i":32,"n":"第三十二条","txt":"对客户信用交易担保证券账户记录的证券，由证券公司以自己的名义，为客户的利益，行使对证券发行人的权利。证券公司行使对证券发行人的权利，应当事先征求客户的意见，并按照其意见办理。客户未表达意见的，证券公司不得行使对发行人的权利。 前款所称对证券发行人的权利，是指请求召开证券持有人会议、参加证券持有人会议、提案、表决、配售股份的认购、请求分配投资收益等因持有证券而产生的权利。"},{"i":33,"n":"第三十三条","txt":"证券登记结算机构受证券发行人委托以证券形式分派投资收益的，应当将分派的证券记录在证券公司客户信用交易担保证券账户内，并相应变更客户信用证券账户的明细数据。 证券登记结算机构受证券发行人委托以现金形式分派投资收益的，应当将分派的资金划入证券公司信用交易资金交收账户。证券公司应当在资金到账后，通知商业银行对客户信用资金账户的明细数据进行变更。"},{"i":34,"n":"第三十四条","txt":"客户融入证券后、归还证券前，证券发行人分配投资收益、向证券持有人配售或者无偿派发证券、发行证券持有人有优先认购权的证券的，客户应当按照融资融券合同的约定，在偿还债务时，向证券公司支付与所融入证券可得利益相等的证券或者资金。"},{"i":35,"n":"第三十五条","txt":"证券公司通过客户信用交易担保证券账户持有的股票不计入其自有股票，证券公司无须因该账户内股票数量的变动而履行相应的信息报告、披露或者要约收购义务。 客户及其一致行动人通过普通证券账户和信用证券账户合计持有一家上市公司股票及其权益的数量或者其增减变动达到规定的比例时，应当依法履行相应的信息报告、披露或者要约收购义务。"},{"i":36,"n":"第三十六条","txt":"证券交易所应当根据市场发展情况，对融资融券业务保证金比例、标的证券范围、可充抵保证金的证券种类及折算率、最低维持担保比例等进行动态调整，实施逆周期调节。 证券交易所可以对单一证券的市场融资买入量、融券卖出量和担保物持有量占其市场流通量的比例、融券卖出的价格作出限制性规定。 证券公司应当在符合监管要求的前提下，根据市场情况、客户和自身风险承受能力，对融资融券业务保证金比例、标的证券范围、可充抵保证金的证券种类及折算率、最低维持担保比例和业务集中度等进行动态调整和差异化控制。 业务集中度包括：向全体客户融资、融券的金额占净资本的比例，单一证券的融资、融券的金额占净资本的比例，接受单只担保证券的市值占该证券总市值的比例，单一客户提交单只担保证券的市值占该客户担保物市值的比例等。"},{"i":37,"n":"第三十七条","txt":"证券公司开展融资融券业务，应当建立完备的管理制度、操作流程和风险识别、评估与控制体系，确保风险可测、可控、可承受。 证券公司应当对融资融券业务实行集中统一管理。融资融券业务的决策和主要管理职责应当由证券公司总部承担。 证券公司应当建立健全融资融券业务压力测试机制，定期、不定期对融资融券业务的流动性风险、信用风险、市场风险、技术系统风险等进行压力测试，根据压力测试结果对本办法第三十六条第三款所规定的本公司相关指标进行优化和调整。"},{"i":38,"n":"第三十八条","txt":"证券交易所应当按照业务规则，采取措施，对融资融券交易的指令进行前端检查，对买卖证券的种类、融券卖出的价格等违反规定的交易指令，予以拒绝。 单一证券的市场融资买入量、融券卖出量或者担保物持有量占其市场流通量的比例达到规定的最高限制比例的，证券交易所可以暂停接受该种证券的融资买入指令或者融券卖出指令。"},{"i":39,"n":"第三十九条","txt":"融资融券交易活动出现异常，已经或者可能危及市场稳定，有必要暂停交易的，证券交易所应当按照业务规则的规定，暂停部分或者全部证券的融资融券交易并公告。"},{"i":40,"n":"第四十条","txt":"证券登记结算机构应当按照业务规则，对与融资融券交易有关的证券划转和证券公司信用交易资金交收账户内的资金划转情况进行监督。对违反规定的证券和资金划转指令，予以拒绝；发现异常情况的，应当要求证券公司作出说明，并向证监会及该公司住所地证监会派出机构报告。"},{"i":41,"n":"第四十一条","txt":"中国证券金融公司应当按照业务规则，要求证券公司及时、准确、真实、完整报送融资融券业务有关数据信息；对证券公司融资融券数据进行统计分析，编制定期报告和专项报告，报送证监会；监测监控融资融券业务风险，对发现的重大业务风险情况，及时报告证监会。"},{"i":42,"n":"第四十二条","txt":"证券公司融资融券业务涉及的客户信用交易资金应当纳入证券市场交易结算资金监控系统，证券公司、存管银行、登记结算机构等应当按要求向中国证券投资者保护基金公司报送相关数据信息。"},{"i":43,"n":"第四十三条","txt":"负责客户信用资金存管的商业银行应当按照客户信用资金存管协议的约定，对证券公司违反规定的资金划拨指令予以拒绝；发现异常情况的，应当要求证券公司作出说明，并向证监会及该公司住所地证监会派出机构报告。"},{"i":44,"n":"第四十四条","txt":"证券公司应当按照融资融券合同约定的方式，向客户送交对账单，并为其提供信用证券账户和信用资金账户内数据的查询服务。 证券登记结算机构应当为客户提供其信用证券账户内数据的查询服务。负责客户信用资金存管的商业银行应当按照客户信用资金存管协议的约定，为客户提供其信用资金账户内数据的查询服务。"},{"i":45,"n":"第四十五条","txt":"证券公司应当通过有效的途径，及时告知客户融资、融券的收费标准及其变动情况。"},{"i":46,"n":"第四十六条","txt":"证券公司应当按照证券交易所的规定，在每日收市后向其报告当日客户融资融券交易的有关信息。证券交易所应当对证券公司报送的信息进行汇总、统计，并在次一交易日开市前予以公告。"},{"i":47,"n":"第四十七条","txt":"证监会及其派出机构、中国证券业协会、证券交易所、证券登记结算机构、中国证券金融公司依照规定履行证券公司融资融券业务监管、自律或者监测分析职责，可以要求证券公司提供与融资融券业务有关的信息、资料。"},{"i":48,"n":"第四十八条","txt":"证监会派出机构按照辖区监管责任制的要求，依法对证券公司及其分支机构的融资融券业务活动中涉及的客户选择、合同签订、授信额度的确定、担保物的收取和管理、补交担保物的通知，以及处分担保物等事项进行非现场检查和现场检查。"},{"i":49,"n":"第四十九条","txt":"对违反本办法规定的证券公司或者其分支机构，证监会或者其派出机构可采取责令改正、监管谈话、出具警示函、责令公开说明、责令参加培训、责令定期报告、暂不受理与行政许可有关的文件、暂停部分或者全部业务、撤销业务许可等相关监管措施；依法应予行政处罚的，依照《证券法》、《行政处罚法》等法律法规和证监会的有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":50,"n":"第五十条","txt":"负责客户信用资金存管的商业银行，应当是按照规定可以存管证券公司客户交易结算资金的商业银行。"},{"i":51,"n":"第五十一条","txt":"本办法所称专业机构投资者是指：经国家金融监管部门批准设立的金融机构，包括商业银行、证券公司、基金管理公司、期货公司、信托公司和保险公司等；上述金融机构管理的金融产品；经证监会或者其授权机构登记备案的私募基金管理机构及其管理的私募基金产品；证监会认可的其他投资者。"},{"i":52,"n":"第五十二条","txt":"证券交易所、证券登记结算机构和中国证券业协会依照本办法的规定，制定融资融券的业务规则和自律规则，报证监会批准后实施。"},{"i":53,"n":"第五十三条","txt":"本办法自公布之日起施行。2011年10月26日发布的《证券公司融资融券业务管理办法》（证监会公告〔2011〕31号）同时废止。"}],"zhengquangongsifengxiankongzhizhibiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了建立以净资本和流动性为核心的风险控制指标体系，加强证券公司风险监管，督促证券公司加强内部控制、提升风险管理水平、防范风险，根据《证券法》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"证券公司应当按照中国证券监督管理委员会（以下简称中国证监会）的有关规定，遵循审慎、实质重于形式的原则，计算净资本、风险覆盖率、资本杠杆率、流动性覆盖率、净稳定资金率等各项风险控制指标，编制净资本计算表、风险资本准备计算表、表内外资产总额计算表、流动性覆盖率计算表、净稳定资金率计算表、风险控制指标计算表等监管报表（以下统称风险控制指标监管报表）。"},{"i":3,"n":"第三条","txt":"中国证监会可以根据市场发展情况和审慎监管原则，对各项风险控制指标标准及计算要求进行动态调整；调整之前，应当公开征求行业意见，并为调整事项的实施作出过渡性安排。 对于未规定风险控制指标标准及计算要求的新产品、新业务，证券公司在投资该产品或者开展该业务前，应当按照规定事先向中国证监会、公司注册地的中国证监会派出机构（以下简称派出机构）报告或者报批。中国证监会根据证券公司新产品、新业务的特点和风险状况，在征求行业意见基础上确定相应的风险控制指标标准及计算要求。"},{"i":4,"n":"第四条","txt":"中国证监会可以按照分类监管原则，根据证券公司的治理结构、内控水平和风险控制情况，对不同类别公司的风险控制指标标准和计算要求，以及某项业务的风险资本准备计算比例进行动态调整。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构应当对证券公司净资本等各项风险控制指标数据的生成过程及计算结果的真实性、准确性、完整性进行定期或者不定期检查。 中国证监会及其派出机构可以根据监管需要，要求证券公司聘请符合《证券法》规定的会计师事务所对其风险控制指标监管报表进行审计。"},{"i":6,"n":"第六条","txt":"证券公司应当根据中国证监会有关规定建立符合自身发展战略需要的全面风险管理体系。证券公司应当将所有子公司以及比照子公司管理的各类孙公司纳入全面风险管理体系，强化分支机构风险管理，实现风险管理全覆盖。全面风险管理体系应当包括可操作的管理制度、健全的组织架构、可靠的信息技术系统、量化的风险指标体系、专业的人才队伍、有效的风险应对机制。 证券公司应当任命一名具有风险管理相关专业背景、任职经历、履职能力的高级管理人员为首席风险官，由其负责全面风险管理工作。"},{"i":7,"n":"第七条","txt":"证券公司应当根据自身资产负债状况和业务发展情况，建立动态的风险控制指标监控和资本补足机制，确保净资本等各项风险控制指标在任一时点都符合规定标准。 证券公司应当在发生重大业务事项及分配利润前对风险控制指标进行压力测试，合理确定有关业务及分配利润的最大规模。 证券公司应当建立健全压力测试机制，及时根据市场变化情况及监管部门要求，对公司风险控制指标进行压力测试。 压力测试结果显示风险超过证券公司自身承受能力范围的，证券公司应采取措施控制业务规模或降低风险。"},{"i":8,"n":"第八条","txt":"证券公司应当聘请符合《证券法》规定的会计师事务所对其年度风险控制指标监管报表进行审计。"},{"i":9,"n":"第九条","txt":"会计师事务所及其注册会计师应当勤勉尽责，对证券公司风险控制指标监管报表的真实性、准确性、完整性进行审计，并发表恰当的审计意见。"},{"i":10,"n":"第十条","txt":"证券公司净资本由核心净资本和附属净资本构成。其中： 核心净资本＝净资产－资产项目的风险调整－或有负债的风险调整－/＋中国证监会认定或核准的其他调整项目。 附属净资本＝长期次级债×规定比例－/＋中国证监会认定或核准的其他调整项目。"},{"i":11,"n":"第十一条","txt":"证券公司应当按照中国证监会规定的证券公司净资本计算标准计算净资本。"},{"i":12,"n":"第十二条","txt":"证券公司计算核心净资本时，应当按照规定对有关项目充分计提资产减值准备。 中国证监会及其派出机构可以要求公司专项说明资产减值准备提取的充足性和合理性。有证据表明公司未充分计提资产减值准备的，中国证监会及其派出机构可以责令公司整改并追究相关人员责任。"},{"i":13,"n":"第十三条","txt":"证券公司应当根据公司期末或有事项的性质（如未决诉讼、未决仲裁、对外提供担保等）、涉及金额、形成原因和进展情况、可能发生的损失和预计损失进行相应会计处理。对于很可能导致经济利益流出公司的或有事项，应当确认预计负债；对于未确认预计负债，但仍可能导致经济利益流出公司的或有事项，在计算核心净资本时，应当作为或有负债，按照一定比例在净资本中予以扣减，并在净资本计算表的附注中披露。"},{"i":14,"n":"第十四条","txt":"证券公司对控股证券业务子公司出具承诺书提供担保承诺的，应当按照担保承诺金额的一定比例扣减核心净资本。从事证券承销与保荐、证券资产管理业务等中国证监会认可的子公司可以将母公司提供的担保承诺按照一定比例计入核心净资本。"},{"i":15,"n":"第十五条","txt":"证券公司向股东或机构投资者借入或发行的次级债，可以按照一定比例计入附属净资本或扣减风险资本准备。具体规定由中国证监会另行制定。"},{"i":16,"n":"第十六条","txt":"证券公司经营证券经纪业务的，其净资本不得低于人民币2000万元。 证券公司经营证券承销与保荐、证券自营、证券资产管理、其他证券业务等业务之一的，其净资本不得低于人民币5000万元。 证券公司经营证券经纪业务，同时经营证券承销与保荐、证券自营、证券资产管理、其他证券业务等业务之一的，其净资本不得低于人民币1亿元。 证券公司经营证券承销与保荐、证券自营、证券资产管理、其他证券业务中两项及两项以上的，其净资本不得低于人民币2亿元。"},{"i":17,"n":"第十七条","txt":"证券公司必须持续符合下列风险控制指标标准： （一）风险覆盖率不得低于100%； （二）资本杠杆率不得低于8%； （三）流动性覆盖率不得低于100%； （四）净稳定资金率不得低于100%； 其中： 风险覆盖率＝净资本/各项风险资本准备之和×100%； 资本杠杆率＝核心净资本/表内外资产总额×100%； 流动性覆盖率＝优质流动性资产/未来30天现金净流出量×100%； 净稳定资金率＝可用稳定资金/所需稳定资金×100%。"},{"i":18,"n":"第十八条","txt":"证券公司应当按照中国证监会规定的证券公司风险资本准备计算标准计算市场风险、信用风险、操作风险资本准备。中国证监会可以根据特定产品或业务的风险特征，以及监督检查结果，要求证券公司计算特定风险资本准备。 市场风险资本准备按照各类金融工具市场风险特征的不同，用投资规模乘以风险系数计算；信用风险资本准备按照各表内外项目信用风险程度的不同，用资产规模乘以风险系数计算；操作风险资本准备按照各项业务收入的一定比例计算。 证券公司可以采取内部模型法等风险计量高级方法计算风险资本准备，具体规定由中国证监会另行制定。"},{"i":19,"n":"第十九条","txt":"证券公司经营证券自营业务、为客户提供融资或融券服务的，应当符合中国证监会对该项业务的风险控制指标标准。"},{"i":20,"n":"第二十条","txt":"证券公司可以结合自身实际情况，在不低于中国证监会规定标准的基础上，确定相应的风险控制指标标准。"},{"i":21,"n":"第二十一条","txt":"中国证监会对各项风险控制指标设置预警标准，对于规定“不得低于”一定标准的风险控制指标，其预警标准是规定标准的120%；对于规定“不得超过”一定标准的风险控制指标，其预警标准是规定标准的80%。"},{"i":22,"n":"第二十二条","txt":"设有子公司的证券公司应当以母公司数据为基础，编制风险控制指标监管报表。 中国证监会及其派出机构可以根据监管需要，要求证券公司以合并数据为基础编制风险控制指标监管报表。"},{"i":23,"n":"第二十三条","txt":"证券公司的董事、高级管理人员应当对公司半年度、年度风险控制指标监管报表签署确认意见。 证券公司经营管理的主要负责人、首席风险官、财务负责人应当对公司月度风险控制指标监管报表签署确认意见。在证券公司风险控制指标监管报表上签字的人员，应当保证风险控制指标监管报表真实、准确、完整，不存在虚假记载、误导性陈述和重大遗漏；对风险控制指标监管报表内容持有异议的，应当在报表上注明自己的意见和理由。"},{"i":24,"n":"第二十四条","txt":"证券公司应当至少每半年经主要负责人、首席风险官签署确认后，向公司全体董事报告一次公司净资本等风险控制指标的具体情况和达标情况；证券公司应当至少每半年经董事会签署确认，向公司全体股东报告一次公司净资本等风险控制指标的具体情况和达标情况，并至少获得主要股东的签收确认证明文件。 净资本指标与上月相比发生20%以上不利变化或不符合规定标准时，证券公司应当在5个工作日内向公司全体董事报告，10个工作日内向公司全体股东报告。"},{"i":25,"n":"第二十五条","txt":"证券公司应当在每月结束之日起7个工作日内，向中国证监会及其派出机构报送月度风险控制指标监管报表。 派出机构可以根据监管需要，要求辖区内单个、部分或者全部证券公司在一定阶段内按周或者按日编制并报送各项风险控制指标监管报表。"},{"i":26,"n":"第二十六条","txt":"证券公司的净资本等风险控制指标与上月相比发生不利变化超过20%的，应当在该情形发生之日起3个工作日内，向中国证监会及其派出机构报告，说明基本情况和变化原因。"},{"i":27,"n":"第二十七条","txt":"证券公司的净资本等风险控制指标达到预警标准或者不符合规定标准的，应当分别在该情形发生之日起3个、1个工作日内，向中国证监会及其派出机构报告，说明基本情况、问题成因以及解决问题的具体措施和期限。"},{"i":28,"n":"第二十八条","txt":"证券公司的财务会计报告、风险控制指标监管报表被注册会计师出具了保留意见、带强调事项段或其他事项段无保留意见的，证券公司应当就涉及事项进行专项说明。 涉及事项不属于明显违反会计准则、证券公司净资本计算规则等有关规定的，中国证监会及其派出机构可以要求证券公司说明该事项对公司净资本等风险控制指标的影响。 涉及事项属于明显违反会计准则、证券公司净资本计算规则等有关规定的，中国证监会及其派出机构可以要求证券公司限期纠正、重新编制风险控制指标监管报表；证券公司未限期纠正的，中国证监会及其派出机构可以认定其净资本等风险控制指标低于规定标准。"},{"i":29,"n":"第二十九条","txt":"证券公司的财务会计报告、风险控制指标监管报表被注册会计师出具了无法表示意见或者否定意见的，中国证监会及其派出机构可以认定其净资本等风险控制指标低于规定标准。"},{"i":30,"n":"第三十条","txt":"证券公司未按照监管部门要求报送风险控制指标监管报表，或者风险控制指标监管报表存在重大错报、漏报以及虚假报送情况，中国证监会及其派出机构可以根据情况采取出具警示函、责令改正、监管谈话、责令处分有关人员等监管措施。"},{"i":31,"n":"第三十一条","txt":"证券公司净资本或者其他风险控制指标不符合规定标准的，派出机构应当责令公司限期改正，在5个工作日制定并报送整改计划，整改期限最长不超过20个工作日；证券公司未按时报送整改计划的，派出机构应当立即限制其业务活动。 整改期内，中国证监会及其派出机构应当区别情形，对证券公司采取下列措施： （一）停止批准新业务； （二）停止批准增设、收购营业性分支机构； （三）限制分配红利； （四）限制转让财产或在财产上设定其他权利。"},{"i":32,"n":"第三十二条","txt":"证券公司整改后，经派出机构验收符合有关风险控制指标的，中国证监会及其派出机构应当自验收完毕之日起3个工作日内解除对其采取的有关措施。"},{"i":33,"n":"第三十三条","txt":"证券公司未按期完成整改的，自整改期限到期的次日起，派出机构应当区别情形，对其采取下列措施： （一）限制业务活动； （二）责令暂停部分业务； （三）限制向董事、监事、高级管理人员支付报酬、提供福利； （四）责令更换董事、监事、高级管理人员或者限制其权利； （五）责令负有责任的股东转让股权，限制负有责任的股东行使股东权利； （六）认定负有责任的董事、监事、高级管理人员为不适当人选； （七）中国证监会及其派出机构认为有必要采取的其他措施。"},{"i":34,"n":"第三十四条","txt":"证券公司未按期完成整改、风险控制指标情况继续恶化，严重危及该证券公司的稳健运行的，中国证监会可以撤销其有关业务许可。"},{"i":35,"n":"第三十五条","txt":"证券公司风险控制指标无法达标，严重危害证券市场秩序、损害投资者利益的，中国证监会可以区别情形，对其采取下列措施： （一）责令停业整顿； （二）指定其他机构托管、接管； （三）撤销经营证券业务许可； （四）撤销。"},{"i":36,"n":"第三十六条","txt":"本办法下列用语的含义： （一）风险资本准备：指证券公司在开展各项业务等过程中，因市场风险、信用风险、操作风险等可能引起的非预期损失所需要的资本。证券公司应当按照一定标准计算风险资本准备并与净资本建立对应关系，确保风险资本准备有对应的净资本支撑。 （二）负债：指对外负债，不含代理买卖证券款、信用交易代理买卖证券款、代理承销证券款。 （三）资产：指自有资产，不含客户资产。 （四）或有负债：指过去的交易或者事项形成的潜在义务，其存在须通过未来不确定事项的发生或者不发生予以证实；或过去的交易或者事项形成的现时义务，履行该义务不是很可能导致经济利益流出企业或该义务的金额不能可靠计量。 （五）表内外资产总额：表内资产余额与表外项目余额之和。"},{"i":37,"n":"第三十七条","txt":"本办法自2006年11月1日起施行。"}],"zhengquanfaxingshangshibaojianyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范证券发行上市保荐业务，提高上市公司质量和证券公司执业水平，保护投资者的合法权益，促进证券市场健康发展，根据《证券法》《证券公司监督管理条例》《国务院办公厅关于贯彻实施修订后的证券法有关工作的通知》（国办发〔2020〕5号）等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"发行人申请从事下列发行事项，依法采取承销方式的，应当聘请具有保荐业务资格的证券公司履行保荐职责： （一）首次公开发行股票； （二）上市公司发行新股、可转换公司债券； （三）公开发行存托凭证； （四）中国证券监督管理委员会（以下简称中国证监会）认定的其他情形。 发行人申请公开发行法律、行政法规规定实行保荐制度的其他证券的，依照前款规定办理。 在实施证券发行核准制的板块，发行人应当就上述已发行证券的上市事项聘请具有保荐业务资格的证券公司履行保荐职责。"},{"i":3,"n":"第三条","txt":"证券公司从事证券发行上市保荐业务，应当依照本办法规定向中国证监会申请保荐业务资格。 未经中国证监会核准，任何机构不得从事保荐业务。"},{"i":4,"n":"第四条","txt":"保荐机构履行保荐职责，应当指定品行良好、具备组织实施保荐项目专业能力的保荐代表人具体负责保荐工作。保荐代表人应当熟练掌握保荐业务相关的法律、会计、财务管理、税务、审计等专业知识，最近5年内具备36个月以上保荐相关业务经历、最近12个月持续从事保荐相关业务，最近3年未受到证券交易所等自律组织的重大纪律处分或者中国证监会的行政处罚、重大行政监管措施。 中国证券业协会制定保荐代表人自律管理规范，组织非准入型的水平评价测试，保障和提高保荐代表人的专业能力水平。"},{"i":5,"n":"第五条","txt":"保荐机构及其保荐代表人、其他从事保荐业务的人员应当遵守法律、行政法规和中国证监会、证券交易所、中国证券业协会的相关规定，恪守业务规则和行业规范，诚实守信，勤勉尽责，尽职推荐发行人证券发行上市，持续督导发行人履行规范运作、信守承诺、信息披露等义务。 保荐机构及其保荐代表人、其他从事保荐业务的人员不得通过从事保荐业务谋取任何不正当利益。"},{"i":6,"n":"第六条","txt":"保荐代表人应当遵守职业道德准则，珍视和维护保荐代表人职业声誉，保持应有的职业谨慎，保持和提高专业胜任能力。 保荐代表人应当维护发行人的合法利益，对从事保荐业务过程中获知的发行人信息保密。保荐代表人应当恪守独立履行职责的原则，不因迎合发行人或者满足发行人的不当要求而丧失客观、公正的立场，不得唆使、协助或者参与发行人及证券服务机构实施非法的或者具有欺诈性的行为。 保荐代表人及其配偶不得以任何名义或者方式持有发行人的股份。 保荐代表人、保荐业务负责人、内核负责人、保荐业务部门负责人及其他保荐业务人员应当保持独立、客观、审慎，与接受其服务的发行人及其关联方不存在利害关系，不存在妨碍其进行独立专业判断的情形。"},{"i":7,"n":"第七条","txt":"同次发行的证券，其发行保荐和上市保荐应当由同一保荐机构承担。保荐机构依法对发行人申请文件、证券发行募集文件进行核查，向中国证监会、证券交易所出具保荐意见。保荐机构应当保证所出具的文件真实、准确、完整。 证券发行规模达到一定数量的，可以采用联合保荐，但参与联合保荐的保荐机构不得超过2家。 证券发行的主承销商可以由该保荐机构担任，也可以由其他具有保荐业务资格的证券公司与该保荐机构共同担任。"},{"i":8,"n":"第八条","txt":"发行人及其控股股东、实际控制人、董事、监事、高级管理人员，为证券发行上市制作、出具有关文件的律师事务所、会计师事务所、资产评估机构等证券服务机构及其签字人员，应当依照法律、行政法规和中国证监会、证券交易所的规定，配合保荐机构及其保荐代表人履行保荐职责，并承担相应的责任。 保荐机构及其保荐代表人履行保荐职责，不能减轻或者免除发行人及其控股股东、实际控制人、董事、监事、高级管理人员、证券服务机构及其签字人员的责任。"},{"i":9,"n":"第九条","txt":"中国证监会依法对保荐机构及其保荐代表人、其他从事保荐业务的人员进行监督管理。 证券交易所、中国证券业协会对保荐机构及其保荐代表人、其他从事保荐业务的人员进行自律管理。"},{"i":10,"n":"第十条","txt":"证券公司申请保荐业务资格，应当具备下列条件： （一）注册资本不低于人民币1亿元，净资本不低于人民币5000万元； （二）具有完善的公司治理和内部控制制度，风险控制指标符合相关规定； （三）保荐业务部门具有健全的业务规程、内部风险评估和控制系统，内部机构设置合理，具备相应的研究能力、销售能力等后台支持； （四）具有良好的保荐业务团队且专业结构合理，从业人员不少于35人，其中最近3年从事保荐相关业务的人员不少于20人； （五）保荐代表人不少于4人； （六）最近3年内未因重大违法违规行为受到行政处罚； （七）中国证监会规定的其他条件。"},{"i":11,"n":"第十一条","txt":"证券公司应当保证申请文件真实、准确、完整。申请期间，申请文件内容发生重大变化的，应当自变化之日起2个工作日内向中国证监会提交更新资料。"},{"i":12,"n":"第十二条","txt":"中国证监会依法受理、审查申请文件。对保荐业务资格的申请，自受理之日起3个月内做出核准或者不予核准的书面决定。"},{"i":13,"n":"第十三条","txt":"证券公司取得保荐业务资格后，应当持续符合本办法第十条规定的条件。保荐机构因重大违法违规行为受到行政处罚的，中国证监会撤销其保荐业务资格；不再具备第十条规定其他条件的，中国证监会可以责令其限期整改，逾期仍然不符合要求的，中国证监会撤销其保荐业务资格。"},{"i":14,"n":"第十四条","txt":"保荐机构出现下列情况的，应当在5个工作日内向其住所地的中国证监会派出机构报告： （一）保荐业务负责人、内核负责人、保荐业务部门负责人发生变化； （二）保荐业务部门机构设置发生重大变化； （三）保荐业务执业情况发生重大不利变化； （四）中国证监会要求的其他事项。"},{"i":15,"n":"第十五条","txt":"保荐机构应当在每一会计年度结束之日起4个月内向其住所地的中国证监会派出机构报送年度执业报告。年度执业报告应当包括以下内容： （一）保荐机构、保荐代表人年度执业情况的说明； （二）保荐机构对保荐代表人尽职调查工作日志检查情况的说明； （三）保荐机构对保荐代表人的年度考核、评定情况； （四）保荐机构、保荐代表人其他重大事项的说明； （五）保荐机构对年度执业报告真实性、准确性、完整性承担责任的承诺函，并应由其法定代表人签字； （六）中国证监会要求的其他事项。"},{"i":16,"n":"第十六条","txt":"保荐机构应当尽职推荐发行人证券发行上市。 发行人证券上市后，保荐机构应当持续督导发行人履行规范运作、信守承诺、信息披露等义务。"},{"i":17,"n":"第十七条","txt":"保荐机构推荐发行人证券发行上市，应当遵循诚实守信、勤勉尽责的原则，按照中国证监会对保荐机构尽职调查工作的要求，对发行人进行全面调查，充分了解发行人的经营状况及其面临的风险和问题。"},{"i":18,"n":"第十八条","txt":"保荐机构在推荐发行人首次公开发行股票并上市前，应当对发行人进行辅导。辅导内容包括，对发行人的董事、监事和高级管理人员、持有5%以上股份的股东和实际控制人（或者其法定代表人）进行系统的法规知识、证券市场知识培训，使其全面掌握发行上市、规范运作等方面的有关法律法规和规则，知悉信息披露和履行承诺等方面的责任和义务，树立进入证券市场的诚信意识、自律意识和法制意识，以及中国证监会规定的其他事项。"},{"i":19,"n":"第十九条","txt":"保荐机构辅导工作完成后，应当由发行人所在地的中国证监会派出机构进行辅导验收。发行人所在地在境外的，应当由发行人境内主营业地或境内证券事务机构所在地的中国证监会派出机构进行辅导验收。"},{"i":20,"n":"第二十条","txt":"保荐机构应当与发行人签订保荐协议，明确双方的权利和义务，按照行业规范协商确定履行保荐职责的相关费用。 保荐协议签订后，保荐机构应当在5个工作日内向承担辅导验收职责的中国证监会派出机构报告。"},{"i":21,"n":"第二十一条","txt":"保荐机构应当确信发行人符合法律、行政法规和中国证监会、证券交易所的有关规定，方可推荐其证券发行上市。 保荐机构决定推荐发行人证券发行上市的，可以根据发行人的委托，组织编制申请文件并出具推荐文件。"},{"i":22,"n":"第二十二条","txt":"对发行人申请文件、证券发行募集文件中有证券服务机构及其签字人员出具专业意见的内容，保荐机构可以合理信赖，对相关内容应当保持职业怀疑、运用职业判断进行分析，存在重大异常、前后重大矛盾，或者与保荐机构获得的信息存在重大差异的，保荐机构应当对有关事项进行调查、复核，并可聘请其他证券服务机构提供专业服务。"},{"i":23,"n":"第二十三条","txt":"对发行人申请文件、证券发行募集文件中无证券服务机构及其签字人员专业意见支持的内容，保荐机构应当获得充分的尽职调查证据，在对各种证据进行综合分析的基础上对发行人提供的资料和披露的内容进行独立判断，并有充分理由确信所作的判断与发行人申请文件、证券发行募集文件的内容不存在实质性差异。"},{"i":24,"n":"第二十四条","txt":"保荐机构推荐发行人发行证券，应当向中国证监会提交发行保荐书、保荐代表人专项授权书以及中国证监会要求的其他与保荐业务有关的文件。发行保荐书应当包括下列内容： （一）逐项说明本次发行是否符合《公司法》《证券法》规定的发行条件和程序； （二）逐项说明本次发行是否符合中国证监会的有关规定，并载明得出每项结论的查证过程及事实依据； （三）发行人存在的主要风险； （四）对发行人发展前景的评价； （五）保荐机构内部审核程序简介及内核意见； （六）保荐机构及其关联方与发行人及其关联方之间的利害关系及主要业务往来情况； （七）相关承诺事项； （八）中国证监会要求的其他事项。 在实施证券发行注册制的板块，保荐机构应当向证券交易所提交前款规定的与保荐业务有关的文件。"},{"i":25,"n":"第二十五条","txt":"保荐机构推荐发行人证券上市，应当向证券交易所提交上市保荐书以及证券交易所要求的其他与保荐业务有关的文件，并报中国证监会备案。上市保荐书应当包括下列内容： （一）逐项说明本次证券上市是否符合《公司法》《证券法》及证券交易所规定的上市条件； （二）对发行人证券上市后持续督导工作的具体安排； （三）保荐机构及其关联方与发行人及其关联方之间的利害关系及主要业务往来情况； （四）相关承诺事项； （五）中国证监会或者证券交易所要求的其他事项。 在实施证券发行注册制的板块，前款规定的与保荐业务有关文件的内容要求和报送要求由证券交易所具体规定。"},{"i":26,"n":"第二十六条","txt":"在发行保荐书和上市保荐书中，保荐机构应当就下列事项做出承诺： （一）有充分理由确信发行人符合法律法规及中国证监会有关证券发行上市的相关规定； （二）有充分理由确信发行人申请文件和信息披露资料不存在虚假记载、误导性陈述或者重大遗漏； （三）有充分理由确信发行人及其董事在申请文件和信息披露资料中表达意见的依据充分合理； （四）有充分理由确信申请文件和信息披露资料与证券服务机构发表的意见不存在实质性差异； （五）保证所指定的保荐代表人及本保荐机构的相关人员已勤勉尽责，对发行人申请文件和信息披露资料进行了尽职调查、审慎核查； （六）保证保荐书、与履行保荐职责有关的其他文件不存在虚假记载、误导性陈述或者重大遗漏； （七）保证对发行人提供的专业服务和出具的专业意见符合法律、行政法规、中国证监会的规定和行业规范； （八）自愿接受中国证监会依照本办法采取的监管措施； （九）中国证监会规定的其他事项。"},{"i":27,"n":"第二十七条","txt":"保荐机构提交发行保荐书后，应当配合中国证监会的审核，并承担下列工作： （一）组织发行人及证券服务机构对中国证监会的意见进行答复； （二）按照中国证监会的要求对涉及本次证券发行上市的特定事项进行尽职调查或者核查； （三）指定保荐代表人与中国证监会职能部门进行专业沟通，保荐代表人在发行审核委员会会议上接受委员质询； （四）中国证监会规定的其他工作。 在实施证券发行注册制的板块，保荐机构应当配合证券交易所、中国证监会的发行上市审核和注册工作，并按规定承担相应工作。"},{"i":28,"n":"第二十八条","txt":"保荐机构应当针对发行人的具体情况，确定证券发行上市后持续督导的内容，督导发行人履行有关上市公司规范运作、信守承诺和信息披露等义务，审阅信息披露文件及向中国证监会、证券交易所提交的其他文件，并承担下列工作： （一）督导发行人有效执行并完善防止控股股东、实际控制人、其他关联方违规占用发行人资源的制度； （二）督导发行人有效执行并完善防止其董事、监事、高级管理人员利用职务之便损害发行人利益的内控制度； （三）督导发行人有效执行并完善保障关联交易公允性和合规性的制度，并对关联交易发表意见； （四）持续关注发行人募集资金的专户存储、投资项目的实施等承诺事项； （五）持续关注发行人为他人提供担保等事项，并发表意见； （六）中国证监会、证券交易所规定及保荐协议约定的其他工作。"},{"i":29,"n":"第二十九条","txt":"首次公开发行股票并在主板上市的，持续督导的期间为证券上市当年剩余时间及其后2个完整会计年度；主板上市公司发行新股、可转换公司债券的，持续督导的期间为证券上市当年剩余时间及其后1个完整会计年度。 首次公开发行股票并在创业板、科创板上市的，持续督导的期间为证券上市当年剩余时间及其后3个完整会计年度；创业板、科创板上市公司发行新股、可转换公司债券的，持续督导的期间为证券上市当年剩余时间及其后2个完整会计年度。 首次公开发行股票并在创业板上市的，持续督导期内保荐机构应当自发行人披露年度报告、中期报告之日起15个工作日内在符合条件的媒体披露跟踪报告，对本办法第二十八条所涉及的事项，进行分析并发表独立意见。发行人临时报告披露的信息涉及募集资金、关联交易、委托理财、为他人提供担保等重大事项的，保荐机构应当自临时报告披露之日起10个工作日内进行分析并在符合条件的媒体发表独立意见。 持续督导的期间自证券"},{"i":30,"n":"第三十条","txt":"持续督导期届满，如有尚未完结的保荐工作，保荐机构应当继续完成。 保荐机构在履行保荐职责期间未勤勉尽责的，其责任不因持续督导期届满而免除或者终止。"},{"i":31,"n":"第三十一条","txt":"保荐机构应当建立分工合理、权责明确、相互制衡、有效监督的内部控制组织体系，发挥项目承做、质量控制、内核合规风控等的全流程内部控制作用，形成科学、合理、有效的保荐业务决策、执行和监督等机制，确保保荐业务纳入公司整体合规管理和风险控制范围。"},{"i":32,"n":"第三十二条","txt":"保荐机构应当建立健全并执行覆盖全部保荐业务流程和全体保荐业务人员的内部控制制度，包括但不限于立项制度、质量控制制度、问核制度、内核制度、反馈意见报告制度、风险事件报告制度、合规检查制度、应急处理制度等，定期对保荐业务内部控制的有效性进行全面评估，保证保荐业务负责人、内核负责人、保荐业务部门负责人、保荐代表人、项目协办人及其他保荐业务相关人员勤勉尽责，严格控制风险，提高保荐业务整体质量。"},{"i":33,"n":"第三十三条","txt":"保荐机构应当建立健全内部问责机制，明确保荐业务人员履职规范和问责措施。 保荐业务人员被采取自律监管措施、自律处分、行政监管措施、市场禁入措施、行政处罚、刑事处罚等的，保荐机构应当进行内部问责。 保荐机构应当在劳动合同、内部制度中明确，保荐业务人员出现前款情形的，应当退还相关违规行为发生当年除基本工资外的其他薪酬。"},{"i":34,"n":"第三十四条","txt":"保荐机构对外提交和报送的发行上市申请文件、反馈意见、披露文件等重要材料和文件应当履行内核程序，由内核机构审议决策。未通过内核程序的保荐业务项目不得以公司名义对外提交或者报送相关文件。"},{"i":35,"n":"第三十五条","txt":"保荐机构应当根据保荐业务特点制定科学、合理的薪酬考核体系，综合考量业务人员的专业胜任能力、执业质量、合规情况、业务收入等各项因素，不得以业务包干等承包方式开展保荐业务，或者以其他形式实施过度激励。"},{"i":36,"n":"第三十六条","txt":"保荐机构从事保荐业务应当综合评估项目执行成本与风险责任，合理确定报价，不得以明显低于行业定价水平等不正当竞争方式招揽业务。"},{"i":37,"n":"第三十七条","txt":"保荐机构应当建立健全保荐业务制度体系，细化尽职调查、辅导、文件申报、持续督导等各个环节的执业标准和操作流程，提高制度的针对性和执行性。 保荐机构应当根据监管要求、制度执行等情况，及时更新和完善保荐业务制度体系。"},{"i":38,"n":"第三十八条","txt":"保荐机构应当建立健全廉洁从业管理内控体系，加强对工作人员的管理，不得在开展保荐业务的过程中谋取或输送不当利益。"},{"i":39,"n":"第三十九条","txt":"保荐机构应当根据保荐业务类型和业务环节的不同，细化反洗钱要求，加强对客户身份的识别、可疑报告、客户资料及交易记录保存、反洗钱培训与宣传等工作。"},{"i":40,"n":"第四十条","txt":"保荐机构应当建立健全对保荐代表人及其他保荐业务相关人员的持续培训制度。"},{"i":41,"n":"第四十一条","txt":"保荐机构应当建立健全工作底稿制度，按规定建设应用工作底稿电子化管理系统。 保荐机构应当为每一项目建立独立的保荐工作底稿。保荐代表人必须为其具体负责的每一项目建立尽职调查工作日志，作为保荐工作底稿的一部分存档备查；保荐机构应当定期对尽职调查工作日志进行检查。 保荐工作底稿应当真实、准确、完整地反映保荐工作的全过程，保存期不少于20年。"},{"i":42,"n":"第四十二条","txt":"保荐机构及其控股股东、实际控制人、重要关联方持有发行人股份的，或者发行人持有、控制保荐机构股份的，保荐机构在推荐发行人证券发行上市时，应当进行利益冲突审查，出具合规审核意见，并按规定充分披露。通过披露仍不能消除影响的，保荐机构应联合1家无关联保荐机构共同履行保荐职责，且该无关联保荐机构为第一保荐机构。"},{"i":43,"n":"第四十三条","txt":"刊登证券发行募集文件前终止保荐协议的，保荐机构和发行人应当自终止之日起5个工作日内分别向中国证监会报告，并说明原因。 在实施证券发行注册制的板块出现上述情形的，保荐机构应同时向证券交易所报告。"},{"i":44,"n":"第四十四条","txt":"刊登证券发行募集文件以后直至持续督导工作结束，保荐机构和发行人不得终止保荐协议，但存在合理理由的情形除外。发行人因再次申请发行证券另行聘请保荐机构、保荐机构被中国证监会撤销保荐业务资格的，应当终止保荐协议。 终止保荐协议的，保荐机构和发行人应当自终止之日起5个工作日内向中国证监会、证券交易所报告，说明原因。"},{"i":45,"n":"第四十五条","txt":"持续督导期间，保荐机构被撤销保荐业务资格的，发行人应当在1个月内另行聘请保荐机构，未在规定期限内另行聘请的，中国证监会可以为其指定保荐机构。"},{"i":46,"n":"第四十六条","txt":"另行聘请的保荐机构应当完成原保荐机构未完成的持续督导工作。 因原保荐机构被撤销保荐业务资格而另行聘请保荐机构的，另行聘请的保荐机构持续督导的时间不得少于1个完整的会计年度。 另行聘请的保荐机构应当自保荐协议签订之日起开展保荐工作并承担相应的责任。原保荐机构在履行保荐职责期间未勤勉尽责的，其责任不因保荐机构的更换而免除或者终止。"},{"i":47,"n":"第四十七条","txt":"保荐机构应当指定2名保荐代表人具体负责1家发行人的保荐工作，出具由法定代表人签字的专项授权书，并确保保荐机构有关部门和人员有效分工协作。保荐机构可以指定1名项目协办人。"},{"i":48,"n":"第四十八条","txt":"证券发行后，保荐机构不得更换保荐代表人，但因保荐代表人离职或者不符合保荐代表人要求的，应当更换保荐代表人。 保荐机构更换保荐代表人的，应当通知发行人，并在5个工作日内向中国证监会、证券交易所报告，说明原因。原保荐代表人在具体负责保荐工作期间未勤勉尽责的，其责任不因保荐代表人的更换而免除或者终止。"},{"i":49,"n":"第四十九条","txt":"保荐机构法定代表人、保荐业务负责人、内核负责人、保荐业务部门负责人、保荐代表人和项目协办人应当在发行保荐书上签字，保荐机构法定代表人、保荐代表人应当同时在证券发行募集文件上签字。"},{"i":50,"n":"第五十条","txt":"保荐机构应当将履行保荐职责时发表的意见及时告知发行人，同时在保荐工作底稿中保存，并可以依照本办法规定公开发表声明、向中国证监会或者证券交易所报告。"},{"i":51,"n":"第五十一条","txt":"持续督导工作结束后，保荐机构应当在发行人公告年度报告之日起的10个工作日内向中国证监会、证券交易所报送保荐总结报告书。保荐机构法定代表人和保荐代表人应当在保荐总结报告书上签字。保荐总结报告书应当包括下列内容： （一）发行人的基本情况； （二）保荐工作概述； （三）履行保荐职责期间发生的重大事项及处理情况； （四）对发行人配合保荐工作情况的说明及评价； （五）对证券服务机构参与证券发行上市相关工作情况的说明及评价； （六）中国证监会、证券交易所要求的其他事项。"},{"i":52,"n":"第五十二条","txt":"保荐代表人及其他保荐业务相关人员属于内幕信息的知情人员，应当遵守法律、行政法规和中国证监会的规定，不得利用内幕信息直接或者间接为保荐机构、本人或者他人谋取不正当利益。"},{"i":53,"n":"第五十三条","txt":"发行人应当为保荐机构及时提供真实、准确、完整的财务会计资料和其他资料，全面配合保荐机构开展尽职调查和其他相关工作。 发行人的控股股东、实际控制人、董事、监事、高级管理人员应当全面配合保荐机构开展尽职调查和其他相关工作，不得要求或者协助发行人隐瞒应当披露的信息。"},{"i":54,"n":"第五十四条","txt":"保荐机构及其保荐代表人履行保荐职责，可以对发行人行使下列权利： （一）要求发行人按照本办法规定和保荐协议约定的方式，及时通报信息； （二）定期或者不定期对发行人进行回访，查阅保荐工作需要的发行人材料； （三）列席发行人的股东大会、董事会和监事会； （四）对发行人的信息披露文件及向中国证监会、证券交易所提交的其他文件进行事前审阅； （五）对有关部门关注的发行人相关事项进行核查，必要时可聘请相关证券服务机构配合； （六）按照中国证监会、证券交易所信息披露规定，对发行人违法违规的事项发表公开声明； （七）中国证监会、证券交易所规定或者保荐协议约定的其他权利。"},{"i":55,"n":"第五十五条","txt":"发行人有下列情形之一的，应当及时通知或者咨询保荐机构，并将相关文件送交保荐机构： （一）变更募集资金及投资项目等承诺事项； （二）发生关联交易、为他人提供担保等事项； （三）涉及重大诉讼、资产发生重大损失； （四）公司财务状况及生产经营的外部条件发生重大变化； （五）重大投资行为和重大购置资产的决定； （六）股东及董事、监事、高级管理人员的变动； （七）召开董事会、监事会、股东大会； （八）履行信息披露义务或者向中国证监会、证券交易所报告有关事项； （九）发生违法违规行为或者其他重大事项； （十）中国证监会、证券交易所规定或者保荐协议约定的其他事项。"},{"i":56,"n":"第五十六条","txt":"证券发行前，发行人及其控股股东、实际控制人、董事、监事、高级管理人员不配合保荐机构履行保荐职责的，保荐机构应当发表保留意见，并在发行保荐书中予以说明；情节严重的，应当不予保荐，已保荐的应当撤销保荐。"},{"i":57,"n":"第五十七条","txt":"证券发行后，保荐机构有充分理由确信发行人可能存在违法违规行为以及其他不当行为的，应当督促发行人作出说明并限期纠正；情节严重的，应当向中国证监会、证券交易所报告。"},{"i":58,"n":"第五十八条","txt":"保荐机构应当组织协调证券服务机构及其签字人员参与证券发行上市的相关工作。 发行人为证券发行上市聘用的会计师事务所、律师事务所、资产评估机构以及其他证券服务机构，保荐机构有充分理由认为其专业能力存在明显缺陷的，可以向发行人建议更换。"},{"i":59,"n":"第五十九条","txt":"保荐机构对证券服务机构及其签字人员出具的专业意见存有疑义的，应当主动与证券服务机构进行协商，并可要求其作出解释或者出具依据。"},{"i":60,"n":"第六十条","txt":"保荐机构有充分理由确信证券服务机构及其签字人员出具的专业意见可能存在虚假记载、误导性陈述或重大遗漏等违法违规情形或者其他不当情形的，应当及时发表意见；情节严重的，应当向中国证监会、证券交易所报告。"},{"i":61,"n":"第六十一条","txt":"证券服务机构及其签字人员应当严格按照依法制定的业务规则和行业自律规范，审慎履行职责，作出专业判断与认定，对保荐机构提出的疑义或者意见，应当保持专业独立性，进行审慎的复核判断，并向保荐机构、发行人及时发表意见。 证券服务机构应当建立并保持有效的质量控制体系，保护投资者合法权益。证券服务机构应当妥善保存客户委托文件、核查和验证资料、工作底稿以及与质量控制、内部管理、业务经营有关的信息和资料。"},{"i":62,"n":"第六十二条","txt":"中国证监会可以对保荐机构及其与发行上市保荐工作相关的人员，证券服务机构、发行人及其与证券发行上市工作相关的人员等进行定期或者不定期现场检查，相关主体应当积极配合检查，如实提供有关资料，不得拒绝、阻挠、逃避检查，不得谎报、隐匿、销毁相关证据材料。"},{"i":63,"n":"第六十三条","txt":"中国证监会对保荐机构及其相关人员进行持续动态的跟踪管理，记录其业务资格、执业情况、违法违规行为、其他不良行为以及对其采取的监管措施等。保荐信用记录向社会公开。"},{"i":64,"n":"第六十四条","txt":"证券公司提交的保荐业务资格申请文件存在虚假记载、误导性陈述或者重大遗漏的，中国证监会不予受理或者不予核准，并给予警告；已核准的，撤销其保荐业务资格。"},{"i":65,"n":"第六十五条","txt":"保荐机构、保荐代表人、保荐业务负责人、内核负责人、保荐业务部门负责人及其他保荐业务相关人员违反本办法，未诚实守信、勤勉尽责地履行相关义务的，中国证监会责令改正，并对其采取监管谈话、重点关注、责令进行业务学习、出具警示函、责令公开说明、认定为不适当人选、责令增加内部合规检查的次数并提交合规检查报告、责令处分有关责任人员并报告结果、对保荐机构及其有关董事、监事、高级管理人员给予谴责等监管措施；依法应给予行政处罚的，依照有关规定进行处罚；情节严重涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":66,"n":"第六十六条","txt":"出现下列情形之一的，中国证监会可以视情节轻重，采取责令改正、监管谈话、出具警示函等监管措施；情节严重的，中国证监会可以在3个月到12个月内不受理保荐机构、保荐代表人具体负责的推荐： （一）制作或者出具的文件不齐备或者不符合要求； （二）擅自改动申请文件、信息披露资料或者其他已提交文件； （三）申请文件或者信息披露资料存在相互矛盾或者同一事实表述不一致且有实质性差异； （四）文件披露的内容表述不清，逻辑混乱，严重影响投资者理解； （五）未及时报告或者未及时披露重大事项； （六）指定不符合本办法第四条规定要求的人员具体负责保荐工作； （七）未通过内核程序，以公司名义对外提交或披露保荐业务项目文件； （八）采取业务包干等承包方式或其他形式进行过度激励； （九）以显著低于行业定价水平等不正当竞争方式招揽业务，违反公平竞争、破坏市场秩序。"},{"i":67,"n":"第六十七条","txt":"保荐机构出现下列情形之一的，中国证监会可以视情节轻重，暂停保荐业务资格3个月到36个月，并可以责令保荐机构更换董事、监事、高级管理人员或者限制其权利；情节特别严重的，撤销其保荐业务资格： （一）向中国证监会、证券交易所提交的与保荐工作相关的文件存在虚假记载、误导性陈述或者重大遗漏； （二）重大事项未报告、未披露； （三）内部控制制度存在重大缺陷或者未有效执行； （四）尽职调查制度、内部核查制度、持续督导制度、保荐工作底稿制度等保荐业务制度存在重大缺陷或者未有效执行； （五）廉洁从业管理内控体系、反洗钱制度存在重大缺陷或者未有效执行； （六）保荐工作底稿存在虚假记载、误导性陈述或者重大遗漏； （七）唆使、协助或者参与发行人及证券服务机构提供存在虚假记载、误导性陈述或者重大遗漏的文件； （八）唆使、协助或者参与发行人干扰中国证监会及其发行审核委员会、证券交易所及其上市委员会的审核工作； （"},{"i":68,"n":"第六十八条","txt":"保荐代表人出现下列情形之一的，中国证监会可以根据情节轻重，在3个月到36个月内不受理相关保荐代表人具体负责的推荐；情节特别严重的，采取认定为不适当人选的监管措施： （一）尽职调查工作日志缺失或者遗漏、隐瞒重要问题； （二）未完成或者未参加辅导工作； （三）重大事项未报告、未披露； （四）未参加持续督导工作，或者持续督导工作未勤勉尽责； （五）因保荐业务或其具体负责保荐工作的发行人在保荐期间内受到证券交易所、中国证券业协会公开谴责； （六）唆使、协助或者参与发行人干扰中国证监会及其发行审核委员会、证券交易所及其上市委员会的审核工作； （七）伪造或者变造签字、盖章； （八）严重违反诚实守信、勤勉尽责义务的其他情形。"},{"i":69,"n":"第六十九条","txt":"保荐代表人出现下列情形之一的，中国证监会可以采取认定为不适当人选的监管措施；情节严重的，对其采取证券市场禁入的措施： （一）在与保荐工作相关文件上签字推荐发行人证券发行上市，但未参加尽职调查工作，或者尽职调查工作不彻底、不充分，明显不符合业务规则和行业规范； （二）通过从事保荐业务谋取不正当利益； （三）本人及其配偶持有发行人的股份； （四）唆使、协助或者参与发行人及证券服务机构提供存在虚假记载、误导性陈述或者重大遗漏的文件； （五）参与组织编制的与保荐工作相关文件存在虚假记载、误导性陈述或者重大遗漏。"},{"i":70,"n":"第七十条","txt":"发行人出现下列情形之一的，中国证监会可以暂停保荐机构的保荐业务资格12个月到36个月，责令保荐机构更换相关负责人，对保荐代表人采取认定为不适当人选的监管措施；情节严重的，撤销保荐业务资格，对相关责任人采取证券市场禁入的措施： （一）证券发行募集文件等申请文件存在虚假记载、误导性陈述或者重大遗漏； （二）持续督导期间信息披露文件存在虚假记载、误导性陈述或者重大遗漏。"},{"i":71,"n":"第七十一条","txt":"发行人公开发行证券上市当年即亏损的，中国证监会可以暂停保荐机构的保荐业务资格3个月，对保荐代表人采取认定为不适当人选的监管措施，尚未盈利的企业或者已在证券发行募集文件中充分分析并揭示相关风险的除外。 前款所称亏损或盈利，涉及的净利润以扣除非经常性损益前后孰低者为计算依据。"},{"i":72,"n":"第七十二条","txt":"发行人在持续督导期间出现下列情形之一的，中国证监会可以根据情节轻重，在3个月到12个月内不受理相关保荐代表人具体负责的推荐；情节特别严重的，对保荐代表人采取认定为不适当人选的监管措施： （一）证券上市当年累计50%以上募集资金的用途与承诺不符； （二）公开发行证券并在主板上市当年营业利润比上年下滑50%以上； （三）首次公开发行股票并上市之日起12个月内控股股东或者实际控制人发生变更； （四）首次公开发行股票并上市之日起12个月内累计50%以上资产或者主营业务发生重组； （五）上市公司公开发行新股、可转换公司债券之日起12个月内累计50%以上资产或者主营业务发生重组，且未在证券发行募集文件中披露； （六）实际盈利低于盈利预测达20%以上； （七）关联交易显失公允或者程序违规，涉及金额较大； （八）控股股东、实际控制人或其他关联方违规占用发行人资源，涉及金额较大； （九）违规为他人提供担"},{"i":73,"n":"第七十三条","txt":"保荐代表人被暂不受理具体负责的推荐或者被采取认定为不适当人选的监管措施的，对已受理的该保荐代表人具体负责推荐的项目，保荐机构应当更换保荐代表人，并指派与本项目无关的人员进行复核；对负有责任的保荐业务负责人、内核负责人、保荐业务部门负责人等人员，保荐机构应当根据内部管理规定进行问责惩戒，情节严重的，应当予以更换。"},{"i":74,"n":"第七十四条","txt":"保荐机构、保荐业务负责人、内核负责人或者保荐业务部门负责人在1个自然年度内被采取本办法第六十五条规定的监管措施累计5次以上，中国证监会可以暂停保荐机构的保荐业务资格3个月，责令保荐机构更换保荐业务负责人、内核负责人或者保荐业务部门负责人。 保荐代表人在2个自然年度内被采取本办法第六十五条规定的监管措施累计2次以上，中国证监会可以6个月内不受理相关保荐代表人具体负责的推荐。"},{"i":75,"n":"第七十五条","txt":"对中国证监会拟采取的监管措施，保荐机构及其保荐代表人提出申辩的，如有充分证据证明下列事实且理由成立，中国证监会予以采纳： （一）发行人或者其董事、监事、高级管理人员故意隐瞒重大事实，保荐机构和保荐代表人已履行勤勉尽责义务； （二）发行人已在证券发行募集文件中做出特别提示，保荐机构和保荐代表人已履行勤勉尽责义务； （三）发行人因不可抗力致使业绩、募集资金运用等出现异常或者未能履行承诺； （四）发行人及其董事、监事、高级管理人员在持续督导期间故意违法违规，保荐机构和保荐代表人主动予以揭示，已履行勤勉尽责义务； （五）保荐机构、保荐代表人已履行勤勉尽责义务的其他情形。"},{"i":76,"n":"第七十六条","txt":"发行人违反本办法规定，持续督导期间违法违规且拒不纠正，发生重大事项未及时通知保荐机构，出现应当变更保荐机构情形未及时予以变更，或者发生其他严重不配合保荐工作情形的，中国证监会可以责令改正，予以公布并可以根据情节轻重采取下列监管措施： （一）要求发行人每月向中国证监会报告接受保荐机构督导的情况； （二）要求发行人披露月度财务报告、相关资料； （三）指定证券服务机构进行核查； （四）要求证券交易所对发行人证券的交易实行特别提示； （五）36个月内不受理其发行证券申请； （六）将直接负责的主管人员和其他责任人员认定为不适当人选。"},{"i":77,"n":"第七十七条","txt":"发行人及其控股股东、实际控制人、董事、监事、高级管理人员未有效配合保荐机构及其保荐代表人开展尽职调查和其他相关工作的，中国证监会可以责令改正，并对相关单位和责任人员采取监管谈话、重点关注、出具警示函、责令公开说明等监管措施。情节严重的，采取12个月到60个月内不接受相关单位及其控制的下属单位公开发行证券相关文件，对责任人采取认定为不适当人选等监管措施，或者采取证券市场禁入的措施。"},{"i":78,"n":"第七十八条","txt":"证券服务机构及其签字人员违反本办法规定的，中国证监会可以责令改正，并对相关机构和责任人员采取监管谈话、重点关注、出具警示函、责令公开说明、认定为不适当人选等监管措施。"},{"i":79,"n":"第七十九条","txt":"证券服务机构及其签字人员出具的专业意见存在虚假记载、误导性陈述或重大遗漏，或者因不配合保荐工作而导致严重后果的，中国证监会可以在6个月到36个月内不受理其文件，并将处理结果予以公布。"},{"i":80,"n":"第八十条","txt":"发行人及其控股股东、实际控制人、董事、监事、高级管理人员、证券服务机构及其签字人员违反法律、行政法规，依法应予行政处罚的，依照有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":81,"n":"第八十一条","txt":"股票公开转让的公众公司向全国中小企业股份转让系统不特定合格投资者公开发行股票后挂牌的，全国中小企业股份转让系统可以参照本办法关于证券交易所的规定制定相关规则。"},{"i":82,"n":"第八十二条","txt":"本办法所称“保荐机构”，是指《证券法》第十条所指“保荐人”。"},{"i":83,"n":"第八十三条","txt":"本办法自公布之日起施行。2008年10月17日发布的《证券发行上市保荐业务管理办法》（证监会令第58号）同时废止。"}],"zhengquanfaxingyuchengxiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范证券发行与承销行为，保护投资者合法权益，根据《证券法》和《公司法》，制定本办法。"},{"i":2,"n":"第二条","txt":"发行人在境内发行股票、存托凭证或者可转换公司债券（以下统称证券），证券公司在境内承销证券以及投资者认购境内发行的证券，适用本办法。中国证监会另有规定的，从其规定。 存托凭证境外基础证券发行人应履行本办法中发行人、上市公司的义务，承担相应的法律责任，境内发行与承销存托凭证适用本办法中关于发行与承销股票的相关规定，但本办法对存托凭证另有规定的除外。 首次公开发行股票时公司股东公开发售其所持股份（以下简称老股转让）的，还应当符合中国证券监督管理委员会（以下简称中国证监会）的相关规定。"},{"i":3,"n":"第三条","txt":"中国证监会依法对证券发行与承销行为进行监督管理。证券交易所、证券登记结算机构和中国证券业协会应当制定相关业务规则（以下简称相关规则），规范证券发行与承销行为。证券公司承销证券，应当依据本办法以及中国证监会有关风险控制和内部控制等相关规定，制定严格的风险管理制度和内部控制制度，加强定价和配售过程管理，落实承销责任。 为证券发行出具相关文件的证券服务机构和人员，应当按照本行业公认的业务标准和道德规范，严格履行法定职责，对其所出具文件的真实性、准确性和完整性承担责任。"},{"i":4,"n":"第四条","txt":"首次公开发行股票，可以通过向网下投资者询价的方式确定股票发行价格，也可以通过发行人与主承销商自主协商直接定价等其他合法可行的方式确定发行价格。公开发行股票数量在2000万股（含）以下且无老股转让计划的，可以通过直接定价的方式确定发行价格。发行人和主承销商应当在招股意向书（或招股说明书，下同）和发行公告中披露本次发行股票的定价方式。上市公司发行证券的定价，应当符合中国证监会关于上市公司证券发行的有关规定。"},{"i":5,"n":"第五条","txt":"首次公开发行股票，网下投资者须具备丰富的投资经验和良好的定价能力，应当接受中国证券业协会的自律管理，遵守中国证券业协会的自律规则。 网下投资者参与报价时，应当持有一定金额的非限售股份或存托凭证。发行人和主承销商可以根据自律规则，设置网下投资者的具体条件，并在发行公告中预先披露。主承销商应当对网下投资者是否符合预先披露的条件进行核查，对不符合条件的投资者，应当拒绝或剔除其报价。"},{"i":6,"n":"第六条","txt":"首次公开发行股票采用询价方式定价的，符合条件的网下机构和个人投资者可以自主决定是否报价，主承销商无正当理由不得拒绝。网下投资者应当遵循独立、客观、诚信的原则合理报价，不得协商报价或者故意压低、抬高价格。 网下投资者报价应当包含每股价格和该价格对应的拟申购股数，且只能有一个报价。非个人投资者应当以机构为单位进行报价。首次公开发行股票价格（或发行价格区间）确定后，提供有效报价的投资者方可参与申购。"},{"i":7,"n":"第七条","txt":"首次公开发行股票采用询价方式的，网下投资者报价后，发行人和主承销商应当剔除拟申购总量中报价最高的部分，剔除部分不得低于所有网下投资者拟申购总量的10%，然后根据剩余报价及拟申购数量协商确定发行价格。剔除部分不得参与网下申购。 公开发行股票数量在4亿股（含）以下的，有效报价投资者的数量不少于10家；公开发行股票数量在4亿股以上的，有效报价投资者的数量不少于20家。剔除最高报价部分后有效报价投资者数量不足的，应当中止发行。"},{"i":8,"n":"第八条","txt":"首次公开发行股票时，发行人和主承销商可以自主协商确定参与网下询价投资者的条件、有效报价条件、配售原则和配售方式，并按照事先确定的配售原则在有效申购的网下投资者中选择配售股票的对象。"},{"i":9,"n":"第九条","txt":"首次公开发行股票采用直接定价方式的，全部向网上投资者发行，不进行网下询价和配售。 首次公开发行股票采用询价方式的，公开发行后总股本在4亿股（含）以下的，网下初始发行比例不低于本次公开发行股票数量的60%；公开发行后总股本超过4亿股的，网下初始发行比例不低于本次公开发行股票数量的70%。其中，应当安排不低于本次网下发行股票数量的40%优先向通过公开募集方式设立的证券投资基金（以下简称公募基金）、全国社会保障基金（以下简称社保基金）和基本养老保险基金（以下简称养老金）配售，安排一定比例的股票向根据《企业年金基金管理办法》设立的企业年金基金和符合《保险资金运用管理暂行办法》等相关规定的保险资金（以下简称保险资金）配售。公募基金、社保基金、养老金、企业年金基金和保险资金有效申购不足安排数量的，发行人和主承销商可以向其他符合条件的网下投资者配售剩余部分。 对网下投资者进行分类配售的，同类投资者获"},{"i":10,"n":"第十条","txt":"首次公开发行股票网下投资者申购数量低于网下初始发行量的，发行人和主承销商不得将网下发行部分向网上回拨，应当中止发行。 网上投资者有效申购倍数超过50倍、低于100倍（含）的，应当从网下向网上回拨，回拨比例为本次公开发行股票数量的20%；网上投资者有效申购倍数超过100倍的，回拨比例为本次公开发行股票数量的40%；网上投资者有效申购倍数超过150倍的，回拨后无锁定期网下发行比例不超过本次公开发行股票数量的10%。本款所指公开发行股票数量应按照扣除设定限售期的股票数量计算。 网上投资者申购数量不足网上初始发行量的，可回拨给网下投资者。"},{"i":11,"n":"第十一条","txt":"首次公开发行股票，持有一定数量非限售股份或存托凭证的投资者才能参与网上申购。网上投资者应当自主表达申购意向，不得全权委托证券公司进行新股申购。采用其他方式进行网上申购和配售的，应当符合中国证监会的有关规定。"},{"i":12,"n":"第十二条","txt":"首次公开发行股票的网下发行应和网上发行同时进行，网下和网上投资者在申购时无需缴付申购资金。投资者应当自行选择参与网下或网上发行，不得同时参与。 发行人股东拟进行老股转让的，发行人和主承销商应于网下网上申购前协商确定发行价格、发行数量和老股转让数量。采用询价方式且无老股转让计划的，发行人和主承销商可以通过网下询价确定发行价格或发行价格区间。网上投资者申购时仅公告发行价格区间、未确定发行价格的，主承销商应当安排投资者按价格区间上限申购。"},{"i":13,"n":"第十三条","txt":"网下和网上投资者申购新股、可转换公司债券、可交换公司债券获得配售后，应当按时足额缴付认购资金。网上投资者连续12个月内累计出现3次中签后未足额缴款的情形时，6个月内不得参与新股、可转换公司债券、可交换公司债券申购。 网下和网上投资者缴款认购的新股或可转换公司债券数量合计不足本次公开发行数量的70%时，可以中止发行。 除本办法规定的中止发行情形外，发行人和主承销商还可以约定中止发行的其他具体情形并事先披露。中止发行后，在核准文件有效期内，经向中国证监会备案，可重新启动发行。"},{"i":14,"n":"第十四条","txt":"首次公开发行股票数量在4亿股以上的，可以向战略投资者配售。发行人应当与战略投资者事先签署配售协议。 发行人和主承销商应当在发行公告中披露战略投资者的选择标准、向战略投资者配售的股票总量、占本次发行股票的比例以及持有期限等。 战略投资者不参与网下询价，且应当承诺获得本次配售的股票持有期限不少于12个月，持有期自本次公开发行的股票上市之日起计算。 根据《关于开展创新企业境内发行股票或存托凭证试点的若干意见》认定的试点企业在境内发行股票或存托凭证的，根据需要向战略投资者配售。"},{"i":15,"n":"第十五条","txt":"首次公开发行股票数量在4亿股以上的，发行人和主承销商可以在发行方案中采用超额配售选择权。超额配售选择权的实施应当遵守中国证监会、证券交易所、证券登记结算机构和中国证券业协会的规定。 根据《关于开展创新企业境内发行股票或存托凭证试点的若干意见》认定的试点企业在境内发行股票或存托凭证的，根据需要采用超额配售选择权。"},{"i":16,"n":"第十六条","txt":"首次公开发行股票网下配售时，发行人和主承销商不得向下列对象配售股票： （一）发行人及其股东、实际控制人、董事、监事、高级管理人员和其他员工；发行人及其股东、实际控制人、董事、监事、高级管理人员能够直接或间接实施控制、共同控制或施加重大影响的公司，以及该公司控股股东、控股子公司和控股股东控制的其他子公司； （二）主承销商及其持股比例5%以上的股东，主承销商的董事、监事、高级管理人员和其他员工；主承销商及其持股比例5%以上的股东、董事、监事、高级管理人员能够直接或间接实施控制、共同控制或施加重大影响的公司，以及该公司控股股东、控股子公司和控股股东控制的其他子公司； （三）承销商及其控股股东、董事、监事、高级管理人员和其他员工； （四）本条第（一）、（二）、（三）项所述人士的关系密切的家庭成员，包括配偶、子女及其配偶、父母及配偶的父母、兄弟姐妹及其配偶、配偶的兄弟姐妹、子女配偶的父母； （五"},{"i":17,"n":"第十七条","txt":"发行人和承销商及相关人员不得泄露询价和定价信息；不得以任何方式操纵发行定价；不得劝诱网下投资者抬高报价，不得干扰网下投资者正常报价和申购；不得以提供透支、回扣或者中国证监会认定的其他不正当手段诱使他人申购股票；不得以代持、信托持股等方式谋取不正当利益或向其他相关利益主体输送利益；不得直接或通过其利益相关方向参与认购的投资者提供财务资助或者补偿；不得以自有资金或者变相通过自有资金参与网下配售；不得与网下投资者互相串通，协商报价和配售；不得收取网下投资者回扣或其他相关利益。"},{"i":18,"n":"第十八条","txt":"上市公司发行证券，存在利润分配方案、公积金转增股本方案尚未提交股东大会表决或者虽经股东大会表决通过但未实施的，应当在方案实施后发行。相关方案实施前，主承销商不得承销上市公司发行的证券。"},{"i":19,"n":"第十九条","txt":"上市公司向原股东配售股票（以下简称配股），应当向股权登记日登记在册的股东配售，且配售比例应当相同。 上市公司向不特定对象公开募集股份（以下简称增发）或者发行可转换公司债券，可以全部或者部分向原股东优先配售，优先配售比例应当在发行公告中披露。 网上投资者在申购可转换公司债券时无需缴付申购资金。"},{"i":20,"n":"第二十条","txt":"上市公司增发或者发行可转换公司债券，主承销商可以对参与网下配售的机构投资者进行分类，对不同类别的机构投资者设定不同的配售比例，对同一类别的机构投资者应当按相同的比例进行配售。主承销商应当在发行公告中明确机构投资者的分类标准。 主承销商未对机构投资者进行分类的，应当在网下配售和网上发行之间建立回拨机制，回拨后两者的获配比例应当一致。"},{"i":21,"n":"第二十一条","txt":"上市公司非公开发行证券的，发行对象及其数量的选择应当符合中国证监会关于上市公司证券发行的相关规定。"},{"i":22,"n":"第二十二条","txt":"发行人和主承销商应当签订承销协议，在承销协议中界定双方的权利义务关系，约定明确的承销基数。采用包销方式的，应当明确包销责任；采用代销方式的，应当约定发行失败后的处理措施。 证券发行依照法律、行政法规的规定应由承销团承销的，组成承销团的承销商应当签订承销团协议，由主承销商负责组织承销工作。证券发行由两家以上证券公司联合主承销的，所有担任主承销商的证券公司应当共同承担主承销责任，履行相关义务。承销团由3家以上承销商组成的，可以设副主承销商，协助主承销商组织承销活动。 承销团成员应当按照承销团协议及承销协议的规定进行承销活动，不得进行虚假承销。"},{"i":23,"n":"第二十三条","txt":"证券公司承销证券，应当依照《证券法》第二十八条的规定采用包销或者代销方式。上市公司非公开发行股票未采用自行销售方式或者上市公司配股的，应当采用代销方式。"},{"i":24,"n":"第二十四条","txt":"股票发行采用代销方式的，应当在发行公告（或认购邀请书）中披露发行失败后的处理措施。股票发行失败后，主承销商应当协助发行人按照发行价并加算银行同期存款利息返还股票认购人。"},{"i":25,"n":"第二十五条","txt":"证券公司实施承销前，应当向中国证监会报送发行与承销方案。"},{"i":26,"n":"第二十六条","txt":"上市公司发行证券期间相关证券的停复牌安排，应当遵守证券交易所的相关规则。 主承销商应当按有关规定及时划付申购资金冻结利息。"},{"i":27,"n":"第二十七条","txt":"投资者申购缴款结束后，发行人和主承销商应当聘请具有证券、期货相关业务资格的会计师事务所对申购和募集资金进行验证，并出具验资报告；还应当聘请律师事务所对网下发行过程、配售行为、参与定价和配售的投资者资质条件及其与发行人和承销商的关联关系、资金划拨等事项进行见证，并出具专项法律意见书。证券上市后10日内，主承销商应当将验资报告、专项法律意见随同承销总结报告等文件一并报中国证监会。"},{"i":28,"n":"第二十八条","txt":"发行人和主承销商在发行过程中，应当按照中国证监会规定的要求编制信息披露文件，履行信息披露义务。发行人和承销商在发行过程中披露的信息，应当真实、准确、完整、及时，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":29,"n":"第二十九条","txt":"首次公开发行股票申请文件受理后至发行人发行申请经中国证监会核准、依法刊登招股意向书前，发行人及与本次发行有关的当事人不得采取任何公开方式或变相公开方式进行与股票发行相关的推介活动，也不得通过其他利益关联方或委托他人等方式进行相关活动。"},{"i":30,"n":"第三十条","txt":"首次公开发行股票招股意向书刊登后，发行人和主承销商可以向网下投资者进行推介和询价，并通过互联网等方式向公众投资者进行推介。 发行人和主承销商向公众投资者进行推介时，向公众投资者提供的发行人信息的内容及完整性应与向网下投资者提供的信息保持一致。"},{"i":31,"n":"第三十一条","txt":"发行人和主承销商在推介过程中不得夸大宣传，或以虚假广告等不正当手段诱导、误导投资者，不得披露除招股意向书等公开信息以外的发行人其他信息。 承销商应当保留推介、定价、配售等承销过程中的相关资料至少三年并存档备查，包括推介宣传材料、路演现场录音等，如实、全面反映询价、定价和配售过程。"},{"i":32,"n":"第三十二条","txt":"发行人和主承销商在发行过程中公告的信息只需选择一家中国证监会指定的报刊披露，同时将其刊登在中国证监会指定的互联网网站，并置备于中国证监会指定的场所，供公众查阅。"},{"i":33,"n":"第三十三条","txt":"发行人披露的招股意向书除不含发行价格、筹资金额以外，其内容与格式应当与招股说明书一致，并与招股说明书具有同等法律效力。"},{"i":34,"n":"第三十四条","txt":"首次公开发行股票的发行人和主承销商应当在发行和承销过程中公开披露以下信息： （一）招股意向书刊登首日在发行公告中披露发行定价方式、定价程序、参与网下询价投资者条件、股票配售原则、配售方式、有效报价的确定方式、中止发行安排、发行时间安排和路演推介相关安排等信息；发行人股东拟老股转让的，还应披露预计老股转让的数量上限，老股转让股东名称及各自转让老股数量，并明确新股发行与老股转让数量的调整机制。 （二）网上申购前披露每位网下投资者的详细报价情况，包括投资者名称、申购价格及对应的拟申购数量；剔除最高报价有关情况；剔除最高报价部分后网下投资者报价的中位数和加权平均数以及公募基金报价的中位数和加权平均数；有效报价和发行价格（或发行价格区间）的确定过程；发行价格（或发行价格区间）及对应的市盈率；网下网上的发行方式和发行数量；回拨机制；中止发行安排；申购缴款要求等。已公告老股转让方案的，还应披露老股转"},{"i":35,"n":"第三十五条","txt":"发行人和主承销商在披露发行市盈率时，应同时披露发行市盈率的计算方式。在进行行业市盈率比较分析时，应当按照中国证监会有关上市公司行业分类指引中制定的行业分类标准确定发行人行业归属，并分析说明行业归属的依据。存在多个市盈率口径时，应当充分列示可供选择的比较基准，并应当按照审慎、充分提示风险的原则选取和披露行业平均市盈率。发行人还可以同时披露市净率等反映发行人所在行业特点的估值指标。 发行人尚未盈利的，可以不披露发行市盈率及与同行业市盈率比较的相关信息，应当披露市销率、市净率等反映发行人所在行业特点的估值指标。"},{"i":36,"n":"第三十六条","txt":"中国证监会对证券发行承销过程实施事中事后监管，发现涉嫌违法违规或者存在异常情形的，可责令发行人和承销商暂停或中止发行，对相关事项进行调查处理。"},{"i":37,"n":"第三十七条","txt":"中国证券业协会应当建立对承销商询价、定价、配售行为和网下投资者报价行为的日常监管制度，加强相关行为的监督检查，发现违规情形的，应当及时采取自律监管措施。中国证券业协会还应当建立对网下投资者和承销商的跟踪分析和评价体系，并根据评价结果采取奖惩措施。"},{"i":38,"n":"第三十八条","txt":"发行人、证券公司、证券服务机构、投资者及其直接负责的主管人员和其他直接责任人员有失诚信、违反法律、行政法规或者本办法规定的，中国证监会可以视情节轻重采取责令改正、监管谈话、出具警示函、责令公开说明、认定为不适当人选等监管措施，或者采取市场禁入措施，并记入诚信档案；依法应予行政处罚的，依照有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":39,"n":"第三十九条","txt":"证券公司承销未经核准擅自公开发行的证券的，依照《证券法》第一百九十条的规定处罚。 证券公司承销证券有前款所述情形的，中国证监会可以采取12至36个月暂不受理其证券承销业务有关文件的监管措施。"},{"i":40,"n":"第四十条","txt":"证券公司及其直接负责的主管人员和其他直接责任人员在承销证券过程中，有下列行为之一的，中国证监会可以采取本办法第三十八条规定的监管措施；情节比较严重的，还可以采取3至12个月暂不受理其证券承销业务有关文件的监管措施；依法应予行政处罚的，依照《证券法》第一百九十一条的规定予以处罚： （一）夸大宣传，或以虚假广告等不正当手段诱导、误导投资者； （二）以不正当竞争手段招揽承销业务； （三）从事本办法第十七条规定禁止的行为； （四）向不符合本办法第五条规定的网下投资者配售股票，或向本办法第十六条规定禁止配售的对象配售股票； （五）未按本办法要求披露有关文件； （六）未按照事先披露的原则和方式配售股票，或其他未依照披露文件实施的行为； （七）向投资者提供除招股意向书等公开信息以外的发行人其他信息； （八）未按照本办法要求保留推介、定价、配售等承销过程中相关资料； （九）其他违反证券承销业务规定的行"},{"i":41,"n":"第四十一条","txt":"发行人及其直接负责的主管人员和其他直接责任人员有下列行为之一的，中国证监会可以采取本办法第三十八条规定的监管措施；构成违反《证券法》相关规定的，依法进行行政处罚： （一）从事本办法第十七条规定禁止的行为； （二）夸大宣传，或以虚假广告等不正当手段诱导、误导投资者； （三）向投资者提供除招股意向书等公开信息以外的发行人信息； （四）中国证监会认定的其他情形。"},{"i":42,"n":"第四十二条","txt":"其他证券的发行与承销比照本办法执行。中国证监会另有规定的，从其规定。"},{"i":43,"n":"第四十三条","txt":"本办法自2013年12月13日起施行。2006年9月17日发布并于2010年10月11日、2012年5月18日修改的《证券发行与承销管理办法》同时废止。"}],"zhengquanjijinjingyingjigouxinxijishuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强证券基金经营机构信息技术管理，保障证券基金行业信息系统安全、合规运行，保护投资者合法权益，根据《证券法》、《证券投资基金法》、《证券公司监督管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"证券基金经营机构借助信息技术手段从事证券基金业务活动，信息技术服务机构为证券基金业务活动提供信息技术服务，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称证券基金经营机构，是指经中国证监会批准在境内设立的证券公司和管理公开募集基金的基金管理公司（以下简称基金管理公司）。 本办法所称信息技术服务机构，是指为证券基金业务活动提供信息技术服务的机构。信息技术服务的范围如下： （一）重要信息系统的开发、测试、集成及测评； （二）重要信息系统的运维及日常安全管理； （三）中国证监会规定的其他情形。 以上机构统称证券基金经营与服务机构。"},{"i":4,"n":"第四条","txt":"证券基金经营机构是从事证券基金业务活动的责任主体，应当保障充足的信息技术投入，在依法合规、有效防范风险的前提下，充分利用现代信息技术手段完善客户服务体系、改进业务运营模式、提升内部管理水平、增强合规风控能力，持续强化现代信息技术对证券基金业务活动的支撑作用。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依法对证券基金经营与服务机构借助信息技术手段从事证券基金业务活动或提供相关服务实施监督管理。 中国证券业协会及中国证券投资基金业协会依照本办法制定和完善相关自律规则，对证券基金经营机构借助信息技术手段从事证券基金业务活动或提供相关服务实施自律管理。 中证信息技术服务有限责任公司（以下简称中证信息）在中国证监会指导下制定相关配套业务规则，协助开展信息技术相关备案、监测、检测和检查等工作。"},{"i":6,"n":"第六条","txt":"证券基金经营机构应当完善信息技术运用过程中的权责分配机制，建立健全信息技术管理制度和操作流程，保障与业务活动规模及复杂程度相适应的信息技术投入水平，持续满足信息技术资源的可用性、安全性与合规性要求。"},{"i":7,"n":"第七条","txt":"证券基金经营机构董事会负责审议本公司的信息技术管理目标，对信息技术管理的有效性承担责任, 履行下列职责： （一）审议信息技术战略，确保与本公司的发展战略、风险管理策略、资本实力相一致； （二）建立信息技术人力和资金保障方案； （三）评估年度信息技术管理工作的总体效果和效率； （四）公司章程规定的其他信息技术管理职责。"},{"i":8,"n":"第八条","txt":"证券基金经营机构经营管理层负责落实信息技术管理目标，对信息技术管理工作承担责任，履行下列职责： （一）组织实施董事会相关决议； （二）建立责任明确、程序清晰的信息技术管理组织架构，明确管理职责、工作程序和协调机制； （三）完善绩效考核和责任追究机制； （四）公司章程规定或董事会授权的其他信息技术管理职责。"},{"i":9,"n":"第九条","txt":"证券基金经营机构应当在公司管理层下设立信息技术治理委员会或指定专门委员会（以下统称信息技术治理委员会）负责制定信息技术战略并审议下列事项： （一）信息技术规划，包括但不限于信息技术建设规划、信息安全规划、数据治理规划等； （二）信息技术投入预算及分配方案； （三）重要信息系统建设或重大改造立项、重大变更方案； （四）信息技术应急预案； （五）使用信息技术手段开展相关业务活动的审查报告以及年度评估报告； （六）信息技术治理委员会委员提请审议的事项； （七）其他对信息技术管理产生重大影响的事项。 信息技术治理委员会应当由高级管理人员以及合规管理部门、风险管理部门、稽核审计部门、主要业务部门、信息技术管理部门等部门负责人组成，可聘请外部专业人员担任信息技术治理委员会委员或顾问。"},{"i":10,"n":"第十条","txt":"证券基金经营机构应当指定一名熟悉证券、基金业务，具有信息技术相关专业背景、任职经历、履职能力的高级管理人员为首席信息官，由其负责信息技术管理工作，并具备下列任职条件： （一）从事信息技术相关工作十年以上，或者在证券监管机构、证券基金业自律组织任职八年以上； （二）最近三年未被金融监管机构实施行政处罚或采取重大行政监管措施； （三）中国证监会规定的其他条件。"},{"i":11,"n":"第十一条","txt":"证券基金经营机构应当设立信息技术管理部门或指定专门机构（以下统称信息技术管理部门）负责实施信息技术规划、信息系统建设、信息技术质量控制、信息安全保障、运维管理等工作。"},{"i":12,"n":"第十二条","txt":"证券基金经营机构应当将信息技术运用情况纳入合规与风险管理体系，为合规管理部门和风险管理部门配备与业务活动规模、复杂程度相适应的信息技术资源，并建立相应的审查、监测和检查机制，确保合规与风险管理覆盖信息技术运用的各个环节。"},{"i":13,"n":"第十三条","txt":"证券基金经营机构借助信息技术手段从事证券基金业务活动的，应当在业务系统上线时，同步上线与业务活动复杂程度和风险状况相适应的风险管理系统或相关功能（以下统称风险管理系统），对风险进行识别、监控、预警和干预。"},{"i":14,"n":"第十四条","txt":"证券基金经营机构借助信息技术手段从事证券基金业务活动前，应当开展内部审查，验证下列事项并建立存档记录： （一）业务系统的流程设计、功能设置、参数配置和技术实现应当遵循业务合规的原则，不得违反法律法规及中国证监会的规定； （二）风险管理系统功能完备、权限清晰，能够与业务系统同步上线运行； （三）具备完善的信息安全防护措施，能够保障经营数据和客户信息的安全、完整； （四）具备符合要求的信息系统备份及运维管理能力，能够保障相关系统安全、平稳运行。"},{"i":15,"n":"第十五条","txt":"证券基金经营机构应当识别借助信息技术手段从事证券基金业务活动的各类风险，建立持续有效的风险监测机制。证券基金经营机构应当及时、稳妥处置发现的风险问题，并至少每年开展一次风险监测机制及执行情况的有效性评估。"},{"i":16,"n":"第十六条","txt":"证券基金经营机构应当定期开展信息技术管理工作专项审计，频率不低于每年一次，确保三年内完成信息技术管理全部事项的审计工作，包括但不限于信息技术治理、信息技术合规与风险管理、信息技术安全管理、应急管理。 证券基金经营机构应当委托外部专业机构开展信息技术管理工作的全面审计，频率不低于每三年一次；未能有效实施信息技术管理被采取行政处罚措施、监管措施或者自律管理措施的，应当在三个月内完成对有关事项的专项审计。 证券基金经营机构应当跟踪审计发现问题的整改情况，相关问题未能及时整改的，应当说明理由，并将审计报告提交信息技术治理委员会审议。证券基金经营机构应当妥善保存审计报告，保存期限不得少于二十年。"},{"i":17,"n":"第十七条","txt":"除法律法规及中国证监会另有规定外，证券基金经营机构应当通过自身运营管理的信息系统直接接收客户交易指令，并记录客户交易指令接收时间。"},{"i":18,"n":"第十八条","txt":"证券基金经营机构应当按照中国证监会有关规定采集、记录、存储、报送客户交易终端信息，并采取有效的技术措施，保障相关信息真实、准确、完整。 证券基金经营机构借助专业化交易信息系统向特定客户提供交易服务的，应当要求客户登记交易终端信息；信息发生变更的，应当要求客户履行变更程序，确保客户真实使用的客户交易终端信息与登记内容一致。"},{"i":19,"n":"第十九条","txt":"证券基金经营机构使用电子合同从事证券基金业务活动的，应当将电子合同存储在指定的信息系统，并提供可供投资者及合同其他相关方查询、下载的公开渠道。"},{"i":20,"n":"第二十条","txt":"证券基金经营机构从事证券交易相关业务，应当按照监管规定及自律管理规则的要求，确保风险管理系统具备审查账户资金及证券是否充足、监控交易及资金划转是否异常等功能。"},{"i":21,"n":"第二十一条","txt":"证券基金经营机构应当建立独立于生产环境的专用开发测试环境，避免风险传导；开发测试环境使用未脱敏数据的，应当采取与生产环境同等的安全控制措施。 证券基金经营机构在生产环境开展重要信息系统技术或业务测试的，应对测试流程及结果进行审查。"},{"i":22,"n":"第二十二条","txt":"证券基金经营机构重要信息系统上线或发生重大变更的，应当制定专项实施方案，并对信息系统上线或变更操作行为进行审查、确认和跟踪。 证券基金经营机构重要信息系统计划停止使用的，应当开展技术和业务影响评估，制定完整的系统停用和数据迁移保管方案，并组织必要的评审及停用后的安全检查。"},{"i":23,"n":"第二十三条","txt":"证券基金经营机构应当结合公司发展战略、市场交易规模等因素定期对重要信息系统开展压力测试和评估分析，确保其容量满足业务开展需要。"},{"i":24,"n":"第二十四条","txt":"证券基金经营机构应当建立健全信息系统安全监测机制，设定监测指标并持续监测重要信息系统的运行状况。 证券基金经营机构应当指定专人跟踪监测发现的异常情形，及时处置并定期开展评估分析。"},{"i":25,"n":"第二十五条","txt":"证券基金经营机构应当妥善保存信息系统开发、测试、上线、变更及运维过程中产生的文档，并根据业务开展情况以及信息系统的重要程度建立与监测工作相适应的日志留痕机制，确保满足应急处置和审计需要。"},{"i":26,"n":"第二十六条","txt":"证券基金经营机构重要信息系统部署以及所承载数据的管理，应当遵循法律法规等规定。"},{"i":27,"n":"第二十七条","txt":"证券基金经营机构可以在安全、合规的前提下为子公司提供机房、通信网络及其他信息技术基础设施，并协助开展相关运维工作。 证券基金经营机构为其子公司提供信息技术服务的，应当充分评估信息技术基础设施的支撑能力与冗余程度，并与子公司签订服务协议，明确合作双方的权利义务，以及建立日常协作、业务隔离和应急管理机制，防范基础设施共用产生的新增风险。 证券基金经营机构可以设立信息技术专业子公司，为母公司提供信息技术服务。信息技术专业子公司经中国证监会备案后可为其他金融机构提供信息技术服务。"},{"i":28,"n":"第二十八条","txt":"证券基金经营机构应当确保重要信息系统具备可审计功能，并可以根据监管部门的要求转换、提供数据。"},{"i":29,"n":"第二十九条","txt":"证券基金经营机构应当结合公司发展战略，建立全面、科学、有效的数据治理组织架构以及数据全生命周期管理机制，确保数据统一管理、持续可控和安全存储，切实履行数据安全及数据质量管理职责，不断提升数据使用价值。"},{"i":30,"n":"第三十条","txt":"证券基金经营机构应当将经营及客户数据按照重要性和敏感性进行分类分级，并根据不同类别和级别作出差异化数据管理制度安排。"},{"i":31,"n":"第三十一条","txt":"证券基金经营机构应当完善网络隔离、用户认证、访问控制、数据加密、数据备份、数据销毁、日志记录、病毒防范和非法入侵检测等安全保障措施，保护经营数据和客户信息安全，防范信息泄露与损毁。"},{"i":32,"n":"第三十二条","txt":"证券基金经营机构应当遵循最少功能以及最小权限等原则分配信息系统管理、操作和访问权限，并履行审批流程。合规管理和风险管理部门应当对权限管理制度和操作流程进行合规审查及风险控制。 证券基金经营机构应当建立对信息系统权限的定期检查与核对机制，确保用户权限与其工作职责相匹配，防止出现授权不当的情形。 证券基金经营机构应当对重要信息系统的开发、测试、运维实施必要分离，保证信息技术管理部门内部岗位的相互制衡。"},{"i":33,"n":"第三十三条","txt":"证券基金经营机构应当记录经营数据和客户信息的使用情况，并持续监督信息技术服务机构等相关方落实保密协议的情况。 证券基金经营机构发现其他机构、个人违规存储或使用自身经营数据和客户信息的，应当排查数据泄露途径、评估影响范围，采取合理可行的整改措施，及时处置风险隐患，并按照中国证监会规定履行报告和调查处理职责。 证券基金经营机构发现信息技术服务机构等相关方违规存储或者使用自身经营数据和客户信息的，应当责令其立即改正并销毁已获取的经营数据和客户信息；信息技术服务机构等相关方拒绝配合整改的，证券基金经营机构应当立即停止与其合作，并采取措施维护自身及客户的合法权益。"},{"i":34,"n":"第三十四条","txt":"证券基金经营机构应当建立健全数据安全管理制度，不得收集与服务无关的客户信息，不得购买或使用非法获取或来源不明的数据。在收集使用客户信息之前，证券基金经营机构应当公开收集、使用的规则和目的，并征得客户同意。 除法律法规和中国证监会另有规定外，证券基金经营机构不得允许或者配合其他机构、个人截取、留存客户信息，不得以任何方式向其他机构、个人提供客户信息。"},{"i":35,"n":"第三十五条","txt":"证券基金经营机构应当充分挖掘、梳理和分析数据内容，提高管理精细化程度，在业务经营、风险管理与内部控制中加强数据应用，实现同一客户、同类业务统一管理，充分发挥数据价值。"},{"i":36,"n":"第三十六条","txt":"证券基金经营机构借助信息技术手段从事证券基金业务活动的，应当建立信息技术应急管理的组织架构，确定重要业务及其恢复目标，制定应急预案，配置充足资源，稳妥处置信息技术突发事件，并积极开展应急演练和信息技术应急管理的评估与改进。"},{"i":37,"n":"第三十七条","txt":"证券基金经营机构应当落实下列应急管理职责： （一）信息技术管理部门为信息技术应急管理的牵头组织部门，组织开展信息技术应急预案的制定、演练、评估与改进工作，并负责信息系统的应急响应与恢复； （二）各业务部门负责评估本业务条线信息技术突发事件相关风险，开展业务影响分析，确定并实施重要业务恢复目标和恢复策略； （三）风险管理部门负责评估信息系统与相关业务恢复目标和恢复策略制定的合理性，确保与公司整体风险管理策略保持一致。"},{"i":38,"n":"第三十八条","txt":"证券基金经营机构应当制定并持续完善应急预案，包括应急管理建设目标、备份信息系统建设和恢复机制、备份数据恢复机制、业务恢复或替代措施、应急联系方式、与客户沟通方式、向监管部门及有关单位的报告路径、应急预案披露与更新机制等内容。 证券基金经营机构应急预案应当充分考虑重要信息系统故障、相关信息技术服务机构无法继续提供服务、证券基金经营机构信息技术高管或重要技术团队发生重大变动以及自然灾害等可能影响重要信息系统平稳运行的事件。"},{"i":39,"n":"第三十九条","txt":"证券基金经营机构应当根据系统变更、业务变化等情况，持续更新应急预案。 证券基金经营机构应当根据应急预案定期组织关键岗位人员开展应急演练，演练频率不低于每年一次，并确保应急演练在两年内覆盖全部重要信息系统。应急演练应当形成报告，保存期限不得少于五年。"},{"i":40,"n":"第四十条","txt":"证券基金经营机构应当在公司网站、客户交易终端等渠道公示信息技术突发事件发生时客户可采取的替代交易方式等信息，提示客户防范和应对可能出现的风险。"},{"i":41,"n":"第四十一条","txt":"证券基金经营机构应当确保备份系统与生产系统具备同等的处理能力，保持备份数据与原始数据的一致性。重要信息系统应当符合下列信息系统备份能力等级要求： （一）实时信息系统、非实时信息系统的数据备份能力应当达到第一级； （二）非实时信息系统的故障应对能力应当达到第二级； （三）证券公司实时信息系统的故障应对能力应当达到第四级，基金管理公司实时信息系统的故障应对能力应当达到第三级； （四）实时信息系统、非实时信息系统应当具备灾难及重大灾难应对能力，相关技术指标应当分别达到灾难应对能力第五级、重大灾难应对能力第六级； （五）灾难应对能力可以通过重大灾难应对能力体现，但重大灾难应对能力相关技术指标应当达到灾难应对能力第五级。"},{"i":42,"n":"第四十二条","txt":"证券基金经营机构应当按照中国证监会有关规定，建立信息安全事件的分级响应机制，明确内部处置工作流程，确保相关信息系统及时恢复运行。"},{"i":43,"n":"第四十三条","txt":"证券基金经营机构借助信息技术手段从事证券基金业务活动的，可以委托信息技术服务机构提供产品或服务，但证券基金经营机构依法应当承担的责任不因委托而免除或减轻。 证券基金经营机构应当清晰、准确、完整的掌握重要信息系统的技术架构、业务逻辑和操作流程等内容，确保重要信息系统运行始终处于自身控制范围。除法律法规及中国证监会另有规定外，不得将重要信息系统的运维、日常安全管理交由信息技术服务机构独立实施。"},{"i":44,"n":"第四十四条","txt":"证券基金经营机构委托信息技术服务机构提供服务，应当按照本办法第十四条的规定对信息技术服务机构及相关信息系统进行内部审查，并向中国证监会及其派出机构报送审查意见及相关资料。 证券基金经营机构应当在选择信息技术服务机构之前，制定更换服务提供方的流程及预案，确保在特定情况下可更换服务提供方。"},{"i":45,"n":"第四十五条","txt":"证券基金经营机构应当与信息技术服务机构签订服务协议和保密协议，明确各方权利、义务和责任，约定质量考核标准、持续监控机制、异常处理机制、服务变更或者终止的处置流程以及现场服务人员保密要求等内容，并持续监督信息技术服务机构及相关人员落实服务协议和保密协议的情况。 证券基金经营机构应当参照本办法第三条在服务协议中列明委托信息技术服务机构提供的服务范围、服务方式、涉及信息系统及相关证券基金业务活动类型。"},{"i":46,"n":"第四十六条","txt":"信息技术服务机构出现异常情形的，证券基金经营机构应当按照应急预案开展内部评估与审查；信息技术服务机构保障能力不足，导致相关产品或服务的可用性、完整性或机密性丧失的，应当及时更换信息技术服务机构。"},{"i":47,"n":"第四十七条","txt":"信息技术服务机构应当向中国证监会备案，具体规定由中国证监会另行制定。"},{"i":48,"n":"第四十八条","txt":"基金信息技术服务机构备案材料应当包括本机构基本情况、信息技术服务情况、服务对象情况、内部控制情况等相关资料。备案内容发生变更的，基金信息技术服务机构应当及时更新备案材料。 基金信息技术服务机构备案材料不完整或者不符合规定的，应当根据中国证监会要求及时补正。"},{"i":49,"n":"第四十九条","txt":"为证券公司、证券投资咨询机构提供信息技术服务的机构（以下简称证券信息技术服务机构）可以自愿接受中证信息业务指导，并遵守相关业务规则。"},{"i":50,"n":"第五十条","txt":"信息技术服务机构应当健全内部质量控制机制，定期监测相关产品或服务，在提供服务过程中出现明显质量问题的，应当立即核实有关情况，采取必要的处理措施，明确修复完成时限，及时完成修复工作。"},{"i":51,"n":"第五十一条","txt":"信息技术服务机构为证券基金业务活动提供信息技术服务，不得有下列行为： （一）参与证券基金经营机构向客户提供业务服务的任何环节或向投资者、社会公众等发布可能引发其从事证券基金业务误解的信息； （二）截取、存储、转发和使用证券基金业务活动相关经营数据和客户信息； （三）在服务对象不知情的情况下，转委托第三方提供信息技术服务； （四）提供的产品或服务相关功能、操作流程、系统权限及参数配置违反现行法律法规； （五）无正当理由关闭系统接口或设置技术壁垒； （六）向社会公开发布信息安全漏洞、信息系统压力测试结果等网络安全信息或泄露未公开信息； （七）法律法规及中国证监会禁止的其他行为。"},{"i":52,"n":"第五十二条","txt":"证券基金经营机构新建或更换重要信息系统所在机房、证券基金交易相关信息系统，应当在开展相关业务活动的五个工作日内向中国证监会报送有关资料，包括内部审查意见、机房基本信息、技术架构设计、操作流程、信息安全管理资料、业务制度、合规管理及风险管理制度等。"},{"i":53,"n":"第五十三条","txt":"证券基金经营机构应当在报送年度报告的同时报送年度信息技术管理专项报告，说明报告期内信息技术治理、信息技术合规与风险管理、信息技术安全管理、信息技术审计等执行本办法规定的情况。 信息技术服务机构提供信息技术服务时，应当按照中国证监会要求定期报送相关资料。 证券基金经营与服务机构提交报告的内容应当真实、准确、完整。"},{"i":54,"n":"第五十四条","txt":"证券基金经营机构应当按照中国证监会有关规定履行信息安全事件报告和调查处理职责。"},{"i":55,"n":"第五十五条","txt":"信息技术服务机构出现下列情形的，应当立即报告住所地中国证监会派出机构： （一）人员、财务、技术管理等方面发生重大变化，可能无法持续为证券基金经营机构提供信息技术服务； （二）提供的信息技术服务存在明显缺陷，可能导致所服务的三家及以上证券基金经营机构发生信息系统运营异常、数据泄露、遭受网络攻击等情形； （三）其他可能对投资者合法权益、证券期货市场造成严重影响的事件。"},{"i":56,"n":"第五十六条","txt":"中国证监会及其派出机构在对证券基金经营与服务机构信息技术管理及服务活动的监管过程中，可以采用渗透测试、漏洞扫描及信息技术风险评估等方式开展现场检查及非现场检查。证券基金经营与服务机构应当予以配合，如实提供有关文件、资料，不得拒绝、阻碍或隐瞒。"},{"i":57,"n":"第五十七条","txt":"证券基金经营机构违反本办法规定的，中国证监会及其派出机构可以依法对其采取责令改正、暂停业务、出具警示函、责令定期报告、责令增加合规检查次数、公开谴责等行政监管措施；对直接负责的主管人员和其他责任人员采取责令改正、监管谈话、出具警示函、公开谴责等行政监管措施。"},{"i":58,"n":"第五十八条","txt":"证券基金经营机构违反本办法规定，反映公司治理混乱、内控失效的，中国证监会及其派出机构可以按照《证券投资基金法》第二十四条、《证券公司监督管理条例》第七十条的规定，采取责令暂停部分或全部业务、责令更换董事、监事、高级管理人员或者限制其权利等行政监管措施。"},{"i":59,"n":"第五十九条","txt":"信息技术服务机构违反本办法规定的，中国证监会及其派出机构可以要求其提交说明材料，并采取责令改正、监管谈话、出具警示函等行政监管措施，情节严重的，中国证监会及其派出机构可以对信息技术服务机构及其直接负责的主管人员和其他直接责任人员单处或者并处警告、三万元以下罚款。"},{"i":60,"n":"第六十条","txt":"证券基金专项业务服务机构借助信息技术手段从事证券基金业务活动的，参照本办法执行。 从事证券公司客户交易结算资金存管活动的商业银行、从事公开募集基金的基金托管机构、证券基金经营机构在境内依法设立的子公司及其下设机构借助信息技术手段从事相关证券基金业务活动的，参照本办法执行。"},{"i":61,"n":"第六十一条","txt":"证券基金专项业务服务机构违反本办法规定的，中国证监会及其派出机构可以对证券基金专项业务服务机构及其直接负责的主管人员和其他直接责任人员单处或者并处警告、责令停止基金服务业务或三万元以下罚款等行政监管措施。"},{"i":62,"n":"第六十二条","txt":"证券基金经营机构、证券基金专项业务服务机构应当按照本办法第五十二条规定，在本办法实施之日起半年内将已投产的重要信息系统所在机房、证券基金交易相关信息系统等相关情况报送中国证监会。 本办法实施前，已提供相关服务的基金信息技术服务机构应当按照本办法规定，在本办法实施之日起半年内向中国证监会备案。 本办法实施前，已从事相关业务活动且不符合本办法第十七条规定的，证券基金经营机构应当妥善处理相关问题，并在本办法实施之日起半年内完成整改；整改未完成前，不得借助违规接收客户交易指令的信息系统增加新客户或提供新服务。"},{"i":63,"n":"第六十三条","txt":"本办法中下列用语的含义： （一）证券基金专项业务服务机构，是指从事公开募集基金的销售、销售支付、份额登记、估值、投资顾问、评价等基金服务业务的机构和证券投资咨询机构。 （二）重要信息系统，是指支持证券基金经营机构和证券基金专项业务服务机构关键业务功能、如出现异常将对证券期货市场和投资者产生重大影响的信息系统。包括集中交易系统、投资交易系统、金融产品销售系统、估值核算系统、投资监督系统、份额登记系统、第三方存管系统、融资融券业务系统、网上交易系统、电话委托系统、移动终端交易系统、法人清算系统、具备开户交易或者客户资料修改功能的门户网站、承载投资咨询业务的系统、存放承销保荐业务工作底稿相关数据的系统、专业即时通信软件以及与上述信息系统具备类似功能的信息系统。 （三）重大变更，是指经证券基金经营机构、证券基金专项业务服务机构自行评估，可能影响业务合规和信息系统安全稳定运行的系统变更，包括但不"},{"i":64,"n":"第六十四条","txt":"本办法自2019年6月1日起实施。《证券投资基金销售机构通过第三方电子商务平台开展业务管理暂行规定》（证监会公告〔2013〕18号）同时废止。"}],"zhengquanjijinjingyingjigoudongshijianshigaojiguana433a1":[{"i":1,"n":"第一条","txt":"为了规范证券公司和公开募集证券投资基金管理公司（以下统称证券基金经营机构）董事、监事、高级管理人员及从业人员的任职管理和执业行为，促进证券基金经营机构合规、稳健运行，保护投资者的合法权益，依据《证券法》《证券投资基金法》《公司法》《证券公司监督管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，证券基金经营机构董事、监事、高级管理人员及从业人员的任职管理和执业行为，适用本办法。 本办法所称高级管理人员是指证券基金经营机构的总经理、副总经理、财务负责人、合规负责人、风控负责人、信息技术负责人、行使经营管理职责并向董事会负责的管理委员会或执行委员会成员，和实际履行上述职务的人员，以及法律法规、中国证券监督管理委员会（以下简称中国证监会）和公司章程规定的其他人员。 本办法所称从业人员是指在证券基金经营机构从事证券基金业务和相关管理工作的人员。"},{"i":3,"n":"第三条","txt":"证券基金经营机构聘任董事、监事、高级管理人员和分支机构负责人，应当依法向中国证监会相关派出机构备案。 证券公司从业人员应当符合从事证券业务的条件，并按照规定在中国证券业协会（以下简称证券业协会）登记；公开募集证券投资基金管理公司（以下简称基金管理公司）从业人员应当符合从事基金业务的条件，并按照规定在中国证券投资基金业协会（以下简称基金业协会）注册，取得基金从业资格。 证券基金经营机构不得聘任不符合任职条件的人员担任董事、监事、高级管理人员和分支机构负责人，不得聘用不符合从业条件的人员从事证券基金业务和相关管理工作，不得违反规定授权不符合任职条件或者从业条件的人员实际履行相关职责。"},{"i":4,"n":"第四条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员应当遵守法律法规和中国证监会的规定，遵守公司章程和行业规范，恪守诚信，勤勉尽责，廉洁从业，不得损害国家利益、社会公共利益和投资者合法权益。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依法对证券基金经营机构董事、监事、高级管理人员及从业人员实施监督管理。 证券业协会、基金业协会（以下统称行业协会）等自律管理组织依法对证券基金经营机构董事、监事、高级管理人员及从业人员实施自律管理。"},{"i":6,"n":"第六条","txt":"拟任证券基金经营机构董事、监事和高级管理人员的人员，应当符合下列基本条件： （一）正直诚实，品行良好； （二）熟悉证券基金法律法规和中国证监会的规定； （三）具备3年以上与其拟任职务相关的证券、基金、金融、法律、会计、信息技术等工作经历； （四）具有与拟任职务相适应的管理经历和经营管理能力； （五）拟任证券基金经营机构高级管理人员的，曾担任证券基金经营机构部门负责人以上职务不少于2年，或者曾担任金融机构部门负责人以上职务不少于4年，或者具有相当职位管理经历； （六）法律法规、中国证监会规定的其他条件。 拟任证券基金经营机构董事长、高级管理人员以及其他从事业务管理工作的人员，还应当符合证券基金从业人员条件。 拟任证券基金经营机构合规负责人、风控负责人、信息技术负责人的，还应当符合中国证监会规定的其他条件。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，不得担任证券基金经营机构董事、监事和高级管理人员： （一）存在《公司法》第一百四十六条、《证券法》第一百二十四条第二款、第一百二十五条第二款和第三款，以及《证券投资基金法》第十五条规定的情形； （二）因犯有危害国家安全、恐怖主义、贪污、贿赂、侵占财产、挪用财产、黑社会性质犯罪或者破坏社会经济秩序罪被判处刑罚，或者因犯罪被剥夺政治权利； （三）因重大违法违规行为受到金融监管部门的行政处罚或者被中国证监会采取证券市场禁入措施，执行期满未逾5年； （四）最近5年被中国证监会撤销基金从业资格或者被基金业协会取消基金从业资格； （五）担任被接管、撤销、宣告破产或吊销营业执照机构的法定代表人和经营管理的主要负责人，自该公司被接管、撤销、宣告破产或吊销营业执照之日起未逾5年，但能够证明本人对该公司被接管、撤销、宣告破产或吊销营业执照不负有个人责任的除外； （六）被中国证监会认定为不"},{"i":8,"n":"第八条","txt":"拟任证券基金经营机构董事长、副董事长、监事会主席、高级管理人员的人员，可以参加行业协会组织的水平评价测试，作为证明其熟悉证券基金法律法规的参考；上述人员不参加行业协会组织的水平评价测试的，应当符合下列条件之一： （一）具备10年以上与其拟任职务相关的证券、基金、金融、法律、会计、信息技术等境内工作经历，且从未被金融监管部门采取行政处罚或者行政监管措施，拟任高级管理人员的，还应当担任证券基金经营机构部门负责人以上职务不少于5年，或者具有相当职位管理经历； （二）中国证监会和行业协会规定的其他条件。"},{"i":9,"n":"第九条","txt":"拟任证券基金经营机构独立董事的，不得在拟任职的证券基金经营机构担任董事会外的职务，且不得存在以下情形： （一）最近3年在拟任职的证券基金经营机构及其关联方任职； （二）直系亲属和主要社会关系人员在拟任职的证券基金经营机构及其关联方任职； （三）与拟任职的证券基金经营机构及其关联方的高级管理人员、其他董事、监事以及其他重要岗位人员存在利害关系； （四）在与拟任职的证券基金经营机构存在业务往来或利益关系的机构任职； （五）在其他证券基金经营机构担任除独立董事以外的职务； （六）其他可能妨碍其作出独立、客观判断的情形。 任何人员最多可以在2家证券基金经营机构担任独立董事。法律法规和中国证监会另有规定的，从其规定。"},{"i":10,"n":"第十条","txt":"证券基金经营机构聘任高级管理人员的，应当按照法律法规和公司章程的规定，由公司股东、董事会专门委员会或者总经理进行提名，提名人应当就拟任人符合任职条件作出书面承诺，并对其个人品行、职业操守、从业经历、业务水平、管理能力等发表明确意见，不得隐瞒重要情况或者提供虚假信息。"},{"i":11,"n":"第十一条","txt":"证券基金经营机构聘任董事、监事和高级管理人员前，应当审慎考察并确认其符合相应的任职条件，自作出聘任决定之日起5个工作日内向中国证监会相关派出机构报送下列备案材料： （一）任职情况备案登记表； （二）聘任决定文件及相关会议决议； （三）聘任单位对受聘人的考察意见、提名人的书面承诺和提名意见； （四）身份、相关工作经历、诚信状况等证明其符合任职条件的文件； （五）受聘人签署的诚信经营承诺书； （六）最近3年曾任职单位出具的离任审计报告、离任审查报告、鉴定意见或者聘任单位委托第三方机构对受聘人出具的任职调查报告； （七）中国证监会要求提交的其他材料。 证券基金经营机构应当在考察意见中对受聘人符合任职条件的情况作出说明。 曾在证券基金经营机构担任董事、监事和高级管理人员的，除补充和更新材料外，可不重复报送本条第一款第（四）项规定的备案材料。"},{"i":12,"n":"第十二条","txt":"证券基金经营机构聘任独立董事的，应当要求拟任人提供关于独立性的声明，并作为备案材料向中国证监会相关派出机构报送。声明应当重点说明拟任人是否存在本办法第九条所列举的情形。"},{"i":13,"n":"第十三条","txt":"中国证监会相关派出机构收到备案材料后，可以通过查询个人档案、征求相关监管机构意见、查询资本市场诚信档案数据库、谈话等方式对受聘人情况进行必要的核查。"},{"i":14,"n":"第十四条","txt":"中国证监会相关派出机构发现受聘人不符合任职条件的，应当要求证券基金经营机构更换有关人员。证券基金经营机构应当立即停止受聘人职务，及时解除对受聘人的聘任决定，并自作出解聘决定之日起5个工作日内向中国证监会相关派出机构报告。 中国证监会相关派出机构发现受聘人的聘任程序不符合公司章程规定的，应当要求证券基金经营机构改正，在履行规定的聘任程序前，受聘人不得实际履行职责。 证券基金经营机构、受聘人的提名人及其他负有考察责任的人员，对未发现受聘人不符合任职条件负有责任的，中国证监会相关派出机构应当依法追究其责任。"},{"i":15,"n":"第十五条","txt":"证券基金经营机构从业人员应当持续符合下列条件： （一）品行良好； （二）具备从事证券基金业务所需的专业能力，掌握证券基金业务相关的专业知识； （三）最近3年未因犯罪被判处刑罚； （四）不存在《证券法》第一百二十五条第二款和第三款，以及《证券投资基金法》第十五条规定的情形； （五）最近5年未被中国证监会撤销基金从业资格或者被基金业协会取消基金从业资格； （六）未被中国证监会采取证券市场禁入措施，或者执行期已经届满； （七）法律法规、中国证监会和行业协会规定的其他条件。"},{"i":16,"n":"第十六条","txt":"证券基金经营机构可以要求拟从事证券基金业务的人员参加从业人员专业能力水平评价测试，作为证明其专业能力的参考；不参加从业人员专业能力水平评价测试的，应当符合行业协会规定的条件。 行业协会根据业务类别负责组织从业人员专业能力水平评价测试，并作出境内外相关资质的互认安排。测试方案、大纲、科目和互认安排等由行业协会拟定并报中国证监会备案后组织实施。"},{"i":17,"n":"第十七条","txt":"证券公司应当自证券从业人员从事业务之日起5个工作日内，向证券业协会提交证明其符合条件的材料和登记信息并办理登记。证券业协会应当自登记信息完备之日起5个工作日内办结登记。登记信息不完备或者不符合规定的，证券公司及其从业人员应当按照要求及时补正。 基金管理公司应当向基金业协会提交基金从业人员符合条件的证明材料和注册信息，为其申请执业注册。基金业协会应当对注册信息进行审查，并自受理之日起5个工作日内准予注册或者不予注册。准予注册的，相关人员取得基金从业资格。不予注册的，应当书面说明理由。基金从业人员在取得基金从业资格前不得从事基金业务活动。"},{"i":18,"n":"第十八条","txt":"从业人员的登记信息或者注册信息发生变化的，应当及时通知证券基金经营机构，证券基金经营机构应当在知悉有关情况之日起5个工作日内向行业协会申请变更登记信息或者注册信息。从业人员不符合从业条件或者离职的，原聘用机构应当自上述情形发生之日起5个工作日内向行业协会办理注销登记或者注销注册。"},{"i":19,"n":"第十九条","txt":"行业协会应当将从业人员登记或者注册情况、证券基金业基本从业信息、诚信记录等进行公示。"},{"i":20,"n":"第二十条","txt":"拟任证券基金经营机构分支机构负责人的人员，应当同时符合本办法第六条第一款第（一）项到第（四）项、第七条和第十五条规定的任职条件。 证券基金经营机构聘任分支机构负责人前，应当考察确认其是否符合相应的任职条件，并自作出聘任决定之日起5个工作日内参照本办法第十一条的规定向中国证监会相关派出机构报送备案材料。中国证监会相关派出机构进行核查时发现受聘人不符合任职条件的，应当要求证券基金经营机构更换有关人员。"},{"i":21,"n":"第二十一条","txt":"担任保荐代表人、证券投资顾问、证券分析师、财务顾问主办人、基金经理、投资经理、基金投资顾问，证券经纪人等与证券公司存在委托合同关系的从业人员，以及法律法规和中国证监会规定的其他人员，还应当符合相应的从业条件，并按照规定在行业协会登记或者注册。"},{"i":22,"n":"第二十二条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员应当遵守法律法规和中国证监会的有关规定，切实履行公司章程、公司制度和劳动合同等规定的职责，并遵守下列执业行为规范： （一）具有良好的守法合规意识，自觉抵制违法违规行为，配合中国证监会及其派出机构依法履行监管职责； （二）诚实守信，廉洁自律，公平竞争，遵守职业道德和行业规范，履行向中国证监会及其派出机构的书面承诺； （三）恪尽职守、勤勉尽责，切实维护投资者合法权益，公平对待投资者，有效防范并妥善处理利益冲突； （四）审慎稳健，牢固树立风险意识，独立客观，不受他人非法干预； （五）中国证监会规定的其他执业行为规范。"},{"i":23,"n":"第二十三条","txt":"证券基金经营机构董事应当按照法律法规、中国证监会和公司章程的规定出席董事会会议，对所议事项发表明确意见，并对董事会决议依法承担相应责任。 证券基金经营机构独立董事应当依法独立履行董事义务，不受公司股东、实际控制人以及其他与公司存在利害关系的单位或个人的影响，维护公司整体利益和投资者合法权益。 证券基金经营机构独立董事应当制作年度履职报告提交股东（大）会审议，并存档备查。"},{"i":24,"n":"第二十四条","txt":"证券基金经营机构监事应当依法检查公司财务，对董事、高级管理人员履职的合法合规性进行监督，维护公司、股东和投资者的合法权益。"},{"i":25,"n":"第二十五条","txt":"证券基金经营机构高级管理人员应当忠实、勤勉履行职责，有效执行董事会决议和公司制度规定，防范和化解经营风险，确保公司规范经营和独立运作。"},{"i":26,"n":"第二十六条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员不得从事下列行为： （一）利用职务之便为本人或者他人牟取不正当利益； （二）与其履行职责存在利益冲突的活动； （三）不正当交易或者利益输送； （四）挪用或者侵占公司、客户资产或者基金财产； （五）私下接受客户委托从事证券基金投资； （六）向客户违规承诺收益或者承担损失； （七）泄露因职务便利获取的未公开信息、利用该信息从事或者明示、暗示他人从事相关的交易活动； （八）违规向客户提供资金、证券或者违规为客户融资提供中介、担保或者其他便利； （九）滥用职权、玩忽职守，不按照规定履行职责； （十）法律法规和中国证监会规定禁止的其他行为。"},{"i":27,"n":"第二十七条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员应当拒绝执行任何机构、个人侵害本公司利益或者投资者合法权益的指令或者授意，发现有侵害投资者合法权益的违法违规行为的，应当及时向合规负责人或者中国证监会相关派出机构报告。"},{"i":28,"n":"第二十八条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员不得违反法律法规和中国证监会的规定，从事证券、基金和未上市企业股权投资。"},{"i":29,"n":"第二十九条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员离任的，应当保守原任职机构商业秘密等非公开信息，不得利用非公开信息为本人或者他人牟取利益。 证券基金经营机构不得聘用从其他证券基金经营机构离任未满6个月的基金经理和投资经理，从事投资、研究、交易等相关业务。"},{"i":30,"n":"第三十条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员应当加强学习培训，提高职业操守、合规意识和专业能力。"},{"i":31,"n":"第三十一条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员应当保证有足够的时间和精力履行职责，不得自营或者为他人经营与所任公司同类或者存在利益冲突的业务。 证券基金经营机构的岗位设置和职责权限应当清晰、明确，有效防范各岗位之间可能存在的利益冲突。"},{"i":32,"n":"第三十二条","txt":"证券基金经营机构的高级管理人员、部门负责人和分支机构负责人，不得在证券基金经营机构参股或者控股的公司以外的营利性机构兼职；在证券基金经营机构参股的公司仅可兼任董事、监事，且数量不得超过2家，在证券基金经营机构控股子公司兼职的，不受前述限制。法律法规和中国证监会另有规定的，从其规定。 董事、监事、高级管理人员、部门负责人、分支机构负责人兼职的，应当及时通知证券基金经营机构，证券基金经营机构应当在知悉有关情况之日起5个工作日内向中国证监会相关派出机构报告。"},{"i":33,"n":"第三十三条","txt":"证券基金经营机构从业人员应当以所在机构的名义从事证券基金业务活动，不得同时在其他证券基金经营机构执业。中国证监会另有规定的，从其规定。"},{"i":34,"n":"第三十四条","txt":"证券基金经营机构董事、监事、高级管理人员及从业人员不得授权不符合任职条件或者从业条件的人员代为履行职责。法律法规和中国证监会另有规定的，从其规定。 证券基金经营机构董事长、总经理、合规负责人和分支机构负责人因故不能履行职务的，证券基金经营机构应当按照《公司法》和公司章程的规定，在15个工作日内决定由符合任职条件的人员代为履行职务，相关人员代为履行职务应当谨慎勤勉尽责，且时间不得超过6个月。中国证监会另有规定的，从其规定。 证券基金经营机构应当自按照前款规定作出决定之日起5个工作日内，向中国证监会相关派出机构报告。决定的人员不符合任职条件的，中国证监会相关派出机构应当要求证券基金经营机构限期另行作出决定，并要求原代为履行职务的人员停止履行职务。"},{"i":35,"n":"第三十五条","txt":"证券基金经营机构应当切实履行董事、监事、高级管理人员及从业人员任职考察、履职监督、内部考核问责的主体责任，建立健全人员任职和执业管理的内部控制机制，强化合规与风险管理，有效管控激励约束、投资行为和利益冲突防范等事项，持续提升人员的道德水准、专业能力、合规风险意识和廉洁从业水平，培育合规、诚信、专业、稳健的行业文化。"},{"i":36,"n":"第三十六条","txt":"证券基金经营机构聘任董事、监事、高级管理人员及从业人员，或者决定代为履行相应职务的人员前，应当向中国证监会相关派出机构和行业协会的信息系统查询其任职管理和执业管理信息。"},{"i":37,"n":"第三十七条","txt":"证券基金经营机构应当对其董事、监事、高级管理人员和分支机构负责人的人员名单在官方网站进行公示，并自发生变化之日起20个工作日内进行更新。"},{"i":38,"n":"第三十八条","txt":"自证券基金经营机构作出聘任决定之日起20个工作日内，高级管理人员和分支机构负责人无正当理由未实际到任履行相应职责的，证券基金经营机构应当撤销对受聘人的聘任决定，并自作出撤销聘任决定之日起5个工作日内向中国证监会相关派出机构报告。"},{"i":39,"n":"第三十九条","txt":"证券基金经营机构董事、监事、高级管理人员和分支机构负责人出现不符合法律法规和中国证监会规定的任职条件的，证券基金经营机构应当立即停止其职权或者免除其职务。 证券基金经营机构董事、监事、高级管理人员及从业人员出现本办法第七条第（七）项规定情形的，应当及时通知证券基金经营机构；相关人员涉嫌重大违法犯罪，或因履职行为被行政机关立案调查或被司法机关立案侦查的，证券基金经营机构应当暂停其职务。"},{"i":40,"n":"第四十条","txt":"证券基金经营机构高级管理人员职责分工发生调整，或者分支机构负责人改任本公司其他分支机构负责人的，应当在5个工作日内向中国证监会相关派出机构报告。 证券基金经营机构变更有关人员涉及《经营证券期货业务许可证》内容变更的，应当自作出有关聘任决定之日起20个工作日内向中国证监会或其派出机构换领《经营证券期货业务许可证》。"},{"i":41,"n":"第四十一条","txt":"证券基金经营机构免除董事、监事、高级管理人员和分支机构负责人职务的，应当自作出免职决定之日起5个工作日内，向中国证监会相关派出机构备案，并提交下列材料： （一）记载免职原因的免职决定文件； （二）相关会议的决议； （三）中国证监会规定的其他材料。 中国证监会相关派出机构依法对免职备案材料进行审查。免职程序不符合规定的，中国证监会相关派出机构应当要求证券基金经营机构改正。"},{"i":42,"n":"第四十二条","txt":"证券基金经营机构免除任期未届满的独立董事职务的，证券基金经营机构和独立董事本人应当在20个工作日内分别向中国证监会相关派出机构和股东（大）会提交书面说明。 除本人申请，或被中国证监会及其派出机构责令更换，或确有证据证明其不符合任职条件、无法正常履职、未能勤勉尽责等情形外，证券基金经营机构不得免除任期未届满的合规负责人、风控负责人的职务。"},{"i":43,"n":"第四十三条","txt":"证券基金经营机构应当加强对高级管理人员和从业人员的执业培训，确保其掌握与岗位职责相关的法律法规、执业规范，持续具备与岗位相适应的专业素质，并定期对其诚信合规、勤勉尽责、廉洁从业、专业能力等情况进行考核。"},{"i":44,"n":"第四十四条","txt":"证券基金经营机构应当建立长效合理的薪酬管理制度，充分反映合规管理和风险管理要求，避免短期、过度激励等不当激励行为。证券基金经营机构应当对董事长、高级管理人员、主要业务部门负责人、分支机构负责人和核心业务人员建立薪酬递延支付机制，在劳动合同、内部制度中合理确定薪酬递延支付标准、年限和比例等。 证券基金经营机构实施股权激励、员工持股计划等长效激励机制的，应当合理设定授予条件、授予期限和分期授予比例。 证券基金经营机构应当建立健全内部问责机制，明确高级管理人员和从业人员的履职规范和问责措施。证券基金经营机构应当在与其高级管理人员及从业人员的劳动合同、内部制度中明确，相关人员未能勤勉尽责，对证券基金经营机构发生违法违规行为或者经营风险负有责任的，证券基金经营机构可以要求其退还相关行为发生当年奖金，或者停止对其实施长效激励措施。在违法违规行为调查期间或者风险处置期间，涉嫌对证券基金经营机构发生违"},{"i":45,"n":"第四十五条","txt":"证券基金经营机构应当建立健全董事、监事、高级管理人员、从业人员及其配偶、利害关系人进行证券、基金（货币市场基金除外）和未上市企业股权投资的申报、登记、审查、监控、处置、惩戒等投资行为管理制度和廉洁从业规范，制定有效的事前防范体系、事中管控措施和事后追责机制，防止董事、监事、高级管理人员及从业人员违规从事投资，切实防范内幕交易、市场操纵、利益冲突和利益输送等不当行为，确保投资者合法权益不受侵害。"},{"i":46,"n":"第四十六条","txt":"证券基金经营机构应当定期对高级管理人员和分支机构负责人的履职情况开展内部稽核或外部审计，并保证稽核审计工作的独立性和有效性。"},{"i":47,"n":"第四十七条","txt":"证券基金经营机构董事长、高级管理人员、分支机构负责人离任的，证券基金经营机构应当对其进行审计，并自其离任之日起2个月内将离任审计报告向中国证监会相关派出机构报告。其中，法定代表人、经营管理的主要负责人离任的，证券基金经营机构应当聘请符合《证券法》规定的会计师事务所对其进行离任审计。 证券基金经营机构基金经理、投资经理离任的，证券基金经营机构应当对其进行离任审查，并自离任之日起2个月内形成离任审查报告，以存档备查。"},{"i":48,"n":"第四十八条","txt":"证券基金经营机构应当按照要求及时向中国证监会相关派出机构报送董事、监事、高级管理人员和分支机构负责人的诚信记录、内部惩戒、激励约束机制执行情况、投资行为管理和廉洁从业制度执行情况等信息，及时向行业协会报送从业人员的前述信息。 证券基金经营机构及其董事、监事、高级管理人员和从业人员应当保证报送的各项材料和信息真实、准确和完整，不得有虚假记载、误导性陈述和重大遗漏。 证券基金经营机构应当妥善保存公司人员管理制度，以及年度考核、执业培训、稽核审计等情况，保存期限不得少于20年。"},{"i":49,"n":"第四十九条","txt":"中国证监会和行业协会建立证券基金经营机构董事、监事、高级管理人员及从业人员任职管理和执业管理信息系统，中国证监会相关派出机构和行业协会应当督促证券基金经营机构按要求将相关人员的职务任免、从业人员登记或者注册情况、从业经历、日常监管、诚信记录、内部惩戒等信息纳入统一的电子化管理，有关信息应当与证券期货交易场所、证券登记结算机构等相关单位共享。"},{"i":50,"n":"第五十条","txt":"行业协会负责制定有关从业人员管理的自律规则，报中国证监会备案后实施。 行业协会应当按照法律法规和中国证监会的规定或者授权，组织从业人员的业务培训，对从事不同业务类型的从业人员实施差异化自律管理。"},{"i":51,"n":"第五十一条","txt":"证券基金经营机构及其董事、监事、高级管理人员及从业人员违反法律法规、本办法和中国证监会其他规定的，中国证监会及其派出机构可以根据情节轻重依法采取责令改正、监管谈话、出具警示函、责令定期报告、责令处分有关人员、责令更换有关人员或者限制其权利、限制向董事、监事、高级管理人员支付报酬或者提供福利、责令暂停履行职务、责令停止职权、责令解除职务、认定为不适当人选等措施。 证券基金经营机构收到中国证监会及其派出机构责令停止职权或者解除职务的决定后，应当立即停止有关人员职权或者解除其职务，不得将其调整到其他平级或者更高层级职务。 证券基金经营机构董事、监事、高级管理人员及从业人员被暂停履行职务期间，不得擅自离职。"},{"i":52,"n":"第五十二条","txt":"证券基金经营机构及其董事、监事、高级管理人员及从业人员有证据证明存在下列情形之一的，可以从轻、减轻或者免除采取行政监管措施： （一）对突发事件或者重大风险积极采取补救措施，有效控制损失和不良影响； （二）对证券基金经营机构作出的涉嫌违法违规决议，在集体决策过程中曾明确发表反对意见，并有书面记录； （三）主动向中国证监会及其派出机构、公司合规负责人报告公司的违法违规行为且调查属实； （四）中国证监会认定的其他情形。"},{"i":53,"n":"第五十三条","txt":"证券基金经营机构及其董事、监事、高级管理人员及从业人员违反本办法规定，且构成违反《证券法》《证券投资基金法》《证券公司监督管理条例》等法律法规规定情形的，应当依照有关规定处理。"},{"i":54,"n":"第五十四条","txt":"证券基金经营机构及其董事、监事、高级管理人员及从业人员违反本办法规定且情节严重，或者拒不执行监管决定，《证券法》《证券投资基金法》《证券公司监督管理条例》等法律法规没有规定相应处理措施或者罚则的，给予警告或者通报批评，并处20万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"本办法下列用语的含义： （一）分支机构负责人，是指证券基金经营机构在境内设立的从事业务经营活动的分公司、证券营业部，以及中国证监会规定的下属其他非法人机构的负责人； （二）部门负责人，是指证券基金经营机构内设的从事证券基金业务和相关管理工作的部门负责人以及实际履行上述职务的人员，被纳入高级管理人员管理的除外； （三）中国证监会相关派出机构，包括证券公司住所地、分支机构所在地的中国证监会派出机构和基金管理公司经营所在地、分支机构所在地的中国证监会派出机构； （四）投资经理，是指证券基金经营机构从事自营业务、私募资产管理业务中负责投资的专业人员； （五）商业秘密，按照《反不正当竞争法》的规定确定。"},{"i":56,"n":"第五十六条","txt":"下列机构的相关人员应当具备本办法第六条第一款第（一）项到第（四）项、第七条和第十五条规定的任职条件，并比照证券基金经营机构及其高级管理人员适用本办法的其他规定： （一）证券基金经营机构以外的其他公募基金管理人及其董事、监事和高级管理人员，基金托管人及其设立的基金托管部门的总经理、副总经理，以及实际履行上述职务的其他人员； （二）证券基金经营机构子公司及其高级管理人员，以及从事证券投资咨询、财务顾问等证券服务机构和从事公募基金销售、份额登记、估值、投资顾问、评价等基金服务机构及其相关高级管理人员，以及实际履行上述职务的其他人员； （三）商业银行以及中国证监会认可的其他金融机构从事证券基金服务业务的，相关机构及其提供证券基金服务部门的相关负责人。 前款规定机构的证券基金从业人员，应当比照证券基金经营机构从业人员适用本办法。"},{"i":57,"n":"第五十七条","txt":"本办法实施前已在证券基金经营机构或者本办法第五十六条规定的机构依法担任董事、监事、高级管理人员，以及担任证券基金经营机构分支机构负责人等职务，但未取得相应的任职资格或者未进行任职备案，且不符合本办法规定任职条件的，应当自本办法实施之日起1年内符合相应的任职条件，并按照规定进行备案。 本办法实施前已在证券基金经营机构或者本办法第五十六条规定的机构依法从业，但不符合本办法规定从业条件的，应当自本办法实施之日起1年内符合相应的从业条件，并按照规定在行业协会登记或者注册。 逾期不符合相关任职条件和从业条件的上述人员，不得继续担任相应职务或者从事相应业务。"},{"i":58,"n":"第五十八条","txt":"本办法自2022年4月1日起施行。中国证监会发布的《证券业从业人员资格管理办法》（中国证监会令第14号）《证券投资基金行业高级管理人员任职管理办法》（中国证监会令第23号）《证券公司董事、监事和高级管理人员任职资格监管办法》（中国证监会令第88号）《关于实施〈证券投资基金行业高级管理人员任职管理办法〉有关问题的通知》（证监基金字〔2004〕150号）同时废止。 span>第六条第一款第（一）项到第（四）项、第七条和第十五条规定的任职条件，并比照证券基金经营机构及其高级管理人员适用本办法的其他规定： （一）证券基金经营机构以外的其他公募基金管理人及其董事、监事和高级管理人员，基金托管人及其设立的基金托管部门的总经理、副总经理，以及实际履行上述职务的其他人员； （二）证券基金经营机构子公司及其高级管理人员，以及从事证券投资咨询、财务顾问等证券服务机构和从事公募基金销售、份额登记、估值、投资"},{"i":59,"n":"第五十七条","txt":"本办法实施前已在证券基金经营机构或者本办法第五十六条规定的机构依法担任董事、监事、高级管理人员，以及担任证券基金经营机构分支机构负责人等职务，但未取得相应的任职资格或者未进行任职备案，且不符合本办法规定任职条件的，应当自本办法实施之日起1年内符合相应的任职条件，并按照规定进行备案。 本办法实施前已在证券基金经营机构或者本办法第五十六条规定的机构依法从业，但不符合本办法规定从业条件的，应当自本办法实施之日起1年内符合相应的从业条件，并按照规定在行业协会登记或者注册。 逾期不符合相关任职条件和从业条件的上述人员，不得继续担任相应职务或者从事相应业务。"},{"i":60,"n":"第五十八条","txt":"本办法自2022年4月1日起施行。中国证监会发布的《证券业从业人员资格管理办法》（中国证监会令第14号）《证券投资基金行业高级管理人员任职管理办法》（中国证监会令第23号）《证券公司董事、监事和高级管理人员任职资格监管办法》（中国证监会令第88号）《关于实施〈证券投资基金行业高级管理人员任职管理办法〉有关问题的通知》（证监基金字〔2004〕150号）同时废止。"}],"zhengquanshichangjinruguiding":[{"i":1,"n":"第一条","txt":"为了维护证券市场秩序，保护投资者合法权益和社会公众利益，促进证券市场健康稳定发展，根据《中华人民共和国证券法》《中华人民共和国证券投资基金法》《中华人民共和国行政处罚法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中国证券监督管理委员会（以下简称中国证监会）及其派出机构（以下统称执法单位）对违反法律、行政法规或者中国证监会有关规定的有关责任人员采取证券市场禁入措施，以事实为依据，遵循公开、公平、公正的原则。"},{"i":3,"n":"第三条","txt":"下列人员违反法律、行政法规或者中国证监会有关规定，情节严重的，执法单位可以根据情节严重的程度，采取证券市场禁入措施： （一）证券发行人的董事、监事、高级管理人员，其他信息披露义务人或者其他信息披露义务人的董事、监事、高级管理人员，证券发行人、其他信息披露义务人持股百分之五以上的股东、实际控制人，证券发行人、其他信息披露义务人持股百分之五以上的股东、实际控制人的董事、监事、高级管理人员，或者执法单位认定的其他对欺诈发行或信息披露违法行为直接负责的主管人员或其他直接责任人员； （二）证券公司及其依法设立的子公司的董事、监事、高级管理人员及工作人员，证券公司的股东、实际控制人或者股东、实际控制人的董事、监事、高级管理人员； （三）证券服务机构、债券受托管理人的董事、监事、高级管理人员、合伙人、负责人及工作人员，证券服务机构、债券受托管理人的股东、实际控制人或者股东、实际控制人的董事、监事、高"},{"i":4,"n":"第四条","txt":"执法单位可以采取的市场禁入种类包括： （一）不得从事证券业务、证券服务业务，不得担任证券发行人的董事、监事、高级管理人员； （二）不得在证券交易场所交易证券。 执法单位可以根据有关责任人员的身份职责、违法行为类型、违法行为的社会危害性和违法情节严重的程度，单独或者合并适用前款规定的不同种类市场禁入措施。"},{"i":5,"n":"第五条","txt":"被采取本规定第四条第一款第一项证券市场禁入措施的人员，在禁入期间内，除不得继续在原机构从事证券业务、证券服务业务或者担任原证券发行人的董事、监事、高级管理人员职务外，也不得在其他任何机构中从事证券业务、证券服务业务或者担任其他证券发行人的董事、监事、高级管理人员职务。 被采取本规定第四条第一款第一项证券市场禁入措施的人员，应当在收到证券市场禁入决定后立即停止从事证券业务、证券服务业务或者停止履行证券发行人董事、监事、高级管理人员职务，并由其所在机构按规定的程序解除其被禁止担任的职务。"},{"i":6,"n":"第六条","txt":"被采取本规定第四条第一款第二项证券市场禁入措施的人员，在禁入期间内，不得直接或者以化名、借他人名义在证券交易场所交易上市或者挂牌的所有证券。但在禁入期间存在以下情形的除外： （一）有关责任人员被依据《中华人民共和国证券法》和中国证监会有关规定责令回购或者买回证券； （二）有关责任人员被责令依法处理非法持有的证券； （三） 有关责任人员持有的证券被依法强制扣划、卖出或转让； （四）根据相关法律、行政法规、中国证监会规定或者依法制定的证券交易场所相关业务规则，为防范和化解信用类业务风险需要继续交易证券； （五）为履行在被禁入前已经报送或者已经公开披露的材料中约定的义务需要继续交易证券； （六）卖出被禁入前已经持有的证券； （七）法律、行政法规、中国证监会或者依法制定的证券交易场所业务规则规定，或者中国证监会认定的其他情形。 被采取本规定第四条第一款第二项证券市场禁入措施的人员，应当在收到证"},{"i":7,"n":"第七条","txt":"违反法律、行政法规或者中国证监会有关规定，情节严重的，可以对有关责任人员采取3年以上5年以下本规定第四条第一款第一项规定的证券市场禁入措施；行为恶劣、严重扰乱证券市场秩序、严重损害投资者利益或者在重大违法活动中起主要作用等情节较为严重的，可以对有关责任人员采取6年以上10年以下本规定第四条第一款第一项规定的证券市场禁入措施；有下列情形之一的，可以对有关责任人员终身采取本规定第四条第一款第一项规定的证券市场禁入措施： （一）严重违反法律、行政法规或者中国证监会有关规定，被人民法院生效司法裁判认定构成犯罪的； （二）从业人员等负有法定职责的人员，故意不履行法律、行政法规或者中国证监会规定的义务，并造成特别恶劣社会影响，或者致使投资者利益受到特别严重损害，或者导致其他特别严重后果的； （三）在报送或者公开披露的材料中，隐瞒、编造或者篡改重要事实、重要财务数据或者其他重要信息，或者组织、指使从"},{"i":8,"n":"第八条","txt":"违反法律、行政法规或者中国证监会有关规定，情节严重的，可以单独对有关责任人员采取证券市场禁入措施，或者一并依法进行行政处罚；涉嫌犯罪的，依法移送有关部门，并可同时采取证券市场禁入措施。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，应当对有关责任人员从轻、减轻采取证券市场禁入措施： （一）主动消除或者减轻违法行为危害后果的； （二）配合查处违法行为有立功表现的； （三）受他人胁迫或者诱骗实施违法行为的； （四）在执法单位依法作出行政处罚决定或者证券市场禁入决定前主动交代违法行为的； （五）其他依法应当从轻、减轻采取证券市场禁入措施的。 违法情节轻微并及时纠正，没有造成危害后果的，免予采取证券市场禁入措施。初次违法并且危害后果轻微并及时纠正的，可以免予采取证券市场禁入措施。"},{"i":10,"n":"第十条","txt":"共同违反法律、行政法规或者中国证监会有关规定，需要采取证券市场禁入措施的，对负次要责任的人员，可以比照应负主要责任的人员，适当从轻、减轻或者免予采取证券市场禁入措施。"},{"i":11,"n":"第十一条","txt":"执法单位采取证券市场禁入措施前，应当告知当事人采取证券市场禁入措施的事实、理由及依据，并告知当事人有陈述、申辩和要求举行听证的权利。具体程序按照《中国证券监督管理委员会行政处罚听证规则》等规定执行。"},{"i":12,"n":"第十二条","txt":"被采取证券市场禁入措施的人员因同一违法行为同时被人民法院生效司法裁判认定构成犯罪或者进行行政处罚的，如果对其所作人民法院生效刑事司法裁判或行政处罚决定被依法撤销或者变更，并因此影响证券市场禁入措施的事实基础或者合法性、适当性的，依法撤销或者变更证券市场禁入措施。"},{"i":13,"n":"第十三条","txt":"被执法单位采取证券市场禁入措施的人员，执法单位将通过中国证监会或者相关派出机构网站，或者指定媒体向社会公布，并记入证券市场诚信档案。"},{"i":14,"n":"第十四条","txt":"有关责任人员违反执法单位依法作出的证券市场禁入决定或者所在机构及相关工作人员不配合履行证券市场禁入决定的，执法单位可依据相关法律法规进行处罚，相关法律法规没有规定的，给予警告并处国务院规定限额以下的罚款；涉嫌犯罪的，依法移送有关部门追究刑事责任。"},{"i":15,"n":"第十五条","txt":"执法单位依法宣布个人或者单位的直接责任人员为期货市场禁止进入者的，可以参照本规定执行。"},{"i":16,"n":"第十六条","txt":"本规定下列用语具有如下含义： （一）证券发行人：包括上市公司、非上市公众公司、公司债券发行人和法律、行政法规以及中国证监会规定的其他证券发行人； （二）信用类业务：包括融资融券、股票质押、债券质押式回购以及其他由法律、行政法规、中国证监会或者证券交易场所业务规则规定的，由投资者提供担保品进行资金或证券融通的交易活动； （三）从业人员：包括本规定第三条第二项、第三项、第四项、第五项和第八项规定的人员，或者执法单位认定的其他人员； （四）立即：本规定第五条第二款所称“立即”是指证券市场禁入决定送达之日的次一工作日，本规定第六条第二款所称“立即”是指证券市场禁入决定送达之日的次一交易日，法律、行政法规或者中国证监会另有规定的除外； （五）本规定所称以上、以下、不超过，均包括本数。"},{"i":17,"n":"第十七条","txt":"本规定自2021年7月19日起施行。2006年7月10日中国证监会发布施行的《证券市场禁入规定》（2006年3月7日中国证券监督管理委员会第173次主席办公会议审议通过，根据2015年5月18日中国证券监督管理委员会《关于修改〈证券市场禁入规定〉的决定》修订，以下简称原规定）同时废止。 对于本规定实施前发生的应予证券市场禁入的违法行为，依照原规定办理，但适用本规定对有关责任人员有利的，适用本规定。 对发生于本规定实施以前，继续或者连续到本规定实施以后的行为，依照本规定办理。"}],"zhengquanshichangzixinpingjiyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了促进证券市场资信评级业务规范发展，提高证券市场的效率和透明度，保护投资者的合法权益和社会公共利益，依据《证券法》，制定本办法。"},{"i":2,"n":"第二条","txt":"资信评级机构从事证券市场资信评级业务（以下简称证券评级业务），应当依照《证券法》、本办法及有关规定，向中国证券监督管理委员会（以下简称中国证监会）备案。 本办法所称证券评级业务，是指对下列评级对象开展资信评级服务： （一）经中国证监会依法注册发行的债券、资产支持证券； （二）在证券交易所或者经中国证监会认可的其他证券交易场所上市交易或者挂牌转让的债券、资产支持证券，国债除外； （三）本款第（一）项和第（二）项规定的证券的发行人、发起机构、上市公司、非上市公众公司、证券期货经营机构； （四）中国证监会规定的其他评级对象。"},{"i":3,"n":"第三条","txt":"经中国证监会备案的资信评级机构（以下简称证券评级机构），从事证券评级业务，应当遵循独立、客观、公正和审慎性原则。"},{"i":4,"n":"第四条","txt":"证券评级机构从事证券评级业务，应当遵循一致性原则，对同一类评级对象评级，或者对同一评级对象跟踪评级，应当采用一致的评级标准和工作程序。评级标准或者工作程序有调整的，应当充分披露。"},{"i":5,"n":"第五条","txt":"证券评级机构从事证券评级业务，应当制定科学的评级方法、完善的质量控制制度，遵守行业规范、职业道德和业务规则，勤勉尽责，恪尽职守，审慎分析，充分揭示相关风险。"},{"i":6,"n":"第六条","txt":"证券评级机构及其人员在开展证券评级业务中，不得有违反公平竞争、进行利益输送、直接或者间接谋取不正当利益以及其他破坏市场秩序的行为。"},{"i":7,"n":"第七条","txt":"中国证监会及其派出机构依法对证券评级业务活动进行监督管理。 相关自律组织依据《证券法》赋予的职责，对证券评级业务活动进行自律管理。"},{"i":8,"n":"第八条","txt":"资信评级机构向中国证监会备案，应当报送下列材料： （一）证券评级机构备案表； （二）营业执照复印件； （三）全球法人机构识别编码； （四）股权结构说明，包括注册资本、股东名单及其出资额或者所持股份，股东在本机构以外的实体持股情况，实际控制人、受益所有人情况； （五）董事、监事、高级管理人员以及资信评级分析人员的情况说明和证明文件； （六）主要股东、实际控制人、受益所有人、董事、监事、高级管理人员未因犯有贪污、贿赂、侵占财产、挪用财产罪或者破坏社会主义市场经济秩序罪，被判处刑罚，或者因犯罪被剥夺政治权利的声明，以及主要股东、实际控制人、受益所有人的信用报告； （七）营业场所、组织机构设置及公司治理情况; （八）独立性、信息披露以及业务制度说明； （九）中国证监会基于保护投资者、维护社会公共利益考虑，合理要求的与证券评级机构及其相关自然人有关的其他材料。 中国证监会可以对高级管理人员和主要"},{"i":9,"n":"第九条","txt":"证券评级机构应当在下列重大事项发生变更之日起10个工作日内，报中国证监会备案： （一）机构名称、住所、法定代表人； （二）董事、监事、高级管理人员； （三）实际控制人、受益所有人、持股5%以上股权的股东； （四）内部控制机制与管理制度、业务制度； （五）证券评级机构及其人员因执业行为涉嫌违法违规被立案调查，或者被司法机关侦查，以及因执业行为受到刑事处罚、行政处罚、监督管理措施、自律管理措施和纪律处分； （六）证券评级机构及其人员因执业行为与委托方、投资者发生民事纠纷，进行诉讼或仲裁； （七）设立或撤销分支机构； （八）不再从事证券评级业务； （九）中国证监会规定的其他重大事项。"},{"i":10,"n":"第十条","txt":"鼓励具备下列条件的资信评级机构开展证券评级业务： （一）实收资本与净资产均超过人民币2000万元； （二）有20名以上证券从业人员，其中10名以上具有三年以上资信评级业务经验、3名以上具备中国注册会计师资格； （三）有3名以上熟悉资信评级业务有关的专业知识，且通过资质测试的高级管理人员； （四）最近五年未受到刑事处罚，最近三年未因违法经营受到行政处罚，不存在因涉嫌违法经营、犯罪正在被调查的情形； （五）最近三年在税务、工商、金融等行政管理机关，以及自律组织、商业银行等机构无重大不良诚信记录； （六）中国证监会基于保护投资者、维护社会公共利益规定的其他条件。"},{"i":11,"n":"第十一条","txt":"证券评级机构应当符合《中华人民共和国公司法》规定的公司设立条件，内部控制机制和管理制度健全且运行良好。 证券评级机构的从业人员应当符合中国证监会及相关自律组织证券从业人员管理相关规定。"},{"i":12,"n":"第十二条","txt":"证券评级机构应当建立证券评级从业人员和管理人员的培训制度，开展培训活动，采取有效措施提高人员的职业道德和业务水平。"},{"i":13,"n":"第十三条","txt":"证券评级机构应当建立与其业务发展相适应的数据库和技术系统。"},{"i":14,"n":"第十四条","txt":"证券评级机构不再从事证券评级业务的，应当向中国证监会报告，并按照以下方式处理证券评级数据库系统： （一）与其他证券评级机构约定，转让给其他证券评级机构； （二）不能依照前项规定转让的，移交给中国证监会指定的证券评级机构； （三）不能依照前两项规定转让、移交的，在中国证监会的监督下销毁。"},{"i":15,"n":"第十五条","txt":"证券评级机构应当建立完善的业务制度，包括信用等级的划分与定义、评级方法与程序、评级质量控制、尽职调查、信用评审委员会、评级结果公布、跟踪评级、信息保密、业务档案管理等。"},{"i":16,"n":"第十六条","txt":"证券评级机构在开展委托评级项目前，应当与委托方签订评级协议，明确双方的权利和义务。"},{"i":17,"n":"第十七条","txt":"证券评级机构开展证券评级业务，应当成立评级项目组。 评级项目组成员应当具备从事相关项目的工作经历或者与评级项目相适应的知识结构，项目组组长应当完成证券从业人员登记且从事资信评级业务三年以上。"},{"i":18,"n":"第十八条","txt":"证券评级机构应当对评级对象开展尽职调查，进行必要的评估以确信评级所需信息来源可靠且充分满足使用需求，并在调查前制定详细的调查提纲。 调查过程中，证券评级机构应当制作尽职调查工作底稿，作为评级资料一并存档保管。"},{"i":19,"n":"第十九条","txt":"评级项目组应当依法收集评级对象的相关资料，并对所依据的文件资料内容进行核查验证和客观分析，在此基础上得出初评结果。"},{"i":20,"n":"第二十条","txt":"证券评级初评结果应当经过三级审核程序，包括评级项目组初审、部门再审和公司三审。 各审核阶段应当相互独立，三级审核文件资料应当按相关要求存档保管。"},{"i":21,"n":"第二十一条","txt":"证券评级机构应当建立信用评审委员会制度。评级结果应当由信用评审委员会召开评审会议，以投票表决方式最终确定。证券评级机构应当根据每一评级项目的具体情况，安排充足且具有相关经验的人员参加评审会议。"},{"i":22,"n":"第二十二条","txt":"证券评级机构应当建立复评制度。证券评级机构接受委托开展证券评级业务，在确定信用等级后，应当将信用等级告知评级委托方、受评级机构或者受评级证券发行人。评级委托方、受评级机构或者受评级证券发行人对信用等级有异议且向证券评级机构提供充分、有效的补充材料的，可以申请复评一次。 证券评级机构受理复评申请的，应当召开信用评审委员会会议重新进行审查，作出决议，确定最终信用等级。"},{"i":23,"n":"第二十三条","txt":"证券评级机构应当建立评级结果公布制度。 评级结果应当包括评级对象的信用等级和评级报告。评级报告应当采用简洁、明了的语言，对评级对象的信用等级做出明确解释，并由符合本办法规定的高级管理人员签字。"},{"i":24,"n":"第二十四条","txt":"证券评级机构应当建立跟踪评级制度。证券评级机构应当在对评级对象出具的首次评级报告中，明确规定跟踪评级事项。在评级对象有效存续期间，证券评级机构应当持续跟踪评级对象的政策环境、行业风险、经营策略、财务状况等因素的重大变化，及时分析该变化对评级对象信用等级的影响，出具定期或者不定期跟踪评级报告。 证券评级机构对评级对象的信用等级做出调整的，应当依据充分、合理审慎。"},{"i":25,"n":"第二十五条","txt":"评级委托方、受评级机构或者受评级证券发行人对其委托的证券评级机构出具的评级报告有异议，另行委托其他证券评级机构出具评级报告的，原受托证券评级机构与现受托证券评级机构应当同时公布评级结果。"},{"i":26,"n":"第二十六条","txt":"证券评级机构应当建立证券评级业务信息保密制度。对于在开展证券评级业务活动中知悉的国家秘密、商业秘密和个人隐私，证券评级机构及其人员应当依法履行保密义务。"},{"i":27,"n":"第二十七条","txt":"证券评级机构应当建立证券评级业务档案管理制度。业务档案应当包括受托开展证券评级业务的评级协议、出具评级报告所依据的原始资料、工作底稿、初评报告、评级报告、信用评审委员会表决意见及会议记录、跟踪评级资料、跟踪评级报告等。 上述信息和资料的保存期限不得少于十年，自业务委托结束之日起算。"},{"i":28,"n":"第二十八条","txt":"证券评级机构应当建立评级质量控制制度，并定期评估评级质量控制执行效果。"},{"i":29,"n":"第二十九条","txt":"发生下列情形之一的，证券评级机构可以终止或者撤销评级： （一）评级委托方、受评级机构或者受评级证券发行人拒不提供评级所需关键材料或者提供的材料存在虚假记载、误导性陈述或者重大遗漏的； （二）受评级机构解散或者被依法宣告破产的； （三）受评级证券不再存续的； （四）评级工作不能正常开展的其他情形。 因上述原因终止或者撤销评级的，证券评级机构应当及时公告并说明原因。"},{"i":30,"n":"第三十条","txt":"证券评级机构不得有下列行为： （一）篡改相关资料或者歪曲评级结果； （二）以承诺分享投资收益或者分担投资损失、承诺高等级、承诺低收费、诋毁同行等手段招揽业务； （三）以挂靠、外包等形式允许其他机构使用其名义开展证券评级业务； （四）与评级委托方、受评级机构、受评级证券发行人或者相关第三方存在不正当交易或者商业贿赂； （五）向评级委托方、受评级机构、受评级证券发行人或者相关第三方提供顾问或者咨询服务； （六）对评级委托方、受评级机构、受评级证券发行人或者相关第三方进行敲诈勒索； （七）违反证券评级业务规则，损害投资人、评级对象合法权益，损害资信评级业声誉的其他行为。"},{"i":31,"n":"第三十一条","txt":"证券评级机构及其评级从业人员应当在对评级对象相关风险进行充分分析的基础之上独立得出评级结果，防止评级结果受到其他商业行为等因素的不当影响。"},{"i":32,"n":"第三十二条","txt":"证券评级机构与评级委托方或者评级对象存在下列利害关系的，不得受托开展证券评级业务： （一）证券评级机构与评级委托方、受评级机构或者受评级证券发行人为同一实际控制人所控制； （二）同一股东持有证券评级机构的股份达到5%以上，且同时持有评级委托方、受评级机构或者受评级证券发行人的股份达到5%以上； （三）评级委托方、受评级机构或者受评级证券发行人及其实际控制人直接或者间接持有证券评级机构股份达到5%以上； （四）证券评级机构及其实际控制人直接或者间接持有评级委托方、受评级机构或者受评级证券发行人股份达到5%以上； （五）证券评级机构及其实际控制人在开展证券评级业务之前6个月内及开展证券评级业务期间买卖评级委托方、受评级机构或者受评级证券发行人的证券； （六）中国证监会基于保护投资者、维护社会公共利益认定的其他情形。"},{"i":33,"n":"第三十三条","txt":"证券评级机构应当建立回避制度。证券评级机构信用评审委员会委员及评级从业人员在开展证券评级业务期间有下列情形之一的，应当回避： （一）本人、直系亲属持有评级委托方、受评级机构或者受评级证券发行人的股份达到5%以上，或者是受评级机构、受评级证券发行人的实际控制人； （二）本人、直系亲属担任评级委托方、受评级机构或者受评级证券发行人的董事、监事和高级管理人员； （三）本人、直系亲属担任评级委托方、受评级机构或者受评级证券发行人聘任的会计师事务所、律师事务所、财务顾问等证券服务机构的负责人或者项目签字人； （四）本人、直系亲属持有评级委托方、受评级证券或者受评级机构发行的证券金额超过50万元，或者与评级委托方、受评级机构、受评级证券发行人发生累计超过50万元的交易； （五）中国证监会认定的足以影响独立、客观、公正、审慎性原则的其他情形。"},{"i":34,"n":"第三十四条","txt":"证券评级机构应当建立完善的公司治理机制和清晰合理的组织结构，合理划分内部机构职能，建立健全防火墙制度，从事证券评级业务的业务部门应当与营销等其他业务部门保持独立。 证券评级机构的人员考核和薪酬制度，不得影响评级从业人员依据独立、客观、公正、审慎、一致性的原则开展业务。 证券评级机构应当建立独立的合规部门，负责监督并向董事会、注册地中国证监会派出机构报告证券评级机构及其员工的合规状况。"},{"i":35,"n":"第三十五条","txt":"证券评级机构的董事、监事和高级管理人员以及评级从业人员不得以任何方式在评级委托方、受评级机构或者受评级证券发行人兼职。"},{"i":36,"n":"第三十六条","txt":"证券评级机构的董事、监事和高级管理人员不得投资其他证券评级机构。"},{"i":37,"n":"第三十七条","txt":"证券评级机构不得为他人提供融资或者担保。 证券评级机构的实际控制人、股东、董事、监事、高级管理人员应当遵纪守法，不得从事损害证券评级机构及其评级对象合法权益的活动。"},{"i":38,"n":"第三十八条","txt":"证券评级机构应当通过中国证券业协会网站和公司网站进行信息披露，评级结果还应当通过受评级证券上市交易或者挂牌转让的证券交易场所网站进行披露。"},{"i":39,"n":"第三十九条","txt":"证券评级机构应当自完成证券评级业务备案之日起20个工作日内，披露下列基本信息： （一）机构基本情况、经营范围； （二）股东及其出资额或者所持股份、出资方式、出资比例、股东之间是否存在关联关系的说明，股权变更信息； （三）保证评级质量的内部控制制度； （四）评级报告采用的评级符号、评级方法、评级模型和关键假设，披露程度以反映评级可靠性为限，不得涉及商业秘密或者妨碍创新； （五）董事、监事、高级管理人员以及信用评审委员会委员基本信息； （六）评级业务制度。 以上内容发生变更的，应当在10个工作日内披露变更后的情况、变更原因和对已评级项目的影响。"},{"i":40,"n":"第四十条","txt":"证券评级机构开展资产支持证券评级的，应当持续更新，并按照本办法第三十九条第一款第（四）项的要求及时披露资产支持证券评级方法、评级模型和关键假设。 证券评级机构应当同时披露资产支持证券与公司债券的评级标准差异及理由。"},{"i":41,"n":"第四十一条","txt":"证券评级机构应当在每个财务年度结束之日起4个月内披露下列独立性相关信息： （一）每年对其独立性的内部审核结果； （二）证券评级分析人员轮换政策； （三）财务年度评级收入前20名或者占比5%以上的客户名单； （四）证券评级机构的关联公司为评级委托方、受评级机构、受评级证券发行人或者相关第三方提供顾问、咨询服务的情况； （五）证券评级机构为评级委托方、受评级机构、受评级证券发行人或者相关第三方提供其他附加服务的情况。 证券评级机构在前款规定时间内将前款第（三）项信息向中国证监会备案的，可以不披露该信息。"},{"i":42,"n":"第四十二条","txt":"证券评级机构应当披露下列评级质量相关信息： （一）一年、三年、五年期的证券评级违约率和信用等级迁移情况； （二）评级委托方、受评级机构或者受评级证券发行人更换证券评级机构后级别调整的，现受托证券评级机构应当公布级别调整的原因及合理性分析； （三）任何终止或者撤销证券评级的决定及原因； （四）其他依法应当披露的信息。"},{"i":43,"n":"第四十三条","txt":"中国证监会及其派出机构应当对证券评级机构内部控制、管理制度、经营运作、风险状况、从业活动、财务状况等进行非现场检查或者现场检查。 证券评级机构及其有关人员应当配合检查，提供的信息、资料应当真实、准确、完整。"},{"i":44,"n":"第四十四条","txt":"证券评级机构应当在每一会计年度结束之日起4个月内，向注册地中国证监会派出机构报送年度报告。年度报告应当包括本机构的基本情况、经营情况、经中国证监会备案的会计师事务所审计的财务会计报告、重大诉讼事项、重大违法违规情况、独立性情况、评级质量控制情况、评级结果的准确性和稳定性统计情况等内容。证券评级机构的董事和高级管理人员应当对年度报告签署书面确认意见；对报告内容持有异议的，应当注明意见和理由。 证券评级机构应当在上半年结束之日起2个月内，向注册地中国证监会派出机构报送包含经营情况、财务会计报告、评级质量控制情况、评级结果的准确性和稳定性统计情况等内容的半年度报告。 发生影响或者可能影响本机构经营管理的重大事件时，证券评级机构应当立即向注册地中国证监会派出机构报送临时报告，说明事件的起因、目前的状态和可能产生的后果。"},{"i":45,"n":"第四十五条","txt":"相关自律组织应当加强对证券评级业务的自律管理，制定证券评级机构及其人员的自律规则和业务规范，对违反自律规则和业务规范的证券评级机构及其人员给予自律管理措施和纪律处分。 相关自律组织应当建立证券评级机构及其人员从事证券评级业务的资料库和诚信档案，将相关诚信信息纳入证券期货市场诚信档案数据库。 中国证券业协会应当积极推动行业信息公开，建立信用评价机制，定期对证券评级机构及其人员开展信用评价。"},{"i":46,"n":"第四十六条","txt":"证券评级机构及其人员应当遵守相关自律组织制定的自律规则和业务规范。"},{"i":47,"n":"第四十七条","txt":"对违反本办法规定的机构和人员，中国证监会及其派出机构可采取责令改正、监管谈话、出具警示函、责令公开说明、责令定期报告等相关监管措施。 对违反本办法规定的机构和人员依法应予行政处罚的，中国证监会及其派出机构依照《证券法》《行政处罚法》《信用评级业管理暂行办法》等法律法规和中国证监会的有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":48,"n":"第四十八条","txt":"资信评级机构从事期货相关资信评级活动，参照本办法执行。"},{"i":49,"n":"第四十九条","txt":"本办法自公布之日起施行。2007年8月24日发布的《证券市场资信评级业务管理暂行办法》（证监会令第50号）同时废止。"}],"zhengquantouzijijintuoguanyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范证券投资基金托管业务，维护证券投资基金托管业务竞争秩序，保护基金份额持有人及相关当事人合法权益，促进证券投资基金健康发展，根据《证券法》《证券投资基金法》《银行业监督管理法》及其他相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称证券投资基金（以下简称基金）托管，是指由依法设立并取得基金托管资格的商业银行或者其他金融机构担任托管人，按照法律法规的规定及基金合同的约定，对基金履行安全保管基金财产、办理清算交割、复核审查净值信息、开展投资监督、召集基金份额持有人大会等职责的行为。"},{"i":3,"n":"第三条","txt":"商业银行及其他金融机构从事基金托管业务，应当经中国证券监督管理委员会（以下简称中国证监会）核准，依法取得基金托管资格。 未取得基金托管资格的机构，不得从事基金托管业务。"},{"i":4,"n":"第四条","txt":"基金托管人应当遵守法律法规的规定以及基金合同和基金托管协议的约定，恪守职业道德和行为规范，诚实信用、谨慎勤勉，为基金份额持有人利益履行基金托管职责。"},{"i":5,"n":"第五条","txt":"基金托管人的基金托管部门高级管理人员和其他从业人员应当忠实、勤勉地履行职责，不得从事损害基金财产和基金份额持有人利益的证券交易及其他活动。"},{"i":6,"n":"第六条","txt":"中国证监会、中国银行保险监督管理委员会（以下简称中国银保监会）依照法律法规和审慎监管原则，对基金托管人及其基金托管业务活动实施监督管理。"},{"i":7,"n":"第七条","txt":"中国证券投资基金业协会依据法律法规和自律规则，对基金托管人及其基金托管业务活动进行自律管理。"},{"i":8,"n":"第八条","txt":"申请基金托管资格的商业银行及其他金融机构（以下简称申请人），应当具备下列条件： （一）净资产不低于200亿元人民币，风险控制指标符合监管部门的有关规定； （二）设有专门的基金托管部门，部门设置能够保证托管业务运营的完整与独立； （三）基金托管部门拟任高级管理人员符合法定条件，取得基金从业资格的人员不低于该部门员工人数的1/2；拟从事基金清算、核算、投资监督、信息披露、内部稽核监控等业务的执业人员不少于8人，并具有基金从业资格，其中，核算、监督等核心业务岗位人员应当具备2年以上托管业务从业经验； （四）有安全保管基金财产、确保基金财产完整与独立的条件； （五）有安全高效的清算、交割系统； （六）基金托管部门有满足营业需要的固定场所、配备独立的安全监控系统； （七）基金托管部门配备独立的托管业务技术系统，包括网络系统、应用系统、安全防护系统、数据备份系统； （八）有完善的内部稽核监控制度和"},{"i":9,"n":"第九条","txt":"申请人应当具有健全的清算、交割业务制度，清算、交割系统应当符合下列规定： （一）系统内证券交易结算资金及时汇划到账； （二）从交易所、证券登记结算机构等相关机构安全接收交易结算数据； （三）与基金管理人、基金注册登记机构、证券登记结算机构等相关业务机构的系统安全对接； （四）依法执行基金管理人的投资指令，及时办理清算、交割事宜。"},{"i":10,"n":"第十条","txt":"申请人的基金托管营业场所、安全防范设施、与基金托管业务有关的其他设施和相关制度，应当符合下列规定: （一）基金托管部门的营业场所相对独立，配备门禁系统； （二）能够接触基金交易数据的业务岗位有单独的办公场所，无关人员不得随意进入； （三）有完善的基金交易数据保密制度； （四）有安全的基金托管业务数据备份系统； （五）有基金托管业务的应急处理方案，具备应急处理能力。"},{"i":11,"n":"第十一条","txt":"申请人应当向中国证监会报送下列申请材料： （一）申请书； （二）符合《证券法》规定的会计师事务所出具的审计报告，风险控制指标最近1年持续符合监管部门有关规定的说明； （三）设立专门基金托管部门的证明文件，确保部门业务运营完整与独立的说明和承诺； （四）内部机构设置和岗位职责规定； （五）基金托管部门拟任高级管理人员任职材料； （六）关于安全保管基金财产有关条件的报告； （七）相关业务规章制度，包括业务管理、操作规程、基金会计核算、基金清算、信息披露、内部稽核监控、内控与风险管理、信息系统管理、从业人员管理、保密与档案管理、重大可疑情况报告、应急处理及其他履行基金托管人职责所需的规章制度； （八）开办基金托管业务的商业计划书； （九）中国证监会规定的其他材料。 申请人为外国银行分行的，还应当报送其总行的下列材料： （一）具有良好的国际声誉和经营业绩，近3年基金托管业务规模、收入、利润、市"},{"i":12,"n":"第十二条","txt":"中国证监会应当自收到申请材料之日起5个工作日内作出是否受理的决定。申请材料齐全、符合法定形式的，向申请人出具受理凭证；申请材料不齐全或者不符合法定形式的，应当一次告知申请人需要补正的全部内容。"},{"i":13,"n":"第十三条","txt":"中国证监会应当自受理申请材料之日起20个工作日内作出行政许可决定。作出不予核准决定的，应当说明理由并告知申请人，行政许可程序终止。"},{"i":14,"n":"第十四条","txt":"取得基金托管资格的商业银行及其他金融机构为基金托管人。基金托管人应当及时办理基金托管部门高级管理人员的任职手续。 基金托管人应当按照《证券投资基金法》及本办法等规定要求，完成基金托管业务的筹备工作，通过中国证监会及其派出机构的现场检查验收，并在完成工商变更登记后，向中国证监会申领《经营证券期货业务许可证》。在取得《经营证券期货业务许可证》前，不得对外开展基金托管业务。 基金托管人开展基金托管业务的，应当持续符合本办法第八条第一款第（一）至第（八）项、第九条、第十条规定的条件。在申请募集基金时，拟任基金托管人应不存在因与托管业务相关的重大违法违规行为、严重失信行为正在被监管机构立案调查、司法机关立案侦查，或者处于整改期间的情形。"},{"i":15,"n":"第十五条","txt":"基金托管人在与基金管理人订立基金合同、基金招募说明书、基金托管协议等法律文件前，应当从保护基金份额持有人角度，对涉及投资范围与投资限制、基金费用、收益分配、会计估值、信息披露等方面的条款进行评估，确保相关约定合规清晰、风险揭示充分、会计估值科学公允。在基金托管协议中，还应当对基金托管人与基金管理人之间的业务监督与协作等职责进行详细约定。"},{"i":16,"n":"第十六条","txt":"外国银行分行的民事责任由总行承担。外国银行分行作为基金托管人的，应当在基金合同、基金招募说明书、基金托管协议等法律文件中约定其总行履行的各项义务，包括外国银行分行开展基金托管业务发生重大风险或损害基金持有人利益时应当按照中国法律承担相应的民事责任等。 外国银行总行应当根据分行托管规模，建立相应的流动性支持机制。"},{"i":17,"n":"第十七条","txt":"基金托管人应当安全保管基金财产，按照相关规定和基金托管协议约定履行下列职责： （一）为所托管的不同基金财产分别设置资金账户、证券账户等投资交易必需的相关账户，确保基金财产的独立与完整； （二）建立与基金管理人的对账机制，定期核对资金头寸、证券账目、净值信息等数据，及时核查认购与申购资金的到账、赎回资金的支付以及投资资金的支付与到账情况，并对基金的会计凭证、交易记录、合同协议等重要文件档案保存20年以上； （三）对基金财产投资信息和相关资料负保密义务，除法律、行政法规和其他有关规定、监管机构及审计要求外，不得向任何机构或者个人泄露相关信息和资料。 非银行金融机构开展基金托管业务，应当为其托管的基金选定具有基金托管资格的商业银行作为资金存管银行，并开立托管资金专门账户，用于托管基金现金资产的归集、存放与支付，该账户不得存放其他性质资金。"},{"i":18,"n":"第十八条","txt":"基金托管人承担市场结算参与人职责的，应当建立健全结算风险防控制度和监测系统，动态评估不同产品和业务的结算风险，持续督促基金管理人采取措施防范风险。 基金托管人与基金管理人应当签订结算协议或者在基金托管协议中约定结算条款，明确双方在基金清算交收及相关风险控制方面的职责。基金清算交收过程中，出现基金财产中资金或证券不足以交收的，基金托管人应当及时通知基金管理人，督促基金管理人积极采取措施、最大程度控制违约交收风险与相关损失，并报告中国证监会。"},{"i":19,"n":"第十九条","txt":"基金托管人与基金管理人应当按照《企业会计准则》及中国证监会的有关规定进行估值核算，对各类金融工具的估值方法予以定期评估。基金托管人发现基金份额净值计价出现错误的，应当提示基金管理人立即纠正，并采取合理措施防止损失进一步扩大。基金托管人发现基金份额净值计价出现重大错误或者估值出现重大偏离的，应当提示基金管理人依法履行披露和报告义务。"},{"i":20,"n":"第二十条","txt":"基金托管人应当按照法律法规的规定以及基金合同的约定办理与基金托管业务有关的信息披露事项，包括但不限于：披露基金托管协议，对基金定期报告等信息披露文件中有关基金财务报告等信息及时进行复核审查并出具意见，在基金年度报告和中期报告中出具托管人报告，就基金托管部门负责人变动等重大事项发布临时公告。"},{"i":21,"n":"第二十一条","txt":"基金托管人应当根据基金合同及托管协议约定，制定基金投资监督标准与监督流程，对基金合同生效之后所托管基金的投资范围、投资比例、投资风格、投资限制、关联方交易等进行严格监督，及时提示基金管理人违规风险。 当发现基金管理人发出但未执行的投资指令或者已经生效的投资指令违反法律、行政法规和其他有关规定，或者基金合同约定，应当依法履行通知基金管理人等程序，并及时报告中国证监会，持续跟进基金管理人的后续处理，督促基金管理人依法履行披露义务。基金管理人的上述违规失信行为给基金财产或者基金份额持有人造成损害的，基金托管人应当督促基金管理人及时予以赔偿。"},{"i":22,"n":"第二十二条","txt":"基金托管人应当对所托管基金履行法律法规、基金合同有关收益分配约定情况进行定期复核，发现基金收益分配有违规失信行为的，应当及时通知基金管理人，并报告中国证监会。"},{"i":23,"n":"第二十三条","txt":"对于转换基金运作方式、更换基金管理人等需召开基金份额持有人大会审议的事项，基金托管人应当积极配合基金管理人召集基金份额持有人大会；基金管理人未按规定召集或者不能召集的，基金托管人应当按照规定召集基金份额持有人大会，并依法履行对外披露与报告义务。"},{"i":24,"n":"第二十四条","txt":"基金托管人在取得基金托管资格后，不得长期不开展基金托管业务；在从事基金托管业务过程中，不得进行不正当竞争，不得利用非法手段垄断市场，不得违反基金托管协议约定将部分或者全部托管的基金财产委托他人托管。"},{"i":25,"n":"第二十五条","txt":"基金托管人应当按照市场化原则，综合考虑基金托管规模、产品类别、服务内容、业务处理难易程度等因素，与基金管理人协商确定基金托管费用的计算方式和方法。 基金托管费用的计提方式和计算方法应当在基金合同、托管协议、基金招募说明书中明确列示。"},{"i":26,"n":"第二十六条","txt":"基金托管人应当按照相关法律法规，针对基金托管业务建立科学合理、控制严密、运行高效的内部控制体系，保持托管业务内部控制制度健全、执行有效。 基金托管人应当加强对基金托管相关准入管理、业务活动、信息系统和人员考核等方面的集中统一管理，不得以承包、转委托等方式开展基金托管业务。 基金托管人应当每年聘请符合《证券法》规定的会计师事务所，或者由托管人内部审计部门组织，针对基金托管法定业务和增值业务的内部控制制度建设与实施情况，开展相关审查与评估，出具评估报告。"},{"i":27,"n":"第二十七条","txt":"基金托管人应当将所托管的基金财产与其固有财产及其受托管理的各类财产严格分开保管，不得将所托管的基金财产归入其固有财产或其受托管理的各类财产，切实保障基金财产的完整和独立。 基金托管人应当建立严格的隔离墙制度，确保托管业务与本机构其他业务保持独立，隔离业务风险，切实防范利益冲突和利益输送。"},{"i":28,"n":"第二十八条","txt":"基金托管人应当完善安全保障措施，保护基金业务数据及投资者信息安全，防范信息泄露与损毁。除法律法规和中国证监会另有规定外，基金托管人不得以任何方式向其他机构、个人提供基金业务数据及投资者信息。"},{"i":29,"n":"第二十九条","txt":"基金托管人应当建立突发事件处理预案制度，对发生严重影响基金份额持有人利益、可能引发系统性风险或者严重影响社会稳定的突发事件，按照预案妥善处理。"},{"i":30,"n":"第三十条","txt":"基金托管人应当健全从业人员管理制度，完善信息管理及保密制度，加强对基金托管部门从业人员执业行为及投资基金等相关活动的管理。 基金托管部门的从业人员不得利用未公开信息为自己或者他人谋取利益。"},{"i":31,"n":"第三十一条","txt":"基金托管人应当根据托管业务发展及其风险控制的需要，不断完善托管业务信息技术系统，配置足够的托管业务人员，规范岗位职责，加强职业培训，保证托管服务质量。"},{"i":32,"n":"第三十二条","txt":"基金托管人根据业务发展的需要，按照法律法规规定和基金托管协议约定委托符合条件的境外资产托管人开展境外资产托管业务的，应当对境外资产托管人进行尽职调查，制定遴选标准与程序，健全相关的业务风险管理和应急处理制度，加强对境外资产托管人的监督与约束。"},{"i":33,"n":"第三十三条","txt":"基金托管人在法定托管职责之外依法开展基金服务外包等增值业务的，应当设立专门的团队与业务系统，与原有基金托管业务团队之间建立必要的业务隔离，有效防范潜在的利益冲突。"},{"i":34,"n":"第三十四条","txt":"商业银行作为托管人的，中国证监会和中国银保监会依法通过非现场监管和现场检查等方式，对商业银行开展基金托管业务实施日常监管。商业银行开展基金托管业务违反法律法规和相关规定的，中国证监会和中国银保监会可依照相关法律法规采取监管措施。中国证监会和中国银保监会对商业银行开展基金托管业务加强信息共享和监管协作。"},{"i":35,"n":"第三十五条","txt":"申请人在申请基金托管资格时，隐瞒有关情况或者提供虚假申请材料的，中国证监会不予受理或者不予核准，并给予警告；申请人在3年内不得再次申请基金托管资格。 申请人以欺骗、贿赂等不正当手段取得基金托管资格的，中国证监会可商中国银保监会取消基金托管资格，给予警告、罚款；中国银保监会可以区别不同情形，责令申请人对直接负责的主管人员和其他直接责任人员给予纪律处分，或者对其给予警告、罚款，或者禁止其一定期限直至终身从事银行业工作；申请人在3年内不得再次申请基金托管资格；涉嫌犯罪的依法移送司法机关，追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"未取得基金托管资格擅自从事基金托管业务的，责令停止，没收违法所得，并处违法所得1倍以上5倍以下罚款；没有违法所得或者违法所得不足100万元的，并处10万元以上100万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处3万元以上30万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"基金托管人应当根据中国证监会的要求，履行下列信息报送义务： （一）基金投资运作监督报告； （二）基金托管业务运营情况报告； （三）基金托管业务内部控制年度评估报告； （四）中国证监会根据审慎监管原则要求报送的其他材料。"},{"i":38,"n":"第三十八条","txt":"当基金托管人发生下列情形之一的，应当自发生之日起5日内向中国证监会报告： （一）基金托管部门的设置发生重大变更； （二）托管人或者其基金托管部门的名称、住所发生变更； （三）基金托管部门的高级管理人员发生变更； （四）托管人及基金托管部门的高级管理人员受到刑事、行政处罚，或者被监管机构、司法机关调查； （五）涉及托管业务的重大诉讼或者仲裁； （六）与基金托管业务相关的其他重大事项。"},{"i":39,"n":"第三十九条","txt":"中国证监会可以根据日常监管情况，对基金托管人的基金托管部门进行现场检查，并采取下列措施： （一）要求提供与检查事项有关的文件、会议记录、报表、凭证和其他资料，查阅、复制与检查事项有关的文件； （二）询问相关工作人员，要求其对有关检查事项做出说明； （三）检查基金托管业务系统； （四）中国证监会规定的其他措施。 中国证监会进行现场检查后，应当向被检查的基金托管人出具检查结论。基金托管人及有关人员应当配合中国证监会进行检查，不得以任何理由拒绝、拖延提供有关材料，或者提供不真实、不准确、不完整的资料。"},{"i":40,"n":"第四十条","txt":"基金托管人及相关人员违反本办法规定，中国证监会及其派出机构可以采取责令改正、监管谈话、出具警示函、责令定期报告、暂不受理与行政许可有关的文件等行政监管措施；对直接负责的主管人员和其他直接责任人员，可以采取监管谈话、出具警示函、责令参加培训、认定为不适当人选等行政监管措施。基金托管人违反本办法规定构成不满足《证券投资基金法》规定的准入条件，或者未能勤勉尽责、履行法定职责时存在重大失误等情形的，依照《证券投资基金法》第三十九条采取行政监管措施。"},{"i":41,"n":"第四十一条","txt":"对有下列情形之一的基金托管人，中国证监会可商中国银保监会依法取消其基金托管资格，依法给予罚款；对直接负责的主管人员和其他直接责任人员，中国证监会依法给予罚款，可以并处暂停或者撤销基金从业资格，中国银保监会可以并处禁止一定期限直至终身从事银行业工作： （一）未能在规定时间内通过整改验收的； （二）违反法律法规，情节严重的； （三）法律法规规定的其他情形。"},{"i":42,"n":"第四十二条","txt":"本办法适用于境内商业银行及依法设立的其他金融机构。 香港特别行政区、澳门特别行政区和台湾地区的银行在内地设立的分行，参照适用本办法。"},{"i":43,"n":"第四十三条","txt":"本办法自公布之日起施行。2013年公布的《证券投资基金托管业务管理办法》（证监会令第92号）、《非银行金融机构开展证券投资基金托管业务暂行规定》（证监会公告〔2013〕15号）同时废止。"}],"zhengquantouzijijinguanligongsiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对证券投资基金管理公司的监督管理，规范证券投资基金管理公司的行为，保护基金份额持有人及相关当事人的合法权益，根据《证券投资基金法》、《公司法》和其他有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称证券投资基金管理公司（以下简称基金管理公司），是指经中国证券监督管理委员会（以下简称中国证监会）批准，在中华人民共和国境内设立，从事证券投资基金管理业务和中国证监会许可的其他业务的企业法人。"},{"i":3,"n":"第三条","txt":"基金管理公司应当遵守法律、行政法规、中国证监会的规定和中国证券投资基金业协会的自律规则，恪守诚信，审慎勤勉，忠实尽责，为基金份额持有人的利益管理和运用基金财产。"},{"i":4,"n":"第四条","txt":"中国证监会及其派出机构依照《证券投资基金法》、《公司法》等法律、行政法规、中国证监会的规定和审慎监管原则，对基金管理公司及其业务活动实施监督管理。"},{"i":5,"n":"第五条","txt":"中国证券投资基金业协会依据法律、行政法规、中国证监会的规定和自律规则，对基金管理公司及其业务活动进行自律管理。"},{"i":6,"n":"第六条","txt":"设立基金管理公司，应当具备下列条件： （一）股东符合《证券投资基金法》和本办法的规定； （二）有符合《证券投资基金法》、《公司法》以及中国证监会规定的章程； （三）注册资本不低于1亿元人民币，且股东必须以货币资金实缴，境外股东应当以可自由兑换货币出资； （四）有符合法律、行政法规和中国证监会规定的拟任高级管理人员以及从事研究、投资、估值、营销等业务的人员，拟任高级管理人员、业务人员不少于15人，并应当取得基金从业资格； （五）有符合要求的营业场所、安全防范设施和与业务有关的其他设施； （六）设置了分工合理、职责清晰的组织机构和工作岗位； （七）有符合中国证监会规定的监察稽核、风险控制等内部监控制度； （八）经国务院批准的中国证监会规定的其他条件。"},{"i":7,"n":"第七条","txt":"申请设立基金管理公司，出资或者持有股份占基金管理公司注册资本的比例（以下简称持股比例）在5%以上的股东，应当具备下列条件： （一）注册资本、净资产不低于1亿元人民币，资产质量良好； （二）持续经营3个以上完整的会计年度，公司治理健全，内部监控制度完善； （三）最近3年没有因违法违规行为受到行政处罚或者刑事处罚； （四）没有挪用客户资产等损害客户利益的行为； （五）没有因违法违规行为正在被监管机构调查，或者正处于整改期间； （六）具有良好的社会信誉，最近3年在金融监管、税务、工商等行政机关，以及自律管理、商业银行等机构无不良记录。"},{"i":8,"n":"第八条","txt":"基金管理公司的主要股东是指持有基金管理公司股权比例最高且不低于25%的股东。 主要股东除应当符合本办法第七条规定的条件外，还应当具备下列条件： （一）从事证券经营、证券投资咨询、信托资产管理或者其他金融资产管理业务； （二）注册资本不低于3亿元人民币； （三）具有较好的经营业绩，资产质量良好。"},{"i":9,"n":"第九条","txt":"中外合资基金管理公司中，持股比例最高的境内股东应当具备本办法第八条规定的主要股东的条件，其他持股比例在5%以上的境内股东应当具备本办法第七条规定的条件。 中外合资基金管理公司的境外股东应当具备下列条件： （一）为依其所在国家或者地区法律设立，合法存续并具有金融资产管理经验的金融机构，财务稳健，资信良好，最近3年没有受到监管机构或者司法机关的处罚； （二）所在国家或者地区具有完善的证券法律和监管制度，其证券监管机构已与中国证监会或者中国证监会认可的其他机构签订证券监管合作谅解备忘录，并保持着有效的监管合作关系； （三）实缴资本不少于3亿元人民币的等值可自由兑换货币； （四）经国务院批准的中国证监会规定的其他条件。 香港特别行政区、澳门特别行政区和台湾地区的投资机构比照适用前款规定。"},{"i":10,"n":"第十条","txt":"基金管理公司股东的持股比例应当符合中国证监会的规定。中外合资基金管理公司外资持股比例或者拥有权益的比例，累计（包括直接持有和间接持有）不得超过我国证券业对外开放所做的承诺。"},{"i":11,"n":"第十一条","txt":"一家机构或者受同一实际控制人控制的多家机构参股基金管理公司的数量不得超过2家，其中控股基金管理公司的数量不得超过1家。"},{"i":12,"n":"第十二条","txt":"申请设立基金管理公司，申请人应当按照中国证监会的规定报送设立申请材料。 主要股东应当组织、协调设立基金管理公司的相关事宜，对申请材料的真实性、完整性负主要责任。"},{"i":13,"n":"第十三条","txt":"申请期间申请材料涉及的事项发生重大变化的，申请人应当自变化发生之日起5个工作日内向中国证监会提交更新材料；股东发生变动的，应当重新报送申请材料。"},{"i":14,"n":"第十四条","txt":"中国证监会依照《行政许可法》和《证券投资基金法》的规定，受理基金管理公司设立申请，并进行审查，做出决定。"},{"i":15,"n":"第十五条","txt":"中国证监会审查基金管理公司设立申请，可以采取下列方式： （一）征求相关机构和部门关于股东条件等方面的意见； （二）采取专家评审、核查等方式对申请材料的内容进行审查； （三）自受理之日起5个月内现场检查基金管理公司设立准备情况。"},{"i":16,"n":"第十六条","txt":"中国证监会批准设立基金管理公司的，申请人应当自收到批准文件之日起30日内向工商行政管理机关办理注册登记手续；凭工商行政管理机关核发的《企业法人营业执照》向中国证监会领取《基金管理资格证书》。 中外合资基金管理公司还应当按照法律、行政法规的规定，申领《外商投资企业批准证书》，并开设外汇资本金账户。 基金管理公司应当自工商注册登记手续办理完毕之日起10日内，在符合中国证监会规定条件的全国性报刊上将公司成立事项予以公告。"},{"i":17,"n":"第十七条","txt":"基金管理公司变更下列重大事项，应当报中国证监会批准： （一）变更持股5%以上的股东； （二）变更持股不足5%但对公司治理有重大影响的股东； （三）变更股东的持股比例超过5%； （四）修改公司章程重要条款； （五）中国证监会规定的其他重大事项。"},{"i":18,"n":"第十八条","txt":"基金管理公司变更股东、注册资本、股东持股比例后，股东的条件、股东的持股比例、股东参股基金管理公司的数量、注册资本等应当符合中国证监会的规定。"},{"i":19,"n":"第十九条","txt":"基金管理公司的股东处分其股权，应当遵守下列规定： （一）股东转让股权应当诚实守信，遵守在认购、受让股权时所做的承诺，不得损害基金份额持有人的合法权益； （二）股东转让股权应当遵守《公司法》的规定，不得采取虚报转让价格等不正当手段损害其他股东的合法权益； （三）股东与受让方应当就转让期间的有关事宜明确约定，确保不损害基金管理公司和基金份额持有人的合法权益，股东及受让方不得通过股权代持、股权托管、信托合同、秘密协议等形式处分其股权； （四）相关的变更股东事项未经中国证监会批准并履行相关法律程序，转让方应当继续履行股东义务，承担相应责任，受让方不得以任何形式行使股东权利； （五）法律、行政法规和公司章程的其他规定。"},{"i":20,"n":"第二十条","txt":"基金管理公司增加的注册资本，股东必须以货币资金实缴。"},{"i":21,"n":"第二十一条","txt":"基金管理公司变更重大事项，应当自董事会或者股东（大）会做出决议之日起60日内按照中国证监会的规定提出变更申请；涉及股东股权转让的，基金管理公司未按照规定提出申请时，相关股东可以直接提出申请。"},{"i":22,"n":"第二十二条","txt":"中国证监会依照《行政许可法》和《证券投资基金法》的规定，受理基金管理公司变更重大事项的申请，并进行审查，做出决定。"},{"i":23,"n":"第二十三条","txt":"中国证监会可以采取约请相关人员谈话、专家评审、核查等方式，审查基金管理公司变更重大事项的申请。 涉及变更基金管理公司主要股东、合计持股比例超过50%以上的股东，或者提名董事人数最多的股东的，中国证监会比照本办法关于基金管理公司设立的规定进行审查。"},{"i":24,"n":"第二十四条","txt":"基金管理公司的重大变更事项涉及变更工商登记的，基金管理公司应当自收到批准文件之日起30日内向工商行政管理机关办理变更登记手续。 基金管理公司变更为中外合资的，还应当按照有关规定申领《外商投资企业批准证书》，并开设外汇资本金账户。"},{"i":25,"n":"第二十五条","txt":"基金管理公司高级管理人员的选任或者改任，应当按照法律、行政法规和中国证监会的规定办理。"},{"i":26,"n":"第二十六条","txt":"基金管理公司的重大变更事项涉及《基金管理资格证书》内容变更的，基金管理公司应当向中国证监会换领《基金管理资格证书》。"},{"i":27,"n":"第二十七条","txt":"基金管理公司应当按照法律、行政法规和中国证监会的规定将重大变更事项予以公告。"},{"i":28,"n":"第二十八条","txt":"基金管理公司的解散，应当在中国证监会取消其基金管理资格后进行。 基金管理公司的解散应当按照《公司法》等法律、行政法规的规定办理。"},{"i":29,"n":"第二十九条","txt":"基金管理公司可以根据专业化经营管理的需要，设立子公司、分公司或者中国证监会规定的其他形式的分支机构。 子公司可以从事特定客户资产管理、基金销售以及中国证监会许可的其他业务。分公司或者中国证监会规定的其他形式的分支机构，可以从事基金品种开发、基金销售以及基金管理公司授权的其他业务。 基金管理公司应当结合自身实际，合理审慎构建和完善经营管理组织模式，设立子公司、分支机构应当进行充分的评估论证，并履行必要的内部决策程序。"},{"i":30,"n":"第三十条","txt":"基金管理公司子公司应当由基金管理公司控股，从事相关业务应当符合有关法律法规的规定。基金管理公司与子公司及各子公司之间应当建立必要的隔离墙制度，防止可能出现的风险传递和利益冲突。 基金管理公司应当建立有效的监督管理制度，加强对子公司、分支机构的业务、人员、财务等的监督和日常管理，分支机构不得以承包、租赁、托管、合作等方式经营。 基金管理公司可以设立办事处，办事处不得从事经营性活动。"},{"i":31,"n":"第三十一条","txt":"基金管理公司设立子公司、分支机构，应当具备下列条件： （一）公司治理健全，内部监控完善，经营稳定，有较强的持续经营能力； （二）公司最近1年内没有因违法违规行为受到行政处罚或者刑事处罚； （三）公司没有因违法违规行为正在被监管机构调查，或者正处于整改期间； （四）拟设立的子公司、分支机构有符合规定的名称、办公场所、业务人员、安全防范设施和与业务有关的其他设施； （五）拟设立的子公司、分支机构有明确的职责和完善的管理制度； （六）中国证监会规定的其他条件。"},{"i":32,"n":"第三十二条","txt":"基金管理公司设立子公司、分支机构，应当自董事会或者股东（大）会做出决议之日起60日内，按照中国证监会的规定报送申请材料。"},{"i":33,"n":"第三十三条","txt":"中国证监会依照《行政许可法》和《证券投资基金法》的规定，受理基金管理公司设立子公司、分支机构的申请，并进行审查，做出决定。 中国证监会可以对拟设立的子公司、分支机构进行现场检查。"},{"i":34,"n":"第三十四条","txt":"基金管理公司变更、撤销分支机构，应当自变更、撤销之日起15日内向中国证监会和所在地中国证监会派出机构报告。 基金管理公司设立、变更或者撤销办事处，应当自设立、变更或者撤销之日起15日内向中国证监会和所在地中国证监会派出机构报告。"},{"i":35,"n":"第三十五条","txt":"基金管理公司设立分支机构，应当自收到批准文件之日起30日内向工商行政管理机关办理登记注册手续。 基金管理公司变更、撤销分支机构，应当按照有关规定向工商行政管理机关办理有关手续。"},{"i":36,"n":"第三十六条","txt":"基金管理公司应当按照法律、行政法规和中国证监会的规定将子公司、分支机构的设立、变更或者撤销事项予以公告。"},{"i":37,"n":"第三十七条","txt":"基金管理公司应当按照《公司法》等法律、行政法规和中国证监会的规定，建立组织机构健全、职责划分清晰、制衡监督有效、激励约束合理的治理结构，保持公司规范运作，维护基金份额持有人的利益。 公司治理应当遵循基金份额持有人利益优先的基本原则。基金管理公司及其股东和公司员工的利益与基金份额持有人的利益发生冲突时，应当优先保障基金份额持有人的利益。"},{"i":38,"n":"第三十八条","txt":"基金管理公司的股东应当履行法定义务，不得虚假出资、抽逃或者变相抽逃出资。 基金管理公司的股东不得为其他机构或者个人代持基金管理公司的股权，不得委托其他机构或者个人代持股权。基金管理公司的股东及其实际控制人不得以任何形式占有或者转移基金管理公司资产。 基金管理公司的主要股东应当秉承长期投资理念，并书面承诺持有基金管理公司股权不少于3年。"},{"i":39,"n":"第三十九条","txt":"基金管理公司应当明确股东（大）会的职权范围和议事规则。 基金管理公司应当建立与股东之间的业务和客户关键信息隔离制度。基金管理公司的股东及其实际控制人应当通过股东（大）会依法行使权利，不得越过股东（大）会、董事会任免基金管理公司的董事、监事、高级管理人员，或者直接干预基金管理公司的经营管理、基金财产的投资运作；不得在证券承销、证券投资等业务活动中要求基金管理公司为其提供配合，损害基金份额持有人和其他当事人的合法权益。 基金管理公司的单个股东或者有关联关系的股东合计持股比例在50%以上的，上述股东及其控制的机构不得经营公募或者类似公募的证券资产管理业务。"},{"i":40,"n":"第四十条","txt":"基金管理公司的主要股东在公司不能正常经营时，应当召集其他股东及有关当事人，按照有利于保护基金份额持有人利益的原则妥善处理有关事宜。"},{"i":41,"n":"第四十一条","txt":"基金管理公司应当明确董事会的职权范围和议事规则。董事会应当按照法律、行政法规和公司章程的规定，制定公司基本制度，决策有关重大事项，监督、奖惩经营管理人员。董事会会议由董事长召集和主持，董事会和董事长不得越权干预经营管理人员的具体经营活动。 董事会对经营管理人员的考核，应当关注基金长期投资业绩、公司合规和风险控制等维护基金份额持有人利益的情况，不得以短期的基金管理规模、盈利增长等为主要考核标准。 基金管理公司的总经理应当为董事会成员。基金管理公司的单个股东或者有关联关系的股东合计持股比例在50%以上的，与上述股东有关联关系的董事不得超过董事会人数的1/3。"},{"i":42,"n":"第四十二条","txt":"基金管理公司应当建立健全独立董事制度，独立董事人数不得少于3人，且不得少于董事会人数的1/3。 独立董事应当独立于基金管理公司及其股东，以基金份额持有人利益最大化为出发点，勤勉尽责，依法对基金财产和公司运作的重大事项独立作出客观、公正的专业判断。"},{"i":43,"n":"第四十三条","txt":"基金管理公司的董事会审议下列事项，应当经过2/3以上的独立董事通过： （一）公司及基金投资运作中的重大关联交易； （二）公司和基金审计事务，聘请或者更换会计师事务所； （三）公司管理的基金的半年度报告和年度报告； （四）法律、行政法规和公司章程规定的其他事项。"},{"i":44,"n":"第四十四条","txt":"基金管理公司应当建立健全督察长制度，督察长由董事会聘任，对董事会负责，对公司经营运作的合法合规性进行监察和稽核。 督察长发现公司存在重大风险或者有违法违规行为，应当告知总经理和其他有关高级管理人员，并向董事会、中国证监会和公司所在地中国证监会派出机构报告。"},{"i":45,"n":"第四十五条","txt":"基金管理公司应当加强监事会或者执行监事对公司财务、董事会履行职责的监督作用，维护股东合法利益。 监事会应当包括股东代表和公司职工代表，其中职工代表的比例不得少于监事会人数的1/2。不设监事会的，执行监事中至少有1名职工代表。 监事会和监事会主席、执行监事不得越权干预经营管理人员的具体经营活动。"},{"i":46,"n":"第四十六条","txt":"基金管理公司的总经理负责公司的经营管理。基金管理公司的高级管理人员及其他工作人员应当忠实、勤勉地履行职责，不得为股东、本人或者他人谋取不正当利益。"},{"i":47,"n":"第四十七条","txt":"基金管理公司的董事、监事、高级管理人员、股东及有关各方，在基金管理公司主要股东不能正常经营或者基金管理公司股权转让期间，应当依法履行职责，恪尽职守，做好风险防范的安排，保证公司正常经营，基金份额持有人利益不受损害。"},{"i":48,"n":"第四十八条","txt":"基金管理公司应当坚持稳健经营理念，管理资产规模应当与自身的人员储备、投研和客户服务能力、信息技术系统承受度、风险管理和内部监控水平相匹配，切实维护基金份额持有人的长远利益。"},{"i":49,"n":"第四十九条","txt":"基金管理公司应当按照中国证监会的规定，建立科学合理、控制严密、运行高效的内部监控体系，制定科学完善的内部监控制度，保持经营运作合法、合规，保持公司内部监控健全、有效。"},{"i":50,"n":"第五十条","txt":"基金管理公司应当建立健全由授权、研究、决策、执行和评估等环节构成的投资管理系统，公平对待其管理的不同基金财产和客户资产。"},{"i":51,"n":"第五十一条","txt":"基金管理公司应当建立完善的基金财务核算与基金资产估值系统，严格遵守国家有关规定，及时、准确和完整地反映基金财产的状况。"},{"i":52,"n":"第五十二条","txt":"基金管理公司应当遵守相关法律法规、行业监管要求、行业技术标准，遵循安全性、实用性、可操作性原则，建立与公司发展战略和业务操作相适应的信息技术系统。"},{"i":53,"n":"第五十三条","txt":"基金管理公司应当建立健全人力资源管理制度，规范岗位职责，强化员工培训，建立与公司发展相适应的激励约束机制、基金从业人员与基金份额持有人的利益绑定机制，为公司经营管理和持续发展提供人力资源支持。"},{"i":54,"n":"第五十四条","txt":"基金管理公司应当建立和完善客户服务标准，加强销售管理，规范基金宣传推介，不得有不正当销售或者不正当竞争的行为。"},{"i":55,"n":"第五十五条","txt":"基金管理公司应当保持良好的财务状况，满足公司运营、业务发展和风险防范的需要。 基金管理公司应当建立健全财务管理制度，严格执行国家财经法律法规，相关资金或者资产必须列入符合规定的本单位会计账簿。"},{"i":56,"n":"第五十六条","txt":"基金管理公司按照审慎经营原则和业务发展需要，可以相应增加注册资本。 基金管理公司应当按照规定提取风险准备金。"},{"i":57,"n":"第五十七条","txt":"基金管理公司应当按照中国证监会的规定，管理和运用固有资金。 基金管理公司管理、运用固有资金，应当保持公司的正常运营，不得损害基金份额持有人的合法权益。"},{"i":58,"n":"第五十八条","txt":"基金管理公司应当建立突发事件处理预案制度，对发生严重影响基金份额持有人利益、可能引起系统性风险、严重影响社会稳定的突发事件，按照预案妥善处理。"},{"i":59,"n":"第五十九条","txt":"基金管理公司可以根据自身发展战略的需要，委托资质良好的基金服务机构代为办理基金份额登记、核算、估值以及信息技术系统开发维护等业务，但基金管理公司依法应当承担的责任并不因委托而免除。 委托基金服务机构代为办理部分业务的，基金管理公司应当进行充分的评估论证，履行必要的内部决策程序，审慎确定委托办理业务的范围、内容以及受托基金服务机构，并制定委托办理业务的风险管理和应急处理制度，加强对受托基金服务机构的评价和约束，确保业务信息的保密性和安全性，维护基金份额持有人的合法权益以及公司的商业秘密等。"},{"i":60,"n":"第六十条","txt":"基金管理公司与基金服务机构签署委托协议后10日内，应当向中国证监会和所在地中国证监会派出机构报告委托办理业务的范围、内容、受托基金服务机构的基本情况和业务准备情况、主要风险及相应的风险防范措施等。基金管理公司应当在基金招募说明书、基金合同、基金年度报告、基金半年度报告以及基金管理公司年度报告中披露委托办理业务的有关情况。 开展受托业务的基金服务机构应当具有健全的治理结构，经营运作规范，财务状况良好，有与受托办理业务相适应的专业人才队伍、营业场所、安全防范设施和技术设施等，并具有完善的内部控制、风险管理、应急处理制度和业务操作流程等。基金服务机构及其从业人员开展相关受托业务应当恪尽职守、诚实守信、谨慎勤勉，确保受托业务运作安全有效，并保守商业秘密，不得泄露或者利用受托业务知悉的非公开信息牟利，不得损害基金份额持有人的合法权益。"},{"i":61,"n":"第六十一条","txt":"基金管理公司、基金管理公司的股东申请批准有关事项，隐瞒有关情况或者提供虚假材料的，中国证监会不予受理；已经受理的，不予批准。"},{"i":62,"n":"第六十二条","txt":"中国证监会依照法律、行政法规、中国证监会规定和审慎监管原则对基金管理公司的公司治理、内部监控、经营运作、风险状况，以及相关业务活动进行非现场检查和现场检查。"},{"i":63,"n":"第六十三条","txt":"非现场检查主要以审阅基金管理公司报送材料的方式进行。 基金管理公司应当向中国证监会和所在地中国证监会派出机构报送下列材料： （一）经符合《证券法》规定的会计师事务所审计的基金管理公司年度报告； （二）由符合《证券法》规定的会计师事务所出具的基金管理公司内部监控情况的年度评价报告； （三）监察稽核季度报告和年度报告； （四）中国证监会根据审慎监管原则要求报送的其他材料。"},{"i":64,"n":"第六十四条","txt":"基金管理公司应当自年度结束之日起3个月内报送基金管理公司年度报告和年度评价报告；自季度结束之日起15日内报送监察稽核季度报告，自年度结束之日起30日内报送监察稽核年度报告。"},{"i":65,"n":"第六十五条","txt":"基金管理公司发生下列情形之一的，应当在5日内向中国证监会和所在地中国证监会派出机构报告： （一）变更持股5%以下的股东； （二）变更股东的持股比例不超过5%； （三）变更名称、住所； （四）股东同比例增减注册资本； （五）修改公司章程一般条款； （六）公司及其董事、高级管理人员、基金经理受到刑事、行政处罚； （七）公司及其董事、高级管理人员、基金经理被监管机构或者司法机关调查； （八）公司财务状况发生重大不利变化； （九）因公司过失遭受重大投诉； （十）面临重大诉讼； （十一）对公司经营产生重大影响的其他事项。 发生前款第（六）项至第（十一）项规定事项的，基金管理公司应当书面通知全体股东。 基金管理公司发生本办法第五十八条规定的突发事件的，应当立即向中国证监会和所在地中国证监会派出机构报告。"},{"i":66,"n":"第六十六条","txt":"基金管理公司股东发生下列情形之一的，应当书面通知公司，并在5日内向中国证监会和公司所在地中国证监会派出机构报告： （一）名称、住所变更； （二）控股股东或者实际控制人变更； （三）主要股东连续3年亏损； （四）所持股权被司法机关采取诉讼保全等措施； （五）决定处分其股权； （六）发生合并、分立或者进行重大资产、债务重组； （七）被监管机构或者司法机关立案调查； （八）被采取责令停业整顿、指定托管、接管或者撤销等监管措施或者进入破产清算程序； （九）对公司运作产生重大影响的其他事项。"},{"i":67,"n":"第六十七条","txt":"中外合资基金管理公司的境外股东，其注册地或者主要经营活动所在地的主管当局对境外投资有备案要求的，该境外股东在依法取得中国证监会的批准文件后，如向其注册地或者主要经营活动所在地的主管当局提交有关备案材料，应当同时将副本报送中国证监会。"},{"i":68,"n":"第六十八条","txt":"中国证监会可以采取下列措施对基金管理公司进行现场检查，并根据日常监管情况确定现场检查的对象、内容和频率： （一）进入基金管理公司及其子公司、分支机构进行检查； （二）要求基金管理公司提供与检查事项有关的文件、会议记录、报表、凭证和其他资料； （三）询问基金管理公司的工作人员，要求其对有关检查事项做出说明； （四）查阅、复制基金管理公司与检查事项有关的文件、资料，对可能被转移、隐匿或者毁损的文件、资料予以封存； （五）检查基金管理公司的信息技术系统； （六）中国证监会规定的其他措施。"},{"i":69,"n":"第六十九条","txt":"中国证监会对基金管理公司进行现场检查时，检查人员不得少于2人，并应当出示合法证件；检查人员少于2人或者未出示合法证件的，基金管理公司有权拒绝检查。 中国证监会可以聘请注册会计师、律师等专业人员为检查工作提供专业服务。"},{"i":70,"n":"第七十条","txt":"基金管理公司及有关人员应当配合中国证监会进行检查，不得以任何理由拒绝、拖延提供有关资料，或者提供不真实、不准确、不完整的资料。"},{"i":71,"n":"第七十一条","txt":"中国证监会对基金管理公司进行现场检查后，应当向被检查的基金管理公司出具检查结论。"},{"i":72,"n":"第七十二条","txt":"中国证监会可以根据监管需要，建立基金管理公司风险控制指标监控体系和监管综合评价体系。对于相关风险控制指标、监管综合评价指标不符合规定的，中国证监会可以责令公司限期改正，并可以采取要求公司增加注册资本金、提高风险准备金提取比例、暂停部分或者全部业务等行政监管措施。"},{"i":73,"n":"第七十三条","txt":"违反本办法的规定，有下列情形之一的，中国证监会责令改正，给予警告，并处3万元以下的罚款，对直接负责的主管人员和其他直接责任人员给予警告，撤销任职资格或者基金从业资格，并处3万元以下的罚款： （一）未经批准持有基金管理公司5%以上股权，或者通过提供虚假申请材料等方式成为基金管理公司股东； （二）委托他人或者接受他人委托持有基金管理公司的股权； （三）基金管理公司的股东及其实际控制人占有或者转移基金管理公司资产； （四）基金管理公司的股东及其实际控制人在证券承销、证券投资等业务活动中，强令、指使、接受基金管理公司为其提供配合，损害基金份额持有人和其他当事人的合法权益。"},{"i":74,"n":"第七十四条","txt":"违反本办法的规定，有下列情形之一的，中国证监会责令改正，并对负有责任的股东、实际控制人、董事、监事、高级管理人员以及直接责任人员等可以采取监管谈话、出具警示函、暂停履行职务等行政监管措施： （一）基金管理公司的股东、实际控制人越过股东（大）会、董事会任免基金管理公司的董事、监事、高级管理人员； （二）基金管理公司的股东、实际控制人越过股东（大）会、董事会直接干预基金管理公司的经营管理或者基金财产的投资运作； （三）基金管理公司及其股东、实际控制人未及时履行报告义务； （四）基金管理公司董事会对经营管理人员的考核不符合规定。"},{"i":75,"n":"第七十五条","txt":"基金管理公司出现下列情形之一的，中国证监会责令其限期整改，整改期间可以暂停受理及审核其基金产品募集申请或者其他业务申请，并对负有责任的董事、监事、高级管理人员以及直接责任人员可以采取监管谈话、出具警示函、暂停履行职务等行政监管措施： （一）公司治理不健全，严重影响公司的独立性、完整性和统一性； （二）公司内部控制制度不完善，相关制度不能有效执行，存在重大风险隐患或者发生较大风险事件； （三）对子公司、分支机构管理松懈，或者选聘的基金服务机构不具备基本的资质条件，存在重大风险隐患或者发生较大风险事件； （四）发生重大违法违规行为。 基金管理公司逾期未完成整改的，中国证监会可以停止批准其增设子公司或者分支机构；限制分配红利，限制其向负有责任的董事、监事、高级管理人员支付报酬、提供福利；责令其更换负有责任的董事、监事、高级管理人员或者限制权利。情节特别严重的，中国证监会可以采取指定其他机构托"},{"i":76,"n":"第七十六条","txt":"基金管理公司的净资产低于4000万元人民币，或者现金、银行存款、国债等可运用的流动资产低于2000万元人民币且低于公司上一会计年度营业支出的，中国证监会可以暂停受理及审核其基金产品募集申请或者其他业务申请，并限期要求改善财务流动性。财务状况持续恶化的，中国证监会责令其进行停业整顿。 被责令停业整顿的，基金管理公司应当在规定的期限内将其管理的基金资产委托给中国证监会认可的基金管理公司进行管理。逾期未按照要求委托管理的，中国证监会可以指定其他机构对其基金管理业务进行托管。"},{"i":77,"n":"第七十七条","txt":"基金服务机构违反本办法的规定，泄露或者利用受托业务知悉的非公开信息牟利，损害基金份额持有人合法权益的，责令改正，给予警告，并处3万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处3万元以下的罚款。"},{"i":78,"n":"第七十八条","txt":"基金管理公司、基金管理公司的股东及实际控制人、基金服务机构及其直接负责的主管人员和其他直接责任人员违反本办法以及其他相关规定，依法应予行政处罚的，依照有关规定进行行政处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":79,"n":"第七十九条","txt":"本办法所称中外合资基金管理公司，包括境外股东与境内股东共同出资设立的基金管理公司和境外股东受让、认购境内基金管理公司股权而变更的基金管理公司。"},{"i":80,"n":"第八十条","txt":"基金管理公司设立子公司的具体管理办法，由中国证监会另行规定。"},{"i":81,"n":"第八十一条","txt":"本办法自2012年11月1日起施行。《证券投资基金管理公司管理办法》（证监会令第22号）同时废止。"}],"zhengquantouzijijinhangyegaojiguanlirenyuanrenzhigf61d64":[{"i":1,"n":"第一条","txt":"为了规范证券投资基金行业高级管理人员的任职管理，保护投资人及相关当事人的合法权益和社会公共利益，根据证券投资基金法、公司法和其他法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称证券投资基金行业高级管理人员（以下简称高级管理人员），是指基金管理公司的董事长、总经理、副总经理、督察长以及实际履行上述职务的其他人员，基金托管银行基金托管部门的总经理、副总经理以及实际履行上述职务的其他人员。"},{"i":3,"n":"第三条","txt":"高级管理人员的选任或者改任，应当报经中国证券监督管理委员会（以下简称中国证监会）审核。 未经中国证监会核准，基金管理公司、基金托管银行不得选任或者改任高级管理人员，不得违反规定决定代为履行高级管理人员职务的人员。"},{"i":4,"n":"第四条","txt":"高级管理人员应当遵守法律、行政法规和中国证监会的规定，遵守公司章程和行业规范，恪守诚信，审慎勤勉，忠实尽责，维护基金份额持有人的合法权益。"},{"i":5,"n":"第五条","txt":"中国证监会依法对高级管理人员进行监督管理，制定高级管理人员、董事、基金经理等人员管理的具体规定。 基金管理公司的董事和基金经理的任免，应当向中国证监会报告。"},{"i":6,"n":"第六条","txt":"申请高级管理人员任职资格，应当具备下列条件： （一）取得基金从业资格； （二）通过中国证监会或者其授权机构组织的高级管理人员证券投资法律知识考试； （三）具有3年以上基金、证券、银行等金融相关领域的工作经历及与拟任职务相适应的管理经历，督察长还应当具有法律、会计、监察、稽核等工作经历； （四）没有公司法、证券投资基金法等法律、行政法规规定的不得担任公司董事、监事、经理和基金从业人员的情形； （五）最近3年没有受到证券、银行、工商和税务等行政管理部门的行政处罚。"},{"i":7,"n":"第七条","txt":"申请基金管理公司高级管理人员任职资格，应当由基金管理公司向中国证监会报送下列申请材料： （一）对拟任高级管理人员（以下简称拟任人）任职资格进行审核的申请及任职资格申请表； （二）相关会议的决议； （三）前条第（三）项规定的从业经历证明； （四）最近3年工作单位出具的离任审计报告、离任审查报告或者鉴定意见； （五）对拟任人的考察意见； （六）拟任人身份、学历、学位证明复印件； （七）拟任人基金从业资格证明复印件； （八）拟任人高级管理人员证券投资法律知识考试合格证明复印件； （九）任职条件、任职程序符合法律、行政法规、中国证监会规定和公司章程的法律意见书； （十）中国证监会规定的其他材料。 申请基金托管部门高级管理人员任职资格，应当由基金托管银行向中国证监会报送前款除第（二）项、第（九）项以外的申请材料。 上述申请材料应当是中文文本，一式3份。原件是外文的，应当附中文译本。"},{"i":8,"n":"第八条","txt":"中国证监会依法对申请材料进行受理和审查。 中国证监会可以通过考察、谈话等方式对拟任人进行审查。考察、谈话应当由两名工作人员进行，谈话应当作出记录并经考察人和拟任人签字。"},{"i":9,"n":"第九条","txt":"申报机构应当自收到中国证监会核准文件之日起20个工作日内，按照本机构的章程等规定作出选任或者改任的决定，并办理相关手续。"},{"i":10,"n":"第十条","txt":"自取得任职资格之日起20个工作日内，拟任人未按照拟任机构的规定履行拟任职务的，除有正当理由的外，其任职资格自动失效。 高级管理人员离任的，其任职资格自离任之日起自动失效。"},{"i":11,"n":"第十一条","txt":"基金管理公司免去高级管理人员职务、任免董事和基金经理，基金托管银行免去基金托管部门高级管理人员职务的，应当在作出决定之日起3个工作日内向中国证监会报告，报送任职、免职报告材料。"},{"i":12,"n":"第十二条","txt":"基金管理公司董事应当具备本办法第六条第（四）项、第（五）项规定的条件。 独立董事还应当具备下列条件： （一）具有5年以上金融、法律或者财务的工作经历； （二）有履行职责所需要的时间； （三）最近3年没有在拟任职的基金管理公司及其股东单位、与拟任职的基金管理公司存在业务联系或者利益关系的机构任职； （四）与拟任职的基金管理公司的高级管理人员、其他董事、监事、基金经理、财务负责人没有利害关系； （五）直系亲属不在拟任职的基金管理公司任职。"},{"i":13,"n":"第十三条","txt":"基金管理公司董事任职报告材料应当包括： （一）董事任职报告和任职登记表； （二）相关会议的决议； （三）本办法第七条第（四）项至第（六）项、第（九）项所列材料。 独立董事任职报告材料还应当包括独立董事具有5年以上金融、法律或者财务工作经历的证明，以及独立董事作出的本人符合前条第二款第（二）项至第（五）项规定的书面承诺。"},{"i":14,"n":"第十四条","txt":"基金管理公司基金经理应当具有3年以上证券投资管理经历，并符合本办法第六条第（一）项、第（二）项、第（四）项和第（五）项规定的条件。"},{"i":15,"n":"第十五条","txt":"基金经理任职报告材料应当包括： （一）基金经理任职报告和任职登记表； （二）相关会议的决议； （三）具有3年以上证券投资管理经历的证明； （四）本办法第七条第（四）项至第（七）项所列材料。"},{"i":16,"n":"第十六条","txt":"基金管理公司免去高级管理人员、董事职务，基金托管银行免去基金托管部门高级管理人员职务的，应当向中国证监会提交下列免职报告材料： （一）免职报告； （二）相关会议的决议； （三）免职程序符合法律、行政法规、中国证监会规定和公司章程等规定的法律意见书。 基金管理公司免去基金经理职务的，应当向中国证监会提交前款第（一）项和第（二）项规定的免职报告材料。"},{"i":17,"n":"第十七条","txt":"中国证监会依法对高级管理人员免职报告材料进行审查。免职程序不符合规定的，中国证监会责令其任职机构改正。"},{"i":18,"n":"第十八条","txt":"中国证监会依法对基金管理公司董事、基金经理的任职和免职报告材料进行审查。 董事、基金经理不符合法定任职条件的，中国证监会责令其任职的基金管理公司按照规定予以更换。任免程序不符合规定的，中国证监会责令改正。"},{"i":19,"n":"第十九条","txt":"高级管理人员、基金管理公司基金经理应当维护所管理基金的合法利益，在基金份额持有人的利益与基金管理公司、基金托管银行的利益发生冲突时，应当坚持基金份额持有人利益优先的原则。 高级管理人员、基金管理公司基金经理不得从事或者配合他人从事损害基金份额持有人利益的活动，不得从事与所服务的基金管理公司或者基金托管银行的合法利益相冲突的活动。"},{"i":20,"n":"第二十条","txt":"高级管理人员、基金管理公司基金经理应当具有良好的职业道德，勤勉尽责，切实履行基金合同、公司章程和公司制度规定的职责，不得滥用职权，不得违反规定授权他人代为履行职务，不得利用职务之便谋取私利，未经规定程序不得离职。"},{"i":21,"n":"第二十一条","txt":"基金管理公司董事应当按照公司章程的规定出席董事会会议、参加公司的活动，切实履行职责。 独立董事应当审慎和客观地发表独立意见，切实保护基金份额持有人的合法权益。"},{"i":22,"n":"第二十二条","txt":"基金管理公司总经理应当认真执行董事会决议，有效执行公司制度，防范和化解经营风险，提高经营管理效率，确保经营业务的稳健运行和所管理的基金财产安全完整，促进公司持续、稳定、健康发展。 基金管理公司副总经理应当协助总经理工作，忠实履行职责。"},{"i":23,"n":"第二十三条","txt":"基金管理公司督察长应当认真履行职责，对公司各项制度、业务的合法合规性及公司内部控制制度的执行情况进行监察、稽核。"},{"i":24,"n":"第二十四条","txt":"基金管理公司基金经理应当严格遵守基金合同及公司有关投资制度的规定，审慎勤勉，充分发挥专业判断能力，不受他人干预，在授权范围内独立行使投资决策权。"},{"i":25,"n":"第二十五条","txt":"基金托管银行基金托管部门的总经理、副总经理应当建立、健全本部门的各项业务制度和管理制度，确保本部门切实履行托管人职责，监督基金管理人的投资运作，保障基金财产的独立与完整。"},{"i":26,"n":"第二十六条","txt":"高级管理人员和基金管理公司董事、基金经理应当加强业务学习，跟踪行业发展动态，按照中国证监会的规定参加业务培训，不断提高管理水平和专业技能。"},{"i":27,"n":"第二十七条","txt":"拟任人在高级管理人员证券投资法律知识考试中作弊，或者提交虚假任职资格申请材料的，中国证监会3年内不受理其任职资格申请。"},{"i":28,"n":"第二十八条","txt":"基金管理公司和基金托管银行应当建立高级管理人员考核制度，定期对高级管理人员进行考核，建立考核档案。 中国证监会定期或者不定期对高级管理人员考核档案进行检查，对高级管理人员守法合规情况等进行考核。"},{"i":29,"n":"第二十九条","txt":"中国证监会建立高级管理人员管理信息系统，记录高级管理人员从事基金业务的相关情况。 基金管理公司和基金托管银行应当依法对高级管理人员的变动情况予以披露。"},{"i":30,"n":"第三十条","txt":"基金管理公司董事长兼任其他职务的，应当经董事会批准，并自批准之日起3个工作日内向中国证监会报告。其他高级管理人员不得在经营性机构兼职。 基金管理公司董事不得担任基金托管银行或者其他基金管理公司的任何职务。董事兼职的，基金管理公司应当自其兼职之日起3个工作日内向中国证监会报告。"},{"i":31,"n":"第三十一条","txt":"基金管理公司高级管理人员有下列情形之一的，督察长应当在知悉该信息之日起3个工作日内，向中国证监会报告： （一）因涉嫌违法违纪被有关机关调查或者处理； （二）辞职、离职、丧失民事行为能力或者因其他原因不能履行职务； （三）拟因私出境1个月以上或者出境逾期未归； （四）直系亲属拟移居境外或者已在境外定居； （五）在非经营性机构兼职； （六）其他可能影响高级管理人员正常履行职务的情形。 督察长发生以上情形时，公司总经理、其他高级管理人员应当向中国证监会报告。"},{"i":32,"n":"第三十二条","txt":"基金管理公司被行业协会、证券交易所等自律组织纪律处分，或者被工商、税务和审计等行政管理部门立案调查、行政处罚的，公司应当自知悉之日起3个工作日内，将相关情况及负有责任的高级管理人员名单向中国证监会报告。"},{"i":33,"n":"第三十三条","txt":"基金管理公司董事长、总经理或者督察长因故不能履行职务的，公司董事会应当在15个工作日内决定由符合高级管理人员任职条件的人员代为履行职务，并在作出决定之日起3个工作日内报中国证监会报告。 董事会决定的人员不符合高级管理人员任职条件的，中国证监会责令董事会限期另行决定代为履行职务的人员。 代为履行职务的时间不得超过90日，但法律、行政法规另有规定的除外。"},{"i":34,"n":"第三十四条","txt":"基金管理公司董事长和总经理因故同时不能履行职务，董事会不能按照前条规定决定代为履行职务人员的，主要股东应当召开临时股东会议，作出决定。"},{"i":35,"n":"第三十五条","txt":"基金管理公司、基金托管银行基金托管部门或者高级管理人员有下列情形之一的，中国证监会依法对相关高级管理人员出具警示函、进行监管谈话： （一）业务活动可能严重损害基金财产或者基金份额持有人的利益； （二）基金管理公司的治理结构、内部控制制度或者基金托管银行基金托管部门的内部控制制度不健全、执行不力，导致出现或者可能出现重大隐患，可能影响其正常履行基金管理人、基金托管人职责； （三）违反诚信、审慎、勤勉、忠实义务； （四）中国证监会根据审慎监管原则规定的其他情形。"},{"i":36,"n":"第三十六条","txt":"高级管理人员有下列情形之一的，中国证监会可以建议任职机构暂停或者免除其职务： （一）最近1年内中国证监会出具警示函、进行监管谈话两次以上，或者在收到警示函、被监管谈话后不按照规定整改； （二）最近1年内受到行业协会纪律处分、证券交易所公开谴责两次以上； （三）擅离职守； （四）向中国证监会提供虚假信息、隐瞒重大事项，或者拒绝配合中国证监会履行监管职责； （五）中国证监会规定的其他情形。"},{"i":37,"n":"第三十七条","txt":"中国证监会按照前条规定作出建议之前，应当事先告知相关高级管理人员的任职机构。相关高级管理人员可以在3个工作日内向任职机构作出说明，任职机构对中国证监会拟作出的建议有异议的，应当在10个工作日内向中国证监会报告。 任职机构应当自收到中国证监会建议之日起20个工作日内，作出是否暂停或者免除相关高级管理人员职务的决定，并在作出决定之日起3个工作日内向中国证监会报告。 基金管理公司及基金托管银行不得聘用被按照前款规定免职未满两年的人员担任高级管理人员。"},{"i":38,"n":"第三十八条","txt":"基金管理公司应当建立高级管理人员、董事和基金经理的离任制度，对离任审计、离任审查等事项作出规定。 基金托管银行应当建立基金托管部门高级管理人员的离任制度，对离任审查等事项作出规定。"},{"i":39,"n":"第三十九条","txt":"基金管理公司董事长、总经理离任的，公司应当立即聘请具有从事证券相关业务资格的会计师事务所进行离任审计，并自离任之日起30个工作日内将审计报告报送中国证监会。 审计报告应当附有被审计人的书面意见；被审计人员拒绝对审计报告发表意见的，应当注明。"},{"i":40,"n":"第四十条","txt":"基金管理公司副总经理、督察长、基金经理离任的，公司应当立即对其进行离任审查，并自离任之日起30个工作日内将审查报告报送中国证监会。 基金托管部门高级管理人员离任的，基金托管银行应当立即对其进行离任审查，并自离任之日起30个工作日内将审查报告报送中国证监会。 审查报告应当附有被审查人的书面意见；被审查人员拒绝对审查报告发表意见的，应当注明。"},{"i":41,"n":"第四十一条","txt":"高级管理人员、基金经理离开任职机构的，应当配合原任职机构完成工作移交，并接受离任审计或者离任审查；在离任审计或者离任审查期间，不得到其他基金管理公司、基金托管银行基金托管部门任职。"},{"i":42,"n":"第四十二条","txt":"高级管理人员、基金经理离开任职机构后，不得泄漏原任职机构的非公开信息，不得利用非公开信息为本人或者他人谋取利益。 基金管理公司不得聘用离任未满3个月的高级管理人员、基金经理从事证券投资业务。"},{"i":43,"n":"第四十三条","txt":"高级管理人员、基金管理公司的董事或者基金经理违反法律、行政法规和中国证监会的规定，依法应予行政处罚的，依照有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"未经中国证监会审核批准，基金管理公司、基金托管银行擅自选任或者改任高级管理人员的，责令改正；对直接负责的主管人员和其他直接责任人员给予警告，并处罚款。 基金管理公司违反本办法的规定，决定代为履行高级管理人员职务人员的，责令改正；对直接负责的主管人员和其他直接责任人员给予警告，并处罚款。"},{"i":45,"n":"第四十五条","txt":"基金管理公司、基金托管银行有下列情形之一的，责令改正，给予警告，并处罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处罚款： （一）未按照本办法的规定履行报告义务，或者报送的报告材料存在虚假内容； （二）违反程序免去高级管理人员职务或者任免基金管理公司董事、基金经理； （三）对中国证监会作出的暂停或者免除高级管理人员职务的建议，未按照规定作出相应处理； （四）违反本办法第四十二条第二款的规定，聘用从事投资业务的人员； （五）不按照本办法规定对离任人员进行离任审计、离任审查。"},{"i":46,"n":"第四十六条","txt":"高级管理人员和基金管理公司董事违反本办法的规定兼任其他职务的，责令改正，给予警告，并处罚款。"},{"i":47,"n":"第四十七条","txt":"高级管理人员违反法律、行政法规和中国证监会的规定，情节严重的，依法暂停或者吊销高级管理人员任职资格。 基金管理人、基金托管人违反证券投资基金法和其他有关法律、行政法规和中国证监会的规定，情节严重的，依法暂停或者吊销直接负责的高级管理人员任职资格。"},{"i":48,"n":"第四十八条","txt":"本办法自2004年10月1日起施行。中国证监会发布的《基金从业人员资格管理办法暂行规定（证监发[1999]53号）》同时废止。"}],"zhengquantouzijijinpingjiayewuguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了规范证券投资基金评价业务，引导证券投资基金的长期投资理念，保障基金投资人和相关当事人的合法权益，根据《证券法》、《证券投资基金法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，基金评价机构对证券投资基金（以下简称基金）进行评价并通过公开形式发布基金评价结果，适用本办法。 基金评价机构仅通过非公开形式发布基金评价结果的，不适用本办法。但该机构应当与使用基金评价结果的对象签订协议，禁止对方对结果进行公开引用。"},{"i":3,"n":"第三条","txt":"本办法所称基金评价业务，包括基金评价机构及其评价人员对基金的投资收益和风险或基金管理人的管理能力开展评级、评奖、单一指标排名或中国证监会认定的其他评价活动。 评级是指基金评价机构及其评价人员运用特定的方法对基金的投资收益和风险或基金管理人的管理能力进行综合性分析，并使用具有特定含义的符号、数字或文字展示分析结果的活动。 公开形式指通过报刊、电台、电视台、互联网等公众传播媒体形式或讲座、报告会、分析会、电脑终端、电话、传真、电子邮件、短信等形式，向非特定对象发布基金评价结果。"},{"i":4,"n":"第四条","txt":"从事基金评价业务，应当遵循下列原则： （一）长期性原则，即注重对基金的长期评价，培育和引导投资人的长期投资理念，不得以短期、频繁的基金评价结果误导投资人； （二）公正性原则，即保持中立地位，公平对待所有评价对象，不得歪曲、诋毁评价对象，防范可能发生的利益冲突； （三）全面性原则，即全面综合评价基金的投资收益和风险或基金管理人的管理能力，不得将单一指标做为基金评级的唯一标准； （四）客观性原则，即基金评价过程和结果客观准确，不得使用虚假信息作为基金评价的依据，不得发布虚假的基金评价结果； （五）一致性原则，即基金评价标准、方法和程序保持一致，不得使用未经公开披露的评价标准、方法和程序； （六）公开性原则，即使用市场公开披露的信息，不得使用公开披露信息以外的数据。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构依法对基金评价业务活动进行监督管理。中国证券投资基金业协会依法对基金评价业务活动进行自律管理。"},{"i":6,"n":"第六条","txt":"基金评价机构应当加入中国证券投资基金业协会。 中国证券投资基金业协会应当制定严格的基金评价机构自律规则、执业规范、入会标准和入会程序。基金评价机构应当在本办法施行后30个工作日内或开始从事基金评价业务后30个工作日内按照协会公示的要求向协会提请办理入会手续。"},{"i":7,"n":"第七条","txt":"基金评价机构应当在加入中国证券投资基金业协会后15个工作日内向中国证监会报送书面材料进行备案，材料应当包括下列文件： （一）基金评价机构基本情况； （二）企业法人营业执照复印件； （三）从事基金评价业务人员和业务主要负责人的名单、简历、身份证件及基金从业资格证明复印件； （四）完整的基金评价理论基础、标准、方法的说明； （五）内部控制制度和业务流程； （六）诚信承诺书； （七）中国证监会要求提供的其他文件。"},{"i":8,"n":"第八条","txt":"基金评价机构应当具有健全的组织架构和完善的内部控制制度；有足够熟悉基金及其评价业务的专业人员；有完善、系统的评价标准、方法以及严谨的业务规范。"},{"i":9,"n":"第九条","txt":"基金评价机构的内部控制应当促进基金评价业务的有效开展和规范运作： （一）具有可靠的基金信息采集制度，并对信息数据库进行严格的管理，保证信息数据的安全、真实和完整； （二）具有确定的基金评价标准、方法和作业程序，并据此建立和维护信息分析处理系统； （三）建立和执行严格的校正和复核程序，保证评价结果的客观准确； （四）建立基金评价标准、方法和程序的公开披露制度，并真实、准确、完整、及时地进行披露； （五）建立和执行严格规范的文档制度，妥善保留业务数据、工作底稿和相关文件； （六）建立基金评价标准、方法和作业程序的检讨评估制度，保证基金评价业务的一致性； （七）建立基金评价结果发布制度和程序，保证发布的基金评价结果符合相关业务规范的要求。"},{"i":10,"n":"第十条","txt":"基金评价人员应当具备基金从业资格。 基金评价人员是指从事基金评价业务的人员。基金评价人员只有被一家基金评价机构聘用后，方可从事基金评价业务，且基金评价人员不得同时在两个以上的基金评价机构执业。 基金评价机构不得聘用有违法、违规记录的人员从事基金评价业务。"},{"i":11,"n":"第十一条","txt":"从事基金评价业务应当有完善、系统的理论基础、标准和方法。基金评价方法应当基于机构自己的研究成果，不得侵犯其他基金评价机构的有关知识产权。 对基金进行评价应当至少考虑下列内容： （一）基金招募说明书和基金合同约定的投资方向、投资范围、投资方法和业绩比较基准等； （二）基金的风险收益特征； （三）基金投资决策系统及交易系统的有效性和一贯性。 对基金管理人进行评价应当至少考虑下列内容： （一）基金管理公司及其人员的合规性； （二）基金管理公司的治理结构； （三）股东、高级管理人员、基金经理的稳定性； （四）投资管理和研究能力； （五）信息披露和风险控制能力。"},{"i":12,"n":"第十二条","txt":"对基金的分类应当以相关法律、行政法规和中国证监会的规定为标准，可以在法律、行政法规和中国证监会对基金分类规定的基础上进行细分；对法律、行政法规和中国证监会未做规定的分类方法，应当明确标注并说明理由。"},{"i":13,"n":"第十三条","txt":"基金评价机构应当将基金评价标准、评价方法和程序报中国证监会、中国证券投资基金业协会备案，并通过中国证券投资基金业协会网站、本机构网站及至少一家符合中国证监会规定条件的媒体向社会公告。基金评价机构修改上述内容时，应当及时备案、公告。"},{"i":14,"n":"第十四条","txt":"任何机构从事基金评价业务并以公开形式发布评价结果的，不得有下列行为： （一）对不同分类的基金进行合并评价； （二）对同一分类中包含基金少于10只的基金进行评级或单一指标排名； （三）对基金合同生效不足6个月的基金（货币市场基金除外）进行评奖或单一指标排名； （四）对基金（货币市场基金除外）、基金管理人评级的评级期间少于36个月； （五）对基金、基金管理人评级的更新间隔少于3个月； （六）对基金、基金管理人评奖的评奖期间少于12个月； （七）对基金、基金管理人单一指标排名（包括具有点击排序功能的网站或咨询系统数据列示）的排名期间少于3个月； （八）对基金、基金管理人单一指标排名的更新间隔少于1 个月； （九）对特定客户资产管理计划进行评价。"},{"i":15,"n":"第十五条","txt":"基金评价机构与评价对象存在当前或潜在利益冲突时，应当在评级报告、评价报告中声明该机构与评价对象之间的关系，同时说明该机构在评价过程中为规避利益冲突影响而采取的措施。"},{"i":16,"n":"第十六条","txt":"基金评价机构应当避免使用与评价对象存在当前或潜在利益冲突的人员对该对象进行评价。"},{"i":17,"n":"第十七条","txt":"基金评价报告等文件应当声明评价结果并不是对未来表现的预测，也不应视作投资基金的建议。"},{"i":18,"n":"第十八条","txt":"基金评价结果应当以基金评价机构的名义而并非基金评价人员的个人名义发布。"},{"i":19,"n":"第十九条","txt":"基金评价机构应当将其向基金投资人或者社会公众提供的基金评价数据和资料，自提供之日起保存15年。"},{"i":20,"n":"第二十条","txt":"基金管理人、基金销售机构及符合中国证监会规定条件的媒体不得引用不具备中国证券投资基金业协会会员资格的机构提供的基金评价结果。"},{"i":21,"n":"第二十一条","txt":"基金管理人、基金销售机构及符合中国证监会规定条件的媒体决定与基金评价机构合作并引用基金评价结果的，应当事先根据本办法第九条的要求对拟合作的基金评价机构进行审慎调查，核查其内部控制是否能够保障基金评价业务的有效开展和规范运作。 基金管理人、基金销售机构及符合中国证监会规定条件的媒体应当避免引用违反本办法第九条内部控制规范要求的基金评价机构提供的基金评价结果。"},{"i":22,"n":"第二十二条","txt":"基金管理人、基金销售机构及符合中国证监会规定条件的媒体决定引用基金评价结果的，应当事先根据本办法第十四条要求的业务规范对基金评价结果做出审查，发现有违反业务规范情形的，应当提请基金评价机构做出调整或拒绝进行引用。"},{"i":23,"n":"第二十三条","txt":"基金评价机构及其评价人员违反本办法规定从事基金评价活动的，中国证监会依法采取责令改正、监管谈话、出具警示函等监管措施；情节严重的，依法进行行政处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。"},{"i":24,"n":"第二十四条","txt":"中国证券投资基金业协会应当对违反自律准则和执业规范的行为给予纪律处分；情节严重的，取消会员资格。"},{"i":25,"n":"第二十五条","txt":"基金评价机构应当按照中国证券投资基金业协会的规定向其提交相关备案文件和年度报告。"},{"i":26,"n":"第二十六条","txt":"中国证券投资基金业协会应当建立基金评价机构及其评价人员从事基金评价业务的资料库和诚信档案，通过适当方式公布基金评价机构会员情况，并建立对基金评价行为的跟踪机制。"},{"i":27,"n":"第二十七条","txt":"中国证券投资基金业协会可以对基金评价机构及其评价人员的业务活动进行检查，被检查的基金评价机构应当予以配合，不得干扰和阻碍。中国证券投资基金业协会应当将检查过程中发现的问题及时向中国证监会报告。"},{"i":28,"n":"第二十八条","txt":"基金评价机构加入中国证券投资基金业协会后，未按照本办法第七条的规定向中国证监会备案，擅自从事基金评价业务的，责令改正，单处或者并处警告、罚款；对直接负责的主管人员和其他直接责任人员单处或者并处警告、罚款。"},{"i":29,"n":"第二十九条","txt":"基金管理人、基金销售机构及符合中国证监会规定条件的媒体引用或发布不具备中国证券投资基金业协会会员资格的基金评价机构提供的基金评价结果的，中国证监会采取责令改正、出具警示函等监管措施，单处或者并处警告、罚款；对直接负责的主管人员和其他直接责任人员单处或者并处警告、罚款。"},{"i":30,"n":"第三十条","txt":"基金评价机构违反本办法规定，聘任不具备基金从业资格的人员的，中国证监会采取责令改正等监管措施，单处或者并处警告、罚款；对直接负责的主管人员和其他直接责任人员单处或者并处警告、罚款。"},{"i":31,"n":"第三十一条","txt":"基金评价机构未按照本办法规定保存有关文件和资料的，责令改正，单处或者并处警告、罚款。"},{"i":32,"n":"第三十二条","txt":"基金评价机构有下列行为之一的，中国证监会采取责令改正、监管谈话、出具警示函等监管措施，单处或者并处警告、罚款： （一）内部控制制度不符合本办法第九条的规定； （二）基金评价标准和方法不符合本办法第十一条、第十二条的规定； （三）未按照本办法第十三条规定公开披露基金评价标准、方法和程序，或未按照公开披露的基金评价标准、方法和程序从事基金评价业务； （四）违反本办法第十四条的规定进行基金评价或发布基金评价结果； （五）违反本办法第十五条和第十六条规定的利益冲突防范制度； （六）不公平对待评价对象，或贬低、诋毁其他基金评价机构、评价人员等不正当竞争行为。"},{"i":33,"n":"第三十三条","txt":"本办法自2010年1月1日起施行。"}],"zhengquantouzizhebaohujijinguanlibanfa":[{"i":1,"n":"第一条","txt":"为建立防范和处置证券公司风险的长效机制，维护社会经济秩序和社会公共利益，保护证券投资者的合法权益，促进证券市场有序、健康发展，制定本办法。"},{"i":2,"n":"第二条","txt":"证券投资者保护基金（以下简称基金）是指按照本办法筹集形成的、在防范和处置证券公司风险中用于保护证券投资者利益的资金。 设立国有独资的中国证券投资者保护基金有限责任公司（以下简称基金公司），负责基金的筹集、管理和使用。"},{"i":3,"n":"第三条","txt":"基金主要用于按照国家有关政策规定对债权人予以偿付。"},{"i":4,"n":"第四条","txt":"证券交易活动实行公开、公平、公正和投资者投资决策自主、投资风险自担的原则。 投资者在证券投资活动中因证券市场波动或投资产品价值本身发生变化所导致的损失，由投资者自行负担。"},{"i":5,"n":"第五条","txt":"基金按照取之于市场、用之于市场的原则筹集。基金的筹集方式、标准，由中国证券监督管理委员会（以下简称证监会）商财政部、中国人民银行决定。"},{"i":6,"n":"第六条","txt":"基金公司依据国家有关法律、法规及本办法独立运作，基金公司董事会对基金的合规使用及安全负责。"},{"i":7,"n":"第七条","txt":"基金公司的职责为： （一）筹集、管理和运作基金； （二）监测证券公司风险，参与证券公司风险处置工作； （三）证券公司被撤销、被关闭、破产或被证监会实施行政接管、托管经营等强制性监管措施时，按照国家有关政策规定对债权人予以偿付； （四）组织、参与被撤销、关闭或破产证券公司的清算工作； （五）管理和处分受偿资产，维护基金权益； （六）发现证券公司经营管理中出现可能危及投资者利益和证券市场安全的重大风险时，向证监会提出监管、处置建议；对证券公司运营中存在的风险隐患会同有关部门建立纠正机制； （七）国务院批准的其他职责。"},{"i":8,"n":"第八条","txt":"基金公司应当与证监会建立证券公司信息共享机制，证监会定期向基金公司通报关于证券公司财务、业务等的经营管理信息。 证监会认定存在风险隐患的证券公司，应按照规定直接向基金公司报送财务、业务等经营管理信息和资料。"},{"i":9,"n":"第九条","txt":"基金公司设立董事会。董事会由9名董事组成。其中4人为执行董事，其他为非执行董事。董事长人选由证监会商财政部、中国人民银行确定后，报国务院备案。"},{"i":10,"n":"第十条","txt":"董事会为基金公司的决策机构，负责制定基本管理制度，决定内部管理机构设置，聘任或者解聘高级管理人员，对基金的筹集、管理和使用等重大事项做出决定，并行使基金公司章程规定的其他职权。"},{"i":11,"n":"第十一条","txt":"基金公司董事会按季召开例会。董事长或1/3以上的董事联名提议时，可以召开临时董事会会议。 董事会会议由全体董事2/3以上出席方可举行。董事会会议决议，由全体董事1/2以上表决通过方为有效。"},{"i":12,"n":"第十二条","txt":"基金公司设总经理1人，副总经理若干人。总经理负责主持公司的经营管理工作，执行董事会决议。总经理、副总经理由证监会提名，董事会聘任或者解聘。"},{"i":13,"n":"第十三条","txt":"基金公司章程由证监会商财政部、中国人民银行依照法律、行政法规和本办法制定。"},{"i":14,"n":"第十四条","txt":"基金的来源： （一）上海、深圳证券交易所在风险基金分别达到规定的上限后，交易经手费的20%纳入基金； （二）所有在中国境内注册的证券公司，按其营业收入的0.5—5%缴纳基金； 经营管理或运作水平较差、风险较高的证券公司，应当按较高比例缴纳基金。各证券公司的具体缴纳比例由基金公司根据证券公司风险状况确定后，报证监会批准，并按年进行调整。证券公司缴纳的基金在其营业成本中列支； （三）发行股票、可转债等证券时，申购冻结资金的利息收入； （四）依法向有关责任方追偿所得和从证券公司破产清算中受偿收入； （五）国内外机构、组织及个人的捐赠； （六）其他合法收入。"},{"i":15,"n":"第十五条","txt":"基金公司设立时，财政部专户储存的历年认购新股冻结资金利差余额，一次性划入，作为基金公司的注册资本；中国人民银行安排发放专项再贷款，垫付基金的初始资金。专项再贷款余额的上限以国务院批准额度为准。"},{"i":16,"n":"第十六条","txt":"根据防范和处置证券公司风险的需要，基金公司可以多种形式进行融资。必要时，经国务院批准，基金公司可以通过发行债券等方式获得特别融资。 基金公司因履行职责需要流动性支持时，证监会会同中国人民银行报请国务院批准后，可以向中国人民银行申请再贷款。"},{"i":17,"n":"第十七条","txt":"证券公司采用当年预缴、次年汇算清缴的方式缴纳基金。 证券公司应在年度审计结束后，根据其审计后的收入和事先核定的比例确定需要缴纳的基金金额，并及时向基金公司申报清缴。"},{"i":18,"n":"第十八条","txt":"中国证券登记结算有限责任公司及各主承销商应于每季结息后5个工作日内，将证券发行申购冻结资金利息全额划入基金公司指定的账户；证券交易所应于每季后10个工作日内，将交易经手费中应纳入基金的部分划入基金公司指定的账户。"},{"i":19,"n":"第十九条","txt":"基金的用途为： （一）证券公司被撤销、被关闭、破产或被证监会实施行政接管、托管经营等强制性监管措施时，按照国家有关政策规定对债权人予以偿付； （二）国务院批准的其他用途。"},{"i":20,"n":"第二十条","txt":"为处置证券公司风险需要动用基金的，证监会根据证券公司的风险状况制定风险处置方案，基金公司制定基金使用方案，报经国务院批准后，由基金公司办理发放基金的具体事宜。"},{"i":21,"n":"第二十一条","txt":"基金公司使用基金偿付证券公司债权人后，取得相应的受偿权，依法参与证券公司的清算。"},{"i":22,"n":"第二十二条","txt":"基金公司应依法合规运作，按照安全、稳健的原则履行对基金的管理职责，保证基金的安全。 基金的资金运用限于银行存款、购买政府债券、中央银行票据、中央企业债券、信用等级较高的金融机构发行的金融债券以及国务院批准的其他资金运用形式。"},{"i":23,"n":"第二十三条","txt":"基金公司日常运营费用按照国家有关规定列支，具体支取范围、标准及预决算等由基金公司董事会制定，报财政部审批。"},{"i":24,"n":"第二十四条","txt":"证监会负责基金公司的业务监管，监督基金的筹集、管理与使用。 财政部负责基金公司的国有资产管理和财务监督。 中国人民银行负责对基金公司向其借用再贷款资金的合规使用情况进行检查监督。"},{"i":25,"n":"第二十五条","txt":"基金公司应建立科学的业绩考评制度，并将考核结果定期报送证监会、财政部、中国人民银行。"},{"i":26,"n":"第二十六条","txt":"基金公司应建立信息报告制度，编制基金筹集、管理、使用的月报信息，报送证监会、财政部、中国人民银行。 基金公司每年应向财政部专题报告财务收支及预算、决算执行情况，接受财政部的监督检查。 基金公司每年应向中国人民银行专题报告再贷款资金的使用情况，接受中国人民银行的监督检查。"},{"i":27,"n":"第二十七条","txt":"证监会应按年度向国务院报告基金公司运作和证券公司风险处置情况，同时抄送财政部、中国人民银行。"},{"i":28,"n":"第二十八条","txt":"证券公司、托管清算机构应按规定用途使用基金，不得将基金挪作他用。 基金公司对使用基金的情况进行检查，并可委托中介机构进行专项审计。接受检查的证券公司或托管清算机构及有关单位、个人应予以配合。"},{"i":29,"n":"第二十九条","txt":"基金公司、证券公司及托管清算机构应妥善保管基金的收划款凭证、兑付清单及原始凭证，确保原始档案的完整性，并建立基金核算台账。"},{"i":30,"n":"第三十条","txt":"证监会负责监督证券公司按期足额缴纳基金以及按期向基金公司如实报送财务、业务等经营管理信息、资料和基金公司监测风险所需的涉及客户资金安全的数据、材料。 证券公司违反前款规定的，证监会应按有关规定进行处理。"},{"i":31,"n":"第三十一条","txt":"对挪用、侵占或骗取基金的违法行为，依法严厉打击；对有关人员的失职行为，依法追究其责任；涉嫌犯罪的，移送司法机关依法追究其刑事责任。"},{"i":32,"n":"第三十二条","txt":"本办法所称托管清算机构，是指证券公司被行政接管、托管经营、撤销、关闭或破产时，对证券公司实施行政接管的接管组、实施托管经营的托管组或依法成立的行政清理组。"},{"i":33,"n":"第三十三条","txt":"本办法自2016年6月1日起施行。"},{"i":34,"n":"第三十四条","txt":"本办法由证监会会同财政部、中国人民银行负责解释。"}],"zhengquanqihuoyexinxianquanbaozhangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保障证券期货信息系统安全运行，加强证券期货业信息安全管理工作，促进证券期货市场稳定健康发展，保护投资者合法权益，根据《证券法》、《证券投资基金法》、《期货交易管理条例》及信息安全保障相关的法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"证券期货业信息安全保障、管理、监督等工作适用本办法。"},{"i":3,"n":"第三条","txt":"证券期货业信息安全保障工作实行“谁运行、谁负责，谁使用、谁负责”、安全优先、保障发展的原则。"},{"i":4,"n":"第四条","txt":"证券期货业信息安全保障的责任主体应当执行国家信息安全相关法律、行政法规和行业相关技术管理规定、技术规则、技术指引和技术标准，开展信息安全工作，保护投资者交易安全和数据安全，并对本机构信息系统安全运行承担责任。 前款所称责任主体，包括承担证券期货市场公共职能的机构、承担证券期货行业信息技术公共基础设施运营的机构等证券期货市场核心机构及其下属机构（以下简称核心机构），证券公司、期货公司、基金管理公司、证券期货服务机构等证券期货经营机构（以下简称经营机构）。"},{"i":5,"n":"第五条","txt":"开展证券客户交易结算资金第三方存管业务，银证、银期、银基转账和结算业务，基金托管和销售业务的机构应当按照有关规定保障相关业务系统的安全运行。"},{"i":6,"n":"第六条","txt":"为证券期货业提供软硬件产品或者技术服务的供应商（以下简称供应商），应当保证所提供的软硬件产品或者技术服务符合国家及证券期货业信息安全相关的技术管理规定、技术规则、技术指引和技术标准。"},{"i":7,"n":"第七条","txt":"中国证监会支持、协助国家信息安全管理部门组织实施信息安全相关法律、行政法规，依法对证券期货业信息安全保障工作实施监督管理。 中国证监会派出机构按照授权履行监督管理职责。"},{"i":8,"n":"第八条","txt":"中国证监会及其派出机构与国家信息安全管理部门、相关行业管理部门建立信息安全协调机制，与国家有关专业安全机构和标准化组织建立信息安全合作机制。"},{"i":9,"n":"第九条","txt":"证券、期货、证券投资基金等行业协会（以下简称证券期货行业协会）依照本办法的规定，对会员的信息安全工作实行自律管理。"},{"i":10,"n":"第十条","txt":"核心机构依照本办法的规定，对市场相关主体关联信息系统的安全保障工作进行督促、指导。"},{"i":11,"n":"第十一条","txt":"核心机构和经营机构应当具有合格的基础设施。机房、电力、空调、消防、通信等基础设施的建设符合行业信息安全管理的有关规定。"},{"i":12,"n":"第十二条","txt":"核心机构和经营机构应当设置合理的网络结构，划分安全区域，各安全区域之间应当进行有效隔离，并具有防范、监控和阻断来自内外部网络攻击破坏的能力。"},{"i":13,"n":"第十三条","txt":"核心机构和经营机构应当建立符合业务要求的信息系统。信息系统应当具有合理的架构，足够的性能、容量、可靠性、扩展性和安全性，能够支持业务的运行和发展。"},{"i":14,"n":"第十四条","txt":"核心机构应当对交易、行情、开户、结算、风控、通信等重要信息系统具有自主开发能力，拥有执行程序和源代码并安全可靠存放，在重要信息系统上线前对执行程序和源代码进行严格的审查和测试。"},{"i":15,"n":"第十五条","txt":"核心机构和经营机构应当具有防范木马、病毒等恶意代码的能力，防止恶意代码对信息系统造成破坏，防止信息泄露或者被篡改。"},{"i":16,"n":"第十六条","txt":"核心机构和经营机构应当建立完善的信息技术治理架构，明确信息技术决策、管理、执行和内部监督的权责机制。"},{"i":17,"n":"第十七条","txt":"核心机构和经营机构应当建立完善的信息技术管理制度和操作规程，并严格执行。"},{"i":18,"n":"第十八条","txt":"核心机构应当制定本机构与市场相关主体信息系统安全互联的技术规则，并报中国证监会备案。 核心机构依法督促市场相关主体执行技术规则。"},{"i":19,"n":"第十九条","txt":"核心机构应当提供多种互为备份的远程接入方式，保证市场相关主体安全接入，并对市场相关主体的远程接入进行监控与管理。"},{"i":20,"n":"第二十条","txt":"核心机构和经营机构应当保障充足、稳定的信息技术经费投入，配备足够的信息技术人员。"},{"i":21,"n":"第二十一条","txt":"核心机构和经营机构应当根据行业规划和本机构发展战略，制定信息化与信息安全发展规划，满足业务发展和信息安全管理的需要。"},{"i":22,"n":"第二十二条","txt":"核心机构和经营机构开展信息系统新建、升级、变更、换代等建设项目，应当进行充分论证和测试。"},{"i":23,"n":"第二十三条","txt":"核心机构交易、行情、开户、结算、通信等重要信息系统上线或者进行重大升级变更时，应当组织市场相关主体进行联网测试，并按规定进行报告。"},{"i":24,"n":"第二十四条","txt":"核心机构和经营机构应当规范开展信息技术基础设施和重要信息系统的运行维护，保障系统安全稳定运行。"},{"i":25,"n":"第二十五条","txt":"核心机构应当指导市场相关主体正确运行维护与本机构互联的系统和通信设施。"},{"i":26,"n":"第二十六条","txt":"核心机构和经营机构应当建立数据备份设施，并按照规定在同城和异地保存备份数据。"},{"i":27,"n":"第二十七条","txt":"核心机构和经营机构应当建立重要信息系统的故障备份设施和灾难备份设施，保证业务活动连续。"},{"i":28,"n":"第二十八条","txt":"核心机构和经营机构应当按照规定向中国证监会指定的证券期货业数据中心报送数据。报送的数据必须真实、完整、准确、及时。 证券期货业数据中心应当按照中国证监会的有关规定开展行业数据的集中保存工作，确保数据的安全、完整、可靠。"},{"i":29,"n":"第二十九条","txt":"核心机构负责建设和运营行业信息技术公共基础设施。"},{"i":30,"n":"第三十条","txt":"核心机构和经营机构应当加强信息安全保密管理，保障投资者信息安全。"},{"i":31,"n":"第三十一条","txt":"核心机构和经营机构应当建立网络与信息安全风险检测、监测、评估和预警机制，发现风险隐患应当及时处置，并按照规定进行报告。"},{"i":32,"n":"第三十二条","txt":"核心机构和经营机构应当建立信息安全应急处置机制，及时处置突发信息安全事件，尽快恢复信息系统的正常运行，并按照规定进行报告，不得迟报、漏报、瞒报。 核心机构和经营机构应当对信息安全事件进行内部调查、责任追究和采取整改措施，并配合中国证监会及其派出机构对事件进行调查处理。 与核心机构和经营机构发生信息安全事件相关的软硬件产品或者技术服务供应商，应当配合相关调查工作。"},{"i":33,"n":"第三十三条","txt":"核心机构应当每年组织市场相关主体进行一次信息安全应急演练，并于实施前15个工作日向中国证监会报告。"},{"i":34,"n":"第三十四条","txt":"核心机构和经营机构应当对信息技术人员进行培训，确保其具有履行岗位职责的能力。"},{"i":35,"n":"第三十五条","txt":"核心机构和经营机构应当建立信息安全内部审计制度，定期开展内部审计，对发现的问题进行整改。"},{"i":36,"n":"第三十六条","txt":"核心机构和经营机构应当建立供应商管理制度，定期对供应商的资质、专业经验、产品和服务的质量进行了解和评估。"},{"i":37,"n":"第三十七条","txt":"核心机构和经营机构在采购软硬件产品或者技术服务时，应当与供应商签订合同和保密协议，并在合同和保密协议中明确约定信息安全和保密的权利和义务。 涉及证券期货交易、行情、开户、结算等软件产品或者技术服务的采购合同，应当约定供应商须接受中国证监会及其派出机构的信息安全延伸检查。"},{"i":38,"n":"第三十八条","txt":"核心机构和经营机构采购的软硬件产品或者技术服务应当满足审慎经营和风险管理的要求。软硬件产品或者技术服务不符合要求，影响核心机构和经营机构持续经营的，中国证监会有权要求核心机构和经营机构予以改进或者更换。"},{"i":39,"n":"第三十九条","txt":"证券期货行业协会应当制定信息技术指引，督促、引导会员执行国家和行业信息安全相关规定和技术标准。"},{"i":40,"n":"第四十条","txt":"证券期货行业协会应当引导行业加强信息技术人才队伍建设，定期组织信息技术培训和交流，提高信息技术人员执业素质。"},{"i":41,"n":"第四十一条","txt":"证券期货行业协会应当引导鼓励行业信息技术研究与创新，增强自主可控能力，组织开展科技奖励，促进行业科技进步。"},{"i":42,"n":"第四十二条","txt":"证券期货行业协会应当引导供应商规范参与行业信息化与信息安全工作，促进市场公平竞争，促进供应商与市场相关主体共同发展。"},{"i":43,"n":"第四十三条","txt":"中国证监会建立统一组织、分级负责的信息安全监督管理体制。 中国证监会信息安全管理部门负责证券期货业信息安全工作的组织、协调和指导；相关业务监管部门依照职责范围对核心机构和经营机构的信息安全进行监督、检查；派出机构根据授权对辖区内经营机构的信息安全进行监督、检查。"},{"i":44,"n":"第四十四条","txt":"中国证监会依法组织制定证券期货业信息安全管理规定和技术标准。"},{"i":45,"n":"第四十五条","txt":"中国证监会及其派出机构依照职责范围，对核心机构和经营机构进行信息安全检查或者委托国家、行业有关专业安全机构进行安全检查。核心机构和经营机构应当配合检查。 核心机构和经营机构的信息安全管理不能达到规定要求的，中国证监会及其派出机构责令其限期改正，改正前可以暂停或者限制其部分或者全部证券期货经营业务活动。"},{"i":46,"n":"第四十六条","txt":"中国证监会及其派出机构可以要求核心机构和经营机构提供信息安全相关资料。 核心机构和经营机构应当及时、准确、完整地提供相关资料。"},{"i":47,"n":"第四十七条","txt":"中国证监会组织制定证券期货业信息安全应急预案，督促、指导行业开展信息安全应急工作。"},{"i":48,"n":"第四十八条","txt":"中国证监会有权对核心机构、经营机构的信息安全事件进行调查处理。 对于损害投资者合法权益或者影响证券期货市场安全稳定运行的信息安全事件，中国证监会依法对相关单位采取监督管理措施或者行政处罚。"},{"i":49,"n":"第四十九条","txt":"中国证监会对发现的系统漏洞、安全隐患、产品缺陷进行全行业通报。"},{"i":50,"n":"第五十条","txt":"核心机构和经营机构违反本办法规定，中国证监会可以视情节，依法对其采取责令改正、监管谈话、出具警示函、公开谴责、责令定期报告、责令处分有关人员、撤销任职资格、暂停或者限制证券期货经营业务活动等措施；情节严重的，给予警告、罚款。"},{"i":51,"n":"第五十一条","txt":"本办法自2012年11月1日起施行。《证券期货业信息安全保障管理暂行办法》（证监信息字〔2005〕5号）同时废止。"}],"zhengquanqihuoyefanxiqiangongzuoshishibanfa":[{"i":1,"n":"第一条","txt":"为进一步配合国务院反洗钱行政主管部门加强证券期货业反洗钱工作，有效防范证券期货业洗钱和恐怖融资风险，规范行业反洗钱监管行为，推动证券期货经营机构认真落实反洗钱工作，维护证券期货市场秩序，根据《中华人民共和国反洗钱法》（以下简称《反洗钱法》）、《中华人民共和国证券法》、《中华人民共和国证券投资基金法》及《期货交易管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内的证券期货业反洗钱工作。 从事基金销售业务的机构在基金销售业务中履行反洗钱责任适用本办法。"},{"i":3,"n":"第三条","txt":"中国证券监督管理委员会（以下简称证监会）依法配合国务院反洗钱行政主管部门履行证券期货业反洗钱监管职责，制定证券期货业反洗钱工作的规章制度，组织、协调、指导证券公司、期货公司和基金管理公司（以下简称证券期货经营机构）的反洗钱工作。 证监会派出机构按照本办法的规定，履行辖区内证券期货业反洗钱监管职责。"},{"i":4,"n":"第四条","txt":"中国证券业协会和中国期货业协会依照本办法的规定，履行证券期货业反洗钱自律管理职责。"},{"i":5,"n":"第五条","txt":"证券期货经营机构应当依法建立健全反洗钱工作制度，按照本办法规定向当地证监会派出机构报送相关信息。证券期货经营机构发现证券期货业内涉嫌洗钱活动线索，应当依法向反洗钱行政主管部门、侦查机关举报。"},{"i":6,"n":"第六条","txt":"证监会负责组织、协调、指导证券期货业的反洗钱工作，履行以下反洗钱工作职责： （一）配合国务院反洗钱行政主管部门研究制定证券期货业反洗钱工作的政策、规划，研究解决证券期货业反洗钱工作重大和疑难问题，及时向国务院反洗钱行政主管部门通报反洗钱工作信息； （二）参与制定证券期货经营机构反洗钱有关规章，对证券期货经营机构提出建立健全反洗钱内控制度的要求，在证券期货经营机构市场准入和人员任职方面贯彻反洗钱要求； （三）配合国务院反洗钱行政主管部门对证券期货经营机构实施反洗钱监管； （四）会同国务院反洗钱行政主管部门指导中国证券业协会、中国期货业协会制定反洗钱工作指引，开展反洗钱宣传和培训； （五）研究证券期货业反洗钱的重大问题并提出政策建议； （六）及时向侦查机关报告涉嫌洗钱犯罪的交易活动，协助司法部门调查处理涉嫌洗钱犯罪案件； （七）对派出机构落实反洗钱监管工作情况进行考评，对中国证券业协会、中"},{"i":7,"n":"第七条","txt":"证监会派出机构履行以下反洗钱工作职责： （一）配合当地反洗钱行政主管部门对辖区证券期货经营机构实施反洗钱监管，并建立信息交流机制； （二）定期向证监会报送辖区内半年度和年度反洗钱工作情况，及时报告辖区证券期货经营机构受反洗钱行政主管部门检查或处罚等信息及相关重大事件； （三）组织、指导辖区证券期货业的反洗钱培训和宣传工作； （四）研究辖区证券期货业反洗钱工作问题，并提出改进措施； （五）法律、行政法规以及证监会规定的其他职责。"},{"i":8,"n":"第八条","txt":"中国证券业协会、中国期货业协会履行以下反洗钱工作职责： （一）在证监会的指导下，制定和修改行业反洗钱相关工作指引； （二）组织会员单位开展反洗钱培训和宣传工作； （三）定期向证监会报送协会年度反洗钱工作报告，及时报告相关重大事件； （四）组织会员单位研究行业反洗钱工作的相关问题； （五）法律、行政法规以及证监会规定的其他职责。"},{"i":9,"n":"第九条","txt":"证券期货经营机构应当依法履行反洗钱义务，建立健全反洗钱内部控制制度。证券期货经营机构负责人应当对反洗钱内部控制制度的有效实施负责，总部应当对分支机构执行反洗钱内部控制制度进行监督管理，根据要求向当地证监会派出机构报告反洗钱工作开展情况。"},{"i":10,"n":"第十条","txt":"证券期货经营机构应当向当地证监会派出机构报送其内部反洗钱工作部门设置、负责人及专门负责反洗钱工作的人员的联系方式等相关信息。如有变更，应当自变更之日起10个工作日内报送更新后的相关信息。"},{"i":11,"n":"第十一条","txt":"证券期货经营机构应当在发现以下事项发生后的5个工作日内，以书面方式向当地证监会派出机构报告： （一）证券期货经营机构受到反洗钱行政主管部门检查或处罚的； （二）证券期货经营机构或其客户从事或涉嫌从事洗钱活动，被反洗钱行政主管部门、侦查机关或者司法机关处罚的； （三）其他涉及反洗钱工作的重大事项。"},{"i":12,"n":"第十二条","txt":"证券期货经营机构应当按照反洗钱法律法规的要求及时建立客户风险等级划分制度，并报当地证监会派出机构备案。在持续关注的基础上，应适时调整客户风险等级。"},{"i":13,"n":"第十三条","txt":"证券期货经营机构在为客户办理业务过程中，发现客户所提供的个人身份证件或机构资料涉嫌虚假记载的，应当拒绝办理；发现存在可疑之处的，应当要求客户补充提供个人身份证件或机构原件等足以证实其身份的相关证明材料，无法证实的，应当拒绝办理。"},{"i":14,"n":"第十四条","txt":"证券期货经营机构通过销售机构向客户销售基金等金融产品时，应当通过合同、协议或其他书面文件,明确双方在客户身份识别、客户身份资料和交易记录保存与信息交换、大额交易和可疑交易报告等方面的反洗钱职责和程序。"},{"i":15,"n":"第十五条","txt":"证券期货经营机构应当建立反洗钱工作保密制度，并报当地证监会派出机构备案。 反洗钱工作保密事项包括以下内容： （一）客户身份资料及客户风险等级划分资料； （二）交易记录； （三）大额交易报告； （四）可疑交易报告； （五）履行反洗钱义务所知悉的国家执法部门调查涉嫌洗钱活动的信息； （六）其他涉及反洗钱工作的保密事项。 查阅、复制涉密档案应当实施书面登记制度。"},{"i":16,"n":"第十六条","txt":"证券期货经营机构应当建立反洗钱培训、宣传制度，每年开展对单位员工的反洗钱培训工作和对客户的反洗钱宣传工作，持续完善反洗钱的预防和监控措施。每年年初，应当向当地证监会派出机构上报反洗钱培训和宣传的落实情况。"},{"i":17,"n":"第十七条","txt":"证券期货经营机构不遵守本办法有关报告、备案或建立相关内控制度等规定的，证监会及其派出机构可采取责令改正、监管谈话或责令参加培训等监管措施。"},{"i":18,"n":"第十八条","txt":"本办法自2010年10月1日起施行。"}],"zhengquanqihuoshichangtongjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范证券期货市场统计行为，发挥统计在反映证券期货市场基础信息和动态状况、加强证券期货市场监管中的作用，根据《中华人民共和国统计法》、《中华人民共和国证券法》、《中华人民共和国证券投资基金法》、《期货交易管理条例》、《证券公司监督管理条例》和《中华人民共和国统计法实施细则》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"证券期货市场统计的基本任务是对证券期货市场发展情况进行统计调查、统计分析，提供证券期货市场统计资料和统计咨询意见，实行统计监督。"},{"i":3,"n":"第三条","txt":"证券期货市场统计调查对象（以下简称统计调查对象）应当如实提供证券期货统计资料，不得虚报、瞒报、拒报、迟报，不得伪造、篡改。 本办法所称的统计调查对象，包括证券公司、证券投资基金管理公司、期货公司及其分支机构，基金托管银行、基金销售机构、合格境外机构投资者托管银行，从事证券期货服务业务的投资咨询机构、财务顾问机构、资信评级机构、资产评估机构、会计师事务所、律师事务所，上市公司、非上市公众公司，证券期货交易所、证券登记结算机构、证券业协会、期货业协会、证券投资者保护基金公司、期货保证金监控中心等市场主体。"},{"i":4,"n":"第四条","txt":"中国证券监督管理委员会（以下简称中国证监会）建立集中统一领导，分业务、分级负责的统计管理体制。 中国证监会负责全国证券期货市场（以下简称证券期货市场）的统计工作，中国证监会派出机构负责辖区内的证券期货统计工作。"},{"i":5,"n":"第五条","txt":"中国证监会制定证券期货市场统计标准，发布证券期货市场统计资料或者可能影响证券期货市场稳定运行的其他统计资料。"},{"i":6,"n":"第六条","txt":"统计资料的管理、使用和公布，应当遵守国家档案管理制度、保密制度和证券期货监督管理信息公开制度、证券期货市场诚信档案管理制度，保守统计调查对象的商业秘密，维护证券期货市场公开、公平、公正的原则。"},{"i":7,"n":"第七条","txt":"中国证监会统计部门履行以下职责： （一）组织证券期货市场统计调查工作，搜集、整理证券期货统计资料，管理、公布、汇编、对外提供证券期货市场统计资料； （二）对证券期货市场运行、发展、风险等情况进行统计分析，编制证券期货市场统计报表，出具统计报告，提出有关的政策建议； （三）建立健全证券期货统计制度，制定证券期货市场统计标准，完善证券期货统计指标体系，对统计法律、行政法规、本办法及中国证监会制定的统计制度的执行情况进行指导和检查监督，对中国证监会派出机构、统计调查对象的统计工作进行考核评估； （四）建设并管理证券期货统计信息自动化系统和统计数据库体系； （五）负责办理与会外单位之间的统计协调工作； （六）办理中国证监会派出机构统计调查项目和证券期货市场统计调查项目补充内容的备案； （七）组织开展证券期货市场统计人员的业务培训。"},{"i":8,"n":"第八条","txt":"中国证监会履行监管职责的其他部门（以下简称中国证监会其他部门）对其职责范围内的统计调查对象进行统计调查，搜集、整理证券期货统计资料。 中国证监会其他部门应当配合中国证监会统计部门的工作。"},{"i":9,"n":"第九条","txt":"中国证监会统计部门建立证券期货市场统计工作联席会议机制，其成员单位包括中国证监会统计部门、中国证监会其他部门、证券期货交易所、证券登记结算机构等。 除中国证监会统计部门之外的其他成员单位按照约定的格式与内容，定期或者不定期地向中国证监会统计部门报送本单位搜集、整理、管理的证券期货统计资料。证券期货市场统计工作联席会议机制确保成员之间实现信息互联共享，并承担以下职能： （一）分析评价证券期货统计标准，提出补充、修改的建议； （二）研究统计工作中遇到的新问题、新情况，加强各单位间的协调、配合； （三）讨论其他与证券期货统计工作有关的重大事项。"},{"i":10,"n":"第十条","txt":"中国证监会派出机构应当指定或者设立专门处室履行统计职责，其统计职责包括： （一）配合中国证监会统计部门完成证券期货市场统计调查任务，搜集、整理、提供辖区内证券期货统计资料； （二）组织辖区内的证券期货统计调查工作，搜集、整理、管理、公布、对外提供证券期货统计资料； （三）对辖区内证券期货发展情况进行统计分析，出具统计报告，提出有关政策建议； （四）对辖区内统计调查对象执行统计法律、行政法规、本办法及中国证监会制定统计制度的情况进行检查监督。"},{"i":11,"n":"第十一条","txt":"统计调查对象应当设立统计部门或者指定部门、人员负责统计工作。"},{"i":12,"n":"第十二条","txt":"中国证监会其他部门、派出机构配置专职的统计人员。统计调查对象应当配备专职或者兼职的统计人员。 统计人员应当具备良好的职业道德，具备必要的证券期货市场基础知识、统计专业基础知识和必备的计算机操作技能。"},{"i":13,"n":"第十三条","txt":"统计人员应当依法如实搜集、报送统计资料。 统计人员应当对其负责搜集、审核、录入的统计资料和调查对象报送的统计资料的真实性负责，不得伪造、篡改统计资料，不得以任何方式要求统计调查对象提供不真实的统计资料。"},{"i":14,"n":"第十四条","txt":"统计人员依法履行统计职责，不受任何单位和个人非法干预。"},{"i":15,"n":"第十五条","txt":"中国证监会统计部门组织对统计人员的专业培训，加强职业道德教育，提高统计工作水平。"},{"i":16,"n":"第十六条","txt":"中国证监会统计部门负责制定证券期货市场统计调查项目。中国证监会派出机构在执行前述统计调查项目时，可以根据本辖区的实际情况和监管工作需要，对统计调查内容作出补充，并报中国证监会统计部门备案。 中国证监会派出机构负责制定辖区内证券期货统计调查项目，并报中国证监会统计部门备案。"},{"i":17,"n":"第十七条","txt":"中国证监会统计部门制定证券期货市场统计标准，以保障统计调查中采用的指标涵义、计算方法、分类目录、调查表式等方面的标准化。 中国证监会其他部门、中国证监会派出机构开展统计调查的，应当适用中国证监会统计部门制定的统计标准。"},{"i":18,"n":"第十八条","txt":"中国证监会及其派出机构在组织统计调查时，应当对统计调查内容、调查对象、统计资料的报送时间、格式及方式等内容作出明确规定。 中国证监会及其派出机构可以采用公文、传真、电话、电子邮件以及网络等统计调查方式。涉及保密内容的统计调查，应当遵循保密管理的相关规定。"},{"i":19,"n":"第十九条","txt":"统计调查对象应当在规定时限内，按照规定的统计调查内容与格式，向中国证监会及其派出机构报送统计资料。统计资料还应当符合中国证监会统计部门制定的统计标准。"},{"i":20,"n":"第二十条","txt":"统计调查对象应当做好基层统计报表的收集、审核和汇总工作，保证统计资料的真实、准确和完整。 统计调查对象应当向中国证监会及其派出机构报送经单位负责人审核、签署的统计数据，并在填报说明中，对基层数据的上报情况及本期数据的异常变动等情况作出说明。"},{"i":21,"n":"第二十一条","txt":"统计调查对象发现报送的统计资料有误的，应当立即报告中国证监会及其派出机构，组织本单位的统计部门或者人员予以核实订正后，及时向中国证监会及其派出机构作出书面更正与说明。必要时，还应当依法及时公开披露。"},{"i":22,"n":"第二十二条","txt":"统计调查应当以定期调查为基础，以抽样调查为补充，综合运用全面调查、重点调查、行政业务记录等方法，搜集、整理证券期货基本统计资料。"},{"i":23,"n":"第二十三条","txt":"中国证监会统计部门应当定期分析、研究证券期货市场和宏观经济发展情况，并就其对证券期货业发展的影响等情况进行调查研究。 中国证监会统计部门可以根据证券期货监管工作的需要，对一些市场高度关注、关系证券期货市场发展大局的情况进行分析、研究。"},{"i":24,"n":"第二十四条","txt":"地方各级人民政府或者国务院其他部门派出机构组织证券期货统计调查的，统计调查对象应当及时向中国证监会派出机构报告。 中国证监会派出机构应当及时了解统计调查内容及其进展情况；必要时，应当及时就统计资料的一致性等问题，与地方各级人民政府或者国务院其他部门派出机构协商。 统计调查属于证券期货市场统计调查一部分的，中国证监会派出机构应当及时报告中国证监会统计部门。中国证监会统计部门应当及时就统计资料的一致性等问题，与国务院其他部门协商。"},{"i":25,"n":"第二十五条","txt":"中国证监会统计部门统一管理证券期货市场统计资料。 中国证监会其他部门、派出机构负责本部门或者单位统计资料的管理工作。 统计调查对象应当按照法律、行政法规的要求，加强统计资料的管理工作。 统计资料档案的保管、调用和移交，应当遵守国家有关档案管理的规定。"},{"i":26,"n":"第二十六条","txt":"中国证监会及其派出机构应当建立健全统计资料的审核、整理、交接和存档等管理制度。 中国证监会统计部门应当建设统一的证券期货统计信息自动化系统，实现与中国证监会其他部门、中国证监会派出机构、证券期货交易所、证券登记结算机构等单位统计资料电子化管理系统、证券期货市场诚信档案系统的对接。"},{"i":27,"n":"第二十七条","txt":"中国证监会及其派出机构应当建立健全统计资料提供和公布制度。 证券期货市场统计资料或者可能影响证券期货市场稳定运行的统计资料应当由中国证监会统计部门对外提供或者公布。 中国证监会派出机构可以对外提供或者公布本辖区证券期货统计资料。"},{"i":28,"n":"第二十八条","txt":"统计调查对象或者其他单位公布统计资料应当遵守法律、行政法规和中国证监会的规定，不得编造、伪造统计资料，扰乱证券期货市场秩序。"},{"i":29,"n":"第二十九条","txt":"中国证监会统计部门、中国证监会派出机构可以对统计调查对象的以下情况，实施定期或者不定期检查： （一）统计部门或者指定负责统计工作的部门、人员的配置情况； （二）统计工作的独立性； （三）基层统计报表的收集、审核和汇总工作及其真实、准确、完整程度； （四）有关统计法律、行政法规、中国证监会规定的其他要求的执行情况。"},{"i":30,"n":"第三十条","txt":"检查分为现场检查与非现场检查。 现场检查时，检查人员不得少于两人，并应当出示合法证件和检查通知书。检查人员有权采取下列措施： （一）询问统计调查对象的有关人员，要求其对检查事项作出说明； （二）查阅、复制统计调查对象与检查事项有关的文件、资料、凭证等； （三）要求统计调查对象及其有关人员提交与检查事项有关的自查报告。 非现场检查时，中国证监会统计部门、中国证监会派出机构可以要求统计调查对象提供备查资料及其说明或者自查报告。"},{"i":31,"n":"第三十一条","txt":"统计调查对象应当配合中国证监会统计部门、中国证监会派出机构的检查工作。任何单位、个人不得干扰和妨碍检查工作。"},{"i":32,"n":"第三十二条","txt":"对于违反本办法规定的统计调查对象，中国证监会可以对其采取以下监督管理措施： （一）责令改正； （二）监管谈话； （三）出具警示函； （四）责令参加培训。"},{"i":33,"n":"第三十三条","txt":"统计调查对象有下列行为之一的，中国证监会可以给予警告，单处或者并处罚款： （一）虚报、瞒报、漏报统计资料； （二）伪造、篡改统计资料； （三）拒报或者无故迟报统计资料； （四）拒绝或者妨碍统计检查。 对前款行为负有直接责任的管理人员和其他直接责任人员，中国证监会可以给予警告，单处或者并处罚款。"},{"i":34,"n":"第三十四条","txt":"统计调查对象或者其他单位违反本办法第二十八条规定，作出虚假陈述或者信息误导，扰乱证券期货市场的，中国证监会按照《证券法》第二百零七条、《期货交易管理条例》第七十一条的规定予以处罚。"},{"i":35,"n":"第三十五条","txt":"统计调查对象报送的监管信息包含统计资料，其报送或者信息披露行为违反法律、行政法规、中国证监会规定的，按照相关规定处理。"},{"i":36,"n":"第三十六条","txt":"中国证监会统计部门、中国证监会其他部门和中国证监会派出机构的工作人员违反国家有关保密规定，擅自公开证券期货统计资料的，中国证监会依照有关规定给予行政处分。"},{"i":37,"n":"第三十七条","txt":"证券期货交易所、证券期货业协会、证券登记结算机构等自律组织组织统计调查的，应当适用中国证监会统计部门规定的统一的统计标准。 前款所称的自律组织可以制定本单位统计工作制度，并报中国证监会统计部门备案。"},{"i":38,"n":"第三十八条","txt":"本办法自2009年3月1日起施行。"}],"zhengquanqihuoshichangchengxinjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强证券期货市场诚信建设，保护投资者合法权益，维护证券期货市场秩序，促进证券期货市场健康稳定发展，根据《证券法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中国证券监督管理委员会（以下简称中国证监会）建立全国统一的证券期货市场诚信档案数据库（以下简称诚信档案），记录证券期货市场诚信信息。"},{"i":3,"n":"第三条","txt":"记入诚信档案的诚信信息的界定、采集与管理，诚信信息的公开、查询，诚信约束、激励与引导等，适用本办法。"},{"i":4,"n":"第四条","txt":"公民（自然人）、法人或者其他组织从事证券期货市场活动，应当诚实信用，遵守法律、行政法规、规章和依法制定的自律规则，禁止欺诈、内幕交易、操纵市场以及其他损害投资者合法权益的不诚实信用行为。"},{"i":5,"n":"第五条","txt":"中国证监会鼓励、支持诚实信用的公民、法人或者其他组织从事证券期货市场活动，实施诚信约束、激励与引导。"},{"i":6,"n":"第六条","txt":"中国证监会可以和国务院其他部门、地方人民政府、国家司法机关、行业组织、境外证券期货监管机构建立诚信监管合作机制，实施诚信信息共享，推动健全社会信用体系。"},{"i":7,"n":"第七条","txt":"下列从事证券期货市场活动的公民、法人或者其他组织的诚信信息，记入诚信档案： （一）证券业从业人员、期货从业人员和基金从业人员； （二）证券期货市场投资者、交易者； （三）证券发行人、上市公司、全国中小企业股份转让系统挂牌公司、区域性股权市场挂牌转让证券的企业及其董事、监事、高级管理人员、主要股东、实际控制人； （四）区域性股权市场的运营机构及其董事、监事和高级管理人员，为区域性股权市场办理账户开立、资金存放、登记结算等业务的机构； （五）证券公司、期货公司、基金管理人、债券受托管理人、债券发行担保人及其董事、监事、高级管理人员、主要股东和实际控制人或者执行事务合伙人，合格境外机构投资者、合格境内机构投资者及其主要投资管理人员，境外证券类机构驻华代表机构及其总代表、首席代表； （六）会计师事务所、律师事务所、保荐机构、财务顾问机构、资产评估机构、投资咨询机构、信用评级机构、基金服务机构、"},{"i":8,"n":"第八条","txt":"本办法所称诚信信息包括： （一）公民的姓名、性别、国籍、身份证件号码，法人或者其他组织的名称、住所、统一社会信用代码等基本信息； （二）中国证监会、国务院其他主管部门等其他省部级及以上单位和证券期货交易场所、证券期货市场行业协会、证券登记结算机构等全国性证券期货市场行业组织（以下简称证券期货市场行业组织）作出的表彰、奖励、评比，以及信用评级机构、诚信评估机构作出的信用评级、诚信评估； （三）中国证监会及其派出机构作出的行政许可决定； （四）发行人、上市公司、全国中小企业股份转让系统挂牌公司及其主要股东、实际控制人，董事、监事和高级管理人员，重大资产重组交易各方，及收购人所作的公开承诺的未履行或者未如期履行、正在履行、已如期履行等情况； （五）中国证监会及其派出机构作出的行政处罚、市场禁入决定和采取的监督管理措施； （六）证券期货市场行业组织实施的纪律处分措施和法律、行政法规、规章规定的"},{"i":9,"n":"第九条","txt":"诚信档案不得采集公民的宗教信仰、基因、指纹、血型、疾病和病史信息以及法律、行政法规规定禁止采集的其他信息。"},{"i":10,"n":"第十条","txt":"本办法第八条第（二）项所列公民、法人或者其他组织所受表彰、奖励、评比和信用评级、诚信评估信息，由其自行向中国证监会及其派出机构申报，记入诚信档案。 公民、法人或者其他组织按规定向中国证监会及其派出机构申报前款规定以外的其他诚信信息，记入诚信档案。 公民、法人或者其他组织申报的诚信信息应当真实、准确、完整。"},{"i":11,"n":"第十一条","txt":"本办法第八条第（一）项、第（三）项至第 （十二）项诚信信息，由中国证监会及其派出机构、证券期货市场行业组织依其职责采集并记入诚信档案；第（十七）项、第（十八）项诚信信息，由相关证券期货市场行业组织、证券期货经营机构采集并记入诚信档案；其他诚信信息由中国证监会及其派出机构通过政府信息公开、信用信息共享等途径采集并记入诚信档案。"},{"i":12,"n":"第十二条","txt":"记入诚信档案的诚信信息所对应的决定或者行为经法定程序撤销、变更的，中国证监会及其派出机构相应删除、修改该诚信信息。"},{"i":13,"n":"第十三条","txt":"本办法第八条规定的违法失信信息，在诚信档案中的效力期限为3年，但因证券期货违法行为被行政处罚、市场禁入、刑事处罚和判决承担较大侵权、违约民事赔偿责任的信息，其效力期限为5年。 法律、行政法规或者中国证监会规章对违法失信信息的效力期限另有规定的，国务院其他主管部门对其产生的违法失信信息的效力期限另有规定的，从其规定。 前款所规定的效力期限，自对违法失信行为的处理决定执行完毕之日起算。 超过效力期限的违法失信信息，不再进行诚信信息公开，并不再接受诚信信息申请查询，公民、法人或者其他组织根据本办法第十七条申请查询自己信息的除外。"},{"i":14,"n":"第十四条","txt":"本办法第八条第（二）、（三）、（四）、（六）项信息和第（五）项的行政处罚、市场禁入信息依法向社会公开。 中国证监会在其网站建立证券期货市场违法失信信息公开查询平台，社会公众可通过该平台查询本办法第八条第（五）项行政处罚、市场禁入决定信息，第（六）项信息等违法失信信息。"},{"i":15,"n":"第十五条","txt":"中国证监会对有下列严重违法失信情形的市场主体，在证券期货市场违法失信信息公开查询平台进行专项公示： （一）因操纵市场、内幕交易、欺诈发行、虚假披露信息、非法从事证券期货业务、利用未公开信息交易以及编造、传播虚假信息被中国证监会及其派出机构作出行政处罚； （二）被中国证监会及其派出机构采取市场禁入措施； （三）因证券期货犯罪被人民法院判处刑罚； （四）因拒不配合中国证监会及其派出机构监督检查、调查被有关机关作出行政处罚或者处理决定； （五）到期拒不执行中国证监会及其派出机构生效行政处罚决定； （六）经责令改正仍逾期不履行《证券法》第八十四条规定的公开承诺； （七）严重侵害投资者合法权益、市场反应强烈的其他严重违法失信情形。 严重违法失信主体的专项公示期为一年，自公示之日起算。 中国证监会对有第（五）、（六）项情形的市场主体，统一归集至全国信用信息共享平台安排公示的，按照相关规定办理。"},{"i":16,"n":"第十六条","txt":"除本办法第十四条、第十五条规定之外的诚信信息，公民、法人或者其他组织可以根据本办法规定向中国证监会及其派出机构申请查询。"},{"i":17,"n":"第十七条","txt":"公民、法人或者其他组织提出诚信信息查询申请，符合以下条件之一的，中国证监会及其派出机构予以办理： （一）公民、法人或者其他组织申请查询自己的诚信信息的； （二）发行人、上市公司申请查询拟任董事、监事、高级管理人员的诚信信息的； （三）发行人、上市公司申请查询拟参与本公司并购、重组的公民、法人或者其他组织的诚信信息的； （四）发行人、上市公司申请查询拟委托的证券公司、证券服务机构及其相关从业人员的诚信信息的； （五）证券公司、债券受托管理人、证券服务机构申请查询其所提供专业服务的发行人、上市公司及其董事、监事、高级管理人员、控股股东和实际控制人以及债券发行担保人的诚信信息的； （六）证券公司、期货公司、基金管理人、证券期货服务机构申请查询已聘任或者拟聘任的董事、监事、高级管理人员或者其他从业人员的诚信信息的； （七）中国证监会规定的其他条件。"},{"i":18,"n":"第十八条","txt":"公民、法人或者其他组织提出诚信信息查询申请，应当如实提供如下材料： （一）查询申请书； （二）身份证明文件； （三）办理本办法第十七条第（二）项至第（六）项查询申请的，查询申请书应经查询对象签字或者盖章同意，或者有查询对象的其他书面同意文件。"},{"i":19,"n":"第十九条","txt":"公民、法人或者其他组织提出的查询申请，符合条件，材料齐备的，中国证监会及其派出机构自收到查询申请之日起5个工作日内反馈。"},{"i":20,"n":"第二十条","txt":"公民、法人或者其他组织申请查询的诚信信息属于国家秘密，其他公民、法人或者其他组织的商业秘密及个人隐私的，中国证监会及其派出机构不予查询，但应当在答复中说明。"},{"i":21,"n":"第二十一条","txt":"记入诚信档案的公民、法人或者其他组织，认为其诚信信息具有本办法第十二条规定的应予删除、修改情形的，或者具有其他重大、明显错误的，可以向中国证监会及其派出机构申请更正。 中国证监会及其派出机构收到公民、法人或者其他组织的信息更正申请后，应当在15个工作日内进行处理，并将处理结果告知申请人。确有本办法第十二条规定的应予删除、修改情形的，或者其他重大、明显错误情形的，应予更正。"},{"i":22,"n":"第二十二条","txt":"公民、法人或者其他组织通过申请查询获取诚信信息的，不得泄露或者提供他人使用，不得进行以营利为目的的使用、加工或者处理，不得用于其他非法目的。"},{"i":23,"n":"第二十三条","txt":"中国证监会建立发行人、上市公司、全国中小企业股份转让系统挂牌公司、证券公司、期货公司、基金管理人、证券期货服务机构、证券期货基金从业人员等主要市场主体的诚信积分制度，实行诚信分类监督管理。 诚信积分和诚信分类监督管理具体办法另行制定。"},{"i":24,"n":"第二十四条","txt":"向中国证监会及其派出机构申请行政许可，申请人以及申请事项涉及的有关当事人应当书面承诺其所提交的申请材料真实、准确、完整，并诚信合法地参与证券期货市场活动。"},{"i":25,"n":"第二十五条","txt":"中国证监会及其派出机构审查行政许可申请，应当查阅申请人以及申请事项所涉及的有关当事人的诚信档案，对其诚信状况进行审查。 证券期货市场行业组织在履行登记、备案、注册、会员批准等工作职责时，应当按照前款规定办理。 证券交易场所依法审核公开发行证券及上市交易或挂牌转让申请时，应当按照第一款规定办理。"},{"i":26,"n":"第二十六条","txt":"中国证监会及其派出机构审查行政许可申请，发现申请人以及有关当事人有本办法第八条第（四）项中的未履行或者未如期履行承诺信息，或者第（五）项至第（十八）项规定的违法失信信息的，可以要求申请人或者受申请人委托为行政许可申请提供证券期货服务的有关机构提供书面反馈意见。 书面反馈意见应就如下事项进行说明： （一）诚信信息所涉及相关事实的基本情况； （二）有关部门所作决定、处理的执行及其他后续情况，并提供证明材料； （三）有关证券期货服务机构关于诚信信息对行政许可事项是否构成影响的分析。 申请人或者有关证券期货服务机构应在规定期限内提交书面反馈意见。"},{"i":27,"n":"第二十七条","txt":"申请人或者有关证券期货服务机构的书面反馈意见不明确，有关分析、说明不充分的，中国证监会及其派出机构可以直接或者委托有关机构对有关事项进行核查。"},{"i":28,"n":"第二十八条","txt":"根据本办法第二十六条、第二十七条提供书面反馈意见或者进行核查的时间，不计入行政许可法定期限。"},{"i":29,"n":"第二十九条","txt":"行政许可申请人以及申请事项所涉及的有关当事人有本办法第八条第（四）项中的未履行或者未如期履行承诺信息，或者第（五）项至第（十八）项规定的违法失信信息之一，属于法定不予许可条件范围的，中国证监会及其派出机构应当依法作出不予许可的决定。 申请人以及申请事项所涉及的有关当事人的诚信信息虽不属于法定不予许可条件范围，但有关法律、行政法规和规章对行政许可法定条件提出诚实信用要求、作出原则性规定或者设定授权性条款的，中国证监会及其派出机构可以综合考虑诚信状况等相关因素，审慎审查申请人提出的行政许可申请事项。"},{"i":30,"n":"第三十条","txt":"业务创新试点申请人有本办法第八条第（四）项中的未履行或者未如期履行承诺信息，或者第（五）项至第（十八）项规定的违法失信信息之一的，中国证监会及其派出机构、证券期货市场行业组织可以暂缓或者不予安排，但申请人能证明该违法失信信息与业务创新明显无关的除外。"},{"i":31,"n":"第三十一条","txt":"中国证监会及其派出机构审查行政许可，对符合以下条件的，在受理后，即时进行审查： （一）近三年没有违反证券期货法律、行政法规和中国证监会规定的失信记录； （二）近三年没有因违法开展经营活动被银行、保险、税收、环保、海关等相关主管部门予以行政处罚； （三）没有因证券期货犯罪或者其他犯罪被人民法院判处刑罚。 中国证监会及其派出机构审查行政许可，可以在同等条件下对诚信积分较高的申请人优先审查。"},{"i":32,"n":"第三十二条","txt":"中国证监会及其派出机构、证券期货市场行业组织在业务创新试点安排中，可以在法律、行政法规规定的范围内，对于同等条件下诚信状况较好的申请人予以优先安排。"},{"i":33,"n":"第三十三条","txt":"中国证监会及其派出机构在对公民、法人或者其他组织进行行政处罚、实施市场禁入和采取监督管理措施中，应当查阅当事人的诚信档案，在综合考虑当事人违法行为的性质、情节、损害投资者合法权益程度和当事人诚信状况等因素的基础上，依法作出处理。"},{"i":34,"n":"第三十四条","txt":"中国证监会及其派出机构在开展监督检查等日常监管工作中，应当查阅被监管机构的诚信档案，根据被监管机构的诚信状况，有针对性地进行现场检查和非现场检查，或者适当调整、安排现场检查的对象、频率和内容。"},{"i":35,"n":"第三十五条","txt":"证券登记结算机构、证券公司、期货公司等机构在为投资者、客户开立证券、期货相关账户时，应当查询投资者、客户的诚信档案，按照规定办理相关账户开立事宜。"},{"i":36,"n":"第三十六条","txt":"证券公司在办理客户证券质押式回购、约定式购回以及融资融券业务申请时，可以查阅客户的诚信档案，根据申请人的诚信状况，决定是否予以办理，或者确定和调整授信额度。 证券金融公司在开展转融通业务时，可以查阅证券公司的诚信档案，根据证券公司的诚信状况，决定是否对其进行转融通，或者确定和调整授信额度。"},{"i":37,"n":"第三十七条","txt":"发行人、上市公司、全国中小企业股份转让系统挂牌公司、证券公司、期货公司、基金管理人、证券期货服务机构拟聘任董事、监事、高级管理人员以及从业人员的，应当查询拟聘任人员的诚信档案，并将其诚信状况作为决定是否聘任的依据。"},{"i":38,"n":"第三十八条","txt":"证券公司、证券服务机构受托为发行人、上市公司、全国中小企业股份转让系统挂牌公司等提供证券服务的，应当查询委托人的诚信档案，并将其诚信状况作为决定是否接受委托、确定收费标准的依据。"},{"i":39,"n":"第三十九条","txt":"公民、法人或者其他组织公开发布证券期货市场评论信息，所述事实内容与实际情况不相符合的，或者存在其他显著误导公众情形的，中国证监会及其派出机构可以对其出具诚信关注函，记入诚信档案，并可将有关情况向其所在工作单位、所属主管部门或者行业自律组织通报。 证券期货投资咨询机构及其人员公开发布证券期货市场评论信息违反规定的，依照有关规定处理、处罚。 公民、法人或者其他组织利用公开发布证券期货市场评论信息进行操纵市场等违法行为的，依法予以处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"证券期货市场行业组织应当教育和鼓励其成员以及从业人员遵守法律，诚实信用。对遵守法律、诚实信用的成员以及从业人员，可以给予表彰、奖励。 中国证监会鼓励证券期货市场行业组织等建立证券期货市场诚信评估制度，组织开展对有关行业和市场主体的诚信状况评估，并将评估结果予以公示。 中国证券业协会、中国期货业协会、中国上市公司协会、中国证券投资基金业协会建立年度诚信会员制度。具体办法由相关协会制定，报中国证监会备案。"},{"i":41,"n":"第四十一条","txt":"上市公司、全国中小企业股份转让系统挂牌公司、证券公司、期货公司、基金管理人和证券期货服务机构等应当不断完善内部诚信监督、约束制度机制，提高诚信水平。 中国证监会及其派出机构对前款规定机构的内部诚信监督、约束制度机制建设情况进行检查、指导，并可以将检查情况在行业和辖区内进行通报。"},{"i":42,"n":"第四十二条","txt":"对有本办法第八条第（四）项中的未履行或者未如期履行承诺信息，或者第（五）项至第（十八）项规定的违法失信信息的公民，中国证监会及其派出机构、证券期货市场行业组织可以不聘任其担任下列职务： （一）中国证监会股票发行审核委员会委员； （二）中国证监会上市公司并购重组审核委员会委员； （三）中国证监会及其派出机构、证券期货市场行业组织成立的负有审核、监督、核查、咨询职责的其他组织的成员。"},{"i":43,"n":"第四十三条","txt":"中国证监会与国务院其他部门、地方人民政府、国家司法机关和有关组织建立对证券期货市场参与主体的失信联合惩戒和守信联合激励制度机制，提供证券期货市场主体的相关诚信信息，依法实施联合惩戒、激励。"},{"i":44,"n":"第四十四条","txt":"中国证监会诚信监督管理机构履行下列职责： （一）界定、组织采集证券期货市场诚信信息； （二）建立、管理诚信档案，组织、督促诚信信息的记入； （三）组织办理诚信信息的公开、查询和共享； （四）建立、协调实施诚信监督、约束与激励机制； （五）中国证监会规定的其他诚信监督管理与服务职责。"},{"i":45,"n":"第四十五条","txt":"中国证监会各派出机构负责接收、办理公民、法人或者其他组织根据本办法规定提出的诚信信息记入申报、诚信信息查询申请、诚信信息更正申请等事项。"},{"i":46,"n":"第四十六条","txt":"中国证监会及其派出机构、证券期货市场行业组织，未按照本办法规定及时、真实、准确、完整地记入诚信信息，造成不良后果的，按照有关规定对相关责任人员进行行政处分；情节严重的，依法追究法律责任。"},{"i":47,"n":"第四十七条","txt":"违反本办法第十条、第十八条、第二十二条、第三十五条、第三十七条、第三十八条规定的，中国证监会及其派出机构可以采取责令改正、监管谈话、出具警示函、责令公开说明、在一定期限内不予接受其诚信信息申报和查询申请等监督管理措施；情节严重的，依法追究法律责任。"},{"i":48,"n":"第四十八条","txt":"中国证监会及其派出机构办理诚信信息查询，除可以收取打印、复制、装订、邮寄成本费用外，不得收取其他费用。"},{"i":49,"n":"第四十九条","txt":"证券期货市场行业组织在履行自律管理职责中，查询诚信档案，实施诚信约束、激励的，参照本办法有关规定执行。"},{"i":50,"n":"第五十条","txt":"本办法自2018年7月1日起施行。《证券期货市场诚信监督管理暂行办法》（证监会令第106号）同时废止。"}],"zhengquanqihuotouzizheshidangxingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范证券期货投资者适当性管理，维护投资者合法权益，根据《证券法》《证券投资基金法》《证券公司监督管理条例》《期货交易管理条例》及其他相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"向投资者销售公开或者非公开发行的证券、公开或者非公开募集的证券投资基金和股权投资基金（包括创业投资基金，以下简称基金）、公开或者非公开转让的期货及其他衍生产品，或者为投资者提供相关业务服务的，适用本办法。"},{"i":3,"n":"第三条","txt":"向投资者销售证券期货产品或者提供证券期货服务的机构（以下简称经营机构）应当遵守法律、行政法规、本办法及其他有关规定，在销售产品或者提供服务的过程中，勤勉尽责，审慎履职，全面了解投资者情况，深入调查分析产品或者服务信息，科学有效评估，充分揭示风险，基于投资者的不同风险承受能力以及产品或者服务的不同风险等级等因素，提出明确的适当性匹配意见，将适当的产品或者服务销售或者提供给适合的投资者，并对违法违规行为承担法律责任。"},{"i":4,"n":"第四条","txt":"投资者应当在了解产品或者服务情况，听取经营机构适当性意见的基础上，根据自身能力审慎决策，独立承担投资风险。 经营机构的适当性匹配意见不表明其对产品或者服务的风险和收益做出实质性判断或者保证。"},{"i":5,"n":"第五条","txt":"中国证券监督管理委员会（以下简称中国证监会）及其派出机构依照法律、行政法规、本办法及其他相关规定，对经营机构履行适当性义务进行监督管理。 证券期货交易场所、登记结算机构及中国证券业协会、中国期货业协会、中国证券投资基金业协会（以下统称行业协会）等自律组织对经营机构履行适当性义务进行自律管理。"},{"i":6,"n":"第六条","txt":"经营机构向投资者销售产品或者提供服务时，应当了解投资者的下列信息： （一）自然人的姓名、住址、职业、年龄、联系方式，法人或者其他组织的名称、注册地址、办公地址、性质、资质及经营范围等基本信息； （二）收入来源和数额、资产、债务等财务状况； （三）投资相关的学习、工作经历及投资经验； （四）投资期限、品种、期望收益等投资目标； （五）风险偏好及可承受的损失； （六）诚信记录； （七）实际控制投资者的自然人和交易的实际受益人； （八）法律法规、自律规则规定的投资者准入要求相关信息； （九）其他必要信息。"},{"i":7,"n":"第七条","txt":"投资者分为普通投资者与专业投资者。 普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护。"},{"i":8,"n":"第八条","txt":"符合下列条件之一的是专业投资者： （一）经有关金融监管部门批准设立的金融机构，包括证券公司、期货公司、基金管理公司及其子公司、商业银行、保险公司、信托公司、财务公司等；经行业协会备案或者登记的证券公司子公司、期货公司子公司、私募基金管理人。 （二）上述机构面向投资者发行的理财产品，包括但不限于证券公司资产管理产品、基金管理公司及其子公司产品、期货公司资产管理产品、银行理财产品、保险产品、信托产品、经行业协会备案的私募基金。 （三）社会保障基金、企业年金等养老基金，慈善基金等社会公益基金，合格境外机构投资者（QFII）、人民币合格境外机构投资者（RQFII）。 （四）同时符合下列条件的法人或者其他组织： 1.最近1年末净资产不低于2000万元； 2.最近1年末金融资产不低于1000万元； 3.具有2年以上证券、基金、期货、黄金、外汇等投资经历。 （五）同时符合下列条件的自然人： 1.金融"},{"i":9,"n":"第九条","txt":"经营机构可以根据专业投资者的业务资格、投资实力、投资经历等因素，对专业投资者进行细化分类和管理。"},{"i":10,"n":"第十条","txt":"专业投资者之外的投资者为普通投资者。 经营机构应当按照有效维护投资者合法权益的要求，综合考虑收入来源、资产状况、债务、投资知识和经验、风险偏好、诚信状况等因素，确定普通投资者的风险承受能力，对其进行细化分类和管理。"},{"i":11,"n":"第十一条","txt":"普通投资者和专业投资者在一定条件下可以互相转化。 符合本办法第八条第（四）、（五）项规定的专业投资者，可以书面告知经营机构选择成为普通投资者，经营机构应当对其履行相应的适当性义务。 符合下列条件之一的普通投资者可以申请转化成为专业投资者，但经营机构有权自主决定是否同意其转化： （一）最近1年末净资产不低于1000万元，最近1年末金融资产不低于500万元，且具有1年以上证券、基金、期货、黄金、外汇等投资经历的除专业投资者外的法人或其他组织； （二）金融资产不低于300万元或者最近3年个人年均收入不低于30万元，且具有1年以上证券、基金、期货、黄金、外汇等投资经历或者1年以上金融产品设计、投资、风险管理及相关工作经历的自然人投资者。"},{"i":12,"n":"第十二条","txt":"普通投资者申请成为专业投资者应当以书面形式向经营机构提出申请并确认自主承担可能产生的风险和后果，提供相关证明材料。 经营机构应当通过追加了解信息、投资知识测试或者模拟交易等方式对投资者进行谨慎评估，确认其符合前条要求，说明对不同类别投资者履行适当性义务的差别，警示可能承担的投资风险，告知申请的审查结果及其理由。"},{"i":13,"n":"第十三条","txt":"经营机构应当告知投资者，其根据本办法第六条规定所提供的信息发生重要变化、可能影响分类的，应及时告知经营机构。经营机构应当建立投资者评估数据库并及时更新，充分使用已了解信息和已有评估结果，避免重复采集，提高评估效率。"},{"i":14,"n":"第十四条","txt":"中国证监会、自律组织在针对特定市场、产品或者服务制定规则时，可以考虑风险性、复杂性以及投资者的认知难度等因素，从资产规模、收入水平、风险识别能力和风险承担能力、投资认购最低金额等方面，规定投资者准入要求。投资者准入要求包含资产指标的，应当规定投资者在购买产品或者接受服务前一定时期内符合该指标。 现有市场、产品或者服务规定投资者准入要求的，应当符合前款规定。"},{"i":15,"n":"第十五条","txt":"经营机构应当了解所销售产品或者所提供服务的信息，根据风险特征和程度，对销售的产品或者提供的服务划分风险等级。"},{"i":16,"n":"第十六条","txt":"划分产品或者服务风险等级时应当综合考虑以下因素： （一）流动性； （二）到期时限； （三）杠杆情况； （四）结构复杂性； （五）投资单位产品或者相关服务的最低金额； （六）投资方向和投资范围； （七）募集方式； （八）发行人等相关主体的信用状况； （九）同类产品或者服务过往业绩； （十）其他因素。 涉及投资组合的产品或者服务，应当按照产品或者服务整体风险等级进行评估。"},{"i":17,"n":"第十七条","txt":"产品或者服务存在下列因素的，应当审慎评估其风险等级： （一）存在本金损失的可能性，因杠杆交易等因素容易导致本金大部分或者全部损失的产品或者服务； （二）产品或者服务的流动变现能力，因无公开交易市场、参与投资者少等因素导致难以在短期内以合理价格顺利变现的产品或者服务； （三）产品或者服务的可理解性，因结构复杂、不易估值等因素导致普通人难以理解其条款和特征的产品或者服务； （四）产品或者服务的募集方式，涉及面广、影响力大的公募产品或者相关服务； （五）产品或者服务的跨境因素，存在市场差异、适用境外法律等情形的跨境发行或者交易的产品或者服务； （六）自律组织认定的高风险产品或者服务； （七）其他有可能构成投资风险的因素。"},{"i":18,"n":"第十八条","txt":"经营机构应当根据产品或者服务的不同风险等级，对其适合销售产品或者提供服务的投资者类型作出判断，根据投资者的不同分类，对其适合购买的产品或者接受的服务作出判断。"},{"i":19,"n":"第十九条","txt":"经营机构告知投资者不适合购买相关产品或者接受相关服务后，投资者主动要求购买风险等级高于其风险承受能力的产品或者接受相关服务的，经营机构在确认其不属于风险承受能力最低类别的投资者后，应当就产品或者服务风险高于其承受能力进行特别的书面风险警示，投资者仍坚持购买的，可以向其销售相关产品或者提供相关服务。"},{"i":20,"n":"第二十条","txt":"经营机构向普通投资者销售高风险产品或者提供相关服务，应当履行特别的注意义务，包括制定专门的工作程序，追加了解相关信息，告知特别的风险点，给予普通投资者更多的考虑时间，或者增加回访频次等。"},{"i":21,"n":"第二十一条","txt":"经营机构应当根据投资者和产品或者服务的信息变化情况，主动调整投资者分类、产品或者服务分级以及适当性匹配意见，并告知投资者上述情况。"},{"i":22,"n":"第二十二条","txt":"禁止经营机构进行下列销售产品或者提供服务的活动： （一）向不符合准入要求的投资者销售产品或者提供服务； （二）向投资者就不确定事项提供确定性的判断，或者告知投资者有可能使其误认为具有确定性的意见； （三）向普通投资者主动推介风险等级高于其风险承受能力的产品或者服务； （四）向普通投资者主动推介不符合其投资目标的产品或者服务； （五）向风险承受能力最低类别的投资者销售或者提供风险等级高于其风险承受能力的产品或者服务； （六）其他违背适当性要求，损害投资者合法权益的行为。"},{"i":23,"n":"第二十三条","txt":"经营机构向普通投资者销售产品或者提供服务前，应当告知下列信息： （一）可能直接导致本金亏损的事项； （二）可能直接导致超过原始本金损失的事项； （三）因经营机构的业务或者财产状况变化，可能导致本金或者原始本金亏损的事项； （四）因经营机构的业务或者财产状况变化，影响客户判断的重要事由； （五）限制销售对象权利行使期限或者可解除合同期限等全部限制内容； （六）本办法第二十九条规定的适当性匹配意见。"},{"i":24,"n":"第二十四条","txt":"经营机构对投资者进行告知、警示，内容应当真实、准确、完整，不存在虚假记载、误导性陈述或者重大遗漏，语言应当通俗易懂；告知、警示应当采用书面形式送达投资者，并由其确认已充分理解和接受。"},{"i":25,"n":"第二十五条","txt":"经营机构通过营业网点向普通投资者进行本办法第十二条、第二十条、第二十一条和第二十三条规定的告知、警示，应当全过程录音或者录像；通过互联网等非现场方式进行的，经营机构应当完善配套留痕安排，由普通投资者通过符合法律、行政法规要求的电子方式进行确认。"},{"i":26,"n":"第二十六条","txt":"经营机构委托其他机构销售本机构发行的产品或者提供服务，应当审慎选择受托方，确认受托方具备代销相关产品或者提供服务的资格和落实相应适当性义务要求的能力，应当制定并告知代销方所委托产品或者提供服务的适当性管理标准和要求，代销方应当严格执行，但法律、行政法规、中国证监会其他规章另有规定的除外。"},{"i":27,"n":"第二十七条","txt":"经营机构代销其他机构发行的产品或者提供相关服务，应当在合同中约定要求委托方提供的信息，包括本办法第十六条、第十七条规定的产品或者服务分级考虑因素等，自行对该信息进行调查核实，并履行投资者评估、适当性匹配等适当性义务。委托方不提供规定的信息、提供信息不完整的，经营机构应当拒绝代销产品或者提供服务。"},{"i":28,"n":"第二十八条","txt":"对在委托销售中违反适当性义务的行为，委托销售机构和受托销售机构应当依法承担相应法律责任，并在委托销售合同中予以明确。"},{"i":29,"n":"第二十九条","txt":"经营机构应当制定适当性内部管理制度，明确投资者分类、产品或者服务分级、适当性匹配的具体依据、方法、流程等，严格按照内部管理制度进行分类、分级，定期汇总分类、分级结果，并对每名投资者提出匹配意见。 经营机构应当制定并严格落实与适当性内部管理有关的限制不匹配销售行为、客户回访检查、评估与销售隔离等风控制度，以及培训考核、执业规范、监督问责等制度机制，不得采取鼓励不适当销售的考核激励措施，确保从业人员切实履行适当性义务。"},{"i":30,"n":"第三十条","txt":"经营机构应当每半年开展一次适当性自查，形成自查报告。发现违反本办法规定的问题，应当及时处理并主动报告住所地中国证监会派出机构。"},{"i":31,"n":"第三十一条","txt":"鼓励经营机构将投资者分类政策、产品或者服务分级政策、自查报告在公司网站或者符合中国证监会规定条件的媒体进行披露。"},{"i":32,"n":"第三十二条","txt":"经营机构应当按照相关规定妥善保存其履行适当性义务的相关信息资料，防止泄露或者被不当利用，接受中国证监会及其派出机构和自律组织的检查。对匹配方案、告知警示资料、录音录像资料、自查报告等的保存期限不得少于20年。"},{"i":33,"n":"第三十三条","txt":"投资者购买产品或者接受服务，按规定需要提供信息的，所提供的信息应当真实、准确、完整。投资者根据本办法第六条规定所提供的信息发生重要变化、可能影响其分类的，应当及时告知经营机构。 投资者不按照规定提供相关信息，提供信息不真实、不准确、不完整的，应当依法承担相应法律责任，经营机构应当告知其后果，并拒绝向其销售产品或者提供服务。"},{"i":34,"n":"第三十四条","txt":"经营机构应当妥善处理适当性相关的纠纷，与投资者协商解决争议，采取必要措施支持和配合投资者提出的调解。经营机构履行适当性义务存在过错并造成投资者损失的，应当依法承担相应法律责任。 经营机构与普通投资者发生纠纷的，经营机构应当提供相关资料，证明其已向投资者履行相应义务。"},{"i":35,"n":"第三十五条","txt":"中国证监会及其派出机构在监管中应当审核或者关注产品或者服务的适当性安排，对适当性制度落实情况进行检查，督促经营机构严格落实适当性义务，强化适当性管理。"},{"i":36,"n":"第三十六条","txt":"证券期货交易场所应当制定完善本市场相关产品或者服务的适当性管理自律规则。 行业协会应当制定完善会员落实适当性管理要求的自律规则，制定并定期更新本行业的产品或者服务风险等级名录以及本办法第十九条、第二十二条规定的风险承受能力最低的投资者类别，供经营机构参考。经营机构评估相关产品或者服务的风险等级不得低于名录规定的风险等级。 证券期货交易场所、行业协会应当督促、引导会员履行适当性义务，对备案产品或者相关服务应当重点关注高风险产品或者服务的适当性安排。"},{"i":37,"n":"第三十七条","txt":"经营机构违反本办法规定的，中国证监会及其派出机构可以对经营机构及其直接负责的主管人员和其他直接责任人员，采取责令改正、监管谈话、出具警示函等监督管理措施。"},{"i":38,"n":"第三十八条","txt":"证券公司、期货公司违反本办法规定，存在较大风险或者风险隐患的，中国证监会及其派出机构可以按照《证券法》第一百四十条、《证券公司监督管理条例》第七十条、《期货交易管理条例》第五十五条的规定，采取监督管理措施。"},{"i":39,"n":"第三十九条","txt":"违反本办法第六条、第十八条、第十九条、第二十条、第二十一条、第二十二条第（三）项至第（六）项、第二十三条、第二十四条、第三十三条规定的，按照《证券法》第一百九十八条、《证券投资基金法》第一百三十七条、《证券公司监督管理条例》第八十四条、《期货交易管理条例》第六十七条予以处理。"},{"i":40,"n":"第四十条","txt":"违反本办法第二十二条第（一）项至第（二）项、第二十六条、第二十七条规定的，按照《证券投资基金法》第一百三十五条、《证券公司监督管理条例》第八十三条、《期货交易管理条例》第六十六条予以处理。"},{"i":41,"n":"第四十一条","txt":"经营机构有下列情形之一的，给予警告，并处以3万元以下罚款；对直接负责的主管人员和其他直接责任人员，给予警告，并处以3万元以下罚款： （一）违反本办法第十条，未按规定对普通投资者进行细化分类和管理的； （二）违反本办法第十一条、第十二条，未按规定进行投资者类别转化的； （三）违反本办法第十三条，未建立或者更新投资者评估数据库的； （四）违反本办法第十五条，未按规定了解所销售产品或者所提供服务信息或者履行分级义务的； （五）违反本办法第十六条、第十七条，未按规定划分产品或者服务风险等级的； （六）违反本办法第二十五条，未按规定录音录像或者采取配套留痕安排的； （七）违反本办法第二十九条，未按规定制定或者落实适当性内部管理制度和相关制度机制的； （八）违反本办法第三十条，未按规定开展适当性自查的； （九）违反本办法第三十二条，未按规定妥善保存相关信息资料的； （十）违反本办法第六条、第十八条"},{"i":42,"n":"第四十二条","txt":"经营机构从业人员违反相关法律法规和本办法规定，情节严重的，中国证监会可以依法采取市场禁入的措施。"},{"i":43,"n":"第四十三条","txt":"本办法自2017年7月1日起施行。"}],"zhengquanqihuojingyingjigoujiqigongzuorenyuanlianj70351e":[{"i":1,"n":"第一条","txt":"为促进资本市场健康发展，净化资本市场生态环境，保护投资者合法权益，切实加强对证券期货经营机构及其工作人员廉洁从业的监督管理，根据《证券法》《证券投资基金法》《证券公司监督管理条例》《期货交易管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称廉洁从业，是指证券期货经营机构及其工作人员在开展证券期货业务及相关活动中，严格遵守法律法规、中国证监会的规定和行业自律规则，遵守社会公德、商业道德、职业道德和行为规范，公平竞争，合规经营，忠实勤勉，诚实守信，不直接或者间接向他人输送不正当利益或者谋取不正当利益。"},{"i":3,"n":"第三条","txt":"中国证监会应当加强对证券期货经营机构及其工作人员廉洁从业的监督管理。 中国证券业协会、中国期货业协会、中国证券投资基金业协会等自律组织依据章程、相关自律规则对证券期货经营机构及其工作人员进行廉洁从业的自律管理。"},{"i":4,"n":"第四条","txt":"证券期货经营机构承担廉洁从业风险防控主体责任。 证券期货经营机构董事会决定廉洁从业管理目标，对廉洁从业管理的有效性承担责任。 证券期货经营机构主要负责人是落实廉洁从业管理职责的第一责任人，各级负责人在职责范围内承担相应管理责任。"},{"i":5,"n":"第五条","txt":"证券期货经营机构应当指定专门部门对本机构及其工作人员的廉洁从业情况进行监督、检查，充分发挥纪检监察、合规、审计等部门的合力，发现问题及时处理，重大情况及时报告。"},{"i":6,"n":"第六条","txt":"证券期货经营机构应当建立健全廉洁从业内部控制制度，制定具体、有效的事前风险防范体系、事中管控措施和事后追责机制，对所从事的业务种类、环节及相关工作进行科学、系统的廉洁风险评估，识别廉洁从业风险点，强化岗位制衡与内部监督机制并确保运作有效。 前款规定的业务种类、环节包括业务承揽、承做、销售、交易、结算、交割、投资、采购、商业合作、人员招聘，以及申请行政许可、接受监管执法和自律管理等。"},{"i":7,"n":"第七条","txt":"证券期货经营机构应当制定工作人员廉洁从业规范，明确廉洁从业要求，加强从业人员廉洁培训和教育，培育廉洁从业文化。 证券期货经营机构应当将工作人员廉洁从业纳入工作人员管理体系，在遇有人员聘用、晋级、提拔、离职以及考核、审计、稽核等情形时，对其廉洁从业情况予以考察评估。"},{"i":8,"n":"第八条","txt":"证券期货经营机构应当强化财经纪律，杜绝账外账等不规范行为。对于业务活动中产生的费用支出制定明确的内部决策流程和具体标准，确保相关费用支出合法合规。"},{"i":9,"n":"第九条","txt":"证券期货经营机构及其工作人员在开展证券期货业务及相关活动中，不得以下列方式向公职人员、客户、正在洽谈的潜在客户或者其他利益关系人输送不正当利益： （一）提供礼金、礼品、房产、汽车、有价证券、股权、佣金返还等财物，或者为上述行为提供代持等便利； （二）提供旅游、宴请、娱乐健身、工作安排等利益； （三）安排显著偏离公允价格的结构化、高收益、保本理财产品等交易； （四）直接或者间接向他人提供内幕信息、未公开信息、商业秘密和客户信息，明示或者暗示他人从事相关交易活动； （五）其他输送不正当利益的情形。 证券期货经营机构及其工作人员按照证券期货经营机构依法制定的内部规定及限定标准，依法合理营销的，不适用前款规定。"},{"i":10,"n":"第十条","txt":"证券期货经营机构工作人员不得以下列方式谋取不正当利益： （一）直接或者间接以第九条所列形式收受、索取他人的财物或者利益； （二）直接或者间接利用他人提供或主动获取的内幕信息、未公开信息、商业秘密和客户信息谋取利益； （三）以诱导客户从事不必要交易、使用客户受托资产进行不必要交易等方式谋取利益； （四）违规从事营利性经营活动，违规兼任可能影响其独立性的职务或者从事与所在机构或者投资者合法利益相冲突的活动； （五）违规利用职权为近亲属或者其他利益关系人从事营利性经营活动提供便利条件； （六）其他谋取不正当利益的情形。"},{"i":11,"n":"第十一条","txt":"证券期货经营机构及其工作人员不得以下列方式干扰或者唆使、协助他人干扰证券期货监督管理或者自律管理工作： （一）以不正当方式影响监督管理或者自律管理决定； （二）以不正当方式影响监督管理或者自律管理人员工作安排； （三）以不正当方式获取监督管理或者自律管理内部信息； （四）协助利益关系人，拒绝、干扰、阻碍或者不配合监管人员行使监督、检查、调查职权； （五）其他干扰证券期货监督管理或者自律管理工作的情形。"},{"i":12,"n":"第十二条","txt":"证券期货经营机构及其工作人员在开展投资银行类业务过程中，不得以下列方式输送或者谋取不正当利益： （一）以非公允价格或者不正当方式为自身或者利益关系人获取拟上市公司股权； （二）以非公允价格或者不正当方式为自身或者利益关系人获取拟并购重组上市公司股权或者标的资产股权； （三）以非公允价格为利益关系人配售债券或者约定回购债券； （四）泄露证券发行询价和定价信息，操纵证券发行价格； （五）直接或者间接通过聘请第三方机构或者个人的方式输送利益； （六）以与监管人员或者其他相关人员熟悉，或者以承诺价格、利率、获得批复及获得批复时间等为手段招揽项目、商定服务费； （七）其他输送或者谋取不正当利益的行为。"},{"i":13,"n":"第十三条","txt":"证券期货经营机构应当对其股东、客户等相关方做好辅导和宣传工作，告知相关方应当遵守廉洁从业规定。"},{"i":14,"n":"第十四条","txt":"证券期货经营机构应当定期或者不定期开展廉洁从业内部检查，对发现的问题及时整改，对责任人严肃处理。 责任人为中共党员的，同时按照党的纪律要求进行处理。"},{"i":15,"n":"第十五条","txt":"证券期货经营机构应当于每年4月30日前，向中国证监会有关派出机构报送上年度廉洁从业管理情况报告。 有下列情形之一的，证券期货经营机构应当在五个工作日内，向中国证监会有关派出机构报告： （一）证券期货经营机构在内部检查中，发现存在违反本规定行为的； （二）证券期货经营机构及其工作人员发现监管人员存在应当回避的情形而未进行回避、利用职务之便索取或者收受不正当利益等违反廉洁规定行为的； （三）证券期货经营机构及其工作人员发现其股东、客户等相关方以不正当手段干扰监管工作的； （四）证券期货经营机构或者其工作人员因违反廉洁从业规定被纪检监察部门、司法机关立案调查或者被采取纪律处分、行政处罚、刑事处罚等措施的。 出现前款第（一）项情形的，应当同时向主管纪检监察部门报告，出现第（一）（二）（三）项情形且涉嫌犯罪的，相关部门应当依法移送监察、司法机关。"},{"i":16,"n":"第十六条","txt":"中国证监会在对证券期货经营机构及其工作人员的现场检查中，可以将廉洁从业管理情况纳入检查范围。证券期货经营机构及其工作人员应当予以配合。"},{"i":17,"n":"第十七条","txt":"中国证券业协会、中国期货业协会、中国证券投资基金业协会等自律组织应当制定和实施行业廉洁从业自律规则，监督、检查会员及其从业人员的执业行为，对违反廉洁从业规定的采取自律惩戒措施，并按照规定记入证券期货市场诚信档案。"},{"i":18,"n":"第十八条","txt":"证券期货经营机构及其工作人员违反本规定的，中国证监会可以采取出具警示函、责令参加培训、责令定期报告、责令改正、监管谈话、认定为不适当人选、暂不受理行政许可相关文件等行政监管措施。"},{"i":19,"n":"第十九条","txt":"证券期货经营机构及其工作人员违反本规定，并构成违反《证券法》《证券投资基金法》《证券公司监督管理条例》《期货交易管理条例》规定违法情形的，中国证监会可以采取限制业务活动，限制向董事、监事、高级管理人员支付报酬、提供福利，责令更换董事、监事、高级管理人员等行政监管措施，并按照相关法律法规的规定进行处罚。"},{"i":20,"n":"第二十条","txt":"证券期货经营机构及其工作人员违反本规定第九条、第十条、第十一条、第十二条、第十三条、第十四条、第十五条规定，按照相关法律法规的规定进行处罚，相关法律法规没有规定的，处以警告、3万元以下罚款。"},{"i":21,"n":"第二十一条","txt":"证券期货经营机构及其工作人员违反本规定，公司董事、监事、高级管理人员和其他人员负有管理责任的，中国证监会可以对其采取第十八条和第二十条规定的行政监管措施或者行政处罚。"},{"i":22,"n":"第二十二条","txt":"证券期货经营机构工作人员违反相关法律法规和本规定，情节严重的，中国证监会可以依法对其采取市场禁入的措施。 证券期货经营机构工作人员在开展证券期货业务及相关活动中向公职人员及其利益关系人输送不正当利益，或者唆使、协助他人向公职人员及其利益关系人输送不正当利益，情节特别严重的，中国证监会可以依法对其采取终身市场禁入的措施。"},{"i":23,"n":"第二十三条","txt":"证券期货经营机构及其工作人员违反本规定，有下列情形之一的，中国证监会应当从重处理： （一）直接、间接或者唆使、协助他人向监管人员输送利益； （二）连续或者多次违反本规定； （三）涉及金额较大或者涉及人员较多； （四）产生恶劣社会影响； （五）曾为公职人员特别是监管人员，以及曾任证券期货经营机构合规风控职务的人员违反本规定； （六）中国证监会认定应当从重处理的其他情形。"},{"i":24,"n":"第二十四条","txt":"证券期货经营机构通过有效的廉洁从业风险管理，主动发现违反本规定的行为，并积极有效整改，落实责任追究，完善内部控制制度和业务流程，及时向中国证监会报告的，依法免于追究责任或者从轻、减轻处理。 证券期货经营机构工作人员违反本规定，事后及时向中国证监会报告，或者积极配合调查的，依法免于追究责任或者从轻、减轻处理。"},{"i":25,"n":"第二十五条","txt":"证券期货经营机构及其工作人员涉嫌违反党纪、政纪的，中国证监会将有关情况通报相关主管单位纪检监察部门；涉嫌犯罪的，依法移送监察、司法机关，追究其刑事责任。"},{"i":26,"n":"第二十六条","txt":"本规定所称证券期货经营机构是指证券公司、期货公司、基金管理公司及其子公司。 本规定所称监管人员包括在中国证监会及其派出机构、行业协会、证券期货交易所、全国中小企业股份转让系统等单位从事监管工作的人员、发行审核委员会委员、并购重组委员会委员等。"},{"i":27,"n":"第二十七条","txt":"私募基金管理人、其他公募基金管理人、证券期货投资咨询机构、证券资信评级机构、基金销售机构、基金托管人以及从事基金评价、基金估值、信息技术服务等证券期货服务类机构参照本规定执行。"},{"i":28,"n":"第二十八条","txt":"中央纪委驻中国证监会纪检组及系统各级纪检监察机关对中国证监会、相关自律组织的上述工作开展监督、检查、问责。"},{"i":29,"n":"第二十九条","txt":"本规定自公布之日起施行。"}],"zhengquanqihuojingyingjigousimuzichanguanliyewugua52c8f9":[{"i":1,"n":"第一条","txt":"为规范证券期货经营机构私募资产管理业务，保护投资者及相关当事人的合法权益，维护证券期货市场秩序，根据《中华人民共和国证券法》、《中华人民共和国证券投资基金法》（以下简称《证券投资基金法》）、《证券公司监督管理条例》、《期货交易管理条例》、《关于规范金融机构资产管理业务的指导意见》（银发〔2018〕106号，以下简称《指导意见》）及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，证券期货经营机构非公开募集资金或者接受财产委托，设立私募资产管理计划（以下简称资产管理计划）并担任管理人，由托管机构担任托管人，依照法律法规和资产管理合同的约定，为投资者的利益进行投资活动，适用本办法。 本办法所称证券期货经营机构，是指证券公司、基金管理公司、期货公司及前述机构依法设立的从事私募资产管理业务的子公司。 证券期货经营机构非公开募集资金开展资产证券化业务，由中国证券监督管理委员会（以下简称中国证监会）另行规定。"},{"i":3,"n":"第三条","txt":"证券期货经营机构从事私募资产管理业务，应当遵循自愿、公平、诚实信用和客户利益至上原则，恪尽职守，谨慎勤勉，维护投资者合法权益，服务实体经济，不得损害国家利益、社会公共利益和他人合法权益。 证券期货经营机构应当遵守审慎经营规则，制定科学合理的投资策略和风险管理制度，有效防范和控制风险，确保业务开展与资本实力、管理能力及风险控制水平相适应。"},{"i":4,"n":"第四条","txt":"证券期货经营机构不得在表内从事私募资产管理业务，不得以任何方式向投资者承诺本金不受损失或者承诺最低收益。 投资者参与资产管理计划，应当根据自身能力审慎决策，独立承担投资风险。"},{"i":5,"n":"第五条","txt":"证券期货经营机构从事私募资产管理业务，应当实行集中运营管理，建立健全内部控制和合规管理制度，采取有效措施，将私募资产管理业务与公司其他业务分开管理，控制敏感信息的不当流动和使用，防范内幕交易、利用未公开信息交易、利益冲突和利益输送。"},{"i":6,"n":"第六条","txt":"资产管理计划财产的债务由资产管理计划财产本身承担，投资者以其出资为限对资产管理计划财产的债务承担责任。但资产管理合同依照《证券投资基金法》另有约定的，从其约定。 资产管理计划财产独立于证券期货经营机构和托管人的固有财产，并独立于证券期货经营机构管理的和托管人托管的其他财产。证券期货经营机构、托管人不得将资产管理计划财产归入其固有财产。 证券期货经营机构、托管人因资产管理计划财产的管理、运用或者其他情形而取得的财产和收益，归入资产管理计划财产。 证券期货经营机构、托管人因依法解散、被依法撤销或者被依法宣告破产等原因进行清算的，资产管理计划财产不属于其清算财产。 非因资产管理计划本身的债务或者法律规定的其他情形，不得查封、冻结、扣划或者强制执行资产管理计划财产。"},{"i":7,"n":"第七条","txt":"中国证监会及其派出机构依据法律、行政法规和本办法的规定，对证券期货经营机构私募资产管理业务实施监督管理。"},{"i":8,"n":"第八条","txt":"证券交易场所、期货交易所、证券登记结算机构、中国证券业协会（以下简称证券业协会）、中国期货业协会（以下简称期货业协会）、中国证券投资基金业协会（以下简称证券投资基金业协会）依照法律、行政法规和中国证监会的规定，对证券期货经营机构私募资产管理业务实施自律管理。"},{"i":9,"n":"第九条","txt":"证券期货经营机构从事私募资产管理业务，应当依法经中国证监会批准。法律、行政法规和中国证监会另有规定的除外。"},{"i":10,"n":"第十条","txt":"证券期货经营机构从事私募资产管理业务，应当符合以下条件： （一）净资产、净资本等财务和风险控制指标符合法律、行政法规和中国证监会的规定； （二）法人治理结构良好，内部控制、合规管理、风险管理制度完备； （三）具备符合条件的高级管理人员和三名以上投资经理； （四）具有投资研究部门，且专职从事投资研究的人员不少于三人； （五）具有符合要求的营业场所、安全防范设施、信息技术系统； （六）最近两年未因重大违法违规行为被行政处罚或者刑事处罚，最近一年未因重大违法违规行为被监管机构采取行政监管措施，无因涉嫌重大违法违规正受到监管机构或有权机关立案调查的情形； （七）中国证监会根据审慎监管原则规定的其他条件。 证券公司、基金管理公司、期货公司设立子公司从事私募资产管理业务，并由其投资研究部门为子公司提供投资研究服务的，视为符合前款第（四）项规定的条件。"},{"i":11,"n":"第十一条","txt":"证券期货经营机构从事私募资产管理业务，应当履行以下管理人职责： （一）依法办理资产管理计划的销售、登记、备案事宜； （二）对所管理的不同资产管理计划的受托财产分别管理、分别记账，进行投资； （三）按照资产管理合同的约定确定收益分配方案，及时向投资者分配收益； （四）进行资产管理计划会计核算并编制资产管理计划财务会计报告； （五）依法计算并披露资产管理计划净值，确定参与、退出价格； （六）办理与受托财产管理业务活动有关的信息披露事项； （七）保存受托财产管理业务活动的记录、账册、报表和其他相关资料； （八）以管理人名义，代表投资者利益行使诉讼权利或者实施其他法律行为； （九）法律、行政法规和中国证监会规定的其他职责。"},{"i":12,"n":"第十二条","txt":"投资经理应当依法取得从业资格，具有三年以上投资管理、投资研究、投资咨询等相关业务经验，具备良好的诚信记录和职业操守，且最近三年未被监管机构采取重大行政监管措施、行政处罚。"},{"i":13,"n":"第十三条","txt":"证券期货经营机构应当将受托财产交由依法取得基金托管资格的托管机构实施独立托管。法律、行政法规和中国证监会另有规定的除外。 托管人应当履行下列职责： （一）安全保管资产管理计划财产； （二）按照规定开设资产管理计划的托管账户，不同托管账户中的财产应当相互独立； （三）按照资产管理合同约定，根据管理人的投资指令，及时办理清算、交割事宜； （四）建立与管理人的对账机制，复核、审查管理人计算的资产管理计划资产净值和资产管理计划参与、退出价格； （五）监督管理人的投资运作，发现管理人的投资或清算指令违反法律、行政法规、中国证监会的规定或者资产管理合同约定的，应当拒绝执行，并向中国证监会相关派出机构和证券投资基金业协会报告； （六）办理与资产管理计划托管业务活动有关的信息披露事项； （七）对资产管理计划财务会计报告、年度报告出具意见； （八）保存资产管理计划托管业务活动的记录、账册、报表和其他相关"},{"i":14,"n":"第十四条","txt":"证券期货经营机构可以自行销售资产管理计划，也可以委托具有基金销售资格的机构（以下简称销售机构）销售或者推介资产管理计划。 销售机构应当依法、合规销售或者推介资产管理计划。"},{"i":15,"n":"第十五条","txt":"证券期货经营机构可以自行办理资产管理计划份额的登记、估值、核算，也可以委托中国证监会认可的其他机构代为办理。"},{"i":16,"n":"第十六条","txt":"证券期货经营机构从事私募资产管理业务，可以聘请符合中国证监会规定条件并接受国务院金融监督管理机构监管的机构为其提供投资顾问服务。证券期货经营机构依法应当承担的责任不因聘请投资顾问而免除。 证券期货经营机构应当向投资者详细披露所聘请的投资顾问的资质、收费等情况，以及更换、解聘投资顾问的条件和程序，充分揭示聘请投资顾问可能产生的特定风险。 证券期货经营机构不得聘请个人或者不符合条件的机构提供投资顾问服务。"},{"i":17,"n":"第十七条","txt":"证券期货经营机构、托管人、投资顾问及相关从业人员不得有下列行为： （一）利用资产管理计划从事内幕交易、操纵市场或者其他不当、违法的证券期货业务活动； （二）泄露因职务便利获取的未公开信息、利用该信息从事或者明示、暗示他人从事相关交易活动； （三）为违法或者规避监管的证券期货业务活动提供交易便利； （四）从事非公平交易、利益输送等损害投资者合法权益的行为； （五）利用资产管理计划进行商业贿赂； （六）侵占、挪用资产管理计划财产； （七）利用资产管理计划或者职务便利为投资者以外的第三方谋取不正当利益； （八）直接或者间接向投资者返还管理费； （九）以获取佣金或者其他不当利益为目的，使用资产管理计划财产进行不必要的交易； （十）法律、行政法规和中国证监会规定禁止的其他行为。"},{"i":18,"n":"第十八条","txt":"证券期货经营机构可以为单一投资者设立单一资产管理计划，也可以为多个投资者设立集合资产管理计划。 集合资产管理计划的投资者人数不少于二人，不得超过二百人。"},{"i":19,"n":"第十九条","txt":"单一资产管理计划可以接受货币资金委托，或者接受投资者合法持有的股票、债券或中国证监会认可的其他金融资产委托。集合资产管理计划原则上应当接受货币资金委托，中国证监会认可的情形除外。 证券登记结算机构应当按照规定为接受股票、债券等证券委托的单一资产管理计划办理证券非交易过户等手续。"},{"i":20,"n":"第二十条","txt":"资产管理计划应当具有明确、合法的投资方向，具备清晰的风险收益特征，并区分最终投向资产类别，按照下列规定确定资产管理计划所属类别： （一）投资于存款、债券等债权类资产的比例不低于资产管理计划总资产80%的，为固定收益类； （二）投资于股票、未上市企业股权等股权类资产的比例不低于资产管理计划总资产80%的，为权益类； （三）投资于商品及金融衍生品的持仓合约价值的比例不低于资产管理计划总资产80%，且衍生品账户权益超过资产管理计划总资产20%的，为商品及金融衍生品类； （四）投资于债权类、股权类、商品及金融衍生品类资产的比例未达到前三类产品标准的，为混合类。"},{"i":21,"n":"第二十一条","txt":"根据资产管理计划的类别、投向资产的流动性及期限特点、投资者需求等因素，证券期货经营机构可以设立存续期间办理参与、退出的开放式资产管理计划，或者存续期间不办理参与和退出的封闭式资产管理计划。 开放式资产管理计划应当明确投资者参与、退出的时间、次数、程序及限制事项。开放式集合资产管理计划每三个月至多开放一次计划份额的参与、退出，中国证监会另有规定的除外。"},{"i":22,"n":"第二十二条","txt":"单一资产管理计划可以不设份额，集合资产管理计划应当设定为均等份额。 开放式集合资产管理计划不得进行份额分级。封闭式集合资产管理计划可以根据风险收益特征对份额进行分级。同级份额享有同等权益、承担同等风险。分级资产管理计划优先级与劣后级的比例应当符合法律、行政法规和中国证监会的规定。 分级资产管理计划的名称应当包含“分级”或“结构化”字样，证券期货经营机构应当向投资者充分披露资产管理计划的分级设计及相应风险、收益分配、风险控制等信息。"},{"i":23,"n":"第二十三条","txt":"证券期货经营机构可以设立基金中基金资产管理计划，将80%以上的资产管理计划资产投资于接受国务院金融监督管理机构监管的机构发行的资产管理产品，但不得违反本办法第四十四条、第四十五条以及中国证监会的其他规定。 证券期货经营机构应当向投资者充分披露基金中基金资产管理计划所投资资产管理产品的选择标准、资产管理计划发生的费用、投资管理人及管理人关联方所设立的资产管理产品的情况。 本办法所称关联方按照《企业会计准则》的规定确定。"},{"i":24,"n":"第二十四条","txt":"证券期货经营机构可以设立管理人中管理人资产管理计划，具体规则由中国证监会另行制定。"},{"i":25,"n":"第二十五条","txt":"资产管理计划应当以非公开方式向合格投资者募集。 证券期货经营机构、销售机构不得公开或变相公开募集资产管理计划，不得通过报刊、电台、电视、互联网等传播媒体或者讲座、报告会、传单、布告、自媒体等方式向不特定对象宣传具体资产管理计划。 证券期货经营机构不得设立多个资产管理计划，同时投资于同一非标准化资产，以变相突破投资者人数限制或者其他监管要求。单一主体及其关联方的非标准化资产，视为同一非标准化资产。 任何单位和个人不得以拆分份额或者转让份额收（受）益权等方式，变相突破合格投资者标准或人数限制。"},{"i":26,"n":"第二十六条","txt":"证券期货经营机构募集资产管理计划，应当与投资者、托管人签订资产管理合同。资产管理合同应当包括《证券投资基金法》第九十二条、第九十三条规定的内容。 资产管理合同应当对巨额退出、延期支付、延期清算、管理人变更或者托管人变更等或有事项，作出明确约定。"},{"i":27,"n":"第二十七条","txt":"证券期货经营机构和销售机构在募集资产管理计划过程中，应当按照中国证监会的规定，严格履行适当性管理义务，充分了解投资者，对投资者进行分类，对资产管理计划进行风险评级，遵循风险匹配原则，向投资者推荐适当的产品，禁止误导投资者购买与其风险承受能力不相符合的产品，禁止向风险识别能力和风险承受能力低于产品风险等级的投资者销售资产管理计划。 投资者应当以真实身份和自有资金参与资产管理计划，并承诺委托资金的来源符合法律、行政法规的规定。投资者未作承诺，或者证券期货经营机构、销售机构知道或者应当知道投资者身份不真实、委托资金来源不合法的，证券期货经营机构、销售机构不得接受其参与资产管理计划。"},{"i":28,"n":"第二十八条","txt":"销售机构应当在募集结束后十个工作日内，将销售过程中产生和保存的投资者信息及资料全面、准确、及时提供给证券期货经营机构。 资产管理计划存续期间持续销售的，销售机构应当在销售行为完成后五个工作日内，将销售过程中产生和保存的投资者信息及资料全面、准确、及时提供给证券期货经营机构。"},{"i":29,"n":"第二十九条","txt":"集合资产管理计划募集期间，证券期货经营机构、销售机构应当在规定期限内，将投资者参与资金存入集合资产管理计划份额登记机构指定的专门账户。集合资产管理计划成立前，任何机构和个人不得动用投资者参与资金。 按照前款规定存入专门账户的投资者参与资金，独立于证券期货经营机构、销售机构的固有财产。非因投资者本身的债务或者法律规定的其他情形，不得查封、冻结、扣划或者强制执行存入专门账户的投资者参与资金。"},{"i":30,"n":"第三十条","txt":"集合资产管理计划成立应当具备下列条件： （一）募集过程符合法律、行政法规和中国证监会的规定； （二）募集金额达到资产管理合同约定的成立规模，且不违反中国证监会规定的最低成立规模； （三）投资者人数不少于二人； （四）符合中国证监会规定以及资产管理合同约定的其他条件。"},{"i":31,"n":"第三十一条","txt":"集合资产管理计划的募集金额缴足之日起十个工作日内，证券期货经营机构应当委托具有证券相关业务资格的会计师事务所进行验资并出具验资报告。 集合资产管理计划在取得验资报告后，由证券期货经营机构公告资产管理计划成立；单一资产管理计划在受托资产入账后，由证券期货经营机构书面通知投资者资产管理计划成立。"},{"i":32,"n":"第三十二条","txt":"证券期货经营机构应当在资产管理计划成立之日起五个工作日内，将资产管理合同、投资者名单与认购金额、验资报告或者资产缴付证明等材料报证券投资基金业协会备案，并抄报中国证监会相关派出机构。 资产管理计划完成备案前不得开展投资活动，以现金管理为目的，投资于银行活期存款、国债、中央银行票据、政策性金融债、地方政府债券、货币市场基金等中国证监会认可的投资品种的除外。 证券投资基金业协会应当制定资产管理计划备案规则，明确工作程序和期限，并向社会公开。"},{"i":33,"n":"第三十三条","txt":"证券期货经营机构应当在资产管理合同约定的募集期内，完成集合资产管理计划的募集。募集期届满，集合资产管理计划未达到本办法第三十条规定的成立条件的，证券期货经营机构应当承担下列责任： （一）以其固有财产承担因募集行为而产生的债务和费用; （二）在募集期届满后三十日内返还投资者已缴纳的款项，并加计银行同期活期存款利息。"},{"i":34,"n":"第三十四条","txt":"证券期货经营机构以自有资金参与集合资产管理计划，应当符合法律、行政法规和中国证监会的规定，并按照《中华人民共和国公司法》和公司章程的规定，获得公司股东会、董事会或者其他授权程序的批准。 证券期货经营机构自有资金所持的集合资产管理计划份额，应当与投资者所持的同类份额享有同等权益、承担同等风险。"},{"i":35,"n":"第三十五条","txt":"投资者可以通过证券交易所以及中国证监会认可的其他方式，向合格投资者转让其持有的集合资产管理计划份额，并按规定办理份额变更登记手续。转让后，持有资产管理计划份额的合格投资者合计不得超过二百人。 证券期货经营机构应当在集合资产管理计划份额转让前，对受让人的合格投资者身份和资产管理计划的投资者人数进行合规性审查。受让方首次参与集合资产管理计划的，应当先与证券期货经营机构、托管人签订资产管理合同。 证券期货经营机构、交易场所不得通过办理集合资产管理计划的份额转让，公开或变相公开募集资产管理计划。"},{"i":36,"n":"第三十六条","txt":"证券期货经营机构设立集合资产管理计划进行投资，除中国证监会另有规定外，应当采用资产组合的方式。 资产组合的具体方式和比例，依照法律、行政法规和中国证监会的规定在资产管理合同中约定。"},{"i":37,"n":"第三十七条","txt":"资产管理计划可以投资于以下资产： （一）银行存款、同业存单，以及符合《指导意见》规定的标准化债权类资产，包括但不限于在证券交易所、银行间市场等国务院同意设立的交易场所交易的可以划分为均等份额、具有合理公允价值和完善流动性机制的债券、中央银行票据、资产支持证券、非金融企业债务融资工具等； （二）上市公司股票、存托凭证，以及中国证监会认可的其他标准化股权类资产； （三）在证券期货交易所等国务院同意设立的交易场所集中交易清算的期货及期权合约等标准化商品及金融衍生品类资产； （四）公开募集证券投资基金（以下简称公募基金），以及中国证监会认可的比照公募基金管理的资产管理产品； （五）第（一）至（三）项规定以外的非标准化债权类资产、股权类资产、商品及金融衍生品类资产； （六）第（四）项规定以外的其他受国务院金融监督管理机构监管的机构发行的资产管理产品； （七）中国证监会认可的其他资产。 前款第（一"},{"i":38,"n":"第三十八条","txt":"资产管理计划可以依法参与证券回购、融资融券、转融通以及中国证监会认可的其他业务。法律、行政法规和中国证监会另有规定的除外。 证券期货经营机构可以依法设立资产管理计划在境内募集资金，投资于中国证监会认可的境外金融产品。"},{"i":39,"n":"第三十九条","txt":"资产管理计划不得直接投资商业银行信贷资产；不得违规为地方政府及其部门提供融资，不得要求或者接受地方政府及其部门违规提供担保；不得直接或者间接投资法律、行政法规和国家政策禁止投资的行业或领域。"},{"i":40,"n":"第四十条","txt":"资产管理计划存续期间，证券期货经营机构应当严格按照法律、行政法规、中国证监会规定以及合同约定的投向和比例进行资产管理计划的投资运作。 资产管理计划改变投向和比例的，应当事先取得投资者同意，并按规定履行合同变更程序。 因证券期货市场波动、证券发行人合并、资产管理计划规模变动等证券期货经营机构之外的因素导致资产管理计划投资不符合法律、行政法规和中国证监会规定的投资比例或者合同约定的投资比例的，证券期货经营机构应当在流动性受限资产可出售、可转让或者恢复交易的十五个交易日内调整至符合相关要求。确有特殊事由未能在规定时间内完成调整的，证券期货经营机构应当及时向中国证监会相关派出机构和证券投资基金业协会报告。"},{"i":41,"n":"第四十一条","txt":"证券期货经营机构应当确保资产管理计划所投资的资产组合的流动性与资产管理合同约定的参与、退出安排相匹配，确保在开放期保持适当比例的现金或者其他高流动性金融资产，且限制流动性受限资产投资比例。"},{"i":42,"n":"第四十二条","txt":"资产管理计划的总资产不得超过该计划净资产的200%，分级资产管理计划的总资产不得超过该计划净资产的140%。"},{"i":43,"n":"第四十三条","txt":"证券期货经营机构应当对资产管理计划实行净值化管理，确定合理的估值方法和科学的估值程序，真实公允地计算资产管理计划净值。"},{"i":44,"n":"第四十四条","txt":"资产管理计划接受其他资产管理产品参与，证券期货经营机构应当切实履行主动管理职责，不得进行转委托，不得再投资除公募基金以外的其他资产管理产品。"},{"i":45,"n":"第四十五条","txt":"资产管理计划投资于其他资产管理产品的，应当明确约定所投资的资产管理产品不再投资除公募基金以外的其他资产管理产品。 资产管理计划投资于其他资产管理产品的，计算该资产管理计划的总资产时应当按照穿透原则合并计算所投资资产管理产品的总资产。 资产管理计划投资于其他私募资产管理产品的，该资产管理计划按照穿透原则合并计算的投资同一资产的比例以及投资同一或同类资产的金额，应当符合本办法及中国证监会相关规定。 资产管理计划应当按照所投资资产管理产品披露投资组合的频率，及时更新计算该资产管理计划所投资资产的金额或比例。 证券期货经营机构不得将其管理的资产管理计划资产投资于该机构管理的其他资产管理计划，依法设立的基金中基金资产管理计划以及中国证监会另有规定的除外。"},{"i":46,"n":"第四十六条","txt":"证券期货经营机构应当切实履行主动管理职责，不得有下列行为： （一）为其他机构、个人或者资产管理产品提供规避投资范围、杠杆约束等监管要求的通道服务； （二）在资产管理合同中约定由委托人或其指定第三方自行负责尽职调查或者投资运作； （三）在资产管理合同中约定由委托人或其指定第三方下达投资指令或者提供投资建议； （四）在资产管理合同中约定管理人根据委托人或其指定第三方的意见行使资产管理计划所持证券的权利； （五）法律、行政法规和中国证监会禁止的其他行为。"},{"i":47,"n":"第四十七条","txt":"证券期货经营机构、托管人、销售机构和其他信息披露义务人应当依法披露资产管理计划信息，保证所披露信息的真实性、准确性、完整性、及时性，确保投资者能够按照资产管理合同约定的时间和方式查阅或者复制所披露的信息资料。"},{"i":48,"n":"第四十八条","txt":"资产管理计划应向投资者提供下列信息披露文件： （一）资产管理合同、计划说明书和风险揭示书； （二）资产管理计划净值，资产管理计划参与、退出价格； （三）资产管理计划定期报告，至少包括季度报告和年度报告； （四）重大事项的临时报告； （五）资产管理计划清算报告； （六）中国证监会规定的其他事项。 证券期货经营机构向投资者提供的信息披露文件，应当及时报送中国证监会相关派出机构、证券投资基金业协会。 信息披露文件的内容与格式指引由中国证监会或者授权证券投资基金业协会另行制定。"},{"i":49,"n":"第四十九条","txt":"证券期货经营机构募集资产管理计划，除向投资者提供资产管理合同外，还应当制作计划说明书和风险揭示书，详细说明资产管理计划管理和运作情况，充分揭示资产管理计划的各类风险。 计划说明书披露的信息应当与资产管理合同内容一致。销售机构应当使用证券期货经营机构制作的计划说明书和其他销售材料，不得擅自修改或者增减材料。 风险揭示书应当作为资产管理计划合同的一部分交由投资者签字确认。"},{"i":50,"n":"第五十条","txt":"资产管理计划运作期间，证券期货经营机构应当按照以下要求向投资者提供相关信息： （一）投资标准化资产的资产管理计划至少每周披露一次净值，投资非标准化资产的资产管理计划至少每季度披露一次净值； （二）开放式资产管理计划净值的披露频率不得低于资产管理计划的开放频率，分级资产管理计划应当披露各类别份额净值； （三）每季度结束之日起一个月内披露季度报告，每年度结束之日起四个月内披露年度报告； （四）发生资产管理合同约定的或者可能影响投资者利益的重大事项时，在事项发生之日起五日内向投资者披露； （五）中国证监会规定的其他要求。 资产管理计划成立不足三个月或者存续期间不足三个月的，证券期货经营机构可以不编制资产管理计划当期的季度报告和年度报告。"},{"i":51,"n":"第五十一条","txt":"披露资产管理计划信息，不得有下列行为： （一）虚假记载、误导性陈述或者重大遗漏； （二）对投资业绩进行预测，或者宣传预期收益率； （三）承诺收益，承诺本金不受损失或者限定损失金额或比例； （四）夸大或者片面宣传管理人、投资经理及其管理的资产管理计划的过往业绩； （五）恶意诋毁、贬低其他资产管理人、托管人、销售机构或者其他资产管理产品； （六）中国证监会禁止的其他情形。"},{"i":52,"n":"第五十二条","txt":"集合资产管理计划年度财务会计报告应当经具有证券相关业务资格的会计师事务所审计，审计机构应当对资产管理计划会计核算及净值计算等出具意见。"},{"i":53,"n":"第五十三条","txt":"资产管理合同需要变更的，证券期货经营机构应当按照资产管理合同约定的方式取得投资者和托管人的同意，保障投资者选择退出资产管理计划的权利，对相关后续事项作出公平、合理安排。 证券期货经营机构应当自资产管理合同变更之日起五个工作日内报证券投资基金业协会备案，并抄报中国证监会相关派出机构。"},{"i":54,"n":"第五十四条","txt":"资产管理计划展期应当符合下列条件： （一）资产管理计划运作规范，证券期货经营机构、托管人未违反法律、行政法规、中国证监会规定和资产管理合同的约定； （二）资产管理计划展期没有损害投资者利益的情形； （三）中国证监会规定的其他条件。 集合资产管理计划展期的，还应当符合集合资产管理计划的成立条件。"},{"i":55,"n":"第五十五条","txt":"有下列情形之一的，资产管理计划终止： （一）资产管理计划存续期届满且不展期； （二）证券期货经营机构被依法撤销资产管理业务资格或者依法解散、被撤销、被宣告破产，且在六个月内没有新的管理人承接； （三）托管人被依法撤销基金托管资格或者依法解散、被撤销、被宣告破产，且在六个月内没有新的托管人承接； （四）经全体投资者、证券期货经营机构和托管人协商一致决定终止的； （五）发生资产管理合同约定的应当终止的情形； （六）集合资产管理计划存续期间，持续五个工作日投资者少于二人； （七）法律、行政法规及中国证监会规定的其他情形。 证券期货经营机构应当自资产管理计划终止之日起五个工作日内报证券投资基金业协会备案，并抄报中国证监会相关派出机构。"},{"i":56,"n":"第五十六条","txt":"资产管理计划终止的，证券期货经营机构应当在发生终止情形之日起五个工作日内开始组织清算资产管理计划财产。 清算后的剩余财产，集合资产管理计划应当按照投资者持有份额占总份额的比例或者资产管理合同的约定，以货币资金形式分配给投资者，中国证监会另有规定的除外；单一资产管理计划应当按照合同约定的形式将全部财产交还投资者自行管理。 证券期货经营机构应当在资产管理计划清算结束后五个工作日内将清算结果报证券投资基金业协会备案，并抄报中国证监会相关派出机构。 资产管理计划因委托财产流动性受限等原因延期清算的，证券期货经营机构应当及时向中国证监会相关派出机构和证券投资基金业协会报告。"},{"i":57,"n":"第五十七条","txt":"证券期货经营机构、托管人、销售机构等机构应当按照法律、行政法规和中国证监会的规定保存资产管理计划的会计账册，妥善保存有关的合同、协议、交易记录等文件、资料和数据，任何人不得隐匿、伪造、篡改或者销毁。保存期限自资产管理计划终止之日起不少于二十年。"},{"i":58,"n":"第五十八条","txt":"证券期货经营机构应当建立健全与私募资产管理业务相关的投资者适当性、投资决策、公平交易、会计核算、风险控制、合规管理、投诉处理等管理制度，覆盖私募资产管理业务的产品设计、募集、研究、投资、交易、会计核算、信息披露、清算、信息技术、投资者服务等各个环节，明确岗位职责和责任追究机制，确保各项制度流程得到有效执行。"},{"i":59,"n":"第五十九条","txt":"证券期货经营机构应当采取有效措施，确保私募资产管理业务与其他业务在场地、人员、账户、资金、信息等方面相分离，不同投资经理管理的资产管理计划的持仓和交易等重大非公开投资信息相隔离，控制敏感信息的不当流动和使用，切实防范内幕交易、利用未公开信息交易、利益冲突和利益输送。"},{"i":60,"n":"第六十条","txt":"证券期货经营机构应当明确投资决策流程与授权管理制度，建立、维护投资对象与交易对手备选库，设定清晰的清算流程和资金划转路径，对资产管理计划账户日常交易情况进行风险识别、监测，严格执行风险控制措施和投资交易复核程序，保证投资决策按照法律、行政法规、中国证监会的规定以及合同约定执行。 投资经理应当在授权范围内独立、客观地履行职责，重要投资应当有详细的研究报告和风险分析支持。"},{"i":61,"n":"第六十一条","txt":"证券期货经营机构应当建立健全信用风险管理制度，对信用风险进行准确识别、审慎评估、动态监控、及时应对和全程管理。 证券期货经营机构应当对投资对象、交易对手开展必要的尽职调查，实施严格的准入管理和交易额度管理，评估并持续关注证券发行人、融资主体和交易对手的资信状况，以及担保物状况、增信措施和其他保障措施的有效性。出现可能影响投资者权益的事项，证券期货经营机构应当及时采取申请追加担保、依法申请财产保全等风险控制措施。"},{"i":62,"n":"第六十二条","txt":"资产管理计划投资于本办法第三十七条第（五）项规定资产的，证券期货经营机构应当建立专门的质量控制制度，进行充分尽职调查并制作书面报告，设置专岗负责投后管理、信息披露等事宜，动态监测风险。"},{"i":63,"n":"第六十三条","txt":"证券期货经营机构应当建立健全流动性风险监测、预警与应急处置制度，将私募资产管理业务纳入常态化压力测试机制，压力测试应当至少每季度进行一次。 证券期货经营机构应当结合市场状况和自身管理能力制定并持续更新流动性风险应急预案，明确预案触发情景、应急程序与措施、应急资金来源、公司董事会、管理层及各部门职责与权限等。"},{"i":64,"n":"第六十四条","txt":"证券期货经营机构应当建立公平交易制度及异常交易监控机制，公平对待所管理的不同资产，对投资交易行为进行监控、分析、评估、核查，监督投资交易的过程和结果，保证公平交易原则的实现，不得开展可能导致不公平交易和利益输送的交易行为。 证券期货经营机构应当对不同资产管理计划之间发生的同向交易和反向交易进行监控。同一资产管理计划不得在同一交易日内进行反向交易。确因投资策略或流动性等需要发生同日反向交易的，应要求投资经理提供决策依据，并留存书面记录备查。 资产管理计划依法投资于本办法第三十七条第（三）项规定资产的，在同一交易日内进行反向交易的，不受前款规定限制。"},{"i":65,"n":"第六十五条","txt":"证券期货经营机构的自营账户、资产管理计划账户、作为投资顾问管理的产品账户之间，以及不同资产管理计划账户之间，不得发生交易，有充分证据证明进行有效隔离并且价格公允的除外。 子公司从事私募资产管理业务的，证券期货经营机构的自营账户、资产管理计划账户以及作为投资顾问管理的产品账户与子公司的资产管理计划账户之间的交易，适用本条规定。"},{"i":66,"n":"第六十六条","txt":"证券期货经营机构应当建立健全关联交易管理制度，对关联交易认定标准、交易定价方法、交易审批程序进行规范，不得以资产管理计划的资产与关联方进行不正当交易、利益输送、内幕交易和操纵市场。 证券期货经营机构以资产管理计划资产从事重大关联交易的，应当遵守法律、行政法规、中国证监会的规定和合同约定，事先取得投资者的同意，事后及时告知投资者和托管人，并向中国证监会相关派出机构和证券投资基金业协会报告，投资于证券期货的关联交易还应当向证券期货交易所报告。"},{"i":67,"n":"第六十七条","txt":"证券期货经营机构应当建立健全信息披露管理制度，设置专门部门或者专岗负责信息披露工作，明确负责的高级管理人员，并建立复核机制，通过规范渠道向投资者披露有关信息，还应当定期对信息披露工作的真实性、准确性、完整性、及时性等进行评估。"},{"i":68,"n":"第六十八条","txt":"证券期货经营机构和托管人应当加强对私募资产管理业务从业人员的管理，加强关键岗位的监督与制衡，投资经理、交易执行、风险控制等岗位不得相互兼任，并建立从业人员投资申报、登记、审查、处置等管理制度，防范与投资者发生利益冲突。 证券期货经营机构应当完善长效激励约束机制，不得以人员挂靠、业务包干等方式从事私募资产管理业务。 证券期货经营机构分管私募资产管理业务的高级管理人员、私募资产管理业务部门负责人以及投资经理离任的，证券期货经营机构应当立即对其进行离任审查，并自离任之日起三十个工作日内将审查报告报送中国证监会相关派出机构和证券投资基金业协会。"},{"i":69,"n":"第六十九条","txt":"证券期货经营机构应当建立资产管理计划的销售机构和投资顾问的授权管理体系，明确销售机构和投资顾问的准入标准和程序，对相关机构资质条件、专业服务能力和风险管理制度等进行尽职调查，确保其符合法规规定。证券期货经营机构应当以书面方式明确界定双方的权利与义务，明确相关风险的责任承担方式。 证券期货经营机构应当建立对销售机构和投资顾问履职情况的监督评估机制，发现违法违规行为的，应当及时更换并报告中国证监会相关派出机构和证券投资基金业协会。"},{"i":70,"n":"第七十条","txt":"证券期货经营机构应当每月从资产管理计划管理费中计提风险准备金，或者按照法律、行政法规以及中国证监会的规定计算风险资本准备。 风险准备金主要用于弥补因证券期货经营机构违法违规、违反资产管理合同约定、操作错误或者技术故障等给资产管理计划资产或者投资者造成的损失。风险准备金计提比例不得低于管理费收入的10%，风险准备金余额达到上季末资产管理计划资产净值的1%时可以不再提取。 计提风险准备金的证券期货经营机构，应当选定具有基金托管资格的商业银行开立专门的私募资产管理业务风险准备金账户，该账户不得与公募基金风险准备金账户及其他类型账户混用，不得存放其他性质资金。风险准备金的投资管理和使用，应当参照公募基金风险准备金监督管理有关规定执行。证券期货经营机构应当在私募资产管理业务管理年度报告中，对风险准备金的提取、投资管理、使用、年末结余等情况作专项说明。"},{"i":71,"n":"第七十一条","txt":"证券期货经营机构合规管理和风险管理部门应当定期对私募资产管理业务制度及执行情况进行检查，发现违反法律、行政法规、中国证监会规定或者合同约定的，应当及时纠正处理，并向中国证监会及相关派出机构、证券投资基金业协会报告。"},{"i":72,"n":"第七十二条","txt":"证券期货经营机构应当建立健全应急处理机制，对发生延期兑付、负面舆论、群体性事件等风险事件的处理原则、方案等作出明确规定，并指定高级管理人员负责实施。出现重大风险事件的，应当及时向中国证监会及相关派出机构、证券投资基金业协会报告。"},{"i":73,"n":"第七十三条","txt":"证券期货经营机构应当于每月十日前向中国证监会及相关派出机构、证券投资基金业协会报送资产管理计划的持续募集情况、投资运作情况、资产最终投向等信息。 证券期货经营机构应当在每季度结束之日起一个月内，编制私募资产管理业务管理季度报告，并报中国证监会相关派出机构和证券投资基金业协会备案。证券期货经营机构、托管人应当在每年度结束之日起四个月内，分别编制私募资产管理业务管理年度报告和托管年度报告，并报中国证监会相关派出机构和证券投资基金业协会备案。 证券期货经营机构应当在私募资产管理业务管理季度报告和管理年度报告中，就本办法所规定的风险管理与内部控制制度在报告期内的执行情况等进行分析，并由合规负责人、风控负责人、总经理分别签署。"},{"i":74,"n":"第七十四条","txt":"证券期货经营机构进行年度审计，应当同时对私募资产管理业务的内部控制情况进行审计。 证券期货经营机构应当在每年度结束之日起四个月内将前述审计结果报送中国证监会及相关派出机构、证券投资基金业协会。"},{"i":75,"n":"第七十五条","txt":"证券交易场所、期货交易所、中国期货市场监控中心（以下简称期货市场监控中心）应当对证券期货经营机构资产管理计划交易行为进行监控。发现存在重大风险、重大异常交易或者涉嫌违法违规事项的，应当及时报告中国证监会及相关派出机构。 证券投资基金业协会应当按照法律、行政法规和中国证监会规定对证券期货经营机构资产管理计划实施备案管理和监测监控。发现提交备案的资产管理计划不符合法律、行政法规和中国证监会规定的，不得予以备案，并报告中国证监会及相关派出机构；发现已备案的资产管理计划存在重大风险或者违规事项的，应当及时报告中国证监会及相关派出机构。"},{"i":76,"n":"第七十六条","txt":"中国证监会及其派出机构对证券期货经营机构、托管人、销售机构和投资顾问等服务机构从事私募资产管理及相关业务的情况，进行定期或者不定期的现场和非现场检查，相关机构应当予以配合。 中国证监会相关派出机构应当定期对辖区证券期货经营机构私募资产管理业务开展情况进行总结分析，纳入监管季度报告和年度报告，发现存在重大风险或者违规事项的，应当及时报告中国证监会。"},{"i":77,"n":"第七十七条","txt":"中国证监会与中国人民银行、中国银行保险监督管理委员会建立监督管理信息共享机制，加强资产管理业务的统计信息共享。 中国证监会及其派出机构、证券交易场所、期货交易所、证券登记结算机构、期货市场监控中心、证券业协会、期货业协会、证券投资基金业协会应当加强证券期货经营机构私募资产管理业务数据信息共享。 证券交易场所、期货交易所、证券登记结算机构、期货市场监控中心、证券业协会、期货业协会、证券投资基金业协会应当按照中国证监会的要求，定期或者不定期提供证券期货经营机构私募资产管理业务专项统计、分析等数据信息。 中国证监会相关派出机构应当每月对证券期货经营机构资产管理计划备案信息和业务数据进行分析汇总，并按照本办法第七十六条的规定报告。"},{"i":78,"n":"第七十八条","txt":"证券期货经营机构、托管人、销售机构和投资顾问等服务机构违反法律、行政法规、本办法及中国证监会其他规定的，中国证监会及相关派出机构可以对其采取责令改正、监管谈话、出具警示函、责令定期报告、暂不受理与行政许可有关的文件等行政监管措施；对直接负责的主管人员和其他直接责任人员，采取监管谈话、出具警示函、责令参加培训、认定为不适当人选等行政监管措施。"},{"i":79,"n":"第七十九条","txt":"证券公司及其子公司、基金管理公司及其子公司违反本办法规定构成公司治理结构不健全、内部控制不完善等情形的，对证券公司、基金管理公司及其直接负责的董事、监事、高级管理人员和其他直接责任人员，依照《证券投资基金法》第二十四条、《证券公司监督管理条例》第七十条采取行政监管措施。 期货公司及其子公司违反本办法规定被责令改正且逾期未改正，其行为严重危及期货公司的稳健运行，损害客户合法权益，或者涉嫌严重违法违规正在被中国证监会及其派出机构调查的，依照《期货交易管理条例》第五十五条采取行政监管措施。 证券期货经营机构未尽合规审查义务，提交备案的资产管理计划明显或者频繁不符合法律、行政法规和中国证监会规定的，依照本条第一款、第二款规定，采取责令暂停私募资产管理业务三个月的行政监管措施；情节严重的，采取责令暂停私募资产管理业务六个月以上的行政监管措施。"},{"i":80,"n":"第八十条","txt":"证券期货经营机构、托管人、销售机构和投资顾问等服务机构有下列情形之一且情节严重的，除法律、行政法规另有规定外，给予警告，并处三万元以下罚款，对直接负责的主管人员和其他直接责任人员，给予警告，并处三万元以下罚款： （一）违反本办法第三条至第六条规定的基本原则； （二）违反本办法第十一条、第十三条的规定，未按规定履行管理人和托管人职责，或者从事第十七条所列举的禁止行为； （三）违反本办法第十四条、第十六条的规定，聘请不符合条件的销售机构、投资顾问； （四）违反本办法第二十二条关于产品分级的规定； （五）违反本办法第二十五条、第二十六条、第二十七条、第二十八条、第二十九条、第三十条、第三十一条、第三十二条、第三十四条、第三十五条关于非公开募集的规定； （六）违反本办法第五章关于投资运作的规定； （七）违反本办法第四十七条、第四十八条、第五十条、第五十一条，未按照规定向投资者披露资产管理计划信"},{"i":81,"n":"第八十一条","txt":"证券期货经营机构、托管人、销售机构和投资顾问等服务机构的相关从业人员违反法律、行政法规和本办法规定，情节严重的，中国证监会可以依法采取市场禁入措施。"},{"i":82,"n":"第八十二条","txt":"过渡期自本办法实施之日起至2020年12月31日。 过渡期内，证券期货经营机构应当自行制定整改计划，有序压缩不符合本办法规定的资产管理计划规模；对于不符合本办法规定的存量资产管理计划，其持有资产未到期的，证券期货经营机构可以设立老产品对接，或者予以展期。过渡期结束后，证券期货经营机构不得发行或者存续违反本办法规定的资产管理计划。 依据《证券公司客户资产管理业务管理办法》（证监会令第93号）、《证券公司定向资产管理业务实施细则》（证监会公告〔2012〕30号）设立的存量定向资产管理计划投资于上市公司股票、挂牌公司股票的，其所持证券的所有权归属、权利行使、信息披露以及证券账户名称等不符合本办法规定的，不受前述过渡期期限的限制，但最晚应当在2023年12月31日前完成规范。"},{"i":83,"n":"第八十三条","txt":"鼓励证券公司设立子公司从事私募资产管理业务，加强风险法人隔离。专门从事资产管理业务的证券公司除外。 鼓励证券公司设立子公司专门从事投资于本办法第三十七条第（五）项规定资产的私募资产管理业务。 中国证监会依据审慎监管原则，对依照本条第一款、第二款规定设立子公司的证券公司，在分类评价、风险资本准备计算等方面实施差异化安排。"},{"i":84,"n":"第八十四条","txt":"证券期货经营机构设立特定目的公司或者合伙企业从事私募资产管理业务的，参照适用本办法。"},{"i":85,"n":"第八十五条","txt":"本办法自2018年10月22日起施行。《证券公司客户资产管理业务管理办法》（证监会令第93号）、《基金管理公司特定客户资产管理业务试点办法》（证监会令第83号）、《期货公司资产管理业务试点办法》（证监会令第81号）、《证券公司集合资产管理业务实施细则》（证监会公告〔2013〕28号）、《证券公司定向资产管理业务实施细则》（证监会公告〔2012〕30号）、《关于实施<基金管理公司特定客户资产管理业务试点办法>有关问题的规定》（证监会公告〔2012〕23号）、《基金管理公司单一客户资产管理合同内容与格式准则》（证监会公告〔2012〕24号）、《基金管理公司特定多个客户资产管理合同内容与格式准则》（证监会公告〔2012〕25号）同时废止。"}],"zhengquanqihuoguizhangzhidingchengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范证券期货规章制定程序，提高规章质量和立法工作效率，根据《中华人民共和国立法法》（以下简称立法法）、《规章制定程序条例》《行政法规制定程序条例》《法规规章备案条例》和《法规汇编编辑出版管理规定》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称证券期货规章（以下简称规章）是指中国证券监督管理委员会（以下简称中国证监会）为履行其证券期货市场监管职责，根据法律、行政法规和国务院授权制定并以中国证监会令的形式公布的规定、办法等。"},{"i":3,"n":"第三条","txt":"规章的立项、起草、审查、决定、公布、备案、解释、修改、废止、汇编和翻译，适用本规定。"},{"i":4,"n":"第四条","txt":"制定规章，应当贯彻落实党的路线方针政策和决策部署，体现全面深化改革精神，遵循立法法确定的立法原则，符合宪法、法律、行政法规和其他上位法的规定。 制定规章，应当注重调查研究，立足我国证券期货市场的发展实际，增强规章的规范化程度和前瞻性、可操作性。"},{"i":5,"n":"第五条","txt":"制定规章，应当经中国证监会委务会议（以下简称委务会）审议通过。 中国证监会制定涉外规章，应当按照有关规定向国务院报告。"},{"i":6,"n":"第六条","txt":"中国证监会法制机构（以下简称法制机构）负责组织规章的制定工作，履行下列职责： （一）研究、拟订、公布年度规章制定工作计划，组织、督促计划的执行； （二）起草或者组织起草规章草案； （三）审查、修改规章草案送审稿（以下简称规章送审稿）； （四）提请委务会审议规章草案； （五）办理规章公布与备案事宜； （六）起草或者组织起草规章解释、修改、废止的草案或者意见； （七）组织开展立法后评估； （八）编辑证券期货法规汇编。"},{"i":7,"n":"第七条","txt":"中国证监会每年年初制定年度规章制定工作计划。"},{"i":8,"n":"第八条","txt":"中国证监会各部门认为需要制定规章的，应当向法制机构报送制定规章的立项申请。 法制机构可以向社会公开征集规章制定项目建议。"},{"i":9,"n":"第九条","txt":"法制机构应当对立项申请和公开征集的规章制定项目建议进行评估论证，按照突出重点、统筹兼顾、切实可行、保证质量的原则，拟订中国证监会年度规章制定工作计划。 年度规章制定工作计划经批准后向社会公布。"},{"i":10,"n":"第十条","txt":"在年度规章制定工作计划执行过程中，中国证监会各部门可以根据实际工作需要提出调整建议，对拟增加的规章项目应当进行补充论证，并向法制机构报送立项申请。法制机构应当对立项申请进行审核，报中国证监会主要负责人批准后纳入年度规章制定工作计划。"},{"i":11,"n":"第十一条","txt":"中国证监会各部门负责其职责范围内的规章起草工作；规章涉及两个或者两个以上部门职责的，由中国证监会负责人指定主要起草部门；重要的或者综合性的规章，可以由法制机构起草或者组织成立专门的工作小组负责起草。"},{"i":12,"n":"第十二条","txt":"起草部门应当按照年度规章制定工作计划完成起草任务，需要延期的，应当经中国证监会负责人批准。法制机构应当督促起草部门执行年度规章制定工作计划。"},{"i":13,"n":"第十三条","txt":"起草部门可以邀请中国证监会派出机构（以下简称派出机构）和证券期货交易场所、证券期货市场行业协会、证券登记结算机构等全国性证券期货市场行业组织（以下简称证券期货市场行业组织）的公职律师等法制工作人员，以及有关专家、单位参与起草工作。 起草部门拟委托有关专家、单位起草规章草案的，应当商法制机构后报中国证监会负责人批准。未经批准，不得将起草工作委托给其他单位或者个人。 起草部门、参与或者接受委托起草规章的有关人员、单位应当遵守保密等制度。"},{"i":14,"n":"第十四条","txt":"起草部门应当深入调查研究，总结实践经验，广泛听取有关机关、组织和公民的意见。听取意见可以采取书面征求意见、座谈会、论证会、听证会等多种形式。 起草部门应当收集国内外的相关立法资料；开展立法调研的，应当制作调研报告；采取各种形式听取意见的，应当制作相应的听取意见情况报告。"},{"i":15,"n":"第十五条","txt":"规章内容涉及国务院其他部门的职责或者与其关系紧密的，应当征求国务院其他部门的意见。 规章内容不能取得一致意见的，起草部门应当在报送规章送审稿时说明情况和理由。"},{"i":16,"n":"第十六条","txt":"除依法需要保密的外，起草部门应当将规章草案及其说明等向社会公布，征求意见。向社会公开征求意见的期限一般不少于30日。 向社会公开征求意见，应当经中国证监会主要负责人批准，并将征求意见稿及其起草说明在中国政府法制信息网、中国证监会网站以及相关媒体等刊登。 起草规章，涉及《规章制定程序条例》第十六条规定的情形，起草部门应当进行论证咨询，需要听证的，起草部门应当举行听证会。起草部门举行听证会，应当经中国证监会负责人批准。"},{"i":17,"n":"第十七条","txt":"起草规章，应当注意与现行规章的衔接。新起草的规章拟取代现行规章的，应当在草案中写明拟废止的规章的名称、文号；新起草的规章对现行规章的部分内容予以修改的，应当在草案中写明所修改的规章的名称、文号、条款或者内容。"},{"i":18,"n":"第十八条","txt":"规章内容涉及市场主体经济活动的，起草部门应当按照有关规定开展公平竞争审查。"},{"i":19,"n":"第十九条","txt":"起草完毕后，起草部门应当制作下列材料并移送审查： （一）规章送审稿； （二）规章送审稿的说明，包括制定规章的必要性、规定的主要制度、有关方面的意见及其协调处理情况等； （三）其他有关材料，包括所规范领域的实际情况和相关数据、实践中存在的主要问题、汇总的意见、调研报告、公开征求意见报告、座谈会报告、论证会报告、听证会报告、国内外有关立法资料等。 移送审查的规章送审稿，应当由起草部门主要负责人签署；几个起草部门共同起草的规章送审稿，应当由该几个起草部门主要负责人共同签署。"},{"i":20,"n":"第二十条","txt":"规章送审稿由法制机构负责统一审查。法制机构除依照《规章制定程序条例》第十九条的有关规定对规章送审稿进行审查外，还要重点审查以下内容： （一）是否与上位法抵触； （二）是否与金融监管政策一致； （三）是否与现行证券期货法制体系协调、衔接； （四）是否符合立法程序要求； （五）是否符合立法技术规范； （六）需要审查的其他内容。"},{"i":21,"n":"第二十一条","txt":"规章送审稿有下列情形之一的，法制机构可以缓办或者退回起草部门： （一）制定规章的基本条件尚不成熟或者发生重大变化的； （二）未按照规定立项的； （三）未按照规定公开征求意见的； （四）中国证监会其他部门对规章送审稿规定的主要制度存在较大争议，起草部门未与其充分协商的； （五）规章涉及国务院其他部门职责或者与其关系紧密，起草部门未充分征求国务院有关部门意见的； （六）规章送审稿等材料不符合本规定第十九条规定的。"},{"i":22,"n":"第二十二条","txt":"法制机构应当就规章送审稿或者规章送审稿涉及的主要问题进行调查研究，听取有关方面意见。 法制机构可以将规章送审稿或者修改稿及其说明等向社会公布，征求意见。向社会公开征求意见的期限一般不少于30日。"},{"i":23,"n":"第二十三条","txt":"规章送审稿涉及《规章制定程序条例》第二十三条规定的情形，法制机构应当进行论证咨询，起草部门在起草过程中未举行听证会的，法制机构经中国证监会负责人批准，可以举行听证会。"},{"i":24,"n":"第二十四条","txt":"有关机构或者部门对规章送审稿涉及的主要措施、管理体制、权限分工等问题有不同意见的，法制机构应当组织进行论证研究。对有较大争议的重要立法事项，法制机构可以委托有关专家、教学科研单位、社会组织进行评估。"},{"i":25,"n":"第二十五条","txt":"法制机构应当认真研究各方面的意见，与起草部门协商后对规章送审稿进行修改，形成规章草案及其说明，提请委务会审议。"},{"i":26,"n":"第二十六条","txt":"委务会审议决定规章的发布和实施。 委务会审议规章草案时，由法制机构作审查意见说明；起草部门就起草情况等进行汇报。 法制机构应当根据委务会的审议意见对规章草案进行修改，形成规章草案修改稿。规章草案修改稿会签起草部门后，报请中国证监会主席签署，以中国证监会令的形式公布。"},{"i":27,"n":"第二十七条","txt":"需要与国务院其他部门联合制定规章的，规章草案应经相关部门依法履行决策程序；规章草案经中国证监会主席签署后，送国务院其他部门签署，以中国证监会令的形式公布。 国务院其他部门需要与中国证监会联合制定规章的，法制机构或者归口业务部门参照本规定第三章、第四章、第五章的规定，办理起草、审查、提请审议、公布等事宜。"},{"i":28,"n":"第二十八条","txt":"规章签署公布后，应当在中国政府法制信息网、中国证监会网站以及相关媒体上公开规章内容及立法说明等。"},{"i":29,"n":"第二十九条","txt":"规章应当明确规定实施日期。规章应当自公布之日起30日后施行。但是，可能严重影响证券期货市场稳定或者公布后不立即施行将有碍规章施行的，经委务会审议通过，可以自公布之日起施行。 法制机构根据上述规定以及主席签署命令的时间，会商起草部门，确定规章实施日期。"},{"i":30,"n":"第三十条","txt":"规章备案事宜，由法制机构负责，依照立法法和《法规规章备案条例》的规定办理。"},{"i":31,"n":"第三十一条","txt":"规章的解释权属于中国证监会。 规章有下列情形之一的，由中国证监会解释： （一）规章的规定需要进一步明确具体含义的； （二）规章制定后出现新的情况，需要明确适用规章依据的。 规章的解释同规章具有同等效力。"},{"i":32,"n":"第三十二条","txt":"中国证监会各部门对其职责范围内的规章可以向法制机构提出解释的建议。法制机构可以根据有关部门的建议，起草规章解释草案，按程序报请批准后，以证券期货法律适用意见形式公布。 中国证监会各部门可以起草规章解释草案，法制机构参照规章送审稿审查程序提出意见，按程序报请批准后，以证券期货法律适用意见形式公布。"},{"i":33,"n":"第三十三条","txt":"现行规章存在下列情形之一的，应当予以修改： （一）部分内容不适应全面深化改革和经济社会发展要求； （二）因上位法的修改需要作相应修改； （三）因国家政策发生变化，有必要进行相应修改； （四）两件以上的规章对同一事项的规定相互抵触； （五）其他情形。 规章的修改程序适用本规定的有关规定。中国证监会各部门对其职责范围内的规章可以向法制机构提出修改的建议。法制机构可以根据有关部门的建议，起草修正案草案，提请委务会审议通过后，以中国证监会令的形式公布。"},{"i":34,"n":"第三十四条","txt":"现行规章存在下列情形之一的，应当予以废止： （一）不适应全面深化改革和经济社会发展要求； （二）因上位法的废止或者修改而失去立法依据； （三）所规范的事项已由新的法律、行政法规予以规范； （四）所规范的事项已由新的规章予以规范； （五）所规范的事项已不存在或者已执行完毕，规章无继续存在的必要； （六）其他情形。 中国证监会各部门对其职责范围内的规章可以向法制机构提出废止的建议。法制机构可以根据有关部门的建议，提出废止的请示，提请委务会审议通过后，以公告形式公布。"},{"i":35,"n":"第三十五条","txt":"中国证监会建立立法信息及时反馈制度。中国证监会各部门以及派出机构、证券期货市场行业组织，在适用现行证券期货法律、行政法规、规章时，发现需要修改、解释的，可以及时向法制机构报告。 中国证监会可以对有关规章或者规章中的有关规定进行立法后评估，并把评估结果作为修改、废止有关规章的重要参考。"},{"i":36,"n":"第三十六条","txt":"中国证监会在每年第一季度对上一年度中国证监会公布的规章和规章以外的其他规范性文件（以下简称规范性文件）进行清理，并及时公布清理结果。"},{"i":37,"n":"第三十七条","txt":"法制机构依照《法规汇编编辑出版管理规定》的规定，负责编辑证券期货法规汇编。证券期货法规汇编的内容包括： （一）全国人民代表大会及其常务委员会审议通过的涉及中国证监会职责的法律、决议、决定和命令等； （二）国务院公布的涉及中国证监会职责的行政法规、决定和命令等； （三）中国证监会公布的规章和规范性文件； （四）司法部门公布的涉及中国证监会职责的司法解释等； （五）国务院有关部门公布的涉及中国证监会职责的规章和规范性文件； （六）其他文件。 证券期货法规汇编编辑完成后，交有关专业出版社出版。"},{"i":38,"n":"第三十八条","txt":"规章需要翻译正式英文译本的，由起草部门或者法制机构向委务会提出建议，由委务会作出决定。 委务会作出翻译规章决定的，由法制机构组织翻译、审定，起草部门和中国证监会国际合作部门予以协助。在翻译和审定工作中，法制机构可以聘请相关专业组织或者人员予以协助。"},{"i":39,"n":"第三十九条","txt":"中国证监会向国务院提出有关法律、行政法规的立法建议，报送法律、行政法规的立法规划、计划项目建议，由法制机构负责办理。"},{"i":40,"n":"第四十条","txt":"证券期货市场行业组织制定或者修改章程、业务规则等文件，应当依照《中华人民共和国证券法》《中华人民共和国证券投资基金法》《期货交易管理条例》和中国证监会的规定，报中国证监会批准、备案。"},{"i":41,"n":"第四十一条","txt":"本规定自2020年4月13日起施行。2008年10月21日发布的《证券期货规章制定程序规定》（证监会令第59号）同时废止。"}],"zhengquanqihuoweifaxingweixingzhengchufabanfa":[{"i":1,"n":"第一条","txt":"为了规范中国证券监督管理委员会（以下简称中国证监会）及其派出机构行政处罚的实施，维护证券期货市场秩序，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国证券法》《中华人民共和国证券投资基金法》《期货交易管理条例》等法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中国证监会依法对全国证券期货市场实行集中统一监督管理。中国证监会派出机构按照授权，依法履行行政处罚职责。"},{"i":3,"n":"第三条","txt":"自然人、法人或者其他组织违反证券期货法律、法规和规章规定，应当给予行政处罚的，中国证监会及其派出机构依照有关法律、法规、规章和本办法规定的程序实施。"},{"i":4,"n":"第四条","txt":"中国证监会及其派出机构实施行政处罚，遵循公开、公平、公正、效率和审慎监管原则，依法、全面、客观地调查、收集有关证据。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构作出的行政处罚决定，应当事实清楚、证据确凿、依据正确、程序合法、处罚适当。"},{"i":6,"n":"第六条","txt":"中国证监会及其派出机构发现自然人、法人或者其他组织涉嫌违反证券期货法律、法规和规章，符合下列条件，且不存在依法不予行政处罚等情形的，应当立案： （一）有明确的违法行为主体； （二）有证明违法事实的证据； （三）法律、法规、规章规定有明确的行政处罚法律责任； （四）尚未超过二年行政处罚时效。涉及金融安全且有危害后果的，尚未超过五年行政处罚时效。"},{"i":7,"n":"第七条","txt":"中国证监会及其派出机构通过文字记录等形式对行政处罚进行全过程记录，归档保存。根据需要，可以对容易引发争议的行政处罚过程进行音像记录，被调查的单位和个人不配合的，执法人员对相关情况进行文字说明。"},{"i":8,"n":"第八条","txt":"中国证监会及其派出机构执法人员必须忠于职守，依法办事，公正廉洁，不得滥用权力，或者利用职务便利牟取不正当利益；严格遵守保密规定，不得泄露案件查办信息，不得泄露所知悉的国家秘密、商业秘密和个人隐私；对于依法取得的个人信息，应当确保信息安全。"},{"i":9,"n":"第九条","txt":"中国证监会及其派出机构进行调查时，执法人员不得少于二人，并应当出示执法证和调查通知书等执法文书。执法人员少于二人或者未出示执法证和调查通知书等执法文书的，被调查的单位和个人有权拒绝。 执法人员应当在询问笔录或现场笔录等材料中对出示情况进行记录。"},{"i":10,"n":"第十条","txt":"被调查的单位和个人应当配合调查，如实回答询问，按要求提供有关文件和资料，不得拒绝、阻碍和隐瞒。"},{"i":11,"n":"第十一条","txt":"中国证监会及其派出机构调查、收集的证据包括： （一）书证； （二）物证； （三）视听资料； （四）电子数据； （五）证人证言； （六）当事人的陈述； （七）鉴定意见； （八）勘验笔录、现场笔录。 证据必须经查证属实，方可作为认定案件事实的根据。 以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":12,"n":"第十二条","txt":"书证原则上应当收集原件。收集原件确有困难的，可以收集与原件核对无误的复印件、照片、节录本。复印件、照片、节录本由证据提供人核对无误后注明与原件一致，同时由证据提供人逐页签名或者盖章。提供复印内容较多且连续编码的，可以在首尾页及骑缝处签名、盖章。"},{"i":13,"n":"第十三条","txt":"物证原则上应当收集原物。收集原物确有困难的，可以收集与原物核对无误的复制品或者证明该物证的照片、录像等其他证据。原物为数量较多的种类物的，可以收集其中一部分。收集复制品或者影像资料的，应当在现场笔录中说明取证情况。"},{"i":14,"n":"第十四条","txt":"视听资料原则上应当收集有关资料的原始载体。收集原始载体确有困难的，可以收集与原始载体核对无误的复制件，并以现场笔录或其他方式注明制作方法、制作时间、制作人和证明对象等。声音资料应当附有该录音内容的文字记录。"},{"i":15,"n":"第十五条","txt":"电子数据原则上应当收集有关数据的原始载体。收集电子数据原始载体确有困难的，可以制作复制件，并以现场笔录或其他方式记录参与人员、技术方法、收集对象、步骤和过程等。具备条件的，可以采取拍照或录像等方式记录取证过程。对于电子数据的关键内容，可以直接打印或者截屏打印，并由证据提供人签字确认。"},{"i":16,"n":"第十六条","txt":"当事人的陈述、证人证言可以通过询问笔录、书面说明等方式调取。询问应当分别单独进行。询问笔录应当由被询问人员及至少二名参与询问的执法人员逐页签名并注明日期；如有修改，应当由被询问人签字确认。 通过书面说明方式调取的，书面说明应当由提供人逐页签名或者盖章并注明日期。"},{"i":17,"n":"第十七条","txt":"对于涉众型违法行为，在能够充分证明基本违法事实的前提下，执法人员可以按一定比例收集和调取书证、证人证言等证据。"},{"i":18,"n":"第十八条","txt":"下列证据材料，经审查符合真实性、合法性及关联性要求的，可以作为行政处罚的证据： （一）中国证监会及其派出机构在立案前调查或者监督检查过程中依法取得的证据材料； （二）司法机关、纪检监察机关、其他行政机关等保存、公布、移交的证据材料； （三）中国证监会及其派出机构通过依法建立的跨境监督管理合作机制获取的证据材料； （四）其他符合真实性、合法性及关联性要求的证据材料。"},{"i":19,"n":"第十九条","txt":"中国证监会及其派出机构根据案情需要，可以委托下列单位和人员提供协助： （一）委托具有法定鉴定资质的鉴定机构对涉案相关事项进行鉴定，鉴定意见应有鉴定人签名和鉴定机构盖章； （二）委托会计师事务所、资产评估事务所、律师事务所等中介机构以及专家顾问提供专业支持； （三）委托证券期货交易场所、登记结算机构等检验、测算相关数据或提供与其职能有关的其他协助。"},{"i":20,"n":"第二十条","txt":"中国证监会及其派出机构可以依法要求当事人或与被调查事件有关的单位和个人，在指定的合理期限内，通过纸质、电子邮件、光盘等指定方式报送与被调查事件有关的文件和资料。"},{"i":21,"n":"第二十一条","txt":"中国证监会及其派出机构依法需要采取冻结、查封、扣押、限制证券买卖等措施的，按照《中华人民共和国行政强制法》等法律、法规以及中国证监会的有关规定办理。"},{"i":22,"n":"第二十二条","txt":"中国证监会及其派出机构依法需要采取封存、先行登记保存措施的，应当经单位负责人批准。 遇有紧急情况，需要立即采取上述措施的，执法人员应当在二十四小时内向单位负责人报告，并补办批准手续。单位负责人认为不应当采取的，应当立即解除。"},{"i":23,"n":"第二十三条","txt":"采取封存、先行登记保存措施的，应当当场清点，出具决定书或通知书，开列清单并制作现场笔录。 对于封存、先行登记保存的证据，中国证监会及其派出机构可以自行或采取委托第三方等其他适当方式保管，当事人和有关人员不得隐藏、转移、变卖或者毁损。"},{"i":24,"n":"第二十四条","txt":"对于先行登记保存的证据，应当在七日内采取下列措施： （一）根据情况及时采取记录、复制、拍照、录像、提取电子数据等证据保全措施； （二）需要检查、检验、鉴定、评估的，送交检查、检验、鉴定、评估； （三）依据有关法律、法规可以采取查封、扣押、封存等措施的，作出查封、扣押、封存等决定； （四）违法事实不成立，或者违法事实成立但依法不应予以查封、扣押、封存的，决定解除先行登记保存措施。"},{"i":25,"n":"第二十五条","txt":"执法人员制作现场笔录的，应当载明时间、地点和事件等内容，并由执法人员和当事人等在场有关人员签名或者盖章。 当事人或者有关人员拒绝或不能在现场笔录、询问笔录、证据材料上签名、盖章的，执法人员应当在现场笔录、询问笔录、证据材料上说明或以录音录像等形式加以证明。必要时，执法人员可以请无利害关系第三方作为见证人签名。"},{"i":26,"n":"第二十六条","txt":"实施行政处罚过程中，有下列情形之一的，中国证监会可以通知出境入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位的主管人员和其他直接责任人员出境： （一）相关人员涉嫌违法行为情节严重、影响恶劣，或存在本办法第三十八条规定的行为，出境后可能对行政处罚的实施产生不利影响的； （二）相关人员涉嫌构成犯罪，可能承担刑事责任的； （三）存在有必要阻止出境的其他情形的。 阻止出境的期限按照出境入境管理机关的规定办理，需要延长期限的，应当通知出境入境管理机关。到期不通知的，由出境入境管理机关按规定解除阻止出境措施。 经调查、审理，被阻止出境人员不属于涉嫌违法人员或责任人员，或者中国证监会认为没有必要继续阻止出境的，应当通知出境入境管理机关依法解除对相关人员的阻止出境措施。"},{"i":27,"n":"第二十七条","txt":"案件调查终结，中国证监会及其派出机构根据案件不同情况，依法报单位负责人批准后，分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，依法移送司法机关。 对情节复杂或者重大违法行为给予行政处罚，中国证监会及其派出机构负责人应当集体讨论决定。"},{"i":28,"n":"第二十八条","txt":"中国证监会设立行政处罚委员会，对按照规定向其移交的案件提出审理意见、依法进行法制审核，报单位负责人批准后作出处理决定。 中国证监会派出机构负责人作出行政处罚的决定之前，依法由从事行政处罚决定法制审核的人员进行法制审核。"},{"i":29,"n":"第二十九条","txt":"中国证监会及其派出机构在行政处罚过程中发现违法行为涉嫌犯罪的，应当依法、及时将案件移送司法机关处理。 司法机关依法不追究刑事责任或者免予刑事处罚，但应当给予行政处罚的，中国证监会及其派出机构依法作出行政处罚决定。"},{"i":30,"n":"第三十条","txt":"行政处罚决定作出前，中国证监会及其派出机构应当向当事人送达行政处罚事先告知书，载明下列内容: （一）拟作出行政处罚的事实、理由和依据； （二）拟作出的行政处罚决定； （三）当事人依法享有陈述和申辩的权利； （四）符合《中国证券监督管理委员会行政处罚听证规则》所规定条件的，当事人享有要求听证的权利。"},{"i":31,"n":"第三十一条","txt":"当事人要求听证的，按照听证相关规定办理。 当事人要求陈述、申辩但未要求听证的，应当在行政处罚事先告知书送达后五日内提出，并在行政处罚事先告知书送达后十五日内提出陈述、申辩意见。当事人书面申请延长陈述、申辩期限的，经同意后可以延期。 当事人存在下列情形的，视为明确放弃陈述、申辩、听证权利： （一）当事人未按前两款规定提出听证要求或陈述、申辩要求的； （二）要求听证的当事人未按听证通知书载明的时间、地点参加听证，截至听证当日也未提出陈述、申辩意见的； （三）要求陈述、申辩但未要求听证的当事人，未在规定时间内提出陈述、申辩意见的。"},{"i":32,"n":"第三十二条","txt":"中国证监会及其派出机构对已经送达的行政处罚事先告知书认定的主要事实、理由、依据或者拟处罚决定作出调整的，应当重新向当事人送达行政处罚事先告知书，但作出对当事人有利变更的除外。"},{"i":33,"n":"第三十三条","txt":"当事人收到行政处罚事先告知书后，可以申请查阅涉及本人行政处罚事项的证据，但涉及国家秘密、他人的商业秘密和个人隐私的内容除外。"},{"i":34,"n":"第三十四条","txt":"证券期货违法行为的违法所得，是指通过违法行为所获利益或者避免的损失，应根据违法行为的不同性质予以认定，具体规则由中国证监会另行制定。"},{"i":35,"n":"第三十五条","txt":"中国证监会及其派出机构应当自立案之日起一年内作出行政处罚决定。有特殊情况需要延长的，应当报经单位负责人批准，每次延长期限不得超过六个月。 中国证监会及其派出机构作出行政处罚决定的，应当依照《中华人民共和国行政处罚法》的规定，在七日内将行政处罚决定书送达当事人，并按照政府信息公开等规定予以公开。"},{"i":36,"n":"第三十六条","txt":"行政执法文书可以采取《中华人民共和国民事诉讼法》规定的方式送达当事人。当事人同意的，可以采用传真、电子邮件等方式送达。"},{"i":37,"n":"第三十七条","txt":"申请适用行政执法当事人承诺制度的，按照有关规定办理。"},{"i":38,"n":"第三十八条","txt":"有下列拒绝、阻碍执法情形之一的，按照《证券法》第二百一十八条的规定追究责任： （一）殴打、围攻、推搡、抓挠、威胁、侮辱、谩骂执法人员的； （二）限制执法人员人身自由的； （三）抢夺、毁损执法装备及执法人员个人物品的； （四）抢夺、毁损、伪造、隐藏证据材料的； （五）不按要求报送文件资料，且无正当理由的； （六）转移、变卖、毁损、隐藏被依法冻结、查封、扣押、封存的资金或涉案财产的； （七）躲避推脱、拒不接受、无故离开等不配合执法人员询问，或在询问时故意提供虚假陈述、谎报案情的； （八）其他不履行配合义务的情形。"},{"i":39,"n":"第三十九条","txt":"本办法所称派出机构，是指中国证监会派驻各省、自治区、直辖市和计划单列市监管局。 中国证监会稽查总队、证券监管专员办事处根据职责或授权对证券期货违法行为进行立案、调查的，依照本办法执行。"},{"i":40,"n":"第四十条","txt":"行政处罚相关信息记入证券期货市场诚信档案数据库。"},{"i":41,"n":"第四十一条","txt":"本办法自公布之日起施行。"}],"zhengquandengjijiesuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范证券登记结算行为，保护投资者的合法权益，维护证券登记结算秩序，防范证券登记结算风险，保障证券市场安全高效运行，根据《证券法》、《公司法》等法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在证券交易所上市的股票、债券、证券投资基金份额等证券及证券衍生品种（以下统称证券）的登记结算，适用本办法。 非上市证券的登记结算业务，参照本办法执行。 境内上市外资股的登记结算业务，法律、行政法规、中国证券监督管理委员会（以下简称中国证监会）另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"证券登记结算活动必须实行公开、公平、公正、安全、高效的原则。"},{"i":4,"n":"第四条","txt":"证券登记结算机构是为证券交易提供集中登记、存管与结算服务，不以营利为目的的法人。 证券登记结算业务采取全国集中统一的运营方式，由证券登记结算机构依法集中统一办理。 证券登记结算机构实行行业自律管理。"},{"i":5,"n":"第五条","txt":"证券登记结算活动必须遵守法律、行政法规、中国证监会的规定以及证券登记结算机构依法制定的业务规则。"},{"i":6,"n":"第六条","txt":"中国证监会依法对证券登记结算机构及证券登记结算活动进行监督管理。"},{"i":7,"n":"第七条","txt":"证券登记结算机构的设立和解散，必须经中国证监会批准。"},{"i":8,"n":"第八条","txt":"证券登记结算机构履行下列职能： （一）证券账户、结算账户的设立和管理； （二）证券的存管和过户； （三）证券持有人名册登记及权益登记； （四）证券和资金的清算交收及相关管理； （五）受发行人的委托派发证券权益； （六）依法提供与证券登记结算业务有关的查询、信息、咨询和培训服务； （七）中国证监会批准的其他业务。"},{"i":9,"n":"第九条","txt":"证券登记结算机构不得从事下列活动： （一）与证券登记结算业务无关的投资； （二）购置非自用不动产； （三）在本办法第六十五条、第六十六条规定之外买卖证券； （四）法律、行政法规和中国证监会禁止的其他行为。"},{"i":10,"n":"第十条","txt":"证券登记结算机构的下列事项，应当报中国证监会批准： （一）章程、业务规则的制定和修改； （二）董事长、副董事长、总经理和副总经理的任免； （三）依法应当报中国证监会批准的其他事项。 前款第（一）项中所称的业务规则，是指证券登记结算机构的证券账户管理、证券登记、证券托管与存管、证券结算、结算参与人管理等与证券登记结算业务有关的业务规则。"},{"i":11,"n":"第十一条","txt":"证券登记结算机构的下列事项和文件，应当向中国证监会报告： （一）业务实施细则； （二）制定或修改业务管理制度、业务复原计划、紧急应对程序； （三）办理新的证券品种的登记结算业务，变更登记结算业务模式； （四）结算参与人和结算银行资格的取得和丧失等变动情况； （五）发现重大业务风险和技术风险，发现重大违法违规行为，或涉及重大诉讼； （六）任免分公司总经理、公司总经理助理、公司部门负责人； （七）有关经营情况和国家有关规定执行情况的年度工作报告； （八）经会计师事务所审计的年度财务报告，财务预决算方案和重大开支项目，聘请或更换会计师事务所； （九）与证券交易所签订的主要业务合作协议，与证券发行人、结算参与人和结算银行签订的各项业务协议的样本格式； （十）重大国际合作与交流活动、涉港澳台重大事务； （十一）与证券登记结算有关的主要收费项目和标准的制定或调整； （十二）中国证监会要求报告的其他"},{"i":12,"n":"第十二条","txt":"证券登记结算机构应当妥善保存登记、存管和结算的原始凭证及有关文件和资料。其保存期限不得少于20年。"},{"i":13,"n":"第十三条","txt":"证券登记结算机构对其所编制的与证券登记结算业务有关的数据和资料进行专属管理；未经证券登记结算机构同意，任何组织和个人不得将其专属管理的数据和资料用于商业目的。"},{"i":14,"n":"第十四条","txt":"证券登记结算机构及其工作人员依法对与证券登记结算业务有关的数据和资料负有保密义务。 对与证券登记结算业务有关的数据和资料，证券登记结算机构应当拒绝查询，但有下列情形之一的，证券登记结算机构应当依法办理： （一）证券持有人查询其本人的有关证券资料； （二）证券发行人查询其证券持有人名册及有关资料； （三）证券交易所、中国金融期货交易所依法履行职责要求证券登记结算机构提供相关数据和资料； （四）人民法院、人民检察院、公安机关和中国证监会依照法定的条件和程序进行查询和取证。 证券登记结算机构应当采取有效措施，方便证券持有人查询其本人证券的持有记录。"},{"i":15,"n":"第十五条","txt":"证券登记结算机构应当公开业务规则、与证券登记结算业务有关的主要收费项目和标准。 证券登记结算机构制定或者变更业务规则、调整证券登记结算主要收费项目和标准等，应当征求相关市场参与人的意见。"},{"i":16,"n":"第十六条","txt":"证券登记结算机构工作人员必须忠于职守、依法办事、不得利用职务便利谋取不正当利益，不得泄露所知悉的有关单位和个人的商业秘密。 证券登记结算机构违反《证券法》及本办法规定的，中国证监会依法予以行政处罚；对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":17,"n":"第十七条","txt":"投资者通过证券账户持有证券，证券账户用于记录投资者持有证券的余额及其变动情况。"},{"i":18,"n":"第十八条","txt":"证券应当记录在证券持有人本人的证券账户内，但依据法律、行政法规和中国证监会的规定，证券记录在名义持有人证券账户内的，从其规定。 证券登记结算机构为依法履行职责，可以要求名义持有人提供其名下证券权益拥有人的相关资料。"},{"i":19,"n":"第十九条","txt":"投资者开立证券账户应当向证券登记结算机构提出申请。 前款所称投资者包括中国公民、中国法人、中国合伙企业、符合规定的外国人及法律、行政法规、中国证监会规章规定的其他投资者。 外国人申请开立证券账户的具体办法，由证券登记结算机构制定，报中国证监会批准。 投资者申请开立证券账户应当保证其提交的开户资料真实、准确、完整。"},{"i":20,"n":"第二十条","txt":"证券登记结算机构可以直接为投资者开立证券账户，也可以委托证券公司代为办理。 证券登记结算机构为投资者开立证券账户，应当遵循方便投资者和优化配置账户资源的原则。"},{"i":21,"n":"第二十一条","txt":"证券公司代理开立证券账户，应当向证券登记结算机构申请取得开户代理资格。 证券公司代理开立证券账户，应当根据证券登记结算机构的业务规则，对投资者提供的有效身份证明文件原件及其他开户资料的真实性、准确性、完整性进行审核，并应当妥善保管相关开户资料，保管期限不得少于20 年。"},{"i":22,"n":"第二十二条","txt":"投资者不得将本人的证券账户提供给他人使用。"},{"i":23,"n":"第二十三条","txt":"证券登记结算机构应当根据业务规则，对开户代理机构开立证券账户的活动进行监督。开户代理机构违反业务规则的，证券登记结算机构可以根据业务规则暂停、取消其开户代理资格，并提请中国证监会按照相关规定采取暂停或撤销其相关证券业务许可；对直接负责的主管人员和其他直接责任人员，单处或并处警告、罚款、撤销任职资格或证券从业资格等处罚措施。"},{"i":24,"n":"第二十四条","txt":"证券公司应当掌握其客户的资料及资信状况，并对其客户证券账户的使用情况进行监督。证券公司发现其客户在证券账户使用过程中存在违规行为的，应当按照证券登记结算机构的业务规则处理，并及时向证券登记结算机构和证券交易所报告。涉及法人以他人名义设立证券账户或者利用他人证券账户买卖证券的，还应当向中国证监会报告，由中国证监会依法予以处罚。"},{"i":25,"n":"第二十五条","txt":"投资者在证券账户开立和使用过程中存在违规行为的，证券登记结算机构应当依法对违规证券账户采取限制使用、注销等处置措施。"},{"i":26,"n":"第二十六条","txt":"上市证券的发行人，应当委托证券登记结算机构办理其所发行证券的登记业务。 证券登记结算机构应当与委托其办理证券登记业务的证券发行人签订证券登记及服务协议，明确双方的权利义务。 证券登记结算机构应当制定并公布证券登记及服务协议的范本。 证券登记结算机构可以根据政府债券主管部门的要求办理上市政府债券的登记业务。"},{"i":27,"n":"第二十七条","txt":"证券登记结算机构根据证券账户的记录，确认证券持有人持有证券的事实，办理证券持有人名册的登记。"},{"i":28,"n":"第二十八条","txt":"证券公开发行后，证券发行人应当向证券登记结算机构提交已发行证券的证券持有人名册及其他相关资料。证券登记结算机构据此办理证券持有人名册的初始登记。 证券发行人应当保证其所提交资料的合法、真实、准确、完整。证券登记结算机构不承担由于证券发行人原因导致证券持有人名册及其他相关资料有误而产生的损失和法律后果。"},{"i":29,"n":"第二十九条","txt":"证券在证券交易所上市交易的，证券登记结算机构应当根据证券交易的交收结果办理证券持有人名册的变更登记。 证券以协议转让、继承、捐赠、强制执行、行政划拨等方式转让的，证券登记结算机构根据业务规则变更相关证券账户的余额，并相应办理证券持有人名册的变更登记。 证券因质押、锁定、冻结等原因导致其持有人权利受到限制的，证券登记结算机构应当在证券持有人名册上加以标记。"},{"i":30,"n":"第三十条","txt":"证券登记结算机构应当保证证券持有人名册和登记过户记录真实、准确、完整，不得隐匿、伪造或者毁损。"},{"i":31,"n":"第三十一条","txt":"证券登记结算机构应当按照业务规则和协议定期向证券发行人发送其证券持有人名册及有关资料。"},{"i":32,"n":"第三十二条","txt":"证券发行人申请办理权益分派等代理服务的，应当按照业务规则和协议向证券登记结算机构提交有关资料并支付款项。 证券发行人未及时履行上述义务的，证券登记结算机构有权推迟或不予办理，证券发行人应当及时发布公告说明有关情况。"},{"i":33,"n":"第三十三条","txt":"证券发行人或者其清算组等终止证券登记及相关服务协议的，证券登记结算机构应当依法向其交付证券持有人名册及其他登记资料。"},{"i":34,"n":"第三十四条","txt":"投资者应当委托证券公司托管其持有的证券，证券公司应当将其自有证券和所托管的客户证券交由证券登记结算机构存管，但法律、行政法规和中国证监会另有规定的除外。"},{"i":35,"n":"第三十五条","txt":"证券登记结算机构为证券公司设立客户证券总账和自有证券总账，用以统计证券公司交存的客户证券和自有证券。 证券公司应当委托证券登记结算机构维护其客户及自有证券账户，但法律、行政法规和中国证监会另有规定的除外。"},{"i":36,"n":"第三十六条","txt":"投资者买卖证券，应当与证券公司签订证券交易、托管与结算协议。 证券登记结算机构应当制定和公布证券交易、托管与结算协议中与证券登记结算业务有关的必备条款。必备条款应当包括但不限于以下内容： （一）证券公司根据客户的委托，按照证券交易规则提出交易申报，根据成交结果完成其与客户的证券和资金的交收，并承担相应的交收责任；客户应当同意集中交易结束后,由证券公司委托证券登记结算机构办理其证券账户与证券公司证券交收账户之间的证券划付； （二）实行质押式回购交易的，投资者和证券公司应当按照业务规则的规定向证券登记结算机构提交用于回购的质押券。投资者和证券公司之间债权债务关系不影响证券登记结算机构按照业务规则对证券公司提交的质押券行使质押权； （三）客户出现资金交收违约时，证券公司可以委托证券登记结算机构将客户净买入证券划付到其证券处置账户内，并要求客户在约定期限内补足资金。客户出现证券交收违约时，证券"},{"i":37,"n":"第三十七条","txt":"证券公司应当将其与客户之间建立、变更和终止证券托管关系的事项报送证券登记结算机构。 证券登记结算机构应当对上述事项加以记录。"},{"i":38,"n":"第三十八条","txt":"客户要求证券公司将其持有证券转由其他证券公司托管的，相关证券公司应当依据证券交易所及证券登记结算机构有关业务规则予以办理，不得拒绝，但有关法律、行政法规和中国证监会另有规定的除外。"},{"i":39,"n":"第三十九条","txt":"证券公司应当采取有效措施，保证其托管的证券的安全，禁止挪用、盗卖。 证券登记结算机构应当采取有效措施，保证其存管的证券的安全，禁止挪用、盗卖。"},{"i":40,"n":"第四十条","txt":"证券的质押、锁定、冻结或扣划，由托管证券的证券公司和证券登记结算机构按照证券登记结算机构的相关规定办理。"},{"i":41,"n":"第四十一条","txt":"证券公司参与证券和资金的集中清算交收，应当向证券登记结算机构申请取得结算参与人资格，与证券登记结算机构签订结算协议，明确双方的权利义务。 没有取得结算参与人资格的证券公司，应当与结算参与人签订委托结算协议，委托结算参与人代其进行证券和资金的集中清算交收。 证券登记结算机构应当制定并公布结算协议和委托结算协议范本。"},{"i":42,"n":"第四十二条","txt":"证券登记结算机构应当选择符合条件的商业银行作为结算银行，办理资金划付业务。 结算银行的条件，由证券登记结算机构制定。"},{"i":43,"n":"第四十三条","txt":"证券和资金结算实行分级结算原则。证券登记结算机构负责办理证券登记结算机构与结算参与人之间的集中清算交收；结算参与人负责办理结算参与人与客户之间的清算交收。"},{"i":44,"n":"第四十四条","txt":"证券登记结算机构应当设立证券集中交收账户和资金集中交收账户，用以办理与结算参与人的证券和资金的集中清算交收。 结算参与人应当根据证券登记结算机构的规定，申请开立证券交收账户和资金交收账户用以办理证券和资金的交收。同时经营证券自营业务和经纪业务的结算参与人，应当申请开立自营证券、资金交收账户和客户证券、资金交收账户分别用以办理自营业务的证券、资金交收和经纪业务的证券、资金交收。"},{"i":45,"n":"第四十五条","txt":"证券登记结算机构采取多边净额结算方式的，应当根据业务规则作为结算参与人的共同对手方，按照货银对付的原则，以结算参与人为结算单位办理清算交收。"},{"i":46,"n":"第四十六条","txt":"证券登记结算机构与参与多边净额结算的结算参与人签订的结算协议应当包括下列内容： （一）对于结算参与人负责结算的证券交易合同，该合同双方结算参与人向对手方结算参与人收取证券或资金的权利，以及向对手方结算参与人支付资金或证券的义务一并转让给证券登记结算机构； （二）受让前项权利和义务后，证券登记结算机构享有原合同双方结算参与人对其对手方结算参与人的权利，并应履行原合同双方结算参与人对其对手方结算参与人的义务。"},{"i":47,"n":"第四十七条","txt":"证券登记结算机构进行多边净额清算时，应当将结算参与人的证券和资金轧差计算出应收应付净额，并在清算结束后将清算结果及时通知结算参与人。 证券登记结算机构采取其他结算方式的，应当按照相关业务规则进行清算。"},{"i":48,"n":"第四十八条","txt":"集中交收前，结算参与人应当向客户收取其应付的证券和资金，并在结算参与人证券交收账户、结算参与人资金交收账户留存足额证券和资金。 结算参与人与客户之间的证券划付，应当委托证券登记结算机构代为办理。"},{"i":49,"n":"第四十九条","txt":"集中交收过程中，证券登记结算机构应当在交收时点，向结算参与人收取其应付的资金和证券，同时交付其应收的证券和资金。交收完成后不可撤销。 结算参与人未能足额履行应付证券或资金交收义务的，不能取得相应的资金或证券。 对于同时经营自营业务以及经纪业务或资产管理业务的结算参与人，如果其客户资金交收账户资金不足的，证券登记结算机构可以动用该结算参与人自营资金交收账户内的资金完成交收。"},{"i":50,"n":"第五十条","txt":"集中交收后，结算参与人应当向客户交付其应收的证券和资金。 结算参与人与客户之间的证券划付，应当委托证券登记结算机构代为办理。"},{"i":51,"n":"第五十一条","txt":"证券登记结算机构应当在结算业务规则中对结算参与人与证券登记结算机构之间的证券和资金的集中交收以及结算参与人与客户之间的证券和资金的交收期限分别做出规定。 结算参与人应当在规定的交收期限内完成证券和资金的交收。"},{"i":52,"n":"第五十二条","txt":"因证券登记结算机构的原因导致清算结果有误的，结算参与人在履行交收责任后可以要求证券登记结算机构予以纠正，并承担结算参与人遭受的直接损失。"},{"i":53,"n":"第五十三条","txt":"证券登记结算机构应当采取下列措施，加强证券登记结算业务的风险防范和控制： （一）制定完善的风险防范制度和内部控制制度； （二）建立完善的技术系统，制定由结算参与人共同遵守的技术标准和规范； （三）建立完善的结算参与人和结算银行准入标准和风险评估体系； （四）对结算数据和技术系统进行备份，制定业务紧急应变程序和操作流程。"},{"i":54,"n":"第五十四条","txt":"证券登记结算机构应当与证券交易所相互配合，建立证券市场系统性风险的防范制度。 证券登记结算机构应当与证券交易所签订业务合作协议，明确双方的权利义务。"},{"i":55,"n":"第五十五条","txt":"证券登记结算机构应当按照结算风险共担的原则，组织结算参与人建立证券结算互保金，用于在结算参与人交收违约时保障交收的连续进行。 证券结算互保金的筹集、使用、管理和补缴办法，由证券登记结算机构在业务规则中规定。"},{"i":56,"n":"第五十六条","txt":"证券登记结算机构可以视结算参与人的风险状况，采取要求结算参与人提供交收担保等风险控制措施。 结算参与人提供交收担保的具体标准，由证券登记结算机构根据结算参与人的风险程度确定和调整。 证券登记结算机构应当将结算参与人提交的交收担保物与其自有资产隔离，严格按结算参与人分户管理，不得挪用。"},{"i":57,"n":"第五十七条","txt":"结算参与人可以在其资金交收账户内，存放证券结算备付金用于完成交收。 证券登记结算机构应当将结算参与人存放的结算备付金与其自有资金隔离，严格按结算参与人分户管理，不得挪用。"},{"i":58,"n":"第五十八条","txt":"证券登记结算机构应当对质押式回购实行质押品保管库制度，将结算参与人提交的用于融资回购担保的质押券转移到质押品保管库。"},{"i":59,"n":"第五十九条","txt":"证券登记结算机构收取的下列资金和证券，只能按业务规则用于已成交的证券交易的清算交收，不得被强制执行： （一）证券登记结算机构收取的证券结算风险基金、证券结算互保金，以及交收担保物、回购质押券等用于担保交收的资金和证券； （二）证券登记结算机构根据本办法设立的证券集中交收账户、资金集中交收账户、专用清偿账户内的证券和资金以及根据业务规则设立的其他专用交收账户内的证券和资金； （三）结算参与人证券交收账户、结算参与人证券处置账户等结算账户内的证券以及结算参与人资金交收账户内根据成交结果确定的应付资金； （四）根据成交结果确定的投资者进入交收程序的应付证券和资金； （五）证券登记结算机构在银行开设的结算备付金等专用存款账户、新股发行验资专户内的资金，以及发行人拟向投资者派发的债息、股息和红利等。"},{"i":60,"n":"第六十条","txt":"证券登记结算机构可以根据组织管理证券登记结算业务的需要，按照有关规定申请授信额度，或将专用清偿账户中的证券用于申请质押贷款，以保障证券登记结算活动的持续正常进行。"},{"i":61,"n":"第六十一条","txt":"证券登记结算机构应当设立专用清偿账户，用于在结算参与人发生违约时存放暂不交付或扣划的证券和资金。"},{"i":62,"n":"第六十二条","txt":"结算参与人发生资金交收违约时，应当按照以下程序办理： （一）违约结算参与人应当向证券登记结算机构发送证券交收划付指令，在该结算参与人当日全部应收证券中指定相当于已交付资金等额的证券种类、数量及对应的证券账户，由证券登记结算机构交付结算参与人；并指定相当于不足金额的证券种类和数量，由证券登记结算机构暂不交付给结算参与人。 （二）证券登记结算机构在规定期限内收到有效证券交收划付指令的，应当依据结算业务规则将相应证券交付结算参与人，将暂不交付的证券划入专用清偿账户，并通知该结算参与人在规定的期限内补足资金或提交交收担保。 证券登记结算机构在规定期限内未收到有效证券交收划付指令的，属于结算参与人重大交收违约情形,证券登记结算机构应当将拟交付给结算参与人的全部证券划入专用清偿账户，暂不交付结算参与人，并通知结算参与人在规定的期限内补足资金或提交交收担保。 暂不交付的证券、补充资金或交收担保不足以"},{"i":63,"n":"第六十三条","txt":"结算参与人发生资金交收违约的，证券登记结算机构应当按照下列顺序动用资金，完成与对手方结算参与人的资金交收： （一）违约结算参与人的担保物中的现金部分； （二）证券结算互保金中违约结算参与人交纳的部分； （三）证券结算互保金中其他结算参与人交纳的部分； （四）证券结算风险基金； （五）其他资金。"},{"i":64,"n":"第六十四条","txt":"结算参与人发生证券交收违约时，证券登记结算机构有权暂不交付相当于违约金额的应收资金。 证券登记结算机构应当将暂不划付的资金划入专用清偿账户，并通知该结算参与人。结算参与人应当在规定的期限内补足证券，或者提供证券登记结算机构认可的担保。"},{"i":65,"n":"第六十五条","txt":"结算参与人发生证券交收违约的，证券登记结算机构可以动用下列证券，完成与对手方结算参与人的证券交收： （一）违约结算参与人提交的用以冲抵的相同证券； （二）委托证券公司以专用清偿账户中的资金买入的相同证券； （三）其他来源的相同证券。"},{"i":66,"n":"第六十六条","txt":"违约结算参与人未在规定的期间内补足资金、证券的，证券登记结算机构可以处分违约结算参与人所提供的担保物、质押品保管库中的回购质押券、卖出专用清偿账户内的证券。 前款处置所得，用于补足违约结算参与人欠付的资金、证券和支付相关费用；有剩余的，应当归还该相关违约结算参与人；不足偿付的，证券登记结算机构应当向相关违约结算参与人追偿。 在规定期限内无法追偿的证券或资金，证券登记结算机构可以依法动用证券结算互保金和证券结算风险基金予以弥补。依法动用证券结算互保金和证券结算风险基金弥补损失后，证券登记结算机构应当继续向违约结算参与人追偿。"},{"i":67,"n":"第六十七条","txt":"结算参与人发生资金交收违约或证券交收违约的，证券登记结算机构可以按照有关规定收取违约金。证券登记结算机构收取的违约金应当计入证券结算风险基金。"},{"i":68,"n":"第六十八条","txt":"结算参与人发生重大交收违约情形的，证券登记结算机构可以按照以下程序办理： （一）暂停、终止办理其部分、全部结算业务，以及中止、撤销结算参与人资格，并提请证券交易所采取停止交易措施。 （二）提请中国证监会按照相关规定采取暂停或撤销其相关证券业务许可；对直接负责的主管人员和其他直接责任人员，单处或并处警告、罚款、撤销任职资格或证券从业资格的处罚措施。 证券登记结算机构提请证券交易所采取停止交易措施的具体办法由证券登记结算机构商证券交易所制订，报中国证监会批准。"},{"i":69,"n":"第六十九条","txt":"证券登记结算机构依法动用证券结算互保金和证券结算风险基金，以及对违约结算参与人采取前条规定的处置措施的，应当在证券登记结算机构年度报告中列示。"},{"i":70,"n":"第七十条","txt":"结算参与人可以根据证券登记结算机构的规定，向证券登记结算机构申请开立证券处置账户，用以存放暂不交付给客户的证券。"},{"i":71,"n":"第七十一条","txt":"结算参与人可以视客户的风险状况，采取包括要求客户提供交收担保在内的风险控制措施。 客户提供交收担保的具体标准，由结算参与人与客户在证券交易、托管与结算协议中明确。"},{"i":72,"n":"第七十二条","txt":"客户出现资金交收违约时，结算参与人可以发出指令，委托证券登记结算机构将客户净买入证券划付到其证券处置账户内，并要求客户在约定期限内补足资金。"},{"i":73,"n":"第七十三条","txt":"客户出现证券交收违约时，结算参与人可以将相当于证券交收违约金额的资金暂不划付给该客户。"},{"i":74,"n":"第七十四条","txt":"违约客户未在规定的期间内补足资金、证券的，结算参与人可以将证券处置账户内的相应证券卖出，或用暂不交付的资金补购相应证券。 前款处置所得，用于补足违约客户欠付的资金、证券和支付相关费用；有剩余的，应当归还该客户；尚有不足的，结算参与人有权继续向客户追偿。"},{"i":75,"n":"第七十五条","txt":"结算参与人未及时将客户应收资金支付给客户或未及时委托证券登记结算机构将客户应收证券从其证券交收账户划付到客户证券账户的，结算参与人应当对客户承担违约责任，给客户造成损失的，结算参与人应当承担对客户的赔偿责任。"},{"i":76,"n":"第七十六条","txt":"客户对结算参与人交收违约的，结算参与人不能因此拒绝履行对证券登记结算机构的交收义务，也不得影响已经完成和正在进行的证券和资金的集中交收及证券登记结算机构代为办理的证券划付。"},{"i":77,"n":"第七十七条","txt":"没有取得结算参与人资格的证券公司与其客户之间的结算权利义务关系，参照本办法执行。"},{"i":78,"n":"第七十八条","txt":"本办法下列用语的含义是： 登记，是指证券登记结算机构接受证券发行人的委托，通过设立和维护证券持有人名册确认证券持有人持有证券事实的行为。 托管，是指证券公司接受客户委托，代其保管证券并提供代收红利等权益维护服务的行为。 存管，是指证券登记结算机构接受证券公司委托，集中保管证券公司的客户证券和自有证券，并提供代收红利等权益维护服务的行为。 结算，是指清算和交收。 清算，是指按照确定的规则计算证券和资金的应收应付数额的行为。 交收，是指根据确定的清算结果，通过转移证券和资金履行相关债权债务的行为。 名义持有人，是指受他人指定并代表他人持有证券的机构。 结算参与人，是指经证券登记结算机构核准，有资格参与集中清算交收的证券公司或其他机构。 共同对手方，是指在结算过程中，同时作为所有买方和卖方的交收对手并保证交收顺利完成的主体。 货银对付，是指证券登记结算机构与结算参与人在交收过程中，当且仅当资"},{"i":79,"n":"第七十九条","txt":"证券公司以外的机构经中国证监会批准，可以接受证券登记结算机构委托为投资者开立证券账户、可以接受投资者委托托管其证券，或者申请成为结算参与人为客户办理证券和资金的清算交收，有关证券登记结算业务处理参照本办法执行。"},{"i":80,"n":"第八十条","txt":"本办法由中国证监会负责解释、修订。"},{"i":81,"n":"第八十一条","txt":"本办法自2006年7月1日起施行。"}],"huobishichangjijinjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为了促进公开募集证券投资基金（以下简称基金）的发展，规范货币市场基金的募集、运作及相关活动，保护投资人及相关当事人的合法权益，根据《证券投资基金法》及其他有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称货币市场基金是指仅投资于货币市场工具，每个交易日可办理基金份额申购、赎回的基金。 在基金名称中使用“货币”、“现金”、“流动”等类似字样的基金视为货币市场基金，适用本办法。 基金管理人可以按照本办法的规定，根据市场与投资者需求，开发设计不同风险收益特征的货币市场基金产品，拓展货币市场基金作为现金管理工具的各项基础功能。"},{"i":3,"n":"第三条","txt":"中国证监会、中国人民银行依照法律、行政法规、本办法的规定和审慎监管原则，对货币市场基金运作活动实施监督管理。"},{"i":4,"n":"第四条","txt":"货币市场基金应当投资于以下金融工具： （一）现金； （二）期限在1年以内（含1 年）的银行存款、债券回购、中央银行票据、同业存单； （三）剩余期限在397天以内（含397 天）的债券、非金融企业债务融资工具、资产支持证券； （四）中国证监会、中国人民银行认可的其他具有良好流动性的货币市场工具。"},{"i":5,"n":"第五条","txt":"货币市场基金不得投资于以下金融工具： （一）股票； （二）可转换债券、可交换债券； （三）以定期存款利率为基准利率的浮动利率债券，已进入最后一个利率调整期的除外； （四）信用等级在AA＋以下的债券与非金融企业债务融资工具； （五）中国证监会、中国人民银行禁止投资的其他金融工具。"},{"i":6,"n":"第六条","txt":"货币市场基金投资于相关金融工具的比例应当符合下列规定： （一）同一机构发行的债券、非金融企业债务融资工具及其作为原始权益人的资产支持证券占基金资产净值的比例合计不得超过10%，国债、中央银行票据、政策性金融债券除外； （二）货币市场基金投资于有固定期限银行存款的比例，不得超过基金资产净值的30%，但投资于有存款期限，根据协议可提前支取的银行存款不受上述比例限制；货币市场基金投资于具有基金托管人资格的同一商业银行的银行存款、同业存单占基金资产净值的比例合计不得超过 20%，投资于不具有基金托管人资格的同一商业银行的银行存款、同业存单占基金资产净值的比例合计不得超过 5%。"},{"i":7,"n":"第七条","txt":"货币市场基金应当保持足够比例的流动性资产以应对潜在的赎回要求，其投资组合应当符合下列规定： （一）现金、国债、中央银行票据、政策性金融债券占基金资产净值的比例合计不得低于5%； （二）现金、国债、中央银行票据、政策性金融债券以及五个交易日内到期的其他金融工具占基金资产净值的比例合计不得低于10%； （三）到期日在 10 个交易日以上的逆回购、银行定期存款等流动性受限资产投资占基金资产净值的比例合计不得超过30%； （四）除发生巨额赎回、连续3个交易日累计赎回20%以上或者连续5个交易日累计赎回30%以上的情形外，债券正回购的资金余额占基金资产净值的比例不得超过20%。"},{"i":8,"n":"第八条","txt":"因市场波动、基金规模变动等基金管理人之外的因素致使货币市场基金投资不符合本办法第六条及第七条第（二）、（三）、（四）项规定的比例或者基金合同约定的投资比例的，基金管理人应当在10 个交易日内进行调整，但中国证监会规定的特殊情形除外。"},{"i":9,"n":"第九条","txt":"货币市场基金投资组合的平均剩余期限不得超过120天，平均剩余存续期不得超过240 天。"},{"i":10,"n":"第十条","txt":"对于每日按照面值进行报价的货币市场基金，可以在基金合同中将收益分配的方式约定为红利再投资，并应当每日进行收益分配。"},{"i":11,"n":"第十一条","txt":"货币市场基金应当采取稳健、适当的会计核算和估值方法。在确保基金资产净值能够公允地反映基金投资组合价值的前提下，可采用摊余成本法对持有的投资组合进行会计核算，但应当在基金合同、基金招募说明书中披露该核算方法及其可能对基金净值波动带来的影响。 前款规定的基金估值核算方法在特殊情形下不能公允反映基金价值的，货币市场基金可以采用其他估值方法。该特殊情形及该估值方法应当在基金合同中约定。"},{"i":12,"n":"第十二条","txt":"对于采用摊余成本法进行核算的货币市场基金，应当采用影子定价的风险控制手段，对摊余成本法计算的基金资产净值的公允性进行评估。 当影子定价确定的基金资产净值与摊余成本法计算的基金资产净值的负偏离度绝对值达到0.25%时，基金管理人应当在5个交易日内将负偏离度绝对值调整到0.25%以内。当正偏离度绝对值达到0.5%时，基金管理人应当暂停接受申购并在 5个交易日内将正偏离度绝对值调整到 0.5%以内。当负偏离度绝对值达到0.5%时，基金管理人应当使用风险准备金或者固有资金弥补潜在资产损失，将负偏离度绝对值控制在0.5%以内。当负偏离度绝对值连续两个交易日超过0.5%时，基金管理人应当采用公允价值估值方法对持有投资组合的账面价值进行调整，或者采取暂停接受所有赎回申请并终止基金合同进行财产清算等措施。 前述情形及处理方法应当事先在基金合同中约定并履行信息披露义务。"},{"i":13,"n":"第十三条","txt":"对于不收取申购、赎回费的货币市场基金，可以按照不高于 0.25%的比例从基金资产计提一定的费用，专门用于本基金的销售与基金持有人服务。基金年度报告应当对该项费用的列支情况作专项说明。"},{"i":14,"n":"第十四条","txt":"为了保护基金份额持有人的合法权益，基金管理人可以依照相关法律法规以及基金合同的约定，在特定市场条件下暂停或者拒绝接受一定金额以上的资金申购。"},{"i":15,"n":"第十五条","txt":"当日申购的基金份额应当自下一个交易日起享有基金的分配权益；当日赎回的基金份额自下一个交易日起不享有基金的分配权益，但中国证监会认定的特殊货币市场基金品种除外。"},{"i":16,"n":"第十六条","txt":"货币市场基金的基金份额可以在依法设立的交易场所进行交易，或者按照法律法规和合同约定进行协议转让。"},{"i":17,"n":"第十七条","txt":"基金管理人应当建立健全内部流动性风险控制制度，细化流动性风险管理措施。在满足相关流动性风险管理要求的前提下，当货币市场基金持有的现金、国债、中央银行票据、政策性金融债券以及5 个交易日内到期的其他金融工具占基金资产净值的比例合计低于5%且偏离度为负时，为确保基金平稳运作，避免诱发系统性风险，基金管理人应当对当日单个基金份额持有人申请赎回基金份额超过基金总份额 1%以上的赎回申请征收 1%的强制赎回费用，并将上述赎回费用全额计入基金财产。基金管理人与基金托管人协商确认上述做法无益于基金利益最大化的情形除外。前述情形及处理方法应当事先在基金合同中约定。 为公平对待不同类别基金份额持有人的合法权益，货币市场基金应当在基金合同中约定，单个基金份额持有人在单个开放日申请赎回基金份额超过基金总份额 10%的，基金管理人可以采取延期办理部分赎回申请或者延缓支付赎回款项的措施。"},{"i":18,"n":"第十八条","txt":"基金管理人应当在货币市场基金的招募说明书及宣传推介材料的显著位置列明，投资者购买货币市场基金并不等于将资金作为存款存放在银行或者存款类金融机构，基金管理人不保证基金一定盈利，也不保证最低收益。"},{"i":19,"n":"第十九条","txt":"基金管理人、基金销售机构在从事货币市场基金销售活动过程中，应当按照有关法律法规规定制作宣传推介材料，严格规范宣传推介行为，充分揭示投资风险，不得承诺收益，不得使用与货币市场基金风险收益特征不相匹配的表述，不得夸大或者片面宣传货币市场基金的投资收益或者过往业绩。 除基金管理人、基金销售机构外，其他机构或者个人不得擅自制作或者发放与货币市场基金相关的宣传推介材料；登载货币市场基金宣传推介材料的，不得片面引用或者修改其内容。"},{"i":20,"n":"第二十条","txt":"基金销售支付结算机构等相关机构开展与货币市场基金相关的业务推广活动，应当事先征得合作基金管理人或者基金销售机构的同意，严格遵守相关法律法规的规定，不得混同、比较货币市场基金与银行存款及其他产品的投资收益，不得以宣传理财账户或者服务平台等名义变相从事货币市场基金的宣传推介活动。"},{"i":21,"n":"第二十一条","txt":"基金管理人、基金销售机构独立或者与互联网机构等其他机构合作开展货币市场基金互联网销售业务时，应当采取显著方式向投资人揭示提供基金销售服务的主体、投资风险以及销售的货币市场基金名称，不得以理财账户或者服务平台的名义代替基金名称，并对合作业务范围、法律关系界定、信息安全保障、客户信息保密、合规经营义务、应急处置机制、防范非法证券活动、合作终止时的业务处理方案、违约责任承担和投资人权益保护等进行明确约定。"},{"i":22,"n":"第二十二条","txt":"基金管理人、基金销售机构与互联网机构等其他机构合作开展货币市场基金销售业务，不得有以下情形： （一）未经中国证监会注册取得基金销售业务资格，擅自从事基金宣传推介、份额发售与申购赎回等相关业务； （二）侵占或者挪用基金销售结算资金； （三）欺诈误导投资人； （四）未向投资人充分揭示投资风险； （五）泄露投资人客户资料、交易信息等非公开信息； （六）从事违法违规经营活动； （七）法律法规及中国证监会规定的其他情形。"},{"i":23,"n":"第二十三条","txt":"基金管理人、基金销售机构、基金销售支付结算机构以及互联网机构在从事或者参与货币市场基金销售过程中，向投资人提供快速赎回等增值服务的，应当充分揭示增值服务的业务规则，并采取有效方式披露增值服务的内容、范围、权利义务、费用及限制条件等信息，不得片面强调增值服务便利性，不得使用夸大或者虚假用语宣传增值服务。 从事基金销售支付结算业务的非银行支付机构应当严格按照《支付机构客户备付金存管办法》有关要求存放、使用、划转客户备付金，不得将客户备付金用于基金赎回垫支。"},{"i":24,"n":"第二十四条","txt":"基金管理人应当严格按照有关基金信息披露法律法规要求履行货币市场基金的信息披露义务，鼓励基金管理人结合自身条件，自愿增加货币市场基金信息披露的频率和内容，提高货币市场基金的透明度。"},{"i":25,"n":"第二十五条","txt":"基金管理人从事货币市场基金投资管理活动，应当坚持组合管理、分散投资的基本原则，严格按照本办法规定和基金合同约定的投资范围与比例限制进行资产配置，构建与货币市场基金风险收益特征相匹配的投资组合。"},{"i":26,"n":"第二十六条","txt":"基金管理人应当建立健全货币市场基金相关投资管理制度、风险控制系统与信息技术系统，加强对流动性风险、利率风险、信用风险、交易对手风险、道德风险等各类风险的管理与控制。"},{"i":27,"n":"第二十七条","txt":"基金管理人应当注重货币市场基金操作风险的防控，针对货币市场基金申购赎回、交易清算、估值核算、信息披露等环节制定相关业务操作指引并建立风险识别与管理制度，提高从业人员的风险防范意识与业务操作能力。"},{"i":28,"n":"第二十八条","txt":"基金管理人应当加强货币市场基金从事逆回购交易的流动性风险和交易对手风险的管理，合理分散逆回购交易到期日和交易对手的集中度，加强逆回购交易质押品资质和质押品期限的控制，质押品按公允价值计算应当足额。"},{"i":29,"n":"第二十九条","txt":"基金管理人应当加强对货币市场基金投资银行存款风险的评估与研究，严格测算与控制投资银行存款的风险敞口，针对不同类型存款银行建立相关投资限制制度，投资各类银行存款所形成的潜在利息损失应当与基金管理人的风险准备金规模相匹配。如果出现因提前支取而导致利息损失的情形，基金管理人应当使用风险准备金予以弥补，风险准备金不足的，应当使用固有资金予以弥补。"},{"i":30,"n":"第三十条","txt":"基金管理人应当建立和完善货币市场基金债券投资的内部信用评级制度，综合运用外部信用评级与内部信用评级结果，按照审慎原则具体限定不同信用等级金融工具的投资限制。基金管理人应当对货币市场基金已投资的信用类金融工具建立内部评级跟踪制度与估值风险防范机制，并保留相关资料备查。"},{"i":31,"n":"第三十一条","txt":"基金管理人应当将压力测试作为货币市场基金风险管理的重要手段，建立科学审慎、全面有效的压力测试制度，结合自身风险管理水平与市场情况定期或者不定期开展压力测试，并针对压力测试结果及时采取防范措施，同时将最近一个年度的压力测试工作底稿留存备查。"},{"i":32,"n":"第三十二条","txt":"货币市场基金遇到下列极端风险情形之一的，基金管理人及其股东在履行内部程序后，可以使用固有资金从货币市场基金购买金融工具： （一）货币市场基金持有的金融工具出现兑付风险； （二）货币市场基金发生巨额赎回，且持有资产的流动性难以满足赎回要求； （三）货币市场基金负偏离度绝对值超过0.25%时，需要从货币市场基金购买风险资产。 基金管理人及其股东购买相关金融工具的价格不得低于该金融工具的账面价值。 前述事项发生后，基金管理人应当在两个交易日内向中国证监会报告，并依法履行信息披露义务，其中涉及到银行间市场的，应当遵守中国人民银行有关规定，向相关部门备案。"},{"i":33,"n":"第三十三条","txt":"基金管理人应当坚持稳健经营理念，其货币市场基金管理规模应当与自身的人员储备、投研和客服能力、风险管理和内部控制水平相匹配，杜绝片面追求收益率和基金规模，不得以收益率作为基金经理考核评价的唯一标准，不得通过交易上的安排规避本办法对投资范围、投资比例、平均剩余期限及存续期的相关规定，不得违规从事或者参与债券代持交易。"},{"i":34,"n":"第三十四条","txt":"基金托管人应当切实履行共同受托职责，严格按照本办法规定对所托管的货币市场基金的日常投资运作活动实施监督，与基金管理人共同做好货币市场基金的风险管理工作，可以根据市场情况及业务发展的需要，对货币市场基金提供流动性支持服务。"},{"i":35,"n":"第三十五条","txt":"货币市场基金的份额净值计价、募集、申购、赎回、投资、信息披露、宣传推介等活动，应当遵守有关法律法规和本办法的规定。"},{"i":36,"n":"第三十六条","txt":"货币市场基金在全国银行间市场的交易、结算等市场行为，应当遵守中国人民银行关于全国银行间市场的管理规定，并接受中国人民银行的监管和动态检查。"},{"i":37,"n":"第三十七条","txt":"基金管理人、基金托管人在管理与托管货币市场基金过程中，因违反法律法规或者基金合同约定导致基金财产或者基金份额持有人损失的，应当分别对各自的行为依法承担赔偿责任；因共同行为导致基金财产或者基金份额持有人损失的，应当承担连带赔偿责任。"},{"i":38,"n":"第三十八条","txt":"基金管理人违反本办法规定的，中国证监会可以采取责令改正、监管谈话、出具警示函，整改期间暂停受理及审查基金产品募集申请或者其他业务申请等行政监管措施，记入诚信档案；对直接负责的主管人员和其他直接责任人员，可以依法采取监管谈话、出具警示函、认定为不适当人选等行政监管措施，记入诚信档案；情节严重的，可以对基金管理人及其直接负责的主管人员和其他直接责任人员单处或者并处警告、3万元以下罚款；涉嫌犯罪的，依法移送司法机关，追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"基金管理人在管理货币市场基金过程中，由于风险管理不善而发生重大风险事件或者存在重大违法违规行为的，中国证监会可以责令基金管理人提高风险准备金的计提比例或者一次性补足一定金额的风险准备金；情节严重的，可以根据《证券投资基金法》有关规定，对基金管理人采取责令停业整顿、指定其他机构托管、接管、取消基金管理资格或者撤销等监管措施。"},{"i":40,"n":"第四十条","txt":"基金托管人未按照本办法规定履行货币市场基金托管职责的，中国证监会可以依据《证券投资基金托管业务管理办法》有关规定采取行政监管措施。"},{"i":41,"n":"第四十一条","txt":"基金销售机构、基金销售支付机构及互联网机构等相关机构或者个人在从事或者参与货币市场基金的销售、宣传推介等活动过程中，违反本办法规定的，中国证监会可以依据《证券投资基金销售管理办法》等有关规定采取行政监管措施。"},{"i":42,"n":"第四十二条","txt":"本办法由中国证监会、中国人民银行负责解释。"},{"i":43,"n":"第四十三条","txt":"本办法自2016年2月1日起施行。《货币市场基金暂行规定》（证监发〔2004〕78号）、《关于货币市场基金投资等相关问题的通知》（证监基金字〔2005〕41号）、《关于货币市场基金投资短期融资券有关问题的通知》（证监基金字〔2005〕163号）、《关于货币市场基金投资银行存款有关问题的通知》（证监发〔2005〕190号）、《关于加强货币市场基金风险控制有关问题的通知》（基金部通知〔2011〕41号）等文件同时废止。"}],"zhuanrongtongyewujianduguanlishixingbanfa":[{"i":1,"n":"第一条","txt":"为了健全融资融券交易机制，拓宽证券公司融资融券业务资金和证券来源，规范转融通业务及相关活动，防范转融通业务风险，根据《证券法》、《证券公司监督管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称转融通业务，是指证券金融公司将自有或者依法筹集的资金和证券出借给证券公司，以供其办理融资融券业务的经营活动。"},{"i":3,"n":"第三条","txt":"从事转融通业务及相关活动，应当遵循平等、自愿、公平和诚实信用原则，不得损害社会公共利益。"},{"i":4,"n":"第四条","txt":"证券金融公司应当遵守法律、行政法规和本办法的规定，严格防范和控制风险，稳健开展转融通业务。"},{"i":5,"n":"第五条","txt":"中国证券监督管理委员会（以下简称证监会）依法对证券金融公司及其相关业务活动进行监督管理。"},{"i":6,"n":"第六条","txt":"证券金融公司根据国务院的决定设立。证监会根据国务院的决定，履行审批程序。"},{"i":7,"n":"第七条","txt":"证券金融公司的组织形式为股份有限公司，注册资本不少于人民币60亿元。 证券金融公司的注册资本应当为实收资本，其股东应当用货币出资。"},{"i":8,"n":"第八条","txt":"证券金融公司应当依照《公司法》和本办法的规定，制定公司章程，设立股东大会、董事会、监事会等组织机构，规范运作。"},{"i":9,"n":"第九条","txt":"证券金融公司董事、监事和高级管理人员的选任，应当经证监会批准。"},{"i":10,"n":"第十条","txt":"证券金融公司不以营利为目的，履行下列职责： （一）为证券公司融资融券业务提供资金和证券的转融通服务； （二）对证券公司融资融券业务运行情况进行监控； （三）监测分析全市场融资融券交易情况，运用市场化手段防控风险； （四）证监会确定的其他职责。"},{"i":11,"n":"第十一条","txt":"证券金融公司变更名称、注册资本、股东、住所、职责范围，制定或者修改公司章程，设立或者撤销分支机构，应当报证监会备案。"},{"i":12,"n":"第十二条","txt":"证券金融公司开展转融通业务，应当以自己的名义，在证券登记结算机构分别开立转融通专用证券账户、转融通担保证券账户和转融通证券交收账户。 转融通专用证券账户用于记录证券金融公司持有的拟向证券公司融出的证券和证券公司归还的证券；转融通担保证券账户用于记录证券公司委托证券金融公司持有、担保证券金融公司因向证券公司转融通所生债权的证券；转融通证券交收账户用于办理证券金融公司与转融通业务有关的证券结算。"},{"i":13,"n":"第十三条","txt":"证券金融公司开展转融通业务，应当以自己的名义，在商业银行开立转融通专用资金账户，在证券登记结算机构分别开立转融通担保资金账户和转融通资金交收账户。 转融通专用资金账户用于存放证券金融公司拟向证券公司融出的资金及证券公司归还的资金；转融通担保资金账户用于记录证券公司交存的、担保证券金融公司因向证券公司转融通所生债权的资金；转融通资金交收账户用于办理证券金融公司与转融通业务有关的资金结算。"},{"i":14,"n":"第十四条","txt":"证券金融公司开展转融通业务，应当了解证券公司的基本情况、业务范围、财务状况、违约记录、风险控制能力等，并以书面和电子的方式予以记录和保存。"},{"i":15,"n":"第十五条","txt":"证券金融公司应当建立客户信用评估机制，对证券公司的信用状况进行评估，并根据评估结果确定和调整对证券公司的授信额度。"},{"i":16,"n":"第十六条","txt":"证券金融公司开展转融通业务，应当与证券公司签订转融通业务合同，约定转融通的资金数额、标的证券的种类和数量、期限、费率、保证金的比例、证券权益处理办法、违约责任等事项。 证券金融公司应当制定转融通业务合同标准格式，报证监会备案。"},{"i":17,"n":"第十七条","txt":"除本条第二款规定的情形外，证券金融公司向证券公司转融通的期限不得超过6个月。转融通的期限，自资金或者证券实际交付之日起算。 证券金融公司可以与证券公司对转融通标的证券暂停交易、终止交易和其他特殊情形下转融通期限的顺延或者缩短作出约定。"},{"i":18,"n":"第十八条","txt":"证券金融公司应当按照国家宏观政策，根据市场状况和风险控制需要，确定和调整转融通费率和保证金的比例。"},{"i":19,"n":"第十九条","txt":"证券金融公司与证券公司签订转融通业务合同后，应当根据证券公司的申请，以证券公司的名义，为其开立转融通担保证券明细账户和转融通担保资金明细账户。 转融通担保证券明细账户是转融通担保证券账户的二级账户，用于记载证券公司委托证券金融公司持有的担保证券的明细数据。转融通担保资金明细账户是转融通担保资金账户的二级账户，用于记载证券公司交存的担保资金的明细数据。证券金融公司可以委托证券登记结算机构根据清算、交收结果等，对证券公司转融通担保证券明细账户和转融通担保资金明细账户内的数据进行变更。"},{"i":20,"n":"第二十条","txt":"证券金融公司开展转融通业务，应当向证券公司收取一定比例的保证金。保证金可以证券充抵，但货币资金占应收取保证金的比例不得低于15%。 证券金融公司应当确定并公布可充抵保证金证券的种类和折算率。 证券金融公司可以与证券登记结算机构签订合同，委托证券登记结算机构代为管理保证金。"},{"i":21,"n":"第二十一条","txt":"证券公司向证券金融公司交存保证金，采取设立信托的方式。保证金中的证券应当记入转融通担保证券账户，保证金中的资金应当记入转融通担保资金账户。 证券金融公司与证券公司应当约定，转融通担保证券账户内的证券和转融通担保资金账户内的资金，均为担保证券金融公司因向证券公司转融通所生债权的信托财产，因本办法第二十二条第三款规定情形所形成的信托财产对证券金融公司的债权，也归入信托财产。"},{"i":22,"n":"第二十二条","txt":"证券金融公司应当逐日计算证券公司交存的保证金价值与其所欠债务的比例。当该比例低于约定的维持保证金比例时，应当通知证券公司在一定的期限内补交差额，直至达到约定的初始保证金比例。但是，对因本条第三款规定情形导致的差额，证券公司无须补交。 证券公司违约的，证券金融公司可以按照约定处分保证金，以实现对证券公司的债权；处分保证金不足以完全实现对证券公司的债权的，证券金融公司应当依法向证券公司追偿。 经证券公司书面同意，证券金融公司可以有偿使用证券公司交存的保证金。证券金融公司使用保证金的用途、期限、对价等具体事项，由双方通过转融通业务合同约定。"},{"i":23,"n":"第二十三条","txt":"证券金融公司可以根据化解证券公司违约风险的需要，建立转融通互保基金。转融通互保基金的管理办法，由证券金融公司制定，报证监会备案后实施。"},{"i":24,"n":"第二十四条","txt":"市场交易活动出现异常，已经或者可能危及市场稳定，有必要暂停转融通业务的，证券金融公司可以按照业务规则和合同约定，暂停全部或者部分转融通业务并公告。"},{"i":25,"n":"第二十五条","txt":"证券登记结算机构根据证券账户和资金账户持有人发出或者认可的指令，办理转融通业务涉及的证券和资金的划转。"},{"i":26,"n":"第二十六条","txt":"司法机关依法对证券公司转融通担保证券明细账户或者转融通担保资金明细账户记载的权益采取财产保全或者强制执行措施的，证券金融公司应当处分保证金，在实现因向证券公司转融通所生债权后，协助司法机关执行。"},{"i":27,"n":"第二十七条","txt":"证券金融公司开展转融通业务，可以使用下列资金和证券： （一）自有资金和证券； （二）通过证券交易所的业务平台融入的资金和证券； （三）通过证券金融公司的业务平台融入的资金； （四）依法筹集的其他资金和证券。"},{"i":28,"n":"第二十八条","txt":"证券金融公司可以依照《公司法》、《证券法》等有关规定，发行公司债券。"},{"i":29,"n":"第二十九条","txt":"证券金融公司可以向股东或者其他特定投资者借入次级债。证券金融公司借入次级债，应当事先向证监会报告。 证券金融公司借入的次级债，参照证监会对证券公司借入次级债的有关规定，计入净资本。"},{"i":30,"n":"第三十条","txt":"证券金融公司通过证券交易所的业务平台融入资金和证券，按照证券交易所的业务规则办理。证券登记结算机构按照证券交易所业务平台的成交结果，办理有关登记结算。"},{"i":31,"n":"第三十一条","txt":"证券金融公司为履行本办法规定的职责，可以通过其在证券登记结算机构开立的普通证券账户买卖证券。"},{"i":32,"n":"第三十二条","txt":"证券登记结算机构根据转融通担保证券账户内的记录，确认证券金融公司受托持有证券的事实，并以证券金融公司为名义持有人，登记于证券持有人名册。"},{"i":33,"n":"第三十三条","txt":"对转融通担保证券账户内记录的证券，由证券金融公司以自己的名义，行使对证券发行人的权利。证券金融公司行使对证券发行人的权利，应当事先征求委托其持有该证券的证券公司意见，并按照其意见办理。 前款所称对证券发行人的权利，是指请求召开证券持有人会议、参加证券持有人会议、提案、表决、配售股份的认购、请求分配投资收益等因持有证券而产生的权利。"},{"i":34,"n":"第三十四条","txt":"证券登记结算机构受证券发行人委托以证券或者现金形式分派投资收益的，应当分别将分派的证券或者现金记录在转融通担保证券账户或者转融通担保资金账户内，并相应变更证券公司转融通担保证券明细账户或者转融通担保资金明细账户的数据。"},{"i":35,"n":"第三十五条","txt":"证券金融公司根据本办法规定融入证券后、归还证券前，或者证券公司向证券金融公司融入证券后、归还证券前，证券发行人分配投资收益、向证券持有人配售或者无偿派发证券、发行证券持有人有优先认购权的证券的，证券金融公司或者证券公司应当按照约定向融出方支付与所融入证券可得利益相等的证券或者资金。"},{"i":36,"n":"第三十六条","txt":"证券金融公司通过转融通担保证券账户持有的证券不计入其自有证券，证券金融公司无须因该账户内证券数量的变动而履行信息报告、披露或者要约收购义务。 证券公司通过其自营证券账户、融券专用证券账户和转融通担保证券明细账户合计持有一家上市公司股票及其权益的数量或者其增减变动达到规定的比例时，应当依法履行信息报告、披露或者要约收购义务。有一致行动人的，一致行动人与证券公司持有的股票及其权益的数量合并计算。"},{"i":37,"n":"第三十七条","txt":"证券金融公司应当依照本办法的规定制定转融通业务规则，明确账户管理、授信管理、标的证券管理、保证金管理、费率管理、信息披露等事项，报证监会备案后实施。"},{"i":38,"n":"第三十八条","txt":"证券金融公司应当每个交易日公布以下转融通信息： （一）转融资余额； （二）转融券余额； （三）转融通成交数据； （四）转融通费率。"},{"i":39,"n":"第三十九条","txt":"证券金融公司应当建立合规管理机制，保证公司的经营管理及工作人员的执业行为合法合规。"},{"i":40,"n":"第四十条","txt":"证券金融公司应当建立风险控制机制，有效识别、评估、控制公司经营管理中的各类风险。"},{"i":41,"n":"第四十一条","txt":"证券金融公司应当遵守以下风险控制指标规定： （一）净资本与各项风险资本准备之和的比例不得低于100%； （二）对单一证券公司转融通的余额，不得超过证券金融公司净资本的50%； （三）融出的每种证券余额不得超过该证券上市可流通市值的10%； （四）充抵保证金的每种证券余额不得超过该证券总市值的15%。 证券金融公司净资本、风险资本准备的计算，参照证监会对证券公司的有关规定执行。证监会另有规定的除外。"},{"i":42,"n":"第四十二条","txt":"证券金融公司不得为他人的债务提供担保。"},{"i":43,"n":"第四十三条","txt":"证券金融公司应当每年按照税后利润的10%提取风险准备金。证监会可以根据防范证券金融公司风险的需要，对提取比例进行调整。"},{"i":44,"n":"第四十四条","txt":"证券金融公司的资金，除用于履行本办法规定职责和维持公司正常运转外，只能用于以下用途： （一）银行存款； （二）购买国债、证券投资基金份额等经证监会认可的高流动性金融产品； （三）购置自用不动产； （四）证监会认可的其他用途。"},{"i":45,"n":"第四十五条","txt":"证券金融公司应当建立信息系统安全管理机制，保障公司信息系统安全、稳定运行。"},{"i":46,"n":"第四十六条","txt":"证券金融公司应当自每一会计年度结束之日起4个月内，向证监会报送年度报告。年度报告应当包含按照规定编制并经符合《证券法》规定的会计师事务所审计的财务会计报告。 证券金融公司应当自每月结束之日起7个工作日内，向证监会报送月度报告。月度报告应当包含本办法第四十一条所列各项风险控制指标和转融通业务专项报表，以及证监会要求报送的其他信息。"},{"i":47,"n":"第四十七条","txt":"发生影响或者可能影响公司经营管理的重大事件的，证券金融公司应当立即向证监会报送临时报告，说明事件的起因、目前的状态、可能产生的后果和应对措施。"},{"i":48,"n":"第四十八条","txt":"证券金融公司为履行监控证券公司融资融券业务运行情况的职责，可以制定证券公司融资融券业务监控规则，报证监会备案后实施。 证券公司应当按照规定向证券金融公司报送融资融券的相关数据。证券公司报送的数据应当真实、准确、完整。 证券交易所、证券登记结算机构、证券金融公司应当建立融资融券信息共享机制。"},{"i":49,"n":"第四十九条","txt":"证券金融公司及其工作人员应当对因履行职责而获悉的信息保密。法律、行政法规和本办法另有规定的除外。"},{"i":50,"n":"第五十条","txt":"证券金融公司应当妥善保存履行本办法规定职责所形成的各类文件、资料，保存期限不少于20年。"},{"i":51,"n":"第五十一条","txt":"证监会为履行监督管理职责，可以要求证券金融公司及其工作人员提供有关信息、资料，并对公司进行现场检查。"},{"i":52,"n":"第五十二条","txt":"证券金融公司或者证券公司违反本办法规定的，由证监会视具体情形，采取责令改正、出具警示函、责令公开说明、责令定期报告等监管措施；应当给予行政处罚的，由证监会对公司及其有关责任人员单处或者并处警告、罚款。"},{"i":53,"n":"第五十三条","txt":"证券交易所和证券登记结算机构根据本办法制定配套的交易、结算规则，按照规定报经证监会批准或者备案后实施。"},{"i":54,"n":"第五十四条","txt":"本办法自公布之日起施行。"}],"feishangshigongzhonggongsixinxipiluguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范非上市公众公司有关信息披露行为，保护投资者合法权益，维护市场秩序和社会公众利益，根据《公司法》《证券法》《国务院关于全国中小企业股份转让系统有关问题的决定》《非上市公众公司监督管理办法》（证监会令第190号）等有关法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于股票在全国中小企业股份转让系统（以下简称全国股转系统）挂牌公开转让的非上市公众公司（以下简称挂牌公司）定期报告和临时报告信息披露有关行为。"},{"i":3,"n":"第三条","txt":"挂牌公司披露的信息，应当真实、准确、完整，简明清晰，通俗易懂，不得有虚假记载、误导性陈述或重大遗漏。 在境外市场发行股票及其他证券品种并上市的挂牌公司在境外市场披露的信息，应当同时在全国股转系统披露。"},{"i":4,"n":"第四条","txt":"根据挂牌公司发展阶段、公众化程度以及风险状况等因素，充分考虑投资者需求，以全国股转系统创新层、基础层分层为基础，实施挂牌公司差异化的信息披露制度。"},{"i":5,"n":"第五条","txt":"挂牌公司的董事、监事、高级管理人员应当忠实、勤勉地履行职责，保证公司及时、公平地披露信息，所披露的信息真实、准确、完整。"},{"i":6,"n":"第六条","txt":"在内幕信息依法披露前，任何知情人不得公开或者泄露该信息，不得利用该信息进行交易。"},{"i":7,"n":"第七条","txt":"挂牌公司依法披露的信息，应当在符合《证券法》规定的信息披露平台发布。挂牌公司在公司网站或者其他公众媒体发布信息的时间不得先于上述信息披露平台。 挂牌公司应当将披露的信息同时置备于公司住所、全国股转系统，供社会公众查阅。 信息披露文件应当采用中文文本。同时采用外文文本的，挂牌公司应当保证两种文本的内容一致。两种文本发生歧义时，以中文文本为准。"},{"i":8,"n":"第八条","txt":"中国证券监督管理委员会（以下简称中国证监会）根据《证券法》等法律法规以及本办法的规定，对挂牌公司信息披露有关各方的行为进行监督管理，并且可以结合市场分层对挂牌公司信息披露实施分类监管。 全国中小企业股份转让系统有限责任公司（以下简称全国股转公司）对挂牌公司信息披露有关行为实施自律管理，强化监管问询，督促挂牌公司及时、准确地披露信息。"},{"i":9,"n":"第九条","txt":"除依法或者按照本办法及有关自律规则需要披露的信息外，挂牌公司可以自愿披露与投资者作出价值判断和投资决策有关的信息，但不得与依法或者按照本办法及有关自律规则披露的信息相冲突，不得误导投资者。 挂牌公司应当保持信息披露的持续性和一致性，避免选择性披露，不得利用自愿披露信息不当影响公司股票及其他证券品种交易价格。自愿披露具有一定预测性质信息的，应当明确预测的依据，并提示可能出现的不确定性和风险。"},{"i":10,"n":"第十条","txt":"由于国家秘密、商业秘密等特殊原因导致本办法规定的某些信息确实不便披露的，挂牌公司可以不予披露，但应当在相关定期报告、临时报告中说明未按照规定进行披露的原因。中国证监会、全国股转公司认为需要披露的，挂牌公司应当披露。"},{"i":11,"n":"第十一条","txt":"挂牌公司定期报告包括年度报告、中期报告。凡是对投资者作出投资决策有重大影响的信息，均应当在定期报告中披露。 年度报告中的财务会计报告应当经符合《证券法》规定的会计师事务所审计。"},{"i":12,"n":"第十二条","txt":"年度报告应当在每个会计年度结束之日起四个月内，中期报告应当在每个会计年度的上半年结束之日起两个月内编制完成并披露。"},{"i":13,"n":"第十三条","txt":"挂牌公司年度报告应当记载以下内容： （一）公司基本情况； （二）主要会计数据和财务指标； （三）管理层讨论与分析； （四）公司股票、债券发行及变动情况，报告期末股票、债券总额、股东总数，公司前十大股东持股情况； （五）控股股东及实际控制人情况； （六）董事、监事、高级管理人员、核心员工任职及持股情况； （七）报告期内发生的重大事件及对公司的影响； （八）公司募集资金使用情况（如有）； （九）利润分配情况； （十）公司治理及内部控制情况； （十一）财务会计报告和审计报告全文； （十二）中国证监会规定的其他事项。"},{"i":14,"n":"第十四条","txt":"挂牌公司中期报告应当记载以下内容： （一）公司基本情况； （二）主要会计数据和财务指标； （三）公司股票、债券发行及变动情况，报告期末股东总数，公司前十大股东持股情况； （四）控股股东及实际控制人发生变化的情况； （五）报告期内重大诉讼、仲裁等重大事件及对公司的影响； （六）公司募集资金使用情况（如有）； （七）财务会计报告； （八）中国证监会规定的其他事项。"},{"i":15,"n":"第十五条","txt":"挂牌公司存在特别表决权股份的，应当在年度报告中披露特别表决权股份的持有和变化情况，以及相关投资者合法权益保护措施的实施情况。"},{"i":16,"n":"第十六条","txt":"挂牌公司股东大会实行累积投票制和网络投票安排的，应当在年度报告中披露累积投票制和网络投票安排的实施情况。"},{"i":17,"n":"第十七条","txt":"挂牌公司董事、高级管理人员应当对定期报告签署书面确认意见。 监事会应当对董事会编制的定期报告进行审核并提出书面审核意见，说明董事会的编制和审核程序是否符合法律、行政法规和中国证监会、全国股转公司的规定，报告的内容是否真实、准确、完整地反映挂牌公司的实际情况。监事应当签署书面确认意见。 挂牌公司董事、监事和高级管理人员无法保证定期报告内容的真实性、准确性、完整性或者有异议的，应当在书面确认意见中发表意见并陈述理由，挂牌公司应当披露。挂牌公司不予披露的，董事、监事和高级管理人员可以直接申请披露。"},{"i":18,"n":"第十八条","txt":"定期报告披露前出现业绩泄露，或者出现业绩传闻且公司股票及其他证券品种交易出现异常波动的，挂牌公司应当及时披露本报告期相关财务数据。"},{"i":19,"n":"第十九条","txt":"定期报告中的财务会计报告被出具非标准审计意见的，挂牌公司董事会应当针对该审计意见涉及事项作出专项说明。"},{"i":20,"n":"第二十条","txt":"挂牌公司未在规定期限内披露定期报告的，全国股转公司根据自律规则予以处理，情节严重的，应当提请中国证监会立案稽查。"},{"i":21,"n":"第二十一条","txt":"发生可能对挂牌公司股票及其他证券品种交易价格产生较大影响，或者对投资者作出投资决策有较大影响的重大事件，投资者尚未得知时，挂牌公司应当立即将有关该重大事件的情况向中国证监会和全国股转公司报送临时报告，并予公告，说明事件的起因、目前的状态和可能产生的影响。 前款所称重大事件包括： （一）公司的经营方针和经营范围的重大变化； （二）公司的重大投资行为，公司在一年内购买、出售重大资产超过公司资产总额百分之三十，或者公司营业用主要资产的抵押、质押、出售或者报废一次超过该资产的百分之三十； （三）公司订立重要合同，提供重大担保或者从事关联交易，可能对公司的资产、负债、权益和经营成果产生重要影响； （四）公司发生重大债务和未能清偿到期重大债务的违约情况； （五）公司发生重大亏损或者重大损失； （六）公司生产经营的外部条件发生的重大变化； （七）公司的董事、三分之一以上监事或者经理发生变动，董事长或"},{"i":22,"n":"第二十二条","txt":"挂牌公司应当在最先发生的以下任一时点，及时履行重大事件的信息披露义务： （一）董事会或者监事会就该重大事件形成决议时； （二）有关各方就该重大事件签署意向书或者协议时； （三）董事、监事或者高级管理人员知悉或者应当知悉该重大事件发生时。 挂牌公司筹划的重大事项存在较大不确定性，立即披露可能会损害公司利益或者误导投资者，且有关内幕信息知情人已书面承诺保密的，公司可以暂不披露，但最迟应当在该重大事项形成最终决议、签署最终协议、交易确定能够达成时对外披露。 相关信息确实难以保密、已经泄露或者出现市场传闻，导致公司股票及其他证券品种交易价格发生大幅波动的，公司应当立即披露相关筹划和进展情况。"},{"i":23,"n":"第二十三条","txt":"挂牌公司披露重大事件后，已披露的重大事件出现可能对投资者决策或者挂牌公司股票及其他证券品种交易价格产生较大影响的进展或者变化的，应当及时披露进展或者变化情况、可能产生的影响。"},{"i":24,"n":"第二十四条","txt":"挂牌公司控股子公司发生本办法第二十一条规定的重大事件，可能对投资者决策或者公司股票及其他证券品种交易价格产生较大影响的，挂牌公司应当履行信息披露义务。 挂牌公司参股公司发生可能对投资者决策或者挂牌公司股票及其他证券品种交易价格产生较大影响的事件，挂牌公司应当履行信息披露义务。"},{"i":25,"n":"第二十五条","txt":"挂牌公司股票及其他证券品种交易被中国证监会或者全国股转公司认定为异常波动的，挂牌公司应当及时了解造成交易异常波动的影响因素，并于次一交易日开盘前披露。"},{"i":26,"n":"第二十六条","txt":"媒体传播的消息可能或者已经对投资者决策或者挂牌公司股票及其他证券品种交易价格产生较大影响的，挂牌公司应当及时了解情况，发布相应澄清公告。"},{"i":27,"n":"第二十七条","txt":"挂牌公司应当制定信息披露事务管理制度，经董事会审议通过并披露。信息披露事务管理制度应当包括： （一）明确挂牌公司应当披露的信息，确定披露标准； （二）未公开信息的传递、审核、披露流程； （三）信息披露事务负责人在信息披露中的职责； （四）董事和董事会、监事和监事会、高级管理人员等的报告、审议和披露的职责； （五）董事、监事、高级管理人员履行职责的记录和保管制度； （六）未公开信息的保密措施，内幕信息知情人登记管理要求，内幕信息知情人的范围和保密责任； （七）财务管理和会计核算的内部控制及监督机制； （八）对外发布信息的申请、审核、发布流程；与投资者、证券服务机构、媒体等的信息沟通与制度； （九）信息披露相关文件、资料的档案管理； （十）涉及子公司的信息披露事务管理和报告制度； （十一）未按规定披露信息的责任追究机制，对违反规定人员的处理措施。 信息披露事务负责人是指挂牌公司董事会秘书或"},{"i":28,"n":"第二十八条","txt":"挂牌公司董事长、经理、信息披露事务负责人，应当对公司临时报告信息披露的真实性、准确性、完整性、及时性和公平性承担主要责任。 挂牌公司董事长、经理、财务负责人应对公司财务报告的真实性、准确性、完整性、及时性和公平性承担主要责任。"},{"i":29,"n":"第二十九条","txt":"挂牌公司董事、监事、高级管理人员应当关注信息披露文件的编制情况，保证定期报告、临时报告在规定期限内披露，配合挂牌公司履行信息披露义务。"},{"i":30,"n":"第三十条","txt":"挂牌公司应当制定定期报告的编制、审议、公告程序。经理、财务负责人、信息披露事务负责人及相关人员应当及时编制定期报告草案，提请董事会审议；信息披露事务负责人负责送达董事审阅；董事长负责召集和主持董事会会议审议定期报告；监事会负责审核董事会编制的定期报告；信息披露事务负责人负责组织定期报告的公告工作。"},{"i":31,"n":"第三十一条","txt":"挂牌公司应当制定重大事件的报告、传递、审核、披露程序。董事、监事、高级管理人员知悉重大事件发生时，应当按照公司规定立即履行报告义务；董事长在接到报告后，应当立即向董事会报告，并敦促信息披露事务负责人组织临时报告的披露工作。"},{"i":32,"n":"第三十二条","txt":"挂牌公司通过业绩说明会、分析师会议、路演、接受投资者调研等形式就公司的经营情况、财务情况及其他事件与任何机构和个人进行沟通的，不得提供内幕信息。"},{"i":33,"n":"第三十三条","txt":"董事应当了解并持续关注公司生产经营情况、财务状况和公司已经发生或者可能发生的重大事件及其影响，主动调查、获取决策所需的资料。"},{"i":34,"n":"第三十四条","txt":"监事应当对公司董事、高级管理人员履行信息披露职责的行为进行监督；关注公司信息披露情况，发现信息披露存在违法违规问题的，应当进行调查并提出处理建议。"},{"i":35,"n":"第三十五条","txt":"高级管理人员应当及时向董事会报告有关公司经营或者财务方面出现的重大事件、已披露的事件的进展或者变化情况及其他相关信息。"},{"i":36,"n":"第三十六条","txt":"信息披露事务负责人负责组织和协调挂牌公司信息披露事务，汇集挂牌公司应当披露的信息并报告董事会，持续关注媒体对公司的报道并主动求证报道的真实情况，办理公司信息对外公布等相关事宜。 信息披露事务负责人有权参加股东大会、董事会会议、监事会会议和高级管理人员相关会议，有权了解公司的财务和经营情况，查阅涉及信息披露事宜的所有文件。挂牌公司应当为信息披露事务负责人履行职责提供便利条件，财务负责人应当配合信息披露事务负责人在财务信息披露方面的相关工作。"},{"i":37,"n":"第三十七条","txt":"挂牌公司的股东、实际控制人不得滥用其股东权利、支配地位指使挂牌公司不按规定履行信息披露义务或者披露有虚假记载、误导性陈述或者重大遗漏的信息，不得要求挂牌公司向其提供内幕信息。 挂牌公司的股东、实际控制人发生以下事件时，应当及时告知公司，并配合挂牌公司履行信息披露义务。 （一）持有公司百分之五以上股份的股东或者实际控制人，其持有股份或者控制公司的情况发生较大变化，公司的实际控制人及其控制的其他企业从事与公司相同或者相似业务的情况发生较大变化； （二）法院裁决禁止控股股东转让其所持股份，任一股东所持公司百分之五以上股份被质押、冻结、司法拍卖、托管、设定信托或者被依法限制表决权； （三）拟对挂牌公司进行重大资产或者业务重组； （四）中国证监会规定的其他情形。 通过接受委托或者信托等方式持有挂牌公司百分之五以上股份的股东或者实际控制人，应当及时将委托人情况告知挂牌公司，配合挂牌公司履行信息披露"},{"i":38,"n":"第三十八条","txt":"挂牌公司董事、监事、高级管理人员、持股百分之五以上的股东及其一致行动人、实际控制人应当及时向挂牌公司董事会报送挂牌公司关联方名单、关联关系及变化情况的说明。挂牌公司应当履行关联交易的审议程序，并严格执行关联交易回避表决制度。交易各方不得通过隐瞒关联关系或者采取其他手段，规避挂牌公司信息披露义务和关联交易审议程序。"},{"i":39,"n":"第三十九条","txt":"为挂牌公司提供持续督导服务的主办券商应持续关注挂牌公司业务经营、公司治理、财务等方面的重大变化，指导、督促挂牌公司规范履行信息披露义务。挂牌公司应当配合主办券商持续督导工作，提供必要材料，为主办券商开展持续督导工作提供便利条件。 持续督导期间内，发现挂牌公司拟披露的信息或已披露信息存在错误、遗漏或者误导的，或者发现存在应当披露而未披露事项的，主办券商应当要求挂牌公司进行更正或补充。挂牌公司拒不更正、补充的，主办券商应当及时发布风险揭示公告并报告全国股转公司，情节严重的，应同时报告挂牌公司注册地中国证监会派出机构。 主办券商持续督导业务有关具体规定由全国股转公司制定。"},{"i":40,"n":"第四十条","txt":"为挂牌公司履行信息披露义务出具专项文件的证券服务机构，应当勤勉尽责、诚实守信，认真履行审慎核查义务，按照依法制定的业务规定、行业执业规范、监管规则和道德准则发表意见，保证所出具文件的真实性、准确性和完整性。 挂牌公司应当配合为其提供服务的证券服务机构的工作，按要求提供与其执业相关的材料，不得要求证券服务机构出具与客观事实不符的文件或阻碍其工作。 证券服务机构在为信息披露出具专项文件时，发现挂牌公司提供的材料有虚假记载、误导性陈述、重大遗漏的，应当要求其补充、纠正。挂牌公司拒不补充、纠正的，证券服务机构应报告全国股转公司，情节严重的，应同时报告挂牌公司注册地中国证监会派出机构。"},{"i":41,"n":"第四十一条","txt":"挂牌公司解聘会计师事务所的，应当在董事会决议后及时通知会计师事务所，公司股东大会就解聘会计师事务所进行表决时，应当允许会计师事务所陈述意见。股东大会作出解聘、更换会计师事务所决议的，挂牌公司应当在披露时说明更换的具体原因和会计师事务所的陈述意见。"},{"i":42,"n":"第四十二条","txt":"任何机构和个人不得非法获取、提供、传播挂牌公司的内幕信息，不得利用所获取的内幕信息买卖或者建议他人买卖公司股票或其他证券品种，不得在投资价值分析报告、研究报告等文件中使用内幕信息。"},{"i":43,"n":"第四十三条","txt":"媒体应当客观、真实地报道涉及挂牌公司的情况，发挥舆论监督作用。 任何机构和个人不得提供、传播虚假或者误导投资者的挂牌公司信息。 违反前两款规定，给投资者造成损失的，依法承担赔偿责任。"},{"i":44,"n":"第四十四条","txt":"中国证监会依法对挂牌公司、主办券商和证券服务机构进行检查，挂牌公司、主办券商和证券服务机构应当予以配合。 中国证监会可以要求挂牌公司及其股东、实际控制人，或者其董事、监事、高级管理人员对有关信息披露问题作出解释、说明或者提供相关资料，或要求挂牌公司提供主办券商或者证券服务机构的专业意见。 中国证监会可以要求主办券商、证券服务机构对挂牌公司有关信息披露问题进行核查，并出具专项意见。中国证监会对主办券商和证券服务机构出具文件的真实性、准确性、完整性有疑义的，可以要求相关机构作出解释、补充，并调阅其工作底稿。"},{"i":45,"n":"第四十五条","txt":"挂牌公司及其董事、监事、高级管理人员，挂牌公司的股东、实际控制人及其董事、监事、高级管理人员违反本办法的，中国证监会可以采取以下措施： （一）责令改正； （二）监管谈话； （三）责令公开说明； （四）出具警示函； （五）依法可以采取的其他监管措施。"},{"i":46,"n":"第四十六条","txt":"主办券商及其人员履行持续督导等义务，未勤勉尽责情节严重的，中国证监会可以采取责令改正、监管谈话、出具警示函及依法可以采取的其他监管措施。"},{"i":47,"n":"第四十七条","txt":"为挂牌公司履行信息披露义务出具专项文件的证券服务机构及其人员，违反《证券法》、行政法规和中国证监会的规定，中国证监会可以采取责令改正、监管谈话、出具警示函及依法可以采取的其他监管措施。"},{"i":48,"n":"第四十八条","txt":"全国股转公司可以依据自律规则及挂牌协议的规定对挂牌公司、主办券商、证券服务机构进行核查、检查，要求挂牌公司及其董事、监事、高级管理人员、股东、实际控制人，主办券商、证券服务机构对有关信息披露问题作出说明，发现问题应当按照有关规定处理，涉嫌违法的及时移送中国证监会。"},{"i":49,"n":"第四十九条","txt":"挂牌公司未按规定履行信息披露义务，或者所披露的信息有虚假记载、误导性陈述或者重大遗漏的，中国证监会依照《证券法》有关规定处罚。 挂牌公司的控股股东、实际控制人指使从事前款行为的，或知晓前款行为而未及时制止、纠正的，中国证监会可以依照前款规定处罚。"},{"i":50,"n":"第五十条","txt":"挂牌公司及其董事、监事、高级管理人员、股东及其一致行动人、实际控制人，主办券商、证券服务机构未按照本办法规定履行报告义务，或者报送的报告有虚假记载、误导性陈述或者重大遗漏的，中国证监会依照《证券法》有关规定处罚。"},{"i":51,"n":"第五十一条","txt":"挂牌公司通过隐瞒关联关系或者采取其他手段，规避信息披露、报告义务的，中国证监会依照《证券法》有关规定处罚。"},{"i":52,"n":"第五十二条","txt":"为挂牌公司履行信息披露义务出具专项文件的证券服务机构及其人员，违反《证券法》、行政法规和中国证监会的规定，应当给予行政处罚的，中国证监会依照《证券法》有关规定处罚。"},{"i":53,"n":"第五十三条","txt":"任何机构和个人泄露挂牌公司内幕信息，或者利用内幕信息买卖股票及其他证券品种，中国证监会依照《证券法》有关规定处罚。"},{"i":54,"n":"第五十四条","txt":"任何机构和个人编制、传播虚假信息扰乱证券市场；媒体传播挂牌公司信息不真实、不客观的，中国证监会依照《证券法》有关规定处罚。 在股票及其他证券品种交易活动中作出虚假陈述或者信息误导的，中国证监会依照《证券法》有关规定处罚。"},{"i":55,"n":"第五十五条","txt":"挂牌公司未按本办法规定制定挂牌公司信息披露事务管理制度的，中国证监会可以采取责令改正的监管措施。拒不改正的，可以给予警告或者三万元以下罚款。"},{"i":56,"n":"第五十六条","txt":"挂牌公司股东、实际控制人未依法配合挂牌公司履行信息披露义务的，或者非法要求挂牌公司提供内幕信息的，中国证监会可以采取责令改正的监管措施。拒不改正的，可以给予警告或者三万元以下罚款。"},{"i":57,"n":"第五十七条","txt":"相关责任主体违反本办法，存在主动消除或者减轻危害后果等情形的，依法从轻或者减轻处罚。 违法行为轻微并及时纠正，没有造成危害后果的，不予处罚。"},{"i":58,"n":"第五十八条","txt":"相关责任主体违反本办法的规定，情节严重的，中国证监会可以采取证券市场禁入的措施。"},{"i":59,"n":"第五十九条","txt":"违反本办法，涉嫌犯罪的，依法移送司法机关，追究刑事责任。"},{"i":60,"n":"第六十条","txt":"本办法下列用语具有如下含义： （一）主办券商，是指依据《全国中小企业股份转让系统有限责任公司管理暂行办法》规定在全国股转系统从事相关业务的证券公司。 （二）证券服务机构，是指为挂牌公司履行信息披露义务出具专项文件的会计师事务所、资产评估机构、律师事务所、财务顾问机构、资信评级机构等。 （三）及时，是指自起算日起或者触及披露时点的两个交易日内。 （四）挂牌公司的关联交易，是指挂牌公司或者其控股子公司与挂牌公司关联方之间发生的转移资源或者义务的事项。 关联方包括关联法人和关联自然人。 具有以下情形之一的法人或非法人组织，为挂牌公司的关联法人： 1.直接或者间接地控制挂牌公司的法人或非法人组织； 2.由前项所述法人直接或者间接控制的除挂牌公司及其控股子公司以外的法人或非法人组织； 3.关联自然人直接或者间接控制的、或者担任董事、高级管理人员的，除挂牌公司及其控股子公司以外的法人或非法人组织；"},{"i":61,"n":"第六十一条","txt":"股票不在全国股转系统公开转让的非上市公众公司有关信息披露行为按照《非上市公众公司监督管理办法》的相关规定执行。"},{"i":62,"n":"第六十二条","txt":"中国证监会对特殊行业公司信息披露有特别规定的，适用其规定。 国家有关部门对公司信息披露有特别规定的，公司还应当遵守其规定并履行信息披露义务。"},{"i":63,"n":"第六十三条","txt":"本办法自公布之日起施行。"}],"feishangshigongzhonggongsishougouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范非上市公众公司（以下简称公众公司）的收购及相关股份权益变动活动，保护公众公司和投资者的合法权益，维护证券市场秩序和社会公共利益，促进证券市场资源的优化配置，根据《证券法》、《公司法》、《国务院关于全国中小企业股份转让系统有关问题的决定》、《国务院关于进一步优化企业兼并重组市场环境的意见》及其他相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"股票在全国中小企业股份转让系统（以下简称全国股份转让系统）公开转让的公众公司，其收购及相关股份权益变动活动应当遵守本办法的规定。"},{"i":3,"n":"第三条","txt":"公众公司的收购及相关股份权益变动活动，必须遵守法律、行政法规及中国证券监督管理委员会（以下简称中国证监会）的规定，遵循公开、公平、公正的原则。当事人应当诚实守信，遵守社会公德、商业道德，自觉维护证券市场秩序，接受政府、社会公众的监督。"},{"i":4,"n":"第四条","txt":"公众公司的收购及相关股份权益变动活动涉及国家产业政策、行业准入、国有股份转让、外商投资等事项，需要取得国家相关部门批准的，应当在取得批准后进行。"},{"i":5,"n":"第五条","txt":"收购人可以通过取得股份的方式成为公众公司的控股股东，可以通过投资关系、协议、其他安排的途径成为公众公司的实际控制人，也可以同时采取上述方式和途径取得公众公司控制权。 收购人包括投资者及其一致行动人。"},{"i":6,"n":"第六条","txt":"进行公众公司收购，收购人及其实际控制人应当具有良好的诚信记录，收购人及其实际控制人为法人的，应当具有健全的公司治理机制。任何人不得利用公众公司收购损害被收购公司及其股东的合法权益。 有下列情形之一的，不得收购公众公司： （一）收购人负有数额较大债务，到期未清偿，且处于持续状态； （二）收购人最近2年有重大违法行为或者涉嫌有重大违法行为； （三）收购人最近2年有严重的证券市场失信行为； （四）收购人为自然人的，存在《公司法》第一百四十六条规定的情形； （五）法律、行政法规规定以及中国证监会认定的不得收购公众公司的其他情形。"},{"i":7,"n":"第七条","txt":"被收购公司的控股股东或者实际控制人不得滥用股东权利损害被收购公司或者其他股东的合法权益。 被收购公司的控股股东、实际控制人及其关联方有损害被收购公司及其他股东合法权益的，上述控股股东、实际控制人在转让被收购公司控制权之前，应当主动消除损害；未能消除损害的，应当就其出让相关股份所得收入用于消除全部损害做出安排，对不足以消除损害的部分应当提供充分有效的履约担保或安排，并提交被收购公司股东大会审议通过，被收购公司的控股股东、实际控制人及其关联方应当回避表决。"},{"i":8,"n":"第八条","txt":"被收购公司的董事、监事、高级管理人员对公司负有忠实义务和勤勉义务，应当公平对待收购本公司的所有收购人。 被收购公司董事会针对收购所做出的决策及采取的措施，应当有利于维护公司及其股东的利益，不得滥用职权对收购设置不适当的障碍，不得利用公司资源向收购人提供任何形式的财务资助。"},{"i":9,"n":"第九条","txt":"收购人按照本办法第三章、第四章的规定进行公众公司收购的，应当聘请具有财务顾问业务资格的专业机构担任财务顾问，但通过国有股行政划转或者变更、因继承取得股份、股份在同一实际控制人控制的不同主体之间进行转让、取得公众公司向其发行的新股、司法判决导致收购人成为或拟成为公众公司第一大股东或者实际控制人的情形除外。 收购人聘请的财务顾问应当勤勉尽责，遵守行业规范和职业道德，保持独立性，对收购人进行辅导，帮助收购人全面评估被收购公司的财务和经营状况；对收购人的相关情况进行尽职调查，对收购人披露的文件进行充分核查和验证；对收购事项客观、公正地发表专业意见，并保证其所制作、出具文件的真实性、准确性和完整性。在收购人公告被收购公司收购报告书至收购完成后12个月内,财务顾问应当持续督导收购人遵守法律、行政法规、中国证监会的规定、全国股份转让系统相关规则以及公司章程，依法行使股东权利，切实履行承诺或者相关约定"},{"i":10,"n":"第十条","txt":"公众公司的收购及相关股份权益变动活动中的信息披露义务人，应当依法严格履行信息披露和其他法定义务，并保证所披露的信息及时、真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 信息披露义务人应当在证券交易场所的网站和符合中国证监会规定条件的媒体上依法披露信息；在其他媒体上进行披露的，披露内容应当一致，披露时间不得早于前述披露时间。在相关信息披露前，信息披露义务人及知悉相关信息的人员负有保密义务，禁止利用该信息进行内幕交易和从事证券市场操纵行为。 信息披露义务人依法披露前，相关信息已在媒体上传播或者公司股票转让出现异常的，公众公司应当立即向当事人进行查询，当事人应当及时予以书面答复，公众公司应当及时披露。"},{"i":11,"n":"第十一条","txt":"中国证监会依法对公众公司的收购及相关股份权益变动活动进行监督管理。 全国股份转让系统应当制定业务规则，为公众公司的收购及相关股份权益变动活动提供服务，对相关证券转让活动进行实时监控，监督公众公司的收购及相关股份权益变动活动的信息披露义务人切实履行信息披露义务。 中国证券登记结算有限责任公司应当制定业务规则，为公众公司的收购及相关股份权益变动活动所涉及的证券登记、存管、结算等事宜提供服务。"},{"i":12,"n":"第十二条","txt":"投资者在公众公司中拥有的权益，包括登记在其名下的股份和虽未登记在其名下但该投资者可以实际支配表决权的股份。投资者及其一致行动人在公众公司中拥有的权益应当合并计算。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，投资者及其一致行动人应当在该事实发生之日起2日内编制并披露权益变动报告书，报送全国股份转让系统，同时通知该公众公司；自该事实发生之日起至披露后2日内，不得再行买卖该公众公司的股票。 （一）通过全国股份转让系统的做市方式、竞价方式进行证券转让，投资者及其一致行动人拥有权益的股份达到公众公司已发行股份的10%； （二）通过协议方式，投资者及其一致行动人在公众公司中拥有权益的股份拟达到或者超过公众公司已发行股份的10%。 投资者及其一致行动人拥有权益的股份达到公众公司已发行股份的10%后，其拥有权益的股份占该公众公司已发行股份的比例每增加或者减少5%（即其拥有权益的股份每达到5%的整数倍时），应当依照前款规定进行披露。自该事实发生之日起至披露后2日内，不得再行买卖该公众公司的股票。"},{"i":14,"n":"第十四条","txt":"投资者及其一致行动人通过行政划转或者变更、执行法院裁定、继承、赠与等方式导致其直接拥有权益的股份变动达到前条规定比例的，应当按照前条规定履行披露义务。 投资者虽不是公众公司的股东，但通过投资关系、协议、其他安排等方式进行收购导致其间接拥有权益的股份变动达到前条规定比例的，应当按照前条规定履行披露义务。"},{"i":15,"n":"第十五条","txt":"因公众公司向其他投资者发行股份、减少股本导致投资者及其一致行动人拥有权益的股份变动出现本章规定情形的，投资者及其一致行动人免于履行披露义务。公众公司应当自完成增加股本、减少股本的变更登记之日起2日内，就因此导致的公司股东拥有权益的股份变动情况进行披露。"},{"i":16,"n":"第十六条","txt":"通过全国股份转让系统的证券转让，投资者及其一致行动人拥有权益的股份变动导致其成为公众公司第一大股东或者实际控制人，或者通过投资关系、协议转让、行政划转或者变更、执行法院裁定、继承、赠与、其他安排等方式拥有权益的股份变动导致其成为或拟成为公众公司第一大股东或者实际控制人且拥有权益的股份超过公众公司已发行股份10%的，应当在该事实发生之日起2日内编制收购报告书，连同财务顾问专业意见和律师出具的法律意见书一并披露，报送全国股份转让系统，同时通知该公众公司。 收购公众公司股份需要取得国家相关部门批准的，收购人应当在收购报告书中进行明确说明，并持续披露批准程序进展情况。"},{"i":17,"n":"第十七条","txt":"以协议方式进行公众公司收购的，自签订收购协议起至相关股份完成过户的期间为公众公司收购过渡期（以下简称过渡期）。在过渡期内，收购人不得通过控股股东提议改选公众公司董事会，确有充分理由改选董事会的，来自收购人的董事不得超过董事会成员总数的1/3；被收购公司不得为收购人及其关联方提供担保；被收购公司不得发行股份募集资金。 在过渡期内，被收购公司除继续从事正常的经营活动或者执行股东大会已经作出的决议外，被收购公司董事会提出拟处置公司资产、调整公司主要业务、担保、贷款等议案，可能对公司的资产、负债、权益或者经营成果造成重大影响的，应当提交股东大会审议通过。"},{"i":18,"n":"第十八条","txt":"按照本办法进行公众公司收购后，收购人成为公司第一大股东或者实际控制人的，收购人持有的被收购公司股份，在收购完成后12个月内不得转让。 收购人在被收购公司中拥有权益的股份在同一实际控制人控制的不同主体之间进行转让不受前述12个月的限制。"},{"i":19,"n":"第十九条","txt":"在公众公司收购中，收购人做出公开承诺事项的，应同时提出所承诺事项未能履行时的约束措施，并公开披露。 全国股份转让系统应当对收购人履行公开承诺行为进行监督和约束，对未能履行承诺的收购人及时采取自律监管措施。"},{"i":20,"n":"第二十条","txt":"公众公司控股股东、实际控制人向收购人协议转让其所持有的公众公司股份的，应当对收购人的主体资格、诚信情况及收购意图进行调查，并在其权益变动报告书中披露有关调查情况。 被收购公司控股股东、实际控制人及其关联方未清偿其对公司的负债，未解除公司为其负债提供的担保，或者存在损害公司利益的其他情形的，被收购公司董事会应当对前述情形及时披露，并采取有效措施维护公司利益。"},{"i":21,"n":"第二十一条","txt":"投资者自愿选择以要约方式收购公众公司股份的，可以向被收购公司所有股东发出收购其所持有的全部股份的要约（以下简称全面要约），也可以向被收购公司所有股东发出收购其所持有的部分股份的要约（以下简称部分要约）。"},{"i":22,"n":"第二十二条","txt":"收购人自愿以要约方式收购公众公司股份的，其预定收购的股份比例不得低于该公众公司已发行股份的5%。"},{"i":23,"n":"第二十三条","txt":"公众公司应当在公司章程中约定在公司被收购时收购人是否需要向公司全体股东发出全面要约收购，并明确全面要约收购的触发条件以及相应制度安排。 收购人根据被收购公司章程规定需要向公司全体股东发出全面要约收购的，对同一种类股票的要约价格，不得低于要约收购报告书披露日前6个月内取得该种股票所支付的最高价格。"},{"i":24,"n":"第二十四条","txt":"以要约方式进行公众公司收购的，收购人应当公平对待被收购公司的所有股东。"},{"i":25,"n":"第二十五条","txt":"以要约方式收购公众公司股份的，收购人应当聘请财务顾问，并编制要约收购报告书，连同财务顾问专业意见和律师出具的法律意见书一并披露，报送全国股份转让系统，同时通知该公众公司。 要约收购需要取得国家相关部门批准的，收购人应当在要约收购报告书中进行明确说明，并持续披露批准程序进展情况。"},{"i":26,"n":"第二十六条","txt":"收购人可以采用现金、证券、现金与证券相结合等合法方式支付收购公众公司的价款。收购人聘请的财务顾问应当说明收购人具备要约收购的能力。收购人应当在披露要约收购报告书的同时，提供以下至少一项安排保证其具备履约能力： （一）将不少于收购价款总额的20%作为履约保证金存入中国证券登记结算有限责任公司指定的银行等金融机构；收购人以在中国证券登记结算有限责任公司登记的证券支付收购价款的，在披露要约收购报告书的同时，将用于支付的全部证券向中国证券登记结算有限责任公司申请办理权属变更或锁定； （二）银行等金融机构对于要约收购所需价款出具的保函； （三）财务顾问出具承担连带担保责任的书面承诺。如要约期满，收购人不支付收购价款，财务顾问应当承担连带责任，并进行支付。 收购人以证券支付收购价款的，应当披露该证券的发行人最近2年经审计的财务会计报表、证券估值报告，并配合被收购公司或其聘请的独立财务顾问的尽职调查"},{"i":27,"n":"第二十七条","txt":"被收购公司董事会应当对收购人的主体资格、资信情况及收购意图进行调查，对要约条件进行分析，对股东是否接受要约提出建议，并可以根据自身情况选择是否聘请独立财务顾问提供专业意见。 被收购公司决定聘请独立财务顾问的，可以聘请为其提供督导服务的主办券商为独立财务顾问，但存在影响独立性、财务顾问业务受到限制等不宜担任独立财务顾问情形的除外。被收购公司也可以同时聘请其他机构为其提供顾问服务。"},{"i":28,"n":"第二十八条","txt":"收购要约约定的收购期限不得少于30日，并不得超过60日；但是出现竞争要约的除外。 收购期限自要约收购报告书披露之日起开始计算。要约收购需要取得国家相关部门批准的，收购人应将取得的本次收购的批准情况连同律师出具的专项核查意见一并在取得全部批准后2日内披露，收购期限自披露之日起开始计算。 在收购要约约定的承诺期限内，收购人不得撤销其收购要约。"},{"i":29,"n":"第二十九条","txt":"采取要约收购方式的，收购人披露后至收购期限届满前，不得卖出被收购公司的股票，也不得采取要约规定以外的形式和超出要约的条件买入被收购公司的股票。"},{"i":30,"n":"第三十条","txt":"收购人需要变更收购要约的，应当重新编制并披露要约收购报告书，报送全国股份转让系统，同时通知被收购公司。变更后的要约收购价格不得低于变更前的要约收购价格。 收购要约期限届满前15日内，收购人不得变更收购要约；但是出现竞争要约的除外。 出现竞争要约时，发出初始要约的收购人变更收购要约距初始要约收购期限届满不足15日的，应当延长收购期限，延长后的要约期应当不少于15日，不得超过最后一个竞争要约的期满日，并按规定比例追加履约保证能力。 发出竞争要约的收购人最迟不得晚于初始要约收购期限届满前15日披露要约收购报告书，并应当根据本办法的规定履行披露义务。"},{"i":31,"n":"第三十一条","txt":"在要约收购期间，被收购公司董事不得辞职。"},{"i":32,"n":"第三十二条","txt":"同意接受收购要约的股东（以下简称预受股东），应当委托证券公司办理预受要约的相关手续。 在要约收购期限届满前2日内，预受股东不得撤回其对要约的接受。在要约收购期限内，收购人应当每日披露已预受收购要约的股份数量。 在要约收购期限届满后2日内，收购人应当披露本次要约收购的结果。"},{"i":33,"n":"第三十三条","txt":"收购期限届满，发出部分要约的收购人应当按照收购要约约定的条件购买被收购公司股东预受的股份，预受要约股份的数量超过预定收购数量时，收购人应当按照同等比例收购预受要约的股份；发出全面要约的收购人应当购买被收购公司股东预受的全部股份。"},{"i":34,"n":"第三十四条","txt":"公众公司董事未履行忠实勤勉义务，利用收购谋取不当利益的，中国证监会采取监管谈话、出具警示函等监管措施，情节严重的，有权认定其为不适当人选。涉嫌犯罪的，依法移交司法机关追究其刑事责任。"},{"i":35,"n":"第三十五条","txt":"收购人在收购要约期限届满时，不按照约定支付收购价款或者购买预受股份的，自该事实发生之日起2年内不得收购公众公司；涉嫌操纵证券市场的，中国证监会对收购人进行调查，依法追究其法律责任。 前款规定的收购人聘请的财务顾问没有充分证据表明其勤勉尽责的，中国证监会视情节轻重，自确认之日起采取3个月至12个月内不接受该机构出具的相关专项文件、12个月至36个月内不接受相关签字人员出具的专项文件的监管措施，并依法追究其法律责任。"},{"i":36,"n":"第三十六条","txt":"公众公司控股股东和实际控制人在转让其对公司的控制权时，未清偿其对公司的负债，未解除公司为其提供的担保，或者未对其损害公司利益的其他情形作出纠正的，且被收购公司董事会未对前述情形及时披露并采取有效措施维护公司利益的，中国证监会责令改正，在改正前收购人应当暂停收购活动。 被收购公司董事会未能依法采取有效措施促使公司控股股东、实际控制人予以纠正，或者在收购完成后未能促使收购人履行承诺、安排或者保证的，中国证监会有权认定相关董事为不适当人选。"},{"i":37,"n":"第三十七条","txt":"公众公司的收购及相关股份权益变动活动中的信息披露义务人，未按照本办法的规定履行信息披露以及其他相关义务，或者信息披露文件中有虚假记载、误导性陈述或者重大遗漏的，中国证监会采取责令改正、监管谈话、出具警示函、责令暂停或者终止收购等监管措施；情节严重的，比照《证券法》第一百九十六条、依照《证券法》第一百九十七条进行行政处罚，并可以采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"投资者及其一致行动人规避法定程序和义务，变相进行公众公司收购，或者外国投资者规避管辖的，中国证监会采取责令改正、出具警示函、责令暂停或者停止收购等监管措施；情节严重的，进行行政处罚，并可以采取市场禁入的措施；涉嫌犯罪的，依法移交司法机关追究其刑事责任。"},{"i":39,"n":"第三十九条","txt":"为公众公司收购出具审计报告、法律意见书和财务顾问报告的证券服务机构或者证券公司及其专业人员，未依法履行职责的，中国证监会采取责令改正、监管谈话、出具警示函等监管措施，并根据情况依照《证券法》第二百一十三条进行行政处罚；情节严重的，可以采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":40,"n":"第四十条","txt":"任何知悉收购信息的人员在相关信息依法披露前，泄露该信息、买卖或者建议他人买卖相关公司股票的，依照《证券法》第一百九十一条予以处罚；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"编造、传播虚假收购信息，操纵证券市场或者进行欺诈活动的，依照《证券法》第一百九十二条、第一百九十三条予以处罚；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"中国证监会将公众公司的收购及相关股份权益变动活动中的当事人的违法行为和整改情况记入诚信档案。"},{"i":43,"n":"第四十三条","txt":"本办法所称一致行动人、公众公司控制权及持股比例计算等参照《上市公司收购管理办法》的相关规定。"},{"i":44,"n":"第四十四条","txt":"为公众公司收购提供服务的财务顾问的业务许可、业务规则和法律责任等，按照《上市公司并购重组财务顾问业务管理办法》的相关规定执行。"},{"i":45,"n":"第四十五条","txt":"做市商持有公众公司股份相关权益变动信息的披露，由中国证监会另行规定。"},{"i":46,"n":"第四十六条","txt":"股票不在全国股份转让系统公开转让的公众公司收购及相关股份权益变动的信息披露内容比照本办法的相关规定执行。"},{"i":47,"n":"第四十七条","txt":"本办法自2014年7月23日起施行。"}],"feishangshigongzhonggongsijianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范非上市公众公司股票转让和发行行为，保护投资者合法权益，维护社会公共利益，根据《证券法》、《公司法》及相关法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称非上市公众公司（以下简称公众公司）是指有下列情形之一且其股票未在证券交易所上市交易的股份有限公司： （一）股票向特定对象发行或者转让导致股东累计超过200人； （二）股票公开转让。"},{"i":3,"n":"第三条","txt":"公众公司应当按照法律、行政法规、本办法和公司章程的规定，做到股权明晰，合法规范经营，公司治理机制健全，履行信息披露义务。"},{"i":4,"n":"第四条","txt":"公众公司公开转让股票应当在全国中小企业股份转让系统（以下简称全国股转系统）进行，公开转让的公众公司股票应当在中国证券登记结算公司集中登记存管。"},{"i":5,"n":"第五条","txt":"公众公司可以依法进行股权融资、债权融资、资产重组等。 公众公司发行优先股、可转换公司债券等证券品种，应当遵守法律、行政法规和中国证券监督管理委员会（以下简称中国证监会）的相关规定。"},{"i":6,"n":"第六条","txt":"为公司出具专项文件的证券公司、律师事务所、会计师事务所及其他证券服务机构，应当勤勉尽责、诚实守信，认真履行审慎核查义务，按照依法制定的业务规则、行业执业规范和职业道德准则发表专业意见，保证所出具文件的真实性、准确性和完整性，并接受中国证监会的监管。"},{"i":7,"n":"第七条","txt":"公众公司应当依法制定公司章程。 中国证监会依法对公众公司章程必备条款作出具体规定，规范公司章程的制定和修改。"},{"i":8,"n":"第八条","txt":"公众公司应当建立兼顾公司特点和公司治理机制基本要求的股东大会、董事会、监事会制度，明晰职责和议事规则。"},{"i":9,"n":"第九条","txt":"公众公司的治理结构应当确保所有股东，特别是中小股东充分行使法律、行政法规和公司章程规定的合法权利。 股东对法律、行政法规和公司章程规定的公司重大事项，享有知情权和参与权。 公众公司应当建立健全投资者关系管理，保护投资者的合法权益。"},{"i":10,"n":"第十条","txt":"公众公司股东大会、董事会、监事会的召集、提案审议、通知时间、召开程序、授权委托、表决和决议等应当符合法律、行政法规和公司章程的规定；会议记录应当完整并安全保存。 股东大会的提案审议应当符合规定程序，保障股东的知情权、参与权、质询权和表决权；董事会应当在职权范围和股东大会授权范围内对审议事项作出决议，不得代替股东大会对超出董事会职权范围和授权范围的事项进行决议。"},{"i":11,"n":"第十一条","txt":"公众公司董事会应当对公司的治理机制是否给所有的股东提供合适的保护和平等权利等情况进行充分讨论、评估。"},{"i":12,"n":"第十二条","txt":"公众公司应当强化内部管理，按照相关规定建立会计核算体系、财务管理和风险控制等制度，确保公司财务报告真实可靠及行为合法合规。"},{"i":13,"n":"第十三条","txt":"公众公司进行关联交易应当遵循平等、自愿、等价、有偿的原则，保证交易公平、公允，维护公司的合法权益，根据法律、行政法规、中国证监会的规定和公司章程，履行相应的审议程序。 关联交易不得损害公众公司利益。"},{"i":14,"n":"第十四条","txt":"公众公司应当采取有效措施防止股东及其关联方以各种形式占用或者转移公司的资金、资产及其他资源。 公众公司股东、实际控制人、董事、监事及高级管理人员不得实施侵占公司资产、利益输送等损害公众公司利益的行为。 未经董事会或股东大会批准或授权，公众公司不得对外提供担保。"},{"i":15,"n":"第十五条","txt":"公众公司实施并购重组行为，应当按照法律、行政法规、中国证监会的规定和公司章程，履行相应的决策程序并聘请证券公司和相关证券服务机构出具专业意见。 任何单位和个人不得利用并购重组损害公众公司及其股东的合法权益。"},{"i":16,"n":"第十六条","txt":"进行公众公司收购，收购人或者其实际控制人应当具有健全的公司治理机制和良好的诚信记录。收购人不得以任何形式从被收购公司获得财务资助，不得利用收购活动损害被收购公司及其股东的合法权益。 在公众公司收购中，收购人持有的被收购公司的股份，在收购完成后12个月内不得转让。"},{"i":17,"n":"第十七条","txt":"公众公司实施重大资产重组，重组的相关资产应当权属清晰、定价公允，重组后的公众公司治理机制健全，不得损害公众公司和股东的合法权益。"},{"i":18,"n":"第十八条","txt":"公众公司应当按照法律的规定，同时结合公司的实际情况在章程中约定建立表决权回避制度。"},{"i":19,"n":"第十九条","txt":"公众公司应当在章程中约定纠纷解决机制。股东有权按照法律、行政法规和公司章程的规定，通过仲裁、民事诉讼或者其他法律手段保护其合法权益。"},{"i":20,"n":"第二十条","txt":"股票公开转让的科技创新公司存在特别表决权股份的，应当在公司章程中规定以下事项： （一）特别表决权股份的持有人资格； （二）特别表决权股份拥有的表决权数量与普通股份拥有的表决权数量的比例安排； （三）持有人所持特别表决权股份能够参与表决的股东大会事项范围; （四）特别表决权股份锁定安排及转让限制； （五）特别表决权股份与普通股份的转换情形； （六）其他事项。 全国股转系统应对存在特别表决权股份的公司表决权差异的设置、存续、调整、信息披露和投资者保护等事项制定具体规定。"},{"i":21,"n":"第二十一条","txt":"公司及其他信息披露义务人应当按照法律、行政法规和中国证监会的规定履行信息披露义务，所披露的信息应当真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。公司及其他信息披露义务人应当及时、公平地向所有投资者披露信息。 公司的董事、监事、高级管理人员应当忠实、勤勉地履行职责，保证公司披露信息的真实、准确、完整。"},{"i":22,"n":"第二十二条","txt":"信息披露文件主要包括公开转让说明书、定向转让说明书、定向发行说明书、发行情况报告书、定期报告和临时报告等。具体的内容与格式、编制规则及披露要求，由中国证监会另行制定。"},{"i":23,"n":"第二十三条","txt":"股票公开转让与定向发行的公众公司应当报送年度报告、中期报告，并予公告。年度报告中的财务会计报告应当经符合《证券法》规定的会计师事务所审计。 股票向特定对象转让导致股东累计超过200人的公众公司，应当报送年度报告，并予公告。年度报告中的财务会计报告应当经会计师事务所审计。"},{"i":24,"n":"第二十四条","txt":"公众公司董事、高级管理人员应当对定期报告签署书面确认意见；对报告内容有异议的，应当单独陈述理由，并与定期报告同时披露。公众公司不得以董事、高级管理人员对定期报告内容有异议为由不按时披露定期报告。 公众公司监事会应当对董事会编制的定期报告进行审核并提出书面审核意见，说明董事会对定期报告的编制和审核程序是否符合法律、行政法规、中国证监会的规定和公司章程，报告的内容是否能够真实、准确、完整地反映公司实际情况。监事应当签署书面确认意见。"},{"i":25,"n":"第二十五条","txt":"证券公司，律师事务所、会计师事务所及其他证券服务机构出具的文件和其他有关的重要文件应当作为备查文件，予以披露。"},{"i":26,"n":"第二十六条","txt":"发生可能对股票价格产生较大影响的重大事件，投资者尚未得知时，公众公司应当立即将有关该重大事件的情况向中国证监会和全国股转系统报送临时报告，并予以公告，说明事件的起因、目前的状态和可能产生的后果。"},{"i":27,"n":"第二十七条","txt":"中国证监会对公众公司实行差异化信息披露管理，具体规定由中国证监会另行制定。"},{"i":28,"n":"第二十八条","txt":"公众公司实施并购重组的，相关信息披露义务人应当依法严格履行公告义务。 参与并购重组的相关单位和人员，应当及时、准确地向公众公司通报有关信息，配合公众公司真实、准确、完整地进行披露，在并购重组的信息依法披露前负有保密义务，禁止利用该信息进行内幕交易。"},{"i":29,"n":"第二十九条","txt":"公众公司应当制定信息披露事务管理制度并指定具有相关专业知识的人员负责信息披露事务。"},{"i":30,"n":"第三十条","txt":"除监事会公告外，公众公司披露的信息应当以董事会公告的形式发布。董事、监事、高级管理人员非经董事会书面授权，不得对外发布未披露的信息。"},{"i":31,"n":"第三十一条","txt":"公司及其他信息披露义务人依法披露的信息，应当在符合《证券法》规定的信息披露平台公布。公司及其他信息披露义务人可在公司网站或者其他公众媒体上刊登依本办法必须披露的信息，但披露的内容应当完全一致，且不得早于在上述信息披露平台披露的时间。 股票向特定对象转让导致股东累计超过200人的公众公司可以在公司章程中约定其他信息披露方式；在《证券法》规定的信息披露平台披露相关信息的，应当符合本条第一款的要求。"},{"i":32,"n":"第三十二条","txt":"公司及其他信息披露义务人应当将信息披露公告文稿和相关备查文件置备于公司住所、全国股转系统（如适用）供社会公众查阅。"},{"i":33,"n":"第三十三条","txt":"公司应当配合为其提供服务的证券公司及律师事务所、会计师事务所等证券服务机构的工作，按要求提供所需资料，不得要求证券公司、证券服务机构出具与客观事实不符的文件或者阻碍其工作。"},{"i":34,"n":"第三十四条","txt":"股票向特定对象转让导致股东累计超过200人的股份有限公司，应当自上述行为发生之日起3个月内，按照中国证监会有关规定制作申请文件，申请文件应当包括但不限于：定向转让说明书、律师事务所出具的法律意见书、会计师事务所出具的审计报告。股份有限公司持申请文件向中国证监会申请核准。在提交申请文件前，股份有限公司应当将相关情况通知所有股东。 在3个月内股东人数降至200人以内的，可以不提出申请。 股票向特定对象转让应当以非公开方式协议转让。申请股票挂牌公开转让的，按照本办法第三十五条、第三十六条的规定办理。"},{"i":35,"n":"第三十五条","txt":"公司申请其股票挂牌公开转让的，董事会应当依法就股票挂牌公开转让的具体方案作出决议，并提请股东大会批准，股东大会决议必须经出席会议的股东所持表决权的2/3以上通过。 董事会和股东大会决议中还应当包括以下内容： （一）按照中国证监会的相关规定修改公司章程； （二）按照法律、行政法规和公司章程的规定建立健全公司治理机制； （三）履行信息披露义务，按照相关规定披露公开转让说明书、年度报告、中期报告及其他信息披露内容。 公司申请其股票挂牌公开转让时，可以按照本办法第五章规定申请发行股票。"},{"i":36,"n":"第三十六条","txt":"股东人数超过200人的公司申请其股票挂牌公开转让，应当按照中国证监会有关规定制作公开转让的申请文件，申请文件应当包括但不限于：公开转让说明书、符合《证券法》规定的律师事务所出具的法律意见书、符合《证券法》规定的会计师事务所出具的审计报告、证券公司出具的推荐文件、全国股转系统的自律监管意见。公司持申请文件向中国证监会申请核准。 公开转让说明书应当在公开转让前披露。"},{"i":37,"n":"第三十七条","txt":"股东人数未超过200人的公司申请其股票挂牌公开转让，中国证监会豁免核准，由全国股转系统进行审查。"},{"i":38,"n":"第三十八条","txt":"中国证监会受理申请文件后，依法对公司治理和信息披露进行审核，在20个工作日内作出核准、中止审核、终止审核、不予核准的决定。"},{"i":39,"n":"第三十九条","txt":"公司及其董事、监事、高级管理人员，应当对公开转让说明书、定向转让说明书签署书面确认意见，保证所披露的信息真实、准确、完整。"},{"i":40,"n":"第四十条","txt":"申请股票挂牌公开转让的公司应当聘请证券公司推荐其股票挂牌公开转让。证券公司应当对所推荐的股票公开转让的公众公司进行持续督导，督促公司诚实守信、及时履行信息披露义务、完善公司治理、提高规范运作水平。 股票公开转让的公众公司应当配合证券公司持续督导工作，接受证券公司的指导和督促。"},{"i":41,"n":"第四十一条","txt":"本办法施行前股东人数超过200人的股份有限公司，符合条件的，可以申请在全国股转系统挂牌公开转让股票、首次公开发行并在证券交易所上市。"},{"i":42,"n":"第四十二条","txt":"本办法所称定向发行包括股份有限公司向特定对象发行股票导致股东累计超过200人，以及公众公司向特定对象发行股票两种情形。 前款所称特定对象的范围包括下列机构或者自然人： （一）公司股东； （二）公司的董事、监事、高级管理人员、核心员工； （三）符合投资者适当性管理规定的自然人投资者、法人投资者及其他经济组织。 股票未公开转让的公司确定发行对象时，符合本条第二款第（三）项规定的投资者合计不得超过35名。 核心员工的认定，应当由公司董事会提名，并向全体员工公示和征求意见，由监事会发表明确意见后，经股东大会审议批准。 投资者适当性管理规定由中国证监会另行制定。"},{"i":43,"n":"第四十三条","txt":"公司应当对发行对象的身份进行确认，有充分理由确信发行对象符合本办法和公司的相关规定。 公司应当与发行对象签订包含风险揭示条款的认购协议，发行过程中不得采取公开路演、询价等方式。"},{"i":44,"n":"第四十四条","txt":"公司董事会应当依法就本次股票发行的具体方案作出决议，并提请股东大会批准，股东大会决议必须经出席会议的股东所持表决权的2/3以上通过。 监事会应当对董事会编制的股票发行文件进行审核并提出书面审核意见。监事应当签署书面确认意见。 股东大会就股票发行作出的决议，至少应当包括下列事项： （一）本次发行股票的种类和数量（数量上限）； （二）发行对象或范围、现有股东优先认购安排； （三）定价方式或发行价格（区间）； （四）限售情况； （五）募集资金用途； （六）决议的有效期； （七）对董事会办理本次发行具体事宜的授权； （八）发行前滚存利润的分配方案； （九）其他必须明确的事项。 申请向特定对象发行股票导致股东累计超过200人的股份有限公司，董事会和股东大会决议中还应当包括以下内容： （一）按照中国证监会的相关规定修改公司章程； （二）按照法律、行政法规和公司章程的规定建立健全公司治理机制； （三"},{"i":45,"n":"第四十五条","txt":"董事会、股东大会决议确定具体发行对象的，董事、股东参与认购或者与认购对象存在关联关系的，应当回避表决。 出席董事会的无关联关系董事人数不足三人的，应将该事项提交公司股东大会审议。"},{"i":46,"n":"第四十六条","txt":"公司应当按照中国证监会有关规定制作定向发行的申请文件，申请文件应当包括但不限于：定向发行说明书、符合《证券法》规定的律师事务所出具的法律意见书、符合《证券法》规定的会计师事务所出具的审计报告、证券公司出具的推荐文件。"},{"i":47,"n":"第四十七条","txt":"股票公开转让的公众公司向公司前十名股东、实际控制人、董事、监事、高级管理人员及核心员工定向发行股票，连续12个月内发行的股份未超过公司总股本10%且融资总额不超过2000万元的，无需提供证券公司出具的推荐文件以及律师事务所出具的法律意见书。 按照前款规定发行股票的，董事会决议中应当明确发行对象、发行价格和发行数量，且公司不得存在以下情形： （一）认购人以非现金资产认购的； （二）发行股票导致公司控制权发生变动的； （三）本次发行中存在特殊投资条款安排的； （四）公司或其控股股东、实际控制人、董事、监事、高级管理人员最近12个月内被中国证监会给予行政处罚或采取监管措施、被全国股转系统采取纪律处分的。"},{"i":48,"n":"第四十八条","txt":"向特定对象发行股票后股东累计超过200人的公司，应当持申请文件向中国证监会申请核准。股票公开转让的公众公司提交的申请文件还应当包括全国股转系统的自律监管意见。 股票公开转让的公众公司向特定对象发行股票后股东累计不超过200人的，中国证监会豁免核准，由全国股转系统自律管理。"},{"i":49,"n":"第四十九条","txt":"中国证监会受理申请文件后，依法对公司治理和信息披露以及发行对象情况进行审核，在20个工作日内作出核准、中止审核、终止审核、不予核准的决定。"},{"i":50,"n":"第五十条","txt":"公司申请定向发行股票，可申请一次核准，分期发行。自中国证监会予以核准之日起，公司应当在3个月内首期发行，剩余数量应当在12个月内发行完毕。超过核准文件限定的有效期未发行的，须重新经中国证监会核准后方可发行。首期发行数量应当不少于总发行数量的50%，剩余各期发行的数量由公司自行确定，每期发行后5个工作日内将发行情况报中国证监会备案。"},{"i":51,"n":"第五十一条","txt":"股票发行结束后，公众公司应当按照中国证监会的有关要求编制并披露发行情况报告书。申请分期发行的公众公司应在每期发行后按照中国证监会的有关要求进行披露，并在全部发行结束或者超过核准文件有效期后按照中国证监会的有关要求编制并披露发行情况报告书。 豁免向中国证监会申请核准定向发行的公众公司，应当在发行结束后按照中国证监会的有关要求编制并披露发行情况报告书。"},{"i":52,"n":"第五十二条","txt":"公司及其董事、监事、高级管理人员，应当对定向发行说明书、发行情况报告书签署书面确认意见，保证所披露的信息真实、准确、完整。"},{"i":53,"n":"第五十三条","txt":"公众公司定向发行股份购买资产的，按照本章有关规定办理。"},{"i":54,"n":"第五十四条","txt":"中国证监会会同国务院有关部门、地方人民政府，依照法律法规和国务院有关规定，各司其职，分工协作，对公众公司进行持续监管，防范风险，维护证券市场秩序。"},{"i":55,"n":"第五十五条","txt":"中国证监会依法履行对公司股票转让、股票发行、信息披露的监管职责，有权对公司、证券公司、证券服务机构等采取《证券法》规定的有关措施。"},{"i":56,"n":"第五十六条","txt":"全国股转系统应当发挥自律管理作用，对股票公开转让的公众公司及相关信息披露义务人披露信息进行监督，督促其依法及时、准确地披露信息。发现股票公开转让的公众公司及相关信息披露义务人有违反法律、行政法规和中国证监会相关规定的行为，应当向中国证监会报告，并采取自律管理措施。 全国股转系统可以依据相关规则对股票公开转让的公众公司进行检查。"},{"i":57,"n":"第五十七条","txt":"中国证券业协会应当发挥自律管理作用，对从事公司股票转让和股票发行业务的证券公司进行监督，督促其勤勉尽责地履行尽职调查和督导职责。发现证券公司有违反法律、行政法规和中国证监会相关规定的行为，应当向中国证监会报告，并采取自律管理措施。"},{"i":58,"n":"第五十八条","txt":"中国证监会可以要求公司及其他信息披露义务人或者其董事、监事、高级管理人员对有关信息披露问题作出解释、说明或者提供相关资料，并要求公司提供证券公司或者证券服务机构的专业意见。 中国证监会对证券公司和证券服务机构出具文件的真实性、准确性、完整性有疑义的，可以要求相关机构作出解释、补充，并调阅其工作底稿。"},{"i":59,"n":"第五十九条","txt":"证券公司在从事股票转让、股票发行等业务活动中，应当按照中国证监会的有关规定勤勉尽责地进行尽职调查，规范履行内核程序，认真编制相关文件，并持续督导所推荐公司及时履行信息披露义务、完善公司治理。"},{"i":60,"n":"第六十条","txt":"证券服务机构为公司的股票转让、股票发行等活动出具审计报告、资产评估报告或者法律意见书等文件的，应当严格履行法定职责，遵循勤勉尽责和诚实信用原则，对公司的主体资格、股本情况、规范运作、财务状况、公司治理、信息披露等内容的真实性、准确性、完整性进行充分的核查和验证，并保证其出具的文件不存在虚假记载、误导性陈述或者重大遗漏。"},{"i":61,"n":"第六十一条","txt":"中国证监会依法对公司及其他信息披露义务人、证券公司、证券服务机构进行监督检查或者调查，被检查或者调查对象有义务提供相关文件资料。对于发现问题的单位和个人，中国证监会可以采取责令改正、监管谈话、责令公开说明、出具警示函等监管措施，并记入诚信档案；涉嫌违法、犯罪的，应当立案调查或者移送司法机关。"},{"i":62,"n":"第六十二条","txt":"公司在其公告的股票挂牌公开转让、股票发行文件中隐瞒重要事实或者编造重要虚假内容的，除依照《证券法》有关规定进行处罚外，中国证监会可视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施；情节严重的，中国证监会可以对有关责任人员采取证券市场禁入的措施。 公司擅自改动已提交的股票转让、股票发行申请文件的，或发生重大事项未及时报告或者未及时披露的，中国证监会可视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施。"},{"i":63,"n":"第六十三条","txt":"公司向不符合本办法规定条件的投资者发行股票的，中国证监会可以责令改正。"},{"i":64,"n":"第六十四条","txt":"公司未依照本办法第三十四条、第三十六条、第四十八条规定，擅自转让或者发行股票的，依照《证券法》有关规定进行处罚。"},{"i":65,"n":"第六十五条","txt":"公众公司违反本办法第十三条、第十四条规定的，中国证监会可以责令改正，对相关责任主体给予警告，单处或者并处3万元以下的罚款。"},{"i":66,"n":"第六十六条","txt":"公司及其他信息披露义务人未按照规定披露信息，或者所披露的信息有虚假记载、误导性陈述或者重大遗漏的，依照《证券法》有关规定进行处罚。"},{"i":67,"n":"第六十七条","txt":"信息披露义务人及其董事、监事、高级管理人员，公司控股股东、实际控制人，为信息披露义务人出具专项文件的证券公司、证券服务机构及其工作人员，违反《证券法》、行政法规和中国证监会相关规定的，中国证监会可以依法采取责令改正、监管谈话、出具警示函等监管措施，并记入诚信档案；情节严重的，中国证监会可以对有关责任人员采取证券市场禁入的措施。"},{"i":68,"n":"第六十八条","txt":"公众公司内幕信息知情人或非法获取内幕信息的人，在对公众公司股票价格有重大影响的信息公开前，泄露该信息、买卖或者建议他人买卖该股票的，依照《证券法》有关规定进行处罚。"},{"i":69,"n":"第六十九条","txt":"股票公开转让的公众公司及其股东、实际控制人未按本办法规定配合证券公司、证券服务机构尽职调查、持续督导等工作的，中国证监会可以依法采取责令改正、监管谈话、出具警示函等监管措施，并记入诚信档案。"},{"i":70,"n":"第七十条","txt":"证券公司及其工作人员未按本办法规定履行持续督导责任，情节严重的，中国证监会可以依法采取责令改正、监管谈话、出具警示函等监管措施。"},{"i":71,"n":"第七十一条","txt":"证券公司、证券服务机构出具的文件有虚假记载、误导性陈述或者重大遗漏的，除依照《证券法》及相关法律法规的规定处罚外，中国证监会可以依法采取责令改正、监管谈话、出具警示函等监管措施；情节严重的，中国证监会可以对有关责任人员采取证券市场禁入的措施。"},{"i":72,"n":"第七十二条","txt":"证券公司、证券服务机构擅自改动已提交的股票转让、股票发行申请文件的，或发生重大事项未及时报告或者未及时披露的，中国证监会可视情节轻重，依法采取责令改正、监管谈话、出具警示函等监管措施。"},{"i":73,"n":"第七十三条","txt":"公众公司申请在证券交易所上市的，应当遵守中国证监会和证券交易所的相关规定。"},{"i":74,"n":"第七十四条","txt":"注册在境内的境外上市公司在境内定向发行股份、将境内股份在全国股转系统挂牌公开转让，按照本办法相关规定执行。"},{"i":75,"n":"第七十五条","txt":"本办法施行前股东人数超过200人的股份有限公司，不在全国股转系统挂牌公开转让股票或证券交易所上市的，应当按相关要求规范后申请纳入非上市公众公司监管。"},{"i":76,"n":"第七十六条","txt":"公司发行优先股、可转换公司债券的，应当符合中国证监会和全国股转系统的有关规定，普通股、优先股、可转换公司债券持有人数合并计算，并按照本办法第五章有关规定办理。"},{"i":77,"n":"第七十七条","txt":"本办法所称股份有限公司是指首次申请股票转让或定向发行的股份有限公司；所称公司包括非上市公众公司和首次申请股票转让或定向发行的股份有限公司。"},{"i":78,"n":"第七十八条","txt":"本办法自2013年1月1日起施行。"}],"feishangshigongzhonggongsizhongdazichanchongzuguan0d8267":[{"i":1,"n":"第一条","txt":"为了规范非上市公众公司（以下简称公众公司）重大资产重组行为，保护公众公司和投资者的合法权益，促进公众公司质量不断提高，维护证券市场秩序和社会公共利益，根据《公司法》、《证券法》、《国务院关于全国中小企业股份转让系统有关问题的决定》、《国务院关于进一步优化企业兼并重组市场环境的意见》及其他相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于股票在全国中小企业股份转让系统（以下简称全国股份转让系统）公开转让的公众公司重大资产重组行为。 本办法所称的重大资产重组是指公众公司及其控股或者控制的公司在日常经营活动之外购买、出售资产或者通过其他方式进行资产交易，导致公众公司的业务、资产发生重大变化的资产交易行为。 公众公司及其控股或者控制的公司购买、出售资产，达到下列标准之一的，构成重大资产重组： （一）购买、出售的资产总额占公众公司最近一个会计年度经审计的合并财务会计报表期末资产总额的比例达到50%以上； （二）购买、出售的资产净额占公众公司最近一个会计年度经审计的合并财务会计报表期末净资产额的比例达到50%以上，且购买、出售的资产总额占公众公司最近一个会计年度经审计的合并财务会计报表期末资产总额的比例达到30%以上。 公众公司发行股份购买资产触及本条所列指标的，应当按照本办法的相关要求办理。"},{"i":3,"n":"第三条","txt":"公众公司实施重大资产重组，应当符合下列要求： （一）重大资产重组所涉及的资产定价公允，不存在损害公众公司和股东合法权益的情形； （二）重大资产重组所涉及的资产权属清晰，资产过户或者转移不存在法律障碍，相关债权债务处理合法；所购买的资产，应当为权属清晰的经营性资产； （三）实施重大资产重组后有利于提高公众公司资产质量和增强持续经营能力，不存在可能导致公众公司重组后主要资产为现金或者无具体经营业务的情形； （四）实施重大资产重组后有利于公众公司形成或者保持健全有效的法人治理结构。"},{"i":4,"n":"第四条","txt":"公众公司实施重大资产重组，有关各方应当及时、公平地披露或者提供信息，保证所披露或者提供信息的真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":5,"n":"第五条","txt":"公众公司的董事、监事和高级管理人员在重大资产重组中，应当诚实守信、勤勉尽责，维护公众公司资产的安全，保护公众公司和全体股东的合法权益。"},{"i":6,"n":"第六条","txt":"公众公司实施重大资产重组，应当聘请符合《证券法》规定的独立财务顾问、律师事务所以及会计师事务所等证券服务机构出具相关意见。公众公司应当聘请为其提供督导服务的主办券商为独立财务顾问，但存在影响独立性、财务顾问业务受到限制等不宜担任独立财务顾问情形的除外。公众公司也可以同时聘请其他机构为其重大资产重组提供顾问服务。 为公众公司重大资产重组提供服务的证券服务机构及人员，应当遵守法律、行政法规和中国证券监督管理委员会（以下简称中国证监会）的有关规定，遵循本行业公认的业务标准和道德规范，严格履行职责，不得谋取不正当利益，并应当对其所制作、出具文件的真实性、准确性和完整性承担责任。"},{"i":7,"n":"第七条","txt":"任何单位和个人对知悉的公众公司重大资产重组信息在依法披露前负有保密义务，不得利用公众公司重大资产重组信息从事内幕交易、操纵证券市场等违法活动。"},{"i":8,"n":"第八条","txt":"公众公司与交易对方就重大资产重组进行初步磋商时，应当采取有效的保密措施，限定相关敏感信息的知悉范围，并与参与或知悉本次重大资产重组信息的相关主体签订保密协议。"},{"i":9,"n":"第九条","txt":"公众公司及其控股股东、实际控制人等相关主体研究、筹划、决策重大资产重组事项，原则上应当在相关股票暂停转让后或者非转让时间进行，并尽量简化决策流程、提高决策效率、缩短决策时限，尽可能缩小内幕信息知情人范围。如需要向有关部门进行政策咨询、方案论证的，应当在相关股票暂停转让后进行。"},{"i":10,"n":"第十条","txt":"公众公司筹划重大资产重组事项，应当详细记载筹划过程中每一具体环节的进展情况，包括商议相关方案、形成相关意向、签署相关协议或者意向书的具体时间、地点、参与机构和人员、商议和决议内容等，制作书面的交易进程备忘录并予以妥当保存。参与每一具体环节的所有人员应当即时在备忘录上签名确认。 公众公司应当按照全国股份转让系统的规定及时做好内幕信息知情人登记工作。"},{"i":11,"n":"第十一条","txt":"在筹划公众公司重大资产重组的阶段，交易各方初步达成实质性意向或者虽未达成实质性意向，但相关信息已在媒体上传播或者预计该信息难以保密或者公司股票转让出现异常波动的，公众公司应当及时向全国股份转让系统申请股票暂停转让。"},{"i":12,"n":"第十二条","txt":"筹划、实施公众公司重大资产重组，相关信息披露义务人应当公平地向所有投资者披露可能对公众公司股票转让价格产生较大影响的相关信息，不得有选择性地向特定对象提前泄露。 公众公司的股东、实际控制人以及参与重大资产重组筹划、论证、决策等环节的其他相关机构和人员，应当及时、准确地向公众公司通报有关信息，并配合公众公司及时、准确、完整地进行披露。"},{"i":13,"n":"第十三条","txt":"公众公司进行重大资产重组，应当由董事会依法作出决议，并提交股东大会审议。"},{"i":14,"n":"第十四条","txt":"公众公司召开董事会决议重大资产重组事项，应当在披露决议的同时披露本次重大资产重组报告书、独立财务顾问报告、法律意见书以及重组涉及的审计报告、资产评估报告（或资产估值报告）。董事会还应当就召开股东大会事项作出安排并披露。 如公众公司就本次重大资产重组首次召开董事会前，相关资产尚未完成审计等工作的，在披露首次董事会决议的同时应当披露重大资产重组预案及独立财务顾问对预案的核查意见。公众公司应在披露重大资产重组预案后6个月内完成审计等工作，并再次召开董事会，在披露董事会决议时一并披露重大资产重组报告书、独立财务顾问报告、法律意见书以及本次重大资产重组涉及的审计报告、资产评估报告（或资产估值报告）等。董事会还应当就召开股东大会事项作出安排并披露。"},{"i":15,"n":"第十五条","txt":"股东大会就重大资产重组事项作出的决议，必须经出席会议的股东所持表决权的2/3以上通过。公众公司股东人数超过200人的，应当对出席会议的持股比例在10%以下的股东表决情况实施单独计票。公众公司应当在决议后及时披露表决情况。 前款所称持股比例在10%以下的股东，不包括公众公司董事、监事、高级管理人员及其关联人以及持股比例在10%以上股东的关联人。 公众公司重大资产重组事项与本公司股东或者其关联人存在关联关系的，股东大会就重大资产重组事项进行表决时，关联股东应当回避表决。"},{"i":16,"n":"第十六条","txt":"公众公司可视自身情况在公司章程中约定是否提供网络投票方式以便于股东参加股东大会；退市公司应当采用安全、便捷的网络投票方式为股东参加股东大会提供便利。"},{"i":17,"n":"第十七条","txt":"公众公司重大资产重组可以使用现金、股份、可转换债券、优先股等支付手段购买资产。 使用股份、可转换债券、优先股等支付手段购买资产的，其支付手段的价格由交易双方自行协商确定，定价可以参考董事会召开前一定期间内公众公司股票的市场价格、同行业可比公司的市盈率或市净率等。董事会应当对定价方法和依据进行充分披露。"},{"i":18,"n":"第十八条","txt":"公众公司重大资产重组不涉及发行股份或者公众公司向特定对象发行股份购买资产后股东累计不超过200人的，经股东大会决议后，应当在2个工作日内将重大资产重组报告书、独立财务顾问报告、法律意见书以及重组涉及的审计报告、资产评估报告（或资产估值报告）等信息披露文件报送全国股份转让系统。 全国股份转让系统应当对上述信息披露文件的完备性进行审查。"},{"i":19,"n":"第十九条","txt":"公众公司向特定对象发行股份购买资产后股东累计超过200人的重大资产重组，经股东大会决议后，应当按照中国证监会的有关规定编制申请文件并申请核准。 中国证监会受理申请文件后，依法进行审核，在20个工作日内作出核准、中止审核、终止审核、不予核准的决定。"},{"i":20,"n":"第二十条","txt":"股东大会作出重大资产重组的决议后，公众公司拟对交易对象、交易标的、交易价格等作出变更，构成对原重组方案重大调整的，应当在董事会表决通过后重新提交股东大会审议，并按照本办法的规定向全国股份转让系统重新报送信息披露文件或者向中国证监会重新提出核准申请。 股东大会作出重大资产重组的决议后，公众公司董事会决议终止本次交易或者撤回有关申请的，应当说明原因并披露，并提交股东大会审议。"},{"i":21,"n":"第二十一条","txt":"公众公司收到中国证监会就其发行股份购买资产的重大资产重组申请作出的核准、中止审核、终止审核、不予核准的决定后，应当在2个工作日内披露。 中国证监会不予核准的，自中国证监会作出不予核准的决定之日起3个月内，中国证监会不受理该公众公司发行股份购买资产的重大资产重组申请。"},{"i":22,"n":"第二十二条","txt":"公众公司实施重大资产重组，相关当事人作出公开承诺事项的，应当同时提出未能履行承诺时的约束措施并披露。 全国股份转让系统应当加强对相关当事人履行公开承诺行为的监督和约束，对不履行承诺的行为及时采取自律监管措施。"},{"i":23,"n":"第二十三条","txt":"公众公司重大资产重组完成相关批准程序后，应当及时实施重组方案，并在本次重大资产重组实施完毕之日起2个工作日内，编制并披露实施情况报告书及独立财务顾问、律师的专业意见。 退市公司重大资产重组涉及发行股份的，自收到中国证监会核准文件之日起60日内，本次重大资产重组未实施完毕的，退市公司应当于期满后2个工作日内披露实施进展情况；此后每30日应当披露一次，直至实施完毕。"},{"i":24,"n":"第二十四条","txt":"独立财务顾问应当按照中国证监会的相关规定，对实施重大资产重组的公众公司履行持续督导职责。持续督导的期限自公众公司完成本次重大资产重组之日起，应当不少于一个完整会计年度。"},{"i":25,"n":"第二十五条","txt":"独立财务顾问应当结合公众公司重大资产重组实施当年和实施完毕后的第一个完整会计年度的年报，自年报披露之日起15日内，对重大资产重组实施的下列事项出具持续督导意见，报送全国股份转让系统，并披露： （一）交易资产的交付或者过户情况； （二）交易各方当事人承诺的履行情况及未能履行承诺时相关约束措施的执行情况； （三）公司治理结构与运行情况； （四）本次重大资产重组对公司运营、经营业绩影响的状况； （五）盈利预测的实现情况（如有）； （六）与已公布的重组方案存在差异的其他事项。"},{"i":26,"n":"第二十六条","txt":"本次重大资产重组涉及发行股份的，特定对象以资产认购而取得的公众公司股份，自股份发行结束之日起6个月内不得转让；属于下列情形之一的，12个月内不得转让： （一）特定对象为公众公司控股股东、实际控制人或者其控制的关联人； （二）特定对象通过认购本次发行的股份取得公众公司的实际控制权； （三）特定对象取得本次发行的股份时，对其用于认购股份的资产持续拥有权益的时间不足12个月。"},{"i":27,"n":"第二十七条","txt":"全国股份转让系统对公众公司重大资产重组实施自律管理。 全国股份转让系统应当对公众公司涉及重大资产重组的股票暂停与恢复转让、防范内幕交易等作出制度安排；加强对公众公司重大资产重组期间股票转让的实时监管，建立相应的市场核查机制，并在后续阶段对股票转让情况进行持续监管。 全国股份转让系统应当督促公众公司及其他信息披露义务人依法履行信息披露义务，发现公众公司重大资产重组信息披露文件中有违反法律、行政法规和中国证监会规定行为的，应当向中国证监会报告，并采取相应的自律监管措施；情形严重的，应当要求其暂停重大资产重组。 全国股份转让系统应当督促为公众公司提供服务的独立财务顾问诚实守信、勤勉尽责，发现独立财务顾问有违反法律、行政法规和中国证监会规定行为的，应当向中国证监会报告，并采取相应的自律监管措施。"},{"i":28,"n":"第二十八条","txt":"中国证监会依法对公众公司重大资产重组实施监督管理。 中国证监会发现公众公司进行重大资产重组未按照本办法的规定履行信息披露及相关义务、存在可能损害公众公司或者投资者合法权益情形的，有权要求其补充披露相关信息、暂停或者终止其重大资产重组；有权对公众公司、证券服务机构采取《证券法》第一百七十条规定的措施。"},{"i":29,"n":"第二十九条","txt":"重大资产重组实施完毕后，凡不属于公众公司管理层事前无法获知且事后无法控制的原因，购买资产实现的利润未达到盈利预测报告或者资产评估报告预测金额的80%，或者实际运营情况与重大资产重组报告书存在较大差距的，公众公司的董事长、总经理、财务负责人应当在公众公司披露年度报告的同时，作出解释，并向投资者公开道歉；实现利润未达到预测金额的50%的，中国证监会可以对公众公司及相关责任人员采取监管谈话、出具警示函、责令定期报告等监管措施。"},{"i":30,"n":"第三十条","txt":"公众公司或其他信息披露义务人未按照本办法的规定披露或报送信息、报告，或者披露或报送的信息、报告有虚假记载、误导性陈述或者重大遗漏的，责令改正，依照《证券法》第一百九十七条予以处罚；情节严重的，责令停止重大资产重组，并可以对有关责任人员采取市场禁入的措施。 中国证监会还可以采取自确认之日起36个月内不受理公众公司定向发行申请的监管措施。"},{"i":31,"n":"第三十一条","txt":"公众公司董事、监事和高级管理人员在重大资产重组中，未履行诚实守信、勤勉尽责义务，导致重组方案损害公众公司利益的，采取责令改正、监管谈话、出具警示函等监管措施；情节严重的，进行行政处罚，并可以采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"为重大资产重组出具财务顾问报告、审计报告、法律意见书、资产评估报告（或资产估值报告）及其他专业文件的证券服务机构及其从业人员未履行诚实守信、勤勉尽责义务，违反行业规范、业务规则的，采取责令改正、监管谈话、出具警示函等监管措施；情节严重的，依法追究法律责任。 前款规定的证券服务机构及其从业人员所制作、出具的文件存在虚假记载、误导性陈述或者重大遗漏的，责令改正，依照《证券法》第二百一十三条予以处罚；情节严重的，可以采取市场禁入的措施；涉嫌犯罪的，依法移送司法机关追究刑事责任；除此之外，中国证监会视情节轻重，自确认之日起采取3个月至12个月内不接受该机构出具的相关专项文件、12个月至36个月内不接受相关签字人员出具的专项文件的监管措施。"},{"i":33,"n":"第三十三条","txt":"违反本办法的规定构成证券违法行为的，比照《证券法》等法律法规的规定追究法律责任。"},{"i":34,"n":"第三十四条","txt":"中国证监会将公众公司重大资产重组中的当事人的违法行为和整改情况记入诚信档案。"},{"i":35,"n":"第三十五条","txt":"计算本办法第二条规定的比例时，应当遵守下列规定： （一）购买的资产为股权的，且购买股权导致公众公司取得被投资企业控股权的，其资产总额以被投资企业的资产总额和成交金额二者中的较高者为准，资产净额以被投资企业的净资产额和成交金额二者中的较高者为准；出售股权导致公众公司丧失被投资企业控股权的，其资产总额、资产净额分别以被投资企业的资产总额以及净资产额为准。 除前款规定的情形外，购买的资产为股权的，其资产总额、资产净额均以成交金额为准；出售的资产为股权的，其资产总额、资产净额均以该股权的账面价值为准。 （二）购买的资产为非股权资产的，其资产总额以该资产的账面值和成交金额二者中的较高者为准，资产净额以相关资产与负债账面值的差额和成交金额二者中的较高者为准；出售的资产为非股权资产的，其资产总额、资产净额分别以该资产的账面值、相关资产与负债账面值的差额为准；该非股权资产不涉及负债的，不适用第二条第三"},{"i":36,"n":"第三十六条","txt":"特定对象以现金认购公众公司定向发行的股份后，公众公司用同一次定向发行所募集的资金向该特定对象购买资产达到重大资产重组标准的适用本办法。"},{"i":37,"n":"第三十七条","txt":"公众公司重大资产重组涉及发行可转换债券、优先股等其他支付手段的，应当遵守《证券法》、《国务院关于开展优先股试点的指导意见》和中国证监会的相关规定。"},{"i":38,"n":"第三十八条","txt":"为公众公司重大资产重组提供服务的独立财务顾问业务许可、业务规则及法律责任等，按照《上市公司并购重组财务顾问业务管理办法》的相关规定执行。"},{"i":39,"n":"第三十九条","txt":"退市公司符合中国证监会和证券交易所规定的重新上市条件的，可依法向证券交易所提出申请。"},{"i":40,"n":"第四十条","txt":"股票不在全国股份转让系统公开转让的公众公司重大资产重组履行的决策程序和信息披露内容比照本办法的相关规定执行。"},{"i":41,"n":"第四十一条","txt":"本办法自2014年7月23日起施行。"}],"shoucigongkaifaxinggupiaobingshangshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范首次公开发行股票并上市的行为，保护投资者的合法权益和社会公共利益，根据《证券法》《公司法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内首次公开发行股票并上市，适用本办法。 境内公司股票以外币认购和交易的，不适用本办法。"},{"i":3,"n":"第三条","txt":"首次公开发行股票并上市，应当符合《证券法》《公司法》和本办法规定的发行条件。"},{"i":4,"n":"第四条","txt":"发行人依法披露的信息，必须真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":5,"n":"第五条","txt":"保荐人及其保荐代表人应当遵循勤勉尽责、诚实守信的原则，认真履行审慎核查和辅导义务，并对其所出具的发行保荐书的真实性、准确性、完整性负责。"},{"i":6,"n":"第六条","txt":"为证券发行出具有关文件的证券服务机构和人员，应当按照本行业公认的业务标准和道德规范，严格履行法定职责，并对其所出具文件的真实性、准确性和完整性负责。"},{"i":7,"n":"第七条","txt":"中国证券监督管理委员会（以下简称中国证监会）对发行人首次公开发行股票的核准，不表明其对该股票的投资价值或者投资者的收益作出实质性判断或者保证。股票依法发行后，因发行人经营与收益的变化引致的投资风险，由投资者自行负责。"},{"i":8,"n":"第八条","txt":"发行人应当是依法设立且合法存续的股份有限公司。 经国务院批准，有限责任公司在依法变更为股份有限公司时，可以采取募集设立方式公开发行股票。"},{"i":9,"n":"第九条","txt":"发行人自股份有限公司成立后，持续经营时间应当在3年以上，但经国务院批准的除外。 有限责任公司按原账面净资产值折股整体变更为股份有限公司的，持续经营时间可以从有限责任公司成立之日起计算。"},{"i":10,"n":"第十条","txt":"发行人的注册资本已足额缴纳，发起人或者股东用作出资的资产的财产权转移手续已办理完毕，发行人的主要资产不存在重大权属纠纷。"},{"i":11,"n":"第十一条","txt":"发行人的生产经营符合法律、行政法规和公司章程的规定，符合国家产业政策。"},{"i":12,"n":"第十二条","txt":"发行人最近3年内主营业务和董事、高级管理人员没有发生重大变化，实际控制人没有发生变更。"},{"i":13,"n":"第十三条","txt":"发行人的股权清晰，控股股东和受控股股东、实际控制人支配的股东持有的发行人股份不存在重大权属纠纷。"},{"i":14,"n":"第十四条","txt":"发行人已经依法建立健全股东大会、董事会、监事会、独立董事、董事会秘书制度，相关机构和人员能够依法履行职责。"},{"i":15,"n":"第十五条","txt":"发行人的董事、监事和高级管理人员已经了解与股票发行上市有关的法律法规，知悉上市公司及其董事、监事和高级管理人员的法定义务和责任。"},{"i":16,"n":"第十六条","txt":"发行人的董事、监事和高级管理人员符合法律、行政法规和规章规定的任职资格，且不得有下列情形： （一）被中国证监会采取证券市场禁入措施尚在禁入期的； （二）最近36个月内受到中国证监会行政处罚，或者最近12个月内受到证券交易所公开谴责； （三）因涉嫌犯罪被司法机关立案侦查或者涉嫌违法违规被中国证监会立案调查，尚未有明确结论意见。"},{"i":17,"n":"第十七条","txt":"发行人的内部控制制度健全且被有效执行，能够合理保证财务报告的可靠性、生产经营的合法性、营运的效率与效果。"},{"i":18,"n":"第十八条","txt":"发行人不得有下列情形： （一）最近36个月内未经法定机关核准，擅自公开或者变相公开发行过证券；或者有关违法行为虽然发生在36个月前，但目前仍处于持续状态； （二）最近36个月内违反工商、税收、土地、环保、海关以及其他法律、行政法规，受到行政处罚，且情节严重； （三）最近36个月内曾向中国证监会提出发行申请，但报送的发行申请文件有虚假记载、误导性陈述或重大遗漏；或者不符合发行条件以欺骗手段骗取发行核准；或者以不正当手段干扰中国证监会及其发行审核委员会审核工作；或者伪造、变造发行人或其董事、监事、高级管理人员的签字、盖章； （四）本次报送的发行申请文件有虚假记载、误导性陈述或者重大遗漏； （五）涉嫌犯罪被司法机关立案侦查，尚未有明确结论意见； （六）严重损害投资者合法权益和社会公共利益的其他情形。"},{"i":19,"n":"第十九条","txt":"发行人的公司章程中已明确对外担保的审批权限和审议程序，不存在为控股股东、实际控制人及其控制的其他企业进行违规担保的情形。"},{"i":20,"n":"第二十条","txt":"发行人有严格的资金管理制度，不得有资金被控股股东、实际控制人及其控制的其他企业以借款、代偿债务、代垫款项或者其他方式占用的情形。"},{"i":21,"n":"第二十一条","txt":"发行人资产质量良好，资产负债结构合理，盈利能力较强，现金流量正常。"},{"i":22,"n":"第二十二条","txt":"发行人的内部控制在所有重大方面是有效的，并由注册会计师出具了无保留结论的内部控制鉴证报告。"},{"i":23,"n":"第二十三条","txt":"发行人会计基础工作规范，财务报表的编制符合企业会计准则和相关会计制度的规定，在所有重大方面公允地反映了发行人的财务状况、经营成果和现金流量，并由注册会计师出具了无保留意见的审计报告。"},{"i":24,"n":"第二十四条","txt":"发行人编制财务报表应以实际发生的交易或者事项为依据；在进行会计确认、计量和报告时应当保持应有的谨慎；对相同或者相似的经济业务，应选用一致的会计政策，不得随意变更。"},{"i":25,"n":"第二十五条","txt":"发行人应完整披露关联方关系并按重要性原则恰当披露关联交易。关联交易价格公允，不存在通过关联交易操纵利润的情形。"},{"i":26,"n":"第二十六条","txt":"发行人应当符合下列条件： （一）最近3个会计年度净利润均为正数且累计超过人民币3000万元，净利润以扣除非经常性损益前后较低者为计算依据； （二）最近3个会计年度经营活动产生的现金流量净额累计超过人民币5000万元；或者最近3个会计年度营业收入累计超过人民币3亿元； （三）发行前股本总额不少于人民币3000万元； （四）最近一期末无形资产（扣除土地使用权、水面养殖权和采矿权等后）占净资产的比例不高于20％； （五）最近一期末不存在未弥补亏损。 中国证监会根据《关于开展创新企业境内发行股票或存托凭证试点的若干意见》等规定认定的试点企业（以下简称试点企业），可不适用前款第（一）项、第（五）项规定。"},{"i":27,"n":"第二十七条","txt":"发行人依法纳税，各项税收优惠符合相关法律法规的规定。发行人的经营成果对税收优惠不存在严重依赖。"},{"i":28,"n":"第二十八条","txt":"发行人不存在重大偿债风险，不存在影响持续经营的担保、诉讼以及仲裁等重大或有事项。"},{"i":29,"n":"第二十九条","txt":"发行人申报文件中不得有下列情形： （一）故意遗漏或虚构交易、事项或者其他重要信息； （二）滥用会计政策或者会计估计； （三）操纵、伪造或篡改编制财务报表所依据的会计记录或者相关凭证。"},{"i":30,"n":"第三十条","txt":"发行人不得有下列影响持续盈利能力的情形： （一）发行人的经营模式、产品或服务的品种结构已经或者将发生重大变化，并对发行人的持续盈利能力构成重大不利影响； （二）发行人的行业地位或发行人所处行业的经营环境已经或者将发生重大变化，并对发行人的持续盈利能力构成重大不利影响； （三）发行人最近1个会计年度的营业收入或净利润对关联方或者存在重大不确定性的客户存在重大依赖； （四）发行人最近1个会计年度的净利润主要来自合并财务报表范围以外的投资收益； （五）发行人在用的商标、专利、专有技术以及特许经营权等重要资产或技术的取得或者使用存在重大不利变化的风险； （六）其他可能对发行人持续盈利能力构成重大不利影响的情形。"},{"i":31,"n":"第三十一条","txt":"发行人董事会应当依法就本次股票发行的具体方案、本次募集资金使用的可行性及其他必须明确的事项作出决议，并提请股东大会批准。"},{"i":32,"n":"第三十二条","txt":"发行人股东大会就本次发行股票作出的决议，至少应当包括下列事项： （一）本次发行股票的种类和数量； （二）发行对象； （三）价格区间或者定价方式； （四）募集资金用途； （五）发行前滚存利润的分配方案； （六）决议的有效期； （七）对董事会办理本次发行具体事宜的授权； （八）其他必须明确的事项。"},{"i":33,"n":"第三十三条","txt":"发行人应当按照中国证监会的有关规定制作申请文件，由保荐人保荐并向中国证监会申报。 特定行业的发行人应当提供管理部门的相关意见。"},{"i":34,"n":"第三十四条","txt":"中国证监会收到申请文件后，在5个工作日内作出是否受理的决定。"},{"i":35,"n":"第三十五条","txt":"中国证监会受理申请文件后，由相关职能部门对发行人的申请文件进行初审，并由发行审核委员会审核。"},{"i":36,"n":"第三十六条","txt":"中国证监会在初审过程中，将征求发行人注册地省级人民政府是否同意发行人发行股票的意见。"},{"i":37,"n":"第三十七条","txt":"中国证监会依照法定条件对发行人的发行申请作出予以核准或者不予核准的决定，并出具相关文件。 自中国证监会核准发行之日起，发行人应在6个月内发行股票；超过6个月未发行的，核准文件失效，须重新经中国证监会核准后方可发行。"},{"i":38,"n":"第三十八条","txt":"发行申请核准后、股票发行结束前，发行人发生重大事项的，应当暂缓或者暂停发行，并及时报告中国证监会，同时履行信息披露义务。影响发行条件的，应当重新履行核准程序。"},{"i":39,"n":"第三十九条","txt":"股票发行申请未获核准的，自中国证监会作出不予核准决定之日起6个月后，发行人可再次提出股票发行申请。"},{"i":40,"n":"第四十条","txt":"发行人应当按照中国证监会的有关规定编制和披露招股说明书。"},{"i":41,"n":"第四十一条","txt":"招股说明书内容与格式准则是信息披露的最低要求。不论准则是否有明确规定，凡是对投资者作出投资决策有重大影响的信息，均应当予以披露。"},{"i":42,"n":"第四十二条","txt":"发行人应当在招股说明书中披露已达到发行监管对公司独立性的基本要求。"},{"i":43,"n":"第四十三条","txt":"发行人及其全体董事、监事和高级管理人员应当在招股说明书上签字、盖章，保证招股说明书的内容真实、准确、完整。保荐人及其保荐代表人应当对招股说明书的真实性、准确性、完整性进行核查，并在核查意见上签字、盖章。"},{"i":44,"n":"第四十四条","txt":"招股说明书中引用的财务报表在其最近一期截止日后6个月内有效，特殊情况下发行人可申请适当延长，但至多不超过3个月。财务报表应当以年度末、半年度末或者季度末为截止日。"},{"i":45,"n":"第四十五条","txt":"招股说明书的有效期为6个月，自中国证监会核准发行申请前招股说明书最后一次签署之日起计算。"},{"i":46,"n":"第四十六条","txt":"申请文件受理后、发行审核委员会审核前，发行人应当将招股说明书（申报稿）在中国证监会网站（www.csrc.gov.cn）预先披露。发行人可以将招股说明书（申报稿）刊登于其企业网站，但披露内容应当完全一致，且不得早于在中国证监会网站的披露时间。"},{"i":47,"n":"第四十七条","txt":"发行人及其全体董事、监事和高级管理人员应当保证预先披露的招股说明书（申报稿）的内容真实、准确、完整。"},{"i":48,"n":"第四十八条","txt":"预先披露的招股说明书（申报稿）不是发行人发行股票的正式文件，不能含有价格信息，发行人不得据此发行股票。 发行人应当在预先披露的招股说明书（申报稿）的显要位置声明：“本公司的发行申请尚未得到中国证监会核准。本招股说明书（申报稿）不具有据以发行股票的法律效力，仅供预先披露之用。投资者应当以正式公告的招股说明书全文作为作出投资决定的依据。”"},{"i":49,"n":"第四十九条","txt":"发行人股票发行前只需在一种中国证监会指定报刊刊登提示性公告，告知投资者网上刊登的地址。同时将招股说明书全文和摘要刊登于中国证监会指定的网站并将招股说明书全文置于发行人住所、拟上市证券交易所、保荐人、主承销商和其他承销机构的住所，以备公众查阅。"},{"i":50,"n":"第五十条","txt":"保荐人出具的发行保荐书、证券服务机构出具的有关文件应当作为招股说明书的备查文件，在中国证监会指定的网站上披露，并置备于发行人住所、拟上市证券交易所、保荐人、主承销商和其他承销机构的住所，以备公众查阅。"},{"i":51,"n":"第五十一条","txt":"发行人可以将招股说明书摘要、招股说明书全文、有关备查文件刊登于其他报刊和网站，但披露内容应当完全一致，且不得早于在中国证监会指定报刊和网站的披露时间。"},{"i":52,"n":"第五十二条","txt":"发行人向中国证监会报送的发行申请文件有虚假记载、误导性陈述或者重大遗漏的，发行人不符合发行条件以欺骗手段骗取发行核准的，发行人以不正当手段干扰中国证监会及其发行审核委员会审核工作的，发行人或其董事、监事、高级管理人员的签字、盖章系伪造或者变造的，除依照《证券法》的有关规定处罚外，中国证监会将采取终止审核并在36个月内不受理发行人的股票发行申请的监管措施。"},{"i":53,"n":"第五十三条","txt":"保荐人出具有虚假记载、误导性陈述或者重大遗漏的发行保荐书，保荐人以不正当手段干扰中国证监会及其发行审核委员会审核工作的，保荐人或其相关签字人员的签字、盖章系伪造或变造的，或者不履行其他法定职责的，依照《证券法》和保荐制度的有关规定处理。"},{"i":54,"n":"第五十四条","txt":"证券服务机构未勤勉尽责，所制作、出具的文件有虚假记载、误导性陈述或者重大遗漏的，除依照《证券法》及其他相关法律、行政法规和规章的规定处罚外，中国证监会将采取12个月内不接受相关机构出具的证券发行专项文件，36个月内不接受相关签字人员出具的证券发行专项文件的监管措施。"},{"i":55,"n":"第五十五条","txt":"发行人、保荐人或证券服务机构制作或者出具的文件不符合要求，擅自改动已提交的文件，或者拒绝答复中国证监会审核中提出的相关问题的，中国证监会将视情节轻重，对相关机构和责任人员采取监管谈话、责令改正等监管措施，记入诚信档案并公布；情节特别严重的，给予警告。"},{"i":56,"n":"第五十六条","txt":"发行人公开发行证券上市当年即亏损的，中国证监会自确认之日起暂停保荐机构的保荐机构资格3个月，撤销相关人员的保荐代表人资格，尚未盈利的试点企业除外。"},{"i":57,"n":"第五十七条","txt":"发行人披露盈利预测的，利润实现数如未达到盈利预测的80％，除因不可抗力外，其法定代表人、盈利预测审核报告签字注册会计师应当在股东大会及中国证监会指定报刊上公开作出解释并道歉；中国证监会可以对法定代表人处以警告。 利润实现数未达到盈利预测的50％的，除因不可抗力外，中国证监会在36个月内不受理该公司的公开发行证券申请。"},{"i":58,"n":"第五十八条","txt":"在中华人民共和国境内，首次公开发行股票且不上市的管理办法，由中国证监会另行规定。"},{"i":59,"n":"第五十九条","txt":"本办法自2006年5月18日起施行。《关于股票发行工作若干规定的通知》（证监[1996]12号）、《关于做好1997年股票发行工作的通知》（证监[1997]13号）、《关于股票发行工作若干问题的补充通知》（证监[1998]8号）、《关于对拟发行上市企业改制情况进行调查的通知》（证监发字[1998]259号）、《关于对拟公开发行股票公司改制运行情况进行调查的通知》（证监发[1999]4号）、《关于拟发行股票公司聘请审计机构等问题的通知》（证监发行字[2000]131号）和《关于进一步规范股票首次发行上市有关工作的通知》（证监发行字[2003]116号）同时废止。"}]};
